#define THEMER_SPOTLIGHT_BINDING_CAP 64
#define THEMER_SPOTLIGHT_MONITOR_ICON_CAP 384

typedef struct {
    uint64_t view;
    uint64_t carrier;
    uint64_t icon;
    uint64_t cache;
    uint64_t appearance;
    uint64_t retrievalOptions;
    uint64_t imageGeneration;
    bool generationKnown;
    char bundle[192];
} ThemerSpotlightCarrierBinding;

typedef struct {
    bool armed;
    bool carrierGapObserved;
    int pid;
    int iconCount;
    int bindingCount;
    uint64_t owner;
    uint64_t dataSource;
    uint64_t iconModel;
    uint64_t repository;
    uint64_t themeRepository;
    uint64_t icons[THEMER_SPOTLIGHT_MONITOR_ICON_CAP];
    uint64_t providers[THEMER_SPOTLIGHT_MONITOR_ICON_CAP];
    char bundles[THEMER_SPOTLIGHT_MONITOR_ICON_CAP][192];
    uint64_t caches[THEMER_SPOTLIGHT_BINDING_CAP];
    uint64_t appearances[THEMER_SPOTLIGHT_BINDING_CAP];
    uint64_t retrievalOptions[THEMER_SPOTLIGHT_BINDING_CAP];
    uint64_t generations[THEMER_SPOTLIGHT_MONITOR_ICON_CAP]
                        [THEMER_SPOTLIGHT_BINDING_CAP];
} ThemerSpotlightMonitorState;

static ThemerSpotlightMonitorState gThemerSpotlightMonitor;
static uint64_t gThemerSpotlightApplyGeneration;
static os_unfair_lock gThemerSpringBoardRefreshIdentifiersLock =
    OS_UNFAIR_LOCK_INIT;
static NSArray<NSString *> *gThemerSpringBoardRefreshBundleIdentifiers;

void themer_set_springboard_iconservices_refresh_bundle_identifiers(
    NSArray<NSString *> *bundleIdentifiers)
{
    NSMutableOrderedSet<NSString *> *sanitized =
        [NSMutableOrderedSet orderedSet];
    for (id value in bundleIdentifiers ?: @[]) {
        if (![value isKindOfClass:NSString.class]) continue;
        NSString *identifier =
            [(NSString *)value stringByTrimmingCharactersInSet:
                NSCharacterSet.whitespaceAndNewlineCharacterSet];
        if (identifier.length > 0) [sanitized addObject:identifier];
    }
    NSArray<NSString *> *snapshot = [sanitized.array
        sortedArrayUsingSelector:@selector(compare:)];
    os_unfair_lock_lock(&gThemerSpringBoardRefreshIdentifiersLock);
    gThemerSpringBoardRefreshBundleIdentifiers = [snapshot copy];
    os_unfair_lock_unlock(&gThemerSpringBoardRefreshIdentifiersLock);
}

static NSArray<NSString *> *
themer_springboard_refresh_bundle_identifiers_snapshot(void)
{
    os_unfair_lock_lock(&gThemerSpringBoardRefreshIdentifiersLock);
    NSArray<NSString *> *snapshot =
        [gThemerSpringBoardRefreshBundleIdentifiers copy] ?: @[];
    os_unfair_lock_unlock(&gThemerSpringBoardRefreshIdentifiersLock);
    return snapshot;
}

