static bool themer_spotlight_current_graph(uint64_t *ownerOut,
                                            uint64_t *dataSourceOut,
                                            uint64_t *iconModelOut,
                                            uint64_t *repositoryOut)
{
    if (ownerOut) *ownerOut = 0;
    if (dataSourceOut) *dataSourceOut = 0;
    if (iconModelOut) *iconModelOut = 0;
    if (repositoryOut) *repositoryOut = 0;

    uint64_t modelClass = r_class("SearchUIHomeScreenModel");
    uint64_t owner = r_is_objc_ptr(modelClass) &&
                     r_responds_main(modelClass, "sharedInstance")
        ? r_msg2_main(modelClass, "sharedInstance", 0, 0, 0, 0)
        : 0;
    uint64_t dataSource = themer_spotlight_trace_object_value(
        owner, "dataSource", "_dataSource");
    uint64_t iconModel = themer_spotlight_trace_object_value(
        owner, "iconModel", "_iconModel");
    uint64_t repository = r_is_objc_ptr(iconModel)
        ? r_ivar_value(iconModel, "iconRepository") : 0;
    if (!r_is_objc_ptr(repository) && r_is_objc_ptr(iconModel)) {
        repository = r_ivar_value(iconModel, "_iconRepository");
    }
    if (!r_is_objc_ptr(repository) && r_is_objc_ptr(iconModel) &&
        r_responds_main(iconModel, "iconRepository")) {
        repository = r_msg2_main(iconModel, "iconRepository", 0, 0, 0, 0);
    }

    if (ownerOut) *ownerOut = owner;
    if (dataSourceOut) *dataSourceOut = dataSource;
    if (iconModelOut) *iconModelOut = iconModel;
    if (repositoryOut) *repositoryOut = repository;
    return r_is_objc_ptr(owner) && r_is_objc_ptr(dataSource) &&
           r_is_objc_ptr(iconModel) && remote_call_current_success();
}

static uint64_t themer_spotlight_process_info(void)
{
    uint64_t processInfoClass = r_class("NSProcessInfo");
    return r_is_objc_ptr(processInfoClass) &&
           r_responds_main(processInfoClass, "processInfo")
        ? r_msg2_main(processInfoClass, "processInfo", 0, 0, 0, 0)
        : 0;
}

static uint64_t themer_spotlight_associated_process_object(
    const char *keyName)
{
    uint64_t processInfo = themer_spotlight_process_info();
    uint64_t key = keyName ? r_sel(keyName) : 0;
    if (!r_is_objc_ptr(processInfo) || !key) return 0;

    /* A direct objc_getAssociatedObject RemoteCall reliably returns nil on
     * physical arm64e SpringBoard, but can lose the synthetic completion
     * when the result is a non-null object. Invoke the exact same Apple IMP
     * through its natural Objective-C ABI instead: _cmd is the association
     * key, so a private method with this selector is a precise getter for the
     * process-owned value. This is the same signed-IMP shape already proven
     * by the Clock and Calendar source bridges. */
    uint64_t processClass = r_dlsym_call(
        R_TIMEOUT, "object_getClass", processInfo,
        0, 0, 0, 0, 0, 0, 0);
    uint64_t getterIMP = themer_remote_symbol_addr(
        "objc_getAssociatedObject");
    if (!r_is_objc_ptr(processClass) || !getterIMP) return 0;

    uint64_t method = r_dlsym_call(
        R_TIMEOUT, "class_getInstanceMethod", processClass, key,
        0, 0, 0, 0, 0, 0);
    if (!method) {
        if (!themer_add_method(processClass, keyName, getterIMP,
                               "@16@0:8")) {
            return 0;
        }
        method = r_dlsym_call(
            R_TIMEOUT, "class_getInstanceMethod", processClass, key,
            0, 0, 0, 0, 0, 0);
    }
    uint64_t installedIMP = method ? r_dlsym_call(
        R_TIMEOUT, "method_getImplementation", method,
        0, 0, 0, 0, 0, 0, 0) : 0;
    if (!installedIMP ||
        native_strip(installedIMP) != native_strip(getterIMP)) {
        return 0;
    }
    return r_msg2_main(processInfo, keyName, 0, 0, 0, 0);
}

static bool themer_spotlight_commit_process_object(const char *keyName,
                                                    uint64_t object)
{
    if (object && !r_is_objc_ptr(object)) return false;
    uint64_t processInfo = themer_spotlight_process_info();
    uint64_t key = keyName ? r_sel(keyName) : 0;
    if (!r_is_objc_ptr(processInfo) || !key) return false;
    r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                 processInfo, key, object, 1, 0, 0, 0, 0);
    return themer_spotlight_associated_process_object(keyName) == object;
}

static uint64_t themer_spotlight_dictionary_object(uint64_t dictionary,
                                                   const char *keyName)
{
    if (!r_is_objc_ptr(dictionary) || !keyName || !keyName[0] ||
        !r_responds_main(dictionary, "objectForKey:")) {
        return 0;
    }
    uint64_t key = r_nsstr_retained(keyName);
    if (!r_is_objc_ptr(key)) return 0;
    uint64_t object = r_msg2_main(dictionary, "objectForKey:",
                                  key, 0, 0, 0);
    r_msg2(key, "release", 0, 0, 0, 0);
    return r_is_objc_ptr(object) ? object : 0;
}

static bool themer_spotlight_dictionary_set_object(uint64_t dictionary,
                                                   const char *keyName,
                                                   uint64_t object)
{
    if (!r_is_objc_ptr(dictionary) || !keyName || !keyName[0] ||
        !r_is_objc_ptr(object) ||
        !r_responds_main(dictionary, "setObject:forKey:")) {
        return false;
    }
    uint64_t key = r_nsstr_retained(keyName);
    if (!r_is_objc_ptr(key)) return false;
    r_msg2_main(dictionary, "setObject:forKey:", object, key, 0, 0);
    uint64_t readback = r_msg2_main(dictionary, "objectForKey:",
                                    key, 0, 0, 0);
    r_msg2(key, "release", 0, 0, 0, 0);
    return readback == object && remote_call_current_success();
}

static uint64_t themer_spotlight_theme_state(void)
{
    return themer_spotlight_associated_process_object(
        "cndSpotlightThemeStateV2");
}

static uint64_t themer_spotlight_theme_repository(void)
{
    uint64_t state = themer_spotlight_theme_state();
    uint64_t images = themer_spotlight_dictionary_object(state, "images");
    if (r_is_objc_ptr(images)) return images;
    return themer_spotlight_associated_process_object(
        "cndSpotlightThemeImageRepository");
}

static bool themer_spotlight_commit_theme_state(uint64_t state)
{
    return themer_spotlight_commit_process_object(
        "cndSpotlightThemeStateV2", state);
}

static bool themer_spotlight_commit_theme_repository(uint64_t repository)
{
    return themer_spotlight_commit_process_object(
        "cndSpotlightThemeImageRepository", repository);
}

static uint64_t themer_spotlight_theme_repository_image(const char *bundle)
{
    if (!bundle || !bundle[0]) return 0;
    uint64_t repository = themer_spotlight_theme_repository();
    if (!r_is_objc_ptr(repository) ||
        !r_responds_main(repository, "objectForKey:")) {
        return 0;
    }
    uint64_t identifier = r_nsstr_retained(bundle);
    if (!r_is_objc_ptr(identifier)) return 0;
    uint64_t image = r_msg2_main(repository, "objectForKey:",
                                 identifier, 0, 0, 0);
    r_msg2(identifier, "release", 0, 0, 0, 0);
    return r_is_objc_ptr(image) ? image : 0;
}

void themer_spotlight_monitor_reset(void)
{
    memset(&gThemerSpotlightMonitor, 0,
           sizeof(gThemerSpotlightMonitor));
}

static bool themer_spotlight_carrier_cache_supports_seed(uint64_t cache)
{
    return r_is_objc_ptr(cache) &&
           r_responds_main(cache,
                           "cacheImage:forIcon:imageAppearance:") &&
           r_responds_main(cache,
                           "cachedImageForIcon:imageAppearance:options:") &&
           r_responds_main(cache, "currentImageGenerationForIcon:");
}

static int themer_spotlight_collect_carrier_bindings(
    ThemerSpotlightCarrierBinding *bindings,
    int cap,
    bool requireSeedable)
{
    if (!bindings || cap <= 0) return 0;
    enum { VIEW_CAP = 64 };
    uint64_t views[VIEW_CAP] = {0};
    int viewCount = themer_spotlight_collect_searchui_views_fast(
        views, VIEW_CAP);
    int count = 0;
    for (int i = 0; i < viewCount && count < cap; i++) {
        uint64_t view = views[i];
        uint64_t carrier = themer_spotlight_image_carrier_for_view(view);
        uint64_t icon = themer_spotlight_app_icon_for_view(view, NULL, 0);
        // Only the cache physically bound to SBIconImageView is relevant to a
        // recycled result row. Deliberately do not fall back to the owner,
        // model, repository, view, or icon graph here.
        uint64_t cache = themer_spotlight_trace_existing_cache(
            0, carrier, 0);
        uint64_t appearance = themer_spotlight_trace_existing_appearance(
            view, carrier);
        if (!r_is_objc_ptr(view) || !r_is_objc_ptr(carrier) ||
            !r_is_objc_ptr(icon)) {
            continue;
        }
        bool generationKnown = r_is_objc_ptr(cache) &&
            r_responds_main(cache, "currentImageGenerationForIcon:");
        if (requireSeedable &&
            (!themer_spotlight_carrier_cache_supports_seed(cache) ||
             !r_is_objc_ptr(appearance) || !generationKnown)) {
            continue;
        }

        char bundle[192] = {0};
        if (!themer_spotlight_bundle_for_patch(view, icon,
                                               bundle, sizeof(bundle),
                                               NULL, 0)) {
            continue;
        }
        uint64_t retrievalOptions = 4ULL;
        if (r_responds_main(carrier, "imageCacheRetrievalOptions")) {
            retrievalOptions |= r_msg2_main(
                carrier, "imageCacheRetrievalOptions", 0, 0, 0, 0);
        }
        uint64_t generation = generationKnown
            ? r_msg2_main(cache, "currentImageGenerationForIcon:",
                          icon, 0, 0, 0)
            : 0;

        ThemerSpotlightCarrierBinding *binding = &bindings[count++];
        binding->view = view;
        binding->carrier = carrier;
        binding->icon = icon;
        binding->cache = cache;
        binding->appearance = appearance;
        binding->retrievalOptions = retrievalOptions;
        binding->imageGeneration = generation;
        binding->generationKnown = generationKnown;
        snprintf(binding->bundle, sizeof(binding->bundle), "%s", bundle);
    }
    return count;
}

static int themer_spotlight_unique_cache_bindings(
    const ThemerSpotlightCarrierBinding *source,
    int sourceCount,
    ThemerSpotlightCarrierBinding *unique,
    int cap)
{
    if (!source || !unique || sourceCount <= 0 || cap <= 0) return 0;
    int count = 0;
    for (int i = 0; i < sourceCount && count < cap; i++) {
        bool duplicate = false;
        for (int j = 0; j < count; j++) {
            if (unique[j].cache == source[i].cache &&
                unique[j].appearance == source[i].appearance &&
                unique[j].retrievalOptions == source[i].retrievalOptions) {
                duplicate = true;
                break;
            }
        }
        if (!duplicate) unique[count++] = source[i];
    }
    return count;
}

static uint64_t themer_spotlight_exact_cached_image(
    const ThemerSpotlightCarrierBinding *binding,
    uint64_t icon,
    bool *supportedOut)
{
    if (supportedOut) *supportedOut = false;
    if (!binding || !r_is_objc_ptr(binding->cache) ||
        !r_is_objc_ptr(binding->appearance) || !r_is_objc_ptr(icon) ||
        !r_responds_main(binding->cache,
                        "cachedImageForIcon:imageAppearance:options:")) {
        return 0;
    }
    if (supportedOut) *supportedOut = true;
    return r_msg2_main(binding->cache,
                       "cachedImageForIcon:imageAppearance:options:",
                       icon, binding->appearance,
                       binding->retrievalOptions, 0);
}

static bool themer_spotlight_monitor_arm(
    const uint64_t *icons,
    const uint64_t *providers,
    char iconBundles[][192],
    int iconCount,
    const ThemerSpotlightCarrierBinding *bindings,
    int bindingCount,
    uint64_t owner,
    uint64_t dataSource,
    uint64_t iconModel,
    uint64_t repository)
{
    if (!icons || !providers || !iconBundles || iconCount <= 0 ||
        bindingCount < 0 || (bindingCount > 0 && !bindings) ||
        iconCount > THEMER_SPOTLIGHT_MONITOR_ICON_CAP ||
        bindingCount > THEMER_SPOTLIGHT_BINDING_CAP) {
        return false;
    }
    ThemerSpotlightMonitorState *candidate = calloc(1, sizeof(*candidate));
    if (!candidate) return false;

    uint64_t currentOwner = 0;
    uint64_t currentDataSource = 0;
    uint64_t currentIconModel = 0;
    uint64_t currentRepository = 0;
    bool graphKnown = themer_spotlight_current_graph(
        &currentOwner, &currentDataSource,
        &currentIconModel, &currentRepository);
    uint64_t themeRepository = themer_spotlight_theme_repository();
    if (!graphKnown || currentOwner != owner ||
        currentDataSource != dataSource || currentIconModel != iconModel ||
        currentRepository != repository ||
        !r_is_objc_ptr(themeRepository)) {
        free(candidate);
        return false;
    }

    candidate->pid = remote_call_current_pid();
    candidate->iconCount = iconCount;
    candidate->bindingCount = bindingCount;
    candidate->owner = owner;
    candidate->dataSource = dataSource;
    candidate->iconModel = iconModel;
    candidate->repository = repository;
    candidate->themeRepository = themeRepository;
    uint64_t primarySelector = r_sel(
        "makeIconImageWithInfo:traitCollection:context:options:");
    for (int i = 0; i < iconCount; i++) {
        candidate->icons[i] = icons[i];
        candidate->providers[i] = providers[i];
        snprintf(candidate->bundles[i],
                 sizeof(candidate->bundles[i]),
                 "%s", iconBundles[i]);
        uint64_t expected = themer_spotlight_theme_repository_image(
            iconBundles[i]);
        uint64_t associated = primarySelector && r_is_objc_ptr(icons[i])
            ? r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                           icons[i], primarySelector,
                           0, 0, 0, 0, 0, 0)
            : 0;
        if (!r_is_objc_ptr(icons[i]) ||
            !r_is_objc_ptr(providers[i]) ||
            !r_is_objc_ptr(expected) || associated != expected) {
            free(candidate);
            return false;
        }
    }
    for (int b = 0; b < bindingCount; b++) {
        if (!themer_spotlight_carrier_cache_supports_seed(
                bindings[b].cache) ||
            !r_is_objc_ptr(bindings[b].appearance)) {
            free(candidate);
            return false;
        }
        candidate->caches[b] = bindings[b].cache;
        candidate->appearances[b] = bindings[b].appearance;
        candidate->retrievalOptions[b] =
            bindings[b].retrievalOptions;
        for (int i = 0; i < iconCount; i++) {
            candidate->generations[i][b] = r_msg2_main(
                bindings[b].cache, "currentImageGenerationForIcon:",
                icons[i], 0, 0, 0);
        }
    }
    if (!remote_call_current_success()) {
        free(candidate);
        return false;
    }
    candidate->armed = true;
    gThemerSpotlightMonitor = *candidate;
    free(candidate);
    return true;
}

ThemerSpotlightMonitorResult themer_spotlight_monitor_poll_in_session(void)
{
    if (!gThemerSpotlightMonitor.armed ||
        gThemerSpotlightMonitor.iconCount <= 0 ||
        remote_call_current_pid() != gThemerSpotlightMonitor.pid) {
        return ThemerSpotlightMonitorResultUnavailable;
    }

    uint64_t owner = 0;
    uint64_t dataSource = 0;
    uint64_t iconModel = 0;
    uint64_t repository = 0;
    if (!themer_spotlight_current_graph(
            &owner, &dataSource, &iconModel, &repository) ||
        owner != gThemerSpotlightMonitor.owner ||
        dataSource != gThemerSpotlightMonitor.dataSource ||
        iconModel != gThemerSpotlightMonitor.iconModel ||
        repository != gThemerSpotlightMonitor.repository ||
        themer_spotlight_theme_repository() !=
            gThemerSpotlightMonitor.themeRepository) {
        printf("[SPOTLIGHT_MONITOR] drift reason=graph\n");
        return ThemerSpotlightMonitorResultReseedNeeded;
    }

    ThemerSpotlightCarrierBinding current[THEMER_SPOTLIGHT_BINDING_CAP] = {{0}};
    int currentCount = themer_spotlight_collect_carrier_bindings(
        current, THEMER_SPOTLIGHT_BINDING_CAP, false);
    if (!remote_call_current_success()) {
        return ThemerSpotlightMonitorResultUnavailable;
    }

    int themedBindings = 0;
    for (int c = 0; c < currentCount; c++) {
        int iconIndex = -1;
        for (int i = 0; i < gThemerSpotlightMonitor.iconCount; i++) {
            if (strcmp(current[c].bundle,
                       gThemerSpotlightMonitor.bundles[i]) == 0) {
                iconIndex = i;
                break;
            }
        }
        if (iconIndex < 0) continue;
        themedBindings++;
        if (current[c].icon != gThemerSpotlightMonitor.icons[iconIndex]) {
            printf("[SPOTLIGHT_MONITOR] drift reason=icon bundle=%s\n",
                   current[c].bundle);
            return ThemerSpotlightMonitorResultReseedNeeded;
        }
        uint64_t activeDataSource = themer_spotlight_trace_object_value(
            current[c].icon, "activeDataSource", "_activeDataSource");
        if (!r_is_objc_ptr(activeDataSource) ||
            activeDataSource !=
                gThemerSpotlightMonitor.providers[iconIndex]) {
            printf("[SPOTLIGHT_MONITOR] drift reason=provider bundle=%s\n",
                   current[c].bundle);
            return ThemerSpotlightMonitorResultReseedNeeded;
        }
        if (!current[c].generationKnown ||
            !r_is_objc_ptr(current[c].cache) ||
            !r_is_objc_ptr(current[c].appearance)) {
            return ThemerSpotlightMonitorResultReseedNeeded;
        }

        int bindingIndex = -1;
        for (int b = 0; b < gThemerSpotlightMonitor.bindingCount; b++) {
            if (current[c].cache == gThemerSpotlightMonitor.caches[b] &&
                current[c].appearance ==
                    gThemerSpotlightMonitor.appearances[b] &&
                current[c].retrievalOptions ==
                    gThemerSpotlightMonitor.retrievalOptions[b]) {
                bindingIndex = b;
                break;
            }
        }
        if (bindingIndex < 0 ||
            !r_is_objc_ptr(themer_spotlight_theme_repository_image(
                current[c].bundle))) {
            printf("[SPOTLIGHT_MONITOR] drift reason=cache-binding bundle=%s\n",
                   current[c].bundle);
            return ThemerSpotlightMonitorResultReseedNeeded;
        }
        uint64_t expected = themer_spotlight_theme_repository_image(
            current[c].bundle);
        bool exactSupported = false;
        uint64_t cached = themer_spotlight_exact_cached_image(
            &current[c], current[c].icon, &exactSupported);
        if (!exactSupported ||
            !themer_spotlight_images_match(expected, cached)) {
            printf("[SPOTLIGHT_MONITOR] drift reason=exact-content bundle=%s "
                   "gap=%d cached=0x%llx expected=0x%llx\n",
                   current[c].bundle,
                   gThemerSpotlightMonitor.carrierGapObserved,
                   (unsigned long long)cached,
                   (unsigned long long)expected);
            return ThemerSpotlightMonitorResultReseedNeeded;
        }
        if (current[c].imageGeneration !=
            gThemerSpotlightMonitor.generations[iconIndex][bindingIndex]) {
            gThemerSpotlightMonitor.generations[iconIndex][bindingIndex] =
                current[c].imageGeneration;
            printf("[SPOTLIGHT_MONITOR] generation-advanced bundle=%s "
                   "generation=%llu contentMatch=1\n",
                   current[c].bundle,
                   (unsigned long long)current[c].imageGeneration);
        }
    }
    if (themedBindings > 0) {
        if (gThemerSpotlightMonitor.carrierGapObserved) {
            printf("[SPOTLIGHT_MONITOR] carrier-reappeared bindings=%d "
                   "contentMatch=1\n", themedBindings);
        }
        gThemerSpotlightMonitor.carrierGapObserved = false;
        return ThemerSpotlightMonitorResultUnchanged;
    }
    gThemerSpotlightMonitor.carrierGapObserved = true;
    return ThemerSpotlightMonitorResultUnavailable;
}

