static NSString *themer_join_strings_for_log(id strings, NSUInteger limit)
{
    if (![strings respondsToSelector:@selector(allObjects)] &&
        ![strings respondsToSelector:@selector(countByEnumeratingWithState:objects:count:)]) {
        return @"";
    }

    NSArray *raw = [strings respondsToSelector:@selector(allObjects)]
        ? [strings allObjects]
        : (NSArray *)strings;
    NSMutableArray<NSString *> *items = [NSMutableArray array];
    for (id obj in raw) {
        if (![obj isKindOfClass:NSString.class] || [obj length] == 0) continue;
        [items addObject:obj];
    }
    [items sortUsingSelector:@selector(compare:)];

    NSUInteger total = items.count;
    if (limit > 0 && items.count > limit) {
        items = [[items subarrayWithRange:NSMakeRange(0, limit)] mutableCopy];
        [items addObject:[NSString stringWithFormat:@"...(+%lu)", (unsigned long)(total - limit)]];
    }
    return [items componentsJoinedByString:@","];
}

static NSString *themer_theme_path_for_bundle(NSDictionary<NSString *, NSString *> *pathByBundle,
                                              NSString *bundle)
{
    if (![bundle isKindOfClass:NSString.class] || bundle.length == 0) return nil;
    NSString *path = pathByBundle[bundle];
    if (!path) path = pathByBundle[bundle.lowercaseString];
    return path;
}

static uint64_t themer_lookup_cached(const char *bundle)
{
    if (!bundle || !bundle[0]) return 0;
    for (int i = 0; i < gThemerCacheCount; i++) {
        if (strcmp(gThemerCache[i].bundle, bundle) == 0) {
            return gThemerCache[i].image;
        }
    }
    return 0;
}

static ThemerEntry *themer_lookup_entry(const char *bundle)
{
    if (!bundle || !bundle[0]) return NULL;
    for (int i = 0; i < gThemerCacheCount; i++) {
        if (strcmp(gThemerCache[i].bundle, bundle) == 0) {
            return &gThemerCache[i];
        }
    }
    return NULL;
}

static void themer_cache_image(const char *bundle, uint64_t image)
{
    if (!bundle || !bundle[0] || !r_is_objc_ptr(image)) return;
    if (gThemerCacheCount >= kThemerMaxCache) return;
    ThemerEntry *e = &gThemerCache[gThemerCacheCount++];
    snprintf(e->bundle, sizeof(e->bundle), "%s", bundle);
    e->image = image;
    e->dataSource = 0;
    e->iconServicesIcon = 0;
    e->iconServicesOriginalClass = 0;
    e->iconServicesSeeded = false;
    e->iconServicesGrafted = false;
    e->modelGrafted = false;
}

static void themer_cache_icon_bundle(uint64_t icon, const char *bundle)
{
    if (!r_is_objc_ptr(icon) || !bundle || !bundle[0]) return;
    for (int i = 0; i < gThemerIconBundleCacheCount; i++) {
        if (gThemerIconBundleCache[i].icon == icon) {
            snprintf(gThemerIconBundleCache[i].bundle,
                     sizeof(gThemerIconBundleCache[i].bundle),
                     "%s", bundle);
            return;
        }
    }
    if (gThemerIconBundleCacheCount >= kThemerMaxIconBundleCache) return;
    ThemerIconBundleEntry *e = &gThemerIconBundleCache[gThemerIconBundleCacheCount++];
    e->icon = icon;
    snprintf(e->bundle, sizeof(e->bundle), "%s", bundle);
}

static bool themer_lookup_icon_bundle(uint64_t icon, char *out, size_t outLen)
{
    if (!r_is_objc_ptr(icon) || !out || outLen == 0) return false;
    for (int i = 0; i < gThemerIconBundleCacheCount; i++) {
        if (gThemerIconBundleCache[i].icon == icon &&
            gThemerIconBundleCache[i].bundle[0]) {
            snprintf(out, outLen, "%s", gThemerIconBundleCache[i].bundle);
            return out[0] != '\0';
        }
    }
    return false;
}

static void themer_reset_icon_bundle_cache(void)
{
    for (int i = 0; i < kThemerMaxIconBundleCache; i++) {
        gThemerIconBundleCache[i].icon = 0;
        gThemerIconBundleCache[i].bundle[0] = '\0';
    }
    gThemerIconBundleCacheCount = 0;
}

// Read a remote ObjC object's class name into a local C buffer.
static void themer_read_class_name(uint64_t obj, char *out, size_t outLen)
{
    if (!out || outLen == 0) return;
    memset(out, 0, outLen);
    if (!r_is_objc_ptr(obj)) return;
    uint64_t cls = r_dlsym_call(R_TIMEOUT, "object_getClass", obj, 0, 0, 0, 0, 0, 0, 0);
    if (!r_is_objc_ptr(cls)) return;
    uint64_t name = r_dlsym_call(R_TIMEOUT, "class_getName", cls, 0, 0, 0, 0, 0, 0, 0);
    if (!name) return;
    (void)r_read_cstring(name, out, outLen);
}

static void themer_read_class_object_name(uint64_t cls, char *out, size_t outLen)
{
    if (!out || outLen == 0) return;
    memset(out, 0, outLen);
    if (!r_is_objc_ptr(cls)) return;
    uint64_t name = r_dlsym_call(R_TIMEOUT, "class_getName",
                                 cls, 0, 0, 0, 0, 0, 0, 0);
    if (!name) return;
    (void)r_read_cstring(name, out, outLen);
}

static bool themer_read_remote_cstring(uint64_t cstr, char *out, size_t outLen)
{
    if (!out || outLen == 0) return false;
    return r_read_cstring(cstr, out, outLen) && out[0];
}

static bool themer_method_name_is_interesting(const char *name)
{
    if (!name || !name[0]) return false;
    static const char *needles[] = {
        "Image", "image", "Cache", "cache", "Descriptor", "descriptor",
        "Remove", "remove", "Clear", "clear", "Invalidate", "invalidate",
        "Delete", "delete", "Purge", "purge", "Flush", "flush",
        "Draw", "draw", "Display", "display", "Layer", "layer",
        "Layout", "layout", "Update", "update", "Refresh", "refresh",
        "Content", "content", "Animation", "animation",
        "Clock", "clock", "Calendar", "calendar", "Date", "date",
        "Time", "time", "Timer", "timer", "Hand", "hand",
        "Hour", "hour", "Minute", "minute", "Second", "second",
    };
    for (size_t i = 0; i < sizeof(needles) / sizeof(needles[0]); i++) {
        if (strstr(name, needles[i])) return true;
    }
    return false;
}

static void themer_log_remote_methods_once(const char *label, uint64_t obj,
                                           bool *loggedFlag)
{
    if (!loggedFlag || *loggedFlag || !label || !r_is_objc_ptr(obj)) return;
    *loggedFlag = true;

    uint64_t cls = r_dlsym_call(R_TIMEOUT, "object_getClass",
                                obj, 0, 0, 0, 0, 0, 0, 0);
    if (!r_is_objc_ptr(cls)) return;

    NSMutableArray<NSString *> *classRows = [NSMutableArray array];
    NSMutableArray<NSString *> *names = [NSMutableArray array];
    uint32_t totalCount = 0;
    for (int depth = 0; r_is_objc_ptr(cls) && depth < 10; depth++) {
        uint64_t countBuf = r_dlsym_call(R_TIMEOUT, "malloc",
                                         8, 0, 0, 0, 0, 0, 0, 0);
        if (!countBuf) break;
        remote_write64(countBuf, 0);
        uint64_t methods = r_dlsym_call(R_TIMEOUT, "class_copyMethodList",
                                        cls, countBuf, 0, 0, 0, 0, 0, 0);
        uint32_t count = 0;
        remote_read(countBuf, &count, sizeof(count));
        r_free(countBuf);

        char clsName[96] = {0};
        themer_read_class_object_name(cls, clsName, sizeof(clsName));
        [classRows addObject:[NSString stringWithFormat:@"%s:%u", clsName, count]];
        totalCount += count;

        if (methods && count > 0 && count <= 1024) {
            uint32_t cap = count < 1024 ? count : 1024;
            for (uint32_t i = 0; i < cap; i++) {
                uint64_t method = remote_read64(methods + ((uint64_t)i * sizeof(uint64_t)));
                if (!method) continue;
                uint64_t sel = r_dlsym_call(R_TIMEOUT, "method_getName",
                                            method, 0, 0, 0, 0, 0, 0, 0);
                if (!sel) continue;
                uint64_t cstr = r_dlsym_call(R_TIMEOUT, "sel_getName",
                                             sel, 0, 0, 0, 0, 0, 0, 0);
                char name[160] = {0};
                if (!themer_read_remote_cstring(cstr, name, sizeof(name))) continue;
                if (!themer_method_name_is_interesting(name)) continue;

                char types[192] = {0};
                uint64_t typeCstr = r_dlsym_call(R_TIMEOUT, "method_getTypeEncoding",
                                                 method, 0, 0, 0, 0, 0, 0, 0);
                (void)themer_read_remote_cstring(typeCstr, types, sizeof(types));
                if (names.count < 100) {
                    [names addObject:[NSString stringWithFormat:@"%s/%s",
                                      name, types[0] ? types : "?"]];
                }
            }
        }
        if (methods) r_free(methods);
        cls = r_dlsym_call(R_TIMEOUT, "class_getSuperclass",
                           cls, 0, 0, 0, 0, 0, 0, 0);
    }

    printf("[THEMER] methods label=%s hierarchy=%s total=%u filtered=%s\n",
           label,
           classRows.count ? [classRows componentsJoinedByString:@">"].UTF8String : "",
           totalCount,
           names.count ? [names componentsJoinedByString:@","].UTF8String : "");
}

static void themer_log_remote_ivars_once(const char *label, uint64_t obj,
                                         bool *loggedFlag)
{
    if (!loggedFlag || *loggedFlag || !label || !r_is_objc_ptr(obj)) return;
    *loggedFlag = true;

    uint64_t cls = r_dlsym_call(R_TIMEOUT, "object_getClass",
                                obj, 0, 0, 0, 0, 0, 0, 0);
    if (!r_is_objc_ptr(cls)) return;

    NSMutableArray<NSString *> *classRows = [NSMutableArray array];
    NSMutableArray<NSString *> *names = [NSMutableArray array];
    uint32_t totalCount = 0;
    for (int depth = 0; r_is_objc_ptr(cls) && depth < 10; depth++) {
        uint64_t countBuf = r_dlsym_call(R_TIMEOUT, "malloc",
                                         8, 0, 0, 0, 0, 0, 0, 0);
        if (!countBuf) break;
        remote_write64(countBuf, 0);
        uint64_t ivars = r_dlsym_call(R_TIMEOUT, "class_copyIvarList",
                                      cls, countBuf, 0, 0, 0, 0, 0, 0);
        uint32_t count = 0;
        remote_read(countBuf, &count, sizeof(count));
        r_free(countBuf);

        char clsName[96] = {0};
        themer_read_class_object_name(cls, clsName, sizeof(clsName));
        [classRows addObject:[NSString stringWithFormat:@"%s:%u",
                              clsName, count]];
        totalCount += count;

        if (ivars && count > 0 && count <= 1024) {
            uint32_t cap = count < 1024 ? count : 1024;
            for (uint32_t i = 0; i < cap; i++) {
                uint64_t ivar = remote_read64(ivars + ((uint64_t)i * sizeof(uint64_t)));
                if (!ivar) continue;
                uint64_t nameCstr = r_dlsym_call(R_TIMEOUT, "ivar_getName",
                                                 ivar, 0, 0, 0, 0, 0, 0, 0);
                uint64_t typeCstr = r_dlsym_call(R_TIMEOUT, "ivar_getTypeEncoding",
                                                 ivar, 0, 0, 0, 0, 0, 0, 0);
                uint64_t offset = r_dlsym_call(R_TIMEOUT, "ivar_getOffset",
                                               ivar, 0, 0, 0, 0, 0, 0, 0);
                char name[160] = {0};
                char type[160] = {0};
                (void)themer_read_remote_cstring(nameCstr, name, sizeof(name));
                (void)themer_read_remote_cstring(typeCstr, type, sizeof(type));
                if (names.count < 160) {
                    [names addObject:[NSString stringWithFormat:@"%s/%s@%lld",
                                      name[0] ? name : "?",
                                      type[0] ? type : "?",
                                      (long long)offset]];
                }
            }
        }
        if (ivars) r_free(ivars);
        cls = r_dlsym_call(R_TIMEOUT, "class_getSuperclass",
                           cls, 0, 0, 0, 0, 0, 0, 0);
    }

    printf("[THEMER] static-dynamic ivars label=%s hierarchy=%s total=%u ivars=%s\n",
           label,
           classRows.count ? [classRows componentsJoinedByString:@">"].UTF8String : "",
           totalCount,
           names.count ? [names componentsJoinedByString:@","].UTF8String : "");
}

static uint64_t themer_lookup_class(const char *name)
{
    if (!name || !name[0]) return 0;
    uint64_t s = r_alloc_str(name);
    if (!s) return 0;
    uint64_t cls = r_dlsym_call(R_TIMEOUT, "objc_lookUpClass",
                                s, 0, 0, 0, 0, 0, 0, 0);
    r_free(s);
    return cls;
}

static uint64_t themer_method_imp(uint64_t cls, const char *selName)
{
    if (!r_is_objc_ptr(cls) || !selName) return 0;
    uint64_t sel = r_sel(selName);
    if (!sel) return 0;
    uint64_t method = r_dlsym_call(R_TIMEOUT, "class_getInstanceMethod",
                                   cls, sel, 0, 0, 0, 0, 0, 0);
    if (!method) return 0;
    return r_dlsym_call(R_TIMEOUT, "method_getImplementation",
                        method, 0, 0, 0, 0, 0, 0, 0);
}

static bool themer_add_method(uint64_t cls, const char *selName,
                              uint64_t imp, const char *types)
{
    if (!r_is_objc_ptr(cls) || !selName || !imp || !types) return false;
    uint64_t sel = r_sel(selName);
    uint64_t typeStr = r_alloc_str(types);
    if (!sel || !typeStr) {
        if (typeStr) r_free(typeStr);
        return false;
    }
    uint64_t ok = r_dlsym_call(R_TIMEOUT, "class_addMethod",
                               cls, sel, imp, typeStr, 0, 0, 0, 0);
    r_free(typeStr);
    return (ok & 0xff) != 0;
}

static bool themer_class_defines_method(uint64_t cls, const char *selName)
{
    if (!r_is_objc_ptr(cls) || !selName || !selName[0]) return false;
    uint64_t sel = r_sel(selName);
    if (!sel) return false;

    uint64_t countBuf = r_dlsym_call(R_TIMEOUT, "malloc",
                                     8, 0, 0, 0, 0, 0, 0, 0);
    if (!countBuf) return false;
    remote_write64(countBuf, 0);
    uint64_t methods = r_dlsym_call(R_TIMEOUT, "class_copyMethodList",
                                    cls, countBuf, 0, 0, 0, 0, 0, 0);
    uint32_t count = 0;
    remote_read(countBuf, &count, sizeof(count));
    r_free(countBuf);

    bool found = false;
    if (methods && count > 0 && count <= 1024) {
        uint32_t cap = count < 1024 ? count : 1024;
        for (uint32_t i = 0; i < cap; i++) {
            uint64_t method = remote_read64(methods + ((uint64_t)i * sizeof(uint64_t)));
            if (!method) continue;
            uint64_t methodSel = r_dlsym_call(R_TIMEOUT, "method_getName",
                                              method, 0, 0, 0, 0, 0, 0, 0);
            if (methodSel == sel) {
                found = true;
                break;
            }
        }
    }
    if (methods) r_free(methods);
    return found;
}

static bool themer_ensure_method(uint64_t cls, const char *selName,
                                 uint64_t imp, const char *types)
{
    if (themer_class_defines_method(cls, selName)) return true;
    return themer_add_method(cls, selName, imp, types);
}

static bool themer_ensure_methods(uint64_t cls, const char **sels, int count,
                                  uint64_t imp, const char *types)
{
    if (!r_is_objc_ptr(cls) || !sels || count <= 0 || !imp || !types) return false;
    bool ok = true;
    for (int i = 0; i < count; i++) {
        ok = themer_ensure_method(cls, sels[i], imp, types) && ok;
    }
    return ok;
}

static bool themer_add_methods(uint64_t cls, const char **sels, int count,
                               uint64_t imp, const char *types)
{
    if (!r_is_objc_ptr(cls) || !sels || count <= 0 || !imp || !types) return false;
    bool ok = true;
    for (int i = 0; i < count; i++) {
        ok = themer_add_method(cls, sels[i], imp, types) && ok;
    }
    return ok;
}

static uint64_t themer_remote_symbol_addr(const char *name)
{
    if (!remote_call_current_success() || !name || !name[0]) return 0;
    uint64_t remoteName = r_alloc_str(name);
    if (!remote_call_current_success()) return 0;
    if (!remoteName) return 0;
    uint64_t sym = r_dlsym_call(R_TIMEOUT, "dlsym",
                                (uint64_t)-2, remoteName, 0, 0, 0, 0, 0, 0);
    if (!remote_call_current_success()) return 0;
    r_free(remoteName);
    return remote_call_current_success() ? sym : 0;
}

static bool themer_ensure_iconservices_loaded(void)
{
    if (!remote_call_current_success()) return false;
    uint64_t bundleIconClass = themer_lookup_class("ISBundleIdentifierIcon");
    if (!remote_call_current_success()) return false;
    uint64_t descriptorClass = themer_lookup_class("ISImageDescriptor");
    if (!remote_call_current_success()) return false;
    uint64_t managerClass = themer_lookup_class("ISIconManager");
    if (!remote_call_current_success()) return false;
    uint64_t imageClass = themer_lookup_class("IFImage");
    if (!remote_call_current_success()) return false;
    if (r_is_objc_ptr(bundleIconClass) &&
        r_is_objc_ptr(descriptorClass) &&
        r_is_objc_ptr(managerClass) &&
        r_is_objc_ptr(imageClass)) {
        return true;
    }

    uint64_t foundationPath = r_alloc_str("/System/Library/PrivateFrameworks/IconFoundation.framework/IconFoundation");
    if (!remote_call_current_success()) return false;
    if (foundationPath) {
        r_dlsym_call(R_TIMEOUT, "dlopen", foundationPath, 1, 0, 0, 0, 0, 0, 0);
        if (!remote_call_current_success()) return false;
        r_free(foundationPath);
        if (!remote_call_current_success()) return false;
    }

    uint64_t path = r_alloc_str("/System/Library/PrivateFrameworks/IconServices.framework/IconServices");
    if (!remote_call_current_success()) return false;
    if (!path) return false;
    uint64_t handle = r_dlsym_call(R_TIMEOUT, "dlopen", path, 1, 0, 0, 0, 0, 0, 0);
    if (!remote_call_current_success()) return false;
    r_free(path);
    if (!remote_call_current_success()) return false;
    (void)handle;

    bundleIconClass = themer_lookup_class("ISBundleIdentifierIcon");
    if (!remote_call_current_success()) return false;
    descriptorClass = themer_lookup_class("ISImageDescriptor");
    if (!remote_call_current_success()) return false;
    managerClass = themer_lookup_class("ISIconManager");
    if (!remote_call_current_success()) return false;
    imageClass = themer_lookup_class("IFImage");
    return remote_call_current_success() &&
           r_is_objc_ptr(bundleIconClass) &&
           r_is_objc_ptr(descriptorClass) &&
           r_is_objc_ptr(managerClass) &&
           r_is_objc_ptr(imageClass);
}

// ---- IconServices store registration-surface inventory (read only) ----
//
// This observer is intentionally kept separate from the materialization lab.
// It invokes only the five ABI-gated object getters needed to reach the
// manager cache, store, storeIndex, and registry. The remaining work is Objective-C
// runtime C metadata inspection; discovered selectors are logged, never sent.

#define THEMER_STORE_SURFACE_METHOD_CAP 256U
#define THEMER_STORE_SURFACE_CANDIDATE_CAP 1024
#define THEMER_STORE_SURFACE_IVAR_CAP 128U
#define THEMER_STORE_SURFACE_IMAGE_CLASS_CAP 4096U
#define THEMER_STORE_SURFACE_MATCH_CAP 32U

// Runtime metadata can reside on pages remote_read cannot map. Use the shared
// reader's remote heap copy and reject local strings that fill the buffer so
// its forced trailing NUL cannot make a truncated name or encoding acceptable.
static bool themer_store_surface_read_cstring(uint64_t cstr, char *out,
                                              size_t outLen)
{
    if (!out || !outLen) return false;
    out[0] = '\0';
    if (!cstr || cstr > UINT64_MAX - (outLen - 1) ||
        !remote_call_current_success()) return false;
    if (outLen > 1 && themer_read_remote_cstring(cstr, out, outLen) &&
        strlen(out) < outLen - 1) return true;
    out[0] = '\0';
    return false;
}

static bool themer_store_surface_getter_encoding(uint64_t cls,
                                                 bool classMethod,
                                                 const char *target,
                                                 const char *selector,
                                                 char *types,
                                                 size_t typesLen)
{
    if (types && typesLen) types[0] = '\0';
    if (!target || !selector || !types || typesLen == 0) {
        return false;
    }
    if (!r_is_objc_ptr(cls) || !remote_call_current_success()) {
        printf("[ICONSERVICES_STORE_SURFACE] abi target=%s kind=%c selector=%s "
               "observed=\"-\" expected=\"@16@0:8\" accepted=0 invoked=0\n",
               target, classMethod ? '+' : '-', selector);
        return false;
    }
    uint64_t sel = r_sel(selector);
    uint64_t method = sel ? r_dlsym_call(
        R_TIMEOUT, classMethod ? "class_getClassMethod" :
                                 "class_getInstanceMethod",
        cls, sel, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t encoding = method ? r_dlsym_call(
        R_TIMEOUT, "method_getTypeEncoding", method,
        0, 0, 0, 0, 0, 0, 0) : 0;
    bool read = encoding && themer_store_surface_read_cstring(encoding, types, typesLen);
    bool accepted = read && strcmp(types, "@16@0:8") == 0;
    printf("[ICONSERVICES_STORE_SURFACE] abi target=%s kind=%c selector=%s "
           "observed=\"%s\" expected=\"@16@0:8\" accepted=%d invoked=0\n",
           target, classMethod ? '+' : '-', selector,
           types[0] ? types : "-", accepted);
    return accepted && remote_call_current_success();
}

static bool themer_store_surface_read_object_class(uint64_t object,
                                                   char *out,
                                                   size_t outLen)
{
    if (out && outLen) out[0] = '\0';
    if (!r_is_objc_ptr(object) || !out || outLen == 0 ||
        !remote_call_current_success()) {
        return false;
    }
    uint64_t cls = r_dlsym_call(R_TIMEOUT, "object_getClass", object,
                                0, 0, 0, 0, 0, 0, 0);
    uint64_t name = r_is_objc_ptr(cls) ? r_dlsym_call(
        R_TIMEOUT, "class_getName", cls, 0, 0, 0, 0, 0, 0, 0) : 0;
    return name && themer_store_surface_read_cstring(name, out, outLen) &&
        remote_call_current_success();
}

// Live-state observer: every remote Objective-C message passes this exact gate.
// No recovery state or index parser participates in this observer.
typedef struct { unsigned rejected, nils, invalid; uint64_t fingerprint; } ThemerStoreState;
static void themer_store_state_hash(ThemerStoreState *state, const void *bytes, size_t length)
{
    const unsigned char *p = bytes;
    for (size_t i = 0; i < length; i++) { state->fingerprint ^= p[i]; state->fingerprint *= 1099511628211ULL; }
}
static uint64_t themer_store_state_call_exact(ThemerStoreState *state, uint64_t object,
    bool classMethod, const char *label, const char *selector, const char *expected, const char *alternative,
    uint64_t argument, bool *known)
{
    if (known) *known = false;
    if (!remote_call_current_success()) return 0;
    if (!object) { printf("[ICONSERVICES_STORE_STATE] field=%s status=parent-nil\n", label); return 0; }
    uint64_t cls = classMethod ? object : r_dlsym_call(R_TIMEOUT, "object_getClass", object, 0,0,0,0,0,0,0);
    uint64_t sel = r_sel(selector);
    uint64_t method = cls && sel ? r_dlsym_call(R_TIMEOUT, classMethod ? "class_getClassMethod" : "class_getInstanceMethod", cls, sel,0,0,0,0,0,0) : 0;
    uint64_t encoding = method ? r_dlsym_call(R_TIMEOUT, "method_getTypeEncoding", method,0,0,0,0,0,0,0) : 0;
    char types[192] = {0};
    bool accepted = encoding && themer_store_surface_read_cstring(encoding, types, sizeof(types)) &&
        (strcmp(types, expected) == 0 || (alternative && strcmp(types, alternative) == 0));
    printf("[ICONSERVICES_STORE_STATE] abi field=%s selector=%s observed=\"%s\" acceptedEncodings=\"%s%s%s\" status=%s accepted=%d invoked=0\n", label, selector, types, expected, alternative ? " | " : "", alternative ?: "",
        !remote_call_current_success() ? "transport-failure" : !method ? "abi-unavailable" : !accepted ? "abi-rejected" : "accepted", accepted && remote_call_current_success());
    if (!accepted || !remote_call_current_success()) { state->rejected++; return 0; }
    uint64_t value = r_msg2_main(object, selector, argument,0,0,0);
    bool clean = remote_call_current_success();
    printf("[ICONSERVICES_STORE_STATE] invocation field=%s selector=%s invoked=1 completion=%s\n",label,selector,clean ? "clean" : "transport-failure");
    if (known) *known = clean;
    // Include graph identity and scalar observations, excluding temporary strings,
    // UUID allocations and data buffer addresses from the lifecycle fingerprint.
    bool fingerprintValue = !strcmp(label,"manager") || !strcmp(label,"cache") ||
        !strcmp(label,"store") || !strcmp(label,"index") ||
        !strcmp(label,"store.registry") || !strcmp(label,"store.connection") ||
        !strcmp(label,"directCandidate.unit") || !strcmp(label,"agentCandidate.unit") ||
        expected[0] == 'Q' || expected[0] == 'B';
    if (fingerprintValue) {
        themer_store_state_hash(state, label, strlen(label));
        themer_store_state_hash(state, &value, sizeof(value));
    }
    if (!clean) { printf("[ICONSERVICES_STORE_STATE] field=%s status=transport-failure\n", label); return 0; }
    char name[96] = {0};
    bool obj = expected[0] == '@';
    if (obj && value && !themer_store_surface_read_object_class(value, name, sizeof(name))) state->rejected++;
    if (obj && !value) state->nils++;
    printf("[ICONSERVICES_STORE_STATE] field=%s value=0x%llx class=%s status=%s\n", label, (unsigned long long)value, name[0] ? name : "-", obj && !value ? "clean-nil" : "present");
    return value;
}
static uint64_t themer_store_state_call(ThemerStoreState *state, uint64_t object,
    bool classMethod, const char *label, const char *selector, const char *expected,
    uint64_t argument, bool *known)
{
    return themer_store_state_call_exact(state, object, classMethod, label, selector,
        expected, NULL, argument, known);
}
#define STATE_GET(o,l,s) themer_store_state_call(&state,o,false,l,s,"@16@0:8",0,NULL)
static bool themer_store_state_remote_stat(NSString *path, struct stat *stOut,
    int *errorOut)
{
    if (stOut) memset(stOut,0,sizeof(*stOut));
    if (errorOut) *errorOut = 0;
    if (!path.length || !remote_call_current_success()) return false;
    uint64_t remotePath = r_alloc_str(path.fileSystemRepresentation);
    uint64_t buffer = r_dlsym_call(R_TIMEOUT,"calloc",1,sizeof(struct stat),0,0,0,0,0,0);
    int rc = -1, error = 0;
    bool read = false;
    if (remotePath && buffer && remote_call_current_success()) {
        rc = (int)r_dlsym_call(R_TIMEOUT,"stat",remotePath,buffer,0,0,0,0,0,0);
        if (rc != 0 && remote_call_current_success()) {
            uint64_t ep = r_dlsym_call(R_TIMEOUT,"__error",0,0,0,0,0,0,0,0);
            if (ep) remote_read(ep,&error,sizeof(error));
        }
        read = rc == 0 && remote_call_current_success() && stOut &&
            remote_read(buffer,stOut,sizeof(*stOut));
    }
    if (errorOut) *errorOut = error;
    if (remote_call_current_success()) {
        if (buffer) r_free(buffer);
        if (remotePath) r_free(remotePath);
    }
    return read;
}
static NSString *themer_store_state_path(ThemerStoreState *state, uint64_t object, bool url, const char *label)
{
    if (!object) return nil;
    uint64_t path = url ? themer_store_state_call(state, object,false,label,"path","@16@0:8",0,NULL) : object;
    bool known = false;
    uint64_t chars = themer_store_state_call_exact(state,path,false,label,"UTF8String","*16@0:8","r*16@0:8",0,&known);
    char text[4096] = {0};
    if (!known || !chars || !themer_store_surface_read_cstring(chars,text,sizeof(text))) return nil;
    NSString *normalized = [[NSString stringWithUTF8String:text] stringByStandardizingPath];
    themer_store_state_hash(state,text,strlen(text));
    struct stat st = {0};
    int error = 0;
    bool read = themer_store_state_remote_stat(normalized,&st,&error);
    printf("[ICONSERVICES_STORE_STATE] path field=%s raw=%s normalized=%s stat=%s errno=%d device=%llu inode=%llu mode=%o size=%lld mtime=%lld\n",label,text,normalized.UTF8String ?: "-", !remote_call_current_success() ? "transport-failure" : read ? "exists" : error == ENOENT ? "absent" : "unavailable",error,(unsigned long long)st.st_dev,(unsigned long long)st.st_ino,st.st_mode,(long long)st.st_size,(long long)st.st_mtime);
    if (read) { themer_store_state_hash(state,&st.st_ino,sizeof(st.st_ino)); themer_store_state_hash(state,&st.st_size,sizeof(st.st_size)); }
    return normalized;
}
static void themer_store_state_format_uuid(const unsigned char bytes[16], char text[37])
{
    snprintf(text,37,
        "%02X%02X%02X%02X-%02X%02X-%02X%02X-%02X%02X-%02X%02X%02X%02X%02X%02X",
        bytes[0],bytes[1],bytes[2],bytes[3],bytes[4],bytes[5],bytes[6],bytes[7],
        bytes[8],bytes[9],bytes[10],bytes[11],bytes[12],bytes[13],bytes[14],bytes[15]);
}

static void themer_store_state_uuid_from_sha256(
    const unsigned char digest[CC_SHA256_DIGEST_LENGTH], unsigned char uuid[16])
{
    memset(uuid,0,16);
    for (unsigned i=0;i<CC_SHA256_DIGEST_LENGTH;i++) uuid[i % 16] ^= digest[i];
    uuid[6] = (uuid[6] & 0x0f) | 0x30;
    uuid[8] = (uuid[8] & 0x3f) | 0x80;
}

static bool themer_store_state_derive_agent_uuid(const char *cacheSalt,
    unsigned char uuid[16], char uuidText[37])
{
    if (!cacheSalt || !cacheSalt[0] || strlen(cacheSalt) > 128) return false;
    const unsigned char responseDigest[CC_SHA256_DIGEST_LENGTH] = {
        0xff,0x50,0x4f,0xdd,0x6c,0x7c,0x87,0xae,0x00,0x6e,0x28,0xd4,0xcc,0x74,0xfd,0x19,
        0x49,0x96,0x6a,0x4d,0xfa,0xb2,0x24,0x4b,0xdb,0x35,0xef,0x5e,0x07,0x87,0x74,0x27
    };
    unsigned char dataUUID[16], finalDigest[CC_SHA256_DIGEST_LENGTH];
    char dataUUIDText[37], material[192];
    themer_store_state_uuid_from_sha256(responseDigest,dataUUID);
    themer_store_state_format_uuid(dataUUID,dataUUIDText);
    int length = snprintf(material,sizeof(material),"%s-%s",dataUUIDText,cacheSalt);
    if (length <= 0 || (size_t)length >= sizeof(material)) return false;
    CC_SHA256(material,(CC_LONG)length,finalDigest);
    themer_store_state_uuid_from_sha256(finalDigest,uuid);
    themer_store_state_format_uuid(uuid,uuidText);
    return true;
}

static void themer_store_state_data(ThemerStoreState *state, uint64_t data,
    const char *label, const unsigned char agentUUID[16], const char *agentText)
{
    if (!data) return;
    char className[96] = {0};
    if (!themer_store_surface_read_object_class(data,className,sizeof(className))) {
        state->rejected++;
        printf("[ICONSERVICES_STORE_STATE] data field=%s dataKind=unknown objectLength=unknown mappedLength=unknown status=%s nonatomic=1\n",label,remote_call_current_success()?"class-unavailable":"transport-failure");
        return;
    }
    bool dispatchData = strcmp(className,"OS_dispatch_data") == 0;
    const char *kind = dispatchData ? "dispatch" : "nsdata";
    bool known = false;
    uint64_t length = 0, bytes = 0, mappedLength = 0;
    uint64_t bufferSlot = 0, sizeSlot = 0, mappedData = 0;
    const char *status = "read-unavailable";
    if (dispatchData) {
        length = r_dlsym_call(R_TIMEOUT,"dispatch_data_get_size",data,0,0,0,0,0,0,0);
        known = remote_call_current_success();
    } else {
        length = themer_store_state_call(state,data,false,label,"length","Q16@0:8",0,&known);
    }
    if (!known || length > (1U << 20) || length > SIZE_MAX) {
        state->rejected++;
        printf("[ICONSERVICES_STORE_STATE] data field=%s dataKind=%s objectLength=%llu mappedLength=unknown status=%s hash=unavailable uuidOccurrence=unknown nonatomic=1\n",label,kind,(unsigned long long)length,!remote_call_current_success()?"transport-failure":known?"bounded-skip":"length-unavailable");
        return;
    }
    if (dispatchData) {
        bufferSlot = r_dlsym_call(R_TIMEOUT,"calloc",1,sizeof(uint64_t),0,0,0,0,0,0);
        sizeSlot = remote_call_current_success() ? r_dlsym_call(R_TIMEOUT,"calloc",1,sizeof(uint64_t),0,0,0,0,0,0) : 0;
        bool slotsReady = bufferSlot && sizeSlot && remote_call_current_success();
        mappedData = slotsReady ? r_dlsym_call(R_TIMEOUT,"dispatch_data_create_map",data,bufferSlot,sizeSlot,0,0,0,0,0) : 0;
        known = remote_call_current_success() && r_is_objc_ptr(mappedData) &&
            remote_read(bufferSlot,&bytes,sizeof(bytes)) &&
            remote_read(sizeSlot,&mappedLength,sizeof(mappedLength));
        status = slotsReady ? "map-unavailable" : "slots-unavailable";
        if (known) {
            known = mappedLength == length && mappedLength <= (1U << 20) &&
                mappedLength <= SIZE_MAX && (!mappedLength || (bytes && bytes <= UINT64_MAX - mappedLength));
            status = known ? "read-unavailable" : "map-bounds-or-length-mismatch";
        }
    } else {
        bytes = themer_store_state_call_exact(state,data,false,label,"bytes","^v16@0:8","r^v16@0:8",0,&known);
        mappedLength = length;
        known = known && (!length || (bytes && bytes <= UINT64_MAX - length));
    }
    unsigned char *copy = known ? calloc(1,(size_t)length + 1) : NULL;
    const char *readPath = dispatchData ? "remote-heap-stage" : "direct";
    bool read = false;
    uint64_t staging = 0;
    if (dispatchData) {
        bool stageDispatched = false, stageCompleted = false;
        const char *stageStatus = known ? "local-allocation-failed" : "map-unavailable";
        if (copy && known && remote_call_current_success()) {
            if (!mappedLength) {
                read = true;
                stageStatus = "empty-no-allocation";
            } else {
                staging = r_dlsym_call(R_TIMEOUT,"malloc",mappedLength,0,0,0,0,0,0,0);
                stageStatus = staging ? "staging-bounds-rejected" : "staging-allocation-failed";
                if (staging && staging <= UINT64_MAX - mappedLength && remote_call_current_success()) {
                    stageDispatched = true;
                    uint64_t copied = r_dlsym_call(R_TIMEOUT,"memcpy",staging,bytes,mappedLength,0,0,0,0,0);
                    stageCompleted = remote_call_current_success() && copied == staging;
                    stageStatus = stageCompleted ? "staging-read-unavailable" : "memcpy-return-mismatch";
                    // File-backed map pages are intentionally never imported by remote_read.
                    if (stageCompleted) read = remote_read(staging,copy,(size_t)mappedLength);
                    if (read) stageStatus = "observed";
                }
            }
        }
        if (!remote_call_current_success()) stageStatus = "transport-failure";
        status = stageStatus;
        printf("[ICONSERVICES_STORE_STATE] staging field=%s dataKind=dispatch readPath=remote-heap-stage objectLength=%llu mappedLength=%llu dispatched=%d completed=%d status=%s nonatomic=1\n",label,(unsigned long long)length,(unsigned long long)mappedLength,stageDispatched,stageCompleted,stageStatus);
        if (staging && remote_call_current_success()) r_free(staging);
    } else {
        read = copy && known && remote_call_current_success() &&
            (!length || remote_read(bytes,copy,(size_t)length));
    }
    if (read) {
        unsigned char digest[CC_SHA256_DIGEST_LENGTH]; char hex[65];
        CC_SHA256(copy,(CC_LONG)length,digest);
        for (unsigned i=0;i<sizeof(digest);i++) snprintf(hex+i*2,3,"%02x",digest[i]);
        const unsigned char directUUID[16] = {0x8b,0xbc,0x66,0x35,0x51,0x24,0x48,0x85,0x95,0x1b,0x33,0x9c,0x3b,0xea,0x1f,0xe8};
        const char *directText="8BBC6635-5124-4885-951B-339C3BEA1FE8";
        unsigned directBinary=0, directTextual=0, agentBinary=0, agentTextual=0;
        for (size_t i=0;i<length;i++) {
            if (length-i>=16 && !memcmp(copy+i,directUUID,16)) directBinary++;
            if (length-i>=36 && !strncasecmp((const char *)copy+i,directText,36)) directTextual++;
            if (agentUUID && length-i>=16 && !memcmp(copy+i,agentUUID,16)) agentBinary++;
            if (agentText && length-i>=36 && !strncasecmp((const char *)copy+i,agentText,36)) agentTextual++;
        }
