static uint64_t themer_store_state_remote_isa_mask(void)
{
    uint64_t mask = 0;
    uint64_t symbolName = r_alloc_str("objc_debug_isa_class_mask");
    uint64_t symbol = symbolName ? r_dlsym_call(
        R_TIMEOUT, "dlsym", UINT64_MAX - 1, symbolName,
        0, 0, 0, 0, 0, 0) : 0;
    if (symbol && remote_call_current_success()) {
        (void)remote_read(symbol, &mask, sizeof(mask));
    }
    if (symbolName && remote_call_current_success()) r_free(symbolName);
    return mask;
}

static bool themer_store_state_ivar_offset(
    uint64_t cls, const char *name, uint64_t *offsetOut)
{
    if (offsetOut) *offsetOut = 0;
    if (!r_is_objc_ptr(cls) || !name || !remote_call_current_success()) {
        return false;
    }
    uint64_t remoteName = r_alloc_str(name);
    uint64_t ivar = remoteName ? r_dlsym_call(
        R_TIMEOUT,"class_getInstanceVariable",cls,remoteName,
        0,0,0,0,0,0) : 0;
    uint64_t offset = ivar && remote_call_current_success()
        ? r_dlsym_call(R_TIMEOUT,"ivar_getOffset",ivar,0,0,0,0,0,0,0)
        : 0;
    if (remoteName && remote_call_current_success()) r_free(remoteName);
    bool valid = ivar && offset >= sizeof(uint64_t) && offset <= 0x400 &&
        remote_call_current_success();
    if (valid && offsetOut) *offsetOut = offset;
    printf("[ICONSERVICES_WRITER_STATE] ivar class=IconCacheService name=%s offset=%llu status=%s mutations=0\n",
           name,(unsigned long long)offset,
           !remote_call_current_success() ? "transport-failure" :
               valid ? "observed" : "unavailable");
    return valid;
}

static bool themer_store_state_isa_word_plausible(uint64_t isa)
{
    if (isa & 1) return true;
    return r_is_objc_ptr(isa) && isa < 0x0000800000000000ULL &&
        (isa & 0x7) == 0;
}

static bool themer_store_state_object_has_exact_class(
    uint64_t object, uint64_t expectedClass, uint64_t isaMask,
    unsigned *runtimeCalls)
{
    if (!r_is_objc_ptr(object) || !r_is_objc_ptr(expectedClass) ||
        object >= 0x0000800000000000ULL || (object & 0x7) != 0 ||
        !remote_call_current_success()) {
        return false;
    }
    uint64_t isa = remote_read64(object);
    if (!themer_store_state_isa_word_plausible(isa)) return false;
    if (isaMask) {
        return (isa & isaMask) == (expectedClass & isaMask);
    }

    // objc_debug_isa_class_mask is a non-API debug global and is hidden on
    // some releases. object_getClass is the runtime's supported C decoder for
    // both pointer and nonpointer ISAs; no Objective-C message is dispatched.
    uint64_t observedClass = r_dlsym_call(
        R_TIMEOUT,"object_getClass",object,0,0,0,0,0,0,0);
    if (runtimeCalls) (*runtimeCalls)++;
    return remote_call_current_success() && observedClass == expectedClass;
}

// The agent's main function retains its sole IconCacheService in callee-saved
// x19 immediately before entering dispatch_main. libdispatch may spill that
// caller value, so inspect both the original registers captured by RemoteCall
// and small callee-save windows along that thread's bounded frame chain. This
// never enumerates the heap. Candidates are not messaged: acceptance requires
// both the runtime nonpointer ISA and the runtime-derived
// IconCacheService->_iconCache -> ISMutableIconCache shape.
static uint64_t themer_store_state_find_agent_service(
    unsigned *matchesOut, unsigned *wordsScannedOut)
{
