    int candidateSourceStates[candidateCap] = {0};
    int candidateSourceKinds[candidateCap] = {0};
    unsigned candidateCount = 0;
    unsigned scanned = 0;
    unsigned framesScanned = 0;
    unsigned stackWordsScanned = 0;

#define ADD_AGENT_SERVICE_CANDIDATE(value_, state_, kind_) do { \
    uint64_t candidate_ = (value_); \
    scanned++; \
    if (!r_is_objc_ptr(candidate_) || candidate_ >= 0x0000800000000000ULL || \
        (candidate_ & 0xf) != 0) break; \
    bool duplicate_ = false; \
    for (unsigned seen_ = 0; seen_ < candidateCount; seen_++) { \
        if (candidates[seen_] == candidate_) { duplicate_ = true; break; } \
    } \
    if (!duplicate_ && candidateCount < candidateCap) { \
        candidates[candidateCount] = candidate_; \
        candidateSourceStates[candidateCount] = (state_); \
        candidateSourceKinds[candidateCount] = (kind_); \
        candidateCount++; \
    } \
} while (0)

    for (size_t stateIndex = 0; stateIndex < originalCount;
         stateIndex++) {
        arm_thread_state64_internal *original = &originals[stateIndex];
        for (int i = 0; i < 29; i++) {
            ADD_AGENT_SERVICE_CANDIDATE(
                original->__x[i],(int)stateIndex,i);
        }

        unsigned stateFrames = 0;
        uint64_t frame = original->__fp;
        uint64_t stackFloor = original->__sp > 0x10000
            ? original->__sp - 0x10000 : 0;
        uint64_t stackCeiling = original->__sp < UINT64_MAX - (8ULL << 20)
            ? original->__sp + (8ULL << 20) : UINT64_MAX;
        for (unsigned depth = 0; depth < frameCap &&
             frame >= stackFloor + 0x200 && frame < stackCeiling &&
             (frame & 0x7) == 0 && remote_call_current_success(); depth++) {
            uint64_t words[frameWords] = {0};
            uint64_t windowStart = frame - 0x200;
            if (!remote_read(windowStart,words,sizeof(words))) break;
            framesScanned++;
            stateFrames++;
            for (unsigned i = 0; i < frameWords; i++) {
                ADD_AGENT_SERVICE_CANDIDATE(
                    words[i],(int)stateIndex,-2);
            }
            uint64_t previousFrame = words[0x200 / sizeof(uint64_t)];
            if (previousFrame <= frame || previousFrame >= stackCeiling) break;
            frame = previousFrame;
        }

        // Some dispatch wait states omit a usable frame-pointer chain. In
        // that case inspect only the first 8 KiB above the captured SP, where
        // ABI callee-save spills for main -> dispatch_main can reside.
        if (stateFrames == 0 && r_is_objc_ptr(original->__sp) &&
            original->__sp < 0x0000800000000000ULL &&
            (original->__sp & 0x7) == 0) {
            enum { stackChunkWords = 128, stackChunkCount = 8 };
            for (unsigned chunk = 0; chunk < stackChunkCount;
                 chunk++) {
                uint64_t words[stackChunkWords] = {0};
                uint64_t address = original->__sp +
                    (uint64_t)chunk * sizeof(words);
                if (address < original->__sp ||
                    !remote_read(address,words,sizeof(words))) break;
                stackWordsScanned += stackChunkWords;
                for (unsigned i = 0; i < stackChunkWords; i++) {
