                cache,cacheClass,isaMask,&runtimeClassCalls)) continue;
        if (!themer_store_state_object_has_exact_class(
                candidate,serviceClass,isaMask,&runtimeClassCalls)) continue;
        match = candidate;
        matchedSource = candidateSourceKinds[i];
        matchedState = candidateSourceStates[i];
