    }

    unsigned matches = match ? 1 : 0;
    if (matchesOut) *matchesOut = matches;
    if (wordsScannedOut) *wordsScannedOut = scanned;
    printf("[ICONSERVICES_WRITER_STATE] discovery status=%s service=0x%llx matches=%u wordsScanned=%u uniquePointers=%u statesInspected=%zu framesScanned=%u stackWordsScanned=%u source=%s sourceState=%d sourceIndex=%d iconCacheOffset=%llu classResolution=%s runtimeClassCalls=%u heapEnumeration=0 mutations=0\n",
           match ? "validated" : "not-found",
           (unsigned long long)match,matches,scanned,candidateCount,
           originalCount,framesScanned,stackWordsScanned,
           matchedSource >= 0 ? "saved-general-register" :
               matchedSource == -2 ? "saved-frame-window" :
               matchedSource == -4 ? "saved-stack-window" : "none",
           matchedState,matchedSource,(unsigned long long)iconCacheOffset,
           isaMask ? "debug-mask" : "runtime-object_getClass",
           runtimeClassCalls);
    return match;
}

