    if (!cache || cache != rawCache) {
        state.invalid++;
        printf("[ICONSERVICES_WRITER_STATE] binding service-iconCache=mismatch raw=0x%llx getter=0x%llx status=invalid\n",
               (unsigned long long)rawCache,(unsigned long long)cache);
        goto finish;
    }
    printf("[ICONSERVICES_WRITER_STATE] binding service-iconCache=equal raw=0x%llx getter=0x%llx status=verified\n",
           (unsigned long long)rawCache,(unsigned long long)cache);
    uint64_t listener = themer_store_state_call(
        &state,service,false,"service.listener","listener","@16@0:8",0,NULL);
    bool listenerBound = listenerOffsetKnown && rawListener &&
        listener == rawListener;
    printf("[ICONSERVICES_WRITER_STATE] service-ivars store=0x%llx storeIndex=0x%llx listenerRaw=0x%llx listenerGetter=0x%llx listenerBinding=%s status=%s readOnly=1\n",
           (unsigned long long)rawServiceStore,
           (unsigned long long)rawServiceIndex,
           (unsigned long long)rawListener,(unsigned long long)listener,
           listenerBound ? "equal" : "unverified",
           !remote_call_current_success() ? "transport-failure" :
               listenerBound ? "observed" : "partial");
    if (!listenerBound) state.invalid++;
    snprintf(report.managerCacheClass,sizeof(report.managerCacheClass),
             "ISMutableIconCache");

    unsigned char agentUUID[16] = {0};
    char agentUUIDText[37] = {0};
    char cacheSalt[160] = {0};
    uint64_t defaultsClass = themer_lookup_class("ISDefaults");
    uint64_t defaults = themer_store_state_call(
        &state,defaultsClass,true,"defaults","sharedInstance","@16@0:8",0,NULL);
    uint64_t saltString = STATE_GET(
        defaults,"defaults.cacheSaltString","cacheSaltString");
    bool saltCharsKnown = false;
    uint64_t saltChars = themer_store_state_call_exact(
        &state,saltString,false,"defaults.cacheSaltString.UTF8String",
        "UTF8String","*16@0:8","r*16@0:8",0,&saltCharsKnown);
    bool saltRead = saltCharsKnown && saltChars &&
        themer_store_surface_read_cstring(
            saltChars,cacheSalt,sizeof(cacheSalt));
    bool agentDerived = saltRead && themer_store_state_derive_agent_uuid(
        cacheSalt,agentUUID,agentUUIDText);
    printf("[ICONSERVICES_WRITER_STATE] agent-derivation cacheSalt=%s saltLength=%zu responseDataUUID=B6C62590-96CE-33E5-9B5B-C78ACBF3893E agentCandidate=%s status=%s readOnly=1\n",
           saltRead ? "observed-redacted" : "unavailable",
           saltRead ? strlen(cacheSalt) : 0,
           agentDerived ? agentUUIDText : "unavailable",
           !remote_call_current_success() ? "transport-failure" :
               agentDerived ? "derived" : "unavailable");

    uint64_t cacheURL = STATE_GET(cache,"cache.cacheURL","cacheURL");
    uint64_t cachePath = STATE_GET(cache,"cache.cachePath","cachePath");
    cacheURLPath = themer_store_state_path(
        &state,cacheURL,true,"cache.cacheURL");
    cachePathText = themer_store_state_path(
        &state,cachePath,false,"cache.cachePath");
    uint64_t store = STATE_GET(cache,"store","store");
    uint64_t index = STATE_GET(cache,"index","storeIndex");
    uint64_t mutableIndex = STATE_GET(
        cache,"mutableIndex","mutableStoreIndex");
    storePath = themer_store_state_path(
        &state,STATE_GET(store,"store.storeURL","storeURL"),true,
        "store.storeURL");
    indexPath = themer_store_state_path(
        &state,STATE_GET(index,"index.indexFileURL","indexFileURL"),true,
        "index.indexFileURL");
    uint64_t storeRegistry = STATE_GET(store,"store.registry","registry");
    STATE_GET(store,"store.connection","connection");
    STATE_GET(store,"store.domain","domain");
    uint64_t sourceRegistry = STATE_GET(
        cache,"cache.unitSourceRegistry","unitSourceRegistry");
    if (storeRegistry) {
        themer_store_state_call(
            &state,storeRegistry,false,"store.registry.count","count",
            "Q16@0:8",0,NULL);
    }
    if (sourceRegistry) {
        themer_store_state_call(
            &state,sourceRegistry,false,"cache.unitSourceRegistry.count",
            "count","Q16@0:8",0,NULL);
    }
    printf("[ICONSERVICES_WRITER_STATE] binding cacheURL-cachePath=%s cacheURL-storeURL=%s indexParent-storeURL=%s storeIndex-mutableStoreIndex=%s\n",
           cacheURLPath&&cachePathText?
               ([cacheURLPath isEqualToString:cachePathText]?"equal":"different"):"unknown",
           cacheURLPath&&storePath?
               ([cacheURLPath isEqualToString:storePath]?"equal":"different"):"unknown",
           indexPath&&storePath?
               ([[indexPath stringByDeletingLastPathComponent]
                   isEqualToString:storePath]?"equal":"different"):"unknown",
           index&&mutableIndex?(index==mutableIndex?"equal":"different"):"unknown");
    printf("[ICONSERVICES_WRITER_STATE] binding serviceStore-cacheStore=%s serviceStoreIndex-mutableStoreIndex=%s serviceStore=0x%llx serviceStoreIndex=0x%llx cacheStore=0x%llx mutableStoreIndex=0x%llx observation=service-ivars-may-be-optional\n",
           rawServiceStore ? (rawServiceStore==store?"equal":"different") :
               "clean-nil",
           rawServiceIndex ? (rawServiceIndex==mutableIndex?"equal":"different") :
               "clean-nil",
           (unsigned long long)rawServiceStore,
           (unsigned long long)rawServiceIndex,
           (unsigned long long)store,(unsigned long long)mutableIndex);
    if (index != mutableIndex) state.invalid++;
    snprintf(report.storeClass,sizeof(report.storeClass),"ISStore");
    snprintf(report.storeIndexClass,sizeof(report.storeIndexClass),
             "ISMutableStoreIndex");

    uint64_t indexData = STATE_GET(index,"index.data","data");
    uint64_t internalData = STATE_GET(
        index,"index._internalData","_internalData");
    themer_store_state_data(&state,indexData,"index.data",
        agentDerived ? agentUUID : NULL,
        agentDerived ? agentUUIDText : NULL);
    if (indexData && internalData == indexData) {
        printf("[ICONSERVICES_WRITER_STATE] data field=index._internalData aliasOf=index.data object=0x%llx capture=shared digestCount=1 nonatomic=1\n",
               (unsigned long long)internalData);
    } else {
        themer_store_state_data(&state,internalData,"index._internalData",
            agentDerived ? agentUUID : NULL,
            agentDerived ? agentUUIDText : NULL);
    }

    themer_store_state_inspect_candidate(
        &state,store,sourceRegistry,storePath,
        "directCandidate","8BBC6635-5124-4885-951B-339C3BEA1FE8");
    if (agentDerived) {
        themer_store_state_inspect_candidate(
            &state,store,sourceRegistry,storePath,
            "agentCandidate",agentUUIDText);
    } else {
        state.rejected++;
        printf("[ICONSERVICES_WRITER_STATE] candidate=agentCandidate status=derivation-unavailable invoked=0\n");
    }

finish:
    themer_store_state_hash(&state,&state.rejected,sizeof(state.rejected));
    themer_store_state_hash(&state,&state.nils,sizeof(state.nils));
    themer_store_state_hash(&state,&state.invalid,sizeof(state.invalid));
    report.transportClean = remote_call_current_success();
    report.result = !report.transportClean
        ? ThemerSpotlightStoreSurfaceInventoryTransportFailed
        : state.rejected || state.invalid
            ? ThemerSpotlightStoreSurfaceInventoryPartial
            : ThemerSpotlightStoreSurfaceInventoryComplete;
    snprintf(report.reason,sizeof(report.reason),
             "writerState=%016llx serviceMatches=%u wordsScanned=%u rejected=%u nil=%u invalid=%u",
             (unsigned long long)state.fingerprint,serviceMatches,
             wordsScanned,state.rejected,state.nils,
             state.invalid);
    printf("[ICONSERVICES_WRITER_STATE] writer-state context=iconservicesagent pid=%d %s result=%d readOnly=1 generated=0 serviceDispatch=0 storeMutations=0 fileMutations=0 recoveryAccess=0\n",
           remote_call_current_pid(),report.reason,report.result);
    if (reportOut) *reportOut = report;
    return report.result;
}
#undef STATE_GET

// All runtime copy APIs used here write unsigned int counts and return a
// malloc-owned pointer array. Validate the entire address span before reading.
static uint64_t themer_store_surface_copy_list(
    const char *api, uint64_t owner, uint32_t cap, uint32_t *scanCount,
    ThemerSpotlightStoreSurfaceInventoryReport *report)
{
    *scanCount = 0;
    uint32_t count = 0;
    uint64_t buffer = r_dlsym_call(R_TIMEOUT, "malloc", sizeof(count), 0, 0, 0, 0, 0, 0, 0);
    bool ready = buffer && remote_call_current_success() && remote_write(buffer, &count, sizeof(count));
    uint64_t list = ready ? r_dlsym_call(R_TIMEOUT, api, owner, buffer, 0, 0, 0, 0, 0, 0) : 0;
    ready = ready && remote_call_current_success() && remote_read(buffer, &count, sizeof(count));
    if (buffer && remote_call_current_success()) r_free(buffer);
    if (!ready || !remote_call_current_success() || (count && !list)) {
        report->methodListTruncated = true;
    } else if ((uint64_t)count > UINT64_MAX / sizeof(uint64_t) ||
               list > UINT64_MAX - (uint64_t)count * sizeof(uint64_t)) {
        report->overflowDetected = true;
    } else {
        *scanCount = count > cap ? cap : count;
        if (count > cap) report->methodListTruncated = true;
    }
    printf("[ICONSERVICES_STORE_SURFACE] list api=%s declared=%u scanned=%u invoked=0\n",
           api, count, *scanCount);
    return list;
}

static bool themer_store_surface_scan_class(
    const char *target, uint64_t cls, bool includeClassMethods,
    ThemerSpotlightStoreSurfaceInventoryReport *report)
{
    if (!r_is_objc_ptr(cls) || !remote_call_current_success()) return false;
    char className[192] = {0};
    uint64_t name = r_dlsym_call(R_TIMEOUT, "class_getName", cls, 0, 0, 0, 0, 0, 0, 0);
    if (!themer_store_surface_read_cstring(name, className, sizeof(className))) {
        report->methodListTruncated = true;
        return false;
    }
    printf("[ICONSERVICES_STORE_SURFACE] class target=%s class=%s\n", target, className);
    report->classesScanned++;
    // Direct instance declarations, direct metaclass declarations, then ivars.
    for (unsigned kind = 0; kind < 3 && remote_call_current_success(); kind++) {
        if (kind == 1 && !includeClassMethods) continue;
        uint64_t owner = kind == 1 ? r_dlsym_call(R_TIMEOUT, "object_getClass", cls, 0, 0, 0, 0, 0, 0, 0) : cls;
        if (!r_is_objc_ptr(owner)) { report->methodListTruncated = true; continue; }
        uint32_t count = 0;
        uint64_t list = themer_store_surface_copy_list(
            kind == 2 ? "class_copyIvarList" : "class_copyMethodList", owner,
            kind == 2 ? THEMER_STORE_SURFACE_IVAR_CAP : THEMER_STORE_SURFACE_METHOD_CAP,
            &count, report);
        if (kind != 2) report->methodListsScanned++;
        for (uint32_t i = 0; i < count && remote_call_current_success(); i++) {
            if (report->candidateCount >= THEMER_STORE_SURFACE_CANDIDATE_CAP) {
                report->candidateTruncated = true;
                break;
            }
            uint64_t entry = 0;
            if (!remote_read(list + (uint64_t)i * sizeof(entry), &entry, sizeof(entry)) || !entry) {
                report->methodListTruncated = true;
                continue;
            }
            uint64_t memberName = r_dlsym_call(R_TIMEOUT, kind == 2 ? "ivar_getName" : "method_getName", entry, 0, 0, 0, 0, 0, 0, 0);
            if (kind != 2 && memberName) memberName = r_dlsym_call(R_TIMEOUT, "sel_getName", memberName, 0, 0, 0, 0, 0, 0, 0);
            uint64_t encoding = r_dlsym_call(R_TIMEOUT, kind == 2 ? "ivar_getTypeEncoding" : "method_getTypeEncoding", entry, 0, 0, 0, 0, 0, 0, 0);
            char member[256] = {0}, types[256] = {0};
            if (!themer_store_surface_read_cstring(memberName, member, sizeof(member)) ||
                !themer_store_surface_read_cstring(encoding, types, sizeof(types))) {
                report->methodListTruncated = true;
                continue;
            }
            if (kind == 2) {
                int64_t offset = (int64_t)r_dlsym_call(R_TIMEOUT, "ivar_getOffset", entry, 0, 0, 0, 0, 0, 0, 0);
                if (!remote_call_current_success()) break;
                if (offset < 0) { report->methodListTruncated = true; continue; }
                printf("[ICONSERVICES_STORE_SURFACE] ivar class=%s name=%s types=\"%s\" offset=%lld invoked=0\n",
                       className, member, types, (long long)offset);
            } else {
                if (!remote_call_current_success()) break;
                printf("[ICONSERVICES_STORE_SURFACE] method class=%s kind=%c selector=%s types=\"%s\" invoked=0\n",
                       className, kind == 1 ? '+' : '-', member, types);
                report->methodsScanned++;
            }
            report->candidateCount++;
        }
        if (list && remote_call_current_success()) r_free(list);
    }
    return remote_call_current_success();
}

static bool themer_store_surface_scan_object(
    const char *target, uint64_t object,
    ThemerSpotlightStoreSurfaceInventoryReport *report)
{
    uint64_t cls = r_is_objc_ptr(object) ? r_dlsym_call(R_TIMEOUT, "object_getClass", object, 0, 0, 0, 0, 0, 0, 0) : 0;
    return themer_store_surface_scan_class(target, cls, false, report);
}

static bool themer_store_surface_class_matches(const char *name)
{
    // ASCII class names; avoid locale-dependent matching or remote messaging.
    char lower[192];
    size_t n = strlen(name);
    if (n >= sizeof(lower)) return false;
    for (size_t i = 0; i <= n; i++) {
        unsigned char ch = (unsigned char)name[i];
        lower[i] = (char)(ch >= 'A' && ch <= 'Z' ? ch + ('a' - 'A') : ch);
    }
    return strstr(lower, "store") || strstr(lower, "unit") || strstr(lower, "registry");
}

static bool themer_store_surface_scan_image(
    uint64_t managerClass, ThemerSpotlightStoreSurfaceInventoryReport *report)
{
    uint64_t imageName = r_dlsym_call(R_TIMEOUT, "class_getImageName", managerClass, 0, 0, 0, 0, 0, 0, 0);
    char imagePath[512] = {0};
    if (!themer_store_surface_read_cstring(imageName, imagePath, sizeof(imagePath))) return false;
    const char *leaf = strrchr(imagePath, '/');
    if (!leaf || strcmp(leaf + 1, "IconServices") != 0) return false;
    printf("[ICONSERVICES_STORE_SURFACE] image=%s\n", imagePath);
    uint32_t count = 0, matches = 0;
    uint64_t list = themer_store_surface_copy_list("objc_copyClassNamesForImage", imageName,
        THEMER_STORE_SURFACE_IMAGE_CLASS_CAP, &count, report);
    for (uint32_t i = 0; i < count && remote_call_current_success(); i++) {
        uint64_t name = 0;
        char className[192] = {0};
        if (!remote_read(list + (uint64_t)i * sizeof(name), &name, sizeof(name)) ||
            !themer_store_surface_read_cstring(name, className, sizeof(className))) {
            report->methodListTruncated = true;
            continue;
        }
        if (!themer_store_surface_class_matches(className)) continue;
        if (matches >= THEMER_STORE_SURFACE_MATCH_CAP) { report->candidateTruncated = true; break; }
        matches++;
        uint64_t cls = themer_lookup_class(className);
        if (!themer_store_surface_scan_class("image", cls, true, report)) report->methodListTruncated = true;
    }
    if (list && remote_call_current_success()) r_free(list);
    printf("[ICONSERVICES_STORE_SURFACE] imageClasses=%u matches=%u\n", count, matches);
    return remote_call_current_success();
}

ThemerSpotlightStoreSurfaceInventoryResult
themer_spotlight_iconservices_inspect_store_surface_in_session(
    ThemerSpotlightStoreSurfaceInventoryReport *reportOut)
{
    ThemerSpotlightStoreSurfaceInventoryReport report = {0};
    report.result = ThemerSpotlightStoreSurfaceInventoryTransportFailed;
    if (!remote_call_current_success()) {
        snprintf(report.reason, sizeof(report.reason), "transport-down-before-start");
        if (reportOut) *reportOut = report;
        return report.result;
    }
    if (!themer_ensure_iconservices_loaded()) {
        report.result = remote_call_current_success()
            ? ThemerSpotlightStoreSurfaceInventoryUnavailable
            : ThemerSpotlightStoreSurfaceInventoryTransportFailed;
        snprintf(report.reason, sizeof(report.reason), "%s",
                 remote_call_current_success() ? "iconservices-unavailable" :
                                                 "transport-during-framework-load");
        if (reportOut) *reportOut = report;
        return report.result;
    }

    uint64_t managerClass = themer_lookup_class("ISIconManager");
    char types[192] = {0};
    report.managerABI = themer_store_surface_getter_encoding(
        managerClass, true, "manager", "sharedInstance", types, sizeof(types));
    if (!report.managerABI) goto abi_rejected;
    uint64_t manager = r_msg2_main(managerClass, "sharedInstance", 0, 0, 0, 0);
    if (!remote_call_current_success()) goto transport_failed;
    if (!r_is_objc_ptr(manager) || !themer_store_surface_read_object_class(
            manager, report.managerClass, sizeof(report.managerClass))) {
        snprintf(report.reason, sizeof(report.reason), "manager-nil-or-class-unreadable");
        goto partial;
    }

    report.iconCacheABI = themer_store_surface_getter_encoding(
        r_dlsym_call(R_TIMEOUT, "object_getClass", manager,
                     0, 0, 0, 0, 0, 0, 0), false,
        "manager", "iconCache", types, sizeof(types));
    if (!report.iconCacheABI) goto abi_rejected;
    uint64_t cache = r_msg2_main(manager, "iconCache", 0, 0, 0, 0);
    if (!remote_call_current_success()) goto transport_failed;
    if (!r_is_objc_ptr(cache) || !themer_store_surface_read_object_class(
            cache, report.managerCacheClass, sizeof(report.managerCacheClass))) {
        snprintf(report.reason, sizeof(report.reason), "manager-cache-nil-or-class-unreadable");
        goto partial;
    }

    uint64_t cacheClass = r_dlsym_call(R_TIMEOUT, "object_getClass", cache,
                                       0, 0, 0, 0, 0, 0, 0);
    report.storeABI = themer_store_surface_getter_encoding(
        cacheClass, false, "manager-cache", "store", types, sizeof(types));
    if (!report.storeABI) goto abi_rejected;
    uint64_t store = r_msg2_main(cache, "store", 0, 0, 0, 0);
    if (!remote_call_current_success()) goto transport_failed;
    if (!r_is_objc_ptr(store) || !themer_store_surface_read_object_class(
            store, report.storeClass, sizeof(report.storeClass))) {
        snprintf(report.reason, sizeof(report.reason), "store-nil-or-class-unreadable");
        goto partial;
    }

    report.storeIndexABI = themer_store_surface_getter_encoding(
        cacheClass, false, "manager-cache", "storeIndex", types, sizeof(types));
    if (!report.storeIndexABI) goto abi_rejected;
    uint64_t storeIndex = r_msg2_main(cache, "storeIndex", 0, 0, 0, 0);
    if (!remote_call_current_success()) goto transport_failed;
    if (!r_is_objc_ptr(storeIndex) || !themer_store_surface_read_object_class(
            storeIndex, report.storeIndexClass, sizeof(report.storeIndexClass))) {
        snprintf(report.reason, sizeof(report.reason), "store-index-nil-or-class-unreadable");
        goto partial;
    }

    if (!themer_store_surface_scan_object("manager-cache", cache, &report) ||
        !themer_store_surface_scan_object("store", store, &report) ||
        !themer_store_surface_scan_object("store-index", storeIndex, &report)) {
        if (!remote_call_current_success()) goto transport_failed;
        snprintf(report.reason, sizeof(report.reason), "runtime-metadata-incomplete");
        goto partial;
    }
    // Re-check the concrete store's exact getter ABI immediately before dispatch.
    uint64_t storeClass = r_dlsym_call(R_TIMEOUT, "object_getClass", store, 0, 0, 0, 0, 0, 0, 0);
    bool registryABI = themer_store_surface_getter_encoding(
        storeClass, false, "store", "registry", types, sizeof(types));
    if (registryABI) {
        uint64_t registry = r_msg2_main(store, "registry", 0, 0, 0, 0);
        if (!themer_store_surface_scan_object("registry", registry, &report)) report.methodListTruncated = true;
    } else {
        report.methodListTruncated = true;
    }
    if (!remote_call_current_success()) goto transport_failed;
    if (!themer_store_surface_scan_image(managerClass, &report)) report.methodListTruncated = true;
    if (!remote_call_current_success()) goto transport_failed;
    if (report.methodListTruncated || report.candidateTruncated ||
        report.overflowDetected) {
        snprintf(report.reason, sizeof(report.reason), "bounded-metadata-truncated");
        goto partial;
    }
    report.result = ThemerSpotlightStoreSurfaceInventoryComplete;
    report.transportClean = true;
    snprintf(report.reason, sizeof(report.reason), "complete");
    goto finished;

abi_rejected:
    report.result = remote_call_current_success()
        ? ThemerSpotlightStoreSurfaceInventoryABIRejected
        : ThemerSpotlightStoreSurfaceInventoryTransportFailed;
    snprintf(report.reason, sizeof(report.reason), "%s",
             remote_call_current_success() ? "getter-abi-rejected" :
                                             "transport-during-abi-gate");
    goto finished;
transport_failed:
    report.result = ThemerSpotlightStoreSurfaceInventoryTransportFailed;
    snprintf(report.reason, sizeof(report.reason), "transport-unstable");
    goto finished;
partial:
    report.result = ThemerSpotlightStoreSurfaceInventoryPartial;
    report.transportClean = remote_call_current_success();
finished:
    report.transportClean = remote_call_current_success();
    printf("[ICONSERVICES_STORE_SURFACE] summary result=%d manager=%s "
           "managerCache=%s store=%s storeIndex=%s classes=%d lists=%d "
           "methods=%d candidates=%d listTruncated=%d candidateTruncated=%d "
           "overflow=%d transport=%d reason=%s generated=0 mutations=0\n",
           report.result,
           report.managerClass[0] ? report.managerClass : "-",
           report.managerCacheClass[0] ? report.managerCacheClass : "-",
           report.storeClass[0] ? report.storeClass : "-",
           report.storeIndexClass[0] ? report.storeIndexClass : "-",
           report.classesScanned, report.methodListsScanned,
           report.methodsScanned, report.candidateCount,
           report.methodListTruncated, report.candidateTruncated,
           report.overflowDetected, report.transportClean,
           report.reason[0] ? report.reason : "-");
    if (reportOut) *reportOut = report;
    return report.result;
}

static NSData *themer_rounded_png_data(NSData *bytes, const char *label)
{
    if (!bytes || bytes.length == 0 || bytes.length > kThemerMaxPngBytes) return bytes;

    @autoreleasepool {
        UIImage *src = [UIImage imageWithData:bytes];
        CGImageRef cg = src.CGImage;
        if (!src || !cg) return bytes;

        size_t width = CGImageGetWidth(cg);
        size_t height = CGImageGetHeight(cg);
        if (width < 2 || height < 2) return bytes;

        CGSize size = CGSizeMake((CGFloat)width, (CGFloat)height);
        UIGraphicsImageRendererFormat *format = [UIGraphicsImageRendererFormat defaultFormat];
        format.scale = 1.0;
        format.opaque = NO;

        CGFloat radius = (CGFloat)MIN(width, height) * 0.225;
        UIGraphicsImageRenderer *renderer =
            [[UIGraphicsImageRenderer alloc] initWithSize:size format:format];
        UIImage *rounded = [renderer imageWithActions:^(UIGraphicsImageRendererContext *ctx) {
            (void)ctx;
            CGRect rect = CGRectMake(0, 0, size.width, size.height);
            [[UIBezierPath bezierPathWithRoundedRect:rect cornerRadius:radius] addClip];
            [src drawInRect:rect];
        }];

        NSData *out = UIImagePNGRepresentation(rounded);
        if (out.length > 0 && out.length <= kThemerMaxPngBytes) return out;

        if (out.length > kThemerMaxPngBytes) {
            printf("[THEMER] rounded PNG too large bundle=%s rounded=%lu original=%lu cap=%zu\n",
                   label ?: "?",
                   (unsigned long)out.length,
                   (unsigned long)bytes.length,
                   kThemerMaxPngBytes);
        }
        return bytes;
    }
}

static double themer_screen_scale(void)
{
    double scale = 3.0;
    uint64_t UIScreen = r_class("UIScreen");
    uint64_t screen = r_is_objc_ptr(UIScreen)
        ? r_msg2(UIScreen, "mainScreen", 0, 0, 0, 0) : 0;
    if (r_is_objc_ptr(screen) && r_responds_main(screen, "scale")) {
        uint64_t bits = r_msg2_main(screen, "scale", 0, 0, 0, 0);
        memcpy(&scale, &bits, sizeof(scale));
    }
    if (scale < 1.0 || scale > 4.0) scale = 3.0;
    return scale;
}

static uint64_t themer_make_is_descriptor(double pointSize,
                                          double scale,
                                          int64_t appearance,
                                          uint64_t variant,
                                          bool useVariantFactory)
{
    uint64_t descCls = themer_lookup_class("ISImageDescriptor");
    if (!r_is_objc_ptr(descCls)) return 0;

    uint64_t desc = 0;
    if (useVariantFactory &&
        r_responds_main(descCls, "imageDescriptorWithIconVariant:options:")) {
        desc = r_msg2_main(descCls, "imageDescriptorWithIconVariant:options:",
                           variant, 0, 0, 0);
        if (r_is_objc_ptr(desc)) {
            desc = r_msg2(desc, "retain", 0, 0, 0, 0);
        }
    }

    if (!r_is_objc_ptr(desc)) {
        uint64_t alloc = r_msg2(descCls, "alloc", 0, 0, 0, 0);
        struct { double width; double height; } size = { pointSize, pointSize };
        desc = r_is_objc_ptr(alloc)
            ? r_msg2_main_raw(alloc, "initWithSize:scale:",
                              &size, sizeof(size),
                              &scale, sizeof(scale),
                              NULL, 0, NULL, 0)
            : 0;
    }
    if (!r_is_objc_ptr(desc)) return 0;

    struct { double width; double height; } size = { pointSize, pointSize };
    if (r_responds_main(desc, "setSize:")) {
        r_msg2_main_raw(desc, "setSize:",
                        &size, sizeof(size),
                        NULL, 0, NULL, 0, NULL, 0);
    }
    if (r_responds_main(desc, "setScale:")) {
        r_msg2_main_raw(desc, "setScale:",
                        &scale, sizeof(scale),
                        NULL, 0, NULL, 0, NULL, 0);
    }
    if (r_responds_main(desc, "setAppearance:")) {
        r_msg2_main(desc, "setAppearance:", (uint64_t)appearance, 0, 0, 0);
    }
    if (r_responds_main(desc, "setAppearanceVariant:")) {
        r_msg2_main(desc, "setAppearanceVariant:", variant, 0, 0, 0);
    }
    if (r_responds_main(desc, "setIgnoreCache:")) {
        r_msg2_main(desc, "setIgnoreCache:", 0, 0, 0, 0);
    }
    return desc;
}

static bool themer_read_remote_description(uint64_t obj, char *out, size_t outLen)
{
    if (!out || outLen == 0) return false;
    out[0] = '\0';
    if (!r_is_objc_ptr(obj) || !r_responds_main(obj, "description")) return false;

    uint64_t desc = r_msg2_main(obj, "description", 0, 0, 0, 0);
    return r_is_objc_ptr(desc) && r_read_nsstring(desc, out, outLen) && out[0];
}

static double themer_read_remote_double_property(uint64_t obj,
                                                 const char *selName,
                                                 double fallback,
                                                 bool *okOut)
{
    if (okOut) *okOut = false;
    if (!r_is_objc_ptr(obj) || !selName || !r_responds_main(obj, selName)) {
        return fallback;
    }

    uint64_t bits = r_msg2_main(obj, selName, 0, 0, 0, 0);
    double value = fallback;
    memcpy(&value, &bits, sizeof(value));
    if (value < -10000.0 || value > 10000.0) return fallback;
    if (okOut) *okOut = true;
    return value;
}

static uint64_t themer_read_remote_uint_property(uint64_t obj,
                                                 const char *selName,
                                                 bool *okOut)
{
    if (okOut) *okOut = false;
    if (!r_is_objc_ptr(obj) || !selName || !r_responds_main(obj, selName)) {
        return 0;
    }
    if (okOut) *okOut = true;
    return r_msg2_main(obj, selName, 0, 0, 0, 0);
}

static void themer_log_iconservices_descriptor(const char *bundle,
                                               const char *phase,
                                               uint64_t desc,
                                               uint64_t after,
                                               uint64_t cacheImage)
{
    if (!bundle || !r_is_objc_ptr(desc)) {
        return;
    }
    bool failed = after != cacheImage;
    if (!failed) {
        return;
    }
    if (gThemerSeedFailureLogBudget <= 0) {
        return;
    }
    gThemerSeedFailureLogBudget--;

    struct { double w; double h; } size = {0.0, 0.0};
    bool hasSize = r_responds_main(desc, "size") &&
        r_msg2_main_struct_ret(desc, "size", &size, sizeof(size),
            NULL, 0, NULL, 0, NULL, 0, NULL, 0);

    bool hasScale = false;
    double scale = themer_read_remote_double_property(desc, "scale", 0.0,
                                                      &hasScale);
    bool hasAppearance = false;
    uint64_t appearance = themer_read_remote_uint_property(desc, "appearance",
                                                           &hasAppearance);
    bool hasAppearanceVariant = false;
    uint64_t appearanceVariant =
        themer_read_remote_uint_property(desc, "appearanceVariant",
                                         &hasAppearanceVariant);
    bool hasIconVariant = false;
    uint64_t iconVariant = themer_read_remote_uint_property(desc, "iconVariant",
                                                            &hasIconVariant);
    bool hasVariantOptions = false;
    uint64_t variantOptions =
        themer_read_remote_uint_property(desc, "variantOptions",
                                         &hasVariantOptions);

    char descCls[96] = {0};
    char descText[220] = {0};
    themer_read_class_name(desc, descCls, sizeof(descCls));
    themer_read_remote_description(desc, descText, sizeof(descText));

    printf("[THEMER] seed-desc-fail bundle=%s phase=%s desc=0x%llx "
           "class=%s size=%s%.1fx%.1f scale=%s%.2f appearance=%s%llu "
           "appearanceVariant=%s%llu iconVariant=%s%llu variantOptions=%s%llu "
           "after=0x%llx cacheImage=0x%llx afterOK=%d "
           "desc=\"%s\"\n",
           bundle,
           phase ?: "?",
           (unsigned long long)desc,
           descCls,
           hasSize ? "" : "?",
           size.w,
           size.h,
           hasScale ? "" : "?",
           scale,
           hasAppearance ? "" : "?",
           (unsigned long long)appearance,
           hasAppearanceVariant ? "" : "?",
           (unsigned long long)appearanceVariant,
           hasIconVariant ? "" : "?",
           (unsigned long long)iconVariant,
           hasVariantOptions ? "" : "?",
           (unsigned long long)variantOptions,
           (unsigned long long)after,
           (unsigned long long)cacheImage,
           after == cacheImage,
           descText);
}

static uint64_t themer_make_if_image(uint64_t uiImage)
{
    if (!r_is_objc_ptr(uiImage)) return 0;

    uint64_t IFImage = themer_lookup_class("IFImage");
    if (!r_is_objc_ptr(IFImage)) return 0;

    uint64_t cgImage = r_responds_main(uiImage, "CGImage")
        ? r_msg2_main(uiImage, "CGImage", 0, 0, 0, 0) : 0;
    if (!cgImage) return 0;

    double scale = themer_screen_scale();
    if (r_responds_main(uiImage, "scale")) {
        uint64_t bits = r_msg2_main(uiImage, "scale", 0, 0, 0, 0);
        memcpy(&scale, &bits, sizeof(scale));
        if (scale < 1.0 || scale > 4.0) scale = themer_screen_scale();
    }

    uint64_t alloc = r_msg2(IFImage, "alloc", 0, 0, 0, 0);
    if (!r_is_objc_ptr(alloc)) return 0;
    return r_msg2_main_raw(alloc, "initWithCGImage:scale:",
                           &cgImage, sizeof(cgImage),
                           &scale, sizeof(scale),
                           NULL, 0, NULL, 0);
}

static uint64_t themer_ensure_iconservices_icon_class(uint64_t currentClass,
                                                      uint64_t *baseClassOut)
{
    if (baseClassOut) *baseClassOut = 0;
    if (!r_is_objc_ptr(currentClass)) return 0;

    uint64_t baseClass = currentClass;
    char clsName[160] = {0};
    themer_read_class_object_name(baseClass, clsName, sizeof(clsName));
    while (strncmp(clsName, "CNDThemedISIcon_", 16) == 0) {
        uint64_t superCls = r_dlsym_call(R_TIMEOUT, "class_getSuperclass",
                                         baseClass, 0, 0, 0, 0, 0, 0, 0);
        if (!r_is_objc_ptr(superCls) || superCls == baseClass) break;
        baseClass = superCls;
        themer_read_class_object_name(baseClass, clsName, sizeof(clsName));
    }
    if (!clsName[0]) return 0;
    if (baseClassOut) *baseClassOut = baseClass;

    char subName[192] = {0};
    snprintf(subName, sizeof(subName), "CNDThemedISIcon_%s", clsName);

    uint64_t sub = themer_lookup_class(subName);
    uint64_t getAssocImp = themer_remote_symbol_addr("objc_getAssociatedObject");
    static const char *imageSels[] = {
        "imageForDescriptor:",
    };

    bool ok = getAssocImp != 0;
    if (r_is_objc_ptr(sub)) {
        ok = ok && themer_ensure_methods(sub, imageSels, 1,
                                         getAssocImp, "@@:@");
        if (!ok) {
            printf("[THEMER] IconServices object graft existing subclass incomplete %s getAssoc=0x%llx\n",
                   subName,
                   (unsigned long long)getAssocImp);
        }
        return sub;
    }

    uint64_t name = r_alloc_str(subName);
    if (!name) return 0;
    sub = r_dlsym_call(R_TIMEOUT, "objc_allocateClassPair",
                       baseClass, name, 0, 0, 0, 0, 0, 0);
    r_free(name);
    if (!r_is_objc_ptr(sub)) return 0;

    ok = ok && themer_ensure_methods(sub, imageSels, 1,
                                     getAssocImp, "@@:@");
    r_dlsym_call(R_TIMEOUT, "objc_registerClassPair",
                 sub, 0, 0, 0, 0, 0, 0, 0);

    if (!ok) {
        printf("[THEMER] IconServices object graft subclass incomplete %s getAssoc=0x%llx\n",
               subName,
               (unsigned long long)getAssocImp);
        return 0;
    }
    return sub;
}

static int themer_graft_iconservices_icon(const char *bundle,
                                          uint64_t icon,
                                          uint64_t cacheImage,
                                          ThemerEntry *entry)
{
    if (!bundle || !bundle[0] ||
        !r_is_objc_ptr(icon) ||
        !r_is_objc_ptr(cacheImage) ||
        !entry) {
        return 0;
    }
    if (entry->iconServicesGrafted &&
        r_is_objc_ptr(entry->iconServicesIcon) &&
        entry->iconServicesIcon != icon) {
        uint64_t oldSel = r_sel("imageForDescriptor:");
        if (oldSel) {
            r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                         entry->iconServicesIcon, oldSel,
                         0, 1, 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(entry->iconServicesOriginalClass)) {
            r_dlsym_call(R_TIMEOUT, "object_setClass",
                         entry->iconServicesIcon,
                         entry->iconServicesOriginalClass,
                         0, 0, 0, 0, 0, 0);
        }
        r_msg2(entry->iconServicesIcon, "release", 0, 0, 0, 0);
        entry->iconServicesIcon = 0;
        entry->iconServicesOriginalClass = 0;
        entry->iconServicesGrafted = false;
    }
    if (entry->iconServicesGrafted &&
        entry->iconServicesIcon == icon) {
        uint64_t sel = r_sel("imageForDescriptor:");
        if (sel) {
            r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                         icon, sel, cacheImage, 1, 0, 0, 0, 0);
        }
        return 1;
    }

    uint64_t currentClass = r_dlsym_call(R_TIMEOUT, "object_getClass",
                                         icon, 0, 0, 0, 0, 0, 0, 0);
    uint64_t baseClass = 0;
    uint64_t themedClass = themer_ensure_iconservices_icon_class(currentClass,
                                                                 &baseClass);
    uint64_t sel = r_sel("imageForDescriptor:");
    if (!r_is_objc_ptr(currentClass) ||
        !r_is_objc_ptr(themedClass) ||
        !sel) {
        return 0;
    }

    r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                 icon, sel, cacheImage, 1, 0, 0, 0, 0);

    bool changed = themedClass != currentClass;
    if (changed) {
        r_msg2(icon, "retain", 0, 0, 0, 0);
        r_dlsym_call(R_TIMEOUT, "object_setClass",
                     icon, themedClass, 0, 0, 0, 0, 0, 0);
    } else if (!entry->iconServicesGrafted) {
        r_msg2(icon, "retain", 0, 0, 0, 0);
    }
    entry->iconServicesIcon = icon;
    entry->iconServicesOriginalClass = r_is_objc_ptr(baseClass)
        ? baseClass : currentClass;
    entry->iconServicesGrafted = true;

    if (!gThemerIconServicesProbeLogged) {
        char oldClass[96] = {0};
        char newClass[96] = {0};
        themer_read_class_object_name(currentClass, oldClass, sizeof(oldClass));
        themer_read_class_object_name(themedClass, newClass, sizeof(newClass));
        printf("[THEMER] IconServices object graft bundle=%s icon=0x%llx class=%s themedClass=%s changed=%d ifImage=0x%llx\n",
               bundle,
               (unsigned long long)icon,
               oldClass,
               newClass,
               changed,
               (unsigned long long)cacheImage);
    }

    return 1;
}

static int themer_call_zero_arg_cache_clears(uint64_t imageCache,
                                             const char *bundle)
{
    if (!remote_call_current_success() || !r_is_objc_ptr(imageCache)) return 0;
    static const char *selectors[] = {
        "removeAllImages",
        "removeAllCachedImages",
        "clearAllImages",
        "clearCachedImages",
        "_clearCachedImages",
        "purgeCachedImages",
        "purge",
        "flush",
        "invalidate",
    };

    int called = 0;
    NSMutableArray<NSString *> *hits = nil;
    for (size_t i = 0; i < sizeof(selectors) / sizeof(selectors[0]); i++) {
        if (!remote_call_current_success()) break;
        const char *sel = selectors[i];
        if (!r_responds_main(imageCache, sel)) continue;
        if (!remote_call_current_success()) break;
        r_msg2_main(imageCache, sel, 0, 0, 0, 0);
        if (!remote_call_current_success()) break;
        called++;
        if (gThemerCacheClearLogBudget > 0) {
            if (!hits) hits = [NSMutableArray array];
            [hits addObject:[NSString stringWithUTF8String:sel]];
        }
    }
    if (called > 0 && gThemerCacheClearLogBudget > 0) {
        printf("[THEMER] cache-clear bundle=%s scope=imageCache zero=%d selectors=%s\n",
               bundle ?: "?",
               called,
               hits.count ? [hits componentsJoinedByString:@","].UTF8String : "");
        gThemerCacheClearLogBudget--;
    }
    return called;
}

static int themer_call_descriptor_cache_clears(uint64_t imageCache,
                                               uint64_t desc,
                                               const char *bundle)
{
    if (!remote_call_current_success() ||
        !r_is_objc_ptr(imageCache) || !r_is_objc_ptr(desc)) return 0;
    static const char *selectors[] = {
        "removeImageForDescriptor:",
        "_removeImageForDescriptor:",
        "removeCachedImageForDescriptor:",
        "_removeCachedImageForDescriptor:",
        "removeImageForImageDescriptor:",
        "_removeImageForImageDescriptor:",
        "clearImageForDescriptor:",
        "_clearImageForDescriptor:",
        "invalidateImageForDescriptor:",
        "_invalidateImageForDescriptor:",
        "invalidateCacheForDescriptor:",
        "_invalidateCacheForDescriptor:",
        "deleteImageForDescriptor:",
        "_deleteImageForDescriptor:",
    };

    int called = 0;
    NSMutableArray<NSString *> *hits = nil;
    for (size_t i = 0; i < sizeof(selectors) / sizeof(selectors[0]); i++) {
        if (!remote_call_current_success()) break;
        const char *sel = selectors[i];
        if (!r_responds_main(imageCache, sel)) continue;
        if (!remote_call_current_success()) break;
        r_msg2_main(imageCache, sel, desc, 0, 0, 0);
        if (!remote_call_current_success()) break;
        called++;
        if (gThemerCacheClearLogBudget > 0) {
            if (!hits) hits = [NSMutableArray array];
            [hits addObject:[NSString stringWithUTF8String:sel]];
        }
    }
    if (called > 0 && gThemerCacheClearLogBudget > 0) {
        printf("[THEMER] cache-clear bundle=%s scope=descriptor one=%d selectors=%s\n",
               bundle ?: "?",
               called,
               hits.count ? [hits componentsJoinedByString:@","].UTF8String : "");
        gThemerCacheClearLogBudget--;
    }
    return called;
}

static uint64_t themer_remote_count(uint64_t obj)
{
    if (!remote_call_current_success() ||
        !r_is_objc_ptr(obj) || !r_responds_main(obj, "count")) return 0;
    if (!remote_call_current_success()) return 0;
    return r_msg2_main(obj, "count", 0, 0, 0, 0);
}

static bool themer_double_near(double a, double b)
{
    double diff = a > b ? (a - b) : (b - a);
    return diff < 0.25;
}

static void themer_add_unique_size(double *sizes, int *count, int cap, double size)
{
    if (!sizes || !count || *count >= cap || size < 10.0 || size > 160.0) return;
    for (int i = 0; i < *count; i++) {
        if (themer_double_near(sizes[i], size)) return;
    }
    sizes[(*count)++] = size;
}

static int themer_reset_image_bags_cache(uint64_t imageCache,
                                         const char *bundle)
{
    if (!remote_call_current_success() ||
        !r_is_objc_ptr(imageCache) ||
        !r_responds_main(imageCache, "imageBagsByDescriptor") ||
        !r_responds_main(imageCache, "setImageBagsByDescriptor:")) {
        return 0;
    }
    if (!remote_call_current_success()) return 0;

    uint64_t oldBags = r_msg2_main(imageCache, "imageBagsByDescriptor",
                                   0, 0, 0, 0);
    if (!remote_call_current_success()) return 0;
    uint64_t before = themer_remote_count(oldBags);
    int cleared = 0;

    if (r_is_objc_ptr(oldBags) && r_responds_main(oldBags, "removeAllObjects")) {
        if (!remote_call_current_success()) return cleared;
        r_msg2_main(oldBags, "removeAllObjects", 0, 0, 0, 0);
        if (!remote_call_current_success()) return cleared;
        cleared++;
    }

    uint64_t dictCls = r_class("NSMutableDictionary");
    if (!remote_call_current_success()) return cleared;
    uint64_t dictAlloc = r_is_objc_ptr(dictCls)
        ? r_msg2(dictCls, "alloc", 0, 0, 0, 0) : 0;
    if (!remote_call_current_success()) return cleared;
    uint64_t newBags = r_is_objc_ptr(dictAlloc)
        ? r_msg2_main(dictAlloc, "init", 0, 0, 0, 0) : 0;
    if (!remote_call_current_success()) return cleared;
    if (r_is_objc_ptr(newBags)) {
        r_msg2_main(imageCache, "setImageBagsByDescriptor:",
                    newBags, 0, 0, 0);
        if (!remote_call_current_success()) return cleared;
        cleared++;
    }

    uint64_t afterBags = r_msg2_main(imageCache, "imageBagsByDescriptor",
                                     0, 0, 0, 0);
    if (!remote_call_current_success()) return cleared;
    uint64_t after = themer_remote_count(afterBags);

    if (cleared > 0 && gThemerCacheClearLogBudget > 0) {
        char oldCls[96] = {0};
        char newCls[96] = {0};
        themer_read_class_name(oldBags, oldCls, sizeof(oldCls));
        themer_read_class_name(afterBags, newCls, sizeof(newCls));
        printf("[THEMER] cache-clear bundle=%s scope=imageBags cleared=%d before=%llu after=%llu oldClass=%s newClass=%s\n",
               bundle ?: "?",
               cleared,
               (unsigned long long)before,
               (unsigned long long)after,
               oldCls,
               newCls);
        gThemerCacheClearLogBudget--;
    }

    return cleared;
}

static bool themer_spotlight_has_armed_recovery_in_session(void);

static int themer_seed_iconservices_cache(const char *bundle,
                                          uint64_t image,
                                          double pointSize)
{
    if (!bundle || !bundle[0] || !r_is_objc_ptr(image)) return 0;
    if (!remote_call_current_success()) return 0;
    if (themer_spotlight_has_armed_recovery_in_session()) return 0;
    if (!themer_ensure_iconservices_loaded()) return 0;
    if (!remote_call_current_success()) return 0;

    uint64_t bid = r_nsstr_retained(bundle);
    if (!remote_call_current_success()) return 0;
    uint64_t iconCls = themer_lookup_class("ISBundleIdentifierIcon");
    if (!remote_call_current_success()) return 0;
    uint64_t mgrCls = themer_lookup_class("ISIconManager");
    if (!r_is_objc_ptr(bid) || !r_is_objc_ptr(iconCls) || !r_is_objc_ptr(mgrCls)) {
        if (r_is_objc_ptr(bid)) r_msg2(bid, "release", 0, 0, 0, 0);
        return 0;
    }

    uint64_t iconAlloc = r_msg2(iconCls, "alloc", 0, 0, 0, 0);
    uint64_t icon = r_is_objc_ptr(iconAlloc)
        ? r_msg2_main(iconAlloc, "initWithBundleIdentifier:", bid, 0, 0, 0)
        : 0;
    if (!remote_call_current_success()) return 0;
    r_msg2(bid, "release", 0, 0, 0, 0);
    if (!remote_call_current_success()) return 0;
    if (!r_is_objc_ptr(icon)) return 0;

    uint64_t mgr = r_msg2(mgrCls, "sharedInstance", 0, 0, 0, 0);
    uint64_t createdIcon = icon;
    uint64_t registered = (r_is_objc_ptr(mgr) &&
                           r_responds_main(mgr, "findOrRegisterIcon:"))
        ? r_msg2_main(mgr, "findOrRegisterIcon:", icon, 0, 0, 0) : 0;
    if (!remote_call_current_success()) return 0;
    if (r_is_objc_ptr(registered) && registered != icon) {
        r_msg2(icon, "release", 0, 0, 0, 0);
        if (!remote_call_current_success()) return 0;
        icon = registered;
    }

    uint64_t imageCache = r_responds_main(icon, "imageCache")
        ? r_msg2_main(icon, "imageCache", 0, 0, 0, 0) : 0;
    if (!remote_call_current_success()) return 0;
    if (!r_is_objc_ptr(imageCache) ||
        !r_responds_main(imageCache, "setImage:forDescriptor:")) {
        if (icon == createdIcon) r_msg2(icon, "release", 0, 0, 0, 0);
        return 0;
    }

    uint64_t cacheImage = themer_make_if_image(image);
    if (!remote_call_current_success()) return 0;
    if (!r_is_objc_ptr(cacheImage)) {
        if (icon == createdIcon) r_msg2(icon, "release", 0, 0, 0, 0);
        return 0;
    }
    ThemerEntry *entry = themer_lookup_entry(bundle);
    int objectGrafted = kThemerIconServicesObjectGraftEnabled
        ? themer_graft_iconservices_icon(bundle, icon, cacheImage, entry)
        : 0;
    if (!remote_call_current_success()) return 0;

    // The 1.5 persistence path invalidated the registered IconServices icon
    // before replacing its descriptor cache. Without this, notification and
    // newly-created home icon views can keep resolving the pre-theme image.
    int invalidBeforeSeed = themer_notify_icon_image_changed(icon);
    if (!remote_call_current_success()) return 0;

    double scale = themer_screen_scale();
    if (!remote_call_current_success()) return 0;
    if (pointSize < 20.0 || pointSize > 120.0) pointSize = 60.0;

    enum { SIZE_CAP = 8 };
    double sizes[SIZE_CAP] = {0};
    int sizeCount = 0;
    themer_add_unique_size(sizes, &sizeCount, SIZE_CAP, pointSize);
    themer_add_unique_size(sizes, &sizeCount, SIZE_CAP, 60.0);

    int seeded = 0;
    int descriptorClears = 0;
    int readbackHits = 0;
    bool checkedReadback = false;

    // Restore the supplied 1.5 cache replacement sequence before descriptor
    // seeding. Replacing imageBagsByDescriptor is what makes subsequent
    // IconServices consumers, including notification views, fetch the theme.
    int imageBagClears = themer_reset_image_bags_cache(imageCache, bundle);
    if (!remote_call_current_success()) return 0;
    int zeroArgClears = themer_call_zero_arg_cache_clears(imageCache, bundle);
    if (!remote_call_current_success()) return 0;

    for (int s = 0; s < sizeCount; s++) {
        if (!remote_call_current_success()) return 0;
        double size = sizes[s];
        bool homeLike = themer_double_near(size, pointSize) ||
                        themer_double_near(size, 60.0);
        int variantLimit = homeLike ? 2 : 1;
        for (int appearance = 0; appearance <= 1; appearance++) {
            for (int variant = 0; variant < variantLimit; variant++) {
                if (!remote_call_current_success()) return 0;
                uint64_t desc = themer_make_is_descriptor(size, scale,
                                                          appearance,
                                                          (uint64_t)variant,
                                                          true);
                if (!r_is_objc_ptr(desc)) continue;
                if (homeLike && kThemerIconServicesDescriptorClearsEnabled) {
                    descriptorClears +=
                        themer_call_descriptor_cache_clears(imageCache,
                                                            desc,
                                                            bundle);
                }
                r_msg2_main(imageCache, "setImage:forDescriptor:",
                            cacheImage, desc, 0, 0);
                if (!remote_call_current_success()) return 0;
                seeded++;

                uint64_t readback = 0;
                bool shouldReadback = !checkedReadback;
                if (shouldReadback && r_responds_main(icon, "imageForDescriptor:")) {
                    readback = r_msg2_main(icon, "imageForDescriptor:", desc, 0, 0, 0);
                }
                if (shouldReadback && !checkedReadback) {
                    checkedReadback = true;
                    if (readback == cacheImage) readbackHits++;
                }
                if (shouldReadback) {
                    themer_log_iconservices_descriptor(bundle,
                                                       "seed",
                                                       desc, readback, cacheImage);
                }
                if (shouldReadback && readback != cacheImage && variant == 0) {
                    themer_log_remote_methods_once("imageCache", imageCache,
                                                   &gThemerImageCacheMethodDumpLogged);
                    themer_log_remote_methods_once("icon", icon,
                                                   &gThemerIconMethodDumpLogged);
                }
                r_msg2(desc, "release", 0, 0, 0, 0);
                if (!remote_call_current_success()) return 0;
            }
        }
    }

    if (!gThemerIconServicesProbeLogged) {
        gThemerIconServicesProbeLogged = true;
        uint64_t cachePath = 0;
        uint64_t iconCache = (r_is_objc_ptr(mgr) && r_responds_main(mgr, "iconCache"))
            ? r_msg2_main(mgr, "iconCache", 0, 0, 0, 0) : 0;
        if (!remote_call_current_success()) return 0;
        if (r_is_objc_ptr(iconCache) && r_responds_main(iconCache, "cachePath")) {
            if (!remote_call_current_success()) return 0;
            cachePath = r_msg2_main(iconCache, "cachePath", 0, 0, 0, 0);
            if (!remote_call_current_success()) return 0;
        }
        char cachePathStr[240] = {0};
        if (r_is_objc_ptr(cachePath)) {
            r_read_nsstring(cachePath, cachePathStr, sizeof(cachePathStr));
            if (!remote_call_current_success()) return 0;
        }
        printf("[THEMER] IconServices seed probe bundle=%s icon=0x%llx imageCache=0x%llx "
               "ifImage=0x%llx seeded=%d imageBagClears=%d zeroClears=%d "
               "descClears=%d descClearEnabled=%d readback=%d objectGraft=%d "
               "invalidBefore=%d pointSize=%.1f scale=%.1f cachePath=\"%s\"\n",
               bundle,
               (unsigned long long)icon,
               (unsigned long long)imageCache,
               (unsigned long long)cacheImage,
               seeded,
               imageBagClears,
               zeroArgClears,
               descriptorClears,
               kThemerIconServicesDescriptorClearsEnabled,
               readbackHits,
               objectGrafted,
               invalidBeforeSeed,
               pointSize, scale,
               cachePathStr);
    }
    r_msg2(cacheImage, "release", 0, 0, 0, 0);
    if (!remote_call_current_success()) return 0;
    if (icon == createdIcon) {
        r_msg2(icon, "release", 0, 0, 0, 0);
        if (!remote_call_current_success()) return 0;
    }
    return remote_call_current_success() ? seeded : 0;
}

// Ships PNG bytes into SB and returns a retained SB UIImage* (+1 owned by
// caller). `label` is just for log output (e.g. "com.apple.mobilesafari").
static uint64_t themer_build_remote_uiimage_from_data(NSData *bytes, const char *label)
{
    if (!bytes || bytes.length == 0 || bytes.length > kThemerMaxPngBytes) {
        printf("[THEMER] PNG size out of range label=%s size=%lu cap=%zu\n",
               label ?: "?",
               (unsigned long)bytes.length,
               kThemerMaxPngBytes);
        return 0;
    }
    if (!remote_call_current_success()) return 0;

    uint64_t remoteBuf = r_dlsym_call(R_TIMEOUT, "malloc",
                                      bytes.length, 0, 0, 0, 0, 0, 0, 0);
    if (!remote_call_current_success()) return 0;
    if (!remoteBuf) {
        printf("[THEMER] remote malloc(%lu) failed label=%s\n",
               (unsigned long)bytes.length, label ?: "?");
        return 0;
    }
    if (!remote_write(remoteBuf, bytes.bytes, bytes.length)) {
        printf("[THEMER] remote_write failed buf=0x%llx size=%lu label=%s\n",
               (unsigned long long)remoteBuf, (unsigned long)bytes.length, label ?: "?");
        if (remote_call_current_success()) r_free(remoteBuf);
        return 0;
    }
    if (!remote_call_current_success()) return 0;

    uint64_t NSDataCls  = r_class("NSData");
    if (!remote_call_current_success()) return 0;
    uint64_t UIImageCls = r_class("UIImage");
    if (!remote_call_current_success()) return 0;
    if (!r_is_objc_ptr(NSDataCls) || !r_is_objc_ptr(UIImageCls)) {
        printf("[THEMER] missing class NSData=0x%llx UIImage=0x%llx\n",
               (unsigned long long)NSDataCls,
               (unsigned long long)UIImageCls);
        if (remote_call_current_success()) r_free(remoteBuf);
        return 0;
    }

    uint64_t dataAlloc = r_msg2(NSDataCls, "alloc", 0, 0, 0, 0);
    if (!remote_call_current_success()) return 0;
    uint64_t nsdata = r_is_objc_ptr(dataAlloc)
        ? r_msg2(dataAlloc, "initWithBytes:length:", remoteBuf, bytes.length, 0, 0)
        : 0;
    if (!remote_call_current_success()) return 0;
    r_free(remoteBuf);  // NSData copied the bytes
    if (!remote_call_current_success()) return 0;

    if (!r_is_objc_ptr(nsdata)) {
        printf("[THEMER] NSData init failed label=%s\n", label ?: "?");
        return 0;
    }

    uint64_t image = r_msg2(UIImageCls, "imageWithData:", nsdata, 0, 0, 0);
    if (!remote_call_current_success()) return 0;
    if (r_is_objc_ptr(image)) {
        r_msg2(image, "retain", 0, 0, 0, 0);
        if (!remote_call_current_success()) return 0;
    }
    r_msg2(nsdata, "release", 0, 0, 0, 0);
    if (!remote_call_current_success()) return 0;

    if (!r_is_objc_ptr(image)) {
        printf("[THEMER] UIImage decode failed for %s (PNG malformed?)\n",
               label ?: "?");
        return 0;
    }
    return remote_call_current_success() ? image : 0;
}

static uint64_t themer_ensure_datasource_class(void)
{
    static uint64_t cls = 0;
    if (r_is_objc_ptr(cls)) return cls;

    cls = themer_lookup_class("CNDIconLayerDataSource");
    if (r_is_objc_ptr(cls)) return cls;

    uint64_t NSObject = r_class("NSObject");
    if (!r_is_objc_ptr(NSObject)) return 0;

    uint64_t name = r_alloc_str("CNDIconLayerDataSource");
    if (!name) return 0;
    cls = r_dlsym_call(R_TIMEOUT, "objc_allocateClassPair",
                       NSObject, name, 0, 0, 0, 0, 0, 0);
    r_free(name);
    if (!r_is_objc_ptr(cls)) return 0;

    uint64_t getAssocImp = themer_remote_symbol_addr("objc_getAssociatedObject");
    bool ok = getAssocImp &&
        themer_add_method(cls, "icon:imageWithInfo:traitCollection:options:",
                          getAssocImp, "@@:@@@Q") &&
        themer_add_method(cls, "icon:layerWithInfo:traitCollection:options:",
                          getAssocImp, "@@:@@@Q") &&
        themer_add_method(cls, "icon:displayNameForLocation:",
                          getAssocImp, "@@:@q") &&
        themer_add_method(cls, "icon:accessibilityLabelForLocation:",
                          getAssocImp, "@@:@q");

    r_dlsym_call(R_TIMEOUT, "objc_registerClassPair",
                 cls, 0, 0, 0, 0, 0, 0, 0);

    if (!ok) {
        printf("[THEMER] model graft: datasource class incomplete getAssoc=0x%llx\n",
               (unsigned long long)getAssocImp);
        return 0;
    }
    return cls;
}

static double themer_icon_width_for_view(uint64_t iconView)
{
    uint64_t iiv = r_ivar_value(iconView, "_iconImageView");
    if (!r_is_objc_ptr(iiv) && r_responds_main(iconView, "_iconImageView")) {
        iiv = r_msg2_main(iconView, "_iconImageView", 0, 0, 0, 0);
    }
    uint64_t layer = r_is_objc_ptr(iiv) && r_responds_main(iiv, "layer")
        ? r_msg2_main(iiv, "layer", 0, 0, 0, 0) : 0;
    struct { double x, y, w, h; } b = {0};
    if (r_is_objc_ptr(layer) &&
        r_responds_main(layer, "bounds") &&
        r_msg2_main_struct_ret(layer, "bounds", &b, sizeof(b),
            NULL, 0, NULL, 0, NULL, 0, NULL, 0) &&
        b.w > 1.0) {
        return b.w;
    }
    return 60.0;
}

static uint64_t themer_icon_image_view_for_iconview(uint64_t iconView)
{
    if (!r_is_objc_ptr(iconView)) return 0;
    uint64_t iiv = r_ivar_value(iconView, "_iconImageView");
    if (!r_is_objc_ptr(iiv) && r_responds_main(iconView, "_iconImageView")) {
        iiv = r_msg2_main(iconView, "_iconImageView", 0, 0, 0, 0);
    }
    return r_is_objc_ptr(iiv) ? iiv : 0;
}

static bool themer_object_looks_like_sbh_icon_image_cache(uint64_t obj)
{
    if (!r_is_objc_ptr(obj)) return false;
    if (r_responds_main(obj, "cacheImage:forIcon:imageAppearance:") ||
        r_responds_main(obj, "cachedImageForIcon:") ||
        r_responds_main(obj, "imageForIcon:")) {
        return true;
    }

    char cls[128] = {0};
    themer_read_class_name(obj, cls, sizeof(cls));
    return strstr(cls, "IconImageCache") != NULL;
}

static uint64_t themer_icon_image_cache_for_image_view(uint64_t iiv)
{
    if (!r_is_objc_ptr(iiv)) return 0;

    static const char *selectors[] = {
        "iconImageCache",
        "_iconImageCache",
        "imageCache",
        "_imageCache",
    };
    for (size_t i = 0; i < sizeof(selectors) / sizeof(selectors[0]); i++) {
        const char *sel = selectors[i];
        if (!r_responds_main(iiv, sel)) continue;
        uint64_t cache = r_msg2_main(iiv, sel, 0, 0, 0, 0);
        if (themer_object_looks_like_sbh_icon_image_cache(cache)) {
            return cache;
        }
    }

    static const char *ivars[] = {
        "_iconImageCache",
        "_imageCache",
        "_cache",
    };
    for (size_t i = 0; i < sizeof(ivars) / sizeof(ivars[0]); i++) {
        uint64_t cache = r_ivar_value(iiv, ivars[i]);
        if (themer_object_looks_like_sbh_icon_image_cache(cache)) {
            return cache;
        }
    }

    return 0;
}

static int themer_clear_sbh_icon_image_caches_for_lists(uint64_t *lvs,
                                                        int nlv,
                                                        uint64_t iconViewCls)
{
    if (!lvs || nlv <= 0 || !r_is_objc_ptr(iconViewCls)) return 0;

    enum { CACHE_CAP = 24, IV_CAP = 64 };
    uint64_t caches[CACHE_CAP] = {0};
    int cacheCount = 0;
    int viewCount = 0;
    int clearCalls = 0;

    for (int i = 0; i < nlv; i++) {
        uint64_t ivs[IV_CAP] = {0};
        int n = sb_collect_views(lvs[i], iconViewCls, ivs, IV_CAP);
        for (int j = 0; j < n; j++) {
            uint64_t v = ivs[j];
            if (!r_is_objc_ptr(v)) continue;
            viewCount++;

            uint64_t iiv = themer_icon_image_view_for_iconview(v);
            uint64_t cache = themer_icon_image_cache_for_image_view(iiv);
            if (!r_is_objc_ptr(cache)) continue;

            bool seen = false;
            for (int c = 0; c < cacheCount; c++) {
                if (caches[c] == cache) {
                    seen = true;
                    break;
                }
            }
            if (seen || cacheCount >= CACHE_CAP) continue;
            caches[cacheCount++] = cache;
        }
    }

    for (int i = 0; i < cacheCount; i++) {
        clearCalls += themer_call_zero_arg_cache_clears(caches[i],
                                                        "SBHIconImageCache");
    }

    printf("[THEMER] SBHIconImageCache update refresh views=%d caches=%d clearCalls=%d\n",
           viewCount, cacheCount, clearCalls);
    return clearCalls;
}

static bool themer_icon_is_application_icon(uint64_t icon)
{
    if (!r_is_objc_ptr(icon)) return false;
    char cls[96] = {0};
    themer_read_class_name(icon, cls, sizeof(cls));
    return strstr(cls, "ApplicationIcon") != NULL &&
           strstr(cls, "WidgetIcon") == NULL &&
           strstr(cls, "FolderIcon") == NULL;
}

static uint64_t themer_application_icon_for_iconview(uint64_t iconView)
{
    if (!r_is_objc_ptr(iconView) || !r_responds_main(iconView, "icon")) return 0;
    uint64_t icon = r_msg2_main(iconView, "icon", 0, 0, 0, 0);
    return themer_icon_is_application_icon(icon) ? icon : 0;
}

static uint64_t themer_iconview_for_image_view(uint64_t iiv)
{
    if (!r_is_objc_ptr(iiv)) return 0;
    uint64_t iconView = r_ivar_value(iiv, "_iconView");
    if (!r_is_objc_ptr(iconView) && r_responds_main(iiv, "iconView")) {
        iconView = r_msg2_main(iiv, "iconView", 0, 0, 0, 0);
    }
    if (!r_is_objc_ptr(iconView) && r_responds_main(iiv, "_iconView")) {
        iconView = r_msg2_main(iiv, "_iconView", 0, 0, 0, 0);
    }
    return r_is_objc_ptr(iconView) ? iconView : 0;
}

static uint64_t themer_application_icon_for_image_view(uint64_t iiv,
                                                       uint64_t *iconViewOut)
{
    if (iconViewOut) *iconViewOut = 0;
    if (!r_is_objc_ptr(iiv)) return 0;

    uint64_t iconView = themer_iconview_for_image_view(iiv);
    if (iconViewOut) *iconViewOut = iconView;

    uint64_t icon = r_ivar_value(iiv, "_icon");
    if (!themer_icon_is_application_icon(icon) && r_is_objc_ptr(iconView)) {
        icon = themer_application_icon_for_iconview(iconView);
    }
    return themer_icon_is_application_icon(icon) ? icon : 0;
}

static bool themer_read_bundle_for_image_view(uint64_t iiv,
                                              char *out,
                                              size_t outLen,
                                              uint64_t *iconViewOut,
                                              uint64_t *iconOut)
{
    if (out && outLen > 0) out[0] = '\0';
    if (iconViewOut) *iconViewOut = 0;
    if (iconOut) *iconOut = 0;
    if (!r_is_objc_ptr(iiv) || !out || outLen == 0) return false;

    uint64_t iconView = 0;
    uint64_t icon = themer_application_icon_for_image_view(iiv, &iconView);
    if (iconViewOut) *iconViewOut = iconView;
    if (iconOut) *iconOut = icon;
    if (!r_is_objc_ptr(icon)) return false;

    return themer_read_bundle_for_icon(icon, iconView, out, outLen);
}

static bool themer_should_pin_dynamic_overlay(const char *bundle, uint64_t iconView)
{
    (void)bundle;
    (void)iconView;
    // Static Clock/Calendar v1: do not pin a floating overlay. The overlay
    // path could survive view reuse and artifact onto neighboring icons.
    return false;
}

static bool themer_prefers_view_level_overlay(const char *bundle)
{
    return kThemerStaticDynamicUseIconViewOverlay &&
           themer_is_static_dynamic_icon_bundle(bundle);
}

static bool themer_needs_visible_push(const char *bundle)
{
    (void)bundle;
    // Keep SnowBoard Lite on the model/cache path. The visible setter path can
    // draw an extra image layer above SpringBoard's own rounded icon mask.
    return false;
}

static NSDictionary<NSString *, NSData *> *themer_normalized_theme_data(NSDictionary<NSString *, NSData *> *input)
{
    if (input.count == 0) return @{};

    NSMutableDictionary<NSString *, NSData *> *out = [NSMutableDictionary dictionaryWithCapacity:input.count];
    NSUInteger aliases = 0;
    for (NSString *key in input) {
        NSData *data = input[key];
        if (![key isKindOfClass:NSString.class] ||
            ![data isKindOfClass:NSData.class] ||
            data.length == 0) {
            continue;
        }

        BOOL usedAlias = NO;
        NSArray<NSString *> *mappedTargets = CNDMappedIOSBundleIDsForIconName(key, &usedAlias);
        if (mappedTargets.count == 0) mappedTargets = @[key];
        for (NSString *target in mappedTargets) {
            if (target.length == 0 || out[target]) continue;
            out[target] = data;
            if (usedAlias) aliases++;
        }
    }

    if (aliases > 0 || out.count != input.count) {
        printf("[THEMER] normalized theme data entries=%lu -> %lu aliases=%lu\n",
               (unsigned long)input.count,
               (unsigned long)out.count,
               (unsigned long)aliases);
    }
    return out;
}

static void themer_add_bundle_filter_aliases(NSMutableSet<NSString *> *out,
                                             NSString *bundleID)
{
    if (![out isKindOfClass:NSMutableSet.class] ||
        ![bundleID isKindOfClass:NSString.class] ||
        bundleID.length == 0) {
        return;
    }

    [out addObject:bundleID];
    BOOL usedAlias = NO;
    NSArray<NSString *> *mapped = CNDMappedIOSBundleIDsForIconName(bundleID,
                                                                   &usedAlias);
    (void)usedAlias;
    for (NSString *candidate in mapped) {
        if ([candidate isKindOfClass:NSString.class] && candidate.length > 0) {
            [out addObject:candidate];
        }
    }
}

static NSDictionary<NSString *, NSData *> *
themer_filter_theme_data_for_bundle_ids(NSDictionary<NSString *, NSData *> *dataByBundle,
                                        NSSet<NSString *> *bundleIDs)
{
    if (![dataByBundle isKindOfClass:NSDictionary.class] ||
        ![bundleIDs isKindOfClass:NSSet.class] ||
        bundleIDs.count == 0) {
        return @{};
    }

    NSMutableSet<NSString *> *targets = [NSMutableSet setWithCapacity:bundleIDs.count * 2];
    for (NSString *bundleID in bundleIDs) {
        themer_add_bundle_filter_aliases(targets, bundleID);
    }

    NSMutableDictionary<NSString *, NSData *> *filtered =
        [NSMutableDictionary dictionaryWithCapacity:targets.count];
    for (NSString *key in dataByBundle) {
        NSData *bytes = dataByBundle[key];
        if (![key isKindOfClass:NSString.class] ||
            ![bytes isKindOfClass:NSData.class] ||
            bytes.length == 0) {
            continue;
        }

        if ([targets containsObject:key]) {
            filtered[key] = bytes;
            continue;
        }

        BOOL usedAlias = NO;
        NSArray<NSString *> *mapped = CNDMappedIOSBundleIDsForIconName(key,
                                                                       &usedAlias);
        (void)usedAlias;
        for (NSString *candidate in mapped) {
            if ([targets containsObject:candidate]) {
                filtered[key] = bytes;
                break;
            }
        }
    }

    return filtered;
}

static bool themer_clear_overlay_on_object(uint64_t obj, uint64_t key)
{
    if (!r_is_objc_ptr(obj) || !key) return false;

    uint64_t overlay = r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                                    obj, key, 0, 0, 0, 0, 0, 0);
    if (!r_is_objc_ptr(overlay)) return false;

    if (r_responds_main(overlay, "setHidden:")) {
        r_msg2_main(overlay, "setHidden:", 1, 0, 0, 0);
    }
    if (r_responds_main(overlay, "removeFromSuperview")) {
        r_msg2_main(overlay, "removeFromSuperview", 0, 0, 0, 0);
    }
    if (r_responds_main(overlay, "removeFromSuperlayer")) {
        r_msg2_main(overlay, "removeFromSuperlayer", 0, 0, 0, 0);
    }
    r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                 obj, key, 0, 1, 0, 0, 0, 0);
    return true;
}

static bool themer_clear_dynamic_overlay(uint64_t iconView)
{
    if (!r_is_objc_ptr(iconView)) return false;
    uint64_t key = r_sel("cnd_themer_pinned_overlay");
    if (!key) return false;

    bool cleared = themer_clear_overlay_on_object(iconView, key);
    uint64_t iiv = themer_icon_image_view_for_iconview(iconView);
    cleared = themer_clear_overlay_on_object(iiv, key) || cleared;
    return cleared;
}

static bool themer_clear_static_dynamic_child_overlay_on_object(uint64_t obj)
{
    if (!r_is_objc_ptr(obj)) return false;
    uint64_t key = r_sel("cnd_themer_static_child_overlay");
    if (!key) return false;
    return themer_clear_overlay_on_object(obj, key);
}

static bool themer_clear_static_dynamic_child_overlay_for_iconview(uint64_t iconView)
{
    if (!r_is_objc_ptr(iconView)) return false;
    bool cleared = themer_clear_static_dynamic_child_overlay_on_object(iconView);
    uint64_t iiv = themer_icon_image_view_for_iconview(iconView);
    cleared = themer_clear_static_dynamic_child_overlay_on_object(iiv) || cleared;
    return cleared;
}

static bool themer_is_static_dynamic_icon_bundle(const char *bundle)
{
    return bundle &&
           (strcmp(bundle, "com.apple.mobiletimer") == 0 ||
            strcmp(bundle, "com.apple.mobilecal") == 0);
}

static bool themer_dynamic_piece_class_name(const char *cls)
{
    if (!cls || !cls[0]) return false;
    return strstr(cls, "Clock") != NULL ||
           strstr(cls, "Calendar") != NULL;
}

static int themer_hide_descendant_views(uint64_t view, int depth)
{
    if (!r_is_objc_ptr(view) || depth > 4 ||
        !r_responds_main(view, "subviews")) {
        return 0;
    }

    uint64_t subs = r_msg2_main(view, "subviews", 0, 0, 0, 0);
    uint64_t count = themer_collection_count_capped(subs, 128);
    int hidden = 0;
    for (uint64_t i = 0; i < count; i++) {
        uint64_t child = r_msg2_main(subs, "objectAtIndex:", i, 0, 0, 0);
        if (!r_is_objc_ptr(child)) continue;
        if (r_responds_main(child, "setHidden:")) {
            r_msg2_main(child, "setHidden:", 1, 0, 0, 0);
            hidden++;
        }
        hidden += themer_hide_descendant_views(child, depth + 1);
    }
    return hidden;
}

static uint64_t themer_collection_count_capped(uint64_t obj, uint64_t cap)
{
    if (!r_is_objc_ptr(obj) || !r_responds_main(obj, "count")) return 0;
    uint64_t count = r_msg2_main(obj, "count", 0, 0, 0, 0);
    return count <= cap ? count : 0;
}

static bool themer_read_rect(uint64_t obj,
                             const char *selName,
                             ThemerRect *out)
{
    if (!out) return false;
    memset(out, 0, sizeof(*out));
    if (!r_is_objc_ptr(obj) || !selName || !r_responds_main(obj, selName)) {
        return false;
    }
    return r_msg2_main_struct_ret(obj, selName,
        out, sizeof(*out),
        NULL, 0, NULL, 0, NULL, 0, NULL, 0);
}

static double themer_remote_alpha(uint64_t obj)
{
    double alpha = -1.0;
    if (!r_is_objc_ptr(obj) || !r_responds_main(obj, "alpha")) return alpha;
    (void)r_msg2_main_struct_ret(obj, "alpha",
        &alpha, sizeof(alpha),
        NULL, 0, NULL, 0, NULL, 0, NULL, 0);
    return alpha;
}

static int themer_remote_hidden(uint64_t obj)
{
    if (!r_is_objc_ptr(obj) || !r_responds_main(obj, "isHidden")) return -1;
    return (r_msg2_main(obj, "isHidden", 0, 0, 0, 0) & 0xff) ? 1 : 0;
}

static bool themer_cstring_has_any(const char *s,
                                   const char * const *needles,
                                   size_t needleCount)
{
    if (!s || !s[0]) return false;
    for (size_t i = 0; i < needleCount; i++) {
        const char *needle = needles[i];
        if (needle && needle[0] && strstr(s, needle)) return true;
    }
    return false;
}

static bool themer_string_looks_like_bundle_id(const char *s)
{
    if (!s || !s[0]) return false;
    size_t len = strlen(s);
    if (len < 5 || len > 180 || !strchr(s, '.')) return false;
    bool hasAlpha = false;
    for (size_t i = 0; i < len; i++) {
        char c = s[i];
        if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')) {
            hasAlpha = true;
            continue;
        }
        if ((c >= '0' && c <= '9') || c == '.' || c == '-' || c == '_') {
            continue;
        }
        return false;
    }
    return hasAlpha;
}

static bool themer_read_bundle_hint_from_stringish(uint64_t obj,
                                                   char *out,
                                                   size_t outLen)
{
    if (!out || outLen == 0) return false;
    out[0] = '\0';
    char tmp[192] = {0};
    if (r_is_objc_ptr(obj) &&
        r_read_nsstring(obj, tmp, sizeof(tmp)) &&
        themer_string_looks_like_bundle_id(tmp)) {
        snprintf(out, outLen, "%s", tmp);
        return true;
    }
    return false;
}

static bool themer_read_bundle_hint_from_object(uint64_t obj,
                                                char *out,
                                                size_t outLen,
                                                char *source,
                                                size_t sourceLen)
{
    if (!out || outLen == 0) return false;
    out[0] = '\0';
    if (source && sourceLen > 0) source[0] = '\0';
    if (!r_is_objc_ptr(obj)) return false;

    static const char *stringSels[] = {
        "bundleIdentifier",
        "applicationBundleIdentifier",
        "applicationIdentifier",
        "displayIdentifier",
        "bundleID",
        "bundleId",
        "_bundleIdentifier",
        "_applicationBundleIdentifier",
        "_applicationIdentifier",
        "_displayIdentifier",
        "sectionIdentifier",
    };
    for (size_t i = 0; i < sizeof(stringSels) / sizeof(stringSels[0]); i++) {
        const char *sel = stringSels[i];
        if (!r_responds_main(obj, sel)) continue;
        uint64_t value = r_msg2_main(obj, sel, 0, 0, 0, 0);
        if (themer_read_bundle_hint_from_stringish(value, out, outLen)) {
            if (source && sourceLen > 0) snprintf(source, sourceLen, "%s", sel);
            return true;
        }
        if (r_is_objc_ptr(value) &&
            r_responds_main(value, "bundleIdentifier")) {
            uint64_t nested = r_msg2_main(value, "bundleIdentifier", 0, 0, 0, 0);
            if (themer_read_bundle_hint_from_stringish(nested, out, outLen)) {
                if (source && sourceLen > 0) {
                    snprintf(source, sourceLen, "%s.bundleIdentifier", sel);
                }
                return true;
            }
        }
    }

    static const char *ivarNames[] = {
        "_bundleIdentifier",
        "_applicationBundleIdentifier",
        "_applicationIdentifier",
        "_displayIdentifier",
        "_sectionIdentifier",
        "_bundleID",
        "_bundleId",
    };
    for (size_t i = 0; i < sizeof(ivarNames) / sizeof(ivarNames[0]); i++) {
        const char *ivar = ivarNames[i];
        uint64_t value = r_ivar_value(obj, ivar);
        if (themer_read_bundle_hint_from_stringish(value, out, outLen)) {
            if (source && sourceLen > 0) snprintf(source, sourceLen, "ivar:%s", ivar);
            return true;
        }
        if (r_is_objc_ptr(value) &&
            r_responds_main(value, "bundleIdentifier")) {
            uint64_t nested = r_msg2_main(value, "bundleIdentifier", 0, 0, 0, 0);
            if (themer_read_bundle_hint_from_stringish(nested, out, outLen)) {
                if (source && sourceLen > 0) {
                    snprintf(source, sourceLen, "ivar:%s.bundleIdentifier", ivar);
                }
                return true;
            }
        }
    }

    return false;
}

static bool themer_find_bundle_hint_near_view(uint64_t view,
                                              char *out,
                                              size_t outLen,
                                              char *source,
                                              size_t sourceLen)
{
    if (!out || outLen == 0) return false;
    out[0] = '\0';
    if (source && sourceLen > 0) source[0] = '\0';
    uint64_t obj = view;
    for (int depth = 0; r_is_objc_ptr(obj) && depth < 7; depth++) {
        if (themer_read_bundle_hint_from_object(obj, out, outLen,
                                                source, sourceLen)) {
            if (source && sourceLen > 0) {
                char tmp[160] = {0};
                snprintf(tmp, sizeof(tmp), "viewDepth%d.%s", depth, source);
                snprintf(source, sourceLen, "%s", tmp);
            }
            return true;
        }

        static const char *objectSels[] = {
            "representedObject",
            "representedApplication",
            "application",
            "app",
            "icon",
            "result",
            "searchResult",
            "suggestion",
            "item",
            "model",
            "configuration",
            "contentConfiguration",
        };
        for (size_t i = 0; i < sizeof(objectSels) / sizeof(objectSels[0]); i++) {
            const char *sel = objectSels[i];
            if (!r_responds_main(obj, sel)) continue;
            uint64_t child = r_msg2_main(obj, sel, 0, 0, 0, 0);
            char childSource[96] = {0};
            if (themer_read_bundle_hint_from_object(child, out, outLen,
                                                    childSource,
                                                    sizeof(childSource))) {
                if (source && sourceLen > 0) {
                    snprintf(source, sourceLen, "viewDepth%d.%s.%s",
                             depth, sel, childSource);
                }
                return true;
            }
        }

        obj = r_responds_main(obj, "superview")
            ? r_msg2_main(obj, "superview", 0, 0, 0, 0) : 0;
    }
    return false;
}

static bool themer_spotlight_class_is_interesting(const char *className)
{
    static const char *needles[] = {
        "Search", "search",
        "Spotlight", "spotlight",
        "Siri", "siri",
        "Suggestion", "suggestion",
        "Suggest", "suggest",
        "Result", "result",
        "Recents", "Recent",
        "Icon", "icon",
    };
    return themer_cstring_has_any(className, needles,
                                  sizeof(needles) / sizeof(needles[0]));
}

static bool themer_spotlight_class_has_search_hint(const char *className)
{
    static const char *needles[] = {
        "Search", "search",
        "Spotlight", "spotlight",
        "Siri", "siri",
        "Suggestion", "suggestion",
        "Suggest", "suggest",
        "Result", "result",
        "Recents", "Recent",
        "SPUI", "CS"
    };
    return themer_cstring_has_any(className, needles,
                                  sizeof(needles) / sizeof(needles[0]));
}

static bool themer_spotlight_method_name_is_interesting(const char *name)
{
    static const char *needles[] = {
        "Icon", "icon",
        "Image", "image",
        "Bundle", "bundle",
        "Application", "application",
        "Identifier", "identifier",
        "Display", "display",
        "Result", "result",
        "Search", "search",
        "Suggestion", "suggestion",
        "Configure", "configure",
        "Cell", "cell",
        "Model", "model",
    };
    return themer_cstring_has_any(name, needles,
                                  sizeof(needles) / sizeof(needles[0]));
}

static void themer_spotlight_log_methods_for_object(uint64_t obj,
                                                    NSMutableSet<NSString *> *seenClasses)
{
    if (gThemerSpotlightMethodLogBudget <= 0 ||
        !r_is_objc_ptr(obj) ||
        !seenClasses) {
        return;
    }

    uint64_t cls = r_dlsym_call(R_TIMEOUT, "object_getClass",
                                obj, 0, 0, 0, 0, 0, 0, 0);
    for (int depth = 0; r_is_objc_ptr(cls) && depth < 6 &&
                        gThemerSpotlightMethodLogBudget > 0; depth++) {
        char clsName[96] = {0};
        themer_read_class_object_name(cls, clsName, sizeof(clsName));
        if (!clsName[0]) break;
        NSString *key = [NSString stringWithUTF8String:clsName];
        if ([seenClasses containsObject:key]) {
            cls = r_dlsym_call(R_TIMEOUT, "class_getSuperclass",
                               cls, 0, 0, 0, 0, 0, 0, 0);
            continue;
        }
        [seenClasses addObject:key];

        uint64_t countBuf = r_dlsym_call(R_TIMEOUT, "malloc",
                                         8, 0, 0, 0, 0, 0, 0, 0);
        if (!countBuf) break;
        remote_write64(countBuf, 0);
        uint64_t methods = r_dlsym_call(R_TIMEOUT, "class_copyMethodList",
                                        cls, countBuf, 0, 0, 0, 0, 0, 0);
        uint32_t count = 0;
        remote_read(countBuf, &count, sizeof(count));
        r_free(countBuf);

        NSMutableArray<NSString *> *names = [NSMutableArray array];
        if (methods && count > 0 && count <= 1024) {
            uint32_t cap = count < 1024 ? count : 1024;
            for (uint32_t i = 0; i < cap && names.count < 48; i++) {
                uint64_t method = remote_read64(methods + ((uint64_t)i * sizeof(uint64_t)));
                if (!method) continue;
                uint64_t sel = r_dlsym_call(R_TIMEOUT, "method_getName",
                                            method, 0, 0, 0, 0, 0, 0, 0);
                uint64_t cName = sel ? r_dlsym_call(R_TIMEOUT, "sel_getName",
                                                    sel, 0, 0, 0, 0, 0, 0, 0) : 0;
                char name[160] = {0};
                if (cName && themer_read_remote_cstring(cName, name, sizeof(name)) &&
                    themer_spotlight_method_name_is_interesting(name)) {
                    [names addObject:[NSString stringWithUTF8String:name]];
                }
            }
        }
        if (methods) r_dlsym_call(R_TIMEOUT, "free",
                                  methods, 0, 0, 0, 0, 0, 0, 0);

        if (names.count > 0 || themer_spotlight_class_is_interesting(clsName)) {
            printf("[SPOTLIGHT] methods class=%s total=%u filtered=%s\n",
                   clsName,
                   count,
                   names.count ? [names componentsJoinedByString:@","].UTF8String : "");
            gThemerSpotlightMethodLogBudget--;
        }

        cls = r_dlsym_call(R_TIMEOUT, "class_getSuperclass",
                           cls, 0, 0, 0, 0, 0, 0, 0);
    }
}

static bool themer_read_image_geometry(uint64_t image,
                                       double *outW,
                                       double *outH,
                                       double *outScale)
{
    if (outW) *outW = 0.0;
    if (outH) *outH = 0.0;
    if (outScale) *outScale = 0.0;
    if (!r_is_objc_ptr(image)) return false;

    struct { double w; double h; } size = {0.0, 0.0};
    bool hasSize = r_responds_main(image, "size") &&
        r_msg2_main_struct_ret(image, "size",
                               &size, sizeof(size),
                               NULL, 0, NULL, 0, NULL, 0, NULL, 0);
    bool hasScale = false;
    double scale = themer_read_remote_double_property(image, "scale", 0.0,
                                                      &hasScale);
    if (outW) *outW = size.w;
    if (outH) *outH = size.h;
    if (outScale) *outScale = scale;
    return hasSize || hasScale;
}

static bool themer_spotlight_image_size_is_iconish(double w, double h)
{
    if (w < 12.0 || h < 12.0 || w > 160.0 || h > 160.0) return false;
    double ratio = w > h ? (w / h) : (h / w);
    return ratio <= 1.45;
}

static bool themer_spotlight_class_is_obvious_non_candidate(const char *className)
{
    static const char *needles[] = {
        "Wallpaper",
        "StatusBar",
        "Keyboard",
        "CoverSheet",
        "ControlCenter",
    };
    return themer_cstring_has_any(className, needles,
                                  sizeof(needles) / sizeof(needles[0]));
}

static bool themer_spotlight_scan_child_classes(uint64_t root,
                                                int depth,
                                                int maxDepth,
                                                NSMutableArray<NSString *> *samples,
                                                int *interestingCount,
                                                int *imageViewCount)
{
    if (!r_is_objc_ptr(root) || depth > maxDepth) return false;

    char className[96] = {0};
    themer_read_class_name(root, className, sizeof(className));
    bool interesting = themer_spotlight_class_is_interesting(className);
    if (interesting && interestingCount) (*interestingCount)++;

    bool imageish = false;
    if (r_responds_main(root, "image")) {
        uint64_t image = r_msg2_main(root, "image", 0, 0, 0, 0);
        double w = 0.0;
        double h = 0.0;
        double scale = 0.0;
        if (r_is_objc_ptr(image) &&
            themer_read_image_geometry(image, &w, &h, &scale) &&
            themer_spotlight_image_size_is_iconish(w, h)) {
            imageish = true;
            if (imageViewCount) (*imageViewCount)++;
        }
    }

    if ((interesting || imageish) && samples.count < 36) {
        [samples addObject:[NSString stringWithFormat:@"%*s%s%s",
                            depth * 2, "",
                            className[0] ? className : "?",
                            imageish ? ":image" : ""]];
    }

    if (!r_responds_main(root, "subviews")) return interesting || imageish;
    uint64_t subs = r_msg2_main(root, "subviews", 0, 0, 0, 0);
    uint64_t count = themer_collection_count_capped(subs, 48);
    bool found = interesting || imageish;
    for (uint64_t i = 0; i < count; i++) {
        uint64_t child = r_msg2_main(subs, "objectAtIndex:", i, 0, 0, 0);
        if (themer_spotlight_scan_child_classes(child, depth + 1, maxDepth,
                                                samples,
                                                interestingCount,
                                                imageViewCount)) {
            found = true;
        }
    }
    return found;
}

static bool themer_spotlight_window_should_deep_walk(uint64_t win,
                                                     const char *winClass,
                                                     uint64_t index,
                                                     int *interestingCountOut,
                                                     int *imageViewCountOut)
{
    if (interestingCountOut) *interestingCountOut = 0;
    if (imageViewCountOut) *imageViewCountOut = 0;
    if (!r_is_objc_ptr(win)) return false;

    int hidden = themer_remote_hidden(win);
    double alpha = themer_remote_alpha(win);
    bool classInteresting = themer_spotlight_class_is_interesting(winClass);
    bool obviousNonCandidate = themer_spotlight_class_is_obvious_non_candidate(winClass);

    NSMutableArray<NSString *> *samples = [NSMutableArray array];
    int interestingCount = classInteresting ? 1 : 0;
    int imageViewCount = 0;
    bool childHint = themer_spotlight_scan_child_classes(win, 0, 2,
                                                        samples,
                                                        &interestingCount,
                                                        &imageViewCount);
    bool visible = hidden != 1 && alpha > 0.01;
    bool shouldWalk = visible && !obviousNonCandidate &&
        (classInteresting || childHint || imageViewCount > 0);

    // Home screen/search occasionally lives in a generic SpringBoard window
    // whose top-level class is not search-specific. Keep one narrow fallback,
    // but still avoid the wallpaper/status/control-center classes above.
    if (!shouldWalk && visible && !obviousNonCandidate && index > 0 &&
        winClass && (strstr(winClass, "SB") || strstr(winClass, "UI"))) {
        shouldWalk = childHint || imageViewCount > 0;
    }

    printf("[SPOTLIGHT] window-scan index=%llu class=%s visible=%d nonCandidate=%d interesting=%d imageViews=%d deep=%d samples=%s\n",
           (unsigned long long)index,
           winClass ?: "?",
           visible,
           obviousNonCandidate,
           interestingCount,
           imageViewCount,
           shouldWalk,
           samples.count ? [samples componentsJoinedByString:@"|"].UTF8String : "");

    if (interestingCountOut) *interestingCountOut = interestingCount;
    if (imageViewCountOut) *imageViewCountOut = imageViewCount;
    return shouldWalk;
}

static int themer_spotlight_walk_root(uint64_t root,
                                      const char *rootLabel,
                                      NSMutableSet<NSString *> *methodClasses)
{
    if (!r_is_objc_ptr(root)) return 0;

    enum { QMAX = 1200 };
    static uint64_t q[QMAX];
    static uint16_t depths[QMAX];
    int head = 0;
    int tail = 0;
    int visited = 0;
    int logged = 0;
    int imageViews = 0;
    int bundleHints = 0;
    int interestingClasses = 0;

    q[tail] = root;
    depths[tail] = 0;
    tail++;

    while (head < tail && visited < QMAX) {
        uint64_t view = q[head];
        uint16_t depth = depths[head];
        head++;
        visited++;
        if (!r_is_objc_ptr(view)) continue;

        char className[96] = {0};
        themer_read_class_name(view, className, sizeof(className));

        uint64_t image = 0;
        double imageW = 0.0;
        double imageH = 0.0;
        double imageScale = 0.0;
        bool hasImage = false;
        if (r_responds_main(view, "image")) {
            image = r_msg2_main(view, "image", 0, 0, 0, 0);
            hasImage = r_is_objc_ptr(image) &&
                themer_read_image_geometry(image, &imageW, &imageH, &imageScale);
            if (hasImage) imageViews++;
        }

        char bundle[192] = {0};
        char bundleSource[160] = {0};
        bool hasBundle = themer_find_bundle_hint_near_view(view,
                                                           bundle, sizeof(bundle),
                                                           bundleSource,
                                                           sizeof(bundleSource));
        if (hasBundle) bundleHints++;

        bool classInteresting = themer_spotlight_class_is_interesting(className);
        if (classInteresting) interestingClasses++;

        bool imageInteresting = hasImage &&
            themer_spotlight_image_size_is_iconish(imageW, imageH);
        if ((classInteresting || imageInteresting || hasBundle) && logged < 180) {
            ThemerRect frame = {0};
            bool hasFrame = themer_read_rect(view, "frame", &frame);
            int hidden = themer_remote_hidden(view);
            double alpha = themer_remote_alpha(view);

            uint64_t superview = r_responds_main(view, "superview")
                ? r_msg2_main(view, "superview", 0, 0, 0, 0) : 0;
            char superClass[96] = {0};
            themer_read_class_name(superview, superClass, sizeof(superClass));

            printf("[SPOTLIGHT] view root=%s depth=%u obj=0x%llx class=%s "
                   "super=%s hidden=%d alpha=%.2f frame=%s%.1f,%.1f %.1fx%.1f "
                   "image=0x%llx imageSize=%.1fx%.1f imageScale=%.2f "
                   "bundle=%s source=%s\n",
                   rootLabel ?: "?",
                   depth,
                   (unsigned long long)view,
                   className,
                   superClass,
                   hidden,
                   alpha,
                   hasFrame ? "" : "?",
                   frame.x, frame.y, frame.w, frame.h,
                   (unsigned long long)image,
                   imageW, imageH, imageScale,
                   hasBundle ? bundle : "-",
                   hasBundle ? bundleSource : "-");
            logged++;
            themer_spotlight_log_methods_for_object(view, methodClasses);
        }

        if (!r_responds_main(view, "subviews")) continue;
        uint64_t subs = r_msg2_main(view, "subviews", 0, 0, 0, 0);
        uint64_t count = themer_collection_count_capped(subs, 256);
        for (uint64_t i = 0; i < count && tail < QMAX; i++) {
            uint64_t child = r_msg2_main(subs, "objectAtIndex:", i, 0, 0, 0);
            if (!r_is_objc_ptr(child)) continue;
            q[tail] = child;
            depths[tail] = depth + 1;
            tail++;
        }
    }

    printf("[SPOTLIGHT] walk root=%s visited=%d queued=%d logged=%d imageViews=%d bundleHints=%d interestingClasses=%d\n",
           rootLabel ?: "?",
           visited,
           tail,
           logged,
           imageViews,
           bundleHints,
           interestingClasses);
    return logged;
}

static int themer_spotlight_walk_visible_ui(void)
{
    uint64_t UIApplication = r_class("UIApplication");
    uint64_t app = r_is_objc_ptr(UIApplication)
        ? r_msg2_main(UIApplication, "sharedApplication", 0, 0, 0, 0) : 0;
    if (!r_is_objc_ptr(app)) {
        printf("[SPOTLIGHT] walk failed: UIApplication/sharedApplication unavailable\n");
        return 0;
    }

    uint64_t windows = r_responds_main(app, "windows")
        ? r_msg2_main(app, "windows", 0, 0, 0, 0) : 0;
    uint64_t windowCount = themer_collection_count_capped(windows, 32);
    printf("[SPOTLIGHT] fast walk begin windows=%llu\n",
           (unsigned long long)windowCount);

    for (uint64_t i = 0; i < windowCount; i++) {
        uint64_t win = r_msg2_main(windows, "objectAtIndex:", i, 0, 0, 0);
        if (!r_is_objc_ptr(win)) continue;
        char winClass[96] = {0};
        themer_read_class_name(win, winClass, sizeof(winClass));
        ThemerRect frame = {0};
        bool hasFrame = themer_read_rect(win, "frame", &frame);
        int hidden = themer_remote_hidden(win);
        double alpha = themer_remote_alpha(win);
        printf("[SPOTLIGHT] window index=%llu obj=0x%llx class=%s hidden=%d alpha=%.2f frame=%s%.1f,%.1f %.1fx%.1f\n",
               (unsigned long long)i,
               (unsigned long long)win,
               winClass,
               hidden,
               alpha,
               hasFrame ? "" : "?",
               frame.x, frame.y, frame.w, frame.h);
    }

    uint64_t imageViewCls = r_class("UIImageView");
    if (!r_is_objc_ptr(imageViewCls)) {
        printf("[SPOTLIGHT] fast image scan skipped: UIImageView unavailable\n");
        return 0;
    }

    enum { IV_CAP = 160 };
    uint64_t imageViews[IV_CAP] = {0};
    int count = sb_collect_views_in_windows(imageViewCls, imageViews, IV_CAP);
    printf("[SPOTLIGHT] fast image scan begin imageViews=%d\n", count);

    int logged = 0;
    int bundleBudget = 2;
    int searchPathHits = 0;
    int iconishHits = 0;
    for (int i = 0; i < count && logged < 40; i++) {
        uint64_t view = imageViews[i];
        if (!r_is_objc_ptr(view)) continue;

        char className[96] = {0};
        themer_read_class_name(view, className, sizeof(className));

        uint64_t image = r_responds_main(view, "image")
            ? r_msg2_main(view, "image", 0, 0, 0, 0) : 0;
        double imageW = 0.0;
        double imageH = 0.0;
        double imageScale = 0.0;
        bool hasImage = r_is_objc_ptr(image) &&
            themer_read_image_geometry(image, &imageW, &imageH, &imageScale);
        bool iconish = hasImage &&
            themer_spotlight_image_size_is_iconish(imageW, imageH);

        NSMutableArray<NSString *> *pathItems = [NSMutableArray array];
        bool searchPath = false;
        uint64_t ancestor = view;
        for (int depth = 0; r_is_objc_ptr(ancestor) && depth < 4; depth++) {
            char ancestorClass[96] = {0};
            themer_read_class_name(ancestor, ancestorClass, sizeof(ancestorClass));
            if (ancestorClass[0]) {
                if (pathItems.count < 8) {
                    [pathItems addObject:[NSString stringWithUTF8String:ancestorClass]];
                }
                static const char *searchNeedles[] = {
                    "Search", "Spotlight", "Siri", "Suggestion", "Result"
                };
                if (themer_cstring_has_any(ancestorClass,
                                           searchNeedles,
                                           sizeof(searchNeedles) / sizeof(searchNeedles[0]))) {
                    searchPath = true;
                }
            }
            ancestor = r_responds_main(ancestor, "superview")
                ? r_msg2_main(ancestor, "superview", 0, 0, 0, 0) : 0;
        }

        if (searchPath) searchPathHits++;
        if (iconish) iconishHits++;
        if (!searchPath && !iconish) continue;

        ThemerRect frame = {0};
        bool hasFrame = themer_read_rect(view, "frame", &frame);
        int hidden = themer_remote_hidden(view);
        double alpha = themer_remote_alpha(view);

        char bundle[192] = {0};
        char bundleSource[160] = {0};
        bool hasBundle = false;
        if (bundleBudget > 0 && searchPath) {
            hasBundle = themer_find_bundle_hint_near_view(view,
                                                          bundle, sizeof(bundle),
                                                          bundleSource,
                                                          sizeof(bundleSource));
            bundleBudget--;
        }

        printf("[SPOTLIGHT] image-view index=%d obj=0x%llx class=%s hidden=%d alpha=%.2f "
               "frame=%s%.1f,%.1f %.1fx%.1f image=0x%llx imageSize=%.1fx%.1f "
               "imageScale=%.2f iconish=%d searchPath=%d bundle=%s source=%s path=%s\n",
               i,
               (unsigned long long)view,
               className,
               hidden,
               alpha,
               hasFrame ? "" : "?",
               frame.x, frame.y, frame.w, frame.h,
               (unsigned long long)image,
               imageW, imageH,
               imageScale,
               iconish,
               searchPath,
               hasBundle ? bundle : "-",
               hasBundle ? bundleSource : "-",
               pathItems.count ? [pathItems componentsJoinedByString:@"<"].UTF8String : "");
        logged++;
    }

    printf("[SPOTLIGHT] fast image scan complete imageViews=%d logged=%d searchPath=%d iconish=%d bundleBudgetLeft=%d\n",
           count,
           logged,
           searchPathHits,
           iconishHits,
           bundleBudget);
    return logged;
}

static NSMutableArray<NSString *> *themer_spotlight_probe_bundles(void)
{
    const NSUInteger cap = 1;
    NSMutableArray<NSString *> *bundles = [NSMutableArray array];
    NSMutableSet<NSString *> *seen = [NSMutableSet set];
    for (int i = 0; i < gThemerCacheCount && bundles.count < cap; i++) {
        const char *bundle = gThemerCache[i].bundle;
        if (!bundle || !bundle[0]) continue;
        NSString *key = [NSString stringWithUTF8String:bundle];
        if ([seen containsObject:key]) continue;
        [bundles addObject:key];
        [seen addObject:key];
    }
    return bundles;
}

static uint64_t themer_spotlight_method_for_target(uint64_t cls,
                                                   const char *selName,
                                                   bool classMethod)
{
    if (!r_is_objc_ptr(cls) || !selName || !selName[0]) return 0;
    uint64_t sel = r_sel(selName);
    if (!sel) return 0;
    return r_dlsym_call(R_TIMEOUT,
                        classMethod ? "class_getClassMethod"
                                    : "class_getInstanceMethod",
                        cls, sel, 0, 0, 0, 0, 0, 0);
}

static int themer_spotlight_log_method_target(const char *className,
                                              bool classMethod,
                                              const char *selName)
{
    uint64_t cls = themer_lookup_class(className);
    uint64_t method = themer_spotlight_method_for_target(cls, selName,
                                                         classMethod);
    uint64_t imp = method
        ? r_dlsym_call(R_TIMEOUT, "method_getImplementation",
                       method, 0, 0, 0, 0, 0, 0, 0)
        : 0;
    uint64_t typeCstr = method
        ? r_dlsym_call(R_TIMEOUT, "method_getTypeEncoding",
                       method, 0, 0, 0, 0, 0, 0, 0)
        : 0;
    char types[192] = {0};
    (void)themer_read_remote_cstring(typeCstr, types, sizeof(types));
    printf("[SPOTLIGHT] hook-target class=%s kind=%c selector=%s objcClass=0x%llx method=0x%llx imp=0x%llx types=\"%s\" present=%d\n",
           className ?: "?",
           classMethod ? '+' : '-',
           selName ?: "?",
           (unsigned long long)cls,
           (unsigned long long)method,
           (unsigned long long)imp,
           types[0] ? types : "?",
           method != 0);
    return method ? 1 : 0;
}

static int themer_spotlight_log_snowboardbase_targets(void)
{
    static const struct {
        const char *className;
        bool classMethod;
        const char *selector;
    } targets[] = {
        { "SBHIconImageCache", false, "cachedImageForIcon:" },
        { "SBHIconImageCache", false, "imageForIcon:" },
        { "SBHIconImageCache", false, "sb_iconImageForIcon:orig:" },
        { "SBHIconImageCache", false, "cacheImage:forIcon:imageAppearance:" },
        { "SBHIconImageCache", false, "clearCachedImages" },
        { "SBHIconImageCache", false, "_clearCachedImages" },

        { "SearchUIHomeScreenAppIconView", false, "resetImageWithAppIcon:" },
        { "SearchUIHomeScreenAppIconView", false, "imageView" },
        { "SearchUIHomeScreenAppIconView", false, "image" },
        { "SearchUIHomeScreenAppIconView", false, "appIcon" },
        { "SearchUIHomeScreenAppIconView", false, "icon" },

        { "UIImage", true, "_applicationIconImageForBundleIdentifier:format:scale:" },
        { "UIImage", true, "_applicationIconImageForBundleIdentifier:format:" },
        { "UIImage", true, "appIconForBundleIdentifier:" },
        { "UIImage", true, "sbf_memoryMappedImageWithPool:" },
        { "UIImage", false, "sbf_memoryMappedImageWithPool:" },

        { "APWUtil", true, "iconForBundleIdentifier:" },
        { "APWUtil", true, "iconForBundleIdentifier:withFormat:" },
        { "WGWidgetHostingViewController", false, "requestIconWithHandler:" },
        { "WGWidgetDiscoveryController", false, "widgetListEditViewController:requestsIconForItemWithIdentifier:withHandler:" },
    };

    printf("[SPOTLIGHT] snowboardbase target scan begin count=%lu methodSwaps=disabled\n",
           (unsigned long)(sizeof(targets) / sizeof(targets[0])));
    int hits = 0;
    for (size_t i = 0; i < sizeof(targets) / sizeof(targets[0]); i++) {
        hits += themer_spotlight_log_method_target(targets[i].className,
                                                   targets[i].classMethod,
                                                   targets[i].selector);
    }
    printf("[SPOTLIGHT] snowboardbase target scan complete present=%d\n",
           hits);
    return hits;
}

static int themer_spotlight_log_provider_image(const char *bundle,
                                               const char *selector,
                                               int32_t format,
                                               double requestScale,
                                               uint64_t image,
                                               uint64_t themedImage)
{
    double w = 0.0;
    double h = 0.0;
    double imageScale = 0.0;
    bool hasGeometry = themer_read_image_geometry(image, &w, &h, &imageScale);

    uint64_t imageCG = r_is_objc_ptr(image) && r_responds_main(image, "CGImage")
        ? r_msg2_main(image, "CGImage", 0, 0, 0, 0) : 0;
    uint64_t themedCG = r_is_objc_ptr(themedImage) && r_responds_main(themedImage, "CGImage")
        ? r_msg2_main(themedImage, "CGImage", 0, 0, 0, 0) : 0;
    int equal = -1;
    if (r_is_objc_ptr(image) &&
        r_is_objc_ptr(themedImage) &&
        r_responds_main(image, "isEqual:")) {
        equal = (int)(r_msg2_main(image, "isEqual:", themedImage, 0, 0, 0) & 1);
    }

    char imageClass[96] = {0};
    themer_read_class_name(image, imageClass, sizeof(imageClass));
    printf("[SPOTLIGHT] app-provider-call bundle=%s selector=%s format=%d requestScale=%.2f "
           "image=0x%llx class=%s geom=%d size=%.1fx%.1f imageScale=%.2f "
           "themedImage=0x%llx ptrEq=%d cgEq=%d isEqual=%d imageCG=0x%llx themedCG=0x%llx\n",
           bundle ?: "?",
           selector ?: "?",
           format,
           requestScale,
           (unsigned long long)image,
           imageClass[0] ? imageClass : "-",
           hasGeometry,
           w, h, imageScale,
           (unsigned long long)themedImage,
           r_is_objc_ptr(image) && image == themedImage,
           imageCG && imageCG == themedCG,
           equal,
           (unsigned long long)imageCG,
           (unsigned long long)themedCG);
    return r_is_objc_ptr(image) ? 1 : 0;
}

static bool themer_spotlight_target_provider_format(int32_t format)
{
    return format == 0 || format == 3;
}

static bool themer_spotlight_image_cg_matches(uint64_t image,
                                              uint64_t themedImage)
{
    uint64_t imageCG = r_is_objc_ptr(image) && r_responds_main(image, "CGImage")
        ? r_msg2_main(image, "CGImage", 0, 0, 0, 0) : 0;
    uint64_t themedCG = r_is_objc_ptr(themedImage) &&
                        r_responds_main(themedImage, "CGImage")
        ? r_msg2_main(themedImage, "CGImage", 0, 0, 0, 0) : 0;
    return imageCG && imageCG == themedCG;
}

static uint64_t themer_spotlight_provider_sized_themed_image(uint64_t themedImage,
                                                             double targetPointWidth,
                                                             double fallbackScale)
{
    if (!r_is_objc_ptr(themedImage) ||
        targetPointWidth < 8.0 ||
        targetPointWidth > 180.0) {
        return 0;
    }

    uint64_t cg = r_responds_main(themedImage, "CGImage")
        ? r_msg2_main(themedImage, "CGImage", 0, 0, 0, 0) : 0;
    if (!cg) return 0;

    uint64_t pixelWidth = r_dlsym_call(R_TIMEOUT, "CGImageGetWidth",
                                       cg, 0, 0, 0, 0, 0, 0, 0);
    double outputScale = fallbackScale;
    if (pixelWidth > 0) {
        outputScale = (double)pixelWidth / targetPointWidth;
    }
    if (outputScale < 1.0 || outputScale > 10.0) {
        outputScale = (fallbackScale >= 1.0 && fallbackScale <= 4.0)
            ? fallbackScale
            : themer_screen_scale();
    }

    uint64_t orientation = r_responds_main(themedImage, "imageOrientation")
        ? r_msg2_main(themedImage, "imageOrientation", 0, 0, 0, 0)
        : 0;
    uint64_t UIImageCls = themer_lookup_class("UIImage");
    if (!r_is_objc_ptr(UIImageCls) ||
        !r_responds_main(UIImageCls, "imageWithCGImage:scale:orientation:")) {
        return 0;
    }

    uint64_t adjusted = r_msg2_main_raw(UIImageCls,
        "imageWithCGImage:scale:orientation:",
        &cg, sizeof(cg),
        &outputScale, sizeof(outputScale),
        &orientation, sizeof(orientation),
        NULL, 0);
    if (r_is_objc_ptr(adjusted)) {
        adjusted = r_msg2(adjusted, "retain", 0, 0, 0, 0);
    }
    return adjusted;
}

static int themer_spotlight_try_patch_provider_asset(const char *bundle,
                                                     int32_t format,
                                                     uint64_t providerImage,
                                                     uint64_t themedImage)
{
    if (!bundle || !bundle[0] ||
        !themer_spotlight_target_provider_format(format) ||
        !r_is_objc_ptr(providerImage) ||
        !r_is_objc_ptr(themedImage)) {
        return 0;
    }

    if (themer_spotlight_image_cg_matches(providerImage, themedImage)) {
        printf("[SPOTLIGHT] provider-asset-patch bundle=%s format=%d skipped reason=already-themed\n",
               bundle,
               format);
        return 0;
    }

    double targetW = 0.0;
    double targetH = 0.0;
    double targetScale = 0.0;
    bool hasGeometry = themer_read_image_geometry(providerImage,
                                                  &targetW,
                                                  &targetH,
                                                  &targetScale);
    if (!hasGeometry || targetW < 8.0 || targetH < 8.0) {
        printf("[SPOTLIGHT] provider-asset-patch bundle=%s format=%d skipped reason=bad-provider-geometry geom=%d size=%.1fx%.1f scale=%.2f\n",
               bundle,
               format,
               hasGeometry,
               targetW,
               targetH,
               targetScale);
        return 0;
    }

    uint64_t asset = r_responds_main(providerImage, "imageAsset")
        ? r_msg2_main(providerImage, "imageAsset", 0, 0, 0, 0) : 0;
    uint64_t trait = r_responds_main(providerImage, "traitCollection")
        ? r_msg2_main(providerImage, "traitCollection", 0, 0, 0, 0) : 0;
    uint64_t config = r_responds_main(providerImage, "configuration")
        ? r_msg2_main(providerImage, "configuration", 0, 0, 0, 0) : 0;
    uint64_t adjusted = themer_spotlight_provider_sized_themed_image(themedImage,
                                                                     targetW,
                                                                     targetScale);

    bool regTrait = false;
    bool regConfig = false;
    if (r_is_objc_ptr(asset) && r_is_objc_ptr(adjusted)) {
        if (r_is_objc_ptr(trait) &&
            r_responds_main(asset, "registerImage:withTraitCollection:")) {
            r_msg2_main(asset, "registerImage:withTraitCollection:",
                        adjusted, trait, 0, 0);
            regTrait = true;
        }
        if (r_is_objc_ptr(config) &&
            r_responds_main(asset, "registerImage:withConfiguration:")) {
            r_msg2_main(asset, "registerImage:withConfiguration:",
                        adjusted, config, 0, 0);
            regConfig = true;
        }
    }

    uint64_t assetTraitImage = 0;
    if (regTrait && r_responds_main(asset, "imageWithTraitCollection:")) {
        assetTraitImage = r_msg2_main(asset, "imageWithTraitCollection:",
                                      trait, 0, 0, 0);
    }
    bool assetTraitCgEq = themer_spotlight_image_cg_matches(assetTraitImage,
                                                            themedImage);
    uint64_t assetConfigImage = 0;
    if (regConfig && r_responds_main(asset, "imageWithConfiguration:")) {
        assetConfigImage = r_msg2_main(asset, "imageWithConfiguration:",
                                       config, 0, 0, 0);
    }
    bool assetConfigCgEq = themer_spotlight_image_cg_matches(assetConfigImage,
                                                             themedImage);

    double adjustedW = 0.0;
    double adjustedH = 0.0;
    double adjustedScale = 0.0;
    bool adjustedGeom = themer_read_image_geometry(adjusted,
                                                   &adjustedW,
                                                   &adjustedH,
                                                   &adjustedScale);

    printf("[SPOTLIGHT] provider-asset-patch bundle=%s format=%d asset=0x%llx trait=0x%llx config=0x%llx "
           "stockSize=%.1fx%.1f stockScale=%.2f adjusted=0x%llx adjustedGeom=%d adjustedSize=%.1fx%.1f adjustedScale=%.2f "
               "regTrait=%d regConfig=%d assetTraitImage=0x%llx assetTraitCgEq=%d "
               "assetConfigImage=0x%llx assetConfigCgEq=%d\n",
           bundle,
           format,
           (unsigned long long)asset,
           (unsigned long long)trait,
           (unsigned long long)config,
           targetW,
           targetH,
           targetScale,
           (unsigned long long)adjusted,
           adjustedGeom,
           adjustedW,
           adjustedH,
           adjustedScale,
               regTrait,
               regConfig,
               (unsigned long long)assetTraitImage,
               assetTraitCgEq,
               (unsigned long long)assetConfigImage,
               assetConfigCgEq);

    if (r_is_objc_ptr(adjusted)) {
        r_msg2(adjusted, "release", 0, 0, 0, 0);
    }

    if (assetTraitCgEq || assetConfigCgEq) return 2;
    return (regTrait || regConfig) ? 1 : 0;
}

static bool themer_spotlight_copy_cf_description(uint64_t obj,
                                                 char *out,
                                                 size_t outLen)
{
    if (!out || outLen == 0) return false;
    out[0] = '\0';
    if (!obj) return false;

    uint64_t desc = r_dlsym_call(R_TIMEOUT, "CFCopyDescription",
                                 obj, 0, 0, 0, 0, 0, 0, 0);
    if (!r_is_objc_ptr(desc)) return false;

    bool ok = r_read_nsstring(desc, out, outLen) && out[0];
    r_dlsym_call(R_TIMEOUT, "CFRelease",
                 desc, 0, 0, 0, 0, 0, 0, 0);
    return ok;
}

static uint64_t themer_spotlight_obj_for_first_selector(uint64_t obj,
                                                        const char * const *sels,
                                                        size_t selCount,
                                                        char *source,
                                                        size_t sourceLen)
{
    if (source && sourceLen > 0) source[0] = '\0';
    if (!r_is_objc_ptr(obj) || !sels || selCount == 0) return 0;

    for (size_t i = 0; i < selCount; i++) {
        const char *sel = sels[i];
        if (!sel || !r_responds_main(obj, sel)) continue;
        uint64_t value = r_msg2_main(obj, sel, 0, 0, 0, 0);
        if (r_is_objc_ptr(value)) {
            if (source && sourceLen > 0) snprintf(source, sourceLen, "%s", sel);
            return value;
        }
    }
    return 0;
}

static void themer_spotlight_log_provider_backing(const char *bundle,
                                                  int32_t format,
                                                  uint64_t image,
                                                  uint64_t themedImage)
{
    uint64_t cg = r_is_objc_ptr(image) && r_responds_main(image, "CGImage")
        ? r_msg2_main(image, "CGImage", 0, 0, 0, 0) : 0;
    uint64_t themedCG = r_is_objc_ptr(themedImage) &&
                        r_responds_main(themedImage, "CGImage")
        ? r_msg2_main(themedImage, "CGImage", 0, 0, 0, 0) : 0;

    uint64_t width = cg ? r_dlsym_call(R_TIMEOUT, "CGImageGetWidth",
                                       cg, 0, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t height = cg ? r_dlsym_call(R_TIMEOUT, "CGImageGetHeight",
                                        cg, 0, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t bpc = cg ? r_dlsym_call(R_TIMEOUT, "CGImageGetBitsPerComponent",
                                     cg, 0, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t bpp = cg ? r_dlsym_call(R_TIMEOUT, "CGImageGetBitsPerPixel",
                                     cg, 0, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t row = cg ? r_dlsym_call(R_TIMEOUT, "CGImageGetBytesPerRow",
                                     cg, 0, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t bitmap = cg ? r_dlsym_call(R_TIMEOUT, "CGImageGetBitmapInfo",
                                        cg, 0, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t alpha = cg ? r_dlsym_call(R_TIMEOUT, "CGImageGetAlphaInfo",
                                       cg, 0, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t provider = cg ? r_dlsym_call(R_TIMEOUT, "CGImageGetDataProvider",
                                          cg, 0, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t themedProvider = themedCG
        ? r_dlsym_call(R_TIMEOUT, "CGImageGetDataProvider",
                       themedCG, 0, 0, 0, 0, 0, 0, 0)
        : 0;
    uint64_t colorSpace = cg ? r_dlsym_call(R_TIMEOUT, "CGImageGetColorSpace",
                                            cg, 0, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t uttype = cg ? r_dlsym_call(R_TIMEOUT, "CGImageGetUTType",
                                        cg, 0, 0, 0, 0, 0, 0, 0) : 0;

    char providerDesc[220] = {0};
    (void)themer_spotlight_copy_cf_description(provider,
                                               providerDesc,
                                               sizeof(providerDesc));
    char colorDesc[160] = {0};
    (void)themer_spotlight_copy_cf_description(colorSpace,
                                               colorDesc,
                                               sizeof(colorDesc));
    char uttypeStr[120] = {0};
    if (r_is_objc_ptr(uttype)) {
        (void)r_read_nsstring(uttype, uttypeStr, sizeof(uttypeStr));
    }

    static const char *assetSels[] = {
        "imageAsset",
        "_imageAsset",
        "asset",
    };
    char assetSource[48] = {0};
    uint64_t asset = themer_spotlight_obj_for_first_selector(
        image, assetSels, sizeof(assetSels) / sizeof(assetSels[0]),
        assetSource, sizeof(assetSource));
    char assetClass[96] = {0};
    char assetDesc[220] = {0};
    themer_read_class_name(asset, assetClass, sizeof(assetClass));
    (void)themer_read_remote_description(asset, assetDesc, sizeof(assetDesc));

    static const char *metaSels[] = {
        "traitCollection",
        "configuration",
        "symbolConfiguration",
        "imageRendererFormat",
    };
    NSMutableArray<NSString *> *metaRows = [NSMutableArray array];
    for (size_t i = 0; i < sizeof(metaSels) / sizeof(metaSels[0]); i++) {
        const char *sel = metaSels[i];
        if (!r_responds_main(image, sel)) continue;
        uint64_t value = r_msg2_main(image, sel, 0, 0, 0, 0);
        if (!r_is_objc_ptr(value)) continue;
        char cls[80] = {0};
        char desc[180] = {0};
        themer_read_class_name(value, cls, sizeof(cls));
        (void)themer_read_remote_description(value, desc, sizeof(desc));
        if (metaRows.count < 6) {
            [metaRows addObject:[NSString stringWithFormat:@"%s=0x%llx/%s/%s",
                                 sel,
                                 (unsigned long long)value,
                                 cls[0] ? cls : "-",
                                 desc[0] ? desc : "-"]];
        }
    }

    uint64_t renderingMode = r_responds_main(image, "renderingMode")
        ? r_msg2_main(image, "renderingMode", 0, 0, 0, 0) : UINT64_MAX;
    char imageDesc[220] = {0};
    (void)themer_read_remote_description(image, imageDesc, sizeof(imageDesc));

    printf("[SPOTLIGHT] app-provider-backing bundle=%s format=%d "
           "image=0x%llx cg=0x%llx themedCG=0x%llx cgEq=%d "
           "pixels=%llux%llu bpc=%llu bpp=%llu row=%llu bitmap=0x%llx alpha=%llu "
           "provider=0x%llx themedProvider=0x%llx providerEq=%d providerDesc=\"%s\" "
           "colorSpace=0x%llx color=\"%s\" uttype=\"%s\" "
           "asset=0x%llx assetClass=%s assetSource=%s assetDesc=\"%s\" "
           "renderingMode=%s%llu meta=%s imageDesc=\"%s\"\n",
           bundle ?: "?",
           format,
           (unsigned long long)image,
           (unsigned long long)cg,
           (unsigned long long)themedCG,
           cg && cg == themedCG,
           (unsigned long long)width,
           (unsigned long long)height,
           (unsigned long long)bpc,
           (unsigned long long)bpp,
           (unsigned long long)row,
           (unsigned long long)bitmap,
           (unsigned long long)alpha,
           (unsigned long long)provider,
           (unsigned long long)themedProvider,
           provider && provider == themedProvider,
           providerDesc[0] ? providerDesc : "-",
           (unsigned long long)colorSpace,
           colorDesc[0] ? colorDesc : "-",
           uttypeStr[0] ? uttypeStr : "-",
           (unsigned long long)asset,
           assetClass[0] ? assetClass : "-",
           assetSource[0] ? assetSource : "-",
           assetDesc[0] ? assetDesc : "-",
           renderingMode == UINT64_MAX ? "?" : "",
           renderingMode == UINT64_MAX ? 0ULL : (unsigned long long)renderingMode,
           metaRows.count ? [metaRows componentsJoinedByString:@"|"].UTF8String : "-",
           imageDesc[0] ? imageDesc : "-");
}

static int themer_spotlight_probe_app_icon_providers(NSArray<NSString *> *bundles)
{
    uint64_t UIImageCls = themer_lookup_class("UIImage");
    bool hasScaled = r_is_objc_ptr(UIImageCls) &&
        r_responds_main(UIImageCls, "_applicationIconImageForBundleIdentifier:format:scale:");
    bool hasUnscaled = r_is_objc_ptr(UIImageCls) &&
        r_responds_main(UIImageCls, "_applicationIconImageForBundleIdentifier:format:");
    double scale = themer_screen_scale();
    printf("[SPOTLIGHT] app-provider probe begin class=0x%llx bundles=%lu scale=%.2f "
           "scaledSel=%d unscaledSel=%d formats=0,3,5 cacheWrites=disabled methodSwaps=disabled providerAssetPatch=enabled\n",
           (unsigned long long)UIImageCls,
           (unsigned long)(bundles ? bundles.count : 0),
           scale,
           hasScaled,
           hasUnscaled);

    if (!r_is_objc_ptr(UIImageCls) || (!hasScaled && !hasUnscaled) ||
        bundles.count == 0) {
        printf("[SPOTLIGHT] app-provider probe complete hits=0 reason=%s\n",
               !r_is_objc_ptr(UIImageCls) ? "missing-UIImage" :
               (!hasScaled && !hasUnscaled) ? "missing-selectors" :
               "no-bundles");
        return 0;
    }

    int hits = 0;
    uint32_t prevSettle = r_settle_us(0);
    for (NSString *bundleString in bundles) {
        if (![bundleString isKindOfClass:NSString.class] ||
            bundleString.length == 0) {
            continue;
        }
        const char *bundle = bundleString.UTF8String;
        uint64_t themedImage = themer_lookup_cached(bundle);
        double themedW = 0.0;
        double themedH = 0.0;
        double themedScale = 0.0;
        bool themedGeom = themer_read_image_geometry(themedImage,
                                                     &themedW,
                                                     &themedH,
                                                     &themedScale);
        printf("[SPOTLIGHT] app-provider bundle=%s themedImage=0x%llx themedGeom=%d "
               "themedSize=%.1fx%.1f themedScale=%.2f\n",
               bundle,
               (unsigned long long)themedImage,
               themedGeom,
               themedW, themedH, themedScale);

        uint64_t bid = r_nsstr_retained(bundle);
        if (!r_is_objc_ptr(bid)) {
            printf("[SPOTLIGHT] app-provider bundle=%s skipped reason=NSString-create-failed\n",
                   bundle);
            continue;
        }

        if (hasScaled) {
            static const int32_t formats[] = { 0, 3, 5 };
            for (size_t i = 0; i < sizeof(formats) / sizeof(formats[0]); i++) {
                int32_t format = formats[i];
                uint64_t image = r_msg2_main_raw(UIImageCls,
                    "_applicationIconImageForBundleIdentifier:format:scale:",
                    &bid, sizeof(bid),
                    &format, sizeof(format),
                    &scale, sizeof(scale),
                    NULL, 0);
                hits += themer_spotlight_log_provider_image(
                    bundle,
                    "_applicationIconImageForBundleIdentifier:format:scale:",
                    format,
                    scale,
                    image,
                    themedImage);
                if (r_is_objc_ptr(image)) {
                    themer_spotlight_log_provider_backing(bundle,
                                                          format,
                                                          image,
                                                          themedImage);
                }
                if (themer_spotlight_try_patch_provider_asset(bundle,
                                                              format,
                                                              image,
                                                              themedImage) > 0) {
                    uint64_t after = r_msg2_main_raw(UIImageCls,
                        "_applicationIconImageForBundleIdentifier:format:scale:",
                        &bid, sizeof(bid),
                        &format, sizeof(format),
                        &scale, sizeof(scale),
                        NULL, 0);
                    hits += themer_spotlight_log_provider_image(
                        bundle,
                        "_applicationIconImageForBundleIdentifier:format:scale:/after-asset-patch",
                        format,
                        scale,
                        after,
                        themedImage);
                    if (r_is_objc_ptr(after)) {
                        themer_spotlight_log_provider_backing(bundle,
                                                              format,
                                                              after,
                                                              themedImage);
                    }
                }
            }
        }

        if (!hasScaled && hasUnscaled) {
            static const int32_t formats[] = { 0, 3, 5 };
            for (size_t i = 0; i < sizeof(formats) / sizeof(formats[0]); i++) {
                int32_t format = formats[i];
                uint64_t image = r_msg2_main_raw(UIImageCls,
                    "_applicationIconImageForBundleIdentifier:format:",
                    &bid, sizeof(bid),
                    &format, sizeof(format),
                    NULL, 0,
                    NULL, 0);
                hits += themer_spotlight_log_provider_image(
                    bundle,
                    "_applicationIconImageForBundleIdentifier:format:",
                    format,
                    0.0,
                    image,
                    themedImage);
                if (r_is_objc_ptr(image)) {
                    themer_spotlight_log_provider_backing(bundle,
                                                          format,
                                                          image,
                                                          themedImage);
                }
                if (themer_spotlight_try_patch_provider_asset(bundle,
                                                              format,
                                                              image,
                                                              themedImage) > 0) {
                    uint64_t after = r_msg2_main_raw(UIImageCls,
                        "_applicationIconImageForBundleIdentifier:format:",
                        &bid, sizeof(bid),
                        &format, sizeof(format),
                        NULL, 0,
                        NULL, 0);
                    hits += themer_spotlight_log_provider_image(
                        bundle,
                        "_applicationIconImageForBundleIdentifier:format:/after-asset-patch",
                        format,
                        0.0,
                        after,
                        themedImage);
                    if (r_is_objc_ptr(after)) {
                        themer_spotlight_log_provider_backing(bundle,
                                                              format,
                                                              after,
                                                              themedImage);
                    }
                }
            }
        }

        r_msg2(bid, "release", 0, 0, 0, 0);
    }
    r_settle_us(prevSettle);

    printf("[SPOTLIGHT] app-provider probe complete hits=%d\n", hits);
    return hits;
}

static NSString *themer_spotlight_method_rows_for_class(uint64_t cls,
                                                        NSUInteger limit)
{
    if (!r_is_objc_ptr(cls) || limit == 0) return @"";

    uint64_t countBuf = r_dlsym_call(R_TIMEOUT, "malloc",
                                     8, 0, 0, 0, 0, 0, 0, 0);
    if (!countBuf) return @"";
    remote_write64(countBuf, 0);
    uint64_t methods = r_dlsym_call(R_TIMEOUT, "class_copyMethodList",
                                    cls, countBuf, 0, 0, 0, 0, 0, 0);
    uint32_t count = 0;
    remote_read(countBuf, &count, sizeof(count));
    r_free(countBuf);

    NSMutableArray<NSString *> *rows = [NSMutableArray array];
    if (methods && count > 0 && count <= 2048) {
        uint32_t cap = count < 2048 ? count : 2048;
        for (uint32_t i = 0; i < cap && rows.count < limit; i++) {
            uint64_t method = remote_read64(methods + ((uint64_t)i * sizeof(uint64_t)));
            if (!method) continue;
            uint64_t sel = r_dlsym_call(R_TIMEOUT, "method_getName",
                                        method, 0, 0, 0, 0, 0, 0, 0);
            uint64_t nameCstr = sel ? r_dlsym_call(R_TIMEOUT, "sel_getName",
                                                   sel, 0, 0, 0, 0, 0, 0, 0) : 0;
            char name[160] = {0};
            if (!themer_read_remote_cstring(nameCstr, name, sizeof(name)) ||
                !themer_spotlight_method_name_is_interesting(name)) {
                continue;
            }

            uint64_t typeCstr = r_dlsym_call(R_TIMEOUT, "method_getTypeEncoding",
                                             method, 0, 0, 0, 0, 0, 0, 0);
            char types[192] = {0};
            (void)themer_read_remote_cstring(typeCstr, types, sizeof(types));
            [rows addObject:[NSString stringWithFormat:@"%s/%s",
                             name, types[0] ? types : "?"]];
        }
    }
    if (methods) r_free(methods);
    return rows.count ? [rows componentsJoinedByString:@","] : @"";
}

static NSString *themer_spotlight_ivar_rows_for_class(uint64_t cls,
                                                      NSUInteger limit)
{
    if (!r_is_objc_ptr(cls) || limit == 0) return @"";

    uint64_t countBuf = r_dlsym_call(R_TIMEOUT, "malloc",
                                     8, 0, 0, 0, 0, 0, 0, 0);
    if (!countBuf) return @"";
    remote_write64(countBuf, 0);
    uint64_t ivars = r_dlsym_call(R_TIMEOUT, "class_copyIvarList",
                                  cls, countBuf, 0, 0, 0, 0, 0, 0);
    uint32_t count = 0;
    remote_read(countBuf, &count, sizeof(count));
    r_free(countBuf);

    NSMutableArray<NSString *> *rows = [NSMutableArray array];
    if (ivars && count > 0 && count <= 2048) {
        uint32_t cap = count < 2048 ? count : 2048;
        for (uint32_t i = 0; i < cap && rows.count < limit; i++) {
            uint64_t ivar = remote_read64(ivars + ((uint64_t)i * sizeof(uint64_t)));
            if (!ivar) continue;
            uint64_t nameCstr = r_dlsym_call(R_TIMEOUT, "ivar_getName",
                                             ivar, 0, 0, 0, 0, 0, 0, 0);
            uint64_t typeCstr = r_dlsym_call(R_TIMEOUT, "ivar_getTypeEncoding",
                                             ivar, 0, 0, 0, 0, 0, 0, 0);
            uint64_t offset = r_dlsym_call(R_TIMEOUT, "ivar_getOffset",
                                           ivar, 0, 0, 0, 0, 0, 0, 0);
            char name[160] = {0};
            char type[160] = {0};
            (void)themer_read_remote_cstring(nameCstr, name, sizeof(name));
            (void)themer_read_remote_cstring(typeCstr, type, sizeof(type));
            if (!name[0]) continue;
            if (!themer_spotlight_method_name_is_interesting(name) &&
                !strstr(name, "app") &&
                !strstr(name, "icon") &&
                !strstr(name, "view") &&
                !strstr(name, "image")) {
                continue;
            }
            [rows addObject:[NSString stringWithFormat:@"%s/%s@%lld",
                             name,
                             type[0] ? type : "?",
                             (long long)offset]];
        }
    }
    if (ivars) r_free(ivars);
    return rows.count ? [rows componentsJoinedByString:@","] : @"";
}

static void themer_spotlight_log_class_shape_for_class(uint64_t cls,
                                                       const char *label)
{
    if (!r_is_objc_ptr(cls)) return;

    NSMutableArray<NSString *> *hierarchy = [NSMutableArray array];
    NSMutableArray<NSString *> *methods = [NSMutableArray array];
    NSMutableArray<NSString *> *ivars = [NSMutableArray array];
    uint64_t cursor = cls;
    for (int depth = 0; r_is_objc_ptr(cursor) && depth < 8; depth++) {
        char className[128] = {0};
        themer_read_class_object_name(cursor, className, sizeof(className));
        if (!className[0]) break;

        [hierarchy addObject:[NSString stringWithUTF8String:className]];
        NSString *methodRows = themer_spotlight_method_rows_for_class(cursor, 32);
        if (methodRows.length > 0 && methods.count < 4) {
            [methods addObject:[NSString stringWithFormat:@"%s:{%@}",
                                className, methodRows]];
        }
        NSString *ivarRows = themer_spotlight_ivar_rows_for_class(cursor, 24);
        if (ivarRows.length > 0 && ivars.count < 4) {
            [ivars addObject:[NSString stringWithFormat:@"%s:{%@}",
                              className, ivarRows]];
        }

        cursor = r_dlsym_call(R_TIMEOUT, "class_getSuperclass",
                              cursor, 0, 0, 0, 0, 0, 0, 0);
    }

    printf("[SPOTLIGHT] class-shape label=%s class=0x%llx hierarchy=%s methods=%s ivars=%s\n",
           label ?: "?",
           (unsigned long long)cls,
           hierarchy.count ? [hierarchy componentsJoinedByString:@">"].UTF8String : "",
           methods.count ? [methods componentsJoinedByString:@"|"].UTF8String : "",
           ivars.count ? [ivars componentsJoinedByString:@"|"].UTF8String : "");
}

static void themer_spotlight_log_class_shape(const char *className)
{
    uint64_t cls = themer_lookup_class(className);
    if (!r_is_objc_ptr(cls)) {
        printf("[SPOTLIGHT] class-shape label=%s unavailable\n",
               className ?: "?");
        return;
    }
    themer_spotlight_log_class_shape_for_class(cls, className);
}

static bool themer_spotlight_loaded_class_is_candidate(const char *className)
{
    if (!className || !className[0]) return false;
    static const char *contextNeedles[] = {
        "Search", "Spotlight", "Siri", "Suggest", "Suggestion",
        "Result", "SPUI", "CS"
    };
    static const char *iconNeedles[] = {
        "Icon", "Image", "Glyph", "App", "Bundle"
    };
    return themer_cstring_has_any(className, contextNeedles,
                                  sizeof(contextNeedles) / sizeof(contextNeedles[0])) &&
           themer_cstring_has_any(className, iconNeedles,
                                  sizeof(iconNeedles) / sizeof(iconNeedles[0]));
}

static int themer_spotlight_log_candidate_classes(void)
{
    uint64_t rawCount = r_dlsym_call(R_TIMEOUT, "objc_getClassList",
                                    0, 0, 0, 0, 0, 0, 0, 0);
    if (rawCount == 0 || rawCount > 50000) {
        printf("[SPOTLIGHT] candidate-class scan skipped count=%llu\n",
               (unsigned long long)rawCount);
        return 0;
    }

    uint64_t bytes = rawCount * sizeof(uint64_t);
    uint64_t buffer = r_dlsym_call(R_TIMEOUT, "malloc",
                                   bytes, 0, 0, 0, 0, 0, 0, 0);
    if (!buffer) {
        printf("[SPOTLIGHT] candidate-class scan skipped reason=malloc-failed count=%llu\n",
               (unsigned long long)rawCount);
        return 0;
    }

    uint64_t filled = r_dlsym_call(R_TIMEOUT, "objc_getClassList",
                                  buffer, rawCount, 0, 0, 0, 0, 0, 0);
    uint64_t count = filled < rawCount ? filled : rawCount;
    NSMutableArray<NSString *> *samples = [NSMutableArray array];
    int matches = 0;
    int shaped = 0;
    for (uint64_t i = 0; i < count; i++) {
        uint64_t cls = remote_read64(buffer + (i * sizeof(uint64_t)));
        if (!r_is_objc_ptr(cls)) continue;
        char className[128] = {0};
        themer_read_class_object_name(cls, className, sizeof(className));
        if (!themer_spotlight_loaded_class_is_candidate(className)) continue;

        matches++;
        if (samples.count < 96) {
            [samples addObject:[NSString stringWithUTF8String:className]];
        }
        if (shaped < 8 && strstr(className, "View")) {
            themer_spotlight_log_class_shape_for_class(cls, className);
            shaped++;
        }
    }
    r_free(buffer);

    printf("[SPOTLIGHT] candidate-class scan complete runtimeClasses=%llu matches=%d shaped=%d samples=%s\n",
           (unsigned long long)count,
           matches,
           shaped,
           samples.count ? [samples componentsJoinedByString:@","].UTF8String : "");
    return matches;
}

static uint64_t themer_spotlight_object_from_candidates(uint64_t obj,
                                                        const char * const *sels,
                                                        size_t selCount,
                                                        const char * const *ivars,
                                                        size_t ivarCount,
                                                        char *source,
                                                        size_t sourceLen)
{
    if (source && sourceLen > 0) source[0] = '\0';
    if (!r_is_objc_ptr(obj)) return 0;

    for (size_t i = 0; i < selCount; i++) {
        const char *sel = sels[i];
        if (!sel || !r_responds_main(obj, sel)) continue;
        uint64_t value = r_msg2_main(obj, sel, 0, 0, 0, 0);
        if (r_is_objc_ptr(value)) {
            if (source && sourceLen > 0) snprintf(source, sourceLen, "sel:%s", sel);
            return value;
        }
    }

    for (size_t i = 0; i < ivarCount; i++) {
        const char *ivar = ivars[i];
        if (!ivar) continue;
        uint64_t value = r_ivar_value(obj, ivar);
        if (r_is_objc_ptr(value)) {
            if (source && sourceLen > 0) snprintf(source, sourceLen, "ivar:%s", ivar);
            return value;
        }
    }
    return 0;
}

static uint64_t themer_spotlight_image_from_view(uint64_t view,
                                                 uint64_t *carrierOut,
                                                 char *source,
                                                 size_t sourceLen)
{
    if (carrierOut) *carrierOut = 0;
    if (source && sourceLen > 0) source[0] = '\0';
    if (!r_is_objc_ptr(view)) return 0;

    if (r_responds_main(view, "image")) {
        uint64_t image = r_msg2_main(view, "image", 0, 0, 0, 0);
        double w = 0.0, h = 0.0, scale = 0.0;
        if (r_is_objc_ptr(image) &&
            themer_read_image_geometry(image, &w, &h, &scale)) {
            if (carrierOut) *carrierOut = view;
            if (source && sourceLen > 0) snprintf(source, sourceLen, "self.image");
            return image;
        }
    }

    static const char *imageViewSels[] = {
        "imageView",
        "_imageView",
        "iconImageView",
        "_iconImageView",
        "appIconImageView",
        "_appIconImageView",
        "contentImageView",
        "_contentImageView",
    };
    static const char *imageViewIvars[] = {
        "_imageView",
        "_iconImageView",
        "_appIconImageView",
        "_contentImageView",
    };
    char carrierSource[96] = {0};
    uint64_t carrier = themer_spotlight_object_from_candidates(
        view,
        imageViewSels, sizeof(imageViewSels) / sizeof(imageViewSels[0]),
        imageViewIvars, sizeof(imageViewIvars) / sizeof(imageViewIvars[0]),
        carrierSource, sizeof(carrierSource));
    if (!r_is_objc_ptr(carrier)) return 0;
    if (carrierOut) *carrierOut = carrier;

    // SBIconImageView commonly leaves UIImageView-style `image` nil while
    // its active render is exposed as `displayedImage`.  Reuse the canonical
    // carrier reader so a nil `image` result does not discard the live row.
    uint64_t image = themer_spotlight_image_from_carrier(carrier);
    double w = 0.0, h = 0.0, scale = 0.0;
    if (r_is_objc_ptr(image) &&
        themer_read_image_geometry(image, &w, &h, &scale)) {
        if (source && sourceLen > 0) {
            snprintf(source, sourceLen, "%s.renderedImage", carrierSource);
        }
        return image;
    }
    return 0;
}

static bool themer_spotlight_object_is_application_icon(uint64_t obj)
{
    if (!r_is_objc_ptr(obj)) return false;

    uint64_t applicationIconClass = themer_lookup_class("SBApplicationIcon");
    if (r_is_objc_ptr(applicationIconClass) &&
        r_responds_main(obj, "isKindOfClass:") &&
        (r_msg2_main(obj, "isKindOfClass:",
                     applicationIconClass, 0, 0, 0) & 1)) {
        return true;
    }
    return themer_icon_is_application_icon(obj);
}

static uint64_t themer_spotlight_application_icon_from_object(uint64_t obj,
                                                              char *source,
                                                              size_t sourceLen)
{
    if (source && sourceLen > 0) source[0] = '\0';
    if (!r_is_objc_ptr(obj)) return 0;
    if (themer_spotlight_object_is_application_icon(obj)) {
        if (source && sourceLen > 0) snprintf(source, sourceLen, "self");
        return obj;
    }

    static const char *selectors[] = {
        "appIcon",
        "icon",
        "applicationIcon",
        "representedIcon",
        "representedAppIcon",
    };
    for (size_t i = 0; i < sizeof(selectors) / sizeof(selectors[0]); i++) {
        const char *selector = selectors[i];
        if (!r_responds_main(obj, selector)) continue;
        uint64_t candidate = r_msg2_main(obj, selector, 0, 0, 0, 0);
        if (!themer_spotlight_object_is_application_icon(candidate)) continue;
        if (source && sourceLen > 0) snprintf(source, sourceLen, "sel:%s", selector);
        return candidate;
    }

    static const char *ivars[] = {
        "_appIcon",
        "_icon",
        "_applicationIcon",
        "_representedIcon",
        "_representedAppIcon",
    };
    for (size_t i = 0; i < sizeof(ivars) / sizeof(ivars[0]); i++) {
        const char *ivar = ivars[i];
        uint64_t candidate = r_ivar_value(obj, ivar);
        if (!themer_spotlight_object_is_application_icon(candidate)) continue;
        if (source && sourceLen > 0) snprintf(source, sourceLen, "ivar:%s", ivar);
        return candidate;
    }
    return 0;
}

static uint64_t themer_spotlight_app_icon_for_view(uint64_t view,
                                                   char *source,
                                                   size_t sourceLen)
{
    if (source && sourceLen > 0) source[0] = '\0';

    char localSource[96] = {0};
    uint64_t icon = themer_spotlight_application_icon_from_object(
        view, localSource, sizeof(localSource));
    if (r_is_objc_ptr(icon)) {
        if (source && sourceLen > 0) {
            snprintf(source, sourceLen, "view.%s", localSource);
        }
        return icon;
    }

    static const char *modelSelectors[] = {
        "representedObject",
        "application",
        "app",
        "item",
        "model",
        "searchResult",
        "result",
        "suggestion",
    };
    for (size_t i = 0;
         i < sizeof(modelSelectors) / sizeof(modelSelectors[0]);
         i++) {
        const char *selector = modelSelectors[i];
        if (!r_responds_main(view, selector)) continue;
        uint64_t model = r_msg2_main(view, selector, 0, 0, 0, 0);
        icon = themer_spotlight_application_icon_from_object(
            model, localSource, sizeof(localSource));
        if (!r_is_objc_ptr(icon)) continue;
        if (source && sourceLen > 0) {
            snprintf(source, sourceLen, "view.%s.%s", selector, localSource);
        }
        return icon;
    }

    static const char *modelIvars[] = {
        "_representedObject",
        "_application",
        "_app",
        "_item",
        "_model",
        "_searchResult",
        "_result",
        "_suggestion",
    };
    for (size_t i = 0; i < sizeof(modelIvars) / sizeof(modelIvars[0]); i++) {
        const char *ivar = modelIvars[i];
        uint64_t model = r_ivar_value(view, ivar);
        icon = themer_spotlight_application_icon_from_object(
            model, localSource, sizeof(localSource));
        if (!r_is_objc_ptr(icon)) continue;
        if (source && sourceLen > 0) {
            snprintf(source, sourceLen, "view.ivar:%s.%s", ivar, localSource);
        }
        return icon;
    }
    return 0;
}

static bool themer_spotlight_bundle_for_view(uint64_t view,
                                             uint64_t appIcon,
                                             char *bundle,
                                             size_t bundleLen,
                                             char *source,
                                             size_t sourceLen,
                                             bool *fromIconOut)
{
    if (bundle && bundleLen > 0) bundle[0] = '\0';
    if (source && sourceLen > 0) source[0] = '\0';
    if (fromIconOut) *fromIconOut = false;
    if (!bundle || bundleLen == 0) return false;

    if (r_is_objc_ptr(appIcon)) {
        if (themer_read_bundle_for_icon(appIcon, view, bundle, bundleLen)) {
            if (source && sourceLen > 0) snprintf(source, sourceLen, "appIcon.application");
            if (fromIconOut) *fromIconOut = true;
            return true;
        }

        char iconSource[160] = {0};
        if (themer_read_bundle_hint_from_object(appIcon,
                                                bundle, bundleLen,
                                                iconSource,
                                                sizeof(iconSource))) {
            if (source && sourceLen > 0) {
                snprintf(source, sourceLen, "appIcon.%s", iconSource);
            }
            return true;
        }

        static const char *nestedIconSels[] = {
            "icon",
            "appIcon",
            "applicationIcon",
            "representedIcon",
            "representedAppIcon",
        };
        char nestedSource[96] = {0};
        uint64_t nested = themer_spotlight_object_from_candidates(
            appIcon,
            nestedIconSels, sizeof(nestedIconSels) / sizeof(nestedIconSels[0]),
            NULL, 0,
            nestedSource, sizeof(nestedSource));
        if (r_is_objc_ptr(nested) &&
            themer_read_bundle_for_icon(nested, view, bundle, bundleLen)) {
            if (source && sourceLen > 0) {
                snprintf(source, sourceLen, "appIcon.%s.application", nestedSource);
            }
            if (fromIconOut) *fromIconOut = true;
            return true;
        }
    }

    char nearSource[160] = {0};
    if (themer_find_bundle_hint_near_view(view,
                                          bundle, bundleLen,
                                          nearSource,
                                          sizeof(nearSource))) {
        if (source && sourceLen > 0) snprintf(source, sourceLen, "%s", nearSource);
        return true;
    }
    return false;
}

static bool themer_spotlight_object_looks_like_icon_cache(uint64_t obj)
{
    if (!r_is_objc_ptr(obj)) return false;
    char className[96] = {0};
    themer_read_class_name(obj, className, sizeof(className));
    if (strstr(className, "IconImageCache")) return true;
    return r_responds_main(obj, "cachedImageForIcon:") ||
           r_responds_main(obj, "imageForIcon:") ||
           r_responds_main(obj, "cacheImage:forIcon:imageAppearance:");
}

static uint64_t themer_spotlight_cache_from_object(uint64_t obj,
                                                   char *source,
                                                   size_t sourceLen)
{
    static const char *cacheSels[] = {
        "iconImageCache",
        "imageCache",
        "cache",
    };
    static const char *cacheIvars[] = {
        "_iconImageCache",
        "_imageCache",
        "_cache",
    };
    uint64_t cache = themer_spotlight_object_from_candidates(
        obj,
        cacheSels, sizeof(cacheSels) / sizeof(cacheSels[0]),
        cacheIvars, sizeof(cacheIvars) / sizeof(cacheIvars[0]),
        source, sourceLen);
    return themer_spotlight_object_looks_like_icon_cache(cache) ? cache : 0;
}

static uint64_t themer_spotlight_find_icon_cache(uint64_t view,
                                                 uint64_t imageCarrier,
                                                 uint64_t appIcon,
                                                 char *source,
                                                 size_t sourceLen)
{
    if (source && sourceLen > 0) source[0] = '\0';
    static const struct {
        const char *label;
        int slot;
    } candidates[] = {
        { "view", 0 },
        { "imageCarrier", 1 },
        { "appIcon", 2 },
    };
    for (size_t i = 0; i < sizeof(candidates) / sizeof(candidates[0]); i++) {
        uint64_t obj = candidates[i].slot == 0 ? view
                     : candidates[i].slot == 1 ? imageCarrier
                     : appIcon;
        char localSource[96] = {0};
        uint64_t cache = themer_spotlight_cache_from_object(obj,
                                                            localSource,
                                                            sizeof(localSource));
        if (r_is_objc_ptr(cache)) {
            if (source && sourceLen > 0) {
                snprintf(source, sourceLen, "%s.%s",
                         candidates[i].label, localSource);
            }
            return cache;
        }
    }
    return 0;
}

static bool themer_spotlight_add_unique_view(uint64_t *views,
                                             int *count,
                                             int cap,
                                             uint64_t view)
{
    if (!views || !count || *count >= cap || !r_is_objc_ptr(view)) return false;
    for (int i = 0; i < *count; i++) {
        if (views[i] == view) return false;
    }
    views[(*count)++] = view;
    return true;
}

static int themer_spotlight_collect_searchui_views(uint64_t *views, int cap)
{
    if (!views || cap <= 0) return 0;

    uint64_t cls = themer_lookup_class("SearchUIHomeScreenAppIconView");
    if (!r_is_objc_ptr(cls)) return 0;

    int count = 0;
    enum { INITIAL_VIEW_CAP = 128 };
    uint64_t initialViews[INITIAL_VIEW_CAP] = {0};
    int initialCap = cap < INITIAL_VIEW_CAP ? cap : INITIAL_VIEW_CAP;
    int initialCount = sb_collect_views_in_windows(cls, initialViews, initialCap);
    for (int i = 0; i < initialCount && count < cap; i++) {
        (void)themer_spotlight_add_unique_view(views, &count, cap,
                                               initialViews[i]);
    }
    if (count >= cap) return count;

    uint64_t UIApplication = themer_lookup_class("UIApplication");
    uint64_t app = r_is_objc_ptr(UIApplication)
        ? r_msg2_main(UIApplication, "sharedApplication", 0, 0, 0, 0) : 0;
    uint64_t scenes = r_is_objc_ptr(app) && r_responds_main(app, "connectedScenes")
        ? r_msg2_main(app, "connectedScenes", 0, 0, 0, 0) : 0;
    uint64_t sceneArray = scenes;
    if (r_is_objc_ptr(sceneArray) &&
        !r_responds_main(sceneArray, "objectAtIndex:") &&
        r_responds_main(sceneArray, "allObjects")) {
        sceneArray = r_msg2_main(sceneArray, "allObjects", 0, 0, 0, 0);
    }

    uint64_t sceneCount = themer_collection_count_capped(sceneArray, 16);
    for (uint64_t i = 0; i < sceneCount && count < cap; i++) {
        uint64_t scene = r_msg2_main(sceneArray, "objectAtIndex:", i, 0, 0, 0);
        uint64_t windows = r_is_objc_ptr(scene) && r_responds_main(scene, "windows")
            ? r_msg2_main(scene, "windows", 0, 0, 0, 0) : 0;
        uint64_t windowCount = themer_collection_count_capped(windows, 32);
        for (uint64_t w = 0; w < windowCount && count < cap; w++) {
            uint64_t window = r_msg2_main(windows, "objectAtIndex:", w, 0, 0, 0);
            if (!r_is_objc_ptr(window)) continue;

            enum { LOCAL_CAP = 64 };
            uint64_t local[LOCAL_CAP] = {0};
            int localCount = sb_collect_views(window, cls, local, LOCAL_CAP);
            for (int j = 0; j < localCount && count < cap; j++) {
                (void)themer_spotlight_add_unique_view(views, &count, cap, local[j]);
            }
        }
    }
    return count;
}

static int themer_spotlight_collect_searchui_views_fast(uint64_t *views,
                                                        int cap)
{
    if (!views || cap <= 0) return 0;
    uint64_t cls = themer_lookup_class("SearchUIHomeScreenAppIconView");
    if (!r_is_objc_ptr(cls)) return 0;

    // The standard UIApplication windows path found all 12 rows on the first
    // device trace. Avoid repeating a connected-scenes crawl on every sample;
    // retain the full collector only as a zero-result fallback.
    int count = sb_collect_views_in_windows(cls, views, cap);
    if (count > 0 || !remote_call_current_success()) return count;
    return themer_spotlight_collect_searchui_views(views, cap);
}

static uint64_t themer_spotlight_image_carrier_for_view(uint64_t view)
{
    if (!r_is_objc_ptr(view)) return 0;
    if (r_responds_main(view, "image") ||
        r_responds_main(view, "displayedImage")) {
        return view;
    }

    static const char *selectors[] = {
        "imageView",
        "_imageView",
        "iconImageView",
        "_iconImageView",
        "appIconImageView",
        "_appIconImageView",
        "contentImageView",
        "_contentImageView",
    };
    static const char *ivars[] = {
        "_imageView",
        "_iconImageView",
        "_appIconImageView",
        "_contentImageView",
    };
    return themer_spotlight_object_from_candidates(
        view,
        selectors, sizeof(selectors) / sizeof(selectors[0]),
        ivars, sizeof(ivars) / sizeof(ivars[0]),
        NULL, 0);
}

static uint64_t themer_spotlight_image_from_carrier(uint64_t carrier)
{
    if (!r_is_objc_ptr(carrier)) return 0;
    static const char *selectors[] = {
        "image",
        "displayedImage",
        "contentsImage",
    };
    for (size_t i = 0; i < sizeof(selectors) / sizeof(selectors[0]); i++) {
        const char *selector = selectors[i];
        if (!r_responds_main(carrier, selector)) continue;
        bool forceSpotlightMain = remote_call_uses_lab_backend() &&
            !strcmp(selector, "contentsImage");
        if (forceSpotlightMain) {
            printf("[ICONINDEX] carrier getter=contentsImage "
                   "dispatch=spotlight-main\n");
        }
        uint64_t image = forceSpotlightMain
            ? r_msg2_target_main_retained_object(
                carrier, selector, 0, 0, 0, 0)
            : r_msg2_main(carrier, selector, 0, 0, 0, 0);
        if (!r_is_objc_ptr(image)) continue;
        if (forceSpotlightMain) {
            // Balance the helper's +1 ownership into the existing remote
            // autorelease pool so callers retain the historical +0 contract.
            uint64_t balanced = r_msg2(image, "autorelease", 0, 0, 0, 0);
            if (balanced != image || !remote_call_current_success()) return 0;
        }
        return image;
    }
    return 0;
}

static bool themer_spotlight_object_selector_returns_object(uint64_t obj,
                                                            const char *selector)
{
    if (!r_is_objc_ptr(obj) || !selector || !selector[0]) return false;
    uint64_t cls = r_dlsym_call(R_TIMEOUT, "object_getClass",
                                obj, 0, 0, 0, 0, 0, 0, 0);
    uint64_t method = themer_spotlight_method_for_target(cls, selector, false);
    uint64_t typeCstr = method
        ? r_dlsym_call(R_TIMEOUT, "method_getTypeEncoding",
                       method, 0, 0, 0, 0, 0, 0, 0)
        : 0;
    char types[96] = {0};
    if (!themer_read_remote_cstring(typeCstr, types, sizeof(types))) return false;

    const char *type = types;
    while (*type && strchr("rnNoORV", *type)) type++;
    return *type == '@';
}

static bool themer_spotlight_bundle_for_patch(uint64_t view,
                                              uint64_t appIcon,
                                              char *bundle,
                                              size_t bundleLen,
                                              char *source,
                                              size_t sourceLen)
{
    if (!bundle || bundleLen == 0) return false;
    bundle[0] = '\0';
    if (source && sourceLen > 0) source[0] = '\0';

    if (r_is_objc_ptr(appIcon)) {
        uint64_t application = r_responds_main(appIcon, "application")
            ? r_msg2_main(appIcon, "application", 0, 0, 0, 0) : 0;
        if (r_is_objc_ptr(application) &&
            themer_read_bundle_hint_from_object(application,
                                                bundle, bundleLen,
                                                source, sourceLen)) {
            if (source && sourceLen > 0) {
                char nested[128] = {0};
                snprintf(nested, sizeof(nested), "application.%s", source);
                snprintf(source, sourceLen, "%s", nested);
            }
            return true;
        }

        if (themer_read_bundle_hint_from_object(appIcon,
                                                bundle, bundleLen,
                                                source, sourceLen)) {
            return true;
        }

        static const char *identifierSelectors[] = {
            "leafIdentifier",
            "applicationBundleID",
        };
        for (size_t i = 0;
             i < sizeof(identifierSelectors) / sizeof(identifierSelectors[0]);
             i++) {
            const char *selector = identifierSelectors[i];
            if (!r_responds_main(appIcon, selector) ||
                !themer_spotlight_object_selector_returns_object(appIcon, selector)) {
                continue;
            }
            uint64_t identifier = r_msg2_main(appIcon, selector, 0, 0, 0, 0);
            char candidate[192] = {0};
            if (r_is_objc_ptr(identifier) &&
                r_read_nsstring(identifier, candidate, sizeof(candidate)) &&
                themer_string_looks_like_bundle_id(candidate)) {
                snprintf(bundle, bundleLen, "%s", candidate);
                if (source && sourceLen > 0) snprintf(source, sourceLen, "%s", selector);
                return true;
            }
        }
    }

    return themer_find_bundle_hint_near_view(view,
                                             bundle, bundleLen,
                                             source, sourceLen);
}

static uint64_t themer_spotlight_image_appearance(uint64_t view,
                                                  uint64_t carrier,
                                                  char *source,
                                                  size_t sourceLen)
{
    if (source && sourceLen > 0) source[0] = '\0';
    static const char *selectors[] = {
        "effectiveIconImageAppearance",
        "iconImageAppearance",
        "imageAppearance",
    };
    static const char *ivars[] = {
        "_effectiveIconImageAppearance",
        "_iconImageAppearance",
        "_imageAppearance",
    };

    uint64_t candidates[] = { carrier, view };
    for (size_t i = 0; i < sizeof(candidates) / sizeof(candidates[0]); i++) {
        char localSource[96] = {0};
        uint64_t appearance = themer_spotlight_object_from_candidates(
            candidates[i],
            selectors, sizeof(selectors) / sizeof(selectors[0]),
            ivars, sizeof(ivars) / sizeof(ivars[0]),
            localSource, sizeof(localSource));
        if (!r_is_objc_ptr(appearance)) continue;
        if (source && sourceLen > 0) {
            snprintf(source, sourceLen, "%s.%s",
                     i == 0 ? "carrier" : "view",
                     localSource);
        }
        return appearance;
    }

    uint64_t appearanceClass = themer_lookup_class("SBHIconImageAppearance");
    static const char *fallbacks[] = {
        "lightAppearance",
        "defaultAppearance",
    };
    for (size_t i = 0; i < sizeof(fallbacks) / sizeof(fallbacks[0]); i++) {
        const char *selector = fallbacks[i];
        if (!r_is_objc_ptr(appearanceClass) ||
            !r_responds_main(appearanceClass, selector)) {
            continue;
        }
        uint64_t appearance = r_msg2_main(appearanceClass, selector, 0, 0, 0, 0);
        if (!r_is_objc_ptr(appearance)) continue;
        if (source && sourceLen > 0) snprintf(source, sourceLen, "class.%s", selector);
        return appearance;
    }
    return 0;
}

static uint64_t themer_spotlight_cached_image(uint64_t cache,
                                              uint64_t appIcon,
                                              const char **selectorOut)
{
    if (selectorOut) *selectorOut = NULL;
    if (!r_is_objc_ptr(cache) || !r_is_objc_ptr(appIcon)) return 0;
    static const char *selectors[] = {
        "cachedImageForIcon:",
        "imageForIcon:",
    };
    for (size_t i = 0; i < sizeof(selectors) / sizeof(selectors[0]); i++) {
        const char *selector = selectors[i];
        if (!r_responds_main(cache, selector)) continue;
        uint64_t image = r_msg2_main(cache, selector, appIcon, 0, 0, 0);
        if (selectorOut) *selectorOut = selector;
        if (r_is_objc_ptr(image)) return image;
    }
    return 0;
}

static bool themer_spotlight_images_match(uint64_t expected, uint64_t actual)
{
    if (!r_is_objc_ptr(expected) || !r_is_objc_ptr(actual)) return false;
    if (expected == actual || themer_spotlight_image_cg_matches(actual, expected)) {
        return true;
    }
    if (r_responds_main(actual, "isEqual:")) {
        return (r_msg2_main(actual, "isEqual:", expected, 0, 0, 0) & 1) != 0;
    }
    return false;
}

typedef struct {
    uint64_t object;
    char source[120];
} ThemerSpotlightCacheTarget;

typedef struct {
    int rootNativeMatches;
    int backingNativeMatches;
    int keyedMatches;
    int rootOptionedReads;
    int rootOptionedMatches;
    int rootRenderReads;
    int rootRenderMatches;
    int rootLegacyReads;
    int rootLegacyMatches;
    int backingReads;
    uint64_t rootOptionedImage;
    uint64_t rootRenderImage;
    uint64_t rootLegacyImage;
} ThemerSpotlightCacheVerification;

static bool themer_spotlight_add_cache_target(
    ThemerSpotlightCacheTarget *targets,
    int *count,
    int cap,
    uint64_t object,
    const char *source)
{
    if (!targets || !count || *count >= cap || !r_is_objc_ptr(object)) {
        return false;
    }
    for (int i = 0; i < *count; i++) {
        if (targets[i].object == object) return false;
    }
    targets[*count].object = object;
    snprintf(targets[*count].source,
             sizeof(targets[*count].source),
             "%s",
             source && source[0] ? source : "unknown");
    (*count)++;
    return true;
}

static void themer_spotlight_collect_hierarchy_object_ivars(
    uint64_t root,
    ThemerSpotlightCacheTarget *targets,
    int *count,
    int cap)
{
    if (!r_is_objc_ptr(root) || !targets || !count || *count >= cap) return;

    uint64_t cls = r_dlsym_call(R_TIMEOUT, "object_getClass",
                                root, 0, 0, 0, 0, 0, 0, 0);
    for (int depth = 0;
         r_is_objc_ptr(cls) && depth < 8 && *count < cap;
         depth++) {
        char className[96] = {0};
        themer_read_class_object_name(cls, className, sizeof(className));

        uint64_t countBuffer = r_dlsym_call(R_TIMEOUT, "malloc",
                                            8, 0, 0, 0, 0, 0, 0, 0);
        if (!countBuffer) break;
        remote_write64(countBuffer, 0);
        uint64_t ivars = r_dlsym_call(R_TIMEOUT, "class_copyIvarList",
                                      cls, countBuffer, 0, 0, 0, 0, 0, 0);
        uint32_t ivarCount = 0;
        remote_read(countBuffer, &ivarCount, sizeof(ivarCount));
        r_free(countBuffer);

        if (ivars && ivarCount > 0 && ivarCount <= 1024) {
            for (uint32_t i = 0; i < ivarCount && *count < cap; i++) {
                uint64_t ivar = remote_read64(
                    ivars + ((uint64_t)i * sizeof(uint64_t)));
                if (!ivar) continue;

                uint64_t nameCString = r_dlsym_call(R_TIMEOUT, "ivar_getName",
                                                    ivar, 0, 0, 0, 0, 0, 0, 0);
                uint64_t typeCString = r_dlsym_call(
                    R_TIMEOUT, "ivar_getTypeEncoding",
                    ivar, 0, 0, 0, 0, 0, 0, 0);
                uint64_t offset = r_dlsym_call(R_TIMEOUT, "ivar_getOffset",
                                               ivar, 0, 0, 0, 0, 0, 0, 0);
                char name[96] = {0};
                char type[96] = {0};
                (void)themer_read_remote_cstring(nameCString,
                                                 name, sizeof(name));
                (void)themer_read_remote_cstring(typeCString,
                                                 type, sizeof(type));
                const char *unqualifiedType = type;
                while (*unqualifiedType &&
                       strchr("rnNoORV", *unqualifiedType)) {
                    unqualifiedType++;
                }
                if (*unqualifiedType != '@') continue;

                uint64_t object = remote_read64(root + offset);
                char source[120] = {0};
                snprintf(source, sizeof(source),
                         "hierarchy:%s.%s@%llu",
                         className[0] ? className : "?",
                         name[0] ? name : "?",
                         (unsigned long long)offset);
                (void)themer_spotlight_add_cache_target(
                    targets, count, cap, object, source);
            }
        }
        if (ivars) r_free(ivars);
        cls = r_dlsym_call(R_TIMEOUT, "class_getSuperclass",
                           cls, 0, 0, 0, 0, 0, 0, 0);
    }
}

static int themer_spotlight_collect_cache_targets(
    uint64_t cache,
    ThemerSpotlightCacheTarget *targets,
    int cap)
{
    if (!r_is_objc_ptr(cache) || !targets || cap <= 0) return 0;
    int count = 0;
    (void)themer_spotlight_add_cache_target(targets, &count, cap,
                                            cache, "cache");

    static const char *selectors[] = {
        "images",
        "imageStore",
        "iconImageStore",
        "imageAppearanceStore",
        "appearanceStore",
        "variantCache",
        "imageCache",
        "cache",
    };
    for (size_t i = 0;
         i < sizeof(selectors) / sizeof(selectors[0]) && count < cap;
         i++) {
        const char *selector = selectors[i];
        if (!r_responds_main(cache, selector)) continue;
        uint64_t object = r_msg2_main(cache, selector, 0, 0, 0, 0);
        char source[72] = {0};
        snprintf(source, sizeof(source), "cache.sel:%s", selector);
        (void)themer_spotlight_add_cache_target(targets, &count, cap,
                                                object, source);
    }

    static const char *ivars[] = {
        "_images",
        "_imageStore",
        "_iconImageStore",
        "_imageAppearanceStore",
        "_appearanceStore",
        "_variantCache",
        "_imageCache",
        "_cache",
    };
    for (size_t i = 0;
         i < sizeof(ivars) / sizeof(ivars[0]) && count < cap;
         i++) {
        const char *ivar = ivars[i];
        uint64_t object = r_ivar_value(cache, ivar);
        char source[72] = {0};
        snprintf(source, sizeof(source), "cache.ivar:%s", ivar);
        (void)themer_spotlight_add_cache_target(targets, &count, cap,
                                                object, source);
    }
    themer_spotlight_collect_hierarchy_object_ivars(cache,
                                                    targets,
                                                    &count,
                                                    cap);

    // The root's object ivars reveal the masked/unmasked variant caches, but
    // the actual retained pixels live one level deeper in each variant's
    // SBHIconImageAppearanceStore. Expand only variant caches so this remains
    // bounded and never walks arbitrary collection/UI graphs.
    for (int i = 1; i < count && count < cap; i++) {
        char className[96] = {0};
        themer_read_class_name(targets[i].object,
                               className, sizeof(className));
        if (strstr(className, "SBHIconImageVariantCache") == NULL) {
            continue;
        }

        static const char *variantSelectors[] = {
            "images",
            "imageStore",
            "imageAppearanceStore",
            "appearanceStore",
        };
        for (size_t j = 0;
             j < sizeof(variantSelectors) / sizeof(variantSelectors[0]) &&
                 count < cap;
             j++) {
            const char *selector = variantSelectors[j];
            if (!r_responds_main(targets[i].object, selector)) continue;
            uint64_t object = r_msg2_main(targets[i].object, selector,
                                          0, 0, 0, 0);
            char source[120] = {0};
            snprintf(source, sizeof(source), "%s.sel:%s",
                     targets[i].source, selector);
            (void)themer_spotlight_add_cache_target(
                targets, &count, cap, object, source);
        }

        static const char *variantIvars[] = {
            "_images",
            "_imageStore",
            "_imageAppearanceStore",
            "_appearanceStore",
        };
        for (size_t j = 0;
             j < sizeof(variantIvars) / sizeof(variantIvars[0]) &&
                 count < cap;
             j++) {
            const char *ivar = variantIvars[j];
            uint64_t object = r_ivar_value(targets[i].object, ivar);
            char source[120] = {0};
            snprintf(source, sizeof(source), "%s.ivar:%s",
                     targets[i].source, ivar);
            (void)themer_spotlight_add_cache_target(
                targets, &count, cap, object, source);
        }
        themer_spotlight_collect_hierarchy_object_ivars(
            targets[i].object, targets, &count, cap);
    }
    return count;
}

static int themer_spotlight_compact_cache_targets(
    ThemerSpotlightCacheTarget *targets,
    int targetCount)
{
    if (!targets || targetCount <= 0) return 0;
    int compactCount = 1; // The root cache is always target zero.
    for (int i = 1; i < targetCount; i++) {
        char className[96] = {0};
        themer_read_class_name(targets[i].object,
                               className, sizeof(className));
        bool isVariant =
            strstr(className, "SBHIconImageVariantCache") != NULL;
        bool isImageAppearanceStore =
            strstr(className, "SBHIconImageAppearanceStore") != NULL &&
            strstr(targets[i].source, "storedImageGeneration") == NULL &&
            strstr(targets[i].source, "StoredImageGeneration") == NULL;
        if (!isVariant && !isImageAppearanceStore) {
            continue;
        }
        if (compactCount != i) targets[compactCount] = targets[i];
        compactCount++;
    }
    return compactCount;
}

static int themer_spotlight_seed_cache_targets(
    ThemerSpotlightCacheTarget *targets,
    int targetCount,
    uint64_t image,
    uint64_t appIcon,
    uint64_t appearance,
    uint64_t imageGeneration,
    bool verbose)
{
    if (!targets || targetCount <= 0 ||
        !r_is_objc_ptr(image) || !r_is_objc_ptr(appIcon)) {
        return 0;
    }

    int totalCalls = 0;
    for (int i = 0; i < targetCount; i++) {
        uint64_t target = targets[i].object;
        char className[96] = {0};
        themer_read_class_name(target, className, sizeof(className));
        int nativeCalls = 0;

        bool isRootCache = i == 0;
        bool isVariantCache = strstr(className, "SBHIconImageVariantCache") != NULL;
        bool isAppearanceStore =
            strstr(className, "SBHIconImageAppearanceStore") != NULL &&
            strstr(targets[i].source, "storedImageGeneration") == NULL &&
            strstr(targets[i].source, "StoredImageGeneration") == NULL;
        if (!isRootCache && !isVariantCache && !isAppearanceStore) {
            if (verbose) {
                printf("[SPOTLIGHT] single-probe cache-target index=%d source=%s "
                       "object=0x%llx class=%s skipped=non-image-cache\n",
                       i,
                       targets[i].source,
                       (unsigned long long)target,
                       className[0] ? className : "-");
            }
            continue;
        }

        if (isRootCache && r_is_objc_ptr(appearance) &&
            r_responds_main(target,
                            "cacheImage:forIcon:imageAppearance:")) {
            r_msg2_main(target, "cacheImage:forIcon:imageAppearance:",
                        image, appIcon, appearance, 0);
            nativeCalls++;
        }
        if (isVariantCache && r_is_objc_ptr(appearance) &&
            r_responds_main(target,
                "cacheImage:forIcon:imageAppearance:imageGeneration:")) {
            r_msg2_main(target,
                        "cacheImage:forIcon:imageAppearance:imageGeneration:",
                        image, appIcon, appearance, imageGeneration);
            nativeCalls++;
        }
        if (isAppearanceStore && r_is_objc_ptr(appearance) &&
            r_responds_main(target,
                            "setImage:forIcon:appearance:")) {
            r_msg2_main(target, "setImage:forIcon:appearance:",
                        image, appIcon, appearance, 0);
            nativeCalls++;
        }

        int calls = nativeCalls;
        totalCalls += calls;
        if (verbose) {
            printf("[SPOTLIGHT] single-probe cache-target index=%d source=%s "
                   "object=0x%llx class=%s nativeSeedCalls=%d "
                   "seedCalls=%d imageGeneration=%llu\n",
                   i,
                   targets[i].source,
                   (unsigned long long)target,
                   className[0] ? className : "-",
                   nativeCalls,
                   calls,
                   (unsigned long long)imageGeneration);
        }
    }
    return totalCalls;
}

static ThemerSpotlightCacheVerification themer_spotlight_verify_cache_targets(
    ThemerSpotlightCacheTarget *targets,
    int targetCount,
    uint64_t expected,
    uint64_t appIcon,
    uint64_t appearance,
    bool verbose)
{
    ThemerSpotlightCacheVerification result = {0};
    if (!targets || targetCount <= 0 ||
        !r_is_objc_ptr(expected) || !r_is_objc_ptr(appIcon)) {
        return result;
    }

    static const struct {
        const char *selector;
        int argumentCount;
        uint64_t options;
    } getters[] = {
        { "cachedImageForIcon:imageAppearance:options:", 3, 0 },
        { "cachedImageForIcon:imageAppearance:options:", 3, 4 },
        { "cachedImageForIcon:", 1, 0 },
        { "imageForIcon:", 1, 0 },
        { "imageForIcon:appearance:", 2, 0 },
        { "_variantImageForIcon:imageAppearance:extraImageOptions:options:", 4, 0 },
    };

    for (int i = 0; i < targetCount; i++) {
        uint64_t target = targets[i].object;
        char className[96] = {0};
        themer_read_class_name(target, className, sizeof(className));
        bool isRootCache = i == 0;
        bool isVariantCache = strstr(className, "SBHIconImageVariantCache") != NULL;
        bool isAppearanceStore =
            strstr(className, "SBHIconImageAppearanceStore") != NULL &&
            strstr(targets[i].source, "storedImageGeneration") == NULL &&
            strstr(targets[i].source, "StoredImageGeneration") == NULL;
        if (!isRootCache && !isVariantCache && !isAppearanceStore) continue;
        for (size_t j = 0; j < sizeof(getters) / sizeof(getters[0]); j++) {
            if (isRootCache &&
                getters[j].argumentCount != 1 &&
                getters[j].argumentCount != 3) {
                continue;
            }
            if (isVariantCache && getters[j].argumentCount != 4) continue;
            if (isAppearanceStore && getters[j].argumentCount != 2) continue;
            if (getters[j].argumentCount >= 2 &&
                !r_is_objc_ptr(appearance)) {
                continue;
            }
            const char *selector = getters[j].selector;
            if (!r_responds_main(target, selector)) continue;
            uint64_t image = 0;
            if (getters[j].argumentCount == 1) {
                image = r_msg2_main(target, selector, appIcon, 0, 0, 0);
            } else if (getters[j].argumentCount == 2) {
                image = r_msg2_main(target, selector,
                                    appIcon, appearance, 0, 0);
            } else if (getters[j].argumentCount == 3) {
                image = r_msg2_main(target, selector,
                                    appIcon, appearance,
                                    getters[j].options, 0);
            } else if (getters[j].argumentCount == 4) {
                image = r_msg2_main(target, selector,
                                    appIcon, appearance, 0,
                                    getters[j].options);
            }
            bool match = themer_spotlight_images_match(expected, image);
            if (i == 0) {
                if (getters[j].argumentCount == 3) {
                    if (getters[j].options & 4ULL) {
                        result.rootRenderReads++;
                        result.rootRenderImage = image;
                        if (match) result.rootRenderMatches++;
                    } else {
                        result.rootOptionedReads++;
                        result.rootOptionedImage = image;
                        if (match) result.rootOptionedMatches++;
                    }
                    if (match) result.keyedMatches++;
                } else {
                    result.rootLegacyReads++;
                    if (!r_is_objc_ptr(result.rootLegacyImage)) {
                        result.rootLegacyImage = image;
                    }
                    if (match) result.rootLegacyMatches++;
                }
                if (match) {
                    result.rootNativeMatches++;
                }
            } else {
                result.backingReads++;
                if (match) result.backingNativeMatches++;
            }
            if (verbose) {
                printf("[SPOTLIGHT] single-probe cache-read source=%s "
                       "selector=%s args=%d options=%llu image=0x%llx match=%d\n",
                       targets[i].source,
                       selector,
                       getters[j].argumentCount,
                       (unsigned long long)getters[j].options,
                       (unsigned long long)image,
                       match);
            }
        }

    }
    return result;
}

static int themer_spotlight_refresh_view_from_model(uint64_t view,
                                                     uint64_t cache,
                                                     uint64_t carrier,
                                                     uint64_t appIcon,
                                                     bool rebuildRowModel)
{
    if (!r_is_objc_ptr(view)) return 0;

    int calls = 0;
    if (rebuildRowModel) {
        uint64_t rowModel = r_responds_main(view, "rowModel")
            ? r_msg2_main(view, "rowModel", 0, 0, 0, 0)
            : 0;
        if (r_is_objc_ptr(rowModel) &&
            r_responds_main(view, "updateWithRowModel:")) {
            r_msg2_main(view, "updateWithRowModel:", rowModel, 0, 0, 0);
            calls++;
        } else if (r_is_objc_ptr(rowModel) &&
                   r_responds_main(view, "setRowModel:")) {
            r_msg2_main(view, "setRowModel:", rowModel, 0, 0, 0);
            calls++;
        }
    }

    if (!rebuildRowModel && r_is_objc_ptr(appIcon)) {
        if (r_is_objc_ptr(cache) &&
            r_responds_main(cache, "beginObservingIconIfNecessary:")) {
            r_msg2_main(cache, "beginObservingIconIfNecessary:",
                        appIcon, 0, 0, 0);
            calls++;
        }
        if (r_is_objc_ptr(carrier) &&
            r_responds_main(view,
                            "iconImageViewDidChangeContents:forIcon:")) {
            r_msg2_main(view,
                        "iconImageViewDidChangeContents:forIcon:",
                        carrier, appIcon, 0, 0);
            calls++;
        }
    }

    if (r_responds_main(view, "_updateIconImageViewAnimated:")) {
        r_msg2_main(view, "_updateIconImageViewAnimated:", 0, 0, 0, 0);
        calls++;
    } else if (r_responds_main(
                   view,
                   "_updateAfterManualIconImageInfoChangeInvalidatingLayout:")) {
        r_msg2_main(
            view,
            "_updateAfterManualIconImageInfoChangeInvalidatingLayout:",
            1, 0, 0, 0);
        calls++;
    }

    if (r_responds_main(view, "setNeedsLayout")) {
        r_msg2_main(view, "setNeedsLayout", 0, 0, 0, 0);
        calls++;
    }
    if (r_responds_main(view, "layoutIfNeeded")) {
        r_msg2_main(view, "layoutIfNeeded", 0, 0, 0, 0);
        calls++;
    }
    return calls;
}

static int themer_spotlight_model_association_matches(uint64_t appIcon,
                                                       uint64_t expected)
{
    if (!r_is_objc_ptr(appIcon) || !r_is_objc_ptr(expected)) return 0;

    static const char *selectors[] = {
        "makeIconImageWithInfo:traitCollection:context:options:",
        "iconImageWithInfo:traitCollection:context:options:",
        "iconImageWithInfo:traitCollection:options:",
        "iconImageWithInfo:",
    };
    int matches = 0;
    for (size_t i = 0; i < sizeof(selectors) / sizeof(selectors[0]); i++) {
        uint64_t sel = r_sel(selectors[i]);
        uint64_t associated = sel
            ? r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                           appIcon, sel, 0, 0, 0, 0, 0, 0)
            : 0;
        bool match = themer_spotlight_images_match(expected, associated);
        if (match) matches++;
        printf("[SPOTLIGHT] model-read selector=%s image=0x%llx match=%d\n",
               selectors[i],
               (unsigned long long)associated,
               match);
    }
    return matches;
}

static int themer_spotlight_push_visible_image(uint64_t view,
                                               uint64_t carrier,
                                               uint64_t image,
                                               uint64_t appearance)
{
    if (!r_is_objc_ptr(image)) return 0;
    int calls = 0;
    if (r_is_objc_ptr(carrier) && r_is_objc_ptr(appearance) &&
        r_responds_main(carrier,
            "updateImageContentsWithImage:imageAppearance:animated:")) {
        r_msg2_main(carrier,
                    "updateImageContentsWithImage:imageAppearance:animated:",
                    image, appearance, 0, 0);
        calls++;
    }
    if (r_is_objc_ptr(carrier) &&
        r_responds_main(carrier, "setDisplayedImage:")) {
        r_msg2_main(carrier, "setDisplayedImage:", image, 0, 0, 0);
        calls++;
    }
    if (r_is_objc_ptr(carrier) && r_responds_main(carrier, "setImage:")) {
        r_msg2_main(carrier, "setImage:", image, 0, 0, 0);
        calls++;
    } else if (r_is_objc_ptr(view) && r_responds_main(view, "setImage:")) {
        r_msg2_main(view, "setImage:", image, 0, 0, 0);
        calls++;
    }
    if (r_is_objc_ptr(view) && r_responds_main(view, "setNeedsLayout")) {
        r_msg2_main(view, "setNeedsLayout", 0, 0, 0, 0);
    }
    return calls;
}

typedef struct {
    char bundle[192];
    uint64_t image;
} ThemerSpotlightRemoteImage;

static uint64_t themer_spotlight_remote_image_for_bundle(
    NSDictionary<NSString *, NSData *> *dataByBundle,
    const char *bundle,
    ThemerSpotlightRemoteImage *images,
    int *imageCount,
    int imageCap)
{
    if (!dataByBundle || !bundle || !bundle[0] ||
        !images || !imageCount || imageCap <= 0) {
        return 0;
    }
    for (int i = 0; i < *imageCount; i++) {
        if (strcmp(images[i].bundle, bundle) == 0) return images[i].image;
    }
    if (*imageCount >= imageCap) return 0;

    NSString *key = [NSString stringWithUTF8String:bundle];
    NSString *matchedKey = nil;
    NSData *bytes = themer_theme_data_for_key(dataByBundle, key, &matchedKey);
    if (![bytes isKindOfClass:NSData.class] || bytes.length == 0) return 0;

    NSData *uploadBytes = themer_rounded_png_data(bytes, bundle);
    uint64_t image = themer_build_remote_uiimage_from_data(uploadBytes ?: bytes,
                                                            bundle);
    if (!r_is_objc_ptr(image)) return 0;

    ThemerSpotlightRemoteImage *entry = &images[*imageCount];
    snprintf(entry->bundle, sizeof(entry->bundle), "%s", bundle);
    entry->image = image;
    (*imageCount)++;
    printf("[SPOTLIGHT] image-upload bundle=%s matchedKey=%s image=0x%llx bytes=%lu\n",
           bundle,
           matchedKey.UTF8String ?: "-",
           (unsigned long long)image,
           (unsigned long)bytes.length);
    return image;
}

typedef struct {
    int visibleCandidates;
    int bundleCandidates;
    int themeCandidates;
    int patchedRows;
    int modelGrafted;
    int modelClassChanged;
    int modelAssociationMatches;
    int providerGrafted;
    int providerClassChanged;
    int providerAssociationMatches;
    int cacheSeedCalls;
    int viewRefreshCalls;
    int directCalls;
    int visibleMatches;
    int appIconReplaced;
    int focusSkips;
    int readyRows;
    int presentationAlphaPins;
    int presentationPinFailures;
    int processedSkips;
    int pointerConflicts;
} ThemerSpotlightLiveStats;

typedef struct {
    uint64_t view;
    uint64_t appIcon;
    uint64_t expectedCG;
    bool ready;
    char bundle[192];
} ThemerSpotlightProcessedRow;

static int themer_spotlight_processed_row_index(
    const ThemerSpotlightProcessedRow *rows,
    int rowCount,
    uint64_t view,
    uint64_t appIcon,
    const char *bundle,
    bool *conflictOut)
{
    if (conflictOut) *conflictOut = false;
    if (!rows || rowCount <= 0 || !r_is_objc_ptr(view) ||
        !r_is_objc_ptr(appIcon) || !bundle || !bundle[0]) {
        return -1;
    }
    for (int i = 0; i < rowCount; i++) {
        if (rows[i].view != view || rows[i].appIcon != appIcon) continue;
        if (strcmp(rows[i].bundle, bundle) == 0) return i;
        if (conflictOut) *conflictOut = true;
        return i;
    }
    return -1;
}

static bool themer_spotlight_view_is_live(uint64_t view)
{
    if (!r_is_objc_ptr(view)) return false;
    int hidden = themer_remote_hidden(view);
    double alpha = themer_remote_alpha(view);
    if (hidden == 1 || (alpha >= 0.0 && alpha < 0.01)) return false;

    if (r_responds_main(view, "window")) {
        uint64_t window = r_msg2_main(view, "window", 0, 0, 0, 0);
        if (!r_is_objc_ptr(window)) return false;
    }

    ThemerRect bounds = {0};
    if (themer_read_rect(view, "bounds", &bounds) &&
        (bounds.w < 8.0 || bounds.h < 8.0)) {
        return false;
    }
    return true;
}

static bool themer_spotlight_patch_live_view(
    uint64_t view,
    int index,
    int pass,
    NSDictionary<NSString *, NSData *> *normalized,
    ThemerSpotlightRemoteImage *images,
    int *imageCount,
    int imageCap,
    bool verbose,
    ThemerSpotlightLiveStats *stats)
{
    if (!themer_spotlight_view_is_live(view)) return false;
    if (stats) stats->visibleCandidates++;

    uint64_t appIcon = themer_spotlight_app_icon_for_view(view, NULL, 0);
    if (!r_is_objc_ptr(appIcon)) return false;

    bool rowPatched = false;
    bool rowReady = false;
    int rowPinCount = 0;
    bool countedBundle = false;
    bool countedTheme = false;
    for (int attempt = 0; attempt < 2; attempt++) {
        char bundle[192] = {0};
        char bundleSource[160] = {0};
        if (!themer_spotlight_bundle_for_patch(view, appIcon,
                                               bundle, sizeof(bundle),
                                               bundleSource,
                                               sizeof(bundleSource))) {
            break;
        }
        if (!countedBundle && stats) {
            stats->bundleCandidates++;
            countedBundle = true;
        }
        if (kThemerFocusBundle && kThemerFocusBundle[0] &&
            strcmp(bundle, kThemerFocusBundle) != 0) {
            if (stats) stats->focusSkips++;
            break;
        }

        uint64_t sourceImage = themer_spotlight_remote_image_for_bundle(
            normalized, bundle, images, imageCount, imageCap);
        if (!r_is_objc_ptr(sourceImage)) break;
        if (!countedTheme && stats) {
            stats->themeCandidates++;
            countedTheme = true;
        }

        uint64_t carrier = themer_spotlight_image_carrier_for_view(view);
        uint64_t stockImage = themer_spotlight_image_from_carrier(carrier);
        char cacheSource[128] = {0};
        uint64_t cache = themer_spotlight_find_icon_cache(
            view, carrier, appIcon,
            cacheSource, sizeof(cacheSource));
        const char *stockSelector = NULL;
        if (!r_is_objc_ptr(stockImage)) {
            stockImage = themer_spotlight_cached_image(cache,
                                                       appIcon,
                                                       &stockSelector);
        }

        double targetW = 0.0;
        double targetH = 0.0;
        double stockScale = 0.0;
        bool stockGeometry = themer_read_image_geometry(stockImage,
                                                        &targetW,
                                                        &targetH,
                                                        &stockScale);
        if (!stockGeometry) {
            ThemerRect carrierBounds = {0};
            if (themer_read_rect(carrier, "bounds", &carrierBounds) &&
                carrierBounds.w >= 8.0 && carrierBounds.w <= 180.0) {
                targetW = carrierBounds.w;
                targetH = carrierBounds.h;
            } else {
                targetW = 60.0;
                targetH = 60.0;
            }
            stockScale = themer_screen_scale();
        }

        uint64_t adjusted = themer_spotlight_provider_sized_themed_image(
            sourceImage, targetW, stockScale);
        uint64_t patchImage = r_is_objc_ptr(adjusted) ? adjusted : sourceImage;

        char appearanceSource[128] = {0};
        uint64_t appearance = themer_spotlight_image_appearance(
            view, carrier,
            appearanceSource, sizeof(appearanceSource));

        ThemerSpotlightCacheTarget cacheTargets[32] = {{0}};
        int cacheTargetCount = themer_spotlight_collect_cache_targets(
            cache, cacheTargets, 32);

        ThemerEntry spotlightModelEntry = {0};
        uint64_t provider = themer_spotlight_trace_object_value(
            appIcon, "activeDataSource", "_activeDataSource");
        bool providerClassChanged = false;
        int providerImageMatches = 0;
        int providerLayerMatches = 0;
        bool providerGrafted = false;
        if (kThemerSpotlightProviderGraftEnabled) {
            providerGrafted = themer_graft_spotlight_provider(
                provider, patchImage, targetW,
                &providerClassChanged,
                &providerImageMatches,
                &providerLayerMatches);
        }
        bool modelClassChanged = false;
        bool grafted = themer_graft_spotlight_icon_model(
            appIcon, patchImage, &spotlightModelEntry, view,
            &modelClassChanged);
        int associationMatches = 0;
        if (grafted && verbose) {
            associationMatches =
                themer_spotlight_model_association_matches(appIcon,
                                                           patchImage);
        }
        if (stats) {
            if (providerGrafted) stats->providerGrafted++;
            if (providerClassChanged) stats->providerClassChanged++;
            stats->providerAssociationMatches +=
                providerImageMatches + providerLayerMatches;
            if (grafted) stats->modelGrafted++;
            if (modelClassChanged) stats->modelClassChanged++;
            stats->modelAssociationMatches += associationMatches;
        }

        uint64_t imageGeneration =
            (r_is_objc_ptr(cache) &&
             r_responds_main(cache, "currentImageGenerationForIcon:"))
            ? r_msg2_main(cache, "currentImageGenerationForIcon:",
                          appIcon, 0, 0, 0)
            : 0;
        int seedCalls = themer_spotlight_seed_cache_targets(
            cacheTargets, cacheTargetCount,
            patchImage, appIcon, appearance,
            imageGeneration,
            verbose);
        if (stats) stats->cacheSeedCalls += seedCalls;

        int refreshCalls = themer_spotlight_refresh_view_from_model(
            view, cache, carrier, appIcon, false);
        if (stats) stats->viewRefreshCalls += refreshCalls;

        uint64_t refreshedCarrier =
            themer_spotlight_image_carrier_for_view(view);
        if (r_is_objc_ptr(refreshedCarrier)) carrier = refreshedCarrier;
        uint64_t visibleImage = themer_spotlight_image_from_carrier(carrier);
        bool visibleMatch = themer_spotlight_images_match(patchImage,
                                                          visibleImage);
        int directCalls = 0;
        if (!visibleMatch) {
            directCalls = themer_spotlight_push_visible_image(
                view, carrier, patchImage, appearance);
            if (stats) stats->directCalls += directCalls;
            refreshedCarrier = themer_spotlight_image_carrier_for_view(view);
            if (r_is_objc_ptr(refreshedCarrier)) carrier = refreshedCarrier;
            visibleImage = themer_spotlight_image_from_carrier(carrier);
            visibleMatch = themer_spotlight_images_match(patchImage,
                                                         visibleImage);
        }
        uint64_t currentAppIcon = themer_spotlight_app_icon_for_view(
            view, NULL, 0);
        char currentBundle[192] = {0};
        bool currentBundleKnown = r_is_objc_ptr(currentAppIcon) &&
            themer_spotlight_bundle_for_patch(
                view, currentAppIcon,
                currentBundle, sizeof(currentBundle),
                NULL, 0);
        bool identityStable = currentAppIcon == appIcon &&
            currentBundleKnown && strcmp(currentBundle, bundle) == 0;

        int pinCount = 0;
        uint64_t expectedCG =
            themer_spotlight_trace_image_cg(patchImage);
        if (visibleMatch && identityStable &&
            kThemerSpotlightPresentationAlphaPinEnabled &&
            themer_spotlight_view_is_live(view)) {
            pinCount = themer_spotlight_pin_ready_presentation_alpha(
                view, carrier, expectedCG, "all-rows");
            if (pinCount != 2 &&
                r_responds_main(
                    view, "iconImageViewDidChangeContents:forIcon:")) {
                r_msg2_main(view,
                            "iconImageViewDidChangeContents:forIcon:",
                            carrier, appIcon, 0, 0);
                usleep(250000);

                currentAppIcon = themer_spotlight_app_icon_for_view(
                    view, NULL, 0);
                memset(currentBundle, 0, sizeof(currentBundle));
                currentBundleKnown = r_is_objc_ptr(currentAppIcon) &&
                    themer_spotlight_bundle_for_patch(
                        view, currentAppIcon,
                        currentBundle, sizeof(currentBundle),
                        NULL, 0);
                identityStable = currentAppIcon == appIcon &&
                    currentBundleKnown &&
                    strcmp(currentBundle, bundle) == 0;
                if (identityStable &&
                    themer_spotlight_view_is_live(view)) {
                    refreshedCarrier =
                        themer_spotlight_image_carrier_for_view(view);
                    if (r_is_objc_ptr(refreshedCarrier)) {
                        carrier = refreshedCarrier;
                    }
                    visibleImage =
                        themer_spotlight_image_from_carrier(carrier);
                    visibleMatch = themer_spotlight_images_match(
                        patchImage, visibleImage);
                    if (visibleMatch) {
                        pinCount =
                            themer_spotlight_pin_ready_presentation_alpha(
                                view, carrier, expectedCG,
                                "all-rows-retry");
                    }
                }
            }
        }
        // The carrier's actual themed CGImage is the presentation contract.
        // Placeholder/layer readiness is useful diagnostics, but the log can
        // legitimately report layerCG=0 while displayedCG is already exact.
        bool ready = visibleMatch && identityStable;
        if (visibleMatch && stats) stats->visibleMatches++;
        rowReady = rowReady || ready;
        if (ready) rowPinCount = pinCount;

        rowPatched = rowPatched || providerGrafted || grafted || seedCalls > 0 ||
                     directCalls > 0 || visibleMatch;

        if (verbose || attempt > 0) {
            char viewClass[96] = {0};
            char iconClass[96] = {0};
            char carrierClass[96] = {0};
            char cacheClass[96] = {0};
            themer_read_class_name(view, viewClass, sizeof(viewClass));
            themer_read_class_name(appIcon, iconClass, sizeof(iconClass));
            themer_read_class_name(carrier, carrierClass, sizeof(carrierClass));
            themer_read_class_name(cache, cacheClass, sizeof(cacheClass));
            printf("[SPOTLIGHT] live-row pass=%d index=%d attempt=%d "
                   "bundle=%s bundleSource=%s view=0x%llx/%s "
                   "appIcon=0x%llx/%s carrier=0x%llx/%s cache=0x%llx/%s "
                   "cacheSource=%s appearance=0x%llx/%s "
                   "stock=0x%llx/%s stockGeom=%d target=%.1fx%.1f@%.2f "
                   "patch=0x%llx provider=0x%llx providerGraft=%d "
                   "providerAssoc=%d/%d graft=%d classChanged=%d assoc=%d "
                   "cacheTargets=%d seedCalls=%d refreshCalls=%d "
                   "directCalls=%d visible=0x%llx visibleMatch=%d "
                   "identityStable=%d pins=%d ready=%d\n",
                   pass,
                   index,
                   attempt,
                   bundle,
                   bundleSource[0] ? bundleSource : "-",
                   (unsigned long long)view,
                   viewClass[0] ? viewClass : "-",
                   (unsigned long long)appIcon,
                   iconClass[0] ? iconClass : "-",
                   (unsigned long long)carrier,
                   carrierClass[0] ? carrierClass : "-",
                   (unsigned long long)cache,
                   cacheClass[0] ? cacheClass : "-",
                   cacheSource[0] ? cacheSource : "-",
                   (unsigned long long)appearance,
                   appearanceSource[0] ? appearanceSource : "-",
                   (unsigned long long)stockImage,
                   stockSelector ?: "carrier",
                   stockGeometry,
                   targetW,
                   targetH,
                   stockScale,
                   (unsigned long long)patchImage,
                   (unsigned long long)provider,
                   providerGrafted,
                   providerImageMatches,
                   providerLayerMatches,
                   grafted,
                   modelClassChanged,
                   associationMatches,
                   cacheTargetCount,
                   seedCalls,
                   refreshCalls,
                   directCalls,
                   (unsigned long long)visibleImage,
                   visibleMatch,
                   identityStable,
                   pinCount,
                   ready);
        } else if (rowPatched) {
            printf("[SPOTLIGHT] live-row pass=%d index=%d attempt=%d "
                   "bundle=%s view=0x%llx appIcon=0x%llx "
                   "seedCalls=%d refreshCalls=%d directCalls=%d "
                   "visibleMatch=%d identityStable=%d providerGraft=%d "
                   "pins=%d ready=%d\n",
                   pass,
                   index,
                   attempt,
                   bundle,
                   (unsigned long long)view,
                   (unsigned long long)appIcon,
                   seedCalls,
                   refreshCalls,
                   directCalls,
                   visibleMatch,
                   identityStable,
                   providerGrafted,
                   pinCount,
                   ready);
        }

        if (r_is_objc_ptr(adjusted)) {
            r_msg2(adjusted, "release", 0, 0, 0, 0);
        }

        uint64_t nextAppIcon = themer_spotlight_app_icon_for_view(view,
                                                                  NULL, 0);
        if (attempt == 0 &&
            r_is_objc_ptr(nextAppIcon) &&
            nextAppIcon != appIcon) {
            if (stats) stats->appIconReplaced++;
            rowReady = false;
            rowPinCount = 0;
            appIcon = nextAppIcon;
            continue;
        }
        break;
    }

    if (stats) {
        if (rowPatched) stats->patchedRows++;
        if (rowReady) stats->readyRows++;
        stats->presentationAlphaPins += rowPinCount;
        if (rowPatched && !rowReady) stats->presentationPinFailures++;
    }
    return rowReady;
}

static bool themer_apply_spotlight_data_live_in_session(
    NSDictionary<NSString *, NSData *> *imageDataByBundle)
{
    uint64_t totalStartUS = themer_now_us();
    NSDictionary<NSString *, NSData *> *normalized =
        themer_normalized_theme_data(imageDataByBundle);
    if (normalized.count == 0) {
        printf("[SPOTLIGHT] live-cache skipped reason=empty-theme\n");
        return false;
    }

    uint32_t previousSettleUS = r_settle_us(5000);
    enum {
        VIEW_CAP = 64,
        IMAGE_CAP = 64,
        PROCESSED_CAP = 128,
        MAX_PASSES = 2,
    };
    ThemerSpotlightRemoteImage images[IMAGE_CAP] = {{0}};
    ThemerSpotlightProcessedRow processed[PROCESSED_CAP] = {{0}};
    int imageCount = 0;
    int processedCount = 0;
    ThemerSpotlightLiveStats stats = {0};
    int passes = 0;
    int rowsSeen = 0;
    int rowsPatchedLastPass = 0;
    int rowsReadyLastPass = 0;

    printf("[SPOTLIGHT] live-cache begin pid=%d entries=%lu maxPasses=%d\n",
           remote_call_current_pid(),
           (unsigned long)normalized.count,
           MAX_PASSES);

    do {
        uint64_t views[VIEW_CAP] = {0};
        uint64_t passStartUS = themer_now_us();
        int viewCount = themer_spotlight_collect_searchui_views(views,
                                                                VIEW_CAP);
        rowsSeen += viewCount;
        int patchedBefore = stats.patchedRows;
        int readyBefore = stats.readyRows;
        int themeBefore = stats.themeCandidates;

        for (int i = 0; i < viewCount; i++) {
            if (!remote_call_current_success()) break;

            uint64_t view = views[i];
            uint64_t beforeIcon =
                themer_spotlight_app_icon_for_view(view, NULL, 0);
            char beforeBundle[192] = {0};
            bool beforeBundleKnown = r_is_objc_ptr(beforeIcon) &&
                themer_spotlight_bundle_for_patch(
                    view, beforeIcon,
                    beforeBundle, sizeof(beforeBundle),
                    NULL, 0);
            bool pointerConflict = false;
            int processedIndex = beforeBundleKnown
                ? themer_spotlight_processed_row_index(
                      processed, processedCount,
                      view, beforeIcon, beforeBundle,
                      &pointerConflict)
                : -1;
            if (processedIndex >= 0) {
                if (pointerConflict) {
                    stats.pointerConflicts++;
                    printf("[SPOTLIGHT] live-row skipped reason=pointer-conflict "
                           "view=0x%llx icon=0x%llx priorBundle=%s "
                           "currentBundle=%s\n",
                           (unsigned long long)view,
                           (unsigned long long)beforeIcon,
                           processed[processedIndex].bundle,
                           beforeBundle);
                    continue;
                }

                ThemerSpotlightProcessedRow *known =
                    &processed[processedIndex];
                if (known->ready && known->expectedCG) {
                    uint64_t currentCarrier =
                        themer_spotlight_image_carrier_for_view(view);
                    int revalidatedPins =
                        themer_spotlight_pin_ready_presentation_alpha(
                            view, currentCarrier, known->expectedCG,
                            "all-rows-revalidate");
                    uint64_t currentImage =
                        themer_spotlight_image_from_carrier(currentCarrier);
                    uint64_t currentCG =
                        themer_spotlight_trace_image_cg(currentImage);
                    if (revalidatedPins == 2 ||
                        currentCG == known->expectedCG) {
                        stats.processedSkips++;
                        continue;
                    }
                    known->ready = false;
                    printf("[SPOTLIGHT] live-row revalidate-miss "
                           "view=0x%llx icon=0x%llx bundle=%s "
                           "expectedCG=0x%llx pins=%d\n",
                           (unsigned long long)view,
                           (unsigned long long)beforeIcon,
                           beforeBundle,
                           (unsigned long long)known->expectedCG,
                           revalidatedPins);
                }
            } else if (beforeBundleKnown &&
                       processedCount < PROCESSED_CAP) {
                NSString *beforeKey =
                    [NSString stringWithUTF8String:beforeBundle];
                NSData *beforeTheme = themer_theme_data_for_key(
                    normalized, beforeKey, NULL);
                if (![beforeTheme isKindOfClass:NSData.class] ||
                    beforeTheme.length == 0) {
                    continue;
                }
                processedIndex = processedCount++;
                ThemerSpotlightProcessedRow *record =
                    &processed[processedIndex];
                record->view = view;
                record->appIcon = beforeIcon;
                snprintf(record->bundle, sizeof(record->bundle), "%s",
                         beforeBundle);
            }

            bool verbose = false;
            uint64_t rowPool =
                themer_spotlight_remote_autorelease_pool_push();
            bool ready = themer_spotlight_patch_live_view(
                view,
                i,
                passes,
                normalized,
                images,
                &imageCount,
                IMAGE_CAP,
                verbose,
                &stats);
            if (rowPool) {
                themer_spotlight_remote_autorelease_pool_pop(rowPool);
            }
            printf("[SPOTLIGHT_FAST] autorelease-scope phase=all-live-row "
                   "pass=%d index=%d token=0x%llx ready=%d success=%d\n",
                   passes,
                   i,
                   (unsigned long long)rowPool,
                   ready,
                   remote_call_current_success());
            if (!ready || processedIndex < 0) continue;

            uint64_t finalIcon =
                themer_spotlight_app_icon_for_view(view, NULL, 0);
            char finalBundle[192] = {0};
            bool finalBundleKnown = r_is_objc_ptr(finalIcon) &&
                themer_spotlight_bundle_for_patch(
                    view, finalIcon,
                    finalBundle, sizeof(finalBundle),
                    NULL, 0);
            if (!finalBundleKnown) continue;
            if (beforeBundleKnown && strcmp(beforeBundle, finalBundle) != 0) {
                stats.pointerConflicts++;
                processed[processedIndex].ready = false;
                printf("[SPOTLIGHT] live-row not-recorded reason=bundle-reused "
                       "view=0x%llx icon=0x%llx before=%s after=%s\n",
                       (unsigned long long)view,
                       (unsigned long long)finalIcon,
                       beforeBundle,
                       finalBundle);
                continue;
            }
            ThemerSpotlightProcessedRow *record =
                &processed[processedIndex];
            record->view = view;
            record->appIcon = finalIcon;
            uint64_t finalCarrier =
                themer_spotlight_image_carrier_for_view(view);
            uint64_t finalImage =
                themer_spotlight_image_from_carrier(finalCarrier);
            uint64_t finalCG =
                themer_spotlight_trace_image_cg(finalImage);
            uint64_t themedExpectedCG = 0;
            for (int imageIndex = 0;
                 imageIndex < imageCount;
                 imageIndex++) {
                if (strcmp(images[imageIndex].bundle, finalBundle) != 0) {
                    continue;
                }
                themedExpectedCG = themer_spotlight_trace_image_cg(
                    images[imageIndex].image);
                break;
            }
            record->expectedCG = themedExpectedCG;
            record->ready = themedExpectedCG != 0 &&
                finalCG == themedExpectedCG;
            snprintf(record->bundle, sizeof(record->bundle), "%s",
                     finalBundle);
        }

        rowsPatchedLastPass = stats.patchedRows - patchedBefore;
        rowsReadyLastPass = stats.readyRows - readyBefore;
        int themeHitsThisPass = stats.themeCandidates - themeBefore;
        uint64_t passEndUS = themer_now_us();
        printf("[SPOTLIGHT] live-pass index=%d views=%d themeHits=%d "
               "patched=%d ready=%d totalPatched=%d totalReady=%d "
               "processed=%d elapsed=%llums\n",
               passes,
               viewCount,
               themeHitsThisPass,
               rowsPatchedLastPass,
               rowsReadyLastPass,
               stats.patchedRows,
               stats.readyRows,
               processedCount,
               (unsigned long long)((passEndUS - passStartUS) / 1000ULL));

        passes++;
        if (!remote_call_current_success() || passes >= MAX_PASSES) break;
        usleep(250000);
    } while (passes < MAX_PASSES);

    for (int i = 0; i < imageCount; i++) {
        if (r_is_objc_ptr(images[i].image)) {
            r_msg2(images[i].image, "release", 0, 0, 0, 0);
        }
    }

    uint64_t totalEndUS = themer_now_us();
    int readyRecordCount = 0;
    for (int i = 0; i < processedCount; i++) {
        if (processed[i].ready) readyRecordCount++;
    }
    bool success = processedCount > 0 &&
        readyRecordCount == processedCount &&
        stats.pointerConflicts == 0 &&
        remote_call_current_success();
    printf("[SPOTLIGHT] live-cache complete success=%d passes=%d rowsSeen=%d "
           "uploads=%d visible=%d bundles=%d themeHits=%d patchedRows=%d "
           "readyRows=%d pins=%d pinFailures=%d processed=%d "
           "recordsReady=%d skips=%d "
           "pointerConflicts=%d "
           "providerGrafted=%d providerClassChanged=%d providerAssoc=%d "
           "modelGrafted=%d classChanged=%d assoc=%d cacheSeedCalls=%d "
           "viewRefreshCalls=%d directCalls=%d visibleMatches=%d "
           "appIconReplaced=%d focusSkips=%d lastPassPatched=%d "
           "lastPassReady=%d total=%llums\n",
           success,
           passes,
           rowsSeen,
           imageCount,
           stats.visibleCandidates,
           stats.bundleCandidates,
           stats.themeCandidates,
           stats.patchedRows,
           stats.readyRows,
           stats.presentationAlphaPins,
           stats.presentationPinFailures,
           processedCount,
           readyRecordCount,
           stats.processedSkips,
           stats.pointerConflicts,
           stats.providerGrafted,
           stats.providerClassChanged,
           stats.providerAssociationMatches,
           stats.modelGrafted,
           stats.modelClassChanged,
           stats.modelAssociationMatches,
           stats.cacheSeedCalls,
           stats.viewRefreshCalls,
           stats.directCalls,
           stats.visibleMatches,
           stats.appIconReplaced,
           stats.focusSkips,
           rowsPatchedLastPass,
           rowsReadyLastPass,
           (unsigned long long)((totalEndUS - totalStartUS) / 1000ULL));

    r_settle_us(previousSettleUS);
    return success;
}

int themer_spotlight_visible_view_count_in_session(void)
{
    enum { VIEW_CAP = 64 };
    uint64_t views[VIEW_CAP] = {0};
    return themer_spotlight_collect_searchui_views(views, VIEW_CAP);
}

