typedef struct {
    uint64_t objects[192];
    int count;
} ThemerSpotlightTraceLifetime;

static ThemerSpotlightLifecycleTrace gThemerSpotlightLifecycleTrace = {0};

static bool themer_spotlight_trace_hold(ThemerSpotlightTraceLifetime *lifetime,
                                        uint64_t object)
{
    if (!lifetime || !r_is_objc_ptr(object)) return false;
    for (int i = 0; i < lifetime->count; i++) {
        if (lifetime->objects[i] == object) return true;
    }
    if (lifetime->count >= (int)(sizeof(lifetime->objects) /
                                 sizeof(lifetime->objects[0]))) {
        return false;
    }
    // NSObject reference counting is thread-safe and does not touch UIKit
    // state. A direct retain avoids constructing a main-thread NSInvocation
    // for every transient identity we pin during a snapshot.
    uint64_t retained = r_msg2(object, "retain", 0, 0, 0, 0);
    if (!r_is_objc_ptr(retained)) return false;
    lifetime->objects[lifetime->count++] = object;
    return true;
}

static void themer_spotlight_trace_release_all(
    ThemerSpotlightTraceLifetime *lifetime)
{
    if (!lifetime) return;
    for (int i = lifetime->count - 1; i >= 0; i--) {
        uint64_t object = lifetime->objects[i];
        if (r_is_objc_ptr(object) && remote_call_current_success()) {
            r_msg2(object, "release", 0, 0, 0, 0);
        }
        lifetime->objects[i] = 0;
    }
    lifetime->count = 0;
}

static uint64_t themer_spotlight_trace_object_value(uint64_t object,
                                                    const char *selector,
                                                    const char *ivar)
{
    if (!r_is_objc_ptr(object)) return 0;
    if (selector && selector[0] && r_responds_main(object, selector)) {
        uint64_t value = r_msg2_main(object, selector, 0, 0, 0, 0);
        if (r_is_objc_ptr(value)) return value;
    }
    uint64_t value = ivar && ivar[0] ? r_ivar_value(object, ivar) : 0;
    return r_is_objc_ptr(value) ? value : 0;
}

static bool themer_spotlight_trace_variant_for_view(uint64_t view,
                                                    uint64_t *variantOut)
{
    if (variantOut) *variantOut = 0;
    if (!r_is_objc_ptr(view)) return false;

    static const char *selectors[] = {
        "variant",
        "iconImageVariant",
    };
    for (size_t i = 0; i < sizeof(selectors) / sizeof(selectors[0]); i++) {
        const char *selector = selectors[i];
        if (!r_responds_main(view, selector)) continue;
        uint64_t variant = r_msg2_main(view, selector, 0, 0, 0, 0);
        if (variantOut) *variantOut = variant;
        return true;
    }
    return false;
}

static uint64_t themer_spotlight_trace_image_cg(uint64_t image)
{
    if (!r_is_objc_ptr(image) || !r_responds_main(image, "CGImage")) return 0;
    return r_msg2_main(image, "CGImage", 0, 0, 0, 0);
}

static int themer_spotlight_trace_bool_value(uint64_t object,
                                             const char *selector)
{
    if (!r_is_objc_ptr(object) || !selector || !selector[0] ||
        !r_responds_main(object, selector)) {
        return -1;
    }
    return (r_msg2_main(object, selector, 0, 0, 0, 0) & 1) ? 1 : 0;
}

static uint64_t themer_spotlight_trace_layer_contents(uint64_t layer)
{
    if (!r_is_objc_ptr(layer) || !r_responds_main(layer, "contents")) {
        return 0;
    }
    // CALayer.contents is commonly a CGImageRef. It is intentionally kept as
    // an opaque identity instead of requiring it to pass an ObjC-pointer test.
    return r_msg2_main(layer, "contents", 0, 0, 0, 0);
}

static uint64_t themer_spotlight_trace_cached_image_with_options(
    uint64_t cache,
    uint64_t icon,
    uint64_t appearance,
    uint64_t options,
    bool *supportedOut)
{
    static const char *selector =
        "cachedImageForIcon:imageAppearance:options:";
    if (supportedOut) *supportedOut = false;
    if (!r_is_objc_ptr(cache) || !r_is_objc_ptr(icon) ||
        !r_is_objc_ptr(appearance) || !r_responds_main(cache, selector)) {
        return 0;
    }
    if (supportedOut) *supportedOut = true;
    return r_msg2_main(cache, selector, icon, appearance, options, 0);
}

static uint64_t themer_spotlight_trace_cached_image_only(
    uint64_t cache,
    uint64_t icon)
{
    static const char *selector = "cachedImageForIcon:";
    if (!r_is_objc_ptr(cache) || !r_is_objc_ptr(icon) ||
        !r_responds_main(cache, selector)) {
        return 0;
    }
    return r_msg2_main(cache, selector, icon, 0, 0, 0);
}

static uint64_t themer_spotlight_trace_stored_model_icon(uint64_t iconModel,
                                                        const char *bundle,
                                                        uint64_t *storageOut,
                                                        int *sourceOut)
{
    if (storageOut) *storageOut = 0;
    if (sourceOut) *sourceOut = 0;
    if (!r_is_objc_ptr(iconModel) || !bundle || !bundle[0]) {
        return 0;
    }

    // The repository and leaf lookup are read-only on the iOS 26 path. Avoid
    // SearchUIHomeScreenModel's app-icon wrapper, which begins provider
    // tracking before it asks the model for an icon.
    uint64_t storage = r_ivar_value(iconModel, "iconRepository");
    if (!r_is_objc_ptr(storage)) {
        storage = r_ivar_value(iconModel, "_iconRepository");
    }
    if (!r_is_objc_ptr(storage) &&
        r_responds_main(iconModel, "iconRepository")) {
        storage = r_msg2_main(iconModel, "iconRepository", 0, 0, 0, 0);
    }
    if (storageOut && r_is_objc_ptr(storage)) *storageOut = storage;

    uint64_t identifier = r_nsstr_retained(bundle);
    if (!r_is_objc_ptr(identifier)) return 0;
    uint64_t icon = 0;
    if (r_responds_main(iconModel, "leafIconForIdentifier:")) {
        uint64_t leaf = r_msg2_main(iconModel, "leafIconForIdentifier:",
                                    identifier, 0, 0, 0);
        if (themer_spotlight_object_is_application_icon(leaf)) {
            icon = leaf;
            if (sourceOut) *sourceOut = 2;
        }
    }
    if (!r_is_objc_ptr(icon) && r_is_objc_ptr(storage) &&
        r_responds_main(storage, "iconForIdentifier:")) {
        uint64_t stored = r_msg2_main(storage, "iconForIdentifier:",
                                      identifier, 0, 0, 0);
        if (themer_spotlight_object_is_application_icon(stored)) {
            icon = stored;
            if (sourceOut) *sourceOut = 3;
        }
    }
    r_msg2(identifier, "release", 0, 0, 0, 0);
    return icon;
}

static uint64_t themer_spotlight_provider_for_identifier(
    uint64_t dataSource,
    uint64_t identifier)
{
    if (!r_is_objc_ptr(dataSource) || !r_is_objc_ptr(identifier)) return 0;
    uint64_t applications = r_ivar_value(dataSource, "_applications");
    uint64_t provider = r_is_objc_ptr(applications) &&
                        r_responds_main(applications, "objectForKey:")
        ? r_msg2_main(applications, "objectForKey:",
                      identifier, 0, 0, 0)
        : 0;
    if (!r_is_objc_ptr(provider) &&
        r_responds_main(dataSource, "applicationWithBundleIdentifier:")) {
        provider = r_msg2_main(dataSource,
                               "applicationWithBundleIdentifier:",
                               identifier, 0, 0, 0);
    }
    return r_is_objc_ptr(provider) ? provider : 0;
}

static bool themer_spotlight_validate_provider_icon(
    uint64_t dataSource,
    uint64_t identifier,
    const char *bundle,
    uint64_t icon,
    uint64_t *providerOut)
{
    if (providerOut) *providerOut = 0;
    if (!r_is_objc_ptr(icon) || !bundle || !bundle[0]) return false;

    char actualBundle[192] = {0};
    if (!themer_read_bundle_for_icon(icon, 0,
                                     actualBundle,
                                     sizeof(actualBundle)) ||
        strcmp(actualBundle, bundle) != 0) {
        return false;
    }
    uint64_t provider = themer_spotlight_provider_for_identifier(
        dataSource, identifier);
    uint64_t activeDataSource = themer_spotlight_trace_object_value(
        icon, "activeDataSource", "_activeDataSource");
    if (!r_is_objc_ptr(provider) || activeDataSource != provider) {
        return false;
    }
    if (providerOut) *providerOut = provider;
    return true;
}

static uint64_t themer_spotlight_materialize_provider_icon(
    uint64_t owner,
    uint64_t dataSource,
    const char *bundle,
    uint64_t *providerApplicationOut,
    const char **selectorOut)
{
    if (providerApplicationOut) *providerApplicationOut = 0;
    if (selectorOut) *selectorOut = NULL;
    if (!r_is_objc_ptr(owner) || !r_is_objc_ptr(dataSource) ||
        !bundle || !bundle[0]) {
        return 0;
    }

    uint64_t identifier = r_nsstr_retained(bundle);
    if (!r_is_objc_ptr(identifier)) return 0;
    uint64_t acceptedIcon = 0;
    uint64_t acceptedProvider = 0;
    const char *acceptedSelector = NULL;
    static const char *wrapperSelector =
        "appIconForApplicationBundleIdentifier:";
    if (r_responds_main(owner, wrapperSelector) &&
        themer_spotlight_object_selector_returns_object(owner,
                                                        wrapperSelector)) {
        uint64_t wrapperResult = r_msg2_main(owner, wrapperSelector,
                                             identifier, 0, 0, 0);
        uint64_t icon = themer_spotlight_application_icon_from_object(
            wrapperResult, NULL, 0);
        uint64_t provider = 0;
        if (themer_spotlight_validate_provider_icon(
                dataSource, identifier, bundle, icon, &provider)) {
            acceptedIcon = icon;
            acceptedProvider = provider;
            acceptedSelector = wrapperSelector;
        }
    }

    // Exact fallback for builds where the wrapper is absent or returned before
    // the selected datasource settled. Keep the temporary NSArray retained
    // across the separate main-thread RemoteCall invocations.
    if (!r_is_objc_ptr(acceptedIcon) && remote_call_current_success()) {
        uint64_t arrayClass = r_class("NSMutableArray");
        uint64_t arrayAlloc = r_is_objc_ptr(arrayClass)
            ? r_msg2(arrayClass, "alloc", 0, 0, 0, 0) : 0;
        uint64_t identifiers = r_is_objc_ptr(arrayAlloc)
            ? r_msg2_main(arrayAlloc, "initWithCapacity:", 1, 0, 0, 0)
            : 0;
        if (r_is_objc_ptr(identifiers) &&
            r_responds_main(identifiers, "addObject:")) {
            r_msg2_main(identifiers, "addObject:", identifier, 0, 0, 0);
        }
        static const char *trackingSelector =
            "beginTrackingApplicationsWithBundleIdentifiers:";
        bool trackingCalled = r_is_objc_ptr(identifiers) &&
            r_responds_main(dataSource, trackingSelector);
        if (trackingCalled) {
            r_msg2_main(dataSource, trackingSelector,
                        identifiers, 0, 0, 0);
        }
        if (r_is_objc_ptr(identifiers)) {
            r_msg2(identifiers, "release", 0, 0, 0, 0);
        }

        uint64_t iconModel = themer_spotlight_trace_object_value(
            owner, "iconModel", "_iconModel");
        static const char *modelSelector =
            "applicationIconForBundleIdentifier:";
        if (trackingCalled && r_is_objc_ptr(iconModel) &&
            r_responds_main(iconModel, modelSelector) &&
            themer_spotlight_object_selector_returns_object(
                iconModel, modelSelector)) {
            uint64_t wrapperResult = r_msg2_main(
                iconModel, modelSelector, identifier, 0, 0, 0);
            uint64_t icon = themer_spotlight_application_icon_from_object(
                wrapperResult, NULL, 0);
            uint64_t provider = 0;
            if (themer_spotlight_validate_provider_icon(
                    dataSource, identifier, bundle, icon, &provider)) {
                acceptedIcon = icon;
                acceptedProvider = provider;
                acceptedSelector =
                    "track-array/model:applicationIconForBundleIdentifier:";
            }
        }
    }
    r_msg2(identifier, "release", 0, 0, 0, 0);
    if (providerApplicationOut) *providerApplicationOut = acceptedProvider;
    if (selectorOut) *selectorOut = acceptedSelector;
    return acceptedIcon;
}

static uint64_t themer_spotlight_trace_existing_cache_for_object(
    uint64_t object)
{
    static const char *ivars[] = {
        "_iconImageCache",
        "_imageCache",
        "_cache",
    };
    static const char *selectors[] = {
        "iconImageCache",
        "imageCache",
    };
    if (!r_is_objc_ptr(object)) return 0;
    for (size_t i = 0; i < sizeof(ivars) / sizeof(ivars[0]); i++) {
        uint64_t cache = r_ivar_value(object, ivars[i]);
        if (themer_spotlight_object_looks_like_icon_cache(cache)) {
            return cache;
        }
    }
    for (size_t i = 0; i < sizeof(selectors) / sizeof(selectors[0]); i++) {
        if (!r_responds_main(object, selectors[i])) continue;
        uint64_t cache = r_msg2_main(object, selectors[i], 0, 0, 0, 0);
        if (themer_spotlight_object_looks_like_icon_cache(cache)) {
            return cache;
        }
    }
    return 0;
}

static uint64_t themer_spotlight_trace_existing_cache(uint64_t view,
                                                      uint64_t carrier,
                                                      uint64_t viewIcon)
{
    uint64_t objects[] = { view, carrier, viewIcon };
    for (size_t i = 0; i < sizeof(objects) / sizeof(objects[0]); i++) {
        uint64_t cache =
            themer_spotlight_trace_existing_cache_for_object(objects[i]);
        if (r_is_objc_ptr(cache)) return cache;
    }
    return 0;
}

static uint64_t themer_spotlight_trace_existing_appearance(uint64_t view,
                                                           uint64_t carrier)
{
    // Cache lookup follows the desired/effective appearance. A freshly
    // recreated carrier can have no displayed appearance yet, so treating the
    // displayed value as the key would manufacture an apparent cache miss.
    static const struct {
        int objectIndex;
        const char *selector;
    } getters[] = {
        { 0, "effectiveIconImageAppearance" },
        { 1, "effectiveIconImageAppearance" },
        { 0, "displayedImageAppearance" },
    };
    uint64_t objects[] = { carrier, view };
    for (size_t i = 0; i < sizeof(getters) / sizeof(getters[0]); i++) {
        uint64_t object = objects[getters[i].objectIndex];
        if (!r_is_objc_ptr(object) ||
            !r_responds_main(object, getters[i].selector)) {
            continue;
        }
        uint64_t appearance = r_msg2_main(object, getters[i].selector,
                                          0, 0, 0, 0);
        if (r_is_objc_ptr(appearance)) return appearance;
    }
    uint64_t override = r_is_objc_ptr(view)
        ? r_ivar_value(view, "_overrideIconImageAppearance") : 0;
    return r_is_objc_ptr(override) ? override : 0;
}

static bool themer_spotlight_trace_view_is_live(
    uint64_t view,
    uint64_t *windowOut,
    int *windowHiddenOut,
    double *windowAlphaOut,
    uint64_t *sceneOut,
    int64_t *sceneActivationStateOut,
    bool *sceneActivationStateKnownOut)
{
    if (windowOut) *windowOut = 0;
    if (windowHiddenOut) *windowHiddenOut = -1;
    if (windowAlphaOut) *windowAlphaOut = -1.0;
    if (sceneOut) *sceneOut = 0;
    if (sceneActivationStateOut) *sceneActivationStateOut = -99;
    if (sceneActivationStateKnownOut) *sceneActivationStateKnownOut = false;
    if (!themer_spotlight_view_is_live(view)) return false;

    uint64_t window = r_responds_main(view, "window")
        ? r_msg2_main(view, "window", 0, 0, 0, 0) : 0;
    if (windowOut) *windowOut = window;
    if (!r_is_objc_ptr(window)) return false;

    int windowHidden = themer_remote_hidden(window);
    double windowAlpha = themer_remote_alpha(window);
    if (windowHiddenOut) *windowHiddenOut = windowHidden;
    if (windowAlphaOut) *windowAlphaOut = windowAlpha;
    if (windowHidden == 1 ||
        (windowAlpha >= 0.0 && windowAlpha < 0.01)) {
        return false;
    }

    uint64_t scene = r_responds_main(window, "windowScene")
        ? r_msg2_main(window, "windowScene", 0, 0, 0, 0) : 0;
    if (sceneOut) *sceneOut = scene;
    if (r_is_objc_ptr(scene) &&
        r_responds_main(scene, "activationState")) {
        int64_t activationState = (int64_t)r_msg2_main(
            scene, "activationState", 0, 0, 0, 0);
        if (sceneActivationStateOut) {
            *sceneActivationStateOut = activationState;
        }
        if (sceneActivationStateKnownOut) {
            *sceneActivationStateKnownOut = true;
        }
        // UISceneActivationStateForegroundActive == 0.
        if (activationState != 0) return false;
    }
    return true;
}

static bool themer_spotlight_lifecycle_trace_capture(
    ThemerSpotlightLifecycleSnapshot *snapshot,
    ThemerSpotlightTraceLifetime *lifetime)
{
    if (!snapshot || !lifetime) return false;
    memset(snapshot, 0, sizeof(*snapshot));
    snapshot->windowHidden = -1;
    snapshot->windowAlpha = -1.0;
    snapshot->sceneActivationState = -99;
    snapshot->displayingImageLayer = -1;
    snapshot->displayingRealImageContents = -1;
    snapshot->shouldDisplayImageLayer = -1;
    snapshot->delayedImageUpdate = -1;
    snapshot->canUpdateImage = -1;
    snapshot->isUpdatingImage = -1;
    snapshot->carrierHidden = -1;
    snapshot->carrierAlpha = -1.0;
    snapshot->placeholderHidden = -1;
    snapshot->placeholderAlpha = -1.0;
    snapshot->currentIconIsPlaceholder = -1;

    uint64_t modelClass = themer_lookup_class("SearchUIHomeScreenModel");
    if (r_is_objc_ptr(modelClass) &&
        r_responds_main(modelClass, "sharedInstance")) {
        snapshot->owner = r_msg2_main(modelClass, "sharedInstance",
                                      0, 0, 0, 0);
    }
    (void)themer_spotlight_trace_hold(lifetime, snapshot->owner);
    snapshot->dataSource = themer_spotlight_trace_object_value(
        snapshot->owner, "dataSource", "_dataSource");
    snapshot->iconModel = themer_spotlight_trace_object_value(
        snapshot->owner, "iconModel", "_iconModel");
    (void)themer_spotlight_trace_hold(lifetime, snapshot->dataSource);
    (void)themer_spotlight_trace_hold(lifetime, snapshot->iconModel);

    snapshot->providerApplications = r_is_objc_ptr(snapshot->dataSource)
        ? r_ivar_value(snapshot->dataSource, "_applications") : 0;
    snapshot->providerTrackedBundleIDs = r_is_objc_ptr(snapshot->dataSource)
        ? r_ivar_value(snapshot->dataSource,
                       "_trackedApplicationBundleIdentifiers") : 0;
    (void)themer_spotlight_trace_hold(lifetime,
                                      snapshot->providerApplications);
    (void)themer_spotlight_trace_hold(lifetime,
                                      snapshot->providerTrackedBundleIDs);
    uint64_t providerIdentifier = r_nsstr_retained(
        gThemerSpotlightLifecycleTrace.bundle);
    if (r_is_objc_ptr(providerIdentifier)) {
        if (r_is_objc_ptr(snapshot->providerApplications) &&
            r_responds_main(snapshot->providerApplications,
                            "objectForKey:")) {
            snapshot->providerApplication = r_msg2_main(
                snapshot->providerApplications, "objectForKey:",
                providerIdentifier, 0, 0, 0);
            (void)themer_spotlight_trace_hold(
                lifetime, snapshot->providerApplication);
        }
        if (r_is_objc_ptr(snapshot->providerTrackedBundleIDs) &&
            r_responds_main(snapshot->providerTrackedBundleIDs,
                            "containsObject:")) {
            snapshot->providerTrackedKnown = true;
            snapshot->providerTracked =
                (r_msg2_main(snapshot->providerTrackedBundleIDs,
                             "containsObject:", providerIdentifier,
                             0, 0, 0) & 1) != 0;
        }
        r_msg2(providerIdentifier, "release", 0, 0, 0, 0);
    }
    if (!remote_call_current_success()) return false;

    enum { VIEW_CAP = 64 };
    uint64_t views[VIEW_CAP] = {0};
    int discoveredViewCount =
        themer_spotlight_collect_searchui_views_fast(views, VIEW_CAP);
    int viewCount = discoveredViewCount;
    if (!remote_call_current_success()) return false;
    bool selectedLive = false;
    for (int i = 0; i < viewCount; i++) {
        uint64_t view = views[i];
        uint64_t icon = themer_spotlight_app_icon_for_view(view, NULL, 0);
        if (!r_is_objc_ptr(icon)) continue;

        char bundle[192] = {0};
        if (!themer_spotlight_bundle_for_patch(view, icon,
                                               bundle, sizeof(bundle),
                                               NULL, 0) ||
            strcmp(bundle, gThemerSpotlightLifecycleTrace.bundle) != 0) {
            continue;
        }

        if (!themer_spotlight_trace_hold(lifetime, view) ||
            !themer_spotlight_trace_hold(lifetime, icon)) {
            if (!remote_call_current_success()) return false;
            continue;
        }

        bool live = themer_spotlight_trace_view_is_live(
            view, NULL, NULL, NULL, NULL, NULL, NULL);
        if (!snapshot->viewFound || (live && !selectedLive)) {
            snapshot->viewFound = true;
            snapshot->view = view;
            snapshot->viewIcon = icon;
            snapshot->viewLive = live;
            selectedLive = live;
        }
        if (live) break;
        if (!remote_call_current_success()) return false;
    }
    if (!remote_call_current_success()) return false;

    snapshot->canonicalIcon = themer_spotlight_trace_stored_model_icon(
        snapshot->iconModel,
        gThemerSpotlightLifecycleTrace.bundle,
        &snapshot->modelIconStorage,
        &snapshot->modelIconSource);
    (void)themer_spotlight_trace_hold(lifetime,
                                      snapshot->modelIconStorage);
    (void)themer_spotlight_trace_hold(lifetime,
                                      snapshot->canonicalIcon);
    snapshot->viewIconMatchesCanonical =
        r_is_objc_ptr(snapshot->viewIcon) &&
        r_is_objc_ptr(snapshot->canonicalIcon) &&
        snapshot->viewIcon == snapshot->canonicalIcon;

    if (r_is_objc_ptr(snapshot->iconModel) &&
        r_is_objc_ptr(snapshot->viewIcon) &&
        r_responds_main(snapshot->iconModel, "containsIcon:")) {
        snapshot->modelContainsViewIconKnown = true;
        snapshot->modelContainsViewIcon =
            (r_msg2_main(snapshot->iconModel, "containsIcon:",
                         snapshot->viewIcon, 0, 0, 0) & 1) != 0;
    }

    snapshot->viewActiveDataSource = themer_spotlight_trace_object_value(
        snapshot->viewIcon, "activeDataSource", "_activeDataSource");
    snapshot->canonicalActiveDataSource =
        themer_spotlight_trace_object_value(
            snapshot->canonicalIcon, "activeDataSource", "_activeDataSource");
    (void)themer_spotlight_trace_hold(lifetime,
                                      snapshot->viewActiveDataSource);
    (void)themer_spotlight_trace_hold(
        lifetime, snapshot->canonicalActiveDataSource);

    snapshot->viewIconDataSources = r_is_objc_ptr(snapshot->viewIcon)
        ? r_ivar_value(snapshot->viewIcon, "_dataSources") : 0;
    (void)themer_spotlight_trace_hold(lifetime,
                                      snapshot->viewIconDataSources);
    if (r_is_objc_ptr(snapshot->viewIconDataSources) &&
        r_responds_main(snapshot->viewIconDataSources, "count")) {
        snapshot->viewIconDataSourceCountKnown = true;
        snapshot->viewIconDataSourceCount = r_msg2_main(
            snapshot->viewIconDataSources, "count", 0, 0, 0, 0);
    }
    if (!remote_call_current_success()) return false;

    if (snapshot->viewFound) {
        snapshot->viewLive = themer_spotlight_trace_view_is_live(
            snapshot->view,
            &snapshot->window,
            &snapshot->windowHidden,
            &snapshot->windowAlpha,
            &snapshot->windowScene,
            &snapshot->sceneActivationState,
            &snapshot->sceneActivationStateKnown);
        snapshot->rowModel = themer_spotlight_trace_object_value(
            snapshot->view, "rowModel", "_rowModel");
        snapshot->variantKnown = themer_spotlight_trace_variant_for_view(
            snapshot->view, &snapshot->variant);
        if (!snapshot->variantKnown &&
            gThemerSpotlightLifecycleTrace.variantHintKnown) {
            snapshot->variant = gThemerSpotlightLifecycleTrace.variantHint;
        }

        snapshot->carrier =
            themer_spotlight_image_carrier_for_view(snapshot->view);
        (void)themer_spotlight_trace_hold(lifetime, snapshot->carrier);

        snapshot->carrierIcon = themer_spotlight_trace_object_value(
            snapshot->carrier, "icon", "_icon");
        snapshot->carrierIconView = themer_spotlight_trace_object_value(
            snapshot->carrier, "iconView", "_iconView");
        snapshot->carrierHidden = themer_remote_hidden(snapshot->carrier);
        snapshot->carrierAlpha = themer_remote_alpha(snapshot->carrier);

        snapshot->placeholderView = themer_spotlight_trace_object_value(
            snapshot->view, "placeholderView", "_placeholderView");
        snapshot->placeholderImage = themer_spotlight_trace_object_value(
            snapshot->placeholderView, "image", "_image");
        snapshot->placeholderImageCG =
            themer_spotlight_trace_image_cg(snapshot->placeholderImage);
        snapshot->placeholderLayer = themer_spotlight_trace_object_value(
            snapshot->placeholderView, "layer", "_layer");
        snapshot->placeholderLayerContents =
            themer_spotlight_trace_layer_contents(
                snapshot->placeholderLayer);
        snapshot->placeholderHidden =
            themer_remote_hidden(snapshot->placeholderView);
        snapshot->placeholderAlpha =
            themer_remote_alpha(snapshot->placeholderView);
        snapshot->currentIconIsPlaceholder =
            themer_spotlight_trace_bool_value(
                snapshot->view, "currentIconIsPlaceholder");

        snapshot->carrierImage = themer_spotlight_trace_object_value(
            snapshot->carrier, "image", "_image");
        snapshot->carrierDisplayedImage =
            themer_spotlight_trace_object_value(
                snapshot->carrier, "displayedImage", "_displayedImage");
        snapshot->carrierContentsImage =
            themer_spotlight_trace_object_value(
                snapshot->carrier, "contentsImage", "_contentsImage");
        snapshot->carrierSquareContentsImage =
            themer_spotlight_trace_object_value(
                snapshot->carrier, "squareContentsImage",
                "_squareContentsImage");
        snapshot->carrierImageCG =
            themer_spotlight_trace_image_cg(snapshot->carrierImage);
        snapshot->carrierDisplayedImageCG =
            themer_spotlight_trace_image_cg(
                snapshot->carrierDisplayedImage);
        snapshot->carrierContentsImageCG =
            themer_spotlight_trace_image_cg(
                snapshot->carrierContentsImage);
        snapshot->carrierSquareContentsImageCG =
            themer_spotlight_trace_image_cg(
                snapshot->carrierSquareContentsImage);
        snapshot->visibleImage = snapshot->carrierImage
            ? snapshot->carrierImage
            : snapshot->carrierDisplayedImage
                ? snapshot->carrierDisplayedImage
                : snapshot->carrierContentsImage
                    ? snapshot->carrierContentsImage
                    : snapshot->carrierSquareContentsImage;
        (void)themer_spotlight_trace_hold(lifetime,
                                          snapshot->visibleImage);
        snapshot->visibleCG =
            themer_spotlight_trace_image_cg(snapshot->visibleImage);

        snapshot->carrierLayer = themer_spotlight_trace_object_value(
            snapshot->carrier, "layer", "_layer");
        snapshot->carrierLayerContents =
            themer_spotlight_trace_layer_contents(snapshot->carrierLayer);
        snapshot->contentsLayerView = themer_spotlight_trace_object_value(
            snapshot->carrier, "contentsLayerView", "_contentsLayerView");
        snapshot->contentsLayer = themer_spotlight_trace_object_value(
            snapshot->carrier, "contentsLayer", "_contentsLayer");
        if (!r_is_objc_ptr(snapshot->contentsLayer)) {
            snapshot->contentsLayer = themer_spotlight_trace_object_value(
                snapshot->contentsLayerView, "layer", "_layer");
        }
        snapshot->contentsLayerContents =
            themer_spotlight_trace_layer_contents(snapshot->contentsLayer);
        snapshot->alternateContentsLayer =
            themer_spotlight_trace_object_value(
                snapshot->carrier, "alternateContentsLayer",
                "_alternateContentsLayer");
        snapshot->alternateContentsLayerContents =
            themer_spotlight_trace_layer_contents(
                snapshot->alternateContentsLayer);
        snapshot->iconLayerView = themer_spotlight_trace_object_value(
            snapshot->carrier, "iconLayerView", "_iconLayerView");
        snapshot->iconLayer = themer_spotlight_trace_object_value(
            snapshot->iconLayerView, "layer", "_layer");
        snapshot->iconLayerContents =
            themer_spotlight_trace_layer_contents(snapshot->iconLayer);
        snapshot->iconForImage = themer_spotlight_trace_object_value(
            snapshot->carrier, "iconForImage", "_iconForImage");
        snapshot->requestedImageIdentity =
            themer_spotlight_trace_object_value(
                snapshot->carrier, "requestedImageIdentity",
                "_requestedImageIdentity");
        (void)themer_spotlight_trace_hold(
            lifetime, snapshot->requestedImageIdentity);
        snapshot->displayedImageIdentity =
            themer_spotlight_trace_object_value(
                snapshot->carrier, "displayedImageIdentity",
                "_displayedImageIdentity");
        (void)themer_spotlight_trace_hold(
            lifetime, snapshot->displayedImageIdentity);
        snapshot->desiredImageIdentity =
            themer_spotlight_trace_object_value(
                snapshot->carrier, "desiredImageIdentity",
                "_desiredImageIdentity");
        (void)themer_spotlight_trace_hold(
            lifetime, snapshot->desiredImageIdentity);
        if (r_is_objc_ptr(snapshot->desiredImageIdentity) &&
            r_is_objc_ptr(snapshot->requestedImageIdentity) &&
            r_responds_main(snapshot->requestedImageIdentity, "isEqual:")) {
            snapshot->requestedIdentityMatchesDesired =
                (r_msg2_main(snapshot->requestedImageIdentity, "isEqual:",
                             snapshot->desiredImageIdentity, 0, 0, 0) & 1) != 0;
        }
        if (r_is_objc_ptr(snapshot->desiredImageIdentity) &&
            r_is_objc_ptr(snapshot->displayedImageIdentity) &&
            r_responds_main(snapshot->displayedImageIdentity, "isEqual:")) {
            snapshot->displayedIdentityMatchesDesired =
                (r_msg2_main(snapshot->displayedImageIdentity, "isEqual:",
                             snapshot->desiredImageIdentity, 0, 0, 0) & 1) != 0;
        }
        snapshot->displayingImageLayer =
            themer_spotlight_trace_bool_value(
                snapshot->carrier, "isDisplayingImageLayer");
        snapshot->displayingRealImageContents =
            themer_spotlight_trace_bool_value(
                snapshot->carrier, "isShowingRealContentsImage");
        if (snapshot->displayingRealImageContents < 0) {
            snapshot->displayingRealImageContents =
                themer_spotlight_trace_bool_value(
                    snapshot->carrier,
                    "isDisplayingRealImageContents");
        }
        snapshot->shouldDisplayImageLayer =
            themer_spotlight_trace_bool_value(
                snapshot->carrier, "shouldDisplayImageLayer");
        snapshot->delayedImageUpdate =
            themer_spotlight_trace_bool_value(
                snapshot->carrier,
                "delayedImageUpdateDueToContentVisibility");
        snapshot->cacheRequestCancellation =
            themer_spotlight_trace_object_value(
                snapshot->carrier, "cacheRequestCancellation",
                "_cacheRequestCancellation");
        (void)themer_spotlight_trace_hold(
            lifetime, snapshot->cacheRequestCancellation);
        snapshot->canUpdateImage = themer_spotlight_trace_bool_value(
            snapshot->carrier, "canUpdateImage");
        snapshot->isUpdatingImage = themer_spotlight_trace_bool_value(
            snapshot->carrier, "isUpdatingImage");
        if (r_is_objc_ptr(snapshot->carrier) &&
            r_responds_main(snapshot->carrier, "contentVisibility")) {
            snapshot->contentVisibilityKnown = true;
            snapshot->contentVisibility = r_msg2_main(
                snapshot->carrier, "contentVisibility", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(snapshot->carrier) &&
            r_responds_main(snapshot->carrier,
                            "imageCacheRetrievalOptions")) {
            snapshot->imageCacheRetrievalOptionsKnown = true;
            snapshot->imageCacheRetrievalOptions = r_msg2_main(
                snapshot->carrier, "imageCacheRetrievalOptions",
                0, 0, 0, 0);
        }
        snapshot->renderCacheOptions =
            snapshot->imageCacheRetrievalOptions | 4ULL;
        snapshot->appearance = themer_spotlight_trace_existing_appearance(
            snapshot->view, snapshot->carrier);
        (void)themer_spotlight_trace_hold(lifetime, snapshot->appearance);
        snapshot->requestedAppearance =
            themer_spotlight_trace_object_value(
                snapshot->carrier, "requestedImageAppearance",
                "_requestedImageAppearance");
        snapshot->displayedAppearance =
            themer_spotlight_trace_object_value(
                snapshot->carrier, "displayedImageAppearance",
                "_displayedImageAppearance");
        (void)themer_spotlight_trace_hold(
            lifetime, snapshot->requestedAppearance);
        (void)themer_spotlight_trace_hold(
            lifetime, snapshot->displayedAppearance);
        if (!remote_call_current_success()) return false;

        // Follow only object references already reachable from the current
        // view/icon. +cacheForVariant: can lazily create a cache after reset,
        // which would perturb the transition this tracer is meant to observe.
        snapshot->viewCache = themer_spotlight_trace_existing_cache(
            snapshot->view, 0, 0);
        snapshot->carrierCache = themer_spotlight_trace_existing_cache(
            0, snapshot->carrier, 0);
        snapshot->iconCache = themer_spotlight_trace_existing_cache(
            0, 0, snapshot->viewIcon);
        // Rendering is owned by SBIconImageView. Prefer its bound cache for
        // generation/content/observer reads; keep the view/icon caches beside
        // it so a mismatched binding remains visible in the trace.
        snapshot->cache = r_is_objc_ptr(snapshot->carrierCache)
            ? snapshot->carrierCache
            : r_is_objc_ptr(snapshot->viewCache)
                ? snapshot->viewCache
                : snapshot->iconCache;
        (void)themer_spotlight_trace_hold(lifetime, snapshot->cache);

        snapshot->maskedCache = r_is_objc_ptr(snapshot->cache)
            ? r_ivar_value(snapshot->cache, "_maskedCache") : 0;
        snapshot->unmaskedCache = r_is_objc_ptr(snapshot->cache)
            ? r_ivar_value(snapshot->cache, "_unmaskedCache") : 0;
        snapshot->cacheObservedIcons = r_is_objc_ptr(snapshot->cache)
            ? r_ivar_value(snapshot->cache, "_observedIcons") : 0;
        snapshot->cacheObservers = r_is_objc_ptr(snapshot->cache)
            ? r_ivar_value(snapshot->cache, "_observers") : 0;
        (void)themer_spotlight_trace_hold(lifetime,
                                          snapshot->maskedCache);
        (void)themer_spotlight_trace_hold(lifetime,
                                          snapshot->unmaskedCache);
        (void)themer_spotlight_trace_hold(lifetime,
                                          snapshot->cacheObservedIcons);
        (void)themer_spotlight_trace_hold(lifetime,
                                          snapshot->cacheObservers);
        if (r_is_objc_ptr(snapshot->cacheObservedIcons) &&
            r_is_objc_ptr(snapshot->viewIcon) &&
            r_responds_main(snapshot->cacheObservedIcons,
                            "containsObject:")) {
            snapshot->cacheObservesViewIconKnown = true;
            snapshot->cacheObservesViewIcon =
                (r_msg2_main(snapshot->cacheObservedIcons,
                             "containsObject:", snapshot->viewIcon,
                             0, 0, 0) & 1) != 0;
        }
        if (r_is_objc_ptr(snapshot->cacheObservers) &&
            r_responds_main(snapshot->cacheObservers, "count")) {
            snapshot->cacheObserverCountKnown = true;
            snapshot->cacheObserverCount = r_msg2_main(
                snapshot->cacheObservers, "count", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(snapshot->cacheObservers) &&
            r_is_objc_ptr(snapshot->carrier) &&
            r_responds_main(snapshot->cacheObservers, "containsObject:")) {
            snapshot->cacheObservesCarrierKnown = true;
            snapshot->cacheObservesCarrier =
                (r_msg2_main(snapshot->cacheObservers, "containsObject:",
                             snapshot->carrier, 0, 0, 0) & 1) != 0;
        }
        if (r_is_objc_ptr(snapshot->cacheObservers) &&
            r_is_objc_ptr(snapshot->view) &&
            r_responds_main(snapshot->cacheObservers, "containsObject:")) {
            snapshot->cacheObservesViewKnown = true;
            snapshot->cacheObservesView =
                (r_msg2_main(snapshot->cacheObservers, "containsObject:",
                             snapshot->view, 0, 0, 0) & 1) != 0;
        }

        if (r_is_objc_ptr(snapshot->cache) &&
            r_is_objc_ptr(snapshot->viewIcon) &&
            r_responds_main(snapshot->cache,
                            "currentImageGenerationForIcon:")) {
            snapshot->currentGenerationKnown = true;
            snapshot->currentGeneration = r_msg2_main(
                snapshot->cache, "currentImageGenerationForIcon:",
                snapshot->viewIcon, 0, 0, 0);
        }

        if (r_is_objc_ptr(snapshot->maskedCache) &&
            r_is_objc_ptr(snapshot->viewIcon) &&
            r_is_objc_ptr(snapshot->appearance) &&
            r_responds_main(snapshot->maskedCache,
                            "storedImageGenerationForIcon:imageAppearance:")) {
            snapshot->maskedStoredGenerationKnown = true;
            snapshot->maskedStoredGeneration = r_msg2_main(
                snapshot->maskedCache,
                "storedImageGenerationForIcon:imageAppearance:",
                snapshot->viewIcon, snapshot->appearance, 0, 0);
        }
        if (r_is_objc_ptr(snapshot->unmaskedCache) &&
            r_is_objc_ptr(snapshot->viewIcon) &&
            r_is_objc_ptr(snapshot->appearance) &&
            r_responds_main(snapshot->unmaskedCache,
                            "storedImageGenerationForIcon:imageAppearance:")) {
            snapshot->unmaskedStoredGenerationKnown = true;
            snapshot->unmaskedStoredGeneration = r_msg2_main(
                snapshot->unmaskedCache,
                "storedImageGenerationForIcon:imageAppearance:",
                snapshot->viewIcon, snapshot->appearance, 0, 0);
        }

        if (r_is_objc_ptr(snapshot->cache) &&
            r_responds_main(snapshot->cache, "cachedImageForIcon:")) {
            snapshot->cacheReadSelector = 1;
        }
        snapshot->cacheReadImage =
            themer_spotlight_trace_cached_image_only(
                snapshot->cache, snapshot->viewIcon);
        snapshot->cacheReadCG =
            themer_spotlight_trace_image_cg(snapshot->cacheReadImage);

        bool optionsZeroSupported = false;
        snapshot->optionsZeroReadImage =
            themer_spotlight_trace_cached_image_with_options(
                snapshot->cache, snapshot->viewIcon,
                snapshot->appearance, 0, &optionsZeroSupported);
        snapshot->optionedCacheReadSupported = optionsZeroSupported;
        snapshot->optionsZeroReadCG =
            themer_spotlight_trace_image_cg(
                snapshot->optionsZeroReadImage);
        bool renderOptionsSupported = false;
        snapshot->renderOptionsReadImage =
            themer_spotlight_trace_cached_image_with_options(
                snapshot->cache, snapshot->viewIcon,
                snapshot->appearance, snapshot->renderCacheOptions,
                &renderOptionsSupported);
        snapshot->optionedCacheReadSupported =
            snapshot->optionedCacheReadSupported ||
            renderOptionsSupported;
        snapshot->renderOptionsReadCG =
            themer_spotlight_trace_image_cg(
                snapshot->renderOptionsReadImage);

        uint64_t expectedCG = gThemerSpotlightLifecycleTrace.expectedCG;
        snapshot->cacheReadMatchesExpected = expectedCG &&
            snapshot->cacheReadCG == expectedCG;
        snapshot->optionsZeroReadMatchesExpected = expectedCG &&
            snapshot->optionsZeroReadCG == expectedCG;
        snapshot->renderOptionsReadMatchesExpected = expectedCG &&
            snapshot->renderOptionsReadCG == expectedCG;
    } else if (gThemerSpotlightLifecycleTrace.variantHintKnown) {
        // A scalar hint is safe to carry across view lifetimes. We purposely do
        // not dereference a prior view/icon/cache/appearance pointer here.
        snapshot->variant = gThemerSpotlightLifecycleTrace.variantHint;
    }
    return remote_call_current_success();
}

void themer_spotlight_lifecycle_trace_forget(void)
{
    memset(&gThemerSpotlightLifecycleTrace, 0,
           sizeof(gThemerSpotlightLifecycleTrace));
}

bool themer_spotlight_lifecycle_trace_is_armed(void)
{
    return gThemerSpotlightLifecycleTrace.armed;
}

static void themer_spotlight_lifecycle_trace_arm(const char *bundle,
                                                 uint64_t expectedCG,
                                                 uint64_t variant,
                                                 bool variantKnown)
{
    themer_spotlight_lifecycle_trace_forget();
    if (!bundle || !bundle[0]) return;

    gThemerSpotlightLifecycleTrace.armed = true;
    gThemerSpotlightLifecycleTrace.pid = remote_call_current_pid();
    gThemerSpotlightLifecycleTrace.startedUS = themer_now_us();
    gThemerSpotlightLifecycleTrace.expectedCG = expectedCG;
    gThemerSpotlightLifecycleTrace.variantHint = variant;
    gThemerSpotlightLifecycleTrace.variantHintKnown = variantKnown;
    snprintf(gThemerSpotlightLifecycleTrace.bundle,
             sizeof(gThemerSpotlightLifecycleTrace.bundle),
             "%s", bundle);

    printf("[SPOTLIGHT_TRACE] armed pid=%d bundle=%s expectedCG=0x%llx "
           "variant=%llu variantKnown=%d "
           "mode=scoped-presentation-intervention\n",
           gThemerSpotlightLifecycleTrace.pid,
           gThemerSpotlightLifecycleTrace.bundle,
           (unsigned long long)expectedCG,
           (unsigned long long)variant,
           variantKnown);
}

static int themer_spotlight_trace_try_clear_displayed_layer(
    ThemerSpotlightLifecycleTrace *trace,
    ThemerSpotlightLifecycleSnapshot *snapshot,
    uint64_t sampleIndex)
{
    if (!trace || !snapshot || !snapshot->viewLive ||
        !r_is_objc_ptr(snapshot->view) ||
        !r_is_objc_ptr(snapshot->carrier) || !trace->expectedCG) {
        return 0;
    }

    bool layerMode = snapshot->displayingImageLayer == 1 ||
                     snapshot->shouldDisplayImageLayer == 1;
    bool returnedAfterAbsence = trace->hasLast &&
                                !trace->last.viewLive &&
                                snapshot->viewLive;
    bool boundIdleRenderer = snapshot->canUpdateImage == 1 &&
        snapshot->isUpdatingImage == 0 &&
        !r_is_objc_ptr(snapshot->cacheRequestCancellation) &&
        snapshot->carrierIcon == snapshot->viewIcon &&
        snapshot->carrierCache == snapshot->cache;
    if (!snapshot->renderOptionsReadMatchesExpected ||
        !r_is_objc_ptr(snapshot->renderOptionsReadImage) ||
        !boundIdleRenderer || !layerMode ||
        snapshot->visibleCG == trace->expectedCG ||
        (trace->lastInterventionCarrier == snapshot->carrier &&
         !returnedAfterAbsence)) {
        return 0;
    }

    uint64_t carrier = themer_spotlight_image_carrier_for_view(
        snapshot->view);
    if (!r_is_objc_ptr(carrier) || carrier != snapshot->carrier) {
        printf("[SPOTLIGHT_TRACE] intervention sample=%llu "
               "called=0 reason=carrier-changed captured=0x%llx "
               "current=0x%llx\n",
               (unsigned long long)sampleIndex,
               (unsigned long long)snapshot->carrier,
               (unsigned long long)carrier);
        return 0;
    }

    static const char *selector =
        "updateImageContentsWithImage:imageAppearance:animated:"
        "shouldClearDisplayedLayer:";
    bool supported = r_responds_main(carrier, selector);
    if (!r_is_objc_ptr(snapshot->appearance) || !supported) {
        printf("[SPOTLIGHT_TRACE] intervention sample=%llu carrier=0x%llx "
               "called=0 supported=%d appearance=0x%llx "
               "reason=clear-layer-api-unavailable\n",
               (unsigned long long)sampleIndex,
               (unsigned long long)carrier,
               supported,
               (unsigned long long)snapshot->appearance);
        return 0;
    }

    uint64_t themedImage = snapshot->renderOptionsReadImage;
    int beforeDisplayingLayer = snapshot->displayingImageLayer;
    int beforeRealContents = snapshot->displayingRealImageContents;
    uint64_t beforeVisibleCG = snapshot->visibleCG;
    trace->lastInterventionCarrier = carrier;
    r_msg2_main(carrier, selector,
                themedImage, snapshot->appearance, 0, 1);
    trace->layerInterventionCount++;

    uint64_t displayedImage = themer_spotlight_trace_object_value(
        carrier, "displayedImage", "_displayedImage");
    uint64_t displayedCG =
        themer_spotlight_trace_image_cg(displayedImage);
    uint64_t layer = themer_spotlight_trace_object_value(
        carrier, "layer", "_layer");
    uint64_t layerContents =
        themer_spotlight_trace_layer_contents(layer);
    uint64_t contentsLayerView = themer_spotlight_trace_object_value(
        carrier, "contentsLayerView", "_contentsLayerView");
    uint64_t contentsLayer = themer_spotlight_trace_object_value(
        carrier, "contentsLayer", "_contentsLayer");
    if (!r_is_objc_ptr(contentsLayer)) {
        contentsLayer = themer_spotlight_trace_object_value(
            contentsLayerView, "layer", "_layer");
    }
    uint64_t contentsLayerContents =
        themer_spotlight_trace_layer_contents(contentsLayer);
    uint64_t alternateLayer = themer_spotlight_trace_object_value(
        carrier, "alternateContentsLayer", "_alternateContentsLayer");
    uint64_t alternateLayerContents =
        themer_spotlight_trace_layer_contents(alternateLayer);
    uint64_t iconLayerView = themer_spotlight_trace_object_value(
        carrier, "iconLayerView", "_iconLayerView");
    uint64_t iconLayer = themer_spotlight_trace_object_value(
        iconLayerView, "layer", "_layer");
    uint64_t iconLayerContents =
        themer_spotlight_trace_layer_contents(iconLayer);
    int displayingLayer = themer_spotlight_trace_bool_value(
        carrier, "isDisplayingImageLayer");
    int showingRealContents = themer_spotlight_trace_bool_value(
        carrier, "isShowingRealContentsImage");
    if (showingRealContents < 0) {
        showingRealContents = themer_spotlight_trace_bool_value(
            carrier, "isDisplayingRealImageContents");
    }
    bool matched = displayedCG == trace->expectedCG ||
                   layerContents == trace->expectedCG ||
                   contentsLayerContents == trace->expectedCG ||
                   alternateLayerContents == trace->expectedCG ||
                   iconLayerContents == trace->expectedCG;

    // Persist the post-intervention presentation state as the comparison
    // baseline. The next sample can then identify an asynchronous layer
    // reinstall instead of comparing against the state we intentionally
    // replaced.
    snapshot->carrierDisplayedImage = displayedImage;
    snapshot->carrierDisplayedImageCG = displayedCG;
    if (r_is_objc_ptr(displayedImage)) {
        snapshot->visibleImage = displayedImage;
        snapshot->visibleCG = displayedCG;
    }
    snapshot->carrierLayer = layer;
    snapshot->carrierLayerContents = layerContents;
    snapshot->contentsLayerView = contentsLayerView;
    snapshot->contentsLayer = contentsLayer;
    snapshot->contentsLayerContents = contentsLayerContents;
    snapshot->alternateContentsLayer = alternateLayer;
    snapshot->alternateContentsLayerContents = alternateLayerContents;
    snapshot->iconLayerView = iconLayerView;
    snapshot->iconLayer = iconLayer;
    snapshot->iconLayerContents = iconLayerContents;
    snapshot->displayingImageLayer = displayingLayer;
    snapshot->displayingRealImageContents = showingRealContents;

    printf("[SPOTLIGHT_TRACE] intervention sample=%llu carrier=0x%llx "
           "called=1 supported=1 clearDisplayedLayer=1 "
           "before={displayLayer:%d,realContents:%d,visibleCG:0x%llx} "
           "after={displayLayer:%d,realContents:%d,displayedImage:0x%llx,"
           "displayedCG:0x%llx,root:0x%llx/0x%llx,"
           "contents:0x%llx/0x%llx,alternate:0x%llx/0x%llx,"
           "icon:0x%llx/0x%llx,matched:%d} "
           "themedImage=0x%llx expectedCG=0x%llx count=%llu\n",
           (unsigned long long)sampleIndex,
           (unsigned long long)carrier,
           beforeDisplayingLayer,
           beforeRealContents,
           (unsigned long long)beforeVisibleCG,
           displayingLayer,
           showingRealContents,
           (unsigned long long)displayedImage,
           (unsigned long long)displayedCG,
           (unsigned long long)layer,
           (unsigned long long)layerContents,
           (unsigned long long)contentsLayer,
           (unsigned long long)contentsLayerContents,
           (unsigned long long)alternateLayer,
           (unsigned long long)alternateLayerContents,
           (unsigned long long)iconLayer,
           (unsigned long long)iconLayerContents,
           matched,
           (unsigned long long)themedImage,
           (unsigned long long)trace->expectedCG,
           (unsigned long long)trace->layerInterventionCount);
    return 1;
}

static uint64_t themer_spotlight_alpha_pinned_class(uint64_t currentClass,
                                                     bool *alreadyPinnedOut)
{
    if (alreadyPinnedOut) *alreadyPinnedOut = false;
    if (!r_is_objc_ptr(currentClass)) return 0;

    static const char *prefix = "CNDSpotlightAlphaPinnedV1_";
    char currentName[160] = {0};
    themer_read_class_object_name(currentClass,
                                  currentName,
                                  sizeof(currentName));
    if (!currentName[0]) return 0;
    if (strncmp(currentName, prefix, strlen(prefix)) == 0) {
        if (alreadyPinnedOut) *alreadyPinnedOut = true;
        return currentClass;
    }

    char subclassName[224] = {0};
    snprintf(subclassName, sizeof(subclassName), "%s%s",
             prefix, currentName);
    uint64_t subclass = themer_lookup_class(subclassName);
    uint64_t noOpImp =
        themer_remote_symbol_addr("objc_getAssociatedObject");
    if (!noOpImp) return 0;

    if (r_is_objc_ptr(subclass)) {
        return themer_ensure_method(subclass, "setAlpha:", noOpImp,
                                    "v24@0:8d16")
            ? subclass : 0;
    }

    uint64_t remoteName = r_alloc_str(subclassName);
    if (!remoteName) return 0;
    subclass = r_dlsym_call(R_TIMEOUT, "objc_allocateClassPair",
                            currentClass, remoteName, 0, 0, 0, 0, 0, 0);
    r_free(remoteName);
    if (!r_is_objc_ptr(subclass)) return 0;

    bool methodAdded = themer_add_method(subclass, "setAlpha:", noOpImp,
                                         "v24@0:8d16");
    r_dlsym_call(R_TIMEOUT, "objc_registerClassPair",
                 subclass, 0, 0, 0, 0, 0, 0, 0);
    if (!methodAdded) {
        printf("[SPOTLIGHT_TRACE] presentation-alpha-pin-class "
               "class=%s status=method-add-failed imp=0x%llx\n",
               subclassName,
               (unsigned long long)noOpImp);
        return 0;
    }
    return subclass;
}

// SearchUI's reactivation path has been observed changing only these two
// UIView alpha properties after the themed image is already present in the
// model, cache, SBIconImageView, and backing layer. Pinning setAlpha: on the
// two concrete instances preserves normal provider/cache updates while
// preventing the empty TLK placeholder from hiding a ready themed carrier.
// objc_getAssociatedObject is a safe no-op here: as a method IMP it consumes
// self/_cmd, ignores the floating-point setter argument, and its return value
// is discarded by the void setter call site.
static int themer_spotlight_pin_ready_presentation_alpha(
    uint64_t view,
    uint64_t carrier,
    uint64_t expectedCG,
    const char *phase)
{
    if (!r_is_objc_ptr(view) || !r_is_objc_ptr(carrier) || !expectedCG ||
        themer_spotlight_image_carrier_for_view(view) != carrier) {
        return 0;
    }

    uint64_t placeholder = themer_spotlight_trace_object_value(
        view, "placeholderView", "_placeholderView");
    if (!r_is_objc_ptr(placeholder)) return 0;

    uint64_t displayedImage = themer_spotlight_trace_object_value(
        carrier, "displayedImage", "_displayedImage");
    uint64_t displayedCG =
        themer_spotlight_trace_image_cg(displayedImage);
    uint64_t carrierLayer = themer_spotlight_trace_object_value(
        carrier, "layer", "_layer");
    uint64_t layerContents =
        themer_spotlight_trace_layer_contents(carrierLayer);
    int logicalPlaceholder = themer_spotlight_trace_bool_value(
        view, "currentIconIsPlaceholder");
    int carrierHidden = themer_remote_hidden(carrier);
    int placeholderHidden = themer_remote_hidden(placeholder);
    double carrierAlpha = themer_remote_alpha(carrier);
    double placeholderAlpha = themer_remote_alpha(placeholder);
    uint64_t viewLoadingBehavior = r_responds_main(
        view, "imageLoadingBehavior")
        ? r_msg2_main(view, "imageLoadingBehavior", 0, 0, 0, 0) : 0;
    uint64_t carrierLoadingBehavior = r_responds_main(
        carrier, "imageLoadingBehavior")
        ? r_msg2_main(carrier, "imageLoadingBehavior", 0, 0, 0, 0) : 0;
    int carrierLoadingSynchronous = themer_spotlight_trace_bool_value(
        carrier, "isImageLoadingBehaviorSynchronous");
    int carrierLoadingAsynchronous = themer_spotlight_trace_bool_value(
        carrier, "isImageLoadingBehaviorAsynchronous");
    bool exactReadyState = displayedCG == expectedCG &&
        layerContents == expectedCG && logicalPlaceholder == 0 &&
        carrierHidden == 0 && carrierAlpha >= 0.99 &&
        placeholderHidden == 0 && placeholderAlpha <= 0.01;
    if (!exactReadyState) {
        printf("[SPOTLIGHT_TRACE] presentation-alpha-pin phase=%s "
               "view=0x%llx carrier=0x%llx placeholder=0x%llx "
               "status=not-ready displayedCG=0x%llx/match:%d "
               "layerCG=0x%llx/match:%d hidden=%d/%d alpha=%.2f/%.2f "
               "logical=%d loading={view:%llu,carrier:%llu,sync:%d,async:%d}\n",
               phase && phase[0] ? phase : "unknown",
               (unsigned long long)view,
               (unsigned long long)carrier,
               (unsigned long long)placeholder,
               (unsigned long long)displayedCG,
               displayedCG == expectedCG,
               (unsigned long long)layerContents,
               layerContents == expectedCG,
               carrierHidden,
               placeholderHidden,
               carrierAlpha,
               placeholderAlpha,
               logicalPlaceholder,
               (unsigned long long)viewLoadingBehavior,
               (unsigned long long)carrierLoadingBehavior,
               carrierLoadingSynchronous,
               carrierLoadingAsynchronous);
        return 0;
    }

    uint64_t carrierClass = r_dlsym_call(R_TIMEOUT, "object_getClass",
                                         carrier, 0, 0, 0, 0, 0, 0, 0);
    uint64_t placeholderClass = r_dlsym_call(R_TIMEOUT, "object_getClass",
                                             placeholder,
                                             0, 0, 0, 0, 0, 0, 0);
    bool carrierAlreadyPinned = false;
    bool placeholderAlreadyPinned = false;
    uint64_t pinnedCarrierClass = themer_spotlight_alpha_pinned_class(
        carrierClass, &carrierAlreadyPinned);
    uint64_t pinnedPlaceholderClass = themer_spotlight_alpha_pinned_class(
        placeholderClass, &placeholderAlreadyPinned);
    if (!r_is_objc_ptr(pinnedCarrierClass) ||
        !r_is_objc_ptr(pinnedPlaceholderClass)) {
        printf("[SPOTLIGHT_TRACE] presentation-alpha-pin phase=%s "
               "view=0x%llx carrier=0x%llx placeholder=0x%llx "
               "status=class-unavailable carrierClass=0x%llx/0x%llx "
               "placeholderClass=0x%llx/0x%llx\n",
               phase && phase[0] ? phase : "unknown",
               (unsigned long long)view,
               (unsigned long long)carrier,
               (unsigned long long)placeholder,
               (unsigned long long)carrierClass,
               (unsigned long long)pinnedCarrierClass,
               (unsigned long long)placeholderClass,
               (unsigned long long)pinnedPlaceholderClass);
        return 0;
    }

    double carrierOne = 1.0;
    double placeholderZero = 0.0;
    if (!carrierAlreadyPinned) {
        r_msg2_main_raw(carrier, "setAlpha:",
                        &carrierOne, sizeof(carrierOne),
                        NULL, 0, NULL, 0, NULL, 0);
    }
    if (!placeholderAlreadyPinned) {
        r_msg2_main_raw(placeholder, "setAlpha:",
                        &placeholderZero, sizeof(placeholderZero),
                        NULL, 0, NULL, 0, NULL, 0);
    }
    carrierAlpha = themer_remote_alpha(carrier);
    placeholderAlpha = themer_remote_alpha(placeholder);
    if (carrierAlpha < 0.99 || placeholderAlpha > 0.01) {
        printf("[SPOTLIGHT_TRACE] presentation-alpha-pin phase=%s "
               "view=0x%llx carrier=0x%llx placeholder=0x%llx "
               "status=precondition-raced alpha=%.2f/%.2f\n",
               phase && phase[0] ? phase : "unknown",
               (unsigned long long)view,
               (unsigned long long)carrier,
               (unsigned long long)placeholder,
               carrierAlpha,
               placeholderAlpha);
        return 0;
    }

    if (!carrierAlreadyPinned) {
        r_dlsym_call(R_TIMEOUT, "object_setClass",
                     carrier, pinnedCarrierClass, 0, 0, 0, 0, 0, 0);
    }
    if (!placeholderAlreadyPinned) {
        r_dlsym_call(R_TIMEOUT, "object_setClass",
                     placeholder, pinnedPlaceholderClass,
                     0, 0, 0, 0, 0, 0);
    }

    uint64_t installedCarrierClass = r_dlsym_call(
        R_TIMEOUT, "object_getClass", carrier, 0, 0, 0, 0, 0, 0, 0);
    uint64_t installedPlaceholderClass = r_dlsym_call(
        R_TIMEOUT, "object_getClass", placeholder, 0, 0, 0, 0, 0, 0, 0);
    bool carrierInstalled = installedCarrierClass == pinnedCarrierClass;
    bool placeholderInstalled =
        installedPlaceholderClass == pinnedPlaceholderClass;

    char carrierClassName[128] = {0};
    char placeholderClassName[128] = {0};
    themer_read_class_object_name(installedCarrierClass,
                                  carrierClassName,
                                  sizeof(carrierClassName));
    themer_read_class_object_name(installedPlaceholderClass,
                                  placeholderClassName,
                                  sizeof(placeholderClassName));
    printf("[SPOTLIGHT_TRACE] presentation-alpha-pin phase=%s "
           "view=0x%llx carrier=0x%llx/%s placeholder=0x%llx/%s "
           "expectedCG=0x%llx alpha=%.2f/%.2f "
           "loading={view:%llu,carrier:%llu,sync:%d,async:%d} "
           "already=%d/%d installed=%d/%d\n",
           phase && phase[0] ? phase : "unknown",
           (unsigned long long)view,
           (unsigned long long)carrier,
           carrierClassName[0] ? carrierClassName : "-",
           (unsigned long long)placeholder,
           placeholderClassName[0] ? placeholderClassName : "-",
           (unsigned long long)expectedCG,
           themer_remote_alpha(carrier),
           themer_remote_alpha(placeholder),
           (unsigned long long)viewLoadingBehavior,
           (unsigned long long)carrierLoadingBehavior,
           carrierLoadingSynchronous,
           carrierLoadingAsynchronous,
           carrierAlreadyPinned,
           placeholderAlreadyPinned,
           carrierInstalled,
           placeholderInstalled);
    return (carrierInstalled ? 1 : 0) +
           (placeholderInstalled ? 1 : 0);
}

static int themer_spotlight_trace_try_reveal_themed_carrier(
    ThemerSpotlightLifecycleTrace *trace,
    ThemerSpotlightLifecycleSnapshot *snapshot,
    uint64_t sampleIndex)
{
    if (!trace || !snapshot || !snapshot->viewLive ||
        !r_is_objc_ptr(snapshot->view) ||
        !r_is_objc_ptr(snapshot->carrier) ||
        !r_is_objc_ptr(snapshot->viewIcon) || !trace->expectedCG) {
        return 0;
    }

    bool foregroundActive = snapshot->sceneActivationStateKnown &&
        snapshot->sceneActivationState == 0;
    bool carrierHasTheme =
        snapshot->visibleCG == trace->expectedCG &&
        snapshot->carrierDisplayedImageCG == trace->expectedCG &&
        snapshot->renderOptionsReadMatchesExpected;
    bool carrierSuppressed = snapshot->carrierHidden == 0 &&
        snapshot->carrierAlpha >= 0.0 &&
        snapshot->carrierAlpha <= 0.01;
    bool placeholderShown = r_is_objc_ptr(snapshot->placeholderView) &&
        snapshot->placeholderHidden == 0 &&
        snapshot->placeholderAlpha >= 0.99;
    bool correctlyBound = snapshot->viewIconMatchesCanonical &&
        snapshot->carrierIcon == snapshot->viewIcon &&
        snapshot->carrierIconView == snapshot->view &&
        r_is_objc_ptr(snapshot->cache) &&
        snapshot->carrierCache == snapshot->cache;
    bool rendererIdle = snapshot->canUpdateImage == 1 &&
        snapshot->isUpdatingImage == 0 &&
        snapshot->delayedImageUpdate == 0 &&
        snapshot->cacheRequestCancellation == 0;
    bool logicalIconIsReady = snapshot->currentIconIsPlaceholder == 0;
    bool epochEligible = trace->presentationEpoch != 0 &&
        trace->lastPresentationRepairEpoch != trace->presentationEpoch;
    if (!foregroundActive || !carrierHasTheme || !carrierSuppressed ||
        !placeholderShown || !correctlyBound || !rendererIdle ||
        !logicalIconIsReady || !epochEligible) {
        return 0;
    }

    uint64_t carrier = themer_spotlight_image_carrier_for_view(
        snapshot->view);
    if (!r_is_objc_ptr(carrier) || carrier != snapshot->carrier) {
        printf("[SPOTLIGHT_TRACE] presentation-repair sample=%llu "
               "called=0 reason=carrier-changed captured=0x%llx "
               "current=0x%llx\n",
               (unsigned long long)sampleIndex,
               (unsigned long long)snapshot->carrier,
               (unsigned long long)carrier);
        return 0;
    }

    static const char *selector =
        "iconImageViewDidChangeContents:forIcon:";
    bool supported = r_responds_main(snapshot->view, selector);
    if (!supported) {
        trace->lastPresentationRepairEpoch = trace->presentationEpoch;
        printf("[SPOTLIGHT_TRACE] presentation-repair sample=%llu "
               "epoch=%llu view=0x%llx carrier=0x%llx "
               "called=0 supported=0 "
               "reason=delegate-api-unavailable\n",
               (unsigned long long)sampleIndex,
               (unsigned long long)trace->presentationEpoch,
               (unsigned long long)snapshot->view,
               (unsigned long long)carrier);
        return 0;
    }

    int beforeCarrierHidden = snapshot->carrierHidden;
    double beforeCarrierAlpha = snapshot->carrierAlpha;
    int beforePlaceholderHidden = snapshot->placeholderHidden;
    double beforePlaceholderAlpha = snapshot->placeholderAlpha;
    int beforeCurrentIconIsPlaceholder =
        snapshot->currentIconIsPlaceholder;
    trace->lastPresentationRepairEpoch = trace->presentationEpoch;
    r_msg2_main(snapshot->view, selector,
                carrier, snapshot->viewIcon, 0, 0);
    trace->presentationRepairCount++;

    uint64_t carrierImage = themer_spotlight_trace_object_value(
        carrier, "image", "_image");
    uint64_t carrierDisplayedImage = themer_spotlight_trace_object_value(
        carrier, "displayedImage", "_displayedImage");
    uint64_t carrierContentsImage = themer_spotlight_trace_object_value(
        carrier, "contentsImage", "_contentsImage");
    uint64_t carrierSquareContentsImage =
        themer_spotlight_trace_object_value(
            carrier, "squareContentsImage", "_squareContentsImage");
    uint64_t visibleImage = carrierImage
        ? carrierImage
        : carrierDisplayedImage
            ? carrierDisplayedImage
            : carrierContentsImage
                ? carrierContentsImage
                : carrierSquareContentsImage;
    uint64_t visibleCG = themer_spotlight_trace_image_cg(visibleImage);
    uint64_t carrierImageCG =
        themer_spotlight_trace_image_cg(carrierImage);
    uint64_t carrierDisplayedCG =
        themer_spotlight_trace_image_cg(carrierDisplayedImage);
    uint64_t carrierContentsImageCG =
        themer_spotlight_trace_image_cg(carrierContentsImage);
    uint64_t carrierSquareContentsImageCG =
        themer_spotlight_trace_image_cg(carrierSquareContentsImage);
    uint64_t carrierLayer = themer_spotlight_trace_object_value(
        carrier, "layer", "_layer");
    uint64_t carrierLayerContents =
        themer_spotlight_trace_layer_contents(carrierLayer);

    uint64_t placeholder = themer_spotlight_trace_object_value(
        snapshot->view, "placeholderView", "_placeholderView");
    uint64_t placeholderImage = themer_spotlight_trace_object_value(
        placeholder, "image", "_image");
    uint64_t placeholderImageCG =
        themer_spotlight_trace_image_cg(placeholderImage);
    uint64_t placeholderLayer = themer_spotlight_trace_object_value(
        placeholder, "layer", "_layer");
    uint64_t placeholderLayerContents =
        themer_spotlight_trace_layer_contents(placeholderLayer);
    int carrierHidden = themer_remote_hidden(carrier);
    double carrierAlpha = themer_remote_alpha(carrier);
    int placeholderHidden = themer_remote_hidden(placeholder);
    double placeholderAlpha = themer_remote_alpha(placeholder);
    int currentIconIsPlaceholder = themer_spotlight_trace_bool_value(
        snapshot->view, "currentIconIsPlaceholder");
    bool revealed = carrierHidden != 1 && carrierAlpha > 0.01;
    bool placeholderCleared = !r_is_objc_ptr(placeholder) ||
        placeholderHidden == 1 || placeholderAlpha <= 0.01;

    snapshot->carrierImage = carrierImage;
    snapshot->carrierDisplayedImage = carrierDisplayedImage;
    snapshot->carrierContentsImage = carrierContentsImage;
    snapshot->carrierSquareContentsImage = carrierSquareContentsImage;
    snapshot->carrierImageCG = carrierImageCG;
    snapshot->carrierDisplayedImageCG = carrierDisplayedCG;
    snapshot->carrierContentsImageCG = carrierContentsImageCG;
    snapshot->carrierSquareContentsImageCG =
        carrierSquareContentsImageCG;
    snapshot->visibleImage = visibleImage;
    snapshot->visibleCG = visibleCG;
    snapshot->carrierLayer = carrierLayer;
    snapshot->carrierLayerContents = carrierLayerContents;
    snapshot->carrierHidden = carrierHidden;
    snapshot->carrierAlpha = carrierAlpha;
    snapshot->placeholderView = placeholder;
    snapshot->placeholderImage = placeholderImage;
    snapshot->placeholderImageCG = placeholderImageCG;
    snapshot->placeholderLayer = placeholderLayer;
    snapshot->placeholderLayerContents = placeholderLayerContents;
    snapshot->placeholderHidden = placeholderHidden;
    snapshot->placeholderAlpha = placeholderAlpha;
    snapshot->currentIconIsPlaceholder = currentIconIsPlaceholder;

    printf("[SPOTLIGHT_TRACE] presentation-repair sample=%llu "
           "epoch=%llu view=0x%llx carrier=0x%llx rowModel=0x%llx "
           "called=1 supported=1 "
           "selector=iconImageViewDidChangeContents:forIcon: "
           "expectedCG=0x%llx "
           "before={carrierHidden:%d,carrierAlpha:%.2f,"
           "placeholderHidden:%d,placeholderAlpha:%.2f,logical:%d} "
           "after={carrierHidden:%d,carrierAlpha:%.2f,revealed:%d,"
           "placeholder:0x%llx,placeholderHidden:%d,"
           "placeholderAlpha:%.2f,placeholderCleared:%d,logical:%d,"
           "visibleCG:0x%llx,displayedCG:0x%llx,"
           "carrierLayer:0x%llx/0x%llx,"
           "placeholderImage:0x%llx/0x%llx,"
           "placeholderLayer:0x%llx/0x%llx} count=%llu\n",
           (unsigned long long)sampleIndex,
           (unsigned long long)trace->presentationEpoch,
           (unsigned long long)snapshot->view,
           (unsigned long long)carrier,
           (unsigned long long)snapshot->rowModel,
           (unsigned long long)trace->expectedCG,
           beforeCarrierHidden,
           beforeCarrierAlpha,
           beforePlaceholderHidden,
           beforePlaceholderAlpha,
           beforeCurrentIconIsPlaceholder,
           carrierHidden,
           carrierAlpha,
           revealed,
           (unsigned long long)placeholder,
           placeholderHidden,
           placeholderAlpha,
           placeholderCleared,
           currentIconIsPlaceholder,
           (unsigned long long)visibleCG,
           (unsigned long long)carrierDisplayedCG,
           (unsigned long long)carrierLayer,
           (unsigned long long)carrierLayerContents,
           (unsigned long long)placeholderImage,
           (unsigned long long)placeholderImageCG,
           (unsigned long long)placeholderLayer,
           (unsigned long long)placeholderLayerContents,
           (unsigned long long)trace->presentationRepairCount);

    int presentationAlphaPins = 0;
    if (kThemerSpotlightPresentationAlphaPinEnabled &&
        revealed && placeholderCleared &&
        currentIconIsPlaceholder == 0 &&
        carrierDisplayedCG == trace->expectedCG &&
        carrierLayerContents == trace->expectedCG) {
        presentationAlphaPins =
            themer_spotlight_pin_ready_presentation_alpha(
                snapshot->view, carrier, trace->expectedCG,
                "presentation-repair");
    }
    printf("[SPOTLIGHT_TRACE] presentation-repair-pin sample=%llu "
           "epoch=%llu pins=%d remoteHealthy=%d\n",
           (unsigned long long)sampleIndex,
           (unsigned long long)trace->presentationEpoch,
           presentationAlphaPins,
           remote_call_current_success());

    static const useconds_t postcheckDelaysUS[] = {
        250000,
        750000,
    };
    uint64_t postcheckElapsedUS = 0;
    for (size_t i = 0;
         i < sizeof(postcheckDelaysUS) / sizeof(postcheckDelaysUS[0]);
         i++) {
        usleep(postcheckDelaysUS[i]);
        postcheckElapsedUS += postcheckDelaysUS[i];

        uint64_t checkRowModel = themer_spotlight_trace_object_value(
            snapshot->view, "rowModel", "_rowModel");
        uint64_t checkCarrier = themer_spotlight_image_carrier_for_view(
            snapshot->view);
        uint64_t checkPlaceholder = themer_spotlight_trace_object_value(
            snapshot->view, "placeholderView", "_placeholderView");
        int checkCarrierHidden = themer_remote_hidden(checkCarrier);
        double checkCarrierAlpha = themer_remote_alpha(checkCarrier);
        int checkPlaceholderHidden =
            themer_remote_hidden(checkPlaceholder);
        double checkPlaceholderAlpha =
            themer_remote_alpha(checkPlaceholder);
        int checkLogicalPlaceholder = themer_spotlight_trace_bool_value(
            snapshot->view, "currentIconIsPlaceholder");
        uint64_t checkDisplayedImage =
            themer_spotlight_trace_object_value(
                checkCarrier, "displayedImage", "_displayedImage");
        uint64_t checkDisplayedCG =
            themer_spotlight_trace_image_cg(checkDisplayedImage);
        uint64_t checkLayer = themer_spotlight_trace_object_value(
            checkCarrier, "layer", "_layer");
        uint64_t checkLayerContents =
            themer_spotlight_trace_layer_contents(checkLayer);
        bool checkLive = themer_spotlight_trace_view_is_live(
            snapshot->view, NULL, NULL, NULL, NULL, NULL, NULL);
        bool checkRevealed = checkCarrierHidden != 1 &&
            checkCarrierAlpha > 0.01;
        bool checkPlaceholderCleared =
            !r_is_objc_ptr(checkPlaceholder) ||
            checkPlaceholderHidden == 1 ||
            checkPlaceholderAlpha <= 0.01;

        printf("[SPOTLIGHT_TRACE] presentation-postcheck sample=%llu "
               "epoch=%llu delayMS=%llu live=%d "
               "rowModel=0x%llx changed=%d "
               "carrier=0x%llx same=%d hidden=%d alpha=%.2f "
               "revealed=%d placeholder=0x%llx hidden=%d alpha=%.2f "
               "cleared=%d logical=%d displayedCG=0x%llx/match:%d "
               "layer=0x%llx/0x%llx/match:%d\n",
               (unsigned long long)sampleIndex,
               (unsigned long long)trace->presentationEpoch,
               (unsigned long long)(postcheckElapsedUS / 1000ULL),
               checkLive,
               (unsigned long long)checkRowModel,
               checkRowModel != snapshot->rowModel,
               (unsigned long long)checkCarrier,
               checkCarrier == carrier,
               checkCarrierHidden,
               checkCarrierAlpha,
               checkRevealed,
               (unsigned long long)checkPlaceholder,
               checkPlaceholderHidden,
               checkPlaceholderAlpha,
               checkPlaceholderCleared,
               checkLogicalPlaceholder,
               (unsigned long long)checkDisplayedCG,
               checkDisplayedCG == trace->expectedCG,
               (unsigned long long)checkLayer,
               (unsigned long long)checkLayerContents,
               checkLayerContents == trace->expectedCG);

        if (!remote_call_current_success()) break;
    }
    return 1;
}

bool themer_spotlight_lifecycle_trace_sentinel_in_session(const char *phase,
                                                          bool forceLog)
{
    (void)forceLog;
    ThemerSpotlightLifecycleTrace *trace =
        &gThemerSpotlightLifecycleTrace;
    if (!trace->armed) return false;

    int currentPID = remote_call_current_pid();
    if (currentPID != trace->pid) {
        printf("[SPOTLIGHT_FAST] rejected phase=%s reason=session-pid-changed "
               "expected=%d actual=%d\n",
               phase && phase[0] ? phase : "sentinel",
               trace->pid,
               currentPID);
        return false;
    }

    uint32_t previousSettleUS = r_settle_us(1000);
    ThemerSpotlightTraceLifetime lifetime = {0};
    @try {
        enum { VIEW_CAP = 32 };
        uint64_t views[VIEW_CAP] = {0};
        int viewCount = themer_spotlight_collect_searchui_views_fast(
            views, VIEW_CAP);
        if (!remote_call_current_success()) return false;

        uint64_t sampleIndex = trace->sampleIndex++;
        uint64_t preferredView = trace->hasSentinel
            ? trace->sentinelView
            : trace->hasLast ? trace->last.view : 0;
        enum { TARGET_CAP = 8 };
        uint64_t targetViews[TARGET_CAP] = {0};
        uint64_t targetIcons[TARGET_CAP] = {0};
        bool targetLive[TARGET_CAP] = {0};
        int targetCount = 0;
        int targetTotal = 0;
        for (int i = 0; i < viewCount; i++) {
            uint64_t view = views[i];
            if (!themer_spotlight_trace_hold(&lifetime, view)) {
                if (!remote_call_current_success()) return false;
                continue;
            }
            uint64_t icon = themer_spotlight_app_icon_for_view(
                view, NULL, 0);
            if (!r_is_objc_ptr(icon) ||
                !themer_spotlight_trace_hold(&lifetime, icon)) {
                if (!remote_call_current_success()) return false;
                continue;
            }
            char bundle[192] = {0};
            if (!themer_spotlight_bundle_for_patch(
                    view, icon, bundle, sizeof(bundle), NULL, 0) ||
                strcmp(bundle, trace->bundle) != 0) {
                if (!remote_call_current_success()) return false;
                continue;
            }
            targetTotal++;
            if (targetCount < TARGET_CAP) {
                targetViews[targetCount] = view;
                targetIcons[targetCount] = icon;
                targetLive[targetCount] =
                    themer_spotlight_view_is_live(view);
                targetCount++;
            }
        }

        int selectedTarget = -1;
        for (int i = 0; i < targetCount; i++) {
            if (targetLive[i] && selectedTarget < 0) {
                selectedTarget = i;
            }
            if (targetLive[i] && targetViews[i] == preferredView) {
                selectedTarget = i;
                break;
            }
        }
        if (selectedTarget < 0 && targetCount > 0) {
            selectedTarget = 0;
            for (int i = 0; i < targetCount; i++) {
                if (targetViews[i] == preferredView) {
                    selectedTarget = i;
                    break;
                }
            }
        }
        uint64_t selectedView = selectedTarget >= 0
            ? targetViews[selectedTarget] : 0;
        uint64_t selectedIcon = selectedTarget >= 0
            ? targetIcons[selectedTarget] : 0;

        for (int i = 0; i < targetCount; i++) {
            uint64_t view = targetViews[i];
            uint64_t carrier =
                themer_spotlight_image_carrier_for_view(view);
            (void)themer_spotlight_trace_hold(&lifetime, carrier);
            uint64_t displayedImage =
                themer_spotlight_trace_object_value(
                    carrier, "displayedImage", "_displayedImage");
            uint64_t displayedCG =
                themer_spotlight_trace_image_cg(displayedImage);
            uint64_t layer = themer_spotlight_trace_object_value(
                carrier, "layer", "_layer");
            uint64_t layerContents =
                themer_spotlight_trace_layer_contents(layer);
            uint64_t placeholder =
                themer_spotlight_trace_object_value(
                    view, "placeholderView", "_placeholderView");
            double viewAlpha = themer_remote_alpha(view);
            int viewHidden = themer_remote_hidden(view);
            uint64_t window = r_responds_main(view, "window")
                ? r_msg2_main(view, "window", 0, 0, 0, 0) : 0;
            ThemerRect frame = {0};
            bool frameKnown = themer_read_rect(view, "frame", &frame);
            uint64_t rowModel = themer_spotlight_trace_object_value(
                view, "rowModel", "_rowModel");
            printf("[SPOTLIGHT_FAST_VIEW] sample=%llu index=%d/%d "
                   "selected=%d preferred=%d live=%d "
                   "view=0x%llx hidden=%d alpha=%.2f window=0x%llx "
                   "frame={%.1f,%.1f,%.1f,%.1f}/%d rowModel=0x%llx "
                   "icon=0x%llx carrier=0x%llx alpha=%.2f "
                   "displayedCG=0x%llx/match:%d "
                   "layer=0x%llx/0x%llx/match:%d "
                   "placeholder=0x%llx/alpha:%.2f\n",
                   (unsigned long long)sampleIndex,
                   i + 1,
                   targetTotal,
                   i == selectedTarget,
                   view == preferredView,
                   targetLive[i],
                   (unsigned long long)view,
                   viewHidden,
                   viewAlpha,
                   (unsigned long long)window,
                   frame.x, frame.y, frame.w, frame.h,
                   frameKnown,
                   (unsigned long long)rowModel,
                   (unsigned long long)targetIcons[i],
                   (unsigned long long)carrier,
                   themer_remote_alpha(carrier),
                   (unsigned long long)displayedCG,
                   displayedCG == trace->expectedCG,
                   (unsigned long long)layer,
                   (unsigned long long)layerContents,
                   layerContents == trace->expectedCG,
                   (unsigned long long)placeholder,
                   themer_remote_alpha(placeholder));
            if (!remote_call_current_success()) return false;
        }

        if (!r_is_objc_ptr(selectedView) ||
            !r_is_objc_ptr(selectedIcon)) {
            printf("[SPOTLIGHT_FAST] sample=%llu phase=%s "
                   "classification=target-view-absent views=%d matches=%d "
                   "expectedCG=0x%llx\n",
                   (unsigned long long)sampleIndex,
                   phase && phase[0] ? phase : "sentinel",
                   viewCount,
                   targetTotal,
                   (unsigned long long)trace->expectedCG);
            trace->sentinelView = 0;
            trace->sentinelRowModel = 0;
            trace->sentinelCarrier = 0;
            trace->sentinelLive = false;
            trace->hasSentinel = true;
            return remote_call_current_success();
        }

        ThemerSpotlightLifecycleSnapshot snapshot = {0};
        snapshot.windowHidden = -1;
        snapshot.windowAlpha = -1.0;
        snapshot.sceneActivationState = -99;
        snapshot.displayingImageLayer = -1;
        snapshot.displayingRealImageContents = -1;
        snapshot.shouldDisplayImageLayer = -1;
        snapshot.delayedImageUpdate = -1;
        snapshot.canUpdateImage = -1;
        snapshot.isUpdatingImage = -1;
        snapshot.carrierHidden = -1;
        snapshot.carrierAlpha = -1.0;
        snapshot.placeholderHidden = -1;
        snapshot.placeholderAlpha = -1.0;
        snapshot.currentIconIsPlaceholder = -1;

        snapshot.viewFound = true;
        snapshot.view = selectedView;
        snapshot.viewIcon = selectedIcon;
        snapshot.canonicalIcon = trace->hasLast
            ? trace->last.canonicalIcon : 0;
        snapshot.viewIconMatchesCanonical =
            r_is_objc_ptr(snapshot.canonicalIcon) &&
            snapshot.viewIcon == snapshot.canonicalIcon;
        snapshot.providerApplication = trace->hasLast
            ? trace->last.providerApplication : 0;
        snapshot.viewActiveDataSource =
            themer_spotlight_trace_object_value(
                selectedIcon, "activeDataSource", "_activeDataSource");
        (void)themer_spotlight_trace_hold(
            &lifetime, snapshot.viewActiveDataSource);
        snapshot.viewLive = themer_spotlight_trace_view_is_live(
            selectedView,
            &snapshot.window,
            &snapshot.windowHidden,
            &snapshot.windowAlpha,
            &snapshot.windowScene,
            &snapshot.sceneActivationState,
            &snapshot.sceneActivationStateKnown);
        snapshot.rowModel = themer_spotlight_trace_object_value(
            selectedView, "rowModel", "_rowModel");

        snapshot.carrier = themer_spotlight_image_carrier_for_view(
            selectedView);
        if (!themer_spotlight_trace_hold(&lifetime, snapshot.carrier)) {
            return false;
        }
        snapshot.carrierIcon = themer_spotlight_trace_object_value(
            snapshot.carrier, "icon", "_icon");
        snapshot.carrierIconView = themer_spotlight_trace_object_value(
            snapshot.carrier, "iconView", "_iconView");
        snapshot.carrierHidden = themer_remote_hidden(snapshot.carrier);
        snapshot.carrierAlpha = themer_remote_alpha(snapshot.carrier);
        snapshot.carrierImage = themer_spotlight_trace_object_value(
            snapshot.carrier, "image", "_image");
        snapshot.carrierDisplayedImage =
            themer_spotlight_trace_object_value(
                snapshot.carrier, "displayedImage", "_displayedImage");
        snapshot.visibleImage = r_is_objc_ptr(snapshot.carrierImage)
            ? snapshot.carrierImage : snapshot.carrierDisplayedImage;
        (void)themer_spotlight_trace_hold(
            &lifetime, snapshot.visibleImage);
        snapshot.visibleCG = themer_spotlight_trace_image_cg(
            snapshot.visibleImage);
        snapshot.carrierDisplayedImageCG =
            themer_spotlight_trace_image_cg(
                snapshot.carrierDisplayedImage);
        snapshot.carrierLayer = themer_spotlight_trace_object_value(
            snapshot.carrier, "layer", "_layer");
        snapshot.carrierLayerContents =
            themer_spotlight_trace_layer_contents(snapshot.carrierLayer);
        snapshot.delayedImageUpdate =
            themer_spotlight_trace_bool_value(
                snapshot.carrier,
                "delayedImageUpdateDueToContentVisibility");
        snapshot.cacheRequestCancellation =
            themer_spotlight_trace_object_value(
                snapshot.carrier, "cacheRequestCancellation",
                "_cacheRequestCancellation");
        snapshot.canUpdateImage = themer_spotlight_trace_bool_value(
            snapshot.carrier, "canUpdateImage");
        snapshot.isUpdatingImage = themer_spotlight_trace_bool_value(
            snapshot.carrier, "isUpdatingImage");

        snapshot.placeholderView = themer_spotlight_trace_object_value(
            selectedView, "placeholderView", "_placeholderView");
        (void)themer_spotlight_trace_hold(
            &lifetime, snapshot.placeholderView);
        snapshot.placeholderHidden =
            themer_remote_hidden(snapshot.placeholderView);
        snapshot.placeholderAlpha =
            themer_remote_alpha(snapshot.placeholderView);
        snapshot.currentIconIsPlaceholder =
            themer_spotlight_trace_bool_value(
                selectedView, "currentIconIsPlaceholder");

        snapshot.viewCache = themer_spotlight_trace_existing_cache(
            selectedView, 0, 0);
        snapshot.carrierCache = themer_spotlight_trace_existing_cache(
            0, snapshot.carrier, 0);
        snapshot.cache = r_is_objc_ptr(snapshot.carrierCache)
            ? snapshot.carrierCache : snapshot.viewCache;
        (void)themer_spotlight_trace_hold(&lifetime, snapshot.cache);
        snapshot.cacheReadImage =
            themer_spotlight_trace_cached_image_only(
                snapshot.cache, selectedIcon);
        (void)themer_spotlight_trace_hold(
            &lifetime, snapshot.cacheReadImage);
        snapshot.cacheReadCG = themer_spotlight_trace_image_cg(
            snapshot.cacheReadImage);
        snapshot.cacheReadMatchesExpected = trace->expectedCG &&
            snapshot.cacheReadCG == trace->expectedCG;
        snapshot.appearance =
            themer_spotlight_trace_existing_appearance(
                selectedView, snapshot.carrier);
        (void)themer_spotlight_trace_hold(
            &lifetime, snapshot.appearance);
        if (r_is_objc_ptr(snapshot.carrier) &&
            r_responds_main(snapshot.carrier,
                            "imageCacheRetrievalOptions")) {
            snapshot.imageCacheRetrievalOptionsKnown = true;
            snapshot.imageCacheRetrievalOptions = r_msg2_main(
                snapshot.carrier, "imageCacheRetrievalOptions",
                0, 0, 0, 0);
        }
        snapshot.renderCacheOptions =
            snapshot.imageCacheRetrievalOptions | 4ULL;
        bool renderSupported = false;
        snapshot.renderOptionsReadImage =
            themer_spotlight_trace_cached_image_with_options(
                snapshot.cache, selectedIcon, snapshot.appearance,
                snapshot.renderCacheOptions, &renderSupported);
        (void)themer_spotlight_trace_hold(
            &lifetime, snapshot.renderOptionsReadImage);
        snapshot.renderOptionsReadCG =
            themer_spotlight_trace_image_cg(
                snapshot.renderOptionsReadImage);
        snapshot.optionedCacheReadSupported = renderSupported;
        snapshot.renderOptionsReadMatchesExpected = trace->expectedCG &&
            snapshot.renderOptionsReadCG == trace->expectedCG;
        if (!renderSupported) {
            snapshot.renderOptionsReadMatchesExpected =
                snapshot.cacheReadMatchesExpected;
        }

        bool hadPrior = trace->hasSentinel || trace->hasLast;
        bool priorLive = trace->hasSentinel
            ? trace->sentinelLive : trace->last.viewLive;
        uint64_t priorView = trace->hasSentinel
            ? trace->sentinelView : trace->last.view;
        uint64_t priorRowModel = trace->hasSentinel
            ? trace->sentinelRowModel : trace->last.rowModel;
        uint64_t priorCarrier = trace->hasSentinel
            ? trace->sentinelCarrier : trace->last.carrier;
        bool presentationEpochChanged = snapshot.viewLive &&
            (!hadPrior || !priorLive || snapshot.view != priorView ||
             snapshot.rowModel != priorRowModel ||
             snapshot.carrier != priorCarrier);
        if (presentationEpochChanged) {
            trace->presentationEpoch++;
        }

        bool activeProviderMatches =
            r_is_objc_ptr(snapshot.providerApplication) &&
            snapshot.viewActiveDataSource ==
                snapshot.providerApplication;
        bool cacheThemed = snapshot.cacheReadMatchesExpected ||
            snapshot.renderOptionsReadMatchesExpected;
        bool displayedThemed = trace->expectedCG &&
            snapshot.carrierDisplayedImageCG == trace->expectedCG;
        bool layerThemed = trace->expectedCG &&
            snapshot.carrierLayerContents == trace->expectedCG;
        bool carrierVisible = snapshot.carrierHidden != 1 &&
            snapshot.carrierAlpha > 0.01;
        bool placeholderVisible =
            r_is_objc_ptr(snapshot.placeholderView) &&
            snapshot.placeholderHidden != 1 &&
            snapshot.placeholderAlpha > 0.01;
        const char *classification = "presentation-other";
        if (!snapshot.viewLive) {
            classification = "target-view-inactive";
        } else if (!snapshot.viewIconMatchesCanonical) {
            classification = "model-icon-replaced";
        } else if (!activeProviderMatches) {
            classification = "provider-entry-rebound";
        } else if (!snapshot.cacheReadCG &&
                   !snapshot.renderOptionsReadCG) {
            classification = "cache-miss";
        } else if (!cacheThemed) {
            classification = "cache-stock";
        } else if (!displayedThemed) {
            classification = "carrier-overwrite";
        } else if (!layerThemed) {
            classification = "layer-overwrite";
        } else if (!carrierVisible && placeholderVisible) {
            classification = "placeholder-takeover";
        } else if (carrierVisible && !placeholderVisible) {
            classification = "themed-visible";
        }

        printf("[SPOTLIGHT_FAST] sample=%llu phase=%s "
               "classification=%s live=%d scene=%lld/%d "
               "view=0x%llx rowModel=0x%llx epoch=%llu "
               "viewIcon=0x%llx canonical=0x%llx same=%d "
               "activeDataSource=0x%llx providerEntry=0x%llx same=%d "
               "cache=0x%llx image=0x%llx cg=0x%llx/match:%d "
               "renderCG=0x%llx/match:%d "
               "carrier=0x%llx displayed=0x%llx/cg:0x%llx/match:%d "
               "layer=0x%llx/contents:0x%llx/match:%d "
               "carrierPresentation={hidden:%d,alpha:%.2f,visible:%d} "
               "placeholder=0x%llx/{hidden:%d,alpha:%.2f,visible:%d} "
               "logicalPlaceholder=%d renderer={delayed:%d,can:%d,"
               "updating:%d,request:0x%llx}\n",
               (unsigned long long)sampleIndex,
               phase && phase[0] ? phase : "sentinel",
               classification,
               snapshot.viewLive,
               (long long)snapshot.sceneActivationState,
               snapshot.sceneActivationStateKnown,
               (unsigned long long)snapshot.view,
               (unsigned long long)snapshot.rowModel,
               (unsigned long long)trace->presentationEpoch,
               (unsigned long long)snapshot.viewIcon,
               (unsigned long long)snapshot.canonicalIcon,
               snapshot.viewIconMatchesCanonical,
               (unsigned long long)snapshot.viewActiveDataSource,
               (unsigned long long)snapshot.providerApplication,
               activeProviderMatches,
               (unsigned long long)snapshot.cache,
               (unsigned long long)snapshot.cacheReadImage,
               (unsigned long long)snapshot.cacheReadCG,
               snapshot.cacheReadMatchesExpected,
               (unsigned long long)snapshot.renderOptionsReadCG,
               snapshot.renderOptionsReadMatchesExpected,
               (unsigned long long)snapshot.carrier,
               (unsigned long long)snapshot.carrierDisplayedImage,
               (unsigned long long)snapshot.carrierDisplayedImageCG,
               displayedThemed,
               (unsigned long long)snapshot.carrierLayer,
               (unsigned long long)snapshot.carrierLayerContents,
               layerThemed,
               snapshot.carrierHidden,
               snapshot.carrierAlpha,
               carrierVisible,
               (unsigned long long)snapshot.placeholderView,
               snapshot.placeholderHidden,
               snapshot.placeholderAlpha,
               placeholderVisible,
               snapshot.currentIconIsPlaceholder,
               snapshot.delayedImageUpdate,
               snapshot.canUpdateImage,
               snapshot.isUpdatingImage,
               (unsigned long long)snapshot.cacheRequestCancellation);

        if (remote_call_current_success()) {
            (void)themer_spotlight_trace_try_reveal_themed_carrier(
                trace, &snapshot, sampleIndex);
        }

        trace->sentinelView = snapshot.view;
        trace->sentinelRowModel = snapshot.rowModel;
        trace->sentinelCarrier = snapshot.carrier;
        trace->sentinelLive = snapshot.viewLive;
        trace->hasSentinel = true;
        return remote_call_current_success();
    } @finally {
        themer_spotlight_trace_release_all(&lifetime);
        r_settle_us(previousSettleUS);
    }
}

uint64_t themer_spotlight_remote_autorelease_pool_push(void)
{
    return r_dlsym_call(R_TIMEOUT, "objc_autoreleasePoolPush",
                        0, 0, 0, 0, 0, 0, 0, 0);
}

void themer_spotlight_remote_autorelease_pool_pop(uint64_t token)
{
    if (!token || !remote_call_current_success()) return;
    r_dlsym_call(R_TIMEOUT, "objc_autoreleasePoolPop",
                 token, 0, 0, 0, 0, 0, 0, 0);
}

bool themer_spotlight_lifecycle_trace_sample_in_session(const char *phase,
                                                        bool forceLog)
{
    ThemerSpotlightLifecycleTrace *trace =
        &gThemerSpotlightLifecycleTrace;
    if (!trace->armed) return false;

    int currentPID = remote_call_current_pid();
    if (currentPID != trace->pid) {
        printf("[SPOTLIGHT_TRACE] rejected phase=%s reason=session-pid-changed "
               "expected=%d actual=%d\n",
               phase && phase[0] ? phase : "sample",
               trace->pid,
               currentPID);
        return false;
    }

    // The normal Remote ObjC settle is intentionally conservative (50 ms).
    // A lifecycle snapshot performs many tiny reads, so scope a 1 ms settle to
    // this serialized sample and always restore the caller's value.
    uint32_t previousSettleUS = r_settle_us(1000);
    ThemerSpotlightTraceLifetime lifetime = {0};
    @try {
        ThemerSpotlightLifecycleSnapshot snapshot = {0};
        if (!themer_spotlight_lifecycle_trace_capture(&snapshot,
                                                       &lifetime)) {
            printf("[SPOTLIGHT_TRACE] sample-failed phase=%s reason=transport "
                   "sample=%llu\n",
                   phase && phase[0] ? phase : "sample",
                   (unsigned long long)trace->sampleIndex);
            return false;
        }

    NSMutableArray<NSString *> *changes = [NSMutableArray array];
    if (trace->hasLast) {
#define THEMER_SPOTLIGHT_TRACE_CHANGE(field, label) \
        do { \
            if (snapshot.field != trace->last.field) { \
                [changes addObject:@label]; \
            } \
        } while (0)
        THEMER_SPOTLIGHT_TRACE_CHANGE(owner, "owner");
        THEMER_SPOTLIGHT_TRACE_CHANGE(dataSource, "dataSource");
        THEMER_SPOTLIGHT_TRACE_CHANGE(iconModel, "iconModel");
        THEMER_SPOTLIGHT_TRACE_CHANGE(modelIconStorage,
                                      "modelIconStorage");
        THEMER_SPOTLIGHT_TRACE_CHANGE(modelIconSource,
                                      "modelIconSource");
        THEMER_SPOTLIGHT_TRACE_CHANGE(providerApplications,
                                      "providerApplications");
        THEMER_SPOTLIGHT_TRACE_CHANGE(providerTrackedBundleIDs,
                                      "providerTrackedBundleIDs");
        THEMER_SPOTLIGHT_TRACE_CHANGE(providerApplication,
                                      "providerApplication");
        THEMER_SPOTLIGHT_TRACE_CHANGE(providerTrackedKnown,
                                      "providerTrackedKnown");
        THEMER_SPOTLIGHT_TRACE_CHANGE(providerTracked,
                                      "providerTracked");
        THEMER_SPOTLIGHT_TRACE_CHANGE(viewFound, "viewFound");
        THEMER_SPOTLIGHT_TRACE_CHANGE(view, "view");
        THEMER_SPOTLIGHT_TRACE_CHANGE(viewLive, "viewLive");
        THEMER_SPOTLIGHT_TRACE_CHANGE(window, "window");
        THEMER_SPOTLIGHT_TRACE_CHANGE(windowHidden, "windowHidden");
        THEMER_SPOTLIGHT_TRACE_CHANGE(windowAlpha, "windowAlpha");
        THEMER_SPOTLIGHT_TRACE_CHANGE(windowScene, "windowScene");
        THEMER_SPOTLIGHT_TRACE_CHANGE(sceneActivationStateKnown,
                                      "sceneStateKnown");
        THEMER_SPOTLIGHT_TRACE_CHANGE(sceneActivationState, "sceneState");
        THEMER_SPOTLIGHT_TRACE_CHANGE(rowModel, "rowModel");
        THEMER_SPOTLIGHT_TRACE_CHANGE(variantKnown, "variantKnown");
        THEMER_SPOTLIGHT_TRACE_CHANGE(variant, "variant");
        THEMER_SPOTLIGHT_TRACE_CHANGE(viewIcon, "viewIcon");
        THEMER_SPOTLIGHT_TRACE_CHANGE(canonicalIcon, "canonicalIcon");
        THEMER_SPOTLIGHT_TRACE_CHANGE(viewIconMatchesCanonical,
                                      "viewIcon==canonical");
        THEMER_SPOTLIGHT_TRACE_CHANGE(modelContainsViewIconKnown,
                                      "modelContainsKnown");
        THEMER_SPOTLIGHT_TRACE_CHANGE(modelContainsViewIcon,
                                      "modelContainsViewIcon");
        THEMER_SPOTLIGHT_TRACE_CHANGE(viewActiveDataSource,
                                      "viewActiveDataSource");
        THEMER_SPOTLIGHT_TRACE_CHANGE(canonicalActiveDataSource,
                                      "canonicalActiveDataSource");
        THEMER_SPOTLIGHT_TRACE_CHANGE(viewIconDataSources,
                                      "viewIconDataSources");
        THEMER_SPOTLIGHT_TRACE_CHANGE(viewIconDataSourceCountKnown,
                                      "viewIconDataSourceCountKnown");
        THEMER_SPOTLIGHT_TRACE_CHANGE(viewIconDataSourceCount,
