        THEMER_SPOTLIGHT_TRACE_CHANGE(cacheObservesViewIcon,
                                      "cacheObservesViewIcon");
        THEMER_SPOTLIGHT_TRACE_CHANGE(cacheObservesCarrierKnown,
                                      "cacheObservesCarrierKnown");
        THEMER_SPOTLIGHT_TRACE_CHANGE(cacheObservesCarrier,
                                      "cacheObservesCarrier");
        THEMER_SPOTLIGHT_TRACE_CHANGE(cacheObservesViewKnown,
                                      "cacheObservesViewKnown");
        THEMER_SPOTLIGHT_TRACE_CHANGE(cacheObservesView,
                                      "cacheObservesView");
        THEMER_SPOTLIGHT_TRACE_CHANGE(appearance, "appearance");
        THEMER_SPOTLIGHT_TRACE_CHANGE(requestedAppearance,
                                      "requestedAppearance");
        THEMER_SPOTLIGHT_TRACE_CHANGE(displayedAppearance,
                                      "displayedAppearance");
        THEMER_SPOTLIGHT_TRACE_CHANGE(currentGenerationKnown,
