                                      "displayedImage");
        THEMER_SPOTLIGHT_TRACE_CHANGE(carrierDisplayedImageCG,
                                      "displayedImageCG");
        THEMER_SPOTLIGHT_TRACE_CHANGE(carrierContentsImage,
                                      "contentsImage");
        THEMER_SPOTLIGHT_TRACE_CHANGE(carrierContentsImageCG,
                                      "contentsImageCG");
        THEMER_SPOTLIGHT_TRACE_CHANGE(carrierSquareContentsImage,
                                      "squareContentsImage");
        THEMER_SPOTLIGHT_TRACE_CHANGE(carrierSquareContentsImageCG,
                                      "squareContentsImageCG");
        THEMER_SPOTLIGHT_TRACE_CHANGE(carrierLayer, "carrierLayer");
        THEMER_SPOTLIGHT_TRACE_CHANGE(carrierLayerContents,
                                      "carrierLayer.contents");
        THEMER_SPOTLIGHT_TRACE_CHANGE(contentsLayerView,
                                      "contentsLayerView");
        THEMER_SPOTLIGHT_TRACE_CHANGE(contentsLayer,
                                      "contentsLayer");
        THEMER_SPOTLIGHT_TRACE_CHANGE(contentsLayerContents,
                                      "contentsLayer.contents");
        THEMER_SPOTLIGHT_TRACE_CHANGE(alternateContentsLayer,
                                      "alternateContentsLayer");
        THEMER_SPOTLIGHT_TRACE_CHANGE(alternateContentsLayerContents,
                                      "alternateContentsLayer.contents");
        THEMER_SPOTLIGHT_TRACE_CHANGE(iconLayerView, "iconLayerView");
        THEMER_SPOTLIGHT_TRACE_CHANGE(iconLayer, "iconLayer");
        THEMER_SPOTLIGHT_TRACE_CHANGE(iconLayerContents,
