        THEMER_SPOTLIGHT_TRACE_CHANGE(iconForImage, "iconForImage");
        THEMER_SPOTLIGHT_TRACE_CHANGE(requestedImageIdentity,
                                      "requestedIdentity");
        THEMER_SPOTLIGHT_TRACE_CHANGE(requestedIdentityMatchesDesired,
                                      "requested==desired");
        THEMER_SPOTLIGHT_TRACE_CHANGE(displayedIdentityMatchesDesired,
                                      "displayed==desired");
        THEMER_SPOTLIGHT_TRACE_CHANGE(displayingImageLayer,
                                      "displayingImageLayer");
        THEMER_SPOTLIGHT_TRACE_CHANGE(displayingRealImageContents,
                                      "displayingRealContents");
        THEMER_SPOTLIGHT_TRACE_CHANGE(shouldDisplayImageLayer,
                                      "shouldDisplayImageLayer");
        THEMER_SPOTLIGHT_TRACE_CHANGE(delayedImageUpdate,
                                      "delayedImageUpdate");
        THEMER_SPOTLIGHT_TRACE_CHANGE(cacheRequestCancellation,
                                      "cacheRequestCancellation");
        THEMER_SPOTLIGHT_TRACE_CHANGE(canUpdateImage,
                                      "canUpdateImage");
        THEMER_SPOTLIGHT_TRACE_CHANGE(isUpdatingImage,
                                      "isUpdatingImage");
        THEMER_SPOTLIGHT_TRACE_CHANGE(contentVisibilityKnown,
                                      "contentVisibilityKnown");
        THEMER_SPOTLIGHT_TRACE_CHANGE(contentVisibility,
                                      "contentVisibility");
        THEMER_SPOTLIGHT_TRACE_CHANGE(carrierHidden, "carrierHidden");
        THEMER_SPOTLIGHT_TRACE_CHANGE(carrierAlpha, "carrierAlpha");
        THEMER_SPOTLIGHT_TRACE_CHANGE(placeholderView,
                                      "placeholderView");
        THEMER_SPOTLIGHT_TRACE_CHANGE(placeholderImage,
                                      "placeholderImage");
        THEMER_SPOTLIGHT_TRACE_CHANGE(placeholderImageCG,
                                      "placeholderImageCG");
        THEMER_SPOTLIGHT_TRACE_CHANGE(placeholderLayer,
                                      "placeholderLayer");
        THEMER_SPOTLIGHT_TRACE_CHANGE(placeholderLayerContents,
                                      "placeholderLayer.contents");
        THEMER_SPOTLIGHT_TRACE_CHANGE(placeholderHidden,
                                      "placeholderHidden");
        THEMER_SPOTLIGHT_TRACE_CHANGE(placeholderAlpha,
                                      "placeholderAlpha");
        THEMER_SPOTLIGHT_TRACE_CHANGE(currentIconIsPlaceholder,
                                      "currentIconIsPlaceholder");
        THEMER_SPOTLIGHT_TRACE_CHANGE(visibleImage, "visibleImage");
        THEMER_SPOTLIGHT_TRACE_CHANGE(visibleCG, "visibleCG");
        THEMER_SPOTLIGHT_TRACE_CHANGE(cacheReadImage, "cacheReadImage");
        THEMER_SPOTLIGHT_TRACE_CHANGE(cacheReadCG, "cacheReadCG");
        THEMER_SPOTLIGHT_TRACE_CHANGE(cacheReadSelector,
                                      "cacheReadSelector");
        THEMER_SPOTLIGHT_TRACE_CHANGE(cacheReadMatchesExpected,
                                      "cacheReadMatchesExpected");
        THEMER_SPOTLIGHT_TRACE_CHANGE(imageCacheRetrievalOptionsKnown,
                                      "retrievalOptionsKnown");
        THEMER_SPOTLIGHT_TRACE_CHANGE(imageCacheRetrievalOptions,
                                      "retrievalOptions");
        THEMER_SPOTLIGHT_TRACE_CHANGE(renderCacheOptions,
                                      "renderOptions");
        THEMER_SPOTLIGHT_TRACE_CHANGE(optionedCacheReadSupported,
                                      "optionedCacheReadSupported");
        THEMER_SPOTLIGHT_TRACE_CHANGE(optionsZeroReadImage,
                                      "options0Image");
        THEMER_SPOTLIGHT_TRACE_CHANGE(optionsZeroReadCG,
                                      "options0CG");
        THEMER_SPOTLIGHT_TRACE_CHANGE(optionsZeroReadMatchesExpected,
                                      "options0MatchesExpected");
        THEMER_SPOTLIGHT_TRACE_CHANGE(renderOptionsReadImage,
                                      "renderOptionsImage");
        THEMER_SPOTLIGHT_TRACE_CHANGE(renderOptionsReadCG,
                                      "renderOptionsCG");
        THEMER_SPOTLIGHT_TRACE_CHANGE(renderOptionsReadMatchesExpected,
                                      "renderOptionsMatchesExpected");
#undef THEMER_SPOTLIGHT_TRACE_CHANGE
    }

    if (!trace->firstVisibleCG && snapshot.visibleCG) {
        trace->firstVisibleCG = snapshot.visibleCG;
    }
    bool visibleMatchesExpected = trace->expectedCG &&
                                  snapshot.visibleCG == trace->expectedCG;
    if (!trace->themedVisibleCG && visibleMatchesExpected) {
        trace->themedVisibleCG = snapshot.visibleCG;
    }
    bool visibleMatchesFirst = trace->firstVisibleCG &&
                               snapshot.visibleCG == trace->firstVisibleCG;
    bool visibleMatchesThemed = trace->themedVisibleCG &&
                                snapshot.visibleCG == trace->themedVisibleCG;
    bool viewReturned = trace->hasLast &&
                        !trace->last.viewLive && snapshot.viewLive;
    bool presentationEpochChanged = snapshot.viewLive &&
        (!trace->hasLast || !trace->last.viewLive ||
         snapshot.view != trace->last.view ||
         snapshot.carrier != trace->last.carrier ||
         snapshot.rowModel != trace->last.rowModel);
    if (presentationEpochChanged) {
        trace->presentationEpoch++;
    }
    bool samePriorView = trace->hasLastLive &&
                         snapshot.view == trace->lastLive.view;
    bool samePriorViewIcon = trace->hasLastLive &&
                             snapshot.viewIcon == trace->lastLive.viewIcon;
    bool samePriorCanonical = trace->hasLastLive &&
                              snapshot.canonicalIcon ==
                                  trace->lastLive.canonicalIcon;
    bool samePriorCache = trace->hasLastLive &&
                          snapshot.cache == trace->lastLive.cache;
    bool samePriorMasked = trace->hasLastLive &&
                           snapshot.maskedCache == trace->lastLive.maskedCache;
    bool samePriorUnmasked = trace->hasLastLive &&
                             snapshot.unmaskedCache ==
                                 trace->lastLive.unmaskedCache;

    uint64_t sampleIndex = trace->sampleIndex++;
    bool baseline = !trace->hasLast;
    bool heartbeat = !baseline && changes.count == 0 &&
                     (sampleIndex % 4ULL) == 0;
    bool shouldLog = baseline || changes.count > 0 || forceLog || heartbeat;
    bool transportOK = remote_call_current_success();

    if (shouldLog) {
        char ownerClass[96] = {0};
        char dataSourceClass[96] = {0};
        char iconModelClass[96] = {0};
        char modelIconStorageClass[96] = {0};
        char providerApplicationsClass[96] = {0};
        char providerTrackedClass[96] = {0};
        char providerApplicationClass[96] = {0};
        char viewClass[96] = {0};
        char viewIconClass[96] = {0};
        char canonicalClass[96] = {0};
        char viewActiveDataSourceClass[96] = {0};
        char canonicalActiveDataSourceClass[96] = {0};
        char viewIconDataSourcesClass[96] = {0};
        char cacheClass[96] = {0};
        char maskedCacheClass[96] = {0};
        char unmaskedCacheClass[96] = {0};
        char cacheObservedIconsClass[96] = {0};
        char carrierClass[96] = {0};
        char placeholderClass[96] = {0};
#define THEMER_SPOTLIGHT_TRACE_CLASS(object, buffer) \
        do { \
            if (remote_call_current_success()) { \
                themer_read_class_name((object), (buffer), sizeof(buffer)); \
            } \
        } while (0)
        THEMER_SPOTLIGHT_TRACE_CLASS(snapshot.owner, ownerClass);
        THEMER_SPOTLIGHT_TRACE_CLASS(snapshot.dataSource, dataSourceClass);
        THEMER_SPOTLIGHT_TRACE_CLASS(snapshot.iconModel, iconModelClass);
        THEMER_SPOTLIGHT_TRACE_CLASS(snapshot.modelIconStorage,
                                     modelIconStorageClass);
        THEMER_SPOTLIGHT_TRACE_CLASS(snapshot.providerApplications,
                                     providerApplicationsClass);
        THEMER_SPOTLIGHT_TRACE_CLASS(snapshot.providerTrackedBundleIDs,
                                     providerTrackedClass);
        THEMER_SPOTLIGHT_TRACE_CLASS(snapshot.providerApplication,
                                     providerApplicationClass);
        THEMER_SPOTLIGHT_TRACE_CLASS(snapshot.view, viewClass);
        THEMER_SPOTLIGHT_TRACE_CLASS(snapshot.viewIcon, viewIconClass);
        THEMER_SPOTLIGHT_TRACE_CLASS(snapshot.canonicalIcon, canonicalClass);
        THEMER_SPOTLIGHT_TRACE_CLASS(snapshot.viewActiveDataSource,
                                     viewActiveDataSourceClass);
        THEMER_SPOTLIGHT_TRACE_CLASS(snapshot.canonicalActiveDataSource,
                                     canonicalActiveDataSourceClass);
        THEMER_SPOTLIGHT_TRACE_CLASS(snapshot.viewIconDataSources,
                                     viewIconDataSourcesClass);
        THEMER_SPOTLIGHT_TRACE_CLASS(snapshot.cache, cacheClass);
        THEMER_SPOTLIGHT_TRACE_CLASS(snapshot.maskedCache, maskedCacheClass);
        THEMER_SPOTLIGHT_TRACE_CLASS(snapshot.unmaskedCache,
                                     unmaskedCacheClass);
        THEMER_SPOTLIGHT_TRACE_CLASS(snapshot.cacheObservedIcons,
                                     cacheObservedIconsClass);
        THEMER_SPOTLIGHT_TRACE_CLASS(snapshot.carrier, carrierClass);
        THEMER_SPOTLIGHT_TRACE_CLASS(snapshot.placeholderView,
                                     placeholderClass);
#undef THEMER_SPOTLIGHT_TRACE_CLASS

        NSString *changeList = changes.count > 0
            ? [changes componentsJoinedByString:@","] : @"-";
        const char *event = baseline ? "baseline"
                          : changes.count > 0 ? "change"
                          : heartbeat ? "heartbeat" : "forced";
        const char *variantSource = snapshot.variantKnown ? "view"
                                  : trace->variantHintKnown ? "hint"
                                  : "unknown";
        const char *suspect = baseline ? "baseline" : "stable";
        if (trace->hasLast) {
            if (snapshot.owner != trace->last.owner) {
                suspect = "owner-replaced";
            } else if (snapshot.dataSource != trace->last.dataSource ||
                       snapshot.iconModel != trace->last.iconModel ||
                       snapshot.modelIconStorage !=
                           trace->last.modelIconStorage ||
                       snapshot.providerApplications !=
                           trace->last.providerApplications ||
                       snapshot.providerTrackedBundleIDs !=
                           trace->last.providerTrackedBundleIDs) {
                suspect = "model-reset";
            } else if (snapshot.viewFound != trace->last.viewFound ||
                       snapshot.view != trace->last.view ||
                       snapshot.viewLive != trace->last.viewLive ||
                       snapshot.window != trace->last.window ||
                       snapshot.windowScene != trace->last.windowScene ||
                       snapshot.sceneActivationState !=
                           trace->last.sceneActivationState ||
                       snapshot.rowModel != trace->last.rowModel) {
                suspect = "view-lifecycle";
            } else if (snapshot.viewIcon != trace->last.viewIcon ||
                       snapshot.canonicalIcon != trace->last.canonicalIcon ||
                       snapshot.viewActiveDataSource !=
                           trace->last.viewActiveDataSource ||
                       snapshot.canonicalActiveDataSource !=
                           trace->last.canonicalActiveDataSource ||
                       snapshot.providerApplication !=
                           trace->last.providerApplication ||
                       snapshot.providerTrackedKnown !=
                           trace->last.providerTrackedKnown ||
                       snapshot.providerTracked !=
                           trace->last.providerTracked ||
                       snapshot.modelContainsViewIconKnown !=
                           trace->last.modelContainsViewIconKnown ||
                       snapshot.modelContainsViewIcon !=
                           trace->last.modelContainsViewIcon ||
                       snapshot.viewIconDataSources !=
                           trace->last.viewIconDataSources ||
                       snapshot.viewIconDataSourceCountKnown !=
                           trace->last.viewIconDataSourceCountKnown ||
                       snapshot.viewIconDataSourceCount !=
                           trace->last.viewIconDataSourceCount) {
                suspect = "icon-provider";
            } else if (snapshot.cache != trace->last.cache ||
                       snapshot.maskedCache != trace->last.maskedCache ||
                       snapshot.unmaskedCache != trace->last.unmaskedCache ||
                       snapshot.cacheObservedIcons !=
                           trace->last.cacheObservedIcons ||
                       snapshot.cacheObservers !=
                           trace->last.cacheObservers) {
                suspect = "cache-replaced";
            } else if (snapshot.viewCache != trace->last.viewCache ||
                       snapshot.carrierCache != trace->last.carrierCache ||
                       snapshot.iconCache != trace->last.iconCache ||
                       snapshot.cacheObserverCountKnown !=
                           trace->last.cacheObserverCountKnown ||
                       snapshot.cacheObserverCount !=
                           trace->last.cacheObserverCount ||
                       snapshot.cacheObservesCarrierKnown !=
                           trace->last.cacheObservesCarrierKnown ||
                       snapshot.cacheObservesCarrier !=
                           trace->last.cacheObservesCarrier ||
                       snapshot.cacheObservesViewKnown !=
                           trace->last.cacheObservesViewKnown ||
                       snapshot.cacheObservesView !=
                           trace->last.cacheObservesView) {
                suspect = "cache-binding";
            } else if (snapshot.currentGeneration !=
                           trace->last.currentGeneration ||
                       snapshot.maskedStoredGeneration !=
                           trace->last.maskedStoredGeneration ||
                       snapshot.unmaskedStoredGeneration !=
                           trace->last.unmaskedStoredGeneration ||
                       snapshot.cacheObservesViewIconKnown !=
                           trace->last.cacheObservesViewIconKnown ||
                       snapshot.cacheObservesViewIcon !=
                           trace->last.cacheObservesViewIcon) {
                suspect = "cache-generation";
            } else if (snapshot.appearance != trace->last.appearance ||
                       snapshot.cacheReadImage !=
                           trace->last.cacheReadImage ||
                       snapshot.cacheReadCG != trace->last.cacheReadCG ||
                       snapshot.cacheReadSelector !=
                           trace->last.cacheReadSelector ||
                       snapshot.cacheReadMatchesExpected !=
                           trace->last.cacheReadMatchesExpected ||
                       snapshot.imageCacheRetrievalOptionsKnown !=
                           trace->last.imageCacheRetrievalOptionsKnown ||
                       snapshot.imageCacheRetrievalOptions !=
                           trace->last.imageCacheRetrievalOptions ||
                       snapshot.renderCacheOptions !=
                           trace->last.renderCacheOptions ||
                       snapshot.optionedCacheReadSupported !=
                           trace->last.optionedCacheReadSupported ||
                       snapshot.optionsZeroReadImage !=
                           trace->last.optionsZeroReadImage ||
                       snapshot.optionsZeroReadCG !=
                           trace->last.optionsZeroReadCG ||
                       snapshot.optionsZeroReadMatchesExpected !=
                           trace->last.optionsZeroReadMatchesExpected ||
                       snapshot.renderOptionsReadImage !=
                           trace->last.renderOptionsReadImage ||
                       snapshot.renderOptionsReadCG !=
                           trace->last.renderOptionsReadCG ||
                       snapshot.renderOptionsReadMatchesExpected !=
                           trace->last.renderOptionsReadMatchesExpected) {
                suspect = "cache-content";
            } else if (snapshot.carrier != trace->last.carrier ||
                       snapshot.carrierIcon != trace->last.carrierIcon ||
                       snapshot.carrierIconView !=
                           trace->last.carrierIconView ||
                       snapshot.carrierImage !=
                           trace->last.carrierImage ||
                       snapshot.carrierImageCG !=
                           trace->last.carrierImageCG ||
                       snapshot.carrierDisplayedImage !=
                           trace->last.carrierDisplayedImage ||
                       snapshot.carrierDisplayedImageCG !=
                           trace->last.carrierDisplayedImageCG ||
                       snapshot.carrierContentsImage !=
                           trace->last.carrierContentsImage ||
                       snapshot.carrierContentsImageCG !=
                           trace->last.carrierContentsImageCG ||
                       snapshot.carrierSquareContentsImage !=
                           trace->last.carrierSquareContentsImage ||
                       snapshot.carrierSquareContentsImageCG !=
                           trace->last.carrierSquareContentsImageCG ||
                       snapshot.carrierLayer != trace->last.carrierLayer ||
                       snapshot.carrierLayerContents !=
                           trace->last.carrierLayerContents ||
                       snapshot.contentsLayerView !=
                           trace->last.contentsLayerView ||
                       snapshot.contentsLayer !=
                           trace->last.contentsLayer ||
                       snapshot.contentsLayerContents !=
                           trace->last.contentsLayerContents ||
                       snapshot.alternateContentsLayer !=
                           trace->last.alternateContentsLayer ||
                       snapshot.alternateContentsLayerContents !=
                           trace->last.alternateContentsLayerContents ||
                       snapshot.iconLayerView != trace->last.iconLayerView ||
                       snapshot.iconLayer != trace->last.iconLayer ||
                       snapshot.iconLayerContents !=
                           trace->last.iconLayerContents ||
                       snapshot.requestedImageIdentity !=
                           trace->last.requestedImageIdentity ||
                       snapshot.requestedIdentityMatchesDesired !=
                           trace->last.requestedIdentityMatchesDesired ||
                       snapshot.displayedIdentityMatchesDesired !=
                           trace->last.displayedIdentityMatchesDesired ||
                       snapshot.displayingImageLayer !=
                           trace->last.displayingImageLayer ||
                       snapshot.displayingRealImageContents !=
                           trace->last.displayingRealImageContents ||
                       snapshot.shouldDisplayImageLayer !=
                           trace->last.shouldDisplayImageLayer ||
                       snapshot.delayedImageUpdate !=
                           trace->last.delayedImageUpdate ||
                       snapshot.cacheRequestCancellation !=
                           trace->last.cacheRequestCancellation ||
                       snapshot.canUpdateImage !=
                           trace->last.canUpdateImage ||
                       snapshot.isUpdatingImage !=
                           trace->last.isUpdatingImage ||
                       snapshot.contentVisibilityKnown !=
                           trace->last.contentVisibilityKnown ||
                       snapshot.contentVisibility !=
                           trace->last.contentVisibility ||
                       snapshot.requestedAppearance !=
                           trace->last.requestedAppearance ||
                       snapshot.displayedAppearance !=
                           trace->last.displayedAppearance ||
                       snapshot.carrierHidden !=
                           trace->last.carrierHidden ||
                       snapshot.carrierAlpha !=
                           trace->last.carrierAlpha ||
                       snapshot.placeholderView !=
                           trace->last.placeholderView ||
                       snapshot.placeholderImage !=
                           trace->last.placeholderImage ||
                       snapshot.placeholderImageCG !=
                           trace->last.placeholderImageCG ||
                       snapshot.placeholderLayer !=
                           trace->last.placeholderLayer ||
                       snapshot.placeholderLayerContents !=
                           trace->last.placeholderLayerContents ||
                       snapshot.placeholderHidden !=
                           trace->last.placeholderHidden ||
                       snapshot.placeholderAlpha !=
                           trace->last.placeholderAlpha ||
                       snapshot.currentIconIsPlaceholder !=
                           trace->last.currentIconIsPlaceholder ||
                       snapshot.visibleImage != trace->last.visibleImage ||
                       snapshot.visibleCG != trace->last.visibleCG) {
                suspect = "carrier-render";
            }
        }
        uint64_t elapsedMS = (themer_now_us() - trace->startedUS) / 1000ULL;

        printf("[SPOTLIGHT_TRACE] sample=%llu phase=%s elapsedMS=%llu "
               "event=%s suspect=%s changes=%s transportOK=%d "
               "owner=0x%llx/%s dataSource=0x%llx/%s "
               "iconModel=0x%llx/%s modelStorage=0x%llx/%s "
               "modelIconSource=%d viewFound=%d view=0x%llx/%s "
               "live=%d window=0x%llx hidden=%d alpha=%.2f "
               "scene=0x%llx activation=%lld/%d rowModel=0x%llx "
               "presentationEpoch=%llu variant=%llu variantKnown=%d "
               "variantSource=%s\n",
               (unsigned long long)sampleIndex,
               phase && phase[0] ? phase : "sample",
               (unsigned long long)elapsedMS,
               event,
               suspect,
               changeList.UTF8String,
               transportOK,
               (unsigned long long)snapshot.owner,
               ownerClass[0] ? ownerClass : "-",
               (unsigned long long)snapshot.dataSource,
               dataSourceClass[0] ? dataSourceClass : "-",
               (unsigned long long)snapshot.iconModel,
               iconModelClass[0] ? iconModelClass : "-",
               (unsigned long long)snapshot.modelIconStorage,
               modelIconStorageClass[0] ? modelIconStorageClass : "-",
               snapshot.modelIconSource,
               snapshot.viewFound,
               (unsigned long long)snapshot.view,
               viewClass[0] ? viewClass : "-",
               snapshot.viewLive,
               (unsigned long long)snapshot.window,
               snapshot.windowHidden,
               snapshot.windowAlpha,
               (unsigned long long)snapshot.windowScene,
               (long long)snapshot.sceneActivationState,
               snapshot.sceneActivationStateKnown,
               (unsigned long long)snapshot.rowModel,
               (unsigned long long)trace->presentationEpoch,
               (unsigned long long)snapshot.variant,
               snapshot.variantKnown,
               variantSource);

        printf("[SPOTLIGHT_TRACE] render sample=%llu "
               "viewIcon=0x%llx/%s canonicalIcon=0x%llx/%s same=%d "
               "viewActiveDataSource=0x%llx/%s "
               "canonicalActiveDataSource=0x%llx/%s cache=0x%llx/%s "
               "masked=0x%llx/%s unmasked=0x%llx/%s appearance=0x%llx "
               "observedIcons=0x%llx/%s observesViewIcon=%d/%d "
               "generation=%llu/%d generationIcon=0x%llx "
               "maskedStored=%llu/%d "
               "unmaskedStored=%llu/%d carrier=0x%llx "
               "visibleImage=0x%llx visibleCG=0x%llx "
               "expectedCG=0x%llx firstCG=0x%llx themedCG=0x%llx "
               "sameExpectedCGIdentity=%d sameFirstCGIdentity=%d "
               "sameThemedCGIdentity=%d "
               "returned=%d priorLive=%d "
               "samePrior={view:%d,icon:%d,canonical:%d,cache:%d,"
               "masked:%d,unmasked:%d}\n",
               (unsigned long long)sampleIndex,
               (unsigned long long)snapshot.viewIcon,
               viewIconClass[0] ? viewIconClass : "-",
               (unsigned long long)snapshot.canonicalIcon,
               canonicalClass[0] ? canonicalClass : "-",
               snapshot.viewIconMatchesCanonical,
               (unsigned long long)snapshot.viewActiveDataSource,
               viewActiveDataSourceClass[0]
                   ? viewActiveDataSourceClass : "-",
               (unsigned long long)snapshot.canonicalActiveDataSource,
               canonicalActiveDataSourceClass[0]
                   ? canonicalActiveDataSourceClass : "-",
               (unsigned long long)snapshot.cache,
               cacheClass[0] ? cacheClass : "-",
               (unsigned long long)snapshot.maskedCache,
               maskedCacheClass[0] ? maskedCacheClass : "-",
               (unsigned long long)snapshot.unmaskedCache,
               unmaskedCacheClass[0] ? unmaskedCacheClass : "-",
               (unsigned long long)snapshot.appearance,
               (unsigned long long)snapshot.cacheObservedIcons,
               cacheObservedIconsClass[0]
                   ? cacheObservedIconsClass : "-",
               snapshot.cacheObservesViewIcon,
               snapshot.cacheObservesViewIconKnown,
               (unsigned long long)snapshot.currentGeneration,
               snapshot.currentGenerationKnown,
               (unsigned long long)snapshot.viewIcon,
               (unsigned long long)snapshot.maskedStoredGeneration,
               snapshot.maskedStoredGenerationKnown,
               (unsigned long long)snapshot.unmaskedStoredGeneration,
               snapshot.unmaskedStoredGenerationKnown,
               (unsigned long long)snapshot.carrier,
               (unsigned long long)snapshot.visibleImage,
               (unsigned long long)snapshot.visibleCG,
               (unsigned long long)trace->expectedCG,
               (unsigned long long)trace->firstVisibleCG,
               (unsigned long long)trace->themedVisibleCG,
               visibleMatchesExpected,
               visibleMatchesFirst,
               visibleMatchesThemed,
               viewReturned,
               trace->hasLastLive,
               samePriorView,
               samePriorViewIcon,
               samePriorCanonical,
               samePriorCache,
               samePriorMasked,
               samePriorUnmasked);

        printf("[SPOTLIGHT_TRACE] carrier sample=%llu "
               "object=0x%llx/%s "
               "images={image:0x%llx/cg:0x%llx/match:%d,"
               "displayed:0x%llx/cg:0x%llx/match:%d,"
               "contents:0x%llx/cg:0x%llx/match:%d,"
               "square:0x%llx/cg:0x%llx/match:%d} "
               "layers={carrier:0x%llx/contents:0x%llx/match:%d,"
               "contentsView:0x%llx/layer:0x%llx/contents:0x%llx/match:%d,"
               "alternate:0x%llx/contents:0x%llx/match:%d,"
               "iconView:0x%llx/layer:0x%llx/contents:0x%llx/match:%d} "
               "iconForImage=0x%llx matchesViewIcon=%d "
               "identities={requested:0x%llx,displayed:0x%llx,"
               "desiredTransient:0x%llx,requestedMatches:%d,"
               "displayedMatches:%d} "
               "flags={displayLayer:%d,realContents:%d,shouldLayer:%d,"
               "delayed:%d,canUpdate:%d,updating:%d,visibility:%llu/%d} "
               "cacheRequest=0x%llx\n",
               (unsigned long long)sampleIndex,
               (unsigned long long)snapshot.carrier,
               carrierClass[0] ? carrierClass : "-",
               (unsigned long long)snapshot.carrierImage,
               (unsigned long long)snapshot.carrierImageCG,
               trace->expectedCG &&
                   snapshot.carrierImageCG == trace->expectedCG,
               (unsigned long long)snapshot.carrierDisplayedImage,
               (unsigned long long)snapshot.carrierDisplayedImageCG,
               trace->expectedCG &&
                   snapshot.carrierDisplayedImageCG == trace->expectedCG,
               (unsigned long long)snapshot.carrierContentsImage,
               (unsigned long long)snapshot.carrierContentsImageCG,
               trace->expectedCG &&
                   snapshot.carrierContentsImageCG == trace->expectedCG,
               (unsigned long long)snapshot.carrierSquareContentsImage,
               (unsigned long long)snapshot.carrierSquareContentsImageCG,
               trace->expectedCG &&
                   snapshot.carrierSquareContentsImageCG == trace->expectedCG,
               (unsigned long long)snapshot.carrierLayer,
               (unsigned long long)snapshot.carrierLayerContents,
               trace->expectedCG &&
                   snapshot.carrierLayerContents == trace->expectedCG,
               (unsigned long long)snapshot.contentsLayerView,
               (unsigned long long)snapshot.contentsLayer,
               (unsigned long long)snapshot.contentsLayerContents,
               trace->expectedCG &&
                   snapshot.contentsLayerContents == trace->expectedCG,
               (unsigned long long)snapshot.alternateContentsLayer,
               (unsigned long long)snapshot.alternateContentsLayerContents,
               trace->expectedCG &&
                   snapshot.alternateContentsLayerContents ==
                       trace->expectedCG,
               (unsigned long long)snapshot.iconLayerView,
               (unsigned long long)snapshot.iconLayer,
               (unsigned long long)snapshot.iconLayerContents,
               trace->expectedCG &&
                   snapshot.iconLayerContents == trace->expectedCG,
               (unsigned long long)snapshot.iconForImage,
               r_is_objc_ptr(snapshot.iconForImage) &&
                   snapshot.iconForImage == snapshot.viewIcon,
               (unsigned long long)snapshot.requestedImageIdentity,
               (unsigned long long)snapshot.displayedImageIdentity,
               (unsigned long long)snapshot.desiredImageIdentity,
               snapshot.requestedIdentityMatchesDesired,
               snapshot.displayedIdentityMatchesDesired,
               snapshot.displayingImageLayer,
               snapshot.displayingRealImageContents,
               snapshot.shouldDisplayImageLayer,
               snapshot.delayedImageUpdate,
               snapshot.canUpdateImage,
               snapshot.isUpdatingImage,
               (unsigned long long)snapshot.contentVisibility,
               snapshot.contentVisibilityKnown,
               (unsigned long long)snapshot.cacheRequestCancellation);

        bool carrierVisible = r_is_objc_ptr(snapshot.carrier) &&
            snapshot.carrierHidden != 1 && snapshot.carrierAlpha > 0.01;
        bool placeholderVisible = r_is_objc_ptr(snapshot.placeholderView) &&
            snapshot.placeholderHidden != 1 &&
            snapshot.placeholderAlpha > 0.01;
        printf("[SPOTLIGHT_TRACE] presentation sample=%llu "
               "carrier=0x%llx/%s hidden=%d alpha=%.2f visible=%d "
               "placeholder=0x%llx/%s hidden=%d alpha=%.2f visible=%d "
               "image=0x%llx cg=0x%llx layer=0x%llx contents=0x%llx "
               "leafIdentifierIsPlaceholder=%d\n",
               (unsigned long long)sampleIndex,
               (unsigned long long)snapshot.carrier,
               carrierClass[0] ? carrierClass : "-",
               snapshot.carrierHidden,
               snapshot.carrierAlpha,
               carrierVisible,
               (unsigned long long)snapshot.placeholderView,
               placeholderClass[0] ? placeholderClass : "-",
               snapshot.placeholderHidden,
               snapshot.placeholderAlpha,
               placeholderVisible,
               (unsigned long long)snapshot.placeholderImage,
               (unsigned long long)snapshot.placeholderImageCG,
               (unsigned long long)snapshot.placeholderLayer,
               (unsigned long long)snapshot.placeholderLayerContents,
               snapshot.currentIconIsPlaceholder);

        printf("[SPOTLIGHT_TRACE] binding sample=%llu "
               "carrierIcon=0x%llx matchesViewIcon=%d "
               "carrierIconView=0x%llx matchesView=%d "
               "caches={selected:0x%llx,view:0x%llx/same:%d,"
               "carrier:0x%llx/same:%d,icon:0x%llx/same:%d} "
               "observers=0x%llx count=%llu/%d "
               "containsCarrier=%d/%d containsView=%d/%d\n",
               (unsigned long long)sampleIndex,
               (unsigned long long)snapshot.carrierIcon,
               r_is_objc_ptr(snapshot.carrierIcon) &&
                   snapshot.carrierIcon == snapshot.viewIcon,
               (unsigned long long)snapshot.carrierIconView,
               r_is_objc_ptr(snapshot.carrierIconView) &&
                   snapshot.carrierIconView == snapshot.view,
               (unsigned long long)snapshot.cache,
               (unsigned long long)snapshot.viewCache,
               r_is_objc_ptr(snapshot.viewCache) &&
                   snapshot.viewCache == snapshot.cache,
               (unsigned long long)snapshot.carrierCache,
               r_is_objc_ptr(snapshot.carrierCache) &&
                   snapshot.carrierCache == snapshot.cache,
               (unsigned long long)snapshot.iconCache,
               r_is_objc_ptr(snapshot.iconCache) &&
                   snapshot.iconCache == snapshot.cache,
               (unsigned long long)snapshot.cacheObservers,
               (unsigned long long)snapshot.cacheObserverCount,
               snapshot.cacheObserverCountKnown,
               snapshot.cacheObservesCarrier,
               snapshot.cacheObservesCarrierKnown,
               snapshot.cacheObservesView,
               snapshot.cacheObservesViewKnown);

        printf("[SPOTLIGHT_TRACE] cache-content sample=%llu "
               "appearances={effective:0x%llx,requested:0x%llx,"
               "displayed:0x%llx} "
               "legacy={supported:%d,image:0x%llx,cg:0x%llx,match:%d} "
               "optionedSupported=%d retrieval=%llu/%d "
               "options0={image:0x%llx,cg:0x%llx,match:%d} "
               "renderOptions=%llu "
               "render={image:0x%llx,cg:0x%llx,match:%d} "
               "expectedCG=0x%llx mode=non-generating\n",
               (unsigned long long)sampleIndex,
               (unsigned long long)snapshot.appearance,
               (unsigned long long)snapshot.requestedAppearance,
               (unsigned long long)snapshot.displayedAppearance,
               snapshot.cacheReadSelector == 1,
               (unsigned long long)snapshot.cacheReadImage,
               (unsigned long long)snapshot.cacheReadCG,
               snapshot.cacheReadMatchesExpected,
               snapshot.optionedCacheReadSupported,
               (unsigned long long)snapshot.imageCacheRetrievalOptions,
               snapshot.imageCacheRetrievalOptionsKnown,
               (unsigned long long)snapshot.optionsZeroReadImage,
               (unsigned long long)snapshot.optionsZeroReadCG,
               snapshot.optionsZeroReadMatchesExpected,
               (unsigned long long)snapshot.renderCacheOptions,
               (unsigned long long)snapshot.renderOptionsReadImage,
               (unsigned long long)snapshot.renderOptionsReadCG,
               snapshot.renderOptionsReadMatchesExpected,
               (unsigned long long)trace->expectedCG);

        bool viewActiveIsProvider =
            r_is_objc_ptr(snapshot.viewActiveDataSource) &&
            snapshot.viewActiveDataSource == snapshot.providerApplication;
        bool canonicalActiveIsProvider =
            r_is_objc_ptr(snapshot.canonicalActiveDataSource) &&
            snapshot.canonicalActiveDataSource ==
                snapshot.providerApplication;
        printf("[SPOTLIGHT_TRACE] provider sample=%llu "
               "applications=0x%llx/%s trackedIDs=0x%llx/%s "
               "entry=0x%llx/%s tracked=%d/%d "
               "modelContainsViewIcon=%d/%d "
               "viewDataSources=0x%llx/%s count=%llu/%d "
               "viewActiveIsEntry=%d canonicalActiveIsEntry=%d\n",
               (unsigned long long)sampleIndex,
               (unsigned long long)snapshot.providerApplications,
               providerApplicationsClass[0]
                   ? providerApplicationsClass : "-",
               (unsigned long long)snapshot.providerTrackedBundleIDs,
               providerTrackedClass[0] ? providerTrackedClass : "-",
               (unsigned long long)snapshot.providerApplication,
               providerApplicationClass[0]
                   ? providerApplicationClass : "-",
               snapshot.providerTracked,
               snapshot.providerTrackedKnown,
               snapshot.modelContainsViewIcon,
               snapshot.modelContainsViewIconKnown,
               (unsigned long long)snapshot.viewIconDataSources,
               viewIconDataSourcesClass[0]
                   ? viewIconDataSourcesClass : "-",
               (unsigned long long)snapshot.viewIconDataSourceCount,
               snapshot.viewIconDataSourceCountKnown,
               viewActiveIsProvider,
               canonicalActiveIsProvider);
    }

        int layerIntervened =
            themer_spotlight_trace_try_clear_displayed_layer(
                trace, &snapshot, sampleIndex);
        if (!layerIntervened) {
            (void)themer_spotlight_trace_try_reveal_themed_carrier(
                trace, &snapshot, sampleIndex);
        }

        transportOK = transportOK && remote_call_current_success();
        if (transportOK) {
            if (snapshot.viewLive) {
                trace->lastLive = snapshot;
                trace->hasLastLive = true;
            }
            trace->last = snapshot;
            trace->hasLast = true;
        }
        return transportOK;
    } @finally {
        themer_spotlight_trace_release_all(&lifetime);
        r_settle_us(previousSettleUS);
    }
}

static bool __attribute__((unused)) themer_apply_spotlight_data_legacy_in_session(
    NSDictionary<NSString *, NSData *> *imageDataByBundle)
{
    NSDictionary<NSString *, NSData *> *normalized =
        themer_normalized_theme_data(imageDataByBundle);
    if (normalized.count == 0) {
        printf("[SPOTLIGHT] cache patch skipped reason=empty-theme\n");
        return false;
    }

    enum { VIEW_CAP = 64, IMAGE_CAP = 64 };
    uint64_t views[VIEW_CAP] = {0};
    int viewCount = themer_spotlight_collect_searchui_views(views, VIEW_CAP);
    printf("[SPOTLIGHT] cache patch begin pid=%d entries=%lu views=%d\n",
           remote_call_current_pid(),
           (unsigned long)normalized.count,
           viewCount);
    if (viewCount == 0) return false;

    ThemerSpotlightRemoteImage images[IMAGE_CAP] = {{0}};
    int imageCount = 0;
    int bundleHits = 0;
    int themeHits = 0;
    int cacheWrites = 0;
    int cacheMatches = 0;
    int resets = 0;
    int visibleMatches = 0;
    int directCalls = 0;

    for (int i = 0; i < viewCount; i++) {
        uint64_t view = views[i];
        uint64_t appIcon = themer_spotlight_app_icon_for_view(view, NULL, 0);
        char bundle[192] = {0};
        char bundleSource[160] = {0};
        bool hasBundle = themer_spotlight_bundle_for_patch(
            view, appIcon,
            bundle, sizeof(bundle),
            bundleSource, sizeof(bundleSource));
        if (!hasBundle) {
            printf("[SPOTLIGHT] cache patch index=%d skipped reason=no-bundle view=0x%llx appIcon=0x%llx\n",
                   i,
                   (unsigned long long)view,
                   (unsigned long long)appIcon);
            continue;
        }
        bundleHits++;

        uint64_t sourceImage = themer_spotlight_remote_image_for_bundle(
            normalized, bundle, images, &imageCount, IMAGE_CAP);
        if (!r_is_objc_ptr(sourceImage)) {
            printf("[SPOTLIGHT] cache patch index=%d bundle=%s skipped reason=no-theme bundleSource=%s\n",
                   i, bundle, bundleSource[0] ? bundleSource : "-");
            continue;
        }
        themeHits++;

        uint64_t carrier = themer_spotlight_image_carrier_for_view(view);
        uint64_t stockImage = themer_spotlight_image_from_carrier(carrier);
        char cacheSource[128] = {0};
        uint64_t cache = themer_spotlight_find_icon_cache(
            view, carrier, appIcon,
            cacheSource, sizeof(cacheSource));
        const char *stockSelector = NULL;
        if (!r_is_objc_ptr(stockImage)) {
            stockImage = themer_spotlight_cached_image(cache,
                                                       appIcon,
                                                       &stockSelector);
        }

        double targetW = 0.0;
        double targetH = 0.0;
        double stockScale = 0.0;
        bool stockGeometry = themer_read_image_geometry(stockImage,
                                                        &targetW,
                                                        &targetH,
                                                        &stockScale);
        if (!stockGeometry) {
            ThemerRect carrierFrame = {0};
            if (themer_read_rect(carrier, "bounds", &carrierFrame) &&
                carrierFrame.w >= 8.0 && carrierFrame.w <= 180.0) {
                targetW = carrierFrame.w;
            } else {
                targetW = 60.0;
            }
            stockScale = themer_screen_scale();
        }

        uint64_t adjusted = themer_spotlight_provider_sized_themed_image(
            sourceImage, targetW, stockScale);
        uint64_t patchImage = r_is_objc_ptr(adjusted) ? adjusted : sourceImage;

        char appearanceSource[128] = {0};
        uint64_t appearance = themer_spotlight_image_appearance(
            view, carrier,
            appearanceSource, sizeof(appearanceSource));

        int localCacheWrites = 0;
        if (r_is_objc_ptr(cache) && r_is_objc_ptr(appIcon) &&
            r_is_objc_ptr(appearance) &&
            r_responds_main(cache, "cacheImage:forIcon:imageAppearance:")) {
            r_msg2_main(cache, "cacheImage:forIcon:imageAppearance:",
                        patchImage, appIcon, appearance, 0);
            localCacheWrites++;
            cacheWrites++;
        }

        bool reset = false;
        if (r_is_objc_ptr(appIcon) &&
            r_responds_main(view, "resetImageWithAppIcon:")) {
            r_msg2_main(view, "resetImageWithAppIcon:", appIcon, 0, 0, 0);
            reset = true;
            resets++;
        }

        const char *readbackSelector = NULL;
        uint64_t cacheReadback = themer_spotlight_cached_image(cache,
                                                               appIcon,
                                                               &readbackSelector);
        bool cacheMatch = themer_spotlight_images_match(patchImage,
                                                        cacheReadback);
        if (cacheMatch) cacheMatches++;

        uint64_t refreshedCarrier = themer_spotlight_image_carrier_for_view(view);
        if (r_is_objc_ptr(refreshedCarrier)) carrier = refreshedCarrier;
        uint64_t visibleImage = themer_spotlight_image_from_carrier(carrier);
        bool visibleMatch = themer_spotlight_images_match(patchImage,
                                                          visibleImage);
        int localDirectCalls = 0;
        if (!visibleMatch) {
            localDirectCalls = themer_spotlight_push_visible_image(
                view, carrier, patchImage, appearance);
            directCalls += localDirectCalls;
            visibleImage = themer_spotlight_image_from_carrier(carrier);
            visibleMatch = themer_spotlight_images_match(patchImage,
                                                          visibleImage);
        }
        if (visibleMatch) visibleMatches++;

        char viewClass[96] = {0};
        char iconClass[96] = {0};
        char carrierClass[96] = {0};
        char cacheClass[96] = {0};
        themer_read_class_name(view, viewClass, sizeof(viewClass));
        themer_read_class_name(appIcon, iconClass, sizeof(iconClass));
        themer_read_class_name(carrier, carrierClass, sizeof(carrierClass));
        themer_read_class_name(cache, cacheClass, sizeof(cacheClass));
        printf("[SPOTLIGHT] cache patch index=%d bundle=%s bundleSource=%s "
               "view=0x%llx/%s appIcon=0x%llx/%s carrier=0x%llx/%s "
               "cache=0x%llx/%s cacheSource=%s appearance=0x%llx/%s "
               "stock=0x%llx stockSelector=%s stockGeom=%d target=%.1fx%.1f@%.2f "
               "patch=0x%llx cacheWrites=%d reset=%d readback=0x%llx/%s "
               "cacheMatch=%d directCalls=%d visible=0x%llx visibleMatch=%d\n",
               i,
               bundle,
               bundleSource[0] ? bundleSource : "-",
               (unsigned long long)view,
               viewClass[0] ? viewClass : "-",
               (unsigned long long)appIcon,
               iconClass[0] ? iconClass : "-",
               (unsigned long long)carrier,
               carrierClass[0] ? carrierClass : "-",
               (unsigned long long)cache,
               cacheClass[0] ? cacheClass : "-",
               cacheSource[0] ? cacheSource : "-",
               (unsigned long long)appearance,
               appearanceSource[0] ? appearanceSource : "-",
               (unsigned long long)stockImage,
               stockSelector ?: "-",
               stockGeometry,
               targetW,
               targetH,
               stockScale,
               (unsigned long long)patchImage,
               localCacheWrites,
               reset,
               (unsigned long long)cacheReadback,
               readbackSelector ?: "-",
               cacheMatch,
               localDirectCalls,
               (unsigned long long)visibleImage,
               visibleMatch);

        if (r_is_objc_ptr(adjusted)) {
            r_msg2(adjusted, "release", 0, 0, 0, 0);
        }
    }

    for (int i = 0; i < imageCount; i++) {
        if (r_is_objc_ptr(images[i].image)) {
            r_msg2(images[i].image, "release", 0, 0, 0, 0);
        }
    }

    printf("[SPOTLIGHT] cache patch complete views=%d bundleHits=%d themeHits=%d "
           "uploads=%d cacheWrites=%d cacheMatches=%d resets=%d directCalls=%d visibleMatches=%d\n",
           viewCount,
           bundleHits,
           themeHits,
           imageCount,
           cacheWrites,
           cacheMatches,
           resets,
           directCalls,
           visibleMatches);
    return visibleMatches > 0 || cacheMatches > 0;
}

typedef struct {
    int requested;
    int trackedBefore;
    int trackedAfter;
    int providersBefore;
    int providersAfter;
    bool supported;
    bool called;
} ThemerSpotlightProviderTrackStats;

static void themer_spotlight_count_tracked_provider_ids(
    uint64_t dataSource,
    const uint64_t *identifiers,
    int identifierCount,
    int *trackedOut,
    int *providersOut)
{
    if (trackedOut) *trackedOut = 0;
    if (providersOut) *providersOut = 0;
    if (!r_is_objc_ptr(dataSource) || !identifiers || identifierCount <= 0) {
        return;
    }

    uint64_t tracked = r_ivar_value(
        dataSource, "_trackedApplicationBundleIdentifiers");
    uint64_t applications = r_ivar_value(dataSource, "_applications");
    int trackedCount = 0;
    int providerCount = 0;
    for (int i = 0; i < identifierCount && remote_call_current_success(); i++) {
        uint64_t identifier = identifiers[i];
        if (!r_is_objc_ptr(identifier)) continue;
        if (r_is_objc_ptr(tracked) &&
            r_responds_main(tracked, "containsObject:") &&
            (r_msg2_main(tracked, "containsObject:",
                         identifier, 0, 0, 0) & 1) != 0) {
            trackedCount++;
        }
        if (r_is_objc_ptr(applications) &&
            r_responds_main(applications, "objectForKey:") &&
            r_is_objc_ptr(r_msg2_main(applications, "objectForKey:",
                                     identifier, 0, 0, 0))) {
            providerCount++;
        }
    }
    if (trackedOut) *trackedOut = trackedCount;
    if (providersOut) *providersOut = providerCount;
}

static ThemerSpotlightProviderTrackStats
themer_spotlight_batch_track_provider_bundles(
    uint64_t dataSource,
    NSArray<NSString *> *bundleKeys)
{
    ThemerSpotlightProviderTrackStats stats = {0};
    if (!r_is_objc_ptr(dataSource) || bundleKeys.count == 0) return stats;

    enum { IDENTIFIER_CAP = THEMER_SPOTLIGHT_MONITOR_ICON_CAP };
    uint64_t identifiers[IDENTIFIER_CAP] = {0};
    uint64_t arrayClass = r_class("NSMutableArray");
    uint64_t arrayAlloc = r_is_objc_ptr(arrayClass)
        ? r_msg2(arrayClass, "alloc", 0, 0, 0, 0) : 0;
    uint64_t remoteIdentifiers = r_is_objc_ptr(arrayAlloc)
        ? r_msg2_main(arrayAlloc, "initWithCapacity:",
                      MIN(bundleKeys.count, (NSUInteger)IDENTIFIER_CAP),
                      0, 0, 0)
        : 0;
    if (!r_is_objc_ptr(remoteIdentifiers)) return stats;

    for (NSString *key in bundleKeys) {
        if (stats.requested >= IDENTIFIER_CAP) break;
        if (![key isKindOfClass:NSString.class] || key.length == 0) continue;
        uint64_t identifier = r_nsstr_retained(key.UTF8String);
        if (!r_is_objc_ptr(identifier)) continue;
        r_msg2_main(remoteIdentifiers, "addObject:",
                    identifier, 0, 0, 0);
        identifiers[stats.requested++] = identifier;
    }

    themer_spotlight_count_tracked_provider_ids(
        dataSource, identifiers, stats.requested,
        &stats.trackedBefore, &stats.providersBefore);
    static const char *selector =
        "beginTrackingApplicationsWithBundleIdentifiers:";
    stats.supported = r_responds_main(dataSource, selector);
    if (stats.supported && stats.requested > 0 &&
        remote_call_current_success()) {
        r_msg2_main(dataSource, selector,
                    remoteIdentifiers, 0, 0, 0);
        stats.called = remote_call_current_success();
    }

    if (stats.called) {
        // The known implementation is synchronous. Allow a short bounded
        // settle for builds that publish the provider dictionary one turn
        // later, without turning tracking into a long polling loop.
        int previousProviderCount = -1;
        for (int attempt = 0; attempt < 3; attempt++) {
            themer_spotlight_count_tracked_provider_ids(
                dataSource, identifiers, stats.requested,
                &stats.trackedAfter, &stats.providersAfter);
            if (stats.trackedAfter == stats.requested &&
                stats.providersAfter == previousProviderCount) {
                break;
            }
            previousProviderCount = stats.providersAfter;
            usleep(100000);
        }
    }

    printf("[SPOTLIGHT_PRELOAD] provider-track requested=%d supported=%d "
           "called=%d tracked=%d->%d providers=%d->%d confirmed=%d\n",
           stats.requested,
           stats.supported,
           stats.called,
           stats.trackedBefore,
           stats.trackedAfter,
           stats.providersBefore,
           stats.providersAfter,
           stats.requested > 0 && stats.trackedAfter == stats.requested);

    for (int i = 0; i < stats.requested; i++) {
        if (r_is_objc_ptr(identifiers[i])) {
            r_msg2(identifiers[i], "release", 0, 0, 0, 0);
        }
    }
    r_msg2(remoteIdentifiers, "release", 0, 0, 0, 0);
    return stats;
}

typedef struct {
    int themeEntries;
    int providerTrackRequested;
    int providerTrackConfirmed;
    int providerEntriesBeforeTracking;
    int providerEntriesAfterTracking;
    bool providerTrackSupported;
    bool providerTrackCalled;
    int canonicalHits;
    int uniqueCanonicalHits;
    int canonicalMisses;
    int repositoryVerified;
    int repositoryMismatches;
    int sourceInvalidationCalls;
    int bundleMismatches;
    int pointerDuplicates;
    int pointerConflicts;
    int uploads;
    int sizedImages;
    int grafted;
    int classChanged;
    int associationsVerified;
    int providersGrafted;
    int providerClassChanged;
    int providerImageAssociations;
    int providerLayerAssociations;
    int providerFailures;
    int failures;
    int cachePurgeCalls;
    int cacheWarmCalls;
    int cacheUpdateCalls;
    int cacheBindingCount;
    int cacheTargetCount;
    int cacheSeedCalls;
    int cacheSeededIcons;
    int cacheSeedPairs;
    int cacheSamples;
    int cacheSampleMatches;
    int cacheOptionedReads;
    int cacheOptionedMatches;
    int cacheRenderReads;
    int cacheRenderMatches;
    int cacheLegacyReads;
    int cacheLegacyMatches;
    int cacheBackingReads;
    int cacheBackingMatches;
    int cacheExpectedBackingReads;
    bool cacheUsable;
    bool timedOut;
    bool cancelled;
    uint64_t owner;
    uint64_t dataSource;
    uint64_t iconModel;
    uint64_t repository;
    uint64_t cache;
    double pointWidth;
    double pointHeight;
    double scale;
} ThemerSpotlightCanonicalStats;

typedef struct {
    double width;
    double height;
    double scale;
    double continuousCornerRadius;
} ThemerSpotlightRemoteIconImageInfo;

static bool themer_spotlight_read_cache_icon_image_info(
    uint64_t cache,
    ThemerSpotlightRemoteIconImageInfo *infoOut)
{
    if (infoOut) memset(infoOut, 0, sizeof(*infoOut));
    if (!r_is_objc_ptr(cache) || !infoOut) return false;

    uint64_t cls = r_dlsym_call(R_TIMEOUT, "object_getClass",
                                cache, 0, 0, 0, 0, 0, 0, 0);
    uint64_t name = r_alloc_str("_iconImageInfo");
    uint64_t ivar = r_is_objc_ptr(cls) && name
        ? r_dlsym_call(R_TIMEOUT, "class_getInstanceVariable",
                       cls, name, 0, 0, 0, 0, 0, 0)
        : 0;
    if (name) r_free(name);
    if (!ivar) return false;

    uint64_t offset = r_dlsym_call(R_TIMEOUT, "ivar_getOffset",
                                   ivar, 0, 0, 0, 0, 0, 0, 0);
    ThemerSpotlightRemoteIconImageInfo info = {0};
    if (!remote_read(cache + offset, &info, sizeof(info))) return false;
    if (info.width < 8.0 || info.width > 180.0 ||
        info.height < 8.0 || info.height > 180.0 ||
        info.scale < 1.0 || info.scale > 4.0) {
        return false;
    }
    *infoOut = info;
    return true;
}

static bool themer_spotlight_apply_canonical_theme(
    NSDictionary<NSString *, NSData *> *normalized,
    ThemerSpotlightCanonicalStats *stats,
    volatile int *stopRequested)
{
    if (!stats) return false;
    memset(stats, 0, sizeof(*stats));
    stats->themeEntries = (int)normalized.count;
    if (normalized.count == 0) return false;

    uint64_t modelClass = themer_lookup_class("SearchUIHomeScreenModel");
    stats->owner = r_is_objc_ptr(modelClass) &&
                   r_responds_main(modelClass, "sharedInstance")
        ? r_msg2_main(modelClass, "sharedInstance", 0, 0, 0, 0)
        : 0;
    stats->dataSource = themer_spotlight_trace_object_value(
        stats->owner, "dataSource", "_dataSource");
    stats->iconModel = themer_spotlight_trace_object_value(
        stats->owner, "iconModel", "_iconModel");
    if (r_is_objc_ptr(stats->iconModel)) {
        stats->repository = r_ivar_value(stats->iconModel, "iconRepository");
        if (!r_is_objc_ptr(stats->repository)) {
            stats->repository = r_ivar_value(stats->iconModel,
                                             "_iconRepository");
        }
        if (!r_is_objc_ptr(stats->repository) &&
            r_responds_main(stats->iconModel, "iconRepository")) {
            stats->repository = r_msg2_main(stats->iconModel,
                                            "iconRepository", 0, 0, 0, 0);
        }
    }

    ThemerSpotlightCarrierBinding carrierRows[
        THEMER_SPOTLIGHT_BINDING_CAP] = {{0}};
    ThemerSpotlightCarrierBinding cacheBindings[
        THEMER_SPOTLIGHT_BINDING_CAP] = {{0}};
    int carrierRowCount = themer_spotlight_collect_carrier_bindings(
        carrierRows, THEMER_SPOTLIGHT_BINDING_CAP, true);
    stats->cacheBindingCount = themer_spotlight_unique_cache_bindings(
        carrierRows, carrierRowCount,
        cacheBindings, THEMER_SPOTLIGHT_BINDING_CAP);
    stats->cache = stats->cacheBindingCount > 0
        ? cacheBindings[0].cache : 0;
    ThemerSpotlightRemoteIconImageInfo cacheInfo = {0};
    bool cacheInfoKnown = themer_spotlight_read_cache_icon_image_info(
        stats->cache, &cacheInfo);
    stats->pointWidth = cacheInfoKnown ? cacheInfo.width : 68.0;
    stats->pointHeight = cacheInfoKnown ? cacheInfo.height : 68.0;
    stats->scale = cacheInfoKnown ? cacheInfo.scale : themer_screen_scale();

    char ownerClass[96] = {0};
    char dataSourceClass[96] = {0};
    char modelObjectClass[96] = {0};
    char repositoryClass[96] = {0};
    char cacheClass[96] = {0};
    themer_read_class_name(stats->owner, ownerClass, sizeof(ownerClass));
    themer_read_class_name(stats->dataSource, dataSourceClass,
                           sizeof(dataSourceClass));
    themer_read_class_name(stats->iconModel, modelObjectClass,
                           sizeof(modelObjectClass));
    themer_read_class_name(stats->repository, repositoryClass,
                           sizeof(repositoryClass));
    themer_read_class_name(stats->cache, cacheClass, sizeof(cacheClass));
    printf("[SPOTLIGHT_PRELOAD] graph pid=%d owner=0x%llx/%s "
           "dataSource=0x%llx/%s iconModel=0x%llx/%s "
           "repository=0x%llx/%s carrierRows=%d cacheBindings=%d "
           "firstCache=0x%llx/%s "
           "cacheInfo=%d size=%.1fx%.1f@%.2f fallback=%d\n",
           remote_call_current_pid(),
           (unsigned long long)stats->owner,
           ownerClass[0] ? ownerClass : "-",
           (unsigned long long)stats->dataSource,
           dataSourceClass[0] ? dataSourceClass : "-",
           (unsigned long long)stats->iconModel,
           modelObjectClass[0] ? modelObjectClass : "-",
           (unsigned long long)stats->repository,
           repositoryClass[0] ? repositoryClass : "-",
           carrierRowCount,
           stats->cacheBindingCount,
           (unsigned long long)stats->cache,
           cacheClass[0] ? cacheClass : "-",
           cacheInfoKnown,
           stats->pointWidth, stats->pointHeight, stats->scale,
           !cacheInfoKnown);

    if (!r_is_objc_ptr(stats->owner) ||
        !r_is_objc_ptr(stats->dataSource) ||
        !r_is_objc_ptr(stats->iconModel)) {
        printf("[SPOTLIGHT_PRELOAD] stopped "
               "reason=provider-graph-unavailable\n");
        return false;
    }

    enum { ICON_CAP = 384, LOG_SAMPLE_CAP = 12, CACHE_TARGET_CAP = 64 };
    uint64_t icons[ICON_CAP] = {0};
    uint64_t providers[ICON_CAP] = {0};
    char iconBundles[ICON_CAP][192] = {{0}};
    int iconCount = 0;
    uint64_t primarySelector = r_sel(
        "makeIconImageWithInfo:traitCollection:context:options:");
    NSArray<NSString *> *keys =
        [[normalized allKeys] sortedArrayUsingSelector:@selector(compare:)];
    uint64_t dictionaryClass = r_class("NSMutableDictionary");
    NSUInteger repositoryCapacity = MIN(
        keys.count, (NSUInteger)THEMER_SPOTLIGHT_MONITOR_ICON_CAP);
    uint64_t imageDictionaryAlloc = r_is_objc_ptr(dictionaryClass)
        ? r_msg2(dictionaryClass, "alloc", 0, 0, 0, 0) : 0;
    uint64_t iconDictionaryAlloc = r_is_objc_ptr(dictionaryClass)
        ? r_msg2(dictionaryClass, "alloc", 0, 0, 0, 0) : 0;
    uint64_t providerDictionaryAlloc = r_is_objc_ptr(dictionaryClass)
        ? r_msg2(dictionaryClass, "alloc", 0, 0, 0, 0) : 0;
    uint64_t classDictionaryAlloc = r_is_objc_ptr(dictionaryClass)
        ? r_msg2(dictionaryClass, "alloc", 0, 0, 0, 0) : 0;
    uint64_t candidateThemeRepository = r_is_objc_ptr(imageDictionaryAlloc)
        ? r_msg2_main(imageDictionaryAlloc, "initWithCapacity:",
                      repositoryCapacity, 0, 0, 0)
        : 0;
    uint64_t candidateIconRepository = r_is_objc_ptr(iconDictionaryAlloc)
        ? r_msg2_main(iconDictionaryAlloc, "initWithCapacity:",
                      repositoryCapacity, 0, 0, 0)
        : 0;
    uint64_t candidateProviderRepository =
        r_is_objc_ptr(providerDictionaryAlloc)
        ? r_msg2_main(providerDictionaryAlloc, "initWithCapacity:",
                      repositoryCapacity, 0, 0, 0)
        : 0;
    uint64_t candidateClassRepository = r_is_objc_ptr(classDictionaryAlloc)
        ? r_msg2_main(classDictionaryAlloc, "initWithCapacity:",
                      repositoryCapacity, 0, 0, 0)
        : 0;
    if (!r_is_objc_ptr(candidateThemeRepository) ||
        !r_is_objc_ptr(candidateIconRepository) ||
        !r_is_objc_ptr(candidateProviderRepository) ||
        !r_is_objc_ptr(candidateClassRepository)) {
        printf("[SPOTLIGHT_PRELOAD] stopped "
               "reason=process-state-repository-create-failed\n");
        if (r_is_objc_ptr(candidateThemeRepository)) {
            r_msg2(candidateThemeRepository, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(candidateIconRepository)) {
            r_msg2(candidateIconRepository, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(candidateProviderRepository)) {
            r_msg2(candidateProviderRepository, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(candidateClassRepository)) {
            r_msg2(candidateClassRepository, "release", 0, 0, 0, 0);
        }
        return false;
    }
    uint64_t startUS = themer_now_us();
    ThemerSpotlightProviderTrackStats trackStats =
        themer_spotlight_batch_track_provider_bundles(
            stats->dataSource, keys);
    stats->providerTrackRequested = trackStats.requested;
    stats->providerTrackConfirmed = trackStats.trackedAfter;
    stats->providerEntriesBeforeTracking = trackStats.providersBefore;
    stats->providerEntriesAfterTracking = trackStats.providersAfter;
    stats->providerTrackSupported = trackStats.supported;
    stats->providerTrackCalled = trackStats.called;
    uint64_t budgetUS = 30000000ULL +
        ((uint64_t)normalized.count * 1000000ULL);
    if (budgetUS < 60000000ULL) budgetUS = 60000000ULL;
    if (budgetUS > 300000000ULL) budgetUS = 300000000ULL;
    const uint64_t deadlineUS = startUS + budgetUS;

    for (NSString *key in keys) {
        if (stopRequested && *stopRequested) {
            stats->cancelled = true;
            break;
        }
        if (!remote_call_current_success()) break;
        if (themer_now_us() >= deadlineUS) {
            stats->timedOut = true;
            break;
        }
        if (iconCount >= ICON_CAP) {
            stats->failures++;
            printf("[SPOTLIGHT_PRELOAD] stopped reason=icon-cap cap=%d\n",
                   ICON_CAP);
            break;
        }
        if (![key isKindOfClass:NSString.class] || key.length == 0) continue;
        NSData *bytes = normalized[key];
        if (![bytes isKindOfClass:NSData.class] || bytes.length == 0) continue;

        const char *bundle = key.UTF8String;
        uint64_t providerApplication = 0;
        const char *providerSelector = NULL;
        uint64_t icon = themer_spotlight_materialize_provider_icon(
            stats->owner, stats->dataSource, bundle,
            &providerApplication, &providerSelector);
        if (!r_is_objc_ptr(icon)) {
            stats->canonicalMisses++;
            if (stats->canonicalMisses <= LOG_SAMPLE_CAP) {
                printf("[SPOTLIGHT_PRELOAD] miss bundle=%s "
                       "reason=no-provider-backed-icon\n",
                       bundle);
            }
            continue;
        }

        char actualBundle[192] = {0};
        if (!themer_read_bundle_for_icon(icon, 0,
                                         actualBundle,
                                         sizeof(actualBundle)) ||
            strcmp(actualBundle, bundle) != 0) {
            stats->bundleMismatches++;
            if (stats->bundleMismatches <= LOG_SAMPLE_CAP) {
                printf("[SPOTLIGHT_PRELOAD] miss bundle=%s reason=bundle-mismatch "
                       "actual=%s icon=0x%llx provider=0x%llx selector=%s\n",
                       bundle,
                       actualBundle[0] ? actualBundle : "?",
                       (unsigned long long)icon,
                       (unsigned long long)providerApplication,
                       providerSelector ?: "-");
            }
            continue;
        }
        uint64_t storedIcon = themer_spotlight_trace_stored_model_icon(
            stats->iconModel, bundle, NULL, NULL);
        if (storedIcon != icon) {
            stats->repositoryMismatches++;
            if (stats->repositoryMismatches <= LOG_SAMPLE_CAP) {
                printf("[SPOTLIGHT_PRELOAD] miss bundle=%s "
                       "reason=canonical-repository-mismatch "
                       "materialized=0x%llx stored=0x%llx\n",
                       bundle,
                       (unsigned long long)icon,
                       (unsigned long long)storedIcon);
            }
            continue;
        }
        stats->repositoryVerified++;
        if (stats->canonicalHits < LOG_SAMPLE_CAP ||
            ((stats->canonicalHits + 1) % 24) == 0) {
            printf("[SPOTLIGHT_PRELOAD] provider-icon bundle=%s "
                   "icon=0x%llx provider=0x%llx selector=%s "
                   "repositoryMatch=1\n",
                   bundle,
                   (unsigned long long)icon,
                   (unsigned long long)providerApplication,
                   providerSelector ?: "-");
        }
        stats->canonicalHits++;

        bool duplicate = false;
        for (int i = 0; i < iconCount; i++) {
            if (icons[i] != icon) continue;
            duplicate = true;
            if (strcmp(iconBundles[i], bundle) == 0) {
                stats->pointerDuplicates++;
            } else {
                stats->pointerConflicts++;
                printf("[SPOTLIGHT_PRELOAD] conflict icon=0x%llx first=%s next=%s\n",
                       (unsigned long long)icon, iconBundles[i], bundle);
            }
            break;
        }
        if (duplicate) continue;
        stats->uniqueCanonicalHits++;

        NSData *uploadBytes = themer_rounded_png_data(bytes, bundle);
        uint64_t sourceImage = themer_build_remote_uiimage_from_data(
            uploadBytes ?: bytes, bundle);
        if (!r_is_objc_ptr(sourceImage)) {
            stats->failures++;
            printf("[SPOTLIGHT_PRELOAD] failure bundle=%s phase=upload\n",
                   bundle);
            continue;
        }
        stats->uploads++;

        uint64_t adjusted = themer_spotlight_provider_sized_themed_image(
            sourceImage, stats->pointWidth, stats->scale);
        uint64_t patchImage = r_is_objc_ptr(adjusted)
            ? adjusted : sourceImage;
        if (r_is_objc_ptr(adjusted)) stats->sizedImages++;

        bool providerClassChanged = false;
        int providerImageMatches = 0;
        int providerLayerMatches = 0;
        bool providerGrafted = false;
        if (kThemerSpotlightProviderGraftEnabled) {
            providerGrafted = themer_graft_spotlight_provider(
                providerApplication, patchImage, stats->pointWidth,
                &providerClassChanged,
                &providerImageMatches,
                &providerLayerMatches);
            if (providerGrafted) {
                stats->providersGrafted++;
                stats->providerImageAssociations += providerImageMatches;
                stats->providerLayerAssociations += providerLayerMatches;
                if (providerClassChanged) stats->providerClassChanged++;
            } else {
                stats->providerFailures++;
            }
        }

        ThemerEntry scratch = {0};
        bool classChanged = false;
        bool grafted = themer_graft_spotlight_icon_model(
            icon, patchImage, &scratch, 0, &classChanged);
        if (grafted) {
            stats->grafted++;
            if (classChanged) stats->classChanged++;
        }

        uint64_t installedClass = grafted
            ? r_dlsym_call(R_TIMEOUT, "object_getClass",
                           icon, 0, 0, 0, 0, 0, 0, 0)
            : 0;
        uint64_t originalClass = 0;
        char installedClassName[192] = {0};
        if (r_is_objc_ptr(installedClass)) {
            themer_read_class_object_name(installedClass,
                                          installedClassName,
                                          sizeof(installedClassName));
            if (strncmp(installedClassName, "CNDSpotlightThemed",
                        sizeof("CNDSpotlightThemed") - 1) == 0) {
                originalClass = r_dlsym_call(
                    R_TIMEOUT, "class_getSuperclass",
                    installedClass, 0, 0, 0, 0, 0, 0, 0);
            }
        }
        uint64_t associated = grafted && primarySelector
            ? r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                           icon, primarySelector, 0, 0, 0, 0, 0, 0)
            : 0;
        bool associationOK = grafted && associated == patchImage &&
                             r_is_objc_ptr(originalClass);
        bool processStateStored = false;
        if (associationOK) {
            uint64_t repositoryKey = r_nsstr_retained(bundle);
            if (r_is_objc_ptr(repositoryKey)) {
                r_msg2_main(candidateThemeRepository,
                            "setObject:forKey:",
                            patchImage, repositoryKey, 0, 0);
                r_msg2_main(candidateIconRepository,
                            "setObject:forKey:",
                            icon, repositoryKey, 0, 0);
                r_msg2_main(candidateProviderRepository,
                            "setObject:forKey:",
                            providerApplication, repositoryKey, 0, 0);
                r_msg2_main(candidateClassRepository,
                            "setObject:forKey:",
                            originalClass, repositoryKey, 0, 0);
                uint64_t storedImage = r_msg2_main(
                    candidateThemeRepository, "objectForKey:",
                    repositoryKey, 0, 0, 0);
                uint64_t storedCanonical = r_msg2_main(
                    candidateIconRepository, "objectForKey:",
                    repositoryKey, 0, 0, 0);
                uint64_t storedProvider = r_msg2_main(
                    candidateProviderRepository, "objectForKey:",
                    repositoryKey, 0, 0, 0);
                uint64_t storedClass = r_msg2_main(
                    candidateClassRepository, "objectForKey:",
                    repositoryKey, 0, 0, 0);
                processStateStored = storedImage == patchImage &&
                                     storedCanonical == icon &&
                                     storedProvider == providerApplication &&
                                     storedClass == originalClass;
                r_msg2(repositoryKey, "release", 0, 0, 0, 0);
            }
        }
        if (associationOK && processStateStored) {
            stats->sourceInvalidationCalls +=
                themer_notify_icon_image_changed(icon);
            stats->associationsVerified++;
            icons[iconCount] = icon;
            providers[iconCount] = providerApplication;
            snprintf(iconBundles[iconCount], sizeof(iconBundles[iconCount]),
                     "%s", bundle);
            iconCount++;
        } else {
            stats->failures++;
            printf("[SPOTLIGHT_PRELOAD] failure bundle=%s phase=%s "
                   "icon=0x%llx patch=0x%llx associated=0x%llx "
                   "stateStored=%d\n",
                   bundle,
                   !grafted ? "graft" :
                       (!associationOK ? "association" : "process-state"),
                   (unsigned long long)icon,
                   (unsigned long long)patchImage,
                   (unsigned long long)associated,
                   processStateStored);
        }

        if (r_is_objc_ptr(adjusted)) {
            r_msg2(adjusted, "release", 0, 0, 0, 0);
        }
        r_msg2(sourceImage, "release", 0, 0, 0, 0);

        if ((stats->canonicalHits % 24) == 0) {
            printf("[SPOTLIGHT_PRELOAD] progress entries=%d hits=%d misses=%d "
                   "grafted=%d verified=%d failures=%d elapsed=%llums\n",
                   stats->themeEntries,
                   stats->canonicalHits,
                   stats->canonicalMisses,
                   stats->grafted,
                   stats->associationsVerified,
                   stats->failures,
                   (unsigned long long)((themer_now_us() - startUS) / 1000ULL));
        }
    }

    if (stopRequested && *stopRequested) stats->cancelled = true;
    if (themer_now_us() >= deadlineUS) stats->timedOut = true;
    if (stats->canonicalHits > stats->providerEntriesAfterTracking) {
        // A provider may publish between the bounded batch-settle sample and
        // its exact owner-wrapper lookup. Count that successfully validated
        // provider in the final coverage target.
        stats->providerEntriesAfterTracking = stats->canonicalHits;
    }
    stats->cacheUsable = kThemerSpotlightCanonicalCacheWarmEnabled &&
                         stats->cacheBindingCount > 0;
    printf("[SPOTLIGHT_PRELOAD] cache-plan enabled=%d usable=%d bindings=%d "
           "acceptedIcons=%d\n",
           kThemerSpotlightCanonicalCacheWarmEnabled,
           stats->cacheUsable,
           stats->cacheBindingCount,
           iconCount);

    ThemerSpotlightCacheTarget *plannedTargets = NULL;
    int *plannedTargetCounts = NULL;
    if (stats->cacheUsable) {
        plannedTargets = calloc(
            (size_t)stats->cacheBindingCount * CACHE_TARGET_CAP,
            sizeof(*plannedTargets));
        plannedTargetCounts = calloc(
            (size_t)stats->cacheBindingCount,
            sizeof(*plannedTargetCounts));
        if (!plannedTargets || !plannedTargetCounts) {
            stats->failures++;
        } else {
            for (int b = 0; b < stats->cacheBindingCount; b++) {
                ThemerSpotlightCacheTarget *targets =
                    plannedTargets + ((size_t)b * CACHE_TARGET_CAP);
                int targetCount = themer_spotlight_collect_cache_targets(
                    cacheBindings[b].cache, targets, CACHE_TARGET_CAP);
                targetCount = themer_spotlight_compact_cache_targets(
                    targets, targetCount);
                plannedTargetCounts[b] = targetCount;
                stats->cacheTargetCount += targetCount;
            }
        }
    }

    if (!stats->timedOut && !stats->cancelled && stats->cacheUsable &&
        plannedTargets && plannedTargetCounts) {
        for (int i = 0;
             i < iconCount && remote_call_current_success();
             i++) {
            bool iconSeededEverywhere = true;
            uint64_t expected = primarySelector
                ? r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                               icons[i], primarySelector,
                               0, 0, 0, 0, 0, 0)
                : 0;
            for (int b = 0;
                 b < stats->cacheBindingCount &&
                     remote_call_current_success();
                 b++) {
                if (stopRequested && *stopRequested) {
                    stats->cancelled = true;
                    iconSeededEverywhere = false;
                    break;
                }
                if (themer_now_us() >= deadlineUS) {
                    stats->timedOut = true;
                    iconSeededEverywhere = false;
                    break;
                }

                ThemerSpotlightCacheTarget *cacheTargets =
                    plannedTargets + ((size_t)b * CACHE_TARGET_CAP);
                int targetCount = plannedTargetCounts[b];
                uint64_t imageGeneration = r_msg2_main(
                    cacheBindings[b].cache,
                    "currentImageGenerationForIcon:",
                    icons[i], 0, 0, 0);
                int seedCalls = themer_spotlight_seed_cache_targets(
                    cacheTargets, targetCount,
                    expected, icons[i], cacheBindings[b].appearance,
                    imageGeneration, false);
                stats->cacheSeedCalls += seedCalls;
                if (targetCount <= 1 || seedCalls != targetCount) {
                    printf("[SPOTLIGHT_PRELOAD] cache-seed-miss "
                           "bundle=%s binding=%d cache=0x%llx "
                           "appearance=0x%llx generation=%llu calls=%d/%d\n",
                           iconBundles[i], b,
                           (unsigned long long)cacheBindings[b].cache,
                           (unsigned long long)cacheBindings[b].appearance,
                           (unsigned long long)imageGeneration,
                           seedCalls,
                           targetCount);
                }

                bool exactSupported = false;
                uint64_t cached = themer_spotlight_exact_cached_image(
                    &cacheBindings[b], icons[i], &exactSupported);
                bool exactMatch = exactSupported &&
                    themer_spotlight_images_match(expected, cached);
                ThemerSpotlightCacheVerification backingVerification =
                    themer_spotlight_verify_cache_targets(
                        cacheTargets, targetCount,
                        expected, icons[i], cacheBindings[b].appearance,
                        false);
                int expectedBackingReads = targetCount - 1;
                stats->cacheExpectedBackingReads += expectedBackingReads;
                stats->cacheBackingReads += backingVerification.backingReads;
                stats->cacheBackingMatches +=
                    backingVerification.backingNativeMatches;
                bool backingMatch = expectedBackingReads > 0 &&
                    backingVerification.backingReads == expectedBackingReads &&
                    backingVerification.backingNativeMatches ==
                        backingVerification.backingReads;
                if (exactSupported) {
                    stats->cacheSamples++;
                    stats->cacheOptionedReads++;
                    stats->cacheRenderReads++;
                }
                if (exactMatch) {
                    stats->cacheSeedPairs++;
                    stats->cacheSampleMatches++;
                    stats->cacheOptionedMatches++;
                    stats->cacheRenderMatches++;
                } else {
                    iconSeededEverywhere = false;
                }
                if (!exactMatch || stats->cacheSamples <= LOG_SAMPLE_CAP ||
                    (stats->cacheSamples % 24) == 0) {
                    printf("[SPOTLIGHT_PRELOAD] exact-cache-read "
                       "bundle=%s binding=%d cache=0x%llx "
                       "appearance=0x%llx options=%llu generation=%llu "
                       "targets=%d expected=0x%llx cached=0x%llx "
                       "supported=%d match=%d backing=%d/%d expected=%d "
                       "backingDiagnostic=%d\n",
                       iconBundles[i], b,
                       (unsigned long long)cacheBindings[b].cache,
                       (unsigned long long)cacheBindings[b].appearance,
                       (unsigned long long)
                           cacheBindings[b].retrievalOptions,
                       (unsigned long long)imageGeneration,
                       targetCount,
                       (unsigned long long)expected,
                       (unsigned long long)cached,
                       exactSupported,
                       exactMatch,
                       backingVerification.backingNativeMatches,
                       backingVerification.backingReads,
                       expectedBackingReads,
                       backingMatch);
                }
            }
            if (iconSeededEverywhere) stats->cacheSeededIcons++;
        }
    }
    free(plannedTargetCounts);
    free(plannedTargets);

    int cacheMutationCalls = stats->cacheWarmCalls +
                             stats->cacheUpdateCalls +
                             stats->cacheSeedCalls;
    int expectedCachePairs = stats->associationsVerified *
                             stats->cacheBindingCount;
    // Source success covers the provider-backed canonical icons that actually
    // materialized and verified. Theme entries for uninstalled/unsupported apps
    // remain diagnostic misses; they must not invalidate an otherwise durable
    // canonical source set.
    bool sourceCoverageComplete = stats->associationsVerified > 0 &&
        stats->providerTrackCalled &&
        stats->providerTrackConfirmed == stats->providerTrackRequested &&
        stats->associationsVerified == stats->uniqueCanonicalHits &&
        stats->repositoryVerified >= stats->associationsVerified;
    bool cacheWarmComplete = stats->cacheUsable &&
        cacheMutationCalls > 0 &&
        stats->cacheSeedCalls > 0 &&
        stats->cacheSeededIcons == stats->associationsVerified &&
        stats->cacheSeedPairs == expectedCachePairs &&
        stats->cacheSamples == expectedCachePairs &&
        stats->cacheSampleMatches == stats->cacheSamples;
    bool themeCoverageComplete = sourceCoverageComplete &&
        stats->canonicalMisses == 0 &&
        stats->associationsVerified == stats->themeEntries &&
        stats->bundleMismatches == 0 &&
        stats->repositoryMismatches == 0 &&
        stats->failures == 0;
    bool success = sourceCoverageComplete &&
                   stats->failures == 0 &&
                   stats->pointerConflicts == 0 &&
                   !stats->timedOut &&
                   !stats->cancelled &&
                   remote_call_current_success();
    uint64_t candidateImageCount =
        themer_remote_count(candidateThemeRepository);
    uint64_t candidateIconCount =
        themer_remote_count(candidateIconRepository);
    uint64_t candidateProviderCount =
        themer_remote_count(candidateProviderRepository);
    uint64_t candidateClassCount =
        themer_remote_count(candidateClassRepository);
    if (success &&
        (candidateImageCount != (uint64_t)stats->associationsVerified ||
         candidateIconCount != (uint64_t)stats->associationsVerified ||
         candidateProviderCount != (uint64_t)stats->associationsVerified ||
         candidateClassCount != (uint64_t)stats->associationsVerified)) {
        printf("[SPOTLIGHT_PRELOAD] failure phase=process-state-coverage "
               "images=%llu icons=%llu providers=%llu classes=%llu "
               "accepted=%d\n",
               (unsigned long long)candidateImageCount,
               (unsigned long long)candidateIconCount,
               (unsigned long long)candidateProviderCount,
               (unsigned long long)candidateClassCount,
               stats->associationsVerified);
        success = false;
    }

    uint64_t candidateState = 0;
    uint64_t candidatePIDString = 0;
    uint64_t candidateGenerationString = 0;
    uint64_t candidateGeneration = gThemerSpotlightApplyGeneration + 1;
    if (success) {
        char pidBuffer[32] = {0};
        char generationBuffer[32] = {0};
        snprintf(pidBuffer, sizeof(pidBuffer), "%d",
                 remote_call_current_pid());
        snprintf(generationBuffer, sizeof(generationBuffer), "%llu",
                 (unsigned long long)candidateGeneration);
        candidatePIDString = r_nsstr_retained(pidBuffer);
        candidateGenerationString = r_nsstr_retained(generationBuffer);

        uint64_t stateAlloc = r_is_objc_ptr(dictionaryClass)
            ? r_msg2(dictionaryClass, "alloc", 0, 0, 0, 0) : 0;
        candidateState = r_is_objc_ptr(stateAlloc)
            ? r_msg2_main(stateAlloc, "initWithCapacity:", 10, 0, 0, 0)
            : 0;
        bool stateReady = r_is_objc_ptr(candidateState) &&
            themer_spotlight_dictionary_set_object(
                candidateState, "images", candidateThemeRepository) &&
            themer_spotlight_dictionary_set_object(
                candidateState, "icons", candidateIconRepository) &&
            themer_spotlight_dictionary_set_object(
                candidateState, "providers", candidateProviderRepository) &&
            themer_spotlight_dictionary_set_object(
                candidateState, "classes", candidateClassRepository) &&
            themer_spotlight_dictionary_set_object(
                candidateState, "owner", stats->owner) &&
            themer_spotlight_dictionary_set_object(
                candidateState, "dataSource", stats->dataSource) &&
            themer_spotlight_dictionary_set_object(
                candidateState, "iconModel", stats->iconModel) &&
            themer_spotlight_dictionary_set_object(
                candidateState, "pid", candidatePIDString) &&
            themer_spotlight_dictionary_set_object(
                candidateState, "generation", candidateGenerationString);
        if (stateReady && r_is_objc_ptr(stats->repository)) {
            stateReady = themer_spotlight_dictionary_set_object(
                candidateState, "repository", stats->repository);
        }
        if (!stateReady) {
            printf("[SPOTLIGHT_PRELOAD] failure phase=process-state-build\n");
            success = false;
        }
    }

    uint64_t previousThemeState = 0;
    uint64_t previousThemeRepository = 0;
    bool previousThemeStateRetained = false;
    bool previousThemeRepositoryRetained = false;
    if (success) {
        previousThemeState = themer_spotlight_theme_state();
        previousThemeRepository =
            themer_spotlight_associated_process_object(
                "cndSpotlightThemeImageRepository");
        if (r_is_objc_ptr(previousThemeState)) {
            r_msg2(previousThemeState, "retain", 0, 0, 0, 0);
            previousThemeStateRetained = remote_call_current_success();
        }
        if (r_is_objc_ptr(previousThemeRepository)) {
            r_msg2(previousThemeRepository, "retain", 0, 0, 0, 0);
            previousThemeRepositoryRetained =
                remote_call_current_success();
        }
    }

    bool stateCommitted = false;
    bool repositoryCommitted = false;
    if (success) {
        stateCommitted = themer_spotlight_commit_theme_state(candidateState);
        repositoryCommitted = stateCommitted &&
            themer_spotlight_commit_theme_repository(
                candidateThemeRepository);
        if (!stateCommitted || !repositoryCommitted) {
            printf("[SPOTLIGHT_PRELOAD] failure phase=process-state-commit "
                   "state=%d images=%d\n",
                   stateCommitted, repositoryCommitted);
            (void)themer_spotlight_commit_theme_state(
                previousThemeStateRetained ? previousThemeState : 0);
            (void)themer_spotlight_commit_theme_repository(
                previousThemeRepositoryRetained
                    ? previousThemeRepository : 0);
            success = false;
        }
    }
    if (success) {
        bool armed = themer_spotlight_monitor_arm(
            icons, providers, iconBundles, iconCount,
            cacheBindings, stats->cacheBindingCount,
            stats->owner, stats->dataSource,
            stats->iconModel, stats->repository);
        if (!armed) {
            printf("[SPOTLIGHT_PRELOAD] failure phase=monitor-arm "
                   "action=process-state-rollback\n");
            (void)themer_spotlight_commit_theme_state(
                previousThemeStateRetained ? previousThemeState : 0);
            (void)themer_spotlight_commit_theme_repository(
                previousThemeRepositoryRetained
                    ? previousThemeRepository : 0);
        }
        success = armed;
    }
    if (success && previousThemeStateRetained &&
        previousThemeState != candidateState) {
        bool staleRestoreComplete = false;
        int staleRestored = themer_spotlight_restore_state_icons(
            previousThemeState, candidateIconRepository, false,
            &staleRestoreComplete);
        printf("[SPOTLIGHT_PRELOAD] previous-state-prune restored=%d "
               "complete=%d\n",
               staleRestored, staleRestoreComplete);
        success = staleRestoreComplete && remote_call_current_success();
    }
    if (success) {
        gThemerSpotlightApplyGeneration = candidateGeneration;
    }
    if (previousThemeStateRetained && remote_call_current_success()) {
        r_msg2(previousThemeState, "release", 0, 0, 0, 0);
    }
    if (previousThemeRepositoryRetained &&
        remote_call_current_success()) {
        r_msg2(previousThemeRepository, "release", 0, 0, 0, 0);
    }
    printf("[SPOTLIGHT_PRELOAD] complete success=%d source=%d "
           "cacheWarm=%s entries=%d coverage=%s accepted=%d "
           "track=%d/%d called=%d supported=%d providers=%d->%d "
           "canonicalHits=%d uniqueCanonicalHits=%d canonicalMisses=%d "
           "repository=%d/%d invalidationCalls=%d bundleMismatches=%d "
           "pointerDuplicates=%d pointerConflicts=%d uploads=%d "
           "sized=%d providerGrafted=%d providerClassChanged=%d "
           "providerAssoc=%d/%d providerFailures=%d "
           "grafted=%d classChanged=%d verified=%d failures=%d "
           "cache=0x%llx usable=%d bindings=%d targets=%d "
           "purgeCalls=%d warmCalls=%d "
           "updateCalls=%d seedCalls=%d seededIcons=%d seedPairs=%d/%d "
           "mutationCalls=%d "
           "cacheSamples=%d cacheSampleMatches=%d render=%d/%d "
           "optioned=%d/%d "
           "legacy=%d/%d backing=%d/%d/%d timedOut=%d cancelled=%d "
           "remoteHealthy=%d total=%llums\n",
           success,
           sourceCoverageComplete,
           !kThemerSpotlightCanonicalCacheWarmEnabled
               ? "skipped-source-first"
               : (stats->cacheUsable
                      ? (cacheWarmComplete ? "complete" : "partial")
                      : "skipped-no-carrier"),
           stats->themeEntries,
           themeCoverageComplete ? "complete" : "partial",
           stats->associationsVerified,
           stats->providerTrackConfirmed,
           stats->providerTrackRequested,
           stats->providerTrackCalled,
           stats->providerTrackSupported,
           stats->providerEntriesBeforeTracking,
           stats->providerEntriesAfterTracking,
           stats->canonicalHits,
           stats->uniqueCanonicalHits,
           stats->canonicalMisses,
           stats->repositoryVerified,
           stats->repositoryMismatches,
           stats->sourceInvalidationCalls,
           stats->bundleMismatches,
           stats->pointerDuplicates,
           stats->pointerConflicts,
           stats->uploads,
           stats->sizedImages,
           stats->providersGrafted,
           stats->providerClassChanged,
           stats->providerImageAssociations,
           stats->providerLayerAssociations,
           stats->providerFailures,
           stats->grafted,
           stats->classChanged,
           stats->associationsVerified,
           stats->failures,
           (unsigned long long)stats->cache,
           stats->cacheUsable,
           stats->cacheBindingCount,
           stats->cacheTargetCount,
           stats->cachePurgeCalls,
           stats->cacheWarmCalls,
           stats->cacheUpdateCalls,
           stats->cacheSeedCalls,
           stats->cacheSeededIcons,
           stats->cacheSeedPairs,
           expectedCachePairs,
           cacheMutationCalls,
           stats->cacheSamples,
           stats->cacheSampleMatches,
           stats->cacheRenderMatches,
           stats->cacheRenderReads,
           stats->cacheOptionedMatches,
           stats->cacheOptionedReads,
           stats->cacheLegacyMatches,
           stats->cacheLegacyReads,
           stats->cacheBackingMatches,
           stats->cacheBackingReads,
           stats->cacheExpectedBackingReads,
           stats->timedOut,
           stats->cancelled,
           remote_call_current_success(),
           (unsigned long long)((themer_now_us() - startUS) / 1000ULL));
    if (r_is_objc_ptr(candidateState) && remote_call_current_success()) {
        r_msg2(candidateState, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(candidatePIDString) && remote_call_current_success()) {
        r_msg2(candidatePIDString, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(candidateGenerationString) &&
        remote_call_current_success()) {
        r_msg2(candidateGenerationString, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(candidateThemeRepository) &&
        remote_call_current_success()) {
        r_msg2(candidateThemeRepository, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(candidateIconRepository) &&
        remote_call_current_success()) {
        r_msg2(candidateIconRepository, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(candidateProviderRepository) &&
        remote_call_current_success()) {
        r_msg2(candidateProviderRepository, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(candidateClassRepository) &&
        remote_call_current_success()) {
        r_msg2(candidateClassRepository, "release", 0, 0, 0, 0);
    }
    return success;
}

bool themer_apply_spotlight_data_in_session(
    NSDictionary<NSString *, NSData *> *imageDataByBundle,
    volatile int *stopRequested)
{
    // Keep the last verified monitor snapshot alive until a replacement
    // preload has completely succeeded and atomically arms a new snapshot.
    themer_spotlight_lifecycle_trace_forget();
    uint64_t totalStartUS = themer_now_us();
    NSDictionary<NSString *, NSData *> *normalized =
        themer_normalized_theme_data(imageDataByBundle);
    if (normalized.count == 0) {
        printf("[SPOTLIGHT_PRELOAD] skipped reason=empty-theme\n");
        return false;
    }

    uint32_t previousSettleUS = r_settle_us(1000);
    ThemerSpotlightCanonicalStats stats = {0};
    bool success = themer_spotlight_apply_canonical_theme(
        normalized, &stats, stopRequested);
    r_settle_us(previousSettleUS);
    printf("[SPOTLIGHT_PRELOAD] action success=%d entries=%lu "
           "remoteHealthy=%d total=%llums\n",
           success,
           (unsigned long)normalized.count,
           remote_call_current_success(),
           (unsigned long long)((themer_now_us() - totalStartUS) / 1000ULL));
    return success && remote_call_current_success();
}

bool themer_apply_spotlight_rows_in_session(
    NSDictionary<NSString *, NSData *> *imageDataByBundle)
{
    themer_spotlight_lifecycle_trace_forget();
    uint64_t totalStartUS = themer_now_us();
    NSDictionary<NSString *, NSData *> *normalized =
        themer_normalized_theme_data(imageDataByBundle);
    if (normalized.count == 0) {
        printf("[SPOTLIGHT] single-probe skipped reason=empty-theme\n");
        return false;
    }

    uint32_t previousSettleUS = r_settle_us(5000);
    enum { VIEW_CAP = 64, IMAGE_CAP = 1, CACHE_TARGET_CAP = 32 };
    uint64_t views[VIEW_CAP] = {0};
    int viewCount = themer_spotlight_collect_searchui_views(views, VIEW_CAP);
    uint64_t collectEndUS = themer_now_us();
    printf("[SPOTLIGHT] single-probe begin pid=%d entries=%lu views=%d collect=%llums\n",
           remote_call_current_pid(),
           (unsigned long)normalized.count,
           viewCount,
           (unsigned long long)((collectEndUS - totalStartUS) / 1000ULL));
    if (viewCount == 0) {
        r_settle_us(previousSettleUS);
        return false;
    }

    typedef struct {
        int index;
        uint64_t view;
        uint64_t appIcon;
        char bundle[192];
        char bundleSource[160];
    } ThemerSpotlightProbeCandidate;

    ThemerSpotlightProbeCandidate selected = {
        .index = -1,
    };
    ThemerSpotlightProbeCandidate fallback = {
        .index = -1,
    };
    int visibleCandidates = 0;
    int bundleCandidates = 0;
    int themeCandidates = 0;

    for (int i = 0; i < viewCount; i++) {
        uint64_t view = views[i];
        int hidden = themer_remote_hidden(view);
        double alpha = themer_remote_alpha(view);
        if (hidden == 1 || (alpha >= 0.0 && alpha < 0.01)) continue;
        visibleCandidates++;

        uint64_t appIcon = themer_spotlight_app_icon_for_view(view, NULL, 0);
        if (!r_is_objc_ptr(appIcon)) continue;

        char bundle[192] = {0};
        char bundleSource[160] = {0};
        if (!themer_spotlight_bundle_for_patch(view, appIcon,
                                               bundle, sizeof(bundle),
                                               bundleSource,
                                               sizeof(bundleSource))) {
            continue;
        }
        bundleCandidates++;

        NSString *key = [NSString stringWithUTF8String:bundle];
        NSData *bytes = themer_theme_data_for_key(normalized, key, NULL);
        if (![bytes isKindOfClass:NSData.class] || bytes.length == 0) continue;
        themeCandidates++;

        ThemerSpotlightProbeCandidate candidate = {
            .index = i,
            .view = view,
            .appIcon = appIcon,
        };
        snprintf(candidate.bundle, sizeof(candidate.bundle), "%s", bundle);
        snprintf(candidate.bundleSource, sizeof(candidate.bundleSource),
                 "%s", bundleSource[0] ? bundleSource : "-");

        if (strcmp(bundle, "com.zeroxjf.ios-cyanide1") == 0) {
            if (fallback.index < 0) fallback = candidate;
            continue;
        }
        selected = candidate;
        break;
    }
    if (selected.index < 0) selected = fallback;

    uint64_t selectEndUS = themer_now_us();
    if (selected.index < 0) {
        printf("[SPOTLIGHT] single-probe stopped reason=no-visible-themed-icon "
               "visible=%d bundles=%d themeHits=%d select=%llums total=%llums\n",
               visibleCandidates,
               bundleCandidates,
               themeCandidates,
               (unsigned long long)((selectEndUS - collectEndUS) / 1000ULL),
               (unsigned long long)((selectEndUS - totalStartUS) / 1000ULL));
        r_settle_us(previousSettleUS);
        return false;
    }

    char viewClass[96] = {0};
    char iconClass[96] = {0};
    themer_read_class_name(selected.view, viewClass, sizeof(viewClass));
    themer_read_class_name(selected.appIcon, iconClass, sizeof(iconClass));
    printf("[SPOTLIGHT] single-probe selected index=%d bundle=%s "
           "bundleSource=%s view=0x%llx/%s appIcon=0x%llx/%s "
           "visible=%d bundles=%d themeHits=%d select=%llums\n",
           selected.index,
           selected.bundle,
           selected.bundleSource,
           (unsigned long long)selected.view,
           viewClass[0] ? viewClass : "-",
           (unsigned long long)selected.appIcon,
           iconClass[0] ? iconClass : "-",
           visibleCandidates,
           bundleCandidates,
           themeCandidates,
           (unsigned long long)((selectEndUS - collectEndUS) / 1000ULL));

    ThemerSpotlightRemoteImage images[IMAGE_CAP] = {{0}};
    int imageCount = 0;
    uint64_t sourceImage = themer_spotlight_remote_image_for_bundle(
        normalized, selected.bundle, images, &imageCount, IMAGE_CAP);
    uint64_t uploadEndUS = themer_now_us();
    if (!r_is_objc_ptr(sourceImage)) {
        printf("[SPOTLIGHT] single-probe stopped reason=image-upload-failed "
               "bundle=%s upload=%llums total=%llums\n",
               selected.bundle,
               (unsigned long long)((uploadEndUS - selectEndUS) / 1000ULL),
               (unsigned long long)((uploadEndUS - totalStartUS) / 1000ULL));
        r_settle_us(previousSettleUS);
        return false;
    }

    uint64_t carrier = themer_spotlight_image_carrier_for_view(selected.view);
    uint64_t stockImage = themer_spotlight_image_from_carrier(carrier);
    char cacheSource[128] = {0};
    uint64_t cache = themer_spotlight_find_icon_cache(
        selected.view, carrier, selected.appIcon,
        cacheSource, sizeof(cacheSource));
    const char *stockSelector = NULL;
    if (!r_is_objc_ptr(stockImage)) {
        stockImage = themer_spotlight_cached_image(cache,
                                                   selected.appIcon,
                                                   &stockSelector);
    }

    double targetW = 0.0;
    double targetH = 0.0;
    double stockScale = 0.0;
    bool stockGeometry = themer_read_image_geometry(stockImage,
                                                    &targetW,
                                                    &targetH,
                                                    &stockScale);
    if (!stockGeometry) {
        ThemerRect carrierBounds = {0};
        if (themer_read_rect(carrier, "bounds", &carrierBounds) &&
            carrierBounds.w >= 8.0 && carrierBounds.w <= 180.0) {
            targetW = carrierBounds.w;
            targetH = carrierBounds.h;
        } else {
            targetW = 60.0;
            targetH = 60.0;
        }
        stockScale = themer_screen_scale();
    }

    uint64_t adjusted = themer_spotlight_provider_sized_themed_image(
        sourceImage, targetW, stockScale);
    uint64_t patchImage = r_is_objc_ptr(adjusted) ? adjusted : sourceImage;
    char appearanceSource[128] = {0};
    uint64_t appearance = themer_spotlight_image_appearance(
        selected.view, carrier,
        appearanceSource, sizeof(appearanceSource));

    char carrierClass[96] = {0};
    char cacheClass[96] = {0};
    themer_read_class_name(carrier, carrierClass, sizeof(carrierClass));
    themer_read_class_name(cache, cacheClass, sizeof(cacheClass));
    ThemerSpotlightCacheTarget cacheTargets[CACHE_TARGET_CAP] = {{0}};
    int cacheTargetCount = themer_spotlight_collect_cache_targets(
        cache, cacheTargets, CACHE_TARGET_CAP);

    uint64_t prepareEndUS = themer_now_us();
    printf("[SPOTLIGHT] single-probe objects carrier=0x%llx/%s "
           "cache=0x%llx/%s cacheSource=%s cacheTargets=%d "
           "appearance=0x%llx/%s stock=0x%llx/%s "
           "stockGeom=%d target=%.1fx%.1f@%.2f patch=0x%llx "
           "prepare=%llums\n",
           (unsigned long long)carrier,
           carrierClass[0] ? carrierClass : "-",
           (unsigned long long)cache,
           cacheClass[0] ? cacheClass : "-",
           cacheSource[0] ? cacheSource : "-",
           cacheTargetCount,
           (unsigned long long)appearance,
           appearanceSource[0] ? appearanceSource : "-",
           (unsigned long long)stockImage,
           stockSelector ?: "carrier",
           stockGeometry,
           targetW,
           targetH,
           stockScale,
           (unsigned long long)patchImage,
           (unsigned long long)((prepareEndUS - uploadEndUS) / 1000ULL));

    uint64_t provider = themer_spotlight_trace_object_value(
        selected.appIcon, "activeDataSource", "_activeDataSource");
    bool providerClassChanged = false;
    int providerImageMatches = 0;
    int providerLayerMatches = 0;
    int providerGrafted = 0;
    if (kThemerSpotlightProviderGraftEnabled) {
        providerGrafted = themer_graft_spotlight_provider(
            provider, patchImage, targetW,
            &providerClassChanged,
            &providerImageMatches,
            &providerLayerMatches) ? 1 : 0;
    }

    ThemerEntry spotlightModelEntry = {0};
    bool modelClassChanged = false;
    int modelGrafted = themer_graft_spotlight_icon_model(
        selected.appIcon,
        patchImage,
        &spotlightModelEntry,
        selected.view,
        &modelClassChanged) ? 1 : 0;
    int modelAssociationMatches = modelGrafted
        ? themer_spotlight_model_association_matches(selected.appIcon,
                                                     patchImage)
        : 0;
    int invalidationCalls = 0;
    uint64_t imageGeneration = (r_is_objc_ptr(cache) &&
                                r_responds_main(cache,
                                               "currentImageGenerationForIcon:"))
        ? r_msg2_main(cache, "currentImageGenerationForIcon:",
                      selected.appIcon, 0, 0, 0)
        : 0;
    uint64_t upstreamEndUS = themer_now_us();

    int cacheSeedCalls = themer_spotlight_seed_cache_targets(
        cacheTargets, cacheTargetCount,
        patchImage, selected.appIcon, appearance,
        imageGeneration,
        true);
    int cacheRefreshCalls = 0;
    bool reset = false;
    ThemerSpotlightCacheVerification cacheVerification =
        themer_spotlight_verify_cache_targets(
            cacheTargets, cacheTargetCount,
            patchImage, selected.appIcon, appearance, true);

    int iconServicesSeeds = 0;
    if (cacheVerification.rootNativeMatches == 0 &&
        cacheVerification.backingNativeMatches == 0) {
        printf("[SPOTLIGHT] live-cache direct seed did not verify; "
               "IconServices fallback intentionally skipped\n");
    }
    int viewRefreshCalls = themer_spotlight_refresh_view_from_model(
        selected.view, cache, carrier, selected.appIcon, false);
    uint64_t refreshedAppIcon = themer_spotlight_app_icon_for_view(
        selected.view, NULL, 0);
    bool appIconReplaced = r_is_objc_ptr(refreshedAppIcon) &&
                           refreshedAppIcon != selected.appIcon;
    uint64_t refreshedCarrier =
        themer_spotlight_image_carrier_for_view(selected.view);
    if (r_is_objc_ptr(refreshedCarrier)) carrier = refreshedCarrier;
    uint64_t visibleImage = themer_spotlight_image_from_carrier(carrier);
    bool visibleFromUpstream = themer_spotlight_images_match(patchImage,
                                                             visibleImage);
    bool rowRefreshFallback = false;
    bool replacementReseeded = false;

    if (!visibleFromUpstream) {
        rowRefreshFallback = true;
        viewRefreshCalls += themer_spotlight_refresh_view_from_model(
            selected.view, cache, carrier, selected.appIcon, true);
        refreshedAppIcon = themer_spotlight_app_icon_for_view(
            selected.view, NULL, 0);
        appIconReplaced = r_is_objc_ptr(refreshedAppIcon) &&
                          refreshedAppIcon != selected.appIcon;

        if (appIconReplaced) {
            selected.appIcon = refreshedAppIcon;
            refreshedCarrier = themer_spotlight_image_carrier_for_view(
                selected.view);
            if (r_is_objc_ptr(refreshedCarrier)) carrier = refreshedCarrier;
            cache = themer_spotlight_find_icon_cache(
                selected.view, carrier, selected.appIcon,
                cacheSource, sizeof(cacheSource));
            appearance = themer_spotlight_image_appearance(
                selected.view, carrier,
                appearanceSource, sizeof(appearanceSource));

            memset(cacheTargets, 0, sizeof(cacheTargets));
            cacheTargetCount = themer_spotlight_collect_cache_targets(
                cache, cacheTargets, CACHE_TARGET_CAP);

            ThemerEntry replacementModelEntry = {0};
            provider = themer_spotlight_trace_object_value(
                selected.appIcon, "activeDataSource", "_activeDataSource");
            bool replacementProviderClassChanged = false;
            int replacementProviderImageMatches = 0;
            int replacementProviderLayerMatches = 0;
            int replacementProviderGrafted = 0;
            if (kThemerSpotlightProviderGraftEnabled) {
                replacementProviderGrafted =
                    themer_graft_spotlight_provider(
                    provider, patchImage, targetW,
                    &replacementProviderClassChanged,
                    &replacementProviderImageMatches,
                    &replacementProviderLayerMatches) ? 1 : 0;
            }
            providerGrafted += replacementProviderGrafted;
            providerClassChanged = providerClassChanged ||
                replacementProviderClassChanged;
            providerImageMatches += replacementProviderImageMatches;
            providerLayerMatches += replacementProviderLayerMatches;
            bool replacementClassChanged = false;
            int replacementModelGrafted = themer_graft_spotlight_icon_model(
                selected.appIcon,
                patchImage,
                &replacementModelEntry,
                selected.view,
                &replacementClassChanged) ? 1 : 0;
            modelGrafted += replacementModelGrafted;
            modelClassChanged = modelClassChanged || replacementClassChanged;
            if (replacementModelGrafted) {
                modelAssociationMatches +=
                    themer_spotlight_model_association_matches(
                        selected.appIcon, patchImage);
            }

            imageGeneration = (r_is_objc_ptr(cache) &&
                               r_responds_main(
                                   cache,
                                   "currentImageGenerationForIcon:"))
                ? r_msg2_main(cache, "currentImageGenerationForIcon:",
                              selected.appIcon, 0, 0, 0)
                : imageGeneration;
            int replacementSeedCalls =
                themer_spotlight_seed_cache_targets(
                    cacheTargets, cacheTargetCount,
                    patchImage, selected.appIcon, appearance,
                    imageGeneration,
                    true);
            cacheSeedCalls += replacementSeedCalls;
            replacementReseeded = replacementSeedCalls > 0;
            cacheVerification = themer_spotlight_verify_cache_targets(
                cacheTargets, cacheTargetCount,
                patchImage, selected.appIcon, appearance, true);
            viewRefreshCalls += themer_spotlight_refresh_view_from_model(
                selected.view, cache, carrier, selected.appIcon, false);
        }
    }

    uint64_t traceVariant = 0;
    bool traceVariantKnown = themer_spotlight_trace_variant_for_view(
        selected.view, &traceVariant);
    uint64_t expectedCG = themer_spotlight_trace_image_cg(patchImage);
    themer_spotlight_lifecycle_trace_arm(selected.bundle,
                                         expectedCG,
                                         traceVariant,
                                         traceVariantKnown);

    usleep(1500000);
    cacheVerification = themer_spotlight_verify_cache_targets(
        cacheTargets, cacheTargetCount,
        patchImage, selected.appIcon, appearance, true);

    uint64_t cacheEndUS = themer_now_us();
    refreshedCarrier = themer_spotlight_image_carrier_for_view(selected.view);
    if (r_is_objc_ptr(refreshedCarrier)) carrier = refreshedCarrier;
    visibleImage = themer_spotlight_image_from_carrier(carrier);
    visibleFromUpstream = themer_spotlight_images_match(patchImage,
                                                        visibleImage);
    bool durableMatch = modelAssociationMatches > 0 &&
                        cacheVerification.rootRenderMatches > 0;
    int directCalls = 0;
    if (durableMatch && !visibleFromUpstream) {
        directCalls = themer_spotlight_push_visible_image(
            selected.view, carrier, patchImage, appearance);
        refreshedCarrier = themer_spotlight_image_carrier_for_view(selected.view);
        if (r_is_objc_ptr(refreshedCarrier)) carrier = refreshedCarrier;
        visibleImage = themer_spotlight_image_from_carrier(carrier);
        visibleFromUpstream = themer_spotlight_images_match(patchImage,
                                                            visibleImage);
    }
    int presentationAlphaPins = 0;
    if (kThemerSpotlightPresentationAlphaPinEnabled &&
        durableMatch && visibleFromUpstream) {
        presentationAlphaPins =
            themer_spotlight_pin_ready_presentation_alpha(
                selected.view, carrier, expectedCG, "post-patch");
    }
    uint64_t visibleEndUS = themer_now_us();

    printf("[SPOTLIGHT] single-probe complete bundle=%s iconServicesSeeds=%d "
           "provider=0x%llx providerGrafted=%d providerClassChanged=%d "
           "providerAssoc=%d/%d "
           "modelGrafted=%d modelClassChanged=%d modelAssociationMatches=%d "
           "invalidationCalls=%d imageGeneration=%llu "
           "cacheSeedCalls=%d cacheRefreshCalls=%d delayedVerifyMS=%d "
           "viewRefreshCalls=%d "
           "rowRefreshFallback=%d appIconReplaced=%d replacementReseeded=%d "
           "rootCacheMatches=%d "
           "backingNativeMatches=%d keyedMatches=%d reset=%d "
           "visibleFromUpstream=%d directCalls=%d presentationAlphaPins=%d "
           "timing=collect:%llums,select:%llums,upload:%llums,prepare:%llums,"
           "upstream:%llums,cache:%llums,visible:%llums,total:%llums "
           "immediateVerification=%d\n",
           selected.bundle,
           iconServicesSeeds,
           (unsigned long long)provider,
           providerGrafted,
           providerClassChanged,
           providerImageMatches,
           providerLayerMatches,
           modelGrafted,
           modelClassChanged,
           modelAssociationMatches,
           invalidationCalls,
           (unsigned long long)imageGeneration,
           cacheSeedCalls,
           cacheRefreshCalls,
           1500,
           viewRefreshCalls,
           rowRefreshFallback,
           appIconReplaced,
           replacementReseeded,
           cacheVerification.rootNativeMatches,
           cacheVerification.backingNativeMatches,
           cacheVerification.keyedMatches,
           reset,
           visibleFromUpstream,
           directCalls,
           presentationAlphaPins,
           (unsigned long long)((collectEndUS - totalStartUS) / 1000ULL),
           (unsigned long long)((selectEndUS - collectEndUS) / 1000ULL),
           (unsigned long long)((uploadEndUS - selectEndUS) / 1000ULL),
           (unsigned long long)((prepareEndUS - uploadEndUS) / 1000ULL),
           (unsigned long long)((upstreamEndUS - prepareEndUS) / 1000ULL),
           (unsigned long long)((cacheEndUS - upstreamEndUS) / 1000ULL),
           (unsigned long long)((visibleEndUS - cacheEndUS) / 1000ULL),
           (unsigned long long)((visibleEndUS - totalStartUS) / 1000ULL),
           durableMatch);

    if (r_is_objc_ptr(adjusted)) {
        r_msg2(adjusted, "release", 0, 0, 0, 0);
    }
    for (int i = 0; i < imageCount; i++) {
        if (r_is_objc_ptr(images[i].image)) {
            r_msg2(images[i].image, "release", 0, 0, 0, 0);
        }
    }
    r_settle_us(previousSettleUS);
    bool representativeSuccess = durableMatch && visibleFromUpstream;
    bool allLiveRowsSuccess = false;
    if (representativeSuccess && remote_call_current_success()) {
        allLiveRowsSuccess =
            themer_apply_spotlight_data_live_in_session(imageDataByBundle);
    }
    printf("[SPOTLIGHT] all-live followup representative=%d "
           "allLiveRows=%d remoteHealthy=%d\n",
           representativeSuccess,
           allLiveRowsSuccess,
           remote_call_current_success());
    return representativeSuccess && allLiveRowsSuccess;
}

bool themer_apply_spotlight_rows_diagnostic_in_session(
    NSDictionary<NSString *, NSData *> *imageDataByBundle)
{
    return themer_apply_spotlight_rows_in_session(imageDataByBundle);
}

static int themer_spotlight_probe_searchui_views(void)
{
    uint64_t cls = themer_lookup_class("SearchUIHomeScreenAppIconView");
    if (!r_is_objc_ptr(cls)) {
        printf("[SPOTLIGHT] searchui-view scan skipped: SearchUIHomeScreenAppIconView unavailable\n");
        return 0;
    }

    enum { VIEW_CAP = 64 };
    uint64_t views[VIEW_CAP] = {0};
    int count = themer_spotlight_collect_searchui_views(views, VIEW_CAP);
    printf("[SPOTLIGHT] searchui-view scan begin class=0x%llx views=%d\n",
           (unsigned long long)cls,
           count);

    int logged = 0;
    int bundleHits = 0;
    for (int i = 0; i < count && logged < 48; i++) {
        uint64_t view = views[i];
        if (!r_is_objc_ptr(view)) continue;

        char viewClass[96] = {0};
        themer_read_class_name(view, viewClass, sizeof(viewClass));
        ThemerRect frame = {0};
        bool hasFrame = themer_read_rect(view, "frame", &frame);
        int hidden = themer_remote_hidden(view);
        double alpha = themer_remote_alpha(view);

        char appIconSource[128] = {0};
        uint64_t appIcon = themer_spotlight_app_icon_for_view(view,
                                                              appIconSource,
                                                              sizeof(appIconSource));
        char appIconClass[96] = {0};
        themer_read_class_name(appIcon, appIconClass, sizeof(appIconClass));

        char bundle[192] = {0};
        char bundleSource[192] = {0};
        bool bundleFromIcon = false;
        bool hasBundle = themer_spotlight_bundle_for_view(view,
                                                          appIcon,
                                                          bundle,
                                                          sizeof(bundle),
                                                          bundleSource,
                                                          sizeof(bundleSource),
                                                          &bundleFromIcon);
        if (hasBundle) bundleHits++;

        uint64_t themedImage = hasBundle ? themer_lookup_cached(bundle) : 0;
        uint64_t rowModel = r_responds_main(view, "rowModel")
            ? r_msg2_main(view, "rowModel", 0, 0, 0, 0) : 0;
        char rowModelClass[96] = {0};
        themer_read_class_name(rowModel, rowModelClass, sizeof(rowModelClass));
        int suggestion = r_responds_main(view, "isInSuggestionContext")
            ? (int)(r_msg2_main(view, "isInSuggestionContext", 0, 0, 0, 0) & 1)
            : -1;

        printf("[SPOTLIGHT] searchui-view index=%d obj=0x%llx class=%s hidden=%d alpha=%.2f "
               "frame=%s%.1f,%.1f %.1fx%.1f suggestion=%d rowModel=0x%llx rowModelClass=%s "
               "appIcon=0x%llx appIconClass=%s appIconSource=%s bundle=%s bundleSource=%s "
               "bundleFromIcon=%d themedImage=0x%llx resetSel=%d\n",
               i,
               (unsigned long long)view,
               viewClass,
               hidden,
               alpha,
               hasFrame ? "" : "?",
               frame.x, frame.y, frame.w, frame.h,
               suggestion,
               (unsigned long long)rowModel,
               rowModelClass[0] ? rowModelClass : "-",
               (unsigned long long)appIcon,
               appIconClass,
               appIconSource[0] ? appIconSource : "-",
               hasBundle ? bundle : "-",
               hasBundle ? bundleSource : "-",
               bundleFromIcon,
               (unsigned long long)themedImage,
               r_responds_main(view, "resetImageWithAppIcon:"));
        logged++;
    }

    printf("[SPOTLIGHT] searchui-view scan complete views=%d logged=%d bundleHits=%d\n",
           count,
           logged,
           bundleHits);
    return logged;
}

typedef struct {
    uint64_t view;
    char source[48];
} ThemerSpotlightIconViewHit;

static NSString *themer_spotlight_iconview_path(uint64_t view,
                                                bool *searchPathOut)
{
    if (searchPathOut) *searchPathOut = false;
    NSMutableArray<NSString *> *items = [NSMutableArray array];
    uint64_t cursor = view;
    for (int depth = 0; r_is_objc_ptr(cursor) && depth < 7; depth++) {
        char className[96] = {0};
        themer_read_class_name(cursor, className, sizeof(className));
        if (className[0]) {
            [items addObject:[NSString stringWithUTF8String:className]];
            static const char *searchNeedles[] = {
                "Search", "Spotlight", "Siri", "Suggest", "Suggestion",
                "Result", "SPUI", "CS"
            };
            if (searchPathOut &&
                themer_cstring_has_any(className, searchNeedles,
                                       sizeof(searchNeedles) / sizeof(searchNeedles[0]))) {
                *searchPathOut = true;
            }
        }
        cursor = r_responds_main(cursor, "superview")
            ? r_msg2_main(cursor, "superview", 0, 0, 0, 0) : 0;
    }
    return items.count ? [items componentsJoinedByString:@"<"] : @"";
}

static bool themer_spotlight_tree_has_search_hint(uint64_t root,
                                                  int depth,
                                                  int maxDepth,
                                                  NSMutableArray<NSString *> *samples)
{
    if (!r_is_objc_ptr(root) || depth > maxDepth) return false;

    char className[96] = {0};
    themer_read_class_name(root, className, sizeof(className));
    bool hint = themer_spotlight_class_has_search_hint(className);
    if (className[0] && (hint || depth <= 1) && samples.count < 24) {
        [samples addObject:[NSString stringWithFormat:@"%*s%s%s",
                            depth * 2,
                            "",
                            className,
                            hint ? "*" : ""]];
    }

    if (depth >= maxDepth || !r_responds_main(root, "subviews")) {
        return hint;
    }
    uint64_t subs = r_msg2_main(root, "subviews", 0, 0, 0, 0);
    uint64_t count = themer_collection_count_capped(subs, 20);
    for (uint64_t i = 0; i < count; i++) {
        uint64_t child = r_msg2_main(subs, "objectAtIndex:", i, 0, 0, 0);
        if (themer_spotlight_tree_has_search_hint(child,
                                                  depth + 1,
                                                  maxDepth,
                                                  samples)) {
            hint = true;
        }
    }
    return hint;
}

static bool themer_spotlight_add_iconview_hit(ThemerSpotlightIconViewHit *hits,
                                              int *count,
                                              int cap,
                                              uint64_t view,
                                              const char *source)
{
    if (!hits || !count || *count >= cap || !r_is_objc_ptr(view)) return false;
    for (int i = 0; i < *count; i++) {
        if (hits[i].view == view) return false;
    }
    hits[*count].view = view;
    snprintf(hits[*count].source, sizeof(hits[*count].source),
             "%s", source && source[0] ? source : "unknown");
    (*count)++;
    return true;
}

static int themer_spotlight_collect_iconviews_from_window(uint64_t window,
                                                          uint64_t iconViewCls,
                                                          ThemerSpotlightIconViewHit *hits,
                                                          int *count,
                                                          int cap,
                                                          const char *source)
{
    if (!r_is_objc_ptr(window) || !r_is_objc_ptr(iconViewCls) ||
        !hits || !count || *count >= cap) {
        return 0;
    }

    enum { LOCAL_CAP = 96 };
    uint64_t views[LOCAL_CAP] = {0};
    int found = sb_collect_views(window, iconViewCls, views, LOCAL_CAP);
    int added = 0;
    for (int i = 0; i < found && *count < cap; i++) {
        if (themer_spotlight_add_iconview_hit(hits, count, cap,
                                              views[i], source)) {
            added++;
        }
    }
    return added;
}

static uint64_t themer_spotlight_collection_array(uint64_t collection)
{
    if (!r_is_objc_ptr(collection)) return 0;
    if (r_responds_main(collection, "objectAtIndex:")) return collection;
    if (r_responds_main(collection, "allObjects")) {
        uint64_t allObjects = r_msg2_main(collection, "allObjects", 0, 0, 0, 0);
        if (r_is_objc_ptr(allObjects) &&
            r_responds_main(allObjects, "objectAtIndex:")) {
            return allObjects;
        }
    }
    return 0;
}

static bool themer_spotlight_window_class_should_scan(const char *className)
{
    if (!className || !className[0]) return false;
    if (strcmp(className, "SBHomeScreenWindow") == 0) return true;

    // Keep this intentionally narrow. A child-tree probe is far too slow over
    // RemoteCall; class-name filtering is enough to reach Spotlight's host.
    static const char *needles[] = {
        "Search",
        "Spotlight",
        "Siri",
        "Suggestion",
        "Suggest"
    };
    return themer_cstring_has_any(className, needles,
                                  sizeof(needles) / sizeof(needles[0]));
}

static int themer_spotlight_collect_iconviews_from_windows(uint64_t windows,
                                                           uint64_t iconViewCls,
                                                           ThemerSpotlightIconViewHit *hits,
                                                           int *count,
                                                           int cap,
                                                           const char *source,
                                                           int *windowCountOut,
                                                           int *hintedWindowsOut)
{
    if (windowCountOut) *windowCountOut = 0;
    if (hintedWindowsOut) *hintedWindowsOut = 0;
    uint64_t array = themer_spotlight_collection_array(windows);
    uint64_t windowCount = themer_collection_count_capped(array, 48);
    if (windowCountOut) *windowCountOut = (int)windowCount;

    int added = 0;
    for (uint64_t i = 0; i < windowCount && *count < cap; i++) {
        uint64_t window = r_msg2_main(array, "objectAtIndex:", i, 0, 0, 0);
        if (!r_is_objc_ptr(window)) continue;

        char windowClass[96] = {0};
        themer_read_class_name(window, windowClass, sizeof(windowClass));
        int hidden = themer_remote_hidden(window);
        double alpha = themer_remote_alpha(window);
        bool searchHint = themer_spotlight_window_class_should_scan(windowClass);
        bool visible = hidden != 1 && alpha > 0.01;
        if (searchHint && hintedWindowsOut) (*hintedWindowsOut)++;
        if (i < 24 || searchHint) {
            printf("[SPOTLIGHT] iconview-window source=%s index=%llu class=%s visible=%d classHint=%d\n",
                   source && source[0] ? source : "unknown",
                   (unsigned long long)i,
                   windowClass[0] ? windowClass : "?",
                   visible,
                   searchHint);
        }
        if (!visible || !searchHint) continue;

        added += themer_spotlight_collect_iconviews_from_window(window,
                                                               iconViewCls,
                                                               hits,
                                                               count,
                                                               cap,
                                                               source);
    }
    return added;
}

static int themer_spotlight_collect_iconviews(ThemerSpotlightIconViewHit *hits,
                                              int cap,
                                              int *appWindowsOut,
                                              int *appAddedOut,
                                              int *sceneCountOut,
                                              int *sceneWindowsOut,
                                              int *sceneAddedOut)
{
    if (appWindowsOut) *appWindowsOut = 0;
    if (appAddedOut) *appAddedOut = 0;
    if (sceneCountOut) *sceneCountOut = 0;
    if (sceneWindowsOut) *sceneWindowsOut = 0;
    if (sceneAddedOut) *sceneAddedOut = 0;
    if (!hits || cap <= 0) return 0;

    uint64_t iconViewCls = r_class("SBIconView");
    uint64_t UIApplication = r_class("UIApplication");
    uint64_t app = r_is_objc_ptr(UIApplication)
        ? r_msg2_main(UIApplication, "sharedApplication", 0, 0, 0, 0) : 0;
    if (!r_is_objc_ptr(iconViewCls) || !r_is_objc_ptr(app)) return 0;

    int count = 0;
    uint64_t windows = r_responds_main(app, "windows")
        ? r_msg2_main(app, "windows", 0, 0, 0, 0) : 0;
    int appWindows = 0;
    int appHinted = 0;
    int appAdded = themer_spotlight_collect_iconviews_from_windows(windows,
                                                                   iconViewCls,
                                                                   hits,
                                                                   &count,
                                                                   cap,
                                                                   "app.windows",
                                                                   &appWindows,
                                                                   &appHinted);

    int sceneCount = 0;
    int sceneWindows = 0;
    int sceneAdded = 0;
    int sceneHinted = 0;
    uint64_t scenes = r_responds_main(app, "connectedScenes")
        ? r_msg2_main(app, "connectedScenes", 0, 0, 0, 0) : 0;
    uint64_t sceneArray = themer_spotlight_collection_array(scenes);
    uint64_t rawSceneCount = themer_collection_count_capped(sceneArray, 16);
    sceneCount = (int)rawSceneCount;
    for (uint64_t i = 0; i < rawSceneCount && count < cap; i++) {
        uint64_t scene = r_msg2_main(sceneArray, "objectAtIndex:", i, 0, 0, 0);
        if (!r_is_objc_ptr(scene)) continue;
        uint64_t sceneWindowsObj = r_responds_main(scene, "windows")
            ? r_msg2_main(scene, "windows", 0, 0, 0, 0) : 0;
        int localWindows = 0;
        char source[48] = {0};
        snprintf(source, sizeof(source), "scene[%llu].windows",
                 (unsigned long long)i);
        int localHinted = 0;
        int localAdded = themer_spotlight_collect_iconviews_from_windows(sceneWindowsObj,
                                                                         iconViewCls,
                                                                         hits,
                                                                         &count,
                                                                         cap,
                                                                         source,
                                                                         &localWindows,
                                                                         &localHinted);
        sceneWindows += localWindows;
        sceneHinted += localHinted;
        sceneAdded += localAdded;
    }

    if (appWindowsOut) *appWindowsOut = appWindows;
    if (appAddedOut) *appAddedOut = appAdded;
    if (sceneCountOut) *sceneCountOut = sceneCount;
    if (sceneWindowsOut) *sceneWindowsOut = sceneWindows;
    if (sceneAddedOut) *sceneAddedOut = sceneAdded;
    printf("[SPOTLIGHT] iconview-window summary appHinted=%d sceneHinted=%d\n",
           appHinted,
           sceneHinted);
    return count;
}

static int themer_spotlight_probe_iconviews(void)
{
    enum { HIT_CAP = 192 };
    ThemerSpotlightIconViewHit hits[HIT_CAP] = {{0}};
    int appWindows = 0;
    int appAdded = 0;
    int sceneCount = 0;
    int sceneWindows = 0;
    int sceneAdded = 0;
    int count = themer_spotlight_collect_iconviews(hits, HIT_CAP,
                                                   &appWindows,
                                                   &appAdded,
                                                   &sceneCount,
                                                   &sceneWindows,
                                                   &sceneAdded);
    printf("[SPOTLIGHT] iconview scan begin total=%d appWindows=%d appAdded=%d scenes=%d sceneWindows=%d sceneAdded=%d\n",
           count,
           appWindows,
           appAdded,
           sceneCount,
           sceneWindows,
           sceneAdded);

    uint64_t searchUICls = themer_lookup_class("SearchUIHomeScreenAppIconView");
    int logged = 0;
    int searchPathHits = 0;
    int bundleHits = 0;
    int suggestionHits = 0;
    for (int i = 0; i < count && logged < 96; i++) {
        uint64_t view = hits[i].view;
        if (!r_is_objc_ptr(view)) continue;

        bool searchPath = false;
        NSString *path = themer_spotlight_iconview_path(view, &searchPath);
        if (searchPath) searchPathHits++;

        char viewClass[96] = {0};
        themer_read_class_name(view, viewClass, sizeof(viewClass));
        uint64_t icon = r_responds_main(view, "icon")
            ? r_msg2_main(view, "icon", 0, 0, 0, 0) : 0;
        char iconClass[96] = {0};
        themer_read_class_name(icon, iconClass, sizeof(iconClass));

        char bundle[192] = {0};
        bool hasBundle = themer_read_bundle_for_icon(icon, view,
                                                     bundle, sizeof(bundle));
        if (hasBundle) bundleHits++;

        uint64_t themedImage = hasBundle ? themer_lookup_cached(bundle) : 0;
        uint64_t rowModel = r_responds_main(view, "rowModel")
            ? r_msg2_main(view, "rowModel", 0, 0, 0, 0) : 0;
        char rowModelClass[96] = {0};
        themer_read_class_name(rowModel, rowModelClass, sizeof(rowModelClass));
        int suggestion = r_responds_main(view, "isInSuggestionContext")
            ? (int)(r_msg2_main(view, "isInSuggestionContext", 0, 0, 0, 0) & 1)
            : -1;
        if (suggestion == 1) suggestionHits++;
        int isSearchUI = (r_is_objc_ptr(searchUICls) &&
                          r_msg2_main(view, "isKindOfClass:",
                                      searchUICls, 0, 0, 0)) ? 1 : 0;

        int shouldLog = searchPath || suggestion == 1 || isSearchUI ||
            rowModelClass[0] || hasBundle || logged < 36;
        if (!shouldLog) continue;

        ThemerRect frame = {0};
        bool hasFrame = themer_read_rect(view, "frame", &frame);
        int hidden = themer_remote_hidden(view);
        double alpha = themer_remote_alpha(view);

        printf("[SPOTLIGHT] iconview index=%d source=%s obj=0x%llx class=%s hidden=%d alpha=%.2f frame=%s%.1f,%.1f %.1fx%.1f searchUI=%d suggestion=%d searchPath=%d path=%s icon=0x%llx iconClass=%s bundle=%s rowModel=0x%llx rowModelClass=%s themedImage=0x%llx\n",
               i,
               hits[i].source,
               (unsigned long long)view,
               viewClass,
               hidden,
               alpha,
               hasFrame ? "" : "?",
               frame.x, frame.y, frame.w, frame.h,
               isSearchUI,
               suggestion,
               searchPath,
               path.length ? path.UTF8String : "-",
               (unsigned long long)icon,
               iconClass,
               hasBundle ? bundle : "-",
               (unsigned long long)rowModel,
               rowModelClass[0] ? rowModelClass : "-",
               (unsigned long long)themedImage);
        logged++;
    }

    printf("[SPOTLIGHT] iconview scan complete total=%d logged=%d searchPath=%d suggestion=%d bundleHits=%d\n",
           count,
           logged,
           searchPathHits,
           suggestionHits,
           bundleHits);
    return logged;
}

static int themer_spotlight_probe_iconservices(void)
{
    NSMutableArray<NSString *> *bundles = themer_spotlight_probe_bundles();
    printf("[SPOTLIGHT] snowboardbase probe begin cache=%d bundles=%lu list=%s\n",
           gThemerCacheCount,
           (unsigned long)bundles.count,
           bundles.count ? [bundles componentsJoinedByString:@","].UTF8String : "");
    if (bundles.count == 0) {
        printf("[SPOTLIGHT] snowboardbase probe note: SnowBoard Lite image cache is empty, so themedImage comparisons will be unavailable.\n");
    }

    int targetHits = themer_spotlight_log_snowboardbase_targets();
    themer_spotlight_log_class_shape("SearchUIHomeScreenAppIconView");
    themer_spotlight_log_class_shape("SBHIconImageCache");
    int classHits = themer_spotlight_log_candidate_classes();
    int providerHits = themer_spotlight_probe_app_icon_providers(bundles);
    int searchUIHits = themer_spotlight_probe_searchui_views();
    int iconViewHits = 0;
    printf("[SPOTLIGHT] iconview scan skipped: disabled because it crawls Home Screen icons instead of Spotlight provider paths\n");
    printf("[SPOTLIGHT] snowboardbase probe complete bundles=%lu targetHits=%d classHits=%d providerHits=%d searchUIHits=%d iconViewHits=%d iconservicesWrites=disabled methodSwaps=disabled providerAssetPatch=enabled\n",
           (unsigned long)bundles.count,
           targetHits,
           classHits,
           providerHits,
           searchUIHits,
           iconViewHits);
    return targetHits + classHits + providerHits + searchUIHits + iconViewHits;
}

bool themer_diagnose_spotlight_icons_in_session(void)
{
    uint64_t startUS = themer_now_us();
    gThemerSpotlightMethodLogBudget = 10;
    printf("[SPOTLIGHT] diagnostic begin pid=%d iosMajor=%d\n",
           remote_call_current_pid(),
           themer_host_ios_major());
    int targetHits = themer_spotlight_log_snowboardbase_targets();
    themer_spotlight_log_class_shape("SearchUIHomeScreenAppIconView");
    themer_spotlight_log_class_shape("SBHIconImageCache");
    int classHits = themer_spotlight_log_candidate_classes();
    int visibleLines = themer_spotlight_probe_searchui_views();
    int probeHits = targetHits + classHits;
    uint64_t elapsedUS = themer_now_us() - startUS;
    printf("[SPOTLIGHT] diagnostic complete visibleLines=%d probeHits=%d elapsed=%llums\n",
           visibleLines,
           probeHits,
           (unsigned long long)(elapsedUS / 1000ULL));
    return visibleLines > 0 || probeHits > 0;
}

static uint64_t themer_dynamic_overlay_for_iconview(uint64_t iconView)
{
    if (!r_is_objc_ptr(iconView)) return 0;
    uint64_t key = r_sel("cnd_themer_pinned_overlay");
    if (!key) return 0;
    uint64_t overlay = r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                                    iconView, key, 0, 0, 0, 0, 0, 0);
    if (r_is_objc_ptr(overlay)) return overlay;
    uint64_t iiv = themer_icon_image_view_for_iconview(iconView);
    if (!r_is_objc_ptr(iiv)) return 0;
    overlay = r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                           iiv, key, 0, 0, 0, 0, 0, 0);
    return r_is_objc_ptr(overlay) ? overlay : 0;
}

static void themer_log_view_node(const char *bundle,
                                 const char *kind,
                                 uint64_t view,
                                 int depth)
{
    if (!r_is_objc_ptr(view)) return;
    char cls[128] = {0};
    themer_read_class_name(view, cls, sizeof(cls));
    ThemerRect frame = {0};
    ThemerRect bounds = {0};
    bool hasFrame = themer_read_rect(view, "frame", &frame);
    bool hasBounds = themer_read_rect(view, "bounds", &bounds);
    printf("[THEMER] static-dynamic diag bundle=%s %*s%s=0x%llx class=%s hidden=%d alpha=%.2f frame=%s%.1f,%.1f %.1fx%.1f bounds=%s%.1f,%.1f %.1fx%.1f\n",
           bundle ?: "?",
           depth * 2, "",
           kind ?: "view",
           (unsigned long long)view,
           cls,
           themer_remote_hidden(view),
           themer_remote_alpha(view),
           hasFrame ? "" : "?",
           frame.x, frame.y, frame.w, frame.h,
           hasBounds ? "" : "?",
           bounds.x, bounds.y, bounds.w, bounds.h);
}

static void themer_log_layer_node(const char *bundle,
                                  uint64_t layer,
                                  int depth)
{
    if (!r_is_objc_ptr(layer)) return;
    char cls[128] = {0};
    themer_read_class_name(layer, cls, sizeof(cls));
    ThemerRect bounds = {0};
    bool hasBounds = themer_read_rect(layer, "bounds", &bounds);
    int hidden = -1;
    if (r_responds_main(layer, "isHidden")) {
        hidden = (r_msg2_main(layer, "isHidden", 0, 0, 0, 0) & 0xff) ? 1 : 0;
    }
    printf("[THEMER] static-dynamic diag bundle=%s %*slayer=0x%llx class=%s hidden=%d bounds=%s%.1f,%.1f %.1fx%.1f\n",
           bundle ?: "?",
           depth * 2, "",
           (unsigned long long)layer,
           cls,
           hidden,
           hasBounds ? "" : "?",
           bounds.x, bounds.y, bounds.w, bounds.h);
}

static void themer_log_view_subtree(const char *bundle,
                                    uint64_t view,
                                    int depth,
                                    int maxDepth)
{
    if (!r_is_objc_ptr(view) || depth > maxDepth) return;
    themer_log_view_node(bundle, depth == 0 ? "rootView" : "subview",
                         view, depth);
    if (depth == maxDepth || !r_responds_main(view, "subviews")) return;
    uint64_t subs = r_msg2_main(view, "subviews", 0, 0, 0, 0);
    uint64_t count = themer_collection_count_capped(subs, 24);
    uint64_t cap = count > 10 ? 10 : count;
    for (uint64_t i = 0; i < cap; i++) {
        uint64_t child = r_msg2_main(subs, "objectAtIndex:", i, 0, 0, 0);
        themer_log_view_subtree(bundle, child, depth + 1, maxDepth);
    }
    if (count > cap) {
        printf("[THEMER] static-dynamic diag bundle=%s %*s... %llu more subviews\n",
               bundle ?: "?", (depth + 1) * 2, "",
               (unsigned long long)(count - cap));
    }
}

static void themer_log_layer_subtree(const char *bundle,
                                     uint64_t layer,
                                     int depth,
                                     int maxDepth)
{
    if (!r_is_objc_ptr(layer) || depth > maxDepth) return;
    themer_log_layer_node(bundle, layer, depth);
    if (depth == maxDepth || !r_responds_main(layer, "sublayers")) return;
    uint64_t subs = r_msg2_main(layer, "sublayers", 0, 0, 0, 0);
    uint64_t count = themer_collection_count_capped(subs, 24);
    uint64_t cap = count > 10 ? 10 : count;
    for (uint64_t i = 0; i < cap; i++) {
        uint64_t child = r_msg2_main(subs, "objectAtIndex:", i, 0, 0, 0);
        themer_log_layer_subtree(bundle, child, depth + 1, maxDepth);
    }
    if (count > cap) {
        printf("[THEMER] static-dynamic diag bundle=%s %*s... %llu more sublayers\n",
               bundle ?: "?", (depth + 1) * 2, "",
               (unsigned long long)(count - cap));
    }
}

static void themer_log_static_dynamic_tree(const char *bundle,
                                           uint64_t iconView,
                                           uint64_t image)
{
    if (gThemerStaticDynamicTreeLogBudget <= 0 ||
        !themer_is_static_dynamic_icon_bundle(bundle) ||
        !r_is_objc_ptr(iconView)) {
        return;
    }
    gThemerStaticDynamicTreeLogBudget--;

    uint64_t iiv = themer_icon_image_view_for_iconview(iconView);
    uint64_t overlay = themer_dynamic_overlay_for_iconview(iconView);
    uint64_t iconLayer = r_responds_main(iconView, "layer")
        ? r_msg2_main(iconView, "layer", 0, 0, 0, 0) : 0;
    uint64_t iivLayer = r_responds_main(iiv, "layer")
        ? r_msg2_main(iiv, "layer", 0, 0, 0, 0) : 0;
    uint64_t overlayLayer = r_responds_main(overlay, "sublayers")
        ? overlay
        : (r_responds_main(overlay, "layer")
            ? r_msg2_main(overlay, "layer", 0, 0, 0, 0) : 0);

    printf("[THEMER] static-dynamic diag BEGIN bundle=%s iconView=0x%llx iiv=0x%llx overlay=0x%llx image=0x%llx\n",
           bundle ?: "?",
           (unsigned long long)iconView,
           (unsigned long long)iiv,
           (unsigned long long)overlay,
           (unsigned long long)image);
    themer_log_view_subtree(bundle, iconView, 0, 3);
    printf("[THEMER] static-dynamic diag layers iconView bundle=%s\n",
           bundle ?: "?");
    themer_log_layer_subtree(bundle, iconLayer, 0, 3);
    printf("[THEMER] static-dynamic diag layers imageView bundle=%s\n",
           bundle ?: "?");
    themer_log_layer_subtree(bundle, iivLayer, 0, 3);
    printf("[THEMER] static-dynamic diag layers overlay bundle=%s\n",
           bundle ?: "?");
    themer_log_layer_subtree(bundle, overlayLayer, 0, 2);
    printf("[THEMER] static-dynamic diag END bundle=%s\n", bundle ?: "?");
}

static uint64_t themer_call0_main(uint64_t obj, const char *selName)
{
    if (!r_is_objc_ptr(obj) || !selName || !r_responds_main(obj, selName)) {
        return 0;
    }
    return r_msg2_main(obj, selName, 0, 0, 0, 0);
}

static int themer_bool0_main(uint64_t obj, const char *selName)
{
    if (!r_is_objc_ptr(obj) || !selName || !r_responds_main(obj, selName)) {
        return -1;
    }
    return (r_msg2_main(obj, selName, 0, 0, 0, 0) & 0xff) ? 1 : 0;
}

static void themer_log_calendar_deep_diag(const char *phase,
                                          uint64_t iconView,
                                          uint64_t iiv,
                                          uint64_t icon,
                                          uint64_t image)
{
    if (gThemerCalendarDeepDiagBudget <= 0 ||
        !r_is_objc_ptr(iiv)) {
        return;
    }
    gThemerCalendarDeepDiagBudget--;

    uint64_t recoveredView = iconView;
    uint64_t recoveredIcon = icon;
    if (!r_is_objc_ptr(recoveredIcon)) {
        recoveredIcon = themer_application_icon_for_image_view(iiv,
                                                               &recoveredView);
    }

    uint64_t iivLayer = themer_call0_main(iiv, "layer");
    uint64_t contentsLayerView = themer_call0_main(iiv, "contentsLayerView");
    uint64_t iconLayerView = themer_call0_main(iiv, "iconLayerView");
    uint64_t displayedImage = themer_call0_main(iiv, "displayedImage");
    uint64_t contentsImage = themer_call0_main(iiv, "contentsImage");
    uint64_t squareContentsImage = themer_call0_main(iiv, "squareContentsImage");
    uint64_t requestedIdentity = themer_call0_main(iiv, "requestedImageIdentity");
    uint64_t displayedIdentity = themer_call0_main(iiv, "displayedImageIdentity");
    uint64_t desiredIdentity = themer_call0_main(iiv, "desiredImageIdentity");
    uint64_t requestedAppearance = themer_call0_main(iiv, "requestedImageAppearance");
    uint64_t displayedAppearance = themer_call0_main(iiv, "displayedImageAppearance");
    uint64_t effectiveAppearance = themer_call0_main(iiv, "effectiveIconImageAppearance");
    uint64_t iconForImage = themer_call0_main(iiv, "iconForImage");

    char iivCls[96] = {0};
    char iconCls[96] = {0};
    char contentsLayerCls[96] = {0};
    char iconLayerCls[96] = {0};
    char reqDesc[180] = {0};
    char dispDesc[180] = {0};
    char desiredDesc[180] = {0};
    themer_read_class_name(iiv, iivCls, sizeof(iivCls));
    themer_read_class_name(recoveredIcon, iconCls, sizeof(iconCls));
    themer_read_class_name(contentsLayerView, contentsLayerCls,
                           sizeof(contentsLayerCls));
    themer_read_class_name(iconLayerView, iconLayerCls, sizeof(iconLayerCls));
    themer_read_remote_description(requestedIdentity, reqDesc, sizeof(reqDesc));
    themer_read_remote_description(displayedIdentity, dispDesc, sizeof(dispDesc));
    themer_read_remote_description(desiredIdentity, desiredDesc,
                                   sizeof(desiredDesc));

    printf("[THEMER] static dynamic calendar diag phase=%s iconView=0x%llx "
           "iiv=0x%llx (%s) icon=0x%llx (%s) image=0x%llx "
           "layer=0x%llx displayed=0x%llx contents=0x%llx square=0x%llx "
           "contentsLayerView=0x%llx (%s) iconLayerView=0x%llx (%s) "
           "iconForImage=0x%llx reqID=0x%llx dispID=0x%llx desiredID=0x%llx "
           "reqApp=0x%llx dispApp=0x%llx effApp=0x%llx "
           "flags{displayLayer=%d real=%d flat=%d squareCorners=%d shouldLayer=%d delayed=%d} "
           "req=\"%s\" disp=\"%s\" desired=\"%s\"\n",
           phase ?: "?",
           (unsigned long long)recoveredView,
           (unsigned long long)iiv,
           iivCls,
           (unsigned long long)recoveredIcon,
           iconCls,
           (unsigned long long)image,
           (unsigned long long)iivLayer,
           (unsigned long long)displayedImage,
           (unsigned long long)contentsImage,
           (unsigned long long)squareContentsImage,
           (unsigned long long)contentsLayerView,
           contentsLayerCls,
           (unsigned long long)iconLayerView,
           iconLayerCls,
           (unsigned long long)iconForImage,
           (unsigned long long)requestedIdentity,
           (unsigned long long)displayedIdentity,
           (unsigned long long)desiredIdentity,
           (unsigned long long)requestedAppearance,
           (unsigned long long)displayedAppearance,
           (unsigned long long)effectiveAppearance,
           themer_bool0_main(iiv, "isDisplayingImageLayer"),
           themer_bool0_main(iiv, "isDisplayingRealImageContents"),
           themer_bool0_main(iiv, "effectivelyPrefersFlatImageLayers"),
           themer_bool0_main(iiv, "showsSquareCorners"),
           themer_bool0_main(iiv, "shouldDisplayImageLayer"),
           themer_bool0_main(iiv, "delayedImageUpdateDueToContentVisibility"),
           reqDesc,
           dispDesc,
           desiredDesc);
}

static void themer_inspect_static_dynamic_icon_view(uint64_t iconView,
                                                    const char *bundle,
                                                    uint64_t image)
{
    if (!themer_is_static_dynamic_icon_bundle(bundle) ||
        !r_is_objc_ptr(iconView)) {
        return;
    }

    uint64_t iiv = themer_icon_image_view_for_iconview(iconView);
    uint64_t icon = r_responds_main(iconView, "icon")
        ? r_msg2_main(iconView, "icon", 0, 0, 0, 0) : 0;
    uint64_t iivSuper = r_responds_main(iiv, "superview")
        ? r_msg2_main(iiv, "superview", 0, 0, 0, 0) : 0;
    uint64_t iivLayer = r_responds_main(iiv, "layer")
        ? r_msg2_main(iiv, "layer", 0, 0, 0, 0) : 0;

    char ivCls[128] = {0};
    char iivCls[128] = {0};
    char iconCls[128] = {0};
    char superCls[128] = {0};
    char layerCls[128] = {0};
    themer_read_class_name(iconView, ivCls, sizeof(ivCls));
    themer_read_class_name(iiv, iivCls, sizeof(iivCls));
    themer_read_class_name(icon, iconCls, sizeof(iconCls));
    themer_read_class_name(iivSuper, superCls, sizeof(superCls));
    themer_read_class_name(iivLayer, layerCls, sizeof(layerCls));

    ThemerRect frame = {0};
    ThemerRect bounds = {0};
    bool hasFrame = themer_read_rect(iiv, "frame", &frame);
    bool hasBounds = themer_read_rect(iiv, "bounds", &bounds);
    int hidden = themer_remote_hidden(iiv);
    double alpha = themer_remote_alpha(iiv);
    uint64_t displayedRead = (r_is_objc_ptr(iiv) &&
                              r_responds_main(iiv, "displayedImage"))
        ? r_msg2_main(iiv, "displayedImage", 0, 0, 0, 0) : 0;

    printf("[THEMER] static-dynamic inspect bundle=%s iconView=0x%llx (%s) "
           "icon=0x%llx (%s) iiv=0x%llx (%s) super=0x%llx (%s) "
           "layer=0x%llx (%s) hidden=%d alpha=%.2f displayed=0x%llx "
           "cacheImage=0x%llx frame=%s%.1f,%.1f %.1fx%.1f "
           "bounds=%s%.1f,%.1f %.1fx%.1f\n",
           bundle ?: "?",
           (unsigned long long)iconView,
           ivCls,
           (unsigned long long)icon,
           iconCls,
           (unsigned long long)iiv,
           iivCls,
           (unsigned long long)iivSuper,
           superCls,
           (unsigned long long)iivLayer,
           layerCls,
           hidden,
           alpha,
           (unsigned long long)displayedRead,
           (unsigned long long)image,
           hasFrame ? "" : "?",
           frame.x, frame.y, frame.w, frame.h,
           hasBounds ? "" : "?",
           bounds.x, bounds.y, bounds.w, bounds.h);

    bool isClock = strcmp(bundle, "com.apple.mobiletimer") == 0;
    bool *methodFlag = isClock ? &gThemerClockIIVMethodsLogged
                               : &gThemerCalendarIIVMethodsLogged;
    bool *ivarFlag = isClock ? &gThemerClockIIVIvarsLogged
                             : &gThemerCalendarIIVIvarsLogged;
    themer_log_remote_methods_once(isClock ? "clock-iiv" : "calendar-iiv",
                                   iiv,
                                   methodFlag);
    themer_log_remote_ivars_once(isClock ? "clock-iiv" : "calendar-iiv",
                                 iiv,
                                 ivarFlag);
    if (!isClock && r_is_objc_ptr(icon)) {
        themer_log_remote_methods_once("calendar-icon",
                                       icon,
                                       &gThemerCalendarIconMethodsLogged);
        themer_log_remote_ivars_once("calendar-icon",
                                     icon,
                                     &gThemerCalendarIconIvarsLogged);
        themer_log_calendar_deep_diag("inspect", iconView, iiv, icon, image);
    }
    themer_log_static_dynamic_tree(bundle, iconView, image);
}

