    bool isClock = strcmp(bundle, "com.apple.mobiletimer") == 0;
    bool *methodFlag = isClock ? &gThemerClockIIVMethodsLogged
                               : &gThemerCalendarIIVMethodsLogged;
    bool *ivarFlag = isClock ? &gThemerClockIIVIvarsLogged
                             : &gThemerCalendarIIVIvarsLogged;
    themer_log_remote_methods_once(isClock ? "clock-iiv" : "calendar-iiv",
                                   iiv,
                                   methodFlag);
    themer_log_remote_ivars_once(isClock ? "clock-iiv" : "calendar-iiv",
                                 iiv,
                                 ivarFlag);

    if (gThemerStaticDynamicTreeLogBudget > 0) {
        gThemerStaticDynamicTreeLogBudget--;
        printf("[THEMER] static-dynamic diag layers direct-iiv bundle=%s\n",
               bundle ?: "?");
        themer_log_layer_subtree(bundle, iivLayer, 0, 3);
    }
}

static int themer_inspect_static_dynamic_image_view_class(const char *className,
                                                          const char *bundle,
                                                          uint64_t image)
{
    if (!className || !className[0] ||
        !themer_is_static_dynamic_icon_bundle(bundle)) {
        return 0;
    }

    uint64_t cls = r_class(className);
    if (!r_is_objc_ptr(cls)) {
        cls = themer_lookup_class(className);
    }
    if (!r_is_objc_ptr(cls)) {
        printf("[THEMER] static dynamic inspect class-miss class=%s bundle=%s\n",
               className, bundle);
        return 0;
    }

    enum { VIEW_CAP = 32 };
    uint64_t views[VIEW_CAP];
    int n = sb_collect_views_in_windows(cls, views, VIEW_CAP);
    if (n <= 0) {
        printf("[THEMER] static dynamic inspect class-empty class=%s bundle=%s\n",
               className, bundle);
        return 0;
    }

    int inspected = 0;
    for (int i = 0; i < n; i++) {
        uint64_t v = views[i];
        if (!r_is_objc_ptr(v)) continue;
        themer_inspect_static_dynamic_image_view(v, bundle, image, className);
        inspected++;
    }

    printf("[THEMER] static dynamic inspect class=%s bundle=%s inspected=%d\n",
           className, bundle, inspected);
    return inspected;
}

static int themer_inspect_static_dynamic_image_views_for_bundle(const char *className,
                                                                const char *bundle,
                                                                uint64_t image)
{
    if (!className || !className[0] ||
        !themer_is_static_dynamic_icon_bundle(bundle)) {
        return 0;
    }

    uint64_t cls = r_class(className);
    if (!r_is_objc_ptr(cls)) {
        cls = themer_lookup_class(className);
    }
    if (!r_is_objc_ptr(cls)) {
        printf("[THEMER] static dynamic inspect bundle-scan class-miss class=%s bundle=%s\n",
               className, bundle);
        return 0;
    }

    enum { VIEW_CAP = 160 };
    uint64_t views[VIEW_CAP];
    int n = sb_collect_views_in_windows(cls, views, VIEW_CAP);
    if (n <= 0) {
        printf("[THEMER] static dynamic inspect bundle-scan class-empty class=%s bundle=%s\n",
               className, bundle);
        return 0;
    }

    int inspected = 0;
    int matched = 0;
    int noBundle = 0;
    for (int i = 0; i < n; i++) {
        uint64_t v = views[i];
        if (!r_is_objc_ptr(v)) continue;

        char actual[128] = {0};
        uint64_t ownerView = 0;
        uint64_t ownerIcon = 0;
        if (!themer_read_bundle_for_image_view(v, actual, sizeof(actual),
                                               &ownerView, &ownerIcon)) {
            noBundle++;
            continue;
        }
        if (strcmp(actual, bundle) != 0) continue;

        matched++;
        themer_inspect_static_dynamic_image_view(v, bundle, image, className);
        themer_log_calendar_deep_diag("bundle-scan-inspect", ownerView, v,
                                      ownerIcon, image);
        inspected++;
    }

    printf("[THEMER] static dynamic inspect bundle-scan class=%s bundle=%s "
           "inspected=%d matched=%d seen=%d noBundle=%d\n",
           className, bundle, inspected, matched, n, noBundle);
    return inspected;
}

static int themer_inspect_static_dynamic_known_image_views(void)
{
    uint64_t clockImage = themer_lookup_cached("com.apple.mobiletimer");
    uint64_t calendarImage = themer_lookup_cached("com.apple.mobilecal");
    if (!r_is_objc_ptr(clockImage)) {
        printf("[THEMER] static dynamic inspect no cached image bundle=com.apple.mobiletimer\n");
    }
    if (!r_is_objc_ptr(calendarImage)) {
        printf("[THEMER] static dynamic inspect no cached image bundle=com.apple.mobilecal\n");
    }

    int inspected = 0;
    inspected += themer_inspect_static_dynamic_image_view_class(
        "SBHClockApplicationIconImageView",
        "com.apple.mobiletimer",
        clockImage);
    inspected += themer_inspect_static_dynamic_image_view_class(
        "SBHCalendarApplicationIconImageView",
        "com.apple.mobilecal",
        calendarImage);
    inspected += themer_inspect_static_dynamic_image_view_class(
        "SBHCalendarIconImageView",
        "com.apple.mobilecal",
        calendarImage);
    if (gThemerStaticDynamicBundleScanEnabled) {
        inspected += themer_inspect_static_dynamic_image_views_for_bundle(
            "SBIconImageView",
            "com.apple.mobilecal",
            calendarImage);
    }

    return inspected;
}

static int themer_hide_dynamic_child_views(uint64_t view,
                                           int depth,
                                           uint64_t protectedView)
{
    if (!r_is_objc_ptr(view) || depth > 4 ||
        !r_responds_main(view, "subviews")) {
        return 0;
    }

    uint64_t subs = r_msg2_main(view, "subviews", 0, 0, 0, 0);
    uint64_t count = themer_collection_count_capped(subs, 128);
    int hidden = 0;
    for (uint64_t i = 0; i < count; i++) {
        uint64_t child = r_msg2_main(subs, "objectAtIndex:", i, 0, 0, 0);
        if (!r_is_objc_ptr(child)) continue;
        if (child == protectedView) {
            hidden += themer_hide_dynamic_child_views(child, depth + 1,
                                                      protectedView);
            continue;
        }

        char cls[128] = {0};
        themer_read_class_name(child, cls, sizeof(cls));
        if (themer_dynamic_piece_class_name(cls)) {
            if (r_responds_main(child, "setHidden:")) {
                r_msg2_main(child, "setHidden:", 1, 0, 0, 0);
            }
            if (r_responds_main(child, "setAlpha:")) {
                double zero = 0.0;
                r_msg2_main_raw(child, "setAlpha:",
                    &zero, sizeof(zero),
                    NULL, 0, NULL, 0, NULL, 0);
            }
            hidden++;
            continue;
        }

        hidden += themer_hide_dynamic_child_views(child, depth + 1,
                                                  protectedView);
    }
    return hidden;
}

static int themer_hide_dynamic_sublayers(uint64_t layer, int depth)
{
    if (!r_is_objc_ptr(layer) || depth > 4 ||
        !r_responds_main(layer, "sublayers")) {
        return 0;
    }

    uint64_t subs = r_msg2_main(layer, "sublayers", 0, 0, 0, 0);
    uint64_t count = themer_collection_count_capped(subs, 128);
    int hidden = 0;
    for (uint64_t i = 0; i < count; i++) {
        uint64_t child = r_msg2_main(subs, "objectAtIndex:", i, 0, 0, 0);
        if (!r_is_objc_ptr(child)) continue;

        char cls[128] = {0};
        themer_read_class_name(child, cls, sizeof(cls));
        if (themer_dynamic_piece_class_name(cls)) {
            if (r_responds_main(child, "setHidden:")) {
                r_msg2_main(child, "setHidden:", 1, 0, 0, 0);
            }
            hidden++;
            continue;
        }

        hidden += themer_hide_dynamic_sublayers(child, depth + 1);
    }
    return hidden;
}

static int themer_hide_all_sublayers(uint64_t layer, int depth)
{
    if (!r_is_objc_ptr(layer) || depth > 4 ||
        !r_responds_main(layer, "sublayers")) {
        return 0;
    }

    uint64_t subs = r_msg2_main(layer, "sublayers", 0, 0, 0, 0);
    uint64_t count = themer_collection_count_capped(subs, 128);
    int hidden = 0;
    for (uint64_t i = 0; i < count; i++) {
        uint64_t child = r_msg2_main(subs, "objectAtIndex:", i, 0, 0, 0);
        if (!r_is_objc_ptr(child)) continue;
        if (r_responds_main(child, "setHidden:")) {
            r_msg2_main(child, "setHidden:", 1, 0, 0, 0);
            hidden++;
        }
        hidden += themer_hide_all_sublayers(child, depth + 1);
    }
    return hidden;
}

static int themer_hide_sublayers_except(uint64_t layer,
                                        uint64_t protectedLayer,
                                        int depth)
{
    if (!r_is_objc_ptr(layer) || depth > 4 ||
        !r_responds_main(layer, "sublayers")) {
        return 0;
    }

    uint64_t subs = r_msg2_main(layer, "sublayers", 0, 0, 0, 0);
    uint64_t count = themer_collection_count_capped(subs, 128);
    int hidden = 0;
    for (uint64_t i = 0; i < count; i++) {
        uint64_t child = r_msg2_main(subs, "objectAtIndex:", i, 0, 0, 0);
        if (!r_is_objc_ptr(child)) continue;
        if (child == protectedLayer) continue;
        if (r_responds_main(child, "setHidden:")) {
            r_msg2_main(child, "setHidden:", 1, 0, 0, 0);
            hidden++;
        }
        hidden += themer_hide_sublayers_except(child, protectedLayer,
                                               depth + 1);
    }
    return hidden;
}

static bool themer_set_layer_image_contents(uint64_t layer, uint64_t image)
{
    if (!r_is_objc_ptr(layer) || !r_is_objc_ptr(image)) return false;

    uint64_t cgImage = r_responds_main(image, "CGImage")
        ? r_msg2_main(image, "CGImage", 0, 0, 0, 0) : 0;
    if (!cgImage || !r_responds_main(layer, "setContents:")) return false;

    r_msg2_main(layer, "setContents:", cgImage, 0, 0, 0);

    double scale = 3.0;
    uint64_t UIScreen = r_class("UIScreen");
    uint64_t screen = r_is_objc_ptr(UIScreen)
        ? r_msg2(UIScreen, "mainScreen", 0, 0, 0, 0) : 0;
    if (r_is_objc_ptr(screen) && r_responds_main(screen, "scale")) {
        uint64_t bits = r_msg2_main(screen, "scale", 0, 0, 0, 0);
        memcpy(&scale, &bits, sizeof(scale));
    }
    if (r_responds_main(layer, "setContentsScale:")) {
        r_msg2_main_raw(layer, "setContentsScale:",
            &scale, sizeof(scale),
            NULL, 0, NULL, 0, NULL, 0);
    }

    ThemerRect bounds = {0};
    double radius = 15.0;
    if (themer_read_rect(layer, "bounds", &bounds) && bounds.w > 1.0) {
        radius = bounds.w * 0.225;
    }
    if (r_responds_main(layer, "setCornerRadius:")) {
        r_msg2_main_raw(layer, "setCornerRadius:",
            &radius, sizeof(radius),
            NULL, 0, NULL, 0, NULL, 0);
    }
    if (r_responds_main(layer, "setMasksToBounds:")) {
        r_msg2_main(layer, "setMasksToBounds:", 1, 0, 0, 0);
    }
    if (r_responds_main(layer, "setNeedsDisplay")) {
        r_msg2_main(layer, "setNeedsDisplay", 0, 0, 0, 0);
    }
    return true;
}

static int themer_hide_clock_layer(uint64_t layer)
{
    if (!r_is_objc_ptr(layer)) return 0;
    int changed = 0;
    if (r_responds_main(layer, "removeAllAnimations")) {
        r_msg2_main(layer, "removeAllAnimations", 0, 0, 0, 0);
    }
    if (r_responds_main(layer, "setHidden:")) {
        r_msg2_main(layer, "setHidden:", 1, 0, 0, 0);
        changed++;
    }
    if (r_responds_main(layer, "setOpacity:")) {
        float zero = 0.0f;
        r_msg2_main_raw(layer, "setOpacity:",
            &zero, sizeof(zero),
            NULL, 0, NULL, 0, NULL, 0);
        changed++;
    }
    return changed > 0 ? 1 : 0;
}

static int themer_hide_clock_hand_layers(uint64_t iiv)
{
    if (!r_is_objc_ptr(iiv)) return 0;

    int hidden = 0;
    static const char *handIvars[] = {
        "_seconds",
        "_minutes",
        "_hours",
        "_hourMinuteDot",
        "_secondDot",
    };
    for (size_t i = 0; i < sizeof(handIvars) / sizeof(handIvars[0]); i++) {
        uint64_t layer = r_ivar_value(iiv, handIvars[i]);
        hidden += themer_hide_clock_layer(layer);
    }

    if (r_responds_main(iiv, "setHandsHidden:animated:")) {
        r_msg2_main(iiv, "setHandsHidden:animated:", 1, 0, 0, 0);
    } else if (r_responds_main(iiv, "setHandsHidden:")) {
        r_msg2_main(iiv, "setHandsHidden:", 1, 0, 0, 0);
    }
    return hidden;
}

static bool themer_pin_static_dynamic_child_overlay(uint64_t iiv,
                                                    uint64_t image,
                                                    const char *bundle,
                                                    const char *source)
{
    if (!r_is_objc_ptr(iiv) || !r_is_objc_ptr(image)) return false;

    uint64_t key = r_sel("cnd_themer_static_child_overlay");
    if (!key) return false;

    uint64_t overlay = r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                                    iiv, key, 0, 0, 0, 0, 0, 0);
    bool created = false;
    if (!r_is_objc_ptr(overlay)) {
        uint64_t overlayCls = r_class("UIImageView");
        uint64_t alloc = r_is_objc_ptr(overlayCls)
            ? r_msg2(overlayCls, "alloc", 0, 0, 0, 0) : 0;
        overlay = r_is_objc_ptr(alloc)
            ? r_msg2_main(alloc, "initWithImage:", image, 0, 0, 0) : 0;
        if (!r_is_objc_ptr(overlay)) return false;
        r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                     iiv, key, overlay, 1, 0, 0, 0, 0);
        r_msg2(overlay, "release", 0, 0, 0, 0);
        created = true;
    } else if (r_responds_main(overlay, "setImage:")) {
        r_msg2_main(overlay, "setImage:", image, 0, 0, 0);
    }

    uint64_t currentSuperview = r_responds_main(overlay, "superview")
        ? r_msg2_main(overlay, "superview", 0, 0, 0, 0) : 0;
    if (currentSuperview != iiv && r_responds_main(overlay, "removeFromSuperview")) {
        r_msg2_main(overlay, "removeFromSuperview", 0, 0, 0, 0);
    }
    if (currentSuperview != iiv && r_responds_main(iiv, "addSubview:")) {
        r_msg2_main(iiv, "addSubview:", overlay, 0, 0, 0);
    }

    ThemerRect bounds = {0};
    if (!themer_read_rect(iiv, "bounds", &bounds) ||
        bounds.w <= 1.0 || bounds.h <= 1.0) {
        bounds.x = 0.0;
        bounds.y = 0.0;
        bounds.w = 68.0;
        bounds.h = 68.0;
    }
    ThemerRect frame = {0.0, 0.0, bounds.w, bounds.h};
    if (r_responds_main(overlay, "setFrame:")) {
        r_msg2_main_raw(overlay, "setFrame:",
            &frame, sizeof(frame),
            NULL, 0, NULL, 0, NULL, 0);
    }
    if (r_responds_main(overlay, "setBounds:")) {
        r_msg2_main_raw(overlay, "setBounds:",
            &frame, sizeof(frame),
            NULL, 0, NULL, 0, NULL, 0);
    }
    if (r_responds_main(overlay, "setAutoresizingMask:")) {
        r_msg2_main(overlay, "setAutoresizingMask:", 18, 0, 0, 0);
    }
    if (r_responds_main(overlay, "setUserInteractionEnabled:")) {
        r_msg2_main(overlay, "setUserInteractionEnabled:", 0, 0, 0, 0);
    }
    if (r_responds_main(overlay, "setContentMode:")) {
        r_msg2_main(overlay, "setContentMode:", 0, 0, 0, 0);
    }
    if (r_responds_main(overlay, "setHidden:")) {
        r_msg2_main(overlay, "setHidden:", 0, 0, 0, 0);
    }
    if (r_responds_main(overlay, "setAlpha:")) {
        double one = 1.0;
        r_msg2_main_raw(overlay, "setAlpha:",
            &one, sizeof(one),
            NULL, 0, NULL, 0, NULL, 0);
    }
    if (r_responds_main(iiv, "bringSubviewToFront:")) {
        r_msg2_main(iiv, "bringSubviewToFront:", overlay, 0, 0, 0);
    }

    uint64_t layer = r_responds_main(overlay, "layer")
        ? r_msg2_main(overlay, "layer", 0, 0, 0, 0) : 0;
    if (r_is_objc_ptr(layer)) {
        if (r_responds_main(layer, "setHidden:")) {
            r_msg2_main(layer, "setHidden:", 0, 0, 0, 0);
        }
        double opacity = 1.0;
        if (r_responds_main(layer, "setOpacity:")) {
            float one = 1.0f;
            r_msg2_main_raw(layer, "setOpacity:",
                &one, sizeof(one),
                NULL, 0, NULL, 0, NULL, 0);
        }
        (void)opacity;
        double z = 9999.0;
        if (r_responds_main(layer, "setZPosition:")) {
            r_msg2_main_raw(layer, "setZPosition:",
                &z, sizeof(z),
                NULL, 0, NULL, 0, NULL, 0);
        }
        /* The supplied SnowBoard artwork already owns its alpha silhouette.
         * Do not add SpringBoard's rounded-rect clipping to this static
         * overlay or transparent Clock/Calendar themes acquire a plate. */
        double radius = 0.0;
        if (r_responds_main(layer, "setCornerRadius:")) {
            r_msg2_main_raw(layer, "setCornerRadius:",
                &radius, sizeof(radius),
                NULL, 0, NULL, 0, NULL, 0);
        }
        if (r_responds_main(layer, "setMasksToBounds:")) {
            r_msg2_main(layer, "setMasksToBounds:", 0, 0, 0, 0);
        }
    }

    static int logBudget = 12;
    if (logBudget > 0) {
        printf("[THEMER] static dynamic child overlay source=%s bundle=%s "
               "iiv=0x%llx overlay=0x%llx created=%d frame=%.1f,%.1f %.1fx%.1f\n",
               source ?: "?",
               bundle ?: "?",
               (unsigned long long)iiv,
               (unsigned long long)overlay,
               created,
               frame.x, frame.y, frame.w, frame.h);
        logBudget--;
    }

    return true;
}

static bool themer_apply_static_clock_image_view(uint64_t iiv,
                                                 uint64_t image,
                                                 uint64_t clockIcon,
                                                 const char *source)
{
    if (!r_is_objc_ptr(iiv) || !r_is_objc_ptr(image)) return false;
    bool childOverlayCleared =
        themer_clear_static_dynamic_child_overlay_on_object(iiv);

    uint64_t oldBackgroundIcon = r_responds_main(iiv, "clockBackgroundIcon")
        ? r_msg2_main(iiv, "clockBackgroundIcon", 0, 0, 0, 0) : 0;
    if (!r_is_objc_ptr(clockIcon)) {
        clockIcon = r_ivar_value(iiv, "_icon");
    }
    if (!themer_icon_is_application_icon(clockIcon)) {
        clockIcon = themer_application_icon_for_image_view(iiv, NULL);
    }
    if (!themer_icon_is_application_icon(clockIcon)) {
        clockIcon = themer_lookup_model_icon_for_bundle("com.apple.mobiletimer");
    }

    bool backgroundIconSet = false;
    bool updatedUnanimated = false;
    if (r_is_objc_ptr(clockIcon) &&
        r_responds_main(iiv, "setClockBackgroundIcon:")) {
        r_msg2_main(iiv, "setClockBackgroundIcon:", clockIcon, 0, 0, 0);
        backgroundIconSet = true;
        if (r_responds_main(iiv, "updateUnanimated")) {
            r_msg2_main(iiv, "updateUnanimated", 0, 0, 0, 0);
            updatedUnanimated = true;
        }
    }

    int handLayers = themer_hide_clock_hand_layers(iiv);
    uint64_t iivLayer = r_responds_main(iiv, "layer")
        ? r_msg2_main(iiv, "layer", 0, 0, 0, 0) : 0;

    int hiddenSublayers = 0;
    if (r_is_objc_ptr(iivLayer)) {
        hiddenSublayers = themer_hide_all_sublayers(iivLayer, 0);
    }

    bool layerImage = themer_set_layer_image_contents(iivLayer, image);
    bool displayed = false;
    if (r_responds_main(iiv, "setDisplayedImage:")) {
        r_msg2_main(iiv, "setDisplayedImage:", image, 0, 0, 0);
        displayed = true;
    }
    bool overlay = false;
    if (kThemerStaticClockChildOverlayEnabled) {
        overlay = themer_pin_static_dynamic_child_overlay(iiv, image,
                                                          "com.apple.mobiletimer",
                                                          source);
    }

    static int logBudget = 12;
    if (logBudget > 0) {
        char cls[128] = {0};
        char iconCls[128] = {0};
        char oldBgCls[128] = {0};
        themer_read_class_name(iiv, cls, sizeof(cls));
        themer_read_class_name(clockIcon, iconCls, sizeof(iconCls));
        themer_read_class_name(oldBackgroundIcon, oldBgCls, sizeof(oldBgCls));
        printf("[THEMER] static dynamic clock apply source=%s iiv=0x%llx (%s) "
               "image=0x%llx bgSet=%d updated=%d bgIcon=0x%llx (%s) "
               "oldBg=0x%llx (%s) handLayers=%d hiddenSublayers=%d "
               "layerImage=%d displayed=%d overlay=%d clearedOverlay=%d\n",
               source ?: "?",
               (unsigned long long)iiv,
               cls,
               (unsigned long long)image,
               backgroundIconSet,
               updatedUnanimated,
               (unsigned long long)clockIcon,
               iconCls,
               (unsigned long long)oldBackgroundIcon,
               oldBgCls,
               handLayers,
               hiddenSublayers,
               layerImage,
               displayed,
               overlay,
               childOverlayCleared);
        logBudget--;
    }

    return overlay || layerImage || displayed ||
           handLayers > 0 || hiddenSublayers > 0;
}

static bool themer_apply_static_calendar_image_view(uint64_t iconView,
                                                    uint64_t iiv,
                                                    uint64_t image,
                                                    uint64_t calendarIcon,
                                                    const char *source)
{
    if (!r_is_objc_ptr(iiv) || !r_is_objc_ptr(image)) return false;

    if (!r_is_objc_ptr(calendarIcon)) {
        calendarIcon = r_is_objc_ptr(iconView)
            ? themer_application_icon_for_iconview(iconView)
            : r_ivar_value(iiv, "_icon");
    }
    if (!themer_icon_is_application_icon(calendarIcon)) {
        calendarIcon = themer_application_icon_for_image_view(iiv, NULL);
    }
    if (!themer_icon_is_application_icon(calendarIcon)) {
        calendarIcon = themer_lookup_model_icon_for_bundle("com.apple.mobilecal");
    }

    themer_log_calendar_deep_diag("pre-apply", iconView, iiv,
                                  calendarIcon, image);

    int rung = 0;
    if (r_is_objc_ptr(iconView)) {
        rung = themer_push_image(iconView, image);
    }

    bool updatedContents = false;
    if (r_is_objc_ptr(iconView) &&
        r_responds_main(iiv, "updateImageContentsWithImage:imageAppearance:animated:")) {
        uint64_t appearance = r_responds_main(iiv, "effectiveIconImageAppearance")
            ? r_msg2_main(iiv, "effectiveIconImageAppearance", 0, 0, 0, 0) : 0;
        if (r_is_objc_ptr(appearance)) {
            r_msg2_main(iiv, "updateImageContentsWithImage:imageAppearance:animated:",
                        image, appearance, 0, 0);
            updatedContents = true;
        }
    }

    uint64_t iivLayer = r_responds_main(iiv, "layer")
        ? r_msg2_main(iiv, "layer", 0, 0, 0, 0) : 0;

    int hiddenSublayers = 0;
    if (r_is_objc_ptr(iivLayer)) {
        hiddenSublayers = themer_hide_all_sublayers(iivLayer, 0);
    }

    bool layerImage = themer_set_layer_image_contents(iivLayer, image);
    bool displayed = false;
    if (r_responds_main(iiv, "setDisplayedImage:")) {
        r_msg2_main(iiv, "setDisplayedImage:", image, 0, 0, 0);
        displayed = true;
    }

    themer_log_calendar_deep_diag("post-apply", iconView, iiv,
                                  calendarIcon, image);

    static int logBudget = 12;
    if (logBudget > 0) {
        char iivCls[128] = {0};
        char iconCls[128] = {0};
        themer_read_class_name(iiv, iivCls, sizeof(iivCls));
        themer_read_class_name(calendarIcon, iconCls, sizeof(iconCls));
        printf("[THEMER] static dynamic calendar apply source=%s iconView=0x%llx "
               "iiv=0x%llx (%s) image=0x%llx icon=0x%llx (%s) "
               "rung=%d hiddenSublayers=%d layerImage=%d displayed=%d updated=%d\n",
               source ?: "?",
               (unsigned long long)iconView,
               (unsigned long long)iiv,
               iivCls,
               (unsigned long long)image,
               (unsigned long long)calendarIcon,
               iconCls,
               rung,
               hiddenSublayers,
               layerImage,
               displayed,
               updatedContents);
        logBudget--;
    }

    return rung > 0 || layerImage || displayed ||
           updatedContents || hiddenSublayers > 0;
}

static bool themer_apply_static_dynamic_icon_state(uint64_t iconView,
                                                   uint64_t image,
                                                   const char *bundle)
{
    if (!themer_is_static_dynamic_icon_bundle(bundle) ||
        !r_is_objc_ptr(iconView) ||
        !r_is_objc_ptr(image) ||
        !r_is_objc_ptr(themer_application_icon_for_iconview(iconView))) {
        return false;
    }

    uint64_t iiv = themer_icon_image_view_for_iconview(iconView);
    if (!r_is_objc_ptr(iiv)) return false;
    uint64_t appIcon = themer_application_icon_for_iconview(iconView);

    themer_log_static_dynamic_tree(bundle, iconView, image);

    if (strcmp(bundle, "com.apple.mobiletimer") == 0) {
        int rung = themer_push_image(iconView, image);
        bool clockApplied = themer_apply_static_clock_image_view(iiv, image, appIcon,
                                                                 "iconView");
        static int loggedClock = 0;
        if (loggedClock < 8) {
            char iivCls[128] = {0};
            themer_read_class_name(iiv, iivCls, sizeof(iivCls));
            printf("[THEMER] static dynamic clock iconView bundle=%s "
                   "iconView=0x%llx iiv=0x%llx (%s) rung=%d applied=%d\n",
                   bundle,
                   (unsigned long long)iconView,
                   (unsigned long long)iiv,
                   iivCls,
                   rung,
                   clockApplied);
            loggedClock++;
        }
        return clockApplied || rung > 0;
    }

    if (strcmp(bundle, "com.apple.mobilecal") == 0) {
        bool calendarApplied = themer_apply_static_calendar_image_view(iconView,
                                                                       iiv,
                                                                       image,
                                                                       appIcon,
                                                                       "iconView");
        static int loggedCalendar = 0;
        if (loggedCalendar < 8) {
            char iivCls[128] = {0};
            themer_read_class_name(iiv, iivCls, sizeof(iivCls));
            printf("[THEMER] static dynamic calendar iconView bundle=%s "
                   "iconView=0x%llx iiv=0x%llx (%s) applied=%d\n",
                   bundle,
                   (unsigned long long)iconView,
                   (unsigned long long)iiv,
                   iivCls,
                   calendarApplied);
            loggedCalendar++;
        }
        return calendarApplied;
    }

    static int logged = 0;
    if (logged < 6) {
        char iivCls[128] = {0};
        themer_read_class_name(iiv, iivCls, sizeof(iivCls));
        printf("[THEMER] static dynamic mutation unavailable bundle=%s iconView=0x%llx "
               "iiv=0x%llx (%s) image=0x%llx\n",
               bundle ?: "?",
               (unsigned long long)iconView,
               (unsigned long long)iiv,
               iivCls,
               (unsigned long long)image);
        logged++;
    }

    return false;
}

static int themer_apply_static_dynamic_image_view_class(const char *className,
                                                        const char *bundle,
                                                        uint64_t image)
{
    if (!className || !className[0] ||
        !themer_is_static_dynamic_icon_bundle(bundle) ||
        !r_is_objc_ptr(image)) {
        return 0;
    }

    uint64_t cls = r_class(className);
    if (!r_is_objc_ptr(cls)) {
        cls = themer_lookup_class(className);
    }
    if (!r_is_objc_ptr(cls)) {
        printf("[THEMER] static dynamic apply class-miss class=%s bundle=%s\n",
               className, bundle);
        return 0;
    }

    enum { VIEW_CAP = 32 };
    uint64_t views[VIEW_CAP];
    int n = sb_collect_views_in_windows(cls, views, VIEW_CAP);
    if (n <= 0) {
        printf("[THEMER] static dynamic apply class-empty class=%s bundle=%s\n",
               className, bundle);
        return 0;
    }

    int applied = 0;
    for (int i = 0; i < n; i++) {
        uint64_t v = views[i];
        if (!r_is_objc_ptr(v)) continue;
        uint64_t ownerView = 0;
        uint64_t ownerIcon = themer_application_icon_for_image_view(v, &ownerView);
        if (strcmp(bundle, "com.apple.mobiletimer") == 0 &&
            themer_apply_static_clock_image_view(v, image, ownerIcon, className)) {
            applied++;
        } else if (strcmp(bundle, "com.apple.mobilecal") == 0 &&
                   themer_apply_static_calendar_image_view(ownerView, v, image,
                                                           ownerIcon, className)) {
            applied++;
        }
    }

    printf("[THEMER] static dynamic apply class=%s bundle=%s applied=%d seen=%d\n",
           className, bundle, applied, n);
    return applied;
}

static int themer_apply_static_dynamic_image_views_for_bundle(const char *className,
                                                              const char *bundle,
                                                              uint64_t image)
{
    if (!className || !className[0] ||
        !themer_is_static_dynamic_icon_bundle(bundle) ||
        !r_is_objc_ptr(image)) {
        return 0;
    }

    uint64_t cls = r_class(className);
    if (!r_is_objc_ptr(cls)) {
        cls = themer_lookup_class(className);
    }
    if (!r_is_objc_ptr(cls)) {
        printf("[THEMER] static dynamic apply bundle-scan class-miss class=%s bundle=%s\n",
               className, bundle);
        return 0;
    }

    enum { VIEW_CAP = 160 };
    uint64_t views[VIEW_CAP];
    int n = sb_collect_views_in_windows(cls, views, VIEW_CAP);
    if (n <= 0) {
        printf("[THEMER] static dynamic apply bundle-scan class-empty class=%s bundle=%s\n",
               className, bundle);
        return 0;
    }

    int applied = 0;
    int matched = 0;
    int noBundle = 0;
    for (int i = 0; i < n; i++) {
        uint64_t v = views[i];
        if (!r_is_objc_ptr(v)) continue;

        char actual[128] = {0};
        uint64_t ownerView = 0;
        uint64_t ownerIcon = 0;
        if (!themer_read_bundle_for_image_view(v, actual, sizeof(actual),
                                               &ownerView, &ownerIcon)) {
            noBundle++;
            continue;
        }
        if (strcmp(actual, bundle) != 0) continue;
        matched++;

        if (strcmp(bundle, "com.apple.mobiletimer") == 0 &&
            themer_apply_static_clock_image_view(v, image, ownerIcon,
                                                 className)) {
            applied++;
        } else if (strcmp(bundle, "com.apple.mobilecal") == 0 &&
                   themer_apply_static_calendar_image_view(ownerView, v, image,
                                                           ownerIcon,
                                                           className)) {
            applied++;
        }
    }

    printf("[THEMER] static dynamic apply bundle-scan class=%s bundle=%s "
           "applied=%d matched=%d seen=%d noBundle=%d\n",
           className, bundle, applied, matched, n, noBundle);
    return applied;
}

static int themer_apply_static_dynamic_known_image_views(void)
{
    int applied = 0;
    uint64_t clockImage = themer_lookup_cached("com.apple.mobiletimer");
    if (!r_is_objc_ptr(clockImage)) {
        printf("[THEMER] static dynamic apply no cached image bundle=com.apple.mobiletimer\n");
    } else {
        applied += themer_apply_static_dynamic_image_view_class(
            "SBHClockApplicationIconImageView",
            "com.apple.mobiletimer",
            clockImage);
    }

    uint64_t calendarImage = themer_lookup_cached("com.apple.mobilecal");
    if (!r_is_objc_ptr(calendarImage)) {
        printf("[THEMER] static dynamic apply no cached image bundle=com.apple.mobilecal\n");
    } else {
        applied += themer_apply_static_dynamic_image_view_class(
            "SBHCalendarApplicationIconImageView",
            "com.apple.mobilecal",
            calendarImage);
        applied += themer_apply_static_dynamic_image_view_class(
            "SBHCalendarIconImageView",
            "com.apple.mobilecal",
            calendarImage);
        if (gThemerStaticDynamicBundleScanEnabled) {
            applied += themer_apply_static_dynamic_image_views_for_bundle(
                "SBIconImageView",
                "com.apple.mobilecal",
                calendarImage);
        }
    }

    return applied;
}

static int themer_static_dynamic_overlay_matching_icon_views(
    const char *bundle, uint64_t image, bool install, int *seenOut,
    int *clearedOut)
{
    if (!bundle || !bundle[0]) return 0;
    uint64_t iconViewClass = r_class("SBIconView");
    if (!r_is_objc_ptr(iconViewClass)) return 0;

    enum { VIEW_CAP = 512 };
    uint64_t views[VIEW_CAP] = {0};
    int count = sb_collect_views_in_windows(
        iconViewClass, views, VIEW_CAP);
    int applied = 0;
    int seen = 0;
    int cleared = 0;
    for (int index = 0;
         index < count && remote_call_current_success(); index++) {
        uint64_t iconView = views[index];
        char actual[128] = {0};
        if (!themer_read_bundle_for_iconview(
                iconView, actual, sizeof(actual)) ||
            strcmp(actual, bundle) != 0) {
            continue;
        }
        seen++;
        uint64_t imageView =
            themer_icon_image_view_for_iconview(iconView);
        if (!r_is_objc_ptr(imageView)) continue;
        if (!install) {
            if (themer_clear_static_dynamic_child_overlay_on_object(
                    imageView)) {
                cleared++;
            }
            continue;
        }
        if (themer_pin_static_dynamic_child_overlay(
                imageView, image, bundle, "static-theme-icon-view")) {
            applied++;
        }
    }
    if (seenOut) *seenOut += seen;
    if (clearedOut) *clearedOut += cleared;
    return applied;
}

static int themer_static_dynamic_overlay_specialized_views(
    const char *className, const char *bundle, uint64_t image,
    bool install, int *seenOut, int *clearedOut)
{
    if (!className || !className[0] || !bundle || !bundle[0]) return 0;
    uint64_t viewClass = r_class(className);
    if (!r_is_objc_ptr(viewClass)) return 0;

    enum { VIEW_CAP = 64 };
    uint64_t views[VIEW_CAP] = {0};
    int count = sb_collect_views_in_windows(viewClass, views, VIEW_CAP);
    int applied = 0;
    int cleared = 0;
    for (int index = 0;
         index < count && remote_call_current_success(); index++) {
        uint64_t imageView = views[index];
        if (!r_is_objc_ptr(imageView)) continue;
        if (!install) {
            if (themer_clear_static_dynamic_child_overlay_on_object(
                    imageView)) {
                cleared++;
            }
            continue;
        }
        if (themer_pin_static_dynamic_child_overlay(
                imageView, image, bundle, className)) {
            applied++;
        }
    }
    if (seenOut) *seenOut += count;
    if (clearedOut) *clearedOut += cleared;
    return applied;
}

