_Static_assert(sizeof(ThemerClockIconImageInfo) == 32,
               "SBIconImageInfo ABI changed");
_Static_assert(sizeof(ThemerClockApplicationIconImageMetrics) == 232,
               "SBHClockApplicationIconImageMetrics ABI changed");

static uint64_t themer_strip_remote_imp(uint64_t value)
{
    return value & 0x00007fffffffffffULL;
}

static bool themer_remote_method_has_types(uint64_t method,
                                           const char *expectedTypes)
{
    uint64_t types = method && expectedTypes
        ? r_dlsym_call(R_TIMEOUT, "method_getTypeEncoding", method,
                       0, 0, 0, 0, 0, 0, 0)
        : 0;
    char actual[128] = {0};
    return types && r_read_cstring(types, actual, sizeof(actual)) &&
        strcmp(actual, expectedTypes) == 0 &&
        remote_call_current_success();
}

static bool themer_set_remote_associated_object(uint64_t object,
                                                const char *keyName,
                                                uint64_t value)
{
    if (!r_is_objc_ptr(object) || (value && !r_is_objc_ptr(value))) {
        return false;
    }
    uint64_t key = keyName ? r_sel(keyName) : 0;
    if (!key) return false;
    (void)r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                       object, key, value, 1, 0, 0, 0, 0);
    /* Never immediately call objc_getAssociatedObject through the physical
     * RemoteCall ABI. A nil result returns normally, but a non-null object can
     * lose synthetic completion on arm64e. Every caller below proves the
     * association through its natural hooked Objective-C selector after the
     * object's class transition, or retains recovery state in a process-owned
     * collection whose getter is itself an Objective-C method. */
    return remote_call_current_success();
}

static const char *const kThemerDynamicRedirectRegistryKey =
    "cnd_sbr_dynamic_redirect_backups_v1";

/* These recovery collections are created and consumed only by this one
 * serialized synthetic thread. Sending ordinary NSMutableArray/Dictionary
 * bookkeeping through SpringBoard's main thread made the physical repair
 * needlessly slow, so keep pure collection work on the existing session. */
static uint64_t themer_session_collection_count(uint64_t collection)
{
    return r_is_objc_ptr(collection) &&
           r_responds(collection, "count")
        ? r_msg2(collection, "count", 0, 0, 0, 0)
        : 0;
}

static uint64_t themer_session_dictionary_object(uint64_t dictionary,
                                                  const char *keyName)
{
    if (!r_is_objc_ptr(dictionary) || !keyName || !keyName[0] ||
        !r_responds(dictionary, "objectForKey:")) return 0;
    uint64_t key = r_nsstr_retained(keyName);
    if (!r_is_objc_ptr(key)) return 0;
    uint64_t object = r_msg2(dictionary, "objectForKey:",
                             key, 0, 0, 0);
    r_msg2(key, "release", 0, 0, 0, 0);
    return r_is_objc_ptr(object) ? object : 0;
}

static bool themer_session_dictionary_set_object(uint64_t dictionary,
                                                  const char *keyName,
                                                  uint64_t object)
{
    if (!r_is_objc_ptr(dictionary) || !keyName || !keyName[0] ||
        !r_is_objc_ptr(object) ||
        !r_responds(dictionary, "setObject:forKey:")) return false;
    uint64_t key = r_nsstr_retained(keyName);
    if (!r_is_objc_ptr(key)) return false;
    r_msg2(dictionary, "setObject:forKey:", object, key, 0, 0);
    uint64_t observed = remote_call_current_success()
        ? r_msg2(dictionary, "objectForKey:", key, 0, 0, 0)
        : 0;
    if (remote_call_current_success()) {
        r_msg2(key, "release", 0, 0, 0, 0);
    }
    return observed == object && remote_call_current_success();
}

static uint64_t themer_dynamic_redirect_registry(bool create)
{
    uint64_t registry = themer_spotlight_associated_process_object(
        kThemerDynamicRedirectRegistryKey);
    if (r_is_objc_ptr(registry) || !create) return registry;

    uint64_t dictionaryClass = themer_lookup_class("NSMutableDictionary");
    uint64_t allocation = r_is_objc_ptr(dictionaryClass)
        ? r_msg2(dictionaryClass, "alloc", 0, 0, 0, 0) : 0;
    registry = r_is_objc_ptr(allocation)
        ? r_msg2(allocation, "initWithCapacity:", 4, 0, 0, 0)
        : 0;
    bool committed = r_is_objc_ptr(registry) &&
        themer_spotlight_commit_process_object(
            kThemerDynamicRedirectRegistryKey, registry);
    if (r_is_objc_ptr(registry) && remote_call_current_success()) {
        r_msg2(registry, "release", 0, 0, 0, 0);
    }
    return committed
        ? themer_spotlight_associated_process_object(
              kThemerDynamicRedirectRegistryKey)
        : 0;
}

static bool themer_dynamic_redirect_remove_backup(uint64_t registry,
                                                   const char *keyName)
{
    if (!r_is_objc_ptr(registry) || !keyName || !keyName[0]) return false;
    uint64_t key = r_nsstr_retained(keyName);
    if (!r_is_objc_ptr(key)) return false;
    r_msg2(registry, "removeObjectForKey:", key, 0, 0, 0);
    uint64_t observed = remote_call_current_success()
        ? r_msg2(registry, "objectForKey:", key, 0, 0, 0)
        : 0;
    if (remote_call_current_success()) {
        r_msg2(key, "release", 0, 0, 0, 0);
    }
    return !r_is_objc_ptr(observed) && remote_call_current_success();
}

static bool themer_configure_apple_signed_redirect(
    uint64_t backupRegistry,
    const char *label,
    const char *targetClassName,
    const char *targetSelectorName,
    const char *sourceClassName,
    const char *sourceSelectorName,
    const char *expectedTypes,
    const char *backupKeyName,
    bool install,
    bool *changedOut)
{
    if (changedOut) *changedOut = false;
    uint64_t targetClass = r_class(targetClassName);
    uint64_t sourceClass = r_class(sourceClassName);
    uint64_t targetSelector = r_sel(targetSelectorName);
    uint64_t sourceSelector = r_sel(sourceSelectorName);
    uint64_t targetMethod = targetClass && targetSelector
        ? r_dlsym_call(R_TIMEOUT, "class_getInstanceMethod",
                       targetClass, targetSelector, 0, 0, 0, 0, 0, 0)
        : 0;
    uint64_t sourceMethod = sourceClass && sourceSelector
        ? r_dlsym_call(R_TIMEOUT, "class_getInstanceMethod",
                       sourceClass, sourceSelector, 0, 0, 0, 0, 0, 0)
        : 0;
    if (!targetMethod || !sourceMethod ||
        !themer_remote_method_has_types(targetMethod, expectedTypes) ||
        !themer_remote_method_has_types(sourceMethod, expectedTypes)) {
        printf("[SBR_DYNAMIC_ICONS] redirect ABI mismatch label=%s install=%d\n",
               label ?: "?", install);
        return false;
    }

    uint64_t current = r_dlsym_call(
        R_TIMEOUT, "method_getImplementation", targetMethod,
        0, 0, 0, 0, 0, 0, 0);
    uint64_t source = r_dlsym_call(
        R_TIMEOUT, "method_getImplementation", sourceMethod,
        0, 0, 0, 0, 0, 0, 0);
    uint64_t backupNumber = r_is_objc_ptr(backupRegistry)
        ? themer_session_dictionary_object(
              backupRegistry, backupKeyName)
        : 0;

    if (install) {
        if (!r_is_objc_ptr(backupNumber) &&
            themer_strip_remote_imp(current) !=
                themer_strip_remote_imp(source)) {
            uint64_t numberClass = r_class("NSNumber");
            backupNumber = r_is_objc_ptr(numberClass)
                ? r_msg2(numberClass, "numberWithUnsignedLongLong:",
                         current, 0, 0, 0)
                : 0;
            if (!r_is_objc_ptr(backupNumber) ||
                !r_is_objc_ptr(backupRegistry) ||
                !themer_session_dictionary_set_object(
                    backupRegistry, backupKeyName, backupNumber)) {
                printf("[SBR_DYNAMIC_ICONS] redirect backup failed label=%s\n",
                       label ?: "?");
                return false;
            }
        }
        if (themer_strip_remote_imp(current) !=
            themer_strip_remote_imp(source)) {
            uint64_t replaced = r_dlsym_call(
                R_TIMEOUT, "method_setImplementation",
                targetMethod, source, 0, 0, 0, 0, 0, 0);
            if (!replaced || !remote_call_current_success()) return false;
            if (changedOut) *changedOut = true;
        }
        uint64_t observed = r_dlsym_call(
            R_TIMEOUT, "method_getImplementation", targetMethod,
            0, 0, 0, 0, 0, 0, 0);
        return themer_strip_remote_imp(observed) ==
            themer_strip_remote_imp(source) &&
            remote_call_current_success();
    }

    if (!r_is_objc_ptr(backupNumber)) return true;
    uint64_t original = r_msg2(
        backupNumber, "unsignedLongLongValue", 0, 0, 0, 0);
    if (!original) return false;
    if (themer_strip_remote_imp(current) !=
        themer_strip_remote_imp(original)) {
        uint64_t replaced = r_dlsym_call(
            R_TIMEOUT, "method_setImplementation",
            targetMethod, original, 0, 0, 0, 0, 0, 0);
        if (!replaced || !remote_call_current_success()) return false;
        if (changedOut) *changedOut = true;
    }
    uint64_t observed = r_dlsym_call(
        R_TIMEOUT, "method_getImplementation", targetMethod,
        0, 0, 0, 0, 0, 0, 0);
    bool restored = themer_strip_remote_imp(observed) ==
        themer_strip_remote_imp(original) && remote_call_current_success();
    if (restored) {
        restored = themer_dynamic_redirect_remove_backup(
            backupRegistry, backupKeyName);
    }
    return restored;
}

static uint64_t themer_build_remote_uiimage_with_scale(
    NSData *bytes, const char *label, double scale)
{
    uint64_t decoded = themer_build_remote_uiimage_from_data(bytes, label);
    if (!r_is_objc_ptr(decoded)) return 0;
    uint64_t cgImage = r_msg2(decoded, "CGImage", 0, 0, 0, 0);
    uint64_t imageClass = r_class("UIImage");
    int64_t orientation = 0;
    uint64_t scaled = r_is_objc_ptr(imageClass) && cgImage
        ? r_msg2_raw(imageClass, "imageWithCGImage:scale:orientation:",
                     &cgImage, sizeof(cgImage),
                     &scale, sizeof(scale),
                     &orientation, sizeof(orientation),
                     NULL, 0)
        : 0;
    if (r_is_objc_ptr(scaled)) {
        scaled = r_msg2(scaled, "retain", 0, 0, 0, 0);
    }
    r_msg2(decoded, "release", 0, 0, 0, 0);
    return r_is_objc_ptr(scaled) && remote_call_current_success()
        ? scaled : 0;
}

static uint64_t themer_clock_image_set_for_appearance(
    uint64_t clockViewClass,
    uint64_t metricsAddress,
    uint64_t appearance)
{
    return r_msg2_raw(
        clockViewClass, "imageSetForMetrics:imageAppearance:",
        &metricsAddress, sizeof(metricsAddress),
        &appearance, sizeof(appearance),
        NULL, 0, NULL, 0);
}

/*
 * Keep Clock hand recovery state on NSProcessInfo rather than attaching it
 * to SBHClockIconImageSet itself.  The latter is a hot private SpringBoard
 * object: on physical devices objc_setAssociatedObject() completes, but the
 * immediate objc_getAssociatedObject() verification can block indefinitely
 * while the live Clock renderer is using the set.  A process-owned registry
 * gives the five stock images a durable +1 owner for the lifetime of this
 * SpringBoard process and lets Apply/Restore verify through the image set's
 * ordinary getters instead of re-entering the associated-object table for
 * that private instance.
 */
static const char *const kThemerClockImageSetRegistryKey =
    "cnd_sbr_clock_image_set_states_v1";

static uint64_t themer_clock_image_set_registry(bool create)
{
    uint64_t registry = themer_spotlight_associated_process_object(
        kThemerClockImageSetRegistryKey);
    if (r_is_objc_ptr(registry) || !create) return registry;

    uint64_t arrayClass = themer_lookup_class("NSMutableArray");
    uint64_t allocation = r_is_objc_ptr(arrayClass)
        ? r_msg2(arrayClass, "alloc", 0, 0, 0, 0) : 0;
    registry = r_is_objc_ptr(allocation)
        ? r_msg2(allocation, "initWithCapacity:", 8, 0, 0, 0)
        : 0;
    bool committed = r_is_objc_ptr(registry) &&
        themer_spotlight_commit_process_object(
            kThemerClockImageSetRegistryKey, registry);
    if (r_is_objc_ptr(registry) && remote_call_current_success()) {
        r_msg2(registry, "release", 0, 0, 0, 0);
    }
    return committed
        ? themer_spotlight_associated_process_object(
              kThemerClockImageSetRegistryKey)
        : 0;
}

static uint64_t themer_clock_image_set_state(uint64_t registry,
    uint64_t imageSet)
{
    uint64_t count = r_is_objc_ptr(registry)
        ? themer_session_collection_count(registry) : 0;
    if (count > 8) return 0;
    for (uint64_t index = 0; index < count; index++) {
        uint64_t state = r_msg2(
            registry, "objectAtIndex:", index, 0, 0, 0);
        if (themer_session_dictionary_object(
                state, "imageSet") == imageSet) {
            return state;
        }
    }
    return 0;
}

static bool themer_clock_backup_or_apply_image_set(
    uint64_t registry,
    uint64_t imageSet,
    const uint64_t themedImages[5],
    bool install,
    bool *changedOut)
{
    if (changedOut) *changedOut = false;
    if (!r_is_objc_ptr(imageSet)) return false;
    static const char *const getters[5] = {
        "hours", "minutes", "seconds", "hourMinuteDot", "secondDot",
    };
    static const char *const setters[5] = {
        "setHours:", "setMinutes:", "setSeconds:",
        "setHourMinuteDot:", "setSecondDot:",
    };
    if (!r_is_objc_ptr(registry)) {
        /* No registry during Restore means this process has no Clock hand
         * mutation to unwind. Apply, however, must never mutate without a
         * durable process-owned backup. */
        return !install && remote_call_current_success();
    }
    uint64_t state = themer_clock_image_set_state(registry, imageSet);
    uint64_t backup = r_is_objc_ptr(state)
        ? themer_session_dictionary_object(state, "originalImages")
        : 0;

    if (install) {
        if (!r_is_objc_ptr(backup)) {
            uint64_t arrayClass = r_class("NSMutableArray");
            backup = r_is_objc_ptr(arrayClass)
                ? r_msg2(arrayClass, "arrayWithCapacity:", 5, 0, 0, 0)
                : 0;
            if (!r_is_objc_ptr(backup)) return false;
            for (NSUInteger index = 0; index < 5; index++) {
                uint64_t original = r_msg2(
                    imageSet, getters[index], 0, 0, 0, 0);
                if (!r_is_objc_ptr(original)) return false;
                r_msg2(backup, "addObject:", original, 0, 0, 0);
            }
            uint64_t dictionaryClass =
                themer_lookup_class("NSMutableDictionary");
            uint64_t allocation = r_is_objc_ptr(dictionaryClass)
                ? r_msg2(dictionaryClass, "alloc", 0, 0, 0, 0) : 0;
            state = r_is_objc_ptr(allocation)
                ? r_msg2(allocation, "initWithCapacity:", 2, 0, 0, 0)
                : 0;
            bool stateReady = r_is_objc_ptr(state) &&
                themer_session_dictionary_set_object(
                    state, "imageSet", imageSet) &&
                themer_session_dictionary_set_object(
                    state, "originalImages", backup);
            uint64_t beforeCount = stateReady
                ? themer_session_collection_count(registry) : 0;
            if (stateReady) {
                r_msg2(registry, "addObject:", state, 0, 0, 0);
            }
            uint64_t afterCount = stateReady
                ? themer_session_collection_count(registry) : beforeCount;
            bool committed = stateReady &&
                afterCount == beforeCount + 1 &&
                themer_clock_image_set_state(registry, imageSet) == state &&
                remote_call_current_success();
            if (r_is_objc_ptr(state) && remote_call_current_success()) {
                r_msg2(state, "release", 0, 0, 0, 0);
            }
            if (!committed) {
                return false;
            }
        }
        for (NSUInteger index = 0; index < 5; index++) {
            if (!r_is_objc_ptr(themedImages[index])) return false;
            r_msg2(imageSet, setters[index], themedImages[index], 0, 0, 0);
        }
        bool verified = remote_call_current_success();
        for (NSUInteger index = 0; verified && index < 5; index++) {
            verified = r_msg2(
                imageSet, getters[index], 0, 0, 0, 0) ==
                    themedImages[index] &&
                remote_call_current_success();
        }
        if (changedOut) *changedOut = verified;
        return verified;
    }

    if (!r_is_objc_ptr(backup)) return true;
    uint64_t count = r_msg2(backup, "count", 0, 0, 0, 0);
    if (count != 5) return false;
    uint64_t originals[5] = {0};
    for (NSUInteger index = 0; index < 5; index++) {
        originals[index] = r_msg2(
            backup, "objectAtIndex:", index, 0, 0, 0);
        if (!r_is_objc_ptr(originals[index])) return false;
        r_msg2(imageSet, setters[index], originals[index], 0, 0, 0);
    }
    bool verified = remote_call_current_success();
    for (NSUInteger index = 0; verified && index < 5; index++) {
        verified = r_msg2(
            imageSet, getters[index], 0, 0, 0, 0) ==
                originals[index] &&
            remote_call_current_success();
    }
    uint64_t beforeCount = verified
        ? themer_session_collection_count(registry) : 0;
    if (verified) {
        r_msg2(registry, "removeObjectIdenticalTo:", state, 0, 0, 0);
    }
    uint64_t afterCount = verified
        ? themer_session_collection_count(registry) : beforeCount;
    bool cleared = verified && beforeCount > 0 &&
        afterCount + 1 == beforeCount &&
        !r_is_objc_ptr(
            themer_clock_image_set_state(registry, imageSet)) &&
        remote_call_current_success();
    if (changedOut) *changedOut = cleared;
    return cleared;
}

static const char *const kThemerClockBaseIdentifier =
    "com.apple.application-icon.clock.base";
static const char *const kThemerClockBaseRegistryKey =
    "cnd_sbr_clock_base_source_states_v1";

static bool themer_clock_remote_string_equals(uint64_t object,
                                               const char *selectorName,
                                               const char *expected)
{
    if (!r_is_objc_ptr(object) || !selectorName || !expected ||
        !r_responds_main(object, selectorName)) {
        return false;
    }
    uint64_t value = r_msg2_main(object, selectorName, 0, 0, 0, 0);
    char actual[192] = {0};
    return r_is_objc_ptr(value) &&
        r_read_nsstring(value, actual, sizeof(actual)) &&
        strcmp(actual, expected) == 0 && remote_call_current_success();
}

static bool themer_clock_leaf_is_base_source(uint64_t leaf)
{
    return themer_clock_remote_string_equals(
               leaf, "leafIdentifier", kThemerClockBaseIdentifier) ||
        themer_clock_remote_string_equals(
               leaf, "iconTypeIdentifierForImage",
               kThemerClockBaseIdentifier);
}

static bool themer_clock_layered_icon_is_base_source(uint64_t icon)
{
    if (themer_clock_remote_string_equals(
            icon, "typeIdentifier", kThemerClockBaseIdentifier)) {
        return true;
    }
    uint64_t value = r_is_objc_ptr(icon)
        ? r_ivar_value(icon, "_typeIdentifier") : 0;
    char actual[192] = {0};
    return r_is_objc_ptr(value) &&
        r_read_nsstring(value, actual, sizeof(actual)) &&
        strcmp(actual, kThemerClockBaseIdentifier) == 0 &&
        remote_call_current_success();
}

static uint64_t themer_make_clock_base_descriptor(void)
{
    uint64_t descriptor = themer_make_is_descriptor(
        68.0, 3.0, 0, 0, false);
    if (!r_is_objc_ptr(descriptor)) return 0;

    static const struct {
        const char *selector;
        uint64_t value;
        bool required;
    } fields[] = {
        { "setIconVariant:", 0, false },
        { "setVariantOptions:", 0, false },
        { "setBadgeOptions:", 0, false },
        { "setBackgroundStyle:", 0, false },
        { "setGraphicVariant:", 0, false },
        { "setSpecialIconOptions:", 2, true },
        { "setPlatformStyle:", 0, false },
        { "setIgnoreCache:", 0, true },
        { "setShouldApplyMask:", 1, true },
        { "setDrawBorder:", 0, true },
        { "setDrawBadge:", 1, true },
        { "setContrast:", 0, false },
        { "setVibrancy:", 0, false },
        { "setLanguageDirection:", 1, true },
        { "setLayoutDirection:", 5, true },
        { "setAssetPlatformHint:", 0, false },
    };
    bool configured = true;
    for (NSUInteger index = 0;
         index < sizeof(fields) / sizeof(fields[0]); index++) {
        if (!r_responds_main(descriptor, fields[index].selector)) {
            configured = configured && !fields[index].required;
            continue;
        }
        r_msg2_main(descriptor, fields[index].selector,
                    fields[index].value, 0, 0, 0);
        configured = configured && remote_call_current_success();
    }

    char description[512] = {0};
    bool exactDigest = configured &&
        themer_read_remote_description(
            descriptor, description, sizeof(description)) &&
        strstr(description,
               "9E1D8C88-D314-329D-BE0F-1D262142B74B") != NULL;
    if (!exactDigest) {
        printf("[SBR_CLOCK_BASE] descriptor mismatch description=\"%s\"\n",
               description[0] ? description : "-");
        if (remote_call_current_success()) {
            r_msg2(descriptor, "release", 0, 0, 0, 0);
        }
        return 0;
    }
    return descriptor;
}

static uint64_t themer_clock_base_registry(bool create)
{
    uint64_t registry = themer_spotlight_associated_process_object(
        kThemerClockBaseRegistryKey);
    if (r_is_objc_ptr(registry) || !create) return registry;

    uint64_t arrayClass = themer_lookup_class("NSMutableArray");
    uint64_t allocation = r_is_objc_ptr(arrayClass)
        ? r_msg2(arrayClass, "alloc", 0, 0, 0, 0) : 0;
    registry = r_is_objc_ptr(allocation)
        ? r_msg2_main(allocation, "initWithCapacity:", 4, 0, 0, 0) : 0;
    bool committed = r_is_objc_ptr(registry) &&
        themer_spotlight_commit_process_object(
            kThemerClockBaseRegistryKey, registry);
    if (r_is_objc_ptr(registry) && remote_call_current_success()) {
        r_msg2(registry, "release", 0, 0, 0, 0);
    }
    return committed
        ? themer_spotlight_associated_process_object(
              kThemerClockBaseRegistryKey)
        : 0;
}

static uint64_t themer_clock_base_state_for_leaf(uint64_t registry,
                                                 uint64_t leaf)
{
    uint64_t count = themer_remote_count(registry);
    if (count > 64) return 0;
    for (uint64_t index = 0; index < count; index++) {
        uint64_t state = r_msg2_main(
            registry, "objectAtIndex:", index, 0, 0, 0);
        if (themer_spotlight_dictionary_object(state, "leaf") == leaf) {
            return state;
        }
    }
    return 0;
}

static uint64_t themer_clock_base_number(uint64_t value)
{
    uint64_t numberClass = themer_lookup_class("NSNumber");
    return r_is_objc_ptr(numberClass) &&
           r_responds_main(numberClass, "numberWithUnsignedLongLong:")
        ? r_msg2_main(numberClass, "numberWithUnsignedLongLong:",
                      value, 0, 0, 0)
        : 0;
}

static uint64_t themer_clock_base_leaf_subclass(uint64_t currentClass)
{
    if (!r_is_objc_ptr(currentClass)) return 0;
    static const char prefix[] = "CNDClockBaseSourceLeafV1_";
    char baseName[128] = {0};
    themer_read_class_object_name(
        currentClass, baseName, sizeof(baseName));
    while (!strncmp(baseName, prefix, sizeof(prefix) - 1)) {
        uint64_t superClass = r_dlsym_call(
            R_TIMEOUT, "class_getSuperclass", currentClass,
            0, 0, 0, 0, 0, 0, 0);
        if (!r_is_objc_ptr(superClass) || superClass == currentClass) {
            return 0;
        }
        currentClass = superClass;
        themer_read_class_object_name(
            currentClass, baseName, sizeof(baseName));
    }
    if (!baseName[0]) return 0;

    uint64_t sourceMethod = r_dlsym_call(
        R_TIMEOUT, "class_getInstanceMethod", currentClass,
        r_sel("iconServicesIconForImage"), 0, 0, 0, 0, 0, 0);
    if (!sourceMethod ||
        !themer_remote_method_has_types(sourceMethod, "@16@0:8")) {
        return 0;
    }

    char subclassName[192] = {0};
    snprintf(subclassName, sizeof(subclassName), "%s%s", prefix, baseName);
    uint64_t subclass = themer_lookup_class(subclassName);
    uint64_t getAssociatedObject =
        themer_remote_symbol_addr("objc_getAssociatedObject");
    if (!getAssociatedObject) return 0;

    if (!r_is_objc_ptr(subclass)) {
        uint64_t remoteName = r_alloc_str(subclassName);
        subclass = remoteName ? r_dlsym_call(
            R_TIMEOUT, "objc_allocateClassPair", currentClass, remoteName,
            0, 0, 0, 0, 0, 0) : 0;
        if (remoteName && remote_call_current_success()) r_free(remoteName);
        if (!r_is_objc_ptr(subclass) ||
            !themer_add_method(subclass, "iconServicesIconForImage",
                               getAssociatedObject, "@16@0:8")) {
            return 0;
        }
        r_dlsym_call(R_TIMEOUT, "objc_registerClassPair",
                     subclass, 0, 0, 0, 0, 0, 0, 0);
    }

    uint64_t method = r_dlsym_call(
        R_TIMEOUT, "class_getInstanceMethod", subclass,
        r_sel("iconServicesIconForImage"), 0, 0, 0, 0, 0, 0);
    uint64_t installed = themer_method_imp(
        subclass, "iconServicesIconForImage");
    return method &&
        themer_remote_method_has_types(method, "@16@0:8") &&
        native_strip(installed) == native_strip(getAssociatedObject) &&
        remote_call_current_success()
        ? subclass : 0;
}

static uint64_t themer_clock_base_image_for_descriptor(uint64_t source,
                                                       uint64_t cache,
                                                       uint64_t descriptor)
{
    if (!r_is_objc_ptr(descriptor)) return 0;
    static const char *const sourceSelectors[] = {
        "imageForImageDescriptor:", "imageForDescriptor:",
    };
    for (NSUInteger index = 0;
         index < sizeof(sourceSelectors) / sizeof(sourceSelectors[0]);
         index++) {
        if (!r_is_objc_ptr(source) ||
            !r_responds_main(source, sourceSelectors[index])) continue;
        uint64_t image = r_msg2_main(
            source, sourceSelectors[index], descriptor, 0, 0, 0);
        if (r_is_objc_ptr(image)) return image;
    }
    return r_is_objc_ptr(cache) &&
           r_responds_main(cache, "imageForDescriptor:")
        ? r_msg2_main(cache, "imageForDescriptor:",
                      descriptor, 0, 0, 0)
        : 0;
}

static bool themer_clock_base_seed_and_verify(uint64_t source,
                                              uint64_t cache,
                                              uint64_t descriptor,
                                              uint64_t replacement)
{
    if (!r_is_objc_ptr(source) || !r_is_objc_ptr(cache) ||
        !r_is_objc_ptr(descriptor) || !r_is_objc_ptr(replacement) ||
        !r_responds_main(cache, "setImage:forDescriptor:") ||
        !r_responds_main(cache, "imageForDescriptor:")) {
        return false;
    }
    r_msg2_main(cache, "setImage:forDescriptor:",
                replacement, descriptor, 0, 0);
    uint64_t cacheReadback = remote_call_current_success()
        ? r_msg2_main(cache, "imageForDescriptor:",
                      descriptor, 0, 0, 0)
        : 0;
    uint64_t sourceReadback = remote_call_current_success()
        ? themer_clock_base_image_for_descriptor(
              source, cache, descriptor)
        : 0;
    return themer_spotlight_images_match(
               replacement, cacheReadback) &&
        themer_spotlight_images_match(
               replacement, sourceReadback) &&
        remote_call_current_success();
}

static int themer_collect_exact_clock_image_views(uint64_t *views, int cap)
{
    if (!views || cap <= 0) return 0;
    uint64_t clockViewClass =
        r_class("SBHClockApplicationIconImageView");
    if (!r_is_objc_ptr(clockViewClass)) return 0;

    /* The VM refresh probe proved this direct identity path.  Do not use
     * sb_collect_views_in_windows() here: despite its bounded output, that
     * helper recursively visits as many as 4096 UIKit nodes and every visit
     * crosses SpringBoard's main-thread RemoteCall boundary. */
    uint64_t controllerClass = r_class("SBIconController");
    uint64_t controller = r_is_objc_ptr(controllerClass) &&
                          r_responds_main(controllerClass, "sharedInstance")
        ? r_msg2_main(controllerClass, "sharedInstance", 0, 0, 0, 0)
        : 0;
    uint64_t manager = r_is_objc_ptr(controller) &&
                       r_responds_main(controller, "iconManager")
        ? r_msg2_main(controller, "iconManager", 0, 0, 0, 0)
        : 0;
    if (!r_is_objc_ptr(manager)) {
        uint64_t managerClass = r_class("SBHIconManager");
        manager = r_is_objc_ptr(managerClass) &&
                  r_responds_main(managerClass, "sharedInstance")
            ? r_msg2_main(managerClass, "sharedInstance", 0, 0, 0, 0)
            : 0;
    }
    uint64_t model = r_is_objc_ptr(manager) &&
                     r_responds_main(manager, "iconModel")
        ? r_msg2_main(manager, "iconModel", 0, 0, 0, 0)
        : 0;
    if (!r_is_objc_ptr(model) && r_is_objc_ptr(manager) &&
        r_responds_main(manager, "model")) {
        model = r_msg2_main(manager, "model", 0, 0, 0, 0);
    }

    uint64_t bundle = r_nsstr_retained("com.apple.mobiletimer");
    uint64_t icon = r_is_objc_ptr(model) && r_is_objc_ptr(bundle) &&
                    r_responds_main(
                        model, "applicationIconForBundleIdentifier:")
        ? r_msg2_main(model, "applicationIconForBundleIdentifier:",
                      bundle, 0, 0, 0)
        : 0;
    if (r_is_objc_ptr(bundle) && remote_call_current_success()) {
        r_msg2(bundle, "release", 0, 0, 0, 0);
    }

    uint64_t root = r_is_objc_ptr(manager) &&
                    r_responds_main(manager, "rootFolderController")
        ? r_msg2_main(manager, "rootFolderController", 0, 0, 0, 0)
        : 0;
    if (!r_is_objc_ptr(root) && r_is_objc_ptr(controller) &&
        r_responds_main(controller, "rootFolderController")) {
        root = r_msg2_main(controller, "rootFolderController", 0, 0, 0, 0);
    }
    uint64_t iconView = r_is_objc_ptr(root) && r_is_objc_ptr(icon) &&
                        r_responds_main(root, "displayedIconViewForIcon:")
        ? r_msg2_main(root, "displayedIconViewForIcon:",
                      icon, 0, 0, 0)
        : 0;
    uint64_t imageView =
        themer_icon_image_view_for_iconview(iconView);
    uint64_t actualClass = r_is_objc_ptr(imageView)
        ? r_dlsym_call(R_TIMEOUT, "object_getClass", imageView,
                       0, 0, 0, 0, 0, 0, 0)
        : 0;
    bool exact = actualClass == clockViewClass &&
        remote_call_current_success();
    if (exact) views[0] = imageView;
    printf("[SBR_CLOCK_BASE] targeted-view model=%#llx icon=%#llx "
           "root=%#llx icon-view=%#llx image-view=%#llx exact=%d\n",
           (unsigned long long)model,
           (unsigned long long)icon,
           (unsigned long long)root,
           (unsigned long long)iconView,
           (unsigned long long)imageView,
           exact);
    return exact ? 1 : 0;
}

static NSDictionary<NSString *, id> *
themer_configure_clock_base_source(NSData *background, bool install)
{
    enum { VIEW_CAP = 64, STATE_CAP = 64 };
    uint64_t registry = themer_clock_base_registry(install);
    uint64_t stateCount = r_is_objc_ptr(registry)
        ? themer_remote_count(registry) : 0;
    if (stateCount > STATE_CAP) {
        return @{
            @"ok": @NO,
            @"stage": @"clock-base-registry-invalid",
            @"message": @"The retained Clock source registry exceeded its bounded capacity.",
        };
    }

    uint64_t views[VIEW_CAP] = {0};
    /* Recovery owns every previously changed leaf in the retained registry.
     * It never needs to locate a mounted Clock view.  Keeping the old lookup
     * out of Restore also lets the replacement route below migrate an older
     * process without reintroducing a visibility requirement. */
    int viewCount = install
        ? themer_collect_exact_clock_image_views(views, VIEW_CAP)
        : 0;

    if (!install) {
        bool restored = true;
        NSUInteger restoredStates = 0;
        for (uint64_t index = 0;
             index < stateCount && remote_call_current_success(); index++) {
            uint64_t state = r_msg2_main(
                registry, "objectAtIndex:", index, 0, 0, 0);
            uint64_t leaf = themer_spotlight_dictionary_object(
                state, "leaf");
            uint64_t source = themer_spotlight_dictionary_object(
                state, "source");
            uint64_t descriptor = themer_spotlight_dictionary_object(
                state, "descriptor");
            uint64_t originalImage =
                themer_spotlight_dictionary_object(
                    state, "originalImage");
            uint64_t classNumber =
                themer_spotlight_dictionary_object(
                    state, "originalClass");
            uint64_t originalClass = r_is_objc_ptr(classNumber) &&
                r_responds_main(classNumber, "unsignedLongLongValue")
                ? r_msg2_main(classNumber, "unsignedLongLongValue",
                              0, 0, 0, 0)
                : 0;
            uint64_t cache = r_is_objc_ptr(source) &&
                r_responds_main(source, "imageCache")
                ? r_msg2_main(source, "imageCache", 0, 0, 0, 0)
                : 0;
            bool oneRestored = r_is_objc_ptr(leaf) &&
                r_is_objc_ptr(source) && r_is_objc_ptr(cache) &&
                r_is_objc_ptr(descriptor) &&
                r_is_objc_ptr(originalImage) &&
                r_is_objc_ptr(originalClass) &&
                themer_clock_base_seed_and_verify(
                    source, cache, descriptor, originalImage);
            if (oneRestored) {
                uint64_t currentClass = r_dlsym_call(
                    R_TIMEOUT, "object_getClass", leaf,
                    0, 0, 0, 0, 0, 0, 0);
                if (currentClass != originalClass) {
                    uint64_t previous = r_dlsym_call(
                        R_TIMEOUT, "object_setClass", leaf, originalClass,
                        0, 0, 0, 0, 0, 0);
                    oneRestored = previous == currentClass &&
                        remote_call_current_success();
                }
            }
            if (oneRestored) {
                oneRestored = themer_set_remote_associated_object(
                    leaf, "iconServicesIconForImage", 0);
            }
            if (oneRestored) restoredStates++;
            restored = restored && oneRestored;
        }

        if (restored && stateCount > 0) {
            restored = themer_spotlight_commit_process_object(
                kThemerClockBaseRegistryKey, 0);
        }
        if (restored) {
            for (int pass = 0; pass < 2; pass++) {
                for (int index = 0; index < viewCount; index++) {
                    if (r_responds_main(
                            views[index], "updateImageAnimated:")) {
                        r_msg2_main(views[index], "updateImageAnimated:",
                                    0, 0, 0, 0);
                    }
                }
            }
        }
        bool ok = restored && remote_call_current_success();
        return @{
            @"ok": @(ok),
            @"stage": ok ? @"clock-base-restored" :
                @"clock-base-restore",
            @"message": ok
                ? @"The exact clock.base source caches and leaf classes were restored."
                : @"The exact clock.base source restore did not fully verify; its registry was retained.",
            @"sourceIdentifier": @"com.apple.application-icon.clock.base",
            @"descriptorDigest": @"9E1D8C88-D314-329D-BE0F-1D262142B74B",
            @"stateCount": @(stateCount),
            @"restoredStateCount": @(restoredStates),
            @"viewCount": @(viewCount),
            @"refreshPasses": @(restored ? 2 : 0),
            @"viewPaintUsed": @NO,
        };
    }

    if (background.length == 0 || !r_is_objc_ptr(registry)) {
        return @{
            @"ok": @NO,
            @"stage": @"clock-base-input",
            @"message": @"The exact clock.base replacement image or process registry is unavailable.",
        };
    }

    uint64_t descriptor = themer_make_clock_base_descriptor();
