        if (!r_responds_main(view, "iconForImage")) {
            configured = false;
            break;
        }
        uint64_t leaf = r_msg2_main(
            view, "iconForImage", 0, 0, 0, 0);
        if (!r_is_objc_ptr(leaf) ||
            !themer_clock_leaf_is_base_source(leaf)) {
            configured = false;
            break;
