            R_TIMEOUT, "object_getClass", leaf,
            0, 0, 0, 0, 0, 0, 0);
        uint64_t subclass =
            themer_clock_base_leaf_subclass(originalClass);
        uint64_t source = r_responds_main(
            leaf, "iconServicesIconForImage")
            ? r_msg2_main(leaf, "iconServicesIconForImage",
                          0, 0, 0, 0)
            : 0;
        uint64_t cache = r_is_objc_ptr(source) &&
            r_responds_main(source, "imageCache")
            ? r_msg2_main(source, "imageCache", 0, 0, 0, 0)
            : 0;
        uint64_t originalImage =
            themer_clock_base_image_for_descriptor(
                source, cache, descriptor);
        bool sourceReady = r_is_objc_ptr(originalClass) &&
            r_is_objc_ptr(subclass) &&
            themer_clock_layered_icon_is_base_source(source) &&
            r_is_objc_ptr(cache) && r_is_objc_ptr(originalImage) &&
            themer_clock_base_seed_and_verify(
                source, cache, descriptor, replacement);
        if (!sourceReady) {
            configured = false;
            break;
        }

        uint64_t dictionaryClass =
            themer_lookup_class("NSMutableDictionary");
        uint64_t allocation = r_is_objc_ptr(dictionaryClass)
            ? r_msg2(dictionaryClass, "alloc", 0, 0, 0, 0) : 0;
        uint64_t state = r_is_objc_ptr(allocation)
            ? r_msg2_main(allocation, "initWithCapacity:",
                          6, 0, 0, 0)
            : 0;
        uint64_t classNumber =
            themer_clock_base_number(originalClass);
        bool stateReady = r_is_objc_ptr(state) &&
            r_is_objc_ptr(classNumber) &&
            themer_spotlight_dictionary_set_object(
                state, "leaf", leaf) &&
            themer_spotlight_dictionary_set_object(
                state, "source", source) &&
            themer_spotlight_dictionary_set_object(
                state, "descriptor", descriptor) &&
            themer_spotlight_dictionary_set_object(
                state, "originalImage", originalImage) &&
            themer_spotlight_dictionary_set_object(
                state, "replacementImage", replacement) &&
            themer_spotlight_dictionary_set_object(
                state, "originalClass", classNumber);

        bool bridgeReady = stateReady &&
            themer_set_remote_associated_object(
                leaf, "iconServicesIconForImage", source);
        if (bridgeReady) {
            uint64_t previousClass = r_dlsym_call(
                R_TIMEOUT, "object_setClass", leaf, subclass,
                0, 0, 0, 0, 0, 0);
            bridgeReady = previousClass == originalClass &&
                r_msg2_main(leaf, "iconServicesIconForImage",
                            0, 0, 0, 0) == source &&
                remote_call_current_success();
        }

        bool committed = false;
        if (bridgeReady) {
            uint64_t beforeCount = themer_remote_count(registry);
            r_msg2_main(registry, "addObject:", state, 0, 0, 0);
            uint64_t afterCount = themer_remote_count(registry);
            uint64_t last = afterCount > 0
                ? r_msg2_main(registry, "lastObject", 0, 0, 0, 0)
                : 0;
            committed = afterCount == beforeCount + 1 &&
                last == state && remote_call_current_success();
        }
        if (!committed && remote_call_current_success()) {
            uint64_t currentClass = r_dlsym_call(
                R_TIMEOUT, "object_getClass", leaf,
                0, 0, 0, 0, 0, 0, 0);
            if (currentClass == subclass) {
                (void)r_dlsym_call(
                    R_TIMEOUT, "object_setClass", leaf, originalClass,
                    0, 0, 0, 0, 0, 0);
            }
            (void)themer_set_remote_associated_object(
                leaf, "iconServicesIconForImage", 0);
