            configured = false;
            break;
        }
        configuredStates++;
        newStates++;
    }

    stateCount = r_is_objc_ptr(registry)
        ? themer_remote_count(registry) : 0;
    int refreshPasses = 0;
    if (configured && stateCount > 0) {
        for (int pass = 0; pass < 2; pass++) {
            for (int index = 0; index < viewCount; index++) {
                if (!r_responds_main(
                        views[index], "updateImageAnimated:")) {
                    configured = false;
                    break;
                }
                r_msg2_main(views[index], "updateImageAnimated:",
                            0, 0, 0, 0);
            }
            if (!configured || !remote_call_current_success()) break;
            refreshPasses++;
        }
    }

    NSUInteger verifiedStates = 0;
    for (uint64_t index = 0;
         configured && index < stateCount && remote_call_current_success();
         index++) {
        uint64_t state = r_msg2_main(
            registry, "objectAtIndex:", index, 0, 0, 0);
        uint64_t leaf = themer_spotlight_dictionary_object(state, "leaf");
        uint64_t source = themer_spotlight_dictionary_object(
            state, "source");
        uint64_t stateDescriptor =
            themer_spotlight_dictionary_object(state, "descriptor");
        uint64_t cache = r_is_objc_ptr(source) &&
            r_responds_main(source, "imageCache")
            ? r_msg2_main(source, "imageCache", 0, 0, 0, 0)
            : 0;
        uint64_t bridged = r_is_objc_ptr(leaf)
            ? r_msg2_main(leaf, "iconServicesIconForImage",
                          0, 0, 0, 0)
            : 0;
        bool verified = source == bridged &&
            themer_clock_base_seed_and_verify(
                source, cache, stateDescriptor, replacement);
        if (verified) verifiedStates++;
        configured = configured && verified;
    }

    if (stateCount == 0 && r_is_objc_ptr(registry) &&
        remote_call_current_success()) {
        (void)themer_spotlight_commit_process_object(
            kThemerClockBaseRegistryKey, 0);
    }
    if (r_is_objc_ptr(replacement) && remote_call_current_success()) {
        r_msg2(replacement, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(uiImage) && remote_call_current_success()) {
        r_msg2(uiImage, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(descriptor) && remote_call_current_success()) {
        r_msg2(descriptor, "release", 0, 0, 0, 0);
    }

    bool materialized = stateCount > 0;
    bool ok = prepared && configured && materialized &&
        verifiedStates == stateCount && remote_call_current_success();
    const char *stage = ok ? "clock-base-source-ready" :
        (!materialized ? "clock-base-not-materialized" :
         "clock-base-source-verify");
    printf("[SBR_CLOCK_BASE] ok=%d stage=%s views=%d states=%llu "
           "configured=%lu new=%lu verified=%lu refresh-passes=%d "
           "digest=9E1D8C88-D314-329D-BE0F-1D262142B74B\n",
           ok, stage, viewCount, (unsigned long long)stateCount,
           (unsigned long)configuredStates, (unsigned long)newStates,
           (unsigned long)verifiedStates, refreshPasses);
    return @{
        @"ok": @(ok),
        @"stage": [NSString stringWithUTF8String:stage] ?: @"clock-base-source",
        @"message": ok
            ? @"The exact clock.base leaf now returns a retained canonical IconServices source whose measured descriptor cache contains the transparent face."
            : (!materialized
                ? @"No exact SBHClockApplicationIconImageView clock.base leaf is materialized in this process; no Clock source was changed."
                : @"The exact clock.base source/cache bridge did not fully verify; retained recovery state remains available."),
        @"sourceIdentifier": @"com.apple.application-icon.clock.base",
        @"descriptorDigest": @"9E1D8C88-D314-329D-BE0F-1D262142B74B",
        @"viewCount": @(viewCount),
        @"stateCount": @(stateCount),
        @"configuredStateCount": @(configuredStates),
        @"newStateCount": @(newStates),
        @"verifiedStateCount": @(verifiedStates),
        @"refreshPasses": @(refreshPasses),
        @"consumerBridge": @"per-clock-base-leaf-associated-source",
        @"ordinaryClockBundleDescriptorsPreserved": @YES,
        @"transitionDescriptorsPreserved": @YES,
        @"viewPaintUsed": @NO,
        @"viewScanUsed": @YES,
        @"viewScanScope": @"exact-SBHClockApplicationIconImageView-only",
    };
