/* Recovery-only state for the retired block-backed Clock experiment.  No
 * installation path remains: mutating a libobjc-owned block's isa made
 * SpringBoard teardown unsafe. */
static const char *const kThemerClockDedicatedRouteStateKey =
    "cnd_sbr_clock_dedicated_route_state_v1";

static NSDictionary<NSString *, id> *
themer_configure_clock_dedicated_route(NSData *background, bool install)
{
    (void)background;
    if (install) {
        return @{
            @"ok": @NO,
            @"stage": @"clock-unsafe-route-disabled",
            @"message": @"The block-backed Clock route is permanently disabled because it is not teardown-safe.",
            @"requiresVisibleView": @NO,
            @"futureViewConstructionCovered": @NO,
            @"viewScanUsed": @NO,
            @"viewPaintUsed": @NO,
        };
    }

    uint64_t state = themer_spotlight_associated_process_object(
        kThemerClockDedicatedRouteStateKey);
    if (!r_is_objc_ptr(state)) {
        return @{
            @"ok": @YES,
            @"stage": @"clock-unsafe-route-absent",
            @"message": @"No retired block-backed Clock route is present.",
            @"blockRepaired": @YES,
            @"blockRemoved": @NO,
            @"viewScanUsed": @NO,
            @"viewPaintUsed": @NO,
        };
    }

    uint64_t routeNumber =
        themer_session_dictionary_object(state, "routeIMP");
    uint64_t originalNumber =
        themer_session_dictionary_object(state, "originalIMP");
    uint64_t blockNumber =
        themer_session_dictionary_object(state, "blockAddress");
    uint64_t routeIMP = r_is_objc_ptr(routeNumber)
        ? r_msg2(routeNumber, "unsignedLongLongValue", 0, 0, 0, 0) : 0;
    uint64_t originalIMP = r_is_objc_ptr(originalNumber)
        ? r_msg2(originalNumber, "unsignedLongLongValue", 0, 0, 0, 0) : 0;
    uint64_t blockAddress = r_is_objc_ptr(blockNumber)
        ? r_msg2(blockNumber, "unsignedLongLongValue", 0, 0, 0, 0) : 0;

    uint64_t viewClass = r_class("SBHClockApplicationIconImageView");
    uint64_t selector = r_sel("iconForImage");
    uint64_t method = r_is_objc_ptr(viewClass) && selector
        ? r_dlsym_call(R_TIMEOUT, "class_getInstanceMethod",
                       viewClass, selector, 0, 0, 0, 0, 0, 0)
        : 0;
    bool restored = method && routeIMP && originalIMP && blockAddress;
    uint64_t currentIMP = restored ? r_dlsym_call(
        R_TIMEOUT, "method_getImplementation", method,
        0, 0, 0, 0, 0, 0, 0) : 0;
    if (restored &&
        themer_strip_remote_imp(currentIMP) ==
            themer_strip_remote_imp(routeIMP)) {
        (void)r_dlsym_call(
            R_TIMEOUT, "method_setImplementation", method, originalIMP,
            0, 0, 0, 0, 0, 0);
        currentIMP = r_dlsym_call(
            R_TIMEOUT, "method_getImplementation", method,
            0, 0, 0, 0, 0, 0, 0);
    }
    restored = restored &&
        themer_strip_remote_imp(currentIMP) ==
            themer_strip_remote_imp(originalIMP) &&
        remote_call_current_success();

    /* Repair the object header before imp_removeBlock can inspect/release it.
     * If removal fails, keep the now-valid global block allocation alive. */
    uint64_t globalBlockClass = restored
        ? themer_remote_symbol_addr("_NSConcreteGlobalBlock") : 0;
    bool blockRepaired = restored && globalBlockClass &&
        remote_write64(blockAddress, globalBlockClass) &&
        remote_read64(blockAddress) == globalBlockClass &&
        remote_call_current_success();
    bool blockRemoved = blockRepaired && r_dlsym_call(
        R_TIMEOUT, "imp_removeBlock", routeIMP,
        0, 0, 0, 0, 0, 0, 0) != 0 &&
        remote_call_current_success();
    if (blockRepaired) {
        restored = themer_spotlight_commit_process_object(
            kThemerClockDedicatedRouteStateKey, 0);
    } else {
        restored = false;
    }
    if (restored && blockRemoved && remote_call_current_success()) {
        r_free(blockAddress);
    }

    return @{
        @"ok": @(restored),
        @"stage": restored ? @"clock-unsafe-route-retired" :
            @"clock-unsafe-route-retirement",
        @"message": restored
            ? @"The unsafe block-backed Clock route is retired and its block ABI was repaired before teardown."
            : @"The unsafe block-backed Clock route could not be retired safely.",
        @"blockRepaired": @(blockRepaired),
        @"blockRemoved": @(blockRemoved),
        @"stateRetainedForReuse": @NO,
        @"requiresVisibleView": @NO,
        @"futureViewConstructionCovered": @NO,
        @"viewScanUsed": @NO,
        @"viewPaintUsed": @NO,
    };
}

static const char *const kThemerCalendarProviderRegistryKey =
    "cnd_sbr_calendar_provider_source_states_v1";
static const char *const kThemerCalendarBundleIdentifier =
    "com.apple.mobilecal";

static uint64_t themer_calendar_provider_registry(bool create)
{
    uint64_t registry = themer_spotlight_associated_process_object(
        kThemerCalendarProviderRegistryKey);
    if (r_is_objc_ptr(registry) || !create) return registry;

    uint64_t arrayClass = themer_lookup_class("NSMutableArray");
    uint64_t allocation = r_is_objc_ptr(arrayClass)
        ? r_msg2(arrayClass, "alloc", 0, 0, 0, 0) : 0;
    registry = r_is_objc_ptr(allocation)
        ? r_msg2_main(allocation, "initWithCapacity:", 2, 0, 0, 0)
        : 0;
    bool committed = r_is_objc_ptr(registry) &&
        themer_spotlight_commit_process_object(
            kThemerCalendarProviderRegistryKey, registry);
    if (r_is_objc_ptr(registry) && remote_call_current_success()) {
        r_msg2(registry, "release", 0, 0, 0, 0);
    }
    return committed
        ? themer_spotlight_associated_process_object(
              kThemerCalendarProviderRegistryKey)
        : 0;
}

static uint64_t themer_calendar_state_for_provider(uint64_t registry,
                                                    uint64_t provider)
{
    uint64_t count = themer_remote_count(registry);
    if (count > 8) return 0;
    for (uint64_t index = 0; index < count; index++) {
        uint64_t state = r_msg2_main(
            registry, "objectAtIndex:", index, 0, 0, 0);
        if (themer_spotlight_dictionary_object(state, "provider") ==
            provider) {
            return state;
        }
    }
    return 0;
}

static bool themer_calendar_stock_source_is_valid(uint64_t source)
{
    uint64_t sourceClass = themer_lookup_class("CUIKIcon");
    return r_is_objc_ptr(source) && r_is_objc_ptr(sourceClass) &&
        r_responds_main(source, "isKindOfClass:") &&
        r_msg2_main(source, "isKindOfClass:",
                    sourceClass, 0, 0, 0) != 0 &&
        r_responds_main(source, "prepareImageForDescriptor:") &&
        remote_call_current_success();
}

static bool themer_calendar_bundle_source_is_valid(uint64_t source)
{
    uint64_t sourceClass =
        themer_lookup_class("ISBundleIdentifierIcon");
    return r_is_objc_ptr(source) && r_is_objc_ptr(sourceClass) &&
        r_responds_main(source, "isKindOfClass:") &&
        r_msg2_main(source, "isKindOfClass:",
                    sourceClass, 0, 0, 0) != 0 &&
        themer_clock_remote_string_equals(
            source, "bundleIdentifier",
            kThemerCalendarBundleIdentifier) &&
        r_responds_main(source, "prepareImageForDescriptor:") &&
        remote_call_current_success();
}

typedef struct {
    uint64_t caches[8];
    bool responseVerified[8][2];
    uint64_t entriesAfterResponseByCache[8];
    int cacheCount;
    NSUInteger purgeCount;
    NSUInteger responseRequestCount;
    NSUInteger responsePrepareCount;
    NSUInteger responsePrepareSuccessCount;
    NSUInteger responseVerifiedCount;
    NSUInteger responseCandidateCount;
    NSUInteger responseExactMatchCount;
    NSUInteger refillPollPasses;
    uint64_t refillWaitUS;
    uint64_t entriesBefore;
    uint64_t entriesAfter;
    uint64_t entriesAfterResponse;
    uint64_t expectedStructuredData[2];
    NSUInteger expectedStructuredDataLength[2];
    bool responseInspectionFailed;
    bool responseInspectionTruncated;
} ThemerCalendarSourceCacheRefresh;

typedef struct {
    bool required;
    uint64_t manager;
    uint64_t cache;
    NSUInteger requestedModelCount;
    NSUInteger updatedModelCount;
} ThemerCalendarConsumerCacheRefresh;

/* ISBundleIdentifierIcon owns a process-local ISImageCache independently in
 * SpringBoard and Spotlight.  A successful persistent-store replacement does
 * not invalidate that cache: the retained Calendar source can continue
 * returning the prior UUID/pixels even after its provider is reloaded.  The
 * 23A341 VM A->B proof showed that replacing imageBagsByDescriptor (rather
 * than merely advancing the provider generation) is the exact bounded
 * invalidation required in both processes. */
static bool themer_calendar_refresh_source_cache_once(
    uint64_t source,
    ThemerCalendarSourceCacheRefresh *refresh,
    bool *purgedOut,
    int *cacheIndexOut)
{
    enum { CACHE_CAP = 8 };
    if (purgedOut) *purgedOut = false;
    if (cacheIndexOut) *cacheIndexOut = -1;
    if (!refresh || !themer_calendar_bundle_source_is_valid(source) ||
        !themer_springboard_method_encoding_is(
            source, "imageCache", "@16@0:8")) {
        return false;
    }

    uint64_t cache = r_msg2_main(
        source, "imageCache", 0, 0, 0, 0);
    uint64_t cacheClass = themer_lookup_class("ISImageCache");
    bool cacheReady = r_is_objc_ptr(cache) &&
        r_is_objc_ptr(cacheClass) &&
        r_responds_main(cache, "isKindOfClass:") &&
        r_msg2_main(cache, "isKindOfClass:",
                    cacheClass, 0, 0, 0) != 0 &&
        themer_springboard_method_encoding_is(
            cache, "imageBagsByDescriptor", "@16@0:8") &&
        themer_springboard_method_encoding_is(
            cache, "setImageBagsByDescriptor:", "v24@0:8@16") &&
        remote_call_current_success();
    if (!cacheReady) return false;

    for (int index = 0; index < refresh->cacheCount; index++) {
        if (refresh->caches[index] == cache) {
            if (cacheIndexOut) *cacheIndexOut = index;
            return true;
        }
    }
    if (refresh->cacheCount >= CACHE_CAP) return false;

    uint64_t beforeBags = r_msg2_main(
        cache, "imageBagsByDescriptor", 0, 0, 0, 0);
    uint64_t beforeCount = themer_remote_count(beforeBags);
    uint64_t dictionaryClass = themer_lookup_class("NSMutableDictionary");
    uint64_t allocation = r_is_objc_ptr(dictionaryClass)
        ? r_msg2(dictionaryClass, "alloc", 0, 0, 0, 0) : 0;
    uint64_t emptyBags = r_is_objc_ptr(allocation)
        ? r_msg2_main(allocation, "init", 0, 0, 0, 0) : 0;
    if (!r_is_objc_ptr(emptyBags) || !remote_call_current_success()) {
        return false;
    }
    r_msg2_main(cache, "setImageBagsByDescriptor:",
                emptyBags, 0, 0, 0);
    if (remote_call_current_success()) {
        r_msg2(emptyBags, "release", 0, 0, 0, 0);
    }
    uint64_t afterBags = remote_call_current_success()
        ? r_msg2_main(cache, "imageBagsByDescriptor", 0, 0, 0, 0)
        : 0;
    uint64_t afterCount = themer_remote_count(afterBags);
    bool purged = r_is_objc_ptr(afterBags) && afterCount == 0 &&
        remote_call_current_success();
    if (!purged) return false;

    int cacheIndex = refresh->cacheCount;
    refresh->caches[refresh->cacheCount++] = cache;
    refresh->purgeCount++;
    refresh->entriesBefore += beforeCount;
    refresh->entriesAfter += afterCount;
    if (purgedOut) *purgedOut = true;
    if (cacheIndexOut) *cacheIndexOut = cacheIndex;
    return true;
}

typedef enum {
    ThemerCalendarExpectedResponseInspectionFailed = -1,
    ThemerCalendarExpectedResponseNotFound = 0,
    ThemerCalendarExpectedResponseFound = 1,
} ThemerCalendarExpectedResponseInspection;

/* A populated ISImageCache is not proof that it contains the themed record.
 * During the asynchronous provider refill, IconServices can publish the
 * descriptor bag before its final IFImage has arrived, and a stock response
 * is also a valid nonempty bag. Inspect only the bounded, documented
 * ISImageCache -> ISImageBag -> IFImage.data graph and require byte equality
 * with the exact journal-verified 68-point response uploaded by Cyanide. */
static ThemerCalendarExpectedResponseInspection
themer_calendar_source_cache_expected_response(
    uint64_t cache,
    uint64_t expectedStructuredData,
    NSUInteger expectedStructuredDataLength,
    uint64_t *entryCountOut,
    NSUInteger *candidateCountOut,
    bool *truncatedOut)
{
    enum {
        BAG_CAP = 16,
        IMAGE_CAP_PER_BAG = 16,
        IMAGE_CAP_TOTAL = 32,
    };
    if (entryCountOut) *entryCountOut = 0;
    if (candidateCountOut) *candidateCountOut = 0;
    if (truncatedOut) *truncatedOut = false;
    if (!r_is_objc_ptr(cache) ||
        !r_is_objc_ptr(expectedStructuredData) ||
        expectedStructuredDataLength == 0 ||
        !themer_springboard_method_encoding_is(
            cache, "imageBagsByDescriptor", "@16@0:8")) {
        return ThemerCalendarExpectedResponseInspectionFailed;
    }

    ThemerCalendarExpectedResponseInspection inspection =
        ThemerCalendarExpectedResponseInspectionFailed;
    uint64_t bags = 0;
    uint64_t bagValues = 0;
    uint64_t images = 0;
    uint64_t data = 0;
    NSUInteger candidates = 0;

    /* Every collection/value used across more than one RemoteCall must be
     * retained in the target.  Getter results can otherwise leave their
     * autorelease scope between calls on physical arm64e, turning a harmless
     * verifier into a dangling-pointer crash inside SpringBoard. */
    bags = r_msg2_main_retained_object(
        cache, "imageBagsByDescriptor", 0, 0, 0, 0);
    uint64_t entryCount = r_is_objc_ptr(bags)
        ? themer_remote_count(bags) : 0;
    if (entryCountOut) *entryCountOut = entryCount;
    if (!r_is_objc_ptr(bags) || !remote_call_current_success()) {
        goto cleanup;
    }
    if (entryCount == 0) {
        inspection = ThemerCalendarExpectedResponseNotFound;
        goto cleanup;
    }
    if (entryCount > BAG_CAP ||
        !themer_springboard_method_encoding_is(
            bags, "allValues", "@16@0:8")) {
        if (truncatedOut) *truncatedOut = entryCount > BAG_CAP;
        goto cleanup;
    }

    bagValues = r_msg2_main_retained_object(
        bags, "allValues", 0, 0, 0, 0);
    uint64_t bagCount = r_is_objc_ptr(bagValues)
        ? themer_remote_count(bagValues) : 0;
    if (!r_is_objc_ptr(bagValues) || bagCount != entryCount ||
        !themer_springboard_method_encoding_is(
            bagValues, "objectAtIndex:", "@24@0:8Q16")) {
        goto cleanup;
    }

    inspection = ThemerCalendarExpectedResponseNotFound;
    for (uint64_t bagIndex = 0;
         bagIndex < bagCount && remote_call_current_success(); bagIndex++) {
        uint64_t bag = r_msg2_main(
            bagValues, "objectAtIndex:", bagIndex, 0, 0, 0);
        if (!r_is_objc_ptr(bag) ||
            !themer_springboard_method_encoding_is(
                bag, "images", "@16@0:8")) {
            inspection = ThemerCalendarExpectedResponseInspectionFailed;
            goto cleanup;
        }
        images = r_msg2_main_retained_object(
            bag, "images", 0, 0, 0, 0);
        uint64_t imageCount = r_is_objc_ptr(images)
            ? themer_remote_count(images) : 0;
        if (!r_is_objc_ptr(images) || imageCount > IMAGE_CAP_PER_BAG ||
            candidates + imageCount > IMAGE_CAP_TOTAL ||
            !themer_springboard_method_encoding_is(
                images, "objectAtIndex:", "@24@0:8Q16")) {
            if (truncatedOut) {
                *truncatedOut = imageCount > IMAGE_CAP_PER_BAG ||
                    candidates + imageCount > IMAGE_CAP_TOTAL;
            }
            inspection = ThemerCalendarExpectedResponseInspectionFailed;
            goto cleanup;
        }

        for (uint64_t imageIndex = 0;
             imageIndex < imageCount && remote_call_current_success();
             imageIndex++) {
            uint64_t image = r_msg2_main(
                images, "objectAtIndex:", imageIndex, 0, 0, 0);
            candidates++;
            if (!r_is_objc_ptr(image) ||
                !themer_springboard_method_encoding_is(
                    image, "data", "@16@0:8")) {
                continue;
            }
            data = r_msg2_main_retained_object(
                image, "data", 0, 0, 0, 0);
            if (!r_is_objc_ptr(data) ||
                !themer_springboard_method_encoding_is(
                    data, "length", "Q16@0:8") ||
                !themer_springboard_method_encoding_is(
                    data, "isEqualToData:", "B24@0:8@16")) {
                if (r_is_objc_ptr(data) &&
                    remote_call_current_success()) {
                    r_msg2(data, "release", 0, 0, 0, 0);
                }
                data = 0;
                continue;
            }
            uint64_t length = r_msg2_main(
                data, "length", 0, 0, 0, 0);
            bool equal = length == expectedStructuredDataLength &&
                (r_msg2_main(
                    data, "isEqualToData:", expectedStructuredData,
                    0, 0, 0) & 0xff) != 0;
            if (remote_call_current_success()) {
                r_msg2(data, "release", 0, 0, 0, 0);
            }
            data = 0;
            if (equal && remote_call_current_success()) {
                inspection = ThemerCalendarExpectedResponseFound;
                goto cleanup;
            }
        }
        if (r_is_objc_ptr(images) &&
            remote_call_current_success()) {
            r_msg2(images, "release", 0, 0, 0, 0);
        }
        images = 0;
    }

cleanup:
    if (candidateCountOut) *candidateCountOut = candidates;
    if (r_is_objc_ptr(data) && remote_call_current_success()) {
        r_msg2(data, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(images) && remote_call_current_success()) {
        r_msg2(images, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(bagValues) && remote_call_current_success()) {
        r_msg2(bagValues, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(bags) && remote_call_current_success()) {
        r_msg2(bags, "release", 0, 0, 0, 0);
    }
    return remote_call_current_success()
        ? inspection
        : ThemerCalendarExpectedResponseInspectionFailed;
}

/* Make the persistent-store read explicit before invalidating the provider.
 * reloadIconImage advances the model generation, but it is not itself a
 * request for pixels when Calendar is offscreen. On 23A341, ISIcon's exact
 * object-returning prepareImageForDescriptor: implementation synchronously
 * calls imageForDescriptor:. After the bounded cache purge that path reaches
 * _imageFromStoreForDescriptor:, inserts the returned IFImage into this
 * source's ISImageCache, and returns it. Retain the result inside the target
 * main-thread invocation so physical arm64e never carries an autoreleased
 * object across RemoteCall boundaries. */
static bool themer_calendar_prepare_source_cache_once(
    uint64_t source,
    ThemerCalendarSourceCacheRefresh *refresh,
    int cacheIndex,
    int appearance)
{
    if (!refresh || cacheIndex < 0 ||
        cacheIndex >= refresh->cacheCount || cacheIndex >= 8 ||
        appearance < 0 || appearance > 1 ||
        !themer_calendar_bundle_source_is_valid(source) ||
        !r_is_objc_ptr(refresh->expectedStructuredData[appearance]) ||
        refresh->expectedStructuredDataLength[appearance] == 0) {
        return false;
    }
    if (refresh->responseVerified[cacheIndex][appearance]) return true;
    if (!themer_springboard_method_encoding_is(
            source, "prepareImageForDescriptor:", "@24@0:8@16")) {
        return false;
    }

    uint64_t descriptor = themer_make_is_descriptor(
        68.0, 3.0, appearance, 0, false);
    if (!r_is_objc_ptr(descriptor) || !remote_call_current_success()) {
        return false;
    }
    refresh->responsePrepareCount++;
    uint64_t image = r_msg2_main_retained_object(
        source, "prepareImageForDescriptor:", descriptor, 0, 0, 0);
    bool imageReady = r_is_objc_ptr(image) &&
        themer_springboard_method_encoding_is(
            image, "placeholder", "B16@0:8") &&
        (r_msg2_main(image, "placeholder", 0, 0, 0, 0) & 0xff) == 0 &&
        remote_call_current_success();

    uint64_t entries = 0;
    NSUInteger candidates = 0;
    bool truncated = false;
    if (imageReady) refresh->responseRequestCount++;
    ThemerCalendarExpectedResponseInspection inspection = imageReady
        ? themer_calendar_source_cache_expected_response(
            refresh->caches[cacheIndex],
            refresh->expectedStructuredData[appearance],
            refresh->expectedStructuredDataLength[appearance],
            &entries, &candidates, &truncated)
        : ThemerCalendarExpectedResponseInspectionFailed;
    refresh->responseCandidateCount += candidates;
    refresh->responseInspectionTruncated |= truncated;
    if (inspection == ThemerCalendarExpectedResponseInspectionFailed) {
        refresh->responseInspectionFailed = true;
    } else if (inspection == ThemerCalendarExpectedResponseFound) {
        refresh->responseVerified[cacheIndex][appearance] = true;
        refresh->responsePrepareSuccessCount++;
        refresh->responseVerifiedCount++;
        refresh->responseExactMatchCount++;
        uint64_t priorEntries =
            refresh->entriesAfterResponseByCache[cacheIndex];
        if (entries > priorEntries) {
            refresh->entriesAfterResponse += entries - priorEntries;
            refresh->entriesAfterResponseByCache[cacheIndex] = entries;
        }
    }

    if (r_is_objc_ptr(image) && remote_call_current_success()) {
        r_msg2(image, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(descriptor) && remote_call_current_success()) {
        r_msg2(descriptor, "release", 0, 0, 0, 0);
    }
    return inspection == ThemerCalendarExpectedResponseFound &&
        remote_call_current_success();
}

/* Retain a bounded fallback verifier for already-requested source caches. The
 * deterministic path prepares every distinct source synchronously before its
 * provider reload, so a successful run returns on the first pass without a
 * settling delay or any requirement that Calendar be visible. */
static bool themer_calendar_wait_for_source_cache_refills(
    ThemerCalendarSourceCacheRefresh *refresh)
{
    enum {
        REFILL_POLL_INTERVAL_US = 5000,
        REFILL_POLL_LIMIT = 51,
    };
    if (!refresh || refresh->cacheCount <= 0 ||
        refresh->cacheCount > 8 ||
        !r_is_objc_ptr(refresh->expectedStructuredData[0]) ||
        !r_is_objc_ptr(refresh->expectedStructuredData[1]) ||
        refresh->expectedStructuredDataLength[0] == 0 ||
        refresh->expectedStructuredDataLength[1] == 0) return false;

    for (NSUInteger pass = 0;
         pass < REFILL_POLL_LIMIT && remote_call_current_success(); pass++) {
        refresh->refillPollPasses++;
        for (int index = 0;
             index < refresh->cacheCount && remote_call_current_success();
             index++) {
            for (int appearance = 0;
                 appearance < 2 && remote_call_current_success();
                 appearance++) {
                if (refresh->responseVerified[index][appearance]) continue;
                refresh->responseRequestCount++;
                uint64_t entries = 0;
                NSUInteger candidates = 0;
                bool truncated = false;
                ThemerCalendarExpectedResponseInspection inspection =
                    themer_calendar_source_cache_expected_response(
                        refresh->caches[index],
                        refresh->expectedStructuredData[appearance],
                        refresh->expectedStructuredDataLength[appearance],
                        &entries, &candidates, &truncated);
                refresh->responseCandidateCount += candidates;
                refresh->responseInspectionTruncated |= truncated;
                if (inspection ==
                        ThemerCalendarExpectedResponseInspectionFailed) {
                    refresh->responseInspectionFailed = true;
                    return false;
                }
                if (inspection == ThemerCalendarExpectedResponseFound) {
                    refresh->responseVerified[index][appearance] = true;
                    refresh->responseVerifiedCount++;
                    refresh->responseExactMatchCount++;
                    uint64_t priorEntries =
                        refresh->entriesAfterResponseByCache[index];
                    if (entries > priorEntries) {
                        refresh->entriesAfterResponse +=
                            entries - priorEntries;
                        refresh->entriesAfterResponseByCache[index] = entries;
                    }
                }
            }
        }
        if (refresh->responseVerifiedCount ==
            (NSUInteger)refresh->cacheCount * 2U) {
            return true;
        }
        if (pass + 1U < REFILL_POLL_LIMIT) {
            usleep(REFILL_POLL_INTERVAL_US);
            refresh->refillWaitUS += REFILL_POLL_INTERVAL_US;
        }
    }
    return false;
}

/* Returns a +1 canonical IconServices source. The Calendar provider already
 * knows how to turn any ISIcon's prepared descriptor result into the exact
 * UIImage/ICRIconLayer requested by its consumer; only its transient CUIKIcon
 * selection is replaced. */
static uint64_t themer_calendar_registered_bundle_source(void)
{
    if (!themer_ensure_iconservices_loaded()) return 0;
    uint64_t identifier =
        r_nsstr_retained(kThemerCalendarBundleIdentifier);
    uint64_t sourceClass =
        themer_lookup_class("ISBundleIdentifierIcon");
    uint64_t managerClass = themer_lookup_class("ISIconManager");
    if (!r_is_objc_ptr(identifier) || !r_is_objc_ptr(sourceClass) ||
        !r_is_objc_ptr(managerClass)) {
        if (r_is_objc_ptr(identifier) &&
            remote_call_current_success()) {
            r_msg2(identifier, "release", 0, 0, 0, 0);
        }
        return 0;
    }

    uint64_t allocation =
        r_msg2(sourceClass, "alloc", 0, 0, 0, 0);
    uint64_t candidate = r_is_objc_ptr(allocation)
        ? r_msg2_main(allocation, "initWithBundleIdentifier:",
                      identifier, 0, 0, 0)
        : 0;
    r_msg2(identifier, "release", 0, 0, 0, 0);
    uint64_t manager = r_is_objc_ptr(candidate)
        ? r_msg2_main(managerClass, "sharedInstance", 0, 0, 0, 0)
        : 0;
    uint64_t canonical = r_is_objc_ptr(manager) &&
        r_responds_main(manager, "findOrRegisterIcon:")
        ? r_msg2_main(manager, "findOrRegisterIcon:",
                      candidate, 0, 0, 0)
        : 0;
    uint64_t retained = r_is_objc_ptr(canonical)
        ? r_msg2(canonical, "retain", 0, 0, 0, 0)
        : 0;
    if (r_is_objc_ptr(candidate) && remote_call_current_success()) {
        r_msg2(candidate, "release", 0, 0, 0, 0);
    }
    if (!themer_calendar_bundle_source_is_valid(retained)) {
        if (r_is_objc_ptr(retained) && remote_call_current_success()) {
            r_msg2(retained, "release", 0, 0, 0, 0);
        }
        return 0;
    }
    return retained;
}

static uint64_t themer_calendar_provider_subclass(uint64_t currentClass)
{
    if (!r_is_objc_ptr(currentClass)) return 0;
    static const char prefix[] = "CNDCalendarPreparedSourceV1_";
    char baseName[128] = {0};
    themer_read_class_object_name(
        currentClass, baseName, sizeof(baseName));
    while (!strncmp(baseName, prefix, sizeof(prefix) - 1)) {
        uint64_t superClass = r_dlsym_call(
            R_TIMEOUT, "class_getSuperclass", currentClass,
            0, 0, 0, 0, 0, 0, 0);
        if (!r_is_objc_ptr(superClass) || superClass == currentClass) {
            return 0;
        }
        currentClass = superClass;
        themer_read_class_object_name(
            currentClass, baseName, sizeof(baseName));
    }
    if (!baseName[0]) return 0;

    uint64_t originalMethod = r_dlsym_call(
        R_TIMEOUT, "class_getInstanceMethod", currentClass,
        r_sel("preparedISIcon"), 0, 0, 0, 0, 0, 0);
    if (!originalMethod ||
        !themer_remote_method_has_types(originalMethod, "@16@0:8")) {
        return 0;
    }

    char subclassName[192] = {0};
    snprintf(subclassName, sizeof(subclassName), "%s%s", prefix, baseName);
    uint64_t subclass = themer_lookup_class(subclassName);
    uint64_t getAssociatedObject =
        themer_remote_symbol_addr("objc_getAssociatedObject");
    if (!getAssociatedObject) return 0;

    if (!r_is_objc_ptr(subclass)) {
        uint64_t remoteName = r_alloc_str(subclassName);
        subclass = remoteName ? r_dlsym_call(
            R_TIMEOUT, "objc_allocateClassPair", currentClass, remoteName,
            0, 0, 0, 0, 0, 0) : 0;
        if (remoteName && remote_call_current_success()) r_free(remoteName);
        if (!r_is_objc_ptr(subclass) ||
            !themer_add_method(subclass, "preparedISIcon",
                               getAssociatedObject, "@16@0:8")) {
            return 0;
        }
        r_dlsym_call(R_TIMEOUT, "objc_registerClassPair",
                     subclass, 0, 0, 0, 0, 0, 0, 0);
    }

    uint64_t method = r_dlsym_call(
        R_TIMEOUT, "class_getInstanceMethod", subclass,
        r_sel("preparedISIcon"), 0, 0, 0, 0, 0, 0);
    uint64_t installed =
        themer_method_imp(subclass, "preparedISIcon");
    return method &&
        themer_remote_method_has_types(method, "@16@0:8") &&
        native_strip(installed) == native_strip(getAssociatedObject) &&
        remote_call_current_success()
        ? subclass : 0;
}

static bool themer_calendar_add_unique_model(uint64_t *models,
                                             int *modelCount,
                                             int modelCap,
                                             uint64_t model,
                                             bool *truncatedOut)
{
    if (!models || !modelCount || modelCap <= 0 ||
        !r_is_objc_ptr(model)) return false;
    for (int index = 0; index < *modelCount; index++) {
        if (models[index] == model) return true;
    }
    if (*modelCount >= modelCap) {
        if (truncatedOut) *truncatedOut = true;
        return false;
    }
    models[(*modelCount)++] = model;
    return true;
}

/* Every SBHCalendarApplicationIcon owns its own image provider.  On
 * SpringBoard the canonical model object and the mounted live leaf can be
 * distinct, so a bridge installed on only one provider does not cover the
 * other.  Collect exactly the canonical object plus Calendar entries from the
 * authoritative live-leaf map.  Spotlight has its own private model and uses
 * the exact materialized object resolved above, so it deliberately skips the
 * SpringBoard singleton graph. */
static int themer_calendar_collect_active_models(uint64_t canonicalModel,
                                                 bool spotlightGraphKnown,
                                                 uint64_t *models,
                                                 int modelCap,
                                                 int *liveLeafMatchesOut,
                                                 bool *truncatedOut)
{
    if (liveLeafMatchesOut) *liveLeafMatchesOut = 0;
    if (truncatedOut) *truncatedOut = false;
    int modelCount = 0;
    bool truncated = false;
    (void)themer_calendar_add_unique_model(
        models, &modelCount, modelCap, canonicalModel, &truncated);
    if (spotlightGraphKnown || !remote_call_current_success()) {
        if (truncatedOut) *truncatedOut = truncated;
        return modelCount;
    }

    enum { ROOT_CAP = 24, LEAF_SCAN_CAP = 2048 };
    uint64_t roots[ROOT_CAP] = {0};
    int rootCount = themer_collect_model_lookup_roots(roots, ROOT_CAP);
    int liveLeafMatches = 0;
    for (int rootIndex = 0;
         rootIndex < rootCount && remote_call_current_success(); rootIndex++) {
        uint64_t root = roots[rootIndex];
        if (!r_responds_main(
                root, "leafIconsUniquedByApplicationBundleIdentifier") ||
            !themer_springboard_method_encoding_is(
                root, "leafIconsUniquedByApplicationBundleIdentifier",
                "@16@0:8")) {
            continue;
        }
        uint64_t collection = r_msg2_main(
            root, "leafIconsUniquedByApplicationBundleIdentifier",
            0, 0, 0, 0);
        uint64_t leafObjects = 0;
        if (r_is_objc_ptr(collection) &&
            r_responds_main(collection, "allValues")) {
            leafObjects = r_msg2_main(
                collection, "allValues", 0, 0, 0, 0);
        } else if (r_is_objc_ptr(collection) &&
                   r_responds_main(collection, "allObjects")) {
            leafObjects = r_msg2_main(
                collection, "allObjects", 0, 0, 0, 0);
        }
        uint64_t leafCount = themer_remote_count(leafObjects);
        if (leafCount > LEAF_SCAN_CAP) truncated = true;
        uint64_t boundedLeafCount = MIN(
            leafCount, (uint64_t)LEAF_SCAN_CAP);
        for (uint64_t index = 0;
             index < boundedLeafCount && remote_call_current_success();
             index++) {
            uint64_t candidate = r_msg2_main(
                leafObjects, "objectAtIndex:", index, 0, 0, 0);
            char bundle[192] = {0};
            if (!themer_read_bundle_for_icon(
                    candidate, 0, bundle, sizeof(bundle)) ||
                strcmp(bundle, kThemerCalendarBundleIdentifier) != 0) {
                continue;
            }
            int beforeCount = modelCount;
            bool covered = themer_calendar_add_unique_model(
                models, &modelCount, modelCap, candidate, &truncated);
            if (covered && modelCount > beforeCount) liveLeafMatches++;
        }
    }
    if (liveLeafMatchesOut) *liveLeafMatchesOut = liveLeafMatches;
    if (truncatedOut) *truncatedOut = truncated;
    return modelCount;
}

static bool themer_calendar_provider_in_inventory(
    uint64_t provider,
    const uint64_t *activeProviders,
    int activeProviderCount)
{
    if (!r_is_objc_ptr(provider) || !activeProviders ||
        activeProviderCount < 0 || activeProviderCount > 8) return false;
    for (int index = 0; index < activeProviderCount; index++) {
        if (activeProviders[index] == provider) return true;
    }
    return false;
}

/* The registry retains recovery information, not authority over which
 * Calendar consumers are current.  A SpringBoard model rebuild can retire a
 * provider while the process remains alive. Restore and remove those stale
 * bridges before admitting the freshly discovered provider inventory so the
 * bounded registry cannot fill with dead consumers. */
static bool themer_calendar_prune_stale_provider_states(
    uint64_t registry,
    const uint64_t *activeProviders,
    int activeProviderCount,
    NSUInteger *prunedOut)
{
    if (prunedOut) *prunedOut = 0;
    uint64_t stateCount = themer_remote_count(registry);
    if (!r_is_objc_ptr(registry) || stateCount > 8 ||
        !themer_springboard_method_encoding_is(
            registry, "removeObjectAtIndex:", "v24@0:8Q16")) {
        return false;
    }
    NSUInteger pruned = 0;
    for (uint64_t cursor = stateCount;
         cursor > 0 && remote_call_current_success(); cursor--) {
        uint64_t index = cursor - 1;
        uint64_t state = r_msg2_main(
            registry, "objectAtIndex:", index, 0, 0, 0);
        uint64_t provider = themer_spotlight_dictionary_object(
            state, "provider");
        if (themer_calendar_provider_in_inventory(
                provider, activeProviders, activeProviderCount)) {
            continue;
        }

        uint64_t replacement = themer_spotlight_dictionary_object(
            state, "replacementSource");
        uint64_t classNumber = themer_spotlight_dictionary_object(
            state, "originalClass");
        uint64_t originalClass = r_is_objc_ptr(classNumber) &&
            r_responds_main(classNumber, "unsignedLongLongValue")
            ? r_msg2_main(classNumber, "unsignedLongLongValue",
                          0, 0, 0, 0)
            : 0;
        uint64_t currentClass = r_is_objc_ptr(provider) &&
            r_is_objc_ptr(originalClass)
            ? r_dlsym_call(R_TIMEOUT, "object_getClass", provider,
                           0, 0, 0, 0, 0, 0, 0)
            : 0;
        bool restored = r_is_objc_ptr(provider) &&
            r_is_objc_ptr(replacement) &&
            r_is_objc_ptr(originalClass) && r_is_objc_ptr(currentClass);
        if (restored && currentClass != originalClass) {
            uint64_t previous = r_dlsym_call(
                R_TIMEOUT, "object_setClass", provider, originalClass,
                0, 0, 0, 0, 0, 0);
            restored = previous == currentClass &&
                remote_call_current_success();
        }
        if (restored) {
            restored = themer_set_remote_associated_object(
                provider, "preparedISIcon", 0);
        }
        uint64_t stockSource = restored
            ? r_msg2_main(provider, "preparedISIcon", 0, 0, 0, 0)
            : 0;
        restored = restored && stockSource != replacement &&
            themer_calendar_stock_source_is_valid(stockSource);
        if (!restored) return false;

        uint64_t countBefore = themer_remote_count(registry);
        r_msg2_main(registry, "removeObjectAtIndex:",
                    index, 0, 0, 0);
        uint64_t countAfter = themer_remote_count(registry);
        if (countBefore != countAfter + 1 ||
            !remote_call_current_success()) return false;
        pruned++;
    }
    if (prunedOut) *prunedOut = pruned;
    return themer_remote_count(registry) == stateCount - pruned &&
        remote_call_current_success();
}

/* Provider reload advances SBHCalendarApplicationIcon's generation, but the
 * VM proved that an already-mounted Home consumer can keep its procedural
 * Calendar pixels until SBHIconImageCache receives its ordinary per-icon
 * update. This is deliberately not the old batch fallback: Calendar has at
 * most the eight canonical/live-leaf models admitted above, and each exact
 * model is updated once through SpringBoard's primary cache. Spotlight does
 * not contain SBIconController, so its provider/source path is unchanged. */
static bool themer_calendar_refresh_springboard_consumer_cache(
    const uint64_t *models,
    int modelCount,
    bool required,
    ThemerCalendarConsumerCacheRefresh *refresh)
{
    enum { MODEL_CAP = 8 };
    if (refresh) memset(refresh, 0, sizeof(*refresh));
    if (!models || modelCount <= 0 || modelCount > MODEL_CAP ||
        !refresh || !remote_call_current_success()) {
        return false;
    }

    refresh->required = required;
    if (!required) return remote_call_current_success();

    uint64_t controllerClass = r_class("SBIconController");
    bool abiReady = themer_springboard_method_encoding_is(
        controllerClass, "sharedInstance", "@16@0:8");
    uint64_t controller = abiReady
        ? r_msg2_main(controllerClass, "sharedInstance", 0, 0, 0, 0)
        : 0;
    abiReady = abiReady && r_is_objc_ptr(controller) &&
        themer_springboard_method_encoding_is(
            controller, "iconManager", "@16@0:8");
    uint64_t manager = abiReady
        ? r_msg2_main(controller, "iconManager", 0, 0, 0, 0)
        : 0;
    refresh->manager = manager;
    abiReady = abiReady && r_is_objc_ptr(manager) &&
        themer_springboard_method_encoding_is(
            manager, "iconImageCache", "@16@0:8");
    uint64_t cache = abiReady
        ? r_msg2_main(manager, "iconImageCache", 0, 0, 0, 0)
        : 0;
    refresh->cache = cache;
    abiReady = abiReady && r_is_objc_ptr(cache) &&
        themer_springboard_method_encoding_is(
            cache, "updateImageForIcon:", "v24@0:8@16");
    if (!abiReady || !remote_call_current_success()) return false;

    for (int index = 0;
         index < modelCount && remote_call_current_success(); index++) {
        uint64_t model = models[index];
        if (!r_is_objc_ptr(model)) return false;
        refresh->requestedModelCount++;
        r_msg2_main(cache, "updateImageForIcon:", model, 0, 0, 0);
        if (remote_call_current_success()) {
            refresh->updatedModelCount++;
        }
    }
    return refresh->requestedModelCount == (NSUInteger)modelCount &&
        refresh->updatedModelCount == refresh->requestedModelCount &&
        remote_call_current_success();
}

static bool themer_calendar_configure_active_provider(
    uint64_t registry,
    uint64_t model,
    ThemerCalendarSourceCacheRefresh *sourceCacheRefresh,
    bool *newStateOut,
    bool *reloadIssuedOut,
    bool *generationAdvancedOut,
    uint64_t *providerOut)
{
    enum { STATE_CAP = 8 };
    if (newStateOut) *newStateOut = false;
    if (reloadIssuedOut) *reloadIssuedOut = false;
    if (generationAdvancedOut) *generationAdvancedOut = false;
    if (providerOut) *providerOut = 0;

    bool modelABIReady =
        themer_springboard_method_encoding_is(
            model, "imageProvider", "@16@0:8") &&
        themer_springboard_method_encoding_is(
            model, "imageGeneration", "Q16@0:8");
    uint64_t provider = modelABIReady
        ? r_msg2_main(model, "imageProvider", 0, 0, 0, 0) : 0;
    if (providerOut) *providerOut = provider;
    bool providerABIReady = r_is_objc_ptr(provider) &&
        themer_springboard_method_encoding_is(
            provider, "preparedISIcon", "@16@0:8") &&
        themer_springboard_method_encoding_is(
            provider, "reloadIconImage", "v16@0:8") &&
        themer_springboard_method_encoding_is(
            provider, "delegate", "@16@0:8");
    if (!modelABIReady || !providerABIReady ||
        !r_is_objc_ptr(registry) || !remote_call_current_success()) {
        return false;
    }

    uint64_t state =
        themer_calendar_state_for_provider(registry, provider);
    bool newState = !r_is_objc_ptr(state);
    if (newStateOut) *newStateOut = newState;
    uint64_t source = newState
        ? themer_calendar_registered_bundle_source()
        : themer_spotlight_dictionary_object(
              state, "replacementSource");
    bool configured = themer_calendar_bundle_source_is_valid(source);
    uint64_t originalClass = 0;
    uint64_t subclass = 0;
    uint64_t originalStockSource = 0;

    if (configured && newState) {
        configured = themer_remote_count(registry) < STATE_CAP;
        originalClass = configured ? r_dlsym_call(
            R_TIMEOUT, "object_getClass", provider,
            0, 0, 0, 0, 0, 0, 0) : 0;
        subclass = configured
            ? themer_calendar_provider_subclass(originalClass) : 0;
        originalStockSource = configured
            ? r_msg2_main(provider, "preparedISIcon", 0, 0, 0, 0) : 0;
        configured = configured && r_is_objc_ptr(originalClass) &&
            r_is_objc_ptr(subclass) &&
            themer_calendar_stock_source_is_valid(originalStockSource);
    }

    if (configured && newState) {
        uint64_t dictionaryClass =
            themer_lookup_class("NSMutableDictionary");
        uint64_t allocation = r_is_objc_ptr(dictionaryClass)
            ? r_msg2(dictionaryClass, "alloc", 0, 0, 0, 0) : 0;
        state = r_is_objc_ptr(allocation)
            ? r_msg2_main(allocation, "initWithCapacity:", 5, 0, 0, 0)
            : 0;
        uint64_t classNumber =
            themer_clock_base_number(originalClass);
        uint64_t stockClass = r_dlsym_call(
            R_TIMEOUT, "object_getClass", originalStockSource,
            0, 0, 0, 0, 0, 0, 0);
        uint64_t stockClassNumber =
            themer_clock_base_number(stockClass);
        bool stateReady = r_is_objc_ptr(state) &&
            r_is_objc_ptr(classNumber) &&
            r_is_objc_ptr(stockClassNumber) &&
            themer_spotlight_dictionary_set_object(
                state, "model", model) &&
            themer_spotlight_dictionary_set_object(
                state, "provider", provider) &&
            themer_spotlight_dictionary_set_object(
                state, "replacementSource", source) &&
            themer_spotlight_dictionary_set_object(
                state, "originalClass", classNumber) &&
            themer_spotlight_dictionary_set_object(
                state, "originalSourceClass", stockClassNumber);
        bool bridgeReady = stateReady &&
            themer_set_remote_associated_object(
                provider, "preparedISIcon", source);
        if (bridgeReady) {
            uint64_t previousClass = r_dlsym_call(
                R_TIMEOUT, "object_setClass", provider, subclass,
                0, 0, 0, 0, 0, 0);
            bridgeReady = previousClass == originalClass &&
                r_msg2_main(provider, "preparedISIcon",
                            0, 0, 0, 0) == source &&
                remote_call_current_success();
        }
        bool committed = false;
        if (bridgeReady) {
            uint64_t beforeCount = themer_remote_count(registry);
            r_msg2_main(registry, "addObject:", state, 0, 0, 0);
            uint64_t afterCount = themer_remote_count(registry);
            committed = afterCount == beforeCount + 1 &&
                r_msg2_main(registry, "lastObject", 0, 0, 0, 0) == state &&
                remote_call_current_success();
        }
        if (!committed && remote_call_current_success()) {
            uint64_t currentClass = r_dlsym_call(
                R_TIMEOUT, "object_getClass", provider,
                0, 0, 0, 0, 0, 0, 0);
            if (currentClass == subclass) {
                (void)r_dlsym_call(
                    R_TIMEOUT, "object_setClass", provider, originalClass,
                    0, 0, 0, 0, 0, 0);
            }
            (void)themer_set_remote_associated_object(
                provider, "preparedISIcon", 0);
        }
        configured = committed;
        if (r_is_objc_ptr(state) && remote_call_current_success()) {
            r_msg2(state, "release", 0, 0, 0, 0);
        }
    } else if (configured) {
        uint64_t stateModel = themer_spotlight_dictionary_object(
            state, "model");
        uint64_t classNumber = themer_spotlight_dictionary_object(
            state, "originalClass");
        originalClass = r_is_objc_ptr(classNumber) &&
            r_responds_main(classNumber, "unsignedLongLongValue")
            ? r_msg2_main(classNumber, "unsignedLongLongValue",
                          0, 0, 0, 0)
            : 0;
        subclass = themer_calendar_provider_subclass(originalClass);
        uint64_t currentClass = r_is_objc_ptr(subclass)
            ? r_dlsym_call(R_TIMEOUT, "object_getClass", provider,
                           0, 0, 0, 0, 0, 0, 0)
            : 0;
        bool stateModelReady = stateModel == model;
        if (!stateModelReady &&
            r_msg2_main(provider, "delegate", 0, 0, 0, 0) == model) {
            stateModelReady = themer_spotlight_dictionary_set_object(
                state, "model", model);
        }
        configured = stateModelReady &&
            r_is_objc_ptr(originalClass) && r_is_objc_ptr(subclass) &&
            (currentClass == originalClass || currentClass == subclass) &&
            themer_set_remote_associated_object(
                provider, "preparedISIcon", source);
        if (configured && currentClass == originalClass) {
            uint64_t previousClass = r_dlsym_call(
                R_TIMEOUT, "object_setClass", provider, subclass,
                0, 0, 0, 0, 0, 0);
            configured = previousClass == originalClass;
        }
        configured = configured &&
            r_msg2_main(provider, "preparedISIcon", 0, 0, 0, 0) == source;
    }

    int sourceCacheIndex = -1;
    configured = configured &&
        themer_calendar_refresh_source_cache_once(
            source, sourceCacheRefresh, NULL, &sourceCacheIndex);
    for (int appearance = 0;
         appearance < 2 && configured && remote_call_current_success();
         appearance++) {
        configured = themer_calendar_prepare_source_cache_once(
            source, sourceCacheRefresh, sourceCacheIndex, appearance);
    }
    uint64_t delegate = configured
        ? r_msg2_main(provider, "delegate", 0, 0, 0, 0) : 0;
    uint64_t generationBefore = configured && delegate == model
        ? r_msg2_main(model, "imageGeneration", 0, 0, 0, 0) : 0;
    bool reloadIssued = configured && delegate == model &&
        r_msg2_main(model, "imageProvider", 0, 0, 0, 0) == provider &&
        remote_call_current_success();
    if (reloadIssued) {
        r_msg2_main(provider, "reloadIconImage", 0, 0, 0, 0);
        reloadIssued = remote_call_current_success();
    }
    if (reloadIssuedOut) *reloadIssuedOut = reloadIssued;
    uint64_t generationAfter = reloadIssued
        ? r_msg2_main(model, "imageGeneration", 0, 0, 0, 0) : 0;
    bool generationAdvanced = reloadIssued &&
        generationAfter == generationBefore + 1ULL;
    if (generationAdvancedOut) {
        *generationAdvancedOut = generationAdvanced;
    }
    /* The source has already synchronously read and verified the persistent
     * 68-point response. reloadIconImage is the remaining consumer boundary:
     * it invalidates the SBHCalendarApplicationIcon and advances its model
     * generation. Future/offscreen renders now hit the verified source cache. */
    configured = configured && reloadIssued && generationAdvanced &&
        sourceCacheIndex >= 0 &&
        r_msg2_main(provider, "preparedISIcon", 0, 0, 0, 0) == source &&
        r_msg2_main(provider, "delegate", 0, 0, 0, 0) == model &&
        remote_call_current_success();

    if (newState && r_is_objc_ptr(source) &&
        remote_call_current_success()) {
        r_msg2(source, "release", 0, 0, 0, 0);
    }
    return configured;
}

static NSDictionary<NSString *, id> *
themer_configure_calendar_provider_source(bool install,
                                          NSData *expectedStructuredDataA0,
                                          NSData *expectedStructuredDataA1,
                                          bool refreshSpringBoardConsumer)
{
    enum { STATE_CAP = 8 };
    uint64_t registry = themer_calendar_provider_registry(install);
    uint64_t stateCount = r_is_objc_ptr(registry)
        ? themer_remote_count(registry) : 0;
    if (stateCount > STATE_CAP) {
        return @{
            @"ok": @NO,
            @"stage": @"calendar-provider-registry-invalid",
            @"message": @"The retained Calendar provider registry exceeded its bounded capacity.",
        };
    }

    if (!install) {
        bool restored = true;
        NSUInteger restoredStates = 0;
        NSUInteger reloadPasses = 0;
        uint64_t restoredModels[STATE_CAP] = {0};
        int restoredModelCount = 0;
        bool restoredModelsTruncated = false;
        for (uint64_t index = 0;
             index < stateCount && remote_call_current_success(); index++) {
            uint64_t state = r_msg2_main(
                registry, "objectAtIndex:", index, 0, 0, 0);
            uint64_t model = themer_spotlight_dictionary_object(
                state, "model");
            uint64_t provider = themer_spotlight_dictionary_object(
                state, "provider");
            uint64_t replacement = themer_spotlight_dictionary_object(
                state, "replacementSource");
            uint64_t classNumber = themer_spotlight_dictionary_object(
                state, "originalClass");
            uint64_t originalClass = r_is_objc_ptr(classNumber) &&
                r_responds_main(classNumber, "unsignedLongLongValue")
                ? r_msg2_main(classNumber, "unsignedLongLongValue",
                              0, 0, 0, 0)
                : 0;
            bool oneRestored = r_is_objc_ptr(provider) &&
                r_is_objc_ptr(replacement) &&
                r_is_objc_ptr(originalClass);
            uint64_t currentClass = oneRestored ? r_dlsym_call(
                R_TIMEOUT, "object_getClass", provider,
                0, 0, 0, 0, 0, 0, 0) : 0;
            if (oneRestored && currentClass != originalClass) {
                uint64_t previous = r_dlsym_call(
                    R_TIMEOUT, "object_setClass", provider, originalClass,
                    0, 0, 0, 0, 0, 0);
                oneRestored = previous == currentClass &&
                    remote_call_current_success();
            }
            if (oneRestored) {
                oneRestored = themer_set_remote_associated_object(
                    provider, "preparedISIcon", 0);
            }
            uint64_t stockBeforeReload = oneRestored &&
                r_responds_main(provider, "preparedISIcon")
                ? r_msg2_main(provider, "preparedISIcon", 0, 0, 0, 0)
                : 0;
            oneRestored = oneRestored &&
                stockBeforeReload != replacement &&
                themer_calendar_stock_source_is_valid(stockBeforeReload);
            if (oneRestored &&
                r_responds_main(provider, "reloadIconImage")) {
                r_msg2_main(provider, "reloadIconImage", 0, 0, 0, 0);
                reloadPasses++;
            } else {
                oneRestored = false;
            }
            uint64_t stockAfterReload = oneRestored
                ? r_msg2_main(provider, "preparedISIcon", 0, 0, 0, 0)
                : 0;
            oneRestored = oneRestored &&
                stockAfterReload != replacement &&
                themer_calendar_stock_source_is_valid(stockAfterReload);
            if (oneRestored) {
                restoredStates++;
                oneRestored = themer_calendar_add_unique_model(
                    restoredModels, &restoredModelCount, STATE_CAP,
                    model, &restoredModelsTruncated);
            }
            restored = restored && oneRestored;
        }
        ThemerCalendarConsumerCacheRefresh consumerRefresh = {0};
        bool consumerRefreshOK = restored && !restoredModelsTruncated &&
            (restoredModelCount == 0 ||
             themer_calendar_refresh_springboard_consumer_cache(
                 restoredModels, restoredModelCount,
                 refreshSpringBoardConsumer, &consumerRefresh));
        restored = restored && consumerRefreshOK;
        if (restored && r_is_objc_ptr(registry)) {
            restored = themer_spotlight_commit_process_object(
                kThemerCalendarProviderRegistryKey, 0);
        }
        bool ok = restored && remote_call_current_success();
        printf("[SBR_CALENDAR_SOURCE] ok=%d stage=%s states=%llu "
               "restored=%lu reload-passes=%lu consumer-cache=%d/%lu/%lu "
               "cache=%#llx source=CUIKIcon\n",
               ok, ok ? "calendar-provider-restored" :
                        "calendar-provider-restore",
               (unsigned long long)stateCount,
               (unsigned long)restoredStates,
               (unsigned long)reloadPasses,
               consumerRefresh.required,
               (unsigned long)consumerRefresh.updatedModelCount,
               (unsigned long)consumerRefresh.requestedModelCount,
               (unsigned long long)consumerRefresh.cache);
        return @{
            @"ok": @(ok),
            @"stage": ok ? @"calendar-provider-restored" :
                @"calendar-provider-restore",
            @"message": ok
                ? @"The Calendar provider again creates a fresh date-specific CUIKIcon and its delegate was reloaded."
                : @"The Calendar provider source restore did not fully verify; its registry was retained.",
            @"stateCount": @(stateCount),
            @"restoredStateCount": @(restoredStates),
            @"reloadPasses": @(reloadPasses),
            @"consumerCacheRefreshRequired": @(consumerRefresh.required),
            @"consumerCacheRefreshCount":
                @(consumerRefresh.updatedModelCount),
            @"consumerCacheRefreshRequestedCount":
                @(consumerRefresh.requestedModelCount),
            @"stockSource": @"CUIKIcon/CUIKDefaultIconGenerator",
            @"viewScanUsed": @NO,
            @"viewPaintUsed": @NO,
        };
    }

    if (![expectedStructuredDataA0 isKindOfClass:NSData.class] ||
        ![expectedStructuredDataA1 isKindOfClass:NSData.class] ||
        expectedStructuredDataA0.length == 0 ||
        expectedStructuredDataA1.length == 0 ||
        expectedStructuredDataA0.length > (1U << 20) ||
        expectedStructuredDataA1.length > (1U << 20)) {
        printf("[SBR_CALENDAR_SOURCE] ok=0 "
               "stage=calendar-expected-68-response-missing "
               "bytes=%lu/%lu states=%llu\n",
               (unsigned long)expectedStructuredDataA0.length,
               (unsigned long)expectedStructuredDataA1.length,
               (unsigned long long)stateCount);
        return @{
            @"ok": @NO,
            @"stage": @"calendar-expected-68-response-missing",
            @"message": @"The active Calendar journal did not provide both exact verified 68-point appearance responses, so no process-local provider state was accepted.",
            @"expectedStructuredResponsePresent": @NO,
            @"expectedStructuredAppearanceCount": @2,
            @"stateCount": @(stateCount),
        };
    }

    /* Spotlight owns a private SBHIconModel and does not expose it through
     * SpringBoard's SBIconController/SBHIconManager singletons. Once the
     * user has opened Spotlight, ask that exact model to materialize the
     * canonical Calendar icon just as SpringBoard does; a visible Calendar
     * result row is not required.
     *
     * SearchUIHomeScreenModel is also present inside SpringBoard. It is not
     * Home's canonical model: selecting it there can bridge a valid but
     * unmounted SBHCalendarApplicationIcon while the mounted Home model keeps
     * its procedural CUIKIcon. refreshSpringBoardConsumer is the already
     * verified target boundary supplied by the caller, so SearchUI discovery
     * must be completely disabled for that host. */
    uint64_t model = 0;
    uint64_t spotlightOwner = 0;
    uint64_t spotlightDataSource = 0;
    uint64_t spotlightIconModel = 0;
    uint64_t spotlightRepository = 0;
    bool allowSpotlightGraph = !refreshSpringBoardConsumer;
    bool spotlightGraphKnown = allowSpotlightGraph &&
        themer_spotlight_current_graph(
            &spotlightOwner, &spotlightDataSource,
            &spotlightIconModel, &spotlightRepository);
    bool spotlightMaterializerAvailable = false;
    bool spotlightMaterializerABIVerified = false;
    bool spotlightMaterializerInvoked = false;
    /* The private SBHIconModel is authoritative, just as SpringBoard's
     * SBHIconManager.iconModel is authoritative for Home.  Resolve through
     * that model before consulting SearchUIHomeScreenModel's convenience
     * materializer, which can return a valid but different icon object. */
    if (allowSpotlightGraph && spotlightGraphKnown) {
        uint64_t spotlightRoots[3] = {
            spotlightIconModel, spotlightRepository,
            spotlightDataSource,
        };
        model = themer_lookup_model_icon_for_bundle_with_roots(
            kThemerCalendarBundleIdentifier,
            spotlightRoots,
            (int)(sizeof(spotlightRoots) / sizeof(spotlightRoots[0])));
    }
    /* current_graph intentionally reports false until the data source and
     * private SBHIconModel are both initialized, but sharedInstance can
     * already expose SearchUIHomeScreenModel's exact materializer during that
     * window. Use that call only as a bootstrap, then discard its returned
     * identity and reacquire Calendar from the private model. */
    if (allowSpotlightGraph && !r_is_objc_ptr(model) &&
        r_is_objc_ptr(spotlightOwner) &&
        r_responds_main(spotlightOwner,
                        "appIconForApplicationBundleIdentifier:")) {
        spotlightMaterializerAvailable = true;
        uint64_t ownerClass = r_dlsym_call(
            R_TIMEOUT, "object_getClass", spotlightOwner,
            0, 0, 0, 0, 0, 0, 0);
        uint64_t materializerMethod = r_is_objc_ptr(ownerClass)
            ? r_dlsym_call(
                R_TIMEOUT, "class_getInstanceMethod", ownerClass,
                r_sel("appIconForApplicationBundleIdentifier:"),
                0, 0, 0, 0, 0, 0)
            : 0;
        spotlightMaterializerABIVerified = materializerMethod &&
            themer_remote_method_has_types(
                materializerMethod, "@24@0:8@16");
        if (spotlightMaterializerABIVerified) {
            uint64_t bundleIdentifier =
                r_nsstr_retained(kThemerCalendarBundleIdentifier);
            uint64_t candidate = r_is_objc_ptr(bundleIdentifier)
                ? r_msg2_main(
                    spotlightOwner,
                    "appIconForApplicationBundleIdentifier:",
                    bundleIdentifier, 0, 0, 0)
                : 0;
            if (r_is_objc_ptr(bundleIdentifier) &&
                remote_call_current_success()) {
                r_msg2(bundleIdentifier, "release", 0, 0, 0, 0);
            }
            char candidateBundle[192] = {0};
            if (r_is_objc_ptr(candidate) &&
                themer_read_bundle_for_icon(
                    candidate, 0, candidateBundle,
                    sizeof(candidateBundle)) &&
                strcmp(candidateBundle,
                       kThemerCalendarBundleIdentifier) == 0) {
                spotlightMaterializerInvoked = true;
                themer_cache_icon_bundle(
                    candidate, kThemerCalendarBundleIdentifier);
            }
        }
    }
    if (allowSpotlightGraph && !r_is_objc_ptr(model) &&
        spotlightMaterializerInvoked && remote_call_current_success()) {
        spotlightGraphKnown = themer_spotlight_current_graph(
            &spotlightOwner, &spotlightDataSource,
            &spotlightIconModel, &spotlightRepository);
        uint64_t spotlightRoots[3] = {
            spotlightIconModel, spotlightRepository,
            spotlightDataSource,
        };
        if (spotlightGraphKnown) {
            model = themer_lookup_model_icon_for_bundle_with_roots(
                kThemerCalendarBundleIdentifier,
                spotlightRoots,
                (int)(sizeof(spotlightRoots) /
                      sizeof(spotlightRoots[0])));
        }
    }
    if (!allowSpotlightGraph && !r_is_objc_ptr(model)) {
        model = themer_lookup_model_icon_for_bundle(
            kThemerCalendarBundleIdentifier);
    }
    uint64_t activeModels[STATE_CAP] = {0};
    int liveLeafModelCount = 0;
    bool activeModelsTruncated = false;
    int activeModelCount = themer_calendar_collect_active_models(
        model, spotlightGraphKnown, activeModels, STATE_CAP,
        &liveLeafModelCount, &activeModelsTruncated);
    if (activeModelCount <= 0 || activeModelsTruncated ||
        !r_is_objc_ptr(registry)) {
        printf("[SBR_CALENDAR_SOURCE] ok=0 "
               "stage=calendar-provider-not-materialized "
               "graph=%d owner=0x%llx canonical=0x%llx models=%d "
               "leaf=%d truncated=%d materializer=%d abi=%d\n",
               spotlightGraphKnown,
               (unsigned long long)spotlightOwner,
               (unsigned long long)model,
               activeModelCount, liveLeafModelCount,
               activeModelsTruncated,
               spotlightMaterializerAvailable,
               spotlightMaterializerABIVerified);
        if (stateCount == 0 && r_is_objc_ptr(registry) &&
            remote_call_current_success()) {
            (void)themer_spotlight_commit_process_object(
                kThemerCalendarProviderRegistryKey, 0);
        }
        return @{
            @"ok": @NO,
            @"stage": @"calendar-provider-not-materialized",
            @"message": @"The bounded Calendar model inventory did not produce a complete canonical/live-leaf provider set; no partial provider update was accepted.",
            @"requiresVisibleView": @NO,
            @"spotlightGraphKnown": @(spotlightGraphKnown),
            @"spotlightMaterializerAvailable":
                @(spotlightMaterializerAvailable),
            @"spotlightMaterializerABIVerified":
                @(spotlightMaterializerABIVerified),
            @"spotlightMaterializerInvoked":
                @(spotlightMaterializerInvoked),
            @"spotlightPrivateModelRequired":
                @(allowSpotlightGraph),
            @"modelMaterialized": @(r_is_objc_ptr(model)),
            @"activeModelCount": @(activeModelCount),
            @"liveLeafModelCount": @(liveLeafModelCount),
            @"activeModelsTruncated": @(activeModelsTruncated),
        };
    }

    uint64_t activeProviders[STATE_CAP] = {0};
    int activeProviderCount = 0;
    bool providerAliasingDetected = false;
    bool providerInventoryReady = true;
    for (int index = 0;
         index < activeModelCount && remote_call_current_success(); index++) {
        uint64_t activeModel = activeModels[index];
        bool modelABIReady = themer_springboard_method_encoding_is(
            activeModel, "imageProvider", "@16@0:8");
        uint64_t provider = modelABIReady
            ? r_msg2_main(activeModel, "imageProvider", 0, 0, 0, 0)
            : 0;
        bool duplicate = themer_calendar_provider_in_inventory(
            provider, activeProviders, activeProviderCount);
        if (duplicate) {
            providerAliasingDetected = true;
        } else if (r_is_objc_ptr(provider) &&
                   activeProviderCount < STATE_CAP) {
            activeProviders[activeProviderCount++] = provider;
        } else {
            providerInventoryReady = false;
        }
    }
    NSUInteger staleStateCount = 0;
    bool staleStatesPruned = providerInventoryReady &&
        !providerAliasingDetected &&
        activeProviderCount == activeModelCount &&
        themer_calendar_prune_stale_provider_states(
            registry, activeProviders, activeProviderCount,
            &staleStateCount);
    if (!staleStatesPruned) {
        printf("[SBR_CALENDAR_SOURCE] ok=0 "
               "stage=calendar-provider-inventory-reconcile "
               "models=%d providers=%d alias=%d states=%llu\n",
               activeModelCount, activeProviderCount,
               providerAliasingDetected,
               (unsigned long long)stateCount);
        return @{
            @"ok": @NO,
            @"stage": @"calendar-provider-inventory-reconcile",
            @"message": @"The current bounded Calendar provider inventory could not be reconciled with retained recovery state.",
            @"activeModelCount": @(activeModelCount),
            @"activeProviderCount": @(activeProviderCount),
            @"providerAliasingDetected": @(providerAliasingDetected),
            @"stateCount": @(stateCount),
        };
    }

    bool configured = true;
    NSUInteger configuredProviders = 0;
    NSUInteger newStateCount = 0;
    NSUInteger reloadPasses = 0;
    NSUInteger generationAdvances = 0;
    ThemerCalendarSourceCacheRefresh sourceCacheRefresh = {0};
    NSData *expectedStructuredDataByAppearance[2] = {
        expectedStructuredDataA0,
        expectedStructuredDataA1,
    };
    bool expectedResponsesUploaded = true;
    for (int appearance = 0;
         appearance < 2 && remote_call_current_success(); appearance++) {
        NSData *expected = expectedStructuredDataByAppearance[appearance];
        sourceCacheRefresh.expectedStructuredData[appearance] =
            themer_make_remote_nsdata(expected);
        sourceCacheRefresh.expectedStructuredDataLength[appearance] =
            expected.length;
        expectedResponsesUploaded = expectedResponsesUploaded &&
            r_is_objc_ptr(
                sourceCacheRefresh.expectedStructuredData[appearance]);
    }
    if (!expectedResponsesUploaded || !remote_call_current_success()) {
        printf("[SBR_CALENDAR_SOURCE] ok=0 "
               "stage=calendar-expected-68-response-upload "
               "bytes=%lu/%lu\n",
               (unsigned long)expectedStructuredDataA0.length,
               (unsigned long)expectedStructuredDataA1.length);
        for (int appearance = 0;
             appearance < 2 && remote_call_current_success(); appearance++) {
            uint64_t uploaded =
                sourceCacheRefresh.expectedStructuredData[appearance];
            if (r_is_objc_ptr(uploaded)) {
                r_msg2(uploaded, "release", 0, 0, 0, 0);
                sourceCacheRefresh.expectedStructuredData[appearance] = 0;
            }
        }
        return @{
            @"ok": @NO,
            @"stage": @"calendar-expected-68-response-upload",
            @"message": @"Both exact verified Calendar appearance responses could not be copied into the consumer process for bounded source-cache verification.",
            @"expectedStructuredResponsePresent": @YES,
            @"expectedStructuredResponseMatched": @NO,
            @"expectedStructuredAppearanceCount": @2,
        };
    }
    for (int index = 0;
         index < activeModelCount && remote_call_current_success(); index++) {
        bool newState = false;
        bool reloadIssued = false;
        bool generationAdvanced = false;
        uint64_t provider = 0;
        bool providerConfigured =
            themer_calendar_configure_active_provider(
                registry, activeModels[index], &sourceCacheRefresh,
                &newState, &reloadIssued,
                &generationAdvanced, &provider) &&
            provider == activeProviders[index];
        if (providerConfigured) configuredProviders++;
        if (providerConfigured && newState) newStateCount++;
        if (providerConfigured && reloadIssued) reloadPasses++;
        if (providerConfigured && generationAdvanced) generationAdvances++;
        configured = configured && providerConfigured;
    }
    bool sourceCachesRefilled = configured &&
        themer_calendar_wait_for_source_cache_refills(
            &sourceCacheRefresh);
    configured = configured && sourceCachesRefilled;
    ThemerCalendarConsumerCacheRefresh consumerRefresh = {0};
    bool consumerRefreshOK = configured &&
        themer_calendar_refresh_springboard_consumer_cache(
            activeModels, activeModelCount,
            refreshSpringBoardConsumer, &consumerRefresh);
    configured = configured && consumerRefreshOK;
    for (int appearance = 0;
         appearance < 2 && remote_call_current_success(); appearance++) {
        uint64_t uploaded =
            sourceCacheRefresh.expectedStructuredData[appearance];
        if (r_is_objc_ptr(uploaded)) {
            r_msg2(uploaded, "release", 0, 0, 0, 0);
        }
        sourceCacheRefresh.expectedStructuredData[appearance] = 0;
    }
    stateCount = themer_remote_count(registry);
    if (stateCount == 0 && r_is_objc_ptr(registry) &&
        remote_call_current_success()) {
        (void)themer_spotlight_commit_process_object(
            kThemerCalendarProviderRegistryKey, 0);
    }
    bool ok = configured && !activeModelsTruncated &&
        !providerAliasingDetected && activeModelCount > 0 &&
        activeProviderCount == activeModelCount &&
        configuredProviders == (NSUInteger)activeModelCount &&
        reloadPasses == configuredProviders &&
        generationAdvances == configuredProviders &&
        sourceCacheRefresh.cacheCount > 0 &&
        sourceCacheRefresh.purgeCount ==
            (NSUInteger)sourceCacheRefresh.cacheCount &&
        sourceCacheRefresh.responseVerifiedCount ==
            (NSUInteger)sourceCacheRefresh.cacheCount * 2U &&
        sourceCacheRefresh.responseExactMatchCount ==
            (NSUInteger)sourceCacheRefresh.cacheCount * 2U &&
        !sourceCacheRefresh.responseInspectionFailed &&
        !sourceCacheRefresh.responseInspectionTruncated &&
        stateCount == configuredProviders && stateCount <= STATE_CAP &&
        remote_call_current_success();
    printf("[SBR_CALENDAR_SOURCE] ok=%d stage=%s canonical=%#llx "
           "models=%d leaf=%d providers=%d configured=%lu states=%llu "
           "new=%lu stale=%lu reload-passes=%lu generations=%lu alias=%d "
           "source-caches=%d/%lu appearances=2 entries=%llu/%llu/%llu "
           "prepares=%lu/%lu exact-responses=%lu/%lu candidates=%lu scan=%s/%s "
           "reload-observations=%lu/%lu polls=%lu wait-us=%llu "
           "consumer-cache=%d/%lu/%lu cache=%#llx "
           "source=ISBundleIdentifierIcon/%s view-scan=0 view-paint=0\n",
           ok, ok ? "calendar-provider-source-ready" :
                    "calendar-provider-source-verify",
           (unsigned long long)model,
           activeModelCount, liveLeafModelCount, activeProviderCount,
           (unsigned long)configuredProviders,
           (unsigned long long)stateCount,
           (unsigned long)newStateCount,
           (unsigned long)staleStateCount,
           (unsigned long)reloadPasses,
           (unsigned long)generationAdvances,
           providerAliasingDetected,
           sourceCacheRefresh.cacheCount,
           (unsigned long)sourceCacheRefresh.purgeCount,
           (unsigned long long)sourceCacheRefresh.entriesBefore,
           (unsigned long long)sourceCacheRefresh.entriesAfter,
           (unsigned long long)sourceCacheRefresh.entriesAfterResponse,
           (unsigned long)sourceCacheRefresh.responsePrepareSuccessCount,
           (unsigned long)sourceCacheRefresh.responsePrepareCount,
           (unsigned long)sourceCacheRefresh.responseExactMatchCount,
           (unsigned long)sourceCacheRefresh.cacheCount * 2UL,
           (unsigned long)sourceCacheRefresh.responseCandidateCount,
           sourceCacheRefresh.responseInspectionFailed ? "failed" : "ok",
           sourceCacheRefresh.responseInspectionTruncated
               ? "truncated" : "bounded",
           (unsigned long)sourceCacheRefresh.responseVerifiedCount,
           (unsigned long)sourceCacheRefresh.responseRequestCount,
           (unsigned long)sourceCacheRefresh.refillPollPasses,
           (unsigned long long)sourceCacheRefresh.refillWaitUS,
           consumerRefresh.required,
           (unsigned long)consumerRefresh.updatedModelCount,
           (unsigned long)consumerRefresh.requestedModelCount,
           (unsigned long long)consumerRefresh.cache,
           kThemerCalendarBundleIdentifier);
    return @{
        @"ok": @(ok),
        @"stage": ok ? @"calendar-provider-source-ready" :
            @"calendar-provider-source-verify",
        @"message": ok
            ? @"Calendar's current canonical/live-leaf providers return the registered bundle source; every distinct source cache refilled with both exact journal-verified themed 68-point appearance responses, and SpringBoard's bounded per-Calendar cache update synchronously refreshed mounted consumers."
            : @"The bounded current Calendar provider set, both exact themed appearance refills, or native consumer invalidation did not fully verify; retained recovery state remains available.",
        @"stockSource": @"CUIKIcon/CUIKDefaultIconGenerator",
        @"replacementSource": @"ISBundleIdentifierIcon/com.apple.mobilecal",
        @"providerClass": @"SBCalendarIconImageProvider",
        @"providerSelector": @"preparedISIcon",
        @"providerSelectorABI": @"@16@0:8",
        @"spotlightGraphKnown": @(spotlightGraphKnown),
        @"spotlightMaterializerAvailable":
            @(spotlightMaterializerAvailable),
        @"spotlightMaterializerABIVerified":
            @(spotlightMaterializerABIVerified),
        @"spotlightMaterializerInvoked":
            @(spotlightMaterializerInvoked),
        @"spotlightPrivateModelRequired":
            @(allowSpotlightGraph),
        @"spotlightPrivateModelResolved":
            @(allowSpotlightGraph && spotlightGraphKnown &&
              r_is_objc_ptr(model)),
        @"modelMaterialized": @(r_is_objc_ptr(model)),
        @"activeModelCount": @(activeModelCount),
        @"liveLeafModelCount": @(liveLeafModelCount),
        @"activeProviderCount": @(activeProviderCount),
        @"configuredProviderCount": @(configuredProviders),
        @"activeModelsTruncated": @(activeModelsTruncated),
        @"providerAliasingDetected": @(providerAliasingDetected),
        @"stateCount": @(stateCount),
        @"newStateCount": @(newStateCount),
        @"staleStateCount": @(staleStateCount),
        @"reloadPasses": @(reloadPasses),
        @"generationAdvanceCount": @(generationAdvances),
        @"consumerCacheRefreshRequired": @(consumerRefresh.required),
        @"consumerCacheRefreshCount":
            @(consumerRefresh.updatedModelCount),
        @"consumerCacheRefreshRequestedCount":
            @(consumerRefresh.requestedModelCount),
        @"sourceCacheCount": @(sourceCacheRefresh.cacheCount),
        @"purgedSourceCacheCount": @(sourceCacheRefresh.purgeCount),
        @"sourceCacheEntriesBefore": @(sourceCacheRefresh.entriesBefore),
        @"sourceCacheEntriesAfter": @(sourceCacheRefresh.entriesAfter),
        @"sourceCacheEntriesObservedAfterReload":
            @(sourceCacheRefresh.entriesAfterResponse),
        @"sourceCacheReloadObservationCount":
            @(sourceCacheRefresh.responseRequestCount),
        @"sourceCachePrepareCount":
            @(sourceCacheRefresh.responsePrepareCount),
        @"sourceCachePrepareSuccessCount":
            @(sourceCacheRefresh.responsePrepareSuccessCount),
        @"sourceCacheReloadObservedCount":
            @(sourceCacheRefresh.responseVerifiedCount),
        @"sourceCacheResponseCandidateCount":
            @(sourceCacheRefresh.responseCandidateCount),
        @"sourceCacheExactResponseMatchCount":
            @(sourceCacheRefresh.responseExactMatchCount),
        @"sourceCacheResponseInspectionFailed":
            @(sourceCacheRefresh.responseInspectionFailed),
        @"sourceCacheResponseInspectionTruncated":
            @(sourceCacheRefresh.responseInspectionTruncated),
        @"sourceCacheRefillPollPasses":
            @(sourceCacheRefresh.refillPollPasses),
        @"sourceCacheRefillWaitUS":
            @(sourceCacheRefresh.refillWaitUS),
        @"expectedStructuredResponsePresent": @YES,
        @"expectedStructuredAppearanceCount": @2,
        @"expectedStructuredResponseMatched": @(
            sourceCacheRefresh.responseExactMatchCount ==
                (NSUInteger)sourceCacheRefresh.cacheCount * 2U &&
            sourceCacheRefresh.cacheCount > 0),
        @"fastPath": @NO,
        @"requiresVisibleView": @NO,
        @"viewScanUsed": @NO,
        @"viewPaintUsed": @NO,
        @"persistentDescriptorMatrixPreserved": @YES,
        @"transitionDescriptorsPreserved": @YES,
    };
}

static const char *const kThemerSpotlightFilesThumbnailRegistryKey =
    "cnd_sbr_spotlight_files_thumbnail_states_v1";
static const char *const kThemerSpotlightFilesBundleIdentifier =
    "com.apple.DocumentsApp";
static const char *const kThemerSpotlightFilesProviderIdentifier =
    "com.apple.FileProvider.LocalStorage";
static const char *const kThemerSpotlightFilesCoreSpotlightIdentifier =
    "__fpdefault/NSFileProviderRootContainerItemIdentifier";

typedef struct {
    uint64_t cell;
    uint64_t model;
    uint64_t leadingImage;
    uint64_t fallbackImage;
} ThemerSpotlightFilesRow;

static bool themer_spotlight_add_unique_controller(
    uint64_t *controllers, int *count, int cap, uint64_t controller)
{
    if (!controllers || !count || *count >= cap ||
        !r_is_objc_ptr(controller)) return false;
    for (int index = 0; index < *count; index++) {
        if (controllers[index] == controller) return false;
    }
    controllers[(*count)++] = controller;
    return true;
}

static void themer_spotlight_add_window_roots(
    uint64_t windows, uint64_t *controllers, int *count, int cap)
{
    uint64_t array = themer_spotlight_collection_array(windows);
    uint64_t windowCount = themer_collection_count_capped(array, 32);
    for (uint64_t index = 0; index < windowCount && *count < cap; index++) {
        uint64_t window = r_msg2_main(
            array, "objectAtIndex:", index, 0, 0, 0);
        uint64_t root = r_is_objc_ptr(window) &&
                        r_responds_main(window, "rootViewController")
            ? r_msg2_main(window, "rootViewController", 0, 0, 0, 0)
            : 0;
        (void)themer_spotlight_add_unique_controller(
            controllers, count, cap, root);
    }
}

static bool themer_spotlight_files_row_is_exact(uint64_t model,
                                                 uint64_t fallback)
{
    uint64_t fallbackClass = r_class("SearchUIAppIconImage");
    return r_is_objc_ptr(model) && r_is_objc_ptr(fallback) &&
        r_is_objc_ptr(fallbackClass) &&
        r_msg2_main(fallback, "isKindOfClass:",
                    fallbackClass, 0, 0, 0) != 0 &&
        themer_clock_remote_string_equals(
            model, "applicationBundleIdentifier",
            kThemerSpotlightFilesBundleIdentifier) &&
        themer_clock_remote_string_equals(
            model, "fileProviderIdentifier",
            kThemerSpotlightFilesProviderIdentifier) &&
        themer_clock_remote_string_equals(
            model, "coreSpotlightIdentifier",
            kThemerSpotlightFilesCoreSpotlightIdentifier) &&
        themer_clock_remote_string_equals(
            fallback, "bundleIdentifier",
            kThemerSpotlightFilesBundleIdentifier) &&
        remote_call_current_success();
}

/* This is deliberately a controller/cell graph, not a recursive window or
 * view walk. The iOS 26 VM trace resolves the active results through:
 * SPUIResultsViewController.resultsTableViewController ->
 * SearchUIResultsCollectionViewController.collectionView.visibleCells. */
static int themer_collect_spotlight_files_rows(
    ThemerSpotlightFilesRow *rows, int cap, int *controllerCountOut,
    int *visibleCellCountOut)
{
    enum { CONTROLLER_CAP = 128 };
    uint64_t controllers[CONTROLLER_CAP] = {0};
    int controllerCount = 0;
    int visibleCellCount = 0;
    int rowCount = 0;
    uint64_t applicationClass = r_class("UIApplication");
    uint64_t application = r_is_objc_ptr(applicationClass) &&
                           r_responds_main(
                               applicationClass, "sharedApplication")
        ? r_msg2_main(applicationClass, "sharedApplication", 0, 0, 0, 0)
        : 0;
    if (!r_is_objc_ptr(application)) return 0;

    uint64_t appWindows = r_responds_main(application, "windows")
        ? r_msg2_main(application, "windows", 0, 0, 0, 0) : 0;
    themer_spotlight_add_window_roots(
        appWindows, controllers, &controllerCount, CONTROLLER_CAP);
    uint64_t scenes = r_responds_main(application, "connectedScenes")
        ? r_msg2_main(application, "connectedScenes", 0, 0, 0, 0) : 0;
    uint64_t sceneArray = themer_spotlight_collection_array(scenes);
    uint64_t sceneCount = themer_collection_count_capped(sceneArray, 16);
    for (uint64_t index = 0;
         index < sceneCount && controllerCount < CONTROLLER_CAP; index++) {
        uint64_t scene = r_msg2_main(
            sceneArray, "objectAtIndex:", index, 0, 0, 0);
        uint64_t windows = r_is_objc_ptr(scene) &&
                           r_responds_main(scene, "windows")
            ? r_msg2_main(scene, "windows", 0, 0, 0, 0) : 0;
        themer_spotlight_add_window_roots(
            windows, controllers, &controllerCount, CONTROLLER_CAP);
    }

    for (int cursor = 0;
         cursor < controllerCount && cursor < CONTROLLER_CAP; cursor++) {
        uint64_t controller = controllers[cursor];
        uint64_t presented = r_responds_main(
            controller, "presentedViewController")
            ? r_msg2_main(controller, "presentedViewController",
                          0, 0, 0, 0)
            : 0;
        (void)themer_spotlight_add_unique_controller(
            controllers, &controllerCount, CONTROLLER_CAP, presented);
        uint64_t children = r_responds_main(
            controller, "childViewControllers")
            ? r_msg2_main(controller, "childViewControllers", 0, 0, 0, 0)
            : 0;
        uint64_t childCount = themer_collection_count_capped(children, 32);
        for (uint64_t index = 0;
             index < childCount && controllerCount < CONTROLLER_CAP;
             index++) {
            uint64_t child = r_msg2_main(
                children, "objectAtIndex:", index, 0, 0, 0);
            (void)themer_spotlight_add_unique_controller(
                controllers, &controllerCount, CONTROLLER_CAP, child);
        }

        uint64_t resultsController = r_responds_main(
            controller, "resultsTableViewController")
            ? r_msg2_main(controller, "resultsTableViewController",
                          0, 0, 0, 0)
            : 0;
        uint64_t collectionView = r_is_objc_ptr(resultsController) &&
                                  r_responds_main(
                                      resultsController, "collectionView")
            ? r_msg2_main(resultsController, "collectionView", 0, 0, 0, 0)
            : 0;
        uint64_t visibleCells = r_is_objc_ptr(collectionView) &&
                                r_responds_main(collectionView, "visibleCells")
            ? r_msg2_main(collectionView, "visibleCells", 0, 0, 0, 0)
            : 0;
        uint64_t cellCount = themer_collection_count_capped(
            visibleCells, 128);
        visibleCellCount += (int)cellCount;
        for (uint64_t index = 0;
             index < cellCount && rowCount < cap; index++) {
            uint64_t cell = r_msg2_main(
                visibleCells, "objectAtIndex:", index, 0, 0, 0);
            uint64_t model = r_is_objc_ptr(cell) &&
                             r_responds_main(cell, "rowModel")
                ? r_msg2_main(cell, "rowModel", 0, 0, 0, 0)
                : 0;
            uint64_t leading = r_is_objc_ptr(model) &&
                               r_responds_main(model, "leadingImage")
                ? r_msg2_main(model, "leadingImage", 0, 0, 0, 0)
                : 0;
            uint64_t fallback = r_is_objc_ptr(model) &&
                                r_responds_main(model, "fallbackImage")
                ? r_msg2_main(model, "fallbackImage", 0, 0, 0, 0)
                : 0;
            if (!themer_spotlight_files_row_is_exact(model, fallback)) {
                continue;
            }
            bool duplicate = false;
            for (int prior = 0; prior < rowCount; prior++) {
                if (rows[prior].model == model) {
                    duplicate = true;
                    break;
                }
            }
            if (duplicate) continue;
            rows[rowCount++] = (ThemerSpotlightFilesRow){
                .cell = cell,
                .model = model,
                .leadingImage = leading,
                .fallbackImage = fallback,
            };
        }
    }
    if (controllerCountOut) *controllerCountOut = controllerCount;
    if (visibleCellCountOut) *visibleCellCountOut = visibleCellCount;
    return rowCount;
}

static uint64_t themer_spotlight_files_thumbnail_registry(bool create)
{
    uint64_t registry = themer_spotlight_associated_process_object(
        kThemerSpotlightFilesThumbnailRegistryKey);
    if (r_is_objc_ptr(registry) || !create) return registry;
    uint64_t arrayClass = themer_lookup_class("NSMutableArray");
    uint64_t allocation = r_is_objc_ptr(arrayClass)
        ? r_msg2(arrayClass, "alloc", 0, 0, 0, 0) : 0;
    registry = r_is_objc_ptr(allocation)
        ? r_msg2_main(allocation, "initWithCapacity:", 2, 0, 0, 0)
        : 0;
    bool committed = r_is_objc_ptr(registry) &&
        themer_spotlight_commit_process_object(
            kThemerSpotlightFilesThumbnailRegistryKey, registry);
    if (r_is_objc_ptr(registry) && remote_call_current_success()) {
        r_msg2(registry, "release", 0, 0, 0, 0);
    }
    return committed
        ? themer_spotlight_associated_process_object(
              kThemerSpotlightFilesThumbnailRegistryKey)
        : 0;
}

static uint64_t themer_spotlight_files_state_for_model(uint64_t registry,
                                                        uint64_t model)
{
    uint64_t count = themer_session_collection_count(registry);
    if (count > 8) return 0;
    for (uint64_t index = 0; index < count; index++) {
        uint64_t state = r_msg2_main(
            registry, "objectAtIndex:", index, 0, 0, 0);
        if (themer_spotlight_dictionary_object(state, "model") == model) {
            return state;
        }
    }
    return 0;
}

static bool themer_spotlight_files_thumbnail_api_ready(void)
{
    uint64_t converterClass = r_class("SearchUITLKImageConverter");
    uint64_t cacheClass = r_class("SearchUIImageCache");
    uint64_t modelClass = r_class("SearchUIDetailedRowModel");
    uint64_t cellClass = r_class("SearchUICollectionViewCell");
    uint64_t converterMethod = converterClass ? r_dlsym_call(
        R_TIMEOUT, "class_getClassMethod", converterClass,
        r_sel("imageForSFImage:"), 0, 0, 0, 0, 0, 0) : 0;
    uint64_t cacheMethod = cacheClass ? r_dlsym_call(
        R_TIMEOUT, "class_getClassMethod", cacheClass,
        r_sel("cacheTLKImage:forSFImage:"), 0, 0, 0, 0, 0, 0) : 0;
    uint64_t modelMethod = modelClass ? r_dlsym_call(
        R_TIMEOUT, "class_getInstanceMethod", modelClass,
        r_sel("setLeadingImage:"), 0, 0, 0, 0, 0, 0) : 0;
    uint64_t cellMethod = cellClass ? r_dlsym_call(
        R_TIMEOUT, "class_getInstanceMethod", cellClass,
        r_sel("updateWithRowModel:"), 0, 0, 0, 0, 0, 0) : 0;
    return converterMethod && cacheMethod && modelMethod && cellMethod &&
        themer_remote_method_has_types(converterMethod, "@24@0:8@16") &&
        themer_remote_method_has_types(cacheMethod, "v32@0:8@16@24") &&
        themer_remote_method_has_types(modelMethod, "v24@0:8@16") &&
        themer_remote_method_has_types(cellMethod, "v24@0:8@16") &&
        remote_call_current_success();
}

static bool themer_spotlight_files_update_row(
    const ThemerSpotlightFilesRow *row, uint64_t image)
{
    if (!row || !r_is_objc_ptr(row->cell) ||
        !r_is_objc_ptr(row->model) || !r_is_objc_ptr(image) ||
        !r_responds_main(row->model, "setLeadingImage:") ||
        !r_responds_main(row->cell, "updateWithRowModel:")) {
        return false;
    }
    r_msg2_main(row->model, "setLeadingImage:", image, 0, 0, 0);
    r_msg2_main(row->cell, "updateWithRowModel:",
                row->model, 0, 0, 0);
    uint64_t observed = r_msg2_main(
        row->model, "leadingImage", 0, 0, 0, 0);
    return observed == image && remote_call_current_success();
}

static NSDictionary<NSString *, id> *
themer_configure_spotlight_files_thumbnail(bool install)
{
    enum { ROW_CAP = 16, STATE_CAP = 8 };
    uint64_t registry =
        themer_spotlight_files_thumbnail_registry(install);
    uint64_t initialStateCount = r_is_objc_ptr(registry)
        ? themer_session_collection_count(registry) : 0;
    if (initialStateCount > STATE_CAP) {
        return @{
            @"ok": @NO,
            @"stage": @"files-thumbnail-registry-invalid",
            @"message": @"The retained Files thumbnail registry exceeded its bounded capacity.",
        };
    }

    ThemerSpotlightFilesRow rows[ROW_CAP] = {{0}};
    int controllerCount = 0;
    int visibleCellCount = 0;
    int rowCount = themer_collect_spotlight_files_rows(
        rows, ROW_CAP, &controllerCount, &visibleCellCount);

    if (!install) {
        bool restored = true;
        NSUInteger cacheRestores = 0;
        NSUInteger modelRestores = 0;
        uint64_t defaultOriginalLeading = 0;
        for (uint64_t index = 0;
             index < initialStateCount && remote_call_current_success();
             index++) {
            uint64_t state = r_msg2_main(
                registry, "objectAtIndex:", index, 0, 0, 0);
            uint64_t model = themer_spotlight_dictionary_object(
                state, "model");
            uint64_t originalLeading = themer_spotlight_dictionary_object(
                state, "originalLeading");
            uint64_t cache = themer_spotlight_dictionary_object(
                state, "cache");
            uint64_t cacheKey = themer_spotlight_dictionary_object(
                state, "cacheKey");
            uint64_t originalCached = themer_spotlight_dictionary_object(
                state, "originalCached");
            if (!defaultOriginalLeading && r_is_objc_ptr(originalLeading)) {
                defaultOriginalLeading = originalLeading;
            }
            bool oneCache = r_is_objc_ptr(cache) &&
                r_is_objc_ptr(cacheKey) &&
                r_responds_main(cache, "removeObjectForKey:") &&
                r_responds_main(cache, "objectForKey:");
            if (oneCache) {
                r_msg2_main(cache, "removeObjectForKey:",
                            cacheKey, 0, 0, 0);
                if (r_is_objc_ptr(originalCached) &&
                    r_responds_main(cache, "setObject:forKey:")) {
                    r_msg2_main(cache, "setObject:forKey:",
                                originalCached, cacheKey, 0, 0);
                }
                uint64_t observed = r_msg2_main(
                    cache, "objectForKey:", cacheKey, 0, 0, 0);
                oneCache = r_is_objc_ptr(originalCached)
                    ? observed == originalCached : !r_is_objc_ptr(observed);
            }
            bool oneModel = r_is_objc_ptr(model) &&
                r_is_objc_ptr(originalLeading) &&
                r_responds_main(model, "setLeadingImage:");
            if (oneModel) {
                r_msg2_main(model, "setLeadingImage:",
                            originalLeading, 0, 0, 0);
                oneModel = r_msg2_main(
                    model, "leadingImage", 0, 0, 0, 0) ==
                        originalLeading;
            }
            if (oneCache) cacheRestores++;
            if (oneModel) modelRestores++;
            restored = restored && oneCache && oneModel;
        }

        NSUInteger repaints = 0;
        for (int index = 0;
             index < rowCount && r_is_objc_ptr(defaultOriginalLeading);
             index++) {
            uint64_t state = themer_spotlight_files_state_for_model(
                registry, rows[index].model);
            uint64_t original = r_is_objc_ptr(state)
                ? themer_spotlight_dictionary_object(
                      state, "originalLeading")
                : defaultOriginalLeading;
            bool toggled = themer_spotlight_files_update_row(
                &rows[index], rows[index].fallbackImage);
            bool repainted = toggled &&
                themer_spotlight_files_update_row(&rows[index], original);
            if (repainted) repaints++;
            restored = restored && repainted;
        }
        if (restored && r_is_objc_ptr(registry)) {
            restored = themer_spotlight_commit_process_object(
                kThemerSpotlightFilesThumbnailRegistryKey, 0);
        }
        bool ok = restored && remote_call_current_success();
        printf("[SBR_FILES_THUMBNAIL] ok=%d install=0 states=%llu "
               "rows=%d controllers=%d visible-cells=%d cache=%lu "
               "models=%lu repaints=%lu graph=controller-visible-cells "
               "recursive-view-walk=0\n",
               ok, (unsigned long long)initialStateCount,
               rowCount, controllerCount, visibleCellCount,
               (unsigned long)cacheRestores,
               (unsigned long)modelRestores,
               (unsigned long)repaints);
        return @{
            @"ok": @(ok),
            @"stage": ok ? @"files-thumbnail-restored" :
                @"files-thumbnail-restore",
            @"message": ok
                ? @"Spotlight's Files root row again uses its stock Quick Look thumbnail source."
                : @"Spotlight's retained Files root thumbnail state did not fully restore.",
            @"stateCount": @(initialStateCount),
            @"rowCount": @(rowCount),
            @"cacheRestoreCount": @(cacheRestores),
            @"modelRestoreCount": @(modelRestores),
            @"repaintCount": @(repaints),
            @"recursiveViewWalkUsed": @NO,
        };
    }

    bool apiReady = themer_spotlight_files_thumbnail_api_ready();
    uint64_t converterClass = apiReady
        ? r_class("SearchUITLKImageConverter") : 0;
    uint64_t cacheOwnerClass = apiReady
        ? r_class("SearchUIImageCache") : 0;
    uint64_t cacheOwner = r_is_objc_ptr(cacheOwnerClass)
        ? r_msg2_main(cacheOwnerClass, "sharedCache", 0, 0, 0, 0) : 0;
    uint64_t cache = r_is_objc_ptr(cacheOwner) &&
                     r_responds_main(cacheOwner, "imageCache")
        ? r_msg2_main(cacheOwner, "imageCache", 0, 0, 0, 0) : 0;
    bool configured = apiReady && r_is_objc_ptr(registry) &&
        r_is_objc_ptr(converterClass) && r_is_objc_ptr(cache);
    NSUInteger cacheSeeds = 0;
    NSUInteger modelUpdates = 0;
    NSUInteger newStates = 0;
    uint64_t quickLookClass = r_class("SFQuickLookThumbnailImage");

    for (int index = 0;
         configured && index < rowCount && remote_call_current_success();
         index++) {
        ThemerSpotlightFilesRow *row = &rows[index];
        uint64_t state = themer_spotlight_files_state_for_model(
            registry, row->model);
        if (r_is_objc_ptr(state)) {
            uint64_t cacheKey = themer_spotlight_dictionary_object(
                state, "cacheKey");
            uint64_t themedTLK = themer_spotlight_dictionary_object(
                state, "themedTLK");
            uint64_t replacement = themer_spotlight_dictionary_object(
                state, "replacementLeading");
            r_msg2_main(cache, "setObject:forKey:",
                        themedTLK, cacheKey, 0, 0);
            bool seeded = r_msg2_main(
                cache, "objectForKey:", cacheKey, 0, 0, 0) == themedTLK;
            bool updated = seeded &&
                themer_spotlight_files_update_row(row, replacement);
            if (seeded) cacheSeeds++;
            if (updated) modelUpdates++;
            configured = configured && seeded && updated;
            continue;
        }

        bool stockQuickLook = r_is_objc_ptr(quickLookClass) &&
            r_is_objc_ptr(row->leadingImage) &&
            r_msg2_main(row->leadingImage, "isKindOfClass:",
                        quickLookClass, 0, 0, 0) != 0;
        uint64_t themedTLK = stockQuickLook
            ? r_msg2_main(converterClass, "imageForSFImage:",
                          row->fallbackImage, 0, 0, 0)
            : 0;
        uint64_t originalCached = r_is_objc_ptr(themedTLK)
            ? r_msg2_main(cache, "objectForKey:",
                          row->leadingImage, 0, 0, 0)
            : 0;
        uint64_t dictionaryClass = themer_lookup_class(
            "NSMutableDictionary");
        uint64_t allocation = r_is_objc_ptr(dictionaryClass)
            ? r_msg2(dictionaryClass, "alloc", 0, 0, 0, 0) : 0;
        state = r_is_objc_ptr(allocation)
            ? r_msg2_main(allocation, "initWithCapacity:",
                          7, 0, 0, 0)
            : 0;
        bool stateReady = r_is_objc_ptr(state) &&
            r_is_objc_ptr(themedTLK) &&
            themer_spotlight_dictionary_set_object(
                state, "model", row->model) &&
            themer_spotlight_dictionary_set_object(
                state, "originalLeading", row->leadingImage) &&
            themer_spotlight_dictionary_set_object(
                state, "replacementLeading", row->fallbackImage) &&
            themer_spotlight_dictionary_set_object(
                state, "cache", cache) &&
            themer_spotlight_dictionary_set_object(
                state, "cacheKey", row->leadingImage) &&
            themer_spotlight_dictionary_set_object(
                state, "themedTLK", themedTLK);
        if (stateReady && r_is_objc_ptr(originalCached)) {
            stateReady = themer_spotlight_dictionary_set_object(
                state, "originalCached", originalCached);
        }
        bool seeded = false;
        bool updated = false;
        bool committed = false;
        if (stateReady) {
            r_msg2_main(cache, "setObject:forKey:",
                        themedTLK, row->leadingImage, 0, 0);
            seeded = r_msg2_main(
                cache, "objectForKey:", row->leadingImage,
                0, 0, 0) == themedTLK;
            updated = seeded &&
                themer_spotlight_files_update_row(
                    row, row->fallbackImage);
        }
        if (updated) {
            uint64_t before = themer_session_collection_count(registry);
            r_msg2_main(registry, "addObject:", state, 0, 0, 0);
            uint64_t after = themer_session_collection_count(registry);
            committed = after == before + 1 &&
                themer_spotlight_files_state_for_model(
                    registry, row->model) == state;
        }
        if (!committed && remote_call_current_success()) {
            (void)themer_spotlight_files_update_row(
                row, row->leadingImage);
            r_msg2_main(cache, "removeObjectForKey:",
                        row->leadingImage, 0, 0, 0);
            if (r_is_objc_ptr(originalCached)) {
                r_msg2_main(cache, "setObject:forKey:",
                            originalCached, row->leadingImage, 0, 0);
            }
        }
        if (r_is_objc_ptr(state) && remote_call_current_success()) {
            r_msg2(state, "release", 0, 0, 0, 0);
        }
        if (seeded && committed) cacheSeeds++;
        if (updated && committed) modelUpdates++;
        if (committed) newStates++;
        configured = configured && committed;
    }

    uint64_t finalStateCount = r_is_objc_ptr(registry)
        ? themer_session_collection_count(registry) : 0;
    bool materialized = finalStateCount > 0;
    bool ok = configured && materialized &&
        finalStateCount <= STATE_CAP && remote_call_current_success();
    if (!materialized && r_is_objc_ptr(registry) &&
        remote_call_current_success()) {
        (void)themer_spotlight_commit_process_object(
            kThemerSpotlightFilesThumbnailRegistryKey, 0);
    }
    printf("[SBR_FILES_THUMBNAIL] ok=%d install=1 api=%d "
           "states=%llu/%llu rows=%d controllers=%d visible-cells=%d "
           "new=%lu cache=%lu models=%lu "
           "graph=controller-visible-cells recursive-view-walk=0\n",
           ok, apiReady,
           (unsigned long long)initialStateCount,
           (unsigned long long)finalStateCount,
           rowCount, controllerCount, visibleCellCount,
           (unsigned long)newStates,
           (unsigned long)cacheSeeds,
           (unsigned long)modelUpdates);
    return @{
        @"ok": @(ok),
        @"stage": ok ? @"files-thumbnail-ready" :
            (materialized ? @"files-thumbnail-configuration" :
                            @"files-thumbnail-not-materialized"),
        @"message": ok
            ? @"Spotlight's exact local File Provider root uses the persistent themed Files app image, and its process cache is seeded for equivalent future rows."
            : (materialized
                ? @"Spotlight's exact Files root thumbnail did not fully verify."
                : @"The Files root result is not materialized. Search for “files” until “File Provider Storage” appears, then retry."),
        @"stateCount": @(finalStateCount),
        @"rowCount": @(rowCount),
        @"newStateCount": @(newStates),
        @"cacheSeedCount": @(cacheSeeds),
        @"modelUpdateCount": @(modelUpdates),
        @"providerIdentifier":
            @"com.apple.FileProvider.LocalStorage",
        @"coreSpotlightIdentifier":
            @"__fpdefault/NSFileProviderRootContainerItemIdentifier",
        @"replacementSource":
            @"SearchUIDetailedRowModel.fallbackImage/com.apple.DocumentsApp",
        @"controllerGraph":
            @"SPUIResultsViewController.resultsTableViewController.collectionView.visibleCells",
        @"recursiveViewWalkUsed": @NO,
    };
}

static NSDictionary<NSString *, id> *
themer_configure_clock_calendar_sources_in_session(
    NSDictionary<NSString *, NSData *> *imageDataByBundle,
    bool useStaticClockPresentation)
{
    bool installClock = imageDataByBundle[@"com.apple.mobiletimer"].length > 0;
    bool installCalendar = imageDataByBundle[@"com.apple.mobilecal"].length > 0;
    NSData *expectedCalendar68A0 =
        [imageDataByBundle[@"__cnd_calendar_68_structured"]
            isKindOfClass:NSData.class]
        ? imageDataByBundle[@"__cnd_calendar_68_structured"] : nil;
    NSData *expectedCalendar68A1 =
        [imageDataByBundle[@"__cnd_calendar_68_structured_a1"]
            isKindOfClass:NSData.class]
        ? imageDataByBundle[@"__cnd_calendar_68_structured_a1"] : nil;
    NSData *clockBackground =
        [imageDataByBundle[@"__cnd_clock_background"]
            isKindOfClass:NSData.class]
            ? imageDataByBundle[@"__cnd_clock_background"] : nil;
    bool installClockFace = installClock && clockBackground.length > 0;
    static NSArray<NSString *> *componentKeys;
    static dispatch_once_t onceToken;
    dispatch_once(&onceToken, ^{
        componentKeys = @[
            @"__cnd_clock_hours", @"__cnd_clock_minutes",
            @"__cnd_clock_seconds", @"__cnd_clock_hour_minute_dot",
            @"__cnd_clock_second_dot",
        ];
    });
    NSMutableArray<NSData *> *componentData =
        [NSMutableArray arrayWithCapacity:5];
    for (NSString *key in componentKeys) {
        NSData *data = [imageDataByBundle[key] isKindOfClass:NSData.class]
            ? imageDataByBundle[key] : nil;
        if (data.length > 0) [componentData addObject:data];
    }
    bool completeClockComponents = !useStaticClockPresentation &&
        installClock && componentData.count == 5;
    /* Resolve each process-owned recovery collection once for the whole
     * transaction.  On physical arm64e, proving the NSProcessInfo-backed
     * association crosses SpringBoard's main-thread Objective-C boundary;
     * repeating that lookup for every redirect and every appearance made a
     * bounded repair look hung even though the face/provider work had not
     * changed. */
    bool installStaticClockRedirect =
        useStaticClockPresentation && installClock;
    bool installSafeSpringBoardClockRedirect =
        !useStaticClockPresentation && installClock;
    uint64_t dynamicRedirectRegistry =
        themer_dynamic_redirect_registry(
            installStaticClockRedirect || installSafeSpringBoardClockRedirect);
    bool installClockHands = !useStaticClockPresentation &&
        completeClockComponents;
    uint64_t clockImageSetRegistry =
        themer_clock_image_set_registry(installClockHands);
    printf("[SBR_DYNAMIC_STAGE] begin host=%s clock=%d calendar=%d "
           "components=%lu/5 background=%d\n",
           useStaticClockPresentation ? "Spotlight" : "SpringBoard",
           installClock, installCalendar,
           (unsigned long)componentData.count,
           installClockFace);

    bool legacyClockRedirectChanged = false;
    bool staticClockViewClassChanged = false;
    bool legacyCalendarImageRedirectChanged = false;
    bool legacyCalendarLayerRedirectChanged = false;

    /* Retire the two obsolete Calendar redirects before any source repair;
     * either redirect can bypass the exact provider boundary. */
    bool legacyCalendarImageRedirectRestored =
        themer_configure_apple_signed_redirect(
        dynamicRedirectRegistry,
        "calendar-obsolete-generic-image",
        "SBHCalendarApplicationIcon",
        "makeIconImageWithInfo:traitCollection:context:options:",
        "SBLeafIcon",
        "makeIconImageWithInfo:traitCollection:context:options:",
        "@72@0:8{SBIconImageInfo={CGSize=dd}dd}16@48@56Q64",
        "cnd_sbr_calendar_image_original_imp", false,
        &legacyCalendarImageRedirectChanged);
    bool legacyCalendarLayerRedirectRestored =
        themer_configure_apple_signed_redirect(
        dynamicRedirectRegistry,
        "calendar-obsolete-image-backed-layer",
        "SBHCalendarApplicationIcon",
        "makeIconLayerWithInfo:traitCollection:context:options:",
        "SBIcon",
        "makeIconLayerFromImageWithInfo:traitCollection:context:options:",
        "@72@0:8{SBIconImageInfo={CGSize=dd}dd}16@48@56Q64",
        "cnd_sbr_calendar_layer_original_imp", false,
        &legacyCalendarLayerRedirectChanged);
    NSDictionary<NSString *, id> *calendarSourceResult = nil;
    if (!legacyCalendarImageRedirectRestored ||
        !legacyCalendarLayerRedirectRestored) {
        calendarSourceResult = @{
            @"ok": @NO,
            @"stage": @"calendar-obsolete-redirect-restore",
            @"message": @"An obsolete class-wide Calendar redirect could not be restored, so the exact provider source was left unchanged.",
        };
    } else {
        /* Materialize Calendar before the Clock/Spotlight presentation work.
         * This preserves the previously working Spotlight initialization
         * path. The failed physical-device trial proved that merely making
         * Calendar the final callback does not repair an unobserved 0 -> 0
         * source-cache fetch. */
        printf("[SBR_DYNAMIC_STAGE] calendar-source-begin\n");
        calendarSourceResult =
            themer_configure_calendar_provider_source(
                installCalendar, expectedCalendar68A0,
                expectedCalendar68A1,
                !useStaticClockPresentation);
    }
    bool calendarSourceOK = [calendarSourceResult[@"ok"] boolValue];
    printf("[SBR_DYNAMIC_STAGE] calendar-source-end ok=%d stage=%s\n",
           calendarSourceOK,
           [calendarSourceResult[@"stage"] UTF8String] ?: "-");

    /* Retire the unsafe block-backed experiment before installing any safe
     * Apple-owned IMP.  Its block isa must be repaired even when its method
     * redirect has already been replaced. */
    NSDictionary<NSString *, id> *unsafeClockRouteRetirement =
        themer_configure_clock_dedicated_route(nil, false);
    bool unsafeClockRouteRetired =
        [unsafeClockRouteRetirement[@"ok"] boolValue];

    /* Use only an ABI-identical Apple-signed implementation.  SpringBoard's
     * safe fallback is the previously proven generic bundle-icon background;
     * the five live hand layers remain independent.  This deliberately gives
     * up the experimental dedicated transparent face until a teardown-safe
     * future-view route exists. */
    bool legacyClockRedirectRestored =
        themer_configure_apple_signed_redirect(
        dynamicRedirectRegistry,
        "clock-safe-generic-redirect",
        "SBHClockApplicationIconImageView", "iconForImage",
        "SBIconImageView", "iconForImage", "@16@0:8",
        "cnd_sbr_clock_icon_for_image_original_imp",
        installSafeSpringBoardClockRedirect,
        &legacyClockRedirectChanged);

    /* Spotlight does not need a live Clock renderer. Redirect the model's
     * view-class factory before any result row exists, so future rows are
     * ordinary SBIconImageView instances backed by the persistently themed
     * com.apple.mobiletimer response. The exact VM trace proves both methods
     * have the same #24@0:8@16 ABI. SpringBoard leaves this redirect restored
     * and continues through the live clock.base source below. */
    bool staticClockViewClassOK =
        themer_configure_apple_signed_redirect(
        dynamicRedirectRegistry,
        "spotlight-clock-static-view-class",
        "SBHClockApplicationIcon", "iconImageViewClassForLocation:",
        "SBIcon", "iconImageViewClassForLocation:", "#24@0:8@16",
        "cnd_sbr_spotlight_clock_view_class_original_imp",
        useStaticClockPresentation && installClock,
        &staticClockViewClassChanged);

    NSDictionary<NSString *, id> *clockBackgroundResult = nil;
    printf("[SBR_DYNAMIC_STAGE] redirects clock=%d unsafe-retired=%d "
           "static-clock=%d "
           "calendar-image=%d calendar-layer=%d\n",
           legacyClockRedirectRestored, unsafeClockRouteRetired,
           staticClockViewClassOK,
           legacyCalendarImageRedirectRestored,
           legacyCalendarLayerRedirectRestored);

    uint64_t themedImages[5] = {0};
    bool decodedComponents = completeClockComponents;
    if (completeClockComponents) {
        for (NSUInteger index = 0; index < 5; index++) {
            themedImages[index] = themer_build_remote_uiimage_with_scale(
                componentData[index], componentKeys[index].UTF8String, 2.0);
            decodedComponents = decodedComponents &&
                r_is_objc_ptr(themedImages[index]);
        }
    }

    NSUInteger imageSetsSeen = 0;
    NSUInteger imageSetsChanged = 0;
    bool imageSetsOK = true;
    printf("[SBR_DYNAMIC_STAGE] clock-hands-begin requested=%d "
           "decoded=%d\n", installClock, decodedComponents);
    uint64_t clockViewClass = r_class("SBHClockApplicationIconImageView");
    uint64_t metricsAddress = 0;
    if (r_is_objc_ptr(clockViewClass) &&
        (decodedComponents || !installClock ||
         useStaticClockPresentation)) {
        metricsAddress = r_dlsym_call(
            R_TIMEOUT, "calloc", 1,
            sizeof(ThemerClockApplicationIconImageMetrics),
            0, 0, 0, 0, 0, 0);
        ThemerClockIconImageInfo info = {
            .size = CGSizeMake(68.0, 68.0),
            .scale = UIScreen.mainScreen.scale,
            .continuousCornerRadius = 17.68,
        };
        if (metricsAddress) {
            (void)r_msg2_raw(
                clockViewClass, "getMetrics:forIconImageInfo:",
                &metricsAddress, sizeof(metricsAddress),
                &info, sizeof(info), NULL, 0, NULL, 0);
        }
        uint64_t appearanceClass = r_class("SBHIconImageAppearance");
        static const char *const appearanceSelectors[] = {
            "defaultAppearance", "lightAppearance", "darkAppearance",
            "clearLightAppearance", "clearDarkAppearance",
            "tintableAppearance",
        };
        for (NSUInteger index = 0;
             metricsAddress && r_is_objc_ptr(appearanceClass) &&
             index < sizeof(appearanceSelectors) /
                         sizeof(appearanceSelectors[0]);
             index++) {
            uint64_t appearance = r_msg2(
                appearanceClass, appearanceSelectors[index], 0, 0, 0, 0);
            uint64_t imageSet = r_is_objc_ptr(appearance)
                ? themer_clock_image_set_for_appearance(
                    clockViewClass, metricsAddress, appearance)
                : 0;
            if (!r_is_objc_ptr(imageSet)) {
                imageSetsOK = false;
                continue;
            }
            imageSetsSeen++;
            bool changed = false;
            bool configured = themer_clock_backup_or_apply_image_set(
                clockImageSetRegistry,
                imageSet, themedImages,
                installClockHands && decodedComponents,
                &changed);
            imageSetsOK = imageSetsOK && configured;
            if (configured && changed) imageSetsChanged++;
        }
    } else if (completeClockComponents) {
        imageSetsOK = false;
    }
    if (metricsAddress && remote_call_current_success()) {
        r_free(metricsAddress);
    }
    for (NSUInteger index = 0; index < 5; index++) {
        if (r_is_objc_ptr(themedImages[index]) &&
            remote_call_current_success()) {
            r_msg2(themedImages[index], "release", 0, 0, 0, 0);
        }
    }

    bool componentWorkOK = useStaticClockPresentation
        ? imageSetsOK
        : (!installClock
            ? imageSetsOK
            : (completeClockComponents && decodedComponents &&
               imageSetsSeen > 0 && imageSetsOK));
    printf("[SBR_DYNAMIC_STAGE] clock-hands-end sets=%lu changed=%lu "
           "ok=%d transport=%d\n",
           (unsigned long)imageSetsSeen,
           (unsigned long)imageSetsChanged,
           componentWorkOK, remote_call_current_success());
    /* The malformed block-backed route is never installed.  SpringBoard uses
     * the safe generic Apple IMP plus the already-configured live hand sets;
     * Spotlight retains its ordinary static icon-view class route. */
    if (!unsafeClockRouteRetired || !legacyClockRedirectRestored ||
        !staticClockViewClassOK) {
        clockBackgroundResult = @{
            @"ok": @NO,
            @"stage": !unsafeClockRouteRetired
                ? @"clock-unsafe-route-retirement"
                : (!legacyClockRedirectRestored
                    ? @"clock-safe-generic-route"
                    : @"spotlight-clock-static-view-class"),
            @"message": !unsafeClockRouteRetired
                ? @"The unsafe block-backed Clock route could not be retired."
                : (!legacyClockRedirectRestored
                    ? @"The safe Apple-signed Clock fallback did not verify."
                    : @"Spotlight could not select the generic static Clock image-view class with exact ABI verification."),
        };
    } else if (useStaticClockPresentation) {
        NSDictionary<NSString *, id> *liveSourceRestore =
            themer_configure_clock_base_source(nil, false);
        bool liveSourceRestored =
            [liveSourceRestore[@"ok"] boolValue];
        bool migratedLiveSourceState =
            [liveSourceRestore[@"stateCount"] unsignedLongLongValue] > 0;
        bool staticReady = liveSourceRestored &&
            staticClockViewClassOK && remote_call_current_success();
        clockBackgroundResult = @{
            @"ok": @(staticReady),
            @"stage": staticReady
                ? (installClock ? @"spotlight-static-clock-ready" :
                   @"spotlight-static-clock-restored")
                : @"spotlight-static-clock-restore",
            @"message": staticReady
                ? (installClock
                    ? @"Future Spotlight Clock rows will use the ordinary persistent themed icon through a generic SBIconImageView; no visible clock.base leaf is required."
                    : @"Spotlight's Clock view-class factory and any prior live clock.base bridge are restored.")
                : @"Spotlight's prior live Clock state could not be cleared before selecting the static Clock route.",
            @"mode": installClock
                ? @"spotlight-static-bundle-icon" : @"stock",
            @"replacementSource": @"com.apple.mobiletimer/persistent-descriptor-matrix",
            @"viewClassFactory": @"SBIcon.iconImageViewClassForLocation:",
            @"viewClassFactoryABI": @"#24@0:8@16",
            @"viewClassRedirectInstalled": @(installClock),
            @"requiresVisibleLeaf": @NO,
            @"existingRowsRequireReconstruction": @(installClock),
            @"liveSourceRestore": liveSourceRestore ?: @{},
            @"unsafeRouteRetirement": unsafeClockRouteRetirement ?: @{},
            @"ordinaryClockBundleDescriptorsPreserved": @YES,
            @"transitionDescriptorsPreserved": @YES,
            @"viewPaintUsed": @NO,
            @"viewScanUsed": @(migratedLiveSourceState),
            @"viewScanScope": migratedLiveSourceState
                ? @"prior-live-clock-recovery-only"
                : @"none-for-static-install",
        };
    } else if (installClock && !installClockFace) {
        clockBackgroundResult = @{
            @"ok": @NO,
            @"stage": @"clock-base-input-missing",
            @"message": @"Clock is themed, but its separately staged transparent clock.base face is missing; the existing Clock source was left unchanged.",
        };
    } else if (!installClock) {
        NSDictionary<NSString *, id> *legacySourceRestore =
            themer_configure_clock_base_source(nil, false);
        bool restored = [legacySourceRestore[@"ok"] boolValue];
        clockBackgroundResult = @{
            @"ok": @(restored),
            @"stage": restored ? @"clock-safe-route-restored" :
                @"clock-safe-route-restore",
            @"message": restored
                ? @"Clock presentation is restored without retaining the unsafe block-backed route."
                : @"The prior Clock source state could not be restored.",
            @"legacySourceRestore": legacySourceRestore ?: @{},
            @"unsafeRouteRetirement": unsafeClockRouteRetirement ?: @{},
            @"viewScanUsed": @NO,
            @"viewPaintUsed": @NO,
        };
    } else {
        printf("[SBR_DYNAMIC_STAGE] clock-face-begin\n");
        NSDictionary<NSString *, id> *legacySourceRestore =
            themer_configure_clock_base_source(nil, false);
        if (![legacySourceRestore[@"ok"] boolValue]) {
            clockBackgroundResult = @{
                @"ok": @NO,
                @"stage": @"clock-legacy-source-restore",
                @"message": @"The prior per-view Clock source bridge could not be retired before installing the dedicated route.",
                @"legacySourceRestore": legacySourceRestore ?: @{},
                @"viewScanUsed": @NO,
            };
        } else {
            clockBackgroundResult = @{
                @"ok": @YES,
                @"stage": @"clock-safe-generic-route-ready",
                @"message": @"SpringBoard uses the safe Apple-signed generic Clock background route with the themed live hand sets; the unsafe dedicated block route is disabled.",
                @"mode": @"springboard-safe-generic-bundle-icon",
                @"transparentDedicatedFaceInstalled": @NO,
                @"liveHandsPreserved": @YES,
                @"futureViewConstructionCovered": @YES,
                @"legacySourceRestore": legacySourceRestore ?: @{},
                @"unsafeRouteRetirement": unsafeClockRouteRetirement ?: @{},
                @"viewScanUsed": @NO,
                @"viewPaintUsed": @NO,
            };
        }
    }
    bool clockBackgroundOK =
        [clockBackgroundResult[@"ok"] boolValue];
    printf("[SBR_DYNAMIC_STAGE] clock-face-end ok=%d stage=%s\n",
           clockBackgroundOK,
           [clockBackgroundResult[@"stage"] UTF8String] ?: "-");

    NSUInteger targetedReloads =
        [calendarSourceResult[@"reloadPasses"] unsignedIntegerValue];
    bool ok = unsafeClockRouteRetired && legacyClockRedirectRestored &&
        staticClockViewClassOK &&
        legacyCalendarImageRedirectRestored &&
        legacyCalendarLayerRedirectRestored &&
        clockBackgroundOK && calendarSourceOK && componentWorkOK &&
        remote_call_current_success();
    printf("[SBR_DYNAMIC_ICONS] ok=%d clock=%d calendar=%d "
           "clock-background=%d clock-stage=%s calendar-source=%d "
           "components=%lu/5 decoded=%d "
           "image-sets=%lu changed=%lu reloads=%lu "
           "clock-mode=%s clock-presentation=%d "
           "static-view-class=%d/%d "
           "legacy-clock-redirect-restored=%d/%d "
           "legacy-calendar-redirects-restored=%d/%d:%d/%d "
           "dedicated-clock-route=0 "
           "bounded-clock-view-scan=%d\n",
           ok, installClock, installCalendar, clockBackgroundOK,
           [clockBackgroundResult[@"stage"] UTF8String] ?: "-",
           calendarSourceOK,
           (unsigned long)componentData.count, decodedComponents,
           (unsigned long)imageSetsSeen,
           (unsigned long)imageSetsChanged,
           (unsigned long)targetedReloads,
           useStaticClockPresentation ? "spotlight-static" :
               "springboard-live",
           clockBackgroundOK,
           staticClockViewClassOK, staticClockViewClassChanged,
           legacyClockRedirectRestored,
           legacyClockRedirectChanged,
           legacyCalendarImageRedirectRestored,
           legacyCalendarImageRedirectChanged,
           legacyCalendarLayerRedirectRestored,
           legacyCalendarLayerRedirectChanged,
           !useStaticClockPresentation);
    return @{
        @"ok": @(ok),
        @"stage": ok ? @"dynamic-icon-sources-ready" :
            @"dynamic-icon-source-configuration",
        @"message": ok
            ? (useStaticClockPresentation
                ? @"Spotlight will construct static Clock rows through the ordinary persistent themed icon, while Calendar's exact provider now resolves the persistent themed descriptor matrix."
                : @"SpringBoard's safe Apple-signed Clock background route and live hand sets are ready, and Calendar resolves its exact preparedISIcon provider boundary.")
            : @"The requested Clock presentation or exact Calendar provider source did not fully verify. One-shot face painting remains disabled.",
        @"clockPresentationMode": useStaticClockPresentation
            ? @"spotlight-static" : @"springboard-live",
        @"clockRequested": @(installClock),
        @"calendarRequested": @(installCalendar),
        @"clockComponentCount": @(componentData.count),
        @"clockComponentsComplete": @(!installClock ||
            useStaticClockPresentation || completeClockComponents),
        @"clockComponentsDecoded": @(decodedComponents),
        @"clockBackgroundVerified": @(clockBackgroundOK),
        @"clockBackground": clockBackgroundResult ?: @{},
        @"calendarProviderSourceVerified": @(calendarSourceOK),
        @"calendarProviderSource": calendarSourceResult ?: @{},
        @"clockImageSetsSeen": @(imageSetsSeen),
        @"clockImageSetsChanged": @(imageSetsChanged),
        @"targetedReloadCount": @(targetedReloads),
        @"targetedReloadVerified": @(calendarSourceOK),
        @"clockBaseSourceVerified": @NO,
        @"clockSafeGenericRouteVerified": @(!useStaticClockPresentation &&
            clockBackgroundOK),
        @"spotlightStaticClockVerified": @(useStaticClockPresentation &&
            clockBackgroundOK),
        @"spotlightStaticClockViewClassVerified":
            @(staticClockViewClassOK),
        @"spotlightStaticClockViewClassChanged":
            @(staticClockViewClassChanged),
        @"legacyClockRedirectRestored":
            @(legacyClockRedirectRestored),
        @"unsafeClockRouteRetired": @(unsafeClockRouteRetired),
        @"legacyCalendarImageRedirectRestored":
            @(legacyCalendarImageRedirectRestored),
        @"legacyCalendarLayerRedirectRestored":
            @(legacyCalendarLayerRedirectRestored),
        @"boundedSourceMutation": @YES,
        @"viewScanUsed": @([clockBackgroundResult[@"viewScanUsed"]
            boolValue]),
        @"viewScanScope": clockBackgroundResult[@"viewScanScope"] ?:
            (useStaticClockPresentation
                ? @"none-for-static-install"
                : @"none-safe-apple-imp-route"),
    };
}

NSDictionary<NSString *, id> *
themer_set_static_dynamic_icon_overlays_in_session(
    NSDictionary<NSString *, NSData *> *imageDataByBundle,
    bool useStaticClockPresentation)
{
    if (!remote_call_current_success()) {
        return @{
            @"ok": @NO,
            @"stage": @"transport",
            @"message": @"The Clock/Calendar source operation has no healthy SpringBoard session.",
        };
    }
    return themer_configure_clock_calendar_sources_in_session(
        imageDataByBundle ?: @{}, useStaticClockPresentation);
}

static bool themer_clear_visible_override(uint64_t iconView)
{
    if (!r_is_objc_ptr(iconView) ||
        !r_responds_main(iconView, "setOverrideImage:")) {
        return false;
    }

    uint64_t cur = r_responds_main(iconView, "overrideImage")
        ? r_msg2_main(iconView, "overrideImage", 0, 0, 0, 0) : 0;
    if (!r_is_objc_ptr(cur)) return false;

    r_msg2_main(iconView, "setOverrideImage:", 0, 0, 0, 0);
    if (r_responds_main(iconView, "setOverrideIconImageAppearance:")) {
        r_msg2_main(iconView, "setOverrideIconImageAppearance:", 0, 0, 0, 0);
    }
    if (r_responds_main(iconView, "_updateIconImageViewAnimated:")) {
        r_msg2_main(iconView, "_updateIconImageViewAnimated:", 0, 0, 0, 0);
    } else if (r_responds_main(iconView,
                               "_updateAfterManualIconImageInfoChangeInvalidatingLayout:")) {
        r_msg2_main(iconView,
                    "_updateAfterManualIconImageInfoChangeInvalidatingLayout:",
                    0, 0, 0, 0);
    }
    return true;
}

static bool themer_should_trace_icon_bundle(const char *bundle)
{
    (void)bundle;
    return false;
}

static bool themer_iconview_image_state(uint64_t iconView,
                                        uint64_t image,
                                        uint64_t *iivOut,
                                        uint64_t *iconOut,
                                        uint64_t *overrideOut,
                                        uint64_t *displayedOut)
{
    if (iivOut) *iivOut = 0;
    if (iconOut) *iconOut = 0;
    if (overrideOut) *overrideOut = 0;
    if (displayedOut) *displayedOut = 0;
    if (!r_is_objc_ptr(iconView) || !r_is_objc_ptr(image)) return false;

    uint64_t iiv = r_ivar_value(iconView, "_iconImageView");
    if (!r_is_objc_ptr(iiv) && r_responds_main(iconView, "_iconImageView")) {
        iiv = r_msg2_main(iconView, "_iconImageView", 0, 0, 0, 0);
    }
    uint64_t icon = r_responds_main(iconView, "icon")
        ? r_msg2_main(iconView, "icon", 0, 0, 0, 0) : 0;
    uint64_t overrideRead = r_responds_main(iconView, "overrideImage")
        ? r_msg2_main(iconView, "overrideImage", 0, 0, 0, 0) : 0;
    uint64_t displayedRead = (r_is_objc_ptr(iiv) &&
                              r_responds_main(iiv, "displayedImage"))
        ? r_msg2_main(iiv, "displayedImage", 0, 0, 0, 0) : 0;

    if (iivOut) *iivOut = iiv;
    if (iconOut) *iconOut = icon;
    if (overrideOut) *overrideOut = overrideRead;
    if (displayedOut) *displayedOut = displayedRead;
    return overrideRead == image || displayedRead == image;
}

static bool themer_log_paint_verification(const char *phase,
                                          const char *bundle,
                                          uint64_t iconView,
                                          uint64_t image,
                                          int rung,
                                          bool dynamicOverlay)
{
    uint64_t iiv = 0;
    uint64_t icon = 0;
    uint64_t overrideRead = 0;
    uint64_t displayedRead = 0;
    bool painted = themer_iconview_image_state(iconView, image, &iiv, &icon,
                                               &overrideRead, &displayedRead);
    if (painted || dynamicOverlay) return true;
    if (gThemerPaintFailLogBudget <= 0) return false;

    uint64_t superv = r_responds_main(iconView, "superview")
        ? r_msg2_main(iconView, "superview", 0, 0, 0, 0) : 0;
    uint64_t window = r_responds_main(iconView, "window")
        ? r_msg2_main(iconView, "window", 0, 0, 0, 0) : 0;
    bool hidden = r_responds_main(iconView, "isHidden")
        ? (r_msg2_main(iconView, "isHidden", 0, 0, 0, 0) & 0xff) != 0
        : false;
    bool borrowed = r_responds_main(iconView, "isIconImageViewBorrowed")
        ? (r_msg2_main(iconView, "isIconImageViewBorrowed", 0, 0, 0, 0) & 0xff) != 0
        : false;
    ThemerEntry *entry = themer_lookup_entry(bundle);

    char ivCls[96] = {0};
    char iivCls[96] = {0};
    char iconCls[96] = {0};
    char superCls[96] = {0};
    char windowCls[96] = {0};
    themer_read_class_name(iconView, ivCls, sizeof(ivCls));
    themer_read_class_name(iiv, iivCls, sizeof(iivCls));
    themer_read_class_name(icon, iconCls, sizeof(iconCls));
    themer_read_class_name(superv, superCls, sizeof(superCls));
    themer_read_class_name(window, windowCls, sizeof(windowCls));

    printf("[THEMER] paint verify fail phase=%s bundle=%s rung=%d "
           "iconView=0x%llx (%s) super=0x%llx (%s) window=0x%llx (%s) "
           "iiv=0x%llx (%s) icon=0x%llx (%s) want=0x%llx "
           "override=0x%llx displayed=0x%llx modelGrafted=%d "
           "iconServices=%d borrowed=%d hidden=%d\n",
           phase ?: "?",
           bundle ?: "?",
           rung,
           (unsigned long long)iconView, ivCls,
           (unsigned long long)superv, superCls,
           (unsigned long long)window, windowCls,
           (unsigned long long)iiv, iivCls,
           (unsigned long long)icon, iconCls,
           (unsigned long long)image,
           (unsigned long long)overrideRead,
           (unsigned long long)displayedRead,
           entry && entry->modelGrafted,
           entry && entry->iconServicesSeeded,
           borrowed,
           hidden);
    gThemerPaintFailLogBudget--;
    return false;
}

static void themer_log_iconview_render_state(const char *phase,
                                             const char *bundle,
                                             uint64_t iconView,
                                             uint64_t image,
                                             int rung)
{
    static int traceBudget = 32;
    if (traceBudget <= 0 || !themer_should_trace_icon_bundle(bundle)) return;
    if (!r_is_objc_ptr(iconView)) return;

    uint64_t iiv = r_ivar_value(iconView, "_iconImageView");
    if (!r_is_objc_ptr(iiv) && r_responds_main(iconView, "_iconImageView")) {
        iiv = r_msg2_main(iconView, "_iconImageView", 0, 0, 0, 0);
    }

    uint64_t icon = r_responds_main(iconView, "icon")
        ? r_msg2_main(iconView, "icon", 0, 0, 0, 0) : 0;
    uint64_t overrideRead = r_responds_main(iconView, "overrideImage")
        ? r_msg2_main(iconView, "overrideImage", 0, 0, 0, 0) : 0;
    uint64_t displayedRead = (r_is_objc_ptr(iiv) &&
                              r_responds_main(iiv, "displayedImage"))
        ? r_msg2_main(iiv, "displayedImage", 0, 0, 0, 0) : 0;

    bool shouldDisplay = (r_is_objc_ptr(iiv) &&
                          r_responds_main(iiv, "shouldDisplayImageLayer"))
        ? (r_msg2_main(iiv, "shouldDisplayImageLayer", 0, 0, 0, 0) & 0xff) != 0
        : true;
    bool square = (r_is_objc_ptr(iiv) &&
                   r_responds_main(iiv, "showsSquareCorners"))
        ? (r_msg2_main(iiv, "showsSquareCorners", 0, 0, 0, 0) & 0xff) != 0
        : false;
    bool borrowed = r_responds_main(iconView, "isIconImageViewBorrowed")
        ? (r_msg2_main(iconView, "isIconImageViewBorrowed", 0, 0, 0, 0) & 0xff) != 0
        : false;
    bool hidden = r_responds_main(iconView, "isHidden")
        ? (r_msg2_main(iconView, "isHidden", 0, 0, 0, 0) & 0xff) != 0
        : false;
    uint64_t superv = r_responds_main(iconView, "superview")
        ? r_msg2_main(iconView, "superview", 0, 0, 0, 0) : 0;
    uint64_t window = r_responds_main(iconView, "window")
        ? r_msg2_main(iconView, "window", 0, 0, 0, 0) : 0;

    char ivCls[96] = {0};
    char iivCls[96] = {0};
    char iconCls[96] = {0};
    char superCls[96] = {0};
    char windowCls[96] = {0};
    themer_read_class_name(iconView, ivCls, sizeof(ivCls));
    themer_read_class_name(iiv, iivCls, sizeof(iivCls));
    themer_read_class_name(icon, iconCls, sizeof(iconCls));
    themer_read_class_name(superv, superCls, sizeof(superCls));
    themer_read_class_name(window, windowCls, sizeof(windowCls));

    printf("[THEMER] trace %s bundle=%s rung=%d iconView=0x%llx (%s) "
           "super=0x%llx (%s) window=0x%llx (%s) iiv=0x%llx (%s) "
           "icon=0x%llx (%s) override=0x%llx displayed=0x%llx "
           "want=0x%llx overrideOK=%d displayedOK=%d imageLayer=%d square=%d "
           "borrowed=%d hidden=%d\n",
           phase ?: "?",
           bundle ?: "?",
           rung,
           (unsigned long long)iconView, ivCls,
           (unsigned long long)superv, superCls,
           (unsigned long long)window, windowCls,
           (unsigned long long)iiv, iivCls,
           (unsigned long long)icon, iconCls,
           (unsigned long long)overrideRead,
           (unsigned long long)displayedRead,
           (unsigned long long)image,
           overrideRead == image,
           displayedRead == image,
           shouldDisplay,
           square,
           borrowed,
           hidden);
    traceBudget--;
}

static bool themer_pin_static_dynamic_layer(uint64_t iconView,
                                            uint64_t image,
                                            const char *bundle)
{
    (void)iconView;
    (void)image;
    static int logged = 0;
    if (themer_is_static_dynamic_icon_bundle(bundle) && logged < 6) {
        printf("[THEMER] static dynamic pin disabled bundle=%s; using inspect-only build\n",
               bundle ?: "?");
        logged++;
    }
    return false;
}

static bool themer_pin_dynamic_overlay(uint64_t iconView, uint64_t image,
                                       const char *bundle)
{
    if (!r_is_objc_ptr(iconView) || !r_is_objc_ptr(image)) return false;

    if (themer_is_static_dynamic_icon_bundle(bundle)) {
        return themer_pin_static_dynamic_layer(iconView, image, bundle);
    }

    uint64_t iiv = themer_icon_image_view_for_iconview(iconView);
    if (!r_is_objc_ptr(iiv)) return false;
    bool viewLevel = themer_prefers_view_level_overlay(bundle);
    uint64_t overlayParent = iiv;
    if (viewLevel) {
        uint64_t iivSuperview = r_responds_main(iiv, "superview")
            ? r_msg2_main(iiv, "superview", 0, 0, 0, 0) : 0;
        overlayParent = r_is_objc_ptr(iivSuperview) ? iivSuperview : iconView;
    }

    uint64_t key = r_sel("cnd_themer_pinned_overlay");
    if (!key) return false;

    uint64_t overlay = r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                                    iconView, key, 0, 0, 0, 0, 0, 0);
    uint64_t imageViewOverlay = r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                                             iiv, key, 0, 0, 0, 0, 0, 0);
    if (!r_is_objc_ptr(overlay) && r_is_objc_ptr(imageViewOverlay)) {
        overlay = imageViewOverlay;
        r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                     iconView, key, overlay, 1, 0, 0, 0, 0);
    } else if (r_is_objc_ptr(overlay) && r_is_objc_ptr(imageViewOverlay) &&
               overlay != imageViewOverlay) {
        themer_clear_overlay_on_object(iiv, key);
    }

    bool created = false;
    if (!r_is_objc_ptr(overlay)) {
        uint64_t overlayCls = r_class("UIImageView");
        uint64_t alloc = r_is_objc_ptr(overlayCls)
            ? r_msg2(overlayCls, "alloc", 0, 0, 0, 0) : 0;
        overlay = r_is_objc_ptr(alloc)
            ? r_msg2_main(alloc, "initWithImage:", image, 0, 0, 0) : 0;
        if (!r_is_objc_ptr(overlay)) return false;

        r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                     iconView, key, overlay, 1, 0, 0, 0, 0);
        r_msg2(overlay, "release", 0, 0, 0, 0);
        created = true;
    } else if (r_responds_main(overlay, "setImage:")) {
        r_msg2_main(overlay, "setImage:", image, 0, 0, 0);
    }

    r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                 iiv, key, overlay, 1, 0, 0, 0, 0);
    if (r_responds_main(overlay, "removeFromSuperview")) {
        r_msg2_main(overlay, "removeFromSuperview", 0, 0, 0, 0);
    }
    if (r_responds_main(overlayParent, "addSubview:")) {
        r_msg2_main(overlayParent, "addSubview:", overlay, 0, 0, 0);
    }

    struct { double x, y, w, h; } bounds = {0.0, 0.0, 0.0, 0.0};
    if (!r_responds_main(iiv, "bounds") ||
        !r_msg2_main_struct_ret(iiv, "bounds",
            &bounds, sizeof(bounds),
            NULL, 0, NULL, 0, NULL, 0, NULL, 0) ||
        bounds.w <= 1.0 || bounds.h <= 1.0) {
        double width = themer_icon_width_for_view(iconView);
        bounds.w = width;
        bounds.h = width;
    }
    if (viewLevel &&
        r_responds_main(iiv, "frame")) {
        struct { double x, y, w, h; } frame = {0.0, 0.0, 0.0, 0.0};
        if (r_msg2_main_struct_ret(iiv, "frame",
            &frame, sizeof(frame),
            NULL, 0, NULL, 0, NULL, 0, NULL, 0) &&
            frame.w > 1.0 && frame.h > 1.0) {
            bounds.x = frame.x;
            bounds.y = frame.y;
            bounds.w = frame.w;
            bounds.h = frame.h;
        }
    }

    if (r_responds_main(overlay, "setFrame:")) {
        r_msg2_main_raw(overlay, "setFrame:",
            &bounds, sizeof(bounds),
            NULL, 0, NULL, 0, NULL, 0);
    }
    if (r_responds_main(overlay, "setBounds:")) {
        struct { double x, y, w, h; } localBounds = {0.0, 0.0, bounds.w, bounds.h};
        r_msg2_main_raw(overlay, "setBounds:",
            &localBounds, sizeof(localBounds),
            NULL, 0, NULL, 0, NULL, 0);
    }
    if (r_responds_main(overlay, "setAutoresizingMask:")) {
        r_msg2_main(overlay, "setAutoresizingMask:", 18, 0, 0, 0);
    }
    if (r_responds_main(overlay, "setUserInteractionEnabled:")) {
        r_msg2_main(overlay, "setUserInteractionEnabled:", 0, 0, 0, 0);
    }
    if (r_responds_main(overlay, "setContentMode:")) {
        r_msg2_main(overlay, "setContentMode:", 0, 0, 0, 0);
    }
    if (r_responds_main(overlay, "setHidden:")) {
        r_msg2_main(overlay, "setHidden:", 0, 0, 0, 0);
    }
    if (r_responds_main(overlayParent, "bringSubviewToFront:")) {
        r_msg2_main(overlayParent, "bringSubviewToFront:", overlay, 0, 0, 0);
    }

    uint64_t layer = r_responds_main(overlay, "layer")
        ? r_msg2_main(overlay, "layer", 0, 0, 0, 0) : 0;
    if (r_is_objc_ptr(layer)) {
        double radius = bounds.w > 1.0 ? bounds.w * 0.225 : 15.0;
        if (r_responds_main(layer, "setCornerRadius:")) {
            r_msg2_main_raw(layer, "setCornerRadius:",
                &radius, sizeof(radius),
                NULL, 0, NULL, 0, NULL, 0);
        }
        if (r_responds_main(layer, "setMasksToBounds:")) {
            r_msg2_main(layer, "setMasksToBounds:", 1, 0, 0, 0);
        }
        if (themer_is_static_dynamic_icon_bundle(bundle) &&
            r_responds_main(layer, "setZPosition:")) {
            double z = 9999.0;
            r_msg2_main_raw(layer, "setZPosition:",
                &z, sizeof(z),
                NULL, 0, NULL, 0, NULL, 0);
        }
        if (kThemerStaticDynamicDiagnosticMarker &&
            themer_is_static_dynamic_icon_bundle(bundle)) {
            double border = 4.0;
            if (r_responds_main(layer, "setBorderWidth:")) {
                r_msg2_main_raw(layer, "setBorderWidth:",
                    &border, sizeof(border),
                    NULL, 0, NULL, 0, NULL, 0);
            }
            uint64_t colorCls = r_class("UIColor");
            uint64_t color = r_is_objc_ptr(colorCls)
                ? r_msg2_main(colorCls, "magentaColor", 0, 0, 0, 0) : 0;
            uint64_t cgColor = r_is_objc_ptr(color) && r_responds_main(color, "CGColor")
                ? r_msg2_main(color, "CGColor", 0, 0, 0, 0) : 0;
            if (cgColor && r_responds_main(layer, "setBorderColor:")) {
                r_msg2_main(layer, "setBorderColor:", cgColor, 0, 0, 0);
            }
        }
    }

    static bool logged = false;
    if (!logged) {
        logged = true;
        char iivCls[128] = {0};
        char parentCls[128] = {0};
        themer_read_class_name(iiv, iivCls, sizeof(iivCls));
        themer_read_class_name(overlayParent, parentCls, sizeof(parentCls));
        printf("[THEMER] dynamic overlay pinned bundle=%s iconView=0x%llx "
               "iiv=0x%llx (%s) parent=0x%llx (%s) overlay=0x%llx "
               "viewLevel=%d marker=%d created=%d\n",
               bundle ?: "?",
               (unsigned long long)iconView,
               (unsigned long long)iiv,
               iivCls,
               (unsigned long long)overlayParent,
               parentCls,
               (unsigned long long)overlay,
               viewLevel,
               kThemerStaticDynamicDiagnosticMarker &&
                   themer_is_static_dynamic_icon_bundle(bundle),
               created);
    }

    return true;
}

static uint64_t themer_make_datasource(uint64_t image, double width)
{
    if (!r_is_objc_ptr(image)) return 0;
    uint64_t dsCls = themer_ensure_datasource_class();
    if (!r_is_objc_ptr(dsCls)) return 0;

    uint64_t alloc = r_msg2(dsCls, "alloc", 0, 0, 0, 0);
    uint64_t ds = r_is_objc_ptr(alloc)
        ? r_msg2_main(alloc, "init", 0, 0, 0, 0) : 0;
    if (!r_is_objc_ptr(ds)) return 0;

    uint64_t layerCls = r_class("CALayer");
    uint64_t layerAlloc = r_is_objc_ptr(layerCls)
        ? r_msg2(layerCls, "alloc", 0, 0, 0, 0) : 0;
    uint64_t layer = r_is_objc_ptr(layerAlloc)
        ? r_msg2_main(layerAlloc, "init", 0, 0, 0, 0) : 0;
    if (!r_is_objc_ptr(layer)) {
        r_msg2(ds, "release", 0, 0, 0, 0);
        return 0;
    }

    uint64_t cgImage = r_responds_main(image, "CGImage")
        ? r_msg2_main(image, "CGImage", 0, 0, 0, 0) : 0;
    if (cgImage && r_responds_main(layer, "setContents:")) {
        r_msg2_main(layer, "setContents:", cgImage, 0, 0, 0);
    }

    struct { double x, y, w, h; } bounds = {0.0, 0.0, width, width};
    if (r_responds_main(layer, "setBounds:")) {
        r_msg2_main_raw(layer, "setBounds:",
            &bounds, sizeof(bounds),
            NULL, 0, NULL, 0, NULL, 0);
    }

    double radius = width * 0.225;
    if (r_responds_main(layer, "setCornerRadius:")) {
        r_msg2_main_raw(layer, "setCornerRadius:",
            &radius, sizeof(radius),
            NULL, 0, NULL, 0, NULL, 0);
    }
    if (r_responds_main(layer, "setMasksToBounds:")) {
        r_msg2_main(layer, "setMasksToBounds:", 1, 0, 0, 0);
    }

    double scale = 3.0;
    uint64_t UIScreen = r_class("UIScreen");
    uint64_t screen = r_is_objc_ptr(UIScreen)
        ? r_msg2(UIScreen, "mainScreen", 0, 0, 0, 0) : 0;
    if (r_is_objc_ptr(screen) && r_responds_main(screen, "scale")) {
        uint64_t bits = r_msg2_main(screen, "scale", 0, 0, 0, 0);
        memcpy(&scale, &bits, sizeof(scale));
    }
    if (r_responds_main(layer, "setContentsScale:")) {
        r_msg2_main_raw(layer, "setContentsScale:",
            &scale, sizeof(scale),
            NULL, 0, NULL, 0, NULL, 0);
    }

    uint64_t imageSel = r_sel("icon:imageWithInfo:traitCollection:options:");
    if (imageSel) {
        r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                     ds, imageSel, image, 1, 0, 0, 0, 0);
    }
    uint64_t layerSel = r_sel("icon:layerWithInfo:traitCollection:options:");
    if (layerSel) {
        r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                     ds, layerSel, layer, 1, 0, 0, 0, 0);
    }
    r_msg2(layer, "release", 0, 0, 0, 0);
    return ds;
}

static uint64_t themer_make_icon_layer(uint64_t image, double width)
{
    if (!r_is_objc_ptr(image)) return 0;

    uint64_t layerCls = r_class("CALayer");
    uint64_t layerAlloc = r_is_objc_ptr(layerCls)
        ? r_msg2(layerCls, "alloc", 0, 0, 0, 0) : 0;
    uint64_t layer = r_is_objc_ptr(layerAlloc)
        ? r_msg2_main(layerAlloc, "init", 0, 0, 0, 0) : 0;
    if (!r_is_objc_ptr(layer)) return 0;

    uint64_t cgImage = r_responds_main(image, "CGImage")
        ? r_msg2_main(image, "CGImage", 0, 0, 0, 0) : 0;
    if (cgImage && r_responds_main(layer, "setContents:")) {
        r_msg2_main(layer, "setContents:", cgImage, 0, 0, 0);
    }

    struct { double x, y, w, h; } bounds = {0.0, 0.0, width, width};
    if (r_responds_main(layer, "setBounds:")) {
        r_msg2_main_raw(layer, "setBounds:",
            &bounds, sizeof(bounds),
            NULL, 0, NULL, 0, NULL, 0);
    }

    double radius = width * 0.225;
    if (r_responds_main(layer, "setCornerRadius:")) {
        r_msg2_main_raw(layer, "setCornerRadius:",
            &radius, sizeof(radius),
            NULL, 0, NULL, 0, NULL, 0);
    }
    if (r_responds_main(layer, "setMasksToBounds:")) {
        r_msg2_main(layer, "setMasksToBounds:", 1, 0, 0, 0);
    }

    double scale = 3.0;
    uint64_t UIScreen = r_class("UIScreen");
    uint64_t screen = r_is_objc_ptr(UIScreen)
        ? r_msg2(UIScreen, "mainScreen", 0, 0, 0, 0) : 0;
    if (r_is_objc_ptr(screen) && r_responds_main(screen, "scale")) {
        uint64_t bits = r_msg2_main(screen, "scale", 0, 0, 0, 0);
        memcpy(&scale, &bits, sizeof(scale));
    }
    if (r_responds_main(layer, "setContentsScale:")) {
        r_msg2_main_raw(layer, "setContentsScale:",
            &scale, sizeof(scale),
            NULL, 0, NULL, 0, NULL, 0);
    }

    return layer;
}

static bool themer_ensure_associated_override_from_base(
    uint64_t subclass,
    uint64_t baseClass,
    const char *selector,
    uint64_t implementation,
    bool *presentOut)
{
    if (presentOut) *presentOut = false;
    if (!r_is_objc_ptr(subclass) || !r_is_objc_ptr(baseClass) ||
        !selector || !selector[0] || !implementation) {
        return false;
    }

    uint64_t sel = r_sel(selector);
    uint64_t method = sel
        ? r_dlsym_call(R_TIMEOUT, "class_getInstanceMethod",
                       baseClass, sel, 0, 0, 0, 0, 0, 0)
        : 0;
    if (!method) return true;
    if (presentOut) *presentOut = true;

    uint64_t typeCString = r_dlsym_call(R_TIMEOUT,
                                        "method_getTypeEncoding",
                                        method, 0, 0, 0, 0, 0, 0, 0);
    char types[256] = {0};
    if (!themer_read_remote_cstring(typeCString, types, sizeof(types))) {
        return false;
    }
    return themer_ensure_method(subclass, selector, implementation, types);
}

static uint64_t themer_ensure_spotlight_provider_class(
    uint64_t currentClass,
    int *imageSelectorCountOut,
    int *layerSelectorCountOut)
{
    if (imageSelectorCountOut) *imageSelectorCountOut = 0;
    if (layerSelectorCountOut) *layerSelectorCountOut = 0;
    if (!r_is_objc_ptr(currentClass)) return 0;

    static const char *prefix = "CNDSpotlightProviderThemedV1_";
    uint64_t baseClass = currentClass;
    char baseName[160] = {0};
    themer_read_class_object_name(baseClass, baseName, sizeof(baseName));
    while (strncmp(baseName, prefix, strlen(prefix)) == 0) {
        uint64_t superClass = r_dlsym_call(R_TIMEOUT,
                                           "class_getSuperclass",
                                           baseClass, 0, 0, 0, 0, 0, 0, 0);
        if (!r_is_objc_ptr(superClass) || superClass == baseClass) break;
        baseClass = superClass;
        themer_read_class_object_name(baseClass, baseName, sizeof(baseName));
    }
    if (!baseName[0]) return 0;

    char subclassName[224] = {0};
    snprintf(subclassName, sizeof(subclassName), "%s%s", prefix, baseName);
    uint64_t subclass = themer_lookup_class(subclassName);
    bool newlyAllocated = false;
    if (!r_is_objc_ptr(subclass)) {
        uint64_t remoteName = r_alloc_str(subclassName);
        if (!remoteName) return 0;
        subclass = r_dlsym_call(R_TIMEOUT, "objc_allocateClassPair",
                                baseClass, remoteName,
                                0, 0, 0, 0, 0, 0);
        r_free(remoteName);
        if (!r_is_objc_ptr(subclass)) return 0;
        newlyAllocated = true;
    }

    uint64_t getAssociatedObject =
        themer_remote_symbol_addr("objc_getAssociatedObject");
    if (!getAssociatedObject) return 0;

    static const char *imageSelectors[] = {
        "icon:imageWithInfo:",
        "icon:unmaskedImageWithInfo:",
        "icon:imageWithInfo:traitCollection:options:",
    };
    static const char *layerSelectors[] = {
        "icon:layerWithInfo:traitCollection:options:",
    };

    bool ok = true;
    int imageSelectorCount = 0;
    int layerSelectorCount = 0;
    for (size_t i = 0;
         i < sizeof(imageSelectors) / sizeof(imageSelectors[0]);
         i++) {
        bool present = false;
        bool methodOK = themer_ensure_associated_override_from_base(
            subclass, baseClass, imageSelectors[i], getAssociatedObject,
            &present);
        ok = ok && methodOK;
        if (present) imageSelectorCount++;
    }
    for (size_t i = 0;
         i < sizeof(layerSelectors) / sizeof(layerSelectors[0]);
         i++) {
        bool present = false;
        bool methodOK = themer_ensure_associated_override_from_base(
            subclass, baseClass, layerSelectors[i], getAssociatedObject,
            &present);
        ok = ok && methodOK;
        if (present) layerSelectorCount++;
    }

    if (newlyAllocated) {
        r_dlsym_call(R_TIMEOUT, "objc_registerClassPair",
                     subclass, 0, 0, 0, 0, 0, 0, 0);
    }
    if (!ok || imageSelectorCount <= 0) {
        printf("[SPOTLIGHT_PRELOAD] provider-class incomplete class=%s "
               "images=%d layers=%d ok=%d\n",
               subclassName, imageSelectorCount, layerSelectorCount, ok);
        return 0;
    }
    if (imageSelectorCountOut) *imageSelectorCountOut = imageSelectorCount;
    if (layerSelectorCountOut) *layerSelectorCountOut = layerSelectorCount;
    return subclass;
}

static bool themer_graft_spotlight_provider(uint64_t provider,
                                            uint64_t image,
                                            double pointWidth,
                                            bool *changedOut,
                                            int *imageMatchesOut,
                                            int *layerMatchesOut)
{
    if (changedOut) *changedOut = false;
    if (imageMatchesOut) *imageMatchesOut = 0;
    if (layerMatchesOut) *layerMatchesOut = 0;
    if (!r_is_objc_ptr(provider) || !r_is_objc_ptr(image)) return false;

    uint64_t currentClass = r_dlsym_call(R_TIMEOUT, "object_getClass",
                                         provider, 0, 0, 0, 0, 0, 0, 0);
    int imageSelectorCount = 0;
    int layerSelectorCount = 0;
    uint64_t themedClass = themer_ensure_spotlight_provider_class(
        currentClass, &imageSelectorCount, &layerSelectorCount);
    if (!r_is_objc_ptr(themedClass)) return false;

    static const char *imageSelectors[] = {
        "icon:imageWithInfo:",
        "icon:unmaskedImageWithInfo:",
        "icon:imageWithInfo:traitCollection:options:",
    };
    static const char *layerSelectors[] = {
        "icon:layerWithInfo:traitCollection:options:",
    };

    uint64_t layer = 0;
    if (layerSelectorCount > 0) {
        layer = themer_make_icon_layer(image, pointWidth);
        if (!r_is_objc_ptr(layer)) return false;
    }

    for (size_t i = 0;
         i < sizeof(imageSelectors) / sizeof(imageSelectors[0]);
         i++) {
        if (!r_responds_main(provider, imageSelectors[i])) continue;
        uint64_t sel = r_sel(imageSelectors[i]);
        if (sel) {
            r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                         provider, sel, image, 1, 0, 0, 0, 0);
        }
    }
    for (size_t i = 0;
         i < sizeof(layerSelectors) / sizeof(layerSelectors[0]);
         i++) {
        if (!r_responds_main(provider, layerSelectors[i])) continue;
        uint64_t sel = r_sel(layerSelectors[i]);
        if (sel && r_is_objc_ptr(layer)) {
            r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                         provider, sel, layer, 1, 0, 0, 0, 0);
        }
    }

    if (themedClass != currentClass) {
        r_dlsym_call(R_TIMEOUT, "object_setClass",
                     provider, themedClass, 0, 0, 0, 0, 0, 0);
        if (changedOut) *changedOut = true;
    }

    int imageMatches = 0;
    int layerMatches = 0;
    for (size_t i = 0;
         i < sizeof(imageSelectors) / sizeof(imageSelectors[0]);
         i++) {
        if (!r_responds_main(provider, imageSelectors[i])) continue;
        uint64_t sel = r_sel(imageSelectors[i]);
        uint64_t associated = sel
            ? r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                           provider, sel, 0, 0, 0, 0, 0, 0)
            : 0;
        if (associated == image) imageMatches++;
    }
    for (size_t i = 0;
         i < sizeof(layerSelectors) / sizeof(layerSelectors[0]);
         i++) {
        if (!r_responds_main(provider, layerSelectors[i])) continue;
        uint64_t sel = r_sel(layerSelectors[i]);
        uint64_t associated = sel
            ? r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                           provider, sel, 0, 0, 0, 0, 0, 0)
            : 0;
        if (associated == layer) layerMatches++;
    }
    uint64_t finalClass = r_dlsym_call(R_TIMEOUT, "object_getClass",
                                       provider, 0, 0, 0, 0, 0, 0, 0);
    if (r_is_objc_ptr(layer)) r_msg2(layer, "release", 0, 0, 0, 0);

    if (imageMatchesOut) *imageMatchesOut = imageMatches;
    if (layerMatchesOut) *layerMatchesOut = layerMatches;
    return finalClass == themedClass &&
           imageMatches == imageSelectorCount &&
           layerMatches == layerSelectorCount;
}

static uint64_t themer_copy_icon_label(uint64_t icon)
{
    if (!r_is_objc_ptr(icon)) return 0;

    uint64_t label = 0;
    if (r_responds_main(icon, "displayNameForLocation:")) {
        label = r_msg2_main(icon, "displayNameForLocation:", 0, 0, 0, 0);
    }
    if (!r_is_objc_ptr(label) && r_responds_main(icon, "displayName")) {
        label = r_msg2_main(icon, "displayName", 0, 0, 0, 0);
    }
    if (!r_is_objc_ptr(label) && r_responds_main(icon, "application")) {
        uint64_t app = r_msg2_main(icon, "application", 0, 0, 0, 0);
        if (r_is_objc_ptr(app) && r_responds_main(app, "displayName")) {
            label = r_msg2_main(app, "displayName", 0, 0, 0, 0);
        }
    }
    if (!r_is_objc_ptr(label)) return 0;
    return r_msg2(label, "copy", 0, 0, 0, 0);
}

static void themer_seed_datasource_metadata(uint64_t ds, uint64_t icon)
{
    if (!r_is_objc_ptr(ds) || !r_is_objc_ptr(icon)) return;

    uint64_t label = themer_copy_icon_label(icon);
    if (!r_is_objc_ptr(label)) return;

    uint64_t displaySel = r_sel("icon:displayNameForLocation:");
    if (displaySel) {
        r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                     ds, displaySel, label, 1, 0, 0, 0, 0);
    }
    uint64_t axSel = r_sel("icon:accessibilityLabelForLocation:");
    if (axSel) {
        r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                     ds, axSel, label, 1, 0, 0, 0, 0);
    }
    r_msg2(label, "release", 0, 0, 0, 0);
}

static uint64_t themer_ensure_model_class_internal(uint64_t currentClass,
                                                   bool forceImagePath)
{
    if (!r_is_objc_ptr(currentClass)) return 0;

    uint64_t baseClass = currentClass;
    char clsName[160] = {0};
    themer_read_class_object_name(baseClass, clsName, sizeof(clsName));
    while (strncmp(clsName, "CNDThemed", sizeof("CNDThemed") - 1) == 0 ||
           strncmp(clsName, "CNDSpotlightThemed",
                   sizeof("CNDSpotlightThemed") - 1) == 0) {
        uint64_t superCls = r_dlsym_call(R_TIMEOUT, "class_getSuperclass",
                                         baseClass, 0, 0, 0, 0, 0, 0, 0);
        if (!r_is_objc_ptr(superCls) || superCls == baseClass) break;
        baseClass = superCls;
        themer_read_class_object_name(baseClass, clsName, sizeof(clsName));
    }
    if (!clsName[0]) return 0;

    char subName[192] = {0};
    snprintf(subName, sizeof(subName),
             forceImagePath ? "CNDSpotlightThemedV1_%s" : "CNDThemedV7_%s",
             clsName);

    uint64_t sub = themer_lookup_class(subName);
    uint64_t getAssocImp = themer_remote_symbol_addr("objc_getAssociatedObject");

    static const char *imageSels[] = {
        "makeIconImageWithInfo:traitCollection:context:options:",
        "iconImageWithInfo:traitCollection:context:options:",
    };
    static const char *imageSels3[] = {
        "iconImageWithInfo:traitCollection:options:",
    };
    static const char *imageInfoSels[] = {
        "iconImageWithInfo:",
    };
    static const char *calendarFalseSels[] = {
        "supportsIconLayers",
        "isIconImageHandledInternallyWithIconServices",
    };
    static const char *calendarNilLayerSels[] = {
        "makeIconLayerWithInfo:traitCollection:context:options:",
    };

    bool isCalendar = strstr(clsName, "Calendar") != NULL;
    bool disableLayerPath = forceImagePath || isCalendar;
    bool alreadyRegistered = r_is_objc_ptr(sub);
    bool ok = getAssocImp != 0;
    if (alreadyRegistered) {
        ok = ok &&
            themer_ensure_methods(sub, imageSels, 2, getAssocImp, "@@:@@@Q") &&
            themer_ensure_methods(sub, imageSels3, 1, getAssocImp, "@@:@@Q") &&
            themer_ensure_methods(sub, imageInfoSels, 1, getAssocImp,
                                  "@@:{SBIconImageInfo={CGSize=dd}dd}");
        if (disableLayerPath) {
            ok = ok &&
                themer_ensure_methods(sub, calendarFalseSels, 2, getAssocImp,
                                      "B16@0:8") &&
                themer_ensure_methods(sub, calendarNilLayerSels, 1, getAssocImp,
                                      "@72@0:8{SBIconImageInfo={CGSize=dd}dd}16@48@56Q64");
        }
        if (ok) return sub;
        printf("[THEMER] model graft: existing subclass incomplete %s getAssoc=0x%llx calendar=%d\n",
               subName,
               (unsigned long long)getAssocImp,
               isCalendar);
        return sub;
    }

    uint64_t name = r_alloc_str(subName);
    if (!name) return 0;
    sub = r_dlsym_call(R_TIMEOUT, "objc_allocateClassPair",
                       baseClass, name, 0, 0, 0, 0, 0, 0);
    r_free(name);
    if (!r_is_objc_ptr(sub)) return 0;

    ok = ok &&
        themer_ensure_methods(sub, imageSels, 2, getAssocImp, "@@:@@@Q") &&
        themer_ensure_methods(sub, imageSels3, 1, getAssocImp, "@@:@@Q") &&
        themer_ensure_methods(sub, imageInfoSels, 1, getAssocImp,
                              "@@:{SBIconImageInfo={CGSize=dd}dd}");
    if (disableLayerPath) {
        ok = ok &&
            themer_ensure_methods(sub, calendarFalseSels, 2, getAssocImp,
                                  "B16@0:8") &&
            themer_ensure_methods(sub, calendarNilLayerSels, 1, getAssocImp,
                                  "@72@0:8{SBIconImageInfo={CGSize=dd}dd}16@48@56Q64");
    }

    r_dlsym_call(R_TIMEOUT, "objc_registerClassPair",
                 sub, 0, 0, 0, 0, 0, 0, 0);

    if (!ok) {
        printf("[THEMER] model graft: subclass incomplete %s getAssoc=0x%llx\n",
               subName,
               (unsigned long long)getAssocImp);
        return 0;
    }
    if (isCalendar) {
        printf("[THEMER] model graft: calendar subclass configured %s layerPathDisabled=1\n",
               subName);
    }
    return sub;
}

static uint64_t themer_ensure_model_class(uint64_t currentClass)
{
    return themer_ensure_model_class_internal(currentClass, false);
}

static uint64_t themer_ensure_spotlight_model_class(uint64_t currentClass)
{
    return themer_ensure_model_class_internal(currentClass, true);
}

static bool themer_graft_icon_model_internal(uint64_t icon, uint64_t image,
                                             ThemerEntry *entry,
                                             uint64_t iconView,
                                             bool *changedOut,
                                             bool forceImagePath)
{
    if (changedOut) *changedOut = false;
    if (!r_is_objc_ptr(icon) || !r_is_objc_ptr(image) || !entry) return false;

    uint64_t currentClass = r_dlsym_call(R_TIMEOUT, "object_getClass",
                                         icon, 0, 0, 0, 0, 0, 0, 0);
    uint64_t themedClass = forceImagePath
        ? themer_ensure_spotlight_model_class(currentClass)
        : themer_ensure_model_class(currentClass);
    if (!r_is_objc_ptr(themedClass)) return false;

    static const char *imageSels[] = {
        "makeIconImageWithInfo:traitCollection:context:options:",
        "iconImageWithInfo:traitCollection:context:options:",
        "iconImageWithInfo:traitCollection:options:",
        "iconImageWithInfo:",
    };
    for (int i = 0; i < 4; i++) {
        uint64_t sel = r_sel(imageSels[i]);
        if (!sel) return false;
        r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                     icon, sel, image, 1, 0, 0, 0, 0);
    }
    (void)iconView;

    if (themedClass != currentClass) {
        r_dlsym_call(R_TIMEOUT, "object_setClass",
                     icon, themedClass, 0, 0, 0, 0, 0, 0);
        if (changedOut) *changedOut = true;
    }

    if (!gThemerModelProbeLogged) {
        gThemerModelProbeLogged = true;
        printf("[THEMER] model graft: icon=0x%llx class=0x%llx changed=%d imageOnly=1\n",
               (unsigned long long)icon,
               (unsigned long long)themedClass,
               changedOut ? *changedOut : false);
    }

    return true;
}

static bool themer_graft_icon_model(uint64_t icon, uint64_t image,
                                    ThemerEntry *entry, uint64_t iconView,
                                    bool *changedOut)
{
    return themer_graft_icon_model_internal(icon, image, entry, iconView,
                                            changedOut, false);
}

static bool themer_graft_spotlight_icon_model(uint64_t icon, uint64_t image,
                                              ThemerEntry *entry,
                                              uint64_t iconView,
                                              bool *changedOut)
{
    return themer_graft_icon_model_internal(icon, image, entry, iconView,
                                            changedOut, true);
}

bool themer_spotlight_monitor_repair_in_session(void)
{
    if (!gThemerSpotlightMonitor.armed ||
        remote_call_current_pid() != gThemerSpotlightMonitor.pid) {
        return false;
    }

    uint64_t owner = 0;
    uint64_t dataSource = 0;
    uint64_t iconModel = 0;
    uint64_t repository = 0;
    if (!themer_spotlight_current_graph(
            &owner, &dataSource, &iconModel, &repository) ||
        owner != gThemerSpotlightMonitor.owner ||
        dataSource != gThemerSpotlightMonitor.dataSource ||
        iconModel != gThemerSpotlightMonitor.iconModel ||
        repository != gThemerSpotlightMonitor.repository ||
        themer_spotlight_theme_repository() !=
            gThemerSpotlightMonitor.themeRepository) {
        return false;
    }

    ThemerSpotlightCarrierBinding current[THEMER_SPOTLIGHT_BINDING_CAP] = {{0}};
    int currentCount = themer_spotlight_collect_carrier_bindings(
        current, THEMER_SPOTLIGHT_BINDING_CAP, true);
    if (currentCount <= 0 || !remote_call_current_success()) return false;

    uint64_t icons[THEMER_SPOTLIGHT_MONITOR_ICON_CAP] = {0};
    uint64_t providers[THEMER_SPOTLIGHT_MONITOR_ICON_CAP] = {0};
    char bundles[THEMER_SPOTLIGHT_MONITOR_ICON_CAP][192] = {{0}};
    int iconCount = gThemerSpotlightMonitor.iconCount;
    for (int i = 0; i < iconCount; i++) {
        icons[i] = gThemerSpotlightMonitor.icons[i];
        providers[i] = gThemerSpotlightMonitor.providers[i];
        snprintf(bundles[i], sizeof(bundles[i]), "%s",
                 gThemerSpotlightMonitor.bundles[i]);
    }

    int repaired = 0;
    int exactMatches = 0;
    for (int c = 0; c < currentCount && remote_call_current_success(); c++) {
        int iconIndex = -1;
        for (int i = 0; i < iconCount; i++) {
            if (strcmp(current[c].bundle, bundles[i]) == 0) {
                iconIndex = i;
                break;
            }
        }
        if (iconIndex < 0) continue;

        uint64_t expected = themer_spotlight_theme_repository_image(
            current[c].bundle);
        uint64_t activeDataSource = themer_spotlight_trace_object_value(
            current[c].icon, "activeDataSource", "_activeDataSource");
        if (!r_is_objc_ptr(expected) ||
            !r_is_objc_ptr(activeDataSource) ||
            activeDataSource != providers[iconIndex]) {
            return false;
        }

        bool exactSupported = false;
        uint64_t cachedBefore = themer_spotlight_exact_cached_image(
            &current[c], current[c].icon, &exactSupported);
        bool exactBefore = exactSupported &&
            themer_spotlight_images_match(expected, cachedBefore);
        bool iconChanged = current[c].icon != icons[iconIndex];

        ThemerEntry scratch = {0};
        bool classChanged = false;
        bool grafted = themer_graft_spotlight_icon_model(
            current[c].icon, expected, &scratch,
            current[c].view, &classChanged);

        enum { TARGET_CAP = 32 };
        ThemerSpotlightCacheTarget targets[TARGET_CAP] = {{0}};
        int targetCount = themer_spotlight_collect_cache_targets(
            current[c].cache, targets, TARGET_CAP);
        targetCount = themer_spotlight_compact_cache_targets(
            targets, targetCount);
        uint64_t generation = r_msg2_main(
            current[c].cache, "currentImageGenerationForIcon:",
            current[c].icon, 0, 0, 0);
        int seedCalls = themer_spotlight_seed_cache_targets(
            targets, targetCount, expected, current[c].icon,
            current[c].appearance, generation, false);

        uint64_t cachedAfter = themer_spotlight_exact_cached_image(
            &current[c], current[c].icon, &exactSupported);
        bool exactAfter = exactSupported &&
            themer_spotlight_images_match(expected, cachedAfter);
        int directCalls = 0;
        uint64_t carrier = themer_spotlight_image_carrier_for_view(
            current[c].view);
        uint64_t displayed = themer_spotlight_image_from_carrier(carrier);
        bool visibleAfter = themer_spotlight_images_match(expected,
                                                           displayed);
        if (exactAfter && !visibleAfter) {
            directCalls = themer_spotlight_push_visible_image(
                current[c].view, carrier, expected,
                current[c].appearance);
            carrier = themer_spotlight_image_carrier_for_view(
                current[c].view);
            displayed = themer_spotlight_image_from_carrier(carrier);
            visibleAfter = themer_spotlight_images_match(expected,
                                                          displayed);
        }

        printf("[SPOTLIGHT_MONITOR] fast-repair bundle=%s "
               "iconChanged=%d exact=%d->%d grafted=%d classChanged=%d "
               "targets=%d seedCalls=%d directCalls=%d visible=%d\n",
               current[c].bundle,
               iconChanged,
               exactBefore,
               exactAfter,
               grafted,
               classChanged,
               targetCount,
               seedCalls,
               directCalls,
               visibleAfter);
        if (!grafted || !exactAfter) return false;

        icons[iconIndex] = current[c].icon;
        providers[iconIndex] = activeDataSource;
        repaired++;
        exactMatches++;
    }

    if (repaired <= 0 || exactMatches != repaired ||
        !remote_call_current_success()) {
        return false;
    }

    ThemerSpotlightCarrierBinding unique[THEMER_SPOTLIGHT_BINDING_CAP] = {{0}};
    int uniqueCount = themer_spotlight_unique_cache_bindings(
        current, currentCount, unique, THEMER_SPOTLIGHT_BINDING_CAP);
    if (uniqueCount <= 0) return false;
    bool armed = themer_spotlight_monitor_arm(
        icons, providers, bundles, iconCount,
        unique, uniqueCount, owner, dataSource, iconModel, repository);
    return armed && remote_call_current_success();
}

static bool themer_graft_visible_icon_model(uint64_t iconView,
                                            const char *bundle,
                                            uint64_t image)
{
    if (!r_is_objc_ptr(iconView) || !bundle || !bundle[0] ||
        !r_is_objc_ptr(image)) {
        return false;
    }

    ThemerEntry *entry = themer_lookup_entry(bundle);
    if (!entry) return false;
    bool wasModelGrafted = entry->modelGrafted;

    uint64_t icon = themer_application_icon_for_iconview(iconView);
    if (!r_is_objc_ptr(icon)) {
        if (gThemerLogBudget > 0) {
            uint64_t rawIcon = r_responds_main(iconView, "icon")
                ? r_msg2_main(iconView, "icon", 0, 0, 0, 0) : 0;
            char ivCls[96] = {0};
            char iconCls[96] = {0};
            char labelBuf[160] = {0};
            themer_read_class_name(iconView, ivCls, sizeof(ivCls));
            if (r_is_objc_ptr(rawIcon)) {
                themer_read_class_name(rawIcon, iconCls, sizeof(iconCls));
                uint64_t label = themer_copy_icon_label(rawIcon);
                if (r_is_objc_ptr(label)) {
                    r_read_nsstring(label, labelBuf, sizeof(labelBuf));
                    r_msg2(label, "release", 0, 0, 0, 0);
                }
            }
            printf("[THEMER] visible model graft skipped bundle=%s iconViewCls=%s icon=0x%llx iconCls=%s label=\"%s\"\n",
                   bundle, ivCls, (unsigned long long)rawIcon, iconCls, labelBuf);
            gThemerLogBudget--;
        }
        return false;
    }

    bool changed = false;
    if (!themer_graft_icon_model(icon, image, entry, iconView, &changed)) {
        return false;
    }

    entry->modelGrafted = true;
    themer_cache_icon_bundle(icon, bundle);
    (void)themer_notify_icon_image_changed(icon);
    if (gThemerLogBudget > 0) {
        printf("[THEMER] visible model graft bundle=%s icon=0x%llx changed=%d alreadyModel=%d\n",
               bundle, (unsigned long long)icon, changed, wasModelGrafted);
        gThemerLogBudget--;
    }
    return true;
}

static int themer_notify_icon_image_changed(uint64_t icon)
{
    if (!r_is_objc_ptr(icon)) return 0;

    int called = 0;
    static const char *selectors[] = {
        "purgeCachedImages",
        "clearCachedImages",
        "_clearCachedImages",
        "removeAllCachedImages",
        "removeCachedImages",
        "invalidateIconImageCache",
        "_invalidateIconImageCache",
        "invalidateCachedImages",
        "_invalidateCachedImages",
        "invalidateIconImage",
        "_invalidateIconImage",
        "reloadIconImage",
        "_reloadIconImage",
        "reloadIconImages",
        "_reloadIconImages",
        "reload",
        "refresh",
        "noteIconImageDidChange",
        "_noteIconImageDidChange",
        "noteIconImageNeedsUpdate",
        "_noteIconImageNeedsUpdate",
        "noteIconImageInfoDidChange",
        "_noteIconImageInfoDidChange",
    };

    for (size_t i = 0;
         i < sizeof(selectors) / sizeof(selectors[0]) &&
         remote_call_current_success();
         i++) {
        const char *sel = selectors[i];
        if (!r_responds_main(icon, sel)) continue;
        r_msg2_main(icon, sel, 0, 0, 0, 0);
        if (remote_call_current_success()) called++;
    }
    return called;
}

static bool themer_spotlight_restore_alpha_pinned_object(uint64_t object,
                                                         double alpha)
{
    if (!r_is_objc_ptr(object)) return true;

    uint64_t currentClass = r_dlsym_call(
        R_TIMEOUT, "object_getClass", object, 0, 0, 0, 0, 0, 0, 0);
    if (!r_is_objc_ptr(currentClass)) return false;

    char className[192] = {0};
    themer_read_class_object_name(currentClass, className, sizeof(className));
    static const char *prefix = "CNDSpotlightAlphaPinnedV1_";
    if (strncmp(className, prefix, strlen(prefix)) == 0) {
        uint64_t originalClass = r_dlsym_call(
            R_TIMEOUT, "class_getSuperclass",
            currentClass, 0, 0, 0, 0, 0, 0, 0);
        if (!r_is_objc_ptr(originalClass)) return false;
        r_dlsym_call(R_TIMEOUT, "object_setClass",
                     object, originalClass, 0, 0, 0, 0, 0, 0);
        uint64_t restoredClass = r_dlsym_call(
            R_TIMEOUT, "object_getClass", object, 0, 0, 0, 0, 0, 0, 0);
        if (restoredClass != originalClass) return false;
    }

    if (r_responds_main(object, "setAlpha:")) {
        r_msg2_main_raw(object, "setAlpha:",
                        &alpha, sizeof(alpha),
                        NULL, 0, NULL, 0, NULL, 0);
    }
    return remote_call_current_success();
}

static bool themer_spotlight_icon_in_list(uint64_t icon,
                                          const uint64_t *icons,
                                          int count)
{
    if (!r_is_objc_ptr(icon) || !icons || count <= 0) return false;
    for (int i = 0; i < count; i++) {
        if (icons[i] == icon) return true;
    }
    return false;
}

static int themer_spotlight_restore_state_icons(uint64_t state,
                                                uint64_t excludingIcons,
                                                bool clearDiscoveredCaches,
                                                bool *completeOut)
{
    if (completeOut) *completeOut = false;
    if (!r_is_objc_ptr(state)) {
        if (completeOut) *completeOut = true;
        return 0;
    }

    uint64_t icons = themer_spotlight_dictionary_object(state, "icons");
    uint64_t classes = themer_spotlight_dictionary_object(state, "classes");
    if (!r_is_objc_ptr(icons) ||
        !r_responds_main(icons, "allKeys") ||
        !r_responds_main(icons, "objectForKey:")) {
        return 0;
    }

    uint64_t keys = r_msg2_main(icons, "allKeys", 0, 0, 0, 0);
    uint64_t keyCount = themer_remote_count(keys);
    if (!r_is_objc_ptr(keys) ||
        !r_responds_main(keys, "objectAtIndex:") ||
        keyCount > THEMER_SPOTLIGHT_MONITOR_ICON_CAP) {
        return 0;
    }

    static const char *rendererSelectors[] = {
        "makeIconImageWithInfo:traitCollection:context:options:",
        "iconImageWithInfo:traitCollection:context:options:",
        "iconImageWithInfo:traitCollection:options:",
        "iconImageWithInfo:",
    };
    uint64_t restoredIcons[THEMER_SPOTLIGHT_MONITOR_ICON_CAP] = {0};
    int expected = 0;
    int restored = 0;
    int associationClears = 0;
    int classRestores = 0;
    int invalidationCalls = 0;

    for (uint64_t i = 0; i < keyCount && remote_call_current_success(); i++) {
        uint64_t key = r_msg2_main(keys, "objectAtIndex:", i, 0, 0, 0);
        if (!r_is_objc_ptr(key)) continue;
        if (r_is_objc_ptr(excludingIcons) &&
            r_responds_main(excludingIcons, "objectForKey:") &&
            r_is_objc_ptr(r_msg2_main(excludingIcons, "objectForKey:",
                                     key, 0, 0, 0))) {
            continue;
        }

        expected++;
        uint64_t icon = r_msg2_main(icons, "objectForKey:", key, 0, 0, 0);
        uint64_t originalClass = r_is_objc_ptr(classes) &&
                                 r_responds_main(classes, "objectForKey:")
            ? r_msg2_main(classes, "objectForKey:", key, 0, 0, 0)
            : 0;
        uint64_t currentClass = r_is_objc_ptr(icon)
            ? r_dlsym_call(R_TIMEOUT, "object_getClass",
                           icon, 0, 0, 0, 0, 0, 0, 0)
            : 0;
        char currentClassName[192] = {0};
        if (r_is_objc_ptr(currentClass)) {
            themer_read_class_object_name(currentClass,
                                          currentClassName,
                                          sizeof(currentClassName));
        }
        if (!r_is_objc_ptr(originalClass) &&
            strncmp(currentClassName, "CNDSpotlightThemed",
                    sizeof("CNDSpotlightThemed") - 1) == 0) {
            originalClass = r_dlsym_call(
                R_TIMEOUT, "class_getSuperclass",
                currentClass, 0, 0, 0, 0, 0, 0, 0);
        }
        char bundle[192] = {0};
        (void)r_read_nsstring(key, bundle, sizeof(bundle));
        if (!r_is_objc_ptr(icon) || !r_is_objc_ptr(originalClass)) {
            printf("[SPOTLIGHT_RESTORE] bundle=%s status=invalid-state "
                   "icon=0x%llx class=0x%llx current=%s\n",
                   bundle[0] ? bundle : "?",
                   (unsigned long long)icon,
                   (unsigned long long)originalClass,
                   currentClassName[0] ? currentClassName : "-");
            continue;
        }

        bool associationsOK = true;
        for (size_t s = 0;
             s < sizeof(rendererSelectors) / sizeof(rendererSelectors[0]);
             s++) {
            uint64_t selector = r_sel(rendererSelectors[s]);
            if (!selector) {
                associationsOK = false;
                continue;
            }
            r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                         icon, selector, 0, 1, 0, 0, 0, 0);
            uint64_t associated = r_dlsym_call(
                R_TIMEOUT, "objc_getAssociatedObject",
                icon, selector, 0, 0, 0, 0, 0, 0);
            if (associated == 0) {
                associationClears++;
            } else {
                associationsOK = false;
            }
        }

        bool classOK = currentClass == originalClass;
        if (!classOK && r_is_objc_ptr(currentClass)) {
            if (strncmp(currentClassName, "CNDSpotlightThemed",
                        sizeof("CNDSpotlightThemed") - 1) == 0) {
                r_dlsym_call(R_TIMEOUT, "object_setClass",
                             icon, originalClass, 0, 0, 0, 0, 0, 0);
                uint64_t installedClass = r_dlsym_call(
                    R_TIMEOUT, "object_getClass",
                    icon, 0, 0, 0, 0, 0, 0, 0);
                classOK = installedClass == originalClass;
                if (classOK) classRestores++;
            }
        }

        invalidationCalls += themer_notify_icon_image_changed(icon);
        if (associationsOK && classOK) {
            restoredIcons[restored++] = icon;
        }
        printf("[SPOTLIGHT_RESTORE] bundle=%s icon=0x%llx "
               "associations=%d class=%d invalidations=%d\n",
               bundle[0] ? bundle : "?",
               (unsigned long long)icon,
               associationsOK,
               classOK,
               invalidationCalls);
    }

    ThemerSpotlightCarrierBinding bindings[
        THEMER_SPOTLIGHT_BINDING_CAP] = {{0}};
    int bindingCount = themer_spotlight_collect_carrier_bindings(
        bindings, THEMER_SPOTLIGHT_BINDING_CAP, false);
    int alphaRestores = 0;
    int cacheClearCalls = 0;
    int rowRefreshCalls = 0;
    if (clearDiscoveredCaches && bindingCount > 0) {
        ThemerSpotlightCarrierBinding unique[
            THEMER_SPOTLIGHT_BINDING_CAP] = {{0}};
        int uniqueCount = themer_spotlight_unique_cache_bindings(
            bindings, bindingCount, unique, THEMER_SPOTLIGHT_BINDING_CAP);
        for (int i = 0; i < uniqueCount && remote_call_current_success(); i++) {
            cacheClearCalls += themer_call_zero_arg_cache_clears(
                unique[i].cache, "Spotlight restore");
        }
    }

    for (int i = 0; i < bindingCount && remote_call_current_success(); i++) {
        bool affected = clearDiscoveredCaches ||
            themer_spotlight_icon_in_list(bindings[i].icon,
                                          restoredIcons,
                                          restored);
        if (!affected) continue;

        uint64_t carrier = themer_spotlight_image_carrier_for_view(
            bindings[i].view);
        uint64_t placeholder = themer_spotlight_trace_object_value(
            bindings[i].view, "placeholderView", "_placeholderView");
        if (themer_spotlight_restore_alpha_pinned_object(carrier, 1.0)) {
            alphaRestores++;
        }
        if (themer_spotlight_restore_alpha_pinned_object(placeholder, 0.0)) {
            alphaRestores++;
        }
        rowRefreshCalls += themer_spotlight_refresh_view_from_model(
            bindings[i].view,
            bindings[i].cache,
            carrier,
            bindings[i].icon,
            false);
    }

    bool complete = restored == expected && remote_call_current_success();
    printf("[SPOTLIGHT_RESTORE] icons=%d/%d associationClears=%d "
           "classRestores=%d invalidationCalls=%d bindings=%d "
           "cacheClearCalls=%d alphaRestores=%d rowRefreshCalls=%d "
           "complete=%d\n",
           restored, expected, associationClears, classRestores,
           invalidationCalls, bindingCount, cacheClearCalls,
           alphaRestores, rowRefreshCalls, complete);
    if (completeOut) *completeOut = complete;
    return restored;
}

bool themer_restore_spotlight_theme_in_session(void)
{
    themer_spotlight_monitor_reset();
    if (!remote_call_current_success()) return false;

    uint64_t state = themer_spotlight_theme_state();
    if (!r_is_objc_ptr(state)) {
        printf("[SPOTLIGHT_RESTORE] no process-resident theme state; "
               "already restored\n");
        return true;
    }

    uint64_t legacyRepository =
        themer_spotlight_associated_process_object(
            "cndSpotlightThemeImageRepository");
    r_msg2(state, "retain", 0, 0, 0, 0);
    bool stateRetained = remote_call_current_success();
    bool legacyRetained = false;
    if (r_is_objc_ptr(legacyRepository) && remote_call_current_success()) {
        r_msg2(legacyRepository, "retain", 0, 0, 0, 0);
        legacyRetained = remote_call_current_success();
    }
    if (!stateRetained || !remote_call_current_success()) return false;

    bool restoreComplete = false;
    int restored = themer_spotlight_restore_state_icons(
        state, 0, true, &restoreComplete);
    bool stateCleared = false;
    bool repositoryCleared = false;
    if (restoreComplete && remote_call_current_success()) {
        stateCleared = themer_spotlight_commit_theme_state(0);
        repositoryCleared = stateCleared &&
            themer_spotlight_commit_theme_repository(0);
        if (!stateCleared || !repositoryCleared) {
            (void)themer_spotlight_commit_theme_state(state);
            if (legacyRetained) {
                (void)themer_spotlight_commit_theme_repository(
                    legacyRepository);
            }
        }
    }

    bool success = restoreComplete && stateCleared && repositoryCleared &&
                   remote_call_current_success();
    if (legacyRetained && remote_call_current_success()) {
        r_msg2(legacyRepository, "release", 0, 0, 0, 0);
    }
    if (stateRetained && remote_call_current_success()) {
        r_msg2(state, "release", 0, 0, 0, 0);
    }
    if (success) {
        gThemerSpotlightApplyGeneration = 0;
    }
    printf("[SPOTLIGHT_RESTORE] complete success=%d restored=%d "
           "stateCleared=%d repositoryCleared=%d remoteHealthy=%d\n",
           success, restored, stateCleared, repositoryCleared,
           remote_call_current_success());
    return success;
}

// Resolve the bundle identifier for an app SBIconView/SBIcon.
static bool themer_read_bundle_for_icon(uint64_t icon,
                                        uint64_t probeIconView,
                                        char *out, size_t outLen)
{
    if (!r_is_objc_ptr(icon) || !out || outLen == 0) return false;

    // Try the SBHApplication path first. On iOS 26 the older leaf identifier
    // selectors can report support but return non-NSString/private values.
    uint64_t appObj = r_responds(icon, "application")
        ? r_msg2(icon, "application", 0, 0, 0, 0) : 0;
    if (r_is_objc_ptr(appObj) && r_responds(appObj, "bundleIdentifier")) {
        uint64_t bid = r_msg2(appObj, "bundleIdentifier", 0, 0, 0, 0);
        if (r_is_objc_ptr(bid) && r_read_nsstring(bid, out, outLen) && out[0]) {
            themer_cache_icon_bundle(icon, out);
            return true;
        }
    }

    if (themer_lookup_icon_bundle(icon, out, outLen)) {
        static int fallbackLogs = 0;
        if (fallbackLogs < 8) {
            printf("[THEMER] model bundle fallback icon=0x%llx bundle=%s\n",
                   (unsigned long long)icon, out);
            fallbackLogs++;
        }
        return true;
    }

    // First-iconView verbose probe: keep this to the known-stable application
    // path. Calling object_getClass on legacy selector returns can PAC-crash
    // SpringBoard when a selector returns a private non-object payload.
    static bool probedShape = false;
    if (!probedShape) {
        probedShape = true;
        char ivCls[96] = {0}, iconCls[96] = {0};
        if (r_is_objc_ptr(probeIconView)) themer_read_class_name(probeIconView, ivCls, sizeof(ivCls));
        themer_read_class_name(icon, iconCls, sizeof(iconCls));
        printf("[THEMER] probe iconView class=%s icon=0x%llx class=%s\n",
               ivCls, (unsigned long long)icon, iconCls);
        if (r_is_objc_ptr(appObj)) {
            char appCls[96] = {0};
            themer_read_class_name(appObj, appCls, sizeof(appCls));
            bool appHasBID = r_responds(appObj, "bundleIdentifier");
            uint64_t appBID = appHasBID
                ? r_msg2(appObj, "bundleIdentifier", 0, 0, 0, 0) : 0;
            char appBIDStr[160] = {0};
            if (r_is_objc_ptr(appBID)) r_read_nsstring(appBID, appBIDStr, sizeof(appBIDStr));
            printf("[THEMER]   application=0x%llx class=%s bundleIdentifier=\"%s\"\n",
                   (unsigned long long)appObj, appCls, appBIDStr);
        }
    }

    return false;
}

static bool themer_read_bundle_for_iconview(uint64_t iconView,
                                            char *out, size_t outLen)
{
    if (!r_is_objc_ptr(iconView) || !out || outLen == 0) return false;

    uint64_t icon = themer_application_icon_for_iconview(iconView);
    return themer_read_bundle_for_icon(icon, iconView, out, outLen);
}

// Rung 1: iOS 26 path —
//          setOverrideImage:                       (track the override slot)
//          + _iconImageView.updateImageContentsWithImage:imageAppearance:animated:
//            (or fallback: setDisplayedImage:)     (force the rendered pixels)
// Rung 2: setIconImage:           (iOS 18 and earlier)
// Rung 3: _setIconImage:          (private variant)
// Rung 4: _iconImageView.setImage: (last-resort UIImageView-style setter)
static bool gThemerInnerCanUpdateContents = false;
static bool gThemerInnerCanSetDisplayed = false;

static int themer_probe_rung(uint64_t iconView)
{
    if (gThemerRung >= 0) return gThemerRung;
    if (!r_is_objc_ptr(iconView)) return -1;

    bool r1 = r_responds_main(iconView, "setOverrideImage:");
    bool r2 = r_responds_main(iconView, "setIconImage:");
    bool r3 = r_responds_main(iconView, "_setIconImage:");

    uint64_t iiv = r_ivar_value(iconView, "_iconImageView");
    if (!r_is_objc_ptr(iiv) && r_responds_main(iconView, "_iconImageView")) {
        iiv = r_msg2_main(iconView, "_iconImageView", 0, 0, 0, 0);
    }
    bool r4 = r_is_objc_ptr(iiv) && r_responds_main(iiv, "setImage:");
    if (r_is_objc_ptr(iiv)) {
        gThemerInnerCanUpdateContents = r_responds_main(iiv,
            "updateImageContentsWithImage:imageAppearance:animated:");
        gThemerInnerCanSetDisplayed = r_responds_main(iiv, "setDisplayedImage:");
    }

    gThemerHasUpdateAfter = r_responds_main(iconView,
        "_updateAfterManualIconImageInfoChangeInvalidatingLayout:");
    gThemerHasUpdateImageView = r_responds_main(iconView,
        "_updateIconImageViewAnimated:");

    char iivCls[96] = {0};
    if (r_is_objc_ptr(iiv)) themer_read_class_name(iiv, iivCls, sizeof(iivCls));
    bool legacyVisible = themer_needs_visible_push(NULL);
    printf("[THEMER] probe iconView=0x%llx setOverrideImage:=%d setIconImage:=%d "
           "_setIconImage:=%d _iconImageView=0x%llx (%s) "
           "setImage:=%d updateContents:=%d setDisplayedImage:=%d "
           "update:=%d updateIV:=%d legacy=%d\n",
           (unsigned long long)iconView, r1, r2, r3,
           (unsigned long long)iiv, iivCls,
           r4, gThemerInnerCanUpdateContents, gThemerInnerCanSetDisplayed,
           gThemerHasUpdateAfter, gThemerHasUpdateImageView,
           legacyVisible);

    if (legacyVisible) {
        if (r2)      gThemerRung = 2;
        else if (r3) gThemerRung = 3;
        else if (r4) gThemerRung = 4;
        else if (r1) gThemerRung = 1;
        else         gThemerRung = 0;
    } else {
        if (r1)      gThemerRung = 1;
        else if (r2) gThemerRung = 2;
        else if (r3) gThemerRung = 3;
        else if (r4) gThemerRung = 4;
        else         gThemerRung = 0;
    }

    return gThemerRung;
}

// Returns the rung that succeeded (1/2/3/4) or 0 if nothing stuck.
static int themer_push_image(uint64_t iconView, uint64_t image)
{
    if (!r_is_objc_ptr(iconView) || !r_is_objc_ptr(image)) return 0;
    int rung = themer_probe_rung(iconView);

    switch (rung) {
        case 1: {
            // iOS 26 contents-path strategy (from RE of SpringBoardHome):
            //   shouldDisplayImageLayer is YES by default → sublayer path that
            //   ignores overrideImage. To force the flat contents path that
            //   DOES read overrideImage:
            //   1. Set overrideIconImageAppearance = +[SBHIconImageAppearance lightAppearance]
            //      (light = appearanceType 0/1 → hasGlass returns NO)
            //   2. Set iconImageView.showsSquareCorners = YES
            //   3. Now shouldDisplayImageLayer returns NO, and
            //      updateImageAnimated: takes updateImageContentsAnimated:,
            //      which calls updateImageContentsWithImage:imageAppearance:animated:
            //      using [iconView overrideImage].
            //   4. Set overrideImage = our UIImage (also triggers updateImageAnimated:NO).
            uint64_t iiv = r_ivar_value(iconView, "_iconImageView");
            if (!r_is_objc_ptr(iiv)) {
                iiv = r_msg2_main(iconView, "_iconImageView", 0, 0, 0, 0);
            }
            if (!r_is_objc_ptr(iiv)) break;

            // PERSISTENCE: populate SBHIconImageCache for this icon. The
            // home-screen render pipeline goes via SBIcon →
            // iconLayerViewWithInfo: → SBHIconImageVariantCache.cachedImage
            // → SBHIconImageAppearanceStore. Cache-populated images stick
            // across layout passes (page swipe, rotation) so home icons
            // don't revert. -[SBHIconImageCache cacheImage:forIcon:imageAppearance:]
            // calls through to setImage:forIcon:appearance: on the underlying
            // store plus bookkeeping.
            uint64_t icon = r_responds_main(iconView, "icon")
                ? r_msg2_main(iconView, "icon", 0, 0, 0, 0) : 0;
            uint64_t cache = r_responds_main(iiv, "iconImageCache")
                ? r_msg2_main(iiv, "iconImageCache", 0, 0, 0, 0) : 0;
            uint64_t appearance = r_responds_main(iiv, "effectiveIconImageAppearance")
                ? r_msg2_main(iiv, "effectiveIconImageAppearance", 0, 0, 0, 0) : 0;
            if (r_is_objc_ptr(cache) && r_is_objc_ptr(icon) &&
                r_is_objc_ptr(appearance) &&
                r_responds_main(cache, "cacheImage:forIcon:imageAppearance:")) {
                r_msg2_main(cache, "cacheImage:forIcon:imageAppearance:",
                            image, icon, appearance, 0);
            }

            uint64_t appearanceCls = r_class("SBHIconImageAppearance");
            uint64_t lightAppearance = r_is_objc_ptr(appearanceCls)
                ? r_msg2(appearanceCls, "lightAppearance", 0, 0, 0, 0) : 0;
            if (r_is_objc_ptr(lightAppearance) &&
                r_responds_main(iconView, "setOverrideIconImageAppearance:")) {
                r_msg2_main(iconView, "setOverrideIconImageAppearance:",
                            lightAppearance, 0, 0, 0);
            }
            if (r_responds_main(iiv, "setShowsSquareCorners:")) {
                r_msg2_main(iiv, "setShowsSquareCorners:", 1, 0, 0, 0);
            }
            r_msg2_main(iconView, "setOverrideImage:", image, 0, 0, 0);

            // App launch/resume can leave the SBIconView carrying our
            // overrideImage while its inner contents/layer was discarded.
            // Force the iOS 26 flat-contents path too, so a cached repaint
            // repairs that state even when setOverrideImage: sees the same
            // pointer it already had.
            uint64_t updateAppearance = r_is_objc_ptr(lightAppearance)
                ? lightAppearance : appearance;
            if (gThemerInnerCanUpdateContents && r_is_objc_ptr(updateAppearance) &&
                r_responds_main(iiv, "updateImageContentsWithImage:imageAppearance:animated:")) {
                r_msg2_main(iiv, "updateImageContentsWithImage:imageAppearance:animated:",
                            image, updateAppearance, 0, 0);
            } else if (gThemerInnerCanSetDisplayed &&
                       r_responds_main(iiv, "setDisplayedImage:")) {
                r_msg2_main(iiv, "setDisplayedImage:", image, 0, 0, 0);
            }

            // Also cache for the light appearance specifically, in case
            // future layout fetches request that variant (we've flipped the
            // override appearance to light, so the cache lookup key likely
            // ends up there).
            if (r_is_objc_ptr(cache) && r_is_objc_ptr(icon) &&
                r_is_objc_ptr(lightAppearance) &&
                r_responds_main(cache, "cacheImage:forIcon:imageAppearance:")) {
                r_msg2_main(cache, "cacheImage:forIcon:imageAppearance:",
                            image, icon, lightAppearance, 0);
            }

            // showsSquareCorners=YES exposed the full iconImageView bounds.
            // Reapply rounded mask on iiv.layer (~22.5% of width).
            uint64_t iivLayer = r_responds_main(iiv, "layer")
                ? r_msg2_main(iiv, "layer", 0, 0, 0, 0) : 0;
            if (r_is_objc_ptr(iivLayer)) {
                struct { double x, y, w, h; } b = {0};
                double radius = 15.0;
                if (r_responds_main(iivLayer, "bounds") &&
                    r_msg2_main_struct_ret(iivLayer, "bounds",
                        &b, sizeof(b),
                        NULL, 0, NULL, 0, NULL, 0, NULL, 0) &&
                    b.w > 0.0) {
                    radius = b.w * 0.225;
                }
                r_msg2_main_raw(iivLayer, "setCornerRadius:",
                    &radius, sizeof(radius),
                    NULL, 0, NULL, 0, NULL, 0);
                if (r_responds_main(iivLayer, "setMasksToBounds:")) {
                    r_msg2_main(iivLayer, "setMasksToBounds:", 1, 0, 0, 0);
                }
            }

            static bool postProbed = false;
            if (!postProbed) {
                postProbed = true;
                bool shouldDisplay = r_responds_main(iiv, "shouldDisplayImageLayer")
                    ? (r_msg2_main(iiv, "shouldDisplayImageLayer", 0, 0, 0, 0) & 0xff) != 0
                    : true;
                bool sqCorners = r_responds_main(iiv, "showsSquareCorners")
                    ? (r_msg2_main(iiv, "showsSquareCorners", 0, 0, 0, 0) & 0xff) != 0
                    : false;
                uint64_t effApp = r_responds_main(iiv, "effectiveIconImageAppearance")
                    ? r_msg2_main(iiv, "effectiveIconImageAppearance", 0, 0, 0, 0) : 0;
                bool hasGlass = (r_is_objc_ptr(effApp) && r_responds_main(effApp, "hasGlass"))
                    ? (r_msg2_main(effApp, "hasGlass", 0, 0, 0, 0) & 0xff) != 0
                    : true;
                uint64_t displayedRead = r_responds_main(iiv, "displayedImage")
                    ? r_msg2_main(iiv, "displayedImage", 0, 0, 0, 0) : 0;
                uint64_t overrideRead = r_responds_main(iconView, "overrideImage")
                    ? r_msg2_main(iconView, "overrideImage", 0, 0, 0, 0) : 0;
                char appCls[96] = {0};
                themer_read_class_name(effApp, appCls, sizeof(appCls));
                printf("[THEMER] post: shouldDisplayImageLayer=%d showsSquareCorners=%d "
                       "hasGlass=%d effApp=0x%llx (%s) displayed=0x%llx override=0x%llx "
                       "(want image=0x%llx) lightAppearance=0x%llx\n",
                       shouldDisplay, sqCorners, hasGlass,
                       (unsigned long long)effApp, appCls,
                       (unsigned long long)displayedRead,
                       (unsigned long long)overrideRead,
                       (unsigned long long)image,
                       (unsigned long long)lightAppearance);
            }
            break;
        }
        case 2:
            r_msg2_main(iconView, "setIconImage:", image, 0, 0, 0);
            break;
        case 3:
            r_msg2_main(iconView, "_setIconImage:", image, 0, 0, 0);
            break;
        case 4: {
            uint64_t iiv = r_ivar_value(iconView, "_iconImageView");
            if (!r_is_objc_ptr(iiv)) {
                iiv = r_msg2_main(iconView, "_iconImageView", 0, 0, 0, 0);
            }
            if (!r_is_objc_ptr(iiv)) return 0;
            r_msg2_main(iiv, "setImage:", image, 0, 0, 0);
            break;
        }
        default:
            return 0;
    }

    return rung;
}

static int themer_iter_iconviews(uint64_t listView,
                                 NSDictionary<NSString *, NSData *> *dataByBundle,
                                 uint64_t iconViewCls,
                                 int *rungHits,
                                 int *misses,
                                 int *paintFails)
{
    if (!r_is_objc_ptr(listView) || !r_is_objc_ptr(iconViewCls)) return 0;

    // BFS the list view so we pick up SBIconViews regardless of how iOS 26
    // wraps them (AMUIInfographIconListLayout adds intermediate containers).
    enum { IV_CAP = 64 };
    uint64_t ivs[IV_CAP];
    int n = sb_collect_views(listView, iconViewCls, ivs, IV_CAP);

    if (n == 0) {
        if (gThemerLogBudget > 0) {
            uint64_t subs = r_msg2_main(listView, "subviews", 0, 0, 0, 0);
            uint64_t sc = r_is_objc_ptr(subs) ? r_msg2_main(subs, "count", 0, 0, 0, 0) : 0;
            char lvCls[96];
            themer_read_class_name(listView, lvCls, sizeof(lvCls));
            printf("[THEMER] listView=0x%llx class=%s no iconViews; direct subviews=%llu\n",
                   (unsigned long long)listView, lvCls, (unsigned long long)sc);
            uint64_t cap = sc > 6 ? 6 : sc;
            for (uint64_t i = 0; i < cap; i++) {
                uint64_t child = r_msg2_main(subs, "objectAtIndex:", i, 0, 0, 0);
                char cls[96] = {0};
                themer_read_class_name(child, cls, sizeof(cls));
                printf("[THEMER]   subview[%llu]=0x%llx class=%s\n",
                       (unsigned long long)i, (unsigned long long)child, cls);
            }
            gThemerLogBudget--;
        }
        return 0;
    }

    if (gThemerLogBudget > 0) {
        printf("[THEMER] listView=0x%llx iconViews=%d (BFS)\n",
               (unsigned long long)listView, n);
        gThemerLogBudget--;
    }

    int applied = 0;
    for (int i = 0; i < n; i++) {
        uint64_t v = ivs[i];
        if (!r_is_objc_ptr(v)) continue;

        char bundle[128] = {0};
        if (!themer_read_bundle_for_iconview(v, bundle, sizeof(bundle))) {
            themer_clear_dynamic_overlay(v);
            themer_clear_static_dynamic_child_overlay_for_iconview(v);
            themer_clear_visible_override(v);
            if (gThemerLogBudget > 0) {
                char ivCls[96] = {0};
                themer_read_class_name(v, ivCls, sizeof(ivCls));
                printf("[THEMER]   bundle read failed iconView=0x%llx class=%s\n",
                       (unsigned long long)v, ivCls);
                gThemerLogBudget--;
            }
            continue;
        }
        if (strcmp(bundle, "com.apple.mobiletimer") != 0) {
            themer_clear_static_dynamic_child_overlay_for_iconview(v);
        }

        // Debug: skip everything except the focus bundle so the log is
        // small enough to reason about.
        if (kThemerFocusBundle && kThemerFocusBundle[0] &&
            strcmp(bundle, kThemerFocusBundle) != 0) {
            continue;
        }

        bool dynamicOverlay = themer_should_pin_dynamic_overlay(bundle, v);
        if (!dynamicOverlay) themer_clear_visible_override(v);

        uint64_t image = themer_lookup_cached(bundle);
        if (!image) {
            NSString *key = [NSString stringWithUTF8String:bundle];
            NSData *pngBytes = key ? dataByBundle[key] : nil;
            if (!pngBytes) {
                themer_clear_dynamic_overlay(v);
                themer_clear_static_dynamic_child_overlay_for_iconview(v);
                themer_clear_visible_override(v);
                if (misses) (*misses)++;
                if (gThemerLogBudget > 0) {
                    printf("[THEMER] miss bundle=%s (no override in theme)\n", bundle);
                    gThemerLogBudget--;
                }
                continue;
            }
            NSData *uploadBytes = themer_rounded_png_data(pngBytes, bundle);
            image = themer_build_remote_uiimage_from_data(uploadBytes ?: pngBytes, bundle);
            if (!image) {
                themer_clear_dynamic_overlay(v);
                themer_clear_static_dynamic_child_overlay_for_iconview(v);
                themer_clear_visible_override(v);
                if (misses) (*misses)++;
                continue;
            }
            themer_cache_image(bundle, image);
            if (gThemerLogBudget > 0) {
                printf("[THEMER] built bundle=%s image=0x%llx\n",
                       bundle, (unsigned long long)image);
                gThemerLogBudget--;
            }
        }
        if (!dynamicOverlay) {
            themer_clear_dynamic_overlay(v);
        }

        // Dynamic/special icons keep a pinned overlay because their mounted
        // image views can redraw from private live renderers.
        bool viewLevelOverlay = themer_prefers_view_level_overlay(bundle);
        (void)viewLevelOverlay;
        int rung = 0;
        bool staticDynamicOK = false;
        if (dynamicOverlay && themer_pin_dynamic_overlay(v, image, bundle)) {
            rung = 1;
        } else if (!dynamicOverlay) {
            rung = themer_push_image(v, image);
            staticDynamicOK =
                themer_apply_static_dynamic_icon_state(v, image, bundle);
            if (staticDynamicOK && rung == 0) {
                rung = 1;
            }
        }
        themer_log_iconview_render_state("initial", bundle, v, image, rung);

        ThemerEntry *entry = themer_lookup_entry(bundle);
        if (kThemerIconServicesApplySeedEnabled &&
            entry && !entry->iconServicesSeeded) {
            double iconWidth = themer_icon_width_for_view(v);
            entry->iconServicesSeeded =
                themer_seed_iconservices_cache(bundle, image, iconWidth) > 0;
        }
        if (rung > 0) {
            applied++;
            if (rungHits && rung >= 1 && rung <= 4) rungHits[rung - 1]++;
            if (!themer_log_paint_verification("initial", bundle, v, image,
                                               rung,
                                               dynamicOverlay || staticDynamicOK) &&
                paintFails) {
                (*paintFails)++;
            }
            if (kThemerDetailedIconLogs) {
                uint64_t superv = r_responds_main(v, "superview")
                    ? r_msg2_main(v, "superview", 0, 0, 0, 0) : 0;
                char supCls[96] = {0};
                themer_read_class_name(superv, supCls, sizeof(supCls));
                double alpha = 1.0;
                if (r_responds_main(v, "alpha")) {
                    r_msg2_main_struct_ret(v, "alpha", &alpha, sizeof(alpha),
                        NULL, 0, NULL, 0, NULL, 0, NULL, 0);
                }
                bool hidden = r_responds_main(v, "isHidden")
                    ? (r_msg2_main(v, "isHidden", 0, 0, 0, 0) & 0xff) != 0
                    : false;
                bool wasBorrowed = r_responds_main(v, "isIconImageViewBorrowed")
                    ? (r_msg2_main(v, "isIconImageViewBorrowed", 0, 0, 0, 0) & 0xff) != 0
                    : false;
                printf("[THEMER]   %s superview=%s borrowed=%d alpha=%.2f hidden=%d\n",
                       bundle, supCls, wasBorrowed, alpha, hidden);
            }
        } else {
            if (misses) (*misses)++;
            if (gThemerLogBudget > 0) {
                printf("[THEMER] no rung stuck bundle=%s iconView=0x%llx\n",
                       bundle, (unsigned long long)v);
                gThemerLogBudget--;
            }
        }
    }
    return applied;
}

static int themer_repaint_cached_iconviews(uint64_t listView,
                                           uint64_t iconViewCls,
                                           int *rungHits,
                                           int *misses,
                                           int *skips,
                                           int *paintFails,
                                           bool force)
{
    if (!r_is_objc_ptr(listView) || !r_is_objc_ptr(iconViewCls)) return 0;

    enum { IV_CAP = 64 };
    uint64_t ivs[IV_CAP];
    int n = sb_collect_views(listView, iconViewCls, ivs, IV_CAP);
    int applied = 0;

    for (int i = 0; i < n; i++) {
        uint64_t v = ivs[i];
        if (!r_is_objc_ptr(v)) continue;

        char bundle[128] = {0};
        if (!themer_read_bundle_for_iconview(v, bundle, sizeof(bundle))) {
            themer_clear_dynamic_overlay(v);
            themer_clear_static_dynamic_child_overlay_for_iconview(v);
            themer_clear_visible_override(v);
            if (misses) (*misses)++;
            continue;
        }
        if (strcmp(bundle, "com.apple.mobiletimer") != 0) {
            themer_clear_static_dynamic_child_overlay_for_iconview(v);
        }

        uint64_t image = themer_lookup_cached(bundle);
        if (!r_is_objc_ptr(image)) {
            themer_clear_dynamic_overlay(v);
            themer_clear_static_dynamic_child_overlay_for_iconview(v);
            themer_clear_visible_override(v);
            if (misses) (*misses)++;
            continue;
        }

        uint64_t overrideRead = r_responds_main(v, "overrideImage")
            ? r_msg2_main(v, "overrideImage", 0, 0, 0, 0) : 0;
        uint64_t iiv = r_ivar_value(v, "_iconImageView");
        if (!r_is_objc_ptr(iiv) && r_responds_main(v, "_iconImageView")) {
            iiv = r_msg2_main(v, "_iconImageView", 0, 0, 0, 0);
        }
        uint64_t displayedRead = (r_is_objc_ptr(iiv) &&
                                  r_responds_main(iiv, "displayedImage"))
            ? r_msg2_main(iiv, "displayedImage", 0, 0, 0, 0) : 0;
        bool dynamicOverlay = themer_should_pin_dynamic_overlay(bundle, v);
        if (!force && !dynamicOverlay &&
            overrideRead == image && displayedRead == image) {
            themer_clear_dynamic_overlay(v);
            if (skips) (*skips)++;
            continue;
        }
        if (!dynamicOverlay && overrideRead && overrideRead != image) {
            themer_clear_visible_override(v);
        }
        if (!dynamicOverlay) {
            themer_clear_dynamic_overlay(v);
        }

        int rung = 0;
        bool staticDynamicOK = false;
        if (dynamicOverlay && themer_pin_dynamic_overlay(v, image, bundle)) {
            rung = 1;
        } else if (!dynamicOverlay) {
            rung = themer_push_image(v, image);
            staticDynamicOK =
                themer_apply_static_dynamic_icon_state(v, image, bundle);
            if (staticDynamicOK && rung == 0) {
                rung = 1;
            }
        }
        themer_log_iconview_render_state(force ? "force-repaint" : "cached-repaint",
                                         bundle, v, image, rung);
        if (rung > 0) {
            applied++;
            if (rungHits && rung >= 1 && rung <= 4) rungHits[rung - 1]++;
            if (!themer_log_paint_verification(force ? "force-repaint" : "cached-repaint",
                                               bundle, v, image, rung,
                                               dynamicOverlay || staticDynamicOK) &&
                paintFails) {
                (*paintFails)++;
            }
        } else if (misses) {
            (*misses)++;
        }
    }

    return applied;
}

static int themer_repaint_dynamic_iconviews(uint64_t listView,
                                            uint64_t iconViewCls,
                                            int *rungHits,
                                            int *misses)
{
    if (!r_is_objc_ptr(listView) || !r_is_objc_ptr(iconViewCls)) return 0;

    enum { IV_CAP = 64 };
    uint64_t ivs[IV_CAP];
    int n = sb_collect_views(listView, iconViewCls, ivs, IV_CAP);
    int applied = 0;

    for (int i = 0; i < n; i++) {
        uint64_t v = ivs[i];
        if (!r_is_objc_ptr(v)) continue;

        char bundle[128] = {0};
        if (!themer_read_bundle_for_iconview(v, bundle, sizeof(bundle))) {
            if (misses) (*misses)++;
            continue;
        }
        if (!themer_should_pin_dynamic_overlay(bundle, v)) continue;

        uint64_t image = themer_lookup_cached(bundle);
        if (!r_is_objc_ptr(image)) {
            if (misses) (*misses)++;
            continue;
        }

        int rung = themer_pin_dynamic_overlay(v, image, bundle) ? 1 : 0;
        if (rung > 0) {
            applied++;
            if (rungHits) rungHits[0]++;
        } else if (misses) {
            (*misses)++;
        }
    }

    return applied;
}

static void themer_add_unique(uint64_t *items, int *count, int cap, uint64_t item)
{
    if (!r_is_objc_ptr(item) || !items || !count || *count >= cap) return;
    for (int i = 0; i < *count; i++) {
        if (items[i] == item) return;
    }
    items[(*count)++] = item;
}

/* Private SpringBoard selector names are not an ABI contract.  Every method
 * invoked by the bounded cache refresh is checked against the encoding
 * measured on 23A341 before it is called.  class_getInstanceMethod follows
 * inherited implementations, which is required for the App Library
 * subclasses used by this build. */
static bool themer_springboard_method_encoding_is(uint64_t object,
                                                  const char *selector,
                                                  const char *expected)
{
    if (!r_is_objc_ptr(object) || !selector || !expected ||
        !remote_call_current_success()) return false;
    uint64_t cls = r_dlsym_call(R_TIMEOUT, "object_getClass", object,
                                0, 0, 0, 0, 0, 0, 0);
    uint64_t sel = r_sel(selector);
    uint64_t method = r_is_objc_ptr(cls) && sel
        ? r_dlsym_call(R_TIMEOUT, "class_getInstanceMethod", cls, sel,
                       0, 0, 0, 0, 0, 0)
        : 0;
    uint64_t typeCString = method
        ? r_dlsym_call(R_TIMEOUT, "method_getTypeEncoding", method,
                       0, 0, 0, 0, 0, 0, 0)
        : 0;
    char observed[96] = {0};
    bool accepted = typeCString &&
        themer_store_surface_read_cstring(typeCString, observed,
                                          sizeof(observed)) &&
        strcmp(observed, expected) == 0;
    if (!accepted) {
        char className[96] = {0};
        themer_read_class_name(object, className, sizeof(className));
        printf("[SBR_ABI] class=%s selector=%s observed=%s expected=%s "
               "accepted=0\n",
               className[0] ? className : "-", selector,
               observed[0] ? observed : "-", expected);
    }
    return accepted && remote_call_current_success();
}

static bool themer_pointer_is_covered(uint64_t pointer, uint64_t resetCache,
                                      const uint64_t *purged, int purgedCount)
{
    if (!r_is_objc_ptr(pointer)) return false;
    if (pointer == resetCache) return true;
    for (int index = 0; index < purgedCount; index++) {
        if (purged[index] == pointer) return true;
    }
    return false;
}

static int themer_collect_model_lookup_roots(uint64_t *roots, int cap)
{
    if (!roots || cap <= 0) return 0;
    int count = 0;

    uint64_t controllerCls = r_class("SBIconController");
    uint64_t controller = (r_is_objc_ptr(controllerCls) &&
                           r_responds(controllerCls, "sharedInstance"))
        ? r_msg2(controllerCls, "sharedInstance", 0, 0, 0, 0) : 0;
    themer_add_unique(roots, &count, cap, controller);

    uint64_t managerCls = r_class("SBHIconManager");
    uint64_t manager = (r_is_objc_ptr(managerCls) &&
                        r_responds(managerCls, "sharedInstance"))
        ? r_msg2(managerCls, "sharedInstance", 0, 0, 0, 0) : 0;
    themer_add_unique(roots, &count, cap, manager);

    const char *childSels[] = {
        "model",
        "iconModel",
        "_iconModel",
        "iconManager",
        "_iconManager",
        "rootFolder",
        "rootFolderController",
        "rootFolderViewController",
    };
    int initial = count;
    for (int i = 0; i < initial && count < cap; i++) {
        uint64_t root = roots[i];
        for (size_t s = 0; s < sizeof(childSels) / sizeof(childSels[0]) && count < cap; s++) {
            if (!r_responds_main(root, childSels[s])) continue;
            uint64_t child = r_msg2_main(root, childSels[s], 0, 0, 0, 0);
            themer_add_unique(roots, &count, cap, child);
        }
    }

    return count;
}

static uint64_t themer_lookup_model_icon_for_bundle_with_roots(const char *bundle,
                                                               const uint64_t *roots,
                                                               int rootCount)
{
    if (!bundle || !bundle[0] || !roots || rootCount <= 0) return 0;

    uint64_t bid = r_nsstr_retained(bundle);
    if (!r_is_objc_ptr(bid)) return 0;

    const char *lookupSels[] = {
        "applicationIconForBundleIdentifier:",
        "applicationIconForDisplayIdentifier:",
        "expectedIconForDisplayIdentifier:",
        "iconForApplicationIdentifier:",
        "iconForIdentifier:",
        "leafIconForIdentifier:",
        "_leafIconForIdentifier:",
        "iconWithIdentifier:",
    };

    static bool loggedShape = false;
    uint64_t found = 0;
    const char *foundSel = NULL;
    uint64_t foundRoot = 0;
    static int mismatchLogs = 0;
    for (int r = 0; r < rootCount && !found; r++) {
        uint64_t root = roots[r];
        for (size_t s = 0; s < sizeof(lookupSels) / sizeof(lookupSels[0]); s++) {
            const char *sel = lookupSels[s];
            if (!r_responds_main(root, sel)) continue;
            uint64_t icon = r_msg2_main(root, sel, bid, 0, 0, 0);
            if (!r_is_objc_ptr(icon)) continue;

            char actual[128] = {0};
            if (!themer_read_bundle_for_icon(icon, 0, actual, sizeof(actual)) ||
                strcmp(actual, bundle) != 0) {
                if (mismatchLogs < 8) {
                    printf("[THEMER] model lookup rejected requested=%s actual=%s "
                           "root=0x%llx selector=%s icon=0x%llx\n",
                           bundle,
                           actual[0] ? actual : "?",
                           (unsigned long long)root,
                           sel,
                           (unsigned long long)icon);
                    mismatchLogs++;
                }
                continue;
            }

            found = icon;
            foundSel = sel;
            foundRoot = root;
            break;
        }
    }
    r_msg2(bid, "release", 0, 0, 0, 0);

    if (!loggedShape) {
        loggedShape = true;
        printf("[THEMER] model lookup probe roots=%d firstBundle=%s root=0x%llx "
               "selector=%s icon=0x%llx\n",
               rootCount,
               bundle,
               (unsigned long long)foundRoot,
               foundSel ?: "(none)",
               (unsigned long long)found);
    }

    if (r_is_objc_ptr(found)) {
        themer_cache_icon_bundle(found, bundle);
    }

    return found;
}

static uint64_t themer_lookup_model_icon_for_bundle(const char *bundle)
{
    enum { ROOT_CAP = 24 };
    uint64_t roots[ROOT_CAP] = {0};
    int rootCount = themer_collect_model_lookup_roots(roots, ROOT_CAP);
    return themer_lookup_model_icon_for_bundle_with_roots(bundle, roots, rootCount);
}

static NSDictionary<NSString *, id> *
themer_springboard_consumer_icon_snapshot(uint64_t icon)
{
    if (!r_is_objc_ptr(icon)) return @{};
    char className[96] = {0};
    char bundle[192] = {0};
    themer_read_class_name(icon, className, sizeof(className));
    BOOL bundleKnown = themer_read_bundle_for_icon(
        icon, 0, bundle, sizeof(bundle));
    BOOL generationKnown = r_responds_main(icon, "imageGeneration");
    uint64_t generation = generationKnown
        ? r_msg2_main(icon, "imageGeneration", 0, 0, 0, 0) : 0;
    uint64_t layerViews = r_ivar_value(icon, "_iconLayerViews");
    uint64_t observers = r_ivar_value(icon, "_observers");
    return @{
        @"pointer": @(icon),
        @"class": className[0]
            ? ([NSString stringWithUTF8String:className] ?: @"") : @"",
        @"bundleIdentifier": bundleKnown && bundle[0]
            ? ([NSString stringWithUTF8String:bundle] ?: @"") : @"",
        @"imageGenerationKnown": @(generationKnown),
        @"imageGeneration": @(generation),
        @"layerViewCount": @(themer_remote_count(layerViews)),
        @"observerCount": @(themer_remote_count(observers)),
    };
}

NSDictionary<NSString *, id> *
themer_audit_springboard_iconservices_consumers_in_session(
    NSArray<NSString *> *bundleIdentifiers)
{
    if (!remote_call_current_success()) {
        return @{
            @"ok": @NO,
            @"stage": @"transport",
            @"message": @"The SpringBoard audit has no healthy RemoteCall session.",
        };
    }

    NSMutableOrderedSet<NSString *> *ordered =
        [NSMutableOrderedSet orderedSet];
    for (id value in bundleIdentifiers ?: @[]) {
        if (![value isKindOfClass:NSString.class]) continue;
        NSString *identifier = [(NSString *)value
            stringByTrimmingCharactersInSet:
                NSCharacterSet.whitespaceAndNewlineCharacterSet];
        if (identifier.length > 0) [ordered addObject:identifier];
    }
    NSArray<NSString *> *targets = ordered.array;
    if (targets.count == 0 || targets.count > 512) {
        return @{
            @"ok": @NO,
            @"stage": @"input",
            @"message": @"The SpringBoard audit requires 1-512 journaled bundle identifiers.",
            @"targetCount": @(targets.count),
        };
    }

    uint32_t previousSettleUS = r_settle_us(0);
    NSMutableSet<NSString *> *targetSet = [NSMutableSet setWithArray:targets];
    NSMutableDictionary<NSString *, NSMutableDictionary *> *byBundle =
        [NSMutableDictionary dictionaryWithCapacity:targets.count];
    for (NSString *identifier in targets) {
        byBundle[identifier] = [@{
            @"bundleIdentifier": identifier,
            @"canonical": @{},
            @"leafIcons": [NSMutableArray array],
            @"switcherItems": [NSMutableArray array],
        } mutableCopy];
    }

    enum { ROOT_CAP = 24 };
    uint64_t roots[ROOT_CAP] = {0};
    int rootCount = themer_collect_model_lookup_roots(roots, ROOT_CAP);
    uint64_t iconModel = 0;
    for (int index = 0;
         index < rootCount && remote_call_current_success(); index++) {
        char className[96] = {0};
        themer_read_class_name(roots[index], className, sizeof(className));
        if ((!strcmp(className, "SBHIconModel") ||
             !strcmp(className, "SBIconModel")) &&
            r_responds_main(roots[index],
                            "applicationIconForBundleIdentifier:")) {
            iconModel = roots[index];
            break;
        }
    }

    if (r_is_objc_ptr(iconModel)) {
        for (NSString *identifier in targets) {
            uint64_t remoteIdentifier =
                r_nsstr_retained(identifier.UTF8String);
            uint64_t icon = remoteIdentifier
                ? r_msg2_main(
                    iconModel, "applicationIconForBundleIdentifier:",
                    remoteIdentifier, 0, 0, 0)
                : 0;
            if (remoteIdentifier && remote_call_current_success()) {
                r_msg2(remoteIdentifier, "release", 0, 0, 0, 0);
            }
            if (!remote_call_current_success()) break;
            byBundle[identifier][@"canonical"] =
                themer_springboard_consumer_icon_snapshot(icon);
        }

        uint64_t leafCollection = r_responds_main(
            iconModel, "leafIconsUniquedByApplicationBundleIdentifier")
            ? r_msg2_main(
                iconModel,
                "leafIconsUniquedByApplicationBundleIdentifier",
                0, 0, 0, 0)
            : 0;
        uint64_t leafObjects = 0;
        if (r_is_objc_ptr(leafCollection) &&
            r_responds_main(leafCollection, "allValues")) {
            leafObjects = r_msg2_main(
                leafCollection, "allValues", 0, 0, 0, 0);
        } else if (r_is_objc_ptr(leafCollection) &&
                   r_responds_main(leafCollection, "allObjects")) {
            leafObjects = r_msg2_main(
                leafCollection, "allObjects", 0, 0, 0, 0);
        }
        uint64_t leafCount = themer_remote_count(leafObjects);
        uint64_t boundedLeafCount = MIN(leafCount, (uint64_t)2048);
        for (uint64_t index = 0;
             index < boundedLeafCount && remote_call_current_success();
             index++) {
            uint64_t icon = r_msg2_main(
                leafObjects, "objectAtIndex:", index, 0, 0, 0);
            char bundle[192] = {0};
            if (!themer_read_bundle_for_icon(
                    icon, 0, bundle, sizeof(bundle)) || !bundle[0]) continue;
            NSString *identifier = [NSString stringWithUTF8String:bundle];
            if (![targetSet containsObject:identifier]) continue;
            NSMutableArray *reports = byBundle[identifier][@"leafIcons"];
            [reports addObject:
                themer_springboard_consumer_icon_snapshot(icon)];
        }
    }

    uint64_t applicationClass = themer_lookup_class("UIApplication");
    uint64_t springBoardApplication = applicationClass &&
        r_responds(applicationClass, "sharedApplication")
        ? r_msg2(applicationClass, "sharedApplication", 0, 0, 0, 0) : 0;
    uint64_t switcherController = springBoardApplication &&
        r_responds_main(springBoardApplication, "_switcherController")
        ? r_msg2_main(springBoardApplication, "_switcherController",
                      0, 0, 0, 0) : 0;
    uint64_t switcherViewController = switcherController &&
        themer_springboard_method_encoding_is(
            switcherController, "contentViewController", "@16@0:8")
        ? r_msg2_main(switcherController, "contentViewController",
                      0, 0, 0, 0) : 0;
    uint64_t titleControllerMap = switcherViewController
        ? r_ivar_value(switcherViewController,
                       "_appLayoutToTitleItemController") : 0;
    if (!r_is_objc_ptr(titleControllerMap) && switcherController &&
        themer_springboard_method_encoding_is(
            switcherController, "switcherViewController", "@16@0:8")) {
        uint64_t wrapper = r_msg2_main(
            switcherController, "switcherViewController", 0, 0, 0, 0);
        uint64_t fallbackMap = r_is_objc_ptr(wrapper)
            ? r_ivar_value(wrapper, "_appLayoutToTitleItemController") : 0;
        if (r_is_objc_ptr(fallbackMap)) {
            switcherViewController = wrapper;
            titleControllerMap = fallbackMap;
        }
    }
    uint64_t titleControllers = 0;
    if (titleControllerMap &&
        r_responds_main(titleControllerMap, "allValues")) {
        titleControllers = r_msg2_main(
            titleControllerMap, "allValues", 0, 0, 0, 0);
    } else if (titleControllerMap &&
               r_responds_main(titleControllerMap, "objectEnumerator")) {
        uint64_t enumerator = r_msg2_main(
            titleControllerMap, "objectEnumerator", 0, 0, 0, 0);
        titleControllers = enumerator &&
            r_responds_main(enumerator, "allObjects")
            ? r_msg2_main(enumerator, "allObjects", 0, 0, 0, 0) : 0;
    }
    uint64_t titleControllerCount = themer_remote_count(titleControllers);
    uint64_t boundedTitleCount = MIN(titleControllerCount, (uint64_t)256);
    for (uint64_t controllerIndex = 0;
         controllerIndex < boundedTitleCount &&
         remote_call_current_success(); controllerIndex++) {
        uint64_t controller = r_msg2_main(
            titleControllers, "objectAtIndex:",
            controllerIndex, 0, 0, 0);
        if (!r_is_objc_ptr(controller)) continue;
        uint64_t displayItems = r_ivar_value(controller, "_displayItems");
        uint64_t displayItemToIcon =
            r_ivar_value(controller, "_displayItemToIcon");
        uint64_t displayItemCount = themer_remote_count(displayItems);
        uint64_t boundedDisplayCount = MIN(displayItemCount, (uint64_t)16);
        for (uint64_t itemIndex = 0;
             itemIndex < boundedDisplayCount &&
             remote_call_current_success(); itemIndex++) {
            uint64_t displayItem = r_msg2_main(
                displayItems, "objectAtIndex:", itemIndex, 0, 0, 0);
            uint64_t bundleObject = displayItem &&
                r_responds_main(displayItem, "bundleIdentifier")
                ? r_msg2_main(displayItem, "bundleIdentifier",
                              0, 0, 0, 0) : 0;
            char bundle[192] = {0};
            if (!bundleObject ||
                !r_read_nsstring(bundleObject, bundle, sizeof(bundle)) ||
                !bundle[0]) continue;
            NSString *identifier = [NSString stringWithUTF8String:bundle];
            if (![targetSet containsObject:identifier]) continue;
            uint64_t icon = displayItemToIcon &&
                r_responds_main(displayItemToIcon, "objectForKey:")
                ? r_msg2_main(displayItemToIcon, "objectForKey:",
                              displayItem, 0, 0, 0) : 0;
            NSDictionary *iconReport =
                themer_springboard_consumer_icon_snapshot(icon);
            NSNumber *canonicalPointer =
                byBundle[identifier][@"canonical"][@"pointer"];
            BOOL matchesLeaf = NO;
            for (NSDictionary *leaf in
                 byBundle[identifier][@"leafIcons"]) {
                if ([leaf[@"pointer"] unsignedLongLongValue] == icon && icon) {
                    matchesLeaf = YES;
                    break;
                }
            }
            NSMutableArray *switcherItems =
                byBundle[identifier][@"switcherItems"];
            [switcherItems addObject:@{
                @"controllerPointer": @(controller),
                @"displayItemPointer": @(displayItem),
                @"icon": iconReport,
                @"matchesCanonical": @(
                    icon && canonicalPointer.unsignedLongLongValue == icon),
                @"matchesLeaf": @(matchesLeaf),
            }];
        }
    }

    NSMutableArray<NSDictionary *> *applications =
        [NSMutableArray arrayWithCapacity:targets.count];
    for (NSString *identifier in targets) {
        NSMutableDictionary *entry = byBundle[identifier];
        NSArray *leaves = entry[@"leafIcons"];
        NSArray *switcherItems = entry[@"switcherItems"];
        NSDictionary *canonical = entry[@"canonical"];
        NSDictionary *firstLeaf = leaves.firstObject ?: @{};
        NSDictionary *firstSwitcher = switcherItems.firstObject ?: @{};
        NSDictionary *firstSwitcherIcon =
            [firstSwitcher[@"icon"] isKindOfClass:NSDictionary.class]
                ? firstSwitcher[@"icon"] : @{};
        log_user("[SBR_AUDIT_CONSUMER] app=%s canonical=0x%llx generation=%llu "
                 "layers=%llu observers=%llu leaves=%lu first-leaf=0x%llx "
                 "first-leaf-generation=%llu switcher-items=%lu "
                 "first-switcher-icon=0x%llx first-switcher-generation=%llu "
                 "switcher-matches-canonical=%s switcher-matches-leaf=%s\n",
                 identifier.UTF8String ?: "?",
                 (unsigned long long)[canonical[@"pointer"]
                     unsignedLongLongValue],
                 (unsigned long long)[canonical[@"imageGeneration"]
                     unsignedLongLongValue],
                 (unsigned long long)[canonical[@"layerViewCount"]
                     unsignedLongLongValue],
                 (unsigned long long)[canonical[@"observerCount"]
                     unsignedLongLongValue],
                 (unsigned long)leaves.count,
                 (unsigned long long)[firstLeaf[@"pointer"]
                     unsignedLongLongValue],
                 (unsigned long long)[firstLeaf[@"imageGeneration"]
                     unsignedLongLongValue],
                 (unsigned long)switcherItems.count,
                 (unsigned long long)[firstSwitcherIcon[@"pointer"]
                     unsignedLongLongValue],
                 (unsigned long long)[firstSwitcherIcon[@"imageGeneration"]
                     unsignedLongLongValue],
                 [firstSwitcher[@"matchesCanonical"] boolValue]
                     ? "yes" : "no",
                 [firstSwitcher[@"matchesLeaf"] boolValue]
                     ? "yes" : "no");
        [applications addObject:[entry copy]];
    }

    BOOL remoteOK = remote_call_current_success();
    (void)r_settle_us(previousSettleUS);
    return @{
        @"ok": @(remoteOK && r_is_objc_ptr(iconModel)),
        @"stage": remoteOK && r_is_objc_ptr(iconModel)
            ? @"audited" : @"springboard-consumer-audit",
        @"message": remoteOK && r_is_objc_ptr(iconModel)
            ? @"SpringBoard canonical, leaf, and materialized switcher icon identities were inspected without refresh or mutation."
            : @"SpringBoard consumer identities could not be inspected safely.",
        @"targetCount": @(targets.count),
        @"modelPointer": @(iconModel),
        @"switcherViewControllerPointer": @(switcherViewController),
        @"titleControllerCount": @(titleControllerCount),
        @"applications": applications,
        @"mutationsIssued": @NO,
        @"reloadIssued": @NO,
        @"cachePurgeIssued": @NO,
        @"updateHandlerIssued": @NO,
    };
}

NSDictionary<NSString *, id> *
themer_inspect_springboard_app_library_miniature_pipeline_in_session(void)
{
    typedef struct {
        CGSize size;
        double scale;
        double continuousCornerRadius;
    } CNDLibraryIconImageInfo;
    _Static_assert(sizeof(CNDLibraryIconImageInfo) == 32,
                   "SBIconImageInfo ABI changed");

    if (!remote_call_current_success()) {
        return @{
            @"ok": @NO,
            @"stage": @"transport",
            @"message": @"The SpringBoard RemoteCall transport was not healthy.",
            @"readOnly": @YES,
            @"processLifecycleMutationCount": @0,
            @"sharedCacheWriteCount": @0,
        };
    }

    uint32_t previousSettleUS = r_settle_us(0);
    enum { ROOT_CAP = 24, SAMPLE_CAP = 8 };
    uint64_t roots[ROOT_CAP] = {0};
    int rootCount = themer_collect_model_lookup_roots(roots, ROOT_CAP);
    uint64_t iconManager = 0;
    uint64_t iconModel = 0;
    for (int index = 0;
         index < rootCount && remote_call_current_success(); index++) {
        char className[96] = {0};
        themer_read_class_name(roots[index], className, sizeof(className));
        if (!iconManager && !strcmp(className, "SBHIconManager")) {
            iconManager = roots[index];
        }
        if (!iconModel &&
            (!strcmp(className, "SBHIconModel") ||
             !strcmp(className, "SBIconModel")) &&
            themer_springboard_method_encoding_is(
                roots[index], "applicationIconForBundleIdentifier:",
                "@24@0:8@16")) {
            iconModel = roots[index];
        }
    }

    uint64_t libraryController = 0;
    const char *controllerRoute = NULL;
    static const char *controllerSelectors[] = {
        "trailingLibraryViewController",
        "overlayLibraryViewController",
    };
    if (r_is_objc_ptr(iconManager)) {
        for (size_t index = 0;
             index < sizeof(controllerSelectors) /
                         sizeof(controllerSelectors[0]); index++) {
            const char *selector = controllerSelectors[index];
            if (!themer_springboard_method_encoding_is(
                    iconManager, selector, "@16@0:8")) continue;
            uint64_t candidate = r_msg2_main(
                iconManager, selector, 0, 0, 0, 0);
            if (!r_is_objc_ptr(candidate)) continue;
            libraryController = candidate;
            controllerRoute = selector;
            break;
        }
    }

    uint64_t folderImageCache = 0;
    uint64_t listLayout = 0;
    uint64_t visualConfiguration = 0;
    uint64_t appearance = 0;
    uint64_t traitCollection = 0;
    uint64_t folderCacheClass = themer_lookup_class(
        "SBFolderIconImageCache");
    uint64_t traitCollectionClass = themer_lookup_class(
        "UITraitCollection");
    CNDLibraryIconImageInfo iconImageInfo = {0};
    CGSize gridCellSize = CGSizeZero;

    BOOL preflightOK = r_is_objc_ptr(iconManager) &&
        r_is_objc_ptr(iconModel) && r_is_objc_ptr(libraryController) &&
        themer_springboard_method_encoding_is(
            libraryController, "folderIconImageCache", "@16@0:8") &&
        themer_springboard_method_encoding_is(
            libraryController, "effectiveIconImageAppearance", "@16@0:8");
    if (preflightOK) {
        folderImageCache = r_msg2_main(
            libraryController, "folderIconImageCache", 0, 0, 0, 0);
        appearance = r_msg2_main(
            libraryController, "effectiveIconImageAppearance", 0, 0, 0, 0);
        char cacheClassName[96] = {0};
        themer_read_class_name(folderImageCache, cacheClassName,
                               sizeof(cacheClassName));
        preflightOK = !strcmp(cacheClassName, "SBFolderIconImageCache") &&
            r_is_objc_ptr(appearance) &&
            themer_springboard_method_encoding_is(
                folderImageCache, "listLayout", "@16@0:8");
    }
    if (preflightOK) {
        listLayout = r_msg2_main(
            folderImageCache, "listLayout", 0, 0, 0, 0);
        preflightOK = r_is_objc_ptr(listLayout) &&
            themer_springboard_method_encoding_is(
                listLayout, "iconImageInfo",
                "{SBIconImageInfo={CGSize=dd}dd}16@0:8") &&
            themer_springboard_method_encoding_is(
                listLayout, "folderIconVisualConfiguration", "@16@0:8");
    }
    if (preflightOK) {
        preflightOK = r_msg2_main_struct_ret(
            listLayout, "iconImageInfo", &iconImageInfo,
            sizeof(iconImageInfo), NULL, 0, NULL, 0, NULL, 0, NULL, 0);
        visualConfiguration = preflightOK ? r_msg2_main(
            listLayout, "folderIconVisualConfiguration", 0, 0, 0, 0) : 0;
        preflightOK = preflightOK && r_is_objc_ptr(visualConfiguration) &&
            themer_springboard_method_encoding_is(
                visualConfiguration, "gridCellSize",
                "{CGSize=dd}16@0:8") &&
            r_msg2_main_struct_ret(
                visualConfiguration, "gridCellSize", &gridCellSize,
                sizeof(gridCellSize), NULL, 0, NULL, 0,
                NULL, 0, NULL, 0);
    }
    if (preflightOK) {
        preflightOK = iconImageInfo.size.width > 0.0 &&
            iconImageInfo.size.height > 0.0 &&
            iconImageInfo.scale >= 1.0 && iconImageInfo.scale <= 4.0 &&
            gridCellSize.width > 0.0 && gridCellSize.height > 0.0 &&
            r_is_objc_ptr(folderCacheClass) &&
            r_is_objc_ptr(traitCollectionClass) &&
            themer_springboard_method_encoding_is(
                traitCollectionClass,
                "sbh_traitCollectionWithIconImageAppearance:",
                "@24@0:8@16") &&
            themer_springboard_method_encoding_is(
                folderCacheClass, "gridCellImageOfSize:forIconImage:",
                "@40@0:8{CGSize=dd}16@32");
    }
    if (preflightOK) {
        traitCollection = r_msg2_main(
            traitCollectionClass,
            "sbh_traitCollectionWithIconImageAppearance:",
            appearance, 0, 0, 0);
        preflightOK = r_is_objc_ptr(traitCollection) &&
            remote_call_current_success();
    }

    printf("[SBR_LIBRARY_PIPELINE] stage=preflight roots=%d "
           "manager=%#llx model=%#llx controller=%#llx route=%s "
           "cache=%#llx layout=%#llx appearance=%#llx trait=%#llx "
           "icon=%.2fx%.2f@%.2f/r%.2f cell=%.2fx%.2f ok=%d\n",
           rootCount, (unsigned long long)iconManager,
           (unsigned long long)iconModel,
           (unsigned long long)libraryController,
           controllerRoute ?: "-",
           (unsigned long long)folderImageCache,
           (unsigned long long)listLayout,
           (unsigned long long)appearance,
           (unsigned long long)traitCollection,
           iconImageInfo.size.width, iconImageInfo.size.height,
           iconImageInfo.scale, iconImageInfo.continuousCornerRadius,
           gridCellSize.width, gridCellSize.height, preflightOK);

    NSMutableOrderedSet<NSString *> *candidateSet =
        [NSMutableOrderedSet orderedSetWithArray:@[
            @"com.apple.MobileSMS",
            @"com.toyopagroup.picaboo",
            @"com.zhiliaoapp.musically",
            @"com.8bit.bitwarden",
        ]];
    for (NSString *identifier in
             themer_springboard_refresh_bundle_identifiers_snapshot()) {
        if (candidateSet.count >= SAMPLE_CAP) break;
        if ([identifier isKindOfClass:NSString.class] &&
            identifier.length > 0) {
            [candidateSet addObject:identifier];
        }
    }

    NSMutableArray<NSDictionary<NSString *, id> *> *samples =
        [NSMutableArray array];
    NSUInteger attempted = 0;
    NSUInteger associatedSources = 0;
    NSUInteger sourceBaked = 0;
    NSUInteger compositorAddsPlate = 0;
    NSUInteger alphaPreserved = 0;
    NSUInteger inconclusive = 0;
    uint64_t sourceSelector = r_sel(
        "iconImageWithInfo:traitCollection:options:");
    for (NSString *identifier in candidateSet) {
        if (!preflightOK || !remote_call_current_success() ||
            attempted >= SAMPLE_CAP) break;
        attempted++;
        uint64_t icon = themer_lookup_model_icon_for_bundle_with_roots(
            identifier.UTF8String, roots, rootCount);
        if (!r_is_objc_ptr(icon)) {
            [samples addObject:@{
                @"bundleIdentifier": identifier,
                @"ok": @NO,
                @"stage": @"icon-not-found",
            }];
            continue;
        }

        uint64_t sourceImage = sourceSelector
            ? r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                           icon, sourceSelector, 0, 0, 0, 0, 0, 0)
            : 0;
        NSString *sourceRoute = @"associated-themed-image";
        if (r_is_objc_ptr(sourceImage)) {
            associatedSources++;
        } else if (themer_springboard_method_encoding_is(
                       icon,
                       "iconImageWithInfo:traitCollection:options:",
                       "@64@0:8{SBIconImageInfo={CGSize=dd}dd}16@48Q56")) {
            uint64_t traitArgument = traitCollection;
            uint64_t options = 1;
            sourceImage = r_msg2_main_raw(
                icon, "iconImageWithInfo:traitCollection:options:",
                &iconImageInfo, sizeof(iconImageInfo),
                &traitArgument, sizeof(traitArgument),
                &options, sizeof(options), NULL, 0);
            sourceRoute = @"stock-iconImageWithInfo";
        }
        if (!r_is_objc_ptr(sourceImage) ||
            r_msg2(sourceImage, "retain", 0, 0, 0, 0) != sourceImage) {
            [samples addObject:@{
                @"bundleIdentifier": identifier,
                @"ok": @NO,
                @"stage": @"source-image",
                @"sourceRoute": sourceRoute,
            }];
            continue;
        }

        uint64_t sourceArgument = sourceImage;
        uint64_t compositedImage = r_msg2_main_raw(
            folderCacheClass, "gridCellImageOfSize:forIconImage:",
            &gridCellSize, sizeof(gridCellSize),
            &sourceArgument, sizeof(sourceArgument),
            NULL, 0, NULL, 0);
        if (r_is_objc_ptr(compositedImage) &&
            r_msg2(compositedImage, "retain", 0, 0, 0, 0) !=
                compositedImage) {
            compositedImage = 0;
        }

        NSMutableDictionary<NSString *, id> *sample = [@{
            @"bundleIdentifier": identifier,
            @"sourceRoute": sourceRoute,
            @"sourcePointer": @(sourceImage),
            @"compositedPointer": @(compositedImage),
        } mutableCopy];
        NSData *sourcePNG = nil;
        NSData *compositedPNG = nil;
        if (r_is_objc_ptr(compositedImage)) {
            uint64_t sourceData = r_dlsym_call(
                R_TIMEOUT, "UIImagePNGRepresentation", sourceImage,
                0, 0, 0, 0, 0, 0, 0);
            uint64_t outputData = r_dlsym_call(
                R_TIMEOUT, "UIImagePNGRepresentation", compositedImage,
                0, 0, 0, 0, 0, 0, 0);
            if (r_is_objc_ptr(sourceData)) {
                (void)r_msg2(sourceData, "retain", 0, 0, 0, 0);
                uint64_t length = r_msg2(sourceData, "length", 0, 0, 0, 0);
                uint64_t bytes = length > 0 && length <= (8U << 20)
                    ? r_msg2(sourceData, "bytes", 0, 0, 0, 0) : 0;
                NSMutableData *copy = bytes
                    ? [NSMutableData dataWithLength:(NSUInteger)length] : nil;
                if (copy && remote_read(bytes, copy.mutableBytes,
                                        (size_t)length)) {
                    sourcePNG = [copy copy];
                }
                if (remote_call_current_success())
                    (void)r_msg2(sourceData, "release", 0, 0, 0, 0);
            }
            if (r_is_objc_ptr(outputData)) {
                (void)r_msg2(outputData, "retain", 0, 0, 0, 0);
                uint64_t length = r_msg2(outputData, "length", 0, 0, 0, 0);
                uint64_t bytes = length > 0 && length <= (8U << 20)
                    ? r_msg2(outputData, "bytes", 0, 0, 0, 0) : 0;
                NSMutableData *copy = bytes
                    ? [NSMutableData dataWithLength:(NSUInteger)length] : nil;
                if (copy && remote_read(bytes, copy.mutableBytes,
                                        (size_t)length)) {
                    compositedPNG = [copy copy];
                }
                if (remote_call_current_success())
                    (void)r_msg2(outputData, "release", 0, 0, 0, 0);
            }
        }

        NSDictionary<NSString *, id> *(^alphaMetrics)(NSData *) =
            ^NSDictionary<NSString *, id> *(NSData *png) {
                UIImage *image = png.length ? [UIImage imageWithData:png] : nil;
                CGImageRef cgImage = image.CGImage;
                size_t width = cgImage ? CGImageGetWidth(cgImage) : 0;
                size_t height = cgImage ? CGImageGetHeight(cgImage) : 0;
                if (!cgImage || width == 0 || height == 0 ||
                    width > 2048 || height > 2048 ||
                    width > SIZE_MAX / height || width * height > SIZE_MAX / 4) {
                    return @{};
                }
                size_t pixelCount = width * height;
                size_t bytesPerRow = width * 4;
                uint8_t *pixels = calloc(pixelCount, 4);
                CGColorSpaceRef colorSpace = CGColorSpaceCreateDeviceRGB();
                CGContextRef context = pixels && colorSpace
                    ? CGBitmapContextCreate(
                        pixels, width, height, 8, bytesPerRow, colorSpace,
                        kCGBitmapByteOrder32Big |
                            kCGImageAlphaPremultipliedLast)
                    : NULL;
                if (context) {
                    CGContextSetBlendMode(context, kCGBlendModeCopy);
                    CGContextDrawImage(
                        context, CGRectMake(0, 0, width, height), cgImage);
                }
                size_t clearCount = 0;
                size_t partialCount = 0;
                size_t opaqueCount = 0;
                size_t outerCount = 0;
                size_t outerOpaqueCount = 0;
                uint64_t alphaSum = 0;
                uint64_t outerAlphaSum = 0;
                size_t band = MAX((size_t)1, MIN(width, height) / 10);
                if (context) {
                    for (size_t y = 0; y < height; y++) {
                        for (size_t x = 0; x < width; x++) {
                            uint8_t alpha = pixels[(y * width + x) * 4 + 3];
                            alphaSum += alpha;
                            if (alpha <= 8) clearCount++;
                            else if (alpha >= 247) opaqueCount++;
                            else partialCount++;
                            BOOL outer = x < band || y < band ||
                                x >= width - band || y >= height - band;
                            if (outer) {
                                outerCount++;
                                outerAlphaSum += alpha;
                                if (alpha >= 247) outerOpaqueCount++;
                            }
                        }
                    }
                }
                uint8_t digest[CC_SHA256_DIGEST_LENGTH] = {0};
                CC_SHA256(png.bytes, (CC_LONG)png.length, digest);
                char sha[CC_SHA256_DIGEST_LENGTH * 2 + 1] = {0};
                for (size_t index = 0;
                     index < CC_SHA256_DIGEST_LENGTH; index++) {
                    snprintf(sha + index * 2, 3, "%02x", digest[index]);
                }
                NSDictionary *result = context ? @{
                    @"pixelWidth": @(width),
                    @"pixelHeight": @(height),
                    @"pngLength": @(png.length),
                    @"pngSHA256": [NSString stringWithUTF8String:sha],
                    @"clearFraction": @((double)clearCount /
                                         (double)pixelCount),
                    @"partialFraction": @((double)partialCount /
                                           (double)pixelCount),
                    @"opaqueFraction": @((double)opaqueCount /
                                          (double)pixelCount),
                    @"meanAlpha": @((double)alphaSum /
                                     (double)pixelCount / 255.0),
                    @"outerOpaqueFraction": @((double)outerOpaqueCount /
                                               (double)outerCount),
                    @"outerMeanAlpha": @((double)outerAlphaSum /
                                          (double)outerCount / 255.0),
                } : @{};
                if (context) CGContextRelease(context);
                if (colorSpace) CGColorSpaceRelease(colorSpace);
                free(pixels);
                return result;
            };

        NSDictionary<NSString *, id> *sourceMetrics =
            alphaMetrics(sourcePNG);
        NSDictionary<NSString *, id> *outputMetrics =
            alphaMetrics(compositedPNG);
        NSString *verdict = @"capture-incomplete";
        if (sourceMetrics.count && outputMetrics.count) {
            double sourceOpaque =
                [sourceMetrics[@"opaqueFraction"] doubleValue];
            double sourceClear =
                [sourceMetrics[@"clearFraction"] doubleValue];
            double sourcePartial =
                [sourceMetrics[@"partialFraction"] doubleValue];
            double sourceOuter =
                [sourceMetrics[@"outerOpaqueFraction"] doubleValue];
            double outputOpaque =
                [outputMetrics[@"opaqueFraction"] doubleValue];
            double outputOuter =
                [outputMetrics[@"outerOpaqueFraction"] doubleValue];
            double opaqueDelta = outputOpaque - sourceOpaque;
            double outerDelta = outputOuter - sourceOuter;
            double sourceTransparency = sourceClear + sourcePartial;
            sample[@"opaqueFractionDelta"] = @(opaqueDelta);
            sample[@"outerOpaqueFractionDelta"] = @(outerDelta);
            if (sourceOpaque >= 0.80 && sourceOuter >= 0.60 &&
                sourceTransparency <= 0.20) {
                verdict = @"source-baked-opaque";
                sourceBaked++;
            } else if (sourceTransparency >= 0.18 &&
                       opaqueDelta >= 0.12 && outerDelta >= 0.10) {
                verdict = @"compositor-adds-opaque-plate";
                compositorAddsPlate++;
            } else if (opaqueDelta > -0.06 && opaqueDelta < 0.06 &&
                       outerDelta > -0.06 && outerDelta < 0.06) {
                verdict = @"alpha-preserved";
                alphaPreserved++;
            } else {
                verdict = @"inconclusive";
                inconclusive++;
            }
            sample[@"ok"] = @YES;
            sample[@"stage"] = @"captured";
        } else {
            sample[@"ok"] = @NO;
            sample[@"stage"] = @"png-capture";
            inconclusive++;
        }
        sample[@"source"] = sourceMetrics;
        sample[@"composited"] = outputMetrics;
        sample[@"verdict"] = verdict;
        [samples addObject:sample];
        printf("[SBR_LIBRARY_PIPELINE] bundle=%s route=%s verdict=%s "
               "source-opaque=%.4f output-opaque=%.4f "
               "source-outer=%.4f output-outer=%.4f\n",
               identifier.UTF8String,
               sourceRoute.UTF8String,
               verdict.UTF8String,
               [sourceMetrics[@"opaqueFraction"] doubleValue],
               [outputMetrics[@"opaqueFraction"] doubleValue],
               [sourceMetrics[@"outerOpaqueFraction"] doubleValue],
               [outputMetrics[@"outerOpaqueFraction"] doubleValue]);

        if (r_is_objc_ptr(compositedImage) &&
            remote_call_current_success()) {
            (void)r_msg2(compositedImage, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(sourceImage) && remote_call_current_success()) {
            (void)r_msg2(sourceImage, "release", 0, 0, 0, 0);
        }
    }

    NSUInteger captured = 0;
    for (NSDictionary *sample in samples) {
        if ([sample[@"ok"] boolValue]) captured++;
    }
    BOOL remoteOK = remote_call_current_success();
    BOOL ok = preflightOK && remoteOK && captured > 0;
    NSString *message = nil;
    if (!preflightOK) {
        message = @"The exact live App Library image pipeline did not pass ABI and geometry preflight.";
    } else if (!remoteOK) {
        message = @"The source/compositor capture lost its bounded SpringBoard transport.";
    } else if (captured == 0) {
        message = @"No installed themed candidate produced a complete source/compositor capture.";
    } else if (compositorAddsPlate > 0 && sourceBaked == 0) {
        message = @"The captured source retained transparency and Apple's App Library compositor added the opaque plate.";
    } else if (sourceBaked > 0 && compositorAddsPlate == 0) {
        message = @"The captured source was already opaque before Apple's App Library compositor.";
    } else if (sourceBaked > 0 && compositorAddsPlate > 0) {
        message = @"The capture is mixed: some miniatures arrive opaque while Apple's compositor adds opacity to others.";
    } else {
        message = @"The capture completed, but its alpha change is not decisive; inspect the per-bundle metrics.";
    }
    printf("[SBR_LIBRARY_PIPELINE] result=%s attempted=%lu captured=%lu "
           "associated=%lu source-baked=%lu compositor-plate=%lu "
           "preserved=%lu inconclusive=%lu lifecycle=0 cache-mutations=0 "
           "shared-cache-writes=0\n",
           ok ? "complete" : "incomplete", (unsigned long)attempted,
           (unsigned long)captured, (unsigned long)associatedSources,
           (unsigned long)sourceBaked,
           (unsigned long)compositorAddsPlate,
           (unsigned long)alphaPreserved,
           (unsigned long)inconclusive);
    (void)r_settle_us(previousSettleUS);

    return @{
        @"ok": @(ok),
        @"stage": ok ? @"app-library-miniature-pipeline-inspected" :
            (preflightOK ? @"capture" : @"preflight"),
        @"message": message,
        @"readOnly": @YES,
        @"controllerRoute": controllerRoute
            ? [NSString stringWithUTF8String:controllerRoute] : @"",
        @"iconImageInfo": @{
            @"width": @(iconImageInfo.size.width),
            @"height": @(iconImageInfo.size.height),
            @"scale": @(iconImageInfo.scale),
            @"continuousCornerRadius":
                @(iconImageInfo.continuousCornerRadius),
        },
        @"gridCellSize": @{
            @"width": @(gridCellSize.width),
            @"height": @(gridCellSize.height),
        },
        @"attemptedCount": @(attempted),
        @"capturedCount": @(captured),
        @"associatedSourceCount": @(associatedSources),
        @"sourceBakedOpaqueCount": @(sourceBaked),
        @"compositorAddsOpaquePlateCount": @(compositorAddsPlate),
        @"alphaPreservedCount": @(alphaPreserved),
        @"inconclusiveCount": @(inconclusive),
        @"samples": samples,
        @"cachePurgeIssued": @NO,
        @"reloadIssued": @NO,
        @"relayoutIssued": @NO,
        @"updateHandlerIssued": @NO,
        @"processLifecycleMutationCount": @0,
        @"sharedCacheWriteCount": @0,
        @"remoteOK": @(remoteOK),
    };
}

NSDictionary<NSString *, id> *
themer_refresh_springboard_app_library_miniatures_in_session(void)
{
    if (!remote_call_current_success()) {
        return @{
            @"ok": @NO,
            @"stage": @"transport",
            @"message": @"The SpringBoard RemoteCall transport was not healthy.",
            @"mutationCount": @0,
            @"processLifecycleMutationCount": @0,
            @"sharedCacheWriteCount": @0,
        };
    }

    /* This is intentionally narrower than the production SpringBoard refresh
     * below. It repairs only stale App Library category miniatures. Resolve
     * and ABI-check the complete bounded object graph before sending the first
     * mutating message. */
    uint32_t previousSettleUS = r_settle_us(0);
    enum {
        ROOT_CAP = 24,
        LIBRARY_CONTROLLER_CAP = 2,
        LIBRARY_CACHE_CAP = 3,
        TARGET_BUNDLE_CAP = 512,
        LEAF_ICON_CAP = 1024,
        RELOAD_ICON_OBJECT_CAP = 1024,
    };
    uint64_t roots[ROOT_CAP] = {0};
    uint64_t libraryControllers[LIBRARY_CONTROLLER_CAP] = {0};
    uint64_t libraryFolderControllers[LIBRARY_CONTROLLER_CAP] = {0};
    uint64_t caches[LIBRARY_CACHE_CAP] = {0};
    int rootCount = themer_collect_model_lookup_roots(roots, ROOT_CAP);
    int libraryControllerCount = 0;
    int libraryFolderControllerCount = 0;
    int cacheCount = 0;
    uint64_t iconManager = 0;
    uint64_t iconModel = 0;
    uint64_t folderImageCache = 0;
    uint64_t folderSourceCache = 0;
    uint64_t reloadIconObjects[RELOAD_ICON_OBJECT_CAP] = {0};
    int reloadIconObjectCount = 0;
    int reloadCanonicalMatches = 0;
    int reloadLeafMatches = 0;
    int reloadLookupMisses = 0;
    uint64_t reloadLeafModelCount = 0;
    char iconManagerClass[96] = {0};
    char iconModelClass[96] = {0};
    char folderImageCacheClass[96] = {0};
    char folderSourceCacheClass[96] = {0};
    NSArray<NSString *> *configuredBundleIdentifiers =
        themer_springboard_refresh_bundle_identifiers_snapshot();
    NSMutableArray<NSString *> *reloadBundleIdentifiers =
        [NSMutableArray arrayWithCapacity:configuredBundleIdentifiers.count];
    NSMutableArray<NSString *> *ignoredNonApplicationTargets =
        [NSMutableArray array];
    for (NSString *identifier in configuredBundleIdentifiers) {
        /* AirDrop is intentionally journaled as an IconServices producer, but
         * it is not an installed application and has no SBApplicationIcon or
         * App Library category miniature. Ignore only this measured pseudo-
         * bundle; every other unresolved identity remains a hard preflight
         * failure. */
        if ([identifier isEqualToString:@"com.apple.Sharing.AirDrop"]) {
            [ignoredNonApplicationTargets addObject:identifier];
        } else {
            [reloadBundleIdentifiers addObject:identifier];
        }
    }
    NSMutableSet<NSString *> *reloadIdentifierSet =
        [NSMutableSet setWithArray:reloadBundleIdentifiers ?: @[]];
    NSMutableSet<NSString *> *matchedReloadIdentifiers =
        [NSMutableSet setWithCapacity:reloadIdentifierSet.count];
    BOOL reloadTargetsTruncated =
        reloadBundleIdentifiers.count > TARGET_BUNDLE_CAP;
    BOOL reloadLeafModelsTruncated = NO;
    BOOL preflightOK = remote_call_current_success();
    NSString *failure = nil;

    for (int index = 0;
         index < rootCount && remote_call_current_success(); index++) {
        uint64_t root = roots[index];
        char rootClass[96] = {0};
        themer_read_class_name(root, rootClass, sizeof(rootClass));
        if (!iconManager && !strcmp(rootClass, "SBHIconManager")) {
            iconManager = root;
            snprintf(iconManagerClass, sizeof(iconManagerClass), "%s",
                     rootClass);
        } else if (!iconModel &&
                   (!strcmp(rootClass, "SBHIconModel") ||
                    !strcmp(rootClass, "SBIconModel")) &&
                   r_responds_main(
                       root, "applicationIconForBundleIdentifier:")) {
            iconModel = root;
            snprintf(iconModelClass, sizeof(iconModelClass), "%s",
                     rootClass);
        }
    }
    if (!r_is_objc_ptr(iconManager) ||
        !themer_springboard_method_encoding_is(
            iconManager, "folderIconImageCache", "@16@0:8")) {
        preflightOK = NO;
        failure = @"The exact SBHIconManager folder-cache interface was unavailable.";
    }
    if (preflightOK &&
        (reloadBundleIdentifiers.count == 0 || reloadTargetsTruncated)) {
        preflightOK = NO;
        failure = reloadTargetsTruncated
            ? @"The configured themed bundle set exceeded the bounded miniature-repair limit."
            : @"No active themed bundle identifiers were configured for the miniature repair.";
    }
    if (preflightOK &&
        (!r_is_objc_ptr(iconModel) ||
         !themer_springboard_method_encoding_is(
             iconModel, "applicationIconForBundleIdentifier:",
             "@24@0:8@16") ||
         !themer_springboard_method_encoding_is(
             iconModel,
             "leafIconsUniquedByApplicationBundleIdentifier",
             "@16@0:8"))) {
        preflightOK = NO;
        failure = @"The exact SpringBoard icon-model lookup interfaces were unavailable.";
    }

    if (preflightOK) {
        folderImageCache = r_msg2_main(
            iconManager, "folderIconImageCache", 0, 0, 0, 0);
        themer_read_class_name(folderImageCache, folderImageCacheClass,
                               sizeof(folderImageCacheClass));
        if (strcmp(folderImageCacheClass, "SBFolderIconImageCache") ||
            !themer_springboard_method_encoding_is(
                folderImageCache, "iconImageCache", "@16@0:8") ||
            !themer_springboard_method_encoding_is(
                folderImageCache, "rebuildAllCachedFolderImages",
                "v16@0:8")) {
            preflightOK = NO;
            failure = @"The exact SBFolderIconImageCache rebuild interface was unavailable.";
        }
    }

    if (preflightOK) {
        folderSourceCache = r_msg2_main(
            folderImageCache, "iconImageCache", 0, 0, 0, 0);
        themer_read_class_name(folderSourceCache, folderSourceCacheClass,
                               sizeof(folderSourceCacheClass));
        if (strcmp(folderSourceCacheClass, "SBHIconImageCache") ||
            !themer_springboard_method_encoding_is(
                folderSourceCache, "purgeAllCachedImages", "v16@0:8")) {
            preflightOK = NO;
            failure = @"The retained folder-composite source cache did not match the proven ABI.";
        } else {
            themer_add_unique(caches, &cacheCount, LIBRARY_CACHE_CAP,
                              folderSourceCache);
        }
    }

    if (preflightOK) {
        const char *librarySelectors[] = {
            "trailingLibraryViewController",
            "overlayLibraryViewController",
        };
        for (size_t index = 0;
             index < sizeof(librarySelectors) / sizeof(librarySelectors[0]) &&
             remote_call_current_success(); index++) {
            if (!themer_springboard_method_encoding_is(
                    iconManager, librarySelectors[index], "@16@0:8")) {
                continue;
            }
            uint64_t controller = r_msg2_main(
                iconManager, librarySelectors[index], 0, 0, 0, 0);
            if (!r_is_objc_ptr(controller)) continue;

            int beforeCount = libraryControllerCount;
            themer_add_unique(libraryControllers,
                              &libraryControllerCount,
                              LIBRARY_CONTROLLER_CAP, controller);
            if (libraryControllerCount == beforeCount) continue;

            BOOL controllerABI =
                themer_springboard_method_encoding_is(
                    controller, "iconImageCache", "@16@0:8") &&
                themer_springboard_method_encoding_is(
                    controller, "folderController", "@16@0:8") &&
                themer_springboard_method_encoding_is(
                    controller, "_enqueueAppLibraryUpdate", "v16@0:8");
            uint64_t libraryCache = controllerABI
                ? r_msg2_main(controller, "iconImageCache", 0, 0, 0, 0)
                : 0;
            uint64_t folderController = controllerABI
                ? r_msg2_main(controller, "folderController", 0, 0, 0, 0)
                : 0;
            char libraryCacheClass[96] = {0};
            themer_read_class_name(libraryCache, libraryCacheClass,
                                   sizeof(libraryCacheClass));
            BOOL cacheABI = !strcmp(libraryCacheClass,
                                    "SBHIconImageCache") &&
                themer_springboard_method_encoding_is(
                    libraryCache, "purgeAllCachedImages", "v16@0:8");
            BOOL folderControllerABI =
                themer_springboard_method_encoding_is(
                    folderController, "_reloadAppIcons", "v16@0:8");
            if (!controllerABI || !cacheABI || !folderControllerABI) {
                preflightOK = NO;
                failure = @"An App Library controller did not match the proven cache/reload ABI.";
                break;
            }
            themer_add_unique(caches, &cacheCount, LIBRARY_CACHE_CAP,
                              libraryCache);
            themer_add_unique(libraryFolderControllers,
                              &libraryFolderControllerCount,
                              LIBRARY_CONTROLLER_CAP, folderController);
        }
    }

    /* Resolve every exact application object before the first cache mutation.
     * The category compositor can retain a source cache even after its outer
     * cache is purged, and SBApplicationIcon generation is the refill
     * boundary. Include both the canonical lookup and live model leaves so a
     * mounted category cannot keep an older generation through an alias. */
    if (preflightOK) {
        for (NSString *identifier in reloadBundleIdentifiers) {
            const char *bundle = identifier.UTF8String;
            uint64_t remoteIdentifier = bundle && bundle[0]
                ? r_nsstr_retained(bundle) : 0;
            uint64_t icon = r_is_objc_ptr(remoteIdentifier)
                ? r_msg2_main(
                    iconModel, "applicationIconForBundleIdentifier:",
                    remoteIdentifier, 0, 0, 0)
                : 0;
            if (r_is_objc_ptr(remoteIdentifier)) {
                r_msg2(remoteIdentifier, "release", 0, 0, 0, 0);
            }
            if (!remote_call_current_success()) break;

            char actual[192] = {0};
            BOOL exactIdentity = r_is_objc_ptr(icon) &&
                themer_read_bundle_for_icon(
                    icon, 0, actual, sizeof(actual)) &&
                bundle && !strcmp(actual, bundle);
            if (!exactIdentity) continue;
            [matchedReloadIdentifiers addObject:identifier];
            int beforeCount = reloadIconObjectCount;
            themer_add_unique(reloadIconObjects, &reloadIconObjectCount,
                              RELOAD_ICON_OBJECT_CAP, icon);
            if (reloadIconObjectCount > beforeCount) {
                reloadCanonicalMatches++;
            }
        }

        uint64_t leafCollection = remote_call_current_success()
            ? r_msg2_main(
                iconModel,
                "leafIconsUniquedByApplicationBundleIdentifier",
                0, 0, 0, 0)
            : 0;
        uint64_t leafObjects = 0;
        if (r_is_objc_ptr(leafCollection) &&
            r_responds_main(leafCollection, "allValues")) {
            leafObjects = r_msg2_main(
                leafCollection, "allValues", 0, 0, 0, 0);
        } else if (r_is_objc_ptr(leafCollection) &&
                   r_responds_main(leafCollection, "allObjects")) {
            leafObjects = r_msg2_main(
                leafCollection, "allObjects", 0, 0, 0, 0);
        }
        reloadLeafModelCount = r_is_objc_ptr(leafObjects) &&
            r_responds_main(leafObjects, "count")
                ? r_msg2_main(leafObjects, "count", 0, 0, 0, 0)
                : 0;
        reloadLeafModelsTruncated = reloadLeafModelCount > LEAF_ICON_CAP;
        uint64_t boundedLeafCount = reloadLeafModelsTruncated
            ? LEAF_ICON_CAP : reloadLeafModelCount;
        for (uint64_t index = 0;
             index < boundedLeafCount && remote_call_current_success();
             index++) {
            uint64_t icon = r_msg2_main(
                leafObjects, "objectAtIndex:", index, 0, 0, 0);
            if (!r_is_objc_ptr(icon)) continue;
            char actual[192] = {0};
            if (!themer_read_bundle_for_icon(
                    icon, 0, actual, sizeof(actual))) continue;
            NSString *identifier =
                [NSString stringWithUTF8String:actual];
            if (identifier.length == 0 ||
                ![reloadIdentifierSet containsObject:identifier]) {
                continue;
            }
            [matchedReloadIdentifiers addObject:identifier];
            int beforeCount = reloadIconObjectCount;
            themer_add_unique(reloadIconObjects, &reloadIconObjectCount,
                              RELOAD_ICON_OBJECT_CAP, icon);
            if (reloadIconObjectCount > beforeCount) reloadLeafMatches++;
        }

        reloadLookupMisses = (int)(
            reloadIdentifierSet.count > matchedReloadIdentifiers.count
                ? reloadIdentifierSet.count - matchedReloadIdentifiers.count
                : 0);
        BOOL reloadObjectsTruncated =
            reloadIconObjectCount >= RELOAD_ICON_OBJECT_CAP;
        if (reloadLeafModelsTruncated || reloadObjectsTruncated ||
            reloadLookupMisses > 0 || reloadIconObjectCount == 0) {
            preflightOK = NO;
            failure = reloadLeafModelsTruncated || reloadObjectsTruncated
                ? @"The bounded live icon-object inventory was truncated."
                : (reloadLookupMisses > 0
                    ? @"At least one active themed bundle had no exact SpringBoard icon identity."
                    : @"No exact themed SpringBoard icon objects were available to reload.");
        }
    }

    if (preflightOK) {
        for (int index = 0; index < reloadIconObjectCount; index++) {
            uint64_t icon = reloadIconObjects[index];
            BOOL exactReloadABI = themer_springboard_method_encoding_is(
                icon, "reloadIconImage", "v16@0:8");
            BOOL exactApplicationABI =
                themer_springboard_method_encoding_is(
                    icon, "isApplicationIcon", "B16@0:8");
            BOOL applicationIcon = exactApplicationABI &&
                ((r_msg2_main(
                    icon, "isApplicationIcon", 0, 0, 0, 0) & 0xff) != 0);
            if (!exactReloadABI || !applicationIcon ||
                !remote_call_current_success()) {
                preflightOK = NO;
                failure = @"A targeted icon did not match the proven SBApplicationIcon reload ABI.";
                break;
            }
        }
    }

    preflightOK = preflightOK && remote_call_current_success() &&
        libraryControllerCount > 0 &&
        libraryFolderControllerCount > 0 && cacheCount > 0;
    if (!preflightOK && !failure) {
        failure = @"No complete App Library category-controller graph was available.";
    }
    printf("[SBR_LIBRARY_MINI_REFRESH] stage=preflight roots=%d "
           "manager=0x%llx/%s model=0x%llx/%s folder=0x%llx/%s "
           "source=0x%llx/%s configured=%lu ignored=%lu targets=%lu "
           "objects=%d canonical=%d "
           "leaf=%d misses=%d controllers=%d folder-controllers=%d "
           "caches=%d ok=%d\n",
           rootCount, (unsigned long long)iconManager,
           iconManagerClass[0] ? iconManagerClass : "-",
           (unsigned long long)iconModel,
           iconModelClass[0] ? iconModelClass : "-",
           (unsigned long long)folderImageCache,
           folderImageCacheClass[0] ? folderImageCacheClass : "-",
           (unsigned long long)folderSourceCache,
           folderSourceCacheClass[0] ? folderSourceCacheClass : "-",
           (unsigned long)configuredBundleIdentifiers.count,
           (unsigned long)ignoredNonApplicationTargets.count,
           (unsigned long)reloadBundleIdentifiers.count,
           reloadIconObjectCount, reloadCanonicalMatches,
           reloadLeafMatches, reloadLookupMisses,
           libraryControllerCount, libraryFolderControllerCount,
           cacheCount, preflightOK);

    int cachesPurged = 0;
    int iconReloads = 0;
    int folderRebuilds = 0;
    int podReloads = 0;
    int updatesEnqueued = 0;
    if (preflightOK) {
        printf("[SBR_LIBRARY_MINI_REFRESH] stage=purge caches=%d\n",
               cacheCount);
        for (int index = 0;
             index < cacheCount && remote_call_current_success(); index++) {
            r_msg2_main(caches[index], "purgeAllCachedImages",
                        0, 0, 0, 0);
            if (remote_call_current_success()) cachesPurged++;
        }
    }
    if (preflightOK && cachesPurged == cacheCount &&
        remote_call_current_success()) {
        printf("[SBR_LIBRARY_MINI_REFRESH] stage=reload-themed-generations "
               "objects=%d\n", reloadIconObjectCount);
        for (int index = 0;
             index < reloadIconObjectCount &&
             remote_call_current_success(); index++) {
            r_msg2_main(reloadIconObjects[index], "reloadIconImage",
                        0, 0, 0, 0);
            if (remote_call_current_success()) iconReloads++;
        }
    }
    if (preflightOK && cachesPurged == cacheCount &&
        iconReloads == reloadIconObjectCount &&
        remote_call_current_success()) {
        printf("[SBR_LIBRARY_MINI_REFRESH] stage=rebuild-composites\n");
        r_msg2_main(folderImageCache, "rebuildAllCachedFolderImages",
                    0, 0, 0, 0);
        if (remote_call_current_success()) folderRebuilds = 1;
    }
    if (folderRebuilds == 1) {
        printf("[SBR_LIBRARY_MINI_REFRESH] stage=reload-pods count=%d\n",
               libraryFolderControllerCount);
        for (int index = 0;
             index < libraryFolderControllerCount &&
             remote_call_current_success(); index++) {
            r_msg2_main(libraryFolderControllers[index],
                        "_reloadAppIcons", 0, 0, 0, 0);
            if (remote_call_current_success()) podReloads++;
        }
    }
    if (podReloads == libraryFolderControllerCount &&
        folderRebuilds == 1) {
        printf("[SBR_LIBRARY_MINI_REFRESH] stage=enqueue-updates count=%d\n",
               libraryControllerCount);
        for (int index = 0;
             index < libraryControllerCount &&
             remote_call_current_success(); index++) {
            r_msg2_main(libraryControllers[index],
                        "_enqueueAppLibraryUpdate", 0, 0, 0, 0);
            if (remote_call_current_success()) updatesEnqueued++;
        }
    }

    BOOL remoteOK = remote_call_current_success();
    BOOL ok = preflightOK && remoteOK &&
        cachesPurged == cacheCount &&
        iconReloads == reloadIconObjectCount && folderRebuilds == 1 &&
        podReloads == libraryFolderControllerCount &&
        updatesEnqueued == libraryControllerCount;
    int mutationCount = cachesPurged + iconReloads + folderRebuilds +
        podReloads + updatesEnqueued;
    printf("[SBR_LIBRARY_MINI_REFRESH] result=%s caches=%d/%d "
           "icon-reload=%d/%d rebuild=%d pods=%d/%d enqueue=%d/%d "
           "mutations=%d manager-reset=0 list-reload=0 relayout=0 "
           "objc-method-mutation=0 lifecycle=0 shared-cache-write=0\n",
           ok ? "complete" : "incomplete", cachesPurged, cacheCount,
           iconReloads, reloadIconObjectCount,
           folderRebuilds, podReloads, libraryFolderControllerCount,
           updatesEnqueued, libraryControllerCount, mutationCount);
    (void)r_settle_us(previousSettleUS);

    return @{
        @"ok": @(ok),
        @"stage": ok ? @"app-library-miniatures-refreshed" :
            (preflightOK ? @"app-library-miniature-refresh" : @"preflight"),
        @"message": ok
            ? @"The targeted App Library miniature generations and folder composites were refreshed; inspect the category folders manually."
            : (failure ?: @"The App Library miniature refresh did not complete."),
        @"iconManagerPointer": @(iconManager),
        @"iconModelPointer": @(iconModel),
        @"folderImageCachePointer": @(folderImageCache),
        @"folderSourceCachePointer": @(folderSourceCache),
        @"configuredTargetBundleCount":
            @(configuredBundleIdentifiers.count),
        @"ignoredNonApplicationTargetCount":
            @(ignoredNonApplicationTargets.count),
        @"ignoredNonApplicationTargets": ignoredNonApplicationTargets,
        @"targetBundleCount": @(reloadBundleIdentifiers.count),
        @"targetIconObjectCount": @(reloadIconObjectCount),
        @"canonicalIconMatches": @(reloadCanonicalMatches),
        @"liveLeafIconMatches": @(reloadLeafMatches),
        @"iconLookupMisses": @(reloadLookupMisses),
        @"leafModelCount": @(reloadLeafModelCount),
        @"targetBundlesTruncated": @(reloadTargetsTruncated),
        @"leafModelsTruncated": @(reloadLeafModelsTruncated),
        @"libraryControllerCount": @(libraryControllerCount),
        @"libraryFolderControllerCount": @(libraryFolderControllerCount),
        @"cacheCount": @(cacheCount),
        @"cachesPurged": @(cachesPurged),
        @"iconReloads": @(iconReloads),
        @"folderRebuilds": @(folderRebuilds),
        @"podReloads": @(podReloads),
        @"updatesEnqueued": @(updatesEnqueued),
        @"mutationCount": @(mutationCount),
        @"managerResetIssued": @NO,
        @"applicationIconReloadIssued": @(iconReloads > 0),
        @"appLibraryListReloadIssued": @NO,
        @"relayoutIssued": @NO,
        @"objectiveCMethodMutationCount": @0,
        @"processLifecycleMutationCount": @0,
        @"sharedCacheWriteCount": @0,
        @"remoteOK": @(remoteOK),
    };
}

bool themer_refresh_springboard_iconservices_cache_in_session(void)
{
    if (!remote_call_current_success()) {
        printf("[SBR_HOME_REFRESH] skipped transport=0\n");
        return false;
    }

    /* The stock cache/rebuild/relayout messages are synchronous on
     * SpringBoard's main thread. Avoid adding RemoteCall's conservative
     * inter-message settle to this already bounded sequence. r_settle_us is
     * thread-local and is restored before returning. */
    uint32_t previousSettleUS = r_settle_us(0);
    printf("[SBR_HOME_REFRESH] stage=discover-roots settle-us=%u->0\n",
           previousSettleUS);

    enum { ROOT_CAP = 24 };
    uint64_t roots[ROOT_CAP] = {0};
    int rootCount = themer_collect_model_lookup_roots(roots, ROOT_CAP);
    uint64_t iconController = 0;
    uint64_t iconManager = 0;
    uint64_t iconModel = 0;
    uint64_t imageCache = 0;
    uint64_t rootFolderController = 0;
    uint64_t rootFolderControllerCache = 0;
    uint64_t notificationCache = 0;
    uint64_t notificationMappedCacheClass = 0;
    uint64_t notificationMappedCache = 0;
    uint64_t tableUICache = 0;
    uint64_t appSwitcherCache = 0;
    uint64_t folderImageCache = 0;
    uint64_t folderSourceCache = 0;
    uint64_t libraryControllers[2] = {0};
    int libraryControllerCount = 0;
    uint64_t librarySearchControllers[4] = {0};
    int librarySearchControllerCount = 0;
    uint64_t libraryTableControllers[4] = {0};
    int libraryTableControllerCount = 0;
    char iconControllerClass[96] = {0};
    char iconManagerClass[96] = {0};
    char iconModelClass[96] = {0};
    char imageCacheClass[96] = {0};
    char rootFolderControllerClass[96] = {0};
    char notificationCacheClass[96] = {0};
    char notificationMappedCacheClassName[96] = {0};
    char tableUICacheClass[96] = {0};
    char appSwitcherCacheClass[96] = {0};
    char folderImageCacheClass[96] = {0};

    printf("[SBR_HOME_REFRESH] stage=discover-caches roots=%d\n",
           rootCount);

    for (int index = 0;
         index < rootCount && remote_call_current_success(); index++) {
        uint64_t root = roots[index];
        if (!r_is_objc_ptr(root)) continue;
        char rootClass[96] = {0};
        themer_read_class_name(root, rootClass, sizeof(rootClass));
        if (!iconController && !strcmp(rootClass, "SBIconController")) {
            iconController = root;
            snprintf(iconControllerClass, sizeof(iconControllerClass), "%s",
                     rootClass);
        } else if (!iconManager && !strcmp(rootClass, "SBHIconManager")) {
            iconManager = root;
            snprintf(iconManagerClass, sizeof(iconManagerClass), "%s",
                     rootClass);
        } else if (!iconModel &&
                   (!strcmp(rootClass, "SBHIconModel") ||
                    !strcmp(rootClass, "SBIconModel")) &&
                   r_responds_main(root, "reloadIcons")) {
            iconModel = root;
            snprintf(iconModelClass, sizeof(iconModelClass), "%s",
                     rootClass);
        }
    }

    if (r_is_objc_ptr(iconController) &&
        r_responds_main(iconController, "notificationIconImageCache")) {
        uint64_t candidate = r_msg2_main(
            iconController, "notificationIconImageCache", 0, 0, 0, 0);
        if (r_is_objc_ptr(candidate)) {
            themer_read_class_name(candidate, notificationCacheClass,
                                   sizeof(notificationCacheClass));
            if (!strcmp(notificationCacheClass, "SBHIconImageCache")) {
                notificationCache = candidate;
            }
        }
    }

    /* Ordinary UserNotificationsUIKit rows do not consume
     * SBIconController.notificationIconImageCache. BBSectionIcon recipes
     * cache decoded pixels in this process-wide BaseBoardUI-backed cache.
     * Resolve the singleton separately so resetAllIconImageCaches cannot be
     * mistaken for notification-row cache coverage. */
    notificationMappedCacheClass = themer_lookup_class(
        "NCUIMappedImageCache");
    if (r_is_objc_ptr(notificationMappedCacheClass) &&
        themer_springboard_method_encoding_is(
            notificationMappedCacheClass, "sharedCache", "@16@0:8")) {
        notificationMappedCache = r_msg2_main(
            notificationMappedCacheClass, "sharedCache", 0, 0, 0, 0);
        themer_read_class_name(
            notificationMappedCache, notificationMappedCacheClassName,
            sizeof(notificationMappedCacheClassName));
        if (strcmp(notificationMappedCacheClassName,
                   "NCUIMappedImageCache")) {
            notificationMappedCache = 0;
        }
    }

    if (r_is_objc_ptr(iconController) &&
        r_responds_main(iconController, "tableUIIconImageCache")) {
        uint64_t candidate = r_msg2_main(
            iconController, "tableUIIconImageCache", 0, 0, 0, 0);
        if (r_is_objc_ptr(candidate)) {
            themer_read_class_name(candidate, tableUICacheClass,
                                   sizeof(tableUICacheClass));
            if (!strcmp(tableUICacheClass, "SBHIconImageCache")) {
                tableUICache = candidate;
            }
        }
    }

    if (r_is_objc_ptr(iconController) &&
        r_responds_main(iconController,
                        "appSwitcherHeaderIconImageCache")) {
        uint64_t candidate = r_msg2_main(
            iconController, "appSwitcherHeaderIconImageCache",
            0, 0, 0, 0);
        if (r_is_objc_ptr(candidate)) {
            themer_read_class_name(candidate, appSwitcherCacheClass,
                                   sizeof(appSwitcherCacheClass));
            if (!strcmp(appSwitcherCacheClass, "SBHIconImageCache")) {
                appSwitcherCache = candidate;
            }
        }
    }

    if (r_is_objc_ptr(iconManager) &&
        r_responds_main(iconManager, "iconImageCache")) {
        uint64_t candidate = r_msg2_main(
            iconManager, "iconImageCache", 0, 0, 0, 0);
        if (r_is_objc_ptr(candidate)) {
            themer_read_class_name(candidate, imageCacheClass,
                                   sizeof(imageCacheClass));
            if (!strcmp(imageCacheClass, "SBHIconImageCache")) {
                imageCache = candidate;
            } else {
                imageCache = 0;
            }
        }
    }
    if (r_is_objc_ptr(iconManager) &&
        themer_springboard_method_encoding_is(
            iconManager, "rootFolderController", "@16@0:8")) {
        rootFolderController = r_msg2_main(
            iconManager, "rootFolderController", 0, 0, 0, 0);
        themer_read_class_name(
            rootFolderController, rootFolderControllerClass,
            sizeof(rootFolderControllerClass));
        if (strcmp(rootFolderControllerClass, "SBRootFolderController")) {
            rootFolderController = 0;
        }
        rootFolderControllerCache =
            themer_springboard_method_encoding_is(
                rootFolderController, "iconImageCache", "@16@0:8")
                ? r_msg2_main(rootFolderController, "iconImageCache",
                              0, 0, 0, 0)
                : 0;
    }
    if (r_is_objc_ptr(iconManager) &&
        r_responds_main(iconManager, "folderIconImageCache")) {
        uint64_t candidate = r_msg2_main(
            iconManager, "folderIconImageCache", 0, 0, 0, 0);
        if (r_is_objc_ptr(candidate)) {
            themer_read_class_name(candidate, folderImageCacheClass,
                                   sizeof(folderImageCacheClass));
            if (!strcmp(folderImageCacheClass, "SBFolderIconImageCache")) {
                folderImageCache = candidate;
            }
        }
    }
    if (r_is_objc_ptr(folderImageCache) &&
        themer_springboard_method_encoding_is(
            folderImageCache, "iconImageCache", "@16@0:8")) {
        uint64_t candidate = r_msg2_main(
            folderImageCache, "iconImageCache", 0, 0, 0, 0);
        if (r_is_objc_ptr(candidate)) folderSourceCache = candidate;
    }

    if (r_is_objc_ptr(iconManager)) {
        const char *librarySelectors[] = {
            "trailingLibraryViewController",
            "overlayLibraryViewController",
        };
        for (size_t index = 0;
             index < sizeof(librarySelectors) / sizeof(librarySelectors[0]);
             index++) {
            if (!r_responds_main(iconManager, librarySelectors[index])) {
                continue;
            }
            uint64_t candidate = r_msg2_main(
                iconManager, librarySelectors[index], 0, 0, 0, 0);
            if (!r_is_objc_ptr(candidate)) continue;
            /* iOS 26 returns SBLibraryViewController here. It subclasses
             * SBHLibraryViewController, so an exact class-name check rejects
             * the real controller. Validate the interface we actually use. */
            if (!r_responds_main(candidate, "iconImageCache")) {
                continue;
            }
            themer_add_unique(libraryControllers, &libraryControllerCount,
                              2, candidate);
        }
    }

    /* The App Library alphabetical/search list does not consume only the
     * manager's generic table cache.  Its SBHIconLibraryTableViewController
     * owns the cache that feeds already-materialized SBHIconTableViewCells.
     * Resolve it through the finite, class-dumped controller graph instead
     * of walking SpringBoard's windows or view tree:
     *
     *   SBHLibraryViewController.iconTableViewController
     *   SBHLibraryViewController.containerViewController
     *     -> SBHLibrarySearchController.searchResultsController
     *
     * The direct table getter and search result commonly name the same
     * object, so every pointer is deduplicated before any mutation. */
    for (int index = 0;
         index < libraryControllerCount && remote_call_current_success();
         index++) {
        uint64_t controller = libraryControllers[index];
        uint64_t directTable =
            r_responds_main(controller, "iconTableViewController")
                ? r_msg2_main(controller, "iconTableViewController",
                              0, 0, 0, 0)
                : 0;
        if (r_is_objc_ptr(directTable) &&
            r_responds_main(directTable, "iconImageCache") &&
            r_responds_main(directTable, "_reloadAppIcons") &&
            r_responds_main(directTable, "_reloadVisibleCells")) {
            themer_add_unique(libraryTableControllers,
                              &libraryTableControllerCount, 4,
                              directTable);
        }

        uint64_t searchController =
            r_responds_main(controller, "containerViewController")
                ? r_msg2_main(controller, "containerViewController",
                              0, 0, 0, 0)
                : 0;
        if (!r_is_objc_ptr(searchController) ||
            !r_responds_main(searchController,
                             "searchResultsController")) {
            continue;
        }
        themer_add_unique(librarySearchControllers,
                          &librarySearchControllerCount, 4,
                          searchController);
        uint64_t searchTable = r_msg2_main(
            searchController, "searchResultsController", 0, 0, 0, 0);
        if (r_is_objc_ptr(searchTable) &&
            r_responds_main(searchTable, "iconImageCache") &&
            r_responds_main(searchTable, "_reloadAppIcons") &&
            r_responds_main(searchTable, "_reloadVisibleCells")) {
            themer_add_unique(libraryTableControllers,
                              &libraryTableControllerCount, 4,
                              searchTable);
        }
    }

    printf("[SBR_HOME_REFRESH] stage=discover-library controllers=%d "
           "search-controllers=%d table-controllers=%d\n",
           libraryControllerCount, librarySearchControllerCount,
           libraryTableControllerCount);

    /* Capture every cache getter immediately before reset.  On 23A341 the
     * manager's primary cache is purged and replaced (the ivar becomes nil and
     * the getter lazily constructs a new object); the dedicated controller
     * caches remain stable.  Never purge a pointer captured before reset. */
    uint64_t imageCacheBeforeReset = imageCache;
    uint64_t rootFolderControllerBeforeReset = rootFolderController;
    uint64_t rootFolderControllerCacheBeforeReset =
        rootFolderControllerCache;
    uint64_t notificationCacheBeforeReset = notificationCache;
    uint64_t notificationMappedCacheBeforeReset =
        notificationMappedCache;
    uint64_t tableUICacheBeforeReset = tableUICache;
    uint64_t appSwitcherCacheBeforeReset = appSwitcherCache;
    uint64_t folderImageCacheBeforeReset = folderImageCache;
    uint64_t folderSourceCacheBeforeReset = folderSourceCache;
    uint64_t libraryCachesBeforeReset[2] = {0};
    int libraryCachesBeforeResetCount = 0;
    for (int index = 0;
         index < libraryControllerCount && remote_call_current_success();
         index++) {
        uint64_t controller = libraryControllers[index];
        uint64_t cache = themer_springboard_method_encoding_is(
                controller, "iconImageCache", "@16@0:8")
            ? r_msg2_main(controller, "iconImageCache", 0, 0, 0, 0) : 0;
        themer_add_unique(libraryCachesBeforeReset,
                          &libraryCachesBeforeResetCount, 2, cache);
    }
    uint64_t libraryTableCachesBeforeReset[4] = {0};
    int libraryTableCachesBeforeResetCount = 0;
    for (int index = 0;
         index < libraryTableControllerCount &&
         remote_call_current_success(); index++) {
        uint64_t controller = libraryTableControllers[index];
        uint64_t cache = themer_springboard_method_encoding_is(
                controller, "iconImageCache", "@16@0:8")
            ? r_msg2_main(controller, "iconImageCache", 0, 0, 0, 0) : 0;
        themer_add_unique(libraryTableCachesBeforeReset,
                          &libraryTableCachesBeforeResetCount, 4, cache);
    }

    bool resetIssued = r_is_objc_ptr(iconManager) &&
        themer_springboard_method_encoding_is(
            iconManager, "resetAllIconImageCaches", "v16@0:8");
    printf("[SBR_HOME_REFRESH] stage=purge-caches bounded=1\n");
    if (resetIssued) {
        r_msg2_main(iconManager, "resetAllIconImageCaches", 0, 0, 0, 0);
        resetIssued = remote_call_current_success();
    }

    /* Reacquire every owner-backed cache after reset, whether or not today's
     * build was observed to replace that particular object. */
    imageCache = resetIssued && themer_springboard_method_encoding_is(
            iconManager, "iconImageCache", "@16@0:8")
        ? r_msg2_main(iconManager, "iconImageCache", 0, 0, 0, 0) : 0;
    notificationCache = resetIssued &&
        themer_springboard_method_encoding_is(
            iconController, "notificationIconImageCache", "@16@0:8")
        ? r_msg2_main(iconController, "notificationIconImageCache",
                      0, 0, 0, 0) : 0;
    notificationMappedCache = resetIssued &&
        themer_springboard_method_encoding_is(
            notificationMappedCacheClass, "sharedCache", "@16@0:8")
        ? r_msg2_main(notificationMappedCacheClass, "sharedCache",
                      0, 0, 0, 0) : 0;
    tableUICache = resetIssued && themer_springboard_method_encoding_is(
            iconController, "tableUIIconImageCache", "@16@0:8")
        ? r_msg2_main(iconController, "tableUIIconImageCache",
                      0, 0, 0, 0) : 0;
    appSwitcherCache = resetIssued &&
        themer_springboard_method_encoding_is(
            iconController, "appSwitcherHeaderIconImageCache", "@16@0:8")
        ? r_msg2_main(iconController, "appSwitcherHeaderIconImageCache",
                      0, 0, 0, 0) : 0;
    folderImageCache = resetIssued &&
        themer_springboard_method_encoding_is(
            iconManager, "folderIconImageCache", "@16@0:8")
        ? r_msg2_main(iconManager, "folderIconImageCache", 0, 0, 0, 0) : 0;
    folderSourceCache = resetIssued &&
        themer_springboard_method_encoding_is(
            folderImageCache, "iconImageCache", "@16@0:8")
        ? r_msg2_main(folderImageCache, "iconImageCache", 0, 0, 0, 0) : 0;
    rootFolderController = resetIssued &&
        themer_springboard_method_encoding_is(
            iconManager, "rootFolderController", "@16@0:8")
        ? r_msg2_main(iconManager, "rootFolderController", 0, 0, 0, 0) : 0;
    themer_read_class_name(
        rootFolderController, rootFolderControllerClass,
        sizeof(rootFolderControllerClass));
    if (strcmp(rootFolderControllerClass, "SBRootFolderController")) {
        rootFolderController = 0;
    }
    rootFolderControllerCache =
        themer_springboard_method_encoding_is(
            rootFolderController, "iconImageCache", "@16@0:8")
            ? r_msg2_main(rootFolderController, "iconImageCache",
                          0, 0, 0, 0)
            : 0;

    themer_read_class_name(imageCache, imageCacheClass,
                           sizeof(imageCacheClass));
    themer_read_class_name(notificationCache, notificationCacheClass,
                           sizeof(notificationCacheClass));
    themer_read_class_name(
        notificationMappedCache, notificationMappedCacheClassName,
        sizeof(notificationMappedCacheClassName));
    themer_read_class_name(tableUICache, tableUICacheClass,
                           sizeof(tableUICacheClass));
    themer_read_class_name(appSwitcherCache, appSwitcherCacheClass,
                           sizeof(appSwitcherCacheClass));
    themer_read_class_name(folderImageCache, folderImageCacheClass,
                           sizeof(folderImageCacheClass));

    enum { CACHE_CAP = 16 };
    uint64_t explicitCaches[CACHE_CAP] = {0};
    int explicitCacheCount = 0;
    themer_add_unique(explicitCaches, &explicitCacheCount, CACHE_CAP,
                      notificationCache);
    themer_add_unique(explicitCaches, &explicitCacheCount, CACHE_CAP,
                      tableUICache);
    themer_add_unique(explicitCaches, &explicitCacheCount, CACHE_CAP,
                      appSwitcherCache);
    themer_add_unique(explicitCaches, &explicitCacheCount, CACHE_CAP,
                      folderSourceCache);

    uint64_t libraryCaches[2] = {0};
    int libraryCacheCount = 0;
    for (int index = 0;
         index < libraryControllerCount && remote_call_current_success();
         index++) {
        uint64_t controller = libraryControllers[index];
        uint64_t libraryCache = themer_springboard_method_encoding_is(
                controller, "iconImageCache", "@16@0:8")
            ? r_msg2_main(controller, "iconImageCache", 0, 0, 0, 0) : 0;
        if (r_is_objc_ptr(libraryCache)) {
            themer_add_unique(libraryCaches, &libraryCacheCount,
                              2, libraryCache);
            themer_add_unique(explicitCaches, &explicitCacheCount,
                              CACHE_CAP, libraryCache);
        }
    }

    uint64_t libraryTableCaches[4] = {0};
    int libraryTableCacheCount = 0;
    for (int index = 0;
         index < libraryTableControllerCount &&
         remote_call_current_success(); index++) {
        uint64_t controller = libraryTableControllers[index];
        uint64_t tableCache = themer_springboard_method_encoding_is(
                controller, "iconImageCache", "@16@0:8")
            ? r_msg2_main(controller, "iconImageCache", 0, 0, 0, 0) : 0;
        if (!r_is_objc_ptr(tableCache)) continue;
        themer_add_unique(libraryTableCaches, &libraryTableCacheCount,
                          4, tableCache);
        themer_add_unique(explicitCaches, &explicitCacheCount,
                          CACHE_CAP, tableCache);
    }

    int explicitPurgeCount = 0;
    uint64_t explicitlyPurgedCaches[CACHE_CAP] = {0};
    int explicitlyPurgedCacheCount = 0;
    for (int index = 0;
         resetIssued && index < explicitCacheCount &&
         remote_call_current_success(); index++) {
        uint64_t cache = explicitCaches[index];
        /* resetAllIconImageCaches already purged the manager's Home cache;
         * the VM showed the App Library getter currently aliases it. */
        if (cache == imageCache) continue;
        if (!themer_springboard_method_encoding_is(
                cache, "purgeAllCachedImages", "v16@0:8")) continue;
        r_msg2_main(cache, "purgeAllCachedImages", 0, 0, 0, 0);
        if (remote_call_current_success()) {
            explicitPurgeCount++;
            themer_add_unique(explicitlyPurgedCaches,
                              &explicitlyPurgedCacheCount,
                              CACHE_CAP, cache);
        }
    }

    int libraryTableCachesPurged = 0;
    for (int index = 0; index < libraryTableCacheCount; index++) {
        uint64_t cache = libraryTableCaches[index];
        bool covered = cache == imageCache;
        for (int purgeIndex = 0;
             !covered && purgeIndex < explicitlyPurgedCacheCount;
             purgeIndex++) {
            covered = explicitlyPurgedCaches[purgeIndex] == cache;
        }
        if (covered) libraryTableCachesPurged++;
    }
    int libraryCachesPurged = 0;
    for (int index = 0; index < libraryCacheCount; index++) {
        if (themer_pointer_is_covered(
                libraryCaches[index], imageCache, explicitlyPurgedCaches,
                explicitlyPurgedCacheCount)) {
            libraryCachesPurged++;
        }
    }

    bool notificationPurgeIssued = resetIssued &&
        themer_pointer_is_covered(notificationCache, imageCache,
                                  explicitlyPurgedCaches,
                                  explicitlyPurgedCacheCount);
    bool tableUIPurgeIssued = resetIssued &&
        themer_pointer_is_covered(tableUICache, imageCache,
                                  explicitlyPurgedCaches,
                                  explicitlyPurgedCacheCount);
    bool appSwitcherPurgeIssued = resetIssued &&
        themer_pointer_is_covered(appSwitcherCache, imageCache,
                                  explicitlyPurgedCaches,
                                  explicitlyPurgedCacheCount);
    bool folderSourcePurgeIssued = resetIssued &&
        themer_pointer_is_covered(folderSourceCache, imageCache,
                                  explicitlyPurgedCaches,
                                  explicitlyPurgedCacheCount);

    /* -removeAllObjects schedules its work on BSUIMappedImageCache's serial
     * queue. -allKeys immediately dispatches synchronously to that same
     * queue, so the read is a deterministic FIFO barrier and avoids a sleep.
     * This cache is independent of the SBHIconImageCache family above. */
    uint64_t notificationMappedKeysBefore = 0;
    uint64_t notificationMappedKeysAfter = 0;
    uint64_t notificationMappedKeyCountBefore = 0;
    uint64_t notificationMappedKeyCountAfter = UINT64_MAX;
    bool notificationMappedCachePurgeIssued = resetIssued &&
        r_is_objc_ptr(notificationMappedCache) &&
        !strcmp(notificationMappedCacheClassName, "NCUIMappedImageCache") &&
        themer_springboard_method_encoding_is(
            notificationMappedCache, "allKeys", "@16@0:8") &&
        themer_springboard_method_encoding_is(
            notificationMappedCache, "removeAllObjects", "v16@0:8");
    if (notificationMappedCachePurgeIssued) {
        notificationMappedKeysBefore = r_msg2_main(
            notificationMappedCache, "allKeys", 0, 0, 0, 0);
        notificationMappedKeyCountBefore =
            r_is_objc_ptr(notificationMappedKeysBefore) &&
            r_responds_main(notificationMappedKeysBefore, "count")
                ? r_msg2_main(notificationMappedKeysBefore, "count",
                              0, 0, 0, 0) : UINT64_MAX;
        r_msg2_main(notificationMappedCache, "removeAllObjects",
                    0, 0, 0, 0);
        if (remote_call_current_success()) {
            notificationMappedKeysAfter = r_msg2_main(
                notificationMappedCache, "allKeys", 0, 0, 0, 0);
            notificationMappedKeyCountAfter =
                r_is_objc_ptr(notificationMappedKeysAfter) &&
                r_responds_main(notificationMappedKeysAfter, "count")
                    ? r_msg2_main(notificationMappedKeysAfter, "count",
                                  0, 0, 0, 0) : UINT64_MAX;
        }
        notificationMappedCachePurgeIssued =
            remote_call_current_success() &&
            notificationMappedKeyCountAfter == 0;
    }
    printf("[SBR_HOME_REFRESH] notification-mapped-cache=0x%llx "
           "keys=%llu->%llu fifo-barrier=allKeys purge=%d\n",
           (unsigned long long)notificationMappedCache,
           (unsigned long long)notificationMappedKeyCountBefore,
           (unsigned long long)notificationMappedKeyCountAfter,
           notificationMappedCachePurgeIssued);

    /* resetAllIconImageCaches replaces only SBHIconManager's cache.  The
     * live SBRootFolderController, SBRootFolderView, every Home page, the
     * dock, and their existing SBIconViews retain the old cache pointer.
     * SBFolderController -setIconImageCache: is Apple's bounded propagation
     * boundary: its view forwards to each owned SBIconListView, whose setter
     * forwards to its materialized SBIconViews/SBIconImageViews.  Rebind only
     * after the old retained source cache and all dedicated caches have been
     * purged, preventing an early refill through the stale object. */
    uint64_t rootFolderControllerCacheBeforeRebind =
        rootFolderControllerCache;
    bool rootFolderCacheRebound = resetIssued && folderSourcePurgeIssued &&
        r_is_objc_ptr(imageCache) && r_is_objc_ptr(rootFolderController) &&
        themer_springboard_method_encoding_is(
            rootFolderController, "setIconImageCache:", "v24@0:8@16") &&
        themer_springboard_method_encoding_is(
            rootFolderController, "iconImageCache", "@16@0:8");
    if (rootFolderCacheRebound) {
        r_msg2_main(rootFolderController, "setIconImageCache:",
                    imageCache, 0, 0, 0);
        rootFolderControllerCache = remote_call_current_success()
            ? r_msg2_main(rootFolderController, "iconImageCache",
                          0, 0, 0, 0)
            : 0;
        rootFolderCacheRebound = remote_call_current_success() &&
            rootFolderControllerCache == imageCache;
    }
    printf("[SBR_HOME_REFRESH] root-cache-rebind controller=0x%llx/%s "
           "controller-pointer=0x%llx->0x%llx "
           "cache=0x%llx->0x%llx manager-cache=0x%llx ok=%d\n",
           (unsigned long long)rootFolderController,
           rootFolderControllerClass[0]
               ? rootFolderControllerClass : "-",
           (unsigned long long)rootFolderControllerBeforeReset,
           (unsigned long long)rootFolderController,
           (unsigned long long)rootFolderControllerCacheBeforeRebind,
           (unsigned long long)rootFolderControllerCache,
           (unsigned long long)imageCache, rootFolderCacheRebound);
    printf("[SBR_CACHE_POINTERS] manager=0x%llx->0x%llx "
           "root=0x%llx->0x%llx root-cache=0x%llx->0x%llx "
           "notification=0x%llx->0x%llx "
           "notification-mapped=0x%llx->0x%llx "
           "table=0x%llx->0x%llx "
           "switcher=0x%llx->0x%llx folder=0x%llx->0x%llx "
           "folder-source=0x%llx->0x%llx "
           "library=0x%llx->0x%llx library-table=0x%llx->0x%llx\n",
           (unsigned long long)imageCacheBeforeReset,
           (unsigned long long)imageCache,
           (unsigned long long)rootFolderControllerBeforeReset,
           (unsigned long long)rootFolderController,
           (unsigned long long)rootFolderControllerCacheBeforeReset,
           (unsigned long long)rootFolderControllerCache,
           (unsigned long long)notificationCacheBeforeReset,
           (unsigned long long)notificationCache,
           (unsigned long long)notificationMappedCacheBeforeReset,
           (unsigned long long)notificationMappedCache,
           (unsigned long long)tableUICacheBeforeReset,
           (unsigned long long)tableUICache,
           (unsigned long long)appSwitcherCacheBeforeReset,
           (unsigned long long)appSwitcherCache,
           (unsigned long long)folderImageCacheBeforeReset,
           (unsigned long long)folderImageCache,
           (unsigned long long)folderSourceCacheBeforeReset,
           (unsigned long long)folderSourceCache,
           (unsigned long long)(libraryCachesBeforeResetCount
               ? libraryCachesBeforeReset[0] : 0),
           (unsigned long long)(libraryCacheCount ? libraryCaches[0] : 0),
           (unsigned long long)(libraryTableCachesBeforeResetCount
               ? libraryTableCachesBeforeReset[0] : 0),
           (unsigned long long)(libraryTableCacheCount
               ? libraryTableCaches[0] : 0));

    /* Persistent IconServices store writes and SBHIconImageCache purges are
     * both silent to a mounted ICRIconLayer. VM tracing established the exact
     * stock refill boundary:
     *
     *   SBApplicationIcon.reloadIconImage
     *     -> imageGeneration++
     *     -> updateImageInIconLayerView: for each live layer
     *     -> loadRealIconContentLayerWithInfo:...
     *     -> _notifyImageDidUpdate for flat-image observers
     *
     * A bundle can have more than one live SBApplicationIcon object. Home can
     * be mounted on the model's leaf object while
     * applicationIconForBundleIdentifier: returns a distinct canonical
     * object. Reloading only the latter makes Apply/Restore appear random:
     * the persistent store is correct, but the visible leaf keeps its old
     * layer. Resolve the canonical object and the model's leaf objects, then
     * reload every distinct object whose bundle is in the durable
     * themed/restoring set. This remains O(theme size + model leaf count), not
     * the former unfiltered 269-application refill storm. */
    NSArray<NSString *> *reloadBundleIdentifiers =
        themer_springboard_refresh_bundle_identifiers_snapshot();
    uint64_t reloadIconCount = reloadBundleIdentifiers.count;
    NSMutableSet<NSString *> *reloadIdentifierSet =
        [NSMutableSet setWithArray:reloadBundleIdentifiers ?: @[]];
    NSMutableSet<NSString *> *matchedReloadIdentifiers =
        [NSMutableSet setWithCapacity:reloadIdentifierSet.count];
    enum { RELOAD_ICON_OBJECT_CAP = 1024 };
    uint64_t reloadIconObjects[RELOAD_ICON_OBJECT_CAP] = {0};
    int reloadIconObjectCount = 0;
    int reloadIconEligible = 0;
    int reloadIconIssued = 0;
    int reloadIconLookupMisses = 0;
    int reloadIconLookupMismatchLogs = 0;
    int reloadCanonicalMatches = 0;
    int reloadLeafMatches = 0;
    uint64_t reloadLeafModelCount = 0;
    bool reloadLeafModelsTruncated = false;
    bool reloadIconsTruncated = false;
    bool reloadLookupAvailable = r_is_objc_ptr(iconModel) &&
        r_responds_main(iconModel,
                        "applicationIconForBundleIdentifier:");
    if (resetIssued && remote_call_current_success() &&
        reloadLookupAvailable) {
        enum { RELOAD_ICON_CAP = 512 };
        reloadIconsTruncated = reloadIconCount > RELOAD_ICON_CAP;
        uint64_t reloadIconBoundedCount = reloadIconsTruncated
            ? RELOAD_ICON_CAP : reloadIconCount;
        printf("[SBR_HOME_REFRESH] stage=resolve-themed-icon-instances "
               "targets=%llu truncated=%d lookup=canonical-model\n",
               (unsigned long long)reloadIconCount,
               reloadIconsTruncated);
        for (uint64_t index = 0;
             index < reloadIconBoundedCount &&
             remote_call_current_success(); index++) {
            NSString *identifier = reloadBundleIdentifiers[index];
            const char *bundle = identifier.UTF8String;
            uint64_t remoteIdentifier = bundle && bundle[0]
                ? r_nsstr_retained(bundle) : 0;
            uint64_t icon = r_is_objc_ptr(remoteIdentifier) &&
                themer_springboard_method_encoding_is(
                    iconModel, "applicationIconForBundleIdentifier:",
                    "@24@0:8@16")
                ? r_msg2_main(
                    iconModel, "applicationIconForBundleIdentifier:",
                    remoteIdentifier, 0, 0, 0)
                : 0;
            if (r_is_objc_ptr(remoteIdentifier)) {
                r_msg2(remoteIdentifier, "release", 0, 0, 0, 0);
            }
            if (!remote_call_current_success()) break;

            char actual[192] = {0};
            bool exactIdentity = r_is_objc_ptr(icon) &&
                themer_read_bundle_for_icon(
                    icon, 0, actual, sizeof(actual)) &&
                bundle && !strcmp(actual, bundle);
            if (!exactIdentity) {
                if (reloadIconLookupMismatchLogs < 8) {
                    printf("[SBR_HOME_REFRESH] themed-icon-lookup-miss "
                           "bundle=%s icon=0x%llx actual=%s\n",
                           bundle ?: "-", (unsigned long long)icon,
                           actual[0] ? actual : "-");
                    reloadIconLookupMismatchLogs++;
                }
                continue;
            }
            NSString *matched = [NSString stringWithUTF8String:actual];
            if (matched.length > 0) {
                [matchedReloadIdentifiers addObject:matched];
            }
            int beforeCount = reloadIconObjectCount;
            themer_add_unique(reloadIconObjects, &reloadIconObjectCount,
                              RELOAD_ICON_OBJECT_CAP, icon);
            if (reloadIconObjectCount > beforeCount) {
                reloadCanonicalMatches++;
            }
        }

        /* leafIconsUniquedByApplicationBundleIdentifier is the authoritative
         * live model leaf set on iOS 26. Snapshot it once, then retain only
         * objects belonging to the active journal identifiers. */
        uint64_t leafCollection =
            themer_springboard_method_encoding_is(
                iconModel,
                "leafIconsUniquedByApplicationBundleIdentifier",
                "@16@0:8")
                ? r_msg2_main(
                    iconModel,
                    "leafIconsUniquedByApplicationBundleIdentifier",
                    0, 0, 0, 0)
                : 0;
        uint64_t leafObjects = 0;
        if (r_is_objc_ptr(leafCollection) &&
            r_responds_main(leafCollection, "allValues")) {
            leafObjects = r_msg2_main(
                leafCollection, "allValues", 0, 0, 0, 0);
        } else if (r_is_objc_ptr(leafCollection) &&
                   r_responds_main(leafCollection, "allObjects")) {
            leafObjects = r_msg2_main(
                leafCollection, "allObjects", 0, 0, 0, 0);
        }
        reloadLeafModelCount = r_is_objc_ptr(leafObjects) &&
            r_responds_main(leafObjects, "count")
                ? r_msg2_main(leafObjects, "count", 0, 0, 0, 0)
                : 0;
        enum { RELOAD_LEAF_MODEL_CAP = 1024 };
        reloadLeafModelsTruncated =
            reloadLeafModelCount > RELOAD_LEAF_MODEL_CAP;
        uint64_t boundedLeafCount = reloadLeafModelsTruncated
            ? RELOAD_LEAF_MODEL_CAP : reloadLeafModelCount;
        for (uint64_t index = 0;
             index < boundedLeafCount && remote_call_current_success();
             index++) {
            uint64_t icon = r_msg2_main(
                leafObjects, "objectAtIndex:", index, 0, 0, 0);
            if (!r_is_objc_ptr(icon)) continue;
            char actual[192] = {0};
            if (!themer_read_bundle_for_icon(
                    icon, 0, actual, sizeof(actual))) continue;
            NSString *identifier =
                [NSString stringWithUTF8String:actual];
            if (identifier.length == 0 ||
                ![reloadIdentifierSet containsObject:identifier]) {
                continue;
            }
            [matchedReloadIdentifiers addObject:identifier];
            int beforeCount = reloadIconObjectCount;
            themer_add_unique(reloadIconObjects, &reloadIconObjectCount,
                              RELOAD_ICON_OBJECT_CAP, icon);
            if (reloadIconObjectCount > beforeCount) reloadLeafMatches++;
        }

        NSUInteger matchedIdentifierCount = matchedReloadIdentifiers.count;
        reloadIconLookupMisses = (int)(
            reloadIdentifierSet.count > matchedIdentifierCount
                ? reloadIdentifierSet.count - matchedIdentifierCount
                : 0);
        if (reloadIconLookupMisses > 0) {
            NSMutableSet<NSString *> *missing =
                [reloadIdentifierSet mutableCopy];
            [missing minusSet:matchedReloadIdentifiers];
            NSArray<NSString *> *sortedMissing =
                [[missing allObjects] sortedArrayUsingSelector:
                    @selector(localizedCaseInsensitiveCompare:)];
            NSUInteger sampleCount = MIN((NSUInteger)8,
                                         sortedMissing.count);
            NSString *missingSample = [[sortedMissing subarrayWithRange:
                NSMakeRange(0, sampleCount)] componentsJoinedByString:@","];
            printf("[SBR_HOME_REFRESH] themed-icon-instance-misses "
                   "count=%d sample=%s\n", reloadIconLookupMisses,
                   missingSample.UTF8String ?: "-");
        }

        printf("[SBR_HOME_REFRESH] stage=reload-themed-icon-generations "
               "objects=%d canonical=%d leaf=%d leaf-model=%llu "
               "leaf-truncated=%d\n", reloadIconObjectCount,
               reloadCanonicalMatches, reloadLeafMatches,
               (unsigned long long)reloadLeafModelCount,
               reloadLeafModelsTruncated);
        for (int index = 0;
             index < reloadIconObjectCount &&
             remote_call_current_success(); index++) {
            uint64_t icon = reloadIconObjects[index];
            if (!themer_springboard_method_encoding_is(
                    icon, "reloadIconImage", "v16@0:8")) continue;
            if (themer_springboard_method_encoding_is(
                    icon, "isApplicationIcon", "B16@0:8") &&
                !(r_msg2_main(icon, "isApplicationIcon", 0, 0, 0, 0) &
                  0xff)) {
                continue;
            }
            reloadIconEligible++;
            r_msg2_main(icon, "reloadIconImage", 0, 0, 0, 0);
            if (remote_call_current_success()) reloadIconIssued++;
        }
    }
    bool reloadIconsOK = remote_call_current_success() &&
        reloadLookupAvailable && !reloadIconsTruncated &&
        !reloadLeafModelsTruncated &&
        reloadIconCount > 0 && reloadIconLookupMisses == 0 &&
        reloadIconEligible == reloadIconObjectCount &&
        reloadIconIssued == reloadIconEligible;
    printf("[SBR_HOME_REFRESH] themed-icon-generation-reload=%d/%d "
           "target-count=%llu object-count=%d canonical=%d leaf=%d "
           "lookup-misses=%d ok=%d\n",
           reloadIconIssued, reloadIconEligible,
           (unsigned long long)reloadIconCount,
           reloadIconObjectCount, reloadCanonicalMatches,
           reloadLeafMatches,
           reloadIconLookupMisses, reloadIconsOK);

    /* appSwitcherHeaderIconImageCache controls future 28-point lookups, but
     * existing title items and their SBFluidSwitcherIconImageContainerViews
     * retain already-decoded pixels.  23A341 disassembly proves that
     * SBFluidSwitcherItemContainerHeaderView -setTitleItems:animated: keys its
     * four view dictionaries by SBDisplayItem and deliberately skips the
     * image setter when the old and new items have the same display item.
     * Consequently _performUpdateHandler can compute the correct new UIImage
     * and still leave an already-materialized card showing the old one.
     *
     * Resolve only the three class-dumped, controller-owned visible-consumer
     * maps. First refresh every title controller's SBApplicationIcon mapping,
     * then clear the exact materialized consumers through Apple's public-to-
     * the-class title setter, and finally run each update handler. Clearing
     * titleItems is an ordinary path used by SpringBoard itself when a title
     * is removed; it forces the subsequent rebuild past the display-item
     * equality shortcut without a window or recursive view walk. */
    uint64_t springBoardApplication = 0;
    uint64_t switcherController = 0;
    uint64_t switcherViewController = 0;
    uint64_t switcherWrapperViewController = 0;
    uint64_t titleControllerMap = 0;
    uint64_t titleControllerKeys = 0;
    uint64_t titleControllerCount = 0;
    uint64_t switcherVisibleConsumerMaps[3] = {0};
    uint64_t eligibleTitleControllers[128] = {0};
    uint64_t eligibleTitleKeys[128] = {0};
    uint64_t switcherMaterializedConsumers[384] = {0};
    int titleControllerEligible = 0;
    int switcherVisibleConsumerMapCount = 0;
    int switcherMaterializedConsumerCount = 0;
    int switcherMaterializedConsumerEligible = 0;
    int switcherMaterializedConsumerCleared = 0;
    int titleControllerUpdated = 0;
    bool titleControllersTruncated = false;
    bool switcherMaterializedConsumersTruncated = false;
    if (appSwitcherPurgeIssued && reloadIconsOK &&
        remote_call_current_success()) {
        uint64_t applicationClass = themer_lookup_class("UIApplication");
        springBoardApplication = r_is_objc_ptr(applicationClass) &&
            r_responds(applicationClass, "sharedApplication")
                ? r_msg2(applicationClass, "sharedApplication",
                         0, 0, 0, 0)
                : 0;
        switcherController = r_is_objc_ptr(springBoardApplication) &&
            r_responds_main(springBoardApplication, "_switcherController")
                ? r_msg2_main(springBoardApplication, "_switcherController",
                              0, 0, 0, 0)
                : 0;
        /* The title map belongs to SBDeckSwitcherViewController, returned by
         * -contentViewController.  -switcherViewController returns an outer
         * SBSwitcherViewController wrapper on 23A341 and has no map. */
        switcherViewController = r_is_objc_ptr(switcherController) &&
            themer_springboard_method_encoding_is(
                switcherController, "contentViewController", "@16@0:8")
                ? r_msg2_main(switcherController, "contentViewController",
                              0, 0, 0, 0)
                : 0;
        titleControllerMap = r_is_objc_ptr(switcherViewController)
            ? r_ivar_value(switcherViewController,
                           "_appLayoutToTitleItemController")
            : 0;
        if (!r_is_objc_ptr(titleControllerMap) &&
            r_is_objc_ptr(switcherController) &&
            themer_springboard_method_encoding_is(
                switcherController, "switcherViewController", "@16@0:8")) {
            switcherWrapperViewController = r_msg2_main(
                switcherController, "switcherViewController", 0, 0, 0, 0);
            uint64_t fallbackMap = r_is_objc_ptr(
                    switcherWrapperViewController)
                ? r_ivar_value(switcherWrapperViewController,
                               "_appLayoutToTitleItemController")
                : 0;
            if (r_is_objc_ptr(fallbackMap)) {
                switcherViewController = switcherWrapperViewController;
                titleControllerMap = fallbackMap;
            }
        }
        if (r_is_objc_ptr(titleControllerMap) &&
            r_responds_main(titleControllerMap, "allKeys")) {
            titleControllerKeys = r_msg2_main(
                titleControllerMap, "allKeys", 0, 0, 0, 0);
        } else if (r_is_objc_ptr(titleControllerMap) &&
                   r_responds_main(titleControllerMap,
                                   "keyEnumerator")) {
            uint64_t enumerator = r_msg2_main(
                titleControllerMap, "keyEnumerator", 0, 0, 0, 0);
            titleControllerKeys = r_is_objc_ptr(enumerator) &&
                r_responds_main(enumerator, "allObjects")
                    ? r_msg2_main(
                        enumerator, "allObjects", 0, 0, 0, 0)
                    : 0;
        }
        titleControllerCount = r_is_objc_ptr(titleControllerKeys) &&
            r_responds_main(titleControllerKeys, "count")
                ? r_msg2_main(titleControllerKeys, "count", 0, 0, 0, 0)
                : 0;
        enum { SWITCHER_TITLE_CONTROLLER_CAP = 128 };
        titleControllersTruncated =
            titleControllerCount > SWITCHER_TITLE_CONTROLLER_CAP;
        uint64_t boundedTitleControllerCount = titleControllersTruncated
            ? SWITCHER_TITLE_CONTROLLER_CAP : titleControllerCount;
        for (uint64_t index = 0;
             index < boundedTitleControllerCount &&
             remote_call_current_success(); index++) {
            uint64_t appLayout = r_msg2_main(
                titleControllerKeys, "objectAtIndex:", index, 0, 0, 0);
            uint64_t controller = r_is_objc_ptr(appLayout) &&
                r_responds_main(titleControllerMap, "objectForKey:")
                    ? r_msg2_main(titleControllerMap, "objectForKey:",
                                  appLayout, 0, 0, 0)
                    : 0;
            if (!r_is_objc_ptr(controller) ||
                !themer_springboard_method_encoding_is(
                    controller, "_updateDisplayItemIcons", "v16@0:8") ||
                !themer_springboard_method_encoding_is(
                    controller, "_performUpdateHandler", "v16@0:8")) {
                continue;
            }
            eligibleTitleControllers[titleControllerEligible] = controller;
            eligibleTitleKeys[titleControllerEligible] = appLayout;
            titleControllerEligible++;
        }

        const char *visibleConsumerMapIvars[] = {
            "_visibleItemContainers",
            "_visibleOverlayAccessoryViews",
            "_visibleUnderlayAccessoryViews",
        };
        for (size_t mapIndex = 0;
             mapIndex < sizeof(visibleConsumerMapIvars) /
                        sizeof(visibleConsumerMapIvars[0]); mapIndex++) {
            uint64_t map = r_is_objc_ptr(switcherViewController)
                ? r_ivar_value(switcherViewController,
                               visibleConsumerMapIvars[mapIndex])
                : 0;
            if (!r_is_objc_ptr(map) ||
                !r_responds_main(map, "objectForKey:")) continue;
            themer_add_unique(switcherVisibleConsumerMaps,
                              &switcherVisibleConsumerMapCount, 3, map);
        }

        /* Phase one updates the retained display-item -> SBApplicationIcon
         * identities. Phase two clears only exact, materialized consumers.
         * Phase three rebuilds their title items against the purged 28-point
         * cache. Keep these phases separate so aliases across the three maps
         * are cleared only once before any handler can refill them. */
        for (int index = 0;
             index < titleControllerEligible &&
             remote_call_current_success(); index++) {
            uint64_t controller = eligibleTitleControllers[index];
            r_msg2_main(controller, "_updateDisplayItemIcons",
                        0, 0, 0, 0);
            if (!remote_call_current_success()) break;
            uint64_t appLayout = eligibleTitleKeys[index];
            for (int mapIndex = 0;
                 mapIndex < switcherVisibleConsumerMapCount; mapIndex++) {
                uint64_t consumer = r_msg2_main(
                    switcherVisibleConsumerMaps[mapIndex], "objectForKey:",
                    appLayout, 0, 0, 0);
                if (!r_is_objc_ptr(consumer)) continue;
                if (switcherMaterializedConsumerCount >= 384) {
                    switcherMaterializedConsumersTruncated = true;
                    continue;
                }
                themer_add_unique(
                    switcherMaterializedConsumers,
                    &switcherMaterializedConsumerCount, 384, consumer);
            }
        }
        for (int index = 0;
             index < switcherMaterializedConsumerCount &&
             remote_call_current_success(); index++) {
            uint64_t consumer = switcherMaterializedConsumers[index];
            if (!themer_springboard_method_encoding_is(
                    consumer, "setTitleItems:animated:",
                    "v28@0:8@16B24")) continue;
            switcherMaterializedConsumerEligible++;
            r_msg2_main(consumer, "setTitleItems:animated:",
                        0, 0, 0, 0);
            if (remote_call_current_success()) {
                switcherMaterializedConsumerCleared++;
            }
        }
        for (int index = 0;
             index < titleControllerEligible &&
             remote_call_current_success(); index++) {
            uint64_t controller = eligibleTitleControllers[index];
            r_msg2_main(controller, "_performUpdateHandler",
                        0, 0, 0, 0);
            if (remote_call_current_success()) titleControllerUpdated++;
        }
    }
    bool switcherTitleRefreshOK = remote_call_current_success() &&
        !titleControllersTruncated &&
        !switcherMaterializedConsumersTruncated &&
        switcherMaterializedConsumerEligible ==
            switcherMaterializedConsumerCount &&
        switcherMaterializedConsumerCleared ==
            switcherMaterializedConsumerEligible &&
        titleControllerUpdated == titleControllerEligible;
    printf("[SBR_HOME_REFRESH] switcher-title-refresh application=0x%llx "
           "controller=0x%llx content=0x%llx wrapper=0x%llx map=0x%llx "
           "count=%llu eligible=%d updated=%d visible-maps=%d "
           "materialized=%d cleared=%d/%d truncated=%d "
           "consumer-truncated=%d ok=%d\n",
           (unsigned long long)springBoardApplication,
           (unsigned long long)switcherController,
           (unsigned long long)switcherViewController,
           (unsigned long long)switcherWrapperViewController,
           (unsigned long long)titleControllerMap,
           (unsigned long long)titleControllerCount,
           titleControllerEligible, titleControllerUpdated,
           switcherVisibleConsumerMapCount,
           switcherMaterializedConsumerCount,
           switcherMaterializedConsumerCleared,
           switcherMaterializedConsumerEligible,
           titleControllersTruncated,
           switcherMaterializedConsumersTruncated,
           switcherTitleRefreshOK);

    /* SBIconController.notificationIconImageCache is used by the switcher
     * suggestion banner, not ordinary UserNotificationsUIKit rows. The
     * NCUIMappedImageCache purge above covers BBSectionIcon pixels, while
     * application-identifier recipes fetch the current 38-point IconServices
     * record directly. Existing NCBadgedIconView objects still retain their
     * decoded UIImage, so update both the controller model and those bounded,
     * model-reachable live consumers:
     *
     *   SBLockScreenManager -> cover sheet -> notification dispatcher ->
     *   main page -> combined list -> structured list -> root model ->
     *   notificationSections -> notificationGroups -> requests -> current cell
     *
     * The section method invalidates content providers and reloads leading
     * cells. It does not replace an equal badged-icon description. Disassembly
     * proved NCBadgedIconView -_updateVisibleIcons also skips a non-null
     * UIImageView.image at an unchanged interface style. Clear only those
     * retained image slots, then invoke the exact refill method. No windows or
     * UIKit subviews are scanned. */
    uint64_t notificationRoot = 0;
    uint64_t notificationSections = 0;
    uint64_t notificationSectionCount = 0;
    int notificationEligibleSections = 0;
    int notificationReloadedSections = 0;
    int notificationGroupCount = 0;
    int notificationRequestCount = 0;
    int notificationMaterializedCellCount = 0;
    int notificationBadgedIconCount = 0;
    int notificationBadgedIconEligible = 0;
    int notificationBadgedIconUpdated = 0;
    int notificationImageSlotsCleared = 0;
    bool notificationSectionsTruncated = false;
    bool notificationGroupsTruncated = false;
    bool notificationRequestsTruncated = false;
    enum {
        NOTIFICATION_SECTION_CAP = 16,
        NOTIFICATION_GROUP_CAP = 128,
        NOTIFICATION_REQUEST_CAP = 256,
        NOTIFICATION_BADGED_ICON_CAP = 256,
    };
    uint64_t notificationBadgedIcons[NOTIFICATION_BADGED_ICON_CAP] = {0};
    if (notificationPurgeIssued && notificationMappedCachePurgeIssued &&
        remote_call_current_success()) {
        uint64_t lockManagerClass = themer_lookup_class(
            "SBLockScreenManager");
        uint64_t lockManager = r_is_objc_ptr(lockManagerClass) &&
            r_responds_main(lockManagerClass, "sharedInstance")
                ? r_msg2_main(lockManagerClass, "sharedInstance",
                              0, 0, 0, 0) : 0;
        uint64_t coverSheet = r_is_objc_ptr(lockManager) &&
            r_responds_main(lockManager, "coverSheetViewController")
                ? r_msg2_main(lockManager, "coverSheetViewController",
                              0, 0, 0, 0) : 0;
        uint64_t dispatcher = r_is_objc_ptr(coverSheet)
            ? r_ivar_value(coverSheet, "_notificationDispatcher") : 0;
        uint64_t destination = r_is_objc_ptr(dispatcher)
            ? r_ivar_value(dispatcher, "_listDestination") : 0;
        uint64_t combined = r_is_objc_ptr(destination) &&
            r_responds_main(destination, "combinedListViewController")
                ? r_msg2_main(destination, "combinedListViewController",
                              0, 0, 0, 0) : 0;
        uint64_t structured = r_is_objc_ptr(combined)
            ? r_ivar_value(combined, "_structuredListViewController") : 0;
        notificationRoot = r_is_objc_ptr(structured) &&
            r_responds_main(structured, "listModel")
                ? r_msg2_main(structured, "listModel", 0, 0, 0, 0) : 0;
        notificationSections = r_is_objc_ptr(notificationRoot) &&
            r_responds_main(notificationRoot, "notificationSections")
                ? r_msg2_main(notificationRoot, "notificationSections",
                              0, 0, 0, 0) : 0;
        notificationSectionCount = r_is_objc_ptr(notificationSections) &&
            r_responds_main(notificationSections, "count")
                ? r_msg2_main(notificationSections, "count", 0, 0, 0, 0)
                : 0;

        notificationSectionsTruncated =
            notificationSectionCount > NOTIFICATION_SECTION_CAP;
        uint64_t boundedCount = notificationSectionsTruncated
            ? NOTIFICATION_SECTION_CAP : notificationSectionCount;
        for (uint64_t index = 0;
             index < boundedCount && remote_call_current_success(); index++) {
            uint64_t section = r_msg2_main(
                notificationSections, "objectAtIndex:", index, 0, 0, 0);
            if (!r_is_objc_ptr(section) ||
                !themer_springboard_method_encoding_is(
                    section,
                    "_reloadLeadingNotificationRequestsForStackedNotificationGroupListsWithForceReloadAllStacks:",
                    "v20@0:8B16")) {
                continue;
            }
            notificationEligibleSections++;
            r_msg2_main(
                section,
                "_reloadLeadingNotificationRequestsForStackedNotificationGroupListsWithForceReloadAllStacks:",
                1, 0, 0, 0);
            if (remote_call_current_success()) {
                notificationReloadedSections++;
            }

            uint64_t groups = 0;
            if (remote_call_current_success() &&
                themer_springboard_method_encoding_is(
                    section, "allNotificationGroups", "@16@0:8")) {
                groups = r_msg2_main(section, "allNotificationGroups",
                                     0, 0, 0, 0);
            } else if (remote_call_current_success() &&
                       themer_springboard_method_encoding_is(
                           section, "notificationGroups", "@16@0:8")) {
                groups = r_msg2_main(section, "notificationGroups",
                                     0, 0, 0, 0);
            }
            uint64_t groupCount = r_is_objc_ptr(groups) &&
                r_responds_main(groups, "count")
                    ? r_msg2_main(groups, "count", 0, 0, 0, 0) : 0;
            uint64_t groupRemaining = notificationGroupCount <
                    NOTIFICATION_GROUP_CAP
                ? (uint64_t)(NOTIFICATION_GROUP_CAP -
                             notificationGroupCount) : 0;
            if (groupCount > groupRemaining) {
                notificationGroupsTruncated = true;
                groupCount = groupRemaining;
            }
            for (uint64_t groupIndex = 0;
                 groupIndex < groupCount &&
                 remote_call_current_success(); groupIndex++) {
                uint64_t group = r_msg2_main(
                    groups, "objectAtIndex:", groupIndex, 0, 0, 0);
                notificationGroupCount++;
                if (!r_is_objc_ptr(group) ||
                    !themer_springboard_method_encoding_is(
                        group, "allNotificationRequests", "@16@0:8") ||
                    !themer_springboard_method_encoding_is(
                        group, "_currentCellForNotificationRequest:",
                        "@24@0:8@16")) {
                    continue;
                }
                uint64_t requests = r_msg2_main(
                    group, "allNotificationRequests", 0, 0, 0, 0);
                uint64_t requestCount = r_is_objc_ptr(requests) &&
                    r_responds_main(requests, "count")
                        ? r_msg2_main(requests, "count", 0, 0, 0, 0) : 0;
                uint64_t requestRemaining = notificationRequestCount <
                        NOTIFICATION_REQUEST_CAP
                    ? (uint64_t)(NOTIFICATION_REQUEST_CAP -
                                 notificationRequestCount) : 0;
                if (requestCount > requestRemaining) {
                    notificationRequestsTruncated = true;
                    requestCount = requestRemaining;
                }
                for (uint64_t requestIndex = 0;
                     requestIndex < requestCount &&
                     remote_call_current_success(); requestIndex++) {
                    uint64_t request = r_msg2_main(
                        requests, "objectAtIndex:", requestIndex,
                        0, 0, 0);
                    notificationRequestCount++;
                    if (!r_is_objc_ptr(request)) continue;
                    uint64_t cell = r_msg2_main(
                        group, "_currentCellForNotificationRequest:",
                        request, 0, 0, 0);
                    if (!r_is_objc_ptr(cell)) continue;
                    notificationMaterializedCellCount++;

                    uint64_t notificationViewController =
                        themer_springboard_method_encoding_is(
                            cell, "notificationViewController", "@16@0:8")
                            ? r_msg2_main(
                                cell, "notificationViewController",
                                0, 0, 0, 0) : 0;
                    if (!r_is_objc_ptr(notificationViewController) &&
                        themer_springboard_method_encoding_is(
                            cell, "contentViewController", "@16@0:8")) {
                        notificationViewController = r_msg2_main(
                            cell, "contentViewController", 0, 0, 0, 0);
                    }
                    uint64_t lookView =
                        themer_springboard_method_encoding_is(
                            notificationViewController,
                            "_lookViewIfLoaded", "@16@0:8")
                            ? r_msg2_main(
                                notificationViewController,
                                "_lookViewIfLoaded", 0, 0, 0, 0) : 0;
                    uint64_t contentView =
                        themer_springboard_method_encoding_is(
                            lookView, "notificationContentView", "@16@0:8")
                            ? r_msg2_main(
                                lookView, "notificationContentView",
                                0, 0, 0, 0) : 0;
                    if (!r_is_objc_ptr(contentView) &&
                        themer_springboard_method_encoding_is(
                            lookView, "_notificationContentView", "@16@0:8")) {
                        contentView = r_msg2_main(
                            lookView, "_notificationContentView",
                            0, 0, 0, 0);
                    }
                    uint64_t badgedIcon = r_is_objc_ptr(contentView)
                        ? r_ivar_value(contentView, "_badgedIconView") : 0;
                    if (!r_is_objc_ptr(badgedIcon) &&
                        r_is_objc_ptr(contentView)) {
                        uint64_t nestedContent = r_ivar_value(
                            contentView, "_contentView");
                        badgedIcon = r_is_objc_ptr(nestedContent)
                            ? r_ivar_value(
                                nestedContent, "_badgedIconView") : 0;
                    }
                    char badgedClass[96] = {0};
                    themer_read_class_name(
                        badgedIcon, badgedClass, sizeof(badgedClass));
                    if (strcmp(badgedClass, "NCBadgedIconView")) continue;
                    themer_add_unique(
                        notificationBadgedIcons,
                        &notificationBadgedIconCount,
                        NOTIFICATION_BADGED_ICON_CAP, badgedIcon);
                }
                if (notificationRequestsTruncated) break;
            }
            if (notificationGroupsTruncated ||
                notificationRequestsTruncated) break;
        }
    }

    for (int index = 0;
         index < notificationBadgedIconCount &&
         remote_call_current_success(); index++) {
        uint64_t badgedIcon = notificationBadgedIcons[index];
        if (!themer_springboard_method_encoding_is(
                badgedIcon, "_updateVisibleIcons", "v16@0:8")) {
            continue;
        }
        notificationBadgedIconEligible++;
        const char *imageViewSelectors[] = {
            "iconView", "subordinateIconView",
        };
        for (size_t selectorIndex = 0;
             selectorIndex < sizeof(imageViewSelectors) /
                sizeof(imageViewSelectors[0]); selectorIndex++) {
            uint64_t imageView = themer_springboard_method_encoding_is(
                    badgedIcon, imageViewSelectors[selectorIndex],
                    "@16@0:8")
                ? r_msg2_main(
                    badgedIcon, imageViewSelectors[selectorIndex],
                    0, 0, 0, 0) : 0;
            if (!r_is_objc_ptr(imageView) ||
                !themer_springboard_method_encoding_is(
                    imageView, "setImage:", "v24@0:8@16")) {
                continue;
            }
            r_msg2_main(imageView, "setImage:", 0, 0, 0, 0);
            if (remote_call_current_success()) {
                notificationImageSlotsCleared++;
            }
        }
        if (!remote_call_current_success()) break;
        r_msg2_main(badgedIcon, "_updateVisibleIcons", 0, 0, 0, 0);
        if (remote_call_current_success()) {
            notificationBadgedIconUpdated++;
        }
    }
    bool notificationRowsRefreshOK = remote_call_current_success() &&
        !notificationSectionsTruncated &&
        !notificationGroupsTruncated &&
        !notificationRequestsTruncated &&
        notificationSectionCount > 0 &&
        notificationEligibleSections == (int)notificationSectionCount &&
        notificationEligibleSections == notificationReloadedSections &&
        notificationBadgedIconEligible == notificationBadgedIconUpdated;
    printf("[SBR_HOME_REFRESH] notification-root=0x%llx sections=%llu "
           "eligible=%d reloaded=%d groups=%d requests=%d cells=%d "
           "badged=%d/%d cleared=%d truncated=%d/%d/%d "
           "view-tree-walk=0 ok=%d\n",
           (unsigned long long)notificationRoot,
           (unsigned long long)notificationSectionCount,
           notificationEligibleSections, notificationReloadedSections,
           notificationGroupCount, notificationRequestCount,
           notificationMaterializedCellCount,
           notificationBadgedIconUpdated,
           notificationBadgedIconEligible,
           notificationImageSlotsCleared,
           notificationSectionsTruncated,
           notificationGroupsTruncated,
           notificationRequestsTruncated,
           notificationRowsRefreshOK);

    /* Folder previews are precomposed. Rebuild the registered composites
     * before the explicit App Library refresh and Home relayout rebind their
     * visible icon views. */
    bool folderRebuildIssued = resetIssued && folderSourcePurgeIssued &&
        reloadIconsOK &&
        remote_call_current_success() && r_is_objc_ptr(folderImageCache) &&
        themer_springboard_method_encoding_is(
            folderImageCache, "rebuildAllCachedFolderImages", "v16@0:8");
    printf("[SBR_HOME_REFRESH] stage=rebuild-folders\n");
    if (folderRebuildIssued) {
        r_msg2_main(folderImageCache, "rebuildAllCachedFolderImages",
                    0, 0, 0, 0);
        folderRebuildIssued = remote_call_current_success();
    }

    /* Do not assume SBHIconManager -relayout always forwards into an
     * off-screen or already-materialized App Library.  The VM trace proved
     * these are the stock, bounded App Library refresh boundaries on iOS 26:
     * the folder controller rebuilds its application icons, then the library
     * controller enqueues its own pod update.  The alphabetical/search table
     * is a separate consumer: after its own cache has been purged, rebuild
     * the table's icon set and reconfigure only its materialized rows.  This
     * remains bounded to four known controllers and never walks a view tree
     * or iterates the installed application catalog. */
    int libraryReloadEligible = 0;
    int libraryReloaded = 0;
    int libraryEnqueueEligible = 0;
    int libraryEnqueued = 0;
    printf("[SBR_HOME_REFRESH] stage=reload-app-library\n");
    for (int index = 0;
         folderRebuildIssued && index < libraryControllerCount &&
         remote_call_current_success(); index++) {
        uint64_t controller = libraryControllers[index];
        uint64_t folderController =
            themer_springboard_method_encoding_is(
                controller, "folderController", "@16@0:8")
                ? r_msg2_main(controller, "folderController", 0, 0, 0, 0)
                : 0;
        if (r_is_objc_ptr(folderController) &&
            themer_springboard_method_encoding_is(
                folderController, "_reloadAppIcons", "v16@0:8")) {
            libraryReloadEligible++;
            r_msg2_main(folderController, "_reloadAppIcons", 0, 0, 0, 0);
            if (remote_call_current_success()) libraryReloaded++;
        }
        if (remote_call_current_success() &&
            themer_springboard_method_encoding_is(
                controller, "_enqueueAppLibraryUpdate", "v16@0:8")) {
            libraryEnqueueEligible++;
            r_msg2_main(controller, "_enqueueAppLibraryUpdate",
                        0, 0, 0, 0);
            if (remote_call_current_success()) libraryEnqueued++;
        }
    }
    bool libraryRefreshOK = remote_call_current_success() &&
        libraryControllerCount > 0 && libraryCacheCount > 0 &&
        libraryCachesPurged == libraryCacheCount &&
        libraryReloadEligible > 0 &&
        libraryReloaded == libraryReloadEligible &&
        libraryEnqueueEligible > 0 &&
        libraryEnqueued == libraryEnqueueEligible;

    int libraryTableAppReloadEligible = 0;
    int libraryTableAppReloaded = 0;
    int libraryTableVisibleReloadEligible = 0;
    int libraryTableVisibleReloaded = 0;
    printf("[SBR_HOME_REFRESH] stage=reload-app-library-table "
           "controllers=%d caches=%d purged=%d\n",
           libraryTableControllerCount, libraryTableCacheCount,
           libraryTableCachesPurged);
    for (int index = 0;
         libraryRefreshOK && index < libraryTableControllerCount &&
         remote_call_current_success(); index++) {
        uint64_t controller = libraryTableControllers[index];
        if (themer_springboard_method_encoding_is(
                controller, "_reloadAppIcons", "v16@0:8")) {
            libraryTableAppReloadEligible++;
            r_msg2_main(controller, "_reloadAppIcons", 0, 0, 0, 0);
            if (remote_call_current_success()) {
                libraryTableAppReloaded++;
            }
        }
        if (remote_call_current_success() &&
            themer_springboard_method_encoding_is(
                controller, "_reloadVisibleCells", "v16@0:8")) {
            libraryTableVisibleReloadEligible++;
            r_msg2_main(controller, "_reloadVisibleCells", 0, 0, 0, 0);
            if (remote_call_current_success()) {
                libraryTableVisibleReloaded++;
            }
        }
    }
    bool libraryTableRefreshOK = remote_call_current_success() &&
        libraryTableControllerCount > 0 &&
        libraryTableCacheCount > 0 &&
        libraryTableCachesPurged == libraryTableCacheCount &&
        libraryTableAppReloadEligible == libraryTableControllerCount &&
        libraryTableAppReloaded == libraryTableAppReloadEligible &&
        libraryTableVisibleReloadEligible == libraryTableControllerCount &&
        libraryTableVisibleReloaded == libraryTableVisibleReloadEligible;

    bool relayoutIssued = folderRebuildIssued &&
        libraryRefreshOK && libraryTableRefreshOK &&
        r_is_objc_ptr(iconManager) &&
        themer_springboard_method_encoding_is(
            iconManager, "relayout", "B16@0:8");
    printf("[SBR_HOME_REFRESH] stage=relayout-home-library\n");
    if (relayoutIssued) {
        uint64_t relayoutResult = r_msg2_main(
            iconManager, "relayout", 0, 0, 0, 0);
        relayoutIssued = remote_call_current_success() &&
            ((relayoutResult & 0xff) != 0);
    }

    bool ok = remote_call_current_success() && resetIssued &&
        rootFolderCacheRebound &&
        notificationPurgeIssued && notificationMappedCachePurgeIssued &&
        tableUIPurgeIssued &&
        appSwitcherPurgeIssued && folderSourcePurgeIssued &&
        switcherTitleRefreshOK &&
        notificationRowsRefreshOK &&
        reloadIconsOK && folderRebuildIssued && libraryRefreshOK &&
        libraryTableRefreshOK && relayoutIssued;
    printf("[SBR_SURFACE] surface=home cache=0x%llx reload=%d/%d "
           "relayout=%d ok=%d\n",
           (unsigned long long)imageCache, reloadIconIssued,
           reloadIconEligible, relayoutIssued,
           rootFolderCacheRebound && reloadIconsOK && relayoutIssued);
    printf("[SBR_SURFACE] surface=folder-preview cache=0x%llx "
           "source=0x%llx source-purge=%d child-reload=%d rebuild=%d "
           "ok=%d\n",
           (unsigned long long)folderImageCache,
           (unsigned long long)folderSourceCache, folderSourcePurgeIssued,
           reloadIconsOK, folderRebuildIssued,
           folderSourcePurgeIssued && reloadIconsOK && folderRebuildIssued);
    printf("[SBR_SURFACE] surface=app-switcher cache=0x%llx "
           "titles=%d/%d retained-consumers=%d/%d ok=%d\n",
           (unsigned long long)appSwitcherCache, titleControllerUpdated,
           titleControllerEligible,
           switcherMaterializedConsumerCleared,
           switcherMaterializedConsumerEligible,
           appSwitcherPurgeIssued && switcherTitleRefreshOK);
    printf("[SBR_SURFACE] surface=app-library-category cache=0x%llx "
           "cache-purge=%d/%d pods=%d/%d enqueue=%d/%d ok=%d\n",
           (unsigned long long)(libraryCacheCount ? libraryCaches[0] : 0),
           libraryCachesPurged, libraryCacheCount,
           libraryReloaded, libraryReloadEligible,
           libraryEnqueued, libraryEnqueueEligible, libraryRefreshOK);
    printf("[SBR_SURFACE] surface=app-library-list cache=0x%llx "
           "cache-purge=%d/%d app-reload=%d/%d visible=%d/%d ok=%d\n",
           (unsigned long long)(libraryTableCacheCount
               ? libraryTableCaches[0] : 0),
           libraryTableCachesPurged, libraryTableCacheCount,
           libraryTableAppReloaded, libraryTableAppReloadEligible,
           libraryTableVisibleReloaded, libraryTableVisibleReloadEligible,
           libraryTableRefreshOK);
    printf("[SBR_SURFACE] surface=notifications auxiliary-cache=0x%llx "
           "mapped-cache=0x%llx mapped-keys=%llu->%llu "
           "sections=%d/%d cells=%d badged-refetch=%d/%d ok=%d\n",
           (unsigned long long)notificationCache,
           (unsigned long long)notificationMappedCache,
           (unsigned long long)notificationMappedKeyCountBefore,
           (unsigned long long)notificationMappedKeyCountAfter,
           notificationReloadedSections, notificationEligibleSections,
           notificationMaterializedCellCount,
           notificationBadgedIconUpdated,
           notificationBadgedIconEligible,
           notificationPurgeIssued &&
               notificationMappedCachePurgeIssued &&
               notificationRowsRefreshOK);
    printf("[SBR_SURFACE] surface=launch-return cache=0x%llx "
           "app-generations=%d/%d ok=%d\n",
           (unsigned long long)imageCache, reloadIconIssued,
           reloadIconEligible, resetIssued && reloadIconsOK);
    printf("[SBR_HOME_REFRESH] roots=%d controller=0x%llx/%s "
           "manager=0x%llx/%s model=0x%llx/%s cache=0x%llx/%s "
           "notification=0x%llx/%s table=0x%llx/%s "
           "switcher=0x%llx/%s folder=0x%llx/%s "
           "notification-mapped=0x%llx/%s "
           "reset=%d explicit-purges=%d/%d notification-purge=%d "
           "notification-mapped-purge=%d "
           "table-purge=%d switcher-purge=%d folder-source-purge=%d "
           "root-cache-rebind=%d "
           "notification-reload=%d/%d notification-badged=%d/%d "
           "icon-reload=%d/%d icon-objects=%d canonical=%d leaf=%d "
           "switcher-title=%d/%d switcher-consumers=%d/%d "
           "folder-rebuild=%d "
           "library=%d library-caches=%d/%d reload=%d/%d enqueue=%d/%d "
           "library-refresh=%d search-controllers=%d "
           "table-controllers=%d table-caches=%d table-cache-purge=%d/%d "
           "table-app-reload=%d/%d table-visible-reload=%d/%d "
           "table-refresh=%d relayout=%d "
           "view-tree-walk=0 themed-icon-iteration=%llu ok=%d\n",
           rootCount,
           (unsigned long long)iconController,
           iconControllerClass[0] ? iconControllerClass : "-",
           (unsigned long long)iconManager,
           iconManagerClass[0] ? iconManagerClass : "-",
           (unsigned long long)iconModel,
           iconModelClass[0] ? iconModelClass : "-",
           (unsigned long long)imageCache,
           imageCacheClass[0] ? imageCacheClass : "-",
           (unsigned long long)notificationCache,
           notificationCacheClass[0] ? notificationCacheClass : "-",
           (unsigned long long)tableUICache,
           tableUICacheClass[0] ? tableUICacheClass : "-",
           (unsigned long long)appSwitcherCache,
           appSwitcherCacheClass[0] ? appSwitcherCacheClass : "-",
           (unsigned long long)folderImageCache,
           folderImageCacheClass[0] ? folderImageCacheClass : "-",
           (unsigned long long)notificationMappedCache,
           notificationMappedCacheClassName[0]
               ? notificationMappedCacheClassName : "-",
           resetIssued, explicitPurgeCount, explicitCacheCount,
           notificationPurgeIssued, notificationMappedCachePurgeIssued,
           tableUIPurgeIssued,
           appSwitcherPurgeIssued, folderSourcePurgeIssued,
           rootFolderCacheRebound,
           notificationReloadedSections, notificationEligibleSections,
           notificationBadgedIconUpdated,
           notificationBadgedIconEligible,
           reloadIconIssued, reloadIconEligible,
           reloadIconObjectCount, reloadCanonicalMatches,
           reloadLeafMatches,
           titleControllerUpdated, titleControllerEligible,
           switcherMaterializedConsumerCleared,
           switcherMaterializedConsumerEligible,
           folderRebuildIssued,
           libraryControllerCount, libraryCachesPurged, libraryCacheCount,
           libraryReloaded, libraryReloadEligible,
           libraryEnqueued, libraryEnqueueEligible,
           libraryRefreshOK,
           librarySearchControllerCount,
           libraryTableControllerCount, libraryTableCacheCount,
           libraryTableCachesPurged, libraryTableCacheCount,
           libraryTableAppReloaded, libraryTableAppReloadEligible,
           libraryTableVisibleReloaded,
           libraryTableVisibleReloadEligible,
           libraryTableRefreshOK,
           relayoutIssued, (unsigned long long)reloadIconCount, ok);
    (void)r_settle_us(previousSettleUS);
    printf("[SBR_HOME_REFRESH] stage=complete ok=%d settle-us-restored=%u\n",
           ok, previousSettleUS);
    return ok;
}

static int themer_graft_icon_models_for_theme_options(NSDictionary<NSString *, NSData *> *dataByBundle,
                                                      int *misses,
                                                      bool forceRefresh)
{
    if (!remote_call_current_success()) return 0;
    int grafted = 0;
    int modelMisses = 0;
    int decodeMisses = 0;
    int lookupMisses = 0;
    int graftMisses = 0;
    int skippedMissingApps = 0;
    int seededBundles = 0;
    int seededDescriptors = 0;
    NSMutableArray<NSString *> *missSamples = [NSMutableArray array];
    NSMutableArray<NSString *> *skipSamples = [NSMutableArray array];
    enum { ROOT_CAP = 24 };
    uint64_t roots[ROOT_CAP] = {0};
    int rootCount = themer_collect_model_lookup_roots(roots, ROOT_CAP);
    if (!remote_call_current_success()) return 0;
    printf("[THEMER] model pass lookup roots=%d entries=%lu\n",
           rootCount,
           (unsigned long)dataByBundle.count);
    for (NSString *key in dataByBundle) {
        if (!remote_call_current_success()) break;
        if (![key isKindOfClass:NSString.class] || key.length == 0) continue;
        const char *bundle = key.UTF8String;
        if (!bundle || !bundle[0]) continue;

        if (kThemerFocusBundle && kThemerFocusBundle[0] &&
            strcmp(bundle, kThemerFocusBundle) != 0) {
            continue;
        }

        NSData *pngBytes = dataByBundle[key];
        if (![pngBytes isKindOfClass:NSData.class] || pngBytes.length == 0) continue;

        uint64_t icon = themer_lookup_model_icon_for_bundle_with_roots(bundle,
                                                                       roots,
                                                                       rootCount);
        if (!remote_call_current_success()) break;
        if (!r_is_objc_ptr(icon)) {
            skippedMissingApps++;
            lookupMisses++;
            if (skipSamples.count < 48) {
                [skipSamples addObject:[NSString stringWithFormat:@"%s", bundle]];
            }
            continue;
        }

        uint64_t image = themer_lookup_cached(bundle);
        if (!image) {
            NSData *uploadBytes = themer_rounded_png_data(pngBytes, bundle);
            image = themer_build_remote_uiimage_from_data(uploadBytes ?: pngBytes, bundle);
            if (!remote_call_current_success()) break;
            if (!image) {
                modelMisses++;
                decodeMisses++;
                if (missSamples.count < 48) {
                    [missSamples addObject:[NSString stringWithFormat:@"%s:decode", bundle]];
                }
                continue;
            }
            themer_cache_image(bundle, image);
        }

        ThemerEntry *entry = themer_lookup_entry(bundle);
        if (forceRefresh && entry) {
            entry->iconServicesSeeded = false;
            entry->modelGrafted = false;
        }

        // Match the supplied 1.5 model lifecycle: invalidate the old renderer
        // result before reseeding and installing the persistent model graft.
        (void)themer_notify_icon_image_changed(icon);
        if (!remote_call_current_success()) break;

        int seededCount = 0;
        if (kThemerIconServicesApplySeedEnabled &&
            entry && (forceRefresh || !entry->iconServicesSeeded)) {
            seededCount = themer_seed_iconservices_cache(bundle, image, 60.0);
            if (!remote_call_current_success()) break;
            entry->iconServicesSeeded = seededCount > 0;
            if (seededCount > 0) {
                seededBundles++;
                seededDescriptors += seededCount;
            }
        }

        bool changed = false;
        if (entry && themer_graft_icon_model(icon, image, entry, 0, &changed)) {
            if (!remote_call_current_success()) break;
            entry->modelGrafted = true;
            (void)themer_notify_icon_image_changed(icon);
            if (!remote_call_current_success()) break;
            grafted++;
        } else {
            if (!remote_call_current_success()) break;
            modelMisses++;
            graftMisses++;
            if (missSamples.count < 48) {
                [missSamples addObject:[NSString stringWithFormat:@"%s:graft", bundle]];
            }
        }
    }

    if (misses) *misses += modelMisses;
    printf("[THEMER] model pass grafted=%d misses=%d decode=%d lookup=%d graft=%d skippedMissingApps=%d seededBundles=%d seededDesc=%d force=%d cache=%d samples=%s skipped=%s\n",
           grafted, modelMisses, decodeMisses, lookupMisses, graftMisses,
           skippedMissingApps,
           seededBundles,
           seededDescriptors,
           forceRefresh,
           gThemerCacheCount,
           missSamples.count ? [missSamples componentsJoinedByString:@","].UTF8String : "",
           skipSamples.count ? [skipSamples componentsJoinedByString:@","].UTF8String : "");
    return grafted;
}

static bool themer_repaint_cached_views_internal(bool force, bool repaintNotifications)
{
    if (!remote_call_current_success() || gThemerCacheCount <= 0) {
        printf("[THEMER] cached repaint skipped; cache empty\n");
        return false;
    }

    uint64_t startUS = themer_now_us();
    uint32_t prevSettle = r_settle_us(kThemerApplySettleUS);

    uint64_t listViewCls = r_class("SBIconListView");
    if (!remote_call_current_success()) {
        r_settle_us(prevSettle);
        return false;
    }
    uint64_t iconViewCls = r_class("SBIconView");
    if (!remote_call_current_success()) {
        r_settle_us(prevSettle);
        return false;
    }
    if (!r_is_objc_ptr(listViewCls) || !r_is_objc_ptr(iconViewCls)) {
        r_settle_us(prevSettle);
        return false;
    }

    enum { LV_CAP = 64 };
    uint64_t lvs[LV_CAP];
    int nlv = sb_collect_views_in_windows(listViewCls, lvs, LV_CAP);
    if (!remote_call_current_success()) {
        r_settle_us(prevSettle);
        return false;
    }
    if (nlv == 0) {
        r_settle_us(prevSettle);
        printf("[THEMER] cached repaint: no visible SBIconListView\n");
        return false;
    }

    int rungHits[4] = {0};
    int misses = 0;
    int skips = 0;
    int paintFails = 0;
    int applied = 0;
    for (int i = 0; i < nlv; i++) {
        if (!remote_call_current_success()) break;
        applied += themer_repaint_cached_iconviews(lvs[i], iconViewCls,
                                                   rungHits, &misses, &skips,
                                                   &paintFails,
                                                   force);
    }

    int notifSkinned = (remote_call_current_success() && force && repaintNotifications)
        ? themer_repaint_notification_icons_from_cache_internal() : 0;

    r_settle_us(prevSettle);
    uint64_t elapsedUS = themer_now_us() - startUS;
    printf("[THEMER] cached repaint%s lists=%d applied=%d skipped=%d misses=%d paintFail=%d notif=%d rungs={1:%d,2:%d,3:%d,4:%d} cache=%d elapsed=%llums\n",
           force ? " force" : "",
           nlv, applied, skips, misses, paintFails, notifSkinned,
           rungHits[0], rungHits[1], rungHits[2], rungHits[3],
           gThemerCacheCount,
           (unsigned long long)(elapsedUS / 1000ULL));
    return remote_call_current_success() &&
           (applied > 0 || skips > 0 || notifSkinned > 0);
}

bool themer_repaint_cached_views_in_session(void)
{
    return themer_repaint_cached_views_internal(false, false);
}

bool themer_force_repaint_cached_views_in_session(void)
{
    return themer_repaint_cached_views_internal(true, true);
}

bool themer_force_repaint_cached_icon_views_in_session(void)
{
    return themer_repaint_cached_views_internal(true, false);
}

bool themer_repaint_dynamic_cached_views_in_session(void)
{
