        r_settle_us(prevSettle);
        return false;
    }
    if (!r_is_objc_ptr(listViewCls) || !r_is_objc_ptr(iconViewCls)) {
        r_settle_us(prevSettle);
        return false;
    }

    enum { LV_CAP = 64 };
    uint64_t lvs[LV_CAP];
