    for (int i = 0; i < nlv; i++) {
        if (!remote_call_current_success()) break;
        applied += themer_repaint_dynamic_iconviews(lvs[i], iconViewCls,
                                                    rungHits, &misses);
    }

    uint64_t elapsed = (themer_now_us() - startUS) / 1000ULL;
