bool themer_repair_static_dynamic_visible_icons_in_session(void)
{
    if (!remote_call_current_success()) return false;
    uint64_t startUS = themer_now_us();
    uint32_t prevSettle = r_settle_us(kThemerApplySettleUS);

    int directApplied = 0;
    uint64_t clockImage = themer_lookup_cached("com.apple.mobiletimer");
    if (r_is_objc_ptr(clockImage)) {
        directApplied = themer_apply_static_dynamic_image_view_class(
            "SBHClockApplicationIconImageView",
