    printf("[THEMER] static dynamic clock direct repair applied=%d cache=%d elapsed=%llums\n",
           directApplied,
           gThemerCacheCount,
           (unsigned long long)elapsed);
    return remote_call_current_success() && directApplied > 0;
}

static NSSet<NSString *> *themer_collect_visible_bundles(void)
{
    if (!remote_call_current_success()) return [NSSet set];
    uint64_t listViewCls = r_class("SBIconListView");
    if (!remote_call_current_success()) return [NSSet set];
    uint64_t iconViewCls = r_class("SBIconView");
    if (!remote_call_current_success()) return [NSSet set];
    if (!r_is_objc_ptr(listViewCls) || !r_is_objc_ptr(iconViewCls)) return [NSSet set];

    enum { LV_CAP = 64 };
    uint64_t lvs[LV_CAP];
    int nlv = sb_collect_views_in_windows(listViewCls, lvs, LV_CAP);
    if (!remote_call_current_success()) return [NSSet set];
    if (nlv == 0) return [NSSet set];

    NSMutableSet<NSString *> *bundles = [NSMutableSet set];
    for (int i = 0; i < nlv; i++) {
        if (!remote_call_current_success()) break;
        enum { IV_CAP = 64 };
        uint64_t ivs[IV_CAP];
        int n = sb_collect_views(lvs[i], iconViewCls, ivs, IV_CAP);
        if (!remote_call_current_success()) break;
        for (int j = 0; j < n; j++) {
            if (!remote_call_current_success()) break;
            char bundle[128] = {0};
            if (themer_read_bundle_for_iconview(ivs[j], bundle, sizeof(bundle)) && bundle[0]) {
                [bundles addObject:@(bundle)];
            }
        }
    }
    return bundles;
}

static uint64_t themer_lookup_cached_image_for_string_key(NSString *key,
                                                          NSString **matchedKeyOut)
{
    if (matchedKeyOut) *matchedKeyOut = nil;
    if (![key isKindOfClass:NSString.class] || key.length == 0) return 0;

    const char *utf8 = key.UTF8String;
    uint64_t exact = utf8 ? themer_lookup_cached(utf8) : 0;
    if (r_is_objc_ptr(exact)) {
        if (matchedKeyOut) *matchedKeyOut = key;
        return exact;
    }

    for (int i = 0; i < gThemerCacheCount; i++) {
        NSString *candidate = @(gThemerCache[i].bundle);
        if ([candidate caseInsensitiveCompare:key] != NSOrderedSame) continue;
        if (!r_is_objc_ptr(gThemerCache[i].image)) continue;
        if (matchedKeyOut) *matchedKeyOut = candidate;
        return gThemerCache[i].image;
    }

    return 0;
}

static uint64_t themer_lookup_cached_image_for_notification_bundle(const char *rawBundle,
                                                                  char *matchedOut,
                                                                  size_t matchedLen)
{
    if (matchedOut && matchedLen) matchedOut[0] = '\0';
    if (!rawBundle || !rawBundle[0]) return 0;

    NSString *raw = [NSString stringWithUTF8String:rawBundle];
    if (raw.length == 0) return 0;

    NSMutableArray<NSString *> *candidates = [NSMutableArray array];
    NSMutableSet<NSString *> *seen = [NSMutableSet set];
    void (^addCandidate)(NSString *) = ^(NSString *candidate) {
        if (![candidate isKindOfClass:NSString.class] || candidate.length == 0) return;
        if ([seen containsObject:candidate]) return;
        [seen addObject:candidate];
        [candidates addObject:candidate];
    };

    addCandidate(raw);
    addCandidate(raw.lowercaseString);

    BOOL usedAlias = NO;
    NSArray<NSString *> *mapped = CNDMappedIOSBundleIDsForIconName(raw, &usedAlias);
    (void)usedAlias;
    for (NSString *candidate in mapped) addCandidate(candidate);

    for (NSString *candidate in candidates) {
        NSString *matched = nil;
        uint64_t image = themer_lookup_cached_image_for_string_key(candidate, &matched);
        if (!r_is_objc_ptr(image)) continue;
        if (matchedOut && matchedLen) {
            snprintf(matchedOut, matchedLen, "%s",
                     (matched ?: candidate).UTF8String ?: "");
        }
        return image;
    }

    return 0;
}

static uint64_t themer_try_msg0_any(uint64_t obj, const char *selName)
{
    if (!r_is_objc_ptr(obj) || !selName || !r_responds(obj, selName)) return 0;
    return r_msg2(obj, selName, 0, 0, 0, 0);
}

static uint64_t themer_try_msg0_main(uint64_t obj, const char *selName)
{
    if (!r_is_objc_ptr(obj) || !selName || !r_responds_main(obj, selName)) return 0;
    return r_msg2_main(obj, selName, 0, 0, 0, 0);
}

static uint64_t themer_try_ivar_or_msg0_any(uint64_t obj,
                                            const char *ivarName,
                                            const char *selName)
{
    uint64_t value = ivarName ? r_ivar_value(obj, ivarName) : 0;
    if (!r_is_objc_ptr(value) && selName) value = themer_try_msg0_any(obj, selName);
    return r_is_objc_ptr(value) ? value : 0;
}

static uint64_t themer_try_ivar_or_msg0_main(uint64_t obj,
                                             const char *ivarName,
                                             const char *selName)
{
    uint64_t value = ivarName ? r_ivar_value(obj, ivarName) : 0;
    if (!r_is_objc_ptr(value) && selName) value = themer_try_msg0_main(obj, selName);
    return r_is_objc_ptr(value) ? value : 0;
}

static bool themer_read_notification_section_bundle(uint64_t obj,
                                                    char *out,
                                                    size_t outLen)
{
    if (!r_is_objc_ptr(obj) || !out || outLen == 0) return false;
    out[0] = '\0';

    static const struct {
        const char *ivarName;
        const char *selName;
    } sectionSources[] = {
        { "_sectionIdentifier", "sectionIdentifier" },
        { "_parentSectionIdentifier", "parentSectionIdentifier" },
        { "_sectionID", "sectionID" },
        { "_publisherSectionIdentifier", "publisherSectionIdentifier" },
    };

    for (size_t i = 0; i < sizeof(sectionSources) / sizeof(sectionSources[0]); i++) {
        uint64_t value = themer_try_ivar_or_msg0_any(obj,
                                                     sectionSources[i].ivarName,
                                                     sectionSources[i].selName);
        if (r_is_objc_ptr(value) && r_read_nsstring(value, out, outLen) && out[0]) {
            return true;
        }
    }

    uint64_t bulletin = themer_try_ivar_or_msg0_any(obj, "_bulletin", "bulletin");
    if (r_is_objc_ptr(bulletin) && bulletin != obj) {
        for (size_t i = 0; i < sizeof(sectionSources) / sizeof(sectionSources[0]); i++) {
            uint64_t value = themer_try_ivar_or_msg0_any(bulletin,
                                                         sectionSources[i].ivarName,
                                                         sectionSources[i].selName);
            if (r_is_objc_ptr(value) && r_read_nsstring(value, out, outLen) && out[0]) {
                return true;
            }
        }
    }

    return false;
}

static bool themer_read_notification_bundle_for_view(uint64_t view,
                                                     char *out,
                                                     size_t outLen)
{
    if (!r_is_objc_ptr(view) || !out || outLen == 0) return false;
    out[0] = '\0';

    uint64_t cursor = view;
    for (int depth = 0; r_is_objc_ptr(cursor) && depth < 10; depth++) {
        if (themer_read_notification_section_bundle(cursor, out, outLen)) {
            return true;
        }

        uint64_t req = themer_try_ivar_or_msg0_main(cursor,
                                                    "_notificationRequest",
                                                    "notificationRequest");
        if (r_is_objc_ptr(req) &&
            themer_read_notification_section_bundle(req, out, outLen)) {
            return true;
        }

        uint64_t contentVC = themer_try_ivar_or_msg0_main(cursor,
                                                          "_contentViewController",
                                                          "contentViewController");
        if (r_is_objc_ptr(contentVC)) {
            if (themer_read_notification_section_bundle(contentVC, out, outLen)) {
                return true;
            }
            req = themer_try_ivar_or_msg0_main(contentVC,
                                               "_notificationRequest",
                                               "notificationRequest");
            if (r_is_objc_ptr(req) &&
                themer_read_notification_section_bundle(req, out, outLen)) {
                return true;
            }
        }

        cursor = themer_try_msg0_main(cursor, "superview");
    }

    return false;
}

static bool themer_set_notification_image_view(uint64_t imageView,
                                               uint64_t image)
{
    if (!r_is_objc_ptr(imageView) || !r_is_objc_ptr(image)) return false;
    bool changed = false;
    if (r_responds_main(imageView, "setImage:")) {
        r_msg2_main(imageView, "setImage:", image, 0, 0, 0);
        changed = true;
    }
    if (r_responds_main(imageView, "setHighlightedImage:")) {
        r_msg2_main(imageView, "setHighlightedImage:", image, 0, 0, 0);
    }
    if (r_responds_main(imageView, "setNeedsDisplay")) {
        r_msg2_main(imageView, "setNeedsDisplay", 0, 0, 0, 0);
    }
    return changed;
}

static int themer_set_notification_icon_image(uint64_t iconHostView,
                                              uint64_t image)
{
    if (!r_is_objc_ptr(iconHostView) || !r_is_objc_ptr(image)) return 0;

    uint64_t imageViews[8] = {0};
    int count = 0;

    static const struct {
        const char *ivarName;
        const char *selName;
    } directImageViews[] = {
        { "_prominentImageView", "_prominentImageView" },
        { "_imageView", "imageView" },
        { "_iconImageView", "iconImageView" },
    };

    for (size_t i = 0; i < sizeof(directImageViews) / sizeof(directImageViews[0]); i++) {
        uint64_t iv = themer_try_ivar_or_msg0_main(iconHostView,
                                                   directImageViews[i].ivarName,
                                                   directImageViews[i].selName);
        if (!r_is_objc_ptr(iv)) continue;
        bool seen = false;
        for (int j = 0; j < count; j++) {
            if (imageViews[j] == iv) { seen = true; break; }
        }
        if (!seen && count < (int)(sizeof(imageViews) / sizeof(imageViews[0]))) {
            imageViews[count++] = iv;
        }
    }

    uint64_t imageViewCls = r_class("UIImageView");
    if (r_is_objc_ptr(imageViewCls) && count < (int)(sizeof(imageViews) / sizeof(imageViews[0]))) {
        uint64_t found[8];
        int n = sb_collect_views(iconHostView, imageViewCls, found, 8);
        for (int i = 0; i < n && count < (int)(sizeof(imageViews) / sizeof(imageViews[0])); i++) {
            bool seen = false;
            for (int j = 0; j < count; j++) {
                if (imageViews[j] == found[i]) { seen = true; break; }
            }
            if (!seen) imageViews[count++] = found[i];
        }
    }

    int changed = 0;
    for (int i = 0; i < count; i++) {
        if (themer_set_notification_image_view(imageViews[i], image)) changed++;
    }

    if (r_responds_main(iconHostView, "setNeedsLayout")) {
        r_msg2_main(iconHostView, "setNeedsLayout", 0, 0, 0, 0);
    }
    if (r_responds_main(iconHostView, "setNeedsDisplay")) {
        r_msg2_main(iconHostView, "setNeedsDisplay", 0, 0, 0, 0);
    }

    return changed;
}

static int themer_repaint_notification_icons_from_cache_internal(void)
{
    if (gThemerCacheCount <= 0) return 0;

    uint64_t badgedCls = themer_lookup_class("NCBadgedIconView");
    if (!r_is_objc_ptr(badgedCls)) {
        if (!gThemerNotificationClassLogged) {
            gThemerNotificationClassLogged = true;
            printf("[THEMER] notification skin skipped: NCBadgedIconView unavailable\n");
        }
        return 0;
    }

    enum { NOTIF_CAP = 96 };
    uint64_t hosts[NOTIF_CAP];
    int n = sb_collect_views_in_windows(badgedCls, hosts, NOTIF_CAP);
    if (n <= 0) return 0;

    int skinned = 0;
    int misses = 0;
    int bundleMisses = 0;
    int imageMisses = 0;
    int setMisses = 0;

    for (int i = 0; i < n; i++) {
        uint64_t host = hosts[i];
        if (!r_is_objc_ptr(host)) continue;

        char rawBundle[160] = {0};
        if (!themer_read_notification_bundle_for_view(host,
                                                      rawBundle,
                                                      sizeof(rawBundle))) {
            bundleMisses++;
            misses++;
            if (gThemerNotificationLogBudget > 0) {
                char cls[96] = {0};
                themer_read_class_name(host, cls, sizeof(cls));
                printf("[THEMER] notif skin miss host=0x%llx class=%s reason=no-section\n",
                       (unsigned long long)host, cls);
                gThemerNotificationLogBudget--;
            }
            continue;
        }

        char matched[160] = {0};
        uint64_t image = themer_lookup_cached_image_for_notification_bundle(rawBundle,
                                                                           matched,
                                                                           sizeof(matched));
        if (!r_is_objc_ptr(image)) {
            imageMisses++;
            misses++;
            if (gThemerNotificationLogBudget > 0) {
                printf("[THEMER] notif skin miss raw=%s reason=no-themed-image\n",
                       rawBundle);
                gThemerNotificationLogBudget--;
            }
            continue;
        }

        int changed = themer_set_notification_icon_image(host, image);
        if (changed > 0) {
            skinned++;
            if (gThemerNotificationLogBudget > 0) {
                printf("[THEMER] notif skin raw=%s matched=%s imageViews=%d\n",
                       rawBundle, matched[0] ? matched : rawBundle, changed);
                gThemerNotificationLogBudget--;
            }
        } else {
            setMisses++;
            misses++;
            if (gThemerNotificationLogBudget > 0) {
                printf("[THEMER] notif skin miss raw=%s matched=%s reason=no-image-view\n",
                       rawBundle, matched[0] ? matched : rawBundle);
                gThemerNotificationLogBudget--;
            }
        }
    }

    if (skinned > 0 || misses > 0) {
        printf("[THEMER] notification skin hosts=%d skinned=%d misses=%d bundleMiss=%d imageMiss=%d setMiss=%d cache=%d\n",
               n, skinned, misses, bundleMisses, imageMisses, setMisses,
               gThemerCacheCount);
    }

    return skinned;
}

static void themer_log_visible_theme_inventory(uint64_t *lvs,
                                               int nlv,
                                               uint64_t iconViewCls,
                                               NSDictionary<NSString *, NSData *> *dataByBundle)
{
    if (!lvs || nlv <= 0 || !r_is_objc_ptr(iconViewCls) ||
        ![dataByBundle isKindOfClass:NSDictionary.class]) {
        return;
    }

    int iconViews = 0;
    int themedVisible = 0;
    int unthemedVisible = 0;
    int readMisses = 0;
    NSMutableSet<NSString *> *visibleBundles = [NSMutableSet set];
    NSMutableSet<NSString *> *themedSamples = [NSMutableSet set];
    NSMutableSet<NSString *> *missingSamples = [NSMutableSet set];
    NSMutableArray<NSString *> *readMissSamples = [NSMutableArray array];

    for (int i = 0; i < nlv; i++) {
        enum { IV_CAP = 64 };
        uint64_t ivs[IV_CAP];
        int n = sb_collect_views(lvs[i], iconViewCls, ivs, IV_CAP);
        for (int j = 0; j < n; j++) {
            uint64_t v = ivs[j];
            if (!r_is_objc_ptr(v)) continue;
            iconViews++;

            char bundle[128] = {0};
            if (!themer_read_bundle_for_iconview(v, bundle, sizeof(bundle)) ||
                !bundle[0]) {
                readMisses++;
                if (readMissSamples.count < 16) {
                    char ivCls[96] = {0};
                    char superCls[96] = {0};
                    uint64_t superv = r_responds_main(v, "superview")
                        ? r_msg2_main(v, "superview", 0, 0, 0, 0) : 0;
                    themer_read_class_name(v, ivCls, sizeof(ivCls));
                    themer_read_class_name(superv, superCls, sizeof(superCls));
                    [readMissSamples addObject:
                        [NSString stringWithFormat:@"0x%llx:%s/super=%s",
                         (unsigned long long)v, ivCls, superCls]];
                }
                continue;
            }

            NSString *key = [NSString stringWithUTF8String:bundle];
            if (key.length == 0) {
                readMisses++;
                continue;
            }
            [visibleBundles addObject:key];

            NSData *pngBytes = dataByBundle[key];
            if ([pngBytes isKindOfClass:NSData.class] && pngBytes.length > 0) {
                themedVisible++;
                if (themedSamples.count < 32) [themedSamples addObject:key];
            } else {
                unthemedVisible++;
                if (missingSamples.count < 48) [missingSamples addObject:key];
            }
        }
    }

    printf("[THEMER] visible inventory lists=%d iconViews=%d unique=%lu themed=%d unthemed=%d readMisses=%d themedSamples=%s missingSamples=%s\n",
           nlv,
           iconViews,
           (unsigned long)visibleBundles.count,
           themedVisible,
           unthemedVisible,
           readMisses,
           themer_join_strings_for_log(themedSamples, 32).UTF8String,
           themer_join_strings_for_log(missingSamples, 48).UTF8String);

    printf("[THEMER] visible readMiss samples=%s\n",
           readMissSamples.count ? [readMissSamples componentsJoinedByString:@","].UTF8String : "");
}

static NSData *themer_theme_data_for_key(NSDictionary<NSString *, NSData *> *dataByBundle,
                                         NSString *key,
                                         NSString **matchedKeyOut)
{
    if (matchedKeyOut) *matchedKeyOut = nil;
    if (![dataByBundle isKindOfClass:NSDictionary.class] ||
        ![key isKindOfClass:NSString.class] ||
        key.length == 0) {
        return nil;
    }

    NSData *exact = dataByBundle[key];
    if ([exact isKindOfClass:NSData.class] && exact.length > 0) {
        if (matchedKeyOut) *matchedKeyOut = key;
        return exact;
    }

    NSString *lower = key.lowercaseString;
    if (![lower isEqualToString:key]) {
        NSData *lowerHit = dataByBundle[lower];
        if ([lowerHit isKindOfClass:NSData.class] && lowerHit.length > 0) {
            if (matchedKeyOut) *matchedKeyOut = lower;
            return lowerHit;
        }
    }

    for (NSString *candidate in dataByBundle) {
        if (![candidate isKindOfClass:NSString.class]) continue;
        if ([candidate caseInsensitiveCompare:key] != NSOrderedSame) continue;
        NSData *bytes = dataByBundle[candidate];
        if (![bytes isKindOfClass:NSData.class] || bytes.length == 0) continue;
        if (matchedKeyOut) *matchedKeyOut = candidate;
        return bytes;
    }

    return nil;
}

static void themer_add_alias_candidates(NSMutableArray<NSString *> *out,
                                        NSMutableSet<NSString *> *seen,
                                        NSString *name)
{
    if (!out || !seen || ![name isKindOfClass:NSString.class] ||
        name.length == 0) {
        return;
    }

    if (![seen containsObject:name]) {
        [out addObject:name];
        [seen addObject:name];
    }

    BOOL usedAlias = NO;
    NSArray<NSString *> *mapped = CNDMappedIOSBundleIDsForIconName(name, &usedAlias);
    (void)usedAlias;
    for (NSString *candidate in mapped) {
        if (![candidate isKindOfClass:NSString.class] || candidate.length == 0) continue;
        if ([seen containsObject:candidate]) continue;
        [out addObject:candidate];
        [seen addObject:candidate];
    }
}

static NSDictionary<NSString *, NSData *> *
themer_enrich_theme_data_with_visible_aliases(uint64_t *lvs,
                                              int nlv,
                                              uint64_t iconViewCls,
                                              NSDictionary<NSString *, NSData *> *dataByBundle)
{
    if (!lvs || nlv <= 0 || !r_is_objc_ptr(iconViewCls) ||
        ![dataByBundle isKindOfClass:NSDictionary.class]) {
        return dataByBundle;
    }

    NSMutableDictionary<NSString *, NSData *> *enriched = nil;
    NSMutableSet<NSString *> *visited = [NSMutableSet set];
    NSMutableArray<NSString *> *samples = [NSMutableArray array];
    NSUInteger added = 0;

    for (int i = 0; i < nlv; i++) {
        enum { IV_CAP = 64 };
        uint64_t ivs[IV_CAP];
        int n = sb_collect_views(lvs[i], iconViewCls, ivs, IV_CAP);
        for (int j = 0; j < n; j++) {
            uint64_t v = ivs[j];
            if (!r_is_objc_ptr(v)) continue;

            char actualBuf[128] = {0};
            if (!themer_read_bundle_for_iconview(v, actualBuf, sizeof(actualBuf)) ||
                !actualBuf[0]) {
                themer_clear_static_dynamic_child_overlay_for_iconview(v);
                continue;
            }
            if (strcmp(actualBuf, "com.apple.mobiletimer") != 0) {
                themer_clear_static_dynamic_child_overlay_for_iconview(v);
            }

            NSString *actual = [NSString stringWithUTF8String:actualBuf];
            if (actual.length == 0 || [visited containsObject:actual]) continue;
            [visited addObject:actual];

            NSString *matchedActual = nil;
            NSData *actualBytes = themer_theme_data_for_key(dataByBundle,
                                                            actual,
                                                            &matchedActual);
            if ([actualBytes isKindOfClass:NSData.class] && actualBytes.length > 0) {
                if (matchedActual.length > 0 &&
                    ![matchedActual isEqualToString:actual] &&
                    !dataByBundle[actual]) {
                    if (!enriched) enriched = [dataByBundle mutableCopy];
                    enriched[actual] = actualBytes;
                    added++;
                    if (samples.count < 24) {
                        [samples addObject:[NSString stringWithFormat:@"%@<=%@",
                                            actual, matchedActual]];
                    }
                }
                continue;
            }

            NSMutableArray<NSString *> *candidates = [NSMutableArray array];
            NSMutableSet<NSString *> *seenCandidates = [NSMutableSet set];
            themer_add_alias_candidates(candidates, seenCandidates, actual);

            uint64_t icon = themer_application_icon_for_iconview(v);
            char labelBuf[160] = {0};
            if (r_is_objc_ptr(icon)) {
                uint64_t label = themer_copy_icon_label(icon);
                if (r_is_objc_ptr(label)) {
                    r_read_nsstring(label, labelBuf, sizeof(labelBuf));
                    r_msg2(label, "release", 0, 0, 0, 0);
                }
            }
            if (labelBuf[0]) {
                NSString *label = [NSString stringWithUTF8String:labelBuf];
                themer_add_alias_candidates(candidates, seenCandidates, label);
            }

            for (NSString *candidate in candidates) {
                if ([candidate isEqualToString:actual]) continue;
                NSString *source = nil;
                NSData *bytes = themer_theme_data_for_key(dataByBundle,
                                                          candidate,
                                                          &source);
                if (![bytes isKindOfClass:NSData.class] || bytes.length == 0) continue;
                if (!enriched) enriched = [dataByBundle mutableCopy];
                enriched[actual] = bytes;
                added++;
                if (samples.count < 24) {
                    [samples addObject:[NSString stringWithFormat:@"%@<=%@ label=\"%s\"",
                                        actual, source ?: candidate, labelBuf]];
                }
                break;
            }
        }
    }

    if (added > 0) {
        printf("[THEMER] visible alias grafts added=%lu samples=%s\n",
               (unsigned long)added,
               samples.count ? [samples componentsJoinedByString:@","].UTF8String : "");
    }

    return enriched ?: dataByBundle;
}

static int themer_paint_static_dynamic_icons_for_lists(uint64_t *lvs,
                                                       int nlv,
                                                       uint64_t iconViewCls,
                                                       NSDictionary<NSString *, NSData *> *dataByBundle,
                                                       int *misses,
                                                       int *paintFails)
{
    if (!lvs || nlv <= 0 || !r_is_objc_ptr(iconViewCls) ||
        ![dataByBundle isKindOfClass:NSDictionary.class]) {
        return 0;
    }

    int applied = 0;
    int seen = 0;
    int inspected = 0;
    int noImage = 0;
    int directApplied = 0;

    for (int i = 0; i < nlv; i++) {
        enum { IV_CAP = 64 };
        uint64_t ivs[IV_CAP];
        int n = sb_collect_views(lvs[i], iconViewCls, ivs, IV_CAP);
        for (int j = 0; j < n; j++) {
            uint64_t v = ivs[j];
            if (!r_is_objc_ptr(v)) continue;

            char bundle[128] = {0};
            if (!themer_read_bundle_for_iconview(v, bundle, sizeof(bundle))) {
                continue;
            }
            if (!themer_is_static_dynamic_icon_bundle(bundle)) {
                continue;
            }
            seen++;

            uint64_t image = themer_lookup_cached(bundle);
            if (!r_is_objc_ptr(image)) {
                NSString *key = [NSString stringWithUTF8String:bundle];
                NSData *pngBytes = themer_theme_data_for_key(dataByBundle,
                                                             key,
                                                             nil);
                if (![pngBytes isKindOfClass:NSData.class] ||
                    pngBytes.length == 0) {
                    noImage++;
                    if (misses) (*misses)++;
                    continue;
                }

                NSData *uploadBytes = themer_rounded_png_data(pngBytes, bundle);
                image = themer_build_remote_uiimage_from_data(uploadBytes ?: pngBytes,
                                                              bundle);
                if (!r_is_objc_ptr(image)) {
                    noImage++;
                    if (misses) (*misses)++;
                    continue;
                }
                themer_cache_image(bundle, image);
            }

            (void)misses;
            themer_inspect_static_dynamic_icon_view(v, bundle, image);
            if (themer_apply_static_dynamic_icon_state(v, image, bundle)) {
                applied++;
            } else if (paintFails) {
                (*paintFails)++;
            }
            inspected++;
        }
    }

    directApplied = themer_apply_static_dynamic_known_image_views();
    applied += directApplied;

    if (seen > 0 || inspected > 0 || noImage > 0 || directApplied > 0) {
        printf("[THEMER] static dynamic pass seen=%d inspected=%d applied=%d directApplied=%d noImage=%d\n",
               seen, inspected, applied, directApplied, noImage);
    }

    return applied;
}

static int themer_run_initial_static_dynamic_specialized_pass(NSDictionary<NSString *, NSData *> *dataByBundle,
                                                              int *misses,
                                                              int *paintFails)
{
    if (![dataByBundle isKindOfClass:NSDictionary.class]) return 0;

    uint64_t listViewCls = r_class("SBIconListView");
    uint64_t iconViewCls = r_class("SBIconView");
    if (!r_is_objc_ptr(listViewCls) || !r_is_objc_ptr(iconViewCls)) {
        printf("[THEMER] static dynamic initial specialized skipped missing classes list=0x%llx iconView=0x%llx\n",
               (unsigned long long)listViewCls,
               (unsigned long long)iconViewCls);
        return 0;
    }

    int totalApplied = 0;
    enum { ATTEMPTS = 3, LV_CAP = 64 };
    for (int attempt = 0; attempt < ATTEMPTS; attempt++) {
        if (attempt > 0) {
            usleep(250000);
        }

        uint64_t lvs[LV_CAP];
        int nlv = sb_collect_views_in_windows(listViewCls, lvs, LV_CAP);
        int applied = 0;
        if (nlv > 0) {
            applied = themer_paint_static_dynamic_icons_for_lists(lvs, nlv,
                                                                  iconViewCls,
                                                                  dataByBundle,
                                                                  misses,
                                                                  paintFails);
        } else {
            applied = themer_apply_static_dynamic_known_image_views();
        }
        totalApplied += applied;
        printf("[THEMER] static dynamic initial specialized attempt=%d lists=%d applied=%d total=%d\n",
               attempt + 1, nlv, applied, totalApplied);
    }

    return totalApplied;
}

bool themer_apply_data_in_session(NSDictionary<NSString *, NSData *> *imageDataByBundle)
{
    if (imageDataByBundle.count == 0) {
        printf("[THEMER] apply data: empty dictionary\n");
        return false;
    }
    if (!remote_call_current_success()) return false;
    imageDataByBundle = themer_normalized_theme_data(imageDataByBundle);
    uint64_t startUS = themer_now_us();
    uint32_t prevSettle = r_settle_us(kThemerApplySettleUS);
    gThemerPaintFailLogBudget = 96;
    gThemerSeedFailureLogBudget = 64;
    gThemerCacheClearLogBudget = 16;
    gThemerSpotlightSeedLogBudget = 16;
    gThemerImageCacheMethodDumpLogged = false;
    gThemerIconMethodDumpLogged = false;
    gThemerStaticDynamicTreeLogBudget = 8;
    gThemerCalendarDeepDiagBudget = 8;
    gThemerStaticDynamicBundleScanEnabled = true;
    printf("[THEMER] apply data entries=%lu cacheCarried=%d\n",
           (unsigned long)imageDataByBundle.count, gThemerCacheCount);
    if (!gThemerVisiblePolicyLogged) {
        gThemerVisiblePolicyLogged = true;
        printf("[THEMER] visible push policy iosMajor=%d legacyVisible=%d\n",
               themer_host_ios_major(),
               themer_needs_visible_push(NULL));
    }

    // Drop the per-msgSend settle for the duration of the apply. The stable
    // RemoteCall trampoline already serializes the calls; sleeping before every
    // ObjC send just makes the initial icon flip visibly lag.
    themer_reset_icon_bundle_cache();

    uint64_t listViewCls = r_class("SBIconListView");
    if (!remote_call_current_success()) {
        r_settle_us(prevSettle);
        return false;
    }
    uint64_t iconViewCls = r_class("SBIconView");
    if (!remote_call_current_success()) {
        r_settle_us(prevSettle);
        return false;
    }
    if (!r_is_objc_ptr(listViewCls) || !r_is_objc_ptr(iconViewCls)) {
        printf("[THEMER] missing class SBIconListView=0x%llx SBIconView=0x%llx\n",
               (unsigned long long)listViewCls,
               (unsigned long long)iconViewCls);
        r_settle_us(prevSettle);
        return false;
    }

    enum { LV_CAP = 64 };
    uint64_t lvs[LV_CAP];
    int nlv = sb_collect_views_in_windows(listViewCls, lvs, LV_CAP);
    if (!remote_call_current_success()) {
        r_settle_us(prevSettle);
        return false;
    }
    if (nlv == 0) {
        printf("[THEMER] no SBIconListView visible (home screen not active?)\n");
        r_settle_us(prevSettle);
        return false;
    }
    // Restore the supplied 1.5 SpringBoardHome cache refresh before model
    // grafting so reused icon views cannot retain stale unthemed entries.
    (void)themer_clear_sbh_icon_image_caches_for_lists(lvs, nlv, iconViewCls);
    if (!remote_call_current_success()) {
        r_settle_us(prevSettle);
        return false;
    }

    int misses = 0;
    int modelGrafted = themer_graft_icon_models_for_theme_options(imageDataByBundle,
                                                                  &misses,
                                                                  true);
    if (!remote_call_current_success()) {
        r_settle_us(prevSettle);
        return false;
    }
    int visiblePaint = 0;
    int visiblePaintFails = 0;
    int visibleRungHits[4] = {0};
    for (int i = 0; i < nlv && remote_call_current_success(); i++) {
        visiblePaint += themer_iter_iconviews(lvs[i], imageDataByBundle,
                                              iconViewCls, visibleRungHits,
                                              &misses, &visiblePaintFails);
    }
    if (!remote_call_current_success()) {
        printf("[THEMER] visible first-paint pass interrupted after persistent model/cache install\n");
    }
    int staticPaintFails = 0;
    gThemerStaticDynamicTreeLogBudget = 8;
    gThemerClockIIVMethodsLogged = false;
    gThemerCalendarIIVMethodsLogged = false;
    gThemerCalendarIconMethodsLogged = false;
    gThemerClockIIVIvarsLogged = false;
    gThemerCalendarIIVIvarsLogged = false;
    gThemerCalendarIconIvarsLogged = false;
    int staticDynamicPainted = 0;
    if (kThemerStaticDynamicInitialListPassEnabled) {
        staticDynamicPainted =
            themer_paint_static_dynamic_icons_for_lists(lvs, nlv, iconViewCls,
                                                        imageDataByBundle,
                                                        &misses,
                                                        &staticPaintFails);
    } else {
        printf("[THEMER] static dynamic initial list pass skipped; direct clock repair remains enabled\n");
    }
    bool healthy = remote_call_current_success();
    if (healthy) usleep(250000);
    bool clockRepairApplied = healthy
        ? themer_repair_static_dynamic_visible_icons_in_session() : false;
    int staticDynamicSpecialized = clockRepairApplied ? 1 : 0;
    staticDynamicPainted += staticDynamicSpecialized;

    r_settle_us(prevSettle);

    uint64_t elapsedUS = themer_now_us() - startUS;
    printf("[THEMER] done lists=%d model=%d staticDynamic=%d clockRepair=%d staticPaintFail=%d visiblePaint=%d visiblePaintFail=%d rungs={1:%d,2:%d,3:%d,4:%d} misses=%d notif=disabled retries=disabled cache=%d elapsed=%llums settle=%uus\n",
           nlv, modelGrafted, staticDynamicPainted, staticDynamicSpecialized,
           staticPaintFails, visiblePaint, visiblePaintFails,
           visibleRungHits[0], visibleRungHits[1], visibleRungHits[2],
           visibleRungHits[3], misses,
           gThemerCacheCount,
           (unsigned long long)(elapsedUS / 1000ULL),
           kThemerApplySettleUS);
    // Direct view painting is presentation-only. Report success from the
    // persistent producer/model path so a visible-only result cannot mask a
    // cache or graft failure.
    return modelGrafted > 0 || staticDynamicPainted > 0;
}

bool themer_apply_data_for_bundle_ids_in_session(NSDictionary<NSString *, NSData *> *imageDataByBundle,
                                                 NSSet<NSString *> *bundleIDs,
                                                 bool forceRefresh)
{
    if (imageDataByBundle.count == 0 || bundleIDs.count == 0) {
        printf("[THEMER] targeted apply skipped entries=%lu targets=%lu\n",
               (unsigned long)imageDataByBundle.count,
               (unsigned long)bundleIDs.count);
        return false;
    }
    if (!remote_call_current_success()) return false;

    uint64_t startUS = themer_now_us();
    uint32_t prevSettle = r_settle_us(kThemerApplySettleUS);
    gThemerSeedFailureLogBudget = 24;
    gThemerCacheClearLogBudget = 12;
    themer_reset_icon_bundle_cache();

    NSDictionary<NSString *, NSData *> *normalized =
        themer_normalized_theme_data(imageDataByBundle);
    NSDictionary<NSString *, NSData *> *filtered =
        themer_filter_theme_data_for_bundle_ids(normalized, bundleIDs);

    if (filtered.count == 0) {
        printf("[THEMER] targeted apply no theme images targets=%s entries=%lu\n",
               themer_join_strings_for_log(bundleIDs, 16).UTF8String,
               (unsigned long)normalized.count);
        r_settle_us(prevSettle);
        return false;
    }

    int misses = 0;
    int grafted = themer_graft_icon_models_for_theme_options(filtered,
                                                             &misses,
                                                             forceRefresh);
    r_settle_us(prevSettle);

    uint64_t elapsedUS = themer_now_us() - startUS;
    printf("[THEMER] targeted apply targets=%lu entries=%lu grafted=%d misses=%d force=%d cache=%d elapsed=%llums targetList=%s\n",
           (unsigned long)bundleIDs.count,
           (unsigned long)filtered.count,
           grafted,
           misses,
           forceRefresh,
           gThemerCacheCount,
           (unsigned long long)(elapsedUS / 1000ULL),
           themer_join_strings_for_log(bundleIDs, 16).UTF8String);
    return grafted > 0;
}

bool themer_apply_in_session(const char *themePath)
{
    if (!themePath || !themePath[0]) {
        printf("[THEMER] apply: nil path\n");
        return false;
    }

    NSString *themeDir = @(themePath);
    NSFileManager *fm = [NSFileManager defaultManager];
    BOOL isDir = NO;
    if (![fm fileExistsAtPath:themeDir isDirectory:&isDir] || !isDir) {
        printf("[THEMER] apply: missing dir %s\n", themePath);
        return false;
    }

    NSArray<NSString *> *files = [fm contentsOfDirectoryAtPath:themeDir error:NULL];
    NSMutableDictionary<NSString *, NSString *> *pathByBundle = [NSMutableDictionary dictionary];
    NSMutableSet<NSString *> *explicitFileBundles = [NSMutableSet set];
    NSMutableSet<NSString *> *appleSystemBundles = [NSMutableSet set];
    NSMutableSet<NSString *> *aliasTargetBundles = [NSMutableSet set];
    NSUInteger availableCount = 0;
    NSUInteger aliasKeyCount = 0;
    for (NSString *f in files) {
        if (![f.pathExtension.lowercaseString isEqualToString:@"png"]) continue;
        availableCount++;
        NSString *bundle = f.stringByDeletingPathExtension;
        NSString *path = [themeDir stringByAppendingPathComponent:f];
        pathByBundle[bundle] = path;
        if (bundle.length > 0) [explicitFileBundles addObject:bundle];
        if ([bundle.lowercaseString hasPrefix:@"com.apple."]) {
            [appleSystemBundles addObject:bundle];
        }
        NSString *lower = bundle.lowercaseString;
        if (lower.length > 0 && !pathByBundle[lower]) {
            pathByBundle[lower] = path;
        }
        if ([lower isEqualToString:@"com.autonavi.minimap"] && !pathByBundle[@"com.autonavi.amap"]) {
            pathByBundle[@"com.autonavi.amap"] = path;
            [aliasTargetBundles addObject:@"com.autonavi.amap"];
        }
        BOOL usedAlias = NO;
        NSArray<NSString *> *mappedTargets = CNDMappedIOSBundleIDsForIconName(f, &usedAlias);
        for (NSString *mapped in mappedTargets) {
            if (mapped.length == 0) continue;
            if ([mapped.lowercaseString hasPrefix:@"com.apple."]) {
                [appleSystemBundles addObject:mapped];
            }
            if (!pathByBundle[mapped]) {
                pathByBundle[mapped] = path;
                if (usedAlias) aliasKeyCount++;
            }
            if (usedAlias) {
                [aliasTargetBundles addObject:mapped];
            }
            NSString *mappedLower = mapped.lowercaseString;
            if (mappedLower.length > 0 && !pathByBundle[mappedLower]) {
                pathByBundle[mappedLower] = path;
            }
        }
    }
    printf("[THEMER] apply path=%s available=%lu aliasKeys=%lu\n",
           themePath, (unsigned long)availableCount, (unsigned long)aliasKeyCount);
    if (availableCount == 0) return false;
    if (!remote_call_current_success()) return false;

    NSSet<NSString *> *visible = themer_collect_visible_bundles();
    if (!remote_call_current_success()) return false;
    printf("[THEMER] visible bundles count=%lu list=%s\n",
           (unsigned long)visible.count,
           themer_join_strings_for_log(visible, 160).UTF8String);
    printf("[THEMER] explicit file bundles count=%lu list=%s\n",
           (unsigned long)explicitFileBundles.count,
           themer_join_strings_for_log(explicitFileBundles, 200).UTF8String);
    printf("[THEMER] apple-system bundles count=%lu list=%s\n",
           (unsigned long)appleSystemBundles.count,
           themer_join_strings_for_log(appleSystemBundles, 200).UTF8String);
    printf("[THEMER] alias-target bundles count=%lu list=%s\n",
           (unsigned long)aliasTargetBundles.count,
           themer_join_strings_for_log(aliasTargetBundles, 240).UTF8String);
    NSMutableSet<NSString *> *targetBundles = [visible mutableCopy];
    NSUInteger explicitAdded = 0;
    NSUInteger priorityAdded = 0;
    NSUInteger appleAdded = 0;
    NSUInteger aliasAdded = 0;
    for (NSString *bid in explicitFileBundles) {
        if (![bid isKindOfClass:NSString.class] || bid.length == 0) continue;
        if ([targetBundles containsObject:bid]) continue;
        if (themer_theme_path_for_bundle(pathByBundle, bid)) {
            [targetBundles addObject:bid];
            explicitAdded++;
        }
    }
    for (NSString *bid in appleSystemBundles) {
        if (![bid isKindOfClass:NSString.class] || bid.length == 0) continue;
        if ([targetBundles containsObject:bid]) continue;
        if (themer_theme_path_for_bundle(pathByBundle, bid)) {
            [targetBundles addObject:bid];
            appleAdded++;
        }
    }
    for (NSString *bid in aliasTargetBundles) {
        if (![bid isKindOfClass:NSString.class] || bid.length == 0) continue;
        if ([targetBundles containsObject:bid]) continue;
        if (themer_theme_path_for_bundle(pathByBundle, bid)) {
            [targetBundles addObject:bid];
            aliasAdded++;
        }
    }
    for (NSString *bid in themer_priority_theme_bundles()) {
        if (![bid isKindOfClass:NSString.class] || bid.length == 0) continue;
        if ([targetBundles containsObject:bid]) continue;
        if (themer_theme_path_for_bundle(pathByBundle, bid)) {
            [targetBundles addObject:bid];
            priorityAdded++;
        }
    }
    printf("[THEMER] target bundles count=%lu list=%s\n",
           (unsigned long)targetBundles.count,
           themer_join_strings_for_log(targetBundles, 240).UTF8String);
    NSMutableDictionary<NSString *, NSData *> *dict = [NSMutableDictionary dictionary];
    NSMutableArray<NSString *> *matchedBundles = [NSMutableArray array];
    NSUInteger caseFallbacks = 0;
    for (NSString *bid in targetBundles) {
        NSString *path = themer_theme_path_for_bundle(pathByBundle, bid);
        if (path && !pathByBundle[bid]) {
            caseFallbacks++;
        }
        if (!path) continue;
        NSData *bytes = [NSData dataWithContentsOfFile:path];
        if (bytes.length) {
            dict[bid] = bytes;
            [matchedBundles addObject:bid];
        }
    }
    printf("[THEMER] matched bundles count=%lu list=%s\n",
           (unsigned long)matchedBundles.count,
           themer_join_strings_for_log(matchedBundles, 240).UTF8String);
    printf("[THEMER] apply loaded=%lu matched of %lu target (%lu visible + %lu explicit + %lu apple + %lu alias + %lu priority), %lu available caseFallbacks=%lu\n",
           (unsigned long)dict.count,
           (unsigned long)targetBundles.count,
           (unsigned long)visible.count,
           (unsigned long)explicitAdded,
           (unsigned long)appleAdded,
           (unsigned long)aliasAdded,
           (unsigned long)priorityAdded,
           (unsigned long)availableCount,
           (unsigned long)caseFallbacks);
    return themer_apply_data_in_session(dict);
}

bool themer_stop_in_session(void)
{
    themer_spotlight_monitor_reset();
    if (!remote_call_current_success()) {
        themer_forget_remote_state();
        return false;
    }
    int released = 0;
    for (int i = 0; i < gThemerCacheCount; i++) {
        if (!remote_call_current_success()) {
            themer_forget_remote_state();
            return false;
        }
        if (r_is_objc_ptr(gThemerCache[i].image)) {
            r_msg2(gThemerCache[i].image, "release", 0, 0, 0, 0);
            if (!remote_call_current_success()) {
                themer_forget_remote_state();
                return false;
            }
            released++;
        }
        if (r_is_objc_ptr(gThemerCache[i].dataSource)) {
            r_msg2(gThemerCache[i].dataSource, "release", 0, 0, 0, 0);
            if (!remote_call_current_success()) {
                themer_forget_remote_state();
                return false;
            }
            released++;
        }
        if (gThemerCache[i].iconServicesGrafted &&
            r_is_objc_ptr(gThemerCache[i].iconServicesIcon)) {
            uint64_t sel = r_sel("imageForDescriptor:");
            if (sel) {
                r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                             gThemerCache[i].iconServicesIcon, sel,
                             0, 1, 0, 0, 0, 0);
                if (!remote_call_current_success()) {
                    themer_forget_remote_state();
                    return false;
                }
            }
            if (r_is_objc_ptr(gThemerCache[i].iconServicesOriginalClass)) {
                r_dlsym_call(R_TIMEOUT, "object_setClass",
                             gThemerCache[i].iconServicesIcon,
                             gThemerCache[i].iconServicesOriginalClass,
                             0, 0, 0, 0, 0, 0);
                if (!remote_call_current_success()) {
                    themer_forget_remote_state();
                    return false;
                }
            }
            r_msg2(gThemerCache[i].iconServicesIcon, "release", 0, 0, 0, 0);
            if (!remote_call_current_success()) {
                themer_forget_remote_state();
                return false;
            }
            released++;
        }
        gThemerCache[i].image = 0;
        gThemerCache[i].dataSource = 0;
        gThemerCache[i].iconServicesIcon = 0;
        gThemerCache[i].iconServicesOriginalClass = 0;
        gThemerCache[i].iconServicesSeeded = false;
        gThemerCache[i].iconServicesGrafted = false;
        gThemerCache[i].modelGrafted = false;
        gThemerCache[i].bundle[0] = '\0';
    }
    gThemerCacheCount = 0;
    themer_reset_icon_bundle_cache();
    gThemerRung = -1;
    gThemerHasUpdateAfter = false;
    gThemerHasUpdateImageView = false;
    gThemerLogBudget = 48;
    gThemerSeedFailureLogBudget = 64;
    gThemerCacheClearLogBudget = 16;
    gThemerSpotlightSeedLogBudget = 16;
    gThemerImageCacheMethodDumpLogged = false;
    gThemerIconMethodDumpLogged = false;
    gThemerModelProbeLogged = false;
    gThemerIconServicesProbeLogged = false;
    gThemerVisiblePolicyLogged = false;
    gThemerStaticDynamicTreeLogBudget = 8;
    gThemerClockIIVMethodsLogged = false;
    gThemerCalendarIIVMethodsLogged = false;
    gThemerCalendarIconMethodsLogged = false;
    gThemerClockIIVIvarsLogged = false;
    gThemerCalendarIIVIvarsLogged = false;
    gThemerCalendarIconIvarsLogged = false;
    gThemerCalendarDeepDiagBudget = 8;
    gThemerStaticDynamicBundleScanEnabled = true;
    printf("[THEMER] stop released=%d\n", released);
    return remote_call_current_success();
}

void themer_forget_remote_state(void)
{
    themer_spotlight_monitor_reset();
    for (int i = 0; i < kThemerMaxCache; i++) {
        gThemerCache[i].image = 0;
        gThemerCache[i].dataSource = 0;
        gThemerCache[i].iconServicesIcon = 0;
        gThemerCache[i].iconServicesOriginalClass = 0;
        gThemerCache[i].iconServicesSeeded = false;
        gThemerCache[i].iconServicesGrafted = false;
        gThemerCache[i].modelGrafted = false;
        gThemerCache[i].bundle[0] = '\0';
    }
    gThemerCacheCount = 0;
    themer_reset_icon_bundle_cache();
    gThemerRung = -1;
    gThemerHasUpdateAfter = false;
    gThemerHasUpdateImageView = false;
    gThemerLogBudget = 48;
    gThemerSeedFailureLogBudget = 64;
    gThemerCacheClearLogBudget = 16;
    gThemerSpotlightSeedLogBudget = 16;
    gThemerImageCacheMethodDumpLogged = false;
    gThemerIconMethodDumpLogged = false;
    gThemerModelProbeLogged = false;
    gThemerIconServicesProbeLogged = false;
    gThemerVisiblePolicyLogged = false;
    gThemerStaticDynamicTreeLogBudget = 8;
    gThemerClockIIVMethodsLogged = false;
    gThemerCalendarIIVMethodsLogged = false;
    gThemerCalendarIconMethodsLogged = false;
    gThemerClockIIVIvarsLogged = false;
    gThemerCalendarIIVIvarsLogged = false;
    gThemerCalendarIconIvarsLogged = false;
    gThemerCalendarDeepDiagBudget = 8;
    gThemerStaticDynamicBundleScanEnabled = true;
}

bool themer_has_remote_state(void)
{
    return gThemerCacheCount > 0;
}

bool themer_detach_remote_state_preserving_grafts(void)
{
    if (!remote_call_current_success()) {
        // The session is already poisoned. Pointers cannot be trusted for
        // release calls; forget them locally without touching SpringBoard.
        themer_forget_remote_state();
        return false;
    }

    int released = 0;
    for (int i = 0; i < gThemerCacheCount; i++) {
        uint64_t *owned[] = {
            &gThemerCache[i].image,
            &gThemerCache[i].dataSource,
            &gThemerCache[i].iconServicesIcon,
        };
        for (size_t j = 0; j < sizeof(owned) / sizeof(owned[0]); j++) {
            if (!r_is_objc_ptr(*owned[j])) continue;
            r_msg2(*owned[j], "release", 0, 0, 0, 0);
            if (!remote_call_current_success()) {
                // Do not issue any more remote calls in an untrustworthy
                // synthetic-thread state.
                themer_forget_remote_state();
                return false;
            }
            *owned[j] = 0;
            released++;
        }
        memset(&gThemerCache[i], 0, sizeof(gThemerCache[i]));
    }
    gThemerCacheCount = 0;
    themer_reset_icon_bundle_cache();
    printf("[THEMER] detach preserving grafts released=%d\n", released);
    return true;
}

// =====================================================================
// Spotlight SearchUIIconImageCache one-app proof (experimental).
//
// Seeds exactly one selected themed app into the process-lifetime
// per-variant SearchUIIconImageCache bound to a live SearchUI row, retains
// everything a later same-PID session needs in the NSProcessInfo associated
// object `cndSpotlightCacheProofStateV1`, then verifies and cleanly
// overwrites only that cache identity with the captured stock image.
// =====================================================================

#define THEMER_SPOTLIGHT_PROOF_STATE_KEY "cndSpotlightCacheProofStateV1"
#define THEMER_SPOTLIGHT_PROOF_VIEW_CAP 64
#define THEMER_SPOTLIGHT_PROOF_IMAGE_CAP 4
#define THEMER_SPOTLIGHT_PROOF_TARGET_CAP 32
#define THEMER_SPOTLIGHT_PROOF_ROW_CAP 32

static void themer_spotlight_proof_release_images(
    ThemerSpotlightRemoteImage *images,
    int imageCount,
    uint64_t adjusted)
{
    if (r_is_objc_ptr(adjusted) && remote_call_current_success()) {
        r_msg2(adjusted, "release", 0, 0, 0, 0);
    }
    for (int i = 0; i < imageCount && remote_call_current_success(); i++) {
        if (r_is_objc_ptr(images[i].image)) {
            r_msg2(images[i].image, "release", 0, 0, 0, 0);
        }
    }
}

static bool themer_spotlight_proof_overwrite_cache(
    uint64_t cache,
    uint64_t image,
    uint64_t icon,
    uint64_t appearance,
    uint64_t generation,
    int *callsOut)
{
    if (callsOut) *callsOut = 0;
    if (!themer_spotlight_carrier_cache_supports_seed(cache) ||
        !r_is_objc_ptr(image) || !r_is_objc_ptr(icon) ||
        !r_is_objc_ptr(appearance)) {
        return false;
    }
    ThemerSpotlightCacheTarget targets[
        THEMER_SPOTLIGHT_PROOF_TARGET_CAP] = {{0}};
    int targetCount = themer_spotlight_collect_cache_targets(
        cache, targets, THEMER_SPOTLIGHT_PROOF_TARGET_CAP);
    int calls = themer_spotlight_seed_cache_targets(
        targets, targetCount, image, icon, appearance, generation, false);
    ThemerSpotlightCacheVerification verification =
        themer_spotlight_verify_cache_targets(
            targets, targetCount, image, icon, appearance, false);
    if (callsOut) *callsOut = calls;
    return calls > 0 &&
           (verification.rootNativeMatches > 0 ||
            verification.backingNativeMatches > 0);
}

static uint64_t themer_spotlight_proof_state(void)
{
    return themer_spotlight_associated_process_object(
        THEMER_SPOTLIGHT_PROOF_STATE_KEY);
}

static bool themer_spotlight_proof_commit_state(uint64_t state)
{
    return themer_spotlight_commit_process_object(
        THEMER_SPOTLIGHT_PROOF_STATE_KEY, state);
}

static void themer_spotlight_proof_clear_state(void)
{
    uint64_t processInfo = themer_spotlight_process_info();
    uint64_t key = r_sel(THEMER_SPOTLIGHT_PROOF_STATE_KEY);
    if (r_is_objc_ptr(processInfo) && key) {
        // objc_setAssociatedObject with a nil object removes the
        // association and releases the previously retained value.
        r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                     processInfo, key, 0, 1, 0, 0, 0, 0);
    }
}

static uint64_t themer_spotlight_proof_number(unsigned long long value)
{
    uint64_t cls = r_class("NSNumber");
    if (!r_is_objc_ptr(cls) ||
        !r_responds_main(cls, "numberWithUnsignedLongLong:")) {
        return 0;
    }
    return r_msg2_main(cls, "numberWithUnsignedLongLong:",
                       value, 0, 0, 0);
}

static bool themer_spotlight_proof_state_set_string(uint64_t state,
                                                    const char *keyName,
                                                    const char *value)
{
    if (!r_is_objc_ptr(state) || !keyName || !keyName[0]) return false;
    uint64_t string = value && value[0] ? r_nsstr_retained(value) : 0;
    if (!r_is_objc_ptr(string)) return false;
    bool ok = themer_spotlight_dictionary_set_object(state, keyName, string);
    r_msg2(string, "release", 0, 0, 0, 0);
    return ok;
}

static uint64_t themer_spotlight_proof_state_object(uint64_t state,
                                                    const char *keyName)
{
    return themer_spotlight_dictionary_object(state, keyName);
}

static bool themer_spotlight_proof_state_u64(uint64_t state,
                                             const char *keyName,
                                             uint64_t *valueOut)
{
    if (valueOut) *valueOut = 0;
    uint64_t number = themer_spotlight_dictionary_object(state, keyName);
    if (!r_is_objc_ptr(number) ||
        !r_responds_main(number, "unsignedLongLongValue")) {
        return false;
    }
    uint64_t value = r_msg2_main(number, "unsignedLongLongValue",
                                 0, 0, 0, 0);
    if (valueOut) *valueOut = value;
    return true;
}

static bool themer_spotlight_proof_state_string(uint64_t state,
                                                const char *keyName,
                                                char *out,
                                                size_t outLen)
{
    if (out && outLen > 0) out[0] = '\0';
    uint64_t string = themer_spotlight_dictionary_object(state, keyName);
    if (!r_is_objc_ptr(string)) return false;
    return r_read_nsstring(string, out, outLen);
}

typedef struct {
    char bundle[192];
    uint64_t icon;
    uint64_t provider;
    const char *selector;
} ThemerSpotlightProofSelection;

static uint64_t themer_spotlight_proof_cache_read(
    uint64_t cache,
    uint64_t icon,
    uint64_t appearance,
    bool renderOnMiss)
{
    if (!r_is_objc_ptr(cache) || !r_is_objc_ptr(icon) ||
        !r_is_objc_ptr(appearance)) {
        return 0;
    }
    static const char *cachedSelector =
        "cachedImageForIcon:imageAppearance:options:";
    if (r_responds_main(cache, cachedSelector)) {
        uint64_t image = r_msg2_main(cache, cachedSelector,
                                     icon, appearance, 0, 0);
        if (r_is_objc_ptr(image) || !renderOnMiss) return image;
    }
    static const char *renderSelector =
        "imageForIcon:imageAppearance:options:";
    if (renderOnMiss && r_responds_main(cache, renderSelector)) {
        return r_msg2_main(cache, renderSelector,
                           icon, appearance, 0, 0);
    }
    return 0;
}

static bool themer_spotlight_proof_cache_seed(
    uint64_t cache,
    uint64_t image,
    uint64_t icon,
    uint64_t appearance)
{
    static const char *selector =
        "cacheImage:forIcon:imageAppearance:";
    if (!r_is_objc_ptr(cache) || !r_is_objc_ptr(image) ||
        !r_is_objc_ptr(icon) || !r_is_objc_ptr(appearance) ||
        !r_responds_main(cache, selector)) {
        return false;
    }
    r_msg2_main(cache, selector, image, icon, appearance, 0);
    uint64_t readback = themer_spotlight_proof_cache_read(
        cache, icon, appearance, false);
    return themer_spotlight_images_match(image, readback) &&
           remote_call_current_success();
}

static bool themer_spotlight_proof_device_variant(uint64_t *variantOut,
                                                   uint64_t *idiomOut)
{
    if (variantOut) *variantOut = 0;
    if (idiomOut) *idiomOut = 0;
    uint64_t deviceClass = themer_lookup_class("UIDevice");
    uint64_t device = r_is_objc_ptr(deviceClass) &&
                      r_responds_main(deviceClass, "currentDevice")
        ? r_msg2_main(deviceClass, "currentDevice", 0, 0, 0, 0)
        : 0;
    if (!r_is_objc_ptr(device) ||
        !r_responds_main(device, "userInterfaceIdiom")) {
        return false;
    }
    uint64_t idiom = r_msg2_main(device, "userInterfaceIdiom", 0, 0, 0, 0);
    // SearchUIHomeScreenAppIconView -init uses variant 4 on iPad and 5 on
    // every other supported idiom on iOS 26.
    uint64_t variant = idiom == 1 ? 4 : 5;
    if (variantOut) *variantOut = variant;
    if (idiomOut) *idiomOut = idiom;
    return remote_call_current_success();
}

static int themer_spotlight_proof_select_icons(
    NSDictionary<NSString *, NSData *> *normalized,
    uint64_t owner,
    uint64_t dataSource,
    volatile int *stopRequested,
    ThemerSpotlightProofSelection *selectedOut,
    ThemerSpotlightProofSelection *controlOut)
{
    if (selectedOut) memset(selectedOut, 0, sizeof(*selectedOut));
    if (controlOut) memset(controlOut, 0, sizeof(*controlOut));
    if (normalized.count == 0 || !r_is_objc_ptr(owner) ||
        !r_is_objc_ptr(dataSource)) {
        return 0;
    }

    NSArray<NSString *> *sortedKeys = [normalized.allKeys
        sortedArrayUsingSelector:@selector(compare:)];
    int found = 0;
    for (int pass = 0; pass < 2 && found < 2; pass++) {
        for (NSString *key in sortedKeys) {
            if (stopRequested && *stopRequested) return found;
            const char *bundle = key.UTF8String;
            bool isCyanide =
                bundle && strcmp(bundle, "com.zeroxjf.ios-cyanide1") == 0;
            if ((pass == 0 && isCyanide) || (pass == 1 && !isCyanide)) {
                continue;
            }
            if (!bundle || !bundle[0] ||
                (found > 0 && selectedOut &&
                 strcmp(selectedOut->bundle, bundle) == 0)) {
                continue;
            }
            NSData *bytes = themer_theme_data_for_key(normalized, key, NULL);
            if (![bytes isKindOfClass:NSData.class] || bytes.length == 0) {
                continue;
            }
            uint64_t provider = 0;
            const char *selector = NULL;
            uint64_t icon = themer_spotlight_materialize_provider_icon(
                owner, dataSource, bundle, &provider, &selector);
            if (!r_is_objc_ptr(icon)) continue;

            ThemerSpotlightProofSelection *destination =
                found == 0 ? selectedOut : controlOut;
            if (!destination) return found;
            snprintf(destination->bundle, sizeof(destination->bundle),
                     "%s", bundle);
            destination->icon = icon;
            destination->provider = provider;
            destination->selector = selector;
            found++;
            if (found >= 2) break;
        }
    }
    return found;
}

ThemerSpotlightProofBeginResult themer_spotlight_proof_begin_in_session(
    NSDictionary<NSString *, NSData *> *imageDataByBundle,
    volatile int *stopRequested)
{
    uint64_t startUS = themer_now_us();
    NSDictionary<NSString *, NSData *> *normalized =
        themer_normalized_theme_data(imageDataByBundle);
    if (normalized.count == 0) {
        printf("[SPOTLIGHT_PROOF] begin skipped reason=empty-theme\n");
        return ThemerSpotlightProofBeginResultNoVisibleThemedIcon;
    }
    if (r_is_objc_ptr(themer_spotlight_proof_state())) {
        printf("[SPOTLIGHT_PROOF] begin stopped reason=proof-already-armed\n");
        return ThemerSpotlightProofBeginResultStateFailed;
    }
    if (r_is_objc_ptr(themer_spotlight_theme_state())) {
        printf("[SPOTLIGHT_PROOF] begin stopped "
               "reason=production-theme-state-present action=respring-first\n");
        return ThemerSpotlightProofBeginResultStateFailed;
    }

    uint32_t previousSettleUS = r_settle_us(1000);
    uint64_t owner = 0;
    uint64_t dataSource = 0;
    uint64_t iconModel = 0;
    uint64_t repository = 0;
    bool graphKnown = themer_spotlight_current_graph(
        &owner, &dataSource, &iconModel, &repository);
    if (!graphKnown) {
        printf("[SPOTLIGHT_PROOF] begin stopped reason=searchui-graph-unavailable\n");
        r_settle_us(previousSettleUS);
        return ThemerSpotlightProofBeginResultNoVisibleThemedIcon;
    }

    ThemerSpotlightProofSelection selected = {0};
    ThemerSpotlightProofSelection control = {0};
    int selectedCount = themer_spotlight_proof_select_icons(
        normalized, owner, dataSource, stopRequested, &selected, &control);
    if (selectedCount < 1 || !r_is_objc_ptr(selected.icon) ||
        (stopRequested && *stopRequested)) {
        printf("[SPOTLIGHT_PROOF] begin stopped "
               "reason=no-eligible-installed-themed-icon candidates=%d\n",
               selectedCount);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightProofBeginResultNoVisibleThemedIcon;
    }

    uint64_t variant = 0;
    uint64_t idiom = 0;
    uint64_t viewClass =
        themer_lookup_class("SearchUIHomeScreenAppIconView");
    bool variantKnown = themer_spotlight_proof_device_variant(
        &variant, &idiom);
    uint64_t cache = variantKnown && r_is_objc_ptr(viewClass) &&
                     r_responds_main(viewClass, "cacheForVariant:")
        ? r_msg2_main(viewClass, "cacheForVariant:", variant, 0, 0, 0)
        : 0;
    ThemerSpotlightRemoteIconImageInfo cacheInfo = {0};
    bool cacheInfoKnown = themer_spotlight_read_cache_icon_image_info(
        cache, &cacheInfo);

    uint64_t appearanceClass =
        themer_lookup_class("SBHIconImageAppearance");
    uint64_t lightAppearance =
        r_is_objc_ptr(appearanceClass) &&
        r_responds_main(appearanceClass, "lightAppearance")
            ? r_msg2_main(appearanceClass, "lightAppearance", 0, 0, 0, 0)
            : 0;
    uint64_t darkAppearance =
        r_is_objc_ptr(appearanceClass) &&
        r_responds_main(appearanceClass, "darkAppearance")
            ? r_msg2_main(appearanceClass, "darkAppearance", 0, 0, 0, 0)
            : 0;
    bool generationKnown = r_is_objc_ptr(cache) &&
        r_responds_main(cache, "currentImageGenerationForIcon:");
    uint64_t imageGeneration = generationKnown
        ? r_msg2_main(cache, "currentImageGenerationForIcon:",
                      selected.icon, 0, 0, 0)
        : 0;
    if (!variantKnown || !themer_spotlight_carrier_cache_supports_seed(cache) ||
        !cacheInfoKnown || !r_is_objc_ptr(lightAppearance) ||
        !r_is_objc_ptr(darkAppearance) || !generationKnown) {
        printf("[SPOTLIGHT_PROOF] begin stopped reason=static-cache-unavailable "
               "variantKnown=%d variant=%llu cache=0x%llx cacheInfo=%d "
               "size=%.1fx%.1f@%.2f light=0x%llx dark=0x%llx "
               "generationKnown=%d\n",
               variantKnown,
               (unsigned long long)variant,
               (unsigned long long)cache,
               cacheInfoKnown,
               cacheInfo.width,
               cacheInfo.height,
               cacheInfo.scale,
               (unsigned long long)lightAppearance,
               (unsigned long long)darkAppearance,
               generationKnown);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightProofBeginResultSeedFailed;
    }

    uint64_t stockLight = themer_spotlight_proof_cache_read(
        cache, selected.icon, lightAppearance, true);
    uint64_t stockDark = themer_spotlight_proof_cache_read(
        cache, selected.icon, darkAppearance, true);
    if (!r_is_objc_ptr(stockLight) || !r_is_objc_ptr(stockDark)) {
        printf("[SPOTLIGHT_PROOF] begin stopped reason=stock-capture-failed "
               "bundle=%s light=0x%llx dark=0x%llx\n",
               selected.bundle,
               (unsigned long long)stockLight,
               (unsigned long long)stockDark);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightProofBeginResultSeedFailed;
    }

    uint64_t controlStockLight = 0;
    uint64_t controlStockDark = 0;
    if (r_is_objc_ptr(control.icon)) {
        controlStockLight = themer_spotlight_proof_cache_read(
            cache, control.icon, lightAppearance, true);
        controlStockDark = themer_spotlight_proof_cache_read(
            cache, control.icon, darkAppearance, true);
    }

    ThemerSpotlightRemoteImage images[THEMER_SPOTLIGHT_PROOF_IMAGE_CAP] = {{0}};
    int imageCount = 0;
    uint64_t sourceImage = themer_spotlight_remote_image_for_bundle(
        normalized, selected.bundle, images, &imageCount,
        THEMER_SPOTLIGHT_PROOF_IMAGE_CAP);
    if (!r_is_objc_ptr(sourceImage)) {
        printf("[SPOTLIGHT_PROOF] begin stopped reason=image-upload-failed "
               "bundle=%s\n", selected.bundle);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightProofBeginResultSeedFailed;
    }
    uint64_t adjusted = themer_spotlight_provider_sized_themed_image(
        sourceImage, cacheInfo.width, cacheInfo.scale);
    uint64_t patchImage = r_is_objc_ptr(adjusted) ? adjusted : sourceImage;
    if (!r_is_objc_ptr(patchImage) ||
        themer_spotlight_images_match(stockLight, patchImage) ||
        themer_spotlight_images_match(stockDark, patchImage)) {
        printf("[SPOTLIGHT_PROOF] begin stopped "
               "reason=invalid-or-already-themed-image bundle=%s patch=0x%llx\n",
               selected.bundle,
               (unsigned long long)patchImage);
        themer_spotlight_proof_release_images(images, imageCount, adjusted);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightProofBeginResultSeedFailed;
    }

    bool lightSeeded = themer_spotlight_proof_cache_seed(
        cache, patchImage, selected.icon, lightAppearance);
    bool darkSeeded = lightSeeded && themer_spotlight_proof_cache_seed(
        cache, patchImage, selected.icon, darkAppearance);
    if (!lightSeeded || !darkSeeded) {
        bool lightRolledBack = themer_spotlight_proof_cache_seed(
            cache, stockLight, selected.icon, lightAppearance);
        bool darkRolledBack = themer_spotlight_proof_cache_seed(
            cache, stockDark, selected.icon, darkAppearance);
        printf("[SPOTLIGHT_PROOF] begin stopped reason=seed-not-verified "
               "bundle=%s light=%d dark=%d rollback=%d/%d\n",
               selected.bundle,
               lightSeeded,
               darkSeeded,
               lightRolledBack,
               darkRolledBack);
        themer_spotlight_proof_release_images(images, imageCount, adjusted);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightProofBeginResultSeedFailed;
    }

    uint64_t dictionaryClass = r_class("NSMutableDictionary");
    uint64_t stateAlloc = r_is_objc_ptr(dictionaryClass)
        ? r_msg2(dictionaryClass, "alloc", 0, 0, 0, 0) : 0;
    uint64_t state = r_is_objc_ptr(stateAlloc)
        ? r_msg2_main(stateAlloc, "initWithCapacity:", 16, 0, 0, 0) : 0;
    bool stateReady = r_is_objc_ptr(state);
    uint64_t pidNumber = themer_spotlight_proof_number(
        (unsigned long long)remote_call_current_pid());
    uint64_t variantNumber = themer_spotlight_proof_number(variant);
    uint64_t generationNumber = themer_spotlight_proof_number(
        imageGeneration);
    stateReady = stateReady && r_is_objc_ptr(pidNumber) &&
        themer_spotlight_dictionary_set_object(state, "pid", pidNumber);
    stateReady = stateReady &&
        themer_spotlight_proof_state_set_string(
            state, "bundle", selected.bundle);
    stateReady = stateReady &&
        themer_spotlight_dictionary_set_object(state, "cache", cache) &&
        themer_spotlight_dictionary_set_object(state, "icon", selected.icon) &&
        themer_spotlight_dictionary_set_object(
            state, "lightAppearance", lightAppearance) &&
        themer_spotlight_dictionary_set_object(
            state, "darkAppearance", darkAppearance) &&
        themer_spotlight_dictionary_set_object(
            state, "expectedImage", patchImage) &&
        themer_spotlight_dictionary_set_object(
            state, "stockLight", stockLight) &&
        themer_spotlight_dictionary_set_object(
            state, "stockDark", stockDark) &&
        r_is_objc_ptr(variantNumber) &&
        themer_spotlight_dictionary_set_object(
            state, "variant", variantNumber) &&
        r_is_objc_ptr(generationNumber) &&
        themer_spotlight_dictionary_set_object(
            state, "imageGeneration", generationNumber);
    if (stateReady && r_is_objc_ptr(control.icon)) {
        stateReady = themer_spotlight_proof_state_set_string(
            state, "controlBundle", control.bundle) &&
            themer_spotlight_dictionary_set_object(
                state, "controlIcon", control.icon) && stateReady;
        if (r_is_objc_ptr(controlStockLight)) {
            stateReady = themer_spotlight_dictionary_set_object(
                state, "controlStockLight", controlStockLight) && stateReady;
        }
        if (r_is_objc_ptr(controlStockDark)) {
            stateReady = themer_spotlight_dictionary_set_object(
                state, "controlStockDark", controlStockDark) && stateReady;
        }
    }

    bool committed = stateReady &&
        themer_spotlight_proof_commit_state(state);
    if (!committed) {
        bool lightRolledBack = themer_spotlight_proof_cache_seed(
            cache, stockLight, selected.icon, lightAppearance);
        bool darkRolledBack = themer_spotlight_proof_cache_seed(
            cache, stockDark, selected.icon, darkAppearance);
        printf("[SPOTLIGHT_PROOF] begin stopped reason=state-commit-failed "
               "bundle=%s stateReady=%d rollback=%d/%d\n",
               selected.bundle,
               stateReady,
               lightRolledBack,
               darkRolledBack);
        if (r_is_objc_ptr(state) && remote_call_current_success()) {
            r_msg2(state, "release", 0, 0, 0, 0);
        }
        themer_spotlight_proof_release_images(images, imageCount, adjusted);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightProofBeginResultStateFailed;
    }

    char cacheClass[96] = {0};
    char iconClass[96] = {0};
    themer_read_class_name(cache, cacheClass, sizeof(cacheClass));
    themer_read_class_name(selected.icon, iconClass, sizeof(iconClass));
    printf("[SPOTLIGHT_PROOF] seed pid=%d bundle=%s control=%s "
           "owner=0x%llx dataSource=0x%llx iconModel=0x%llx "
           "repository=0x%llx icon=0x%llx/%s provider=0x%llx via=%s "
           "idiom=%llu variant=%llu cache=0x%llx/%s "
           "size=%.1fx%.1f@%.2f generation=%llu "
           "stock=0x%llx/0x%llx expected=0x%llx light=%d dark=%d "
           "stateCommitted=%d total=%llums\n",
           remote_call_current_pid(),
           selected.bundle,
           r_is_objc_ptr(control.icon) ? control.bundle : "-",
           (unsigned long long)owner,
           (unsigned long long)dataSource,
           (unsigned long long)iconModel,
           (unsigned long long)repository,
           (unsigned long long)selected.icon,
           iconClass[0] ? iconClass : "-",
           (unsigned long long)selected.provider,
           selected.selector ?: "-",
           (unsigned long long)idiom,
           (unsigned long long)variant,
           (unsigned long long)cache,
           cacheClass[0] ? cacheClass : "-",
           cacheInfo.width,
           cacheInfo.height,
           cacheInfo.scale,
           (unsigned long long)imageGeneration,
           (unsigned long long)stockLight,
           (unsigned long long)stockDark,
           (unsigned long long)patchImage,
           lightSeeded,
           darkSeeded,
           committed,
           (unsigned long long)((themer_now_us() - startUS) / 1000ULL));

    if (r_is_objc_ptr(state) && remote_call_current_success()) {
        r_msg2(state, "release", 0, 0, 0, 0);
    }
    themer_spotlight_proof_release_images(images, imageCount, adjusted);
    r_settle_us(previousSettleUS);
    return ThemerSpotlightProofBeginResultSeeded;
}

static __attribute__((unused)) ThemerSpotlightProofBeginResult
themer_spotlight_proof_begin_visible_legacy_in_session(
    NSDictionary<NSString *, NSData *> *imageDataByBundle,
    volatile int *stopRequested)
{
    uint64_t totalStartUS = themer_now_us();
    NSDictionary<NSString *, NSData *> *normalized =
        themer_normalized_theme_data(imageDataByBundle);
    if (normalized.count == 0) {
        printf("[SPOTLIGHT_PROOF] begin skipped reason=empty-theme\n");
        return ThemerSpotlightProofBeginResultNoVisibleThemedIcon;
    }
    if (r_is_objc_ptr(themer_spotlight_proof_state())) {
        printf("[SPOTLIGHT_PROOF] begin stopped reason=proof-already-armed\n");
        return ThemerSpotlightProofBeginResultStateFailed;
    }
    if (r_is_objc_ptr(themer_spotlight_theme_state())) {
        printf("[SPOTLIGHT_PROOF] begin stopped "
               "reason=production-theme-state-present action=respring-first\n");
        return ThemerSpotlightProofBeginResultStateFailed;
    }

    uint32_t previousSettleUS = r_settle_us(1000);

    uint64_t views[THEMER_SPOTLIGHT_PROOF_VIEW_CAP] = {0};
    int viewCount = themer_spotlight_collect_searchui_views(
        views, THEMER_SPOTLIGHT_PROOF_VIEW_CAP);
    uint64_t collectEndUS = themer_now_us();

    // Snapshot the live themed rows once. Begin deliberately requires the
    // proof app to be visible: the materialized row supplies the exact
    // cache/variant/appearance binding, and persistence across dismissal
    // and reopen is the property under test.
    typedef struct {
        uint64_t view;
        uint64_t appIcon;
        char bundle[192];
    } ThemerSpotlightProofRow;
    ThemerSpotlightProofRow rows[THEMER_SPOTLIGHT_PROOF_ROW_CAP] = {{0}};
    int rowCount = 0;
    for (int i = 0; i < viewCount && rowCount < THEMER_SPOTLIGHT_PROOF_ROW_CAP;
         i++) {
        if (stopRequested && *stopRequested) break;
        uint64_t view = views[i];
        if (!themer_spotlight_view_is_live(view)) continue;
        uint64_t appIcon = themer_spotlight_app_icon_for_view(view, NULL, 0);
        if (!r_is_objc_ptr(appIcon)) continue;
        char bundle[192] = {0};
        if (!themer_spotlight_bundle_for_patch(view, appIcon,
                                               bundle, sizeof(bundle),
                                               NULL, 0)) {
            continue;
        }
        NSString *key = [NSString stringWithUTF8String:bundle];
        NSData *bytes = themer_theme_data_for_key(normalized, key, NULL);
        if (![bytes isKindOfClass:NSData.class] || bytes.length == 0) continue;
        ThemerSpotlightProofRow *row = &rows[rowCount++];
        row->view = view;
        row->appIcon = appIcon;
        snprintf(row->bundle, sizeof(row->bundle), "%s", bundle);
    }
    uint64_t rowScanEndUS = themer_now_us();

    // Deterministic selection: iterate the theme keys in sorted order; the
    // first visible themed row is the proof seed and the second is the
    // untouched negative control. The Cyanide app itself is deferred to the
    // fallback slot, matching the existing single-probe convention.
    NSArray<NSString *> *sortedKeys = [normalized.allKeys
        sortedArrayUsingSelector:@selector(compare:)];
    ThemerSpotlightProofRow selected = {0};
    ThemerSpotlightProofRow control = {0};
    for (NSString *key in sortedKeys) {
        if (stopRequested && *stopRequested) break;
        const char *bundle = key.UTF8String;
        if (strcmp(bundle, "com.zeroxjf.ios-cyanide1") == 0) continue;
        for (int i = 0; i < rowCount; i++) {
            if (strcmp(rows[i].bundle, bundle) != 0) continue;
            if (!r_is_objc_ptr(selected.view)) {
                selected = rows[i];
            } else if (!r_is_objc_ptr(control.view)) {
                control = rows[i];
                break;
            }
        }
        if (r_is_objc_ptr(control.view)) break;
    }
    if (!r_is_objc_ptr(selected.view)) {
        for (int i = 0; i < rowCount; i++) {
            if (strcmp(rows[i].bundle, "com.zeroxjf.ios-cyanide1") != 0) {
                continue;
            }
            selected = rows[i];
            break;
        }
    }
    uint64_t selectEndUS = themer_now_us();
    if (!r_is_objc_ptr(selected.view)) {
        printf("[SPOTLIGHT_PROOF] begin stopped reason=no-visible-themed-icon "
               "views=%d rows=%d select=%llums total=%llums\n",
               viewCount,
               rowCount,
               (unsigned long long)((selectEndUS - rowScanEndUS) / 1000ULL),
               (unsigned long long)((selectEndUS - totalStartUS) / 1000ULL));
        r_settle_us(previousSettleUS);
        return ThemerSpotlightProofBeginResultNoVisibleThemedIcon;
    }

    char viewClass[96] = {0};
    char iconClass[96] = {0};
    themer_read_class_name(selected.view, viewClass, sizeof(viewClass));
    themer_read_class_name(selected.appIcon, iconClass, sizeof(iconClass));
    printf("[SPOTLIGHT_PROOF] select pid=%d bundle=%s control=%s "
           "view=0x%llx/%s appIcon=0x%llx/%s views=%d rows=%d "
           "select=%llums\n",
           remote_call_current_pid(),
           selected.bundle,
           r_is_objc_ptr(control.view) ? control.bundle : "-",
           (unsigned long long)selected.view,
           viewClass[0] ? viewClass : "-",
           (unsigned long long)selected.appIcon,
           iconClass[0] ? iconClass : "-",
           viewCount,
           rowCount,
           (unsigned long long)((selectEndUS - collectEndUS) / 1000ULL));

    // Upload the themed image and size it to the stock geometry when the
    // existing resize helper can.
    ThemerSpotlightRemoteImage images[THEMER_SPOTLIGHT_PROOF_IMAGE_CAP] = {{0}};
    int imageCount = 0;
    uint64_t sourceImage = themer_spotlight_remote_image_for_bundle(
        normalized, selected.bundle, images, &imageCount,
        THEMER_SPOTLIGHT_PROOF_IMAGE_CAP);
    if (!r_is_objc_ptr(sourceImage)) {
        printf("[SPOTLIGHT_PROOF] begin stopped reason=image-upload-failed "
               "bundle=%s\n",
               selected.bundle);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightProofBeginResultSeedFailed;
    }
    uint64_t uploadEndUS = themer_now_us();

    uint64_t carrier = themer_spotlight_image_carrier_for_view(selected.view);
    uint64_t stockImage = themer_spotlight_image_from_carrier(carrier);
    char cacheSource[128] = {0};
    uint64_t cache = themer_spotlight_find_icon_cache(
        selected.view, carrier, selected.appIcon,
        cacheSource, sizeof(cacheSource));
    const char *stockSelector = NULL;
    if (!r_is_objc_ptr(stockImage)) {
        stockImage = themer_spotlight_cached_image(cache, selected.appIcon,
                                                   &stockSelector);
    }
    if (!r_is_objc_ptr(cache) ||
        !themer_spotlight_carrier_cache_supports_seed(cache) ||
        !r_is_objc_ptr(stockImage)) {
        printf("[SPOTLIGHT_PROOF] begin stopped "
               "reason=cache-or-stock-unavailable "
               "bundle=%s cache=0x%llx cacheSource=%s stock=0x%llx\n",
               selected.bundle,
               (unsigned long long)cache,
               cacheSource[0] ? cacheSource : "-",
               (unsigned long long)stockImage);
        themer_spotlight_proof_release_images(images, imageCount, 0);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightProofBeginResultSeedFailed;
    }

    double targetW = 0.0;
    double targetH = 0.0;
    double stockScale = 0.0;
    bool stockGeometry = themer_read_image_geometry(stockImage,
                                                    &targetW,
                                                    &targetH,
                                                    &stockScale);
    if (!stockGeometry) {
        ThemerRect carrierBounds = {0};
        if (themer_read_rect(carrier, "bounds", &carrierBounds) &&
            carrierBounds.w >= 8.0 && carrierBounds.w <= 180.0) {
            targetW = carrierBounds.w;
            targetH = carrierBounds.h;
        } else {
            targetW = 60.0;
            targetH = 60.0;
        }
        stockScale = themer_screen_scale();
    }

    uint64_t adjusted = themer_spotlight_provider_sized_themed_image(
        sourceImage, targetW, stockScale);
    uint64_t patchImage = r_is_objc_ptr(adjusted) ? adjusted : sourceImage;
    if (!r_is_objc_ptr(patchImage)) {
        printf("[SPOTLIGHT_PROOF] begin stopped reason=no-patch-image "
               "bundle=%s\n",
               selected.bundle);
        themer_spotlight_proof_release_images(images, imageCount, adjusted);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightProofBeginResultSeedFailed;
    }
    if (themer_spotlight_images_match(stockImage, patchImage)) {
        printf("[SPOTLIGHT_PROOF] begin stopped "
               "reason=stock-already-matches-theme bundle=%s\n",
               selected.bundle);
        themer_spotlight_proof_release_images(images, imageCount, adjusted);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightProofBeginResultSeedFailed;
    }

    char appearanceSource[128] = {0};
    uint64_t appearance = themer_spotlight_image_appearance(
        selected.view, carrier,
        appearanceSource, sizeof(appearanceSource));
    uint64_t variant = 0;
    bool variantKnown = themer_spotlight_trace_variant_for_view(
        selected.view, &variant);
    uint64_t staticCache = 0;
    uint64_t viewClassObject =
        themer_lookup_class("SearchUIHomeScreenAppIconView");
    if (variantKnown && r_is_objc_ptr(viewClassObject) &&
        r_responds_main(viewClassObject, "cacheForVariant:")) {
        staticCache = r_msg2_main(viewClassObject, "cacheForVariant:",
                                  variant, 0, 0, 0);
        if (themer_spotlight_carrier_cache_supports_seed(staticCache)) {
            cache = staticCache;
            snprintf(cacheSource, sizeof(cacheSource),
                     "class.cacheForVariant:%llu",
                     (unsigned long long)variant);
        }
    }
    bool generationKnown = r_responds_main(cache,
                                           "currentImageGenerationForIcon:");
    uint64_t imageGeneration = generationKnown
        ? r_msg2_main(cache, "currentImageGenerationForIcon:",
                      selected.appIcon, 0, 0, 0)
        : 0;
    if (!r_is_objc_ptr(appearance) || !variantKnown ||
        !r_is_objc_ptr(staticCache) || cache != staticCache ||
        !generationKnown) {
        printf("[SPOTLIGHT_PROOF] begin stopped "
               "reason=missing-static-binding bundle=%s "
               "appearance=0x%llx variantKnown=%d variant=%llu "
               "rowCache=0x%llx staticCache=0x%llx generationKnown=%d\n",
               selected.bundle,
               (unsigned long long)appearance,
               variantKnown,
               (unsigned long long)variant,
               (unsigned long long)cache,
               (unsigned long long)staticCache,
               generationKnown);
        themer_spotlight_proof_release_images(images, imageCount, adjusted);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightProofBeginResultSeedFailed;
    }
    uint64_t prepareEndUS = themer_now_us();

    ThemerSpotlightCacheTarget cacheTargets[THEMER_SPOTLIGHT_PROOF_TARGET_CAP] = {{0}};
    int cacheTargetCount = themer_spotlight_collect_cache_targets(
        cache, cacheTargets, THEMER_SPOTLIGHT_PROOF_TARGET_CAP);
    int cacheSeedCalls = themer_spotlight_seed_cache_targets(
        cacheTargets, cacheTargetCount,
        patchImage, selected.appIcon, appearance,
        imageGeneration, true);
    ThemerSpotlightCacheVerification cacheVerification =
        themer_spotlight_verify_cache_targets(
            cacheTargets, cacheTargetCount,
            patchImage, selected.appIcon, appearance, true);
    bool seeded = cacheSeedCalls > 0 &&
                  (cacheVerification.rootNativeMatches > 0 ||
                   cacheVerification.backingNativeMatches > 0);
    uint64_t cacheEndUS = themer_now_us();

    // Negative control: capture the untouched row's stock CG identity.
    uint64_t controlStockCG = 0;
    if (r_is_objc_ptr(control.view)) {
        uint64_t controlCarrier = themer_spotlight_image_carrier_for_view(
            control.view);
        uint64_t controlImage = themer_spotlight_image_from_carrier(
            controlCarrier);
        if (!r_is_objc_ptr(controlImage)) {
            char controlCacheSource[128] = {0};
            uint64_t controlCache = themer_spotlight_find_icon_cache(
                control.view, controlCarrier, control.appIcon,
                controlCacheSource, sizeof(controlCacheSource));
            controlImage = themer_spotlight_cached_image(controlCache,
                                                         control.appIcon,
                                                         NULL);
        }
        if (r_is_objc_ptr(controlImage) &&
            r_responds_main(controlImage, "CGImage")) {
            controlStockCG = r_msg2_main(controlImage, "CGImage", 0, 0, 0, 0);
        }
    }

    if (!seeded) {
        int rollbackCalls = 0;
        bool rolledBack = themer_spotlight_proof_overwrite_cache(
            cache, stockImage, selected.appIcon, appearance,
            imageGeneration, &rollbackCalls);
        printf("[SPOTLIGHT_PROOF] begin stopped reason=seed-not-verified "
               "bundle=%s seedCalls=%d rootNative=%d backingNative=%d "
               "keyed=%d rootOptioned=%d/%d rootRender=%d/%d "
               "rootLegacy=%d/%d rollbackCalls=%d rolledBack=%d\n",
               selected.bundle,
               cacheSeedCalls,
               cacheVerification.rootNativeMatches,
               cacheVerification.backingNativeMatches,
               cacheVerification.keyedMatches,
               cacheVerification.rootOptionedReads,
               cacheVerification.rootOptionedMatches,
               cacheVerification.rootRenderReads,
               cacheVerification.rootRenderMatches,
               cacheVerification.rootLegacyReads,
               cacheVerification.rootLegacyMatches,
               rollbackCalls,
               rolledBack);
        themer_spotlight_proof_release_images(images, imageCount, adjusted);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightProofBeginResultSeedFailed;
    }

    // Retain everything a later same-PID session needs in one process
    // associated object. The committed dictionary intentionally keeps the
    // +1 from init, matching the existing theme-state convention, so the
    // state is never released while the process is alive.
    uint64_t dictionaryClass = r_class("NSMutableDictionary");
    uint64_t stateAlloc = r_is_objc_ptr(dictionaryClass)
        ? r_msg2(dictionaryClass, "alloc", 0, 0, 0, 0) : 0;
    uint64_t state = r_is_objc_ptr(stateAlloc)
        ? r_msg2_main(stateAlloc, "init", 0, 0, 0, 0) : 0;
    if (!r_is_objc_ptr(state)) {
        int rollbackCalls = 0;
        bool rolledBack = themer_spotlight_proof_overwrite_cache(
            cache, stockImage, selected.appIcon, appearance,
            imageGeneration, &rollbackCalls);
        printf("[SPOTLIGHT_PROOF] begin stopped reason=state-create-failed "
               "bundle=%s rollbackCalls=%d rolledBack=%d\n",
               selected.bundle,
               rollbackCalls,
               rolledBack);
        themer_spotlight_proof_release_images(images, imageCount, adjusted);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightProofBeginResultStateFailed;
    }

    bool stateReady = true;
    uint64_t pidNumber = themer_spotlight_proof_number(
        (unsigned long long)remote_call_current_pid());
    uint64_t variantNumber = variantKnown
        ? themer_spotlight_proof_number(variant) : 0;
    uint64_t generationNumber = generationKnown
        ? themer_spotlight_proof_number(imageGeneration) : 0;
    uint64_t controlCGNumber = controlStockCG
        ? themer_spotlight_proof_number(controlStockCG) : 0;
    if (r_is_objc_ptr(pidNumber)) {
        stateReady = themer_spotlight_dictionary_set_object(
            state, "pid", pidNumber) && stateReady;
    } else {
        stateReady = false;
    }
    stateReady = themer_spotlight_proof_state_set_string(
        state, "bundle", selected.bundle) && stateReady;
    if (r_is_objc_ptr(control.view)) {
        stateReady = themer_spotlight_proof_state_set_string(
            state, "controlBundle", control.bundle) && stateReady;
    }
    stateReady = themer_spotlight_dictionary_set_object(
        state, "cache", cache) && stateReady;
    stateReady = themer_spotlight_dictionary_set_object(
        state, "icon", selected.appIcon) && stateReady;
    stateReady = themer_spotlight_dictionary_set_object(
        state, "appearance", appearance) && stateReady;
    stateReady = themer_spotlight_dictionary_set_object(
        state, "expectedImage", patchImage) && stateReady;
    if (r_is_objc_ptr(stockImage)) {
        stateReady = themer_spotlight_dictionary_set_object(
            state, "stockImage", stockImage) && stateReady;
    }
    if (r_is_objc_ptr(variantNumber)) {
        stateReady = themer_spotlight_dictionary_set_object(
            state, "variant", variantNumber) && stateReady;
    }
    if (r_is_objc_ptr(generationNumber)) {
        stateReady = themer_spotlight_dictionary_set_object(
            state, "imageGeneration", generationNumber) && stateReady;
    }
    if (r_is_objc_ptr(controlCGNumber)) {
        stateReady = themer_spotlight_dictionary_set_object(
            state, "controlStockCG", controlCGNumber) && stateReady;
    }
    if (!stateReady) {
        int rollbackCalls = 0;
        bool rolledBack = themer_spotlight_proof_overwrite_cache(
            cache, stockImage, selected.appIcon, appearance,
            imageGeneration, &rollbackCalls);
        printf("[SPOTLIGHT_PROOF] begin stopped reason=state-build-failed "
               "bundle=%s rollbackCalls=%d rolledBack=%d\n",
               selected.bundle,
               rollbackCalls,
               rolledBack);
        if (r_is_objc_ptr(state) && remote_call_current_success()) {
            r_msg2(state, "release", 0, 0, 0, 0);
        }
        themer_spotlight_proof_release_images(images, imageCount, adjusted);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightProofBeginResultStateFailed;
    }

    bool committed = themer_spotlight_proof_commit_state(state);
    if (!committed) {
        int rollbackCalls = 0;
        bool rolledBack = themer_spotlight_proof_overwrite_cache(
            cache, stockImage, selected.appIcon, appearance,
            imageGeneration, &rollbackCalls);
        printf("[SPOTLIGHT_PROOF] begin stopped reason=state-commit-failed "
               "bundle=%s rollbackCalls=%d rolledBack=%d\n",
               selected.bundle,
               rollbackCalls,
               rolledBack);
        if (r_is_objc_ptr(state) && remote_call_current_success()) {
            r_msg2(state, "release", 0, 0, 0, 0);
        }
        themer_spotlight_proof_release_images(images, imageCount, adjusted);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightProofBeginResultStateFailed;
    }

    printf("[SPOTLIGHT_PROOF] seed bundle=%s cache=0x%llx/%s "
           "cacheTargets=%d appearance=0x%llx/%s variantKnown=%d "
           "variant=%llu generation=%llu seedCalls=%d rootNative=%d "
           "backingNative=%d keyed=%d control=%s controlStockCG=0x%llx "
           "stateCommitted=%d timing=collect:%llums,select:%llums,upload:"
           "%llums,prepare:%llums,cache:%llums,total:%llums\n",
           selected.bundle,
           (unsigned long long)cache,
           cacheSource[0] ? cacheSource : "-",
           cacheTargetCount,
           (unsigned long long)appearance,
           appearanceSource[0] ? appearanceSource : "-",
           variantKnown,
           (unsigned long long)variant,
           (unsigned long long)imageGeneration,
           cacheSeedCalls,
           cacheVerification.rootNativeMatches,
           cacheVerification.backingNativeMatches,
           cacheVerification.keyedMatches,
           r_is_objc_ptr(control.view) ? control.bundle : "-",
           (unsigned long long)controlStockCG,
           committed,
           (unsigned long long)((collectEndUS - totalStartUS) / 1000ULL),
           (unsigned long long)((selectEndUS - collectEndUS) / 1000ULL),
           (unsigned long long)((uploadEndUS - selectEndUS) / 1000ULL),
           (unsigned long long)((prepareEndUS - uploadEndUS) / 1000ULL),
           (unsigned long long)((cacheEndUS - prepareEndUS) / 1000ULL),
           (unsigned long long)((cacheEndUS - totalStartUS) / 1000ULL));

    if (r_is_objc_ptr(state) && remote_call_current_success()) {
        r_msg2(state, "release", 0, 0, 0, 0);
    }
    themer_spotlight_proof_release_images(images, imageCount, adjusted);
    r_settle_us(previousSettleUS);
    return ThemerSpotlightProofBeginResultSeeded;
}

ThemerSpotlightProofVerifyResult
themer_spotlight_proof_verify_and_cleanup_in_session(void)
{
    uint64_t startUS = themer_now_us();
    uint64_t state = themer_spotlight_proof_state();
    if (!r_is_objc_ptr(state)) {
        printf("[SPOTLIGHT_PROOF] verify skipped reason=no-state\n");
        return ThemerSpotlightProofVerifyResultNoState;
    }

    uint64_t statePid = 0;
    bool pidKnown = themer_spotlight_proof_state_u64(
        state, "pid", &statePid);
    int currentPid = remote_call_current_pid();
    if (!pidKnown || statePid != (uint64_t)currentPid) {
        printf("[SPOTLIGHT_PROOF] verify host-mismatch statePid=%llu "
               "currentPid=%d\n",
               (unsigned long long)statePid,
               currentPid);
        themer_spotlight_proof_clear_state();
        return ThemerSpotlightProofVerifyResultHostStateMismatch;
    }

    char bundle[192] = {0};
    char controlBundle[192] = {0};
    (void)themer_spotlight_proof_state_string(
        state, "bundle", bundle, sizeof(bundle));
    (void)themer_spotlight_proof_state_string(
        state, "controlBundle", controlBundle, sizeof(controlBundle));
    uint64_t storedCache = themer_spotlight_proof_state_object(
        state, "cache");
    uint64_t storedIcon = themer_spotlight_proof_state_object(
        state, "icon");
    uint64_t lightAppearance = themer_spotlight_proof_state_object(
        state, "lightAppearance");
    uint64_t darkAppearance = themer_spotlight_proof_state_object(
        state, "darkAppearance");
    uint64_t expectedImage = themer_spotlight_proof_state_object(
        state, "expectedImage");
    uint64_t stockLight = themer_spotlight_proof_state_object(
        state, "stockLight");
    uint64_t stockDark = themer_spotlight_proof_state_object(
        state, "stockDark");
    uint64_t storedControlIcon = themer_spotlight_proof_state_object(
        state, "controlIcon");
    uint64_t controlStockLight = themer_spotlight_proof_state_object(
        state, "controlStockLight");
    uint64_t controlStockDark = themer_spotlight_proof_state_object(
        state, "controlStockDark");
    uint64_t variant = 0;
    uint64_t storedGeneration = 0;
    bool variantKnown = themer_spotlight_proof_state_u64(
        state, "variant", &variant);
    bool storedGenerationKnown = themer_spotlight_proof_state_u64(
        state, "imageGeneration", &storedGeneration);
    if (!bundle[0] || !variantKnown ||
        !r_is_objc_ptr(storedCache) || !r_is_objc_ptr(storedIcon) ||
        !r_is_objc_ptr(lightAppearance) ||
        !r_is_objc_ptr(darkAppearance) ||
        !r_is_objc_ptr(expectedImage) ||
        !r_is_objc_ptr(stockLight) || !r_is_objc_ptr(stockDark)) {
        printf("[SPOTLIGHT_PROOF] verify host-mismatch "
               "reason=incomplete-state bundle=%s variantKnown=%d "
               "cache=0x%llx icon=0x%llx expected=0x%llx "
               "stock=0x%llx/0x%llx\n",
               bundle[0] ? bundle : "-",
               variantKnown,
               (unsigned long long)storedCache,
               (unsigned long long)storedIcon,
               (unsigned long long)expectedImage,
               (unsigned long long)stockLight,
               (unsigned long long)stockDark);
        themer_spotlight_proof_clear_state();
        return ThemerSpotlightProofVerifyResultHostStateMismatch;
    }

    uint64_t viewClass =
        themer_lookup_class("SearchUIHomeScreenAppIconView");
    uint64_t resolvedCache =
        r_is_objc_ptr(viewClass) &&
        r_responds_main(viewClass, "cacheForVariant:")
            ? r_msg2_main(viewClass, "cacheForVariant:",
                          variant, 0, 0, 0)
            : 0;
    const char *cacheResolution = !r_is_objc_ptr(resolvedCache)
        ? "unavailable"
        : resolvedCache == storedCache ? "same" : "different";
    if (!themer_spotlight_carrier_cache_supports_seed(resolvedCache)) {
        resolvedCache = storedCache;
        cacheResolution = "retained-fallback";
    }

    uint64_t owner = 0;
    uint64_t dataSource = 0;
    uint64_t iconModel = 0;
    uint64_t repository = 0;
    bool graphKnown = themer_spotlight_current_graph(
        &owner, &dataSource, &iconModel, &repository);
    uint64_t currentProvider = 0;
    const char *currentSelector = NULL;
    uint64_t currentIcon = graphKnown
        ? themer_spotlight_materialize_provider_icon(
              owner, dataSource, bundle,
              &currentProvider, &currentSelector)
        : 0;
    bool currentIconFresh = r_is_objc_ptr(currentIcon);
    if (!currentIconFresh) currentIcon = storedIcon;

    bool currentGenerationKnown =
        r_responds_main(resolvedCache, "currentImageGenerationForIcon:");
    uint64_t currentGeneration = currentGenerationKnown
        ? r_msg2_main(resolvedCache, "currentImageGenerationForIcon:",
                      currentIcon, 0, 0, 0)
        : 0;
    bool generationDrifted = storedGenerationKnown &&
        currentGenerationKnown && currentGeneration != storedGeneration;

    uint64_t lightReadback = themer_spotlight_proof_cache_read(
        resolvedCache, currentIcon, lightAppearance, false);
    uint64_t darkReadback = themer_spotlight_proof_cache_read(
        resolvedCache, currentIcon, darkAppearance, false);
    bool lightMatch = themer_spotlight_images_match(
        expectedImage, lightReadback);
    bool darkMatch = themer_spotlight_images_match(
        expectedImage, darkReadback);
    bool readsHappened =
        r_is_objc_ptr(lightReadback) || r_is_objc_ptr(darkReadback);

    uint64_t currentControlIcon = 0;
    uint64_t currentControlProvider = 0;
    const char *currentControlSelector = NULL;
    if (controlBundle[0] && graphKnown) {
        currentControlIcon = themer_spotlight_materialize_provider_icon(
            owner, dataSource, controlBundle,
            &currentControlProvider, &currentControlSelector);
    }
    if (!r_is_objc_ptr(currentControlIcon)) {
        currentControlIcon = storedControlIcon;
    }
    bool controlChecked = false;
    bool controlStillStock = false;
    uint64_t controlLightReadback = 0;
    uint64_t controlDarkReadback = 0;
    if (r_is_objc_ptr(currentControlIcon) &&
        r_is_objc_ptr(controlStockLight) &&
        r_is_objc_ptr(controlStockDark)) {
        controlLightReadback = themer_spotlight_proof_cache_read(
            resolvedCache, currentControlIcon, lightAppearance, false);
        controlDarkReadback = themer_spotlight_proof_cache_read(
            resolvedCache, currentControlIcon, darkAppearance, false);
        controlChecked = r_is_objc_ptr(controlLightReadback) ||
                         r_is_objc_ptr(controlDarkReadback);
        controlStillStock =
            themer_spotlight_images_match(
                controlStockLight, controlLightReadback) &&
            themer_spotlight_images_match(
                controlStockDark, controlDarkReadback);
    }

    // Diagnostic only: a row cannot normally remain foreground while the user
    // invokes Cyanide's Phase 2 action. If SearchUI retained its row objects,
    // record whether their carriers still reference the seeded image, but do
    // not make that incidental presentation lifetime part of the cache verdict.
    int materializedRows = 0;
    int liveRows = 0;
    int rowImageMatches = 0;
    uint64_t views[THEMER_SPOTLIGHT_PROOF_VIEW_CAP] = {0};
    int viewCount = themer_spotlight_collect_searchui_views(
        views, THEMER_SPOTLIGHT_PROOF_VIEW_CAP);
    for (int i = 0; i < viewCount; i++) {
        uint64_t rowIcon = themer_spotlight_app_icon_for_view(
            views[i], NULL, 0);
        if (!r_is_objc_ptr(rowIcon)) continue;
        char rowBundle[192] = {0};
        if (!themer_spotlight_bundle_for_patch(
                views[i], rowIcon, rowBundle, sizeof(rowBundle),
                NULL, 0) || strcmp(rowBundle, bundle) != 0) {
            continue;
        }
        materializedRows++;
        if (themer_spotlight_view_is_live(views[i])) liveRows++;
        uint64_t carrier = themer_spotlight_image_carrier_for_view(views[i]);
        uint64_t rowImage = themer_spotlight_image_from_carrier(carrier);
        if (themer_spotlight_images_match(expectedImage, rowImage)) {
            rowImageMatches++;
        }
    }

    ThemerSpotlightProofVerifyResult verdict;
    if (lightMatch && darkMatch) {
        verdict = ThemerSpotlightProofVerifyResultThemedHit;
    } else if (readsHappened) {
        verdict = ThemerSpotlightProofVerifyResultStockOrMiss;
    } else {
        verdict = ThemerSpotlightProofVerifyResultInconclusive;
    }

    bool restoreLight = themer_spotlight_proof_cache_seed(
        resolvedCache, stockLight, currentIcon, lightAppearance);
    bool restoreDark = themer_spotlight_proof_cache_seed(
        resolvedCache, stockDark, currentIcon, darkAppearance);
    bool restoreStoredCache = true;
    if (storedCache != resolvedCache) {
        bool storedLight = themer_spotlight_proof_cache_seed(
            storedCache, stockLight, storedIcon, lightAppearance);
        bool storedDark = themer_spotlight_proof_cache_seed(
            storedCache, stockDark, storedIcon, darkAppearance);
        restoreStoredCache = storedLight && storedDark;
    }
    bool restored = restoreLight && restoreDark && restoreStoredCache;
    bool stateCleared = false;
    if (restored) {
        themer_spotlight_proof_clear_state();
        stateCleared = !r_is_objc_ptr(themer_spotlight_proof_state());
    }

    printf("[SPOTLIGHT_PROOF] verify verdict=%d pid=%d bundle=%s "
           "control=%s cache=0x%llx storedCache=0x%llx resolution=%s "
           "variant=%llu graph=%d currentIcon=0x%llx fresh=%d via=%s "
           "generation=%llu/%llu drifted=%d "
           "light=0x%llx/%d dark=0x%llx/%d "
           "controlChecked=%d controlStillStock=%d "
           "controlReadback=0x%llx/0x%llx rows=%d liveRows=%d "
           "rowImageMatches=%d restore=%d/%d storedRestore=%d "
           "stateCleared=%d total=%llums\n",
           verdict,
           currentPid,
           bundle,
           controlBundle[0] ? controlBundle : "-",
           (unsigned long long)resolvedCache,
           (unsigned long long)storedCache,
           cacheResolution,
           (unsigned long long)variant,
           graphKnown,
           (unsigned long long)currentIcon,
           currentIconFresh,
           currentSelector ?: "-",
           (unsigned long long)storedGeneration,
           (unsigned long long)currentGeneration,
           generationDrifted,
           (unsigned long long)lightReadback,
           lightMatch,
           (unsigned long long)darkReadback,
           darkMatch,
           controlChecked,
           controlStillStock,
           (unsigned long long)controlLightReadback,
           (unsigned long long)controlDarkReadback,
           materializedRows,
           liveRows,
           rowImageMatches,
           restoreLight,
           restoreDark,
           restoreStoredCache,
           stateCleared,
           (unsigned long long)((themer_now_us() - startUS) / 1000ULL));

    if (!restored || !stateCleared) {
        return ThemerSpotlightProofVerifyResultCleanupFailed;
    }
    return verdict;
}

static __attribute__((unused)) ThemerSpotlightProofVerifyResult
themer_spotlight_proof_verify_visible_legacy_and_cleanup_in_session(void)
{
    uint64_t totalStartUS = themer_now_us();
    uint64_t state = themer_spotlight_proof_state();
    if (!r_is_objc_ptr(state)) {
        printf("[SPOTLIGHT_PROOF] verify skipped reason=no-state\n");
        return ThemerSpotlightProofVerifyResultNoState;
    }

    // Enforce the same target process: a PID that moved on cannot trust the
    // retained pointers or the cache identity.
    uint64_t statePid = 0;
    bool pidKnown = themer_spotlight_proof_state_u64(state, "pid", &statePid);
    int currentPid = remote_call_current_pid();
    if (!pidKnown || statePid != (uint64_t)currentPid) {
        printf("[SPOTLIGHT_PROOF] verify host-mismatch statePid=%llu "
               "currentPid=%d\n",
               (unsigned long long)statePid,
               currentPid);
        themer_spotlight_proof_clear_state();
        return ThemerSpotlightProofVerifyResultHostStateMismatch;
    }

    char bundle[192] = {0};
    char controlBundle[192] = {0};
    uint64_t cache = themer_spotlight_proof_state_object(state, "cache");
    uint64_t icon = themer_spotlight_proof_state_object(state, "icon");
    uint64_t appearance = themer_spotlight_proof_state_object(
        state, "appearance");
    uint64_t expectedImage = themer_spotlight_proof_state_object(
        state, "expectedImage");
    uint64_t stockImage = themer_spotlight_proof_state_object(
        state, "stockImage");
    uint64_t variant = 0;
    bool variantKnown = themer_spotlight_proof_state_u64(
        state, "variant", &variant);
    uint64_t storedGeneration = 0;
    bool generationKnown = themer_spotlight_proof_state_u64(
        state, "imageGeneration", &storedGeneration);
    (void)themer_spotlight_proof_state_string(state, "bundle",
                                              bundle, sizeof(bundle));
    (void)themer_spotlight_proof_state_string(state, "controlBundle",
                                              controlBundle,
                                              sizeof(controlBundle));

    if (!r_is_objc_ptr(cache) || !r_is_objc_ptr(icon) ||
        !r_is_objc_ptr(appearance) || !r_is_objc_ptr(expectedImage)) {
        printf("[SPOTLIGHT_PROOF] verify host-mismatch "
               "reason=stale-state-objects bundle=%s cache=0x%llx "
               "icon=0x%llx appearance=0x%llx expected=0x%llx\n",
               bundle[0] ? bundle : "-",
               (unsigned long long)cache,
               (unsigned long long)icon,
               (unsigned long long)appearance,
               (unsigned long long)expectedImage);
        themer_spotlight_proof_clear_state();
        return ThemerSpotlightProofVerifyResultHostStateMismatch;
    }

    // Re-resolve the process-lifetime per-variant cache through the class
    // method when the runtime exposes it; otherwise keep the retained cache.
    uint64_t resolvedCache = cache;
    const char *resolution = "retained";
    if (variantKnown) {
        uint64_t cls = themer_lookup_class("SearchUIHomeScreenAppIconView");
        if (r_is_objc_ptr(cls) &&
            r_responds_main(cls, "cacheForVariant:")) {
            uint64_t fresh = r_msg2_main(cls, "cacheForVariant:",
                                         variant, 0, 0, 0);
            if (r_is_objc_ptr(fresh)) {
                resolvedCache = fresh;
                resolution = fresh == cache
                    ? "cacheForVariant:same"
                    : "cacheForVariant:different";
            } else {
                resolution = "cacheForVariant:unavailable";
            }
        } else {
            resolution = "cacheForVariant:unsupported";
        }
    }

    uint64_t currentGeneration = 0;
    bool currentGenerationKnown =
        r_responds_main(resolvedCache, "currentImageGenerationForIcon:");
    if (currentGenerationKnown) {
        currentGeneration = r_msg2_main(resolvedCache,
                                        "currentImageGenerationForIcon:",
                                        icon, 0, 0, 0);
    }
    bool generationDrifted = generationKnown && currentGenerationKnown &&
                             currentGeneration != storedGeneration;

    // Full optioned readback through the same cache-target verification used
    // at seed time. Only cached getters are exercised on the root cache;
    // render-path getters are limited to the already-seeded variant caches.
    ThemerSpotlightCacheTarget targets[THEMER_SPOTLIGHT_PROOF_TARGET_CAP] = {{0}};
    int targetCount = themer_spotlight_collect_cache_targets(
        resolvedCache, targets, THEMER_SPOTLIGHT_PROOF_TARGET_CAP);
    ThemerSpotlightCacheVerification verification =
        themer_spotlight_verify_cache_targets(
            targets, targetCount,
            expectedImage, icon, appearance, false);
    bool themedHit =
        verification.rootNativeMatches > 0 ||
        verification.backingNativeMatches > 0 ||
        verification.keyedMatches > 0 ||
        verification.rootOptionedMatches > 0 ||
        verification.rootRenderMatches > 0 ||
        verification.rootLegacyMatches > 0;
    bool readsHappened =
        verification.rootOptionedReads > 0 ||
        verification.rootRenderReads > 0 ||
        verification.rootLegacyReads > 0 ||
        verification.backingReads > 0;

    bool stockMatches = false;
    if (r_is_objc_ptr(stockImage)) {
        uint64_t readback = verification.rootOptionedImage;
        if (!r_is_objc_ptr(readback)) readback = verification.rootRenderImage;
        if (!r_is_objc_ptr(readback)) readback = verification.rootLegacyImage;
        stockMatches = themer_spotlight_images_match(stockImage, readback);
    }

    // The cache readback proves the static anchor retained the image. A live
    // selected row additionally proves SearchUI consumed that anchor after the
    // dismissal/reopen cycle rather than merely leaving an unreachable entry.
    int selectedRowsVisible = 0;
    bool selectedVisibleThemed = false;
    if (bundle[0]) {
        uint64_t views[THEMER_SPOTLIGHT_PROOF_VIEW_CAP] = {0};
        int viewCount = themer_spotlight_collect_searchui_views(
            views, THEMER_SPOTLIGHT_PROOF_VIEW_CAP);
        for (int i = 0; i < viewCount; i++) {
            uint64_t view = views[i];
            if (!themer_spotlight_view_is_live(view)) continue;
            uint64_t appIcon = themer_spotlight_app_icon_for_view(view,
                                                                  NULL, 0);
            if (!r_is_objc_ptr(appIcon)) continue;
            char rowBundle[192] = {0};
            if (!themer_spotlight_bundle_for_patch(view, appIcon,
                                                   rowBundle,
                                                   sizeof(rowBundle),
                                                   NULL, 0) ||
                strcmp(rowBundle, bundle) != 0) {
                continue;
            }
            selectedRowsVisible++;
            uint64_t carrier = themer_spotlight_image_carrier_for_view(view);
            uint64_t image = themer_spotlight_image_from_carrier(carrier);
            selectedVisibleThemed =
                themer_spotlight_images_match(expectedImage, image);
            break;
        }
    }

    // Optional negative control: if the untouched bundle still has a live
    // row, confirm its cache image still equals the stock CG captured at
    // seed time.
    uint64_t controlStockCG = 0;
    (void)themer_spotlight_proof_state_u64(state, "controlStockCG",
                                           &controlStockCG);
    int controlRowsVisible = 0;
    bool controlStillStock = false;
    if (controlBundle[0] && controlStockCG) {
        uint64_t views[THEMER_SPOTLIGHT_PROOF_VIEW_CAP] = {0};
        int viewCount = themer_spotlight_collect_searchui_views(
            views, THEMER_SPOTLIGHT_PROOF_VIEW_CAP);
        for (int i = 0; i < viewCount; i++) {
            uint64_t view = views[i];
            if (!themer_spotlight_view_is_live(view)) continue;
            uint64_t appIcon = themer_spotlight_app_icon_for_view(view,
                                                                  NULL, 0);
            if (!r_is_objc_ptr(appIcon)) continue;
            char rowBundle[192] = {0};
            if (!themer_spotlight_bundle_for_patch(view, appIcon,
                                                   rowBundle,
                                                   sizeof(rowBundle),
                                                   NULL, 0)) {
                continue;
            }
            if (strcmp(rowBundle, controlBundle) != 0) continue;
            controlRowsVisible++;
            uint64_t carrier = themer_spotlight_image_carrier_for_view(view);
            uint64_t image = themer_spotlight_image_from_carrier(carrier);
            if (!r_is_objc_ptr(image)) {
                char controlCacheSource[128] = {0};
                uint64_t controlCache = themer_spotlight_find_icon_cache(
                    view, carrier, appIcon,
                    controlCacheSource, sizeof(controlCacheSource));
                image = themer_spotlight_cached_image(controlCache,
                                                      appIcon, NULL);
            }
            if (r_is_objc_ptr(image) &&
                r_responds_main(image, "CGImage")) {
                uint64_t cg = r_msg2_main(image, "CGImage", 0, 0, 0, 0);
                controlStillStock = (cg == controlStockCG);
            }
            break;
        }
    }
    uint64_t verifyEndUS = themer_now_us();

    ThemerSpotlightProofVerifyResult verdict;
    if (themedHit && selectedRowsVisible > 0 && selectedVisibleThemed) {
        verdict = ThemerSpotlightProofVerifyResultThemedHit;
    } else if (themedHit && selectedRowsVisible == 0) {
        verdict = ThemerSpotlightProofVerifyResultInconclusive;
    } else if (themedHit || readsHappened) {
        verdict = ThemerSpotlightProofVerifyResultStockOrMiss;
    } else {
        verdict = ThemerSpotlightProofVerifyResultInconclusive;
    }

    printf("[SPOTLIGHT_PROOF] verify verdict=%d bundle=%s cache=0x%llx "
           "resolution=%s variantKnown=%d variant=%llu "
           "generationStored=%llu generationCurrent=%llu "
           "generationDrifted=%d rootNative=%d backingNative=%d keyed=%d "
           "rootOptioned=%d/%d rootRender=%d/%d rootLegacy=%d/%d "
           "stockMatches=%d selectedRows=%d selectedVisibleThemed=%d "
           "control=%s controlRows=%d controlStillStock=%d "
           "verify=%llums total=%llums\n",
           verdict,
           bundle[0] ? bundle : "-",
           (unsigned long long)resolvedCache,
           resolution,
           variantKnown,
           (unsigned long long)variant,
           (unsigned long long)storedGeneration,
           (unsigned long long)currentGeneration,
           generationDrifted,
           verification.rootNativeMatches,
           verification.backingNativeMatches,
           verification.keyedMatches,
           verification.rootOptionedReads,
           verification.rootOptionedMatches,
           verification.rootRenderReads,
           verification.rootRenderMatches,
           verification.rootLegacyReads,
           verification.rootLegacyMatches,
           stockMatches,
           selectedRowsVisible,
           selectedVisibleThemed,
           controlBundle[0] ? controlBundle : "-",
           controlRowsVisible,
           controlStillStock,
           (unsigned long long)((verifyEndUS - totalStartUS) / 1000ULL),
           (unsigned long long)((verifyEndUS - totalStartUS) / 1000ULL));

    // Cleanup: targeted stock overwrite of only the proof bundle's cache
    // identity, then release the associated state. Never a broad cache
    // clear. When no stock image was captured, the process-lifetime cache
    // keeps the themed image until the process exits (a respring); that is
    // the safest available action without generation bumps or broad clears.
    uint64_t cleanupStartUS = themer_now_us();
    int overwriteCalls = 0;
    bool restored = themer_spotlight_proof_overwrite_cache(
        resolvedCache, stockImage, icon, appearance,
        currentGenerationKnown ? currentGeneration : storedGeneration,
        &overwriteCalls);
    bool stateCleared = false;
    if (restored) {
        themer_spotlight_proof_clear_state();
        stateCleared = !r_is_objc_ptr(themer_spotlight_proof_state());
    }
    uint64_t cleanupEndUS = themer_now_us();
    printf("[SPOTLIGHT_PROOF] cleanup bundle=%s action=stock-overwrite "
           "overwriteCalls=%d restored=%d stateCleared=%d cleanup=%llums\n",
           bundle[0] ? bundle : "-",
           overwriteCalls,
           restored,
           stateCleared,
           (unsigned long long)((cleanupEndUS - cleanupStartUS) / 1000ULL));
    if (!restored || !stateCleared) {
        return ThemerSpotlightProofVerifyResultCleanupFailed;
    }
    return verdict;
}

// =====================================================================
// Spotlight IconServices-only object lab (experimental).
//
// Determines empirically which IconServices object/descriptor path inside
// the Spotlight UI host is actually consumed when Spotlight creates a
// result icon. IconServices objects (ISBundleIdentifierIcon, ISImageDescriptor,
// ISIconManager, ISIconCache image caches, IFImage) are the ONLY mutation
// targets. There are no SearchUI cache writes, no view traversal/painting/
// hooks, and no model/provider/object isa grafts. Exactly one reversible
// candidate is exercised per run; run state is process-resident under
// NSProcessInfo key "cndSpotlightIconServicesLabStateV1" so a later
// same-PID session can verify persistence and perform targeted restore.
// The production themer_seed_iconservices_cache combined sequence is never
// invoked from this lab.
// =====================================================================

#define THEMER_ICONSERVICES_LAB_STATE_KEY "cndSpotlightIconServicesLabStateV1"
#define THEMER_ICONSERVICES_LAB_TRACE_KEY "cndSpotlightIconServicesTraceV1"
#define THEMER_ICONSERVICES_LAB_GENERATION_GUARD_KEY \
    "cndSpotlightIconServicesRecordIdentifiersClassGuardV4"
#define THEMER_ICONSERVICES_LAB_GENERATION_ENABLED 0
#define THEMER_ICONSERVICES_LAB_EXTENDED_PROBES_ENABLED 0
#define THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP 8
#define THEMER_ICONSERVICES_LAB_METHOD_CAP 96
#define THEMER_ICONSERVICES_LAB_IVAR_CAP 48
#define THEMER_ICONSERVICES_LAB_PROPERTY_CAP 48
#define THEMER_ICONSERVICES_LAB_TRACE_TEXT_CAP 4096
#define THEMER_STOCK68_FINGERPRINT_CAP 32768
#define THEMER_ICONSERVICES_LAB_PENDING_STORE_UUID_KEY \
    @"CNDSpotlightPendingStoreUUIDV1"
#define THEMER_ICONSERVICES_LAB_PENDING_CACHE_TARGET_KEY \
    @"CNDSpotlightPendingCacheTargetV1"
#define THEMER_ICONSERVICES_LAB_PENDING_CACHE_BACKUP_KEY \
    @"CNDSpotlightPendingCacheBackupV1"
#define THEMER_ICONSERVICES_LAB_PENDING_CACHE_TEMP_KEY \
    @"CNDSpotlightPendingCacheTempV1"
#define THEMER_ICONSERVICES_LAB_STOCK68_UUID_KEY \
    @"CNDSpotlightStock68UUIDV1"
#define THEMER_ICONSERVICES_LAB_STOCK68_TOKEN_KEY \
    @"CNDSpotlightStock68TokenV1"
#define THEMER_ICONSERVICES_LAB_STOCK68_PID_KEY \
    @"CNDSpotlightStock68PIDV1"
#define THEMER_ICONSERVICES_LAB_STOCK68_PATH_KEY \
    @"CNDSpotlightStock68PathV1"
#define THEMER_ICONSERVICES_LAB_STOCK68_BUNDLE_KEY \
    @"CNDSpotlightStock68BundleV1"
