#define THEMER_STOCK68_V2_TOKEN_KEY @"CNDSpotlightStock68TokenV2"
#define THEMER_STOCK68_V2_PID_KEY @"CNDSpotlightStock68PIDV2"
#define THEMER_STOCK68_V2_PATH_KEY @"CNDSpotlightStock68PathV2"
#define THEMER_STOCK68_V2_BUNDLE_KEY @"CNDSpotlightStock68BundleV2"
#define THEMER_STOCK68_V2_FINGERPRINT_KEY @"CNDSpotlightStock68FingerprintV2"
#define THEMER_STOCK68_V2_DIGEST_KEY @"CNDSpotlightStock68NamedDigestV2"
#define THEMER_STOCK68_V2_FILE_SIZE_KEY @"CNDSpotlightStock68FileSizeV2"
#define THEMER_STOCK68_IDENTITY_RETIREMENT_KEY @"CNDSpotlightStock68IdentityRetirementV1"
