    @"CNDSpotlightStock68AdoptionCertificateV1"
// Keep the legacy V1 value available to old journal readers and diagnostics;
// new transactions are written as V2 under the same defaults key.
#define THEMER_STOCK68_JOURNAL_VERSION 1
#define THEMER_STOCK68_JOURNAL_V2_VERSION 2
#define THEMER_STOCK68_JOURNAL_PREPARED_PHASE @"prepared"
#define THEMER_STOCK68_JOURNAL_NO_DISPATCH_PHASE @"no-dispatch-proven"
#define THEMER_STOCK68_JOURNAL_DISPATCH_PHASE @"dispatch-possible"
#define THEMER_ICONSERVICES_LAB_DATA_CAPTURE_CAP (1U << 18)
#define THEMER_ICONSERVICES_LAB_STOCK_COMPARE_DATA_CAP (1U << 20)
#define THEMER_ICONSERVICES_LAB_INDEX_CAPTURE_CAP (1U << 23)
#define THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP 4096U

static NSData *themer_iconservices_lab_scaled_png_data(NSData *bytes,
                                                       double pointWidth,
                                                       double pointHeight,
                                                       double scale)
{
    if (![bytes isKindOfClass:NSData.class] || bytes.length == 0 ||
        pointWidth < 1.0 || pointHeight < 1.0 ||
        scale < 1.0 || scale > 4.0) {
        return nil;
    }
    @autoreleasepool {
        UIImage *source = [UIImage imageWithData:bytes];
        if (!source || !source.CGImage) return nil;
        CGSize pixels = CGSizeMake(
            (CGFloat)(pointWidth * scale),
            (CGFloat)(pointHeight * scale));
        if (pixels.width < 1.0 || pixels.height < 1.0 ||
            pixels.width > 1024.0 || pixels.height > 1024.0) {
            return nil;
        }
        UIGraphicsImageRendererFormat *format =
            [UIGraphicsImageRendererFormat defaultFormat];
        format.scale = 1.0;
        format.opaque = NO;
        UIGraphicsImageRenderer *renderer =
            [[UIGraphicsImageRenderer alloc] initWithSize:pixels format:format];
        UIImage *scaled = [renderer imageWithActions:
            ^(UIGraphicsImageRendererContext *context) {
                (void)context;
                [source drawInRect:CGRectMake(0.0, 0.0,
                                              pixels.width, pixels.height)];
            }];
        NSData *png = UIImagePNGRepresentation(scaled);
        return png.length > 0 && png.length <= kThemerMaxPngBytes ? png : nil;
    }
}

static NSDictionary<NSString *, NSData *> *
themer_iconservices_lab_scaled_theme_data(
    NSDictionary<NSString *, NSData *> *normalized,
    const char *bundle,
    double pointWidth,
    double pointHeight,
    double scale)
{
    if (!normalized || !bundle || !bundle[0]) return nil;
    NSString *key = [NSString stringWithUTF8String:bundle];
    NSString *matchedKey = nil;
    NSData *bytes = themer_theme_data_for_key(normalized, key, &matchedKey);
    NSData *scaled = themer_iconservices_lab_scaled_png_data(
        bytes, pointWidth, pointHeight, scale);
    if (!scaled) return nil;
    printf("[ICONSERVICES_LAB] themed-png bundle=%s matchedKey=%s "
           "sourceBytes=%lu scaledBytes=%lu points=%.1fx%.1f scale=%.2f\n",
           bundle,
           matchedKey.UTF8String ?: "-",
           (unsigned long)bytes.length,
           (unsigned long)scaled.length,
           pointWidth,
           pointHeight,
           scale);
    return @{ key: scaled };
}

const char *themer_spotlight_iconservices_candidate_name(
    ThemerSpotlightIconServicesCandidate candidate)
{
    switch (candidate) {
        case ThemerSpotlightIconServicesCandidateLocalExistingDescriptor:
            return "local-named-spotlight";
        case ThemerSpotlightIconServicesCandidateCanonicalExistingDescriptor:
            return "canonical-named-spotlight";
        case ThemerSpotlightIconServicesCandidateCanonicalFactoryClone:
            return "disabled-factory-clone";
        case ThemerSpotlightIconServicesCandidateCanonicalInitClone:
            return "disabled-init-clone";
        case ThemerSpotlightIconServicesCandidateCanonicalBagSwap:
            return "canonical-retained-cg-bag-clone";
        case ThemerSpotlightIconServicesCandidateCanonicalDescriptorClear:
            return "canonical-descriptor-clear";
        case ThemerSpotlightIconServicesCandidateCanonicalIconInvalidator:
            return "canonical-icon-invalidator";
        case ThemerSpotlightIconServicesCandidateCanonicalCacheClear:
            return "canonical-cache-clear";
        case ThemerSpotlightIconServicesCandidateManagerCache:
            return "manager-cache";
        case ThemerSpotlightIconServicesCandidateCanonicalMixedBag:
            return "canonical-stock-preserved-themed68-store";
        default:
            return "unknown";
    }
}

static const char *themer_iconservices_lab_candidate_risk(int candidate)
{
    switch (candidate) {
        case ThemerSpotlightIconServicesCandidateLocalExistingDescriptor:
        case ThemerSpotlightIconServicesCandidateCanonicalExistingDescriptor:
        case ThemerSpotlightIconServicesCandidateCanonicalFactoryClone:
        case ThemerSpotlightIconServicesCandidateCanonicalInitClone:
            return "low";
        case ThemerSpotlightIconServicesCandidateCanonicalBagSwap:
        case ThemerSpotlightIconServicesCandidateCanonicalMixedBag:
            return "medium";
        default:
            return "high";
    }
}

static uint64_t themer_iconservices_lab_state(void)
{
    return themer_spotlight_associated_process_object(
        THEMER_ICONSERVICES_LAB_STATE_KEY);
}

static bool themer_iconservices_lab_commit_state(uint64_t state)
{
    return themer_spotlight_commit_process_object(
        THEMER_ICONSERVICES_LAB_STATE_KEY, state);
}

static void themer_iconservices_lab_clear_state(void)
{
    uint64_t processInfo = themer_spotlight_process_info();
    uint64_t key = r_sel(THEMER_ICONSERVICES_LAB_STATE_KEY);
    if (r_is_objc_ptr(processInfo) && key) {
        // objc_setAssociatedObject with a nil object removes the
        // association and releases the previously retained value.
        r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                     processInfo, key, 0, 1, 0, 0, 0, 0);
    }
}

static uint64_t themer_iconservices_lab_trace_state(void)
{
    return themer_spotlight_associated_process_object(
        THEMER_ICONSERVICES_LAB_TRACE_KEY);
}

static bool themer_iconservices_lab_trace_commit(uint64_t state)
{
    return themer_spotlight_commit_process_object(
        THEMER_ICONSERVICES_LAB_TRACE_KEY, state);
}

static void themer_iconservices_lab_trace_clear(void)
{
    uint64_t processInfo = themer_spotlight_process_info();
    uint64_t key = r_sel(THEMER_ICONSERVICES_LAB_TRACE_KEY);
    if (r_is_objc_ptr(processInfo) && key) {
        r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                     processInfo, key, 0, 1, 0, 0, 0, 0);
    }
}

static uint64_t themer_stock68_materialization_state(void)
{
    return themer_spotlight_associated_process_object(
        THEMER_STOCK68_MATERIALIZATION_STATE_KEY);
}

static void themer_stock68_prearm_log(const char *phase,
                                      const char *operation,
                                      bool status)
{
    RemoteCallDebugSnapshot snapshot = {0};
    bool copied = remote_call_copy_debug_snapshot(&snapshot);
    printf("[ICONSERVICES_MATERIALIZE] prearm %s phase=%s status=%d "
           "transport=%d snapshot=%d pid=%d stable=%llu failures=%llu "
           "ioFailures=%llu lastStableCall=%s lastStableFailure=%s "
           "reason=%s\n",
           phase ?: "after",
           operation ?: "-",
           status,
           remote_call_current_success(),
           copied,
           snapshot.pid,
           (unsigned long long)snapshot.stableCalls,
           (unsigned long long)snapshot.stableFailures,
           (unsigned long long)snapshot.ioFailures,
           copied ? snapshot.lastStableCall : "-",
           copied ? snapshot.lastStableFailure : "-",
           copied ? snapshot.lastStableFailureReason : "-");
}

static void themer_stock68_prearm_before(const char *operation)
{
    printf("[ICONSERVICES_MATERIALIZE] prearm before operation=%s\n",
           operation ?: "-");
}

static uint64_t themer_stock68_prearm_number(const char *field,
                                             unsigned long long value)
{
    char operation[128] = {0};
    snprintf(operation, sizeof(operation), "NSNumber-create:%s",
             field ?: "-");
    themer_stock68_prearm_before(operation);
    uint64_t number = themer_spotlight_proof_number(value);
    themer_stock68_prearm_log("after", operation,
                              r_is_objc_ptr(number) &&
                              remote_call_current_success());
    return number;
}

static bool themer_stock68_prearm_set_field(uint64_t state,
                                            const char *field,
                                            uint64_t object)
{
    if (!r_is_objc_ptr(state) || !field || !field[0] ||
        !r_is_objc_ptr(object) || !remote_call_current_success()) {
        return false;
    }
    char operation[160] = {0};
    snprintf(operation, sizeof(operation), "field:%s", field);

    char keyOperation[192] = {0};
    snprintf(keyOperation, sizeof(keyOperation), "key-create:%s", field);
    themer_stock68_prearm_before(keyOperation);
    uint64_t key = r_nsstr_retained(field);
    bool keyReady = r_is_objc_ptr(key) && remote_call_current_success();
    themer_stock68_prearm_log("after", keyOperation, keyReady);
    if (!keyReady) return false;

    char setOperation[192] = {0};
    snprintf(setOperation, sizeof(setOperation), "setObject:%s", field);
    themer_stock68_prearm_before(setOperation);
    r_msg2_main(state, "setObject:forKey:", object, key, 0, 0);
    bool setOK = remote_call_current_success();
    themer_stock68_prearm_log("after", setOperation, setOK);
    if (!setOK) return false;

    char readOperation[192] = {0};
    snprintf(readOperation, sizeof(readOperation), "readback:%s", field);
    themer_stock68_prearm_before(readOperation);
    uint64_t readback = r_msg2_main(state, "objectForKey:",
                                    key, 0, 0, 0);
    bool readOK = remote_call_current_success() && readback == object;
    themer_stock68_prearm_log("after", readOperation, readOK);
    if (!remote_call_current_success()) return false;

    char releaseOperation[192] = {0};
    snprintf(releaseOperation, sizeof(releaseOperation), "key-release:%s",
             field);
    themer_stock68_prearm_before(releaseOperation);
    r_msg2(key, "release", 0, 0, 0, 0);
    bool releaseOK = remote_call_current_success();
    themer_stock68_prearm_log("after", releaseOperation, releaseOK);
    return readOK && releaseOK;
}

static bool themer_stock68_prearm_set_string(uint64_t state,
                                             const char *field,
                                             const char *value)
{
    if (!value || !value[0] || !field || !field[0] ||
        !remote_call_current_success()) {
        return false;
    }
    char operation[192] = {0};
    snprintf(operation, sizeof(operation), "string-create:%s", field);
    themer_stock68_prearm_before(operation);
    uint64_t string = r_nsstr_retained(value);
    bool stringReady = r_is_objc_ptr(string) && remote_call_current_success();
    themer_stock68_prearm_log("after", operation, stringReady);
    if (!stringReady) return false;

    bool setOK = themer_stock68_prearm_set_field(state, field, string);
    if (!remote_call_current_success()) return false;
    snprintf(operation, sizeof(operation), "string-release:%s", field);
    themer_stock68_prearm_before(operation);
    r_msg2(string, "release", 0, 0, 0, 0);
    bool releaseOK = remote_call_current_success();
    themer_stock68_prearm_log("after", operation, releaseOK);
    return setOK && releaseOK;
}

static bool themer_stock68_materialization_commit_state(uint64_t state)
{
    if (!r_is_objc_ptr(state) || !remote_call_current_success()) return false;
    themer_stock68_prearm_before("process-info-get");
    uint64_t processInfo = themer_spotlight_process_info();
    bool processInfoReady = r_is_objc_ptr(processInfo) &&
        remote_call_current_success();
    themer_stock68_prearm_log("after", "process-info-get", processInfoReady);
    if (!processInfoReady) return false;

    themer_stock68_prearm_before("association-key-create");
    uint64_t key = r_sel(THEMER_STOCK68_MATERIALIZATION_STATE_KEY);
    bool keyReady = key && remote_call_current_success();
    themer_stock68_prearm_log("after", "association-key-create", keyReady);
    if (!keyReady) return false;

    themer_stock68_prearm_before("association-set");
    r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                 processInfo, key, state, 1, 0, 0, 0, 0);
    bool setOK = remote_call_current_success();
    themer_stock68_prearm_log("after", "association-set", setOK);
    if (!setOK) return false;

    themer_stock68_prearm_before("association-get");
    uint64_t readback = themer_spotlight_associated_process_object(
        THEMER_STOCK68_MATERIALIZATION_STATE_KEY);
    bool readOK = remote_call_current_success() && readback == state;
    themer_stock68_prearm_log("after", "association-get", readOK);
    return readOK;
}

static bool themer_stock68_materialization_clear_state(void)
{
    uint64_t processInfo = themer_spotlight_process_info();
    uint64_t key = r_sel(THEMER_STOCK68_MATERIALIZATION_STATE_KEY);
    if (!r_is_objc_ptr(processInfo) || !key ||
        !remote_call_current_success()) {
        return false;
    }
    r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                 processInfo, key, 0, 1, 0, 0, 0, 0);
    if (!remote_call_current_success()) return false;
    uint64_t readback = themer_stock68_materialization_state();
    return remote_call_current_success() && readback == 0;
}

// The generation phase remains unchanged. Store writes have an independent,
// strictly monotonic transaction inside the same atomic defaults value.
static id themer_stock68_identity_canonical(id value);
static bool themer_stock68_identity_values_equal(id a, id b);

static NSString *themer_stock68_registration_hash(NSData *data)
{
    if (![data isKindOfClass:NSData.class] || data.length > UINT32_MAX) return nil;
    unsigned char digest[CC_SHA256_DIGEST_LENGTH];
    CC_SHA256(data.bytes, (CC_LONG)data.length, digest);
    char text[65] = {0};
    for (size_t i = 0; i < sizeof(digest); i++) snprintf(text + i * 2, 3, "%02x", digest[i]);
    return @(text);
}

static NSString *themer_stock68_registration_raw_hash(id value)
{
    if (!value) return nil;
    NSData *data = [NSPropertyListSerialization dataWithPropertyList:
        themer_stock68_identity_canonical(value) format:NSPropertyListBinaryFormat_v1_0
        options:0 error:NULL];
    return data ? themer_stock68_registration_hash(data) : nil;
}

static bool themer_stock68_registration_integer(id value, uint64_t *out)
{
    if (![value isKindOfClass:NSNumber.class] ||
        CFGetTypeID((__bridge CFTypeRef)value) == CFBooleanGetTypeID() ||
        strchr("cCsSiIlLqQ", [value objCType][0]) == NULL ||
        [value compare:@0] == NSOrderedAscending) return false;
    if (out) *out = [value unsignedLongLongValue];
    return true;
}

static int themer_stock68_registration_phase(id value)
{
    if (![value isKindOfClass:NSString.class]) return -1;
    NSArray *phases = @[@"prepared", @"write-possible", @"write-verified",
        @"cleanup-required", @"cleanup-verified"];
    NSUInteger index = [phases indexOfObject:value];
    return index == NSNotFound ? -1 : (int)index;
}

static bool themer_stock68_registration_valid(id value, NSDictionary *journal)
{
    if (![value isKindOfClass:NSDictionary.class]) return false;
    NSDictionary *r = value;
    NSSet *keys = [NSSet setWithArray:@[@"version", @"phase", @"transaction", @"pid", @"proc", @"task",
        @"target", @"fingerprint", @"namedDigest", @"generatedDigest", @"originalDictionary",
        @"baselineFingerprint", @"dictionaryCount", @"keyCount", @"actualKeyCount", @"entryCount",
        @"uuid", @"cachePath", @"path", @"data", @"dataSize", @"dataSHA256", @"token", @"tokenLength",
        @"tokenSHA256", @"recordBlob", @"recordBlobSHA256", @"requestCount", @"decodeComplete",
        @"ownershipVerified", @"constructorVerified", @"reconstructionVerified", @"prewriteFileAbsent",
        @"prewriteHealthyNil", @"width", @"height", @"scale", @"pixelWidth", @"pixelHeight"]];
    if (![[NSSet setWithArray:r.allKeys] isEqual:keys] ||
        ![journal[@"version"] isEqual:@2] || ![journal[@"phase"] isEqual:@"dispatch-possible"] ||
        themer_stock68_registration_phase(r[@"phase"]) < 0) return false;
    for (NSString *key in @[@"version", @"pid", @"proc", @"task", @"originalDictionary", @"dictionaryCount",
            @"keyCount", @"actualKeyCount", @"entryCount", @"dataSize", @"tokenLength", @"requestCount",
            @"width", @"height", @"scale", @"pixelWidth", @"pixelHeight"])
        if (!themer_stock68_registration_integer(r[key], NULL)) return false;
    for (NSString *key in @[@"decodeComplete", @"ownershipVerified", @"constructorVerified",
            @"reconstructionVerified", @"prewriteFileAbsent", @"prewriteHealthyNil"])
        if (CFGetTypeID((__bridge CFTypeRef)r[key]) != CFBooleanGetTypeID() || ![r[key] boolValue]) return false;
    for (NSString *key in @[@"target", @"fingerprint", @"namedDigest", @"generatedDigest"])
        if (![r[key] isKindOfClass:NSString.class] || ![r[key] isEqual:journal[key]]) return false;
    for (NSString *key in @[@"transaction", @"uuid", @"cachePath", @"path", @"baselineFingerprint"])
        if (![r[key] isKindOfClass:NSString.class] || ![r[key] length] ||
            [r[key] lengthOfBytesUsingEncoding:NSUTF8StringEncoding] != strlen([r[key] UTF8String])) return false;
    // This is the physical path captured by realpath and bound to storeURL.
    // stringByStandardizingPath can rewrite an existing /private/var path to
    // /var, so it cannot validate this representation. Check syntax without
    // consulting the filesystem; the live store preflight verifies identity.
    NSArray<NSString *> *cacheComponents = [r[@"cachePath"] componentsSeparatedByString:@"/"];
    for (NSUInteger i = 1; i < cacheComponents.count; i++) {
        NSString *component = cacheComponents[i];
        if (!component.length || [component isEqual:@"."] || [component isEqual:@".."]) return false;
    }
    NSUUID *transaction = [[NSUUID alloc] initWithUUIDString:r[@"transaction"]];
    NSUUID *uuid = [[NSUUID alloc] initWithUUIDString:r[@"uuid"]];
    NSString *expectedPath = [r[@"cachePath"] stringByAppendingPathComponent:
        [r[@"uuid"] stringByAppendingString:@".isdata"]];
    NSData *data = r[@"data"], *token = r[@"token"], *blob = r[@"recordBlob"];
    if (![data isKindOfClass:NSData.class] || ![token isKindOfClass:NSData.class] ||
        ![blob isKindOfClass:NSData.class] || !data.length || data.length > (1U << 20) ||
        token.length != 40 || blob.length != 36) return false;
    uint8_t uuidBytes[16];
    [uuid getUUIDBytes:uuidBytes];
    const uint8_t *b = blob.bytes;
    const uint8_t expectedHead[12] = {0,0,0,0,0x68,0x0f,0,0,8,0,0,0};
    const uint8_t expectedTail[8] = {0x68,0x0f,0,0,0,0,0,0};
    uint64_t proc = [r[@"proc"] unsignedLongLongValue], task = [r[@"task"] unsignedLongLongValue];
    uint64_t original = [r[@"originalDictionary"] unsignedLongLongValue];
    NSString *baseline = [NSString stringWithFormat:
        @"captured=1;dictionary=0x%016llx;dictionaryCount=0;dictionaryCountKnown=1;keyCount=0;keyArray=1;keyCountKnown=1;keysTruncated=0",
        (unsigned long long)original];
    return transaction && uuid && [transaction.UUIDString isEqual:r[@"transaction"]] &&
        [uuid.UUIDString isEqual:r[@"uuid"]] && [r[@"version"] isEqual:@1] &&
        [r[@"pid"] isEqual:journal[@"pid"]] && proc != UINT64_MAX && task != UINT64_MAX &&
        (proc >> 48) == UINT16_MAX && (task >> 48) == UINT16_MAX && r_is_objc_ptr(original) &&
        [r[@"baselineFingerprint"] isEqual:baseline] &&
        [r[@"dictionaryCount"] isEqual:@0] && [r[@"keyCount"] isEqual:@0] &&
        [r[@"actualKeyCount"] isEqual:@0] && [r[@"entryCount"] isEqual:@0] &&
        [r[@"requestCount"] isEqual:@1] && [r[@"width"] isEqual:@68] && [r[@"height"] isEqual:@68] &&
        [r[@"scale"] isEqual:@3] && [r[@"pixelWidth"] isEqual:@204] && [r[@"pixelHeight"] isEqual:@204] &&
        [r[@"cachePath"] hasPrefix:@"/private/var/"] && [r[@"cachePath"] length] < 400 &&
        [r[@"path"] isEqual:expectedPath] && [r[@"dataSize"] isEqual:@(data.length)] &&
        [r[@"tokenLength"] isEqual:@40] &&
        [r[@"dataSHA256"] isEqual:themer_stock68_registration_hash(data)] &&
        [r[@"tokenSHA256"] isEqual:themer_stock68_registration_hash(token)] &&
        [r[@"recordBlobSHA256"] isEqual:themer_stock68_registration_hash(blob)] &&
        memcmp(b, expectedHead, 12) == 0 && memcmp(b + 28, expectedTail, 8) == 0 &&
        memcmp(b + 12, uuidBytes, 16) == 0 && memcmp(uuidBytes, token.bytes, 16) == 0;
}

static bool themer_stock68_local_journal_has_any_key(void)
{
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    return [defaults objectForKey:THEMER_STOCK68_JOURNAL_KEY] != nil;
}

static NSDictionary *themer_stock68_local_journal_dictionary(void)
{
    id value = [NSUserDefaults.standardUserDefaults
        objectForKey:THEMER_STOCK68_JOURNAL_KEY];
    if (![value isKindOfClass:NSDictionary.class]) return nil;
    NSDictionary *journal = value;
    id version = journal[@"version"];
    id pid = journal[@"pid"];
    id target = journal[@"target"];
    id fingerprint = journal[@"fingerprint"];
    id namedDigest = journal[@"namedDigest"];
    id generatedDigest = journal[@"generatedDigest"];
    id issued = journal[@"issued"];
    bool versionInteger = [version isKindOfClass:NSNumber.class] &&
        [version doubleValue] == (double)[version longLongValue];
    long long versionValue = versionInteger ? [version longLongValue] : 0;
    bool pidInteger = [pid isKindOfClass:NSNumber.class] &&
        [pid doubleValue] == (double)[pid longLongValue];
    bool fingerprintHex = [fingerprint isKindOfClass:NSString.class] &&
        strlen([fingerprint UTF8String] ?: "") == 64;
    if (fingerprintHex) {
        const char *hex = [fingerprint UTF8String];
        for (size_t i = 0; i < 64; i++) {
            char c = hex[i];
            if (!((c >= '0' && c <= '9') ||
                  (c >= 'a' && c <= 'f') ||
                  (c >= 'A' && c <= 'F'))) {
                fingerprintHex = false;
                break;
            }
        }
    }
    bool issuedBoolean = [issued isKindOfClass:NSNumber.class] &&
        ([issued isEqual:@YES] || [issued isEqual:@NO]);
    bool valid = versionInteger &&
        (versionValue == THEMER_STOCK68_JOURNAL_VERSION ||
         versionValue == 2) &&
        pidInteger && [pid longLongValue] > 0 && [pid longLongValue] <= INT_MAX &&
        [target isKindOfClass:NSString.class] && [target length] > 0 &&
        fingerprintHex &&
        [namedDigest isKindOfClass:NSString.class] && [namedDigest length] > 0 &&
        [generatedDigest isKindOfClass:NSString.class] &&
        [generatedDigest length] > 0 &&
        issuedBoolean;
    if (valid && versionValue == 2) {
        id phase = journal[@"phase"];
        id dispatchPossible = journal[@"dispatchPossible"];
        id transactionBound = journal[@"transactionBound"];
        bool phaseKnown = [phase isKindOfClass:NSString.class] &&
            ([phase isEqualToString:@"prepared"] ||
             [phase isEqualToString:@"no-dispatch-proven"] ||
             [phase isEqualToString:@"dispatch-possible"]);
        bool dispatchBoolean = [dispatchPossible isKindOfClass:NSNumber.class] &&
            ([dispatchPossible isEqual:@YES] || [dispatchPossible isEqual:@NO]);
        bool transactionBoolean =
            ([transactionBound isKindOfClass:NSNumber.class] &&
             ([transactionBound isEqual:@YES] ||
              [transactionBound isEqual:@NO]));
        bool phaseConsistent = phaseKnown && dispatchBoolean &&
            (([phase isEqualToString:@"dispatch-possible"] &&
              [dispatchPossible boolValue] && [issued boolValue]) ||
             (![phase isEqualToString:@"dispatch-possible"] &&
              ![dispatchPossible boolValue] && ![issued boolValue]));
        bool transactionConsistent = phaseKnown && transactionBoolean &&
            ([phase isEqualToString:@"prepared"]
                ? ![transactionBound boolValue] : [transactionBound boolValue]);
        valid = valid && transactionConsistent && phaseConsistent;
    }
    if (valid && journal[@"storeRegistration"])
        valid = themer_stock68_registration_valid(journal[@"storeRegistration"], journal);
    return valid ? journal : nil;
}

static bool themer_stock68_local_journal_persist(
    const char *targetBundle,
    const char *themeFingerprint,
    const char *namedDigest,
    const char *generatedDigest)
{
    if (!targetBundle || !targetBundle[0] || !themeFingerprint ||
        strlen(themeFingerprint) != 64 || !namedDigest || !namedDigest[0] ||
        !generatedDigest || !generatedDigest[0]) {
        return false;
    }
    NSString *target = [NSString stringWithUTF8String:targetBundle];
    NSString *fingerprint = [NSString stringWithUTF8String:themeFingerprint];
    NSString *named = [NSString stringWithUTF8String:namedDigest];
    NSString *generated = [NSString stringWithUTF8String:generatedDigest];
    NSNumber *pid = @(remote_call_current_pid());
    if (!target || !fingerprint || !named || !generated || !pid ||
        target.length == 0 || fingerprint.length != 64 || named.length == 0 ||
        generated.length == 0 || remote_call_current_pid() <= 0) {
        return false;
    }
    NSDictionary *journal = @{
        @"version": @2,
        @"pid": pid,
        @"target": target,
        @"fingerprint": fingerprint,
        @"namedDigest": named,
        @"generatedDigest": generated,
        @"issued": @NO,
        @"phase": @"prepared",
        @"dispatchPossible": @NO,
        @"transactionBound": @NO,
    };
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    [defaults setObject:journal forKey:THEMER_STOCK68_JOURNAL_KEY];
    if (![defaults synchronize]) {
        // The single record remains a fail-closed marker even when the
        // immediate synchronize acknowledgement is unavailable.
        return false;
    }
    bool persisted = [themer_stock68_local_journal_dictionary()
                         isEqual:journal];
    printf("[ICONSERVICES_MATERIALIZE] journal persist pid=%d target=%s "
           "fingerprint=%.16s named=%.16s generated=%.16s verified=%d\n",
           remote_call_current_pid(), targetBundle, themeFingerprint,
           namedDigest, generatedDigest, persisted);
    return persisted;
}

// This is the only durable operation that arms the generation uncertainty
// bit.  It is deliberately called by the materializer immediately before the
// existing generationInvoked boundary, after all remote request preflight has
// completed. A failed synchronize/readback prevents helper dispatch; the
// best-effort prepared-marker rollback below may itself fail to persist.
static bool themer_stock68_local_journal_mark_dispatch_possible(void)
{
    NSDictionary *journal = themer_stock68_local_journal_dictionary();
    if (!journal || [journal[@"version"] longLongValue] != 2 ||
        [journal[@"pid"] intValue] <= 0 ||
        [journal[@"pid"] intValue] != remote_call_current_pid() ||
        [journal[@"dispatchPossible"] boolValue] ||
        [journal[@"issued"] boolValue]) {
        return false;
    }
    NSMutableDictionary *updated = [journal mutableCopy];
    if (!updated) return false;
    updated[@"phase"] = @"dispatch-possible";
    updated[@"dispatchPossible"] = @YES;
    updated[@"transactionBound"] = @YES;
    updated[@"issued"] = @YES;
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    [defaults setObject:updated forKey:THEMER_STOCK68_JOURNAL_KEY];
    bool synchronized = [defaults synchronize];
    NSDictionary *readback = themer_stock68_local_journal_dictionary();
    bool verified = synchronized && [readback isEqual:updated] &&
        [readback[@"dispatchPossible"] boolValue] &&
        [readback[@"issued"] boolValue];
    if (!verified) {
        // Preserve the armed marker.  A best-effort restore is useful when a
        // defaults implementation changed its in-memory value before a
        // failed durable acknowledgement.
        [defaults setObject:journal forKey:THEMER_STOCK68_JOURNAL_KEY];
        (void)[defaults synchronize];
    }
    printf("[ICONSERVICES_MATERIALIZE] journal dispatch-possible="
           "%d verified=%d\n", 1, verified);
    return verified;
}

typedef struct {
    const char *targetBundle;
    const char *themeFingerprint;
    const char *namedDigest;
    const char *generatedDigest;
    int pid;
    uint64_t proc;
    uint64_t task;
} ThemerStock68GenerationDispatchContext;

static bool themer_stock68_generation_dispatch_marker(void *opaque)
{
    ThemerStock68GenerationDispatchContext *context = opaque;
    if (!context || context->pid <= 0 ||
        !context->proc || context->proc == UINT64_MAX ||
        !context->task || context->task == UINT64_MAX ||
        remote_call_current_pid() != context->pid ||
        remote_call_current_proc() != context->proc ||
        remote_call_current_task() != context->task) {
        return false;
    }
    ThemerSpotlightStock68JournalSnapshot snapshot =
        themer_spotlight_stock68_journal_snapshot();
    bool bound = snapshot.valid && snapshot.version == 2 &&
        snapshot.pid == context->pid &&
        snapshot.classification ==
            ThemerSpotlightStock68JournalNoDispatchProven &&
        strcmp(snapshot.targetBundle, context->targetBundle ?: "") == 0 &&
        strcmp(snapshot.themeFingerprint,
               context->themeFingerprint ?: "") == 0 &&
        strcmp(snapshot.namedDigest, context->namedDigest ?: "") == 0 &&
        strcmp(snapshot.generatedDigest,
               context->generatedDigest ?: "") == 0;
    printf("[ICONSERVICES_MATERIALIZE] dispatch-marker-binding "
           "bound=%d pid=%d proc=0x%llx task=0x%llx journalPid=%d class=%d\n",
           bound,
           context->pid,
           (unsigned long long)context->proc,
           (unsigned long long)context->task,
           snapshot.pid,
           snapshot.classification);
    return bound && remote_call_current_pid() == context->pid &&
        remote_call_current_proc() == context->proc &&
        remote_call_current_task() == context->task &&
        themer_stock68_local_journal_mark_dispatch_possible();
}

// Certificate a known current transaction as having stopped before the
// generation helper boundary.  The complete identity is checked again so a
// stale or pre-existing journal can never be certified retroactively.
static bool themer_stock68_local_journal_persist_no_dispatch_certificate(
    const char *targetBundle,
    const char *themeFingerprint,
    const char *namedDigest,
    const char *generatedDigest)
{
    NSDictionary *journal = themer_stock68_local_journal_dictionary();
    if (!journal || [journal[@"version"] longLongValue] != 2 ||
        [journal[@"pid"] intValue] <= 0 ||
        [journal[@"pid"] intValue] != remote_call_current_pid() ||
        [journal[@"dispatchPossible"] boolValue] ||
        [journal[@"issued"] boolValue] || !targetBundle ||
        !themeFingerprint || !namedDigest || !generatedDigest) {
        return false;
    }
    NSString *target = [NSString stringWithUTF8String:targetBundle];
    NSString *fingerprint = [NSString stringWithUTF8String:themeFingerprint];
    NSString *named = [NSString stringWithUTF8String:namedDigest];
    NSString *generated = [NSString stringWithUTF8String:generatedDigest];
    if (!target || !fingerprint || !named || !generated ||
        ![journal[@"target"] isEqual:target] ||
        ![journal[@"fingerprint"] isEqual:fingerprint] ||
        ![journal[@"namedDigest"] isEqual:named] ||
        ![journal[@"generatedDigest"] isEqual:generated]) {
        return false;
    }
    NSMutableDictionary *certificate = [journal mutableCopy];
    if (!certificate) return false;
    certificate[@"phase"] = @"no-dispatch-proven";
    certificate[@"dispatchPossible"] = @NO;
    certificate[@"transactionBound"] = @YES;
    certificate[@"issued"] = @NO;
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    [defaults setObject:certificate forKey:THEMER_STOCK68_JOURNAL_KEY];
    bool synchronized = [defaults synchronize];
    NSDictionary *readback = themer_stock68_local_journal_dictionary();
    bool verified = synchronized && [readback isEqual:certificate] &&
        [readback[@"version"] longLongValue] == 2 &&
        ![readback[@"dispatchPossible"] boolValue] &&
        ![readback[@"issued"] boolValue] &&
        [readback[@"transactionBound"] boolValue];
    if (!verified) {
        [defaults setObject:journal forKey:THEMER_STOCK68_JOURNAL_KEY];
        (void)[defaults synchronize];
    }
    printf("[ICONSERVICES_MATERIALIZE] journal no-dispatch-certificate="
           "%d verified=%d\n", 1, verified);
    return verified;
}

static bool themer_stock68_local_journal_clear(void)
{
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    id originalJournal = [defaults objectForKey:THEMER_STOCK68_JOURNAL_KEY];
    if (!originalJournal) return true;
    // Only the dedicated clean-close finalizer may retire a store transaction.
    if ([originalJournal isKindOfClass:NSDictionary.class] && originalJournal[@"storeRegistration"]) return false;
    [defaults removeObjectForKey:THEMER_STOCK68_JOURNAL_KEY];
    bool synchronized = [defaults synchronize];
    bool cleared = synchronized && !themer_stock68_local_journal_has_any_key();
    if (!cleared) {
        // A missing in-memory value is insufficient when durable removal was
        // not acknowledged. Keep the admission gate armed in this process too.
        [defaults setObject:originalJournal forKey:THEMER_STOCK68_JOURNAL_KEY];
        (void)[defaults synchronize];
    }
    printf("[ICONSERVICES_MATERIALIZE] journal clear verified=%d\n", cleared);
    return cleared;
}

ThemerSpotlightStock68JournalSnapshot
themer_spotlight_stock68_journal_snapshot(void)
{
    ThemerSpotlightStock68JournalSnapshot snapshot = {0};
    id raw = [NSUserDefaults.standardUserDefaults
        objectForKey:THEMER_STOCK68_JOURNAL_KEY];
    snapshot.present = raw != nil;
    snapshot.storeRegistrationPresent = [raw isKindOfClass:NSDictionary.class] && raw[@"storeRegistration"] != nil;
    snapshot.classification = snapshot.present
        ? ThemerSpotlightStock68JournalInvalid
        : ThemerSpotlightStock68JournalAbsent;
    if (!snapshot.present) return snapshot;
    NSDictionary *journal = themer_stock68_local_journal_dictionary();
    if (!journal) return snapshot;
    id version = journal[@"version"];
    id pid = journal[@"pid"];
    id target = journal[@"target"];
    id fingerprint = journal[@"fingerprint"];
    id namedDigest = journal[@"namedDigest"];
    id generatedDigest = journal[@"generatedDigest"];
    id issued = journal[@"issued"];
    const char *targetText = [target isKindOfClass:NSString.class]
        ? [target UTF8String] : NULL;
    const char *fingerprintText = [fingerprint isKindOfClass:NSString.class]
        ? [fingerprint UTF8String] : NULL;
    const char *namedText = [namedDigest isKindOfClass:NSString.class]
        ? [namedDigest UTF8String] : NULL;
    const char *generatedText = [generatedDigest isKindOfClass:NSString.class]
        ? [generatedDigest UTF8String] : NULL;
    if (!targetText || !fingerprintText || !namedText || !generatedText ||
        !targetText[0] || !namedText[0] || !generatedText[0] ||
        [target lengthOfBytesUsingEncoding:NSUTF8StringEncoding] != strlen(targetText) ||
        [fingerprint lengthOfBytesUsingEncoding:NSUTF8StringEncoding] != strlen(fingerprintText) ||
        [namedDigest lengthOfBytesUsingEncoding:NSUTF8StringEncoding] != strlen(namedText) ||
        [generatedDigest lengthOfBytesUsingEncoding:NSUTF8StringEncoding] != strlen(generatedText) ||
        strlen(targetText) >= sizeof(snapshot.targetBundle) ||
        strlen(fingerprintText) >= sizeof(snapshot.themeFingerprint) ||
        strlen(namedText) >= sizeof(snapshot.namedDigest) ||
        strlen(generatedText) >= sizeof(snapshot.generatedDigest)) {
        return snapshot;
    }
    snapshot.storeRegistrationValid = snapshot.storeRegistrationPresent;
    snprintf(snapshot.rawJournalSHA256, sizeof(snapshot.rawJournalSHA256), "%s",
        themer_stock68_registration_raw_hash(journal).UTF8String ?: "");
    snapshot.version = (int)[version longLongValue];
    snapshot.pid = (int)[pid longLongValue];
    snprintf(snapshot.targetBundle, sizeof(snapshot.targetBundle), "%s",
             targetText);
    snprintf(snapshot.themeFingerprint, sizeof(snapshot.themeFingerprint), "%s",
             fingerprintText);
    snprintf(snapshot.namedDigest, sizeof(snapshot.namedDigest), "%s",
             namedText);
    snprintf(snapshot.generatedDigest, sizeof(snapshot.generatedDigest), "%s",
             generatedText);
    snapshot.issuedKnown = true;
    snapshot.issued = [issued boolValue];
    snapshot.valid = true;
    if (snapshot.version == THEMER_STOCK68_JOURNAL_VERSION) {
        snapshot.classification = snapshot.issued
            ? ThemerSpotlightStock68JournalLegacyIssuedAmbiguous
            : ThemerSpotlightStock68JournalLegacyUnissued;
        return snapshot;
    }
    if (snapshot.version != 2) {
        snapshot.valid = false;
        snapshot.classification = ThemerSpotlightStock68JournalInvalid;
        return snapshot;
    }
    id phase = journal[@"phase"];
    id dispatchPossible = journal[@"dispatchPossible"];
    id transactionBound = journal[@"transactionBound"];
    snapshot.dispatchPossibleKnown = [dispatchPossible isKindOfClass:NSNumber.class] &&
        ([dispatchPossible isEqual:@YES] || [dispatchPossible isEqual:@NO]);
    snapshot.dispatchPossible = [dispatchPossible boolValue];
    snapshot.transactionBound = [transactionBound boolValue];
    if ([phase isKindOfClass:NSString.class] &&
        [phase length] < sizeof(snapshot.phase)) {
        snprintf(snapshot.phase, sizeof(snapshot.phase), "%s",
                 [phase UTF8String] ?: "");
    }
    if (!snapshot.dispatchPossibleKnown || snapshot.phase[0] == '\0' ||
        (snapshot.dispatchPossible && !snapshot.issued) ||
        (!snapshot.dispatchPossible && snapshot.issued)) {
        snapshot.valid = false;
        snapshot.classification = ThemerSpotlightStock68JournalInvalid;
        return snapshot;
    }
    snapshot.classification = snapshot.dispatchPossible
        ? ThemerSpotlightStock68JournalDispatchPossible
        : ThemerSpotlightStock68JournalNoDispatchProven;
    return snapshot;
}

bool themer_spotlight_stock68_has_unresolved_generation(void)
{
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    return themer_stock68_local_journal_has_any_key() ||
        [defaults objectForKey:THEMER_STOCK68_IDENTITY_RETIREMENT_KEY] != nil ||
        [defaults objectForKey:THEMER_STOCK68_ADOPTION_CERTIFICATE_KEY] != nil;
}

bool themer_spotlight_iconservices_has_pending_recovery(void)
{
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    NSArray<NSString *> *keys = @[
        THEMER_ICONSERVICES_LAB_PENDING_STORE_UUID_KEY,
        THEMER_ICONSERVICES_LAB_PENDING_CACHE_TARGET_KEY,
        THEMER_ICONSERVICES_LAB_PENDING_CACHE_BACKUP_KEY,
        THEMER_ICONSERVICES_LAB_PENDING_CACHE_TEMP_KEY,
    ];
    for (NSString *key in keys) {
        // Check object presence rather than string length so an incomplete or
        // malformed journal cannot be silently treated as clean.
        if ([defaults objectForKey:key] != nil) return true;
    }
    return false;
}

static bool themer_spotlight_has_armed_recovery_in_session(void)
{
    if (!remote_call_current_success()) return true;
    bool armed = r_is_objc_ptr(themer_spotlight_proof_state()) ||
        r_is_objc_ptr(themer_iconservices_lab_state()) ||
        r_is_objc_ptr(themer_iconservices_lab_trace_state()) ||
        r_is_objc_ptr(themer_stock68_materialization_state()) ||
        r_is_objc_ptr(themer_spotlight_theme_state()) ||
        themer_spotlight_stock68_has_unresolved_generation() ||
        themer_spotlight_iconservices_has_pending_recovery();
    return armed || !remote_call_current_success();
}

static bool themer_stock68_materialization_guard_claim(
    bool *alreadyClaimedOut)
{
    if (alreadyClaimedOut) *alreadyClaimedOut = false;
    if (!remote_call_current_success()) return false;
    uint64_t existing = themer_spotlight_associated_process_object(
        THEMER_STOCK68_MATERIALIZATION_GUARD_KEY);
    if (r_is_objc_ptr(existing)) {
        if (alreadyClaimedOut) *alreadyClaimedOut = true;
        return true;
    }
    uint64_t marker = themer_spotlight_proof_number(
        (unsigned long long)remote_call_current_pid());
    bool claimed = r_is_objc_ptr(marker) &&
        themer_spotlight_commit_process_object(
            THEMER_STOCK68_MATERIALIZATION_GUARD_KEY, marker);
    printf("[ICONSERVICES_MATERIALIZE] request-guard pid=%d "
           "already=0 claimed=%d marker=0x%llx\n",
           remote_call_current_pid(),
           claimed,
           (unsigned long long)marker);
    return claimed && remote_call_current_success();
}

static bool themer_iconservices_lab_generation_guard_claim(
    bool *alreadyClaimedOut)
{
    if (alreadyClaimedOut) *alreadyClaimedOut = false;
    if (!remote_call_current_success()) return false;
    uint64_t existing = themer_spotlight_associated_process_object(
        THEMER_ICONSERVICES_LAB_GENERATION_GUARD_KEY);
    if (r_is_objc_ptr(existing)) {
        if (alreadyClaimedOut) *alreadyClaimedOut = true;
        return true;
    }
    if (!remote_call_current_success()) return false;
    uint64_t marker = themer_spotlight_proof_number(
        (unsigned long long)remote_call_current_pid());
    bool claimed = r_is_objc_ptr(marker) &&
        themer_spotlight_commit_process_object(
            THEMER_ICONSERVICES_LAB_GENERATION_GUARD_KEY, marker);
    printf("[ICONSERVICES_LAB] record-identifiers-class-guard "
           "claim=%d pid=%d marker=0x%llx\n",
           claimed,
           remote_call_current_pid(),
           (unsigned long long)marker);
    return claimed && remote_call_current_success();
}

static uint64_t themer_iconservices_lab_double_number(double value)
{
    uint64_t cls = r_class("NSNumber");
    if (!r_is_objc_ptr(cls) ||
        !r_responds_main(cls, "numberWithDouble:")) {
        return 0;
    }
    return r_msg2_main_raw(cls, "numberWithDouble:",
                           &value, sizeof(value),
                           NULL, 0, NULL, 0, NULL, 0);
}

static bool themer_iconservices_lab_state_double(uint64_t state,
                                                 const char *keyName,
                                                 double *valueOut)
{
    if (valueOut) *valueOut = 0.0;
    uint64_t number = themer_spotlight_dictionary_object(state, keyName);
    if (!r_is_objc_ptr(number) ||
        !r_responds_main(number, "doubleValue")) {
        return false;
    }
    uint64_t bits = r_msg2_main(number, "doubleValue", 0, 0, 0, 0);
    double value = 0.0;
    memcpy(&value, &bits, sizeof(value));
    if (valueOut) *valueOut = value;
    return true;
}

static void themer_iconservices_lab_log_descriptor(const char *tag,
                                                   uint64_t desc)
{
    if (!tag || !r_is_objc_ptr(desc) || !remote_call_current_success()) {
        return;
    }
    struct { double w; double h; } size = {0.0, 0.0};
    bool hasSize = r_responds_main(desc, "size") &&
        r_msg2_main_struct_ret(desc, "size", &size, sizeof(size),
            NULL, 0, NULL, 0, NULL, 0, NULL, 0);
    bool hasScale = false;
    double scale = themer_read_remote_double_property(desc, "scale", 0.0,
                                                      &hasScale);
    bool hasAppearance = false;
    uint64_t appearance = themer_read_remote_uint_property(
        desc, "appearance", &hasAppearance);
    bool hasAppearanceVariant = false;
    uint64_t appearanceVariant = themer_read_remote_uint_property(
        desc, "appearanceVariant", &hasAppearanceVariant);
    bool hasIconVariant = false;
    uint64_t iconVariant = themer_read_remote_uint_property(
        desc, "iconVariant", &hasIconVariant);
    bool hasVariantOptions = false;
    uint64_t variantOptions = themer_read_remote_uint_property(
        desc, "variantOptions", &hasVariantOptions);
    char cls[96] = {0};
    char text[220] = {0};
    themer_read_class_name(desc, cls, sizeof(cls));
    themer_read_remote_description(desc, text, sizeof(text));
    printf("[ICONSERVICES_LAB] descriptor tag=%s desc=0x%llx class=%s "
           "size=%s%.1fx%.1f scale=%s%.2f appearance=%s%llu "
           "appearanceVariant=%s%llu iconVariant=%s%llu "
           "variantOptions=%s%llu desc=\"%s\"\n",
           tag,
           (unsigned long long)desc,
           cls[0] ? cls : "-",
           hasSize ? "" : "?",
           size.w,
           size.h,
           hasScale ? "" : "?",
           scale,
           hasAppearance ? "" : "?",
           (unsigned long long)appearance,
           hasAppearanceVariant ? "" : "?",
           (unsigned long long)appearanceVariant,
           hasIconVariant ? "" : "?",
           (unsigned long long)iconVariant,
           hasVariantOptions ? "" : "?",
           (unsigned long long)variantOptions,
           text);
}

static void themer_iconservices_lab_log_bag_image(const char *source,
                                                  int index,
                                                  uint64_t image)
{
    if (!source || !r_is_objc_ptr(image) ||
        !remote_call_current_success()) {
        return;
    }
    char cls[96] = {0};
    char text[220] = {0};
    themer_read_class_name(image, cls, sizeof(cls));
    themer_read_remote_description(image, text, sizeof(text));
    bool hasScale = false;
    double scale = themer_read_remote_double_property(
        image, "scale", 0.0, &hasScale);
    struct { double w; double h; } size = {0.0, 0.0};
    bool hasSize = r_responds_main(image, "size") &&
        r_msg2_main_struct_ret(image, "size", &size, sizeof(size),
            NULL, 0, NULL, 0, NULL, 0, NULL, 0);
    struct { double w; double h; } pixels = {0.0, 0.0};
    bool hasPixels = r_responds_main(image, "pixelSize") &&
        r_msg2_main_struct_ret(image, "pixelSize", &pixels, sizeof(pixels),
            NULL, 0, NULL, 0, NULL, 0, NULL, 0);
    uint64_t cgImage = r_responds_main(image, "CGImage")
        ? r_msg2_main(image, "CGImage", 0, 0, 0, 0) : 0;
    bool hasPlaceholder = false;
    uint64_t placeholder = themer_read_remote_uint_property(
        image, "placeholder", &hasPlaceholder);
    bool hasDimension = false;
    double dimension = themer_read_remote_double_property(
        image, "dimension", 0.0, &hasDimension);
    bool hasValidationFlags = false;
    uint64_t validationFlags = themer_read_remote_uint_property(
        image, "validationFlags", &hasValidationFlags);
    struct { double w; double h; } minimumSize = {0.0, 0.0};
    bool hasMinimumSize = r_responds_main(image, "minimumSize") &&
        r_msg2_main_struct_ret(image, "minimumSize", &minimumSize,
            sizeof(minimumSize), NULL, 0, NULL, 0, NULL, 0, NULL, 0);
    struct { double w; double h; } iconSize = {0.0, 0.0};
    bool hasIconSize = r_responds_main(image, "iconSize") &&
        r_msg2_main_struct_ret(image, "iconSize", &iconSize,
            sizeof(iconSize), NULL, 0, NULL, 0, NULL, 0, NULL, 0);
    uint64_t uuid = r_responds_main(image, "uuid")
        ? r_msg2_main(image, "uuid", 0, 0, 0, 0) : 0;
    uint64_t validationToken = r_responds_main(image, "validationToken")
        ? r_msg2_main(image, "validationToken", 0, 0, 0, 0) : 0;
    uint64_t tokenLength = r_is_objc_ptr(validationToken) &&
        r_responds_main(validationToken, "length")
        ? r_msg2_main(validationToken, "length", 0, 0, 0, 0) : 0;
    char uuidCls[96] = {0};
    char tokenCls[96] = {0};
    themer_read_class_name(uuid, uuidCls, sizeof(uuidCls));
    themer_read_class_name(validationToken, tokenCls, sizeof(tokenCls));
    printf("[ICONSERVICES_LAB] bag-image source=%s index=%d image=0x%llx "
           "class=%s scale=%s%.2f size=%s%.1fx%.1f "
           "pixelSize=%s%.0fx%.0f minimumSize=%s%.1fx%.1f "
           "iconSize=%s%.1fx%.1f dimension=%s%.2f cgImage=0x%llx "
           "uuid=0x%llx/%s validationToken=0x%llx/%s/%llu "
           "validationFlags=%s%llu placeholder=%s%llu desc=\"%s\"\n",
           source,
           index,
           (unsigned long long)image,
           cls[0] ? cls : "-",
           hasScale ? "" : "?",
           scale,
           hasSize ? "" : "?",
           size.w,
           size.h,
           hasPixels ? "" : "?",
           pixels.w,
           pixels.h,
           hasMinimumSize ? "" : "?",
           minimumSize.w,
           minimumSize.h,
           hasIconSize ? "" : "?",
           iconSize.w,
           iconSize.h,
           hasDimension ? "" : "?",
           dimension,
           (unsigned long long)cgImage,
           (unsigned long long)uuid,
           uuidCls[0] ? uuidCls : "-",
           (unsigned long long)validationToken,
           tokenCls[0] ? tokenCls : "-",
           (unsigned long long)tokenLength,
           hasValidationFlags ? "" : "?",
           (unsigned long long)validationFlags,
           hasPlaceholder ? "" : "?",
           (unsigned long long)placeholder,
           text);
}

