static void themer_iconservices_lab_log_object_surface(const char *role,
                                                       uint64_t object)
{
    if (!role || !r_is_objc_ptr(object) ||
        !remote_call_current_success()) {
        return;
    }

    uint64_t cls = r_dlsym_call(R_TIMEOUT, "object_getClass",
                                object, 0, 0, 0, 0, 0, 0, 0);
    if (!r_is_objc_ptr(cls)) return;

    int methodsLogged = 0;
    int ivarsLogged = 0;
    for (int depth = 0; r_is_objc_ptr(cls) && depth < 8; depth++) {
        char owner[96] = {0};
        themer_read_class_object_name(cls, owner, sizeof(owner));

        uint64_t countBuf = r_dlsym_call(R_TIMEOUT, "malloc",
                                         8, 0, 0, 0, 0, 0, 0, 0);
        if (!countBuf) break;
        remote_write64(countBuf, 0);
        uint64_t methods = r_dlsym_call(R_TIMEOUT, "class_copyMethodList",
                                        cls, countBuf, 0, 0, 0, 0, 0, 0);
        uint32_t methodCount = 0;
        bool methodCountRead = remote_read(countBuf, &methodCount,
                                           sizeof(methodCount));
        r_free(countBuf);
        if (!methodCountRead || !remote_call_current_success()) {
            if (methods) r_free(methods);
            break;
        }
        if (methods && methodCount <= 1024) {
            uint32_t remaining = methodsLogged < THEMER_ICONSERVICES_LAB_METHOD_CAP
                ? (uint32_t)(THEMER_ICONSERVICES_LAB_METHOD_CAP - methodsLogged)
                : 0;
            uint32_t cap = methodCount < remaining ? methodCount : remaining;
            for (uint32_t i = 0; i < cap && remote_call_current_success(); i++) {
                uint64_t method = remote_read64(
                    methods + ((uint64_t)i * sizeof(uint64_t)));
                if (!method) continue;
                uint64_t sel = r_dlsym_call(R_TIMEOUT, "method_getName",
                                            method, 0, 0, 0, 0, 0, 0, 0);
                uint64_t nameCstr = sel
                    ? r_dlsym_call(R_TIMEOUT, "sel_getName",
                                   sel, 0, 0, 0, 0, 0, 0, 0)
                    : 0;
                uint64_t typeCstr = r_dlsym_call(
                    R_TIMEOUT, "method_getTypeEncoding",
                    method, 0, 0, 0, 0, 0, 0, 0);
                char name[160] = {0};
                char types[192] = {0};
                (void)themer_read_remote_cstring(nameCstr, name,
                                                 sizeof(name));
                (void)themer_read_remote_cstring(typeCstr, types,
                                                 sizeof(types));
                printf("[ICONSERVICES_LAB] bag-method role=%s owner=%s "
                       "depth=%d name=%s types=\"%s\"\n",
                       role,
                       owner[0] ? owner : "-",
                       depth,
                       name[0] ? name : "?",
                       types[0] ? types : "?");
                methodsLogged++;
            }
        }
        if (methods) r_free(methods);

        countBuf = r_dlsym_call(R_TIMEOUT, "malloc",
                                8, 0, 0, 0, 0, 0, 0, 0);
        if (!countBuf) break;
        remote_write64(countBuf, 0);
        uint64_t ivars = r_dlsym_call(R_TIMEOUT, "class_copyIvarList",
                                      cls, countBuf, 0, 0, 0, 0, 0, 0);
        uint32_t ivarCount = 0;
        bool ivarCountRead = remote_read(countBuf, &ivarCount,
                                         sizeof(ivarCount));
        r_free(countBuf);
        if (!ivarCountRead || !remote_call_current_success()) {
            if (ivars) r_free(ivars);
            break;
        }
        if (ivars && ivarCount <= 1024) {
            uint32_t remaining = ivarsLogged < THEMER_ICONSERVICES_LAB_IVAR_CAP
                ? (uint32_t)(THEMER_ICONSERVICES_LAB_IVAR_CAP - ivarsLogged)
                : 0;
            uint32_t cap = ivarCount < remaining ? ivarCount : remaining;
            for (uint32_t i = 0; i < cap && remote_call_current_success(); i++) {
                uint64_t ivar = remote_read64(
                    ivars + ((uint64_t)i * sizeof(uint64_t)));
                if (!ivar) continue;
                uint64_t nameCstr = r_dlsym_call(R_TIMEOUT, "ivar_getName",
                                                 ivar, 0, 0, 0, 0, 0, 0, 0);
                uint64_t typeCstr = r_dlsym_call(
                    R_TIMEOUT, "ivar_getTypeEncoding",
                    ivar, 0, 0, 0, 0, 0, 0, 0);
                uint64_t offset = r_dlsym_call(R_TIMEOUT, "ivar_getOffset",
                                               ivar, 0, 0, 0, 0, 0, 0, 0);
                char name[160] = {0};
                char types[160] = {0};
                (void)themer_read_remote_cstring(nameCstr, name,
                                                 sizeof(name));
                (void)themer_read_remote_cstring(typeCstr, types,
                                                 sizeof(types));
                printf("[ICONSERVICES_LAB] bag-ivar role=%s owner=%s "
                       "depth=%d name=%s type=\"%s\" offset=%lld\n",
                       role,
                       owner[0] ? owner : "-",
                       depth,
                       name[0] ? name : "?",
                       types[0] ? types : "?",
                       (long long)offset);
                ivarsLogged++;
            }
        }
        if (ivars) r_free(ivars);

        cls = r_dlsym_call(R_TIMEOUT, "class_getSuperclass",
                           cls, 0, 0, 0, 0, 0, 0, 0);
    }

    printf("[ICONSERVICES_LAB] bag-surface role=%s methods=%d ivars=%d "
           "methodCap=%d ivarCap=%d\n",
           role,
           methodsLogged,
           ivarsLogged,
           THEMER_ICONSERVICES_LAB_METHOD_CAP,
           THEMER_ICONSERVICES_LAB_IVAR_CAP);
}

static int themer_iconservices_lab_log_runtime_methods(
    const char *className,
    const char *kind,
    uint64_t cls,
