    uint64_t methods = r_dlsym_call(R_TIMEOUT, "class_copyMethodList",
                                    cls, countBuf, 0, 0, 0, 0, 0, 0);
    uint32_t count = 0;
    bool countRead = remote_read(countBuf, &count, sizeof(count));
    r_free(countBuf);
    if (!countRead || count > 1024) {
        if (methods) r_free(methods);
        return 0;
    }
    uint32_t cap = count < (uint32_t)remaining ? count : (uint32_t)remaining;
    int logged = 0;
    for (uint32_t i = 0; methods && i < cap &&
         remote_call_current_success(); i++) {
        uint64_t method = remote_read64(
            methods + ((uint64_t)i * sizeof(uint64_t)));
        if (!method) continue;
        uint64_t sel = r_dlsym_call(R_TIMEOUT, "method_getName",
                                    method, 0, 0, 0, 0, 0, 0, 0);
        uint64_t nameCstr = sel
            ? r_dlsym_call(R_TIMEOUT, "sel_getName",
                           sel, 0, 0, 0, 0, 0, 0, 0)
            : 0;
        uint64_t typesCstr = r_dlsym_call(
            R_TIMEOUT, "method_getTypeEncoding",
            method, 0, 0, 0, 0, 0, 0, 0);
        char name[160] = {0};
        char types[192] = {0};
        (void)themer_read_remote_cstring(nameCstr, name, sizeof(name));
        (void)themer_read_remote_cstring(typesCstr, types, sizeof(types));
        printf("[ICONSERVICES_LAB] generation-method class=%s kind=%s "
               "name=%s types=\"%s\"\n",
               className,
               kind,
               name[0] ? name : "?",
               types[0] ? types : "?");
        logged++;
    }
    if (methods) r_free(methods);
    return logged;
}

