static void themer_iconservices_lab_log_runtime_class_surface(
    const char *className)
{
    if (!className || !className[0] || !remote_call_current_success()) return;
    uint64_t cls = themer_lookup_class(className);
    if (!r_is_objc_ptr(cls)) {
        printf("[ICONSERVICES_LAB] generation-surface class=%s available=0\n",
               className);
        return;
    }
    int methods = themer_iconservices_lab_log_runtime_methods(
        className, "instance", cls, THEMER_ICONSERVICES_LAB_METHOD_CAP);
    uint64_t meta = r_dlsym_call(R_TIMEOUT, "object_getClass",
                                 cls, 0, 0, 0, 0, 0, 0, 0);
    methods += themer_iconservices_lab_log_runtime_methods(
        className, "class", meta,
        THEMER_ICONSERVICES_LAB_METHOD_CAP - methods);
    int ivars = themer_iconservices_lab_log_runtime_ivars(className, cls);
    int properties = themer_iconservices_lab_log_runtime_properties(
        className, cls);
    printf("[ICONSERVICES_LAB] generation-surface class=%s available=1 "
           "methods=%d ivars=%d properties=%d caps=%d/%d/%d\n",
           className,
           methods,
           ivars,
           properties,
           THEMER_ICONSERVICES_LAB_METHOD_CAP,
           THEMER_ICONSERVICES_LAB_IVAR_CAP,
           THEMER_ICONSERVICES_LAB_PROPERTY_CAP);
}

static void themer_iconservices_lab_log_runtime_protocol_surface(
    const char *protocolName)
{
    if (!protocolName || !protocolName[0] ||
        !remote_call_current_success()) {
        return;
    }
    uint64_t remoteName = r_alloc_str(protocolName);
    if (!remoteName) return;
    uint64_t protocol = r_dlsym_call(R_TIMEOUT, "objc_getProtocol",
                                     remoteName, 0, 0, 0, 0, 0, 0, 0);
    r_free(remoteName);
    if (!protocol) {
        printf("[ICONSERVICES_LAB] generation-protocol name=%s available=0\n",
               protocolName);
        return;
    }
    int logged = 0;
    for (int required = 1; required >= 0 &&
         remote_call_current_success(); required--) {
        for (int instance = 1; instance >= 0 &&
             remote_call_current_success(); instance--) {
            uint64_t countBuf = r_dlsym_call(R_TIMEOUT, "malloc",
                                             8, 0, 0, 0, 0, 0, 0, 0);
            if (!countBuf) continue;
            remote_write64(countBuf, 0);
            uint64_t descriptions = r_dlsym_call(
                R_TIMEOUT, "protocol_copyMethodDescriptionList",
                protocol, (uint64_t)required, (uint64_t)instance,
                countBuf, 0, 0, 0, 0);
            uint32_t count = 0;
            bool countRead = remote_read(countBuf, &count, sizeof(count));
            r_free(countBuf);
            if (!countRead || count > 1024) {
                if (descriptions) r_free(descriptions);
                continue;
            }
            int remaining = THEMER_ICONSERVICES_LAB_METHOD_CAP - logged;
            uint32_t cap = remaining > 0 && count < (uint32_t)remaining
                ? count : (remaining > 0 ? (uint32_t)remaining : 0);
            for (uint32_t i = 0; descriptions && i < cap &&
                 remote_call_current_success(); i++) {
                uint64_t row = descriptions + ((uint64_t)i * 16ULL);
                uint64_t sel = remote_read64(row);
                uint64_t typesCstr = remote_read64(row + 8ULL);
                uint64_t nameCstr = sel
                    ? r_dlsym_call(R_TIMEOUT, "sel_getName",
                                   sel, 0, 0, 0, 0, 0, 0, 0)
                    : 0;
                char name[160] = {0};
                char types[192] = {0};
                (void)themer_read_remote_cstring(
                    nameCstr, name, sizeof(name));
                (void)themer_read_remote_cstring(
                    typesCstr, types, sizeof(types));
                printf("[ICONSERVICES_LAB] generation-protocol-method "
                       "protocol=%s required=%d kind=%s name=%s "
                       "types=\"%s\"\n",
                       protocolName,
                       required,
                       instance ? "instance" : "class",
                       name[0] ? name : "?",
                       types[0] ? types : "?");
                logged++;
            }
            if (descriptions) r_free(descriptions);
        }
    }
    printf("[ICONSERVICES_LAB] generation-protocol name=%s available=1 "
           "methods=%d cap=%d\n",
           protocolName,
           logged,
           THEMER_ICONSERVICES_LAB_METHOD_CAP);
}

static void themer_iconservices_lab_log_generation_surfaces_once(void)
{
    static int loggedPid = -1;
    int pid = remote_call_current_pid();
    if (pid <= 0 || loggedPid == pid || !remote_call_current_success()) return;
    loggedPid = pid;
    static const char *classes[] = {
        "ISCompositorResourceValidationToken",
        "ISCompositorResource",
        "ISCompositorResourceProvider",
        "ISCompositorResourceProviderKey",
        "ISGenerationRequest",
        "ISGenerationResponse",
        "ISGenerationReport",
        "ISImageProvider",
        "ISImageCache",
        "ISIconCache",
        "ISImageDescriptor",
        "IFCacheImage",
    };
    uint64_t ioFailuresBefore = remote_call_current_io_failure_count();
    for (size_t i = 0; i < sizeof(classes) / sizeof(classes[0]) &&
         remote_call_current_success(); i++) {
        themer_iconservices_lab_log_runtime_class_surface(classes[i]);
    }
    themer_iconservices_lab_log_runtime_protocol_surface(
        "ISIconCacheServiceProtocol");
    uint64_t ioFailuresAfter = remote_call_current_io_failure_count();
    printf("[ICONSERVICES_LAB] generation-surface-summary pid=%d "
           "classes=%zu protocol=ISIconCacheServiceProtocol "
           "ioFailures=%llu->%llu transportClean=%d\n",
           pid,
           sizeof(classes) / sizeof(classes[0]),
           (unsigned long long)ioFailuresBefore,
           (unsigned long long)ioFailuresAfter,
           ioFailuresAfter == ioFailuresBefore);
}

static void themer_iconservices_lab_log_bag_selectors(uint64_t bag)
{
    if (!r_is_objc_ptr(bag) || !remote_call_current_success()) return;
    static const char *selectors[] = {
        "init",
        "initWithImages:",
        "initWithImagesByScale:",
        "setImages:",
        "setImagesByScale:",
        "insertImage:",
        "addImage:",
        "addImage:forScale:",
        "copy",
        "mutableCopy",
    };
    for (size_t i = 0;
         i < sizeof(selectors) / sizeof(selectors[0]) &&
         remote_call_current_success();
         i++) {
        printf("[ICONSERVICES_LAB] bag-selector name=%s responds=%d\n",
               selectors[i],
               r_responds_main(bag, selectors[i]));
    }
}

static bool themer_iconservices_lab_method_types(uint64_t object,
                                                const char *selector,
                                                char *types,
                                                size_t typesLen)
{
    if (types && typesLen) types[0] = '\0';
    if (!r_is_objc_ptr(object) || !selector || !types || typesLen == 0 ||
        !remote_call_current_success()) {
        return false;
    }
    uint64_t cls = r_dlsym_call(R_TIMEOUT, "object_getClass",
                                object, 0, 0, 0, 0, 0, 0, 0);
    uint64_t sel = r_sel(selector);
    if (!r_is_objc_ptr(cls) || !sel) return false;
    uint64_t method = r_dlsym_call(R_TIMEOUT, "class_getInstanceMethod",
                                   cls, sel, 0, 0, 0, 0, 0, 0);
    if (!method) return false;
    uint64_t typeCstr = r_dlsym_call(R_TIMEOUT, "method_getTypeEncoding",
                                     method, 0, 0, 0, 0, 0, 0, 0);
    return themer_read_remote_cstring(typeCstr, types, typesLen);
}

static bool themer_iconservices_lab_bag_key_matches_descriptor(
    uint64_t descriptor,
    uint64_t bagKey)
{
    if (!r_is_objc_ptr(descriptor) || !r_is_objc_ptr(bagKey) ||
        !remote_call_current_success()) {
        return false;
    }
    if (descriptor == bagKey) return true;
    char types[192] = {0};
    if (!r_responds_main(descriptor, "digest") ||
        !themer_iconservices_lab_method_types(
            descriptor, "digest", types, sizeof(types)) ||
        types[0] != '@') {
        return false;
    }
    uint64_t digest = r_msg2_main(descriptor, "digest", 0, 0, 0, 0);
    if (!remote_call_current_success() || !r_is_objc_ptr(digest)) return false;
    if (digest == bagKey) return true;
    return r_responds_main(bagKey, "isEqual:") &&
        (r_msg2_main(bagKey, "isEqual:", digest, 0, 0, 0) & 1) != 0 &&
        remote_call_current_success();
}

static uint64_t themer_iconservices_lab_image_for_size_scale(
    uint64_t object,
    double width,
    double height,
    double scale)
{
    if (!r_is_objc_ptr(object) || !remote_call_current_success() ||
        !r_responds_main(object, "imageForSize:scale:")) {
        return 0;
    }
    char types[192] = {0};
    if (!themer_iconservices_lab_method_types(
            object, "imageForSize:scale:", types, sizeof(types)) ||
        types[0] != '@') {
        return 0;
    }
    struct { double w; double h; } size = {width, height};
    uint64_t image = r_msg2_main_raw(
        object, "imageForSize:scale:",
        &size, sizeof(size),
        &scale, sizeof(scale),
        NULL, 0, NULL, 0);
    return remote_call_current_success() ? image : 0;
}

typedef struct {
    uint64_t image;  // Borrowed for stock entries; +1 owned for payload entries.
    double width;
    double height;
    double scale;
    bool geometryKnown;
} ThemerIconServicesLabBagEntry;

static bool themer_iconservices_lab_read_image_geometry(
    uint64_t image,
    double *widthOut,
    double *heightOut,
    double *scaleOut)
{
    if (widthOut) *widthOut = 0.0;
    if (heightOut) *heightOut = 0.0;
    if (scaleOut) *scaleOut = 0.0;
    if (!r_is_objc_ptr(image) || !remote_call_current_success()) return false;
    struct { double w; double h; } size = {0.0, 0.0};
    bool hasSize = r_responds_main(image, "size") &&
        r_msg2_main_struct_ret(image, "size", &size, sizeof(size),
            NULL, 0, NULL, 0, NULL, 0, NULL, 0);
    bool hasScale = false;
    double scale = themer_read_remote_double_property(
        image, "scale", 0.0, &hasScale);
    if (widthOut) *widthOut = size.w;
    if (heightOut) *heightOut = size.h;
    if (scaleOut) *scaleOut = scale;
    return hasSize && hasScale && size.w > 0.0 && size.h > 0.0 &&
        scale >= 1.0 && scale <= 4.0 && remote_call_current_success();
}

typedef struct {
    uint64_t image;
    double width;
    double height;
    double scale;
    bool geometryKnown;
} ThemerIconServicesLabSnapshotEntry;

typedef struct {
    uint64_t key;
    uint64_t bag;
    char keyClass[96];
    char keyText[160];
    int entryCount;
    bool entriesTruncated;
    bool bagKnown;
    bool imageArrayKnown;
    bool imageCountKnown;
    ThemerIconServicesLabSnapshotEntry entries[
        THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP];
} ThemerIconServicesLabSnapshotKey;

typedef struct {
    bool captured;
    uint64_t dictionary;
    int dictionaryCount;
    int keyCount;
    int actualKeyCount;
    int totalEntryCount;
    bool keysTruncated;
    bool keyArrayKnown;
    bool dictionaryCountKnown;
    bool keyCountKnown;
    bool actualKeyCountKnown;
    bool totalEntryCountKnown;
    ThemerIconServicesLabSnapshotKey keys[
        THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP];
} ThemerIconServicesLabTopologySnapshot;

// Getter-only topology capture. Deliberately excludes prepareImageForDescriptor:,
// imageForDescriptor:, imageForSize:scale:, imagesForScale:, debugDescription,
// CGImage, and every setter so the snapshot minimally perturbs the live cache.
static bool themer_iconservices_lab_capture_topology(
    uint64_t cache,
    const char *phase,
    ThemerIconServicesLabTopologySnapshot *snapshot)
{
    if (!snapshot || !phase) return false;
    memset(snapshot, 0, sizeof(*snapshot));
    if (!r_is_objc_ptr(cache) ||
        !r_responds_main(cache, "imageBagsByDescriptor")) {
        printf("[ICONSERVICES_LAB] bag-snapshot phase=%s captured=0 "
               "reason=cache-or-getter-unavailable\n", phase);
        return remote_call_current_success();
    }
    uint64_t bags = r_msg2_main(
        cache, "imageBagsByDescriptor", 0, 0, 0, 0);
    if (!remote_call_current_success()) return false;
    snapshot->dictionary = bags;
    snapshot->captured = r_is_objc_ptr(bags);
    snapshot->dictionaryCountKnown = snapshot->captured &&
        r_responds_main(bags, "count");
    snapshot->dictionaryCount = snapshot->captured &&
        snapshot->dictionaryCountKnown
        ? (int)themer_remote_count(bags) : 0;
    if (!remote_call_current_success()) return false;
    if (!snapshot->captured ||
        !r_responds_main(bags, "allKeys") ||
        !r_responds_main(bags, "objectForKey:")) {
        printf("[ICONSERVICES_LAB] bag-snapshot phase=%s captured=%d "
               "dictionary=0x%llx count=%d keyCount=0\n",
               phase,
               snapshot->captured,
               (unsigned long long)bags,
               snapshot->dictionaryCount);
        return remote_call_current_success();
    }
    uint64_t keys = r_msg2_main(bags, "allKeys", 0, 0, 0, 0);
    snapshot->keyArrayKnown = r_is_objc_ptr(keys);
    snapshot->keyCountKnown = snapshot->keyArrayKnown &&
        r_responds_main(keys, "count");
    int actualKeyCount = snapshot->keyCountKnown
        ? (int)themer_remote_count(keys) : 0;
    snapshot->actualKeyCountKnown = snapshot->keyCountKnown;
    snapshot->actualKeyCount = actualKeyCount;
    if (!remote_call_current_success()) return false;
    snapshot->keysTruncated =
        actualKeyCount > THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP;
    snapshot->keyCount = actualKeyCount < THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP
        ? actualKeyCount : THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP;
    snapshot->totalEntryCount = 0;
    snapshot->totalEntryCountKnown = snapshot->keyCountKnown;
    printf("[ICONSERVICES_LAB] bag-snapshot phase=%s captured=1 "
           "dictionary=0x%llx count=%d keyCount=%d actualKeys=%d "
           "truncated=%d\n",
           phase,
           (unsigned long long)bags,
           snapshot->dictionaryCount,
           snapshot->keyCount,
           actualKeyCount,
           snapshot->keysTruncated);
    for (int i = 0;
         i < snapshot->keyCount && remote_call_current_success(); i++) {
        ThemerIconServicesLabSnapshotKey *item = &snapshot->keys[i];
        item->key = r_msg2_main(
            keys, "objectAtIndex:", (uint64_t)i, 0, 0, 0);
        item->bag = r_msg2_main(
            bags, "objectForKey:", item->key, 0, 0, 0);
        item->bagKnown = r_is_objc_ptr(item->bag);
        themer_read_class_name(item->key, item->keyClass,
                               sizeof(item->keyClass));
        themer_read_remote_description(item->key, item->keyText,
                                       sizeof(item->keyText));
        uint64_t images = r_is_objc_ptr(item->bag) &&
            r_responds_main(item->bag, "images")
            ? r_msg2_main(item->bag, "images", 0, 0, 0, 0) : 0;
        item->imageArrayKnown = r_is_objc_ptr(images);
        item->imageCountKnown = item->imageArrayKnown &&
            r_responds_main(images, "count");
        int actualEntryCount = item->imageCountKnown
            ? (int)themer_remote_count(images) : 0;
        if (item->imageCountKnown && actualEntryCount >= 0) {
            snapshot->totalEntryCount += actualEntryCount;
        } else {
            snapshot->totalEntryCountKnown = false;
        }
        item->entriesTruncated =
            actualEntryCount > THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP;
        item->entryCount =
            actualEntryCount < THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP
                ? actualEntryCount : THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP;
        printf("[ICONSERVICES_LAB] bag-snapshot-key phase=%s index=%d "
               "key=0x%llx/%s bag=0x%llx entries=%d actualEntries=%d "
               "truncated=%d desc=\"%s\"\n",
               phase,
               i,
               (unsigned long long)item->key,
               item->keyClass[0] ? item->keyClass : "-",
               (unsigned long long)item->bag,
               item->entryCount,
               actualEntryCount,
               item->entriesTruncated,
               item->keyText);
        if (!r_is_objc_ptr(images) ||
            !r_responds_main(images, "objectAtIndex:")) {
            continue;
        }
        for (int j = 0;
             j < item->entryCount && remote_call_current_success(); j++) {
            ThemerIconServicesLabSnapshotEntry *entry = &item->entries[j];
            entry->image = r_msg2_main(
                images, "objectAtIndex:", (uint64_t)j, 0, 0, 0);
            entry->geometryKnown =
                themer_iconservices_lab_read_image_geometry(
                    entry->image, &entry->width, &entry->height,
                    &entry->scale);
            printf("[ICONSERVICES_LAB] bag-snapshot-entry phase=%s "
                   "keyIndex=%d entryIndex=%d image=0x%llx geometry=%d "
                   "size=%.1fx%.1f scale=%.2f\n",
                   phase,
                   i,
                   j,
                   (unsigned long long)entry->image,
                   entry->geometryKnown,
                   entry->width,
                   entry->height,
                   entry->scale);
        }
    }
    return remote_call_current_success();
}

// Capture a specific dictionary without consulting the cache getter. This is
// required while rolling back: the live cache may already point at a generated
// dictionary, so the retained original must be inspected directly before it
// is passed back to the setter.
static bool themer_iconservices_lab_capture_topology_from_dictionary(
    uint64_t bags,
    const char *phase,
    ThemerIconServicesLabTopologySnapshot *snapshot)
{
    if (!snapshot || !phase) return false;
    memset(snapshot, 0, sizeof(*snapshot));
    if (!r_is_objc_ptr(bags) || !remote_call_current_success() ||
        !r_responds_main(bags, "allKeys") ||
        !r_responds_main(bags, "objectForKey:")) {
        printf("[ICONSERVICES_MATERIALIZE] strict-dictionary phase=%s "
               "captured=0 dictionary=0x%llx\n",
               phase, (unsigned long long)bags);
        return false;
    }
    snapshot->dictionary = bags;
    snapshot->captured = true;
    snapshot->dictionaryCountKnown = r_responds_main(bags, "count");
    snapshot->dictionaryCount = snapshot->dictionaryCountKnown
        ? (int)themer_remote_count(bags) : 0;
    if (!remote_call_current_success() ||
        snapshot->dictionaryCount < 0 ||
        snapshot->dictionaryCount > THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP) {
        return false;
    }
    uint64_t keys = r_msg2_main(bags, "allKeys", 0, 0, 0, 0);
    snapshot->keyArrayKnown = r_is_objc_ptr(keys);
    if (!remote_call_current_success() || !snapshot->keyArrayKnown) {
        return false;
    }
    snapshot->keyCountKnown = r_responds_main(keys, "count");
    int actualKeyCount = snapshot->keyCountKnown
        ? (int)themer_remote_count(keys) : 0;
    if (!remote_call_current_success() || actualKeyCount < 0) return false;
    snapshot->keysTruncated =
        actualKeyCount > THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP;
    snapshot->keyCount = actualKeyCount < THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP
        ? actualKeyCount : THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP;
    snapshot->actualKeyCountKnown = snapshot->keyCountKnown;
    snapshot->actualKeyCount = actualKeyCount;
    snapshot->totalEntryCount = 0;
    snapshot->totalEntryCountKnown = snapshot->keyCountKnown;
    if (snapshot->keysTruncated ||
        actualKeyCount != snapshot->dictionaryCount) {
        return false;
    }
    for (int i = 0; i < snapshot->keyCount &&
         remote_call_current_success(); i++) {
        ThemerIconServicesLabSnapshotKey *item = &snapshot->keys[i];
        item->key = r_msg2_main(keys, "objectAtIndex:", (uint64_t)i,
                                0, 0, 0);
        item->bag = r_msg2_main(bags, "objectForKey:", item->key,
                                0, 0, 0);
        item->bagKnown = r_is_objc_ptr(item->bag);
        themer_read_class_name(item->key, item->keyClass,
                               sizeof(item->keyClass));
        themer_read_remote_description(item->key, item->keyText,
                                       sizeof(item->keyText));
        uint64_t images = item->bagKnown &&
            r_responds_main(item->bag, "images")
            ? r_msg2_main(item->bag, "images", 0, 0, 0, 0) : 0;
        item->imageArrayKnown = r_is_objc_ptr(images);
        item->imageCountKnown = item->imageArrayKnown &&
            r_responds_main(images, "count");
        int actualEntryCount = item->imageCountKnown
            ? (int)themer_remote_count(images) : 0;
        if (item->imageCountKnown && actualEntryCount >= 0) {
            snapshot->totalEntryCount += actualEntryCount;
        } else {
            snapshot->totalEntryCountKnown = false;
        }
        if (!remote_call_current_success() || actualEntryCount < 0) {
            return false;
        }
        item->entriesTruncated =
            actualEntryCount > THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP;
        item->entryCount = actualEntryCount <
            THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP
            ? actualEntryCount : THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP;
        for (int j = 0; j < item->entryCount &&
             remote_call_current_success(); j++) {
            ThemerIconServicesLabSnapshotEntry *entry = &item->entries[j];
            entry->image = r_msg2_main(images, "objectAtIndex:",
                                       (uint64_t)j, 0, 0, 0);
            entry->geometryKnown =
                themer_iconservices_lab_read_image_geometry(
                    entry->image, &entry->width, &entry->height,
                    &entry->scale);
        }
    }
    return remote_call_current_success();
}

static const ThemerIconServicesLabSnapshotKey *
themer_iconservices_lab_snapshot_find_key(
    const ThemerIconServicesLabTopologySnapshot *snapshot,
    const ThemerIconServicesLabSnapshotKey *needle)
{
    if (!snapshot || !needle) return NULL;
    for (int i = 0; i < snapshot->keyCount; i++) {
        const ThemerIconServicesLabSnapshotKey *candidate =
            &snapshot->keys[i];
        if (candidate->key == needle->key ||
            (needle->keyText[0] && candidate->keyText[0] &&
             strcmp(candidate->keyText, needle->keyText) == 0)) {
            return candidate;
        }
    }
    return NULL;
}

static void themer_iconservices_lab_log_topology_delta(
    const char *fromPhase,
    const ThemerIconServicesLabTopologySnapshot *from,
    const char *toPhase,
    const ThemerIconServicesLabTopologySnapshot *to)
{
    if (!fromPhase || !toPhase || !from || !to) return;
    bool changed = from->captured != to->captured ||
        from->dictionary != to->dictionary ||
        from->dictionaryCount != to->dictionaryCount ||
        from->keyCount != to->keyCount ||
        from->keysTruncated != to->keysTruncated;
    for (int i = 0; i < from->keyCount; i++) {
        const ThemerIconServicesLabSnapshotKey *before = &from->keys[i];
        const ThemerIconServicesLabSnapshotKey *after =
            themer_iconservices_lab_snapshot_find_key(to, before);
        bool keyChanged = !after || before->bag != after->bag ||
            before->entryCount != after->entryCount ||
            before->entriesTruncated != after->entriesTruncated;
        int compareCount = after && before->entryCount < after->entryCount
            ? before->entryCount : (after ? after->entryCount : 0);
        for (int j = 0; j < compareCount; j++) {
            const ThemerIconServicesLabSnapshotEntry *a = &before->entries[j];
            const ThemerIconServicesLabSnapshotEntry *b = &after->entries[j];
            double dw = a->width - b->width;
            double dh = a->height - b->height;
            double ds = a->scale - b->scale;
            if (dw < 0.0) dw = -dw;
            if (dh < 0.0) dh = -dh;
            if (ds < 0.0) ds = -ds;
            if (a->image != b->image ||
                a->geometryKnown != b->geometryKnown ||
                dw >= 0.01 || dh >= 0.01 || ds >= 0.01) {
                keyChanged = true;
            }
        }
        changed = changed || keyChanged;
        printf("[ICONSERVICES_LAB] bag-topology-delta-key "
               "from=%s to=%s key=\"%s\" beforeBag=0x%llx "
               "afterBag=0x%llx beforeEntries=%d afterEntries=%d "
               "changed=%d\n",
               fromPhase,
               toPhase,
               before->keyText,
               (unsigned long long)before->bag,
               (unsigned long long)(after ? after->bag : 0),
               before->entryCount,
               after ? after->entryCount : 0,
               keyChanged);
    }
    for (int i = 0; i < to->keyCount; i++) {
        if (!themer_iconservices_lab_snapshot_find_key(from, &to->keys[i])) {
            changed = true;
        }
    }
    int changedState = !from->captured && !to->captured
        ? -1 : (changed ? 1 : 0);
    printf("[ICONSERVICES_LAB] bag-topology-delta from=%s to=%s "
           "beforeDictionary=0x%llx afterDictionary=0x%llx "
           "beforeCount=%d afterCount=%d beforeKeys=%d afterKeys=%d "
           "observable=%d changed=%d\n",
           fromPhase,
           toPhase,
           (unsigned long long)from->dictionary,
           (unsigned long long)to->dictionary,
           from->dictionaryCount,
           to->dictionaryCount,
           from->keyCount,
           to->keyCount,
           from->captured || to->captured,
           changedState);
}

static void themer_iconservices_lab_append_trace_text(
    char *out,
    size_t outLen,
    size_t *used,
    const char *text)
{
    if (!out || outLen == 0 || !used || *used >= outLen || !text) return;
    size_t textLen = strlen(text);
    size_t available = outLen - *used;
    size_t copyLen = textLen < available - 1 ? textLen : available - 1;
    if (copyLen > 0) memcpy(out + *used, text, copyLen);
    *used += copyLen;
    out[*used] = '\0';
}

static bool themer_iconservices_lab_topology_fingerprint(
    const ThemerIconServicesLabTopologySnapshot *snapshot,
    char *out,
    size_t outLen)
{
    if (!snapshot || !out || outLen == 0) return false;
    out[0] = '\0';
    size_t used = 0;
    char row[512] = {0};
    snprintf(row, sizeof(row),
             "captured=%d;dictionaryCount=%d;keyCount=%d;keysTruncated=%d",
             snapshot->captured,
             snapshot->dictionaryCount,
             snapshot->keyCount,
             snapshot->keysTruncated);
    themer_iconservices_lab_append_trace_text(out, outLen, &used, row);
    for (int i = 0; i < snapshot->keyCount; i++) {
        const ThemerIconServicesLabSnapshotKey *key = &snapshot->keys[i];
        snprintf(row, sizeof(row),
                 ";key%d=%s/%s/entries=%d/truncated=%d",
                 i,
                 key->keyClass[0] ? key->keyClass : "-",
                 key->keyText[0] ? key->keyText : "-",
                 key->entryCount,
                 key->entriesTruncated);
        themer_iconservices_lab_append_trace_text(out, outLen, &used, row);
        for (int j = 0; j < key->entryCount; j++) {
            const ThemerIconServicesLabSnapshotEntry *entry = &key->entries[j];
            snprintf(row, sizeof(row),
                     "/entry%d=%d:%.3fx%.3f@%.3f",
                     j,
                     entry->geometryKnown,
                     entry->width,
                     entry->height,
                     entry->scale);
            themer_iconservices_lab_append_trace_text(
                out, outLen, &used, row);
        }
    }
    return used > 0 && used < outLen - 1;
}

// Materialization uses a stricter contract than the read-only lab.  The lab
// intentionally tolerates an unavailable bag as an observation; a rollback
// cannot do that because a missing getter result could make us overwrite a
// live cache with an incomplete reconstruction.  Keep this validator local to
// the stock-68 path so the legacy topology trace retains its old semantics.
static bool themer_stock68_topology_complete(
    const ThemerIconServicesLabTopologySnapshot *snapshot,
    const char *phase)
{
    if (!snapshot || !snapshot->captured ||
        !snapshot->keyArrayKnown || !snapshot->dictionaryCountKnown ||
        !snapshot->keyCountKnown || !snapshot->actualKeyCountKnown ||
        !snapshot->totalEntryCountKnown || snapshot->keysTruncated ||
        snapshot->dictionaryCount < 0 ||
        snapshot->dictionaryCount > THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP ||
        snapshot->keyCount < 0 ||
        snapshot->keyCount > THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP ||
        snapshot->actualKeyCount < 0 ||
        snapshot->dictionaryCount != snapshot->keyCount ||
        snapshot->actualKeyCount != snapshot->keyCount ||
        snapshot->totalEntryCount < 0) {
        printf("[ICONSERVICES_MATERIALIZE] strict-snapshot phase=%s "
               "complete=0 captured=%d keyArray=%d dictionaryCount=%d "
               "keyCount=%d truncated=%d\n",
               phase ?: "-",
               snapshot ? snapshot->captured : 0,
               snapshot ? snapshot->keyArrayKnown : 0,
               snapshot ? snapshot->dictionaryCount : 0,
               snapshot ? snapshot->keyCount : 0,
               snapshot ? snapshot->keysTruncated : 0);
        return false;
    }
    for (int i = 0; i < snapshot->keyCount; i++) {
        const ThemerIconServicesLabSnapshotKey *key = &snapshot->keys[i];
        if (!r_is_objc_ptr(key->key) || !key->keyText[0] ||
            !key->bagKnown || !r_is_objc_ptr(key->bag) ||
            !key->imageArrayKnown || !key->imageCountKnown ||
            key->entriesTruncated) {
            printf("[ICONSERVICES_MATERIALIZE] strict-snapshot phase=%s "
                   "complete=0 keyIndex=%d key=0x%llx/%s bag=0x%llx "
                   "bagKnown=%d imageArray=%d imageCount=%d entries=%d "
                   "truncated=%d\n",
                   phase ?: "-", i,
                   (unsigned long long)key->key,
                   key->keyText[0] ? key->keyText : "-",
                   (unsigned long long)key->bag,
                   key->bagKnown,
                   key->imageArrayKnown,
                   key->imageCountKnown,
                   key->entryCount,
                   key->entriesTruncated);
            return false;
        }
        for (int j = 0; j < key->entryCount; j++) {
            const ThemerIconServicesLabSnapshotEntry *entry =
                &key->entries[j];
            if (!r_is_objc_ptr(entry->image) || !entry->geometryKnown) {
                printf("[ICONSERVICES_MATERIALIZE] strict-snapshot phase=%s "
                       "complete=0 keyIndex=%d entryIndex=%d image=0x%llx "
                       "geometry=%d\n",
                       phase ?: "-", i, j,
                       (unsigned long long)entry->image,
                       entry->geometryKnown);
                return false;
            }
        }
    }
    return true;
}

static bool themer_stock68_capture_strict_topology(
    uint64_t cache,
    const char *phase,
    ThemerIconServicesLabTopologySnapshot *snapshot)
{
    bool captured = themer_iconservices_lab_capture_topology(
        cache, phase, snapshot);
    if (!captured) return false;
    return themer_stock68_topology_complete(snapshot, phase) &&
        remote_call_current_success();
}

static bool themer_stock68_capture_strict_dictionary(
    uint64_t dictionary,
    const char *phase,
    ThemerIconServicesLabTopologySnapshot *snapshot)
{
    bool captured = themer_iconservices_lab_capture_topology_from_dictionary(
        dictionary, phase, snapshot);
    if (!captured) return false;
    return themer_stock68_topology_complete(snapshot, phase) &&
        remote_call_current_success();
}

static bool themer_stock68_strict_fingerprint(
    const ThemerIconServicesLabTopologySnapshot *snapshot,
    char *out,
    size_t outLen)
{
    if (out && outLen) out[0] = '\0';
    if (!snapshot || !out || outLen < 2 ||
        !themer_stock68_topology_complete(snapshot, "fingerprint")) {
        return false;
    }

    // allKeys ordering is not a stable contract. Sort by the remote key's
    // exact textual identity, then by pointer for the impossible duplicate
    // text case, while preserving each bag's image-array order.
    int order[THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP] = {0};
    for (int i = 0; i < snapshot->keyCount; i++) order[i] = i;
    for (int i = 1; i < snapshot->keyCount; i++) {
        int value = order[i];
        int j = i;
        while (j > 0) {
            const ThemerIconServicesLabSnapshotKey *left =
                &snapshot->keys[order[j - 1]];
            const ThemerIconServicesLabSnapshotKey *right =
                &snapshot->keys[value];
            int comparison = strcmp(left->keyText, right->keyText);
            if (comparison < 0 ||
                (comparison == 0 && left->key <= right->key)) {
                break;
            }
            order[j] = order[j - 1];
            j--;
        }
        order[j] = value;
    }

    size_t used = 0;
    char row[640] = {0};
    snprintf(row, sizeof(row),
             "captured=%d;dictionary=0x%016llx;dictionaryCount=%d;"
             "dictionaryCountKnown=%d;keyCount=%d;keyArray=%d;"
             "keyCountKnown=%d;keysTruncated=%d",
             snapshot->captured,
             (unsigned long long)snapshot->dictionary,
             snapshot->dictionaryCount,
             snapshot->dictionaryCountKnown,
             snapshot->keyCount,
             snapshot->keyArrayKnown,
             snapshot->keyCountKnown,
             snapshot->keysTruncated);
    themer_iconservices_lab_append_trace_text(out, outLen, &used, row);
    for (int sorted = 0; sorted < snapshot->keyCount; sorted++) {
        const ThemerIconServicesLabSnapshotKey *key =
            &snapshot->keys[order[sorted]];
        snprintf(row, sizeof(row),
                 ";key=%016llx/%s/%s;bag=%016llx;bagKnown=%d;"
                 "imageArray=%d;imageCount=%d;entryCount=%d;"
                 "entriesTruncated=%d",
                 (unsigned long long)key->key,
                 key->keyClass[0] ? key->keyClass : "-",
                 key->keyText,
                 (unsigned long long)key->bag,
                 key->bagKnown,
                 key->imageArrayKnown,
                 key->imageCountKnown,
                 key->entryCount,
                 key->entriesTruncated);
        themer_iconservices_lab_append_trace_text(out, outLen, &used, row);
        for (int j = 0; j < key->entryCount; j++) {
            const ThemerIconServicesLabSnapshotEntry *entry =
                &key->entries[j];
            snprintf(row, sizeof(row),
                     ";entry=%016llx/%d/%.17g/%.17g/%.17g",
                     (unsigned long long)entry->image,
                     entry->geometryKnown,
                     entry->width,
                     entry->height,
                     entry->scale);
            themer_iconservices_lab_append_trace_text(
                out, outLen, &used, row);
        }
    }
    return used > 0 && used < outLen - 1;
}

static const ThemerIconServicesLabSnapshotKey *
themer_iconservices_lab_snapshot_key_for_text(
    const ThemerIconServicesLabTopologySnapshot *snapshot,
    const char *keyText)
{
    if (!snapshot || !keyText || !keyText[0]) return NULL;
    for (int i = 0; i < snapshot->keyCount; i++) {
        if (strcmp(snapshot->keys[i].keyText, keyText) == 0) {
            return &snapshot->keys[i];
        }
    }
    return NULL;
}

static bool themer_iconservices_lab_snapshot_has_size(
    const ThemerIconServicesLabSnapshotKey *key,
    double width,
    double height,
    double scale)
{
    if (!key) return false;
    for (int i = 0; i < key->entryCount; i++) {
        const ThemerIconServicesLabSnapshotEntry *entry = &key->entries[i];
        double dw = entry->width - width;
        double dh = entry->height - height;
        double ds = entry->scale - scale;
        if (dw < 0.0) dw = -dw;
        if (dh < 0.0) dh = -dh;
        if (ds < 0.0) ds = -ds;
        if (entry->geometryKnown && dw < 0.01 && dh < 0.01 && ds < 0.01) {
            return true;
        }
    }
    return false;
}

typedef struct {
    uint8_t *bytes;
    size_t objectLength;
    size_t capturedLength;
    bool truncated;
} ThemerIconServicesLabDataCapture;

static void themer_iconservices_lab_free_data_capture(
    ThemerIconServicesLabDataCapture *capture);
static bool themer_iconservices_lab_capture_nsdata(
    uint64_t data,
    size_t cap,
    ThemerIconServicesLabDataCapture *capture);
static void themer_iconservices_lab_hex_bytes(
    const uint8_t *bytes,
    size_t length,
    char *output,
    size_t outputLength);
static bool themer_iconservices_lab_digest(
    const char *symbol,
    const uint8_t *bytes,
    size_t length,
    uint8_t *digest);
static uint64_t themer_iconservices_lab_retained_getter(
    uint64_t object,
    const char *selector);
static bool themer_iconservices_lab_sizes_match(
    double firstWidth,
    double firstHeight,
    double secondWidth,
    double secondHeight);

#define THEMER_RECORD_DECODER_MAX_ITEMS 16
#define THEMER_RECORD_DECODER_MAX_NODES 32
#define THEMER_RECORD_DECODER_MAX_DEPTH 2
#define THEMER_RECORD_DECODER_MAX_SCALAR_BYTES 512
#define THEMER_RECORD_DECODER_MAX_METADATA 64
#define THEMER_RECORD_RUNTIME_MAX_ANCESTRY 8
#define THEMER_RECORD_BLOB_CAPTURE_CAP 4096
#define THEMER_RECORD_BLOB_HEX_CAP 512

typedef enum {
    ThemerRecordFamilyUnknown = 0,
    ThemerRecordFamilyUUID,
    ThemerRecordFamilyString,
    ThemerRecordFamilyData,
    ThemerRecordFamilyNumber,
    ThemerRecordFamilyArray,
    ThemerRecordFamilySet,
    ThemerRecordFamilyDictionary,
} ThemerRecordFamily;

typedef struct {
    uint64_t object;
    uint64_t classObject;
    char className[96];
    char superclassNames[THEMER_RECORD_RUNTIME_MAX_ANCESTRY][96];
    char methodNames[THEMER_RECORD_DECODER_MAX_METADATA][96];
    char methodTypes[THEMER_RECORD_DECODER_MAX_METADATA][96];
    int methodCount;
    int metadataCount;
    bool metadataTruncated;
    bool transportClean;
} ThemerRecordRuntimeSurface;

typedef struct {
    ThemerIconServicesLabDataCapture capture;
    bool captured;
    unsigned dataLeafCount;
    char sha256[65];
    char prefixHex[129];
    char hex[THEMER_RECORD_BLOB_HEX_CAP * 2 + 1];
    char format[96];
} ThemerRecordBlobObservation;

typedef struct {
    int depth;
    int nodes;
    int metadata;
    bool truncated;
    bool malformed;
    bool unsupported;
    bool transportFailed;
    ThemerRecordBlobObservation *firstBlob;
} ThemerRecordDecoderContext;

static bool themer_iconservices_lab_parse_uuid_text(
    const char *text, uint8_t output[16]);

static bool themer_record_uuid_text_at(const uint8_t *bytes, size_t length,
                                       size_t offset, char output[37])
{
    if (!bytes || !output || offset > length || length - offset < 36) return false;
    char text[37] = {0};
    memcpy(text, bytes + offset, 36);
    uint8_t ignored[16] = {0};
    if (!themer_iconservices_lab_parse_uuid_text(text, ignored)) return false;
    snprintf(output, 37, "%s", text);
    return true;
}

static void themer_record_uuid_hex(const uint8_t bytes[16], char output[37])
{
    snprintf(output, 37,
             "%02x%02x%02x%02x-%02x%02x-%02x%02x-"
             "%02x%02x-%02x%02x%02x%02x%02x%02x",
             bytes[0], bytes[1], bytes[2], bytes[3], bytes[4], bytes[5],
             bytes[6], bytes[7], bytes[8], bytes[9], bytes[10], bytes[11],
             bytes[12], bytes[13], bytes[14], bytes[15]);
}

static void themer_record_plist_summary(id object, int depth, int *nodes,
                                        char *out, size_t outLength)
{
    if (!object || !nodes || !out || !outLength || depth > 3 || *nodes >= 32) return;
    (*nodes)++;
    size_t used = strlen(out);
    if (used >= outLength - 1) return;
    if ([object isKindOfClass:NSString.class]) {
        snprintf(out + used, outLength - used, "string(%lu)",
                 (unsigned long)[(NSString *)object length]);
    } else if ([object isKindOfClass:NSData.class]) {
        snprintf(out + used, outLength - used, "data(%lu)",
                 (unsigned long)[(NSData *)object length]);
    } else if ([object isKindOfClass:NSNumber.class]) {
        snprintf(out + used, outLength - used, "number(%s)",
                 [(NSNumber *)object stringValue].UTF8String ?: "?");
    } else if ([object isKindOfClass:NSArray.class]) {
        NSArray *array = object;
        snprintf(out + used, outLength - used, "array(%lu)[", (unsigned long)array.count);
        for (NSUInteger i = 0; i < array.count && i < 8 && *nodes < 32; i++) {
            if (i) strncat(out, ",", outLength - strlen(out) - 1);
            themer_record_plist_summary(array[i], depth + 1, nodes, out, outLength);
        }
        strncat(out, "]", outLength - strlen(out) - 1);
    } else if ([object isKindOfClass:NSDictionary.class]) {
        NSDictionary *dictionary = object;
        snprintf(out + used, outLength - used, "dictionary(%lu){", (unsigned long)dictionary.count);
        NSUInteger item = 0;
        for (id key in dictionary) {
            if (item++ >= 8 || *nodes >= 32) break;
            if (item > 1) strncat(out, ",", outLength - strlen(out) - 1);
            if ([key isKindOfClass:NSString.class]) {
                char keyText[48] = {0};
                snprintf(keyText, sizeof(keyText), "%s", [(NSString *)key UTF8String] ?: "?");
                strncat(out, keyText, outLength - strlen(out) - 1);
            } else {
                strncat(out, "key", outLength - strlen(out) - 1);
            }
            strncat(out, ":", outLength - strlen(out) - 1);
            themer_record_plist_summary(dictionary[key], depth + 1, nodes, out, outLength);
        }
        strncat(out, "}", outLength - strlen(out) - 1);
    } else {
        strncat(out, "other", outLength - strlen(out) - 1);
    }
}

static void themer_record_observe_blob(ThemerRecordBlobObservation *blob)
{
    if (!blob || !blob->captured) return;
    const uint8_t *bytes = blob->capture.bytes;
    size_t length = blob->capture.capturedLength;
    uint8_t digest[32] = {0};
    if (length && themer_iconservices_lab_digest("CC_SHA256", bytes, length, digest)) {
        themer_iconservices_lab_hex_bytes(digest, sizeof(digest), blob->sha256,
                                          sizeof(blob->sha256));
    }
    themer_iconservices_lab_hex_bytes(bytes, length < 64 ? length : 64,
                                      blob->prefixHex, sizeof(blob->prefixHex));
    themer_iconservices_lab_hex_bytes(bytes,
                                      length < THEMER_RECORD_BLOB_HEX_CAP ? length : THEMER_RECORD_BLOB_HEX_CAP,
                                      blob->hex, sizeof(blob->hex));
    snprintf(blob->format, sizeof(blob->format), "opaque");
    if (length == 16) {
        char uuid[37] = {0};
        themer_record_uuid_hex(bytes, uuid);
        snprintf(blob->format, sizeof(blob->format), "binary-uuid-candidate:%s", uuid);
    } else if (length >= 8 && memcmp(bytes, "bplist00", 8) == 0) {
        snprintf(blob->format, sizeof(blob->format), "bplist00");
    } else if (length >= 5 && memcmp(bytes, "<?xml", 5) == 0) {
        snprintf(blob->format, sizeof(blob->format), "xml-plist");
    } else {
        bool printable = length > 0;
        for (size_t i = 0; i < length; i++) {
            if (!(bytes[i] == '\n' || bytes[i] == '\r' || bytes[i] == '\t' ||
                  (bytes[i] >= 0x20 && bytes[i] < 0x7f))) { printable = false; break; }
        }
        if (printable) {
            char text[37] = {0};
            bool uuid = length == 36 && themer_record_uuid_text_at(bytes, length, 0, text);
            snprintf(blob->format, sizeof(blob->format), uuid ? "uuid-text-candidate:%s" : "printable-utf8", uuid ? text : "");
        }
    }
    if (strncmp(blob->format, "bplist00", 8) == 0 ||
        strncmp(blob->format, "xml-plist", 9) == 0) {
        NSData *localData = [NSData dataWithBytes:bytes length:length];
        NSError *error = nil;
        id plist = [NSPropertyListSerialization propertyListWithData:localData
            options:NSPropertyListImmutable format:NULL error:&error];
        char summary[384] = {0}; int nodes = 0;
        if (plist) themer_record_plist_summary(plist, 0, &nodes, summary, sizeof(summary));
        snprintf(blob->format, sizeof(blob->format), "%s:%s",
                 strncmp(blob->format, "bplist00", 8) == 0 ? "bplist" : "xml",
                 plist ? summary : "parse-failed");
    }
    char canonical[37] = {0};
    for (size_t i = 0; !canonical[0] && i + 36 <= length; i++) {
        (void)themer_record_uuid_text_at(bytes, length, i, canonical);
    }
    if (canonical[0]) {
        printf("[ICONSERVICES_LAB] record-identifiers-blob uuid-text-candidate=%s candidateOnly=1\n", canonical);
    }
    for (size_t i = 0; i + 16 <= length && i < 256; i += 16) {
        char candidate[37] = {0};
        themer_record_uuid_hex(bytes + i, candidate);
        printf("[ICONSERVICES_LAB] record-identifiers-blob aligned-uuid-candidate=%s offset=%zu candidateOnly=1\n", candidate, i);
    }
    printf("[ICONSERVICES_LAB] record-identifiers-blob total=%zu captured=%zu truncated=%d sha256=%s prefix=%s hex=%s format=%s\n",
           blob->capture.objectLength, blob->capture.capturedLength,
           blob->capture.truncated, blob->sha256[0] ? blob->sha256 : "-",
           blob->prefixHex, blob->hex, blob->format);
}

static bool themer_record_runtime_discover(
    uint64_t object,
    ThemerRecordRuntimeSurface *surface)
{
    if (!surface) return false;
    memset(surface, 0, sizeof(*surface));
    surface->object = object;
    if (!r_is_objc_ptr(object) || !remote_call_current_success()) {
        surface->transportClean = remote_call_current_success();
        return false;
    }
    surface->classObject = r_dlsym_call(
        R_TIMEOUT, "object_getClass", object, 0, 0, 0, 0, 0, 0, 0);
    if (!r_is_objc_ptr(surface->classObject)) return false;
    uint64_t cls = surface->classObject;
    for (int depth = 0; r_is_objc_ptr(cls) &&
         depth <= THEMER_RECORD_RUNTIME_MAX_ANCESTRY &&
         remote_call_current_success(); depth++) {
        uint64_t name = r_dlsym_call(
            R_TIMEOUT, "class_getName", cls, 0, 0, 0, 0, 0, 0, 0);
        char className[96] = {0};
        if (!name || !r_read_cstring(name, className, sizeof(className))) {
            surface->transportClean = remote_call_current_success();
            return false;
        }
        if (depth == 0) {
            snprintf(surface->className, sizeof(surface->className), "%s",
                     className);
        } else if (depth - 1 < THEMER_RECORD_RUNTIME_MAX_ANCESTRY) {
            snprintf(surface->superclassNames[depth - 1],
                     sizeof(surface->superclassNames[depth - 1]), "%s",
                     className);
        }
        cls = r_dlsym_call(
            R_TIMEOUT, "class_getSuperclass", cls, 0, 0, 0, 0, 0, 0, 0);
    }
    surface->transportClean = remote_call_current_success();
    if (!surface->className[0]) return false;
    // Foundation classes have thousands of methods on current devices.
    // Never enumerate them: after ancestry establishes a supported family,
    // resolve only the public selectors this bounded observer can use.
    bool supported = false;
    for (int i = 0; i < THEMER_RECORD_RUNTIME_MAX_ANCESTRY; i++) {
        const char *name = i == 0 ? surface->className :
            surface->superclassNames[i - 1];
        if (!name[0]) continue;
        supported = strcmp(name, "NSData") == 0 ||
            strcmp(name, "NSMutableData") == 0 ||
            strcmp(name, "NSArray") == 0 ||
            strcmp(name, "NSMutableArray") == 0 ||
            strcmp(name, "NSSet") == 0 || strcmp(name, "NSMutableSet") == 0 ||
            strcmp(name, "NSDictionary") == 0 ||
            strcmp(name, "NSMutableDictionary") == 0 ||
            strcmp(name, "NSString") == 0 || strcmp(name, "NSMutableString") == 0 ||
            strcmp(name, "NSNumber") == 0 || strcmp(name, "NSUUID") == 0;
        if (supported) break;
    }
    if (supported) {
        static const char *const selectors[] = {
            "getUUIDBytes:", "UTF8String", "length", "bytes",
            "longLongValue", "copy", "release", "count", "objectAtIndex:",
            "getObjects:count:", "getObjects:andKeys:count:",
        };
        for (size_t i = 0; i < sizeof(selectors) / sizeof(selectors[0]); i++) {
            uint64_t selector = r_sel(selectors[i]);
            uint64_t method = selector ? r_dlsym_call(
                R_TIMEOUT, "class_getInstanceMethod", surface->classObject,
                selector, 0, 0, 0, 0, 0, 0) : 0;
            uint64_t types = method ? r_dlsym_call(
                R_TIMEOUT, "method_getTypeEncoding", method,
                0, 0, 0, 0, 0, 0, 0) : 0;
            char type[96] = {0};
            if (types && !r_read_cstring(types, type, sizeof(type))) return false;
            if (surface->methodCount < THEMER_RECORD_DECODER_MAX_METADATA &&
                type[0]) {
                int index = surface->methodCount++;
                snprintf(surface->methodNames[index],
                         sizeof(surface->methodNames[index]), "%s", selectors[i]);
                snprintf(surface->methodTypes[index],
                         sizeof(surface->methodTypes[index]), "%s", type);
                surface->metadataCount++;
            }
        }
    }
    surface->transportClean = remote_call_current_success();
    printf("[ICONSERVICES_LAB] record-identifiers-runtime class=%s "
           "super=%s>%s metadata=%d/%d metadataTruncated=%d transport=%d\n",
           surface->className,
           surface->superclassNames[0][0] ? surface->superclassNames[0] : "-",
           surface->superclassNames[1][0] ? surface->superclassNames[1] : "-",
           surface->methodCount,
           surface->metadataCount,
           surface->metadataTruncated,
           surface->transportClean);
    return surface->transportClean;
}

static bool themer_record_runtime_method_exact(
    const ThemerRecordRuntimeSurface *surface,
    const char *selector,
    const char *expectedTypes)
{
    if (!surface || !selector || !expectedTypes) return false;
    for (int i = 0; i < surface->methodCount &&
         i < THEMER_RECORD_DECODER_MAX_METADATA; i++) {
        if (strcmp(surface->methodNames[i], selector) == 0) {
            bool accepted = strcmp(surface->methodTypes[i], expectedTypes) == 0;
            printf("[ICONSERVICES_LAB] record-identifiers-abi selector=%s observed=\"%s\" expected=\"%s\" accepted=%d invoked=0\n",
                   selector, surface->methodTypes[i], expectedTypes, accepted);
            return accepted;
        }
    }
    printf("[ICONSERVICES_LAB] record-identifiers-abi selector=%s observed=\"-\" expected=\"%s\" accepted=0 invoked=0\n",
           selector, expectedTypes);
    return false;
}

static bool themer_record_runtime_method_one_of(
    const ThemerRecordRuntimeSurface *surface, const char *selector,
    const char *first, const char *second)
{
    if (!surface || !selector || !first || !second) return false;
    for (int i = 0; i < surface->methodCount; i++) {
        if (strcmp(surface->methodNames[i], selector) == 0) {
            bool accepted = strcmp(surface->methodTypes[i], first) == 0 ||
                strcmp(surface->methodTypes[i], second) == 0;
            printf("[ICONSERVICES_LAB] record-identifiers-abi selector=%s observed=\"%s\" expected=\"%s|%s\" accepted=%d invoked=0\n",
                   selector, surface->methodTypes[i], first, second, accepted);
            return accepted;
        }
    }
    printf("[ICONSERVICES_LAB] record-identifiers-abi selector=%s observed=\"-\" expected=\"%s|%s\" accepted=0 invoked=0\n",
           selector, first, second);
    return false;
}

static void themer_record_runtime_log_invoke(
    const ThemerRecordRuntimeSurface *surface, const char *selector,
    const char *accepted)
{
    const char *observed = "-";
    if (surface && selector) for (int i = 0; i < surface->methodCount; i++) {
        if (strcmp(surface->methodNames[i], selector) == 0) {
            observed = surface->methodTypes[i]; break;
        }
    }
    printf("[ICONSERVICES_LAB] record-identifiers-abi selector=%s observed=\"%s\" expected=\"%s\" accepted=1 invoked=1\n",
           selector ?: "-", observed, accepted ?: "-");
}

static ThemerRecordFamily themer_record_family(
    const ThemerRecordRuntimeSurface *surface)
{
    if (!surface) return ThemerRecordFamilyUnknown;
    const char *names[THEMER_RECORD_RUNTIME_MAX_ANCESTRY + 1] = {0};
    names[0] = surface->className;
    for (int i = 0; i < THEMER_RECORD_RUNTIME_MAX_ANCESTRY; i++) {
        names[i + 1] = surface->superclassNames[i];
    }
    for (size_t i = 0; i < sizeof(names) / sizeof(names[0]); i++) {
        const char *name = names[i];
        if (!name || !name[0]) continue;
        if (strcmp(name, "NSUUID") == 0 ||
            strcmp(name, "__NSConcreteUUID") == 0) {
            return ThemerRecordFamilyUUID;
        }
        if (strcmp(name, "NSString") == 0 ||
            strcmp(name, "NSMutableString") == 0 ||
            strcmp(name, "__NSCFString") == 0 ||
            strcmp(name, "__NSCFConstantString") == 0 ||
            strcmp(name, "NSTaggedPointerString") == 0 ||
            strcmp(name, "NSConstantString") == 0) {
            return ThemerRecordFamilyString;
        }
        if (strcmp(name, "NSData") == 0 ||
            strcmp(name, "NSMutableData") == 0 ||
            strcmp(name, "__NSCFData") == 0 ||
            strcmp(name, "NSConcreteData") == 0) {
            return ThemerRecordFamilyData;
        }
        if (strcmp(name, "NSNumber") == 0 ||
            strcmp(name, "__NSCFNumber") == 0 ||
            strcmp(name, "__NSCFBoolean") == 0 ||
            strcmp(name, "NSCFBoolean") == 0 ||
            strcmp(name, "NSDecimalNumber") == 0) {
            return ThemerRecordFamilyNumber;
        }
        if (strcmp(name, "NSArray") == 0 ||
            strcmp(name, "NSMutableArray") == 0 ||
            strcmp(name, "__NSArrayI") == 0 ||
            strcmp(name, "__NSArrayM") == 0 ||
            strcmp(name, "__NSSingleObjectArrayI") == 0 ||
            strcmp(name, "__NSFrozenArrayM") == 0 ||
            strcmp(name, "NSConcreteArray") == 0) {
            return ThemerRecordFamilyArray;
        }
        if (strcmp(name, "NSSet") == 0 ||
            strcmp(name, "NSMutableSet") == 0 ||
            strcmp(name, "__NSSetI") == 0 ||
            strcmp(name, "__NSSetM") == 0 ||
            strcmp(name, "NSConcreteSet") == 0) {
            return ThemerRecordFamilySet;
        }
        if (strcmp(name, "NSDictionary") == 0 ||
            strcmp(name, "NSMutableDictionary") == 0 ||
            strcmp(name, "__NSDictionaryI") == 0 ||
            strcmp(name, "__NSDictionaryM") == 0 ||
            strcmp(name, "NSConcreteDictionary") == 0) {
            return ThemerRecordFamilyDictionary;
        }
    }
    return ThemerRecordFamilyUnknown;
}

static const char *themer_record_family_name(ThemerRecordFamily family)
{
    switch (family) {
        case ThemerRecordFamilyUUID: return "NSUUID";
        case ThemerRecordFamilyString: return "NSString";
        case ThemerRecordFamilyData: return "NSData";
        case ThemerRecordFamilyNumber: return "NSNumber";
        case ThemerRecordFamilyArray: return "NSArray";
        case ThemerRecordFamilySet: return "NSSet";
        case ThemerRecordFamilyDictionary: return "NSDictionary";
        case ThemerRecordFamilyUnknown: return "unsupported";
    }
    return "unsupported";
}

static bool themer_record_decode_object(
    uint64_t object,
    ThemerRecordDecoderContext *context,
    int depth);

static bool themer_record_decode_string_value(
    uint64_t object,
    const ThemerRecordRuntimeSurface *surface,
    char *out,
    size_t outLength,
    ThemerRecordDecoderContext *context)
{
    if (out && outLength) out[0] = '\0';
    if (!surface || !out || outLength == 0 ||
        !themer_record_runtime_method_exact(surface, "UTF8String",
                                            "@16@0:8")) {
        if (context) context->malformed = true;
        return false;
    }
    themer_record_runtime_log_invoke(surface, "UTF8String", "@16@0:8");
    uint64_t value = r_msg2_main(object, "UTF8String", 0, 0, 0, 0);
    if (!remote_call_current_success() || !value ||
        !r_read_cstring(value, out, outLength)) {
        if (context) context->transportFailed = !remote_call_current_success();
        return false;
    }
    for (char *p = out; *p; p++) {
        if (*p == '\n' || *p == '\r' || *p == '\t' || *p == '"') *p = ' ';
    }
    return true;
}

static void themer_record_release_snapshot(
    uint64_t snapshot,
    const ThemerRecordRuntimeSurface *surface,
    ThemerRecordDecoderContext *context)
{
    // -copy returns an owned object even when Foundation can return the same
    // immutable instance. Always balance that +1; the original object is
    // borrowed and is never released here.
    if (snapshot) {
        // Current Foundation images have been observed to expose either the
        // ordinary void encoding or the oneway-qualified spelling. Query the
        // concrete object's method type before every invocation; no broader
        // acceptance is implied by this ownership-only exception.
        if (!surface || !themer_record_runtime_method_one_of(
                surface, "release", "v16@0:8", "Vv16@0:8")) {
            if (context) context->malformed = true;
            return;
        }
        themer_record_runtime_log_invoke(
            surface, "release", "v16@0:8|Vv16@0:8");
        r_msg2(snapshot, "release", 0, 0, 0, 0);
        if (context && !remote_call_current_success()) {
            context->transportFailed = true;
        }
    }
}

static bool themer_record_decode_object(
    uint64_t object,
    ThemerRecordDecoderContext *context,
    int depth)
{
    if (!context || !r_is_objc_ptr(object) ||
        !remote_call_current_success()) {
        if (context) {
            context->malformed = true;
            context->transportFailed = !remote_call_current_success();
        }
        return false;
    }
    if (depth > THEMER_RECORD_DECODER_MAX_DEPTH ||
        context->nodes >= THEMER_RECORD_DECODER_MAX_NODES) {
        context->truncated = true;
        return false;
    }
    context->nodes++;
    ThemerRecordRuntimeSurface surface = {0};
    if (!themer_record_runtime_discover(object, &surface)) {
        context->malformed = true;
        context->transportFailed = !remote_call_current_success();
        return false;
    }
    context->metadata += surface.metadataCount;
    if (context->metadata > THEMER_RECORD_DECODER_MAX_METADATA) {
        context->truncated = true;
        return false;
    }
    ThemerRecordFamily family = themer_record_family(&surface);
    if (family == ThemerRecordFamilyUnknown) {
        context->unsupported = true;
        printf("[ICONSERVICES_LAB] record-identifiers-unsupported class=%s "
               "super=%s>%s metadata=%d/%d\n",
               surface.className,
               surface.superclassNames[0][0] ? surface.superclassNames[0] : "-",
               surface.superclassNames[1][0] ? surface.superclassNames[1] : "-",
               surface.methodCount,
               surface.metadataCount);
        return false;
    }
    if (family == ThemerRecordFamilyUUID) {
        if (!themer_record_runtime_method_exact(
                &surface, "getUUIDBytes:", "v24@0:8[16C]16")) {
            context->malformed = true;
            return false;
        }
        uint64_t uuidBuffer = r_dlsym_call(
            R_TIMEOUT, "malloc", 16, 0, 0, 0, 0, 0, 0, 0);
        uint8_t bytes[16] = {0};
        bool decoded = uuidBuffer && remote_write(uuidBuffer, bytes, 16);
        if (decoded) {
            themer_record_runtime_log_invoke(&surface, "getUUIDBytes:", "v24@0:8[16C]16");
            r_msg2_main(object, "getUUIDBytes:", uuidBuffer, 0, 0, 0);
            decoded = remote_call_current_success() &&
                remote_read(uuidBuffer, bytes, sizeof(bytes));
        }
        if (uuidBuffer && remote_call_current_success()) r_free(uuidBuffer);
        char value[37] = {0};
        if (decoded) {
            snprintf(value, sizeof(value),
                     "%02x%02x%02x%02x-%02x%02x-%02x%02x-"
                     "%02x%02x-%02x%02x%02x%02x%02x%02x",
                     bytes[0], bytes[1], bytes[2], bytes[3],
                     bytes[4], bytes[5], bytes[6], bytes[7],
                     bytes[8], bytes[9], bytes[10], bytes[11],
                     bytes[12], bytes[13], bytes[14], bytes[15]);
        } else {
            context->transportFailed = !remote_call_current_success();
        }
        printf("[ICONSERVICES_LAB] record-identifiers-node depth=%d "
               "class=%s value=uuid:%s decoded=%d\n",
               depth, surface.className, decoded ? value : "?", decoded);
        return decoded;
    }
    if (family == ThemerRecordFamilyString) {
        char value[256] = {0};
        bool decoded = themer_record_decode_string_value(
            object, &surface, value, sizeof(value), context);
        printf("[ICONSERVICES_LAB] record-identifiers-node depth=%d "
               "class=%s value=string:%s decoded=%d\n",
               depth, surface.className, decoded ? value : "?", decoded);
        return decoded;
    }
    if (family == ThemerRecordFamilyData) {
        bool lengthABI = themer_record_runtime_method_exact(
            &surface, "length", "Q16@0:8");
        if (!lengthABI) {
            context->malformed = true;
            return false;
        }
        themer_record_runtime_log_invoke(&surface, "length", "Q16@0:8");
        uint64_t length = r_msg2_main(object, "length", 0, 0, 0, 0);
        if (!remote_call_current_success() || length > SIZE_MAX) {
            context->transportFailed = !remote_call_current_success();
            context->malformed = !context->transportFailed;
            return false;
        }
        bool bytesABI = themer_record_runtime_method_one_of(
            &surface, "bytes", "^v16@0:8", "r^v16@0:8");
        if (!bytesABI) {
            context->malformed = true;
            return false;
        }
        ThemerRecordBlobObservation *blob = context->firstBlob;
        if (blob) blob->dataLeafCount++;
        if (blob && !blob->captured) {
            blob->capture.objectLength = (size_t)length;
            blob->capture.capturedLength = blob->capture.objectLength <
                THEMER_RECORD_BLOB_CAPTURE_CAP ? blob->capture.objectLength :
                THEMER_RECORD_BLOB_CAPTURE_CAP;
            blob->capture.truncated = blob->capture.capturedLength <
                blob->capture.objectLength;
            if (blob->capture.capturedLength) {
                themer_record_runtime_log_invoke(
                    &surface, "bytes", "^v16@0:8|r^v16@0:8");
                uint64_t bytes = r_msg2_main(object, "bytes", 0, 0, 0, 0);
                if (!bytes || !remote_call_current_success()) {
                    context->transportFailed = !remote_call_current_success();
                    context->malformed = !context->transportFailed;
                    return false;
                }
                blob->capture.bytes = malloc(blob->capture.capturedLength);
                if (!blob->capture.bytes || !remote_read(bytes, blob->capture.bytes,
                    blob->capture.capturedLength)) {
                    themer_iconservices_lab_free_data_capture(&blob->capture);
                    context->transportFailed = true;
                    return false;
                }
            }
            blob->captured = true;
            themer_record_observe_blob(blob);
            if (blob->capture.truncated) context->truncated = true;
        }
        printf("[ICONSERVICES_LAB] record-identifiers-node depth=%d class=%s "
               "value=data:%llu captured=%zu truncated=%d decoded=1\n",
               depth, surface.className, (unsigned long long)length,
               blob && blob->captured ? blob->capture.capturedLength : 0,
               blob && blob->captured ? blob->capture.truncated : 0);
        return true;
    }
    if (family == ThemerRecordFamilyNumber) {
        if (!themer_record_runtime_method_exact(
                &surface, "longLongValue", "q16@0:8")) {
            context->malformed = true;
            return false;
        }
        themer_record_runtime_log_invoke(&surface, "longLongValue", "q16@0:8");
        uint64_t bits = r_msg2_main(object, "longLongValue", 0, 0, 0, 0);
        printf("[ICONSERVICES_LAB] record-identifiers-node depth=%d "
               "class=%s value=number:%lld\n", depth, surface.className,
               (long long)bits);
        return remote_call_current_success();
    }
    if (depth >= THEMER_RECORD_DECODER_MAX_DEPTH) {
        context->truncated = true;
        return false;
    }

    // Copy first so mutable containers cannot change while the bounded walk
    // is reading them. The copy selector is public and exact-checked.
    uint64_t snapshot = 0;
    if (!themer_record_runtime_method_exact(&surface, "copy", "@16@0:8")) {
        context->malformed = true;
        return false;
    }
    themer_record_runtime_log_invoke(&surface, "copy", "@16@0:8");
    snapshot = r_msg2_main(object, "copy", 0, 0, 0, 0);
    if (!r_is_objc_ptr(snapshot) || !remote_call_current_success()) {
        context->malformed = true;
        context->transportFailed = !remote_call_current_success();
        return false;
    }
    ThemerRecordRuntimeSurface snapshotSurface = {0};
    if (!themer_record_runtime_discover(snapshot, &snapshotSurface)) {
        context->malformed = true;
        // The +1 copy is intentionally leaked when its concrete class cannot
        // be established. Messaging an unclassified object is less safe.
        return false;
    }
    if (themer_record_family(&snapshotSurface) != family) {
        context->malformed = true;
        return false;
    }
    bool countABI = themer_record_runtime_method_exact(
        &snapshotSurface, "count", "Q16@0:8");
    if (countABI) themer_record_runtime_log_invoke(&snapshotSurface, "count", "Q16@0:8");
    uint64_t count = countABI
        ? r_msg2_main(snapshot, "count", 0, 0, 0, 0) : 0;
    if (!countABI || !remote_call_current_success()) {
        context->malformed = true;
        context->transportFailed = !remote_call_current_success();
        themer_record_release_snapshot(snapshot, &snapshotSurface, context);
        return false;
    }
    if (count > THEMER_RECORD_DECODER_MAX_ITEMS) {
        context->truncated = true;
        themer_record_release_snapshot(snapshot, &snapshotSurface, context);
        return false;
    }
    bool decoded = true;
    if (family == ThemerRecordFamilyArray) {
        decoded = themer_record_runtime_method_exact(
            &snapshotSurface, "objectAtIndex:", "@24@0:8Q16");
        for (uint64_t i = 0; decoded && i < count; i++) {
            themer_record_runtime_log_invoke(&snapshotSurface, "objectAtIndex:", "@24@0:8Q16");
            uint64_t child = r_msg2_main(snapshot, "objectAtIndex:", i, 0, 0, 0);
            decoded = themer_record_decode_object(child, context, depth + 1);
        }
    } else if (family == ThemerRecordFamilySet) {
        decoded = themer_record_runtime_method_exact(
            &snapshotSurface, "getObjects:count:", "v32@0:8^@16Q24");
        uint64_t objects = decoded && count
            ? r_dlsym_call(R_TIMEOUT, "malloc", count * sizeof(uint64_t),
                           0, 0, 0, 0, 0, 0, 0)
            : 0;
        if (decoded && count && objects) {
            themer_record_runtime_log_invoke(&snapshotSurface, "getObjects:count:", "v32@0:8^@16Q24");
            r_msg2_main(snapshot, "getObjects:count:", objects, count, 0, 0);
            decoded = remote_call_current_success();
        } else if (count) {
            decoded = false;
            context->malformed = true;
        }
        for (uint64_t i = 0; decoded && i < count; i++) {
            uint64_t child = remote_read64(
                objects + (i * sizeof(uint64_t)));
            decoded = themer_record_decode_object(
                child, context, depth + 1);
        }
        if (objects && remote_call_current_success()) r_free(objects);
    } else if (family == ThemerRecordFamilyDictionary) {
        decoded = themer_record_runtime_method_exact(
            &snapshotSurface, "getObjects:andKeys:count:",
            "v40@0:8^@16^@24Q32");
        uint64_t objects = decoded && count
            ? r_dlsym_call(R_TIMEOUT, "malloc", count * sizeof(uint64_t),
                           0, 0, 0, 0, 0, 0, 0)
            : 0;
        uint64_t keys = decoded && count
            ? r_dlsym_call(R_TIMEOUT, "malloc", count * sizeof(uint64_t),
                           0, 0, 0, 0, 0, 0, 0)
            : 0;
        if (decoded && count && objects && keys) {
            themer_record_runtime_log_invoke(&snapshotSurface, "getObjects:andKeys:count:", "v40@0:8^@16^@24Q32");
            r_msg2_main(snapshot, "getObjects:andKeys:count:",
                        objects, keys, count, 0);
            decoded = remote_call_current_success();
        } else if (count) {
            decoded = false;
            context->malformed = true;
        }
        for (uint64_t i = 0; decoded && i < count; i++) {
            uint64_t key = remote_read64(keys + (i * sizeof(uint64_t)));
            uint64_t value = remote_read64(
                objects + (i * sizeof(uint64_t)));
            decoded = themer_record_decode_object(
                key, context, depth + 1) &&
                themer_record_decode_object(value, context, depth + 1);
        }
        if (objects && remote_call_current_success()) r_free(objects);
        if (keys && remote_call_current_success()) r_free(keys);
    } else {
        context->unsupported = true;
        decoded = false;
    }
    themer_record_release_snapshot(snapshot, &snapshotSurface, context);
    printf("[ICONSERVICES_LAB] record-identifiers-container depth=%d "
           "class=%s family=%s count=%llu decoded=%d\n",
           depth, surface.className, themer_record_family_name(family),
           (unsigned long long)count, decoded);
    return decoded && remote_call_current_success();
}

static ThemerSpotlightStock68RecordIdentifiersDecodeStatus
themer_iconservices_lab_decode_record_identifiers(
    uint64_t object,
    int *nodesOut,
    int *metadataOut,
    ThemerRecordBlobObservation *firstBlob)
{
    if (nodesOut) *nodesOut = 0;
    if (metadataOut) *metadataOut = 0;
    if (!object) {
        printf("[ICONSERVICES_LAB] record-identifiers-decode status=nil\n");
        return ThemerSpotlightStock68RecordIdentifiersDecodeNil;
    }
    ThemerRecordDecoderContext context = {0};
    context.firstBlob = firstBlob;
    bool decoded = themer_record_decode_object(object, &context, 0);
    if (nodesOut) *nodesOut = context.nodes;
    if (metadataOut) *metadataOut = context.metadata;
    ThemerSpotlightStock68RecordIdentifiersDecodeStatus status =
        context.transportFailed || !remote_call_current_success()
            ? ThemerSpotlightStock68RecordIdentifiersDecodeTransportFailed
        : context.truncated
            ? ThemerSpotlightStock68RecordIdentifiersDecodeTruncated
        : context.unsupported
            ? ThemerSpotlightStock68RecordIdentifiersDecodeUnsupportedClass
        : context.malformed || !decoded
            ? ThemerSpotlightStock68RecordIdentifiersDecodeMalformed
        : ThemerSpotlightStock68RecordIdentifiersDecodeDecoded;
    printf("[ICONSERVICES_LAB] record-identifiers-decode status=%d "
           "nodes=%d metadata=%d truncated=%d unsupported=%d malformed=%d "
           "transport=%d\n",
           status, context.nodes, context.metadata, context.truncated,
           context.unsupported, context.malformed, context.transportFailed);
    return status;
}

typedef enum {
    ThemerIconServicesLabTraceNoState = 0,
    ThemerIconServicesLabTraceUnchanged = 1,
    ThemerIconServicesLabTraceNew68 = 2,
    ThemerIconServicesLabTraceChangedWithout68 = 3,
    ThemerIconServicesLabTraceDiscarded = 4,
} ThemerIconServicesLabTraceResult;

static bool themer_iconservices_lab_method_types(uint64_t object,
                                                const char *selector,
                                                char *types,
                                                size_t typesLen);

static bool themer_iconservices_lab_descriptor_digest_text(
    uint64_t descriptor,
    char *out,
    size_t outLen)
{
    if (out && outLen) out[0] = '\0';
    if (!r_is_objc_ptr(descriptor) || !out || outLen == 0 ||
        !r_responds_main(descriptor, "digest")) {
        return false;
    }
    char types[192] = {0};
    if (!themer_iconservices_lab_method_types(
            descriptor, "digest", types, sizeof(types)) ||
        types[0] != '@') {
        return false;
    }
    uint64_t digest = r_msg2_main(descriptor, "digest", 0, 0, 0, 0);
    return remote_call_current_success() && r_is_objc_ptr(digest) &&
        themer_read_remote_description(digest, out, outLen);
}

static bool themer_iconservices_lab_trace_arm(
    const char *targetBundle,
    uint64_t descriptor,
    double scale,
    const ThemerIconServicesLabTopologySnapshot *baseline)
{
    if (!targetBundle || !targetBundle[0] || !r_is_objc_ptr(descriptor) ||
        scale < 1.0 || scale > 4.0 || !baseline || !baseline->captured ||
        !remote_call_current_success()) {
        return false;
    }
    char fingerprint[THEMER_ICONSERVICES_LAB_TRACE_TEXT_CAP] = {0};
    char digestText[160] = {0};
    bool fingerprintKnown = themer_iconservices_lab_topology_fingerprint(
        baseline, fingerprint, sizeof(fingerprint));
    bool digestKnown = themer_iconservices_lab_descriptor_digest_text(
        descriptor, digestText, sizeof(digestText));
    const ThemerIconServicesLabSnapshotKey *digestKey = digestKnown
        ? themer_iconservices_lab_snapshot_key_for_text(baseline, digestText)
        : NULL;
    bool baselineHas68 = themer_iconservices_lab_snapshot_has_size(
        digestKey, 68.0, 68.0, scale);

    uint64_t dictionaryClass = r_class("NSMutableDictionary");
    uint64_t alloc = r_is_objc_ptr(dictionaryClass)
        ? r_msg2(dictionaryClass, "alloc", 0, 0, 0, 0) : 0;
    uint64_t state = r_is_objc_ptr(alloc)
        ? r_msg2_main(alloc, "initWithCapacity:", 8, 0, 0, 0) : 0;
    uint64_t pidNumber = themer_spotlight_proof_number(
        (unsigned long long)remote_call_current_pid());
    uint64_t scaleNumber = themer_iconservices_lab_double_number(scale);
    uint64_t has68Number = themer_spotlight_proof_number(
        baselineHas68 ? 1 : 0);
    bool ready = fingerprintKnown && digestKnown && r_is_objc_ptr(state) &&
        r_is_objc_ptr(pidNumber) && r_is_objc_ptr(scaleNumber) &&
        r_is_objc_ptr(has68Number) &&
        themer_spotlight_dictionary_set_object(state, "pid", pidNumber) &&
        themer_spotlight_proof_state_set_string(
            state, "targetBundle", targetBundle) &&
        themer_spotlight_proof_state_set_string(
            state, "descriptorDigest", digestText) &&
        themer_spotlight_proof_state_set_string(
            state, "baselineFingerprint", fingerprint) &&
        themer_spotlight_dictionary_set_object(
            state, "descriptorScale", scaleNumber) &&
        themer_spotlight_dictionary_set_object(
            state, "baselineHas68", has68Number);
    bool committed = ready && themer_iconservices_lab_trace_commit(state);
    printf("[ICONSERVICES_LAB] materialization-trace armed=%d pid=%d "
           "target=%s digest=\"%s\" scale=%.2f baselineHas68=%d "
           "captured=%d dictionaryCount=%d keyCount=%d truncated=%d\n",
           committed,
           remote_call_current_pid(),
           targetBundle,
           digestKnown ? digestText : "-",
           scale,
           baselineHas68,
           baseline->captured,
           baseline->dictionaryCount,
           baseline->keyCount,
           baseline->keysTruncated);
    if (r_is_objc_ptr(state) && remote_call_current_success()) {
        r_msg2(state, "release", 0, 0, 0, 0);
    }
    return committed && remote_call_current_success();
}

static ThemerIconServicesLabTraceResult
themer_iconservices_lab_trace_follow_up(
    const char *targetBundle,
    const ThemerIconServicesLabTopologySnapshot *current)
{
    uint64_t state = themer_iconservices_lab_trace_state();
    if (!r_is_objc_ptr(state)) return ThemerIconServicesLabTraceNoState;
    uint64_t storedPid = 0;
    uint64_t baselineHas68Value = 0;
    double scale = 0.0;
    char storedBundle[192] = {0};
    char digestText[160] = {0};
    char baselineFingerprint[THEMER_ICONSERVICES_LAB_TRACE_TEXT_CAP] = {0};
    char stock40UUID[160] = {0};
    char stock40TokenHex[THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP * 2 + 1]
        = {0};
    char stock40DataSHA1[41] = {0};
    char stock40DataSHA256[65] = {0};
    bool stateKnown =
        themer_spotlight_proof_state_u64(state, "pid", &storedPid) &&
        themer_spotlight_proof_state_string(
            state, "targetBundle", storedBundle, sizeof(storedBundle)) &&
        themer_spotlight_proof_state_string(
            state, "descriptorDigest", digestText, sizeof(digestText)) &&
        themer_spotlight_proof_state_string(
            state, "baselineFingerprint", baselineFingerprint,
            sizeof(baselineFingerprint)) &&
        themer_iconservices_lab_state_double(
            state, "descriptorScale", &scale) &&
        themer_spotlight_proof_state_u64(
            state, "baselineHas68", &baselineHas68Value) &&
        themer_spotlight_proof_state_string(
            state, "stock40UUID", stock40UUID, sizeof(stock40UUID)) &&
        themer_spotlight_proof_state_string(
            state, "stock40TokenHex", stock40TokenHex,
            sizeof(stock40TokenHex)) &&
        themer_spotlight_proof_state_string(
            state, "stock40DataSHA1", stock40DataSHA1,
            sizeof(stock40DataSHA1)) &&
        themer_spotlight_proof_state_string(
            state, "stock40DataSHA256", stock40DataSHA256,
            sizeof(stock40DataSHA256));
    int currentPid = remote_call_current_pid();
    bool pidMatch = stateKnown && storedPid == (uint64_t)currentPid;
    bool bundleMatch = stateKnown && targetBundle && targetBundle[0] &&
        strcmp(storedBundle, targetBundle) == 0;
    if (!stateKnown || !pidMatch || !bundleMatch || !current) {
        printf("[ICONSERVICES_LAB] materialization-trace discarded "
               "stateKnown=%d statePid=%llu currentPid=%d pidMatch=%d "
               "storedTarget=%s currentTarget=%s bundleMatch=%d\n",
               stateKnown,
               (unsigned long long)storedPid,
               currentPid,
               pidMatch,
               storedBundle[0] ? storedBundle : "-",
               targetBundle && targetBundle[0] ? targetBundle : "-",
               bundleMatch);
        themer_iconservices_lab_trace_clear();
        return ThemerIconServicesLabTraceDiscarded;
    }

    char currentFingerprint[THEMER_ICONSERVICES_LAB_TRACE_TEXT_CAP] = {0};
    bool currentKnown = themer_iconservices_lab_topology_fingerprint(
        current, currentFingerprint, sizeof(currentFingerprint));
    bool changed = currentKnown &&
        strcmp(baselineFingerprint, currentFingerprint) != 0;
    const ThemerIconServicesLabSnapshotKey *digestKey =
        themer_iconservices_lab_snapshot_key_for_text(current, digestText);
    bool currentHas68 = themer_iconservices_lab_snapshot_has_size(
        digestKey, 68.0, 68.0, scale);
    bool new68 = currentHas68 && baselineHas68Value == 0;
    bool conclusive = currentKnown && !current->keysTruncated &&
        (!digestKey || !digestKey->entriesTruncated);
    ThemerIconServicesLabTraceResult result = new68 && conclusive
        ? ThemerIconServicesLabTraceNew68
        : (changed
            ? ThemerIconServicesLabTraceChangedWithout68
            : ThemerIconServicesLabTraceUnchanged);
    printf("[ICONSERVICES_LAB] materialization-trace follow-up pid=%d "
           "target=%s digest=\"%s\" scale=%.2f stateKnown=%d "
           "currentKnown=%d changed=%d baselineHas68=%llu "
           "currentHas68=%d new68=%d conclusive=%d result=%d "
           "captured=%d dictionaryCount=%d keyCount=%d truncated=%d\n",
           currentPid,
           targetBundle,
           digestText,
           scale,
           stateKnown,
           currentKnown,
           changed,
           (unsigned long long)baselineHas68Value,
           currentHas68,
           new68,
           conclusive,
           result,
           current->captured,
           current->dictionaryCount,
           current->keyCount,
           current->keysTruncated);
    if (digestKey) {
        for (int i = 0; i < digestKey->entryCount; i++) {
            const ThemerIconServicesLabSnapshotEntry *entry =
                &digestKey->entries[i];
            double scaleDelta = entry->scale - scale;
            if (scaleDelta < 0.0) scaleDelta = -scaleDelta;
            bool is68 = entry->geometryKnown &&
                entry->width > 67.99 && entry->width < 68.01 &&
                entry->height > 67.99 && entry->height < 68.01 &&
                scaleDelta < 0.01;
            printf("[ICONSERVICES_LAB] materialization-trace-entry "
                   "index=%d/%d image=0x%llx geometry=%d "
                   "size=%.1fx%.1f scale=%.2f is68=%d\n",
                   i,
                   digestKey->entryCount,
                   (unsigned long long)entry->image,
                   entry->geometryKnown,
                   entry->width,
                   entry->height,
                   entry->scale,
                   is68);
            if (is68) {
                themer_iconservices_lab_log_bag_image(
                    "materialization-follow-up-68", i, entry->image);
                ThemerIconServicesLabDataCapture dataCapture = {0};
                ThemerIconServicesLabDataCapture bitmapCapture = {0};
                ThemerIconServicesLabDataCapture tokenCapture = {0};
                uint64_t data = themer_iconservices_lab_retained_getter(
                    entry->image, "data");
                uint64_t bitmap = themer_iconservices_lab_retained_getter(
                    entry->image, "bitmapData");
                uint64_t uuid = themer_iconservices_lab_retained_getter(
                    entry->image, "uuid");
                uint64_t token = themer_iconservices_lab_retained_getter(
                    entry->image, "validationToken");
                bool dataCaptured = r_is_objc_ptr(data) &&
                    themer_iconservices_lab_capture_nsdata(
                        data, THEMER_ICONSERVICES_LAB_STOCK_COMPARE_DATA_CAP,
                        &dataCapture);
                bool bitmapCaptured = r_is_objc_ptr(bitmap) &&
                    themer_iconservices_lab_capture_nsdata(
                        bitmap, THEMER_ICONSERVICES_LAB_STOCK_COMPARE_DATA_CAP,
                        &bitmapCapture);
                bool tokenCaptured = r_is_objc_ptr(token) &&
                    themer_iconservices_lab_capture_nsdata(
                        token, THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP,
                        &tokenCapture);
                uint8_t dataSHA1[20] = {0};
                uint8_t dataSHA256[32] = {0};
                uint8_t bitmapSHA1[20] = {0};
                uint8_t bitmapSHA256[32] = {0};
                bool dataSHA1Known = dataCaptured && !dataCapture.truncated &&
                    dataCapture.capturedLength > 0 &&
                    themer_iconservices_lab_digest(
                        "CC_SHA1", dataCapture.bytes,
                        dataCapture.capturedLength, dataSHA1);
                bool dataSHA256Known = dataCaptured && !dataCapture.truncated &&
                    dataCapture.capturedLength > 0 &&
                    themer_iconservices_lab_digest(
                        "CC_SHA256", dataCapture.bytes,
                        dataCapture.capturedLength, dataSHA256);
                bool bitmapSHA1Known = bitmapCaptured &&
                    !bitmapCapture.truncated && bitmapCapture.capturedLength > 0 &&
                    themer_iconservices_lab_digest(
                        "CC_SHA1", bitmapCapture.bytes,
                        bitmapCapture.capturedLength, bitmapSHA1);
                bool bitmapSHA256Known = bitmapCaptured &&
                    !bitmapCapture.truncated && bitmapCapture.capturedLength > 0 &&
                    themer_iconservices_lab_digest(
                        "CC_SHA256", bitmapCapture.bytes,
                        bitmapCapture.capturedLength, bitmapSHA256);
                char uuidText[160] = {0};
                char dataPrefix[65] = {0};
                char bitmapPrefix[65] = {0};
                char tokenHex[THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP * 2 + 1]
                    = {0};
                char dataSHA1Hex[41] = {0};
                char dataSHA256Hex[65] = {0};
                char bitmapSHA1Hex[41] = {0};
                char bitmapSHA256Hex[65] = {0};
                (void)themer_read_remote_description(
                    uuid, uuidText, sizeof(uuidText));
                themer_iconservices_lab_hex_bytes(
                    dataCapture.bytes,
                    dataCapture.capturedLength < 32
                        ? dataCapture.capturedLength : 32,
                    dataPrefix, sizeof(dataPrefix));
                themer_iconservices_lab_hex_bytes(
                    bitmapCapture.bytes,
                    bitmapCapture.capturedLength < 32
                        ? bitmapCapture.capturedLength : 32,
                    bitmapPrefix, sizeof(bitmapPrefix));
                themer_iconservices_lab_hex_bytes(
                    tokenCapture.bytes, tokenCapture.capturedLength,
                    tokenHex, sizeof(tokenHex));
                themer_iconservices_lab_hex_bytes(
                    dataSHA1, sizeof(dataSHA1),
                    dataSHA1Hex, sizeof(dataSHA1Hex));
                themer_iconservices_lab_hex_bytes(
                    dataSHA256, sizeof(dataSHA256),
                    dataSHA256Hex, sizeof(dataSHA256Hex));
                themer_iconservices_lab_hex_bytes(
                    bitmapSHA1, sizeof(bitmapSHA1),
                    bitmapSHA1Hex, sizeof(bitmapSHA1Hex));
                themer_iconservices_lab_hex_bytes(
                    bitmapSHA256, sizeof(bitmapSHA256),
                    bitmapSHA256Hex, sizeof(bitmapSHA256Hex));
                printf("[ICONSERVICES_LAB] materialization-trace-stock68 "
                       "image=0x%llx uuid=\"%s\" "
                       "data=%zu/%zu/truncated=%d prefix=%s "
                       "bitmap=%zu/%zu/captured=%d/truncated=%d prefix=%s "
                       "token=%zu/%zu/captured=%d/truncated=%d hex=%s "
                       "dataSHA1=%s%s dataSHA256=%s%s "
                       "bitmapSHA1=%s%s bitmapSHA256=%s%s\n",
                       (unsigned long long)entry->image,
                       uuidText,
                       dataCapture.objectLength,
                       dataCapture.capturedLength,
                       dataCapture.truncated,
                       dataPrefix,
                       bitmapCapture.objectLength,
                       bitmapCapture.capturedLength,
                       bitmapCaptured,
                       bitmapCapture.truncated,
                       bitmapPrefix,
                       tokenCapture.objectLength,
                       tokenCapture.capturedLength,
                       tokenCaptured,
                       tokenCapture.truncated,
                       tokenHex,
                       dataSHA1Known ? "" : "?", dataSHA1Hex,
                       dataSHA256Known ? "" : "?", dataSHA256Hex,
                       bitmapSHA1Known ? "" : "?", bitmapSHA1Hex,
                       bitmapSHA256Known ? "" : "?", bitmapSHA256Hex);
                bool tokenComparable = tokenCaptured &&
                    !tokenCapture.truncated && tokenHex[0] &&
                    stock40TokenHex[0];
                bool tokenBytesEqual = tokenComparable &&
                    strcmp(stock40TokenHex, tokenHex) == 0;
                bool dataSHA1Comparable = dataSHA1Known &&
                    stock40DataSHA1[0];
                bool dataSHA1Equal = dataSHA1Comparable &&
                    strcmp(stock40DataSHA1, dataSHA1Hex) == 0;
                bool dataSHA256Comparable = dataSHA256Known &&
                    stock40DataSHA256[0];
                bool dataSHA256Equal = dataSHA256Comparable &&
                    strcmp(stock40DataSHA256, dataSHA256Hex) == 0;
                printf("[ICONSERVICES_LAB] materialization-trace-stock40-vs68 "
                       "stock40UUID=\"%s\" stock68UUID=\"%s\" "
                       "tokenKnown=%d tokenBytesEqual=%d "
                       "dataSHA1Known=%d dataSHA1Equal=%d "
                       "dataSHA256Known=%d dataSHA256Equal=%d "
                       "stock40Token=%s stock68Token=%s\n",
                       stock40UUID,
                       uuidText,
                       tokenComparable,
                       tokenBytesEqual,
                       dataSHA1Comparable,
                       dataSHA1Equal,
                       dataSHA256Comparable,
                       dataSHA256Equal,
                       stock40TokenHex,
                       tokenHex);
                if (r_is_objc_ptr(token) && remote_call_current_success()) {
                    r_msg2(token, "release", 0, 0, 0, 0);
                }
                if (r_is_objc_ptr(uuid) && remote_call_current_success()) {
                    r_msg2(uuid, "release", 0, 0, 0, 0);
                }
                if (r_is_objc_ptr(bitmap) && remote_call_current_success()) {
                    r_msg2(bitmap, "release", 0, 0, 0, 0);
                }
                if (r_is_objc_ptr(data) && remote_call_current_success()) {
                    r_msg2(data, "release", 0, 0, 0, 0);
                }
                themer_iconservices_lab_free_data_capture(&tokenCapture);
                themer_iconservices_lab_free_data_capture(&bitmapCapture);
                themer_iconservices_lab_free_data_capture(&dataCapture);
            }
        }
    }
    themer_iconservices_lab_trace_clear();
    return result;
}

static bool themer_iconservices_lab_image_geometry_matches(
    uint64_t image,
    double expectedWidth,
    double expectedHeight,
    double expectedScale)
{
    double width = 0.0;
    double height = 0.0;
    double scale = 0.0;
    bool known = themer_iconservices_lab_read_image_geometry(
        image, &width, &height, &scale);
    double dw = width - expectedWidth;
    double dh = height - expectedHeight;
    double ds = scale - expectedScale;
    if (dw < 0.0) dw = -dw;
    if (dh < 0.0) dh = -dh;
    if (ds < 0.0) ds = -ds;
    return known && dw < 0.01 && dh < 0.01 && ds < 0.01 &&
        remote_call_current_success();
}

static bool themer_iconservices_lab_set_minimum_size(
    uint64_t image,
    double expectedWidth,
    double expectedHeight)
{
    if (!r_is_objc_ptr(image) || expectedWidth <= 0.0 ||
        expectedHeight <= 0.0 || !remote_call_current_success() ||
        !r_responds_main(image, "setMinimumSize:") ||
        !r_responds_main(image, "minimumSize")) {
        return false;
    }
    struct { double w; double h; } requested = {
        expectedWidth, expectedHeight
    };
    r_msg2_main_raw(
        image, "setMinimumSize:",
        &requested, sizeof(requested),
        NULL, 0, NULL, 0, NULL, 0);
    if (!remote_call_current_success()) return false;

    struct { double w; double h; } actual = {0.0, 0.0};
    bool readable = r_msg2_main_struct_ret(
        image, "minimumSize", &actual, sizeof(actual),
        NULL, 0, NULL, 0, NULL, 0, NULL, 0);
    double dw = actual.w - expectedWidth;
    double dh = actual.h - expectedHeight;
    if (dw < 0.0) dw = -dw;
    if (dh < 0.0) dh = -dh;
    bool matched = readable && dw < 0.01 && dh < 0.01 &&
        remote_call_current_success();
    printf("[ICONSERVICES_LAB] concrete-ifimage minimum-size "
           "image=0x%llx requested=%.1fx%.1f actual=%.1fx%.1f "
           "readable=%d matched=%d\n",
           (unsigned long long)image,
           expectedWidth,
           expectedHeight,
           actual.w,
           actual.h,
           readable,
           matched);
    return matched;
}

static uint64_t themer_iconservices_lab_make_if_image_from_cgimage(
    uint64_t cgImage,
    double scale)
{
    if (!cgImage || scale < 1.0 || scale > 4.0 ||
        !remote_call_current_success()) {
        return 0;
    }
    uint64_t imageClass = themer_lookup_class("IFImage");
    if (!r_is_objc_ptr(imageClass) || !remote_call_current_success()) return 0;
    uint64_t alloc = r_msg2(imageClass, "alloc", 0, 0, 0, 0);
    if (!r_is_objc_ptr(alloc) || !remote_call_current_success()) return 0;
    if (!r_responds_main(alloc, "initWithCGImage:scale:")) {
        printf("[ICONSERVICES_LAB] concrete-ifimage unsupported "
               "selector=initWithCGImage:scale:\n");
        if (remote_call_current_success()) {
            r_msg2(alloc, "release", 0, 0, 0, 0);
        }
        return 0;
    }

    // Device proof: initWithCGImage:scale: adopts the incoming CGImageRef.
    // Passing a borrowed reference caused releasing the temporary
    // IFConcreteImage to invalidate the original stock IFCacheImage's raster.
    // Give the new object its own +1 reference and transfer that ownership to
    // the successful initializer.
    uint64_t retainedCGImage = r_dlsym_call(
        R_TIMEOUT, "CGImageRetain", cgImage, 0, 0, 0, 0, 0, 0, 0);
    if (!retainedCGImage || !remote_call_current_success()) {
        if (remote_call_current_success()) {
            r_msg2(alloc, "release", 0, 0, 0, 0);
        }
        return 0;
    }
    uint64_t image = r_msg2_main_raw(
        alloc, "initWithCGImage:scale:",
        &retainedCGImage, sizeof(retainedCGImage),
        &scale, sizeof(scale),
        NULL, 0, NULL, 0);
    printf("[ICONSERVICES_LAB] concrete-ifimage ownership "
           "sourceCG=0x%llx retainedCG=0x%llx image=0x%llx "
           "transfer=%d\n",
           (unsigned long long)cgImage,
           (unsigned long long)retainedCGImage,
           (unsigned long long)image,
           r_is_objc_ptr(image));
    // A successful initializer owns retainedCGImage. If the initializer returns
    // nil, its partial-object teardown owns any balancing release; avoid a
    // speculative second CGImageRelease on that exceptional path.
    return remote_call_current_success() && r_is_objc_ptr(image) ? image : 0;
}

static uint64_t themer_iconservices_lab_make_if_image(uint64_t sourceImage,
                                                      double scale)
{
    if (!r_is_objc_ptr(sourceImage) || !remote_call_current_success() ||
        !r_responds_main(sourceImage, "CGImage")) {
        return 0;
    }
    uint64_t cgImage = r_msg2_main(sourceImage, "CGImage", 0, 0, 0, 0);
    return remote_call_current_success()
        ? themer_iconservices_lab_make_if_image_from_cgimage(cgImage, scale)
        : 0;
}

static uint64_t themer_iconservices_lab_make_structured_if_image(
    uint64_t sourceImage,
    double scale,
    NSData *layerData)
{
    if (!r_is_objc_ptr(sourceImage) || ![layerData isKindOfClass:NSData.class] ||
        layerData.length == 0 || scale < 1.0 || scale > 4.0 ||
        !remote_call_current_success() ||
        !r_responds_main(sourceImage, "CGImage")) {
        return 0;
    }
    uint64_t cgImage = r_msg2_main(sourceImage, "CGImage", 0, 0, 0, 0);
    uint64_t imageClass = themer_lookup_class("IFImage");
    uint64_t alloc = r_is_objc_ptr(imageClass)
        ? r_msg2(imageClass, "alloc", 0, 0, 0, 0) : 0;
    char types[192] = {0};
    bool abiReady = r_is_objc_ptr(alloc) &&
        r_responds_main(alloc, "initWithCGImage:scale:layerData:") &&
        themer_iconservices_lab_method_types(
            alloc, "initWithCGImage:scale:layerData:",
            types, sizeof(types)) &&
        strcmp(types, "@40@0:8^{CGImage=}16d24@32") == 0;
    uint64_t remoteLayerData = abiReady
        ? themer_make_remote_nsdata(layerData) : 0;
    uint64_t retainedCGImage = r_is_objc_ptr(remoteLayerData)
        ? r_dlsym_call(R_TIMEOUT, "CGImageRetain", cgImage,
                       0, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t image = 0;
    if (retainedCGImage && remote_call_current_success()) {
        image = r_msg2_main_raw(
            alloc, "initWithCGImage:scale:layerData:",
            &retainedCGImage, sizeof(retainedCGImage),
            &scale, sizeof(scale),
            &remoteLayerData, sizeof(remoteLayerData),
            NULL, 0);
    }
    printf("[ICONSERVICES_PERSISTENT] structured-ifimage abi=%d "
           "types=\"%s\" layerBytes=%lu sourceCG=0x%llx "
           "retainedCG=0x%llx image=0x%llx\n",
           abiReady, types[0] ? types : "-",
           (unsigned long)layerData.length,
           (unsigned long long)cgImage,
           (unsigned long long)retainedCGImage,
           (unsigned long long)image);
    if (r_is_objc_ptr(remoteLayerData) && remote_call_current_success()) {
        r_msg2(remoteLayerData, "release", 0, 0, 0, 0);
    }
    // The initializer consumes the allocation and the +1 CGImage on both its
    // successful and exceptional paths; do not speculate about either after
    // it has been invoked.
    return remote_call_current_success() && r_is_objc_ptr(image) ? image : 0;
}

static bool themer_capture_contains_marker(
    const ThemerIconServicesLabDataCapture *capture,
    const char *marker)
{
    if (!capture || capture->truncated || !capture->bytes || !marker) {
        return false;
    }
    size_t markerLength = strlen(marker);
    if (markerLength == 0 || capture->capturedLength < markerLength) {
        return false;
    }
    const uint8_t *bytes = capture->bytes;
    for (size_t offset = 0;
         offset <= capture->capturedLength - markerLength; offset++) {
        if (bytes[offset] == (uint8_t)marker[0] &&
            !memcmp(bytes + offset, marker, markerLength)) {
            return true;
        }
    }
    return false;
}

// Builds a +1 IFImageBag whose image array exactly mirrors the enumerated
// stock topology. The caller owns the returned bag. Probe and Seed share this
// constructor so both exercise identical Objective-C construction.
static uint64_t themer_iconservices_lab_make_bag_from_images(
    const uint64_t *images,
    int imageCount)
{
    if (!images || imageCount < 1 ||
        imageCount > THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP ||
        !remote_call_current_success()) {
        return 0;
    }
    for (int i = 0; i < imageCount; i++) {
        if (!r_is_objc_ptr(images[i])) return 0;
    }
    uint64_t imagesArray = 0;
    uint64_t bag = 0;
    uint64_t arrayClass = r_class("NSMutableArray");
    uint64_t arrayAlloc = r_is_objc_ptr(arrayClass)
        ? r_msg2(arrayClass, "alloc", 0, 0, 0, 0) : 0;
    imagesArray = r_is_objc_ptr(arrayAlloc)
        ? r_msg2_main(arrayAlloc, "initWithCapacity:",
                      (uint64_t)imageCount, 0, 0, 0)
        : 0;
    if (r_is_objc_ptr(imagesArray) &&
        r_responds_main(imagesArray, "addObject:")) {
        for (int i = 0; i < imageCount && remote_call_current_success(); i++) {
            r_msg2_main(imagesArray, "addObject:", images[i], 0, 0, 0);
        }
        if (remote_call_current_success() &&
            themer_remote_count(imagesArray) == (uint64_t)imageCount) {
            uint64_t bagClass = themer_lookup_class("IFImageBag");
            uint64_t bagAlloc = r_is_objc_ptr(bagClass)
                ? r_msg2(bagClass, "alloc", 0, 0, 0, 0) : 0;
            bag = r_is_objc_ptr(bagAlloc)
                ? r_msg2_main(bagAlloc, "initWithImages:",
                              imagesArray, 0, 0, 0)
                : 0;
        }
    }
    if (r_is_objc_ptr(imagesArray) && remote_call_current_success()) {
        r_msg2(imagesArray, "release", 0, 0, 0, 0);
    }
    return remote_call_current_success() && r_is_objc_ptr(bag) ? bag : 0;
}

static void themer_iconservices_lab_log_descriptor_digest(uint64_t descriptor)
{
    if (!r_is_objc_ptr(descriptor) || !remote_call_current_success()) return;
    static const char *selectors[] = {
        "digest",
        "UUID",
        "uuid",
        "imageDigest",
        "descriptorDigest",
        "digestUUID",
        "cacheKey",
        "identifier",
        "name",
    };
    for (size_t i = 0;
         i < sizeof(selectors) / sizeof(selectors[0]) &&
         remote_call_current_success();
         i++) {
        const char *selector = selectors[i];
        bool responds = r_responds_main(descriptor, selector);
        char types[192] = {0};
        bool hasTypes = responds && themer_iconservices_lab_method_types(
            descriptor, selector, types, sizeof(types));
        uint64_t value = 0;
        bool invoked = false;
        if (responds && hasTypes && types[0] == '@') {
            value = r_msg2_main(descriptor, selector, 0, 0, 0, 0);
            invoked = remote_call_current_success();
        }
        char valueCls[96] = {0};
        char valueText[220] = {0};
        if (invoked && r_is_objc_ptr(value)) {
            themer_read_class_name(value, valueCls, sizeof(valueCls));
            themer_read_remote_description(value, valueText,
                                           sizeof(valueText));
        }
        printf("[ICONSERVICES_LAB] descriptor-digest selector=%s "
               "responds=%d types=\"%s\" invoked=%d value=0x%llx/%s "
               "desc=\"%s\"\n",
               selector,
               responds,
               hasTypes ? types : "",
               invoked,
               (unsigned long long)value,
               valueCls[0] ? valueCls : "-",
               valueText);
    }
}

static void themer_iconservices_lab_log_bag_size_image(uint64_t bag,
                                                      double width,
                                                      double height,
                                                      double scale)
{
    uint64_t image = themer_iconservices_lab_image_for_size_scale(
        bag, width, height, scale);
    if (!remote_call_current_success()) return;
    printf("[ICONSERVICES_LAB] bag-size-image requested=%.1fx%.1f "
           "scale=%.2f image=0x%llx\n",
           width,
           height,
           scale,
           (unsigned long long)image);
    char source[48] = {0};
    snprintf(source, sizeof(source), "size-%.0fx%.0f", width, height);
    themer_iconservices_lab_log_bag_image(source, 0, image);
}

static void themer_iconservices_lab_log_bag_value(uint64_t bag,
                                                 uint64_t descriptor)
{
    if (!r_is_objc_ptr(bag) || !remote_call_current_success()) return;
    char cls[96] = {0};
    char text[300] = {0};
    themer_read_class_name(bag, cls, sizeof(cls));
    if (r_responds_main(bag, "debugDescription")) {
        uint64_t desc = r_msg2_main(bag, "debugDescription", 0, 0, 0, 0);
        if (r_is_objc_ptr(desc)) {
            (void)r_read_nsstring(desc, text, sizeof(text));
        }
    }
    for (char *p = text; *p; p++) {
        if (*p == '\n' || *p == '\r' || *p == '\t') *p = ' ';
        if (*p == '"') *p = '\'';
    }
    uint64_t images = r_responds_main(bag, "images")
        ? r_msg2_main(bag, "images", 0, 0, 0, 0) : 0;
    uint64_t byScale = r_responds_main(bag, "imagesByScale")
        ? r_msg2_main(bag, "imagesByScale", 0, 0, 0, 0) : 0;
    int imagesCount = (int)themer_remote_count(images);
    int scaleKeyCount = (int)themer_remote_count(byScale);
    bool hasScale = false;
    double scale = themer_read_remote_double_property(
        descriptor, "scale", themer_screen_scale(), &hasScale);
    uint64_t scaleImages = 0;
    if (r_responds_main(bag, "imagesForScale:")) {
        scaleImages = r_msg2_main_raw(
            bag, "imagesForScale:",
            &scale, sizeof(scale),
            NULL, 0, NULL, 0, NULL, 0);
    }
    int scaleImagesCount = (int)themer_remote_count(scaleImages);
    printf("[ICONSERVICES_LAB] bag-value bag=0x%llx class=%s "
           "images=0x%llx/%d imagesByScale=0x%llx/%d "
           "requestedScale=%s%.2f scaleImages=0x%llx/%d "
           "respondsImages=%d respondsByScale=%d respondsForScale=%d "
           "respondsForSizeScale=%d debug=\"%s\"\n",
           (unsigned long long)bag,
           cls[0] ? cls : "-",
           (unsigned long long)images,
           imagesCount,
           (unsigned long long)byScale,
           scaleKeyCount,
           hasScale ? "" : "?",
           scale,
           (unsigned long long)scaleImages,
           scaleImagesCount,
           r_responds_main(bag, "images"),
           r_responds_main(bag, "imagesByScale"),
           r_responds_main(bag, "imagesForScale:"),
           r_responds_main(bag, "imageForSize:scale:"),
           text);

    themer_iconservices_lab_log_object_surface("bag", bag);
    themer_iconservices_lab_log_bag_selectors(bag);
    themer_iconservices_lab_log_descriptor_digest(descriptor);

    if (r_is_objc_ptr(images) && imagesCount > 0 &&
        r_responds_main(images, "objectAtIndex:")) {
        uint64_t firstImage = r_msg2_main(images, "objectAtIndex:",
                                          0, 0, 0, 0);
        themer_iconservices_lab_log_object_surface("cache-image",
                                                   firstImage);
        if (imagesCount > 1 && remote_call_current_success()) {
            uint64_t secondImage = r_msg2_main(images, "objectAtIndex:",
                                               1, 0, 0, 0);
            uint64_t firstClass = r_is_objc_ptr(firstImage)
                ? r_dlsym_call(R_TIMEOUT, "object_getClass",
                               firstImage, 0, 0, 0, 0, 0, 0, 0)
                : 0;
            uint64_t secondClass = r_is_objc_ptr(secondImage)
                ? r_dlsym_call(R_TIMEOUT, "object_getClass",
                               secondImage, 0, 0, 0, 0, 0, 0, 0)
                : 0;
            if (r_is_objc_ptr(secondClass) && secondClass != firstClass) {
                themer_iconservices_lab_log_object_surface(
                    "cache-image-alt", secondImage);
            }
        }
    }

    struct { double w; double h; } descriptorSize = {0.0, 0.0};
    bool hasDescriptorSize = r_responds_main(descriptor, "size") &&
        r_msg2_main_struct_ret(descriptor, "size", &descriptorSize,
            sizeof(descriptorSize), NULL, 0, NULL, 0, NULL, 0, NULL, 0);
    if (hasDescriptorSize && hasScale) {
        themer_iconservices_lab_log_bag_size_image(
            bag, descriptorSize.w, descriptorSize.h, scale);
    }
    if (r_is_objc_ptr(images) &&
        r_responds_main(images, "objectAtIndex:")) {
        int cap = imagesCount < THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP
            ? imagesCount : THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP;
        for (int i = 0; i < cap && remote_call_current_success(); i++) {
            uint64_t image = r_msg2_main(images, "objectAtIndex:",
                                         (uint64_t)i, 0, 0, 0);
            double entryW = 0.0;
            double entryH = 0.0;
            double entryScale = 0.0;
            if (themer_iconservices_lab_read_image_geometry(
                    image, &entryW, &entryH, &entryScale)) {
                themer_iconservices_lab_log_bag_size_image(
                    bag, entryW, entryH, entryScale);
            }
        }
    }

    themer_iconservices_lab_log_bag_image_array("all", images);
    if (scaleImages != images) {
        themer_iconservices_lab_log_bag_image_array("requested-scale",
                                                    scaleImages);
    }

    if (r_is_objc_ptr(byScale) &&
        r_responds_main(byScale, "allKeys") &&
        r_responds_main(byScale, "objectForKey:")) {
        uint64_t keys = r_msg2_main(byScale, "allKeys", 0, 0, 0, 0);
        int keyCount = (int)themer_remote_count(keys);
        int cap = keyCount < THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP
            ? keyCount : THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP;
        for (int i = 0; i < cap && remote_call_current_success(); i++) {
            uint64_t key = r_msg2_main(keys, "objectAtIndex:",
                                       (uint64_t)i, 0, 0, 0);
            uint64_t value = r_msg2_main(byScale, "objectForKey:",
                                         key, 0, 0, 0);
            char keyCls[96] = {0};
            char keyText[160] = {0};
            char valueCls[96] = {0};
            themer_read_class_name(key, keyCls, sizeof(keyCls));
            themer_read_remote_description(key, keyText, sizeof(keyText));
            themer_read_class_name(value, valueCls, sizeof(valueCls));
            printf("[ICONSERVICES_LAB] bag-scale-key index=%d key=0x%llx/%s "
                   "value=0x%llx/%s valueCount=%llu keyDesc=\"%s\"\n",
                   i,
                   (unsigned long long)key,
                   keyCls[0] ? keyCls : "-",
                   (unsigned long long)value,
                   valueCls[0] ? valueCls : "-",
                   (unsigned long long)themer_remote_count(value),
                   keyText);
        }
    }
}

static uint64_t themer_iconservices_lab_make_bundle_icon(const char *bundle)
{
    if (!bundle || !bundle[0] || !remote_call_current_success()) return 0;
    uint64_t bid = r_nsstr_retained(bundle);
    if (!remote_call_current_success()) return 0;
    uint64_t iconCls = themer_lookup_class("ISBundleIdentifierIcon");
    if (!remote_call_current_success() || !r_is_objc_ptr(iconCls) ||
        !r_is_objc_ptr(bid)) {
        if (r_is_objc_ptr(bid)) r_msg2(bid, "release", 0, 0, 0, 0);
        return 0;
    }
    uint64_t alloc = r_msg2(iconCls, "alloc", 0, 0, 0, 0);
    if (!remote_call_current_success()) {
        r_msg2(bid, "release", 0, 0, 0, 0);
        return 0;
    }
    uint64_t icon = r_is_objc_ptr(alloc)
        ? r_msg2_main(alloc, "initWithBundleIdentifier:", bid, 0, 0, 0)
        : 0;
    r_msg2(bid, "release", 0, 0, 0, 0);
    if (!remote_call_current_success()) return 0;
    return r_is_objc_ptr(icon) ? icon : 0;  // +1 owned by caller
}

static uint64_t themer_iconservices_lab_named_spotlight_descriptor(
    uint64_t *symbolOut,
    uint64_t *nameObjectOut,
    bool *literalFallbackOut)
{
    if (symbolOut) *symbolOut = 0;
    if (nameObjectOut) *nameObjectOut = 0;
    if (literalFallbackOut) *literalFallbackOut = false;
    if (!remote_call_current_success()) return 0;

    uint64_t descCls = themer_lookup_class("ISImageDescriptor");
    if (!remote_call_current_success() || !r_is_objc_ptr(descCls) ||
        !r_responds_main(descCls, "imageDescriptorNamed:")) {
        return 0;
    }

    // Resolve the exported symbol only as capability telemetry. Mapping and
    // dereferencing shared-cache data through remote VM can record a spurious
    // I/O failure even though the public named-descriptor API is usable. Pass
    // the exact exported identifier string directly instead.
    uint64_t symbol = themer_remote_symbol_addr(
        "kISImageDescriptorSpotlight");
    if (!remote_call_current_success()) return 0;
    uint64_t nameObject = r_nsstr_retained(
        "com.apple.IconServices.ImageDescriptor.Spotlight");
    bool literalFallback = true;
    if (!remote_call_current_success() || !r_is_objc_ptr(nameObject)) {
        return 0;
    }

    uint64_t descriptor = r_msg2_main(
        descCls, "imageDescriptorNamed:", nameObject, 0, 0, 0);
    if (remote_call_current_success() && r_is_objc_ptr(descriptor)) {
        descriptor = r_msg2(descriptor, "retain", 0, 0, 0, 0);
    }
    if (symbolOut) *symbolOut = symbol;
    if (nameObjectOut) *nameObjectOut = 0;
    if (literalFallbackOut) *literalFallbackOut = literalFallback;
    r_msg2(nameObject, "release", 0, 0, 0, 0);
    return remote_call_current_success() && r_is_objc_ptr(descriptor)
        ? descriptor : 0;
}

static uint64_t themer_iconservices_lab_prepare_stock_image(
    uint64_t icon,
    uint64_t descriptor,
    uint64_t *prepareResultOut,
    bool *prepareSupportedOut)
{
    if (prepareResultOut) *prepareResultOut = 0;
    if (prepareSupportedOut) *prepareSupportedOut = false;
    if (!remote_call_current_success() || !r_is_objc_ptr(icon) ||
        !r_is_objc_ptr(descriptor)) {
        return 0;
    }

    if (r_responds_main(icon, "prepareImageForDescriptor:")) {
        if (prepareSupportedOut) *prepareSupportedOut = true;
        uint64_t prepared = r_msg2_main(
            icon, "prepareImageForDescriptor:", descriptor, 0, 0, 0);
        if (prepareResultOut) *prepareResultOut = prepared;
        if (!remote_call_current_success()) return 0;
    }
    if (!r_responds_main(icon, "imageForDescriptor:")) return 0;
    return r_msg2_main(icon, "imageForDescriptor:", descriptor, 0, 0, 0);
}

static int themer_iconservices_lab_select_bundles(
    NSDictionary<NSString *, NSData *> *normalized,
    volatile int *stopRequested,
    char *targetOut, size_t targetLen,
    char *controlOut, size_t controlLen)
{
    if (targetOut && targetLen) targetOut[0] = '\0';
    if (controlOut && controlLen) controlOut[0] = '\0';
    if (!normalized || normalized.count == 0) return 0;

    NSArray<NSString *> *sortedKeys = [normalized.allKeys
        sortedArrayUsingSelector:@selector(compare:)];
    int found = 0;
    for (int pass = 0; pass < 2 && found < 2; pass++) {
        for (NSString *key in sortedKeys) {
            if (stopRequested && *stopRequested) return found;
            const char *bundle = key.UTF8String;
            bool isCyanide =
                bundle && strcmp(bundle, "com.zeroxjf.ios-cyanide1") == 0;
            if ((pass == 0 && isCyanide) || (pass == 1 && !isCyanide)) {
                continue;
            }
            if (!bundle || !bundle[0]) continue;
            NSData *bytes = themer_theme_data_for_key(normalized, key, NULL);
            if (![bytes isKindOfClass:NSData.class] || bytes.length == 0) {
                continue;
            }
            char *dst = found == 0 ? targetOut : controlOut;
            size_t dstLen = found == 0 ? targetLen : controlLen;
            if (!dst || dstLen == 0) return found;
            snprintf(dst, dstLen, "%s", bundle);
            found++;
            if (found >= 2) break;
        }
        if (found >= 2) break;
    }
    return found;
}

static bool themer_iconservices_lab_find_first_selector(
    uint64_t obj,
    const char *const *selectors,
    size_t count,
    char *out,
    size_t outLen)
{
    if (out && outLen > 0) out[0] = '\0';
    if (!r_is_objc_ptr(obj) || !selectors || count == 0 ||
        !out || outLen == 0) {
        return false;
    }
    for (size_t i = 0; i < count && remote_call_current_success(); i++) {
        if (!selectors[i] || !selectors[i][0]) continue;
        if (r_responds_main(obj, selectors[i])) {
            snprintf(out, outLen, "%s", selectors[i]);
            return true;
        }
    }
    // A healthy transport with no matching selector is not a capability hit.
    return false;
}

