// Discovery result for one target app plus one untouched control app.
// Objects marked +1 are owned by the discovery and released by
// themer_iconservices_lab_release_discovery unless transferred into the
// committed lab state dictionary (which retains them).
typedef struct {
    bool loaded;
    uint64_t manager;
    uint64_t managerIconCache;
    bool managerCacheContract;      // setImage:forDescriptor: + imageForDescriptor:
    bool managerCachePathKnown;
    char managerCachePath[240];
    char targetBundle[192];
    char controlBundle[192];
    bool haveControl;
    uint64_t localIcon;              // +1, pre-registration ISBundleIdentifierIcon
    uint64_t canonicalIcon;          // manager-owned, not retained
    uint64_t localCache;             // getter result, not retained
    uint64_t canonicalCache;         // getter result, not retained
    bool localCacheDistinct;
    bool localCacheWritable;
    bool canonicalCacheWritable;
    uint64_t controlCanonicalIcon;   // manager-owned, not retained
    uint64_t controlCanonicalCache;  // getter result, not retained
    uint64_t descriptor;             // +1 named Spotlight descriptor
    uint64_t descriptorSymbol;
    uint64_t descriptorNameObject;
    bool descriptorLiteralFallback;
    char descriptorClass[96];
    char descriptorText[220];
    bool descriptorPropsKnown;
    double descSizeW;
    double descSizeH;
    double descScale;
    bool descSizeOK;
    bool descScaleOK;
    uint64_t descAppearance;
    uint64_t descAppearanceVariant;
    uint64_t descIconVariant;
    uint64_t descVariantOptions;
    bool descAppearanceOK;
    bool descAppearanceVariantOK;
    bool descIconVariantOK;
    bool descVariantOptionsOK;
    uint64_t stockTargetImage;       // canonical icon readback (not retained)
    uint64_t stockLocalImage;        // local icon readback (not retained)
    uint64_t stockManagerImage;      // manager cache readback (not retained)
    uint64_t stockControlImage;      // control icon readback (not retained)
    uint64_t prepareTargetResult;    // prepareImageForDescriptor: result
    uint64_t prepareLocalResult;
    uint64_t prepareControlResult;
    bool prepareTargetSupported;
    bool prepareLocalSupported;
    bool prepareControlSupported;
    ThemerIconServicesLabTopologySnapshot beforeDescriptorSnapshot;
    ThemerIconServicesLabTopologySnapshot beforePrepareSnapshot;
    ThemerIconServicesLabTopologySnapshot afterTargetPrepareSnapshot;
    ThemerIconServicesLabTopologySnapshot afterAllPrepareSnapshot;
    uint64_t prePrepareBagsCopy;     // +1 mutable copy, pristine restore content
    int prePrepareBagsCount;
    bool prePrepareBagsCopyKnown;
    bool prePrepareBagsEmpty;
    uint64_t originalBags;           // +1, intact post-prepare dictionary
    uint64_t originalBagKey;         // dictionary-owned key, not retained
    uint64_t originalBagValue;       // dictionary-owned IFImageBag, not retained
    ThemerIconServicesLabBagEntry stockEntries[
        THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP];  // originalBagValue-owned images
    int stockEntryCount;
    int primaryEntryIndex;
    bool stockTopologyKnown;
    bool originalBagExactKey;
    bool originalBagDigestKey;
    int bagsCount;
    bool bagsReadWrite;
    bool hasDescriptorClear;
    char descriptorClearSelector[96];
    bool hasIconInvalidator;
    char iconInvalidatorSelector[96];
    bool hasCacheClear;
    char cacheClearSelector[96];
    bool factoryRoute;
    ThemerIconServicesLabTraceResult traceResult;
    uint64_t supportedMask;
} ThemerIconServicesLabDiscovery;

static void themer_iconservices_lab_release_discovery(
    ThemerIconServicesLabDiscovery *d)
{
    if (!d) return;
    if (r_is_objc_ptr(d->localIcon) && remote_call_current_success()) {
        r_msg2(d->localIcon, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(d->descriptor) && remote_call_current_success()) {
        r_msg2(d->descriptor, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(d->prePrepareBagsCopy) &&
        remote_call_current_success()) {
        r_msg2(d->prePrepareBagsCopy, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(d->originalBags) && remote_call_current_success()) {
        r_msg2(d->originalBags, "release", 0, 0, 0, 0);
    }
    memset(d, 0, sizeof(*d));
}

static void themer_iconservices_lab_free_data_capture(
    ThemerIconServicesLabDataCapture *capture)
{
    if (!capture) return;
    free(capture->bytes);
    memset(capture, 0, sizeof(*capture));
}

static bool themer_iconservices_lab_capture_nsdata(
    uint64_t data,
    size_t cap,
    ThemerIconServicesLabDataCapture *capture)
{
    if (!capture) return false;
    memset(capture, 0, sizeof(*capture));
    if (!r_is_objc_ptr(data) || cap == 0 || !remote_call_current_success() ||
        !r_responds_main(data, "length") ||
        !r_responds_main(data, "bytes")) {
        return false;
    }
    uint64_t remoteLength = r_msg2_main(data, "length", 0, 0, 0, 0);
    if (!remote_call_current_success() || remoteLength > SIZE_MAX) return false;
    capture->objectLength = (size_t)remoteLength;
    capture->capturedLength = capture->objectLength < cap
        ? capture->objectLength : cap;
    capture->truncated = capture->capturedLength < capture->objectLength;
    if (capture->capturedLength == 0) return true;

    uint64_t remoteBytes = r_msg2_main(data, "bytes", 0, 0, 0, 0);
    if (!remoteBytes || !remote_call_current_success()) return false;
    capture->bytes = malloc(capture->capturedLength);
    if (!capture->bytes) return false;
    if (!remote_read(remoteBytes, capture->bytes, capture->capturedLength)) {
        themer_iconservices_lab_free_data_capture(capture);
        return false;
    }
    return remote_call_current_success();
}

static NSString *themer_iconservices_lab_cache_recovery_directory(void)
{
    NSString *base = NSSearchPathForDirectoriesInDomains(
        NSApplicationSupportDirectory, NSUserDomainMask, YES).firstObject;
    return [base stringByAppendingPathComponent:@"Cyanide/SpotlightCacheRecovery"];
}

static NSData *themer_iconservices_lab_read_local_file(NSString *path)
{
    if (path.length == 0) return nil;
    int fd = open(path.fileSystemRepresentation, O_RDONLY | O_CLOEXEC);
    if (fd < 0) return nil;
    struct stat st = {0};
    if (fstat(fd, &st) != 0 || !S_ISREG(st.st_mode) || st.st_size <= 0 ||
        st.st_size > (off_t)(8U << 20)) {
        close(fd);
        return nil;
    }
    NSMutableData *data = [NSMutableData dataWithLength:(NSUInteger)st.st_size];
    uint8_t *bytes = data.mutableBytes;
    size_t offset = 0;
    while (offset < data.length) {
        ssize_t amount = read(fd, bytes + offset, data.length - offset);
        if (amount > 0) {
            offset += (size_t)amount;
            continue;
        }
        if (amount < 0 && errno == EINTR) continue;
        close(fd);
        return nil;
    }
    close(fd);
    return data;
}

static bool themer_iconservices_lab_local_files_equal(
    NSString *first,
    NSString *second)
{
    NSData *firstData = themer_iconservices_lab_read_local_file(first);
    NSData *secondData = themer_iconservices_lab_read_local_file(second);
    return firstData && secondData && [firstData isEqualToData:secondData];
}

static uint64_t themer_iconservices_lab_overwrite_file(
    NSString *targetPath,
    NSString *sourcePath)
{
    if (targetPath.length == 0 || sourcePath.length == 0) return UINT64_MAX;
    if (!remote_call_lab_backend_opted_in()) {
        return overwrite_system_file(
            (char *)targetPath.fileSystemRepresentation,
            (char *)sourcePath.fileSystemRepresentation);
    }

    int sourceFD = open(sourcePath.fileSystemRepresentation,
                        O_RDONLY | O_CLOEXEC | O_NOFOLLOW);
    int targetFD = open(targetPath.fileSystemRepresentation,
                        O_RDWR | O_CLOEXEC | O_NOFOLLOW);
    struct stat sourceStat = {0};
    struct stat targetBefore = {0};
    bool ready = sourceFD >= 0 && targetFD >= 0 &&
        fstat(sourceFD, &sourceStat) == 0 &&
        fstat(targetFD, &targetBefore) == 0 &&
        S_ISREG(sourceStat.st_mode) && S_ISREG(targetBefore.st_mode) &&
        sourceStat.st_size > 0 &&
        sourceStat.st_size == targetBefore.st_size &&
        sourceStat.st_size <= (off_t)(8U << 20);
    int savedError = ready ? 0 : (errno ? errno : EINVAL);
    uint8_t buffer[16384];
    off_t offset = 0;
    while (ready && offset < sourceStat.st_size) {
        size_t wanted = (size_t)(sourceStat.st_size - offset);
        if (wanted > sizeof(buffer)) wanted = sizeof(buffer);
        ssize_t amount = pread(sourceFD, buffer, wanted, offset);
        if (amount <= 0) {
            ready = false;
            savedError = amount < 0 && errno ? errno : EIO;
            break;
        }
        size_t written = 0;
        while (written < (size_t)amount) {
            ssize_t result = pwrite(targetFD, buffer + written,
                                    (size_t)amount - written,
                                    offset + (off_t)written);
            if (result > 0) {
                written += (size_t)result;
                continue;
            }
            if (result < 0 && errno == EINTR) continue;
            ready = false;
            savedError = result < 0 && errno ? errno : EIO;
            break;
        }
        offset += (off_t)written;
    }
    if (ready && fsync(targetFD) != 0) {
        ready = false;
        savedError = errno ? errno : EIO;
    }
    struct stat targetAfter = {0};
    if (ready && (fstat(targetFD, &targetAfter) != 0 ||
                  targetAfter.st_dev != targetBefore.st_dev ||
                  targetAfter.st_ino != targetBefore.st_ino ||
                  targetAfter.st_size != targetBefore.st_size)) {
        ready = false;
        savedError = errno ? errno : EIO;
    }
    if (targetFD >= 0) close(targetFD);
    if (sourceFD >= 0) close(sourceFD);
    printf("[ICONSERVICES_LAB] vm-vnode-overwrite target=\"%s\" "
           "source=\"%s\" bytes=%lld sameVnode=%d result=%d (%s)\n",
           targetPath.UTF8String ?: "-",
           sourcePath.UTF8String ?: "-",
           (long long)(ready ? sourceStat.st_size : offset),
           ready,
           savedError,
           savedError ? strerror(savedError) : "ok");
    return ready ? 0 : UINT64_MAX;
}

static uint64_t themer_make_remote_nsdata(NSData *data)
{
    if (![data isKindOfClass:NSData.class] || data.length == 0 ||
        data.length > (8U << 20) || !remote_call_current_success()) {
        return 0;
    }
    uint64_t remoteBytes = r_dlsym_call(
        R_TIMEOUT, "malloc", data.length, 0, 0, 0, 0, 0, 0, 0);
    if (!remoteBytes || !remote_write(remoteBytes, data.bytes, data.length)) {
        if (remoteBytes && remote_call_current_success()) r_free(remoteBytes);
        return 0;
    }
    uint64_t dataClass = r_class("NSData");
    uint64_t alloc = r_is_objc_ptr(dataClass)
        ? r_msg2(dataClass, "alloc", 0, 0, 0, 0) : 0;
    uint64_t remoteData = r_is_objc_ptr(alloc)
        ? r_msg2(alloc, "initWithBytes:length:",
                 remoteBytes, data.length, 0, 0) : 0;
    if (remote_call_current_success()) r_free(remoteBytes);
    return remote_call_current_success() && r_is_objc_ptr(remoteData)
        ? remoteData : 0;
}

static void themer_iconservices_lab_clear_stock68_identity(void)
{
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    [defaults removeObjectForKey:THEMER_ICONSERVICES_LAB_STOCK68_UUID_KEY];
    [defaults removeObjectForKey:THEMER_ICONSERVICES_LAB_STOCK68_TOKEN_KEY];
    [defaults removeObjectForKey:THEMER_ICONSERVICES_LAB_STOCK68_PID_KEY];
    [defaults removeObjectForKey:THEMER_ICONSERVICES_LAB_STOCK68_PATH_KEY];
    [defaults removeObjectForKey:THEMER_ICONSERVICES_LAB_STOCK68_BUNDLE_KEY];
    (void)[defaults synchronize];
}

static bool themer_iconservices_lab_persist_stock68_identity(
    const ThemerIconServicesLabDiscovery *d)
{
    if (!d || !d->targetBundle[0] || !d->managerCachePathKnown ||
        !remote_call_current_success()) {
        themer_iconservices_lab_clear_stock68_identity();
        return false;
    }
    const ThemerIconServicesLabBagEntry *entry = NULL;
    for (int i = 0; i < d->stockEntryCount; i++) {
        if (d->stockEntries[i].geometryKnown &&
            themer_iconservices_lab_sizes_match(
                d->stockEntries[i].width, d->stockEntries[i].height,
                68.0, 68.0)) {
            entry = &d->stockEntries[i];
            break;
        }
    }
    uint64_t uuid = entry
        ? themer_iconservices_lab_retained_getter(entry->image, "uuid") : 0;
    uint64_t token = entry
        ? themer_iconservices_lab_retained_getter(
            entry->image, "validationToken") : 0;
    uint64_t uuidString = r_is_objc_ptr(uuid)
        ? themer_iconservices_lab_retained_getter(uuid, "UUIDString") : 0;
    char uuidText[80] = {0};
    bool uuidKnown = r_is_objc_ptr(uuidString) &&
        r_read_nsstring(uuidString, uuidText, sizeof(uuidText));
    ThemerIconServicesLabDataCapture tokenCapture = {0};
    bool tokenKnown = r_is_objc_ptr(token) &&
        themer_iconservices_lab_capture_nsdata(
            token, THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP, &tokenCapture) &&
        !tokenCapture.truncated && tokenCapture.objectLength > 0;
    NSData *tokenData = tokenKnown
        ? [NSData dataWithBytes:tokenCapture.bytes
                         length:tokenCapture.objectLength]
        : nil;
    NSString *uuidValue = uuidKnown
        ? [NSString stringWithUTF8String:uuidText] : nil;
    NSString *pathValue = [NSString stringWithUTF8String:d->managerCachePath];
    NSString *bundleValue = [NSString stringWithUTF8String:d->targetBundle];
    NSNumber *pidValue = @(remote_call_current_pid());
    bool metadataReady = uuidValue.length > 0 && tokenData.length > 0 &&
        pathValue.length > 0 && bundleValue.length > 0;
    bool persisted = false;
    if (metadataReady) {
        NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
        [defaults setObject:uuidValue
                     forKey:THEMER_ICONSERVICES_LAB_STOCK68_UUID_KEY];
        [defaults setObject:tokenData
                     forKey:THEMER_ICONSERVICES_LAB_STOCK68_TOKEN_KEY];
        [defaults setObject:pidValue
                     forKey:THEMER_ICONSERVICES_LAB_STOCK68_PID_KEY];
        [defaults setObject:pathValue
                     forKey:THEMER_ICONSERVICES_LAB_STOCK68_PATH_KEY];
        [defaults setObject:bundleValue
                     forKey:THEMER_ICONSERVICES_LAB_STOCK68_BUNDLE_KEY];
        (void)[defaults synchronize];
        persisted = [[defaults stringForKey:
            THEMER_ICONSERVICES_LAB_STOCK68_UUID_KEY]
                isEqualToString:uuidValue] &&
            [[defaults dataForKey:THEMER_ICONSERVICES_LAB_STOCK68_TOKEN_KEY]
                isEqualToData:tokenData] &&
            [[defaults objectForKey:THEMER_ICONSERVICES_LAB_STOCK68_PID_KEY]
                isEqual:pidValue] &&
            [[defaults stringForKey:THEMER_ICONSERVICES_LAB_STOCK68_PATH_KEY]
                isEqualToString:pathValue] &&
            [[defaults stringForKey:THEMER_ICONSERVICES_LAB_STOCK68_BUNDLE_KEY]
                isEqualToString:bundleValue];
    }
    if (!persisted) themer_iconservices_lab_clear_stock68_identity();
    printf("[ICONSERVICES_LAB] stock68-identity persist entry=0x%llx "
           "uuid=\"%s\" tokenBytes=%zu pid=%d path=\"%s\" "
           "bundle=%s persisted=%d\n",
           (unsigned long long)(entry ? entry->image : 0),
           uuidKnown ? uuidText : "-",
           tokenKnown ? tokenCapture.objectLength : 0,
           remote_call_current_pid(),
           d->managerCachePath,
           d->targetBundle,
           persisted);
    if (r_is_objc_ptr(uuidString) && remote_call_current_success()) {
        r_msg2(uuidString, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(token) && remote_call_current_success()) {
        r_msg2(token, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(uuid) && remote_call_current_success()) {
        r_msg2(uuid, "release", 0, 0, 0, 0);
    }
    themer_iconservices_lab_free_data_capture(&tokenCapture);
    return persisted && remote_call_current_success();
}

static bool themer_iconservices_lab_load_stock68_identity(
    const char *targetBundle,
    const char *managerCachePath,
    NSString **uuidOut,
    NSData **tokenOut)
{
    if (uuidOut) *uuidOut = nil;
    if (tokenOut) *tokenOut = nil;
    if (!targetBundle || !targetBundle[0] ||
        !managerCachePath || !managerCachePath[0]) {
        return false;
    }
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    NSString *uuid = [defaults stringForKey:
        THEMER_ICONSERVICES_LAB_STOCK68_UUID_KEY];
    NSData *token = [defaults dataForKey:
        THEMER_ICONSERVICES_LAB_STOCK68_TOKEN_KEY];
    NSNumber *pid = [defaults objectForKey:
        THEMER_ICONSERVICES_LAB_STOCK68_PID_KEY];
    NSString *path = [defaults stringForKey:
        THEMER_ICONSERVICES_LAB_STOCK68_PATH_KEY];
    NSString *bundle = [defaults stringForKey:
        THEMER_ICONSERVICES_LAB_STOCK68_BUNDLE_KEY];
    NSString *expectedBundle = [NSString stringWithUTF8String:targetBundle];
    NSString *expectedPath = [NSString stringWithUTF8String:managerCachePath];
    bool ready = uuid.length > 0 && token.length > 0 &&
        pid.intValue == remote_call_current_pid() &&
        [path isEqualToString:expectedPath] &&
        [bundle isEqualToString:expectedBundle];
    if (!ready) return false;
    if (uuidOut) *uuidOut = uuid;
    if (tokenOut) *tokenOut = token;
    return true;
}

static uint64_t themer_iconservices_lab_make_remote_uuid(NSString *uuidText)
{
    if (uuidText.length == 0 || !remote_call_current_success()) return 0;
    uint64_t remoteString = r_nsstr_retained(uuidText.UTF8String);
    uint64_t uuidClass = r_class("NSUUID");
    uint64_t alloc = r_is_objc_ptr(uuidClass)
        ? r_msg2(uuidClass, "alloc", 0, 0, 0, 0) : 0;
    char types[192] = {0};
    bool abiReady = r_is_objc_ptr(alloc) && r_is_objc_ptr(remoteString) &&
        r_responds_main(alloc, "initWithUUIDString:") &&
        themer_iconservices_lab_method_types(
            alloc, "initWithUUIDString:", types, sizeof(types)) &&
        strcmp(types, "@24@0:8@16") == 0;
    uint64_t uuid = abiReady
        ? r_msg2_main(alloc, "initWithUUIDString:", remoteString, 0, 0, 0)
        : 0;
    if (r_is_objc_ptr(remoteString) && remote_call_current_success()) {
        r_msg2(remoteString, "release", 0, 0, 0, 0);
    }
    return remote_call_current_success() && r_is_objc_ptr(uuid) ? uuid : 0;
}

static bool themer_iconservices_lab_persist_cache_recovery(
    NSString *targetPath,
    NSString *backupPath,
    NSString *tempPath)
{
    if (targetPath.length == 0 || backupPath.length == 0 || tempPath.length == 0) {
        return false;
    }
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    [defaults setObject:targetPath
                 forKey:THEMER_ICONSERVICES_LAB_PENDING_CACHE_TARGET_KEY];
    [defaults setObject:backupPath
                 forKey:THEMER_ICONSERVICES_LAB_PENDING_CACHE_BACKUP_KEY];
    [defaults setObject:tempPath
                 forKey:THEMER_ICONSERVICES_LAB_PENDING_CACHE_TEMP_KEY];
    (void)[defaults synchronize];
    return [[defaults stringForKey:
                THEMER_ICONSERVICES_LAB_PENDING_CACHE_TARGET_KEY]
                    isEqualToString:targetPath] &&
        [[defaults stringForKey:
            THEMER_ICONSERVICES_LAB_PENDING_CACHE_BACKUP_KEY]
                isEqualToString:backupPath] &&
        [[defaults stringForKey:
            THEMER_ICONSERVICES_LAB_PENDING_CACHE_TEMP_KEY]
                isEqualToString:tempPath];
}

static void themer_iconservices_lab_clear_cache_recovery(void)
{
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    NSString *backupPath = [defaults stringForKey:
        THEMER_ICONSERVICES_LAB_PENDING_CACHE_BACKUP_KEY];
    NSString *tempPath = [defaults stringForKey:
        THEMER_ICONSERVICES_LAB_PENDING_CACHE_TEMP_KEY];
    if (backupPath.length > 0) unlink(backupPath.fileSystemRepresentation);
    if (tempPath.length > 0) unlink(tempPath.fileSystemRepresentation);
    [defaults removeObjectForKey:THEMER_ICONSERVICES_LAB_PENDING_CACHE_TARGET_KEY];
    [defaults removeObjectForKey:THEMER_ICONSERVICES_LAB_PENDING_CACHE_BACKUP_KEY];
    [defaults removeObjectForKey:THEMER_ICONSERVICES_LAB_PENDING_CACHE_TEMP_KEY];
    (void)[defaults synchronize];
}

static bool themer_iconservices_lab_restore_pending_cache_file(void)
{
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    NSString *targetPath = [defaults stringForKey:
        THEMER_ICONSERVICES_LAB_PENDING_CACHE_TARGET_KEY];
    NSString *backupPath = [defaults stringForKey:
        THEMER_ICONSERVICES_LAB_PENDING_CACHE_BACKUP_KEY];
    if (targetPath.length == 0 && backupPath.length == 0) return true;
    bool metadataReady = targetPath.length > 0 && backupPath.length > 0;
    bool backupReady = metadataReady &&
        themer_iconservices_lab_read_local_file(backupPath) != nil;
    uint64_t overwriteResult = backupReady
        ? themer_iconservices_lab_overwrite_file(targetPath, backupPath)
        : UINT64_MAX;
    bool restored = overwriteResult == 0 &&
        themer_iconservices_lab_local_files_equal(targetPath, backupPath);
    printf("[ICONSERVICES_LAB] cache-file-restore target=\"%s\" "
           "backup=\"%s\" metadata=%d backupReady=%d overwrite=%llu "
           "restored=%d\n",
           targetPath.UTF8String ?: "-",
           backupPath.UTF8String ?: "-",
           metadataReady,
           backupReady,
           (unsigned long long)overwriteResult,
           restored);
    if (restored) themer_iconservices_lab_clear_cache_recovery();
    return restored;
}

static bool themer_iconservices_lab_capture_dispatch_data(
    uint64_t data,
    size_t cap,
    ThemerIconServicesLabDataCapture *capture)
{
    if (!capture) return false;
    memset(capture, 0, sizeof(*capture));
    if (!r_is_objc_ptr(data) || cap == 0 ||
        !remote_call_current_success()) {
        return false;
    }

    uint64_t objectLength = r_dlsym_call(
        R_TIMEOUT, "dispatch_data_get_size", data,
        0, 0, 0, 0, 0, 0, 0);
    if (!remote_call_current_success() || objectLength > SIZE_MAX) {
        return false;
    }
    capture->objectLength = (size_t)objectLength;
    capture->capturedLength = capture->objectLength < cap
        ? capture->objectLength : cap;
    capture->truncated = capture->capturedLength < capture->objectLength;
    if (capture->capturedLength == 0) return true;

    uint64_t bufferSlot = r_dlsym_call(
        R_TIMEOUT, "malloc", sizeof(uint64_t),
        0, 0, 0, 0, 0, 0, 0);
    uint64_t sizeSlot = r_dlsym_call(
        R_TIMEOUT, "malloc", sizeof(uint64_t),
        0, 0, 0, 0, 0, 0, 0);
    bool slotsReady = bufferSlot && sizeSlot &&
        remote_write64(bufferSlot, 0) && remote_write64(sizeSlot, 0);
    uint64_t mappedData = slotsReady
        ? r_dlsym_call(
            R_TIMEOUT, "dispatch_data_create_map", data,
            bufferSlot, sizeSlot, 0, 0, 0, 0, 0)
        : 0;
    uint64_t remoteBytes = 0;
    uint64_t mappedLength = 0;
    bool mapRead = r_is_objc_ptr(mappedData) &&
        remote_read(bufferSlot, &remoteBytes, sizeof(remoteBytes)) &&
        remote_read(sizeSlot, &mappedLength, sizeof(mappedLength));
    bool boundsOK = mapRead && remoteBytes &&
        mappedLength >= capture->capturedLength;
    if (boundsOK) {
        capture->bytes = malloc(capture->capturedLength);
        boundsOK = capture->bytes &&
            remote_read(remoteBytes, capture->bytes,
                        capture->capturedLength);
    }
    if (!boundsOK) {
        themer_iconservices_lab_free_data_capture(capture);
    }
    if (r_is_objc_ptr(mappedData) && remote_call_current_success()) {
        r_msg2(mappedData, "release", 0, 0, 0, 0);
    }
    if (sizeSlot && remote_call_current_success()) r_free(sizeSlot);
    if (bufferSlot && remote_call_current_success()) r_free(bufferSlot);
    return boundsOK && remote_call_current_success();
}

static void themer_iconservices_lab_hex_bytes(
    const uint8_t *bytes,
    size_t length,
    char *output,
    size_t outputLength)
{
    static const char digits[] = "0123456789abcdef";
    if (!output || outputLength == 0) return;
    output[0] = '\0';
    if (!bytes || length == 0) return;
    size_t count = length;
    if (count > (outputLength - 1) / 2) {
        count = (outputLength - 1) / 2;
    }
    for (size_t i = 0; i < count; i++) {
        output[i * 2] = digits[(bytes[i] >> 4) & 0xf];
        output[i * 2 + 1] = digits[bytes[i] & 0xf];
    }
    output[count * 2] = '\0';
}

static bool themer_iconservices_lab_digest(
    const char *symbol,
    const uint8_t *bytes,
    size_t length,
    uint8_t *digest)
{
    if (!symbol || !bytes || length > UINT32_MAX || !digest) return false;
    typedef unsigned char *(*ThemerDigestFn)(
        const void *, uint32_t, unsigned char *);
    void *handle = dlopen(
        "/usr/lib/system/libcommonCrypto.dylib", RTLD_LAZY | RTLD_LOCAL);
    ThemerDigestFn function = (ThemerDigestFn)dlsym(RTLD_DEFAULT, symbol);
    if (!function && handle) {
        function = (ThemerDigestFn)dlsym(handle, symbol);
    }
    bool success = function &&
        function(bytes, (uint32_t)length, digest) == digest;
    if (handle) dlclose(handle);
    return success;
}

static void themer_stock68_append_u64_be(NSMutableData *data, uint64_t value)
{
    if (!data) return;
    uint8_t bytes[8] = {0};
    for (int i = 7; i >= 0; i--) {
        bytes[i] = (uint8_t)(value & 0xff);
        value >>= 8;
    }
    [data appendBytes:bytes length:sizeof(bytes)];
}

bool themer_spotlight_stock68_select_target(
    NSDictionary<NSString *, NSData *> *imageDataByBundle,
    char *targetOut, size_t targetLen,
    char *controlOut, size_t controlLen,
    char fingerprintOut[65])
{
    if (targetOut && targetLen) targetOut[0] = '\0';
    if (controlOut && controlLen) controlOut[0] = '\0';
    if (fingerprintOut) fingerprintOut[0] = '\0';
    NSDictionary<NSString *, NSData *> *normalized =
        themer_normalized_theme_data(imageDataByBundle);
    if (normalized.count == 0 || !fingerprintOut) return false;

    int selected = themer_iconservices_lab_select_bundles(
        normalized, NULL,
        targetOut, targetLen,
        controlOut, controlLen);
    if (selected < 1 || !targetOut || !targetOut[0]) return false;

    NSArray<NSString *> *keys = [normalized.allKeys
        sortedArrayUsingSelector:@selector(compare:)];
    NSMutableData *canonical = [NSMutableData data];
    static const uint8_t version[] = {'C','N','D','S','6','8','V','1'};
    [canonical appendBytes:version length:sizeof(version)];
    themer_stock68_append_u64_be(canonical, (uint64_t)keys.count);
    for (NSString *key in keys) {
        NSData *bundleData = [key dataUsingEncoding:NSUTF8StringEncoding];
        NSData *iconData = normalized[key];
        if (![bundleData isKindOfClass:NSData.class] ||
            ![iconData isKindOfClass:NSData.class]) {
            return false;
        }
        uint8_t iconDigest[32] = {0};
        if (!themer_iconservices_lab_digest(
                "CC_SHA256", iconData.bytes, iconData.length,
                iconDigest)) {
            return false;
        }
        themer_stock68_append_u64_be(canonical, bundleData.length);
        [canonical appendData:bundleData];
        themer_stock68_append_u64_be(canonical, iconData.length);
        [canonical appendBytes:iconDigest length:sizeof(iconDigest)];
    }
    uint8_t digest[32] = {0};
    bool known = themer_iconservices_lab_digest(
        "CC_SHA256", canonical.bytes, canonical.length, digest);
    if (known) {
        themer_iconservices_lab_hex_bytes(
            digest, sizeof(digest), fingerprintOut, 65);
    }
    printf("[ICONSERVICES_MATERIALIZE] selection target=%s control=%s "
           "entries=%lu fingerprint=%s ready=%d\n",
           targetOut,
           selected >= 2 && controlOut && controlOut[0] ? controlOut : "-",
           (unsigned long)normalized.count,
           known ? fingerprintOut : "-",
           known);
    return known;
}

static int themer_iconservices_lab_hex_nibble(uint8_t byte)
{
    if (byte >= '0' && byte <= '9') return byte - '0';
    if (byte >= 'a' && byte <= 'f') return byte - 'a' + 10;
    if (byte >= 'A' && byte <= 'F') return byte - 'A' + 10;
    return -1;
}

static bool themer_iconservices_lab_parse_uuid_text(
    const char *text,
    uint8_t output[16])
{
    if (!text || !output) return false;
    memset(output, 0, 16);
    // UUIDString is expected in the canonical 8-4-4-4-12 form. Accepting
    // arbitrary separators or silently ignoring trailing bytes would allow a
    // journal path to escape the exact record identity being verified.
    if (strlen(text) != 36 || text[8] != '-' || text[13] != '-' ||
        text[18] != '-' || text[23] != '-') {
        return false;
    }
    size_t written = 0;
    int nibble = -1;
    for (size_t i = 0; i < 36; i++) {
        if (text[i] == '-') continue;
        int value = themer_iconservices_lab_hex_nibble((uint8_t)text[i]);
        if (value < 0) return false;
        if (nibble < 0) {
            nibble = value;
        } else {
            if (written >= 16) return false;
            output[written++] = (uint8_t)((nibble << 4) | value);
            nibble = -1;
        }
    }
    return written == 16 && nibble < 0;
}

static size_t themer_iconservices_lab_count_byte_sequence(
    const uint8_t *bytes,
    size_t length,
    const uint8_t *needle,
    size_t needleLength,
    size_t *firstOffsetOut)
{
    if (firstOffsetOut) *firstOffsetOut = SIZE_MAX;
    if (!bytes || !needle || needleLength == 0 || length < needleLength) {
        return 0;
    }
    size_t count = 0;
    for (size_t offset = 0; offset <= length - needleLength; offset++) {
        if (memcmp(bytes + offset, needle, needleLength) != 0) continue;
        if (count == 0 && firstOffsetOut) *firstOffsetOut = offset;
        count++;
    }
    return count;
}

static bool themer_iconservices_lab_token_matches_digest(
    const uint8_t *token,
    size_t tokenLength,
    const uint8_t *digest,
    size_t digestLength)
{
    if (!token || !digest) return false;
    if (tokenLength == digestLength &&
        memcmp(token, digest, digestLength) == 0) {
        return true;
    }
    if (tokenLength != digestLength * 2) return false;
    for (size_t i = 0; i < digestLength; i++) {
        int high = themer_iconservices_lab_hex_nibble(token[i * 2]);
        int low = themer_iconservices_lab_hex_nibble(token[i * 2 + 1]);
        if (high < 0 || low < 0 ||
            (uint8_t)((high << 4) | low) != digest[i]) {
            return false;
        }
    }
    return true;
}

static uint64_t themer_iconservices_lab_retained_getter(
    uint64_t object,
    const char *selector)
{
    if (!r_is_objc_ptr(object) || !selector ||
        !remote_call_current_success() ||
        !r_responds_main(object, selector)) {
        return 0;
    }
    uint64_t value = r_msg2_main(object, selector, 0, 0, 0, 0);
    if (!r_is_objc_ptr(value) || !remote_call_current_success()) return 0;
    uint64_t retained = r_msg2(value, "retain", 0, 0, 0, 0);
    return remote_call_current_success() && r_is_objc_ptr(retained)
        ? retained : 0;
}

static bool themer_iconservices_lab_objects_equal(
    uint64_t first,
    uint64_t second)
{
    if (!r_is_objc_ptr(first) || !r_is_objc_ptr(second) ||
        !remote_call_current_success()) {
        return false;
    }
    if (first == second) return true;
    return r_responds_main(first, "isEqual:") &&
        (r_msg2_main(first, "isEqual:", second, 0, 0, 0) & 1) != 0 &&
        remote_call_current_success();
}

static bool themer_iconservices_lab_read_size_property(
    uint64_t object,
    const char *selector,
    double *widthOut,
    double *heightOut)
{
    if (widthOut) *widthOut = 0.0;
    if (heightOut) *heightOut = 0.0;
    if (!r_is_objc_ptr(object) || !selector ||
        !remote_call_current_success() ||
        !r_responds_main(object, selector)) {
        return false;
    }
    struct { double w; double h; } value = {0.0, 0.0};
    bool read = r_msg2_main_struct_ret(
        object, selector, &value, sizeof(value),
        NULL, 0, NULL, 0, NULL, 0, NULL, 0);
    if (widthOut) *widthOut = value.w;
    if (heightOut) *heightOut = value.h;
    return read && remote_call_current_success();
}

static bool themer_iconservices_lab_sizes_match(
    double firstWidth,
    double firstHeight,
    double secondWidth,
    double secondHeight)
{
    double dw = firstWidth - secondWidth;
    double dh = firstHeight - secondHeight;
    if (dw < 0.0) dw = -dw;
    if (dh < 0.0) dh = -dh;
    return dw < 0.01 && dh < 0.01;
}

static uint64_t themer_iconservices_lab_make_if_cache_image(
    uint64_t data,
    uint64_t uuid,
    uint64_t validationToken)
{
    if (!r_is_objc_ptr(data) || !r_is_objc_ptr(uuid) ||
        !r_is_objc_ptr(validationToken) ||
        !remote_call_current_success()) {
        return 0;
    }
    uint64_t imageClass = themer_lookup_class("IFCacheImage");
    uint64_t alloc = r_is_objc_ptr(imageClass)
        ? r_msg2(imageClass, "alloc", 0, 0, 0, 0) : 0;
    if (!r_is_objc_ptr(alloc) || !remote_call_current_success()) return 0;
    char types[192] = {0};
    if (!r_responds_main(alloc, "initWithData:uuid:validationToken:") ||
        !themer_iconservices_lab_method_types(
            alloc, "initWithData:uuid:validationToken:",
            types, sizeof(types)) ||
        strcmp(types, "@40@0:8@16@24@32") != 0) {
        printf("[ICONSERVICES_LAB] cacheimage-roundtrip unsupported "
               "selector=initWithData:uuid:validationToken: types=\"%s\"\n",
               types);
        if (remote_call_current_success()) {
            r_msg2(alloc, "release", 0, 0, 0, 0);
        }
        return 0;
    }
    uint64_t image = r_msg2_main(
        alloc, "initWithData:uuid:validationToken:",
        data, uuid, validationToken, 0);
    printf("[ICONSERVICES_LAB] cacheimage-roundtrip construct "
           "data=0x%llx uuid=0x%llx token=0x%llx image=0x%llx "
           "success=%d\n",
           (unsigned long long)data,
           (unsigned long long)uuid,
           (unsigned long long)validationToken,
           (unsigned long long)image,
           r_is_objc_ptr(image));
    // As with the CGImage initializer, a nil result owns any partial-object
    // teardown. Do not speculatively release alloc after invoking init.
    return remote_call_current_success() && r_is_objc_ptr(image) ? image : 0;
}

static uint64_t themer_iconservices_lab_make_if_cache_image_without_token(
    uint64_t data,
    uint64_t uuid)
{
    if (!r_is_objc_ptr(data) || !r_is_objc_ptr(uuid) ||
        !remote_call_current_success()) {
        return 0;
    }
    uint64_t imageClass = themer_lookup_class("IFCacheImage");
    uint64_t alloc = r_is_objc_ptr(imageClass)
        ? r_msg2(imageClass, "alloc", 0, 0, 0, 0) : 0;
    if (!r_is_objc_ptr(alloc) || !remote_call_current_success()) return 0;
    char types[192] = {0};
    if (!r_responds_main(alloc, "initWithData:uuid:") ||
        !themer_iconservices_lab_method_types(
            alloc, "initWithData:uuid:", types, sizeof(types)) ||
        types[0] != '@') {
        printf("[ICONSERVICES_LAB] construction-probe unsupported "
               "selector=initWithData:uuid: types=\"%s\"\n",
               types);
        if (remote_call_current_success()) {
            r_msg2(alloc, "release", 0, 0, 0, 0);
        }
        return 0;
    }
    uint64_t image = r_msg2_main(
        alloc, "initWithData:uuid:", data, uuid, 0, 0);
    printf("[ICONSERVICES_LAB] construction-probe construct-no-token "
           "data=0x%llx uuid=0x%llx image=0x%llx success=%d\n",
           (unsigned long long)data,
           (unsigned long long)uuid,
           (unsigned long long)image,
           r_is_objc_ptr(image));
    // A nil initializer result owns any partial-object teardown. As with the
    // proven three-argument initializer, do not speculatively release alloc.
    return remote_call_current_success() && r_is_objc_ptr(image) ? image : 0;
}

// Consumes one +1 IFConcreteImage and returns a +1 data-backed IFCacheImage.
// The source image, serialized data, and fresh UUID are all released before the
// returned object is accepted, proving the cache image retains its own inputs.
static uint64_t themer_iconservices_lab_make_tokenless_cache_image(
    uint64_t concreteImage,
    double expectedWidth,
    double expectedHeight,
    double expectedScale,
    double expectedMinimumWidth,
    double expectedMinimumHeight,
    bool *readyOut)
{
    if (readyOut) *readyOut = false;
    if (!r_is_objc_ptr(concreteImage) || expectedWidth <= 0.0 ||
        expectedHeight <= 0.0 || expectedScale <= 0.0 ||
        expectedMinimumWidth <= 0.0 || expectedMinimumHeight <= 0.0 ||
        !remote_call_current_success()) {
        if (r_is_objc_ptr(concreteImage) && remote_call_current_success()) {
            r_msg2(concreteImage, "release", 0, 0, 0, 0);
        }
        return 0;
    }
    uint64_t ioFailuresBefore = remote_call_current_io_failure_count();
    bool minimumSet = themer_iconservices_lab_set_minimum_size(
        concreteImage, expectedMinimumWidth, expectedMinimumHeight);
    uint64_t sourceData = minimumSet
        ? themer_iconservices_lab_retained_getter(concreteImage, "data") : 0;
    ThemerIconServicesLabDataCapture sourceCapture = {0};
    bool sourceCaptured = r_is_objc_ptr(sourceData) &&
        themer_iconservices_lab_capture_nsdata(
            sourceData, THEMER_ICONSERVICES_LAB_DATA_CAPTURE_CAP,
            &sourceCapture);
    bool sourceComplete = sourceCaptured && !sourceCapture.truncated &&
        sourceCapture.objectLength > 0;

    uint64_t uuidClass = r_class("NSUUID");
    uint64_t uuidAlloc = r_is_objc_ptr(uuidClass)
        ? r_msg2(uuidClass, "alloc", 0, 0, 0, 0) : 0;
    uint64_t sourceUuid = r_is_objc_ptr(uuidAlloc)
        ? r_msg2_main(uuidAlloc, "init", 0, 0, 0, 0) : 0;
    char sourceUuidText[160] = {0};
    themer_read_remote_description(
        sourceUuid, sourceUuidText, sizeof(sourceUuidText));
    uint64_t cacheImage = sourceComplete && r_is_objc_ptr(sourceUuid)
        ? themer_iconservices_lab_make_if_cache_image_without_token(
            sourceData, sourceUuid) : 0;

    // Remove every external owner before validating the new object's getters.
    if (r_is_objc_ptr(concreteImage) && remote_call_current_success()) {
        r_msg2(concreteImage, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(sourceData) && remote_call_current_success()) {
        r_msg2(sourceData, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(sourceUuid) && remote_call_current_success()) {
        r_msg2(sourceUuid, "release", 0, 0, 0, 0);
    }

    char cacheClass[96] = {0};
    themer_read_class_name(cacheImage, cacheClass, sizeof(cacheClass));
    bool classOK = strcmp(cacheClass, "IFCacheImage") == 0;
    uint64_t retainedData = classOK
        ? themer_iconservices_lab_retained_getter(cacheImage, "data") : 0;
    uint64_t retainedUuid = classOK
        ? themer_iconservices_lab_retained_getter(cacheImage, "uuid") : 0;
    uint64_t retainedToken = classOK
        ? themer_iconservices_lab_retained_getter(
            cacheImage, "validationToken") : 0;
    ThemerIconServicesLabDataCapture retainedCapture = {0};
    ThemerIconServicesLabDataCapture tokenCapture = {0};
    bool retainedCaptured = r_is_objc_ptr(retainedData) &&
        themer_iconservices_lab_capture_nsdata(
            retainedData, THEMER_ICONSERVICES_LAB_DATA_CAPTURE_CAP,
            &retainedCapture);
    bool dataSelfRetained = sourceComplete && retainedCaptured &&
        !retainedCapture.truncated &&
        retainedCapture.objectLength == sourceCapture.objectLength &&
        retainedCapture.capturedLength == sourceCapture.capturedLength &&
        memcmp(retainedCapture.bytes, sourceCapture.bytes,
               sourceCapture.capturedLength) == 0;
    char retainedUuidText[160] = {0};
    themer_read_remote_description(
        retainedUuid, retainedUuidText, sizeof(retainedUuidText));
    bool uuidSelfRetained = sourceUuidText[0] && retainedUuidText[0] &&
        strcmp(sourceUuidText, retainedUuidText) == 0;
    bool tokenCaptured = r_is_objc_ptr(retainedToken) &&
        themer_iconservices_lab_capture_nsdata(
            retainedToken, THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP,
            &tokenCapture);
    bool tokenIsNil = !r_is_objc_ptr(retainedToken);
    bool tokenAcceptable = tokenIsNil ||
        (tokenCaptured && !tokenCapture.truncated &&
         tokenCapture.objectLength > 0);

    bool geometry = classOK &&
        themer_iconservices_lab_image_geometry_matches(
            cacheImage, expectedWidth, expectedHeight, expectedScale);
    double pixelWidth = 0.0, pixelHeight = 0.0;
    double minimumWidth = 0.0, minimumHeight = 0.0;
    double iconWidth = 0.0, iconHeight = 0.0;
    bool properties =
        themer_iconservices_lab_read_size_property(
            cacheImage, "pixelSize", &pixelWidth, &pixelHeight) &&
        themer_iconservices_lab_read_size_property(
            cacheImage, "minimumSize", &minimumWidth, &minimumHeight) &&
        themer_iconservices_lab_read_size_property(
            cacheImage, "iconSize", &iconWidth, &iconHeight) &&
        themer_iconservices_lab_sizes_match(
            pixelWidth, pixelHeight,
            expectedWidth * expectedScale, expectedHeight * expectedScale) &&
        themer_iconservices_lab_sizes_match(
            minimumWidth, minimumHeight,
            expectedMinimumWidth, expectedMinimumHeight) &&
        themer_iconservices_lab_sizes_match(
            iconWidth, iconHeight, expectedWidth, expectedHeight);
    uint64_t cgImage = classOK && r_responds_main(cacheImage, "CGImage")
        ? r_msg2_main(cacheImage, "CGImage", 0, 0, 0, 0) : 0;
    uint64_t cgWidth = cgImage
        ? r_dlsym_call(R_TIMEOUT, "CGImageGetWidth",
                       cgImage, 0, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t cgHeight = cgImage
        ? r_dlsym_call(R_TIMEOUT, "CGImageGetHeight",
                       cgImage, 0, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t expectedCGWidth =
        (uint64_t)(expectedWidth * expectedScale + 0.5);
    uint64_t expectedCGHeight =
        (uint64_t)(expectedHeight * expectedScale + 0.5);
    uint64_t images[1] = {cacheImage};
    uint64_t testBag = classOK
        ? themer_iconservices_lab_make_bag_from_images(images, 1) : 0;
    uint64_t routed = r_is_objc_ptr(testBag)
        ? themer_iconservices_lab_image_for_size_scale(
            testBag, expectedWidth, expectedHeight, expectedScale) : 0;
    bool routeExact = themer_spotlight_images_match(cacheImage, routed);
    uint64_t ioFailuresAfter = remote_call_current_io_failure_count();
    bool transportClean = remote_call_current_success() &&
        ioFailuresAfter == ioFailuresBefore;
    bool ready = minimumSet && classOK && dataSelfRetained &&
        uuidSelfRetained && tokenAcceptable && geometry && properties &&
        cgImage && cgWidth == expectedCGWidth && cgHeight == expectedCGHeight &&
        r_is_objc_ptr(testBag) && routeExact && transportClean;

    printf("[ICONSERVICES_LAB] tokenless-cacheimage payload "
           "source=0x%llx data=%zu/%zu/truncated=%d uuid=\"%s\" "
           "image=0x%llx class=%s classOK=%d dataSelfRetained=%d "
           "uuidSelfRetained=%d token=0x%llx/nil=%d/length=%zu/acceptable=%d "
           "geometry=%d properties=%d pixel=%.1fx%.1f minimum=%.1fx%.1f "
           "icon=%.1fx%.1f cgImage=0x%llx pixels=%llux%llu "
           "bag=0x%llx routed=0x%llx exact=%d ioFailures=%llu->%llu "
           "transportClean=%d ready=%d\n",
           (unsigned long long)concreteImage,
           sourceCapture.objectLength,
           sourceCapture.capturedLength,
           sourceCapture.truncated,
           sourceUuidText,
           (unsigned long long)cacheImage,
           cacheClass[0] ? cacheClass : "-",
           classOK,
           dataSelfRetained,
           uuidSelfRetained,
           (unsigned long long)retainedToken,
           tokenIsNil,
           tokenCapture.objectLength,
           tokenAcceptable,
           geometry,
           properties,
           pixelWidth, pixelHeight,
           minimumWidth, minimumHeight,
           iconWidth, iconHeight,
           (unsigned long long)cgImage,
           (unsigned long long)cgWidth,
           (unsigned long long)cgHeight,
           (unsigned long long)testBag,
           (unsigned long long)routed,
           routeExact,
           (unsigned long long)ioFailuresBefore,
           (unsigned long long)ioFailuresAfter,
           transportClean,
           ready);

    if (r_is_objc_ptr(testBag) && remote_call_current_success()) {
        r_msg2(testBag, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(retainedToken) && remote_call_current_success()) {
        r_msg2(retainedToken, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(retainedUuid) && remote_call_current_success()) {
        r_msg2(retainedUuid, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(retainedData) && remote_call_current_success()) {
        r_msg2(retainedData, "release", 0, 0, 0, 0);
    }
    if (!ready && r_is_objc_ptr(cacheImage) &&
        remote_call_current_success()) {
        r_msg2(cacheImage, "release", 0, 0, 0, 0);
        cacheImage = 0;
    }
    themer_iconservices_lab_free_data_capture(&tokenCapture);
    themer_iconservices_lab_free_data_capture(&retainedCapture);
    themer_iconservices_lab_free_data_capture(&sourceCapture);
    if (readyOut) *readyOut = ready;
    return ready && remote_call_current_success() ? cacheImage : 0;
}

static uint64_t themer_iconservices_lab_retained_store(uint64_t iconCache)
{
    if (!r_is_objc_ptr(iconCache) || !remote_call_current_success()) return 0;
    char types[192] = {0};
    bool abiReady = r_responds_main(iconCache, "store") &&
        themer_iconservices_lab_method_types(
            iconCache, "store", types, sizeof(types)) &&
        strcmp(types, "@16@0:8") == 0;
    return abiReady
        ? r_msg2_main_retained_object(iconCache, "store", 0, 0, 0, 0)
        : 0;
}

static void themer_iconservices_lab_log_store_filesystem_access(
    uint64_t iconCache)
{
    if (!r_is_objc_ptr(iconCache) || !remote_call_current_success()) return;

    uint64_t store = themer_iconservices_lab_retained_store(iconCache);
    char storeURLTypes[192] = {0};
    bool storeURLABI = r_is_objc_ptr(store) &&
        r_responds_main(store, "storeURL") &&
        themer_iconservices_lab_method_types(
            store, "storeURL", storeURLTypes, sizeof(storeURLTypes)) &&
        strcmp(storeURLTypes, "@16@0:8") == 0;
    uint64_t storeURL = storeURLABI
        ? r_msg2_main_retained_object(store, "storeURL", 0, 0, 0, 0) : 0;

    char pathTypes[192] = {0};
    bool pathABI = r_is_objc_ptr(storeURL) &&
        r_responds_main(storeURL, "path") &&
        themer_iconservices_lab_method_types(
            storeURL, "path", pathTypes, sizeof(pathTypes)) &&
        strcmp(pathTypes, "@16@0:8") == 0;
    uint64_t path = pathABI
        ? r_msg2_main_retained_object(storeURL, "path", 0, 0, 0, 0) : 0;
    char pathText[1024] = {0};
    bool pathKnown = r_is_objc_ptr(path) &&
        r_read_nsstring(path, pathText, sizeof(pathText));

    uint64_t fileManagerClass = r_class("NSFileManager");
    char defaultTypes[192] = {0};
    bool defaultABI = r_is_objc_ptr(fileManagerClass) &&
        r_responds_main(fileManagerClass, "defaultManager") &&
        themer_iconservices_lab_method_types(
            fileManagerClass, "defaultManager",
            defaultTypes, sizeof(defaultTypes)) &&
        strcmp(defaultTypes, "@16@0:8") == 0;
    uint64_t fileManager = defaultABI
        ? r_msg2_main_retained_object(
            fileManagerClass, "defaultManager", 0, 0, 0, 0) : 0;

    char existsTypes[192] = {0};
    char readableTypes[192] = {0};
    char writableTypes[192] = {0};
    bool accessABI = r_is_objc_ptr(fileManager) && r_is_objc_ptr(path) &&
        r_responds_main(fileManager, "fileExistsAtPath:") &&
        themer_iconservices_lab_method_types(
            fileManager, "fileExistsAtPath:",
            existsTypes, sizeof(existsTypes)) &&
        strcmp(existsTypes, "B24@0:8@16") == 0 &&
        r_responds_main(fileManager, "isReadableFileAtPath:") &&
        themer_iconservices_lab_method_types(
            fileManager, "isReadableFileAtPath:",
            readableTypes, sizeof(readableTypes)) &&
        strcmp(readableTypes, "B24@0:8@16") == 0 &&
        r_responds_main(fileManager, "isWritableFileAtPath:") &&
        themer_iconservices_lab_method_types(
            fileManager, "isWritableFileAtPath:",
            writableTypes, sizeof(writableTypes)) &&
        strcmp(writableTypes, "B24@0:8@16") == 0;
    bool exists = accessABI &&
        (r_msg2_main(fileManager, "fileExistsAtPath:", path, 0, 0, 0) & 1) != 0;
    bool readable = accessABI && remote_call_current_success() &&
        (r_msg2_main(fileManager, "isReadableFileAtPath:", path, 0, 0, 0) & 1) != 0;
    bool writable = accessABI && remote_call_current_success() &&
        (r_msg2_main(fileManager, "isWritableFileAtPath:", path, 0, 0, 0) & 1) != 0;

    uint64_t uid = remote_call_current_success()
        ? r_dlsym_call(R_TIMEOUT, "getuid", 0, 0, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t euid = remote_call_current_success()
        ? r_dlsym_call(R_TIMEOUT, "geteuid", 0, 0, 0, 0, 0, 0, 0, 0) : 0;

    NSString *localPath = pathKnown
        ? [NSString stringWithUTF8String:pathText] : nil;
    NSFileManager *localFileManager = NSFileManager.defaultManager;
    bool localExists = localPath.length > 0 &&
        [localFileManager fileExistsAtPath:localPath];
    bool localReadable = localPath.length > 0 &&
        [localFileManager isReadableFileAtPath:localPath];
    bool localWritable = localPath.length > 0 &&
        [localFileManager isWritableFileAtPath:localPath];
    printf("[ICONSERVICES_LAB] store-filesystem store=0x%llx "
           "storeURLTypes=\"%s\" pathTypes=\"%s\" path=\"%s\" "
           "remoteABI=%d remoteExists=%d remoteReadable=%d remoteWritable=%d "
           "remoteUID=%llu remoteEUID=%llu localExists=%d localReadable=%d "
           "localWritable=%d localUID=%u localEUID=%u\n",
           (unsigned long long)store,
           storeURLTypes,
           pathTypes,
           pathKnown ? pathText : "-",
           accessABI,
           exists,
           readable,
           writable,
           (unsigned long long)uid,
           (unsigned long long)euid,
           localExists,
           localReadable,
           localWritable,
           (unsigned)getuid(),
           (unsigned)geteuid());

    if (r_is_objc_ptr(fileManager) && remote_call_current_success()) {
        r_msg2(fileManager, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(path) && remote_call_current_success()) {
        r_msg2(path, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(storeURL) && remote_call_current_success()) {
        r_msg2(storeURL, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(store) && remote_call_current_success()) {
        r_msg2(store, "release", 0, 0, 0, 0);
    }
}

static void themer_iconservices_lab_log_local_stock_store_file(
    const ThemerIconServicesLabDiscovery *d)
{
    if (!d || !d->managerCachePathKnown || d->primaryEntryIndex < 0 ||
        d->primaryEntryIndex >= d->stockEntryCount ||
        !remote_call_current_success()) {
        return;
    }

    uint64_t image = d->stockEntries[d->primaryEntryIndex].image;
    char imageClass[96] = {0};
    themer_read_class_name(image, imageClass, sizeof(imageClass));
    bool imageClassOK = strcmp(imageClass, "IFCacheImage") == 0;
    char uuidTypes[192] = {0};
    bool uuidABI = imageClassOK && r_is_objc_ptr(image) &&
        r_responds_main(image, "uuid") &&
        themer_iconservices_lab_method_types(
            image, "uuid", uuidTypes, sizeof(uuidTypes)) &&
        strcmp(uuidTypes, "@16@0:8") == 0;
    uint64_t uuid = uuidABI
        ? r_msg2_main_retained_object(image, "uuid", 0, 0, 0, 0) : 0;

    char stringTypes[192] = {0};
    bool stringABI = r_is_objc_ptr(uuid) &&
        r_responds_main(uuid, "UUIDString") &&
        themer_iconservices_lab_method_types(
            uuid, "UUIDString", stringTypes, sizeof(stringTypes)) &&
        strcmp(stringTypes, "@16@0:8") == 0;
    uint64_t uuidString = stringABI
        ? r_msg2_main_retained_object(uuid, "UUIDString", 0, 0, 0, 0) : 0;
    char uuidText[80] = {0};
    bool uuidKnown = r_is_objc_ptr(uuidString) &&
        r_read_nsstring(uuidString, uuidText, sizeof(uuidText));

    NSString *storePath = [NSString stringWithUTF8String:d->managerCachePath];
    NSString *fileName = uuidKnown
        ? [NSString stringWithFormat:@"%s.isdata", uuidText] : nil;
    NSString *filePath = fileName.length > 0
        ? [storePath stringByAppendingPathComponent:fileName] : nil;

    struct stat st = {0};
    errno = 0;
    int statResult = filePath.length > 0
        ? stat(filePath.fileSystemRepresentation, &st) : -1;
    int statError = statResult == 0 ? 0 : errno;

    errno = 0;
    int fd = filePath.length > 0
        ? open(filePath.fileSystemRepresentation, O_RDONLY) : -1;
    int openError = fd >= 0 ? 0 : errno;
    uint8_t prefixBytes[16] = {0};
    errno = 0;
    ssize_t prefixLength = fd >= 0
        ? pread(fd, prefixBytes, sizeof(prefixBytes), 0) : -1;
    int readError = prefixLength >= 0 ? 0 : errno;
    if (fd >= 0) close(fd);

    char prefixHex[sizeof(prefixBytes) * 2 + 1] = {0};
    if (prefixLength > 0) {
        size_t count = (size_t)prefixLength < sizeof(prefixBytes)
            ? (size_t)prefixLength : sizeof(prefixBytes);
        for (size_t i = 0; i < count; i++) {
            snprintf(prefixHex + (i * 2),
                     sizeof(prefixHex) - (i * 2),
                     "%02x", prefixBytes[i]);
        }
    }
    printf("[ICONSERVICES_LAB] local-stock-store-file index=%d "
           "class=%s uuidTypes=\"%s\" uuid=%s path=\"%s\" "
           "stat=%d statErrno=%d "
           "regular=%d size=%lld mode=%o owner=%u:%u open=%d openErrno=%d "
           "pread=%lld preadErrno=%d prefix=%s\n",
           d->primaryEntryIndex,
           imageClass[0] ? imageClass : "-",
           uuidTypes,
           uuidKnown ? uuidText : "-",
           filePath.UTF8String ?: "-",
           statResult,
           statError,
           statResult == 0 && S_ISREG(st.st_mode),
           statResult == 0 ? (long long)st.st_size : -1LL,
           statResult == 0 ? (unsigned)(st.st_mode & 07777) : 0,
           statResult == 0 ? (unsigned)st.st_uid : 0,
           statResult == 0 ? (unsigned)st.st_gid : 0,
           fd >= 0,
           openError,
           (long long)prefixLength,
           readError,
           prefixHex[0] ? prefixHex : "-");

    if (r_is_objc_ptr(uuidString) && remote_call_current_success()) {
        r_msg2(uuidString, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(uuid) && remote_call_current_success()) {
        r_msg2(uuid, "release", 0, 0, 0, 0);
    }
}

static bool themer_iconservices_lab_remove_store_unit(
    uint64_t iconCache,
    uint64_t uuid)
{
    // Existing-cache-file route: the caller may pass a nil unit UUID when only
    // the forward inode overwrite is armed. The recovery metadata short-circuits
    // before any store-unit lookup.
    NSString *cacheTarget = [NSUserDefaults.standardUserDefaults
        stringForKey:THEMER_ICONSERVICES_LAB_PENDING_CACHE_TARGET_KEY];
    if (cacheTarget.length > 0) {
        return themer_iconservices_lab_restore_pending_cache_file();
    }
    if (!r_is_objc_ptr(iconCache) || !r_is_objc_ptr(uuid) ||
        !remote_call_current_success()) {
        return false;
    }
    uint64_t store = themer_iconservices_lab_retained_store(iconCache);
    char removeTypes[192] = {0};
    char lookupTypes[192] = {0};
    bool abiReady = r_is_objc_ptr(store) &&
        r_responds_main(store, "removeUnitForUUID:") &&
        themer_iconservices_lab_method_types(
            store, "removeUnitForUUID:", removeTypes,
            sizeof(removeTypes)) &&
        strcmp(removeTypes, "B24@0:8@16") == 0 &&
        r_responds_main(store, "unitForUUID:") &&
        themer_iconservices_lab_method_types(
            store, "unitForUUID:", lookupTypes,
            sizeof(lookupTypes)) &&
        strcmp(lookupTypes, "@24@0:8@16") == 0;
    uint64_t before = abiReady
        ? r_msg2_main(store, "unitForUUID:", uuid, 0, 0, 0) : 0;
    bool beforePresent = r_is_objc_ptr(before);
    uint64_t removedRaw = abiReady && beforePresent
        ? r_msg2_main(store, "removeUnitForUUID:", uuid, 0, 0, 0) : 1;
    uint64_t after = abiReady && remote_call_current_success()
        ? r_msg2_main(store, "unitForUUID:", uuid, 0, 0, 0) : 0;
    bool removed = abiReady && (!beforePresent || (removedRaw & 1) != 0) &&
        !r_is_objc_ptr(after) && remote_call_current_success();
    printf("[ICONSERVICES_LAB] themed-store-remove store=0x%llx "
           "uuid=0x%llx abiReady=%d before=0x%llx removedRaw=%llu "
           "after=0x%llx removed=%d\n",
           (unsigned long long)store,
           (unsigned long long)uuid,
           abiReady,
           (unsigned long long)before,
           (unsigned long long)(removedRaw & 1),
           (unsigned long long)after,
           removed);
    if (r_is_objc_ptr(store) && remote_call_current_success()) {
        r_msg2(store, "release", 0, 0, 0, 0);
    }
    return removed;
}

static void themer_iconservices_lab_clear_pending_store_uuid(void)
{
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    [defaults removeObjectForKey:THEMER_ICONSERVICES_LAB_PENDING_STORE_UUID_KEY];
    (void)[defaults synchronize];
}

static bool themer_iconservices_lab_remove_pending_store_unit(
    uint64_t iconCache)
{
    if (!themer_iconservices_lab_restore_pending_cache_file()) return false;
    NSString *text = [NSUserDefaults.standardUserDefaults
        stringForKey:THEMER_ICONSERVICES_LAB_PENDING_STORE_UUID_KEY];
    if (text.length == 0) return true;
    uint64_t remoteString = r_nsstr_retained(text.UTF8String);
    uint64_t uuidClass = r_class("NSUUID");
    uint64_t alloc = r_is_objc_ptr(uuidClass)
        ? r_msg2(uuidClass, "alloc", 0, 0, 0, 0) : 0;
    char types[192] = {0};
    bool abiReady = r_is_objc_ptr(alloc) &&
        r_responds_main(alloc, "initWithUUIDString:") &&
        themer_iconservices_lab_method_types(
            alloc, "initWithUUIDString:", types, sizeof(types)) &&
        strcmp(types, "@24@0:8@16") == 0;
    uint64_t uuid = abiReady && r_is_objc_ptr(remoteString)
        ? r_msg2_main(alloc, "initWithUUIDString:", remoteString, 0, 0, 0)
        : 0;
    bool removed = r_is_objc_ptr(uuid) &&
        themer_iconservices_lab_remove_store_unit(iconCache, uuid);
    if (removed) themer_iconservices_lab_clear_pending_store_uuid();
    printf("[ICONSERVICES_LAB] themed-store pending cleanup "
           "uuid=%s abiReady=%d removed=%d\n",
           text.UTF8String ?: "-",
           abiReady,
           removed);
    if (r_is_objc_ptr(uuid) && remote_call_current_success()) {
        r_msg2(uuid, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(remoteString) && remote_call_current_success()) {
        r_msg2(remoteString, "release", 0, 0, 0, 0);
    }
    return removed;
}

// Consumes concreteImage and returns one +1 existing-record IFCacheImage. A
// live stock68 entry is preferred; the Probe-bound UUID/token identity is the
// fallback when IconServices prunes the 68 entry before the Seed session.
static uint64_t themer_iconservices_lab_make_store_backed_cache_image(
    uint64_t concreteImage,
    const ThemerIconServicesLabBagEntry *stock68Entry,
    const char *targetBundle,
    const char *managerCachePath,
    double expectedWidth,
    double expectedHeight,
    double expectedScale,
    double expectedMinimumWidth,
    double expectedMinimumHeight,
    bool *storeUnitAddedOut,
    bool *readyOut)
{
    if (storeUnitAddedOut) *storeUnitAddedOut = false;
    if (readyOut) *readyOut = false;
    NSString *persistedUUIDText = nil;
    NSData *persistedTokenData = nil;
    bool persistedIdentity = themer_iconservices_lab_load_stock68_identity(
        targetBundle, managerCachePath,
        &persistedUUIDText, &persistedTokenData);
    bool liveIdentity = stock68Entry &&
        r_is_objc_ptr(stock68Entry->image);
    if (!r_is_objc_ptr(concreteImage) ||
        (!liveIdentity && !persistedIdentity) ||
        !managerCachePath || !managerCachePath[0] ||
        !remote_call_current_success()) {
        if (r_is_objc_ptr(concreteImage) && remote_call_current_success()) {
            r_msg2(concreteImage, "release", 0, 0, 0, 0);
        }
        printf("[ICONSERVICES_LAB] cache-file-overwrite unavailable "
               "image=0x%llx donor=0x%llx live=%d persisted=%d "
               "path=\"%s\" bundle=%s\n",
               (unsigned long long)concreteImage,
               (unsigned long long)(stock68Entry ? stock68Entry->image : 0),
               liveIdentity,
               persistedIdentity,
               managerCachePath ? managerCachePath : "-",
               targetBundle ? targetBundle : "-");
        return 0;
    }

    // 1. Set the 65-pt minimum and capture the themed serialized data.
    bool minimumSet = themer_iconservices_lab_set_minimum_size(
        concreteImage, expectedMinimumWidth, expectedMinimumHeight);
    uint64_t sourceData = minimumSet
        ? themer_iconservices_lab_retained_getter(concreteImage, "data") : 0;
    ThemerIconServicesLabDataCapture sourceCapture = {0};
    bool sourceCaptured = r_is_objc_ptr(sourceData) &&
        themer_iconservices_lab_capture_nsdata(
            sourceData, THEMER_ICONSERVICES_LAB_DATA_CAPTURE_CAP,
            &sourceCapture);
    bool sourceComplete = sourceCaptured && !sourceCapture.truncated &&
        sourceCapture.objectLength > 0;

    // 2. Resolve the genuine stock68 donor identity (uuid + validationToken).
    uint64_t donor = liveIdentity ? stock68Entry->image : 0;
    char donorClass[96] = {0};
    if (liveIdentity) {
        themer_read_class_name(donor, donorClass, sizeof(donorClass));
    }
    bool donorClassOK = liveIdentity &&
        strcmp(donorClass, "IFCacheImage") == 0;
    uint64_t donorUUID = donorClassOK
        ? themer_iconservices_lab_retained_getter(donor, "uuid")
        : themer_iconservices_lab_make_remote_uuid(persistedUUIDText);
    uint64_t donorToken = donorClassOK
        ? themer_iconservices_lab_retained_getter(
            donor, "validationToken")
        : themer_make_remote_nsdata(persistedTokenData);
    uint64_t uuidString = r_is_objc_ptr(donorUUID)
        ? themer_iconservices_lab_retained_getter(donorUUID, "UUIDString") : 0;
    char uuidText[80] = {0};
    bool uuidKnown = r_is_objc_ptr(uuidString) &&
        r_read_nsstring(uuidString, uuidText, sizeof(uuidText));

    // 3. Derive the existing record path and read its exact bytes.
    NSString *storePath = uuidKnown
        ? [NSString stringWithUTF8String:managerCachePath] : nil;
    NSString *fileName = uuidKnown
        ? [NSString stringWithFormat:@"%s.isdata", uuidText] : nil;
    NSString *targetPath = fileName.length > 0
        ? [storePath stringByAppendingPathComponent:fileName] : nil;
    NSData *targetData = targetPath.length > 0
        ? themer_iconservices_lab_read_local_file(targetPath) : nil;
    NSUInteger targetLength = targetData.length;
    uint64_t remoteStockData = targetData.length > 0
        ? themer_make_remote_nsdata(targetData) : 0;
    uint64_t stockValidationImage = r_is_objc_ptr(remoteStockData) &&
            r_is_objc_ptr(donorUUID) && r_is_objc_ptr(donorToken)
        ? themer_iconservices_lab_make_if_cache_image(
            remoteStockData, donorUUID, donorToken)
        : 0;
    bool stockIdentityValid = r_is_objc_ptr(stockValidationImage) &&
        themer_iconservices_lab_image_geometry_matches(
            stockValidationImage, expectedWidth, expectedHeight,
            expectedScale);

    NSString *recoveryDir = themer_iconservices_lab_cache_recovery_directory();
    NSString *backupPath = nil;
    NSString *tempPath = nil;
    if (targetData != nil && recoveryDir.length > 0) {
        [[NSFileManager defaultManager]
            createDirectoryAtPath:recoveryDir
            withIntermediateDirectories:YES
            attributes:nil error:NULL];
        backupPath = [recoveryDir stringByAppendingPathComponent:
            [NSString stringWithFormat:@"%s.isdata.bak", uuidText]];
        tempPath = [recoveryDir stringByAppendingPathComponent:
            [NSString stringWithFormat:@"%s.isdata.themed", uuidText]];
    }
    bool pathsReady = stockIdentityValid && targetData != nil &&
        targetLength > 0 && backupPath.length > 0 && tempPath.length > 0;
    bool fitsInRecord = sourceComplete &&
        sourceCapture.objectLength <= targetLength;

    // 4. Pad the themed data to the exact existing record length.
    NSMutableData *paddedData = nil;
    if (pathsReady && fitsInRecord) {
        paddedData = [NSMutableData dataWithLength:targetLength];
        memcpy(paddedData.mutableBytes, sourceCapture.bytes,
               sourceCapture.objectLength);
        if (targetLength > sourceCapture.objectLength) {
            memset((uint8_t *)paddedData.mutableBytes +
                       sourceCapture.objectLength,
                   0,
                   targetLength - sourceCapture.objectLength);
        }
    }

    // 5. Validate the padded bytes still construct a correct 68-pt cache image
    //    under the stock68 uuid + token before touching any existing inode.
    uint64_t remotePadded = paddedData != nil
        ? themer_make_remote_nsdata(paddedData) : 0;
    uint64_t cacheImage = r_is_objc_ptr(remotePadded) &&
            r_is_objc_ptr(donorUUID) && r_is_objc_ptr(donorToken)
        ? themer_iconservices_lab_make_if_cache_image(
            remotePadded, donorUUID, donorToken)
        : 0;
    bool geometry = r_is_objc_ptr(cacheImage) &&
        themer_iconservices_lab_image_geometry_matches(
            cacheImage, expectedWidth, expectedHeight, expectedScale);
    double minimumWidth = 0.0, minimumHeight = 0.0;
    bool minimumOK = r_is_objc_ptr(cacheImage) &&
        themer_iconservices_lab_read_size_property(
            cacheImage, "minimumSize", &minimumWidth, &minimumHeight) &&
        themer_iconservices_lab_sizes_match(
            minimumWidth, minimumHeight,
            expectedMinimumWidth, expectedMinimumHeight);

    // 6. Backup exact stock bytes, persist recovery metadata, write themed temp.
    bool backupWritten = geometry && minimumOK &&
        [targetData writeToFile:backupPath atomically:YES];
    bool backupVerified = backupWritten &&
        themer_iconservices_lab_local_files_equal(targetPath, backupPath);
    bool recoveryPersisted = backupVerified &&
        themer_iconservices_lab_persist_cache_recovery(
            targetPath, backupPath, tempPath);
    bool tempWritten = recoveryPersisted &&
        [paddedData writeToFile:tempPath atomically:YES];
    NSData *tempRead = tempWritten
        ? themer_iconservices_lab_read_local_file(tempPath) : nil;
    bool tempVerified = tempRead != nil && [tempRead isEqualToData:paddedData];

    // 7. Overwrite the existing inode in place and byte-verify.
    uint64_t overwriteResult = tempVerified
        ? themer_iconservices_lab_overwrite_file(targetPath, tempPath)
        : UINT64_MAX;
    bool forwardVerified = overwriteResult == 0 &&
        themer_iconservices_lab_local_files_equal(targetPath, tempPath);

    bool ready = geometry && minimumOK && forwardVerified &&
        remote_call_current_success();
    if (!ready && backupVerified) {
        // Never write from an unverified backup. If the forward write was not
        // attempted, clear recovery only when the target still equals the exact
        // captured stock bytes; otherwise retain metadata for Emergency Restore.
        bool targetMatchesBackup =
            themer_iconservices_lab_local_files_equal(targetPath, backupPath);
        if (!targetMatchesBackup && tempVerified) {
            (void)themer_iconservices_lab_overwrite_file(
                targetPath, backupPath);
            targetMatchesBackup =
                themer_iconservices_lab_local_files_equal(
                    targetPath, backupPath);
        }
        if (targetMatchesBackup) {
            themer_iconservices_lab_clear_cache_recovery();
        }
    }

    printf("[ICONSERVICES_LAB] cache-file-overwrite "
           "donor=0x%llx class=%s/%d identity=%s stockValid=%d "
           "uuid=\"%s\" target=\"%s\" targetLen=%lu themedLen=%lu "
           "minimumSet=%d sourceComplete=%d "
           "fits=%d geometry=%d minimumOK=%d backupWritten=%d "
           "backupVerified=%d recoveryPersisted=%d tempWritten=%d "
           "tempVerified=%d overwrite=%llu forwardVerified=%d ready=%d\n",
           (unsigned long long)donor,
           donorClass[0] ? donorClass : "-",
           donorClassOK,
           donorClassOK ? "live" : "probe-persisted",
           stockIdentityValid,
           uuidKnown ? uuidText : "-",
           targetPath.UTF8String ?: "-",
           (unsigned long)targetLength,
           (unsigned long)(sourceComplete ? sourceCapture.objectLength : 0),
           minimumSet,
           sourceComplete,
           fitsInRecord,
           geometry,
           minimumOK,
           backupWritten,
           backupVerified,
           recoveryPersisted,
           tempWritten,
           tempVerified,
           (unsigned long long)overwriteResult,
           forwardVerified,
           ready);

    if (r_is_objc_ptr(stockValidationImage) &&
        remote_call_current_success()) {
        r_msg2(stockValidationImage, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(remoteStockData) && remote_call_current_success()) {
        r_msg2(remoteStockData, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(uuidString) && remote_call_current_success()) {
        r_msg2(uuidString, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(donorToken) && remote_call_current_success()) {
        r_msg2(donorToken, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(donorUUID) && remote_call_current_success()) {
        r_msg2(donorUUID, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(remotePadded) && remote_call_current_success()) {
        r_msg2(remotePadded, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(sourceData) && remote_call_current_success()) {
        r_msg2(sourceData, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(concreteImage) && remote_call_current_success()) {
        r_msg2(concreteImage, "release", 0, 0, 0, 0);
    }
    themer_iconservices_lab_free_data_capture(&sourceCapture);
    if (!ready && r_is_objc_ptr(cacheImage) && remote_call_current_success()) {
        r_msg2(cacheImage, "release", 0, 0, 0, 0);
        cacheImage = 0;
    }
    if (readyOut) *readyOut = ready;
    return ready ? cacheImage : 0;
}

static bool themer_iconservices_lab_stock_cacheimage_roundtrip(
    const ThemerIconServicesLabDiscovery *d,
    bool *readyOut)
{
    if (readyOut) *readyOut = false;
    if (!d || !remote_call_current_success()) return false;

    const ThemerIconServicesLabBagEntry *donorEntry = NULL;
    const char *donorRole = "stock68";
    for (int i = 0; i < d->stockEntryCount; i++) {
        const ThemerIconServicesLabBagEntry *entry = &d->stockEntries[i];
        if (entry->geometryKnown &&
            themer_iconservices_lab_sizes_match(
                entry->width, entry->height, 68.0, 68.0)) {
            donorEntry = entry;
            break;
        }
    }
    if (!donorEntry && d->primaryEntryIndex >= 0 &&
        d->primaryEntryIndex < d->stockEntryCount &&
        d->stockEntries[d->primaryEntryIndex].geometryKnown) {
        donorEntry = &d->stockEntries[d->primaryEntryIndex];
        donorRole = "stock40-fallback";
    }
    if (!donorEntry) {
        printf("[ICONSERVICES_LAB] cacheimage-roundtrip donor=0x0 "
               "available=0 reason=no-genuine-cacheimage entries=%d\n",
               d->stockEntryCount);
        return remote_call_current_success();
    }
    uint64_t donor = donorEntry->image;
    double donorWidth = donorEntry->width;
    double donorHeight = donorEntry->height;
    double donorScale = donorEntry->scale;

    char donorClass[96] = {0};
    themer_read_class_name(donor, donorClass, sizeof(donorClass));
    bool donorClassOK = strcmp(donorClass, "IFCacheImage") == 0;
    uint64_t data = donorClassOK
        ? themer_iconservices_lab_retained_getter(donor, "data") : 0;
    uint64_t bitmapData = donorClassOK
        ? themer_iconservices_lab_retained_getter(donor, "bitmapData") : 0;
    uint64_t uuid = donorClassOK
        ? themer_iconservices_lab_retained_getter(donor, "uuid") : 0;
    uint64_t token = donorClassOK
        ? themer_iconservices_lab_retained_getter(
            donor, "validationToken") : 0;
    uint64_t uuidAgain = donorClassOK && r_responds_main(donor, "uuid")
        ? r_msg2_main(donor, "uuid", 0, 0, 0, 0) : 0;
    bool uuidStable = themer_iconservices_lab_objects_equal(uuid, uuidAgain);

    ThemerIconServicesLabDataCapture dataCapture = {0};
    ThemerIconServicesLabDataCapture bitmapCapture = {0};
    ThemerIconServicesLabDataCapture tokenCapture = {0};
    bool dataCaptured = r_is_objc_ptr(data) &&
        themer_iconservices_lab_capture_nsdata(
            data, THEMER_ICONSERVICES_LAB_DATA_CAPTURE_CAP, &dataCapture);
    bool bitmapCaptured = r_is_objc_ptr(bitmapData) &&
        themer_iconservices_lab_capture_nsdata(
            bitmapData, THEMER_ICONSERVICES_LAB_DATA_CAPTURE_CAP,
            &bitmapCapture);
    bool tokenCaptured = r_is_objc_ptr(token) &&
        themer_iconservices_lab_capture_nsdata(
            token, THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP, &tokenCapture);

    uint8_t dataSHA1[20] = {0};
    uint8_t dataSHA256[32] = {0};
    uint8_t bitmapSHA1[20] = {0};
    uint8_t bitmapSHA256[32] = {0};
    bool dataSHA1Known = dataCaptured && !dataCapture.truncated &&
        themer_iconservices_lab_digest(
            "CC_SHA1", dataCapture.bytes, dataCapture.capturedLength,
            dataSHA1);
    bool dataSHA256Known = dataCaptured && !dataCapture.truncated &&
        themer_iconservices_lab_digest(
            "CC_SHA256", dataCapture.bytes, dataCapture.capturedLength,
            dataSHA256);
    bool bitmapSHA1Known = bitmapCaptured && !bitmapCapture.truncated &&
        themer_iconservices_lab_digest(
            "CC_SHA1", bitmapCapture.bytes, bitmapCapture.capturedLength,
            bitmapSHA1);
    bool bitmapSHA256Known = bitmapCaptured && !bitmapCapture.truncated &&
        themer_iconservices_lab_digest(
            "CC_SHA256", bitmapCapture.bytes, bitmapCapture.capturedLength,
            bitmapSHA256);

    char dataPrefix[65] = {0};
    char bitmapPrefix[65] = {0};
    char tokenHex[THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP * 2 + 1] = {0};
    char dataSHA1Hex[41] = {0};
    char dataSHA256Hex[65] = {0};
    char bitmapSHA1Hex[41] = {0};
    char bitmapSHA256Hex[65] = {0};
    themer_iconservices_lab_hex_bytes(
        dataCapture.bytes,
        dataCapture.capturedLength < 32 ? dataCapture.capturedLength : 32,
        dataPrefix, sizeof(dataPrefix));
    themer_iconservices_lab_hex_bytes(
        bitmapCapture.bytes,
        bitmapCapture.capturedLength < 32 ? bitmapCapture.capturedLength : 32,
        bitmapPrefix, sizeof(bitmapPrefix));
    themer_iconservices_lab_hex_bytes(
        tokenCapture.bytes, tokenCapture.capturedLength,
        tokenHex, sizeof(tokenHex));
    themer_iconservices_lab_hex_bytes(
        dataSHA1, sizeof(dataSHA1), dataSHA1Hex, sizeof(dataSHA1Hex));
    themer_iconservices_lab_hex_bytes(
        dataSHA256, sizeof(dataSHA256), dataSHA256Hex, sizeof(dataSHA256Hex));
    themer_iconservices_lab_hex_bytes(
        bitmapSHA1, sizeof(bitmapSHA1),
        bitmapSHA1Hex, sizeof(bitmapSHA1Hex));
    themer_iconservices_lab_hex_bytes(
        bitmapSHA256, sizeof(bitmapSHA256),
        bitmapSHA256Hex, sizeof(bitmapSHA256Hex));

    bool tokenDataSHA1 = tokenCaptured && dataSHA1Known &&
        themer_iconservices_lab_token_matches_digest(
            tokenCapture.bytes, tokenCapture.capturedLength,
            dataSHA1, sizeof(dataSHA1));
    bool tokenDataSHA256 = tokenCaptured && dataSHA256Known &&
        themer_iconservices_lab_token_matches_digest(
            tokenCapture.bytes, tokenCapture.capturedLength,
            dataSHA256, sizeof(dataSHA256));
    bool tokenBitmapSHA1 = tokenCaptured && bitmapSHA1Known &&
        themer_iconservices_lab_token_matches_digest(
            tokenCapture.bytes, tokenCapture.capturedLength,
            bitmapSHA1, sizeof(bitmapSHA1));
    bool tokenBitmapSHA256 = tokenCaptured && bitmapSHA256Known &&
        themer_iconservices_lab_token_matches_digest(
            tokenCapture.bytes, tokenCapture.capturedLength,
            bitmapSHA256, sizeof(bitmapSHA256));

    char uuidText[160] = {0};
    themer_read_remote_description(uuid, uuidText, sizeof(uuidText));
    printf("[ICONSERVICES_LAB] cacheimage-roundtrip donor=0x%llx "
           "role=%s geometry=%.1fx%.1f@%.2f class=%s classOK=%d "
           "uuid=0x%llx stable=%d desc=\"%s\" "
           "data=0x%llx/%zu/%zu/truncated=%d prefix=%s "
           "bitmap=0x%llx/%zu/%zu/truncated=%d prefix=%s "
           "token=0x%llx/%zu/%zu/truncated=%d hex=%s\n",
           (unsigned long long)donor,
           donorRole,
           donorWidth,
           donorHeight,
           donorScale,
           donorClass[0] ? donorClass : "-",
           donorClassOK,
           (unsigned long long)uuid,
           uuidStable,
           uuidText,
           (unsigned long long)data,
           dataCapture.objectLength,
           dataCapture.capturedLength,
           dataCapture.truncated,
           dataPrefix,
           (unsigned long long)bitmapData,
           bitmapCapture.objectLength,
           bitmapCapture.capturedLength,
           bitmapCapture.truncated,
           bitmapPrefix,
           (unsigned long long)token,
           tokenCapture.objectLength,
           tokenCapture.capturedLength,
           tokenCapture.truncated,
           tokenHex);
    printf("[ICONSERVICES_LAB] cacheimage-roundtrip hashes "
           "dataSHA1=%s/%s dataSHA256=%s/%s "
           "bitmapSHA1=%s/%s bitmapSHA256=%s/%s "
           "tokenDataSHA1=%d tokenDataSHA256=%d "
           "tokenBitmapSHA1=%d tokenBitmapSHA256=%d\n",
           dataSHA1Known ? "" : "?", dataSHA1Hex,
           dataSHA256Known ? "" : "?", dataSHA256Hex,
           bitmapSHA1Known ? "" : "?", bitmapSHA1Hex,
           bitmapSHA256Known ? "" : "?", bitmapSHA256Hex,
           tokenDataSHA1,
           tokenDataSHA256,
           tokenBitmapSHA1,
           tokenBitmapSHA256);

    uint64_t clone = donorClassOK && r_is_objc_ptr(data) &&
        r_is_objc_ptr(uuid) && r_is_objc_ptr(token) &&
        dataCaptured && tokenCaptured
        ? themer_iconservices_lab_make_if_cache_image(data, uuid, token) : 0;
    char cloneClass[96] = {0};
    themer_read_class_name(clone, cloneClass, sizeof(cloneClass));
    bool cloneClassOK = strcmp(cloneClass, "IFCacheImage") == 0;
    uint64_t cloneData = cloneClassOK && r_responds_main(clone, "data")
        ? r_msg2_main(clone, "data", 0, 0, 0, 0) : 0;
    uint64_t cloneUuid = cloneClassOK && r_responds_main(clone, "uuid")
        ? r_msg2_main(clone, "uuid", 0, 0, 0, 0) : 0;
    uint64_t cloneToken = cloneClassOK &&
        r_responds_main(clone, "validationToken")
        ? r_msg2_main(clone, "validationToken", 0, 0, 0, 0) : 0;
    bool dataEqual = themer_iconservices_lab_objects_equal(cloneData, data);
    bool uuidEqual = themer_iconservices_lab_objects_equal(cloneUuid, uuid);
    bool tokenEqual = themer_iconservices_lab_objects_equal(cloneToken, token);
    bool geometry = cloneClassOK &&
        themer_iconservices_lab_image_geometry_matches(
            clone, donorWidth, donorHeight, donorScale);

    double donorPixelW = 0.0, donorPixelH = 0.0;
    double clonePixelW = 0.0, clonePixelH = 0.0;
    double donorMinimumW = 0.0, donorMinimumH = 0.0;
    double cloneMinimumW = 0.0, cloneMinimumH = 0.0;
    double donorIconW = 0.0, donorIconH = 0.0;
    double cloneIconW = 0.0, cloneIconH = 0.0;
    bool pixelParity =
        themer_iconservices_lab_read_size_property(
            donor, "pixelSize", &donorPixelW, &donorPixelH) &&
        themer_iconservices_lab_read_size_property(
            clone, "pixelSize", &clonePixelW, &clonePixelH) &&
        themer_iconservices_lab_sizes_match(
            donorPixelW, donorPixelH, clonePixelW, clonePixelH);
    bool minimumParity =
        themer_iconservices_lab_read_size_property(
            donor, "minimumSize", &donorMinimumW, &donorMinimumH) &&
        themer_iconservices_lab_read_size_property(
            clone, "minimumSize", &cloneMinimumW, &cloneMinimumH) &&
        themer_iconservices_lab_sizes_match(
            donorMinimumW, donorMinimumH, cloneMinimumW, cloneMinimumH);
    bool iconParity =
        themer_iconservices_lab_read_size_property(
            donor, "iconSize", &donorIconW, &donorIconH) &&
        themer_iconservices_lab_read_size_property(
            clone, "iconSize", &cloneIconW, &cloneIconH) &&
        themer_iconservices_lab_sizes_match(
            donorIconW, donorIconH, cloneIconW, cloneIconH);
    uint64_t cloneCGImage = cloneClassOK && r_responds_main(clone, "CGImage")
        ? r_msg2_main(clone, "CGImage", 0, 0, 0, 0) : 0;
    uint64_t clonePixelWidth = cloneCGImage
        ? r_dlsym_call(R_TIMEOUT, "CGImageGetWidth",
                       cloneCGImage, 0, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t clonePixelHeight = cloneCGImage
        ? r_dlsym_call(R_TIMEOUT, "CGImageGetHeight",
                       cloneCGImage, 0, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t cloneImages[1] = {clone};
    uint64_t testBag = cloneClassOK
        ? themer_iconservices_lab_make_bag_from_images(cloneImages, 1) : 0;
    uint64_t routed = r_is_objc_ptr(testBag)
        ? themer_iconservices_lab_image_for_size_scale(
            testBag, donorWidth, donorHeight, donorScale) : 0;
    bool routedExact = themer_spotlight_images_match(clone, routed);
    uint64_t expectedPixelWidth =
        (uint64_t)(donorWidth * donorScale + 0.5);
    uint64_t expectedPixelHeight =
        (uint64_t)(donorHeight * donorScale + 0.5);
    bool cloneReady = cloneClassOK && dataEqual && uuidEqual && tokenEqual &&
        geometry && pixelParity && minimumParity && iconParity &&
        cloneCGImage && clonePixelWidth == expectedPixelWidth &&
        clonePixelHeight == expectedPixelHeight &&
        r_is_objc_ptr(testBag) && routedExact && remote_call_current_success();

    printf("[ICONSERVICES_LAB] cacheimage-roundtrip clone=0x%llx "
           "class=%s classOK=%d dataEqual=%d uuidEqual=%d tokenEqual=%d "
           "geometry=%d pixelParity=%d minimumParity=%d iconParity=%d "
           "cgImage=0x%llx pixels=%llux%llu bag=0x%llx "
           "routed=0x%llx exact=%d ready=%d\n",
           (unsigned long long)clone,
           cloneClass[0] ? cloneClass : "-",
           cloneClassOK,
           dataEqual,
           uuidEqual,
           tokenEqual,
           geometry,
           pixelParity,
           minimumParity,
           iconParity,
           (unsigned long long)cloneCGImage,
           (unsigned long long)clonePixelWidth,
           (unsigned long long)clonePixelHeight,
           (unsigned long long)testBag,
           (unsigned long long)routed,
           routedExact,
           cloneReady);

    if (r_is_objc_ptr(testBag) && remote_call_current_success()) {
        r_msg2(testBag, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(clone) && remote_call_current_success()) {
        r_msg2(clone, "release", 0, 0, 0, 0);
    }
    bool donorReadable = remote_call_current_success() &&
        themer_iconservices_lab_image_geometry_matches(
            donor, donorWidth, donorHeight, donorScale);
    printf("[ICONSERVICES_LAB] cacheimage-roundtrip cleanup "
           "donor=0x%llx donorReadable=%d ready=%d\n",
           (unsigned long long)donor,
           donorReadable,
           cloneReady && donorReadable);

    if (r_is_objc_ptr(token) && remote_call_current_success()) {
        r_msg2(token, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(uuid) && remote_call_current_success()) {
        r_msg2(uuid, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(bitmapData) && remote_call_current_success()) {
        r_msg2(bitmapData, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(data) && remote_call_current_success()) {
        r_msg2(data, "release", 0, 0, 0, 0);
    }
    themer_iconservices_lab_free_data_capture(&tokenCapture);
    themer_iconservices_lab_free_data_capture(&bitmapCapture);
    themer_iconservices_lab_free_data_capture(&dataCapture);
    if (readyOut) *readyOut = cloneReady && donorReadable;
    return remote_call_current_success();
}

// Probe-only comparison of every genuine stock IFCacheImage currently retained
// by discovery. This reads object properties and remote NSData bytes only; it
// never asks the live bag to route or mutates cache, bag, image, or lab state.
static bool themer_iconservices_lab_stock_token_comparison_probe(
    const ThemerIconServicesLabDiscovery *d)
{
    if (!d || !remote_call_current_success()) return false;
    typedef struct {
        uint64_t image;
        uint64_t data;
        uint64_t bitmapData;
        uint64_t uuid;
        uint64_t token;
        ThemerIconServicesLabDataCapture dataCapture;
        ThemerIconServicesLabDataCapture bitmapCapture;
        ThemerIconServicesLabDataCapture tokenCapture;
        bool dataCaptured;
        bool bitmapCaptured;
        bool tokenCaptured;
    } ThemerStockTokenSample;

    ThemerStockTokenSample samples[
        THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP] = {{0}};
    int sampleCount = d->stockEntryCount;
    if (sampleCount < 0) sampleCount = 0;
    if (sampleCount > THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP) {
        sampleCount = THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP;
    }
    uint64_t ioFailuresBefore = remote_call_current_io_failure_count();

    for (int i = 0; i < sampleCount && remote_call_current_success(); i++) {
        const ThemerIconServicesLabBagEntry *entry = &d->stockEntries[i];
        ThemerStockTokenSample *sample = &samples[i];
        sample->image = entry->image;
        char imageClass[96] = {0};
        themer_read_class_name(
            sample->image, imageClass, sizeof(imageClass));
        bool classOK = strcmp(imageClass, "IFCacheImage") == 0;
        sample->data = classOK
            ? themer_iconservices_lab_retained_getter(
                sample->image, "data") : 0;
        sample->bitmapData = classOK
            ? themer_iconservices_lab_retained_getter(
                sample->image, "bitmapData") : 0;
        sample->uuid = classOK
            ? themer_iconservices_lab_retained_getter(
                sample->image, "uuid") : 0;
        sample->token = classOK
            ? themer_iconservices_lab_retained_getter(
                sample->image, "validationToken") : 0;
        sample->dataCaptured = r_is_objc_ptr(sample->data) &&
            themer_iconservices_lab_capture_nsdata(
                sample->data,
                THEMER_ICONSERVICES_LAB_STOCK_COMPARE_DATA_CAP,
                &sample->dataCapture);
        sample->bitmapCaptured = r_is_objc_ptr(sample->bitmapData) &&
            themer_iconservices_lab_capture_nsdata(
                sample->bitmapData,
                THEMER_ICONSERVICES_LAB_STOCK_COMPARE_DATA_CAP,
                &sample->bitmapCapture);
        sample->tokenCaptured = r_is_objc_ptr(sample->token) &&
            themer_iconservices_lab_capture_nsdata(
                sample->token,
                THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP,
                &sample->tokenCapture);

        uint8_t dataSHA1[20] = {0};
        uint8_t dataSHA256[32] = {0};
        uint8_t bitmapSHA1[20] = {0};
        uint8_t bitmapSHA256[32] = {0};
        bool dataSHA1Known = sample->dataCaptured &&
            !sample->dataCapture.truncated &&
            sample->dataCapture.capturedLength > 0 &&
            themer_iconservices_lab_digest(
                "CC_SHA1", sample->dataCapture.bytes,
                sample->dataCapture.capturedLength, dataSHA1);
        bool dataSHA256Known = sample->dataCaptured &&
            !sample->dataCapture.truncated &&
            sample->dataCapture.capturedLength > 0 &&
            themer_iconservices_lab_digest(
                "CC_SHA256", sample->dataCapture.bytes,
                sample->dataCapture.capturedLength, dataSHA256);
        bool bitmapSHA1Known = sample->bitmapCaptured &&
            !sample->bitmapCapture.truncated &&
            sample->bitmapCapture.capturedLength > 0 &&
            themer_iconservices_lab_digest(
                "CC_SHA1", sample->bitmapCapture.bytes,
                sample->bitmapCapture.capturedLength, bitmapSHA1);
        bool bitmapSHA256Known = sample->bitmapCaptured &&
            !sample->bitmapCapture.truncated &&
            sample->bitmapCapture.capturedLength > 0 &&
            themer_iconservices_lab_digest(
                "CC_SHA256", sample->bitmapCapture.bytes,
                sample->bitmapCapture.capturedLength, bitmapSHA256);
        bool tokenDataSHA1 = sample->tokenCaptured && dataSHA1Known &&
            themer_iconservices_lab_token_matches_digest(
                sample->tokenCapture.bytes,
                sample->tokenCapture.capturedLength,
                dataSHA1, sizeof(dataSHA1));
        bool tokenDataSHA256 = sample->tokenCaptured && dataSHA256Known &&
            themer_iconservices_lab_token_matches_digest(
                sample->tokenCapture.bytes,
                sample->tokenCapture.capturedLength,
                dataSHA256, sizeof(dataSHA256));
        bool tokenBitmapSHA1 = sample->tokenCaptured && bitmapSHA1Known &&
            themer_iconservices_lab_token_matches_digest(
                sample->tokenCapture.bytes,
                sample->tokenCapture.capturedLength,
                bitmapSHA1, sizeof(bitmapSHA1));
        bool tokenBitmapSHA256 = sample->tokenCaptured && bitmapSHA256Known &&
            themer_iconservices_lab_token_matches_digest(
                sample->tokenCapture.bytes,
                sample->tokenCapture.capturedLength,
                bitmapSHA256, sizeof(bitmapSHA256));

        char uuidText[160] = {0};
        char dataPrefix[65] = {0};
        char bitmapPrefix[65] = {0};
        char tokenHex[THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP * 2 + 1] = {0};
        char dataSHA1Hex[41] = {0};
        char dataSHA256Hex[65] = {0};
        char bitmapSHA1Hex[41] = {0};
        char bitmapSHA256Hex[65] = {0};
        themer_read_remote_description(
            sample->uuid, uuidText, sizeof(uuidText));
        themer_iconservices_lab_hex_bytes(
            sample->dataCapture.bytes,
            sample->dataCapture.capturedLength < 32
                ? sample->dataCapture.capturedLength : 32,
            dataPrefix, sizeof(dataPrefix));
        themer_iconservices_lab_hex_bytes(
            sample->bitmapCapture.bytes,
            sample->bitmapCapture.capturedLength < 32
                ? sample->bitmapCapture.capturedLength : 32,
            bitmapPrefix, sizeof(bitmapPrefix));
        themer_iconservices_lab_hex_bytes(
            sample->tokenCapture.bytes,
            sample->tokenCapture.capturedLength,
            tokenHex, sizeof(tokenHex));
        themer_iconservices_lab_hex_bytes(
            dataSHA1, sizeof(dataSHA1), dataSHA1Hex, sizeof(dataSHA1Hex));
        themer_iconservices_lab_hex_bytes(
            dataSHA256, sizeof(dataSHA256),
            dataSHA256Hex, sizeof(dataSHA256Hex));
        themer_iconservices_lab_hex_bytes(
            bitmapSHA1, sizeof(bitmapSHA1),
            bitmapSHA1Hex, sizeof(bitmapSHA1Hex));
        themer_iconservices_lab_hex_bytes(
            bitmapSHA256, sizeof(bitmapSHA256),
            bitmapSHA256Hex, sizeof(bitmapSHA256Hex));

        printf("[ICONSERVICES_LAB] stock-token-entry index=%d/%d "
               "primary=%d image=0x%llx class=%s classOK=%d "
               "geometry=%.1fx%.1f@%.2f uuid=0x%llx desc=\"%s\" "
               "data=0x%llx/%zu/%zu/truncated=%d prefix=%s "
               "bitmap=0x%llx/%zu/%zu/truncated=%d prefix=%s "
               "token=0x%llx/%zu/%zu/truncated=%d hex=%s\n",
               i,
               sampleCount,
               i == d->primaryEntryIndex,
               (unsigned long long)sample->image,
               imageClass[0] ? imageClass : "-",
               classOK,
               entry->width, entry->height, entry->scale,
               (unsigned long long)sample->uuid,
               uuidText,
               (unsigned long long)sample->data,
               sample->dataCapture.objectLength,
               sample->dataCapture.capturedLength,
               sample->dataCapture.truncated,
               dataPrefix,
               (unsigned long long)sample->bitmapData,
               sample->bitmapCapture.objectLength,
               sample->bitmapCapture.capturedLength,
               sample->bitmapCapture.truncated,
               bitmapPrefix,
               (unsigned long long)sample->token,
               sample->tokenCapture.objectLength,
               sample->tokenCapture.capturedLength,
               sample->tokenCapture.truncated,
               tokenHex);
        printf("[ICONSERVICES_LAB] stock-token-hashes index=%d "
               "dataSHA1=%s%s dataSHA256=%s%s "
               "bitmapSHA1=%s%s bitmapSHA256=%s%s "
               "tokenDataSHA1=%d tokenDataSHA256=%d "
               "tokenBitmapSHA1=%d tokenBitmapSHA256=%d\n",
               i,
               dataSHA1Known ? "" : "?", dataSHA1Hex,
               dataSHA256Known ? "" : "?", dataSHA256Hex,
               bitmapSHA1Known ? "" : "?", bitmapSHA1Hex,
               bitmapSHA256Known ? "" : "?", bitmapSHA256Hex,
               tokenDataSHA1,
               tokenDataSHA256,
               tokenBitmapSHA1,
               tokenBitmapSHA256);
    }

    int pairCount = 0;
    for (int i = 0;
         i < sampleCount && remote_call_current_success(); i++) {
        for (int j = i + 1;
             j < sampleCount && remote_call_current_success(); j++) {
            const ThemerStockTokenSample *first = &samples[i];
            const ThemerStockTokenSample *second = &samples[j];
            bool uuidKnown = r_is_objc_ptr(first->uuid) &&
                r_is_objc_ptr(second->uuid);
            bool uuidEqual = uuidKnown &&
                themer_iconservices_lab_objects_equal(
                    first->uuid, second->uuid);
            bool tokenKnown = first->tokenCaptured &&
                second->tokenCaptured &&
                !first->tokenCapture.truncated &&
                !second->tokenCapture.truncated;
            bool tokenObjectEqual = r_is_objc_ptr(first->token) &&
                r_is_objc_ptr(second->token) &&
                themer_iconservices_lab_objects_equal(
                    first->token, second->token);
            bool tokenBytesEqual = tokenKnown &&
                first->tokenCapture.objectLength ==
                    second->tokenCapture.objectLength &&
                (first->tokenCapture.objectLength == 0 ||
                 memcmp(first->tokenCapture.bytes,
                        second->tokenCapture.bytes,
                        first->tokenCapture.objectLength) == 0);
            bool dataKnown = first->dataCaptured && second->dataCaptured &&
                !first->dataCapture.truncated &&
                !second->dataCapture.truncated;
            bool dataObjectEqual = r_is_objc_ptr(first->data) &&
                r_is_objc_ptr(second->data) &&
                themer_iconservices_lab_objects_equal(
                    first->data, second->data);
            bool dataBytesEqual = dataKnown &&
                first->dataCapture.objectLength ==
                    second->dataCapture.objectLength &&
                (first->dataCapture.objectLength == 0 ||
                 memcmp(first->dataCapture.bytes,
                        second->dataCapture.bytes,
                        first->dataCapture.objectLength) == 0);
            bool bitmapKnown = first->bitmapCaptured &&
                second->bitmapCaptured &&
                !first->bitmapCapture.truncated &&
                !second->bitmapCapture.truncated;
            bool bitmapObjectEqual = r_is_objc_ptr(first->bitmapData) &&
                r_is_objc_ptr(second->bitmapData) &&
                themer_iconservices_lab_objects_equal(
                    first->bitmapData, second->bitmapData);
            bool bitmapBytesEqual = bitmapKnown &&
                first->bitmapCapture.objectLength ==
                    second->bitmapCapture.objectLength &&
                (first->bitmapCapture.objectLength == 0 ||
                 memcmp(first->bitmapCapture.bytes,
                        second->bitmapCapture.bytes,
                        first->bitmapCapture.objectLength) == 0);
            char firstTokenPrefix[65] = {0};
            char secondTokenPrefix[65] = {0};
            themer_iconservices_lab_hex_bytes(
                first->tokenCapture.bytes,
                first->tokenCapture.capturedLength < 32
                    ? first->tokenCapture.capturedLength : 32,
                firstTokenPrefix, sizeof(firstTokenPrefix));
            themer_iconservices_lab_hex_bytes(
                second->tokenCapture.bytes,
                second->tokenCapture.capturedLength < 32
                    ? second->tokenCapture.capturedLength : 32,
                secondTokenPrefix, sizeof(secondTokenPrefix));
            printf("[ICONSERVICES_LAB] stock-token-compare first=%d/%s "
                   "second=%d/%s uuidKnown=%d uuidEqual=%d "
                   "tokenKnown=%d tokenObjectEqual=%d tokenBytesEqual=%d "
                   "tokenPrefix=%s/%s dataKnown=%d dataObjectEqual=%d "
                   "dataBytesEqual=%d bitmapKnown=%d "
                   "bitmapObjectEqual=%d bitmapBytesEqual=%d\n",
                   i,
                   i == d->primaryEntryIndex ? "primary" : "secondary",
                   j,
                   j == d->primaryEntryIndex ? "primary" : "secondary",
                   uuidKnown,
                   uuidEqual,
                   tokenKnown,
                   tokenObjectEqual,
                   tokenBytesEqual,
                   firstTokenPrefix,
                   secondTokenPrefix,
                   dataKnown,
                   dataObjectEqual,
                   dataBytesEqual,
                   bitmapKnown,
                   bitmapObjectEqual,
                   bitmapBytesEqual);
            pairCount++;
        }
    }

    for (int i = 0; i < sampleCount; i++) {
        ThemerStockTokenSample *sample = &samples[i];
        if (r_is_objc_ptr(sample->token) &&
            remote_call_current_success()) {
            r_msg2(sample->token, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(sample->uuid) &&
            remote_call_current_success()) {
            r_msg2(sample->uuid, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(sample->bitmapData) &&
            remote_call_current_success()) {
            r_msg2(sample->bitmapData, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(sample->data) &&
            remote_call_current_success()) {
            r_msg2(sample->data, "release", 0, 0, 0, 0);
        }
        themer_iconservices_lab_free_data_capture(&sample->tokenCapture);
        themer_iconservices_lab_free_data_capture(&sample->bitmapCapture);
        themer_iconservices_lab_free_data_capture(&sample->dataCapture);
    }
    uint64_t ioFailuresAfter = remote_call_current_io_failure_count();
    printf("[ICONSERVICES_LAB] stock-token-summary entries=%d pairs=%d "
           "ioFailures=%llu->%llu transportClean=%d\n",
           sampleCount,
           pairCount,
           (unsigned long long)ioFailuresBefore,
           (unsigned long long)ioFailuresAfter,
           ioFailuresAfter == ioFailuresBefore);
    return remote_call_current_success();
}

static bool themer_iconservices_lab_store_record_lookup_probe(
    const ThemerIconServicesLabDiscovery *d)
{
    if (!d || !remote_call_current_success()) return false;

    uint64_t cache = d->managerIconCache;
    char storeTypes[192] = {0};
    char storeIndexTypes[192] = {0};
    bool storeABI = r_is_objc_ptr(cache) &&
        r_responds_main(cache, "store") &&
        themer_iconservices_lab_method_types(
            cache, "store", storeTypes, sizeof(storeTypes)) &&
        strcmp(storeTypes, "@16@0:8") == 0;
    bool storeIndexABI = r_is_objc_ptr(cache) &&
        r_responds_main(cache, "storeIndex") &&
        themer_iconservices_lab_method_types(
            cache, "storeIndex", storeIndexTypes,
            sizeof(storeIndexTypes)) &&
        strcmp(storeIndexTypes, "@16@0:8") == 0;
    uint64_t store = storeABI
        ? r_msg2_main_retained_object(cache, "store", 0, 0, 0, 0) : 0;
    uint64_t storeIndex = storeIndexABI
        ? r_msg2_main_retained_object(
            cache, "storeIndex", 0, 0, 0, 0) : 0;
    char storeClass[96] = {0};
    char storeIndexClass[96] = {0};
    themer_read_class_name(store, storeClass, sizeof(storeClass));
    themer_read_class_name(
        storeIndex, storeIndexClass, sizeof(storeIndexClass));
    printf("[ICONSERVICES_LAB] store-layer cache=0x%llx "
           "storeTypes=\"%s\" storeABI=%d store=0x%llx/%s "
           "storeIndexTypes=\"%s\" storeIndexABI=%d "
           "storeIndex=0x%llx/%s\n",
           (unsigned long long)cache,
           storeTypes,
           storeABI,
           (unsigned long long)store,
           storeClass[0] ? storeClass : "-",
           storeIndexTypes,
           storeIndexABI,
           (unsigned long long)storeIndex,
           storeIndexClass[0] ? storeIndexClass : "-");
    if (r_is_objc_ptr(store) && storeClass[0]) {
        uint64_t cls = r_dlsym_call(
            R_TIMEOUT, "object_getClass", store, 0, 0, 0, 0, 0, 0, 0);
        if (r_is_objc_ptr(cls)) {
            (void)themer_iconservices_lab_log_runtime_methods(
                storeClass, "store-object", cls, 48);
        }
    }
    if (r_is_objc_ptr(storeIndex) && storeIndexClass[0] &&
        remote_call_current_success()) {
        uint64_t cls = r_dlsym_call(
            R_TIMEOUT, "object_getClass", storeIndex,
            0, 0, 0, 0, 0, 0, 0);
        if (r_is_objc_ptr(cls)) {
            (void)themer_iconservices_lab_log_runtime_methods(
                storeIndexClass, "store-index", cls, 48);
        }
    }

    char indexDataTypes[192] = {0};
    bool indexDataABI = r_is_objc_ptr(storeIndex) &&
        r_responds_main(storeIndex, "data") &&
        themer_iconservices_lab_method_types(
            storeIndex, "data", indexDataTypes,
            sizeof(indexDataTypes)) &&
        strcmp(indexDataTypes, "@16@0:8") == 0;
    uint64_t indexData = indexDataABI
        ? r_msg2_main_retained_object(
            storeIndex, "data", 0, 0, 0, 0) : 0;
    ThemerIconServicesLabDataCapture indexCapture = {0};
    char indexDataClass[96] = {0};
    themer_read_class_name(
        indexData, indexDataClass, sizeof(indexDataClass));
    bool dispatchData = strstr(indexDataClass, "dispatch_data") != NULL;
    bool indexCaptured = r_is_objc_ptr(indexData) &&
        (dispatchData
            ? themer_iconservices_lab_capture_dispatch_data(
                indexData, THEMER_ICONSERVICES_LAB_INDEX_CAPTURE_CAP,
                &indexCapture)
            : themer_iconservices_lab_capture_nsdata(
                indexData, THEMER_ICONSERVICES_LAB_INDEX_CAPTURE_CAP,
                &indexCapture));
    printf("[ICONSERVICES_LAB] store-index-data index=0x%llx/%s "
           "selector=data types=\"%s\" abiReady=%d data=0x%llx/%s "
           "captureMode=%s length=%zu captured=%zu truncated=%d "
           "capturedOK=%d\n",
           (unsigned long long)storeIndex,
           storeIndexClass[0] ? storeIndexClass : "-",
           indexDataTypes,
           indexDataABI,
           (unsigned long long)indexData,
           indexDataClass[0] ? indexDataClass : "-",
           dispatchData ? "dispatch-map" : "nsdata",
           indexCapture.objectLength,
           indexCapture.capturedLength,
           indexCapture.truncated,
           indexCaptured);

    char methodTypes[192] = {0};
    bool abiReady = r_is_objc_ptr(cache) &&
        r_responds_main(cache, "storeUnitForUUID:") &&
        themer_iconservices_lab_method_types(
            cache, "storeUnitForUUID:", methodTypes,
            sizeof(methodTypes)) &&
        strcmp(methodTypes, "@24@0:8@16") == 0;
    uint64_t ioFailuresBefore = remote_call_current_io_failure_count();
    int attempted = 0;
    int found = 0;
    bool methodsLogged = false;

    for (int i = 0; i < d->stockEntryCount &&
         remote_call_current_success(); i++) {
        const ThemerIconServicesLabBagEntry *entry = &d->stockEntries[i];
        uint64_t uuid = r_is_objc_ptr(entry->image)
            ? themer_iconservices_lab_retained_getter(entry->image, "uuid")
            : 0;
        uint64_t storeUnit = 0;
        if (abiReady && r_is_objc_ptr(uuid)) {
            attempted++;
            storeUnit = r_msg2_main_retained_object(
                cache, "storeUnitForUUID:", uuid, 0, 0, 0);
        }
        char uuidClass[96] = {0};
        char unitClass[96] = {0};
        themer_read_class_name(uuid, uuidClass, sizeof(uuidClass));
        themer_read_class_name(storeUnit, unitClass, sizeof(unitClass));
        bool lookupFound = r_is_objc_ptr(storeUnit) && unitClass[0] &&
            remote_call_current_success();
        if (lookupFound) found++;
        printf("[ICONSERVICES_LAB] store-record-lookup index=%d "
               "geometry=%.1fx%.1f@%.2f cache=0x%llx "
               "selector=storeUnitForUUID: types=\"%s\" abiReady=%d "
               "uuid=0x%llx/%s storeUnit=0x%llx/%s found=%d\n",
               i,
               entry->width,
               entry->height,
               entry->scale,
               (unsigned long long)cache,
               methodTypes,
               abiReady,
               (unsigned long long)uuid,
               uuidClass[0] ? uuidClass : "-",
               (unsigned long long)storeUnit,
               unitClass[0] ? unitClass : "-",
               lookupFound);

        char unitUUIDTypes[192] = {0};
        char unitDataTypes[192] = {0};
        char unitValidTypes[192] = {0};
        bool unitABI = lookupFound &&
            r_responds_main(storeUnit, "UUID") &&
            themer_iconservices_lab_method_types(
                storeUnit, "UUID", unitUUIDTypes,
                sizeof(unitUUIDTypes)) &&
            strcmp(unitUUIDTypes, "@16@0:8") == 0 &&
            r_responds_main(storeUnit, "data") &&
            themer_iconservices_lab_method_types(
                storeUnit, "data", unitDataTypes,
                sizeof(unitDataTypes)) &&
            strcmp(unitDataTypes, "@16@0:8") == 0 &&
            r_responds_main(storeUnit, "isValid") &&
            themer_iconservices_lab_method_types(
                storeUnit, "isValid", unitValidTypes,
                sizeof(unitValidTypes)) &&
            strcmp(unitValidTypes, "B16@0:8") == 0;
        uint64_t unitUUID = unitABI
            ? r_msg2_main_retained_object(
                storeUnit, "UUID", 0, 0, 0, 0) : 0;
        uint64_t unitData = unitABI
            ? r_msg2_main_retained_object(
                storeUnit, "data", 0, 0, 0, 0) : 0;
        uint64_t imageData = unitABI && r_is_objc_ptr(entry->image)
            ? themer_iconservices_lab_retained_getter(entry->image, "data")
            : 0;
        uint64_t validRaw = unitABI
            ? r_msg2_main(storeUnit, "isValid", 0, 0, 0, 0) : 0;
        bool validObserved = unitABI && remote_call_current_success();
        bool unitValid = validObserved && (validRaw & 1) != 0;
        bool uuidEqual = r_is_objc_ptr(unitUUID) && r_is_objc_ptr(uuid) &&
            themer_iconservices_lab_objects_equal(unitUUID, uuid);
        bool dataEqual = r_is_objc_ptr(unitData) && r_is_objc_ptr(imageData) &&
            themer_iconservices_lab_objects_equal(unitData, imageData);
        uint64_t unitDataLength = r_is_objc_ptr(unitData) &&
            r_responds_main(unitData, "length")
            ? r_msg2_main(unitData, "length", 0, 0, 0, 0) : 0;
        uint64_t imageDataLength = r_is_objc_ptr(imageData) &&
            r_responds_main(imageData, "length")
            ? r_msg2_main(imageData, "length", 0, 0, 0, 0) : 0;
        printf("[ICONSERVICES_LAB] store-unit-integrity index=%d "
               "class=%s abiReady=%d UUIDTypes=\"%s\" "
               "dataTypes=\"%s\" isValidTypes=\"%s\" "
               "validObserved=%d isValid=%d unitUUID=0x%llx "
               "imageUUID=0x%llx uuidEqual=%d unitData=0x%llx/%llu "
               "imageData=0x%llx/%llu dataEqual=%d\n",
               i,
               unitClass[0] ? unitClass : "-",
               unitABI,
               unitUUIDTypes,
               unitDataTypes,
               unitValidTypes,
               validObserved,
               unitValid,
               (unsigned long long)unitUUID,
               (unsigned long long)uuid,
               uuidEqual,
               (unsigned long long)unitData,
               (unsigned long long)unitDataLength,
               (unsigned long long)imageData,
               (unsigned long long)imageDataLength,
               dataEqual);

        char uuidStringTypes[192] = {0};
        bool uuidStringABI = r_is_objc_ptr(uuid) &&
            r_responds_main(uuid, "UUIDString") &&
            themer_iconservices_lab_method_types(
                uuid, "UUIDString", uuidStringTypes,
                sizeof(uuidStringTypes)) &&
            strcmp(uuidStringTypes, "@16@0:8") == 0;
        uint64_t uuidString = uuidStringABI
            ? r_msg2_main_retained_object(
                uuid, "UUIDString", 0, 0, 0, 0) : 0;
        char uuidText[80] = {0};
        bool uuidTextKnown = r_is_objc_ptr(uuidString) &&
            r_read_nsstring(uuidString, uuidText, sizeof(uuidText));
        uint8_t uuidBytes[16] = {0};
        bool uuidParsed = uuidTextKnown &&
            themer_iconservices_lab_parse_uuid_text(uuidText, uuidBytes);
        uint64_t token = r_is_objc_ptr(entry->image)
            ? themer_iconservices_lab_retained_getter(
                entry->image, "validationToken") : 0;
        ThemerIconServicesLabDataCapture tokenCapture = {0};
        bool tokenCaptured = r_is_objc_ptr(token) &&
            themer_iconservices_lab_capture_nsdata(
                token, THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP,
                &tokenCapture);
        size_t uuidFirstOffset = SIZE_MAX;
        size_t tokenFirstOffset = SIZE_MAX;
        size_t uuidMatches = indexCaptured && uuidParsed
            ? themer_iconservices_lab_count_byte_sequence(
                indexCapture.bytes, indexCapture.capturedLength,
                uuidBytes, sizeof(uuidBytes), &uuidFirstOffset)
            : 0;
        size_t tokenMatches = indexCaptured && tokenCaptured &&
            tokenCapture.capturedLength > 0
            ? themer_iconservices_lab_count_byte_sequence(
                indexCapture.bytes, indexCapture.capturedLength,
                tokenCapture.bytes, tokenCapture.capturedLength,
                &tokenFirstOffset)
            : 0;
        printf("[ICONSERVICES_LAB] store-index-correlation index=%d "
               "UUIDStringTypes=\"%s\" uuidABI=%d uuidText=\"%s\" "
               "uuidParsed=%d uuidMatches=%zu uuidFirstOffset=%lld "
               "tokenLength=%zu tokenMatches=%zu tokenFirstOffset=%lld "
               "indexCaptured=%d indexLength=%zu capturedLength=%zu "
               "truncated=%d\n",
               i,
               uuidStringTypes,
               uuidStringABI,
               uuidTextKnown ? uuidText : "-",
               uuidParsed,
               uuidMatches,
               uuidFirstOffset == SIZE_MAX
                   ? -1LL : (long long)uuidFirstOffset,
               tokenCapture.objectLength,
               tokenMatches,
               tokenFirstOffset == SIZE_MAX
                   ? -1LL : (long long)tokenFirstOffset,
               indexCaptured,
               indexCapture.objectLength,
               indexCapture.capturedLength,
               indexCapture.truncated);
        if (r_is_objc_ptr(token) && remote_call_current_success()) {
            r_msg2(token, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(uuidString) && remote_call_current_success()) {
            r_msg2(uuidString, "release", 0, 0, 0, 0);
        }
        themer_iconservices_lab_free_data_capture(&tokenCapture);

        if (lookupFound && !methodsLogged) {
            uint64_t unitClassObject = r_dlsym_call(
                R_TIMEOUT, "object_getClass", storeUnit,
                0, 0, 0, 0, 0, 0, 0);
            if (r_is_objc_ptr(unitClassObject)) {
                (void)themer_iconservices_lab_log_runtime_methods(
                    unitClass, "store-record", unitClassObject, 48);
                methodsLogged = remote_call_current_success();
            }
        }
        if (r_is_objc_ptr(imageData) && remote_call_current_success()) {
            r_msg2(imageData, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(unitData) && remote_call_current_success()) {
            r_msg2(unitData, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(unitUUID) && remote_call_current_success()) {
            r_msg2(unitUUID, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(storeUnit) && remote_call_current_success()) {
            r_msg2(storeUnit, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(uuid) && remote_call_current_success()) {
            r_msg2(uuid, "release", 0, 0, 0, 0);
        }
    }

    if (r_is_objc_ptr(indexData) && remote_call_current_success()) {
        r_msg2(indexData, "release", 0, 0, 0, 0);
    }
    themer_iconservices_lab_free_data_capture(&indexCapture);
    if (r_is_objc_ptr(storeIndex) && remote_call_current_success()) {
        r_msg2(storeIndex, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(store) && remote_call_current_success()) {
        r_msg2(store, "release", 0, 0, 0, 0);
    }

    uint64_t ioFailuresAfter = remote_call_current_io_failure_count();
    printf("[ICONSERVICES_LAB] store-record-summary cache=0x%llx "
           "selector=storeUnitForUUID: types=\"%s\" abiReady=%d "
           "entries=%d attempted=%d found=%d methodsLogged=%d "
           "ioFailures=%llu->%llu transportClean=%d\n",
           (unsigned long long)cache,
           methodTypes,
           abiReady,
           d->stockEntryCount,
           attempted,
           found,
           methodsLogged,
           (unsigned long long)ioFailuresBefore,
           (unsigned long long)ioFailuresAfter,
           ioFailuresAfter == ioFailuresBefore);
    return remote_call_current_success();
}

static bool themer_iconservices_lab_trace_store_stock40_metadata(
    const ThemerIconServicesLabDiscovery *d)
{
    if (!d || d->primaryEntryIndex < 0 ||
        d->primaryEntryIndex >= d->stockEntryCount ||
        !remote_call_current_success()) {
        return false;
    }
    uint64_t state = themer_iconservices_lab_trace_state();
    const ThemerIconServicesLabBagEntry *entry =
        &d->stockEntries[d->primaryEntryIndex];
    if (!r_is_objc_ptr(state) || !r_is_objc_ptr(entry->image) ||
        !entry->geometryKnown) {
        return false;
    }

    uint64_t data = themer_iconservices_lab_retained_getter(
        entry->image, "data");
    uint64_t uuid = themer_iconservices_lab_retained_getter(
        entry->image, "uuid");
    uint64_t token = themer_iconservices_lab_retained_getter(
        entry->image, "validationToken");
    ThemerIconServicesLabDataCapture dataCapture = {0};
    ThemerIconServicesLabDataCapture tokenCapture = {0};
    bool dataCaptured = r_is_objc_ptr(data) &&
        themer_iconservices_lab_capture_nsdata(
            data, THEMER_ICONSERVICES_LAB_STOCK_COMPARE_DATA_CAP,
            &dataCapture);
    bool tokenCaptured = r_is_objc_ptr(token) &&
        themer_iconservices_lab_capture_nsdata(
            token, THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP,
            &tokenCapture);
    uint8_t sha1[20] = {0};
    uint8_t sha256[32] = {0};
    bool sha1Known = dataCaptured && !dataCapture.truncated &&
        dataCapture.capturedLength > 0 &&
        themer_iconservices_lab_digest(
            "CC_SHA1", dataCapture.bytes, dataCapture.capturedLength, sha1);
    bool sha256Known = dataCaptured && !dataCapture.truncated &&
        dataCapture.capturedLength > 0 &&
        themer_iconservices_lab_digest(
            "CC_SHA256", dataCapture.bytes, dataCapture.capturedLength,
            sha256);
    char uuidText[160] = {0};
    char tokenHex[THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP * 2 + 1] = {0};
    char sha1Hex[41] = {0};
    char sha256Hex[65] = {0};
    (void)themer_read_remote_description(
        uuid, uuidText, sizeof(uuidText));
    themer_iconservices_lab_hex_bytes(
        tokenCapture.bytes, tokenCapture.capturedLength,
        tokenHex, sizeof(tokenHex));
    themer_iconservices_lab_hex_bytes(
        sha1, sizeof(sha1), sha1Hex, sizeof(sha1Hex));
    themer_iconservices_lab_hex_bytes(
        sha256, sizeof(sha256), sha256Hex, sizeof(sha256Hex));

    uint64_t widthNumber = themer_iconservices_lab_double_number(entry->width);
    uint64_t heightNumber = themer_iconservices_lab_double_number(entry->height);
    uint64_t scaleNumber = themer_iconservices_lab_double_number(entry->scale);
    uint64_t dataLengthNumber = themer_spotlight_proof_number(
        (unsigned long long)dataCapture.objectLength);
    uint64_t tokenLengthNumber = themer_spotlight_proof_number(
        (unsigned long long)tokenCapture.objectLength);
    bool ready = dataCaptured && !dataCapture.truncated && tokenCaptured &&
        !tokenCapture.truncated && sha1Known && sha256Known &&
        uuidText[0] && tokenHex[0] &&
        r_is_objc_ptr(widthNumber) && r_is_objc_ptr(heightNumber) &&
        r_is_objc_ptr(scaleNumber) && r_is_objc_ptr(dataLengthNumber) &&
        r_is_objc_ptr(tokenLengthNumber) &&
        themer_spotlight_dictionary_set_object(
            state, "stock40Width", widthNumber) &&
        themer_spotlight_dictionary_set_object(
            state, "stock40Height", heightNumber) &&
        themer_spotlight_dictionary_set_object(
            state, "stock40Scale", scaleNumber) &&
        themer_spotlight_dictionary_set_object(
            state, "stock40DataLength", dataLengthNumber) &&
        themer_spotlight_dictionary_set_object(
            state, "stock40TokenLength", tokenLengthNumber) &&
        themer_spotlight_proof_state_set_string(
            state, "stock40UUID", uuidText) &&
        themer_spotlight_proof_state_set_string(
            state, "stock40TokenHex", tokenHex) &&
        themer_spotlight_proof_state_set_string(
            state, "stock40DataSHA1", sha1Hex) &&
        themer_spotlight_proof_state_set_string(
            state, "stock40DataSHA256", sha256Hex);
    printf("[ICONSERVICES_LAB] materialization-trace-stock40 stored=%d "
           "image=0x%llx geometry=%.1fx%.1f@%.2f uuid=\"%s\" "
           "data=%zu/%zu/truncated=%d sha1=%s sha256=%s "
           "token=%zu/%zu/truncated=%d hex=%s\n",
           ready,
           (unsigned long long)entry->image,
           entry->width,
           entry->height,
           entry->scale,
           uuidText,
           dataCapture.objectLength,
           dataCapture.capturedLength,
           dataCapture.truncated,
           sha1Known ? sha1Hex : "?",
           sha256Known ? sha256Hex : "?",
           tokenCapture.objectLength,
           tokenCapture.capturedLength,
           tokenCapture.truncated,
           tokenHex);
    if (r_is_objc_ptr(token) && remote_call_current_success()) {
        r_msg2(token, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(uuid) && remote_call_current_success()) {
        r_msg2(uuid, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(data) && remote_call_current_success()) {
        r_msg2(data, "release", 0, 0, 0, 0);
    }
    themer_iconservices_lab_free_data_capture(&tokenCapture);
    themer_iconservices_lab_free_data_capture(&dataCapture);
    return ready && remote_call_current_success();
}

// Construction-only experiment for deriving a genuine themed IFCacheImage.
// Every object mutated here is newly allocated and throwaway; no IconServices
// cache, image bag, donor image, or process-resident lab state is modified.
typedef struct {
    uint64_t result;
    uint64_t recordImage;
    uint64_t data;
    uint64_t uuidRaw;
    uint64_t token;
    uint64_t error;
    uint64_t sharedMemory;
    ThemerIconServicesLabDataCapture dataCapture;
    ThemerIconServicesLabDataCapture tokenCapture;
    bool dataCaptured;
    bool tokenCaptured;
    bool uuidObserved;
    bool recordImageOwned;
    bool geometryKnown;
    bool pixelKnown;
    double width;
    double height;
    double scale;
    double pixelWidth;
    double pixelHeight;
    uint64_t cgImage;
    bool coherent;
} ThemerIconServicesLabGenerationSample;

static void themer_iconservices_lab_release_generation_sample(
    ThemerIconServicesLabGenerationSample *sample)
{
    if (!sample) return;
    if (sample->recordImageOwned && r_is_objc_ptr(sample->recordImage) &&
        remote_call_current_success()) {
        r_msg2(sample->recordImage, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(sample->sharedMemory) &&
        remote_call_current_success()) {
        r_msg2(sample->sharedMemory, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(sample->error) && remote_call_current_success()) {
        r_msg2(sample->error, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(sample->token) && remote_call_current_success()) {
        r_msg2(sample->token, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(sample->data) && remote_call_current_success()) {
        r_msg2(sample->data, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(sample->result) && remote_call_current_success()) {
        r_msg2(sample->result, "release", 0, 0, 0, 0);
    }
    themer_iconservices_lab_free_data_capture(&sample->tokenCapture);
    themer_iconservices_lab_free_data_capture(&sample->dataCapture);
    memset(sample, 0, sizeof(*sample));
}

static bool themer_iconservices_lab_capture_generation_sample(
    const char *role,
    uint64_t result,
    double expectedWidth,
    double expectedHeight,
    double expectedScale,
    ThemerIconServicesLabGenerationSample *sample)
{
    if (!role || !sample || !r_is_objc_ptr(result) ||
        !remote_call_current_success()) {
        return false;
    }
    memset(sample, 0, sizeof(*sample));
    sample->result = result;  // +1 already owned by the caller.
    char resultClass[96] = {0};
    char resultText[220] = {0};
    themer_read_class_name(result, resultClass, sizeof(resultClass));
    themer_read_remote_description(result, resultText, sizeof(resultText));

    sample->data = themer_iconservices_lab_retained_getter(result, "data");
    bool respondsUUID = r_responds_main(result, "uuid");
    sample->uuidRaw = respondsUUID
        ? r_msg2_main(result, "uuid", 0, 0, 0, 0) : 0;
    sample->uuidObserved = respondsUUID && remote_call_current_success();
    sample->token = themer_iconservices_lab_retained_getter(
        result, "validationToken");
    sample->error = themer_iconservices_lab_retained_getter(result, "error");
    sample->sharedMemory = themer_iconservices_lab_retained_getter(
        result, "sharedMemory");
    sample->dataCaptured = r_is_objc_ptr(sample->data) &&
        themer_iconservices_lab_capture_nsdata(
            sample->data, THEMER_ICONSERVICES_LAB_STOCK_COMPARE_DATA_CAP,
            &sample->dataCapture);
    sample->tokenCaptured = r_is_objc_ptr(sample->token) &&
        themer_iconservices_lab_capture_nsdata(
            sample->token, THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP,
            &sample->tokenCapture);

    sample->recordImage = result;
    sample->geometryKnown = r_is_objc_ptr(sample->recordImage) &&
        themer_iconservices_lab_read_image_geometry(
            sample->recordImage,
            &sample->width, &sample->height, &sample->scale);
    sample->pixelKnown = r_is_objc_ptr(sample->recordImage) &&
        themer_iconservices_lab_read_size_property(
            sample->recordImage, "pixelSize",
            &sample->pixelWidth, &sample->pixelHeight);
    sample->cgImage = r_is_objc_ptr(sample->recordImage) &&
        r_responds_main(sample->recordImage, "CGImage")
        ? r_msg2_main(sample->recordImage, "CGImage", 0, 0, 0, 0) : 0;
    uint64_t cgWidth = sample->cgImage
        ? r_dlsym_call(R_TIMEOUT, "CGImageGetWidth",
                       sample->cgImage, 0, 0, 0, 0, 0, 0, 0)
        : 0;
    uint64_t cgHeight = sample->cgImage
        ? r_dlsym_call(R_TIMEOUT, "CGImageGetHeight",
                       sample->cgImage, 0, 0, 0, 0, 0, 0, 0)
        : 0;
    double widthDelta = sample->width - expectedWidth;
    double heightDelta = sample->height - expectedHeight;
    double scaleDelta = sample->scale - expectedScale;
    if (widthDelta < 0.0) widthDelta = -widthDelta;
    if (heightDelta < 0.0) heightDelta = -heightDelta;
    if (scaleDelta < 0.0) scaleDelta = -scaleDelta;
    double expectedPixelsW = expectedWidth * expectedScale;
    double expectedPixelsH = expectedHeight * expectedScale;
    double pixelWidthDelta = sample->pixelWidth - expectedPixelsW;
    double pixelHeightDelta = sample->pixelHeight - expectedPixelsH;
    if (pixelWidthDelta < 0.0) pixelWidthDelta = -pixelWidthDelta;
    if (pixelHeightDelta < 0.0) pixelHeightDelta = -pixelHeightDelta;
    sample->coherent = sample->dataCaptured &&
        !sample->dataCapture.truncated && sample->dataCapture.objectLength > 0 &&
        sample->tokenCaptured && !sample->tokenCapture.truncated &&
        sample->tokenCapture.objectLength > 0 &&
        sample->uuidObserved && sample->error == 0 &&
        sample->geometryKnown && widthDelta < 0.01 && heightDelta < 0.01 &&
        scaleDelta < 0.01 && sample->pixelKnown &&
        pixelWidthDelta < 0.01 && pixelHeightDelta < 0.01 &&
        cgWidth == (uint64_t)expectedPixelsW &&
        cgHeight == (uint64_t)expectedPixelsH &&
        remote_call_current_success();

    char errorText[220] = {0};
    char sharedClass[96] = {0};
    char dataPrefix[65] = {0};
    char tokenHex[THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP * 2 + 1] = {0};
    themer_read_remote_description(
        sample->error, errorText, sizeof(errorText));
    themer_read_class_name(
        sample->sharedMemory, sharedClass, sizeof(sharedClass));
    themer_iconservices_lab_hex_bytes(
        sample->dataCapture.bytes,
        sample->dataCapture.capturedLength < 32
            ? sample->dataCapture.capturedLength : 32,
        dataPrefix, sizeof(dataPrefix));
    themer_iconservices_lab_hex_bytes(
        sample->tokenCapture.bytes, sample->tokenCapture.capturedLength,
        tokenHex, sizeof(tokenHex));
    printf("[ICONSERVICES_LAB] generation-result role=%s result=0x%llx/%s "
           "desc=\"%s\" recordImage=0x%llx/owned=%d "
           "data=%zu/%zu/truncated=%d prefix=%s "
           "uuidRaw=0x%llx observed=%d "
           "token=%zu/%zu/truncated=%d hex=%s "
           "error=0x%llx/\"%s\" shared=0x%llx/%s "
           "geometry=%d/%.1fx%.1f@%.2f pixel=%d/%.0fx%.0f "
           "cgImage=0x%llx/%llux%llu coherent=%d\n",
           role,
           (unsigned long long)result,
           resultClass[0] ? resultClass : "-",
           resultText,
           (unsigned long long)sample->recordImage,
           sample->recordImageOwned,
           sample->dataCapture.objectLength,
           sample->dataCapture.capturedLength,
           sample->dataCapture.truncated,
           dataPrefix,
           (unsigned long long)sample->uuidRaw,
           sample->uuidObserved,
           sample->tokenCapture.objectLength,
           sample->tokenCapture.capturedLength,
           sample->tokenCapture.truncated,
           "<redacted>",
           (unsigned long long)sample->error,
           errorText,
           (unsigned long long)sample->sharedMemory,
           sharedClass[0] ? sharedClass : "-",
           sample->geometryKnown,
           sample->width,
           sample->height,
           sample->scale,
           sample->pixelKnown,
           sample->pixelWidth,
           sample->pixelHeight,
           (unsigned long long)sample->cgImage,
           (unsigned long long)cgWidth,
           (unsigned long long)cgHeight,
           sample->coherent);
    return remote_call_current_success();
}

typedef struct {
    uint64_t generationInvocation;
    uint64_t holderInvocation;
    uint64_t directHolderInvocation;
    uint64_t outSlot;
    uint64_t directSlot;
    uint64_t directRaw;
    uint64_t raw;
    bool exactABI;
    bool dispatchPossible;
    bool generationInvoked;
    bool observed;
    bool binderInvoked;
    bool retainerInvoked;
    bool holderArgumentMatches;
    bool argumentsRetained;
    bool directArgumentMatches;
    bool directArgumentsRetained;
    bool ownerBoundPostDispatch;
    bool transportClean;
    ThemerSpotlightStock68RecordIdentifiersDecodeStatus decodeStatus;
    int decodeNodes;
    int decodeMetadata;
    ThemerRecordBlobObservation firstBlob;
} ThemerIconServicesLabRecordIdentifiersObservation;

static void themer_record_blob_copy_to_report(
    const ThemerRecordBlobObservation *blob,
    ThemerSpotlightStock68MaterializationReport *report)
{
    if (!blob || !report || !blob->captured) return;
    report->recordIdentifiersBlobCaptured = true;
    report->recordIdentifiersBlobTotalLength = blob->capture.objectLength;
    report->recordIdentifiersBlobCapturedLength = blob->capture.capturedLength;
    report->recordIdentifiersBlobTruncated = blob->capture.truncated;
    snprintf(report->recordIdentifiersBlobFormat,
             sizeof(report->recordIdentifiersBlobFormat), "%s", blob->format);
    snprintf(report->recordIdentifiersBlobSHA256,
             sizeof(report->recordIdentifiersBlobSHA256), "%s", blob->sha256);
    snprintf(report->recordIdentifiersBlobPrefixHex,
             sizeof(report->recordIdentifiersBlobPrefixHex), "%s", blob->prefixHex);
    snprintf(report->recordIdentifiersBlobHex,
             sizeof(report->recordIdentifiersBlobHex), "%s", blob->hex);
}

static bool themer_record_bytes_contain(const uint8_t *haystack,
                                        size_t haystackLength,
                                        const uint8_t *needle,
                                        size_t needleLength)
{
    // Empty captures carry no evidence about record-identifier/token
    // relationships.  Treat them as incomparable instead of reporting a
    // vacuous containment match in this diagnostic.
    if (haystackLength == 0 || needleLength == 0) return false;
    if (!haystack || !needle || needleLength > haystackLength) return false;
    for (size_t i = 0; i + needleLength <= haystackLength; i++) {
        if (memcmp(haystack + i, needle, needleLength) == 0) return true;
    }
    return false;
}

static void themer_record_blob_compare_token(
    const ThemerRecordBlobObservation *blob,
    const ThemerIconServicesLabGenerationSample *sample,
    ThemerSpotlightStock68MaterializationReport *report)
{
    if (!blob || !sample || !report || !blob->captured || !sample->tokenCaptured) return;
    const uint8_t *left = blob->capture.bytes;
    const uint8_t *right = sample->tokenCapture.bytes;
    size_t leftLength = blob->capture.capturedLength;
    size_t rightLength = sample->tokenCapture.capturedLength;
    report->recordIdentifiersTokenLength = sample->tokenCapture.objectLength;
    report->recordIdentifiersTokenTruncated = sample->tokenCapture.truncated;
    report->recordIdentifiersBlobEqualsToken = leftLength > 0 &&
        rightLength > 0 && !blob->capture.truncated &&
        !sample->tokenCapture.truncated && leftLength == rightLength &&
        memcmp(left, right, leftLength) == 0;
    report->recordIdentifiersBlobContainsToken =
        themer_record_bytes_contain(left, leftLength, right, rightLength);
    report->recordIdentifiersTokenContainsBlob =
        themer_record_bytes_contain(right, rightLength, left, leftLength);
    printf("[ICONSERVICES_LAB] record-identifiers-blob-token blob=%zu/%d token=%zu/%d "
           "equal=%d blobContainsToken=%d tokenContainsBlob=%d observationalOnly=1\n",
           blob->capture.objectLength, blob->capture.truncated,
           sample->tokenCapture.objectLength, sample->tokenCapture.truncated,
           report->recordIdentifiersBlobEqualsToken,
           report->recordIdentifiersBlobContainsToken,
           report->recordIdentifiersTokenContainsBlob);
}

static uint32_t themer_record_read_u32_le(const uint8_t *bytes)
{
    return (uint32_t)bytes[0] | ((uint32_t)bytes[1] << 8) |
        ((uint32_t)bytes[2] << 16) | ((uint32_t)bytes[3] << 24);
}

static uint64_t themer_record_read_u64_le(const uint8_t *bytes)
{
    uint64_t value = 0;
    for (int i = 7; i >= 0; i--) value = (value << 8) | bytes[i];
    return value;
}

static void themer_stock68_candidate_uuid_text(const uint8_t bytes[16],
                                                char output[80])
{
    if (!bytes || !output) return;
    snprintf(output, 80,
             "%02X%02X%02X%02X-%02X%02X-%02X%02X-"
             "%02X%02X-%02X%02X%02X%02X%02X%02X",
             bytes[0], bytes[1], bytes[2], bytes[3],
             bytes[4], bytes[5], bytes[6], bytes[7],
             bytes[8], bytes[9], bytes[10], bytes[11],
             bytes[12], bytes[13], bytes[14], bytes[15]);
}

// This recognizes exactly one observed packed shape.  The field labels use
// offsets deliberately: their semantics are unknown and are never inferred.
static bool themer_stock68_parse_record_candidate(
    const ThemerRecordBlobObservation *blob,
    const ThemerIconServicesLabGenerationSample *sample,
    ThemerSpotlightStock68MaterializationReport *report)
{
    if (!blob || !sample || !report || !blob->captured || blob->dataLeafCount != 1 ||
        report->recordIdentifiersDecodeStatus != ThemerSpotlightStock68RecordIdentifiersDecodeDecoded ||
        !report->recordIdentifiersOwnershipVerified || report->requestCount != 1) return false;
    const ThemerIconServicesLabDataCapture *capture = &blob->capture;
    const uint8_t *bytes = capture->bytes;
    bool exactLength = capture->objectLength == 36 &&
        capture->capturedLength == 36 && !capture->truncated && bytes;
    uint32_t word0 = exactLength ? themer_record_read_u32_le(bytes) : 0;
    uint32_t word4 = exactLength ? themer_record_read_u32_le(bytes + 4) : 0;
    uint32_t word8 = exactLength ? themer_record_read_u32_le(bytes + 8) : 0;
    uint64_t tail = exactLength ? themer_record_read_u64_le(bytes + 28) : 0;
    bool layout = exactLength && word0 == 0 && word4 == 3944 && word8 == 8 &&
        tail == 3944 && word4 == tail;
    if (layout) {
        report->recordIdentifiersCandidateWord0 = word0;
        report->recordIdentifiersCandidateWord4 = word4;
        report->recordIdentifiersCandidateWord8 = word8;
        report->recordIdentifiersCandidateTail = tail;
        themer_stock68_candidate_uuid_text(
            bytes + 12, report->recordIdentifiersCandidateUUID);
    }
    bool tokenComplete = sample->tokenCaptured &&
        !sample->tokenCapture.truncated &&
        sample->tokenCapture.objectLength == 40 &&
        sample->tokenCapture.capturedLength == 40 &&
        sample->tokenCapture.bytes;
    bool tokenBound = layout && tokenComplete &&
        memcmp(bytes + 12, sample->tokenCapture.bytes, 16) == 0;
    report->recordIdentifiersCandidateParsed = layout;
    report->recordIdentifiersCandidateTokenBound = tokenBound;
    report->recordIdentifiersCandidateClassified = layout && tokenBound;
    printf("[ICONSERVICES_MATERIALIZE] record-candidate length=%zu/%zu "
           "truncated=%d offsets=0/%u/4/%u/8/%u/28/%llu layout=%d "
           "uuid=%s token=%zu/%zu truncated=%d prefixBound=%d "
           "classified=%d observationalOnly=1\n",
           capture->objectLength,
           capture->capturedLength,
           capture->truncated,
           word0,
           word4,
           word8,
           (unsigned long long)tail,
           layout,
           layout ? report->recordIdentifiersCandidateUUID : "-",
           sample->tokenCapture.objectLength,
           sample->tokenCapture.capturedLength,
           sample->tokenCapture.truncated,
           tokenBound,
           report->recordIdentifiersCandidateClassified);
    return report->recordIdentifiersCandidateClassified;
}

static uint64_t themer_stock68_correlation_retained_object_exact(
    uint64_t object,
    const char *selector,
    char *types,
    size_t typesLength,
    bool *abiOut)
{
    if (abiOut) *abiOut = false;
    if (types && typesLength) types[0] = '\0';
    bool abi = r_is_objc_ptr(object) && selector &&
        r_responds_main(object, selector) &&
        themer_iconservices_lab_method_types(object, selector, types,
                                             typesLength) &&
        strcmp(types, "@16@0:8") == 0;
    if (abiOut) *abiOut = abi;
    return abi ? r_msg2_main_retained_object(object, selector, 0, 0, 0, 0) : 0;
}

static void themer_stock68_correlate_record_candidate(
    uint64_t managerCache,
    const char *managerCachePath,
    double namedScale,
    const ThemerIconServicesLabGenerationSample *sample,
    ThemerSpotlightStock68MaterializationReport *report)
{
    if (!sample || !report || !report->recordIdentifiersCandidateClassified ||
        !managerCachePath || !managerCachePath[0] ||
        !r_is_objc_ptr(sample->data) || !r_is_objc_ptr(sample->token) ||
        !remote_call_current_success()) return;

    uint8_t uuidBytes[16] = {0};
    if (!themer_iconservices_lab_parse_uuid_text(
            report->recordIdentifiersCandidateUUID, uuidBytes)) return;
    NSString *uuidText = [NSString stringWithUTF8String:
        report->recordIdentifiersCandidateUUID];
    uint64_t remoteUUID = uuidText
        ? themer_iconservices_lab_make_remote_uuid(uuidText) : 0;
    NSString *directory = [NSString stringWithUTF8String:managerCachePath];
    NSString *fileName = uuidText.length > 0
        ? [NSString stringWithFormat:@"%@.isdata", uuidText] : nil;
    NSString *path = directory && fileName
        ? [directory stringByAppendingPathComponent:fileName] : nil;
    snprintf(report->recordIdentifiersCandidatePath,
             sizeof(report->recordIdentifiersCandidatePath), "%s",
             path.UTF8String ?: "");
    struct stat st = {0};
    int statResult = path.length > 0
        ? lstat(path.fileSystemRepresentation, &st) : -1;
    report->recordIdentifiersCandidateFileExists = statResult == 0;
    report->recordIdentifiersCandidateFileRegular = statResult == 0 &&
        S_ISREG(st.st_mode);
    report->recordIdentifiersCandidateFileReadable =
        report->recordIdentifiersCandidateFileRegular &&
        access(path.fileSystemRepresentation, R_OK) == 0;
    report->recordIdentifiersCandidateFileNonempty =
        report->recordIdentifiersCandidateFileRegular && st.st_size > 0;
    report->recordIdentifiersCandidateFileSize =
        report->recordIdentifiersCandidateFileRegular && st.st_size >= 0
        ? (uint64_t)st.st_size : 0;
    NSData *fileData = report->recordIdentifiersCandidateFileReadable &&
        report->recordIdentifiersCandidateFileNonempty &&
        st.st_size <= (off_t)(8U << 20)
        ? themer_iconservices_lab_read_local_file(path) : nil;
    report->recordIdentifiersCandidateFileExactSize = fileData &&
        (uint64_t)fileData.length == report->recordIdentifiersCandidateFileSize;

    char lookupTypes[192] = {0};
    bool lookupABI = r_is_objc_ptr(managerCache) &&
        r_responds_main(managerCache, "storeUnitForUUID:") &&
        themer_iconservices_lab_method_types(
            managerCache, "storeUnitForUUID:", lookupTypes,
            sizeof(lookupTypes)) && strcmp(lookupTypes, "@24@0:8@16") == 0;
    report->recordIdentifiersCandidateStoreLookupABI = lookupABI;
    uint64_t storeUnit = 0;
    if (lookupABI && r_is_objc_ptr(remoteUUID)) {
        report->recordIdentifiersCandidateStoreLookupAttempted = true;
        storeUnit = r_msg2_main_retained_object(
            managerCache, "storeUnitForUUID:", remoteUUID, 0, 0, 0);
    }
    char unitClass[96] = {0};
    themer_read_class_name(storeUnit, unitClass, sizeof(unitClass));
    snprintf(report->recordIdentifiersCandidateStoreUnitClass,
             sizeof(report->recordIdentifiersCandidateStoreUnitClass), "%s",
             unitClass);
    report->recordIdentifiersCandidateStoreUnitFound =
        r_is_objc_ptr(storeUnit) && unitClass[0] && remote_call_current_success();

    char unitUUIDTypes[192] = {0};
    char unitDataTypes[192] = {0};
    char unitValidTypes[192] = {0};
    bool unitABI = report->recordIdentifiersCandidateStoreUnitFound &&
        r_responds_main(storeUnit, "UUID") &&
        themer_iconservices_lab_method_types(storeUnit, "UUID", unitUUIDTypes,
                                             sizeof(unitUUIDTypes)) &&
        strcmp(unitUUIDTypes, "@16@0:8") == 0 &&
        r_responds_main(storeUnit, "data") &&
        themer_iconservices_lab_method_types(storeUnit, "data", unitDataTypes,
                                             sizeof(unitDataTypes)) &&
        strcmp(unitDataTypes, "@16@0:8") == 0 &&
        r_responds_main(storeUnit, "isValid") &&
        themer_iconservices_lab_method_types(storeUnit, "isValid", unitValidTypes,
                                             sizeof(unitValidTypes)) &&
        strcmp(unitValidTypes, "B16@0:8") == 0;
    report->recordIdentifiersCandidateStoreUnitABI = unitABI;
    uint64_t unitUUID = unitABI ? r_msg2_main_retained_object(
        storeUnit, "UUID", 0, 0, 0, 0) : 0;
    uint64_t unitData = unitABI ? r_msg2_main_retained_object(
        storeUnit, "data", 0, 0, 0, 0) : 0;
    uint64_t validRaw = unitABI
        ? r_msg2_main(storeUnit, "isValid", 0, 0, 0, 0) : 0;
    report->recordIdentifiersCandidateStoreUnitValidKnown = unitABI &&
        remote_call_current_success();
    report->recordIdentifiersCandidateStoreUnitValid =
        report->recordIdentifiersCandidateStoreUnitValidKnown && (validRaw & 1);
    report->recordIdentifiersCandidateStoreUnitUUIDEqual =
        r_is_objc_ptr(unitUUID) && r_is_objc_ptr(remoteUUID) &&
        themer_iconservices_lab_objects_equal(unitUUID, remoteUUID);
    report->recordIdentifiersCandidateStoreUnitDataEqual =
        r_is_objc_ptr(unitData) &&
        themer_iconservices_lab_objects_equal(unitData, sample->data);

    char indexTypes[192] = {0};
    uint64_t storeIndex = themer_stock68_correlation_retained_object_exact(
        managerCache, "storeIndex", indexTypes, sizeof(indexTypes), NULL);
    char dataTypes[192] = {0};
    uint64_t indexData = themer_stock68_correlation_retained_object_exact(
        storeIndex, "data", dataTypes, sizeof(dataTypes), NULL);
    char indexDataClass[96] = {0};
    themer_read_class_name(indexData, indexDataClass, sizeof(indexDataClass));
    ThemerIconServicesLabDataCapture indexCapture = {0};
    bool indexCaptured = r_is_objc_ptr(indexData) &&
        (strstr(indexDataClass, "dispatch_data")
            ? themer_iconservices_lab_capture_dispatch_data(
                indexData, THEMER_ICONSERVICES_LAB_INDEX_CAPTURE_CAP,
                &indexCapture)
            : themer_iconservices_lab_capture_nsdata(
                indexData, THEMER_ICONSERVICES_LAB_INDEX_CAPTURE_CAP,
                &indexCapture));
    size_t uuidFirstOffset = SIZE_MAX;
    size_t tokenFirstOffset = SIZE_MAX;
    report->recordIdentifiersCandidateIndexUUIDOccurrences = indexCaptured
        ? themer_iconservices_lab_count_byte_sequence(
            indexCapture.bytes, indexCapture.capturedLength, uuidBytes,
            sizeof(uuidBytes), &uuidFirstOffset) : 0;
    report->recordIdentifiersCandidateIndexTokenOccurrences = indexCaptured
        ? themer_iconservices_lab_count_byte_sequence(
            indexCapture.bytes, indexCapture.capturedLength,
            sample->tokenCapture.bytes, sample->tokenCapture.capturedLength,
            &tokenFirstOffset) : 0;
    report->recordIdentifiersCandidateIndexUUIDFirstOffset =
        uuidFirstOffset == SIZE_MAX ? -1 : (int64_t)uuidFirstOffset;
    report->recordIdentifiersCandidateIndexTokenFirstOffset =
        tokenFirstOffset == SIZE_MAX ? -1 : (int64_t)tokenFirstOffset;

    uint64_t reconstructed = r_is_objc_ptr(remoteUUID)
        ? themer_iconservices_lab_make_if_cache_image(
            sample->data, remoteUUID, sample->token) : 0;
    report->recordIdentifiersCandidateReconstructionAttempted =
        r_is_objc_ptr(remoteUUID);
    char reconstructionClass[96] = {0};
    themer_read_class_name(reconstructed, reconstructionClass,
                           sizeof(reconstructionClass));
    report->recordIdentifiersCandidateReconstructionClass =
        strcmp(reconstructionClass, "IFCacheImage") == 0;
    char reconstructedUUIDTypes[192] = {0};
    char reconstructedTokenTypes[192] = {0};
    uint64_t reconstructedUUID =
        themer_stock68_correlation_retained_object_exact(
            reconstructed, "uuid", reconstructedUUIDTypes,
            sizeof(reconstructedUUIDTypes), NULL);
    uint64_t reconstructedToken =
        themer_stock68_correlation_retained_object_exact(
            reconstructed, "validationToken", reconstructedTokenTypes,
            sizeof(reconstructedTokenTypes), NULL);
    report->recordIdentifiersCandidateReconstructionUUIDEqual =
        r_is_objc_ptr(reconstructedUUID) &&
        themer_iconservices_lab_objects_equal(reconstructedUUID, remoteUUID);
    report->recordIdentifiersCandidateReconstructionTokenEqual =
        r_is_objc_ptr(reconstructedToken) &&
        themer_iconservices_lab_objects_equal(reconstructedToken, sample->token);
    report->recordIdentifiersCandidateReconstructionGeometry =
        report->recordIdentifiersCandidateReconstructionClass &&
        themer_iconservices_lab_image_geometry_matches(
            reconstructed, 68.0, 68.0, namedScale);
    report->recordIdentifiersCandidateReconstructionFileEqual = fileData &&
        sample->dataCaptured && !sample->dataCapture.truncated &&
        fileData.length == sample->dataCapture.objectLength &&
        memcmp(fileData.bytes, sample->dataCapture.bytes, fileData.length) == 0;
    printf("[ICONSERVICES_MATERIALIZE] record-candidate-correlation "
           "uuid=%s path=\"%s\" file=%d/%d/%d/%d exact=%d/%llu "
           "lookup types=\"%s\" abi=%d attempted=%d unit=%d/%s unitABI=%d "
           "uuidEqual=%d dataEqual=%d valid=%d/%d index=%s/%zu/%zu "
           "uuidOccurrences=%llu@%lld tokenOccurrences=%llu@%lld "
           "reconstruct=%d/%d uuid=%d token=%d geometry=%d fileEqual=%d "
           "observationalOnly=1\n",
           report->recordIdentifiersCandidateUUID,
           report->recordIdentifiersCandidatePath,
           report->recordIdentifiersCandidateFileExists,
           report->recordIdentifiersCandidateFileRegular,
           report->recordIdentifiersCandidateFileReadable,
           report->recordIdentifiersCandidateFileNonempty,
           report->recordIdentifiersCandidateFileExactSize,
           (unsigned long long)report->recordIdentifiersCandidateFileSize,
           lookupTypes,
           lookupABI,
           report->recordIdentifiersCandidateStoreLookupAttempted,
           report->recordIdentifiersCandidateStoreUnitFound,
           unitClass[0] ? unitClass : "-",
           unitABI,
           report->recordIdentifiersCandidateStoreUnitUUIDEqual,
           report->recordIdentifiersCandidateStoreUnitDataEqual,
           report->recordIdentifiersCandidateStoreUnitValidKnown,
           report->recordIdentifiersCandidateStoreUnitValid,
           indexDataClass[0] ? indexDataClass : "-",
           indexCapture.objectLength,
           indexCapture.capturedLength,
           (unsigned long long)report->recordIdentifiersCandidateIndexUUIDOccurrences,
           (long long)report->recordIdentifiersCandidateIndexUUIDFirstOffset,
           (unsigned long long)report->recordIdentifiersCandidateIndexTokenOccurrences,
           (long long)report->recordIdentifiersCandidateIndexTokenFirstOffset,
           report->recordIdentifiersCandidateReconstructionAttempted,
           report->recordIdentifiersCandidateReconstructionClass,
           report->recordIdentifiersCandidateReconstructionUUIDEqual,
           report->recordIdentifiersCandidateReconstructionTokenEqual,
           report->recordIdentifiersCandidateReconstructionGeometry,
           report->recordIdentifiersCandidateReconstructionFileEqual);
    if (r_is_objc_ptr(reconstructedToken) && remote_call_current_success())
        r_msg2(reconstructedToken, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(reconstructedUUID) && remote_call_current_success())
        r_msg2(reconstructedUUID, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(reconstructed) && remote_call_current_success())
        r_msg2(reconstructed, "release", 0, 0, 0, 0);
    themer_iconservices_lab_free_data_capture(&indexCapture);
    if (r_is_objc_ptr(indexData) && remote_call_current_success())
        r_msg2(indexData, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(storeIndex) && remote_call_current_success())
        r_msg2(storeIndex, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(unitData) && remote_call_current_success())
        r_msg2(unitData, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(unitUUID) && remote_call_current_success())
        r_msg2(unitUUID, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(storeUnit) && remote_call_current_success())
        r_msg2(storeUnit, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(remoteUUID) && remote_call_current_success())
        r_msg2(remoteUUID, "release", 0, 0, 0, 0);
}

typedef bool (*ThemerStock68GenerationDispatchMarker)(void *context);

static bool themer_stock68_topology_exactly_empty(
    const ThemerIconServicesLabTopologySnapshot *snapshot);

static uint64_t themer_iconservices_lab_generation_request(
    uint64_t icon,
    uint64_t descriptor,
    bool *abiReadyOut,
    ThemerIconServicesLabRecordIdentifiersObservation *recordIdentifiersOut,
    bool *generationInvokedOut,
    bool *dispatchPossibleOut,
    ThemerStock68GenerationDispatchMarker dispatchMarker,
    void *dispatchMarkerContext)
{
    if (abiReadyOut) *abiReadyOut = false;
    if (recordIdentifiersOut) {
        memset(recordIdentifiersOut, 0, sizeof(*recordIdentifiersOut));
    }
    if (generationInvokedOut) *generationInvokedOut = false;
    if (dispatchPossibleOut) *dispatchPossibleOut = false;
    if (!r_is_objc_ptr(icon) || !r_is_objc_ptr(descriptor) ||
        !remote_call_current_success()) {
        return 0;
    }
    uint64_t requestClass = themer_lookup_class("ISGenerationRequest");
    uint64_t concreteIconClass = themer_lookup_class("ISConcreteIcon");
    bool iconConcrete = r_is_objc_ptr(concreteIconClass) &&
        r_responds_main(icon, "isKindOfClass:") &&
        (r_msg2_main(icon, "isKindOfClass:",
                     concreteIconClass, 0, 0, 0) & 1) != 0;
    uint64_t alloc = r_is_objc_ptr(requestClass)
        ? r_msg2(requestClass, "alloc", 0, 0, 0, 0) : 0;
    char initTypes[192] = {0};
    char iconTypes[192] = {0};
    char descriptorTypes[192] = {0};
    char iconGetterTypes[192] = {0};
    char descriptorGetterTypes[192] = {0};
    char recordTypes[192] = {0};
    bool abiReady = r_is_objc_ptr(alloc) && iconConcrete &&
        r_responds_main(alloc, "init") &&
        themer_iconservices_lab_method_types(
            alloc, "init", initTypes, sizeof(initTypes)) &&
        strcmp(initTypes, "@16@0:8") == 0 &&
        r_responds_main(alloc, "setIcon:") &&
        themer_iconservices_lab_method_types(
            alloc, "setIcon:", iconTypes, sizeof(iconTypes)) &&
        strcmp(iconTypes, "v24@0:8@16") == 0 &&
        r_responds_main(alloc, "setImageDescriptor:") &&
        themer_iconservices_lab_method_types(
            alloc, "setImageDescriptor:", descriptorTypes,
            sizeof(descriptorTypes)) &&
        strcmp(descriptorTypes, "v24@0:8@16") == 0 &&
        r_responds_main(alloc, "icon") &&
        themer_iconservices_lab_method_types(
            alloc, "icon", iconGetterTypes, sizeof(iconGetterTypes)) &&
        strcmp(iconGetterTypes, "@16@0:8") == 0 &&
        r_responds_main(alloc, "imageDescriptor") &&
        themer_iconservices_lab_method_types(
            alloc, "imageDescriptor", descriptorGetterTypes,
            sizeof(descriptorGetterTypes)) &&
        strcmp(descriptorGetterTypes, "@16@0:8") == 0 &&
        r_responds_main(alloc, "generateImageReturningRecordIdentifiers:") &&
        themer_iconservices_lab_method_types(
            alloc, "generateImageReturningRecordIdentifiers:", recordTypes,
            sizeof(recordTypes)) &&
        strcmp(recordTypes, "@24@0:8^@16") == 0;
    char iconClass[96] = {0};
    themer_read_class_name(icon, iconClass, sizeof(iconClass));
    printf("[ICONSERVICES_LAB] generation-request preflight icon=0x%llx/%s "
           "concreteClass=0x%llx iconConcrete=%d requestClass=0x%llx "
           "alloc=0x%llx init=\"%s\" setIcon=\"%s\" "
           "setDescriptor=\"%s\" iconGetter=\"%s\" "
           "descriptorGetter=\"%s\" recordIdentifiers=\"%s\" "
           "abiReady=%d\n",
           (unsigned long long)icon,
           iconClass[0] ? iconClass : "-",
           (unsigned long long)concreteIconClass,
           iconConcrete,
           (unsigned long long)requestClass,
           (unsigned long long)alloc,
           initTypes,
           iconTypes,
           descriptorTypes,
           iconGetterTypes,
           descriptorGetterTypes,
           recordTypes,
           abiReady);
    if (!abiReady) {
        if (r_is_objc_ptr(alloc) && remote_call_current_success()) {
            r_msg2(alloc, "release", 0, 0, 0, 0);
        }
        return 0;
    }
    uint64_t request = r_msg2_main(alloc, "init", 0, 0, 0, 0);
    if (!r_is_objc_ptr(request) || !remote_call_current_success()) return 0;
    r_msg2_main(request, "setIcon:", icon, 0, 0, 0);
    r_msg2_main(request, "setImageDescriptor:", descriptor, 0, 0, 0);
    bool inputsMatch = remote_call_current_success() &&
        r_responds_main(request, "icon") &&
        r_msg2_main(request, "icon", 0, 0, 0, 0) == icon &&
        r_responds_main(request, "imageDescriptor") &&
        r_msg2_main(request, "imageDescriptor", 0, 0, 0, 0) == descriptor;
    bool generationInvoked = false;
    bool dispatchPossible = false;
    uint64_t result = 0;
    ThemerIconServicesLabRecordIdentifiersObservation localObservation = {0};
    ThemerIconServicesLabRecordIdentifiersObservation *observation =
        recordIdentifiersOut ? recordIdentifiersOut : &localObservation;
    RMainPreparedOutObjectCapture prepared = {0};
    if (inputsMatch && remote_call_current_success()) {
        result = r_msg2_main_prepared_out_object_batch(
            request, "generateImageReturningRecordIdentifiers:",
            "@24@0:8^@16",
            (RMainDispatchMarker)dispatchMarker,
            dispatchMarkerContext, &prepared);
        observation->generationInvocation = prepared.generationInvocation;
        observation->holderInvocation = prepared.holderInvocation;
        observation->directHolderInvocation =
            prepared.directHolderInvocation;
        observation->outSlot = prepared.outSlot;
        observation->directSlot = prepared.directSlot;
        observation->directRaw = prepared.directRaw;
        observation->raw = prepared.raw;
        observation->exactABI = prepared.exactABI;
        observation->dispatchPossible = prepared.dispatchPossible;
        observation->generationInvoked = prepared.generationInvoked;
        observation->observed = prepared.observed;
        observation->binderInvoked = prepared.binderInvoked;
        observation->retainerInvoked = prepared.retainerInvoked;
        observation->holderArgumentMatches = prepared.holderArgumentMatches;
        observation->argumentsRetained = prepared.argumentsRetained;
        observation->directArgumentMatches =
            prepared.directArgumentMatches;
        observation->directArgumentsRetained =
            prepared.directArgumentsRetained;
        observation->transportClean = prepared.transportClean;
        observation->ownerBoundPostDispatch = !dispatchMarker ||
            (dispatchMarkerContext &&
             remote_call_current_pid() ==
                 ((ThemerStock68GenerationDispatchContext *)
                      dispatchMarkerContext)->pid &&
             remote_call_current_proc() ==
                 ((ThemerStock68GenerationDispatchContext *)
                      dispatchMarkerContext)->proc &&
             remote_call_current_task() ==
                 ((ThemerStock68GenerationDispatchContext *)
                      dispatchMarkerContext)->task);
        bool ownershipVerified = observation->observed &&
            observation->holderArgumentMatches &&
            observation->argumentsRetained && observation->transportClean &&
            observation->ownerBoundPostDispatch;
        if (ownershipVerified) {
            // The decoder is observation-only. Its class metadata and checked
            // Foundation reads can never certify a V2 identity or clear a
            // recovery marker.
            observation->decodeStatus =
                themer_iconservices_lab_decode_record_identifiers(
                    observation->raw, &observation->decodeNodes,
                    &observation->decodeMetadata, &observation->firstBlob);
        }
        generationInvoked = prepared.generationInvoked;
        dispatchPossible = prepared.dispatchPossible;
    }
    if (dispatchPossibleOut) *dispatchPossibleOut = dispatchPossible;
    if (generationInvokedOut) *generationInvokedOut = generationInvoked;
    const char *captureMode = remote_call_uses_lab_backend()
        ? "record-identifiers-lab-worker-direct-owned"
        : "record-identifiers-main-thread-batch";
    printf("[ICONSERVICES_LAB] record-identifiers-object "
           "capturePhase=%s generationInvocation=0x%llx "
           "holderInvocation=0x%llx directRaw=0x%llx "
           "directHolderInvocation=0x%llx directSlot=0x%llx "
           "raw=0x%llx observed=%d binderInvoked=%d retainerInvoked=%d "
           "holderArgumentMatches=%d argumentsRetained=%d exactABI=%d "
           "directArgumentMatches=%d directArgumentsRetained=%d "
           "ownerBoundPostDispatch=%d "
           "transportClean=%d decodeStatus=%d decodeNodes=%d "
           "decodeMetadata=%d\n",
           captureMode,
           (unsigned long long)observation->generationInvocation,
           (unsigned long long)observation->holderInvocation,
           (unsigned long long)observation->directRaw,
           (unsigned long long)observation->directHolderInvocation,
           (unsigned long long)observation->directSlot,
           (unsigned long long)observation->raw,
           observation->observed,
           observation->binderInvoked,
           observation->retainerInvoked,
           observation->holderArgumentMatches,
           observation->argumentsRetained,
           observation->exactABI,
           observation->directArgumentMatches,
           observation->directArgumentsRetained,
           observation->ownerBoundPostDispatch,
           observation->transportClean,
           observation->decodeStatus,
           observation->decodeNodes,
           observation->decodeMetadata);
    printf("[ICONSERVICES_LAB] generation-request invoke "
           "mode=%s request=0x%llx descriptor=0x%llx "
           "inputsMatch=%d slot=0x%llx zeroed=%d result=0x%llx "
           "recordIdentifiersRaw=0x%llx observed=%d\n",
           captureMode,
           (unsigned long long)request,
           (unsigned long long)descriptor,
           inputsMatch,
           (unsigned long long)observation->outSlot,
           observation->outSlot != 0,
           (unsigned long long)result,
           (unsigned long long)observation->raw,
           observation->observed);
    if (r_is_objc_ptr(request) && remote_call_current_success()) {
        r_msg2(request, "release", 0, 0, 0, 0);
    }
    if (abiReadyOut) {
        *abiReadyOut = abiReady && inputsMatch && observation->exactABI &&
            observation->observed && observation->holderArgumentMatches &&
            observation->argumentsRetained &&
            observation->directArgumentMatches &&
            observation->directArgumentsRetained &&
            observation->ownerBoundPostDispatch;
    }
    return remote_call_current_success() && r_is_objc_ptr(result) ? result : 0;
}

static bool themer_iconservices_lab_generation_probe(
    const ThemerIconServicesLabDiscovery *d,
    bool *controlReadyOut)
{
    if (controlReadyOut) *controlReadyOut = false;
    if (!d || !r_is_objc_ptr(d->canonicalIcon) ||
        !r_is_objc_ptr(d->canonicalCache) || !r_is_objc_ptr(d->descriptor) ||
        !d->prePrepareBagsCopyKnown ||
        !r_is_objc_ptr(d->prePrepareBagsCopy) ||
        !r_responds_main(d->canonicalCache, "setImageBagsByDescriptor:") ||
        !remote_call_current_success()) {
        return false;
    }
    uint64_t ioFailuresBefore = remote_call_current_io_failure_count();
    uint64_t latestBefore = themer_iconservices_lab_retained_getter(
        d->canonicalCache, "latestValidationToken");
    ThemerIconServicesLabDataCapture latestBeforeCapture = {0};
    bool latestBeforeCaptured = r_is_objc_ptr(latestBefore) &&
        themer_iconservices_lab_capture_nsdata(
            latestBefore, THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP,
            &latestBeforeCapture);
    ThemerIconServicesLabTopologySnapshot before = {0};
    bool beforeCaptured = themer_iconservices_lab_capture_topology(
        d->canonicalCache, "before-generation", &before);

    bool latestBeforeReady = latestBeforeCaptured &&
        !latestBeforeCapture.truncated &&
        latestBeforeCapture.objectLength > 0;
    bool controlABI = false;
    ThemerIconServicesLabRecordIdentifiersObservation recordIdentifiers = {0};
    bool generationInvoked = false;
    uint64_t controlResult = beforeCaptured && latestBeforeReady
        ? themer_iconservices_lab_generation_request(
            d->canonicalIcon, d->descriptor, &controlABI,
            &recordIdentifiers, &generationInvoked, NULL, NULL, NULL)
        : 0;
    r_msg2_main(d->canonicalCache, "setImageBagsByDescriptor:",
                d->prePrepareBagsCopy, 0, 0, 0);
    bool controlRestored = remote_call_current_success() &&
        themer_iconservices_lab_dictionary_restored(
            d->canonicalCache, d->prePrepareBagsCopy,
            d->prePrepareBagsCount);

    ThemerIconServicesLabGenerationSample control = {0};
    bool controlCaptured = controlRestored && r_is_objc_ptr(controlResult) &&
        themer_iconservices_lab_capture_generation_sample(
            "stock40-control", controlResult,
            d->descSizeW, d->descSizeH, d->descScale, &control);
    if (!controlCaptured && r_is_objc_ptr(controlResult)) {
        control.result = controlResult;
    }
    bool controlReady = controlCaptured && control.coherent && controlABI &&
        recordIdentifiers.exactABI && recordIdentifiers.observed &&
        recordIdentifiers.holderArgumentMatches &&
        recordIdentifiers.argumentsRetained &&
        recordIdentifiers.directArgumentMatches &&
        recordIdentifiers.directArgumentsRetained && controlRestored;

    uint64_t latestAfter = themer_iconservices_lab_retained_getter(
        d->canonicalCache, "latestValidationToken");
    ThemerIconServicesLabDataCapture latestAfterCapture = {0};
    bool latestAfterCaptured = r_is_objc_ptr(latestAfter) &&
        themer_iconservices_lab_capture_nsdata(
            latestAfter, THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP,
            &latestAfterCapture);
    bool latestKnown = latestBeforeCaptured && latestAfterCaptured &&
        !latestBeforeCapture.truncated && !latestAfterCapture.truncated;
    bool latestEqual = latestKnown &&
        latestBeforeCapture.objectLength == latestAfterCapture.objectLength &&
        (latestBeforeCapture.objectLength == 0 ||
         memcmp(latestBeforeCapture.bytes, latestAfterCapture.bytes,
                latestBeforeCapture.objectLength) == 0);
    bool latestMatchesControl = latestAfterCaptured &&
        control.tokenCaptured && !latestAfterCapture.truncated &&
        !control.tokenCapture.truncated &&
        latestAfterCapture.objectLength == control.tokenCapture.objectLength &&
        (latestAfterCapture.objectLength == 0 ||
         memcmp(latestAfterCapture.bytes, control.tokenCapture.bytes,
                latestAfterCapture.objectLength) == 0);
    bool latestTokenDrift = latestKnown && !latestEqual;
    bool generationReturned = r_is_objc_ptr(controlResult);
    bool possiblePersistentSideEffect = generationInvoked || latestTokenDrift;

    ThemerIconServicesLabTopologySnapshot after = {0};
    bool afterCaptured = themer_iconservices_lab_capture_topology(
        d->canonicalCache, "after-generation", &after);
    if (beforeCaptured && afterCaptured) {
        themer_iconservices_lab_log_topology_delta(
            "before-generation", &before, "after-generation", &after);
    }
    r_msg2_main(d->canonicalCache, "setImageBagsByDescriptor:",
                d->prePrepareBagsCopy, 0, 0, 0);
    bool restored = remote_call_current_success() &&
        themer_iconservices_lab_dictionary_restored(
            d->canonicalCache, d->prePrepareBagsCopy,
            d->prePrepareBagsCount);
    uint64_t ioFailuresAfter = remote_call_current_io_failure_count();
    printf("[ICONSERVICES_LAB] generation-summary "
           "mode=stock40-record-identifiers-main-thread-batch controlABI=%d "
           "generationImageDirect=%d "
           "recordIdentifiersRaw=0x%llx recordIdentifiersObserved=%d "
           "recordIdentifiersHolderArgumentMatches=%d "
           "recordIdentifiersArgumentsRetained=%d "
           "recordIdentifiersExactABI=%d "
           "controlCaptured=%d controlRestored=%d controlReady=%d "
           "latestBefore=%zu/%d latestAfter=%zu/%d "
           "latestKnown=%d latestEqual=%d latestTokenDrift=%d "
           "latestMatchesControl=%d generationInvoked=%d "
           "generationReturned=%d possiblePersistentSideEffect=%d "
           "topology=%d/%d dictionaryRestored=%d cleanRestoreProven=%d "
           "ioFailures=%llu->%llu transportClean=%d\n",
           controlABI,
           recordIdentifiers.directRaw != 0,
           (unsigned long long)recordIdentifiers.raw,
           recordIdentifiers.observed,
           recordIdentifiers.holderArgumentMatches,
           recordIdentifiers.argumentsRetained,
           recordIdentifiers.exactABI,
           controlCaptured,
           controlRestored,
           controlReady,
           latestBeforeCapture.objectLength,
           latestBeforeCaptured,
           latestAfterCapture.objectLength,
           latestAfterCaptured,
           latestKnown,
           latestEqual,
           latestTokenDrift,
           latestMatchesControl,
           generationInvoked,
           generationReturned,
           possiblePersistentSideEffect,
           beforeCaptured,
           afterCaptured,
           restored,
           restored && !possiblePersistentSideEffect,
           (unsigned long long)ioFailuresBefore,
           (unsigned long long)ioFailuresAfter,
           ioFailuresAfter == ioFailuresBefore);

    if (r_is_objc_ptr(latestAfter) && remote_call_current_success()) {
        r_msg2(latestAfter, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(latestBefore) && remote_call_current_success()) {
        r_msg2(latestBefore, "release", 0, 0, 0, 0);
    }
    themer_iconservices_lab_release_generation_sample(&control);
    themer_iconservices_lab_free_data_capture(&latestAfterCapture);
    themer_iconservices_lab_free_data_capture(&latestBeforeCapture);

    // The generation and holder invocations plus their out slot remain alive
    // for this target process. They are the ownership certificate for the
    // returned out object and are reclaimed with the process.
    bool invocationDeferred =
        r_is_objc_ptr(recordIdentifiers.generationInvocation) &&
        r_is_objc_ptr(recordIdentifiers.holderInvocation);
    bool outSlotDeferred = recordIdentifiers.outSlot != 0;
    printf("[ICONSERVICES_LAB] generation-invocation-cleanup "
           "invocation=0x%llx processLifetimeDeferred=%d outSlot=0x%llx "
           "outSlotProcessLifetimeDeferred=%d transport=%d\n",
           (unsigned long long)recordIdentifiers.generationInvocation,
           invocationDeferred,
           (unsigned long long)recordIdentifiers.outSlot,
           outSlotDeferred,
           remote_call_current_success());

    if (controlReadyOut) *controlReadyOut = controlReady;
    return restored && remote_call_current_success();
}

typedef struct {
    uint64_t manager;
    uint64_t managerCache;
    uint64_t localIcon;
    uint64_t canonicalIcon;
    uint64_t canonicalCache;
    uint64_t namedDescriptor;
    double namedScale;
    char managerCachePath[240];
    char namedDigest[160];
} ThemerStock68MaterializationContext;

static void themer_stock68_release_context(
    ThemerStock68MaterializationContext *context)
{
    if (!context) return;
    if (r_is_objc_ptr(context->namedDescriptor) &&
        remote_call_current_success()) {
        r_msg2(context->namedDescriptor, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(context->localIcon) && remote_call_current_success()) {
        r_msg2(context->localIcon, "release", 0, 0, 0, 0);
    }
    memset(context, 0, sizeof(*context));
}

static bool themer_stock68_acquire_context(
    const char *targetBundle,
    ThemerStock68MaterializationContext *context)
{
    if (!targetBundle || !targetBundle[0] || !context ||
        !remote_call_current_success()) {
        return false;
    }
    memset(context, 0, sizeof(*context));
    if (!themer_ensure_iconservices_loaded()) return false;
    uint64_t managerClass = themer_lookup_class("ISIconManager");
    context->manager = r_is_objc_ptr(managerClass) &&
        r_responds_main(managerClass, "sharedInstance")
        ? r_msg2_main(managerClass, "sharedInstance", 0, 0, 0, 0) : 0;
    context->managerCache = r_is_objc_ptr(context->manager) &&
        r_responds_main(context->manager, "iconCache")
        ? r_msg2_main(context->manager, "iconCache", 0, 0, 0, 0) : 0;
    uint64_t cachePath = r_is_objc_ptr(context->managerCache) &&
        r_responds_main(context->managerCache, "cachePath")
        ? r_msg2_main(context->managerCache, "cachePath", 0, 0, 0, 0) : 0;
    bool pathKnown = r_is_objc_ptr(cachePath) &&
        r_read_nsstring(cachePath, context->managerCachePath,
                        sizeof(context->managerCachePath));
    context->localIcon = themer_iconservices_lab_make_bundle_icon(targetBundle);
    context->canonicalIcon = r_is_objc_ptr(context->manager) &&
        r_is_objc_ptr(context->localIcon) &&
        r_responds_main(context->manager, "findOrRegisterIcon:")
        ? r_msg2_main(context->manager, "findOrRegisterIcon:",
                      context->localIcon, 0, 0, 0) : 0;
    context->canonicalCache = r_is_objc_ptr(context->canonicalIcon) &&
        r_responds_main(context->canonicalIcon, "imageCache")
        ? r_msg2_main(context->canonicalIcon, "imageCache", 0, 0, 0, 0) : 0;
    context->namedDescriptor =
        themer_iconservices_lab_named_spotlight_descriptor(NULL, NULL, NULL);
    char scaleTypes[192] = {0};
    bool scaleABI = r_is_objc_ptr(context->namedDescriptor) &&
        themer_iconservices_lab_method_types(
            context->namedDescriptor, "scale", scaleTypes,
            sizeof(scaleTypes)) &&
        strcmp(scaleTypes, "d16@0:8") == 0;
    bool scaleKnown = false;
    context->namedScale = scaleABI
        ? themer_read_remote_double_property(
            context->namedDescriptor, "scale", 0.0, &scaleKnown)
        : 0.0;
    bool digestKnown =
        themer_iconservices_lab_descriptor_digest_text(
            context->namedDescriptor, context->namedDigest,
            sizeof(context->namedDigest));
    bool ready = remote_call_current_success() && pathKnown &&
        r_is_objc_ptr(context->manager) &&
        r_is_objc_ptr(context->managerCache) &&
        r_is_objc_ptr(context->canonicalIcon) &&
        r_is_objc_ptr(context->canonicalCache) &&
        r_is_objc_ptr(context->namedDescriptor) &&
        scaleABI && scaleKnown && context->namedScale >= 1.0 &&
        context->namedScale <= 4.0 && digestKnown;
    printf("[ICONSERVICES_MATERIALIZE] context target=%s manager=0x%llx "
           "cache=0x%llx icon=0x%llx imageCache=0x%llx "
           "named=0x%llx scaleABI=\"%s\" scale=%.2f digest=\"%s\" "
           "path=\"%s\" ready=%d\n",
           targetBundle,
           (unsigned long long)context->manager,
           (unsigned long long)context->managerCache,
           (unsigned long long)context->canonicalIcon,
           (unsigned long long)context->canonicalCache,
           (unsigned long long)context->namedDescriptor,
           scaleTypes,
           context->namedScale,
           context->namedDigest,
           pathKnown ? context->managerCachePath : "-",
           ready);
    return ready;
}

static uint64_t themer_stock68_make_generation_descriptor(
    double scale,
    char *digestOut,
    size_t digestOutLen,
    bool *abiReadyOut)
{
    if (digestOut && digestOutLen) digestOut[0] = '\0';
    if (abiReadyOut) *abiReadyOut = false;
    uint64_t descriptorClass = themer_lookup_class("ISImageDescriptor");
    uint64_t alloc = r_is_objc_ptr(descriptorClass)
        ? r_msg2(descriptorClass, "alloc", 0, 0, 0, 0) : 0;
    char initTypes[192] = {0};
    char setSizeTypes[192] = {0};
    char sizeTypes[192] = {0};
    char scaleTypes[192] = {0};
    char digestTypes[192] = {0};
    bool abiReady = r_is_objc_ptr(alloc) &&
        themer_iconservices_lab_method_types(
            alloc, "initWithSize:scale:", initTypes, sizeof(initTypes)) &&
        strcmp(initTypes, "@40@0:8{CGSize=dd}16d32") == 0 &&
        themer_iconservices_lab_method_types(
            alloc, "setSize:", setSizeTypes, sizeof(setSizeTypes)) &&
        strcmp(setSizeTypes, "v32@0:8{CGSize=dd}16") == 0 &&
        themer_iconservices_lab_method_types(
            alloc, "size", sizeTypes, sizeof(sizeTypes)) &&
        strcmp(sizeTypes, "{CGSize=dd}16@0:8") == 0 &&
        themer_iconservices_lab_method_types(
            alloc, "scale", scaleTypes, sizeof(scaleTypes)) &&
        strcmp(scaleTypes, "d16@0:8") == 0 &&
        themer_iconservices_lab_method_types(
            alloc, "digest", digestTypes, sizeof(digestTypes)) &&
        strcmp(digestTypes, "@16@0:8") == 0;
    struct { double width; double height; } size = {68.0, 68.0};
    uint64_t descriptor = abiReady
        ? r_msg2_main_raw(
            alloc, "initWithSize:scale:",
            &size, sizeof(size), &scale, sizeof(scale),
            NULL, 0, NULL, 0)
        : 0;
    if (r_is_objc_ptr(descriptor) && remote_call_current_success()) {
        r_msg2_main_raw(descriptor, "setSize:",
                        &size, sizeof(size),
                        NULL, 0, NULL, 0, NULL, 0);
    } else if (r_is_objc_ptr(alloc) && !abiReady &&
               remote_call_current_success()) {
        r_msg2(alloc, "release", 0, 0, 0, 0);
    }
    double readWidth = 0.0, readHeight = 0.0;
    bool sizeKnown = r_is_objc_ptr(descriptor) &&
        themer_iconservices_lab_read_size_property(
            descriptor, "size", &readWidth, &readHeight);
    bool scaleKnown = false;
    double readScale = r_is_objc_ptr(descriptor)
        ? themer_read_remote_double_property(
            descriptor, "scale", 0.0, &scaleKnown)
        : 0.0;
    bool digestKnown = r_is_objc_ptr(descriptor) && digestOut &&
        themer_iconservices_lab_descriptor_digest_text(
            descriptor, digestOut, digestOutLen);
    double scaleDelta = readScale - scale;
    if (scaleDelta < 0.0) scaleDelta = -scaleDelta;
    bool geometry = sizeKnown && scaleKnown &&
        themer_iconservices_lab_sizes_match(
            readWidth, readHeight, 68.0, 68.0) && scaleDelta < 0.01;
    bool ready = abiReady && geometry && digestKnown &&
        remote_call_current_success();
    printf("[ICONSERVICES_MATERIALIZE] descriptor-abi "
           "init=\"%s\" setSize=\"%s\" size=\"%s\" "
           "scale=\"%s\" digest=\"%s\" descriptor=0x%llx "
           "readback=%.1fx%.1f@%.2f digestText=\"%s\" ready=%d\n",
           initTypes, setSizeTypes, sizeTypes, scaleTypes, digestTypes,
           (unsigned long long)descriptor,
           readWidth, readHeight, readScale,
           digestKnown ? digestOut : "-",
           ready);
    if (!ready && r_is_objc_ptr(descriptor) &&
        remote_call_current_success()) {
        r_msg2(descriptor, "release", 0, 0, 0, 0);
        descriptor = 0;
    }
    if (abiReadyOut) *abiReadyOut = ready;
    return descriptor;
}

static bool themer_stock68_snapshot_entry_equal(
    const ThemerIconServicesLabSnapshotEntry *first,
    const ThemerIconServicesLabSnapshotEntry *second)
{
    if (!first || !second || first->image != second->image ||
        first->geometryKnown != second->geometryKnown) {
        return false;
    }
    if (!first->geometryKnown) return true;
    double dw = first->width - second->width;
    double dh = first->height - second->height;
    double ds = first->scale - second->scale;
    if (dw < 0.0) dw = -dw;
    if (dh < 0.0) dh = -dh;
    if (ds < 0.0) ds = -ds;
    return dw < 0.01 && dh < 0.01 && ds < 0.01;
}

static bool themer_stock68_key_contains_entry(
    const ThemerIconServicesLabSnapshotKey *key,
    const ThemerIconServicesLabSnapshotEntry *entry)
{
    if (!key || !entry) return false;
    for (int i = 0; i < key->entryCount; i++) {
        if (themer_stock68_snapshot_entry_equal(&key->entries[i], entry)) {
            return true;
        }
    }
    return false;
}

static bool themer_stock68_keys_equal(
    const ThemerIconServicesLabSnapshotKey *first,
    const ThemerIconServicesLabSnapshotKey *second)
{
    if (!first || !second || first->bag != second->bag ||
        first->entryCount != second->entryCount ||
        first->entriesTruncated != second->entriesTruncated) {
        return false;
    }
    for (int i = 0; i < first->entryCount; i++) {
        if (!themer_stock68_key_contains_entry(second, &first->entries[i])) {
            return false;
        }
    }
    return true;
}

static bool themer_stock68_topologies_equal(
    const ThemerIconServicesLabTopologySnapshot *first,
    const ThemerIconServicesLabTopologySnapshot *second)
{
    if (!first || !second || first->captured != second->captured ||
        first->dictionaryCount != second->dictionaryCount ||
        first->keyCount != second->keyCount ||
        first->keysTruncated != second->keysTruncated) {
        return false;
    }
    for (int i = 0; i < first->keyCount; i++) {
        const ThemerIconServicesLabSnapshotKey *other =
            themer_iconservices_lab_snapshot_find_key(second, &first->keys[i]);
        if (!themer_stock68_keys_equal(&first->keys[i], other)) return false;
    }
    return true;
}

static bool themer_stock68_entry_is_68(
    const ThemerIconServicesLabSnapshotEntry *entry,
    double scale)
{
    if (!entry || !entry->geometryKnown) return false;
    double ds = entry->scale - scale;
    if (ds < 0.0) ds = -ds;
    return themer_iconservices_lab_sizes_match(
        entry->width, entry->height, 68.0, 68.0) && ds < 0.01;
}

static int themer_stock68_count_new_68(
    const ThemerIconServicesLabSnapshotKey *before,
    const ThemerIconServicesLabSnapshotKey *after,
    double scale,
    const ThemerIconServicesLabSnapshotEntry **uniqueOut)
{
    if (uniqueOut) *uniqueOut = NULL;
    if (!after) return 0;
    int count = 0;
    for (int i = 0; i < after->entryCount; i++) {
        const ThemerIconServicesLabSnapshotEntry *entry = &after->entries[i];
        if (!themer_stock68_entry_is_68(entry, scale) ||
            (before && themer_stock68_key_contains_entry(before, entry))) {
            continue;
        }
        count++;
        if (uniqueOut) *uniqueOut = entry;
    }
    return count;
}

static bool themer_stock68_baseline_entries_preserved(
    const ThemerIconServicesLabSnapshotKey *before,
    const ThemerIconServicesLabSnapshotKey *after)
{
    if (!before) return true;
    if (!after || before->entriesTruncated || after->entriesTruncated) {
        return false;
    }
    for (int i = 0; i < before->entryCount; i++) {
        if (!themer_stock68_key_contains_entry(after, &before->entries[i])) {
            return false;
        }
    }
    return true;
}

static int themer_stock68_count_wrong_key_new_68(
    const ThemerIconServicesLabTopologySnapshot *before,
    const ThemerIconServicesLabTopologySnapshot *after,
    const char *namedDigest,
    double scale)
{
    if (!before || !after || !namedDigest) return 0;
    int count = 0;
    for (int i = 0; i < after->keyCount; i++) {
        const ThemerIconServicesLabSnapshotKey *key = &after->keys[i];
        if (strcmp(key->keyText, namedDigest) == 0) continue;
        const ThemerIconServicesLabSnapshotKey *old =
            themer_iconservices_lab_snapshot_find_key(before, key);
        count += themer_stock68_count_new_68(old, key, scale, NULL);
    }
    return count;
}

static bool themer_stock68_other_keys_unchanged(
    const ThemerIconServicesLabTopologySnapshot *before,
    const ThemerIconServicesLabTopologySnapshot *after,
    const char *namedDigest)
{
    if (!before || !after || !namedDigest) return false;
    for (int i = 0; i < before->keyCount; i++) {
        const ThemerIconServicesLabSnapshotKey *key = &before->keys[i];
        if (strcmp(key->keyText, namedDigest) == 0) continue;
        const ThemerIconServicesLabSnapshotKey *other =
            themer_iconservices_lab_snapshot_find_key(after, key);
        if (!themer_stock68_keys_equal(key, other)) return false;
    }
    for (int i = 0; i < after->keyCount; i++) {
        const ThemerIconServicesLabSnapshotKey *key = &after->keys[i];
        if (strcmp(key->keyText, namedDigest) == 0) continue;
        if (!themer_iconservices_lab_snapshot_find_key(before, key)) return false;
    }
    return true;
}

static void themer_stock68_clear_v2_identity(void)
{
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    NSArray<NSString *> *keys = @[
        THEMER_STOCK68_V2_UUID_KEY, THEMER_STOCK68_V2_TOKEN_KEY,
        THEMER_STOCK68_V2_PID_KEY, THEMER_STOCK68_V2_PATH_KEY,
        THEMER_STOCK68_V2_BUNDLE_KEY, THEMER_STOCK68_V2_FINGERPRINT_KEY,
        THEMER_STOCK68_V2_DIGEST_KEY, THEMER_STOCK68_V2_FILE_SIZE_KEY,
    ];
    for (NSString *key in keys) [defaults removeObjectForKey:key];
    (void)[defaults synchronize];
}

static bool themer_stock68_validate_identity(
    uint64_t image,
    const char *targetBundle,
    const char *themeFingerprint,
    const char *namedDigest,
    const char *managerCachePath,
    double scale,
    bool persist,
    ThemerSpotlightStock68MaterializationReport *report)
{
    char imageClass[96] = {0};
    themer_read_class_name(image, imageClass, sizeof(imageClass));
    if (strcmp(imageClass, "IFCacheImage") != 0) return false;
    uint64_t uuid = themer_iconservices_lab_retained_getter(image, "uuid");
    uint64_t token = themer_iconservices_lab_retained_getter(
        image, "validationToken");
    uint64_t uuidString = r_is_objc_ptr(uuid)
        ? themer_iconservices_lab_retained_getter(uuid, "UUIDString") : 0;
    char uuidText[80] = {0};
    bool uuidKnown = r_is_objc_ptr(uuidString) &&
        r_read_nsstring(uuidString, uuidText, sizeof(uuidText));
    uint8_t uuidBytes[16] = {0};
    bool uuidFormat = uuidKnown &&
        themer_iconservices_lab_parse_uuid_text(uuidText, uuidBytes);
    uuidKnown = uuidKnown && uuidFormat;
    ThemerIconServicesLabDataCapture tokenCapture = {0};
    bool tokenKnown = r_is_objc_ptr(token) &&
        themer_iconservices_lab_capture_nsdata(
            token, THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP,
            &tokenCapture) && !tokenCapture.truncated &&
        tokenCapture.objectLength > 0;
    NSString *store = managerCachePath && managerCachePath[0]
        ? [NSString stringWithUTF8String:managerCachePath] : nil;
    NSString *fileName = uuidKnown
        ? [NSString stringWithFormat:@"%s.isdata", uuidText] : nil;
    NSString *path = fileName.length > 0
        ? [store stringByAppendingPathComponent:fileName] : nil;
    NSData *fileData = path.length > 0
        ? themer_iconservices_lab_read_local_file(path) : nil;
    uint64_t remoteData = fileData.length > 0
        ? themer_make_remote_nsdata(fileData) : 0;
    uint64_t reconstructed = r_is_objc_ptr(remoteData) &&
        r_is_objc_ptr(uuid) && r_is_objc_ptr(token)
        ? themer_iconservices_lab_make_if_cache_image(remoteData, uuid, token)
        : 0;
    char reconstructedClass[96] = {0};
    themer_read_class_name(reconstructed, reconstructedClass,
                           sizeof(reconstructedClass));
    bool reconstructedIdentity =
        strcmp(reconstructedClass, "IFCacheImage") == 0;
    bool reconstruction = reconstructedIdentity &&
        themer_iconservices_lab_image_geometry_matches(
            reconstructed, 68.0, 68.0, scale);
    bool identityReady = uuidKnown && tokenKnown && fileData.length > 0 &&
        reconstruction && remote_call_current_success();
    NSData *tokenData = tokenKnown
        ? [NSData dataWithBytes:tokenCapture.bytes
                         length:tokenCapture.objectLength] : nil;
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    NSString *targetValue = targetBundle
        ? [NSString stringWithUTF8String:targetBundle] : nil;
    NSString *fingerprintValue = themeFingerprint
        ? [NSString stringWithUTF8String:themeFingerprint] : nil;
    NSString *digestValue = namedDigest
        ? [NSString stringWithUTF8String:namedDigest] : nil;
    NSNumber *fileSizeValue = @((uint64_t)fileData.length);
    bool bindingMatches = identityReady;
    if (!persist && identityReady) {
        bindingMatches =
            [[defaults stringForKey:THEMER_STOCK68_V2_UUID_KEY]
                isEqualToString:[NSString stringWithUTF8String:uuidText]] &&
            [[defaults dataForKey:THEMER_STOCK68_V2_TOKEN_KEY]
                isEqualToData:tokenData] &&
            [defaults integerForKey:THEMER_STOCK68_V2_PID_KEY] ==
                remote_call_current_pid() &&
            [[defaults stringForKey:THEMER_STOCK68_V2_PATH_KEY]
                isEqualToString:path] &&
            [[defaults stringForKey:THEMER_STOCK68_V2_BUNDLE_KEY]
                isEqualToString:targetValue] &&
            [[defaults stringForKey:THEMER_STOCK68_V2_FINGERPRINT_KEY]
                isEqualToString:fingerprintValue] &&
            [[defaults stringForKey:THEMER_STOCK68_V2_DIGEST_KEY]
                isEqualToString:digestValue] &&
            [[defaults objectForKey:THEMER_STOCK68_V2_FILE_SIZE_KEY]
                isEqual:fileSizeValue];
    }
    if (persist && identityReady) {
        themer_stock68_clear_v2_identity();
        [defaults setObject:[NSString stringWithUTF8String:uuidText]
                     forKey:THEMER_STOCK68_V2_UUID_KEY];
        [defaults setObject:tokenData forKey:THEMER_STOCK68_V2_TOKEN_KEY];
        [defaults setInteger:remote_call_current_pid()
                      forKey:THEMER_STOCK68_V2_PID_KEY];
        [defaults setObject:path forKey:THEMER_STOCK68_V2_PATH_KEY];
        [defaults setObject:targetValue forKey:THEMER_STOCK68_V2_BUNDLE_KEY];
        [defaults setObject:fingerprintValue
                     forKey:THEMER_STOCK68_V2_FINGERPRINT_KEY];
        [defaults setObject:digestValue
                     forKey:THEMER_STOCK68_V2_DIGEST_KEY];
        [defaults setObject:fileSizeValue
                     forKey:THEMER_STOCK68_V2_FILE_SIZE_KEY];
        (void)[defaults synchronize];
        bindingMatches =
            [[defaults stringForKey:THEMER_STOCK68_V2_UUID_KEY]
                isEqualToString:[NSString stringWithUTF8String:uuidText]] &&
            [[defaults dataForKey:THEMER_STOCK68_V2_TOKEN_KEY]
                isEqualToData:tokenData] &&
            [[defaults objectForKey:THEMER_STOCK68_V2_PID_KEY]
                isEqual:@(remote_call_current_pid())] &&
            [[defaults stringForKey:THEMER_STOCK68_V2_PATH_KEY]
                isEqualToString:path] &&
            [[defaults stringForKey:THEMER_STOCK68_V2_BUNDLE_KEY]
                isEqualToString:targetValue] &&
            [[defaults stringForKey:THEMER_STOCK68_V2_FINGERPRINT_KEY]
                isEqualToString:fingerprintValue] &&
            [[defaults stringForKey:THEMER_STOCK68_V2_DIGEST_KEY]
                isEqualToString:digestValue] &&
            [[defaults objectForKey:THEMER_STOCK68_V2_FILE_SIZE_KEY]
                isEqual:fileSizeValue];
        if (!bindingMatches) themer_stock68_clear_v2_identity();
    }
    if (report) {
        snprintf(report->uuid, sizeof(report->uuid), "%s",
                 uuidKnown ? uuidText : "");
        snprintf(report->storePath, sizeof(report->storePath), "%s",
                 path.UTF8String ?: "");
        report->fileSize = fileData.length;
        report->uuidValid = uuidKnown;
        report->tokenValid = tokenKnown;
        report->fileValid = fileData.length > 0;
        report->reconstructionValid = reconstruction;
    }
    printf("[ICONSERVICES_MATERIALIZE] stock68-identity image=0x%llx "
           "class=%s uuid=%s tokenBytes=%zu path=\"%s\" fileBytes=%lu "
           "reconstruction=%d persist=%d binding=%d\n",
           (unsigned long long)image,
           imageClass[0] ? imageClass : "-",
           uuidKnown ? uuidText : "-",
           tokenKnown ? tokenCapture.objectLength : 0,
           path.UTF8String ?: "-",
           (unsigned long)fileData.length,
           reconstruction,
           persist,
           bindingMatches);
    if (r_is_objc_ptr(reconstructed) && remote_call_current_success()) {
        r_msg2(reconstructed, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(remoteData) && remote_call_current_success()) {
        r_msg2(remoteData, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(uuidString) && remote_call_current_success()) {
        r_msg2(uuidString, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(token) && remote_call_current_success()) {
        r_msg2(token, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(uuid) && remote_call_current_success()) {
        r_msg2(uuid, "release", 0, 0, 0, 0);
    }
    themer_iconservices_lab_free_data_capture(&tokenCapture);
    return bindingMatches && remote_call_current_success();
}

// Recovery is deliberately separate from materialization.  Its only remote
// operations are getters, byte reads, and construction of a short-lived
// IFCacheImage from the exact existing file bytes.  In particular it never
// prepares, renders, generates, mutates image bags, or changes the active
// process association.
typedef struct {
    NSData *tokenData;
    char uuid[80];
    char path[512];
    char fileSHA256[65];
    char tokenSHA256[65];
    uint64_t fileSize;
} ThemerStock68RecoveryIdentity;

static bool themer_stock68_snapshot_exact_equal(
    const ThemerSpotlightStock68JournalSnapshot *first,
    const ThemerSpotlightStock68JournalSnapshot *second)
{
    if (!first || !second) return false;
    return first->classification == second->classification &&
        first->version == second->version && first->pid == second->pid &&
        first->present == second->present && first->valid == second->valid &&
        first->issuedKnown == second->issuedKnown &&
        first->issued == second->issued &&
        first->dispatchPossibleKnown == second->dispatchPossibleKnown &&
        first->dispatchPossible == second->dispatchPossible &&
        first->transactionBound == second->transactionBound &&
        first->storeRegistrationPresent == second->storeRegistrationPresent &&
        first->storeRegistrationValid == second->storeRegistrationValid &&
        strcmp(first->rawJournalSHA256, second->rawJournalSHA256) == 0 &&
        strcmp(first->targetBundle, second->targetBundle) == 0 &&
        strcmp(first->themeFingerprint, second->themeFingerprint) == 0 &&
        strcmp(first->namedDigest, second->namedDigest) == 0 &&
        strcmp(first->generatedDigest, second->generatedDigest) == 0 &&
        strcmp(first->phase, second->phase) == 0;
}

static bool themer_stock68_recovery_current_journal_matches(
    const ThemerSpotlightStock68JournalSnapshot *expected)
{
    ThemerSpotlightStock68JournalSnapshot current =
        themer_spotlight_stock68_journal_snapshot();
    return themer_stock68_snapshot_exact_equal(expected, &current);
}

static bool themer_stock68_recovery_issued_class(
    ThemerSpotlightStock68JournalClassification classification)
{
    return classification == ThemerSpotlightStock68JournalLegacyIssuedAmbiguous ||
        classification == ThemerSpotlightStock68JournalDispatchPossible;
}

static bool themer_stock68_recovery_complete_journal(
    const ThemerSpotlightStock68JournalSnapshot *journal)
{
    return journal && !journal->storeRegistrationPresent && journal->present && journal->valid && journal->issued &&
        journal->issuedKnown && themer_stock68_recovery_issued_class(
            journal->classification) && journal->pid > 0 &&
        journal->targetBundle[0] && strlen(journal->targetBundle) <
            sizeof(journal->targetBundle) &&
        strlen(journal->themeFingerprint) == 64 &&
        journal->namedDigest[0] && journal->generatedDigest[0] &&
        strcmp(journal->namedDigest, journal->generatedDigest) == 0;
}

static bool themer_stock68_recovery_canonical_owner(uint64_t value)
{
    return value != 0 && value != UINT64_MAX &&
        (value >> 48) == UINT16_MAX;
}

static uint64_t themer_stock68_recovery_retained_object(
    uint64_t object,
    const char *selector,
    const char *expectedTypes)
{
    char types[192] = {0};
    bool exact = r_is_objc_ptr(object) && selector && expectedTypes &&
        r_responds_main(object, selector) &&
        themer_iconservices_lab_method_types(
            object, selector, types, sizeof(types)) &&
        strcmp(types, expectedTypes) == 0;
    if (!exact) return 0;
    uint64_t value = r_msg2_main(object, selector, 0, 0, 0, 0);
    if (!r_is_objc_ptr(value) || !remote_call_current_success()) return 0;
    uint64_t retained = r_msg2(value, "retain", 0, 0, 0, 0);
    return remote_call_current_success() && r_is_objc_ptr(retained)
        ? retained : 0;
}

static bool themer_stock68_recovery_capture_exact_data(
    uint64_t data,
    size_t cap,
    ThemerIconServicesLabDataCapture *capture)
{
    return r_is_objc_ptr(data) &&
        themer_iconservices_lab_capture_nsdata(data, cap, capture) &&
        !capture->truncated && capture->objectLength > 0 &&
        capture->capturedLength == capture->objectLength &&
        remote_call_current_success();
}

static bool themer_stock68_recovery_validate_store_unit(
    uint64_t managerCache,
    uint64_t uuid,
    const uint8_t *expectedBytes,
    size_t expectedLength,
    bool *integrityOut)
{
    if (integrityOut) *integrityOut = false;
    uint64_t store = themer_iconservices_lab_retained_store(managerCache);
    char lookupTypes[192] = {0};
    bool lookupABI = r_is_objc_ptr(store) && r_responds_main(store, "unitForUUID:") &&
        themer_iconservices_lab_method_types(
            store, "unitForUUID:", lookupTypes, sizeof(lookupTypes)) &&
        strcmp(lookupTypes, "@24@0:8@16") == 0;
    uint64_t unit = lookupABI && r_is_objc_ptr(uuid)
        ? r_msg2_main_retained_object(store, "unitForUUID:", uuid, 0, 0, 0)
        : 0;
    char uuidTypes[192] = {0};
    char dataTypes[192] = {0};
    char validTypes[192] = {0};
    bool unitABI = r_is_objc_ptr(unit) &&
        r_responds_main(unit, "UUID") &&
        themer_iconservices_lab_method_types(unit, "UUID", uuidTypes,
                                              sizeof(uuidTypes)) &&
        strcmp(uuidTypes, "@16@0:8") == 0 &&
        r_responds_main(unit, "data") &&
        themer_iconservices_lab_method_types(unit, "data", dataTypes,
                                              sizeof(dataTypes)) &&
        strcmp(dataTypes, "@16@0:8") == 0 &&
        r_responds_main(unit, "isValid") &&
        themer_iconservices_lab_method_types(unit, "isValid", validTypes,
                                              sizeof(validTypes)) &&
        strcmp(validTypes, "B16@0:8") == 0;
    uint64_t unitUUID = unitABI
        ? themer_stock68_recovery_retained_object(unit, "UUID", "@16@0:8") : 0;
    uint64_t unitData = unitABI
        ? themer_stock68_recovery_retained_object(unit, "data", "@16@0:8") : 0;
    uint64_t validRaw = unitABI
        ? r_msg2_main(unit, "isValid", 0, 0, 0, 0) : 0;
    ThemerIconServicesLabDataCapture unitCapture = {0};
    bool unitDataExact = themer_stock68_recovery_capture_exact_data(
        unitData, 8U << 20, &unitCapture);
    bool uuidEqual = r_is_objc_ptr(unitUUID) && r_is_objc_ptr(uuid) &&
        themer_iconservices_lab_objects_equal(unitUUID, uuid);
    bool bytesEqual = unitDataExact && expectedBytes &&
        unitCapture.objectLength == expectedLength &&
        memcmp(unitCapture.bytes, expectedBytes, expectedLength) == 0;
    bool integrity = lookupABI && unitABI && (validRaw & 1) != 0 &&
        uuidEqual && bytesEqual && remote_call_current_success();
    printf("[ICONSERVICES_RECOVERY] store-unit selector=unitForUUID: "
           "types=\"%s\" unitUUID=\"%s\" data=\"%s\" valid=\"%s\" "
           "lookup=%d unit=%d uuid=%d bytes=%d verdict=%d\n",
           lookupTypes, uuidTypes, dataTypes, validTypes, lookupABI, unitABI,
           uuidEqual, bytesEqual, integrity);
    if (r_is_objc_ptr(unitData) && remote_call_current_success())
        r_msg2(unitData, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(unitUUID) && remote_call_current_success())
        r_msg2(unitUUID, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(unit) && remote_call_current_success())
        r_msg2(unit, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(store) && remote_call_current_success())
        r_msg2(store, "release", 0, 0, 0, 0);
    themer_iconservices_lab_free_data_capture(&unitCapture);
    if (integrityOut) *integrityOut = integrity;
    return integrity;
}

static bool themer_stock68_recovery_certificate_matches(
    NSDictionary *, const ThemerSpotlightStock68JournalSnapshot *, int,
    ThemerStock68RecoveryIdentity *);

static NSArray<NSString *> *themer_stock68_identity_keys(void)
{
    return @[THEMER_STOCK68_V2_UUID_KEY, THEMER_STOCK68_V2_TOKEN_KEY,
        THEMER_STOCK68_V2_PID_KEY, THEMER_STOCK68_V2_PATH_KEY,
        THEMER_STOCK68_V2_BUNDLE_KEY, THEMER_STOCK68_V2_FINGERPRINT_KEY,
        THEMER_STOCK68_V2_DIGEST_KEY, THEMER_STOCK68_V2_FILE_SIZE_KEY];
}

static NSDictionary *themer_stock68_identity_raw(NSUserDefaults *defaults)
{
    NSMutableDictionary *raw = [NSMutableDictionary dictionary];
    for (NSString *key in [themer_stock68_identity_keys()
            arrayByAddingObject:THEMER_STOCK68_ADOPTION_CERTIFICATE_KEY]) {
        id value = [defaults objectForKey:key];
        if (value) raw[key] = value;
    }
    return [raw copy];
}

// Canonicalize dictionaries recursively so the fingerprint does not depend on
// NSUserDefaults' dictionary enumeration order. All raw values participate.
static id themer_stock68_identity_canonical(id value)
{
    if ([value isKindOfClass:NSDictionary.class]) {
        NSMutableArray *pairs = [NSMutableArray array];
        for (id key in [[value allKeys] sortedArrayUsingSelector:@selector(compare:)])
            [pairs addObject:@[key, themer_stock68_identity_canonical(value[key])]];
        return @[@"dictionary", pairs];
    }
    if ([value isKindOfClass:NSArray.class]) {
        NSMutableArray *items = [NSMutableArray array];
        for (id item in value) [items addObject:themer_stock68_identity_canonical(item)];
        return @[@"array", items];
    }
    return value;
}

// NSObject equality intentionally equates some NSNumber integer/float/Boolean
// values. Recovery rollback must preserve the raw property-list types too.
static bool themer_stock68_identity_values_equal(id a, id b)
{
    if (!a || !b) return a == b;
    NSData *left = [NSPropertyListSerialization dataWithPropertyList:
        themer_stock68_identity_canonical(a) format:NSPropertyListBinaryFormat_v1_0 options:0 error:NULL];
    NSData *right = [NSPropertyListSerialization dataWithPropertyList:
        themer_stock68_identity_canonical(b) format:NSPropertyListBinaryFormat_v1_0 options:0 error:NULL];
    return left && right && [left isEqualToData:right];
}

ThemerStock68V2IdentitySnapshot themer_spotlight_stock68_v2_identity_snapshot(
    const ThemerSpotlightStock68JournalSnapshot *journal,
    int currentPID, const char *managerCachePath)
{
    ThemerStock68V2IdentitySnapshot snapshot = {0};
    snapshot.classification = ThemerStock68V2IdentityRejected;
    NSDictionary *raw = themer_stock68_identity_raw(NSUserDefaults.standardUserDefaults);
    NSArray *keys = themer_stock68_identity_keys();
    for (NSUInteger i = 0; i < keys.count; i++)
        if (raw[keys[i]]) snapshot.presenceMask |= 1U << i;
    id certificate = raw[THEMER_STOCK68_ADOPTION_CERTIFICATE_KEY];
    snapshot.certificatePresent = certificate != nil;
    // Bind the complete raw journal too: normalized journal fields alone can
    // hide changes to additional transaction metadata or numeric encodings.
    id rawJournal = [NSUserDefaults.standardUserDefaults objectForKey:THEMER_STOCK68_JOURNAL_KEY];
    NSDictionary *fingerprintInput = rawJournal ? @{@"identity": raw, @"journal": rawJournal} : @{@"identity": raw};
    NSData *encoded = [NSPropertyListSerialization dataWithPropertyList:
        themer_stock68_identity_canonical(fingerprintInput) format:NSPropertyListBinaryFormat_v1_0
        options:0 error:NULL];
    if (encoded.length && encoded.length <= UINT32_MAX) {
        unsigned char digest[CC_SHA256_DIGEST_LENGTH];
        CC_SHA256(encoded.bytes, (CC_LONG)encoded.length, digest);
        themer_iconservices_lab_hex_bytes(digest, sizeof(digest),
            snapshot.snapshotSHA256, sizeof(snapshot.snapshotSHA256));
        snapshot.snapshotKnown = true;
    }
    if (!snapshot.presenceMask) {
        if (!certificate && snapshot.snapshotKnown)
            snapshot.classification = ThemerStock68V2IdentityAbsent;
        return snapshot;
    }
    if (snapshot.presenceMask != 255 || !snapshot.snapshotKnown ||
        !themer_stock68_recovery_complete_journal(journal) ||
        journal->version != THEMER_STOCK68_JOURNAL_V2_VERSION ||
        !journal->transactionBound || !managerCachePath || !managerCachePath[0]) return snapshot;
    // Recovery accepts the exact persisted integer owner/version, never a
    // floating-point or Boolean value that merely coerces to the same number.
    if (![rawJournal isKindOfClass:NSDictionary.class]) return snapshot;
    for (NSString *key in @[@"version", @"pid"]) {
        id number = rawJournal[key];
        if (![number isKindOfClass:NSNumber.class] ||
            CFGetTypeID((__bridge CFTypeRef)number) == CFBooleanGetTypeID() ||
            CFNumberIsFloatType((__bridge CFNumberRef)number)) return snapshot;
    }
    id uuid = raw[keys[0]], token = raw[keys[1]], pid = raw[keys[2]], path = raw[keys[3]];
    id bundle = raw[keys[4]], fingerprint = raw[keys[5]], digest = raw[keys[6]], size = raw[keys[7]];
    bool types = [uuid isKindOfClass:NSString.class] && [token isKindOfClass:NSData.class] &&
        [pid isKindOfClass:NSNumber.class] && CFGetTypeID((__bridge CFTypeRef)pid) != CFBooleanGetTypeID() &&
        !CFNumberIsFloatType((__bridge CFNumberRef)pid) &&
        [path isKindOfClass:NSString.class] && [bundle isKindOfClass:NSString.class] &&
        [fingerprint isKindOfClass:NSString.class] && [digest isKindOfClass:NSString.class] &&
        [size isKindOfClass:NSNumber.class] && CFGetTypeID((__bridge CFTypeRef)size) != CFBooleanGetTypeID() &&
        !CFNumberIsFloatType((__bridge CFNumberRef)size);
    if (!types) return snapshot;
    long long savedPID = [pid longLongValue], fileSize = [size longLongValue];
    if (savedPID <= 0 || savedPID > INT_MAX || ![pid isEqual:@(savedPID)] ||
        fileSize <= 0 || ![size isEqual:@(fileSize)] || [token length] == 0 ||
        [token length] > THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP) return snapshot;
    snapshot.savedPID = (int)savedPID;
    snapshot.fileSize = (uint64_t)fileSize;
    snapshot.tokenLength = [token length];
    uint8_t uuidBytes[16];
    if ([uuid lengthOfBytesUsingEncoding:NSUTF8StringEncoding] != strlen([uuid UTF8String]) ||
        [uuid lengthOfBytesUsingEncoding:NSUTF8StringEncoding] >= sizeof(snapshot.uuid) ||
        !themer_iconservices_lab_parse_uuid_text([uuid UTF8String], uuidBytes)) return snapshot;
    NSString *canonical = [[NSString stringWithUTF8String:managerCachePath]
        stringByAppendingPathComponent:[uuid stringByAppendingString:@".isdata"]];
    if ([canonical lengthOfBytesUsingEncoding:NSUTF8StringEncoding] != strlen(canonical.UTF8String) ||
        [canonical lengthOfBytesUsingEncoding:NSUTF8StringEncoding] >= sizeof(snapshot.canonicalPath) ||
        ![path isEqual:canonical] || ![bundle isEqual:@(journal->targetBundle)] ||
        ![fingerprint isEqual:@(journal->themeFingerprint)] || ![digest isEqual:@(journal->namedDigest)]) return snapshot;
    snprintf(snapshot.uuid, sizeof(snapshot.uuid), "%s", [uuid UTF8String]);
    snprintf(snapshot.canonicalPath, sizeof(snapshot.canonicalPath), "%s", canonical.UTF8String);
    ThemerStock68RecoveryIdentity adopted = {0};
    bool certificateTypes = [certificate isKindOfClass:NSDictionary.class];
    if (certificateTypes) {
        for (NSString *key in @[@"version", @"journalVersion", @"journalClassification", @"oldPID", @"currentPID", @"fileSize"]) {
            id number = certificate[key];
            if (![number isKindOfClass:NSNumber.class] ||
                CFGetTypeID((__bridge CFTypeRef)number) == CFBooleanGetTypeID() ||
                CFNumberIsFloatType((__bridge CFNumberRef)number)) certificateTypes = false;
        }
        certificateTypes = certificateTypes && [certificate[@"version"] isEqual:@1] &&
            [certificate[@"journalVersion"] isEqual:@(journal->version)] &&
            [certificate[@"journalClassification"] isEqual:@((int)journal->classification)] &&
            [certificate[@"oldPID"] isEqual:@(journal->pid)] &&
            [certificate[@"currentPID"] isEqual:@(currentPID)] &&
            [certificate[@"fileSize"] isEqual:size] &&
            [certificate[@"uuid"] isEqual:uuid] && [certificate[@"path"] isEqual:path];
        for (NSString *key in @[@"fileSHA256", @"tokenSHA256"]) {
            id hash = certificate[key];
            certificateTypes = certificateTypes && [hash isKindOfClass:NSString.class] &&
                [hash length] == 64 && [hash rangeOfCharacterFromSet:
                    [[NSCharacterSet characterSetWithCharactersInString:@"0123456789abcdef"] invertedSet]].location == NSNotFound;
        }
    }
    snapshot.certificateBound = certificateTypes && savedPID == currentPID &&
        themer_stock68_recovery_certificate_matches(certificate, journal, currentPID, &adopted) &&
        strcmp(adopted.uuid, snapshot.uuid) == 0 && strcmp(adopted.path, snapshot.canonicalPath) == 0 &&
        adopted.fileSize == snapshot.fileSize && [adopted.tokenData isEqual:token];
    if ((!certificate && savedPID == journal->pid) || snapshot.certificateBound)
        snapshot.classification = ThemerStock68V2IdentityBound;
    return snapshot;
}

static bool themer_stock68_identity_snapshot_equal(
    const ThemerStock68V2IdentitySnapshot *a, const ThemerStock68V2IdentitySnapshot *b)
{
    return a && b && a->snapshotKnown && b->snapshotKnown &&
        a->classification == b->classification && a->presenceMask == b->presenceMask &&
        a->savedPID == b->savedPID && a->certificatePresent == b->certificatePresent &&
        a->certificateBound == b->certificateBound && a->tokenLength == b->tokenLength &&
        a->fileSize == b->fileSize && strcmp(a->snapshotSHA256, b->snapshotSHA256) == 0 &&
        strcmp(a->uuid, b->uuid) == 0 && strcmp(a->canonicalPath, b->canonicalPath) == 0;
}

static uint64_t themer_stock68_absence_getter(uint64_t receiver, const char *selector)
{
    char types[192] = {0};
    bool exact = remote_call_current_success() && r_is_objc_ptr(receiver) &&
        r_responds_main(receiver, selector) &&
        themer_iconservices_lab_method_types(receiver, selector, types, sizeof(types)) &&
        strcmp(types, "@16@0:8") == 0 && remote_call_current_success();
    uint64_t result = exact ? r_msg2_main(receiver, selector, 0, 0, 0, 0) : 0;
    printf("[ICONSERVICES_RECOVERY] empty-getter receiver=0x%llx selector=%s types=\"%s\" exact=%d healthy=%d\n",
        (unsigned long long)receiver, selector, types, exact, remote_call_current_success());
    return remote_call_current_success() && r_is_objc_ptr(result) ? result : 0;
}

static void themer_stock68_inspect_empty_identity(
    const ThemerSpotlightStock68JournalSnapshot *journal,
    ThemerSpotlightStock68RecoveryInspectionReport *report)
{
    ThemerStock68V2AbsenceEvidence *e = &report->emptyIdentity;
    e->identity = themer_spotlight_stock68_v2_identity_snapshot(journal,
        report->currentPID, report->managerCachePath);
    if (e->identity.classification == ThemerStock68V2IdentityBound) {
        struct stat st = {0};
        errno = 0;
        e->fileResult = lstat(e->identity.canonicalPath, &st);
        e->fileErrno = e->fileResult == -1 ? errno : 0;
        e->fileAbsent = e->fileResult == -1 && e->fileErrno == ENOENT;
        uint64_t managerClass = themer_lookup_class("ISIconManager");
        uint64_t manager = themer_stock68_absence_getter(managerClass, "sharedInstance");
        uint64_t cache = themer_stock68_absence_getter(manager, "iconCache");
        uint64_t remotePath = themer_stock68_absence_getter(cache, "cachePath");
        char actualPath[512] = {0};
        bool pathBound = r_is_objc_ptr(remotePath) &&
            r_read_nsstring(remotePath, actualPath, sizeof(actualPath)) &&
            strcmp(actualPath, report->managerCachePath) == 0 && remote_call_current_success();
        uint64_t store = pathBound ? themer_stock68_absence_getter(cache, "store") : 0;
        e->storeReceiver = store;
        if (r_is_objc_ptr(store)) themer_read_class_name(store, e->storeClass, sizeof(e->storeClass));
        uint64_t uuid = themer_iconservices_lab_make_remote_uuid(@(e->identity.uuid));
        e->storeABI = r_is_objc_ptr(store) && strcmp(e->storeClass, "ISStore") == 0 &&
            r_is_objc_ptr(uuid) && r_responds_main(store, "unitForUUID:") &&
            themer_iconservices_lab_method_types(store, "unitForUUID:", e->storeTypes, sizeof(e->storeTypes)) &&
            strcmp(e->storeTypes, "@24@0:8@16") == 0 && remote_call_current_success();
        if (e->storeABI && remote_call_current_success()) {
            e->storeDispatched = true;
            uint64_t unit = r_msg2_main(store, "unitForUUID:", uuid, 0, 0, 0);
            e->storeHealthyNil = unit == 0 && remote_call_current_success();
        }
        if (r_is_objc_ptr(uuid) && remote_call_current_success()) r_msg2(uuid, "release", 0, 0, 0, 0);
    }
    printf("[ICONSERVICES_RECOVERY] empty-identity mask=0x%x class=%d savedPID=%d certificate=%d bound=%d tokenLength=%llu canonical=%s fileResult=%d errno=%d absent=%d store=0x%llx class=%s ABI=\"%s\" dispatched=%d healthyNil=%d\n",
        e->identity.presenceMask, e->identity.classification, e->identity.savedPID,
        e->identity.certificatePresent, e->identity.certificateBound,
        (unsigned long long)e->identity.tokenLength, e->identity.canonicalPath,
        e->fileResult, e->fileErrno, e->fileAbsent, (unsigned long long)e->storeReceiver,
        e->storeClass, e->storeTypes, e->storeDispatched, e->storeHealthyNil);
}

static ThemerSpotlightStock68RecoveryInspectionResult
themer_stock68_recovery_inspect_common(
    const ThemerSpotlightStock68JournalSnapshot *expectedJournal,
    int expectedPID,
    uint64_t expectedProc,
    uint64_t expectedTask,
    bool ownerExitProven,
    ThemerSpotlightStock68RecoveryInspectionReport *reportOut,
    ThemerStock68RecoveryIdentity *identityOut)
{
    ThemerSpotlightStock68RecoveryInspectionReport report = {0};
    ThemerStock68RecoveryIdentity identity = {0};
    NSString *path = nil;
    NSData *fileData = nil;
    ThemerSpotlightStock68JournalSnapshot after = {0};
    ThemerSpotlightStock68RecoveryInspectionResult result =
        ThemerSpotlightStock68RecoveryInspectionRejected;
    ThemerSpotlightStock68JournalSnapshot before =
        themer_spotlight_stock68_journal_snapshot();
    if (expectedJournal) {
        report.journalVersion = expectedJournal->version;
        report.journalPID = expectedJournal->pid;
        snprintf(report.targetBundle, sizeof(report.targetBundle), "%s",
                 expectedJournal->targetBundle);
        snprintf(report.themeFingerprint, sizeof(report.themeFingerprint), "%s",
                 expectedJournal->themeFingerprint);
        snprintf(report.namedDigest, sizeof(report.namedDigest), "%s",
                 expectedJournal->namedDigest);
        snprintf(report.generatedDigest, sizeof(report.generatedDigest), "%s",
                 expectedJournal->generatedDigest);
    }
    report.journalBinding = themer_stock68_recovery_complete_journal(expectedJournal) &&
        themer_stock68_snapshot_exact_equal(expectedJournal, &before);
    report.expectedOwnerBinding = expectedPID > 0 && expectedPID == before.pid &&
        themer_stock68_recovery_canonical_owner(expectedProc) &&
        themer_stock68_recovery_canonical_owner(expectedTask);
    report.ownerExitProven = ownerExitProven;
    int currentPID = remote_call_current_pid();
    report.currentPID = currentPID;
    report.currentProc = remote_call_current_proc();
    report.currentTask = remote_call_current_task();
    report.retiredProc = expectedProc;
    report.retiredTask = expectedTask;
    report.currentPIDHealthy = remote_call_current_success() && currentPID > 0 &&
        currentPID != before.pid;
    if (!report.journalBinding || !report.expectedOwnerBinding ||
        !report.ownerExitProven || !report.currentPIDHealthy) {
        snprintf(report.reason, sizeof(report.reason), "%s",
                 "journal-owner-or-current-pid-binding");
        goto done;
    }

    // This is the one association read required to prove that the fresh host
    // did not inherit an in-process materialization transaction.
    uint64_t state = themer_stock68_materialization_state();
    report.stateAbsenceKnown = remote_call_current_success();
    report.stateAbsent = report.stateAbsenceKnown && state == 0;
    if (!report.stateAbsent) {
        snprintf(report.reason, sizeof(report.reason), "%s", "remote-state-present");
        goto done;
    }

    ThemerStock68MaterializationContext context = {0};
    if (!themer_stock68_acquire_context(before.targetBundle, &context)) {
        snprintf(report.reason, sizeof(report.reason), "%s", "context-acquire");
        themer_stock68_release_context(&context);
        goto done;
    }
    report.digestMatch = strcmp(context.namedDigest, before.namedDigest) == 0 &&
        strcmp(before.generatedDigest, before.namedDigest) == 0;
    ThemerIconServicesLabTopologySnapshot topology = {0};
    report.topologyComplete = themer_stock68_capture_strict_topology(
        context.canonicalCache, "recovery-inspect", &topology);
    report.dictionaryCount = topology.dictionaryCount;
    report.keyCount = topology.keyCount;
    report.actualKeyCountKnown = topology.actualKeyCountKnown;
    report.actualKeyCount = topology.actualKeyCount;
    report.totalEntryCountKnown = topology.totalEntryCountKnown;
    report.totalEntryCount = topology.totalEntryCount;
    report.descriptorScale = context.namedScale;
    report.descriptorScaleKnown = context.namedScale >= 1.0 &&
        context.namedScale <= 4.0;
    snprintf(report.authoritativeDigest, sizeof(report.authoritativeDigest),
             "%s", context.namedDigest);
    snprintf(report.managerCachePath, sizeof(report.managerCachePath), "%s",
             context.managerCachePath);
    if (!report.digestMatch || !report.topologyComplete) {
        snprintf(report.reason, sizeof(report.reason), "%s",
                 report.digestMatch ? "topology-incomplete" : "digest-binding");
        themer_stock68_release_context(&context);
        goto done;
    }
    const ThemerIconServicesLabSnapshotKey *namedKey =
        themer_iconservices_lab_snapshot_key_for_text(&topology,
                                                      before.namedDigest);
    uint64_t candidate = 0;
    for (int i = 0; i < topology.keyCount; i++) {
        const ThemerIconServicesLabSnapshotKey *key = &topology.keys[i];
        for (int j = 0; j < key->entryCount; j++) {
            const ThemerIconServicesLabSnapshotEntry *entry = &key->entries[j];
            if (!themer_stock68_entry_is_68(entry, context.namedScale)) continue;
            if (key == namedKey) {
                report.named68Count++;
                char className[96] = {0};
                themer_read_class_name(entry->image, className, sizeof(className));
                if (strcmp(className, "IFCacheImage") == 0) {
                    report.candidateCount++;
                    candidate = entry->image;
                }
            } else {
                report.wrongKey68Count++;
            }
        }
    }
    report.topologyExactlyEmpty = report.topologyComplete &&
        !topology.keysTruncated && report.actualKeyCountKnown &&
        report.totalEntryCountKnown && report.dictionaryCount == 0 &&
        report.keyCount == 0 && report.actualKeyCount == 0 &&
        report.totalEntryCount == 0 && report.named68Count == 0 &&
        report.candidateCount == 0 && report.wrongKey68Count == 0 &&
        report.digestMatch && report.authoritativeDigest[0] != '\0' &&
        report.descriptorScaleKnown && report.stateAbsenceKnown &&
        report.stateAbsent && report.journalBinding &&
        report.expectedOwnerBinding && report.ownerExitProven &&
        report.currentPIDHealthy && remote_call_current_success();
    if (report.topologyExactlyEmpty) {
        themer_stock68_inspect_empty_identity(expectedJournal, &report);
        ThemerIconServicesLabTopologySnapshot afterAbsence = {0};
        bool stillEmpty = remote_call_current_success() &&
            themer_stock68_capture_strict_topology(context.canonicalCache,
                "recovery-after-absence", &afterAbsence) &&
            !afterAbsence.keysTruncated && afterAbsence.actualKeyCountKnown &&
            afterAbsence.totalEntryCountKnown && afterAbsence.dictionaryCount == 0 &&
            afterAbsence.keyCount == 0 && afterAbsence.actualKeyCount == 0 &&
            afterAbsence.totalEntryCount == 0;
        uint64_t stateAfter = remote_call_current_success()
            ? themer_stock68_materialization_state() : UINT64_MAX;
        report.topologyExactlyEmpty = stillEmpty && stateAfter == 0 && remote_call_current_success();
    }
    if (!namedKey || report.named68Count == 0) {
        result = ThemerSpotlightStock68RecoveryInspectionNoCandidate;
        snprintf(report.reason, sizeof(report.reason), "%s", "no-named-68-candidate");
        themer_stock68_release_context(&context);
        goto done;
    }
    if (report.candidateCount != 1 || report.named68Count != 1 ||
        report.wrongKey68Count != 0) {
        result = ThemerSpotlightStock68RecoveryInspectionAmbiguous;
        snprintf(report.reason, sizeof(report.reason), "%s", "topology-candidate-ambiguity");
        themer_stock68_release_context(&context);
        goto done;
    }

    uint64_t uuid = themer_stock68_recovery_retained_object(candidate, "uuid", "@16@0:8");
    uint64_t token = themer_stock68_recovery_retained_object(
        candidate, "validationToken", "@16@0:8");
    uint64_t imageData = themer_stock68_recovery_retained_object(candidate, "data", "@16@0:8");
    uint64_t uuidString = themer_stock68_recovery_retained_object(uuid, "UUIDString", "@16@0:8");
    uint8_t uuidBytes[16] = {0};
    report.uuidValid = r_is_objc_ptr(uuidString) &&
        r_read_nsstring(uuidString, identity.uuid, sizeof(identity.uuid)) &&
        themer_iconservices_lab_parse_uuid_text(identity.uuid, uuidBytes);
    ThemerIconServicesLabDataCapture tokenCapture = {0};
    ThemerIconServicesLabDataCapture imageCapture = {0};
    report.tokenValid = themer_stock68_recovery_capture_exact_data(
        token, THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP, &tokenCapture);
    bool imageDataExact = themer_stock68_recovery_capture_exact_data(
        imageData, 8U << 20, &imageCapture);
    identity.tokenData = report.tokenValid
        ? [NSData dataWithBytes:tokenCapture.bytes length:tokenCapture.objectLength] : nil;
    path = report.uuidValid && context.managerCachePath[0]
        ? [[NSString stringWithUTF8String:context.managerCachePath]
            stringByAppendingPathComponent:[NSString stringWithFormat:@"%s.isdata", identity.uuid]] : nil;
    struct stat st = {0};
    int statResult = path.length ? stat(path.fileSystemRepresentation, &st) : -1;
    report.fileRegular = statResult == 0 && S_ISREG(st.st_mode);
    report.fileReadable = report.fileRegular && access(path.fileSystemRepresentation, R_OK) == 0;
    report.fileNonempty = report.fileRegular && st.st_size > 0;
    report.fileBounded = report.fileRegular && st.st_size <= (off_t)(8U << 20);
    fileData = report.fileReadable && report.fileNonempty && report.fileBounded
        ? themer_iconservices_lab_read_local_file(path) : nil;
    report.fileSize = fileData.length;
    identity.fileSize = fileData.length;
    snprintf(identity.path, sizeof(identity.path), "%s", path.UTF8String ?: "");
    bool fileMatchesStat = fileData.length > 0 && (off_t)fileData.length == st.st_size;
    uint8_t fileDigest[32] = {0};
    uint8_t tokenDigest[32] = {0};
    report.fileHashKnown = fileMatchesStat && themer_iconservices_lab_digest(
        "CC_SHA256", fileData.bytes, fileData.length, fileDigest);
    bool tokenHashKnown = report.tokenValid && themer_iconservices_lab_digest(
        "CC_SHA256", tokenCapture.bytes, tokenCapture.objectLength, tokenDigest);
    if (report.fileHashKnown) themer_iconservices_lab_hex_bytes(
        fileDigest, sizeof(fileDigest), identity.fileSHA256, sizeof(identity.fileSHA256));
    if (tokenHashKnown) themer_iconservices_lab_hex_bytes(
        tokenDigest, sizeof(tokenDigest), identity.tokenSHA256, sizeof(identity.tokenSHA256));
    bool imageMatchesFile = imageDataExact && fileData.length == imageCapture.objectLength &&
        memcmp(fileData.bytes, imageCapture.bytes, fileData.length) == 0;
    uint64_t remoteFileData = fileData.length > 0
        ? themer_make_remote_nsdata(fileData) : 0;
    uint64_t reconstructed = r_is_objc_ptr(remoteFileData) && r_is_objc_ptr(uuid) && r_is_objc_ptr(token)
        ? themer_iconservices_lab_make_if_cache_image(remoteFileData, uuid, token) : 0;
    report.reconstructionValid = r_is_objc_ptr(reconstructed) &&
        themer_iconservices_lab_image_geometry_matches(reconstructed, 68.0, 68.0,
                                                        context.namedScale);
    report.storeIntegrity = report.uuidValid && imageMatchesFile &&
        themer_stock68_recovery_validate_store_unit(context.managerCache, uuid,
                                                    fileData.bytes, fileData.length,
                                                    NULL);
    report.candidateIdentityProven = report.uuidValid && report.tokenValid &&
        report.fileRegular && report.fileReadable && report.fileNonempty &&
        report.fileBounded && report.fileHashKnown && imageMatchesFile &&
        report.reconstructionValid && report.storeIntegrity &&
        remote_call_current_success();
    report.adoptionEligible = report.candidateIdentityProven;
    snprintf(report.uuid, sizeof(report.uuid), "%s", identity.uuid);
    snprintf(report.storePath, sizeof(report.storePath), "%s", identity.path);
    snprintf(report.fileSHA256, sizeof(report.fileSHA256), "%s", identity.fileSHA256);
    snprintf(report.tokenSHA256, sizeof(report.tokenSHA256), "%s", identity.tokenSHA256);
    if (!report.candidateIdentityProven) {
        result = ThemerSpotlightStock68RecoveryInspectionAmbiguous;
        snprintf(report.reason, sizeof(report.reason), "%s", "candidate-identity-or-store-mismatch");
    } else {
        result = ThemerSpotlightStock68RecoveryInspectionCandidateValidated;
        snprintf(report.reason, sizeof(report.reason), "%s", "candidate-proven-no-ownership");
    }
    if (r_is_objc_ptr(reconstructed) && remote_call_current_success()) r_msg2(reconstructed, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(remoteFileData) && remote_call_current_success()) r_msg2(remoteFileData, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(uuidString) && remote_call_current_success()) r_msg2(uuidString, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(imageData) && remote_call_current_success()) r_msg2(imageData, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(token) && remote_call_current_success()) r_msg2(token, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(uuid) && remote_call_current_success()) r_msg2(uuid, "release", 0, 0, 0, 0);
    themer_iconservices_lab_free_data_capture(&imageCapture);
    themer_iconservices_lab_free_data_capture(&tokenCapture);
    themer_stock68_release_context(&context);

done:
    after = themer_spotlight_stock68_journal_snapshot();
    bool transportHealthy = remote_call_current_success() &&
        report.currentPID == remote_call_current_pid() &&
        report.currentProc == remote_call_current_proc() &&
        report.currentTask == remote_call_current_task();
    if (!themer_stock68_snapshot_exact_equal(expectedJournal, &after)) {
        report.journalBinding = false;
        report.adoptionEligible = false;
        if (result == ThemerSpotlightStock68RecoveryInspectionCandidateValidated)
            result = ThemerSpotlightStock68RecoveryInspectionRejected;
        snprintf(report.reason, sizeof(report.reason), "%s", "journal-changed-during-inspection");
    }
    if (!transportHealthy) {
        report.adoptionEligible = false;
        result = ThemerSpotlightStock68RecoveryInspectionTransportFailed;
        snprintf(report.reason, sizeof(report.reason), "%s", "remote-transport-failed");
    }
    if (report.topologyExactlyEmpty) {
        ThemerStock68V2IdentitySnapshot currentIdentity =
            themer_spotlight_stock68_v2_identity_snapshot(expectedJournal,
                report.currentPID, report.managerCachePath);
        if (!themer_stock68_identity_snapshot_equal(&currentIdentity, &report.emptyIdentity.identity)) {
            report.topologyExactlyEmpty = false;
            snprintf(report.reason, sizeof(report.reason), "%s", "durable-identity-changed");
        }
    }
    if (!report.journalBinding || !transportHealthy) {
        report.topologyExactlyEmpty = false;
    }
    report.result = result;
    printf("[ICONSERVICES_RECOVERY] inspect class=%d journal=%d owner=%d pid=%d "
           "absence=%d topology=%d empty=%d digest=%d dictionary=%d keys=%d "
           "actualKeys=%d entries=%d named68=%d candidate=%d wrong68=%d "
           "identity=%d store=%d eligible=%d transactionOwnership=%d verdict=%d reason=%s\n",
           expectedJournal ? expectedJournal->classification : -1,
           report.journalBinding, report.expectedOwnerBinding, report.currentPIDHealthy,
           report.stateAbsent, report.topologyComplete, report.topologyExactlyEmpty,
           report.digestMatch, report.dictionaryCount, report.keyCount,
           report.actualKeyCount, report.totalEntryCount,
           report.named68Count, report.candidateCount, report.wrongKey68Count,
           report.candidateIdentityProven, report.storeIntegrity, report.adoptionEligible,
           report.transactionOwnershipProven, result, report.reason);
    if (identityOut && result == ThemerSpotlightStock68RecoveryInspectionCandidateValidated &&
        report.adoptionEligible) {
        *identityOut = identity;
    }
    if (reportOut) *reportOut = report;
    return result;
}

ThemerSpotlightStock68RecoveryInspectionResult
themer_spotlight_stock68_inspect_recovery_in_session(
    const ThemerSpotlightStock68JournalSnapshot *expectedJournal,
    int expectedPID,
    uint64_t expectedProc,
    uint64_t expectedTask,
    bool ownerExitProven,
    ThemerSpotlightStock68RecoveryInspectionReport *reportOut)
{
    return themer_stock68_recovery_inspect_common(
        expectedJournal, expectedPID, expectedProc, expectedTask,
        ownerExitProven, reportOut, NULL);
}

static bool themer_stock68_recovery_empty_report_matches_journal(
    const ThemerSpotlightStock68JournalSnapshot *expectedJournal,
    const ThemerSpotlightStock68RecoveryInspectionReport *report,
    int expectedCurrentPID)
{
    if (!expectedJournal || !report || expectedCurrentPID <= 0 ||
        report->result != ThemerSpotlightStock68RecoveryInspectionNoCandidate ||
        report->journalVersion != expectedJournal->version ||
        report->journalPID != expectedJournal->pid ||
        report->currentPID != expectedCurrentPID ||
        strcmp(report->targetBundle, expectedJournal->targetBundle) != 0 ||
        strcmp(report->themeFingerprint, expectedJournal->themeFingerprint) != 0 ||
        strcmp(report->namedDigest, expectedJournal->namedDigest) != 0 ||
        strcmp(report->generatedDigest, expectedJournal->generatedDigest) != 0 ||
        strcmp(report->authoritativeDigest, expectedJournal->namedDigest) != 0 ||
        report->managerCachePath[0] == '\0' ||
        !report->journalBinding || !report->expectedOwnerBinding ||
        !report->ownerExitProven || !report->currentPIDHealthy ||
        !report->stateAbsenceKnown || !report->stateAbsent ||
        !report->topologyComplete || !report->digestMatch ||
        !report->actualKeyCountKnown || !report->totalEntryCountKnown ||
        !report->descriptorScaleKnown || !report->topologyExactlyEmpty ||
        report->dictionaryCount != 0 || report->keyCount != 0 ||
        report->actualKeyCount != 0 || report->totalEntryCount != 0 ||
        report->candidateCount != 0 || report->named68Count != 0 ||
        report->wrongKey68Count != 0 || report->candidateIdentityProven ||
        report->adoptionEligible || report->adoptionPersisted ||
        report->transactionOwnershipProven || report->uuidValid ||
        report->tokenValid || report->fileRegular || report->fileReadable ||
        report->fileNonempty || report->fileBounded || report->fileHashKnown ||
        report->reconstructionValid || report->storeIntegrity ||
        report->fileSize != 0 || report->uuid[0] != '\0' ||
        report->storePath[0] != '\0' || report->fileSHA256[0] != '\0' ||
        report->tokenSHA256[0] != '\0' ||
        !(report->descriptorScale >= 1.0 && report->descriptorScale <= 4.0)) {
        return false;
    }
    return true;
}

static bool themer_stock68_empty_identity_eligible(const ThemerStock68V2AbsenceEvidence *e)
{
    if (!e || !e->identity.snapshotKnown) return false;
    if (e->identity.classification == ThemerStock68V2IdentityAbsent)
        return e->identity.presenceMask == 0 && !e->identity.certificatePresent;
    return e->identity.classification == ThemerStock68V2IdentityBound &&
        e->identity.presenceMask == 255 && e->identity.savedPID > 0 &&
        e->identity.canonicalPath[0] && e->identity.uuid[0] &&
        (!e->identity.certificatePresent || e->identity.certificateBound) &&
        e->fileAbsent && e->fileResult == -1 && e->fileErrno == ENOENT &&
        e->storeABI && e->storeDispatched && e->storeHealthyNil;
}

bool themer_spotlight_stock68_empty_recovery_reports_match(
    const ThemerSpotlightStock68JournalSnapshot *expectedJournal,
    const ThemerSpotlightStock68RecoveryInspectionReport *first,
    const ThemerSpotlightStock68RecoveryInspectionReport *second)
{
    if (!expectedJournal || !first || !second ||
        first->currentPID <= 0 || first->currentPID != second->currentPID ||
        !themer_stock68_recovery_canonical_owner(first->currentProc) ||
        !themer_stock68_recovery_canonical_owner(first->currentTask) ||
        !themer_stock68_recovery_canonical_owner(first->retiredProc) ||
        !themer_stock68_recovery_canonical_owner(first->retiredTask) ||
        first->currentProc != second->currentProc || first->currentTask != second->currentTask ||
        first->retiredProc != second->retiredProc || first->retiredTask != second->retiredTask ||
        !themer_stock68_empty_identity_eligible(&first->emptyIdentity) ||
        !themer_stock68_empty_identity_eligible(&second->emptyIdentity) ||
        !themer_stock68_identity_snapshot_equal(&first->emptyIdentity.identity, &second->emptyIdentity.identity) ||
        strcmp(first->managerCachePath, second->managerCachePath) != 0 ||
        strcmp(first->authoritativeDigest, second->authoritativeDigest) != 0) {
        return false;
    }
    if (!themer_stock68_recovery_empty_report_matches_journal(
            expectedJournal, first, first->currentPID) ||
        !themer_stock68_recovery_empty_report_matches_journal(
            expectedJournal, second, first->currentPID)) {
        return false;
    }
    double scaleDelta = first->descriptorScale - second->descriptorScale;
    if (scaleDelta < 0.0) scaleDelta = -scaleDelta;
    return scaleDelta < 0.01 &&
        strcmp(first->targetBundle, second->targetBundle) == 0 &&
        strcmp(first->themeFingerprint, second->themeFingerprint) == 0 &&
        strcmp(first->namedDigest, second->namedDigest) == 0 &&
        strcmp(first->generatedDigest, second->generatedDigest) == 0;
}

static bool themer_stock68_v2_identity_absent(NSUserDefaults *defaults)
{
    if (!defaults) return false;
    NSArray<NSString *> *keys = @[
        THEMER_STOCK68_V2_UUID_KEY, THEMER_STOCK68_V2_TOKEN_KEY,
        THEMER_STOCK68_V2_PID_KEY, THEMER_STOCK68_V2_PATH_KEY,
        THEMER_STOCK68_V2_BUNDLE_KEY, THEMER_STOCK68_V2_FINGERPRINT_KEY,
        THEMER_STOCK68_V2_DIGEST_KEY, THEMER_STOCK68_V2_FILE_SIZE_KEY,
    ];
    for (NSString *key in keys) {
        if ([defaults objectForKey:key] != nil) return false;
    }
    return true;
}

// A durable backup makes an interrupted multi-key retirement recoverable. Only
// Emergency Restore invokes this compensating restore; inspectors never do.
bool themer_spotlight_stock68_restore_interrupted_identity_retirement(void)
{
    NSUserDefaults *d = NSUserDefaults.standardUserDefaults;
    id record = [d objectForKey:THEMER_STOCK68_IDENTITY_RETIREMENT_KEY];
    if (!record) return true;
    if (![record isKindOfClass:NSDictionary.class] ||
        ![record[@"version"] isKindOfClass:NSNumber.class] ||
        CFGetTypeID((__bridge CFTypeRef)record[@"version"]) == CFBooleanGetTypeID() ||
        CFNumberIsFloatType((__bridge CFNumberRef)record[@"version"]) ||
        ![record[@"version"] isEqual:@1] || [record count] != 3 ||
        ![record[@"raw"] isKindOfClass:NSDictionary.class] ||
        ![record[@"journal"] isKindOfClass:NSDictionary.class]) return false;
    id currentJournal = [d objectForKey:THEMER_STOCK68_JOURNAL_KEY];
    // The journal may already have been cleared when the process died. The
    // backup still arms admission, and restores the exact transaction on retry.
    if (currentJournal && !themer_stock68_identity_values_equal(record[@"journal"], currentJournal)) return false;
    NSDictionary *raw = record[@"raw"];
    NSArray *keys = [themer_stock68_identity_keys()
        arrayByAddingObject:THEMER_STOCK68_ADOPTION_CERTIFICATE_KEY];
    for (id key in raw) if (![keys containsObject:key]) return false;
    for (id key in themer_stock68_identity_keys()) if (!raw[key]) return false;
    // Never overwrite unrelated durable state. An interrupted deletion can
    // leave only a subset of the exact original values.
    NSDictionary *now = themer_stock68_identity_raw(d);
    for (id key in now) if (!themer_stock68_identity_values_equal(now[key], raw[key])) return false;
    // Rearm the journal before restoring identity; the backup remains durable
    // through both operations and through the final acknowledgement.
    if (!currentJournal) [d setObject:record[@"journal"] forKey:THEMER_STOCK68_JOURNAL_KEY];
    for (id key in raw) [d setObject:raw[key] forKey:key];
    bool restored = [d synchronize] && themer_stock68_identity_values_equal(themer_stock68_identity_raw(d), raw) &&
        themer_stock68_identity_values_equal([d objectForKey:THEMER_STOCK68_JOURNAL_KEY], record[@"journal"]);
    if (!restored) return false;
    [d removeObjectForKey:THEMER_STOCK68_IDENTITY_RETIREMENT_KEY];
    bool cleared = [d synchronize] && [d objectForKey:THEMER_STOCK68_IDENTITY_RETIREMENT_KEY] == nil;
    if (!cleared) {
        [d setObject:record forKey:THEMER_STOCK68_IDENTITY_RETIREMENT_KEY];
        (void)[d synchronize];
    }
    printf("[ICONSERVICES_RECOVERY] identity-retirement rollback=%d recordCleared=%d\n", restored, cleared);
    return cleared;
}

static bool themer_stock68_retire_exact_identity(
    const ThemerSpotlightStock68JournalSnapshot *journal,
    const ThemerStock68V2IdentitySnapshot *expected,
    int currentPID, const char *cachePath)
{
    NSUserDefaults *d = NSUserDefaults.standardUserDefaults;
    NSDictionary *raw = themer_stock68_identity_raw(d);
    ThemerStock68V2IdentitySnapshot now =
        themer_spotlight_stock68_v2_identity_snapshot(journal, currentPID, cachePath);
    if (!themer_stock68_identity_snapshot_equal(expected, &now) ||
        [d objectForKey:THEMER_STOCK68_IDENTITY_RETIREMENT_KEY] != nil ||
        !themer_stock68_recovery_current_journal_matches(journal) ||
        themer_spotlight_iconservices_has_pending_recovery()) return false;
    if (now.classification == ThemerStock68V2IdentityAbsent) return true;
    if (now.classification != ThemerStock68V2IdentityBound) return false;
    id rawJournal = [d objectForKey:THEMER_STOCK68_JOURNAL_KEY];
    if (!rawJournal) return false;
    NSDictionary *record = @{@"version": @1, @"raw": raw, @"journal": rawJournal};
    [d setObject:record forKey:THEMER_STOCK68_IDENTITY_RETIREMENT_KEY];
    bool prepared = [d synchronize] &&
        themer_stock68_identity_values_equal([d objectForKey:THEMER_STOCK68_IDENTITY_RETIREMENT_KEY], record);
    ThemerStock68V2IdentitySnapshot preparedIdentity =
        themer_spotlight_stock68_v2_identity_snapshot(journal, currentPID, cachePath);
    if (!prepared || !themer_stock68_identity_snapshot_equal(expected, &preparedIdentity) ||
        !themer_stock68_identity_values_equal(themer_stock68_identity_raw(d), raw) ||
        !themer_stock68_recovery_current_journal_matches(journal) ||
        themer_spotlight_iconservices_has_pending_recovery()) return false;
    for (id key in raw) [d removeObjectForKey:key];
    bool removed = [d synchronize] && themer_stock68_identity_raw(d).count == 0;
    if (!removed) {
        (void)themer_spotlight_stock68_restore_interrupted_identity_retirement();
        return false;
    }
    // Keep the durable backup until the journal clear is acknowledged. A
    // crash at any intermediate point must preserve exact rollback evidence.
    return true;
}

bool themer_spotlight_stock68_finalize_empty_issued_after_clean_sessions(
    const ThemerSpotlightStock68JournalSnapshot *expectedJournal,
    const ThemerSpotlightStock68RecoveryInspectionReport *first,
    const ThemerSpotlightStock68RecoveryInspectionReport *second,
    int expectedCurrentPID)
{
    ThemerSpotlightStock68JournalSnapshot current =
        themer_spotlight_stock68_journal_snapshot();
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    bool v1LegacyIssued = expectedJournal &&
        expectedJournal->classification ==
            ThemerSpotlightStock68JournalLegacyIssuedAmbiguous &&
        expectedJournal->version == THEMER_STOCK68_JOURNAL_VERSION &&
        expectedJournal->present && expectedJournal->valid &&
        expectedJournal->issuedKnown && expectedJournal->issued &&
        !expectedJournal->dispatchPossibleKnown &&
        !expectedJournal->dispatchPossible &&
        !expectedJournal->transactionBound &&
        expectedJournal->phase[0] == '\0' &&
        themer_stock68_recovery_complete_journal(expectedJournal);
    bool v2DispatchPossible = expectedJournal &&
        expectedJournal->classification ==
            ThemerSpotlightStock68JournalDispatchPossible &&
        expectedJournal->version == THEMER_STOCK68_JOURNAL_V2_VERSION &&
        expectedJournal->present && expectedJournal->valid &&
        expectedJournal->issuedKnown && expectedJournal->issued &&
        expectedJournal->dispatchPossibleKnown &&
        expectedJournal->dispatchPossible &&
        expectedJournal->transactionBound &&
        strcmp(expectedJournal->phase, "dispatch-possible") == 0 &&
        themer_stock68_recovery_complete_journal(expectedJournal);
    bool issuedJournal = v1LegacyIssued || v2DispatchPossible;
    bool exactJournal = issuedJournal &&
        themer_stock68_snapshot_exact_equal(expectedJournal, &current);
    bool reportsMatch = exactJournal && expectedCurrentPID > 0 &&
        themer_spotlight_stock68_empty_recovery_reports_match(
            expectedJournal, first, second) &&
        first->currentPID == expectedCurrentPID &&
        expectedCurrentPID != expectedJournal->pid;
    bool noV2Identity = themer_stock68_v2_identity_absent(defaults);
    bool noCertificate =
        [defaults objectForKey:THEMER_STOCK68_ADOPTION_CERTIFICATE_KEY] == nil;
    bool noPendingRecovery = !themer_spotlight_iconservices_has_pending_recovery();
    bool retirementAbsent = [defaults objectForKey:THEMER_STOCK68_IDENTITY_RETIREMENT_KEY] == nil;
    ThemerStock68V2IdentitySnapshot durable = themer_spotlight_stock68_v2_identity_snapshot(
        expectedJournal, expectedCurrentPID, first ? first->managerCachePath : NULL);
    bool identityExact = reportsMatch &&
        themer_stock68_identity_snapshot_equal(&durable, &first->emptyIdentity.identity);
    bool allowed = reportsMatch && identityExact && noPendingRecovery && retirementAbsent;
    if (!allowed) {
        printf("[ICONSERVICES_RECOVERY] empty-finalize predicates reports=%d identityExact=%d pendingAbsent=%d retirementAbsent=%d\n",
            reportsMatch, identityExact, noPendingRecovery, retirementAbsent);
        printf("[ICONSERVICES_RECOVERY] empty-finalize class=%d "
               "issuedJournal=%d journalExact=%d reports=%d currentPID=%d "
               "oldPID=%d v2Absent=%d certificateAbsent=%d pendingAbsent=%d "
               "journalCleared=0 reason=proof-or-durable-state\n",
               expectedJournal ? expectedJournal->classification : -1,
               issuedJournal, exactJournal, reportsMatch, expectedCurrentPID,
               expectedJournal ? expectedJournal->pid : 0, noV2Identity,
               noCertificate, noPendingRecovery);
        return false;
    }

    // Recheck immediately before the only mutation.  The durable helper
    // restores the original journal if synchronize/readback does not prove
    // removal, so an uncertain clear remains fail-closed.
    bool journalUnchanged = themer_stock68_recovery_current_journal_matches(
        expectedJournal);
    NSDictionary *originalRaw = themer_stock68_identity_raw(defaults);
    id originalJournal = [defaults objectForKey:THEMER_STOCK68_JOURNAL_KEY];
    bool identityRetired = journalUnchanged && themer_stock68_retire_exact_identity(
        expectedJournal, &durable, expectedCurrentPID, first->managerCachePath);
    NSDictionary *expectedBackup = originalRaw.count && originalJournal
        ? @{@"version": @1, @"raw": originalRaw, @"journal": originalJournal} : nil;
    id actualBackup = [defaults objectForKey:THEMER_STOCK68_IDENTITY_RETIREMENT_KEY];
    bool backupExact = expectedBackup ? themer_stock68_identity_values_equal(actualBackup, expectedBackup) : actualBackup == nil;
    bool finalState = identityRetired && themer_stock68_v2_identity_absent(defaults) &&
        [defaults objectForKey:THEMER_STOCK68_ADOPTION_CERTIFICATE_KEY] == nil && backupExact &&
        !themer_spotlight_iconservices_has_pending_recovery() &&
        themer_stock68_identity_values_equal([defaults objectForKey:THEMER_STOCK68_JOURNAL_KEY], originalJournal) &&
        themer_stock68_recovery_current_journal_matches(expectedJournal);
    bool journalCleared = finalState && themer_stock68_local_journal_clear();
    if (journalCleared && expectedBackup) {
        [defaults removeObjectForKey:THEMER_STOCK68_IDENTITY_RETIREMENT_KEY];
        journalCleared = [defaults synchronize] &&
            [defaults objectForKey:THEMER_STOCK68_IDENTITY_RETIREMENT_KEY] == nil &&
            [defaults objectForKey:THEMER_STOCK68_JOURNAL_KEY] == nil &&
            themer_stock68_identity_raw(defaults).count == 0;
        if (!journalCleared) {
            [defaults setObject:expectedBackup forKey:THEMER_STOCK68_IDENTITY_RETIREMENT_KEY];
            (void)[defaults synchronize];
        }
    }
    if (!journalCleared && expectedBackup &&
        themer_stock68_identity_values_equal([defaults objectForKey:THEMER_STOCK68_IDENTITY_RETIREMENT_KEY], expectedBackup)) {
        (void)themer_spotlight_stock68_restore_interrupted_identity_retirement();
    }
    printf("[ICONSERVICES_RECOVERY] empty-finalize class=%d "
           "issuedJournal=%d journalExact=%d reports=%d currentPID=%d "
           "oldPID=%d v2Absent=%d certificateAbsent=%d pendingAbsent=%d "
           "journalUnchanged=%d journalCleared=%d reason=%s\n",
           expectedJournal->classification, issuedJournal, exactJournal,
           reportsMatch, expectedCurrentPID, expectedJournal->pid,
           noV2Identity, noCertificate, noPendingRecovery, journalUnchanged,
           journalCleared,
           journalCleared ? "dead-host-issued-empty" : "journal-retained");
    return journalCleared;
}

static bool themer_stock68_recovery_v2_identity_matches(
    NSUserDefaults *defaults,
    const ThemerStock68RecoveryIdentity *identity,
    const ThemerSpotlightStock68JournalSnapshot *journal,
    int currentPID)
{
    if (!defaults || !identity || !journal || currentPID <= 0 ||
        !identity->tokenData || !identity->uuid[0] || !identity->path[0] ||
        !identity->fileSHA256[0]) return false;
    return [[defaults stringForKey:THEMER_STOCK68_V2_UUID_KEY]
                isEqualToString:[NSString stringWithUTF8String:identity->uuid]] &&
        [[defaults dataForKey:THEMER_STOCK68_V2_TOKEN_KEY]
                isEqualToData:identity->tokenData] &&
        [[defaults objectForKey:THEMER_STOCK68_V2_PID_KEY] isEqual:@(currentPID)] &&
        [[defaults stringForKey:THEMER_STOCK68_V2_PATH_KEY]
                isEqualToString:[NSString stringWithUTF8String:identity->path]] &&
        [[defaults stringForKey:THEMER_STOCK68_V2_BUNDLE_KEY]
                isEqualToString:[NSString stringWithUTF8String:journal->targetBundle]] &&
        [[defaults stringForKey:THEMER_STOCK68_V2_FINGERPRINT_KEY]
                isEqualToString:[NSString stringWithUTF8String:journal->themeFingerprint]] &&
        [[defaults stringForKey:THEMER_STOCK68_V2_DIGEST_KEY]
                isEqualToString:[NSString stringWithUTF8String:journal->namedDigest]] &&
        [[defaults objectForKey:THEMER_STOCK68_V2_FILE_SIZE_KEY]
                isEqual:@(identity->fileSize)];
}

static NSDictionary *themer_stock68_recovery_adoption_certificate(
    const ThemerSpotlightStock68JournalSnapshot *journal,
    int currentPID,
    const ThemerStock68RecoveryIdentity *identity)
{
    if (!themer_stock68_recovery_complete_journal(journal) || currentPID <= 0 ||
        !identity || !identity->tokenData || !identity->uuid[0] ||
        !identity->path[0] || !identity->fileSHA256[0] ||
        !identity->tokenSHA256[0]) return nil;
    return @{
        @"version": @1,
        @"journalVersion": @(journal->version),
        @"journalClassification": @((int)journal->classification),
        @"oldPID": @(journal->pid),
        @"currentPID": @(currentPID),
        @"target": [NSString stringWithUTF8String:journal->targetBundle],
        @"fingerprint": [NSString stringWithUTF8String:journal->themeFingerprint],
        @"namedDigest": [NSString stringWithUTF8String:journal->namedDigest],
        @"generatedDigest": [NSString stringWithUTF8String:journal->generatedDigest],
        @"uuid": [NSString stringWithUTF8String:identity->uuid],
        @"path": [NSString stringWithUTF8String:identity->path],
        @"fileSize": @(identity->fileSize),
        @"fileSHA256": [NSString stringWithUTF8String:identity->fileSHA256],
        @"tokenSHA256": [NSString stringWithUTF8String:identity->tokenSHA256],
        @"token": identity->tokenData,
    };
}

static bool themer_stock68_recovery_certificate_matches(
    NSDictionary *certificate,
    const ThemerSpotlightStock68JournalSnapshot *journal,
    int currentPID,
    ThemerStock68RecoveryIdentity *identityOut)
{
    if (identityOut) *identityOut = (ThemerStock68RecoveryIdentity){0};
    if (![certificate isKindOfClass:NSDictionary.class] ||
        !themer_stock68_recovery_complete_journal(journal) || currentPID <= 0) {
        return false;
    }
    id version = certificate[@"version"];
    id journalVersion = certificate[@"journalVersion"];
    id journalClass = certificate[@"journalClassification"];
    id oldPID = certificate[@"oldPID"];
    id certificatePID = certificate[@"currentPID"];
    id target = certificate[@"target"];
    id fingerprint = certificate[@"fingerprint"];
    id namedDigest = certificate[@"namedDigest"];
    id generatedDigest = certificate[@"generatedDigest"];
    id uuid = certificate[@"uuid"];
    id path = certificate[@"path"];
    id fileSize = certificate[@"fileSize"];
    id fileHash = certificate[@"fileSHA256"];
    id tokenHash = certificate[@"tokenSHA256"];
    id token = certificate[@"token"];
    bool types = [version isEqual:@1] && [journalVersion isKindOfClass:NSNumber.class] &&
        [journalClass isKindOfClass:NSNumber.class] && [oldPID isKindOfClass:NSNumber.class] &&
        [certificatePID isKindOfClass:NSNumber.class] && [target isKindOfClass:NSString.class] &&
        [fingerprint isKindOfClass:NSString.class] && [namedDigest isKindOfClass:NSString.class] &&
        [generatedDigest isKindOfClass:NSString.class] && [uuid isKindOfClass:NSString.class] &&
        [path isKindOfClass:NSString.class] && [fileSize isKindOfClass:NSNumber.class] &&
        [fileHash isKindOfClass:NSString.class] && [tokenHash isKindOfClass:NSString.class] &&
        [token isKindOfClass:NSData.class] && [token length] > 0 &&
        [token length] <= THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP;
    if (!types || [journalVersion intValue] != journal->version ||
        [journalClass intValue] != (int)journal->classification ||
        [oldPID intValue] != journal->pid || [certificatePID intValue] != currentPID ||
        ![target isEqualToString:[NSString stringWithUTF8String:journal->targetBundle]] ||
        ![fingerprint isEqualToString:[NSString stringWithUTF8String:journal->themeFingerprint]] ||
        ![namedDigest isEqualToString:[NSString stringWithUTF8String:journal->namedDigest]] ||
        ![generatedDigest isEqualToString:[NSString stringWithUTF8String:journal->generatedDigest]] ||
        [uuid length] == 0 || [uuid length] >= 80 || [path length] == 0 ||
        [path length] >= 512 || [fileSize unsignedLongLongValue] == 0 ||
        [fileHash length] != 64 || [tokenHash length] != 64) {
        return false;
    }
    uint8_t uuidBytes[16] = {0};
    if (!themer_iconservices_lab_parse_uuid_text([uuid UTF8String], uuidBytes)) return false;
    uint8_t tokenDigest[32] = {0};
    char tokenDigestText[65] = {0};
    bool tokenDigestKnown = themer_iconservices_lab_digest(
        "CC_SHA256", [token bytes], [token length], tokenDigest);
    if (tokenDigestKnown) themer_iconservices_lab_hex_bytes(
        tokenDigest, sizeof(tokenDigest), tokenDigestText, sizeof(tokenDigestText));
    if (!tokenDigestKnown || ![tokenHash isEqualToString:
                               [NSString stringWithUTF8String:tokenDigestText]]) {
        return false;
    }
    if (identityOut) {
        identityOut->tokenData = token;
        identityOut->fileSize = [fileSize unsignedLongLongValue];
        snprintf(identityOut->uuid, sizeof(identityOut->uuid), "%s", [uuid UTF8String]);
        snprintf(identityOut->path, sizeof(identityOut->path), "%s", [path UTF8String]);
        snprintf(identityOut->fileSHA256, sizeof(identityOut->fileSHA256), "%s", [fileHash UTF8String]);
        snprintf(identityOut->tokenSHA256, sizeof(identityOut->tokenSHA256), "%s", [tokenHash UTF8String]);
    }
    return true;
}

static bool themer_stock68_recovery_persist_adoption(
    const ThemerSpotlightStock68JournalSnapshot *journal,
    int currentPID,
    const ThemerStock68RecoveryIdentity *identity)
{
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    NSDictionary *certificate = themer_stock68_recovery_adoption_certificate(
        journal, currentPID, identity);
    if (!certificate || !themer_stock68_recovery_current_journal_matches(
            journal)) {
        return false;
    }
    // These are the only resolver mutations: the complete V2 identity and its
    // adoption certificate.  The old issued journal is deliberately untouched.
    [defaults setObject:[NSString stringWithUTF8String:identity->uuid]
                 forKey:THEMER_STOCK68_V2_UUID_KEY];
    [defaults setObject:identity->tokenData forKey:THEMER_STOCK68_V2_TOKEN_KEY];
    [defaults setObject:@(currentPID) forKey:THEMER_STOCK68_V2_PID_KEY];
    [defaults setObject:[NSString stringWithUTF8String:identity->path]
                 forKey:THEMER_STOCK68_V2_PATH_KEY];
    [defaults setObject:[NSString stringWithUTF8String:journal->targetBundle]
                 forKey:THEMER_STOCK68_V2_BUNDLE_KEY];
    [defaults setObject:[NSString stringWithUTF8String:journal->themeFingerprint]
                 forKey:THEMER_STOCK68_V2_FINGERPRINT_KEY];
    [defaults setObject:[NSString stringWithUTF8String:journal->namedDigest]
                 forKey:THEMER_STOCK68_V2_DIGEST_KEY];
    [defaults setObject:@(identity->fileSize) forKey:THEMER_STOCK68_V2_FILE_SIZE_KEY];
    bool identitySynchronized = [defaults synchronize] &&
        themer_stock68_recovery_v2_identity_matches(defaults, identity, journal, currentPID);
    if (!identitySynchronized) return false;
    [defaults setObject:certificate forKey:THEMER_STOCK68_ADOPTION_CERTIFICATE_KEY];
    bool certificateSynchronized = [defaults synchronize] &&
        [[defaults objectForKey:THEMER_STOCK68_ADOPTION_CERTIFICATE_KEY]
            isEqual:certificate] &&
        themer_stock68_recovery_v2_identity_matches(defaults, identity, journal, currentPID) &&
        themer_stock68_recovery_current_journal_matches(journal);
    printf("[ICONSERVICES_RECOVERY] adoption persist pid=%d identity=%d "
           "certificate=%d journalRetained=%d\n", currentPID,
           identitySynchronized, certificateSynchronized,
           themer_stock68_recovery_current_journal_matches(journal));
    return certificateSynchronized;
}

ThemerSpotlightStock68RecoveryInspectionResult
themer_spotlight_stock68_resolve_issued_generation_in_session(
    const ThemerSpotlightStock68JournalSnapshot *expectedJournal,
    int expectedPID,
    uint64_t expectedProc,
    uint64_t expectedTask,
    bool ownerExitProven,
    ThemerSpotlightStock68RecoveryInspectionReport *reportOut)
{
    ThemerStock68RecoveryIdentity identity = {0};
    ThemerSpotlightStock68RecoveryInspectionReport report = {0};
    ThemerSpotlightStock68RecoveryInspectionResult result =
        themer_stock68_recovery_inspect_common(
            expectedJournal, expectedPID, expectedProc, expectedTask,
            ownerExitProven, &report, &identity);
    if (result != ThemerSpotlightStock68RecoveryInspectionCandidateValidated ||
        !report.adoptionEligible || !themer_stock68_recovery_complete_journal(expectedJournal) ||
        !remote_call_current_success()) {
        if (reportOut) *reportOut = report;
        return result;
    }
    bool persisted = themer_stock68_recovery_persist_adoption(
        expectedJournal, report.currentPID, &identity);
    report.adoptionPersisted = persisted;
    if (!persisted) {
        result = remote_call_current_success()
            ? ThemerSpotlightStock68RecoveryInspectionRejected
            : ThemerSpotlightStock68RecoveryInspectionTransportFailed;
        report.adoptionEligible = false;
        snprintf(report.reason, sizeof(report.reason), "%s",
                 "adoption-persist-or-journal-binding");
    }
    report.result = result;
    printf("[ICONSERVICES_RECOVERY] resolve verdict=%d persisted=%d pid=%d\n",
           result, persisted, report.currentPID);
    if (reportOut) *reportOut = report;
    return result;
}

bool themer_spotlight_stock68_finalize_resolved_generation_after_clean_close(
    const ThemerSpotlightStock68JournalSnapshot *expectedJournal,
    int expectedCurrentPID)
{
    // This intentionally has no RemoteCall activity.  Settings supplies the
    // clean-close proof; here we only compare durable records and clear them
    // in the recoverable order certificate -> issued generation journal.
    ThemerSpotlightStock68JournalSnapshot current =
        themer_spotlight_stock68_journal_snapshot();
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    ThemerStock68RecoveryIdentity identity = {0};
    NSDictionary *certificate = [defaults objectForKey:
        THEMER_STOCK68_ADOPTION_CERTIFICATE_KEY];
    bool exactJournal = themer_stock68_recovery_complete_journal(expectedJournal) &&
        themer_stock68_snapshot_exact_equal(expectedJournal, &current);
    bool certificateBound = exactJournal && themer_stock68_recovery_certificate_matches(
        certificate, expectedJournal, expectedCurrentPID, &identity);
    bool identityBound = certificateBound && themer_stock68_recovery_v2_identity_matches(
        defaults, &identity, expectedJournal, expectedCurrentPID);
    if (!exactJournal || !certificateBound || !identityBound) {
        printf("[ICONSERVICES_RECOVERY] finalize retained journal=%d certificate=%d "
               "identity=%d pid=%d\n", exactJournal, certificateBound,
               identityBound, expectedCurrentPID);
        return false;
    }
    [defaults removeObjectForKey:THEMER_STOCK68_ADOPTION_CERTIFICATE_KEY];
    bool certificateCleared = [defaults synchronize] &&
        [defaults objectForKey:THEMER_STOCK68_ADOPTION_CERTIFICATE_KEY] == nil;
    if (!certificateCleared) {
        // Restore the exact certificate if durable removal was not proven; the
        // generation journal is untouched in either outcome.
        [defaults setObject:certificate forKey:THEMER_STOCK68_ADOPTION_CERTIFICATE_KEY];
        (void)[defaults synchronize];
        printf("[ICONSERVICES_RECOVERY] finalize retained reason=certificate-clear\n");
        return false;
    }
    bool journalUnchanged = themer_stock68_recovery_current_journal_matches(
        expectedJournal);
    bool journalCleared = journalUnchanged && themer_stock68_local_journal_clear();
    if (!journalCleared) {
        // Keep an admission marker and the exact retry evidence when the
        // final durable journal removal was not acknowledged.
        [defaults setObject:certificate
                     forKey:THEMER_STOCK68_ADOPTION_CERTIFICATE_KEY];
        (void)[defaults synchronize];
    }
    printf("[ICONSERVICES_RECOVERY] finalize certificateCleared=%d journalExact=%d "
           "journalCleared=%d certificateRestored=%d\n", certificateCleared,
           journalUnchanged, journalCleared,
           !journalCleared &&
               [defaults objectForKey:
                   THEMER_STOCK68_ADOPTION_CERTIFICATE_KEY] != nil);
    return journalCleared;
}

static bool themer_stock68_exact_bag_setter_abi(uint64_t cache,
                                                char *types,
                                                size_t typesLen)
{
    if (types && typesLen) types[0] = '\0';
    if (!r_is_objc_ptr(cache) || !types || typesLen == 0 ||
        !remote_call_current_success() ||
        !r_responds_main(cache, "setImageBagsByDescriptor:") ||
        !themer_iconservices_lab_method_types(
            cache, "setImageBagsByDescriptor:", types, typesLen)) {
        return false;
    }
    return strcmp(types, "v24@0:8@16") == 0 &&
        remote_call_current_success();
}

static bool themer_stock68_restore_materialization_state(uint64_t state)
{
    if (!r_is_objc_ptr(state) || !remote_call_current_success()) return false;
    uint64_t cache = themer_spotlight_dictionary_object(state, "cache");
    uint64_t originalBags = themer_spotlight_dictionary_object(
        state, "originalBags");
    uint64_t originalCount = 0;
    char baselineFingerprint[THEMER_STOCK68_FINGERPRINT_CAP] = {0};
    bool stateReady = themer_spotlight_proof_state_u64(
            state, "originalCount", &originalCount) &&
        themer_spotlight_proof_state_string(
            state, "baselineFingerprint", baselineFingerprint,
            sizeof(baselineFingerprint)) &&
        r_is_objc_ptr(cache) && r_is_objc_ptr(originalBags) &&
        originalCount <= INT_MAX;
    if (!stateReady || !remote_call_current_success()) return false;

    char setterTypes[192] = {0};
    bool setterABI = themer_stock68_exact_bag_setter_abi(
        cache, setterTypes, sizeof(setterTypes));
    printf("[ICONSERVICES_MATERIALIZE] restore setter-abi types=\"%s\" "
           "ready=%d\n", setterTypes, setterABI);
    if (!setterABI) return false;

    // The retained original dictionary and every shared bag/image must still
    // be exactly the baseline. If any caller mutated the shared object, do not
    // repair from a private copy and do not invoke the setter at all.
    ThemerIconServicesLabTopologySnapshot current = {0};
    char currentFingerprint[THEMER_STOCK68_FINGERPRINT_CAP] = {0};
    bool currentCaptured = themer_stock68_capture_strict_dictionary(
        originalBags, "materialization-restore-before", &current);
    bool currentFingerprintKnown = currentCaptured &&
        themer_stock68_strict_fingerprint(
            &current, currentFingerprint, sizeof(currentFingerprint));
    bool exactBaseline = currentFingerprintKnown &&
        current.dictionary == originalBags &&
        current.dictionaryCount == (int)originalCount &&
        strcmp(currentFingerprint, baselineFingerprint) == 0;
    printf("[ICONSERVICES_MATERIALIZE] restore precondition exact=%d "
           "currentDictionary=0x%llx original=0x%llx currentFingerprint=\"%s\" "
           "baseline=\"%s\"\n",
           exactBaseline,
           (unsigned long long)current.dictionary,
           (unsigned long long)originalBags,
           currentFingerprintKnown ? currentFingerprint : "-",
           baselineFingerprint[0] ? baselineFingerprint : "-");
    if (!exactBaseline || !remote_call_current_success()) return false;

    r_msg2_main(cache, "setImageBagsByDescriptor:",
                originalBags, 0, 0, 0);
    if (!remote_call_current_success()) return false;

    ThemerIconServicesLabTopologySnapshot restored = {0};
    char restoredFingerprint[THEMER_STOCK68_FINGERPRINT_CAP] = {0};
    bool restoredCaptured = themer_stock68_capture_strict_topology(
        cache, "materialization-restored", &restored);
    bool restoredFingerprintKnown = restoredCaptured &&
        themer_stock68_strict_fingerprint(
            &restored, restoredFingerprint, sizeof(restoredFingerprint));
    bool topologyRestored = restoredFingerprintKnown &&
        restored.dictionary == originalBags &&
        restored.dictionaryCount == (int)originalCount &&
        strcmp(baselineFingerprint, restoredFingerprint) == 0;
    printf("[ICONSERVICES_MATERIALIZE] rollback verify dictionary=%d "
           "topology=%d expected=\"%s\" actual=\"%s\" stateRetained=1\n",
           restored.dictionary == originalBags,
           topologyRestored,
           baselineFingerprint,
           restoredFingerprintKnown ? restoredFingerprint : "-");
    // Keep the recovery state and local journal until the caller has proved
    // the complete recovery transaction. This also makes emergency restore
    // retryable after a transient failure.
    return topologyRestored && remote_call_current_success();
}

bool themer_spotlight_stock68_materialization_has_state_in_session(void)
{
    return remote_call_current_success() &&
        r_is_objc_ptr(themer_stock68_materialization_state());
}

static bool themer_stock68_topology_exactly_empty(
    const ThemerIconServicesLabTopologySnapshot *snapshot)
{
    return snapshot && snapshot->captured && !snapshot->keysTruncated &&
        snapshot->dictionaryCountKnown && snapshot->keyCountKnown &&
        snapshot->actualKeyCountKnown && snapshot->totalEntryCountKnown &&
        snapshot->dictionaryCount == 0 && snapshot->keyCount == 0 &&
        snapshot->actualKeyCount == 0 && snapshot->totalEntryCount == 0;
}

typedef struct {
    bool ready;
    int pid;
    uint64_t proc;
    uint64_t task;
    char journalSHA256[65];
} ThemerStock68RegistrationCloseProof;
static ThemerStock68RegistrationCloseProof gStock68RegistrationCloseProof;

static bool themer_stock68_registration_abi(uint64_t receiver, const char *selector,
                                             const char *expected)
{
    char types[192] = {0};
    bool exact = remote_call_current_success() && r_is_objc_ptr(receiver) &&
        r_responds_main(receiver, selector) &&
        themer_iconservices_lab_method_types(receiver, selector, types, sizeof(types)) &&
        strcmp(types, expected) == 0 && remote_call_current_success();
    if (!exact) printf("[ICONSERVICES_MATERIALIZE] store-registration ABI selector=%s actual=\"%s\" expected=\"%s\" healthy=%d\n",
        selector, types, expected, remote_call_current_success());
    return exact;
}

static bool themer_stock68_registration_unit_abi(uint64_t unit)
{
    char name[96] = {0};
    char types[4][192] = {{0}};
    const char *selectors[] = {"initWithData:UUID:", "UUID", "data", "isValid"};
    const char *expected[] = {"@32@0:8@16@24", "@16@0:8", "@16@0:8", "B16@0:8"};
    if (r_is_objc_ptr(unit)) themer_read_class_name(unit, name, sizeof(name));
    bool exact = r_is_objc_ptr(unit) && strcmp(name, "ISStoreUnit") == 0;
    for (unsigned i = 0; i < 4 && exact; i++) {
        exact = remote_call_current_success() && r_responds_main(unit, selectors[i]) &&
            themer_iconservices_lab_method_types(unit, selectors[i], types[i], sizeof(types[i])) &&
            strcmp(types[i], expected[i]) == 0 && remote_call_current_success();
    }
    printf("[ICONSERVICES_MATERIALIZE] store-registration unit-ABI class=%s init=\"%s\" UUID=\"%s\" data=\"%s\" isValid=\"%s\" exact=%d healthy=%d\n",
        name, types[0], types[1], types[2], types[3], exact, remote_call_current_success());
    return exact;
}

// Resolve and gate the concrete high-level store. The path comparison uses
// real directories, so /var aliases cannot direct the write outside the cache.
static uint64_t themer_stock68_registration_store(uint64_t managerCache,
                                                   const char *cachePath)
{
    uint64_t store = themer_stock68_absence_getter(managerCache, "store");
    char name[96] = {0}, actualPath[512] = {0};
    char expectedReal[PATH_MAX] = {0}, actualReal[PATH_MAX] = {0};
    if (r_is_objc_ptr(store)) themer_read_class_name(store, name, sizeof(name));
    bool exact = r_is_objc_ptr(store) && strcmp(name, "ISStore") == 0 &&
        themer_stock68_registration_abi(store, "storeURL", "@16@0:8") &&
        themer_stock68_registration_abi(store, "writeStoreUnit:", "B24@0:8@16") &&
        themer_stock68_registration_abi(store, "unitForUUID:", "@24@0:8@16") &&
        themer_stock68_registration_abi(store, "removeUnitForUUID:", "B24@0:8@16");
    uint64_t url = exact ? themer_stock68_absence_getter(store, "storeURL") : 0;
    uint64_t path = r_is_objc_ptr(url) ? themer_stock68_absence_getter(url, "path") : 0;
    struct stat st = {0};
    bool pathBound = path && r_read_nsstring(path, actualPath, sizeof(actualPath)) &&
        cachePath && realpath(cachePath, expectedReal) && realpath(actualPath, actualReal) &&
        strcmp(expectedReal, actualReal) == 0 && stat(expectedReal, &st) == 0 && S_ISDIR(st.st_mode);
    printf("[ICONSERVICES_MATERIALIZE] store-registration preflight storeClass=%s ABI=%d pathBound=%d healthy=%d\n",
        name, exact, pathBound, remote_call_current_success());
    return exact && pathBound && remote_call_current_success() ? store : 0;
}

static bool themer_stock68_registration_preflight(uint64_t managerCache, const char *cachePath)
{
    uint64_t store = themer_stock68_registration_store(managerCache, cachePath);
    uint64_t cls = store ? themer_lookup_class("ISStoreUnit") : 0;
    uint64_t unit = r_is_objc_ptr(cls) ? r_msg2_main(cls, "alloc", 0, 0, 0, 0) : 0;
    bool ready = themer_stock68_registration_unit_abi(unit);
    if (r_is_objc_ptr(unit) && remote_call_current_success()) r_msg2(unit, "release", 0, 0, 0, 0);
    return ready && remote_call_current_success();
}

static bool themer_stock68_registration_persist(NSDictionary *expected, NSDictionary *record)
{
    NSUserDefaults *d = NSUserDefaults.standardUserDefaults;
    NSDictionary *current = themer_stock68_local_journal_dictionary();
    if (!current || !themer_stock68_identity_values_equal(current, expected) ||
        !themer_stock68_registration_valid(record, current)) return false;
    NSDictionary *prior = current[@"storeRegistration"];
    if (prior) {
        NSMutableDictionary *oldIdentity = [prior mutableCopy], *newIdentity = [record mutableCopy];
        [oldIdentity removeObjectForKey:@"phase"]; [newIdentity removeObjectForKey:@"phase"];
        int oldPhase = themer_stock68_registration_phase(prior[@"phase"]);
        int newPhase = themer_stock68_registration_phase(record[@"phase"]);
        if (!themer_stock68_identity_values_equal(oldIdentity, newIdentity) || newPhase < oldPhase ||
            (newPhase != oldPhase && newPhase != oldPhase + 1 && newPhase != 3)) return false;
    } else if (themer_stock68_registration_phase(record[@"phase"]) != 0) return false;
    NSMutableDictionary *updated = [current mutableCopy];
    updated[@"storeRegistration"] = record;
    [d setObject:updated forKey:THEMER_STOCK68_JOURNAL_KEY];
    bool synced = [d synchronize];
    bool exact = synced && themer_stock68_identity_values_equal(
        [d objectForKey:THEMER_STOCK68_JOURNAL_KEY], updated) && themer_stock68_local_journal_dictionary();
    // Never roll back this nested phase: a dispatch may already have happened.
    printf("[ICONSERVICES_MATERIALIZE] store-registration phase=%s persisted=%d transaction=%s\n",
        [record[@"phase"] UTF8String], exact, [record[@"transaction"] UTF8String]);
    return exact;
}

static bool themer_stock68_registration_advance(NSString *phase)
{
    NSDictionary *journal = themer_stock68_local_journal_dictionary();
    if (!journal[@"storeRegistration"]) return false;
    NSMutableDictionary *record = [journal[@"storeRegistration"] mutableCopy];
    record[@"phase"] = phase;
    return themer_stock68_registration_persist(journal, record);
}

static bool themer_stock68_registration_absent(uint64_t store, uint64_t uuid, NSString *path)
{
    if (!r_is_objc_ptr(store) || !r_is_objc_ptr(uuid) || !remote_call_current_success()) return false;
    struct stat st = {0};
    errno = 0;
    int result = lstat(path.fileSystemRepresentation, &st);
    int fileError = result == -1 ? errno : 0;
    bool absent = result == -1 && fileError == ENOENT;
    uint64_t raw = r_msg2_main(store, "unitForUUID:", uuid, 0, 0, 0);
    printf("[ICONSERVICES_MATERIALIZE] store-registration absence fileAbsent=%d fileResult=%d fileErrno=%d storeNil=%d healthy=%d\n",
        absent, result, fileError, raw == 0, remote_call_current_success());
    return absent && raw == 0 && remote_call_current_success();
}

static NSData *themer_stock68_registration_file(NSDictionary *record, bool *absent)
{
    if (absent) *absent = false;
    NSString *path = record[@"path"];
    struct stat before = {0}, after = {0}, named = {0};
    errno = 0;
    int fd = open(path.fileSystemRepresentation, O_RDONLY | O_NOFOLLOW | O_NONBLOCK);
    if (fd == -1) {
        if (absent) *absent = errno == ENOENT;
        return nil;
    }
    NSUInteger length = [record[@"dataSize"] unsignedIntegerValue];
    bool exact = fstat(fd, &before) == 0 && S_ISREG(before.st_mode) &&
        before.st_size == (off_t)length && length > 0 && length <= (1U << 20);
    NSMutableData *data = exact ? [NSMutableData dataWithLength:length] : nil;
    size_t offset = 0;
    while (data && offset < length) {
        ssize_t count = read(fd, (uint8_t *)data.mutableBytes + offset, length - offset);
        if (count < 0 && errno == EINTR) continue;
        if (count <= 0) break;
        offset += (size_t)count;
    }
    uint8_t extra;
    exact = exact && data && offset == length && read(fd, &extra, 1) == 0 &&
        fstat(fd, &after) == 0 && lstat(path.fileSystemRepresentation, &named) == 0 &&
        S_ISREG(named.st_mode) && before.st_dev == after.st_dev && before.st_ino == after.st_ino &&
        before.st_size == after.st_size && before.st_dev == named.st_dev && before.st_ino == named.st_ino &&
        named.st_size == before.st_size && [data isEqualToData:record[@"data"]] &&
        [themer_stock68_registration_hash(data) isEqual:record[@"dataSHA256"]];
    close(fd);
    return exact ? data : nil;
}

static bool themer_stock68_registration_unit_exact(uint64_t unit, uint64_t uuid, NSDictionary *record)
{
    bool abi = themer_stock68_registration_unit_abi(unit);
    if (!abi) {
        printf("[ICONSERVICES_MATERIALIZE] store-registration unit-exact ABI=0 healthy=%d\n", remote_call_current_success());
        return false;
    }
    uint64_t actualUUID = r_msg2_main(unit, "UUID", 0, 0, 0, 0);
    bool uuidTransport = remote_call_current_success();
    uint64_t data = r_msg2_main(unit, "data", 0, 0, 0, 0);
    bool dataTransport = remote_call_current_success();
    uint64_t valid = r_msg2_main(unit, "isValid", 0, 0, 0, 0);
    bool validTransport = remote_call_current_success();
    ThemerIconServicesLabDataCapture capture = {0};
    bool uuidEqual = valid == 1 && validTransport &&
        r_is_objc_ptr(actualUUID) && themer_iconservices_lab_objects_equal(actualUUID, uuid);
    bool captured = uuidEqual &&
        themer_stock68_recovery_capture_exact_data(data, 1U << 20, &capture);
    NSData *bytes = captured ? [NSData dataWithBytes:capture.bytes length:capture.objectLength] : nil;
    bool bytesEqual = bytes && [bytes isEqual:record[@"data"]];
    bool hashEqual = bytesEqual && [themer_stock68_registration_hash(bytes) isEqual:record[@"dataSHA256"]];
    bool exact = hashEqual && remote_call_current_success();
    printf("[ICONSERVICES_MATERIALIZE] store-registration unit-exact ABI=%d UUIDTransport=%d UUIDPointer=%d UUIDEqual=%d dataTransport=%d dataPointer=%d validRaw=%llu validTransport=%d captured=%d length=%llu expectedLength=%llu bytesEqual=%d hashEqual=%d exact=%d healthy=%d\n",
        abi, uuidTransport, r_is_objc_ptr(actualUUID), uuidEqual, dataTransport, r_is_objc_ptr(data),
        (unsigned long long)valid, validTransport, captured, (unsigned long long)capture.objectLength,
        (unsigned long long)[record[@"data"] length], bytesEqual, hashEqual, exact, remote_call_current_success());
    themer_iconservices_lab_free_data_capture(&capture);
    return exact;
}

static bool themer_stock68_registration_reconstruction(uint64_t data, uint64_t uuid, uint64_t token)
{
    uint64_t image = themer_iconservices_lab_make_if_cache_image(data, uuid, token);
    char name[96] = {0};
    if (r_is_objc_ptr(image)) themer_read_class_name(image, name, sizeof(name));
    bool exact = r_is_objc_ptr(image) && strcmp(name, "IFCacheImage") == 0 &&
        themer_stock68_registration_abi(image, "uuid", "@16@0:8") &&
        themer_stock68_registration_abi(image, "validationToken", "@16@0:8");
    uint64_t actualUUID = exact ? r_msg2_main(image, "uuid", 0, 0, 0, 0) : 0;
    uint64_t actualToken = exact ? r_msg2_main(image, "validationToken", 0, 0, 0, 0) : 0;
    double w = 0, h = 0;
    exact = exact && r_is_objc_ptr(actualUUID) && r_is_objc_ptr(actualToken) &&
        themer_iconservices_lab_objects_equal(actualUUID, uuid) &&
        themer_iconservices_lab_objects_equal(actualToken, token) &&
        themer_iconservices_lab_image_geometry_matches(image, 68, 68, 3) &&
        themer_iconservices_lab_read_size_property(image, "pixelSize", &w, &h) && w == 204 && h == 204;
    if (r_is_objc_ptr(image) && remote_call_current_success()) r_msg2(image, "release", 0, 0, 0, 0);
    return exact && remote_call_current_success();
}

static bool themer_stock68_registration_no_other_recovery(void)
{
    NSUserDefaults *d = NSUserDefaults.standardUserDefaults;
    return themer_stock68_identity_raw(d).count == 0 &&
        [d objectForKey:THEMER_STOCK68_IDENTITY_RETIREMENT_KEY] == nil &&
        !themer_spotlight_iconservices_has_pending_recovery() &&
        !themer_spotlight_iconservices_has_state_in_session() && remote_call_current_success();
}

static bool themer_stock68_registration_dictionary(NSDictionary *record, uint64_t state,
    ThemerStock68MaterializationContext *context, bool sameOwner)
{
    if (sameOwner && r_is_objc_ptr(state)) {
        uint64_t pid = 0, originalCount = UINT64_MAX;
        char target[192] = {0}, fingerprint[65] = {0};
        uint64_t original = themer_spotlight_dictionary_object(state, "originalBags");
        uint64_t cache = themer_spotlight_dictionary_object(state, "cache");
        if (!themer_spotlight_proof_state_u64(state, "pid", &pid) || pid != [record[@"pid"] unsignedLongLongValue] ||
            !themer_spotlight_proof_state_u64(state, "originalCount", &originalCount) || originalCount != 0 ||
            !themer_spotlight_proof_state_string(state, "targetBundle", target, sizeof(target)) ||
            !themer_spotlight_proof_state_string(state, "themeFingerprint", fingerprint, sizeof(fingerprint)) ||
            strcmp(target, [record[@"target"] UTF8String]) || strcmp(fingerprint, [record[@"fingerprint"] UTF8String]) ||
            original != [record[@"originalDictionary"] unsignedLongLongValue] || cache != context->canonicalCache ||
            !themer_stock68_restore_materialization_state(state)) return false;
    } else if (sameOwner && themer_stock68_registration_phase(record[@"phase"]) != 4) {
        return false;
    } else if (!sameOwner && state != 0) {
        return false;
    }
    ThemerIconServicesLabTopologySnapshot topology = {0};
    char fingerprint[THEMER_STOCK68_FINGERPRINT_CAP] = {0};
    bool exact = themer_stock68_capture_strict_topology(context->canonicalCache,
        "store-registration-restored-empty", &topology) && themer_stock68_topology_exactly_empty(&topology) &&
        themer_stock68_strict_fingerprint(&topology, fingerprint, sizeof(fingerprint));
    // Numeric persisted addresses are compared only to freshly returned live
    // objects. Replacement owners never use an old address as a receiver.
    return exact && (!sameOwner ||
        (topology.dictionary == [record[@"originalDictionary"] unsignedLongLongValue] &&
         strcmp(fingerprint, [record[@"baselineFingerprint"] UTF8String]) == 0)) && remote_call_current_success();
}

bool themer_spotlight_stock68_recover_store_registration_in_session(
    bool oldOwnerExitProven, int expectedPID, uint64_t expectedProc, uint64_t expectedTask)
{
    memset(&gStock68RegistrationCloseProof, 0, sizeof(gStock68RegistrationCloseProof));
    NSDictionary *journal = themer_stock68_local_journal_dictionary();
    NSDictionary *record = journal[@"storeRegistration"];
    if (!record || !themer_stock68_registration_valid(record, journal) ||
        expectedPID != [record[@"pid"] intValue] ||
        expectedProc != [record[@"proc"] unsignedLongLongValue] ||
        expectedTask != [record[@"task"] unsignedLongLongValue] ||
        !themer_stock68_registration_no_other_recovery()) return false;
    int pid = remote_call_current_pid();
    uint64_t proc = remote_call_current_proc(), task = remote_call_current_task();
    bool sameOwner = pid == [record[@"pid"] intValue] &&
        proc == [record[@"proc"] unsignedLongLongValue] && task == [record[@"task"] unsignedLongLongValue];
    if (!sameOwner && !oldOwnerExitProven) return false;
    ThemerStock68MaterializationContext context = {0};
    bool ready = themer_stock68_acquire_context([record[@"target"] UTF8String], &context);
    char canonicalPath[PATH_MAX] = {0};
    ready = ready && realpath(context.managerCachePath, canonicalPath) &&
        strcmp(canonicalPath, [record[@"cachePath"] UTF8String]) == 0 &&
        strcmp(context.namedDigest, [record[@"namedDigest"] UTF8String]) == 0 && context.namedScale == 3;
    uint64_t state = ready ? themer_stock68_materialization_state() : UINT64_MAX;
    ready = ready && remote_call_current_success() &&
        themer_stock68_registration_dictionary(record, state, &context, sameOwner) &&
        themer_stock68_identity_values_equal(journal, themer_stock68_local_journal_dictionary());
    uint64_t store = ready ? themer_stock68_registration_store(context.managerCache, canonicalPath) : 0;
    uint64_t uuid = store ? themer_iconservices_lab_make_remote_uuid(record[@"uuid"]) : 0;
    uint64_t unit = r_is_objc_ptr(uuid) ? r_msg2_main(store, "unitForUUID:", uuid, 0, 0, 0) : UINT64_MAX;
    bool fileAbsent = false;
    NSData *file = ready && store && r_is_objc_ptr(uuid)
        ? themer_stock68_registration_file(record, &fileAbsent) : nil;
    bool owned = ready && remote_call_current_success() && unit != 0 &&
        themer_stock68_registration_unit_exact(unit, uuid, record) && (file || fileAbsent);
    bool absent = ready && unit == 0 && fileAbsent && remote_call_current_success();
    // A file without a healthy unit cannot be claimed or unlinked. A present
    // unit and any present file must independently match the journal bytes.
    bool clean = false;
    if ((owned || absent) && remote_call_current_pid() == pid &&
        remote_call_current_proc() == proc && remote_call_current_task() == task &&
        themer_stock68_registration_no_other_recovery() &&
        themer_stock68_identity_values_equal(journal, themer_stock68_local_journal_dictionary())) {
        int phase = themer_stock68_registration_phase(record[@"phase"]);
        bool marked = phase == 4 || themer_stock68_registration_advance(@"cleanup-required");
        if (marked && owned && phase != 4 && remote_call_current_success()) {
            uint64_t removed = r_msg2_main(store, "removeUnitForUUID:", uuid, 0, 0, 0);
            clean = removed == 1 && remote_call_current_success() &&
                themer_stock68_registration_absent(store, uuid, record[@"path"]);
        } else if (marked && absent) {
            clean = themer_stock68_registration_absent(store, uuid, record[@"path"]);
        }
        clean = clean && themer_stock68_registration_dictionary(record, state, &context, sameOwner) &&
            (phase == 4 || themer_stock68_registration_advance(@"cleanup-verified"));
        if (clean && r_is_objc_ptr(state)) clean = themer_stock68_materialization_clear_state();
        if (clean) clean = themer_stock68_materialization_state() == 0 && remote_call_current_success();
    }
    if (r_is_objc_ptr(uuid) && remote_call_current_success()) r_msg2(uuid, "release", 0, 0, 0, 0);
    themer_stock68_release_context(&context);
    clean = clean && remote_call_current_success() && remote_call_current_pid() == pid &&
        remote_call_current_proc() == proc && remote_call_current_task() == task;
    if (clean) {
        NSDictionary *current = themer_stock68_local_journal_dictionary();
        NSDictionary *finalRecord = current[@"storeRegistration"];
        NSMutableDictionary *expected = [record mutableCopy]; expected[@"phase"] = @"cleanup-verified";
        clean = current && themer_stock68_identity_values_equal(expected, finalRecord);
        if (clean) {
            gStock68RegistrationCloseProof.ready = true;
            gStock68RegistrationCloseProof.pid = pid; gStock68RegistrationCloseProof.proc = proc;
            gStock68RegistrationCloseProof.task = task;
            snprintf(gStock68RegistrationCloseProof.journalSHA256, sizeof(gStock68RegistrationCloseProof.journalSHA256),
                "%s", themer_stock68_registration_raw_hash(current).UTF8String ?: "");
        }
    }
    printf("[ICONSERVICES_RECOVERY] store-registration sameOwner=%d oldOwnerExit=%d dictionary=%d unitOwned=%d absent=%d cleanup=%d journalRetained=1\n",
        sameOwner, oldOwnerExitProven, ready, owned, absent, clean);
    return clean;
}

bool themer_spotlight_stock68_finalize_store_registration_after_clean_close(
    bool cleanClose, int pid, uint64_t proc, uint64_t task)
{
    ThemerStock68RegistrationCloseProof proof = gStock68RegistrationCloseProof;
    memset(&gStock68RegistrationCloseProof, 0, sizeof(gStock68RegistrationCloseProof));
    NSDictionary *journal = themer_stock68_local_journal_dictionary();
    NSDictionary *record = journal[@"storeRegistration"];
    if (!cleanClose || !proof.ready || pid != proof.pid || proc != proof.proc || task != proof.task ||
        !record || ![record[@"phase"] isEqual:@"cleanup-verified"] ||
        strcmp(proof.journalSHA256, themer_stock68_registration_raw_hash(journal).UTF8String ?: "") ||
        themer_spotlight_iconservices_has_pending_recovery() ||
        themer_stock68_identity_raw(NSUserDefaults.standardUserDefaults).count != 0 ||
        [NSUserDefaults.standardUserDefaults objectForKey:THEMER_STOCK68_IDENTITY_RETIREMENT_KEY]) return false;
    NSUserDefaults *d = NSUserDefaults.standardUserDefaults;
    [d removeObjectForKey:THEMER_STOCK68_JOURNAL_KEY];
    bool cleared = [d synchronize] && ![d objectForKey:THEMER_STOCK68_JOURNAL_KEY];
    if (!cleared) { [d setObject:journal forKey:THEMER_STOCK68_JOURNAL_KEY]; (void)[d synchronize]; }
    return cleared;
}

// This diagnostic has exactly one write boundary and always leaves the named
// stock68 materialization verdict to the existing authoritative topology path.
static ThemerSpotlightStock68MaterializationResult themer_stock68_registration_roundtrip(
    ThemerStock68MaterializationContext *context, uint64_t state, uint64_t original,
    const char *baseline, const ThemerIconServicesLabGenerationSample *sample,
    const ThemerRecordBlobObservation *blob, ThemerSpotlightStock68MaterializationReport *report)
{
    ThemerSpotlightStock68MaterializationResult result =
        ThemerSpotlightStock68MaterializationResultIssuedUnmaterializedRecoveryRequired;
    NSDictionary *journal = themer_stock68_local_journal_dictionary();
    bool inputs = journal && !journal[@"storeRegistration"] && report->recordIdentifiersCandidateClassified &&
        sample->coherent && sample->dataCaptured && !sample->dataCapture.truncated &&
        sample->dataCapture.objectLength == sample->dataCapture.capturedLength && context->namedScale == 3;
    int noOtherRecovery = inputs ? themer_stock68_registration_no_other_recovery() : -1;
    int pid = remote_call_current_pid(); uint64_t proc = remote_call_current_proc(), task = remote_call_current_task();
    char cachePath[PATH_MAX] = {0};
    int pathResolved = inputs && noOtherRecovery == 1 ? realpath(context->managerCachePath, cachePath) != NULL : -1;
    uint64_t store = pathResolved == 1 ? themer_stock68_registration_store(context->managerCache, cachePath) : 0;
    if (!inputs || noOtherRecovery != 1 || pathResolved != 1 || !store) {
        printf("[ICONSERVICES_MATERIALIZE] store-registration gates inputs=%d noOtherRecovery=%d realpath=%d store=%d downstream=unattempted prepared=0 healthy=%d\n",
            inputs, noOtherRecovery, pathResolved, store != 0, remote_call_current_success());
        return result;
    }
    uint64_t uuid = store ? themer_iconservices_lab_make_remote_uuid(@(report->recordIdentifiersCandidateUUID)) : 0;
    bool uuidBound = r_is_objc_ptr(uuid) && sample->uuidObserved &&
        (sample->uuidRaw == 0 || (r_is_objc_ptr(sample->uuidRaw) &&
         themer_iconservices_lab_objects_equal(sample->uuidRaw, uuid)));
    bool reconstruction = uuidBound && themer_stock68_registration_reconstruction(sample->data, uuid, sample->token);
    NSData *data = [NSData dataWithBytes:sample->dataCapture.bytes length:sample->dataCapture.capturedLength];
    NSData *token = [NSData dataWithBytes:sample->tokenCapture.bytes length:sample->tokenCapture.capturedLength];
    NSData *recordBlob = [NSData dataWithBytes:blob->capture.bytes length:blob->capture.capturedLength];
    NSString *path = [@(cachePath) stringByAppendingPathComponent:
        [@(report->recordIdentifiersCandidateUUID) stringByAppendingString:@".isdata"]];
    NSMutableDictionary *record = [@{@"version":@1, @"phase":@"prepared", @"transaction":NSUUID.UUID.UUIDString,
        @"pid":@(pid), @"proc":@(proc), @"task":@(task), @"target":journal[@"target"],
        @"fingerprint":journal[@"fingerprint"], @"namedDigest":journal[@"namedDigest"], @"generatedDigest":journal[@"generatedDigest"],
        @"originalDictionary":@(original), @"baselineFingerprint":@(baseline), @"dictionaryCount":@0, @"keyCount":@0,
        @"actualKeyCount":@0, @"entryCount":@0, @"uuid":@(report->recordIdentifiersCandidateUUID), @"cachePath":@(cachePath),
        @"path":path, @"data":data, @"dataSize":@(data.length), @"dataSHA256":themer_stock68_registration_hash(data),
        @"token":token, @"tokenLength":@(token.length), @"tokenSHA256":themer_stock68_registration_hash(token),
        @"recordBlob":recordBlob, @"recordBlobSHA256":themer_stock68_registration_hash(recordBlob), @"requestCount":@1,
        @"decodeComplete":@YES, @"ownershipVerified":@YES, @"constructorVerified":@YES, @"reconstructionVerified":@YES,
        @"prewriteFileAbsent":@YES, @"prewriteHealthyNil":@YES, @"width":@68, @"height":@68, @"scale":@3,
        @"pixelWidth":@204, @"pixelHeight":@204} mutableCopy];
    uint64_t unitClass = reconstruction ? themer_lookup_class("ISStoreUnit") : 0;
    uint64_t allocation = r_is_objc_ptr(unitClass) ? r_msg2_main(unitClass, "alloc", 0, 0, 0, 0) : 0;
    bool constructorABI = themer_stock68_registration_unit_abi(allocation);
    uint64_t unit = constructorABI ? r_msg2_main(allocation, "initWithData:UUID:", sample->data, uuid, 0, 0) : 0;
    bool initTransport = remote_call_current_success();
    if (!constructorABI && r_is_objc_ptr(allocation) && remote_call_current_success()) r_msg2(allocation, "release", 0, 0, 0, 0);
    char unitName[96] = {0};
    if (r_is_objc_ptr(unit) && initTransport) themer_read_class_name(unit, unitName, sizeof(unitName));
    printf("[ICONSERVICES_MATERIALIZE] store-registration constructor classPointer=%d allocationPointer=%d ABI=%d initPointer=%d initClass=%s initTransport=%d\n",
        r_is_objc_ptr(unitClass), r_is_objc_ptr(allocation), constructorABI, r_is_objc_ptr(unit), unitName, initTransport);
    bool constructed = constructorABI && themer_stock68_registration_unit_exact(unit, uuid, record);
    int schema = constructed ? themer_stock68_registration_valid(record, journal) : -1;
    int dictionary = schema == 1 ? themer_stock68_registration_dictionary(record, state, context, true) : -1;
    int absent = dictionary == 1 ? themer_stock68_registration_absent(store, uuid, path) : -1;
    int ownerStable = absent == 1 ? remote_call_current_pid() == pid &&
        remote_call_current_proc() == proc && remote_call_current_task() == task : -1;
    int persisted = ownerStable == 1 ? themer_stock68_registration_persist(journal, record) : -1;
    bool prepared = persisted == 1;
    printf("[ICONSERVICES_MATERIALIZE] store-registration gates inputs=%d noOtherRecovery=%d realpath=%d store=%d UUIDBound=%d reconstruction=%d constructorABI=%d constructed=%d schema=%d dictionary=%d absent=%d ownerStable=%d persist=%d prepared=%d healthy=%d skipped=-1\n",
        inputs, noOtherRecovery, pathResolved, store != 0, uuidBound, reconstruction, constructorABI,
        constructed, schema, dictionary, absent, ownerStable, persisted, prepared, remote_call_current_success());
    if (prepared) {
        result = ThemerSpotlightStock68MaterializationResultStoreRegisteredRecoveryRequired;
        // Diagnostic getters are borrowed, read-only observations, never write gates.
        void (^observeStore)(const char *) = ^(const char *stage) {
            const char *getters[] = {"registry", "connection", "domain"};
            for (size_t i = 0; i < sizeof(getters) / sizeof(getters[0]); i++) {
                bool getterABI = themer_stock68_registration_abi(store, getters[i], "@16@0:8");
                uint64_t value = getterABI ? r_msg2_main(store, getters[i], 0, 0, 0, 0) : 0;
                bool getterHealthy = remote_call_current_success();
                char name[96] = {0};
                if (getterHealthy && r_is_objc_ptr(value)) themer_read_class_name(value, name, sizeof(name));
                printf("[ICONSERVICES_MATERIALIZE] store-registration store-observation stage=%s getter=%s ABI=%d raw=0x%llx class=%s healthy=%d\n",
                    stage, getters[i], getterABI, (unsigned long long)value, name, remote_call_current_success());
                if (i != 0 || !getterABI || !getterHealthy || !r_is_objc_ptr(value)) continue;
                uint64_t dictionaryClass = remote_call_current_success() ? themer_lookup_class("NSDictionary") : 0;
                bool kindABI = r_is_objc_ptr(dictionaryClass) &&
                    themer_stock68_registration_abi(value, "isKindOfClass:", "B24@0:8#16");
                bool dictionary = kindABI && r_msg2_main(value, "isKindOfClass:", dictionaryClass, 0, 0, 0) == 1 &&
                    remote_call_current_success();
                bool countABI = dictionary && themer_stock68_registration_abi(value, "count", "Q16@0:8");
                uint64_t count = countABI ? r_msg2_main(value, "count", 0, 0, 0, 0) : 0;
                bool countKnown = countABI && remote_call_current_success();
                bool keyABI = dictionary && themer_stock68_registration_abi(value, "objectForKey:", "@24@0:8@16");
                uint64_t entry = keyABI ? r_msg2_main(value, "objectForKey:", uuid, 0, 0, 0) : 0;
                bool keyKnown = keyABI && remote_call_current_success() && (entry == 0 || r_is_objc_ptr(entry));
                printf("[ICONSERVICES_MATERIALIZE] store-registration registry stage=%s class=%s dictionary=%d countABI=%d countKnown=%d count=%llu keyABI=%d UUIDPresent=%d healthy=%d unknown=-1\n",
                    stage, name, dictionary, countABI, countKnown, (unsigned long long)count,
                    keyABI, keyKnown ? entry != 0 : -1, remote_call_current_success());
            }
        };
        observeStore("before-write");
        bool writeNoOtherRecovery = themer_stock68_registration_no_other_recovery();
        int writeDictionary = writeNoOtherRecovery ? themer_stock68_registration_dictionary(record, state, context, true) : -1;
        int writeAbsent = writeDictionary == 1 ? themer_stock68_registration_absent(store, uuid, path) : -1;
        int writeOwnerStable = writeAbsent == 1 ? remote_call_current_pid() == pid &&
            remote_call_current_proc() == proc && remote_call_current_task() == task : -1;
        int writePersisted = writeOwnerStable == 1 ? themer_stock68_registration_advance(@"write-possible") : -1;
        bool writeReady = writePersisted == 1;
        printf("[ICONSERVICES_MATERIALIZE] store-registration write-gates noOtherRecovery=%d dictionary=%d absent=%d ownerStable=%d persist=%d ready=%d healthy=%d skipped=-1\n",
            writeNoOtherRecovery, writeDictionary, writeAbsent, writeOwnerStable, writePersisted, writeReady, remote_call_current_success());
        bool written = false;
        bool dispatched = false;
        if (writeReady && remote_call_current_success()) {
            // The durable incident and write-possible record precede this sole dispatch.
            dispatched = true;
            uint64_t raw = r_msg2_main(store, "writeStoreUnit:", unit, 0, 0, 0);
            written = raw == 1 && remote_call_current_success();
            printf("[ICONSERVICES_MATERIALIZE] store-registration write-return raw=%llu healthy=%d\n",
                (unsigned long long)raw, remote_call_current_success());
        }
        // A false BOOL does not establish absence. Preserve the high-level readback.
        uint64_t readback = dispatched && remote_call_current_success()
            ? r_msg2_main(store, "unitForUUID:", uuid, 0, 0, 0) : 0;
        printf("[ICONSERVICES_MATERIALIZE] store-registration readback dispatched=%d raw=0x%llx healthy=%d\n",
            dispatched, (unsigned long long)readback, remote_call_current_success());
        if (dispatched) observeStore("after-write");
        bool verified = written && themer_stock68_registration_unit_exact(readback, uuid, record) &&
            themer_stock68_registration_file(record, NULL) &&
            themer_stock68_registration_reconstruction(sample->data, uuid, sample->token) &&
            themer_stock68_registration_advance(@"write-verified");
        ThemerIconServicesLabTopologySnapshot topology = {0};
        bool empty = verified && themer_stock68_capture_strict_topology(context->canonicalCache,
            "store-registration-after-write", &topology) && themer_stock68_topology_exactly_empty(&topology);
        printf("[ICONSERVICES_MATERIALIZE] store-registration dispatched=%d returnedTrue=%d verified=%d exactEmpty=%d materialized=0\n",
            dispatched, written, verified, empty);
        if (empty && themer_spotlight_stock68_recover_store_registration_in_session(false, pid, proc, task))
            result = ThemerSpotlightStock68MaterializationResultStoreRoundTripVerified;
        // All write, readback, file, topology and cleanup failures retain the
        // transaction. Emergency Restore is the only subsequent mutation.
    } else if (themer_stock68_local_journal_dictionary()[@"storeRegistration"]) {
        result = ThemerSpotlightStock68MaterializationResultStoreRegisteredRecoveryRequired;
    }
    if (r_is_objc_ptr(unit) && remote_call_current_success()) r_msg2(unit, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(uuid) && remote_call_current_success()) r_msg2(uuid, "release", 0, 0, 0, 0);
    return result;
}

ThemerSpotlightStock68LiveOwnerRetirementResult
themer_spotlight_stock68_prepare_live_owner_retirement_in_session(
    const ThemerSpotlightStock68JournalSnapshot *expectedJournal,
    int expectedPID,
    uint64_t expectedProc,
    uint64_t expectedTask,
    ThemerSpotlightStock68LiveOwnerRetirementReport *reportOut)
{
    ThemerSpotlightStock68LiveOwnerRetirementReport report = {0};
    if (!remote_call_current_success()) {
        if (reportOut) *reportOut = report;
        return ThemerSpotlightStock68LiveOwnerRetirementTransportFailed;
    }

    uint64_t state = themer_stock68_materialization_state();
    ThemerSpotlightStock68JournalSnapshot current =
        themer_spotlight_stock68_journal_snapshot();
    report.journalDispatchPossible = expectedJournal &&
        expectedJournal->present && expectedJournal->valid &&
        expectedJournal->classification ==
            ThemerSpotlightStock68JournalDispatchPossible &&
        expectedJournal->version == THEMER_STOCK68_JOURNAL_V2_VERSION &&
        expectedJournal->issuedKnown && expectedJournal->issued &&
        expectedJournal->dispatchPossibleKnown &&
        expectedJournal->dispatchPossible &&
        expectedJournal->transactionBound &&
        strcmp(expectedJournal->phase, "dispatch-possible") == 0 &&
        themer_stock68_recovery_complete_journal(expectedJournal);
    report.journalExact = report.journalDispatchPossible &&
        themer_stock68_snapshot_exact_equal(expectedJournal, &current);

    uint64_t statePID = 0;
    uint64_t requestIssued = 0;
    char stateTarget[192] = {0};
    char stateFingerprint[65] = {0};
    report.stateIdentityBound = r_is_objc_ptr(state) &&
        themer_spotlight_proof_state_u64(state, "pid", &statePID) &&
        themer_spotlight_proof_state_u64(
            state, "requestIssued", &requestIssued) &&
        themer_spotlight_proof_state_string(
            state, "targetBundle", stateTarget, sizeof(stateTarget)) &&
        themer_spotlight_proof_state_string(
            state, "themeFingerprint", stateFingerprint,
            sizeof(stateFingerprint)) &&
        expectedJournal && statePID == (uint64_t)expectedPID &&
        expectedPID == expectedJournal->pid && requestIssued == 1 &&
        strcmp(stateTarget, expectedJournal->targetBundle) == 0 &&
        strcmp(stateFingerprint, expectedJournal->themeFingerprint) == 0;
    report.requestIssued = report.stateIdentityBound && requestIssued == 1;

    report.ownerIdentityBound = expectedPID > 0 &&
        expectedProc && expectedProc != UINT64_MAX &&
        expectedTask && expectedTask != UINT64_MAX &&
        remote_call_current_pid() == expectedPID &&
        remote_call_current_proc() == expectedProc &&
        remote_call_current_task() == expectedTask;
    report.themedStateAbsent =
        !themer_spotlight_iconservices_has_state_in_session() &&
        remote_call_current_success();
    report.pendingRecoveryAbsent =
        !themer_spotlight_iconservices_has_pending_recovery();

    uint64_t originalBags = r_is_objc_ptr(state)
        ? themer_spotlight_dictionary_object(state, "originalBags") : 0;
    uint64_t originalCount = UINT64_MAX;
    ThemerIconServicesLabTopologySnapshot original = {0};
    bool originalCaptured = r_is_objc_ptr(originalBags) &&
        themer_spotlight_proof_state_u64(
            state, "originalCount", &originalCount) &&
        originalCount == 0 &&
        themer_stock68_capture_strict_dictionary(
            originalBags, "retire-original-empty", &original);
    report.originalTopologyExactlyEmpty = originalCaptured &&
        original.dictionary == originalBags &&
        themer_stock68_topology_exactly_empty(&original);

    bool preflight = report.journalExact && report.stateIdentityBound &&
        report.ownerIdentityBound && report.requestIssued &&
        report.originalTopologyExactlyEmpty && report.themedStateAbsent &&
        report.pendingRecoveryAbsent && remote_call_current_success();
    if (preflight) {
        report.dictionaryRestored =
            themer_stock68_restore_materialization_state(state);
        uint64_t cache = themer_spotlight_dictionary_object(state, "cache");
        ThemerIconServicesLabTopologySnapshot restored = {0};
        bool restoredCaptured = report.dictionaryRestored &&
            r_is_objc_ptr(cache) &&
            themer_stock68_capture_strict_topology(
                cache, "retire-restored-empty", &restored);
        report.restoredTopologyExactlyEmpty = restoredCaptured &&
            restored.dictionary == originalBags &&
            themer_stock68_topology_exactly_empty(&restored);
    }

    report.stateRetained =
        themer_stock68_materialization_state() == state && r_is_objc_ptr(state);
    ThemerSpotlightStock68JournalSnapshot after =
        themer_spotlight_stock68_journal_snapshot();
    report.journalRetained = expectedJournal &&
        themer_stock68_snapshot_exact_equal(expectedJournal, &after);
    bool eligible = preflight && report.dictionaryRestored &&
        report.restoredTopologyExactlyEmpty && report.stateRetained &&
        report.journalRetained && remote_call_current_success();
    printf("[ICONSERVICES_RECOVERY] retire-preflight class=%d version=%d "
           "pid=%d proc=0x%llx task=0x%llx journal=%d dispatch=%d "
           "state=%d owner=%d issued=%d originalEmpty=%d restored=%d "
           "restoredEmpty=%d themedAbsent=%d pendingAbsent=%d "
           "stateRetained=%d journalRetained=%d eligible=%d\n",
           expectedJournal ? expectedJournal->classification : -1,
           expectedJournal ? expectedJournal->version : 0,
           expectedPID, (unsigned long long)expectedProc,
           (unsigned long long)expectedTask, report.journalExact,
           report.journalDispatchPossible, report.stateIdentityBound,
           report.ownerIdentityBound, report.requestIssued,
           report.originalTopologyExactlyEmpty, report.dictionaryRestored,
           report.restoredTopologyExactlyEmpty, report.themedStateAbsent,
           report.pendingRecoveryAbsent, report.stateRetained,
           report.journalRetained, eligible);
    if (reportOut) *reportOut = report;
    if (!remote_call_current_success()) {
        return ThemerSpotlightStock68LiveOwnerRetirementTransportFailed;
    }
    return eligible
        ? ThemerSpotlightStock68LiveOwnerRetirementRequired
        : ThemerSpotlightStock68LiveOwnerRetirementRejected;
}

bool themer_spotlight_stock68_materialization_emergency_restore_in_session(void)
{
    uint64_t state = themer_stock68_materialization_state();
    if (!r_is_objc_ptr(state)) return false;
    ThemerSpotlightStock68JournalSnapshot journal =
        themer_spotlight_stock68_journal_snapshot();
    if (journal.storeRegistrationPresent) return false;
    bool journalPresent = journal.present;
    bool legacyUnissued = journal.classification ==
        ThemerSpotlightStock68JournalLegacyUnissued;
    bool v2NoDispatch = journal.classification ==
        ThemerSpotlightStock68JournalNoDispatchProven;
    uint64_t statePID = 0;
    char stateTarget[192] = {0};
    char stateFingerprint[65] = {0};
    bool stateIdentityKnown =
        themer_spotlight_proof_state_u64(state, "pid", &statePID) &&
        statePID == (uint64_t)remote_call_current_pid() &&
        themer_spotlight_proof_state_string(
            state, "targetBundle", stateTarget, sizeof(stateTarget)) &&
        themer_spotlight_proof_state_string(
            state, "themeFingerprint", stateFingerprint,
            sizeof(stateFingerprint));
    bool identityBound = !journalPresent ||
        (journal.valid && stateIdentityKnown &&
         statePID == (uint64_t)journal.pid &&
         strcmp(stateTarget, journal.targetBundle) == 0 &&
         strcmp(stateFingerprint, journal.themeFingerprint) == 0);
    // Restore the exact retained dictionary first.  This deliberately does
    // not clear the recovery association: any unknown request state must
    // remain recoverable after a later cache/store proof.
    if (!journal.valid && journalPresent) {
        printf("[ICONSERVICES_MATERIALIZE] emergency recovery retained "
               "journal=%d class=%d reason=invalid-journal\n",
               journalPresent, journal.classification);
        return false;
    }
    if (!identityBound || !remote_call_current_success()) {
        printf("[ICONSERVICES_MATERIALIZE] emergency recovery retained "
               "journal=%d class=%d identityBound=%d reason=journal-binding\n",
               journalPresent, journal.classification, identityBound);
        return false;
    }
    bool restored = themer_stock68_restore_materialization_state(state);
    if (!restored) return false;

    uint64_t remoteIssued = UINT64_MAX;
    bool remoteIssuedKnown =
        themer_spotlight_proof_state_u64(state, "requestIssued", &remoteIssued) &&
        (remoteIssued == 0 || remoteIssued == 1) &&
        remote_call_current_success();
    bool remoteRequestAllowed = remoteIssuedKnown &&
        (remoteIssued == 0 || (remoteIssued == 1 && v2NoDispatch));
    bool canClearJournal = !journalPresent || legacyUnissued || v2NoDispatch;
    if (!remoteRequestAllowed || !canClearJournal) {
        printf("[ICONSERVICES_MATERIALIZE] emergency recovery retained "
               "remote-state=1 journal=%d remoteIssuedKnown=%d "
               "remoteIssued=%llu journalClass=%d journalIssued=%d "
               "reason=store-cleanup-unproven\n",
               journalPresent,
               remoteIssuedKnown,
               (unsigned long long)remoteIssued,
               journal.classification,
               journal.issued);
        return false;
    }
    if (themer_spotlight_iconservices_has_pending_recovery()) {
        printf("[ICONSERVICES_MATERIALIZE] emergency recovery retained "
               "remote-state=1 journal=%d reason=pending-cache-store-cleanup\n",
               journalPresent);
        return false;
    }
    bool stateCleared = themer_stock68_materialization_clear_state();
    if (!stateCleared) return false;
    if (!journalPresent) return true;
    // A complete legacy-unissued or V2 no-dispatch journal can be removed only
    // after the exact dictionary restore and associated-state removal both
    // read back.  Legacy issued and malformed records remain armed.
    return themer_stock68_local_journal_clear();
}

bool themer_spotlight_stock68_recover_no_state_unissued_in_session(
    const char *expectedTargetBundle,
    const char *expectedThemeFingerprint,
    int expectedPID,
    uint64_t expectedProc,
    uint64_t expectedTask,
    bool ownerExitProven,
    bool healthyAbsenceRead)
{
    ThemerSpotlightStock68JournalSnapshot journal =
        themer_spotlight_stock68_journal_snapshot();
    if (journal.storeRegistrationPresent) return false;
    bool supportedClass = journal.classification ==
            ThemerSpotlightStock68JournalLegacyUnissued ||
        journal.classification ==
            ThemerSpotlightStock68JournalNoDispatchProven;
    bool identityBound = journal.valid && supportedClass &&
        expectedTargetBundle && expectedThemeFingerprint &&
        strlen(expectedThemeFingerprint) == 64 &&
        expectedPID > 0 && expectedProc && expectedTask &&
        expectedProc != UINT64_MAX && expectedTask != UINT64_MAX &&
        (expectedProc >> 48) == UINT16_MAX &&
        (expectedTask >> 48) == UINT16_MAX &&
        journal.pid == expectedPID &&
        strcmp(journal.targetBundle, expectedTargetBundle) == 0 &&
        strcmp(journal.themeFingerprint, expectedThemeFingerprint) == 0 &&
        remote_call_current_pid() > 0;
    // Do not trust a caller's absence flag.  Read the process association in
    // this core API and require that read itself to remain transport-healthy.
    uint64_t state = themer_stock68_materialization_state();
    bool stateAbsent = state == 0;
    bool healthyAbsence = stateAbsent &&
        remote_call_current_success() && healthyAbsenceRead;
    bool pendingCleanup = themer_spotlight_iconservices_has_pending_recovery();
    printf("[ICONSERVICES_MATERIALIZE] no-state-recovery class=%d "
           "journalPid=%d expected=%d ownerExit=%d absence=%d "
           "healthy=%d pendingCleanup=%d proc=0x%llx task=0x%llx\n",
           journal.classification,
           journal.pid,
           expectedPID,
           ownerExitProven,
           stateAbsent,
           healthyAbsence,
           pendingCleanup,
           (unsigned long long)expectedProc,
           (unsigned long long)expectedTask);
    if (!identityBound || !ownerExitProven || !healthyAbsence ||
        pendingCleanup) {
        return false;
    }
    // A journal clear is the final operation.  Its implementation restores
    // the marker when synchronize/readback is not acknowledged.
    return themer_stock68_local_journal_clear();
}

#define THEMER_AGENT_PUBLICATION_JOURNAL_KEY \
    @"Cyanide.IconServices.AgentPublicationJournal.v1"
#define THEMER_AGENT_PUBLICATION_VERSION 2
#define THEMER_AGENT_PUBLICATION_STATE_KEY \
    "cndSpotlightAgentPublicationStateV2"

static NSDictionary *themer_agent_publication_journal(void)
{
    id value = [NSUserDefaults.standardUserDefaults
        objectForKey:THEMER_AGENT_PUBLICATION_JOURNAL_KEY];
    return [value isKindOfClass:NSDictionary.class] ? value : nil;
}

static bool themer_agent_publication_journal_valid(NSDictionary *record)
{
    if (![record isKindOfClass:NSDictionary.class] ||
        [record[@"version"] integerValue] !=
            THEMER_AGENT_PUBLICATION_VERSION) {
        return false;
    }
    NSString *phase = record[@"phase"];
    NSString *transaction = record[@"transaction"];
    NSString *target = record[@"target"];
    NSString *fingerprint = record[@"fingerprint"];
    NSString *imageSHA256 = record[@"imageSHA256"];
    return [phase isKindOfClass:NSString.class] && phase.length > 0 &&
        [transaction isKindOfClass:NSString.class] &&
        transaction.length >= 32 &&
        [target isKindOfClass:NSString.class] && target.length > 0 &&
        [fingerprint isKindOfClass:NSString.class] &&
        fingerprint.length == 64 &&
        [imageSHA256 isKindOfClass:NSString.class] &&
        imageSHA256.length == 64;
}

static bool themer_agent_publication_journal_store(NSDictionary *record)
{
    if (!themer_agent_publication_journal_valid(record)) return false;
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    [defaults setObject:record forKey:THEMER_AGENT_PUBLICATION_JOURNAL_KEY];
    if (![defaults synchronize]) return false;
    return [themer_agent_publication_journal() isEqualToDictionary:record];
}

bool themer_spotlight_agent_publication_has_state(void)
{
    return themer_agent_publication_journal_valid(
        themer_agent_publication_journal());
}

bool themer_spotlight_agent_publication_is_published(void)
{
    NSDictionary *record = themer_agent_publication_journal();
    return themer_agent_publication_journal_valid(record) &&
        [record[@"phase"] isEqualToString:@"published"];
}

static uint64_t themer_agent_publication_state(void)
{
    return themer_spotlight_associated_process_object(
        THEMER_AGENT_PUBLICATION_STATE_KEY);
}

static bool themer_agent_publication_commit_state(uint64_t state)
{
    return themer_spotlight_commit_process_object(
        THEMER_AGENT_PUBLICATION_STATE_KEY, state);
}

static bool themer_agent_publication_clear_state(void)
{
    uint64_t processInfo = themer_spotlight_process_info();
    uint64_t key = r_sel(THEMER_AGENT_PUBLICATION_STATE_KEY);
    if (!r_is_objc_ptr(processInfo) || !key ||
        !remote_call_current_success()) {
        return false;
    }
    r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                 processInfo, key, 0, 1, 0, 0, 0, 0);
    return remote_call_current_success() &&
        themer_agent_publication_state() == 0;
}

static bool themer_agent_publication_journal_matches_transaction(
    NSDictionary *record,
    const char *transaction)
{
    if (!themer_agent_publication_journal_valid(record) ||
        !transaction || !transaction[0]) {
        return false;
    }
    NSString *expected = [NSString stringWithUTF8String:transaction];
    return expected && [record[@"transaction"] isEqualToString:expected];
}

bool themer_spotlight_agent_publication_finalize_after_clean_close(
    const char *transaction,
    bool cleanClose)
{
    NSDictionary *record = themer_agent_publication_journal();
    if (!cleanClose ||
        !themer_agent_publication_journal_matches_transaction(
            record, transaction) ||
        ![record[@"phase"] isEqualToString:@"dispatch-possible"] ||
        ![record[@"responseVerified"] boolValue] ||
        ![record[@"cachePublished"] boolValue]) {
        return false;
    }
    NSMutableDictionary *published = [record mutableCopy];
    published[@"phase"] = @"published";
    published[@"publishedAt"] = @([[NSDate date] timeIntervalSince1970]);
    return themer_agent_publication_journal_store(published);
}

bool themer_spotlight_agent_restore_finalize_after_clean_close(
    const char *transaction,
    bool cleanClose)
{
    NSDictionary *record = themer_agent_publication_journal();
    if (!cleanClose ||
        !themer_agent_publication_journal_matches_transaction(
            record, transaction) ||
        ![record[@"phase"] isEqualToString:@"restore-dispatch-possible"] ||
        ![record[@"restoreResponseVerified"] boolValue]) {
        return false;
    }
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    [defaults removeObjectForKey:THEMER_AGENT_PUBLICATION_JOURNAL_KEY];
    if (![defaults synchronize]) return false;
    return themer_agent_publication_journal() == nil;
}

static bool themer_agent_method_is(
    uint64_t object,
    const char *selector,
    const char *first,
    const char *second,
    char observed[192])
{
    if (observed) observed[0] = '\0';
    bool known = observed && themer_iconservices_lab_method_types(
        object, selector, observed, 192);
    bool accepted = known &&
        ((!strcmp(observed, first)) || (second && !strcmp(observed, second)));
    printf("[ICONSERVICES_AGENT_PREFLIGHT] abi selector=%s observed=\"%s\" "
           "accepted=\"%s%s%s\" status=%s invoked=0\n",
           selector ?: "-", known ? observed : "-", first ?: "-",
           second ? " | " : "", second ?: "",
           !remote_call_current_success() ? "transport-failure" :
           accepted ? "accepted" : "rejected");
    return accepted;
}

static bool themer_agent_capture_data(
    uint64_t data,
    ThemerIconServicesLabDataCapture *capture)
{
    char lengthTypes[192] = {0};
    char bytesTypes[192] = {0};
    bool abi = r_is_objc_ptr(data) &&
        themer_agent_method_is(
            data, "length", "Q16@0:8", NULL, lengthTypes) &&
        themer_agent_method_is(
            data, "bytes", "^v16@0:8", "r^v16@0:8", bytesTypes);
    return abi && themer_iconservices_lab_capture_nsdata(
        data, THEMER_ICONSERVICES_LAB_STOCK_COMPARE_DATA_CAP, capture);
}

static bool themer_agent_captures_equal(
    const ThemerIconServicesLabDataCapture *first,
    const ThemerIconServicesLabDataCapture *second)
{
    return first && second && !first->truncated && !second->truncated &&
        first->objectLength == second->objectLength &&
        first->capturedLength == second->capturedLength &&
        (first->capturedLength == 0 ||
         (first->bytes && second->bytes &&
          !memcmp(first->bytes, second->bytes, first->capturedLength)));
}

static void themer_agent_capture_sha256(
    const ThemerIconServicesLabDataCapture *capture,
    char output[65])
{
    if (output) output[0] = '\0';
    if (!capture || !output || capture->truncated ||
        capture->capturedLength != capture->objectLength ||
        (capture->capturedLength && !capture->bytes)) {
        return;
    }
    uint8_t digest[CC_SHA256_DIGEST_LENGTH] = {0};
    if (themer_iconservices_lab_digest(
            "CC_SHA256", capture->bytes, capture->capturedLength, digest)) {
        themer_iconservices_lab_hex_bytes(
            digest, sizeof(digest), output, 65);
    }
}

typedef struct {
    uint64_t width;
    uint64_t height;
    uint64_t bitsPerComponent;
    uint64_t bitsPerPixel;
    uint64_t bytesPerRow;
} ThemerAgentCGMetadata;

// Capture decoded provider bytes, not IFImage's private serialized data.  The
// latter legitimately changes when iconservicesagent re-encodes a response.
// Pixel equality is useful telemetry, while geometry and a complete response
// contract remain the publication gate because the service may intentionally
// apply descriptor-specific rendering.
static bool themer_agent_capture_image_pixels(
    uint64_t image,
    ThemerIconServicesLabDataCapture *capture,
    ThemerAgentCGMetadata *metadata,
    char sha256[65])
{
    if (capture) memset(capture, 0, sizeof(*capture));
    if (metadata) memset(metadata, 0, sizeof(*metadata));
    if (sha256) sha256[0] = '\0';
    if (!capture || !metadata || !sha256 || !r_is_objc_ptr(image)) {
        return false;
    }
    char cgTypes[192] = {0};
    if (!themer_agent_method_is(
            image, "CGImage", "^{CGImage=}16@0:8",
            "^{CGImage}16@0:8", cgTypes)) {
        return false;
    }
    uint64_t cg = r_msg2_main(image, "CGImage", 0, 0, 0, 0);
    if (!cg || !remote_call_current_success()) return false;
    metadata->width = r_dlsym_call(
        R_TIMEOUT, "CGImageGetWidth", cg, 0, 0, 0, 0, 0, 0, 0);
    metadata->height = r_dlsym_call(
        R_TIMEOUT, "CGImageGetHeight", cg, 0, 0, 0, 0, 0, 0, 0);
    metadata->bitsPerComponent = r_dlsym_call(
        R_TIMEOUT, "CGImageGetBitsPerComponent", cg, 0, 0, 0, 0, 0, 0, 0);
    metadata->bitsPerPixel = r_dlsym_call(
        R_TIMEOUT, "CGImageGetBitsPerPixel", cg, 0, 0, 0, 0, 0, 0, 0);
    metadata->bytesPerRow = r_dlsym_call(
        R_TIMEOUT, "CGImageGetBytesPerRow", cg, 0, 0, 0, 0, 0, 0, 0);
    uint64_t provider = r_dlsym_call(
        R_TIMEOUT, "CGImageGetDataProvider", cg, 0, 0, 0, 0, 0, 0, 0);
    uint64_t providerData = provider ? r_dlsym_call(
        R_TIMEOUT, "CGDataProviderCopyData", provider,
        0, 0, 0, 0, 0, 0, 0) : 0;
    bool captured = r_is_objc_ptr(providerData) &&
        themer_agent_capture_data(providerData, capture) &&
        !capture->truncated && capture->objectLength > 0;
    if (captured) themer_agent_capture_sha256(capture, sha256);
    if (providerData && remote_call_current_success()) {
        (void)r_dlsym_call(
            R_TIMEOUT, "CFRelease", providerData, 0, 0, 0, 0, 0, 0, 0);
    }
    return captured && metadata->width > 0 && metadata->height > 0 &&
        remote_call_current_success();
}

static uint64_t themer_agent_new_publication_state(
    uint64_t canonicalIcon,
    uint64_t canonicalCache,
    uint64_t descriptor)
{
    uint64_t dictionaryClass = r_class("NSMutableDictionary");
    uint64_t alloc = r_is_objc_ptr(dictionaryClass)
        ? r_msg2(dictionaryClass, "alloc", 0, 0, 0, 0) : 0;
    uint64_t state = r_is_objc_ptr(alloc)
        ? r_msg2_main(alloc, "init", 0, 0, 0, 0) : 0;
    bool complete = r_is_objc_ptr(state) &&
        themer_spotlight_dictionary_set_object(
            state, "canonicalIcon", canonicalIcon) &&
        themer_spotlight_dictionary_set_object(
            state, "canonicalCache", canonicalCache) &&
        themer_spotlight_dictionary_set_object(
            state, "descriptor", descriptor);
    if (!complete && r_is_objc_ptr(state) && remote_call_current_success()) {
        r_msg2(state, "release", 0, 0, 0, 0);
        state = 0;
    }
    return complete ? state : 0;
}


static bool themer_cached_response_method_is(
    uint64_t receiver, const char *selector, const char *first,
    const char *second, char observed[192])
{
    if (observed) observed[0] = '\0';
    bool known = observed && themer_iconservices_lab_method_types(
        receiver, selector, observed, 192);
    bool accepted = known &&
        (!strcmp(observed, first) || (second && !strcmp(observed, second)));
    printf("[ICONSERVICES_AGENT_RESPONSE] abi selector=%s observed=\"%s\" "
           "accepted=\"%s%s%s\" acceptedFlag=%d invoked=0\n",
           selector ?: "-", known ? observed : "-", first ?: "-",
           second ? " | " : "", second ?: "", accepted);
    return accepted;
}

static bool themer_cached_response_declared_method_is(
    uint64_t cls, const char *className, const char *selector,
    const char *first, const char *second, char observed[192])
{
    if (observed) observed[0] = '\0';
    uint64_t sel = r_is_objc_ptr(cls) ? r_sel(selector) : 0;
    uint64_t method = sel ? r_dlsym_call(
        R_TIMEOUT, "class_getInstanceMethod", cls, sel, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t types = method ? r_dlsym_call(
        R_TIMEOUT, "method_getTypeEncoding", method, 0, 0, 0, 0, 0, 0, 0) : 0;
    bool known = observed && themer_read_remote_cstring(types, observed, 192);
    bool accepted = known &&
        (!strcmp(observed, first) || (second && !strcmp(observed, second)));
    printf("[ICONSERVICES_AGENT_RESPONSE] abi target=%s selector=%s "
           "observed=\"%s\" acceptedFlag=%d invoked=0\n",
           className ?: "-", selector ?: "-", known ? observed : "-", accepted);
    return accepted;
}

static uint64_t themer_cached_response_retain(uint64_t object)
{
    return r_is_objc_ptr(object) && remote_call_current_success()
        ? r_dlsym_call(R_TIMEOUT, "objc_retain", object, 0, 0, 0, 0, 0, 0, 0)
        : 0;
}

static void themer_cached_response_release(uint64_t object)
{
    if (r_is_objc_ptr(object) && remote_call_current_success())
        (void)r_dlsym_call(R_TIMEOUT, "objc_release", object, 0, 0, 0, 0, 0, 0, 0);
}

static bool themer_cached_response_capture(
    uint64_t data, size_t cap, ThemerIconServicesLabDataCapture *capture)
{
    char lengthTypes[192] = {0}, bytesTypes[192] = {0};
    if (!capture) return false;
    memset(capture, 0, sizeof(*capture));
    if (!r_is_objc_ptr(data) || cap == 0 ||
        !themer_cached_response_method_is(data, "length", "Q16@0:8", NULL,
                                          lengthTypes) ||
        !themer_cached_response_method_is(data, "bytes", "^v16@0:8",
                                          "r^v16@0:8", bytesTypes)) {
        return false;
    }

    uint64_t objectLength = r_msg2_main(data, "length", 0, 0, 0, 0);
    if (!remote_call_current_success() || objectLength > SIZE_MAX) return false;
    capture->objectLength = (size_t)objectLength;
    capture->capturedLength = capture->objectLength < cap
        ? capture->objectLength : cap;
    capture->truncated = capture->capturedLength < capture->objectLength;
    if (capture->capturedLength == 0) return true;

    uint64_t remoteBytes = r_msg2_main(data, "bytes", 0, 0, 0, 0);
    if (!remoteBytes || remoteBytes > UINT64_MAX - capture->capturedLength ||
        !remote_call_current_success()) {
        return false;
    }
    capture->bytes = malloc(capture->capturedLength);
    if (!capture->bytes) return false;
    if (!remote_read(remoteBytes, capture->bytes, capture->capturedLength)) {
        themer_iconservices_lab_free_data_capture(capture);
        return false;
    }
    return remote_call_current_success();
}

static bool themer_cached_response_uuid_text(uint64_t uuid, char output[80])
{
    if (output) output[0] = '\0';
    char uuidTypes[192] = {0}, utf8Types[192] = {0};
    if (!output || !r_is_objc_ptr(uuid) ||
        !themer_cached_response_method_is(uuid, "UUIDString", "@16@0:8", NULL,
                                          uuidTypes)) return false;
    uint64_t string = r_msg2_main(uuid, "UUIDString", 0, 0, 0, 0);
    if (!r_is_objc_ptr(string) ||
        !themer_cached_response_method_is(string, "UTF8String", "*16@0:8",
                                          "r*16@0:8", utf8Types)) return false;
    uint64_t chars = r_msg2_main(string, "UTF8String", 0, 0, 0, 0);
    return chars && themer_read_remote_cstring(chars, output, 80);
}

static uint64_t themer_cached_response_adrp_address(uint64_t pc, uint32_t insn)
{
    int64_t imm = (int64_t)((((uint64_t)(insn >> 5) & 0x7ffffULL) << 2) |
                            ((insn >> 29) & 3));
    if (imm & (1LL << 20)) imm |= ~((1LL << 21) - 1);
    return (pc & ~0xfffULL) + (uint64_t)(imm << 12);
}

// Decode only adjacent ADRP/LDR (64-bit unsigned-immediate) pairs.  The
// sharedInstance IMP is inspected, never invoked.
static uint64_t themer_cached_response_initialized_manager(uint64_t managerClass)
{
    uint64_t sel = r_sel("sharedInstance");
    uint64_t method = sel ? r_dlsym_call(
        R_TIMEOUT, "class_getClassMethod", managerClass, sel,
        0, 0, 0, 0, 0, 0) : 0;
    uint64_t signedIMP = method ? r_dlsym_call(
        R_TIMEOUT, "method_getImplementation", method, 0, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t imp = native_strip(signedIMP);
    uint32_t code[32] = {0};
    uint64_t staging = imp ? r_dlsym_call(
        R_TIMEOUT, "malloc", sizeof(code), 0, 0, 0, 0, 0, 0, 0) : 0;
    bool stageDispatched = staging && staging <= UINT64_MAX - sizeof(code) &&
        imp <= UINT64_MAX - sizeof(code) && remote_call_current_success();
    uint64_t copied = stageDispatched ? r_dlsym_call(
        R_TIMEOUT, "memcpy", staging, imp, sizeof(code),
        0, 0, 0, 0, 0) : 0;
    bool stageCompleted = stageDispatched && copied == staging &&
        remote_call_current_success();
    bool codeRead = stageCompleted && remote_read(staging, code, sizeof(code));
    printf("[ICONSERVICES_AGENT_RESPONSE] singleton-entry class=0x%llx "
           "selector=0x%llx method=0x%llx signedIMP=0x%llx "
           "strippedIMP=0x%llx readPath=remote-heap-stage "
           "stagingDispatched=%d stagingCompleted=%d codeRead=%d "
           "scratchBytes=%zu sharedInstanceInvoked=0\n",
           (unsigned long long)managerClass,
           (unsigned long long)sel,
           (unsigned long long)method,
           (unsigned long long)signedIMP,
           (unsigned long long)imp,
           stageDispatched,
           stageCompleted,
           codeRead,
           sizeof(code));
    if (staging && remote_call_current_success()) r_free(staging);
    if (!codeRead) {
        return 0;
    }
    uint64_t globals[24] = {0};
    size_t globalCount = 0;
    bool bodyEnded = false;
    for (size_t i = 0; i < 32 && globalCount < 24; i++) {
        uint32_t adrp = code[i];
        if (adrp == 0xd65f03c0U ||
            ((adrp & 0xfc000000U) == 0x14000000U && globalCount >= 2)) {
            bodyEnded = true;
            break;
        }
        if (i + 1 >= 32) break;
        uint32_t ldr = code[i + 1];
        if ((adrp & 0x9f000000U) != 0x90000000U ||
            (ldr & 0xffc00000U) != 0xf9400000U) continue;
        unsigned adrpRd = adrp & 31, ldrRn = (ldr >> 5) & 31;
        if (adrpRd != ldrRn || adrpRd == 31) continue;
        uint64_t page = themer_cached_response_adrp_address(imp + i * 4, adrp);
        uint64_t address = page + (((uint64_t)(ldr >> 10) & 0xfffULL) << 3);
        bool duplicate = false;
        for (size_t j = 0; j < globalCount; j++) duplicate |= globals[j] == address;
        if (!duplicate) globals[globalCount++] = address;
    }
    bool onceReady = false;
    uint64_t singleton = 0;
    for (size_t i = 0; i < globalCount && i < 2; i++) {
        uint64_t value = 0;
        if (!remote_read(globals[i], &value, sizeof(value))) continue;
        if (i == 0 && value == UINT64_MAX) onceReady = true;
        if (i != 1 || !r_is_objc_ptr(value)) continue;
        char name[96] = {0};
        themer_read_class_name(value, name, sizeof(name));
        if (!strcmp(name, "ISIconManager")) singleton = value;
    }
    printf("[ICONSERVICES_AGENT_RESPONSE] singleton-static imp=0x%llx "
           "pairs=%zu onceReady=%d singleton=0x%llx sharedInstanceInvoked=0\n",
           (unsigned long long)imp, globalCount, onceReady,
           (unsigned long long)singleton);
    return bodyEnded && onceReady ? singleton : 0;
}

static bool themer_cached_response_cache_lookup_is_read_only(
    uint64_t imageCache, uint64_t expectedCacheClass)
{
    uint64_t runtimeClass = r_is_objc_ptr(imageCache)
        ? r_dlsym_call(R_TIMEOUT, "object_getClass", imageCache,
                       0, 0, 0, 0, 0, 0, 0)
        : 0;
    uint64_t declaredIMP = r_is_objc_ptr(expectedCacheClass)
        ? themer_method_imp(expectedCacheClass, "imageForDescriptor:") : 0;
    uint64_t runtimeIMP = r_is_objc_ptr(runtimeClass)
        ? themer_method_imp(runtimeClass, "imageForDescriptor:") : 0;
    char runtimeName[96] = {0};
    themer_read_class_name(imageCache, runtimeName, sizeof(runtimeName));
    bool exact = runtimeClass == expectedCacheClass && declaredIMP &&
        runtimeIMP == declaredIMP && !strcmp(runtimeName, "ISImageCache");
    printf("[ICONSERVICES_AGENT_RESPONSE] cache-static-proof class=%s "
           "runtimeClass=0x%llx expectedClass=0x%llx runtimeIMP=0x%llx "
           "declaredIMP=0x%llx exact=%d "
           "evidence=offline-disassembly-unfair-lock-dictionary-bag-lookup\n",
           runtimeName[0] ? runtimeName : "-",
           (unsigned long long)runtimeClass,
           (unsigned long long)expectedCacheClass,
           (unsigned long long)runtimeIMP,
           (unsigned long long)declaredIMP,
           exact);
    return exact;
}

static bool themer_cached_response_size(
    uint64_t object, const char *selector, double *w, double *h,
    bool *abiMismatch)
{
    char types[192] = {0};
    bool abi = themer_cached_response_method_is(
        object, selector, "{CGSize=dd}16@0:8", "{CGSize=dd}16@0:8", types);
    if (!abi) { if (abiMismatch) *abiMismatch = true; return false; }
    struct { double w; double h; } value = {0.0, 0.0};
    bool read = r_msg2_main_struct_ret(
        object, selector, &value, sizeof(value),
        NULL, 0, NULL, 0, NULL, 0, NULL, 0);
    if (w) *w = value.w;
    if (h) *h = value.h;
    return read && remote_call_current_success();
}

static double themer_cached_response_double(
    uint64_t object, const char *selector, bool *known)
{
    if (known) *known = false;
    uint64_t bits = r_msg2_main(object, selector, 0, 0, 0, 0);
    double value = 0.0;
    memcpy(&value, &bits, sizeof(value));
    if (!remote_call_current_success() || value < -10000.0 ||
        value > 10000.0) {
        return 0.0;
    }
    if (known) *known = true;
    return value;
}

ThemerSpotlightAgentResponseContractResult
themer_spotlight_iconservices_agent_response_contract_in_session(
    ThemerSpotlightAgentResponseContractReport *reportOut)
{
    ThemerSpotlightAgentResponseContractReport report = {0};
    report.result = ThemerSpotlightAgentResponseContractTransportFailed;
    uint64_t registryObjects = 0, selectedIcon = 0, descriptorName = 0;
    uint64_t descriptor = 0, donor = 0, sourceData = 0, sourceUUID = 0;
    uint64_t sourceToken = 0, response = 0, responseData = 0;
    uint64_t responseUUID = 0, responseToken = 0, reconstructed = 0;
    uint64_t reconstructedData = 0, reconstructedUUID = 0;
    uint64_t reconstructedToken = 0;
    ThemerIconServicesLabDataCapture sourceCapture = {0};
    ThemerIconServicesLabDataCapture tokenCapture = {0};
    ThemerIconServicesLabDataCapture responseCapture = {0};
    ThemerIconServicesLabDataCapture responseTokenCapture = {0};
    ThemerIconServicesLabDataCapture reconstructedCapture = {0};
    ThemerIconServicesLabDataCapture reconstructedTokenCapture = {0};
    bool sourceUnavailable = false;
#define RESPONSE_FAIL(stage, why) do { \
    if (!report.firstFailureStage[0]) snprintf(report.firstFailureStage, \
        sizeof(report.firstFailureStage), "%s", (stage)); \
    if (!report.reason[0]) snprintf(report.reason, sizeof(report.reason), \
        "%s", (why)); \
} while (0)

    printf("[ICONSERVICES_AGENT_RESPONSE] begin pid=%d cachedDonor=1 "
           "scratchResponse=1 readOnly=1 generated=0 serviceDispatch=0 "
           "storeCalls=0 fileMutations=0 recoveryAccess=0\n",
           remote_call_current_pid());
    if (!remote_call_current_success() || !themer_ensure_iconservices_loaded()) {
        RESPONSE_FAIL("load", "iconservices-unavailable"); goto done;
    }
    uint64_t managerClass = themer_lookup_class("ISIconManager");
    uint64_t bundleIconClass = themer_lookup_class("ISBundleIdentifierIcon");
    uint64_t descriptorClass = themer_lookup_class("ISImageDescriptor");
    uint64_t responseClass = themer_lookup_class("ISGenerationResponse");
    uint64_t imageClass = themer_lookup_class("IFImage");
    uint64_t imageCacheClass = themer_lookup_class("ISImageCache");
    uint64_t stringClass = r_class("NSString");
    uint64_t concreteIconClass = themer_lookup_class("ISConcreteIcon");
    if (!managerClass || !bundleIconClass || !descriptorClass || !responseClass ||
        !imageClass || !imageCacheClass || !stringClass || !concreteIconClass) {
        report.abiMismatch = true; RESPONSE_FAIL("classes", "required-class-missing");
        goto done;
    }
    char types[192] = {0};
    report.clientSyncABI = themer_cached_response_declared_method_is(
        concreteIconClass, "ISConcreteIcon", "generateImageWithDescriptor:",
        "@24@0:8@16", NULL, types);
    report.clientCompletionABI = themer_cached_response_declared_method_is(
        concreteIconClass, "ISConcreteIcon",
        "generateImageWithDescriptor:completion:", "v32@0:8@16@?24", NULL, types);
    report.abiMismatch |= !report.clientSyncABI || !report.clientCompletionABI;

    uint64_t manager = themer_cached_response_initialized_manager(managerClass);
    report.managerProvenInitialized = r_is_objc_ptr(manager);
    if (!report.managerProvenInitialized) {
        sourceUnavailable = true;
        RESPONSE_FAIL("manager-singleton", "safe-manager-acquisition-unavailable"); goto done;
    }
    if (!themer_cached_response_method_is(manager, "iconRegistry", "@16@0:8",
                                          NULL, types)) {
        report.abiMismatch = true; RESPONSE_FAIL("icon-registry-abi", "abi-mismatch");
        goto done;
    }
    uint64_t registry = r_msg2_main(manager, "iconRegistry", 0, 0, 0, 0);
    if (!r_is_objc_ptr(registry)) {
        sourceUnavailable = true;
        RESPONSE_FAIL("icon-registry", "source-unavailable-registry-nil");
        goto done;
    }
    if (!themer_cached_response_method_is(registry, "allObjects", "@16@0:8",
                                          NULL, types)) {
        report.abiMismatch = true; RESPONSE_FAIL("registry-all-objects", "abi-mismatch");
        goto done;
    }
    registryObjects = themer_cached_response_retain(
        r_msg2_main(registry, "allObjects", 0, 0, 0, 0));
    if (!r_is_objc_ptr(registryObjects) ||
        !themer_cached_response_method_is(registryObjects, "count", "Q16@0:8",
                                          NULL, types) ||
        !themer_cached_response_method_is(registryObjects, "objectAtIndex:",
                                          "@24@0:8Q16", NULL, types)) {
        report.abiMismatch = true; RESPONSE_FAIL("registry-enumeration", "abi-mismatch");
        goto done;
    }
    uint64_t count = r_msg2_main(registryObjects, "count", 0, 0, 0, 0);
    if (count > 4096) { RESPONSE_FAIL("registry-bound", "registry-too-large"); goto done; }
    for (uint64_t i = 0; i < count && !selectedIcon; i++) {
        uint64_t icon = r_msg2_main(registryObjects, "objectAtIndex:", i, 0, 0, 0);
        char className[96] = {0}; themer_read_class_name(icon, className, sizeof(className));
        if (strcmp(className, "ISBundleIdentifierIcon")) continue;
        if (!themer_cached_response_method_is(icon, "bundleIdentifier", "@16@0:8",
                                              NULL, types)) {
            report.abiMismatch = true; RESPONSE_FAIL("bundle-id-abi", "abi-mismatch");
            goto done;
        }
        uint64_t bundle = r_msg2_main(icon, "bundleIdentifier", 0, 0, 0, 0);
        if (!r_is_objc_ptr(bundle) ||
            !themer_cached_response_method_is(bundle, "UTF8String", "*16@0:8",
                                              "r*16@0:8", types)) {
            report.abiMismatch = true; RESPONSE_FAIL("bundle-utf8-abi", "abi-mismatch");
            goto done;
        }
        char bundleText[192] = {0};
        uint64_t chars = r_msg2_main(bundle, "UTF8String", 0, 0, 0, 0);
        if (chars && themer_read_remote_cstring(chars, bundleText, sizeof(bundleText)) &&
            !strcmp(bundleText, "ai.perplexity.app"))
            selectedIcon = themer_cached_response_retain(icon);
    }
    if (!selectedIcon) { sourceUnavailable = true; RESPONSE_FAIL("donor-icon", "source-unavailable"); goto done; }
    if (!themer_cached_response_method_is(selectedIcon, "imageCache", "@16@0:8",
                                          NULL, types)) {
        report.abiMismatch = true; RESPONSE_FAIL("image-cache-abi", "abi-mismatch"); goto done;
    }
    uint64_t imageCache = r_msg2_main(selectedIcon, "imageCache", 0, 0, 0, 0);
    if (!r_is_objc_ptr(imageCache)) {
        sourceUnavailable = true;
        RESPONSE_FAIL("image-cache", "source-unavailable-image-cache-nil");
        goto done;
    }
    report.cacheLookupStaticProof =
        themer_cached_response_cache_lookup_is_read_only(
            imageCache, imageCacheClass);
    bool cacheGetterABI = themer_cached_response_method_is(
        imageCache, "imageForDescriptor:", "@24@0:8@16", NULL, types);
    if (!cacheGetterABI) {
        report.abiMismatch = true; RESPONSE_FAIL("cache-lookup-abi", "abi-mismatch"); goto done;
    }
    if (!report.cacheLookupStaticProof) {
        sourceUnavailable = true;
        RESPONSE_FAIL("cache-lookup-proof", "safe-cache-proof-unavailable"); goto done;
    }
    if (!themer_cached_response_method_is(stringClass, "stringWithUTF8String:",
                                          "@24@0:8*16", "@24@0:8r*16", types) ||
        !themer_cached_response_method_is(descriptorClass, "imageDescriptorNamed:",
                                          "@24@0:8@16", NULL, types)) {
        report.abiMismatch = true; RESPONSE_FAIL("descriptor-abi", "abi-mismatch"); goto done;
    }
    uint64_t nameChars = r_alloc_str("com.apple.IconServices.ImageDescriptor.Spotlight");
    descriptorName = nameChars ? themer_cached_response_retain(
        r_msg2_main(stringClass, "stringWithUTF8String:", nameChars, 0, 0, 0)) : 0;
    if (nameChars) r_free(nameChars);
    descriptor = r_is_objc_ptr(descriptorName) ? themer_cached_response_retain(
        r_msg2_main(descriptorClass, "imageDescriptorNamed:", descriptorName, 0, 0, 0)) : 0;
    donor = r_is_objc_ptr(descriptor) ? themer_cached_response_retain(
        r_msg2_main(imageCache, "imageForDescriptor:", descriptor, 0, 0, 0)) : 0;
    if (!donor) { sourceUnavailable = true; RESPONSE_FAIL("cache-donor", "source-unavailable-cache-miss"); goto done; }
    report.donorFound = true;

    char donorClassName[96] = {0};
    themer_read_class_name(donor, donorClassName, sizeof(donorClassName));
    snprintf(report.donorClass, sizeof(report.donorClass), "%s", donorClassName);
    if (strcmp(donorClassName, "IFCacheImage") && strcmp(donorClassName, "IFImage")) {
        RESPONSE_FAIL("donor-class", "donor-class-mismatch"); goto done;
    }
    uint64_t donorRuntimeClass = r_dlsym_call(
        R_TIMEOUT, "object_getClass", donor, 0, 0, 0, 0, 0, 0, 0);
    uint64_t dataIvarName = r_alloc_str("_data");
    uint64_t dataIvar = dataIvarName ? r_dlsym_call(
        R_TIMEOUT, "class_getInstanceVariable", donorRuntimeClass, dataIvarName,
        0, 0, 0, 0, 0, 0) : 0;
    if (dataIvarName) r_free(dataIvarName);
    int64_t dataOffset = dataIvar ? (int64_t)r_dlsym_call(
        R_TIMEOUT, "ivar_getOffset", dataIvar, 0, 0, 0, 0, 0, 0, 0) : -1;
    if (!dataIvar || dataOffset < 0) {
        report.abiMismatch = true;
        RESPONSE_FAIL("donor-data-ivar", "ifimage-data-ivar-missing"); goto done;
    }
    uint64_t dataBefore = remote_read64(donor + (uint64_t)dataOffset);
    if (!themer_cached_response_method_is(donor, "data", "@16@0:8", NULL, types) ||
        !themer_cached_response_method_is(donor, "uuid", "@16@0:8", NULL, types) ||
        !themer_cached_response_method_is(donor, "validationToken", "@16@0:8", NULL, types)) {
        report.abiMismatch = true; RESPONSE_FAIL("donor-field-abi", "abi-mismatch"); goto done;
    }
    sourceData = themer_cached_response_retain(r_msg2_main(donor, "data", 0, 0, 0, 0));
    sourceUUID = themer_cached_response_retain(r_msg2_main(donor, "uuid", 0, 0, 0, 0));
    sourceToken = themer_cached_response_retain(r_msg2_main(donor, "validationToken", 0, 0, 0, 0));
    uint64_t dataAfter = remote_read64(donor + (uint64_t)dataOffset);
    report.donorDataMemoized = !dataBefore && dataAfter && dataAfter == sourceData;
    report.donorDataIvarStable = dataBefore == dataAfter ||
                                 report.donorDataMemoized;
    printf("[ICONSERVICES_AGENT_RESPONSE] donor-data-ivar before=0x%llx "
           "after=0x%llx getter=0x%llx stable=%d memoized=%d "
           "cacheMapMutation=0 storeMutation=0\n",
           (unsigned long long)dataBefore, (unsigned long long)dataAfter,
           (unsigned long long)sourceData, report.donorDataIvarStable,
           report.donorDataMemoized);
    if (!sourceData || !sourceUUID || !sourceToken ||
        !themer_cached_response_capture(sourceData,
            THEMER_ICONSERVICES_LAB_STOCK_COMPARE_DATA_CAP, &sourceCapture) ||
        sourceCapture.truncated ||
        !themer_cached_response_capture(sourceToken,
            THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP, &tokenCapture) ||
        tokenCapture.truncated || tokenCapture.objectLength == 0) {
        sourceUnavailable = true;
        RESPONSE_FAIL("donor-capture", "donor-fields-unavailable"); goto done;
    }
    report.sourceDataLength = sourceCapture.objectLength;
    report.validationTokenLength = tokenCapture.objectLength;
    char sourceUUIDText[80] = {0};
    if (!themer_cached_response_uuid_text(sourceUUID, sourceUUIDText) ||
        !sourceUUIDText[0]) {
        sourceUnavailable = true;
        RESPONSE_FAIL("donor-uuid", "donor-uuid-unavailable"); goto done;
    }
    if (sourceCapture.capturedLength < 48) { RESPONSE_FAIL("if-v9-header", "short-if-image"); goto done; }
    uint32_t version = 0, bitmap = 0, layer = 0;
    memcpy(&version, sourceCapture.bytes, 4);
    memcpy(&bitmap, sourceCapture.bytes + 4, 4); memcpy(&layer, sourceCapture.bytes + 8, 4);
    uint64_t logical = 48ULL + bitmap + layer;
    if (version != 9 || logical < 48 || logical > sourceCapture.objectLength ||
        logical > sourceCapture.capturedLength) {
        RESPONSE_FAIL("if-v9-lengths", "invalid-if-image-lengths"); goto done;
    }
    report.bitmapLength = bitmap; report.layerLength = layer;
    report.logicalDataLength = logical; report.sourceHeaderVerified = true;
    uint8_t digest[CC_SHA256_DIGEST_LENGTH] = {0};
    if (themer_iconservices_lab_digest("CC_SHA256", sourceCapture.bytes, logical, digest))
        themer_iconservices_lab_hex_bytes(digest, sizeof(digest),
                                          report.logicalDataSHA256,
                                          sizeof(report.logicalDataSHA256));
    if (themer_iconservices_lab_digest("CC_SHA256", tokenCapture.bytes,
                                      tokenCapture.capturedLength, digest))
        themer_iconservices_lab_hex_bytes(digest, sizeof(digest),
                                          report.validationTokenSHA256,
                                          sizeof(report.validationTokenSHA256));

    if (!themer_cached_response_method_is(responseClass, "alloc", "@16@0:8", NULL, types)) {
        report.abiMismatch = true; RESPONSE_FAIL("response-alloc-abi", "abi-mismatch"); goto done;
    }
    uint64_t responseAlloc = r_msg2(responseClass, "alloc", 0, 0, 0, 0);
    if (!r_is_objc_ptr(responseAlloc) ||
        !themer_cached_response_method_is(responseAlloc,
            "initWithData:uuid:validationToken:", "@40@0:8@16@24@32", NULL, types)) {
        report.abiMismatch = true; themer_cached_response_release(responseAlloc);
        RESPONSE_FAIL("response-init-abi", "abi-mismatch"); goto done;
    }
    response = r_msg2_main(responseAlloc, "initWithData:uuid:validationToken:",
                           sourceData, sourceUUID, sourceToken, 0);
    report.responseConstructed = r_is_objc_ptr(response);
    themer_read_class_name(response, report.responseClass, sizeof(report.responseClass));
    if (!report.responseConstructed) {
        RESPONSE_FAIL("response-construct", "response-construction-failed");
        goto done;
    }
    if (strcmp(report.responseClass, "ISGenerationResponse")) {
        RESPONSE_FAIL("response-class", "response-class-mismatch");
        goto done;
    }
    if (!themer_cached_response_method_is(response, "data", "@16@0:8", NULL, types) ||
        !themer_cached_response_method_is(response, "uuid", "@16@0:8", NULL, types) ||
        !themer_cached_response_method_is(response, "validationToken", "@16@0:8", NULL, types) ||
        !themer_cached_response_method_is(response, "error", "@16@0:8", NULL, types)) {
        report.abiMismatch = true; RESPONSE_FAIL("response-fields-abi", "abi-mismatch"); goto done;
    }
    responseData = themer_cached_response_retain(r_msg2_main(response, "data", 0, 0, 0, 0));
    responseUUID = themer_cached_response_retain(r_msg2_main(response, "uuid", 0, 0, 0, 0));
    responseToken = themer_cached_response_retain(r_msg2_main(response, "validationToken", 0, 0, 0, 0));
    uint64_t responseError = r_msg2_main(response, "error", 0, 0, 0, 0);
    char responseUUIDText[80] = {0};
    bool responseUUIDExact = themer_cached_response_uuid_text(
        responseUUID, responseUUIDText) &&
        !strcmp(responseUUIDText, sourceUUIDText);
    bool responseTokenExact = themer_cached_response_capture(
        responseToken, THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP,
        &responseTokenCapture) && !responseTokenCapture.truncated &&
        responseTokenCapture.objectLength == tokenCapture.objectLength &&
        responseTokenCapture.capturedLength == tokenCapture.capturedLength &&
        !memcmp(responseTokenCapture.bytes, tokenCapture.bytes,
                tokenCapture.capturedLength);
    if (!themer_cached_response_capture(responseData,
            THEMER_ICONSERVICES_LAB_STOCK_COMPARE_DATA_CAP, &responseCapture) ||
        responseCapture.truncated || responseCapture.objectLength < logical ||
        (responseCapture.objectLength & 0x3fffULL) != 0 ||
        memcmp(responseCapture.bytes, sourceCapture.bytes, logical) || responseError ||
        !responseUUIDExact || !responseTokenExact) {
        RESPONSE_FAIL("scratch-response-fields", "response-field-mismatch"); goto done;
    }
    report.responseDataLength = responseCapture.objectLength;
    report.responsePaddingLength = responseCapture.objectLength - logical;
    if (report.responsePaddingLength &&
        themer_iconservices_lab_digest("CC_SHA256", responseCapture.bytes,
                                      responseCapture.capturedLength, digest))
        themer_iconservices_lab_hex_bytes(digest, sizeof(digest),
                                          report.paddedDataSHA256,
                                          sizeof(report.paddedDataSHA256));
    snprintf(report.responseUUID, sizeof(report.responseUUID), "%s", sourceUUIDText);
    report.responseFieldsVerified = true;

    uint64_t imageAlloc = 0;
    if (!themer_cached_response_method_is(imageClass, "alloc", "@16@0:8", NULL, types) ||
        !(imageAlloc = r_msg2(imageClass, "alloc", 0, 0, 0, 0)) ||
        !themer_cached_response_method_is(imageAlloc,
            "initWithData:uuid:validationToken:", "@40@0:8@16@24@32", NULL, types)) {
        report.abiMismatch = true; themer_cached_response_release(imageAlloc);
        RESPONSE_FAIL("ifimage-init-abi", "abi-mismatch"); goto done;
    }
    reconstructed = r_msg2_main(imageAlloc, "initWithData:uuid:validationToken:",
                                responseData, responseUUID, responseToken, 0);
    report.returnedImageConstructed = r_is_objc_ptr(reconstructed);
    themer_read_class_name(reconstructed, report.returnedImageClass,
                           sizeof(report.returnedImageClass));
    if (!report.returnedImageConstructed ||
        (strcmp(report.returnedImageClass, "IFCacheImage") &&
         strcmp(report.returnedImageClass, "IFImage"))) {
        RESPONSE_FAIL("ifimage-class", "reconstructed-class-mismatch"); goto done;
    }
    if (!themer_cached_response_method_is(reconstructed, "data", "@16@0:8", NULL, types) ||
        !themer_cached_response_method_is(reconstructed, "uuid", "@16@0:8", NULL, types) ||
        !themer_cached_response_method_is(reconstructed, "validationToken", "@16@0:8", NULL, types)) {
        report.abiMismatch = true;
        RESPONSE_FAIL("ifimage-fields-abi", "abi-mismatch"); goto done;
    }
    reconstructedData = themer_cached_response_retain(
        r_msg2_main(reconstructed, "data", 0, 0, 0, 0));
    reconstructedUUID = themer_cached_response_retain(
        r_msg2_main(reconstructed, "uuid", 0, 0, 0, 0));
    reconstructedToken = themer_cached_response_retain(
        r_msg2_main(reconstructed, "validationToken", 0, 0, 0, 0));
    char reconstructedUUIDText[80] = {0};
    bool reconstructedUUIDExact = themer_cached_response_uuid_text(
        reconstructedUUID, reconstructedUUIDText) &&
        !strcmp(reconstructedUUIDText, sourceUUIDText);
    bool reconstructedTokenExact = themer_cached_response_capture(
        reconstructedToken, THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP,
        &reconstructedTokenCapture) && !reconstructedTokenCapture.truncated &&
        reconstructedTokenCapture.objectLength == tokenCapture.objectLength &&
        reconstructedTokenCapture.capturedLength == tokenCapture.capturedLength &&
        !memcmp(reconstructedTokenCapture.bytes, tokenCapture.bytes,
                tokenCapture.capturedLength);
    bool reconstructedDataCaptured = themer_cached_response_capture(
        reconstructedData, THEMER_ICONSERVICES_LAB_STOCK_COMPARE_DATA_CAP,
        &reconstructedCapture) && !reconstructedCapture.truncated &&
        reconstructedCapture.capturedLength >= 48;
    uint32_t reconstructedVersion = 0, reconstructedBitmap = 0;
    uint32_t reconstructedLayer = 0;
    if (reconstructedDataCaptured) {
        memcpy(&reconstructedVersion, reconstructedCapture.bytes, 4);
        memcpy(&reconstructedBitmap, reconstructedCapture.bytes + 4, 4);
        memcpy(&reconstructedLayer, reconstructedCapture.bytes + 8, 4);
    }
    uint64_t reconstructedLogical = 48ULL + reconstructedBitmap + reconstructedLayer;
    bool reconstructedPayloadExact = reconstructedDataCaptured &&
        reconstructedVersion == 9 && reconstructedLogical == logical &&
        reconstructedLogical <= reconstructedCapture.objectLength &&
        reconstructedLogical <= reconstructedCapture.capturedLength &&
        !memcmp(reconstructedCapture.bytes, sourceCapture.bytes, logical);
    bool reconstructedFieldsExact = reconstructedPayloadExact &&
        reconstructedUUIDExact && reconstructedTokenExact;
    double donorSizeW=0, donorSizeH=0, imageSizeW=0, imageSizeH=0;
    double donorPixelW=0, donorPixelH=0, imagePixelW=0, imagePixelH=0;
    double donorMinimumW=0, donorMinimumH=0, imageMinimumW=0, imageMinimumH=0;
    double donorIconW=0, donorIconH=0, imageIconW=0, imageIconH=0;
    bool geometry = themer_cached_response_size(donor, "size", &donorSizeW, &donorSizeH, &report.abiMismatch) &&
        themer_cached_response_size(reconstructed, "size", &imageSizeW, &imageSizeH, &report.abiMismatch) &&
        themer_cached_response_size(donor, "pixelSize", &donorPixelW, &donorPixelH, &report.abiMismatch) &&
        themer_cached_response_size(reconstructed, "pixelSize", &imagePixelW, &imagePixelH, &report.abiMismatch) &&
        themer_cached_response_size(donor, "minimumSize", &donorMinimumW, &donorMinimumH, &report.abiMismatch) &&
        themer_cached_response_size(reconstructed, "minimumSize", &imageMinimumW, &imageMinimumH, &report.abiMismatch) &&
        themer_cached_response_size(donor, "iconSize", &donorIconW, &donorIconH, &report.abiMismatch) &&
        themer_cached_response_size(reconstructed, "iconSize", &imageIconW, &imageIconH, &report.abiMismatch) &&
        themer_iconservices_lab_sizes_match(donorSizeW, donorSizeH, imageSizeW, imageSizeH) &&
        themer_iconservices_lab_sizes_match(donorPixelW, donorPixelH, imagePixelW, imagePixelH) &&
        themer_iconservices_lab_sizes_match(donorMinimumW, donorMinimumH, imageMinimumW, imageMinimumH) &&
        themer_iconservices_lab_sizes_match(donorIconW, donorIconH, imageIconW, imageIconH);
    char scaleTypes[192] = {0}; bool donorScaleKnown = false, imageScaleKnown = false;
    bool scaleABI = themer_cached_response_method_is(donor, "scale", "d16@0:8", NULL, scaleTypes) &&
        themer_cached_response_method_is(reconstructed, "scale", "d16@0:8", NULL, scaleTypes);
    double donorScale = scaleABI
        ? themer_cached_response_double(donor, "scale", &donorScaleKnown) : 0;
    double imageScale = scaleABI
        ? themer_cached_response_double(
            reconstructed, "scale", &imageScaleKnown) : 0;
    report.abiMismatch |= !scaleABI;
    report.geometryVerified = geometry && donorScaleKnown && imageScaleKnown &&
        donorScale == imageScale;
    char cgTypes[192] = {0};
    bool cgABI = themer_cached_response_method_is(reconstructed, "CGImage",
        "^{CGImage=}16@0:8", "^{CGImage}16@0:8", cgTypes);
    report.abiMismatch |= !cgABI;
    uint64_t cg = cgABI ? r_msg2_main(reconstructed, "CGImage", 0, 0, 0, 0) : 0;
    uint64_t cgW = cg ? r_dlsym_call(R_TIMEOUT, "CGImageGetWidth", cg, 0,0,0,0,0,0,0) : 0;
    uint64_t cgH = cg ? r_dlsym_call(R_TIMEOUT, "CGImageGetHeight", cg, 0,0,0,0,0,0,0) : 0;
    report.cgImageVerified = cg && cgW == (uint64_t)(imagePixelW + 0.5) &&
        cgH == (uint64_t)(imagePixelH + 0.5);
    report.returnedImageFieldsVerified = reconstructedFieldsExact &&
        report.geometryVerified && report.cgImageVerified;
    if (!report.returnedImageFieldsVerified) RESPONSE_FAIL("ifimage-parity", "reconstructed-field-mismatch");

done:
    report.transportClean = remote_call_current_success();
    if (!report.transportClean) {
        report.result = ThemerSpotlightAgentResponseContractTransportFailed;
        RESPONSE_FAIL("transport", "transport-failed");
    } else if (report.abiMismatch) {
        report.result = ThemerSpotlightAgentResponseContractUnsupportedABI;
    } else if (sourceUnavailable) {
        report.result = ThemerSpotlightAgentResponseContractSourceUnavailable;
    } else if (report.responseFieldsVerified && report.returnedImageFieldsVerified) {
        report.result = ThemerSpotlightAgentResponseContractReady;
        snprintf(report.reason, sizeof(report.reason), "cached-donor-scratch-response-ready");
    } else {
        report.result = ThemerSpotlightAgentResponseContractVerificationFailed;
    }
    printf("[ICONSERVICES_AGENT_RESPONSE] summary result=%d abiMismatch=%d "
           "firstFailure=%s manager=%d cacheProof=%d donor=%d/%s "
           "ivarStable=%d memoized=%d "
           "source=%llu logical=%llu bitmap=%llu layer=%llu logicalSHA=%s "
           "scratchResponse=%d/%d response=%llu padding=%llu paddedSHA=%s "
           "ifImage=%d/%d geometry=%d cgImage=%d transport=%d reason=%s "
           "readOnly=1 generated=0 serviceDispatch=0 storeCalls=0 "
           "fileMutations=0 recoveryAccess=0\n",
           report.result, report.abiMismatch,
           report.firstFailureStage[0] ? report.firstFailureStage : "-",
           report.managerProvenInitialized, report.cacheLookupStaticProof,
           report.donorFound, report.donorClass[0] ? report.donorClass : "-",
           report.donorDataIvarStable, report.donorDataMemoized,
           (unsigned long long)report.sourceDataLength,
           (unsigned long long)report.logicalDataLength,
           (unsigned long long)report.bitmapLength,
           (unsigned long long)report.layerLength,
           report.logicalDataSHA256[0] ? report.logicalDataSHA256 : "-",
           report.responseConstructed, report.responseFieldsVerified,
           (unsigned long long)report.responseDataLength,
           (unsigned long long)report.responsePaddingLength,
           report.paddedDataSHA256[0] ? report.paddedDataSHA256 : "-",
           report.returnedImageConstructed, report.returnedImageFieldsVerified,
           report.geometryVerified, report.cgImageVerified,
           report.transportClean, report.reason[0] ? report.reason : "-");
    themer_cached_response_release(reconstructed);
    themer_cached_response_release(reconstructedToken);
    themer_cached_response_release(reconstructedUUID);
    themer_cached_response_release(reconstructedData);
    themer_cached_response_release(responseToken);
    themer_cached_response_release(responseUUID);
    themer_cached_response_release(responseData);
    themer_cached_response_release(response);
    themer_cached_response_release(sourceToken);
    themer_cached_response_release(sourceUUID);
    themer_cached_response_release(sourceData);
    themer_cached_response_release(donor);
    themer_cached_response_release(descriptor);
    themer_cached_response_release(descriptorName);
    themer_cached_response_release(selectedIcon);
    themer_cached_response_release(registryObjects);
    themer_iconservices_lab_free_data_capture(&responseCapture);
    themer_iconservices_lab_free_data_capture(&responseTokenCapture);
    themer_iconservices_lab_free_data_capture(&reconstructedCapture);
    themer_iconservices_lab_free_data_capture(&reconstructedTokenCapture);
    themer_iconservices_lab_free_data_capture(&tokenCapture);
    themer_iconservices_lab_free_data_capture(&sourceCapture);
    if (reportOut) *reportOut = report;
#undef RESPONSE_FAIL
    return report.result;
}

static ThemerSpotlightAgentPreflightResult
themer_spotlight_iconservices_agent_request_in_session(
    NSDictionary<NSString *, NSData *> *imageDataByBundle,
    const char *targetBundle,
    const char *themeFingerprint,
    bool serviceDispatch,
    ThemerSpotlightAgentPreflightReport *reportOut)
{
    ThemerSpotlightAgentPreflightReport report = {0};
    report.result = ThemerSpotlightAgentPreflightTransportFailed;
    if (targetBundle) {
        snprintf(report.targetBundle, sizeof(report.targetBundle), "%s",
                 targetBundle);
    }
    if (themeFingerprint) {
        snprintf(report.themeFingerprint, sizeof(report.themeFingerprint),
                 "%s", themeFingerprint);
    }
    printf("[ICONSERVICES_AGENT_PREFLIGHT] begin pid=%d target=%s "
           "readOnly=%d generated=0 serviceDispatchRequested=%d "
           "directStoreCalls=0 fileMutations=0 recoveryAccess=0\n",
           remote_call_current_pid(), targetBundle ?: "-",
           !serviceDispatch, serviceDispatch);

    uint64_t targetIcon = 0;
    uint64_t namedDescriptor = 0;
    uint64_t descriptor = 0;
    uint64_t ifImage = 0;
    uint64_t scratchIcon = 0;
    uint64_t request = 0;
    uint64_t archive = 0;
    uint64_t decodedRequest = 0;
    ThemerSpotlightRemoteImage sources[1] = {{0}};
    int sourceCount = 0;
    ThemerIconServicesLabDataCapture sourceCapture = {0};
    ThemerIconServicesLabDataCapture scratchCapture = {0};
    ThemerIconServicesLabDataCapture decodedCapture = {0};
    ThemerIconServicesLabDataCapture serviceResponseCapture = {0};
    ThemerIconServicesLabDataCapture sourcePixelCapture = {0};
    ThemerIconServicesLabDataCapture responsePixelCapture = {0};
    ThemerIconServicesLabDataCapture responseTokenCapture = {0};
    NSDictionary<NSString *, NSData *> *scaled = nil;
    NSString *publicationTransaction = nil;
    NSMutableDictionary *publicationRecord = nil;
    uint64_t publicationState = 0;
    bool publicationStateCommitted = false;

    NSDictionary<NSString *, NSData *> *normalized =
        themer_normalized_theme_data(imageDataByBundle);
    if (!targetBundle || !targetBundle[0] || normalized.count == 0) {
        report.result = ThemerSpotlightAgentPreflightNoEligibleTarget;
        snprintf(report.reason, sizeof(report.reason), "no-eligible-target");
        goto finished;
    }
    if (!remote_call_current_success() || !themer_ensure_iconservices_loaded()) {
        snprintf(report.reason, sizeof(report.reason), "iconservices-unavailable");
        goto finished;
    }

    uint64_t descriptorClass = themer_lookup_class("ISImageDescriptor");
    char namedTypes[192] = {0};
    if (!r_is_objc_ptr(descriptorClass) ||
        !themer_agent_method_is(
            descriptorClass, "imageDescriptorNamed:",
            "@24@0:8@16", NULL, namedTypes)) {
        report.result = remote_call_current_success()
            ? ThemerSpotlightAgentPreflightUnsupportedABI
            : ThemerSpotlightAgentPreflightTransportFailed;
        snprintf(report.reason, sizeof(report.reason),
                 "named-descriptor-abi");
        goto finished;
    }
    namedDescriptor = themer_iconservices_lab_named_spotlight_descriptor(
        NULL, NULL, NULL);
    char scaleTypes[192] = {0};
    char digestTypes[192] = {0};
    char copyTypes[192] = {0};
    char ignoreSetTypes[192] = {0};
    char ignoreGetTypes[192] = {0};
    bool descriptorABI = r_is_objc_ptr(namedDescriptor) &&
        themer_agent_method_is(
            namedDescriptor, "scale", "d16@0:8", NULL, scaleTypes) &&
        themer_agent_method_is(
            namedDescriptor, "digest", "@16@0:8", NULL, digestTypes) &&
        themer_agent_method_is(
            namedDescriptor, "copy", "@16@0:8", NULL, copyTypes);
    bool scaleKnown = false;
    double scale = descriptorABI
        ? themer_read_remote_double_property(
            namedDescriptor, "scale", 0.0, &scaleKnown)
        : 0.0;
    bool descriptorDigestKnown = descriptorABI &&
        themer_iconservices_lab_descriptor_digest_text(
            namedDescriptor, report.descriptorDigest,
            sizeof(report.descriptorDigest));
    descriptor = descriptorABI
        ? r_msg2_main(namedDescriptor, "copy", 0, 0, 0, 0)
        : 0;
    descriptorABI = descriptorABI && r_is_objc_ptr(descriptor) &&
        themer_agent_method_is(
            descriptor, "setIgnoreCache:", "v20@0:8B16", NULL,
            ignoreSetTypes) &&
        themer_agent_method_is(
            descriptor, "ignoreCache", "B16@0:8", NULL,
            ignoreGetTypes);
    if (!descriptorABI || !scaleKnown || scale < 1.0 || scale > 4.0 ||
        !descriptorDigestKnown) {
        report.result = remote_call_current_success()
            ? ThemerSpotlightAgentPreflightUnsupportedABI
            : ThemerSpotlightAgentPreflightTransportFailed;
        snprintf(report.reason, sizeof(report.reason), "descriptor-preflight");
        goto finished;
    }
    r_msg2_main(descriptor, "setIgnoreCache:", 1, 0, 0, 0);
    report.ignoreCacheEnabled = remote_call_current_success() &&
        (r_msg2_main(descriptor, "ignoreCache", 0, 0, 0, 0) & 1) != 0;
    char descriptorDigestAfter[160] = {0};
    report.descriptorDigestPreserved = report.ignoreCacheEnabled &&
        themer_iconservices_lab_descriptor_digest_text(
            descriptor, descriptorDigestAfter,
            sizeof(descriptorDigestAfter)) &&
        !strcmp(report.descriptorDigest, descriptorDigestAfter);

    scaled = themer_iconservices_lab_scaled_theme_data(
        normalized, targetBundle, 68.0, 68.0, scale);
    uint64_t sourceImage = scaled
        ? themer_spotlight_remote_image_for_bundle(
            scaled, targetBundle, sources, &sourceCount, 1)
        : 0;
    ifImage = r_is_objc_ptr(sourceImage)
        ? themer_iconservices_lab_make_if_image(sourceImage, scale)
        : 0;
    if (!r_is_objc_ptr(ifImage) || !remote_call_current_success()) {
        report.result = remote_call_current_success()
            ? ThemerSpotlightAgentPreflightVerificationFailed
            : ThemerSpotlightAgentPreflightTransportFailed;
        snprintf(report.reason, sizeof(report.reason), "themed-ifimage");
        goto finished;
    }

    targetIcon = themer_iconservices_lab_make_bundle_icon(targetBundle);
    uint64_t scratchClass = themer_lookup_class("_ISImageIcon");
    uint64_t concreteClass = themer_lookup_class("ISConcreteIcon");
    uint64_t scratchAlloc = r_is_objc_ptr(scratchClass)
        ? r_msg2(scratchClass, "alloc", 0, 0, 0, 0) : 0;
    char initImageTypes[192] = {0};
    char targetDigestTypes[192] = {0};
    char scratchDigestTypes[192] = {0};
    char imageDataTypes[192] = {0};
    char secureTypes[192] = {0};
    bool iconABI = r_is_objc_ptr(targetIcon) &&
        r_is_objc_ptr(scratchAlloc) && r_is_objc_ptr(concreteClass) &&
        themer_agent_method_is(
            targetIcon, "digest", "@16@0:8", NULL, targetDigestTypes) &&
        themer_agent_method_is(
            scratchAlloc, "initImage:", "@24@0:8@16", NULL,
            initImageTypes) &&
        themer_agent_method_is(
            scratchClass, "supportsSecureCoding", "B16@0:8", NULL,
            secureTypes);
    report.secureCodingSupported = iconABI &&
        (r_msg2_main(scratchClass, "supportsSecureCoding", 0, 0, 0, 0) & 1);
    scratchIcon = iconABI
        ? r_msg2_main(scratchAlloc, "initImage:", ifImage, 0, 0, 0)
        : 0;
    if (!r_is_objc_ptr(scratchIcon) || !report.secureCodingSupported ||
        !themer_agent_method_is(
            scratchIcon, "digest", "@16@0:8", NULL,
            scratchDigestTypes) ||
        !themer_agent_method_is(
            scratchIcon, "imageData", "@16@0:8", NULL,
            imageDataTypes)) {
        report.result = remote_call_current_success()
            ? ThemerSpotlightAgentPreflightUnsupportedABI
            : ThemerSpotlightAgentPreflightTransportFailed;
        snprintf(report.reason, sizeof(report.reason), "image-icon-abi");
        goto finished;
    }
    themer_read_class_name(
        scratchIcon, report.scratchClass, sizeof(report.scratchClass));
    uint64_t targetDigest = r_msg2_main(
        targetIcon, "digest", 0, 0, 0, 0);
    report.targetDigestKnown = r_is_objc_ptr(targetDigest) &&
        themer_read_remote_description(
            targetDigest, report.targetDigest, sizeof(report.targetDigest));
    uint64_t ivarName = r_alloc_str("_digest");
    uint64_t digestIvar = ivarName && r_is_objc_ptr(concreteClass)
        ? r_dlsym_call(R_TIMEOUT, "class_getInstanceVariable",
                       concreteClass, ivarName, 0, 0, 0, 0, 0, 0)
        : 0;
    if (ivarName && remote_call_current_success()) r_free(ivarName);
    if (report.targetDigestKnown && digestIvar &&
        remote_call_current_success()) {
        (void)r_dlsym_call(
            R_TIMEOUT, "object_setIvarWithStrongDefault",
            scratchIcon, digestIvar, targetDigest, 0, 0, 0, 0, 0);
    }
    uint64_t replacedDigest = remote_call_current_success()
        ? r_msg2_main(scratchIcon, "digest", 0, 0, 0, 0) : 0;
    char replacedDigestText[160] = {0};
    report.scratchDigestReplaced = r_is_objc_ptr(replacedDigest) &&
        themer_read_remote_description(
            replacedDigest, replacedDigestText, sizeof(replacedDigestText)) &&
        !strcmp(report.targetDigest, replacedDigestText);

    char ifImageDataTypes[192] = {0};
    if (!themer_agent_method_is(
