        r_msg2(descriptor, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(namedDescriptor) && remote_call_current_success()) {
        r_msg2(namedDescriptor, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(targetIcon) && remote_call_current_success()) {
        r_msg2(targetIcon, "release", 0, 0, 0, 0);
    }
    themer_spotlight_proof_release_images(sources, sourceCount, 0);
    themer_iconservices_lab_free_data_capture(&decodedCapture);
    themer_iconservices_lab_free_data_capture(&serviceResponseCapture);
    themer_iconservices_lab_free_data_capture(&responseTokenCapture);
    themer_iconservices_lab_free_data_capture(&responsePixelCapture);
    themer_iconservices_lab_free_data_capture(&sourcePixelCapture);
    themer_iconservices_lab_free_data_capture(&scratchCapture);
    themer_iconservices_lab_free_data_capture(&sourceCapture);
    if (reportOut) *reportOut = report;
    return report.result;
}

