ThemerSpotlightAgentPreflightResult
themer_spotlight_iconservices_agent_restore_in_session(
    ThemerSpotlightAgentPreflightReport *reportOut)
{
    ThemerSpotlightAgentPreflightReport report = {0};
    report.result = ThemerSpotlightAgentPreflightTransportFailed;
    NSDictionary *journal = themer_agent_publication_journal();
    uint64_t namedDescriptor = 0;
    uint64_t descriptor = 0;
    uint64_t targetIcon = 0;
    uint64_t liveState = 0;
    ThemerIconServicesLabDataCapture responseCapture = {0};
    ThemerIconServicesLabDataCapture tokenCapture = {0};
    NSString *restoreTransaction = nil;
    NSMutableDictionary *restoreRecord = nil;
    NSString *stockSHA = nil;
    NSString *target = themer_agent_publication_journal_valid(journal)
        ? journal[@"target"] : nil;
    NSString *fingerprint = themer_agent_publication_journal_valid(journal)
        ? journal[@"fingerprint"] : nil;
    if (target.length > 0) {
        snprintf(report.targetBundle, sizeof(report.targetBundle), "%s",
                 target.UTF8String ?: "");
    }
    if (fingerprint.length > 0) {
        snprintf(report.themeFingerprint, sizeof(report.themeFingerprint),
                 "%s", fingerprint.UTF8String ?: "");
    }
    printf("[ICONSERVICES_AGENT_RESTORE] begin pid=%d journal=%d "
           "phase=%s target=%s serviceDispatchRequested=conditional "
           "directStoreCalls=0 fileMutations=0\n",
           remote_call_current_pid(),
           themer_agent_publication_journal_valid(journal),
           [journal[@"phase"] UTF8String] ?: "-",
           target.UTF8String ?: "-");
    if (!themer_agent_publication_journal_valid(journal) ||
        target.length == 0) {
        report.result = ThemerSpotlightAgentPreflightVerificationFailed;
        snprintf(report.reason, sizeof(report.reason),
                 "publication-journal-absent-or-invalid");
        goto restore_finished;
    }
    liveState = themer_agent_publication_state();
    int journalPID = [journal[@"pid"] intValue];
    bool samePID = journalPID > 0 &&
        journalPID == remote_call_current_pid();
    if (!samePID || !r_is_objc_ptr(liveState)) {
        // The v2 effect is process-resident.  A different PID (or a missing
        // association in the recorded PID) is positive evidence that no live
        // themed canonical icon remains to restore.
        restoreTransaction = NSUUID.UUID.UUIDString;
        restoreRecord = [journal mutableCopy];
        restoreRecord[@"phase"] = @"restore-dispatch-possible";
        restoreRecord[@"transaction"] = restoreTransaction ?: @"";
        restoreRecord[@"restoreResponseVerified"] = @YES;
        restoreRecord[@"restoreNoLiveState"] = @YES;
        restoreRecord[@"restoreCreatedAt"] =
            @([[NSDate date] timeIntervalSince1970]);
        bool persisted =
            themer_agent_publication_journal_store(restoreRecord);
        snprintf(report.transaction, sizeof(report.transaction), "%s",
                 restoreTransaction.UTF8String ?: "");
        report.serviceResponseVerified = persisted;
        report.result = persisted
            ? ThemerSpotlightAgentPreflightReady
            : ThemerSpotlightAgentPreflightVerificationFailed;
        snprintf(report.reason, sizeof(report.reason), "%s",
                 persisted ? "process-resident-publication-already-gone"
                           : "restore-no-live-state-journal-failed");
        printf("[ICONSERVICES_AGENT_RESTORE] no-live-state "
               "journalPid=%d currentPid=%d association=%d "
               "transaction=%s journalUpdated=%d serviceDispatch=0\n",
               journalPID, remote_call_current_pid(),
               r_is_objc_ptr(liveState), report.transaction, persisted);
        goto restore_finished;
    }
    if (!remote_call_current_success() ||
        themer_spotlight_has_armed_recovery_in_session() ||
        !themer_ensure_iconservices_loaded()) {
        report.result = remote_call_current_success()
            ? ThemerSpotlightAgentPreflightVerificationFailed
            : ThemerSpotlightAgentPreflightTransportFailed;
        snprintf(report.reason, sizeof(report.reason),
                 "other-recovery-or-iconservices-unavailable");
        goto restore_finished;
    }

    uint64_t descriptorClass = themer_lookup_class("ISImageDescriptor");
    char namedTypes[192] = {0};
    if (!r_is_objc_ptr(descriptorClass) ||
        !themer_agent_method_is(
            descriptorClass, "imageDescriptorNamed:",
            "@24@0:8@16", NULL, namedTypes)) {
        report.result = remote_call_current_success()
            ? ThemerSpotlightAgentPreflightUnsupportedABI
            : ThemerSpotlightAgentPreflightTransportFailed;
        snprintf(report.reason, sizeof(report.reason),
                 "restore-named-descriptor-abi");
        goto restore_finished;
    }
    namedDescriptor = themer_iconservices_lab_named_spotlight_descriptor(
        NULL, NULL, NULL);
    char copyTypes[192] = {0};
    char setIgnoreTypes[192] = {0};
    char getIgnoreTypes[192] = {0};
    bool descriptorABI = r_is_objc_ptr(namedDescriptor) &&
        themer_agent_method_is(
            namedDescriptor, "copy", "@16@0:8", NULL, copyTypes);
    descriptor = descriptorABI
        ? r_msg2_main(namedDescriptor, "copy", 0, 0, 0, 0) : 0;
    descriptorABI = descriptorABI && r_is_objc_ptr(descriptor) &&
        themer_agent_method_is(
            descriptor, "setIgnoreCache:", "v20@0:8B16", NULL,
            setIgnoreTypes) &&
        themer_agent_method_is(
            descriptor, "ignoreCache", "B16@0:8", NULL,
            getIgnoreTypes);
    if (descriptorABI) {
        r_msg2_main(descriptor, "setIgnoreCache:", 1, 0, 0, 0);
        report.ignoreCacheEnabled = remote_call_current_success() &&
            (r_msg2_main(descriptor, "ignoreCache", 0, 0, 0, 0) & 1);
    }
    targetIcon = descriptorABI
        ? themer_iconservices_lab_make_bundle_icon(target.UTF8String) : 0;
    uint64_t liveCache = themer_spotlight_dictionary_object(
        liveState, "canonicalCache");
    uint64_t liveDescriptor = themer_spotlight_dictionary_object(
        liveState, "descriptor");
    uint64_t liveIcon = themer_spotlight_dictionary_object(
        liveState, "canonicalIcon");
    char generateTypes[192] = {0}, setTypes[192] = {0};
    char readTypes[192] = {0};
    bool generateABI = report.ignoreCacheEnabled &&
        r_is_objc_ptr(targetIcon) &&
        themer_agent_method_is(
            targetIcon, "generateImageWithDescriptor:",
            "@24@0:8@16", NULL, generateTypes) &&
        r_is_objc_ptr(liveIcon) && r_is_objc_ptr(liveCache) &&
        r_is_objc_ptr(liveDescriptor) &&
        themer_agent_method_is(
            liveCache, "setImage:forDescriptor:",
            "v32@0:8@16@24", NULL, setTypes) &&
        themer_agent_method_is(
            liveCache, "imageForDescriptor:",
            "@24@0:8@16", NULL, readTypes);
    if (!generateABI) {
        report.result = remote_call_current_success()
            ? ThemerSpotlightAgentPreflightUnsupportedABI
            : ThemerSpotlightAgentPreflightTransportFailed;
        snprintf(report.reason, sizeof(report.reason),
                 "restore-generation-abi");
        goto restore_finished;
    }

    restoreTransaction = NSUUID.UUID.UUIDString;
    restoreRecord = [journal mutableCopy];
    restoreRecord[@"phase"] = @"restore-dispatch-possible";
    restoreRecord[@"transaction"] = restoreTransaction ?: @"";
    restoreRecord[@"restoreResponseVerified"] = @NO;
    restoreRecord[@"restoreCreatedAt"] =
        @([[NSDate date] timeIntervalSince1970]);
    if (!themer_agent_publication_journal_store(restoreRecord)) {
        report.result = ThemerSpotlightAgentPreflightVerificationFailed;
        snprintf(report.reason, sizeof(report.reason),
                 "restore-journal-persist-failed");
        goto restore_finished;
    }
    snprintf(report.transaction, sizeof(report.transaction), "%s",
             restoreTransaction.UTF8String ?: "");
    report.serviceDispatchPossible = true;
    printf("[ICONSERVICES_AGENT_RESTORE] phase=restore-dispatch-possible "
           "transaction=%s target=%s directStoreCalls=0\n",
           report.transaction, target.UTF8String ?: "-");
    uint64_t response = r_msg2_main(
        targetIcon, "generateImageWithDescriptor:", descriptor, 0, 0, 0);
    char dataTypes[192] = {0}, uuidTypes[192] = {0};
    char tokenTypes[192] = {0}, cgTypes[192] = {0};
    themer_read_class_name(response, report.serviceResponseClass,
                           sizeof(report.serviceResponseClass));
    bool dataABI = r_is_objc_ptr(response) &&
        themer_agent_method_is(
            response, "data", "@16@0:8", NULL, dataTypes) &&
        themer_agent_method_is(
            response, "uuid", "@16@0:8", NULL, uuidTypes) &&
        themer_agent_method_is(
            response, "validationToken", "@16@0:8", NULL,
            tokenTypes) &&
        themer_agent_method_is(
            response, "CGImage", "^{CGImage=}16@0:8",
            "^{CGImage}16@0:8", cgTypes);
    uint64_t data = dataABI
        ? r_msg2_main(response, "data", 0, 0, 0, 0) : 0;
    uint64_t uuid = dataABI
        ? r_msg2_main(response, "uuid", 0, 0, 0, 0) : 0;
    uint64_t token = dataABI
        ? r_msg2_main(response, "validationToken", 0, 0, 0, 0) : 0;
    uint64_t cg = dataABI
        ? r_msg2_main(response, "CGImage", 0, 0, 0, 0) : 0;
    bool captured = dataABI &&
        themer_agent_capture_data(data, &responseCapture);
    bool tokenCaptured = r_is_objc_ptr(token) &&
        themer_agent_capture_data(token, &tokenCapture) &&
        !tokenCapture.truncated && tokenCapture.objectLength > 0;
    uint64_t cgWidth = cg ? r_dlsym_call(
        R_TIMEOUT, "CGImageGetWidth", cg, 0, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t cgHeight = cg ? r_dlsym_call(
        R_TIMEOUT, "CGImageGetHeight", cg, 0, 0, 0, 0, 0, 0, 0) : 0;
    report.serviceResponseLength = responseCapture.objectLength;
    themer_agent_capture_sha256(
        &responseCapture, report.serviceResponseSHA256);
    stockSHA = report.serviceResponseSHA256[0]
        ? [NSString stringWithUTF8String:report.serviceResponseSHA256] : nil;
    bool responseClassOK =
        !strcmp(report.serviceResponseClass, "IFImage") ||
        !strcmp(report.serviceResponseClass, "IFCacheImage");
    bool responseContract = responseClassOK && captured &&
        !responseCapture.truncated && responseCapture.objectLength > 0 &&
        stockSHA.length == 64 && r_is_objc_ptr(uuid) && tokenCaptured &&
        cg && cgWidth > 0 && cgHeight > 0;
    if (responseContract) {
        r_msg2_main(liveCache, "setImage:forDescriptor:",
                    response, liveDescriptor, 0, 0);
        report.cachePublished = remote_call_current_success();
    }
    uint64_t readback = report.cachePublished
        ? r_msg2_main(liveCache, "imageForDescriptor:",
                      liveDescriptor, 0, 0, 0) : 0;
    report.cacheReadbackVerified = report.cachePublished &&
        readback == response && remote_call_current_success();
    bool stateReleased = report.cacheReadbackVerified &&
        themer_agent_publication_clear_state();
    report.serviceResponseVerified = responseContract &&
        report.cacheReadbackVerified && stateReleased;
    if (report.serviceResponseVerified) {
        restoreRecord[@"restoreResponseVerified"] = @YES;
        restoreRecord[@"restoreCachePublished"] = @YES;
        restoreRecord[@"restoreStateReleased"] = @YES;
        restoreRecord[@"restoreResponseLength"] =
            @(report.serviceResponseLength);
        restoreRecord[@"restoreResponseSHA256"] = stockSHA;
        restoreRecord[@"restoreResponseAt"] =
            @([[NSDate date] timeIntervalSince1970]);
    }
    bool responsePersisted = report.serviceResponseVerified &&
        themer_agent_publication_journal_store(restoreRecord);
    printf("[ICONSERVICES_AGENT_RESTORE] response transaction=%s "
           "object=0x%llx class=%s captured=%d contract=%d "
           "length=%llu sha256=%s cg=%llux%llu cache=%d/%d "
           "stateReleased=%d journalUpdated=%d transport=%d "
           "directStoreCalls=0\n",
           report.transaction, (unsigned long long)response,
           report.serviceResponseClass[0]
                ? report.serviceResponseClass : "-",
           captured, responseContract,
           (unsigned long long)report.serviceResponseLength,
           report.serviceResponseSHA256[0]
                ? report.serviceResponseSHA256 : "-",
           (unsigned long long)cgWidth,
           (unsigned long long)cgHeight,
           report.cachePublished,
           report.cacheReadbackVerified,
           stateReleased,
           responsePersisted, remote_call_current_success());
    if (responsePersisted) {
        report.result = ThemerSpotlightAgentPreflightReady;
        snprintf(report.reason, sizeof(report.reason),
                 "stock-response-cached-and-retention-released");
    } else {
        report.result = remote_call_current_success()
            ? ThemerSpotlightAgentPreflightVerificationFailed
            : ThemerSpotlightAgentPreflightTransportFailed;
        snprintf(report.reason, sizeof(report.reason),
                 "stock-agent-response-unverified");
    }

restore_finished:
    report.transportClean = remote_call_current_success();
    if (!report.transportClean) {
        report.result = ThemerSpotlightAgentPreflightTransportFailed;
    }
    printf("[ICONSERVICES_AGENT_RESTORE] summary result=%d target=%s "
           "transaction=%s dispatchPossible=%d response=%d/%llu/%s "
           "cache=%d/%d associationPresent=%d transport=%d reason=%s "
           "directStoreCalls=0 fileMutations=0\n",
           report.result,
           report.targetBundle[0] ? report.targetBundle : "-",
           report.transaction[0] ? report.transaction : "-",
           report.serviceDispatchPossible,
           report.serviceResponseVerified,
           (unsigned long long)report.serviceResponseLength,
           report.serviceResponseSHA256[0]
                ? report.serviceResponseSHA256 : "-",
           report.cachePublished,
           report.cacheReadbackVerified,
           report.transportClean
                ? r_is_objc_ptr(themer_agent_publication_state()) : 1,
           report.transportClean,
           report.reason[0] ? report.reason : "-");
    if (r_is_objc_ptr(targetIcon) && remote_call_current_success()) {
        r_msg2(targetIcon, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(descriptor) && remote_call_current_success()) {
        r_msg2(descriptor, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(namedDescriptor) && remote_call_current_success()) {
        r_msg2(namedDescriptor, "release", 0, 0, 0, 0);
    }
    themer_iconservices_lab_free_data_capture(&responseCapture);
    themer_iconservices_lab_free_data_capture(&tokenCapture);
    if (reportOut) *reportOut = report;
    return report.result;
}

ThemerSpotlightStock68MaterializationResult
themer_spotlight_stock68_materialize_in_session(
    const char *targetBundle,
    const char *themeFingerprint,
    volatile int *stopRequested,
    ThemerSpotlightStock68MaterializationReport *reportOut)
{
    uint64_t startUS = themer_now_us();
    ThemerSpotlightStock68MaterializationReport report = {0};
    report.recordIdentifiersCandidateIndexUUIDFirstOffset = -1;
    report.recordIdentifiersCandidateIndexTokenFirstOffset = -1;
    // The decoded leaf is local memory only. It remains alive through the
    // generation sample/token comparison and is freed at the common finish
    // barrier; no remote pointer leaves this session.
    ThemerIconServicesLabRecordIdentifiersObservation observation = {0};
    if (targetBundle) {
        snprintf(report.targetBundle, sizeof(report.targetBundle), "%s",
                 targetBundle);
    }
    if (themeFingerprint) {
        snprintf(report.themeFingerprint, sizeof(report.themeFingerprint), "%s",
                 themeFingerprint);
    }
    ThemerSpotlightStock68MaterializationResult result =
        ThemerSpotlightStock68MaterializationResultTransportFailed;
    // Initialized before every goto.  A known return before the generation
    // boundary can therefore commit an explicit transaction-local
    // no-dispatch certificate even if transport health has since degraded.
    bool journalPrepared = false;
    bool generationBoundaryReached = false;
    bool dispatchPossible = false;
    bool noDispatchCertified = false;
    bool correlationTransportFailed = false;
    if (!targetBundle || !targetBundle[0] ||
        !themeFingerprint || strlen(themeFingerprint) != 64) {
        result = ThemerSpotlightStock68MaterializationResultNoEligibleTarget;
        goto finish;
    }
    if (!remote_call_current_success()) goto finish;
    if (themer_spotlight_has_armed_recovery_in_session()) {
        result = ThemerSpotlightStock68MaterializationResultStatePresent;
        goto finish;
    }
    if (stopRequested && *stopRequested) {
        result = ThemerSpotlightStock68MaterializationResultCancelled;
        goto finish;
    }

    ThemerStock68MaterializationContext context = {0};
    if (!themer_stock68_acquire_context(targetBundle, &context)) {
        result = remote_call_current_success()
            ? ThemerSpotlightStock68MaterializationResultUnsupportedABI
            : ThemerSpotlightStock68MaterializationResultTransportFailed;
        themer_stock68_release_context(&context);
        goto finish;
    }
    snprintf(report.namedDigest, sizeof(report.namedDigest), "%s",
             context.namedDigest);

    ThemerIconServicesLabTopologySnapshot before = {0};
    bool beforeCaptured = themer_stock68_capture_strict_topology(
        context.canonicalCache, "materialization-before", &before);
    report.baselineKeyCount = before.keyCount;
    const ThemerIconServicesLabSnapshotKey *beforeNamed =
        themer_iconservices_lab_snapshot_key_for_text(
            &before, context.namedDigest);
    report.baselineNamedEntryCount = beforeNamed ? beforeNamed->entryCount : 0;
    int baseline68Count = 0;
    const ThemerIconServicesLabSnapshotEntry *existing68 = NULL;
    if (beforeNamed) {
        for (int i = 0; i < beforeNamed->entryCount; i++) {
            if (themer_stock68_entry_is_68(
                    &beforeNamed->entries[i], context.namedScale)) {
                baseline68Count++;
                existing68 = &beforeNamed->entries[i];
            }
        }
    }
    report.baselineHad68 = baseline68Count > 0;
    if (!beforeCaptured || !remote_call_current_success()) {
        result = ThemerSpotlightStock68MaterializationResultUnsupportedABI;
        if (!remote_call_current_success()) {
            result = ThemerSpotlightStock68MaterializationResultTransportFailed;
        }
        themer_stock68_release_context(&context);
        goto finish;
    }
    if (report.baselineHad68 && beforeNamed) {
        bool valid = baseline68Count == 1 && existing68 &&
            themer_stock68_validate_identity(
                existing68->image, targetBundle, themeFingerprint,
                context.namedDigest, context.managerCachePath,
                context.namedScale, true, &report);
        printf("[ICONSERVICES_MATERIALIZE] baseline-stock68 count=%d "
               "unique=%d valid=%d\n",
               baseline68Count,
               baseline68Count == 1,
               valid);
        result = valid
            ? ThemerSpotlightStock68MaterializationResultAlreadyPresent
            : ThemerSpotlightStock68MaterializationResultVerificationFailed;
        themer_stock68_release_context(&context);
        goto finish;
    }

    char generatedDigest[160] = {0};
    bool descriptorABI = false;
    uint64_t generatedDescriptor =
        themer_stock68_make_generation_descriptor(
            context.namedScale, generatedDigest,
            sizeof(generatedDigest), &descriptorABI);
    snprintf(report.generatedDigest, sizeof(report.generatedDigest), "%s",
             generatedDigest);
    if (!descriptorABI || !r_is_objc_ptr(generatedDescriptor)) {
        result = ThemerSpotlightStock68MaterializationResultUnsupportedABI;
        themer_stock68_release_context(&context);
        goto finish;
    }

    bool storeRegistrationABI = !themer_stock68_topology_exactly_empty(&before) ||
        themer_stock68_registration_preflight(context.managerCache, context.managerCachePath);
    if (!storeRegistrationABI) {
        result = remote_call_current_success() ? ThemerSpotlightStock68MaterializationResultUnsupportedABI
            : ThemerSpotlightStock68MaterializationResultTransportFailed;
        if (remote_call_current_success()) r_msg2(generatedDescriptor, "release", 0, 0, 0, 0);
        themer_stock68_release_context(&context);
        goto finish;
    }

    uint64_t originalBags = before.dictionary;
    char setterTypes[192] = {0};
    bool setterABI = themer_stock68_exact_bag_setter_abi(
        context.canonicalCache, setterTypes, sizeof(setterTypes));
    printf("[ICONSERVICES_MATERIALIZE] materialization-setter-abi "
           "types=\"%s\" ready=%d\n", setterTypes, setterABI);
    if (!setterABI) {
        result = remote_call_current_success()
            ? ThemerSpotlightStock68MaterializationResultUnsupportedABI
            : ThemerSpotlightStock68MaterializationResultTransportFailed;
        if (remote_call_current_success()) {
            r_msg2(generatedDescriptor, "release", 0, 0, 0, 0);
        }
        themer_stock68_release_context(&context);
        goto finish;
    }
    themer_stock68_prearm_before("original-dictionary-retain");
    uint64_t retainedOriginalBags = r_msg2(
        originalBags, "retain", 0, 0, 0, 0);
    bool originalRetained = r_is_objc_ptr(retainedOriginalBags) &&
        remote_call_current_success();
    themer_stock68_prearm_log("after", "original-dictionary-retain",
                              originalRetained);
    if (!originalRetained) {
        result = remote_call_current_success()
            ? ThemerSpotlightStock68MaterializationResultUnsupportedABI
            : ThemerSpotlightStock68MaterializationResultTransportFailed;
        if (remote_call_current_success()) {
            r_msg2(generatedDescriptor, "release", 0, 0, 0, 0);
        }
        themer_stock68_release_context(&context);
        goto finish;
    }
    char baselineFingerprint[THEMER_STOCK68_FINGERPRINT_CAP] = {0};
    bool baselineFingerprintKnown =
        themer_stock68_strict_fingerprint(
            &before, baselineFingerprint, sizeof(baselineFingerprint));
    themer_stock68_prearm_before("state-class-get");
    uint64_t dictionaryClass = r_class("NSMutableDictionary");
    bool dictionaryClassReady = r_is_objc_ptr(dictionaryClass) &&
        remote_call_current_success();
    themer_stock68_prearm_log("after", "state-class-get",
                              dictionaryClassReady);
    if (!dictionaryClassReady) {
        result = remote_call_current_success()
            ? ThemerSpotlightStock68MaterializationResultUnsupportedABI
            : ThemerSpotlightStock68MaterializationResultTransportFailed;
        if (remote_call_current_success()) {
            r_msg2(retainedOriginalBags, "release", 0, 0, 0, 0);
        }
        if (remote_call_current_success()) {
            r_msg2(generatedDescriptor, "release", 0, 0, 0, 0);
        }
        themer_stock68_release_context(&context);
        goto finish;
    }
    themer_stock68_prearm_before("state-alloc");
    uint64_t stateAlloc = dictionaryClassReady &&
        remote_call_current_success()
        ? r_msg2(dictionaryClass, "alloc", 0, 0, 0, 0) : 0;
    bool stateAllocReady = r_is_objc_ptr(stateAlloc) &&
        remote_call_current_success();
    themer_stock68_prearm_log("after", "state-alloc", stateAllocReady);
    if (!stateAllocReady || !baselineFingerprintKnown) {
        result = remote_call_current_success()
            ? ThemerSpotlightStock68MaterializationResultUnsupportedABI
            : ThemerSpotlightStock68MaterializationResultTransportFailed;
        if (r_is_objc_ptr(stateAlloc) && remote_call_current_success()) {
            r_msg2(stateAlloc, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(retainedOriginalBags) &&
            remote_call_current_success()) {
            r_msg2(retainedOriginalBags, "release", 0, 0, 0, 0);
        }
        if (remote_call_current_success()) {
            r_msg2(generatedDescriptor, "release", 0, 0, 0, 0);
        }
        themer_stock68_release_context(&context);
        goto finish;
    }
    themer_stock68_prearm_before("state-init");
    uint64_t state = r_is_objc_ptr(stateAlloc)
        ? r_msg2_main(stateAlloc, "initWithCapacity:", 16, 0, 0, 0) : 0;
    bool stateInitialized = r_is_objc_ptr(state) &&
        remote_call_current_success();
    bool stateReady = stateInitialized;
    themer_stock68_prearm_log("after", "state-init", stateInitialized);
    uint64_t pidNumber = 0;
    uint64_t countNumber = 0;
    uint64_t requestNumber = 0;
    if (stateReady) {
        pidNumber = themer_stock68_prearm_number(
            "pid", (unsigned long long)remote_call_current_pid());
        stateReady = r_is_objc_ptr(pidNumber) &&
            remote_call_current_success();
    }
    if (stateReady) {
        stateReady = themer_stock68_prearm_set_field(
            state, "pid", pidNumber);
    }
    if (stateReady) {
        stateReady = themer_stock68_prearm_set_field(
            state, "cache", context.canonicalCache);
    }
    if (stateReady) {
        stateReady = themer_stock68_prearm_set_field(
            state, "originalBags", retainedOriginalBags);
    }
    if (stateReady) {
        countNumber = themer_stock68_prearm_number(
            "originalCount", (unsigned long long)before.dictionaryCount);
        stateReady = r_is_objc_ptr(countNumber) &&
            remote_call_current_success();
    }
    if (stateReady) {
        stateReady = themer_stock68_prearm_set_field(
            state, "originalCount", countNumber);
    }
    if (stateReady) {
        stateReady = themer_stock68_prearm_set_field(
            state, "namedDescriptor", context.namedDescriptor);
    }
    if (stateReady) {
        stateReady = themer_stock68_prearm_set_field(
            state, "generatedDescriptor", generatedDescriptor);
    }
    if (stateReady) {
        requestNumber = themer_stock68_prearm_number("requestIssued", 0);
        stateReady = r_is_objc_ptr(requestNumber) &&
            remote_call_current_success();
    }
    if (stateReady) {
        stateReady = themer_stock68_prearm_set_field(
            state, "requestIssued", requestNumber);
    }
    if (stateReady) {
        stateReady = themer_stock68_prearm_set_string(
            state, "targetBundle", targetBundle);
    }
    if (stateReady) {
        stateReady = themer_stock68_prearm_set_string(
            state, "themeFingerprint", themeFingerprint);
    }
    if (stateReady) {
        stateReady = themer_stock68_prearm_set_string(
            state, "baselineFingerprint", baselineFingerprint);
    }
    bool prearmed = stateReady &&
        themer_stock68_materialization_commit_state(state);
    printf("[ICONSERVICES_MATERIALIZE] recovery-prearm state=0x%llx "
           "original=0x%llx count=%d ready=%d fieldsReady=%d\n",
           (unsigned long long)state,
           (unsigned long long)retainedOriginalBags,
           before.dictionaryCount,
           prearmed,
           stateReady);
    if (!prearmed) {
        // Completed fields followed by an unproven association commit require
        // recovery even if the transport itself still reports healthy.
        result = !remote_call_current_success()
            ? ThemerSpotlightStock68MaterializationResultTransportFailed
            : stateReady
                ? ThemerSpotlightStock68MaterializationResultRollbackFailed
                : ThemerSpotlightStock68MaterializationResultUnsupportedABI;
        if (r_is_objc_ptr(retainedOriginalBags) &&
            remote_call_current_success()) {
            r_msg2(retainedOriginalBags, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(state) && remote_call_current_success()) {
            r_msg2(state, "release", 0, 0, 0, 0);
        }
        // initWithCapacity: has run at this point.  If it returned nil, its
        // ownership/partial teardown is initializer-defined; do not send a
        // speculative release to the pre-initialized allocation.
        if (r_is_objc_ptr(generatedDescriptor) &&
            remote_call_current_success()) {
            r_msg2(generatedDescriptor, "release", 0, 0, 0, 0);
        }
        themer_stock68_release_context(&context);
        goto finish;
    }
    if (stopRequested && *stopRequested) {
        bool cleared = themer_stock68_materialization_clear_state();
        result = cleared
            ? ThemerSpotlightStock68MaterializationResultCancelled
            : ThemerSpotlightStock68MaterializationResultTransportFailed;
        goto materialization_cleanup;
    }

    bool alreadyClaimed = false;
    bool guardReady = themer_stock68_materialization_guard_claim(
        &alreadyClaimed);
    if (!guardReady) {
        result = ThemerSpotlightStock68MaterializationResultTransportFailed;
        goto materialization_cleanup;
    }
    if (alreadyClaimed) {
        bool stateCleared = themer_stock68_materialization_clear_state();
        result = stateCleared
            ? ThemerSpotlightStock68MaterializationResultStatePresent
            : ThemerSpotlightStock68MaterializationResultTransportFailed;
        goto materialization_cleanup;
    }
    bool journalPersisted = themer_stock68_local_journal_persist(
        targetBundle, themeFingerprint, context.namedDigest,
        generatedDigest);
    if (!journalPersisted) {
        // A partial local journal is itself a durable recovery marker. No
        // generation dispatch is permitted until all identity fields read
        // back successfully.
        result = ThemerSpotlightStock68MaterializationResultTransportFailed;
        goto materialization_cleanup;
    }
    journalPrepared = true;
    // requestIssued is remote preflight state.  It is intentionally written
    // before the durable dispatch marker so a remote request bit cannot be
    // mistaken for entry into the generation helper.
    uint64_t requestIssuedNumber = themer_stock68_prearm_number(
        "requestIssued", 1);
    bool requestMarked = r_is_objc_ptr(requestIssuedNumber) &&
        themer_stock68_prearm_set_field(
            state, "requestIssued", requestIssuedNumber);
    bool requestABI = false;
    bool generationInvoked = false;
    ThemerStock68GenerationDispatchContext dispatchContext = {
        targetBundle, themeFingerprint, context.namedDigest, generatedDigest,
        remote_call_current_pid(), remote_call_current_proc(),
        remote_call_current_task()
    };
    uint64_t generatedImage = requestMarked
        ? themer_iconservices_lab_generation_request(
            context.canonicalIcon, generatedDescriptor,
            &requestABI, &observation, &generationInvoked,
            &dispatchPossible,
            themer_stock68_generation_dispatch_marker,
            &dispatchContext)
        : 0;
    generationBoundaryReached = generationInvoked;
    report.requestCount = generationInvoked ? 1 : 0;
    report.recordIdentifiersDecodeStatus = observation.decodeStatus;
    report.recordIdentifiersDecodeNodes = observation.decodeNodes;
    report.recordIdentifiersDecodeMetadata = observation.decodeMetadata;
    report.recordIdentifiersOwnershipVerified =
        observation.observed && observation.holderArgumentMatches &&
        observation.argumentsRetained && observation.transportClean;
    themer_record_blob_copy_to_report(&observation.firstBlob, &report);
    printf("[ICONSERVICES_MATERIALIZE] request invoke marked=%d "
           "abi=%d invoked=%d result=0x%llx deferredInvocation=0x%llx "
           "deferredSlot=0x%llx cancelDeferred=%d\n",
           requestMarked,
           requestABI,
           generationInvoked,
           (unsigned long long)generatedImage,
           (unsigned long long)observation.generationInvocation,
           (unsigned long long)observation.outSlot,
           stopRequested && *stopRequested);

    if (!generationBoundaryReached && journalPrepared &&
        !dispatchPossible) {
        // This can only certify the freshly created V2 transaction above;
        // it never upgrades an existing or legacy journal.
        noDispatchCertified =
            themer_stock68_local_journal_persist_no_dispatch_certificate(
                targetBundle, themeFingerprint, context.namedDigest,
                generatedDigest);
    }

    ThemerIconServicesLabGenerationSample generationSample = {0};
    bool generationCaptured = r_is_objc_ptr(generatedImage) &&
        themer_iconservices_lab_capture_generation_sample(
            "stock68-materialization", generatedImage,
            68.0, 68.0, context.namedScale, &generationSample);
    themer_record_blob_compare_token(&observation.firstBlob,
                                     &generationSample, &report);
    bool recordCandidateClassified = themer_stock68_parse_record_candidate(
        &observation.firstBlob, &generationSample, &report);
    bool generationCoherent = generationCaptured &&
        generationSample.coherent && requestABI && generationInvoked &&
        observation.exactABI && observation.observed &&
        observation.binderInvoked && observation.retainerInvoked &&
        observation.holderArgumentMatches && observation.argumentsRetained &&
        observation.directArgumentMatches &&
        observation.directArgumentsRetained &&
        observation.ownerBoundPostDispatch &&
        observation.transportClean;

    ThemerIconServicesLabTopologySnapshot after = {0};
    bool afterCaptured = themer_stock68_capture_strict_topology(
        context.canonicalCache, "materialization-after", &after);
    if (!remote_call_current_success()) {
        result = ThemerSpotlightStock68MaterializationResultTransportFailed;
        themer_iconservices_lab_release_generation_sample(&generationSample);
        goto materialization_cleanup;
    }
    char afterFingerprint[THEMER_STOCK68_FINGERPRINT_CAP] = {0};
    bool afterFingerprintKnown = afterCaptured &&
        themer_stock68_strict_fingerprint(
            &after, afterFingerprint, sizeof(afterFingerprint));
    report.finalKeyCount = after.keyCount;
    report.dictionaryChanged = beforeCaptured && afterFingerprintKnown &&
        strcmp(baselineFingerprint, afterFingerprint) != 0;
    themer_iconservices_lab_log_topology_delta(
        "materialization-before", &before,
        "materialization-after", &after);
    const ThemerIconServicesLabSnapshotKey *afterNamed =
        themer_iconservices_lab_snapshot_key_for_text(
            &after, context.namedDigest);
    report.finalNamedEntryCount = afterNamed ? afterNamed->entryCount : 0;
    const ThemerIconServicesLabSnapshotEntry *newNamedEntry = NULL;
    report.newNamed68Count = themer_stock68_count_new_68(
        beforeNamed, afterNamed, context.namedScale, &newNamedEntry);
    report.wrongKey68Count = themer_stock68_count_wrong_key_new_68(
        &before, &after, context.namedDigest, context.namedScale);
    bool afterComplete = afterCaptured && afterFingerprintKnown;
    int expectedNamedCount = (beforeNamed ? beforeNamed->entryCount : 0) + 1;
    bool namedOnly = afterComplete && generationCoherent &&
        report.newNamed68Count == 1 && report.wrongKey68Count == 0 &&
        afterNamed && afterNamed->entryCount == expectedNamedCount &&
        themer_stock68_baseline_entries_preserved(beforeNamed, afterNamed) &&
        themer_stock68_other_keys_unchanged(
            &before, &after, context.namedDigest);
    bool identityValid = namedOnly && newNamedEntry &&
        themer_stock68_validate_identity(
            newNamedEntry->image, targetBundle, themeFingerprint,
            context.namedDigest, context.managerCachePath,
            context.namedScale, true, &report);
    printf("[ICONSERVICES_MATERIALIZE] topology-classification "
           "complete=%d coherent=%d changed=%d newNamed68=%d "
           "wrongKey68=%d namedOnly=%d identity=%d\n",
           afterComplete,
           generationCoherent,
           report.dictionaryChanged,
           report.newNamed68Count,
           report.wrongKey68Count,
           namedOnly,
           identityValid);

    bool exactEmptyUnchanged = generationCoherent && generationInvoked &&
        themer_stock68_topology_exactly_empty(&before) &&
        themer_stock68_topology_exactly_empty(&after) &&
        afterFingerprintKnown &&
        strcmp(baselineFingerprint, afterFingerprint) == 0;

    bool pendingCleanupBeforeClear =
        themer_spotlight_iconservices_has_pending_recovery();
    if (identityValid && generationInvoked && !pendingCleanupBeforeClear) {
        bool cleared = themer_stock68_materialization_clear_state();
        bool journalCleared = cleared && themer_stock68_local_journal_clear();
        result = cleared && journalCleared
            ? ThemerSpotlightStock68MaterializationResultMaterialized
            : ThemerSpotlightStock68MaterializationResultTransportFailed;
    } else if (!generationInvoked && noDispatchCertified &&
               !pendingCleanupBeforeClear && remote_call_current_success() &&
               afterFingerprintKnown &&
               strcmp(baselineFingerprint, afterFingerprint) == 0) {
        // The preflight failed before dispatch, so there is no remote
        // generation to recover. Clear the provisional journal only after the
        // exact unchanged baseline and process-state removal are verified.
        bool stateCleared = themer_stock68_materialization_clear_state();
        bool journalCleared = stateCleared &&
            themer_stock68_local_journal_clear();
        result = stateCleared && journalCleared
            ? ThemerSpotlightStock68MaterializationResultUnsupportedABI
            : ThemerSpotlightStock68MaterializationResultTransportFailed;
    } else if (exactEmptyUnchanged) {
        // A coherent direct image proves the request reached IconServices even
        // when no record was materialized into the exact empty dictionary.
        // Restore first. Only the exact eligible record may enter the bounded
        // journaled store round trip; every other issued request stays armed.
        report.rollbackAttempted = true;
        report.rollbackVerified =
            themer_stock68_restore_materialization_state(state);
        result = report.rollbackVerified
            ? ThemerSpotlightStock68MaterializationResultIssuedUnmaterializedRecoveryRequired
            : ThemerSpotlightStock68MaterializationResultRollbackFailed;
        if (report.rollbackVerified && recordCandidateClassified && !pendingCleanupBeforeClear &&
            remote_call_current_pid() == dispatchContext.pid &&
            remote_call_current_proc() == dispatchContext.proc &&
            remote_call_current_task() == dispatchContext.task)
            result = themer_stock68_registration_roundtrip(&context, state, originalBags, baselineFingerprint,
                &generationSample, &observation.firstBlob, &report);
        printf("[ICONSERVICES_MATERIALIZE] issued-unmaterialized "
               "exactEmpty=1 coherent=%d restore=%d result=%d "
               "journalPresent=%d decodeStatus=%d\n",
               generationCoherent,
               report.rollbackVerified,
               result, themer_stock68_local_journal_has_any_key(),
               report.recordIdentifiersDecodeStatus);
    } else {
        report.rollbackAttempted = true;
        report.rollbackVerified =
            themer_stock68_restore_materialization_state(state);
        // An issued or transport-uncertain generation is never reported as
        // unchanged. Keep both the remote recovery dictionary and journal so
        // store cleanup can be proven by a later recovery pass.
        result = ThemerSpotlightStock68MaterializationResultRollbackFailed;
    }
    if (recordCandidateClassified && remote_call_current_success() &&
        !themer_stock68_local_journal_dictionary()[@"storeRegistration"]) {
        // This runs after the materialization result has been derived.  Its
        // read-only store/file observations cannot affect topology, journal,
        // recovery, or the result classification above.
        themer_stock68_correlate_record_candidate(
            context.managerCache, context.managerCachePath, context.namedScale,
            &generationSample, &report);
        correlationTransportFailed = !remote_call_current_success();
    }
    themer_iconservices_lab_release_generation_sample(&generationSample);

materialization_cleanup:
    if (r_is_objc_ptr(retainedOriginalBags) &&
        remote_call_current_success()) {
        r_msg2(retainedOriginalBags, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(state) && remote_call_current_success()) {
        r_msg2(state, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(generatedDescriptor) &&
        remote_call_current_success()) {
        r_msg2(generatedDescriptor, "release", 0, 0, 0, 0);
    }
    themer_stock68_release_context(&context);

finish:;
    themer_iconservices_lab_free_data_capture(&observation.firstBlob.capture);
    if (!remote_call_current_success() && !correlationTransportFailed) {
        result = themer_stock68_local_journal_dictionary()[@"storeRegistration"]
            ? ThemerSpotlightStock68MaterializationResultStoreRegisteredRecoveryRequired
            : ThemerSpotlightStock68MaterializationResultTransportFailed;
    }
    RemoteCallDebugSnapshot summarySnapshot = {0};
    bool summarySnapshotCopied =
        remote_call_copy_debug_snapshot(&summarySnapshot);
    printf("[ICONSERVICES_MATERIALIZE] summary result=%d pid=%d target=%s "
           "fingerprint=%.16s requests=%d baselineKeys=%d finalKeys=%d "
           "baselineNamed=%d finalNamed=%d baseline68=%d newNamed68=%d "
           "wrongKey68=%d uuid=%d token=%d file=%d reconstruction=%d "
           "changed=%d rollback=%d/%d total=%llums ioFailures=%llu "
           "recordIdentifiersDecodeStatus=%d decodeNodes=%d "
           "decodeMetadata=%d recordIdentifiersOwnership=%d "
           "recordBlob=%d/%llu/%llu truncated=%d format=%s sha256=%s "
           "blobToken=%d/%d/%d candidate=%d/%d/%d uuid=%s "
           "candidateFile=%d/%d/%d/%d/%d/%llu unit=%d/%d/%d/%s "
           "index=%llu@%lld/%llu@%lld reconstruct=%d/%d/%d/%d/%d/%d "
           "snapshot=%d stableCalls=%llu stableFailures=%llu "
           "lastStableCall=%s lastStableFailure=%s "
           "lastStableFailureReason=%s\n",
           result,
           remote_call_current_pid(),
           report.targetBundle[0] ? report.targetBundle : "-",
           report.themeFingerprint,
           report.requestCount,
           report.baselineKeyCount,
           report.finalKeyCount,
           report.baselineNamedEntryCount,
           report.finalNamedEntryCount,
           report.baselineHad68,
           report.newNamed68Count,
           report.wrongKey68Count,
           report.uuidValid,
           report.tokenValid,
           report.fileValid,
           report.reconstructionValid,
           report.dictionaryChanged,
           report.rollbackAttempted,
           report.rollbackVerified,
           (unsigned long long)((themer_now_us() - startUS) / 1000ULL),
           (unsigned long long)remote_call_current_io_failure_count(),
           report.recordIdentifiersDecodeStatus,
           report.recordIdentifiersDecodeNodes,
           report.recordIdentifiersDecodeMetadata,
           report.recordIdentifiersOwnershipVerified,
           report.recordIdentifiersBlobCaptured,
           (unsigned long long)report.recordIdentifiersBlobTotalLength,
           (unsigned long long)report.recordIdentifiersBlobCapturedLength,
           report.recordIdentifiersBlobTruncated,
           report.recordIdentifiersBlobFormat[0] ? report.recordIdentifiersBlobFormat : "-",
           report.recordIdentifiersBlobSHA256[0] ? report.recordIdentifiersBlobSHA256 : "-",
           report.recordIdentifiersBlobEqualsToken,
           report.recordIdentifiersBlobContainsToken,
           report.recordIdentifiersTokenContainsBlob,
           report.recordIdentifiersCandidateParsed,
           report.recordIdentifiersCandidateTokenBound,
           report.recordIdentifiersCandidateClassified,
           report.recordIdentifiersCandidateUUID[0]
               ? report.recordIdentifiersCandidateUUID : "-",
           report.recordIdentifiersCandidateFileExists,
           report.recordIdentifiersCandidateFileRegular,
           report.recordIdentifiersCandidateFileReadable,
           report.recordIdentifiersCandidateFileNonempty,
           report.recordIdentifiersCandidateFileExactSize,
           (unsigned long long)report.recordIdentifiersCandidateFileSize,
           report.recordIdentifiersCandidateStoreLookupABI,
           report.recordIdentifiersCandidateStoreLookupAttempted,
           report.recordIdentifiersCandidateStoreUnitFound,
           report.recordIdentifiersCandidateStoreUnitClass[0]
               ? report.recordIdentifiersCandidateStoreUnitClass : "-",
           (unsigned long long)report.recordIdentifiersCandidateIndexUUIDOccurrences,
           (long long)report.recordIdentifiersCandidateIndexUUIDFirstOffset,
           (unsigned long long)report.recordIdentifiersCandidateIndexTokenOccurrences,
           (long long)report.recordIdentifiersCandidateIndexTokenFirstOffset,
           report.recordIdentifiersCandidateReconstructionAttempted,
           report.recordIdentifiersCandidateReconstructionClass,
           report.recordIdentifiersCandidateReconstructionUUIDEqual,
           report.recordIdentifiersCandidateReconstructionTokenEqual,
           report.recordIdentifiersCandidateReconstructionGeometry,
           report.recordIdentifiersCandidateReconstructionFileEqual,
           summarySnapshotCopied,
           (unsigned long long)summarySnapshot.stableCalls,
           (unsigned long long)summarySnapshot.stableFailures,
           summarySnapshotCopied ? summarySnapshot.lastStableCall : "-",
           summarySnapshotCopied ? summarySnapshot.lastStableFailure : "-",
           summarySnapshotCopied
               ? summarySnapshot.lastStableFailureReason : "-");
    if (reportOut) *reportOut = report;
    return result;
}

ThemerSpotlightStock68MaterializationResult
themer_spotlight_stock68_verify_in_session(
    const char *targetBundle,
    const char *themeFingerprint,
    ThemerSpotlightStock68MaterializationReport *reportOut)
{
    ThemerSpotlightStock68MaterializationReport report = {0};
    if (targetBundle) {
        snprintf(report.targetBundle, sizeof(report.targetBundle), "%s",
                 targetBundle);
    }
    if (themeFingerprint) {
        snprintf(report.themeFingerprint, sizeof(report.themeFingerprint), "%s",
                 themeFingerprint);
    }
    if (!targetBundle || !targetBundle[0] || !themeFingerprint ||
        strlen(themeFingerprint) != 64) {
        if (reportOut) *reportOut = report;
        return ThemerSpotlightStock68MaterializationResultVerificationFailed;
    }
    if (!remote_call_current_success()) {
        if (reportOut) *reportOut = report;
        return ThemerSpotlightStock68MaterializationResultTransportFailed;
    }
    if (themer_spotlight_has_armed_recovery_in_session()) {
        if (reportOut) *reportOut = report;
        return remote_call_current_success()
            ? ThemerSpotlightStock68MaterializationResultStatePresent
            : ThemerSpotlightStock68MaterializationResultTransportFailed;
    }
    ThemerStock68MaterializationContext context = {0};
    if (!themer_stock68_acquire_context(targetBundle, &context)) {
        themer_stock68_release_context(&context);
        if (reportOut) *reportOut = report;
        return remote_call_current_success()
            ? ThemerSpotlightStock68MaterializationResultUnsupportedABI
            : ThemerSpotlightStock68MaterializationResultTransportFailed;
    }
    snprintf(report.namedDigest, sizeof(report.namedDigest), "%s",
             context.namedDigest);
    ThemerIconServicesLabTopologySnapshot snapshot = {0};
    bool captured = themer_stock68_capture_strict_topology(
        context.canonicalCache, "materialization-verify", &snapshot);
    const ThemerIconServicesLabSnapshotKey *named =
        themer_iconservices_lab_snapshot_key_for_text(
            &snapshot, context.namedDigest);
    int matches = 0;
    int total68 = 0;
    if (captured && named && !snapshot.keysTruncated &&
        !named->entriesTruncated) {
        for (int i = 0; i < named->entryCount; i++) {
            if (!themer_stock68_entry_is_68(
                    &named->entries[i], context.namedScale)) {
                continue;
            }
            total68++;
            ThemerSpotlightStock68MaterializationReport candidate = report;
            if (themer_stock68_validate_identity(
                    named->entries[i].image,
                    targetBundle, themeFingerprint,
                    context.namedDigest, context.managerCachePath,
                    context.namedScale, false, &candidate)) {
                report = candidate;
                matches++;
            }
        }
    }
    report.finalKeyCount = snapshot.keyCount;
    report.finalNamedEntryCount = named ? named->entryCount : 0;
    report.freshVerification = total68 == 1 && matches == 1 &&
        remote_call_current_success();
    printf("[ICONSERVICES_MATERIALIZE] verify-fresh-session pid=%d "
           "target=%s fingerprint=%.16s digest=\"%s\" total68=%d "
           "matches=%d verified=%d\n",
           remote_call_current_pid(),
           targetBundle,
           themeFingerprint,
           context.namedDigest,
           total68,
           matches,
           report.freshVerification);
    themer_stock68_release_context(&context);
    if (!remote_call_current_success()) {
        report.freshVerification = false;
        if (reportOut) *reportOut = report;
        return ThemerSpotlightStock68MaterializationResultTransportFailed;
    }
    if (reportOut) *reportOut = report;
    return report.freshVerification
        ? ThemerSpotlightStock68MaterializationResultAlreadyPresent
        : ThemerSpotlightStock68MaterializationResultVerificationFailed;
}

static bool themer_iconservices_lab_construction_probe(
    const ThemerIconServicesLabDiscovery *d,
    uint64_t themedImage,
    bool *readyOut)
{
    if (readyOut) *readyOut = false;
    if (!d || !remote_call_current_success()) return false;
    uint64_t ioFailuresBefore = remote_call_current_io_failure_count();

    const ThemerIconServicesLabBagEntry *donorEntry = NULL;
    const char *donorRole = "stock68";
    for (int i = 0; i < d->stockEntryCount; i++) {
        const ThemerIconServicesLabBagEntry *entry = &d->stockEntries[i];
        if (entry->geometryKnown &&
            themer_iconservices_lab_sizes_match(
                entry->width, entry->height, 68.0, 68.0)) {
            donorEntry = entry;
            break;
        }
    }
    if (!donorEntry && d->primaryEntryIndex >= 0 &&
        d->primaryEntryIndex < d->stockEntryCount &&
        d->stockEntries[d->primaryEntryIndex].geometryKnown) {
        donorEntry = &d->stockEntries[d->primaryEntryIndex];
        donorRole = "stock40-fallback";
    }
    if (!donorEntry || !r_is_objc_ptr(themedImage)) {
        printf("[ICONSERVICES_LAB] construction-probe unavailable "
               "donor=%d themed=0x%llx ioFailures=%llu\n",
               donorEntry != NULL,
               (unsigned long long)themedImage,
               (unsigned long long)ioFailuresBefore);
        return remote_call_current_success();
    }

    uint64_t donor = donorEntry->image;
    double donorWidth = donorEntry->width;
    double donorHeight = donorEntry->height;
    double donorScale = donorEntry->scale;
    char donorClass[96] = {0};
    char themedClass[96] = {0};
    themer_read_class_name(donor, donorClass, sizeof(donorClass));
    themer_read_class_name(themedImage, themedClass, sizeof(themedClass));
    bool donorClassOK = strcmp(donorClass, "IFCacheImage") == 0;

    uint64_t themedData = themer_iconservices_lab_retained_getter(
        themedImage, "data");
    uint64_t themedBitmapData = themer_iconservices_lab_retained_getter(
        themedImage, "bitmapData");
    ThemerIconServicesLabDataCapture themedDataCapture = {0};
    ThemerIconServicesLabDataCapture themedBitmapCapture = {0};
    bool themedDataCaptured = r_is_objc_ptr(themedData) &&
        themer_iconservices_lab_capture_nsdata(
            themedData, THEMER_ICONSERVICES_LAB_DATA_CAPTURE_CAP,
            &themedDataCapture);
    bool themedBitmapCaptured = r_is_objc_ptr(themedBitmapData) &&
        themer_iconservices_lab_capture_nsdata(
            themedBitmapData, THEMER_ICONSERVICES_LAB_DATA_CAPTURE_CAP,
            &themedBitmapCapture);
    bool themedDataUsable = themedDataCaptured &&
        themedDataCapture.objectLength > 0;

    char themedDataPrefix[65] = {0};
    char themedBitmapPrefix[65] = {0};
    themer_iconservices_lab_hex_bytes(
        themedDataCapture.bytes,
        themedDataCapture.capturedLength < 32
            ? themedDataCapture.capturedLength : 32,
        themedDataPrefix, sizeof(themedDataPrefix));
    themer_iconservices_lab_hex_bytes(
        themedBitmapCapture.bytes,
        themedBitmapCapture.capturedLength < 32
            ? themedBitmapCapture.capturedLength : 32,
        themedBitmapPrefix, sizeof(themedBitmapPrefix));
    uint8_t themedDataSHA1[20] = {0};
    uint8_t themedDataSHA256[32] = {0};
    char themedDataSHA1Hex[41] = {0};
    char themedDataSHA256Hex[65] = {0};
    bool themedDataSHA1Known = themedDataUsable &&
        !themedDataCapture.truncated &&
        themer_iconservices_lab_digest(
            "CC_SHA1", themedDataCapture.bytes,
            themedDataCapture.capturedLength, themedDataSHA1);
    bool themedDataSHA256Known = themedDataUsable &&
        !themedDataCapture.truncated &&
        themer_iconservices_lab_digest(
            "CC_SHA256", themedDataCapture.bytes,
            themedDataCapture.capturedLength, themedDataSHA256);
    themer_iconservices_lab_hex_bytes(
        themedDataSHA1, sizeof(themedDataSHA1),
        themedDataSHA1Hex, sizeof(themedDataSHA1Hex));
    themer_iconservices_lab_hex_bytes(
        themedDataSHA256, sizeof(themedDataSHA256),
        themedDataSHA256Hex, sizeof(themedDataSHA256Hex));

    double themedPixelW = 0.0, themedPixelH = 0.0;
    double themedMinimumW = 0.0, themedMinimumH = 0.0;
    double themedIconW = 0.0, themedIconH = 0.0;
    bool themedProperties =
        themer_iconservices_lab_read_size_property(
            themedImage, "pixelSize", &themedPixelW, &themedPixelH) &&
        themer_iconservices_lab_read_size_property(
            themedImage, "minimumSize", &themedMinimumW, &themedMinimumH) &&
        themer_iconservices_lab_read_size_property(
            themedImage, "iconSize", &themedIconW, &themedIconH);

    printf("[ICONSERVICES_LAB] construction-probe themed=0x%llx "
           "class=%s dataCaptured=%d data=0x%llx/%zu/%zu/truncated=%d "
           "prefix=%s bitmapCaptured=%d "
           "bitmap=0x%llx/%zu/%zu/truncated=%d prefix=%s "
           "sha1=%s%s sha256=%s%s properties=%d "
           "pixel=%.1fx%.1f minimum=%.1fx%.1f icon=%.1fx%.1f\n",
           (unsigned long long)themedImage,
           themedClass[0] ? themedClass : "-",
           themedDataCaptured,
           (unsigned long long)themedData,
           themedDataCapture.objectLength,
           themedDataCapture.capturedLength,
           themedDataCapture.truncated,
           themedDataPrefix,
           themedBitmapCaptured,
           (unsigned long long)themedBitmapData,
           themedBitmapCapture.objectLength,
           themedBitmapCapture.capturedLength,
           themedBitmapCapture.truncated,
           themedBitmapPrefix,
           themedDataSHA1Known ? "" : "?", themedDataSHA1Hex,
           themedDataSHA256Known ? "" : "?", themedDataSHA256Hex,
           themedProperties,
           themedPixelW, themedPixelH,
           themedMinimumW, themedMinimumH,
           themedIconW, themedIconH);

    uint64_t donorData = donorClassOK
        ? themer_iconservices_lab_retained_getter(donor, "data") : 0;
    uint64_t donorUuid = donorClassOK
        ? themer_iconservices_lab_retained_getter(donor, "uuid") : 0;
    uint64_t donorToken = donorClassOK
        ? themer_iconservices_lab_retained_getter(
            donor, "validationToken") : 0;

    uint64_t uuidClass = r_class("NSUUID");
    uint64_t uuidAlloc = r_is_objc_ptr(uuidClass)
        ? r_msg2(uuidClass, "alloc", 0, 0, 0, 0) : 0;
    uint64_t freshUuid = r_is_objc_ptr(uuidAlloc)
        ? r_msg2_main(uuidAlloc, "init", 0, 0, 0, 0) : 0;
    uint64_t freshImage = themedDataUsable && r_is_objc_ptr(freshUuid)
        ? themer_iconservices_lab_make_if_cache_image_without_token(
            themedData, freshUuid) : 0;
    char freshClass[96] = {0};
    themer_read_class_name(freshImage, freshClass, sizeof(freshClass));
    bool freshClassOK = strcmp(freshClass, "IFCacheImage") == 0;
    uint64_t freshData = freshClassOK && r_responds_main(freshImage, "data")
        ? r_msg2_main(freshImage, "data", 0, 0, 0, 0) : 0;
    uint64_t freshReadUuid = freshClassOK &&
        r_responds_main(freshImage, "uuid")
        ? r_msg2_main(freshImage, "uuid", 0, 0, 0, 0) : 0;
    uint64_t freshToken = freshClassOK
        ? themer_iconservices_lab_retained_getter(
            freshImage, "validationToken") : 0;
    ThemerIconServicesLabDataCapture freshTokenCapture = {0};
    bool freshTokenCaptured = r_is_objc_ptr(freshToken) &&
        themer_iconservices_lab_capture_nsdata(
            freshToken, THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP,
            &freshTokenCapture);
    char freshTokenHex[129] = {0};
    themer_iconservices_lab_hex_bytes(
        freshTokenCapture.bytes,
        freshTokenCapture.capturedLength < 64
            ? freshTokenCapture.capturedLength : 64,
        freshTokenHex, sizeof(freshTokenHex));
    bool freshDataEqual = themer_iconservices_lab_objects_equal(
        freshData, themedData);
    bool freshUuidEqual = themer_iconservices_lab_objects_equal(
        freshReadUuid, freshUuid);
    bool freshTokenNil = !r_is_objc_ptr(freshToken);
    bool freshTokenDiffers = r_is_objc_ptr(freshToken) &&
        r_is_objc_ptr(donorToken) &&
        !themer_iconservices_lab_objects_equal(freshToken, donorToken);
    bool freshTokenAcceptable = freshTokenNil ||
        (freshTokenCaptured && freshTokenCapture.objectLength > 0 &&
         freshTokenDiffers);
    bool freshGeometry = freshClassOK &&
        themer_iconservices_lab_image_geometry_matches(
            freshImage, 68.0, 68.0, d->descScale);

    double freshPixelW = 0.0, freshPixelH = 0.0;
    double freshMinimumW = 0.0, freshMinimumH = 0.0;
    double freshIconW = 0.0, freshIconH = 0.0;
    bool freshPropertyParity = themedProperties &&
        themer_iconservices_lab_read_size_property(
            freshImage, "pixelSize", &freshPixelW, &freshPixelH) &&
        themer_iconservices_lab_read_size_property(
            freshImage, "minimumSize", &freshMinimumW, &freshMinimumH) &&
        themer_iconservices_lab_read_size_property(
            freshImage, "iconSize", &freshIconW, &freshIconH) &&
        themer_iconservices_lab_sizes_match(
            themedPixelW, themedPixelH, freshPixelW, freshPixelH) &&
        themer_iconservices_lab_sizes_match(
            themedMinimumW, themedMinimumH, freshMinimumW, freshMinimumH) &&
        themer_iconservices_lab_sizes_match(
            themedIconW, themedIconH, freshIconW, freshIconH);
    uint64_t freshCGImage = freshClassOK &&
        r_responds_main(freshImage, "CGImage")
        ? r_msg2_main(freshImage, "CGImage", 0, 0, 0, 0) : 0;
    uint64_t freshPixelWidth = freshCGImage
        ? r_dlsym_call(R_TIMEOUT, "CGImageGetWidth",
                       freshCGImage, 0, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t freshPixelHeight = freshCGImage
        ? r_dlsym_call(R_TIMEOUT, "CGImageGetHeight",
                       freshCGImage, 0, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t freshImages[1] = {freshImage};
    uint64_t freshBag = freshClassOK
        ? themer_iconservices_lab_make_bag_from_images(freshImages, 1) : 0;
    uint64_t freshRouted = r_is_objc_ptr(freshBag)
        ? themer_iconservices_lab_image_for_size_scale(
            freshBag, 68.0, 68.0, d->descScale) : 0;
    bool freshRouteExact = themer_spotlight_images_match(
        freshImage, freshRouted);
    uint64_t expectedThemedPixel =
        (uint64_t)(68.0 * d->descScale + 0.5);
    bool freshReady = freshClassOK && freshDataEqual && freshUuidEqual &&
        freshTokenAcceptable && freshGeometry && freshPropertyParity &&
        freshCGImage && freshPixelWidth == expectedThemedPixel &&
        freshPixelHeight == expectedThemedPixel &&
        r_is_objc_ptr(freshBag) && freshRouteExact &&
        remote_call_current_success();

    printf("[ICONSERVICES_LAB] construction-probe fresh=0x%llx "
           "class=%s classOK=%d uuid=0x%llx/read=0x%llx/equal=%d "
           "dataEqual=%d token=0x%llx/%zu/%zu/truncated=%d hex=%s "
           "tokenNil=%d tokenDiffersFromDonor=%d tokenAcceptable=%d "
           "geometry=%d propertyParity=%d "
           "pixel=%.1fx%.1f minimum=%.1fx%.1f icon=%.1fx%.1f "
           "cgImage=0x%llx pixels=%llux%llu bag=0x%llx "
           "routed=0x%llx exact=%d ready=%d\n",
           (unsigned long long)freshImage,
           freshClass[0] ? freshClass : "-",
           freshClassOK,
           (unsigned long long)freshUuid,
           (unsigned long long)freshReadUuid,
           freshUuidEqual,
           freshDataEqual,
           (unsigned long long)freshToken,
           freshTokenCapture.objectLength,
           freshTokenCapture.capturedLength,
           freshTokenCapture.truncated,
           freshTokenHex,
           freshTokenNil,
           freshTokenDiffers,
           freshTokenAcceptable,
           freshGeometry,
           freshPropertyParity,
           freshPixelW, freshPixelH,
           freshMinimumW, freshMinimumH,
           freshIconW, freshIconH,
           (unsigned long long)freshCGImage,
           (unsigned long long)freshPixelWidth,
           (unsigned long long)freshPixelHeight,
           (unsigned long long)freshBag,
           (unsigned long long)freshRouted,
           freshRouteExact,
           freshReady);

    uint64_t stockClone = donorClassOK && r_is_objc_ptr(donorData) &&
        r_is_objc_ptr(donorUuid) && r_is_objc_ptr(donorToken)
        ? themer_iconservices_lab_make_if_cache_image(
            donorData, donorUuid, donorToken) : 0;
    char stockCloneClass[96] = {0};
    themer_read_class_name(
        stockClone, stockCloneClass, sizeof(stockCloneClass));
    bool stockCloneClassOK = strcmp(stockCloneClass, "IFCacheImage") == 0;
    uint64_t stockCloneData = stockCloneClassOK &&
        r_responds_main(stockClone, "data")
        ? r_msg2_main(stockClone, "data", 0, 0, 0, 0) : 0;
    uint64_t stockCloneUuid = stockCloneClassOK &&
        r_responds_main(stockClone, "uuid")
        ? r_msg2_main(stockClone, "uuid", 0, 0, 0, 0) : 0;
    uint64_t stockTokenBefore = stockCloneClassOK
        ? themer_iconservices_lab_retained_getter(
            stockClone, "validationToken") : 0;
    bool stockCloneExact = stockCloneClassOK &&
        themer_iconservices_lab_objects_equal(stockCloneData, donorData) &&
        themer_iconservices_lab_objects_equal(stockCloneUuid, donorUuid) &&
        themer_iconservices_lab_objects_equal(stockTokenBefore, donorToken) &&
        themer_iconservices_lab_image_geometry_matches(
            stockClone, donorWidth, donorHeight, donorScale);

    char setDataTypes[192] = {0};
    bool setDataSupported = stockCloneClassOK &&
        r_responds_main(stockClone, "setData:") &&
        themer_iconservices_lab_method_types(
            stockClone, "setData:", setDataTypes, sizeof(setDataTypes)) &&
        setDataTypes[0] == 'v';
    bool setDataApplied = false;
    if (stockCloneExact && themedDataUsable && setDataSupported) {
        r_msg2_main(stockClone, "setData:", themedData, 0, 0, 0);
        setDataApplied = remote_call_current_success();
    }

    uint64_t stockTokenAfter = setDataApplied
        ? themer_iconservices_lab_retained_getter(
            stockClone, "validationToken") : 0;
    ThemerIconServicesLabDataCapture stockTokenBeforeCapture = {0};
    ThemerIconServicesLabDataCapture stockTokenAfterCapture = {0};
    bool stockTokenBeforeCaptured = r_is_objc_ptr(stockTokenBefore) &&
        themer_iconservices_lab_capture_nsdata(
            stockTokenBefore, THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP,
            &stockTokenBeforeCapture);
    bool stockTokenAfterCaptured = r_is_objc_ptr(stockTokenAfter) &&
        themer_iconservices_lab_capture_nsdata(
            stockTokenAfter, THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP,
            &stockTokenAfterCapture);
    char stockTokenBeforeHex[129] = {0};
    char stockTokenAfterHex[129] = {0};
    themer_iconservices_lab_hex_bytes(
        stockTokenBeforeCapture.bytes,
        stockTokenBeforeCapture.capturedLength < 64
            ? stockTokenBeforeCapture.capturedLength : 64,
        stockTokenBeforeHex, sizeof(stockTokenBeforeHex));
    themer_iconservices_lab_hex_bytes(
        stockTokenAfterCapture.bytes,
        stockTokenAfterCapture.capturedLength < 64
            ? stockTokenAfterCapture.capturedLength : 64,
        stockTokenAfterHex, sizeof(stockTokenAfterHex));
    bool setDataTokenChanged = stockTokenBeforeCaptured &&
        stockTokenAfterCaptured &&
        !themer_iconservices_lab_objects_equal(
            stockTokenBefore, stockTokenAfter);
    uint64_t setDataReadback = setDataApplied &&
        r_responds_main(stockClone, "data")
        ? r_msg2_main(stockClone, "data", 0, 0, 0, 0) : 0;
    bool setDataEqual = setDataApplied &&
        themer_iconservices_lab_objects_equal(setDataReadback, themedData);
    bool setDataGeometry = setDataApplied &&
        themer_iconservices_lab_image_geometry_matches(
            stockClone, 68.0, 68.0, d->descScale);
    double setDataPixelW = 0.0, setDataPixelH = 0.0;
    double setDataMinimumW = 0.0, setDataMinimumH = 0.0;
    double setDataIconW = 0.0, setDataIconH = 0.0;
    bool setDataPropertyParity = setDataApplied && themedProperties &&
        themer_iconservices_lab_read_size_property(
            stockClone, "pixelSize", &setDataPixelW, &setDataPixelH) &&
        themer_iconservices_lab_read_size_property(
            stockClone, "minimumSize", &setDataMinimumW, &setDataMinimumH) &&
        themer_iconservices_lab_read_size_property(
            stockClone, "iconSize", &setDataIconW, &setDataIconH) &&
        themer_iconservices_lab_sizes_match(
            themedPixelW, themedPixelH, setDataPixelW, setDataPixelH) &&
        themer_iconservices_lab_sizes_match(
            themedMinimumW, themedMinimumH,
            setDataMinimumW, setDataMinimumH) &&
        themer_iconservices_lab_sizes_match(
            themedIconW, themedIconH, setDataIconW, setDataIconH);
    uint64_t setDataCGImage = setDataApplied &&
        r_responds_main(stockClone, "CGImage")
        ? r_msg2_main(stockClone, "CGImage", 0, 0, 0, 0) : 0;
    uint64_t setDataPixelWidth = setDataCGImage
        ? r_dlsym_call(R_TIMEOUT, "CGImageGetWidth",
                       setDataCGImage, 0, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t setDataPixelHeight = setDataCGImage
        ? r_dlsym_call(R_TIMEOUT, "CGImageGetHeight",
                       setDataCGImage, 0, 0, 0, 0, 0, 0, 0) : 0;
    uint64_t setDataImages[1] = {stockClone};
    uint64_t setDataBag = setDataApplied && stockCloneClassOK
        ? themer_iconservices_lab_make_bag_from_images(setDataImages, 1) : 0;
    uint64_t setDataRouted = r_is_objc_ptr(setDataBag)
        ? themer_iconservices_lab_image_for_size_scale(
            setDataBag, 68.0, 68.0, d->descScale) : 0;
    bool setDataRouteExact = themer_spotlight_images_match(
        stockClone, setDataRouted);
    bool setDataReady = setDataApplied && setDataEqual &&
        stockTokenAfterCaptured && stockTokenAfterCapture.objectLength > 0 &&
        setDataTokenChanged && setDataGeometry && setDataPropertyParity &&
        setDataCGImage && setDataPixelWidth == expectedThemedPixel &&
        setDataPixelHeight == expectedThemedPixel &&
        r_is_objc_ptr(setDataBag) && setDataRouteExact &&
        remote_call_current_success();

    printf("[ICONSERVICES_LAB] construction-probe setdata donor=0x%llx/%s "
           "stockClone=0x%llx class=%s exact=%d supported=%d types=\"%s\" "
           "applied=%d dataEqual=%d tokenBefore=0x%llx/%zu/%s "
           "tokenAfter=0x%llx/%zu/%s tokenChanged=%d geometry=%d "
           "propertyParity=%d pixel=%.1fx%.1f minimum=%.1fx%.1f "
           "icon=%.1fx%.1f cgImage=0x%llx pixels=%llux%llu "
           "bag=0x%llx routed=0x%llx exactRoute=%d ready=%d\n",
           (unsigned long long)donor,
           donorRole,
           (unsigned long long)stockClone,
           stockCloneClass[0] ? stockCloneClass : "-",
           stockCloneExact,
           setDataSupported,
           setDataTypes,
           setDataApplied,
           setDataEqual,
           (unsigned long long)stockTokenBefore,
           stockTokenBeforeCapture.objectLength,
           stockTokenBeforeHex,
           (unsigned long long)stockTokenAfter,
           stockTokenAfterCapture.objectLength,
           stockTokenAfterHex,
           setDataTokenChanged,
           setDataGeometry,
           setDataPropertyParity,
           setDataPixelW, setDataPixelH,
           setDataMinimumW, setDataMinimumH,
           setDataIconW, setDataIconH,
           (unsigned long long)setDataCGImage,
           (unsigned long long)setDataPixelWidth,
           (unsigned long long)setDataPixelHeight,
           (unsigned long long)setDataBag,
           (unsigned long long)setDataRouted,
           setDataRouteExact,
           setDataReady);

    if (r_is_objc_ptr(setDataBag) && remote_call_current_success()) {
        r_msg2(setDataBag, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(freshBag) && remote_call_current_success()) {
        r_msg2(freshBag, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(freshImage) && remote_call_current_success()) {
        r_msg2(freshImage, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(stockClone) && remote_call_current_success()) {
        r_msg2(stockClone, "release", 0, 0, 0, 0);
    }

    bool donorReadable = remote_call_current_success() &&
        themer_iconservices_lab_image_geometry_matches(
            donor, donorWidth, donorHeight, donorScale);
    uint64_t ioFailuresAfter = remote_call_current_io_failure_count();
    bool transportClean = remote_call_current_success() &&
        ioFailuresAfter == ioFailuresBefore;
    bool constructionReady = transportClean && donorReadable &&
        (freshReady || setDataReady);
    printf("[ICONSERVICES_LAB] construction-probe cleanup "
           "donor=0x%llx donorReadable=%d freshReady=%d setDataReady=%d "
           "ioFailures=%llu->%llu transportClean=%d ready=%d\n",
           (unsigned long long)donor,
           donorReadable,
           freshReady,
           setDataReady,
           (unsigned long long)ioFailuresBefore,
           (unsigned long long)ioFailuresAfter,
           transportClean,
           constructionReady);

    if (r_is_objc_ptr(stockTokenAfter) && remote_call_current_success()) {
        r_msg2(stockTokenAfter, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(stockTokenBefore) && remote_call_current_success()) {
        r_msg2(stockTokenBefore, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(freshToken) && remote_call_current_success()) {
        r_msg2(freshToken, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(freshUuid) && remote_call_current_success()) {
        r_msg2(freshUuid, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(donorToken) && remote_call_current_success()) {
        r_msg2(donorToken, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(donorUuid) && remote_call_current_success()) {
        r_msg2(donorUuid, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(donorData) && remote_call_current_success()) {
        r_msg2(donorData, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(themedBitmapData) && remote_call_current_success()) {
        r_msg2(themedBitmapData, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(themedData) && remote_call_current_success()) {
        r_msg2(themedData, "release", 0, 0, 0, 0);
    }
    themer_iconservices_lab_free_data_capture(&stockTokenAfterCapture);
    themer_iconservices_lab_free_data_capture(&stockTokenBeforeCapture);
    themer_iconservices_lab_free_data_capture(&freshTokenCapture);
    themer_iconservices_lab_free_data_capture(&themedBitmapCapture);
    themer_iconservices_lab_free_data_capture(&themedDataCapture);
    if (readyOut) *readyOut = constructionReady;
    return remote_call_current_success();
}

// Returns 1 on success, 0 for an unsupported IconServices contract,
// -1 for no eligible icon, and -2 for transport failure. Descriptor
// availability is host-wide because the lab resolves IconServices' named
// Spotlight descriptor; it is not inferred from per-bundle cache contents.
static int themer_iconservices_lab_discover(
    NSDictionary<NSString *, NSData *> *normalized,
    volatile int *stopRequested,
    bool consumeMaterializationTrace,
    ThemerIconServicesLabDiscovery *d)
{
    memset(d, 0, sizeof(*d));
    d->primaryEntryIndex = -1;
    if (!remote_call_current_success()) return -2;
    if (!normalized) return -1;
    if (!themer_ensure_iconservices_loaded()) {
        printf("[ICONSERVICES_LAB] discovery unsupported reason=iconservices-unavailable\n");
        return 0;
    }
    if (!remote_call_current_success()) return -2;
    d->loaded = true;

    // Runtime metadata only: enumerate the generation/token/cache contract on
    // the device before invoking any IconServices object method.
    themer_iconservices_lab_log_generation_surfaces_once();
    if (!remote_call_current_success()) return -2;

    uint64_t mgrCls = themer_lookup_class("ISIconManager");
    if (!remote_call_current_success()) return -2;
    if (!r_is_objc_ptr(mgrCls) || !r_responds_main(mgrCls, "sharedInstance")) {
        printf("[ICONSERVICES_LAB] discovery unsupported reason=manager-unavailable\n");
        return 0;
    }
    d->manager = r_msg2_main(mgrCls, "sharedInstance", 0, 0, 0, 0);
    if (!remote_call_current_success()) return -2;
    if (!r_is_objc_ptr(d->manager)) {
        printf("[ICONSERVICES_LAB] discovery unsupported reason=manager-nil\n");
        return 0;
    }

    // Manager-level iconCache stays read-only in this pass.
    if (r_responds_main(d->manager, "iconCache")) {
        d->managerIconCache = r_msg2_main(d->manager, "iconCache",
                                          0, 0, 0, 0);
        if (!remote_call_current_success()) return -2;
        if (r_is_objc_ptr(d->managerIconCache)) {
            d->managerCacheContract =
                r_responds_main(d->managerIconCache,
                                "setImage:forDescriptor:") &&
                r_responds_main(d->managerIconCache,
                                "imageForDescriptor:");
            if (r_responds_main(d->managerIconCache, "cachePath")) {
                uint64_t path = r_msg2_main(d->managerIconCache,
                                            "cachePath", 0, 0, 0, 0);
                if (remote_call_current_success() &&
                    r_is_objc_ptr(path)) {
                    d->managerCachePathKnown =
                        r_read_nsstring(path, d->managerCachePath,
                                        sizeof(d->managerCachePath));
                }
            }
        }
    }
    if (!remote_call_current_success()) return -2;
    if (r_is_objc_ptr(d->managerIconCache)) {
        themer_iconservices_lab_log_store_filesystem_access(
            d->managerIconCache);
    }
    if (!remote_call_current_success()) return -2;

    int selected = themer_iconservices_lab_select_bundles(
        normalized, stopRequested,
        d->targetBundle, sizeof(d->targetBundle),
        d->controlBundle, sizeof(d->controlBundle));
    if (!remote_call_current_success()) return -2;
    if (selected < 1 || !d->targetBundle[0]) {
        printf("[ICONSERVICES_LAB] discovery no-eligible-icon reason=no-theme-bundle\n");
        return -1;
    }
    d->haveControl = selected >= 2 && d->controlBundle[0];

    // Local icon and its pre-registration imageCache.
    d->localIcon = themer_iconservices_lab_make_bundle_icon(d->targetBundle);
    if (!remote_call_current_success()) return -2;
    if (!r_is_objc_ptr(d->localIcon)) {
        printf("[ICONSERVICES_LAB] discovery unsupported "
               "reason=local-icon-unconstructible bundle=%s\n",
               d->targetBundle);
        return 0;
    }
    if (r_responds_main(d->localIcon, "imageCache")) {
        d->localCache = r_msg2_main(d->localIcon, "imageCache", 0, 0, 0, 0);
    }
    if (!remote_call_current_success()) return -2;
    d->localCacheWritable = r_is_objc_ptr(d->localCache) &&
        r_responds_main(d->localCache, "setImage:forDescriptor:") &&
        r_responds_main(d->localIcon, "imageForDescriptor:");

    // Canonical registration is an acquisition step only; never a seed.
    if (!r_responds_main(d->manager, "findOrRegisterIcon:")) {
        printf("[ICONSERVICES_LAB] discovery unsupported "
               "reason=findOrRegisterIcon-unavailable\n");
        return 0;
    }
    d->canonicalIcon = r_msg2_main(d->manager, "findOrRegisterIcon:",
                                   d->localIcon, 0, 0, 0);
    if (!remote_call_current_success()) return -2;
    if (!r_is_objc_ptr(d->canonicalIcon)) {
        printf("[ICONSERVICES_LAB] discovery unsupported "
               "reason=canonical-registration-failed bundle=%s\n",
               d->targetBundle);
        return 0;
    }
    if (r_responds_main(d->canonicalIcon, "imageCache")) {
        d->canonicalCache = r_msg2_main(d->canonicalIcon, "imageCache",
                                        0, 0, 0, 0);
    }
    if (!remote_call_current_success()) return -2;
    d->canonicalCacheWritable = r_is_objc_ptr(d->canonicalCache) &&
        r_responds_main(d->canonicalCache, "setImage:forDescriptor:") &&
        r_responds_main(d->canonicalIcon, "imageForDescriptor:");
    d->localCacheDistinct = d->localCache != d->canonicalCache;

    if (d->haveControl) {
        uint64_t controlLocal = themer_iconservices_lab_make_bundle_icon(
            d->controlBundle);
        if (!remote_call_current_success()) return -2;
        if (r_is_objc_ptr(controlLocal)) {
            d->controlCanonicalIcon = r_msg2_main(
                d->manager, "findOrRegisterIcon:", controlLocal, 0, 0, 0);
            r_msg2(controlLocal, "release", 0, 0, 0, 0);
            if (!remote_call_current_success()) return -2;
        }
        if (r_is_objc_ptr(d->controlCanonicalIcon) &&
            r_responds_main(d->controlCanonicalIcon, "imageCache")) {
            d->controlCanonicalCache = r_msg2_main(
                d->controlCanonicalIcon, "imageCache", 0, 0, 0, 0);
        }
        if (!remote_call_current_success()) return -2;
    }

    if (!themer_iconservices_lab_capture_topology(
            d->canonicalCache, "before-descriptor",
            &d->beforeDescriptorSnapshot)) {
        return -2;
    }
    d->traceResult = consumeMaterializationTrace
        ? themer_iconservices_lab_trace_follow_up(
            d->targetBundle, &d->beforeDescriptorSnapshot)
        : ThemerIconServicesLabTraceNoState;
    if (!remote_call_current_success()) return -2;

    // Resolve IconServices' authoritative named Spotlight descriptor. The
    // image-bag dictionary is a lazy cache and may legitimately remain empty;
    // it is telemetry only and never the descriptor source.
    d->descriptor = themer_iconservices_lab_named_spotlight_descriptor(
        &d->descriptorSymbol,
        &d->descriptorNameObject,
        &d->descriptorLiteralFallback);
    if (!remote_call_current_success()) return -2;
    if (!r_is_objc_ptr(d->descriptor)) {
        printf("[ICONSERVICES_LAB] discovery unsupported "
               "reason=named-spotlight-descriptor-unavailable symbol=0x%llx\n",
               (unsigned long long)d->descriptorSymbol);
        return 0;
    }
    themer_iconservices_lab_log_descriptor("named-spotlight", d->descriptor);
    if (!themer_iconservices_lab_capture_topology(
            d->canonicalCache, "before-prepare",
            &d->beforePrepareSnapshot)) {
        return -2;
    }
    themer_iconservices_lab_log_topology_delta(
        "before-descriptor", &d->beforeDescriptorSnapshot,
        "before-prepare", &d->beforePrepareSnapshot);
    uint64_t prePrepareBags = d->beforePrepareSnapshot.dictionary;
    if (r_is_objc_ptr(prePrepareBags) &&
        r_responds_main(prePrepareBags, "mutableCopy")) {
        d->prePrepareBagsCopy = r_msg2_main(
            prePrepareBags, "mutableCopy", 0, 0, 0, 0);
        if (!remote_call_current_success()) return -2;
        if (r_is_objc_ptr(d->prePrepareBagsCopy)) {
            d->prePrepareBagsCount =
                (int)themer_remote_count(d->prePrepareBagsCopy);
            d->prePrepareBagsCopyKnown = remote_call_current_success();
            d->prePrepareBagsEmpty = d->prePrepareBagsCopyKnown &&
                d->prePrepareBagsCount == 0;
        }
    }
    printf("[ICONSERVICES_LAB] pre-prepare-restore-copy source=0x%llx "
           "copy=0x%llx known=%d count=%d empty=%d\n",
           (unsigned long long)prePrepareBags,
           (unsigned long long)d->prePrepareBagsCopy,
           d->prePrepareBagsCopyKnown,
           d->prePrepareBagsCount,
           d->prePrepareBagsEmpty);

    d->stockTargetImage = themer_iconservices_lab_prepare_stock_image(
        d->canonicalIcon, d->descriptor,
        &d->prepareTargetResult, &d->prepareTargetSupported);
    if (!remote_call_current_success()) return -2;
    if (!themer_iconservices_lab_capture_topology(
            d->canonicalCache, "after-target-prepare",
            &d->afterTargetPrepareSnapshot)) {
        return -2;
    }
    themer_iconservices_lab_log_topology_delta(
        "before-prepare", &d->beforePrepareSnapshot,
        "after-target-prepare", &d->afterTargetPrepareSnapshot);

    d->stockLocalImage = themer_iconservices_lab_prepare_stock_image(
        d->localIcon, d->descriptor,
        &d->prepareLocalResult, &d->prepareLocalSupported);
    if (!remote_call_current_success()) return -2;
    if (r_is_objc_ptr(d->controlCanonicalIcon)) {
        d->stockControlImage = themer_iconservices_lab_prepare_stock_image(
            d->controlCanonicalIcon, d->descriptor,
            &d->prepareControlResult, &d->prepareControlSupported);
        if (!remote_call_current_success()) return -2;
    }
    if (!themer_iconservices_lab_capture_topology(
            d->canonicalCache, "after-all-prepare",
            &d->afterAllPrepareSnapshot)) {
        return -2;
    }
    themer_iconservices_lab_log_topology_delta(
        "after-target-prepare", &d->afterTargetPrepareSnapshot,
        "after-all-prepare", &d->afterAllPrepareSnapshot);
    themer_iconservices_lab_log_topology_delta(
        "before-prepare", &d->beforePrepareSnapshot,
        "after-all-prepare", &d->afterAllPrepareSnapshot);

    // Inspect image bags only after the real descriptor request. Retain the
    // exact object for an optional reversible bag-swap candidate, but do not
    // require it to contain a descriptor key.
    if (r_is_objc_ptr(d->canonicalCache) &&
        r_responds_main(d->canonicalCache, "imageBagsByDescriptor")) {
        uint64_t bags = r_msg2_main(d->canonicalCache,
                                    "imageBagsByDescriptor", 0, 0, 0, 0);
        if (!remote_call_current_success()) return -2;
        if (r_is_objc_ptr(bags)) {
            d->originalBags = r_msg2(bags, "retain", 0, 0, 0, 0);
            if (!remote_call_current_success()) return -2;
            d->bagsCount = (int)themer_remote_count(d->originalBags);
            if (!remote_call_current_success()) return -2;
            d->bagsReadWrite = r_responds_main(
                d->canonicalCache, "setImageBagsByDescriptor:");

            if (r_responds_main(d->originalBags, "objectForKey:")) {
                d->originalBagValue = r_msg2_main(
                    d->originalBags, "objectForKey:",
                    d->descriptor, 0, 0, 0);
                if (r_is_objc_ptr(d->originalBagValue)) {
                    d->originalBagKey = d->descriptor;
                    d->originalBagExactKey = true;
                    d->originalBagDigestKey = true;
                }
            }
            if (!r_is_objc_ptr(d->originalBagValue) &&
                r_responds_main(d->originalBags, "allKeys")) {
                uint64_t keys = r_msg2_main(
                    d->originalBags, "allKeys", 0, 0, 0, 0);
                int keyCount = (int)themer_remote_count(keys);
                int cap = keyCount < THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP
                    ? keyCount : THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP;
                for (int i = 0;
                     i < cap && remote_call_current_success(); i++) {
                    uint64_t key = r_msg2_main(
                        keys, "objectAtIndex:", (uint64_t)i, 0, 0, 0);
                    uint64_t value = r_msg2_main(
                        d->originalBags, "objectForKey:", key, 0, 0, 0);
                    bool equal = key == d->descriptor;
                    if (!equal && r_is_objc_ptr(key) &&
                        r_responds_main(key, "isEqual:")) {
                        equal = (r_msg2_main(key, "isEqual:",
                                             d->descriptor, 0, 0, 0) & 1) != 0;
                    }
                    bool digestEqual =
                        themer_iconservices_lab_bag_key_matches_descriptor(
                            d->descriptor, key);
                    char keyCls[96] = {0};
                    char valueCls[96] = {0};
                    char keyText[220] = {0};
                    themer_read_class_name(key, keyCls, sizeof(keyCls));
                    themer_read_class_name(value, valueCls, sizeof(valueCls));
                    themer_read_remote_description(key, keyText,
                                                   sizeof(keyText));
                    printf("[ICONSERVICES_LAB] bag-descriptor-key index=%d "
                           "key=0x%llx/%s value=0x%llx/%s equalNamed=%d "
                           "equalDigest=%d desc=\"%s\"\n",
                           i,
                           (unsigned long long)key,
                           keyCls[0] ? keyCls : "-",
                           (unsigned long long)value,
                           valueCls[0] ? valueCls : "-",
                           equal,
                           digestEqual,
                           keyText);
                    if (!r_is_objc_ptr(d->originalBagValue) &&
                        r_is_objc_ptr(value) && digestEqual) {
                        d->originalBagKey = key;
                        d->originalBagValue = value;
                        d->originalBagExactKey = equal;
                        d->originalBagDigestKey = true;
                    }
                }
            }
            if (r_is_objc_ptr(d->originalBagValue)) {
                printf("[ICONSERVICES_LAB] bag-compare role=original-stock "
                       "mutation=0\n");
                themer_iconservices_lab_log_bag_value(
                    d->originalBagValue, d->descriptor);
                printf("[ICONSERVICES_LAB] bag-compare-end "
                       "role=original-stock\n");
            } else {
                printf("[ICONSERVICES_LAB] bag-value missing descriptor=0x%llx "
                       "bags=%d\n",
                       (unsigned long long)d->descriptor,
                       d->bagsCount);
            }
        }
    }
    if (!remote_call_current_success()) return -2;
    themer_read_class_name(d->descriptor, d->descriptorClass,
                           sizeof(d->descriptorClass));
    themer_read_remote_description(d->descriptor, d->descriptorText,
                                   sizeof(d->descriptorText));
    struct { double w; double h; } size = {0.0, 0.0};
    d->descSizeOK = r_responds_main(d->descriptor, "size") &&
        r_msg2_main_struct_ret(d->descriptor, "size", &size, sizeof(size),
            NULL, 0, NULL, 0, NULL, 0, NULL, 0);
    if (d->descSizeOK) {
        d->descSizeW = size.w;
        d->descSizeH = size.h;
    }
    d->descScaleOK = false;
    d->descScale = themer_read_remote_double_property(
        d->descriptor, "scale", 0.0, &d->descScaleOK);
    d->descAppearance = themer_read_remote_uint_property(
        d->descriptor, "appearance", &d->descAppearanceOK);
    d->descAppearanceVariant = themer_read_remote_uint_property(
        d->descriptor, "appearanceVariant", &d->descAppearanceVariantOK);
    d->descIconVariant = themer_read_remote_uint_property(
        d->descriptor, "iconVariant", &d->descIconVariantOK);
    d->descVariantOptions = themer_read_remote_uint_property(
        d->descriptor, "variantOptions", &d->descVariantOptionsOK);
    d->descriptorPropsKnown = d->descSizeOK && d->descScaleOK;
    if (d->descriptorPropsKnown && r_is_objc_ptr(d->originalBagValue) &&
        r_responds_main(d->originalBagValue, "images")) {
        uint64_t stockImages = r_msg2_main(
            d->originalBagValue, "images", 0, 0, 0, 0);
        int stockCount = (int)themer_remote_count(stockImages);
        if (stockCount >= 1 &&
            stockCount <= THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP &&
            r_is_objc_ptr(stockImages) &&
            r_responds_main(stockImages, "objectAtIndex:")) {
            d->stockEntryCount = stockCount;
            d->stockTopologyKnown = true;
            for (int i = 0;
                 i < stockCount && remote_call_current_success(); i++) {
                ThemerIconServicesLabBagEntry *entry = &d->stockEntries[i];
                entry->image = r_msg2_main(
                    stockImages, "objectAtIndex:", (uint64_t)i, 0, 0, 0);
                entry->geometryKnown =
                    themer_iconservices_lab_read_image_geometry(
                        entry->image, &entry->width, &entry->height,
                        &entry->scale);
                if (!entry->geometryKnown) d->stockTopologyKnown = false;
                bool primary = entry->geometryKnown &&
                    themer_iconservices_lab_image_geometry_matches(
                        entry->image, d->descSizeW, d->descSizeH,
                        d->descScale);
                if (primary && d->primaryEntryIndex < 0) {
                    d->primaryEntryIndex = i;
                }
                printf("[ICONSERVICES_LAB] stock-bag-entry index=%d "
                       "image=0x%llx geometry=%d size=%.1fx%.1f "
                       "scale=%.2f primary=%d\n",
                       i,
                       (unsigned long long)entry->image,
                       entry->geometryKnown,
                       entry->width,
                       entry->height,
                       entry->scale,
                       primary);
            }
            d->stockTopologyKnown = d->stockTopologyKnown &&
                d->primaryEntryIndex >= 0 && remote_call_current_success();
        } else {
            printf("[ICONSERVICES_LAB] stock-bag-topology unsupported "
                   "count=%d cap=%d\n",
                   stockCount, THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP);
        }
        uint64_t primaryRoute =
            themer_iconservices_lab_image_for_size_scale(
                d->originalBagValue, d->descSizeW, d->descSizeH,
                d->descScale);
        printf("[ICONSERVICES_LAB] stock-bag-route-primary image=0x%llx "
               "exact=%d entryCount=%d primaryIndex=%d topologyKnown=%d\n",
               (unsigned long long)primaryRoute,
               themer_iconservices_lab_image_geometry_matches(
                   primaryRoute, d->descSizeW, d->descSizeH, d->descScale),
               d->stockEntryCount,
               d->primaryEntryIndex,
               d->stockTopologyKnown);
    }
    uint64_t descCls = themer_lookup_class("ISImageDescriptor");
    d->factoryRoute = r_is_objc_ptr(descCls) &&
        r_responds_main(descCls, "imageDescriptorWithIconVariant:options:");
    if (!remote_call_current_success()) return -2;

    if (r_responds_main(d->canonicalIcon, "imageForDescriptor:")) {
        d->stockTargetImage = r_msg2_main(d->canonicalIcon,
                                          "imageForDescriptor:",
                                          d->descriptor, 0, 0, 0);
    }
    if (r_is_objc_ptr(d->localIcon) &&
        r_responds_main(d->localIcon, "imageForDescriptor:")) {
        d->stockLocalImage = r_msg2_main(d->localIcon,
                                         "imageForDescriptor:",
                                         d->descriptor, 0, 0, 0);
    }
    if (d->managerCacheContract) {
        d->stockManagerImage = r_msg2_main(d->managerIconCache,
                                           "imageForDescriptor:",
                                           d->descriptor, 0, 0, 0);
    }
    if (r_is_objc_ptr(d->controlCanonicalIcon) &&
        r_responds_main(d->controlCanonicalIcon, "imageForDescriptor:")) {
        d->stockControlImage = r_msg2_main(d->controlCanonicalIcon,
                                           "imageForDescriptor:",
                                           d->descriptor, 0, 0, 0);
    }
    if (!remote_call_current_success()) return -2;

    d->hasDescriptorClear = themer_iconservices_lab_find_first_selector(
        d->canonicalCache,
        themer_iconservices_lab_descriptor_clears,
        sizeof(themer_iconservices_lab_descriptor_clears) /
            sizeof(themer_iconservices_lab_descriptor_clears[0]),
        d->descriptorClearSelector, sizeof(d->descriptorClearSelector));
    if (!remote_call_current_success()) return -2;
    d->hasIconInvalidator = themer_iconservices_lab_find_first_selector(
        d->canonicalIcon,
        themer_iconservices_lab_icon_invalidators,
        sizeof(themer_iconservices_lab_icon_invalidators) /
            sizeof(themer_iconservices_lab_icon_invalidators[0]),
        d->iconInvalidatorSelector, sizeof(d->iconInvalidatorSelector));
    if (!remote_call_current_success()) return -2;
    d->hasCacheClear = themer_iconservices_lab_find_first_selector(
        d->canonicalCache,
        themer_iconservices_lab_cache_clears,
        sizeof(themer_iconservices_lab_cache_clears) /
            sizeof(themer_iconservices_lab_cache_clears[0]),
        d->cacheClearSelector, sizeof(d->cacheClearSelector));
    if (!remote_call_current_success()) return -2;

    bool stockOK = r_is_objc_ptr(d->stockTargetImage);
    bool descOK = r_is_objc_ptr(d->descriptor);
    bool controlOK = d->haveControl &&
        r_is_objc_ptr(d->controlCanonicalIcon) &&
        r_is_objc_ptr(d->stockControlImage);
    bool localStockOK = stockOK && r_is_objc_ptr(d->stockLocalImage);
    bool managerStockOK = stockOK && r_is_objc_ptr(d->stockManagerImage);
    uint64_t mask = 0;
    if (!stockOK) {
        printf("[ICONSERVICES_LAB] discovery unsupported "
               "reason=named-spotlight-target-unreadable target=%s "
               "prepare=0x%llx supported=%d\n",
               d->targetBundle,
               (unsigned long long)d->prepareTargetResult,
               d->prepareTargetSupported);
    } else if (!controlOK) {
        printf("[ICONSERVICES_LAB] discovery unsupported "
               "reason=named-spotlight-control-unreadable target=%s control=%s "
               "prepare=0x%llx supported=%d\n",
               d->targetBundle,
               d->haveControl ? d->controlBundle : "-",
               (unsigned long long)d->prepareControlResult,
               d->prepareControlSupported);
    } else {
        if (descOK && localStockOK && d->localCacheDistinct &&
            d->localCacheWritable) {
            mask |= (1ULL << ThemerSpotlightIconServicesCandidateLocalExistingDescriptor);
        }
        if (descOK && stockOK && d->canonicalCacheWritable) {
            mask |= (1ULL << ThemerSpotlightIconServicesCandidateCanonicalExistingDescriptor);
        }
        // Factory/init clones are intentionally not promoted. The corrected
        // lab tests only IconServices' authoritative named Spotlight
        // descriptor rather than constructed approximations.
        if (descOK && stockOK && d->canonicalCacheWritable &&
            d->bagsReadWrite && r_is_objc_ptr(d->originalBagKey) &&
            r_is_objc_ptr(d->originalBagValue) &&
            d->stockTopologyKnown && d->stockEntryCount >= 1 &&
            d->primaryEntryIndex >= 0 &&
            d->originalBagDigestKey &&
            r_responds_main(d->originalBagValue, "initWithImages:") &&
            r_responds_main(d->originalBagValue, "imageForSize:scale:")) {
            mask |= (1ULL <<
                ThemerSpotlightIconServicesCandidateCanonicalBagSwap);
            if (d->prePrepareBagsCopyKnown &&
                r_is_objc_ptr(d->prePrepareBagsCopy)) {
                mask |= (1ULL <<
                    ThemerSpotlightIconServicesCandidateCanonicalMixedBag);
            }
        }
        if (descOK && stockOK && d->canonicalCacheWritable &&
            d->hasDescriptorClear) {
            mask |= (1ULL << ThemerSpotlightIconServicesCandidateCanonicalDescriptorClear);
        }
        if (descOK && stockOK && d->canonicalCacheWritable &&
            d->hasIconInvalidator) {
            mask |= (1ULL << ThemerSpotlightIconServicesCandidateCanonicalIconInvalidator);
        }
        if (descOK && stockOK && d->canonicalCacheWritable && d->hasCacheClear) {
            mask |= (1ULL << ThemerSpotlightIconServicesCandidateCanonicalCacheClear);
        }
        if (descOK && managerStockOK && d->managerCacheContract) {
            mask |= (1ULL << ThemerSpotlightIconServicesCandidateManagerCache);
        }
    }
    uint64_t mixedBit = UINT64_C(1) <<
        ThemerSpotlightIconServicesCandidateCanonicalMixedBag;
    d->supportedMask = mask & mixedBit;
    printf("[ICONSERVICES_LAB] discovery candidate-mask raw=0x%llx "
           "enabled=0x%llx policy=canonical-stock-preserved-themed68-store-only\n",
           (unsigned long long)mask,
           (unsigned long long)d->supportedMask);

    char localIconCls[96] = {0};
    char canonicalIconCls[96] = {0};
    char localCacheCls[96] = {0};
    char canonicalCacheCls[96] = {0};
    char managerCacheCls[96] = {0};
    themer_read_class_name(d->localIcon, localIconCls, sizeof(localIconCls));
    themer_read_class_name(d->canonicalIcon, canonicalIconCls,
                           sizeof(canonicalIconCls));
    if (r_is_objc_ptr(d->localCache)) {
        themer_read_class_name(d->localCache, localCacheCls,
                               sizeof(localCacheCls));
    }
    if (r_is_objc_ptr(d->canonicalCache)) {
        themer_read_class_name(d->canonicalCache, canonicalCacheCls,
                               sizeof(canonicalCacheCls));
    }
    if (r_is_objc_ptr(d->managerIconCache)) {
        themer_read_class_name(d->managerIconCache, managerCacheCls,
                               sizeof(managerCacheCls));
    }
    printf("[ICONSERVICES_LAB] discovery pid=%d target=%s control=%s "
           "localIcon=0x%llx/%s canonicalIcon=0x%llx/%s iconsSame=%d "
           "localCache=0x%llx/%s canonicalCache=0x%llx/%s cachesDistinct=%d "
           "canonicalWritable=%d managerCache=0x%llx/%s "
           "managerContract=%d cachePath=\"%s\" descriptorSource=named-spotlight "
           "descriptorSymbol=0x%llx descriptorName=0x%llx literalName=%d "
           "descriptor=0x%llx/%s prepareTarget=0x%llx/%d "
           "prepareLocal=0x%llx/%d prepareControl=0x%llx/%d "
           "stockTarget=0x%llx stockLocal=0x%llx stockManager=0x%llx "
           "stockControl=0x%llx preRestore=0x%llx/%d/empty=%d "
           "bags=%d bagsRW=%d bagKey=0x%llx bagValue=0x%llx "
           "bagEntries=%d primaryIndex=%d topologyKnown=%d "
           "bagExact=%d bagDigest=%d descClear=%s "
           "invalidator=%s cacheClear=%s mask=0x%llx ioFailures=%llu\n",
           remote_call_current_pid(),
           d->targetBundle,
           d->haveControl ? d->controlBundle : "-",
           (unsigned long long)d->localIcon,
           localIconCls[0] ? localIconCls : "-",
           (unsigned long long)d->canonicalIcon,
           canonicalIconCls[0] ? canonicalIconCls : "-",
           d->localIcon == d->canonicalIcon,
           (unsigned long long)d->localCache,
           localCacheCls[0] ? localCacheCls : "-",
           (unsigned long long)d->canonicalCache,
           canonicalCacheCls[0] ? canonicalCacheCls : "-",
           d->localCacheDistinct,
           d->canonicalCacheWritable,
           (unsigned long long)d->managerIconCache,
           managerCacheCls[0] ? managerCacheCls : "-",
           d->managerCacheContract,
           d->managerCachePathKnown ? d->managerCachePath : "-",
           (unsigned long long)d->descriptorSymbol,
           (unsigned long long)d->descriptorNameObject,
           d->descriptorLiteralFallback,
           (unsigned long long)d->descriptor,
           d->descriptorClass[0] ? d->descriptorClass : "-",
           (unsigned long long)d->prepareTargetResult,
           d->prepareTargetSupported,
           (unsigned long long)d->prepareLocalResult,
           d->prepareLocalSupported,
           (unsigned long long)d->prepareControlResult,
           d->prepareControlSupported,
           (unsigned long long)d->stockTargetImage,
           (unsigned long long)d->stockLocalImage,
           (unsigned long long)d->stockManagerImage,
           (unsigned long long)d->stockControlImage,
           (unsigned long long)d->prePrepareBagsCopy,
           d->prePrepareBagsCount,
           d->prePrepareBagsEmpty,
           d->bagsCount,
           d->bagsReadWrite,
           (unsigned long long)d->originalBagKey,
           (unsigned long long)d->originalBagValue,
           d->stockEntryCount,
           d->primaryEntryIndex,
           d->stockTopologyKnown,
           d->originalBagExactKey,
           d->originalBagDigestKey,
           d->descriptorClearSelector[0]
               ? d->descriptorClearSelector : "-",
           d->iconInvalidatorSelector[0]
               ? d->iconInvalidatorSelector : "-",
           d->cacheClearSelector[0] ? d->cacheClearSelector : "-",
           (unsigned long long)d->supportedMask,
           (unsigned long long)remote_call_current_io_failure_count());

    bool preparationRestored = false;
    if (d->prePrepareBagsCopyKnown &&
        r_is_objc_ptr(d->prePrepareBagsCopy) &&
        r_is_objc_ptr(d->canonicalCache) &&
        r_responds_main(d->canonicalCache,
                        "setImageBagsByDescriptor:")) {
        r_msg2_main(d->canonicalCache, "setImageBagsByDescriptor:",
                    d->prePrepareBagsCopy, 0, 0, 0);
        preparationRestored = remote_call_current_success() &&
            themer_iconservices_lab_dictionary_restored(
                d->canonicalCache, d->prePrepareBagsCopy,
                d->prePrepareBagsCount);
    }
    printf("[ICONSERVICES_LAB] discovery preparation-restore "
           "copy=0x%llx count=%d restored=%d\n",
           (unsigned long long)d->prePrepareBagsCopy,
           d->prePrepareBagsCount,
           preparationRestored);
    if (d->prePrepareBagsCopyKnown && !preparationRestored) {
        d->supportedMask = 0;
        return remote_call_current_success() ? 0 : -2;
    }
    return remote_call_current_success() ? 1 : -2;
}

ThemerSpotlightIconServicesProbeResult
themer_spotlight_iconservices_probe_in_session(
    NSDictionary<NSString *, NSData *> *imageDataByBundle,
    volatile int *stopRequested,
    uint64_t *supportedCandidateMaskOut)
{
    uint64_t startUS = themer_now_us();
    if (supportedCandidateMaskOut) *supportedCandidateMaskOut = 0;
    if (!remote_call_current_success()) {
        printf("[ICONSERVICES_LAB] probe aborted reason=transport-down\n");
        return ThemerSpotlightIconServicesProbeResultFailed;
    }
    if (themer_spotlight_has_armed_recovery_in_session()) {
        printf("[ICONSERVICES_LAB] probe stopped reason=recovery-present "
               "transport=%d\n", remote_call_current_success());
        return remote_call_current_success()
            ? ThemerSpotlightIconServicesProbeResultStatePresent
            : ThemerSpotlightIconServicesProbeResultFailed;
    }
    if (stopRequested && *stopRequested) {
        printf("[ICONSERVICES_LAB] probe stopped reason=cancelled\n");
        return ThemerSpotlightIconServicesProbeResultFailed;
    }

    uint32_t previousSettleUS = r_settle_us(1000);
    NSDictionary<NSString *, NSData *> *normalized =
        themer_normalized_theme_data(imageDataByBundle);
    if (normalized.count == 0) {
        printf("[ICONSERVICES_LAB] probe no-eligible-icon reason=empty-theme\n");
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesProbeResultNoEligibleIcon;
    }

    ThemerIconServicesLabDiscovery d = {0};
    int discoveryResult = themer_iconservices_lab_discover(
        normalized, stopRequested, true, &d);
    if (discoveryResult != 1) {
        printf("[ICONSERVICES_LAB] probe finished reason=discovery "
               "result=%d pid=%d total=%llums\n",
               discoveryResult,
               remote_call_current_pid(),
               (unsigned long long)((themer_now_us() - startUS) / 1000ULL));
        themer_iconservices_lab_release_discovery(&d);
        r_settle_us(previousSettleUS);
        if (discoveryResult == -1) {
            return ThemerSpotlightIconServicesProbeResultNoEligibleIcon;
        }
        if (discoveryResult == -2) {
            return ThemerSpotlightIconServicesProbeResultFailed;
        }
        return ThemerSpotlightIconServicesProbeResultUnsupported;
    }
    if (stopRequested && *stopRequested) {
        themer_iconservices_lab_release_discovery(&d);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesProbeResultFailed;
    }
    themer_iconservices_lab_log_local_stock_store_file(&d);
    if (!remote_call_current_success()) {
        themer_iconservices_lab_release_discovery(&d);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesProbeResultFailed;
    }
    if (!themer_iconservices_lab_remove_pending_store_unit(
            d.managerIconCache)) {
        printf("[ICONSERVICES_LAB] probe stopped "
               "reason=pending-store-cleanup-failed\n");
        themer_iconservices_lab_release_discovery(&d);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesProbeResultFailed;
    }

    bool generationControlReady = false;
    bool generation68Ready = false;
    bool generationProbeRan = false;
    if (!THEMER_ICONSERVICES_LAB_GENERATION_ENABLED) {
        printf("[ICONSERVICES_LAB] generation-probe disabled "
               "reason=store-find-only pid=%d\n",
               remote_call_current_pid());
    } else if (d.traceResult == ThemerIconServicesLabTraceUnchanged) {
        themer_iconservices_lab_trace_clear();
        bool alreadyClaimed = false;
        bool guardReady = remote_call_current_success() &&
            themer_iconservices_lab_generation_guard_claim(&alreadyClaimed);
        if (guardReady && !alreadyClaimed) {
            generationProbeRan = true;
            if (!themer_iconservices_lab_generation_probe(
                    &d, &generationControlReady)) {
                printf("[ICONSERVICES_LAB] generation-probe failed "
                       "mode=stock40-record-identifiers-dual-retain-bounded-invocation "
                       "transport=%d continuing=%d\n",
                       remote_call_current_success(),
                       remote_call_current_success());
                if (!remote_call_current_success()) {
                    themer_iconservices_lab_release_discovery(&d);
                    r_settle_us(previousSettleUS);
                    return ThemerSpotlightIconServicesProbeResultFailed;
                }
            }
        } else {
            printf("[ICONSERVICES_LAB] generation-probe disabled "
                   "reason=%s pid=%d\n",
                   alreadyClaimed ? "one-shot" : "guard-failed",
                   remote_call_current_pid());
        }
    }

    bool stockCacheImageRoundTrip = true;
    if (THEMER_ICONSERVICES_LAB_EXTENDED_PROBES_ENABLED) {
        stockCacheImageRoundTrip = false;
        if (!themer_iconservices_lab_stock_cacheimage_roundtrip(
                &d, &stockCacheImageRoundTrip) ||
            !themer_iconservices_lab_stock_token_comparison_probe(&d) ||
            !themer_iconservices_lab_store_record_lookup_probe(&d)) {
            themer_iconservices_lab_release_discovery(&d);
            r_settle_us(previousSettleUS);
            return ThemerSpotlightIconServicesProbeResultFailed;
        }
    }

    // Read-only candidate gate: preserve the genuine stock 40 entry and prove
    // that one ownership-safe themed 68 entry can coexist and route exactly.
    uint64_t stock40 = d.primaryEntryIndex >= 0 &&
        d.primaryEntryIndex < d.stockEntryCount
        ? d.stockEntries[d.primaryEntryIndex].image : 0;
    ThemerSpotlightRemoteImage probeSources[2] = {{0}};
    int probeSourceCount = 0;
    NSDictionary<NSString *, NSData *> *scaledTheme68 =
        d.descScaleOK ? themer_iconservices_lab_scaled_theme_data(
            normalized, d.targetBundle, 68.0, 68.0, d.descScale) : nil;
    uint64_t source68 = scaledTheme68
        ? themer_spotlight_remote_image_for_bundle(
            scaledTheme68, d.targetBundle,
            probeSources, &probeSourceCount, 2)
        : 0;
    uint64_t concrete68 = d.descScaleOK
        ? themer_iconservices_lab_make_if_image(source68, d.descScale) : 0;
    bool concreteMinimum65 = r_is_objc_ptr(concrete68) &&
        themer_iconservices_lab_set_minimum_size(concrete68, 65.0, 65.0);
    bool stock40Geometry = r_is_objc_ptr(stock40) &&
        d.descriptorPropsKnown &&
        themer_iconservices_lab_image_geometry_matches(
            stock40, d.descSizeW, d.descSizeH, d.descScale);
    bool concrete68Geometry = r_is_objc_ptr(concrete68) && d.descScaleOK &&
        themer_iconservices_lab_image_geometry_matches(
            concrete68, 68.0, 68.0, d.descScale);
    bool themedCacheImageReady = false;
    if (!themer_iconservices_lab_construction_probe(
            &d, concrete68, &themedCacheImageReady)) {
        if (r_is_objc_ptr(concrete68) && remote_call_current_success()) {
            r_msg2(concrete68, "release", 0, 0, 0, 0);
        }
        themer_spotlight_proof_release_images(
            probeSources, probeSourceCount, 0);
        themer_iconservices_lab_release_discovery(&d);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesProbeResultFailed;
    }
    bool tokenlessPayloadReady = false;
    uint64_t themed68 = themer_iconservices_lab_make_tokenless_cache_image(
        concrete68, 68.0, 68.0, d.descScale, 65.0, 65.0,
        &tokenlessPayloadReady);
    concrete68 = 0;  // Consumed by the tokenless cache-image constructor.
    double themedMinimumW = 0.0, themedMinimumH = 0.0;
    bool themed68Minimum65 = r_is_objc_ptr(themed68) &&
        themer_iconservices_lab_read_size_property(
            themed68, "minimumSize", &themedMinimumW, &themedMinimumH) &&
        themer_iconservices_lab_sizes_match(
            themedMinimumW, themedMinimumH, 65.0, 65.0);
    bool themed68Geometry = r_is_objc_ptr(themed68) && d.descScaleOK &&
        themer_iconservices_lab_image_geometry_matches(
            themed68, 68.0, 68.0, d.descScale);
    uint64_t mixedImages[THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP] = {0};
    double mixedWidths[THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP] = {0};
    double mixedHeights[THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP] = {0};
    double mixedScales[THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP] = {0};
    int themed68Index = -1;
    int stock64Index = -1;
    int mixedEntryCount = d.stockEntryCount;
    for (int i = 0; i < d.stockEntryCount; i++) {
        const ThemerIconServicesLabBagEntry *entry = &d.stockEntries[i];
        mixedImages[i] = entry->image;
        mixedWidths[i] = entry->width;
        mixedHeights[i] = entry->height;
        mixedScales[i] = entry->scale;
        if (entry->geometryKnown &&
            themer_iconservices_lab_sizes_match(
                entry->width, entry->height, 68.0, 68.0)) {
            themed68Index = i;
        } else if (entry->geometryKnown &&
                   themer_iconservices_lab_sizes_match(
                       entry->width, entry->height, 64.0, 64.0)) {
            stock64Index = i;
        }
    }
    if (themed68Index < 0 &&
        mixedEntryCount < THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP) {
        themed68Index = mixedEntryCount++;
        mixedWidths[themed68Index] = 68.0;
        mixedHeights[themed68Index] = 68.0;
        mixedScales[themed68Index] = d.descScale;
    }
    if (themed68Index >= 0) mixedImages[themed68Index] = themed68;
    uint64_t mixedBag = d.stockEntryCount >= 1 && mixedEntryCount >= 2 &&
        themed68Index >= 0 && stock40Geometry && concreteMinimum65 &&
        concrete68Geometry && themedCacheImageReady && tokenlessPayloadReady &&
        themed68Geometry && themed68Minimum65
        ? themer_iconservices_lab_make_bag_from_images(
            mixedImages, mixedEntryCount) : 0;
    int routeHits = 0;
    for (int i = 0; r_is_objc_ptr(mixedBag) &&
         i < mixedEntryCount && remote_call_current_success(); i++) {
        uint64_t routed = themer_iconservices_lab_image_for_size_scale(
            mixedBag, mixedWidths[i], mixedHeights[i], mixedScales[i]);
        bool hit = themer_spotlight_images_match(mixedImages[i], routed);
        if (hit) routeHits++;
        printf("[ICONSERVICES_LAB] mixed-stock-preserved route index=%d "
               "expected=0x%llx routed=0x%llx hit=%d "
               "size=%.1fx%.1f@%.2f themed=%d\n",
               i,
               (unsigned long long)mixedImages[i],
               (unsigned long long)routed,
               hit,
               mixedWidths[i],
               mixedHeights[i],
               mixedScales[i],
               i == themed68Index);
    }
    bool mixedReady = d.supportedMask != 0 && d.stockEntryCount >= 1 &&
        mixedEntryCount >= 2 && themed68Index >= 0 && stock40Geometry &&
        concreteMinimum65 && concrete68Geometry && themedCacheImageReady &&
        tokenlessPayloadReady && themed68Geometry && themed68Minimum65 &&
        r_is_objc_ptr(mixedBag) && routeHits == mixedEntryCount &&
        remote_call_current_success();
    printf("[ICONSERVICES_LAB] mixed-stock-preserved-themed68 probe "
           "stockEntries=%d testEntries=%d primaryIndex=%d stock64Index=%d "
           "themed68Index=%d stock40=0x%llx/%d cacheImageReady=%d "
           "tokenlessReady=%d themed68=0x%llx/%d minimum65=%d "
           "bag=0x%llx routeHits=%d ready=%d\n",
           d.stockEntryCount,
           mixedEntryCount,
           d.primaryEntryIndex,
           stock64Index,
           themed68Index,
           (unsigned long long)stock40,
           stock40Geometry,
           themedCacheImageReady,
           tokenlessPayloadReady,
           (unsigned long long)themed68,
           themed68Geometry,
           themed68Minimum65,
           (unsigned long long)mixedBag,
           routeHits,
           mixedReady);
    if (r_is_objc_ptr(mixedBag) && remote_call_current_success()) {
        r_msg2(mixedBag, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(themed68) && remote_call_current_success()) {
        r_msg2(themed68, "release", 0, 0, 0, 0);
    }
    themer_spotlight_proof_release_images(
        probeSources, probeSourceCount, 0);
    if (!remote_call_current_success()) {
        themer_iconservices_lab_release_discovery(&d);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesProbeResultFailed;
    }
    bool genuineStock68Present = false;
    for (int i = 0; i < d.stockEntryCount; i++) {
        const ThemerIconServicesLabBagEntry *entry = &d.stockEntries[i];
        double scaleDelta = entry->scale - d.descScale;
        if (scaleDelta < 0.0) scaleDelta = -scaleDelta;
        if (entry->geometryKnown &&
            themer_iconservices_lab_sizes_match(
                entry->width, entry->height, 68.0, 68.0) &&
            d.descScaleOK && scaleDelta < 0.01) {
            genuineStock68Present = true;
            break;
        }
    }
    bool traceArmed = false;
    if (mixedReady && !genuineStock68Present &&
        d.traceResult != ThemerIconServicesLabTraceNew68 &&
        !generationProbeRan && remote_call_current_success()) {
        // The synthetic mixed bag proves the routing shape, but Seed remains
        // disabled until a real 68-pt cache record appears. Preserve a read-only
        // baseline across real Spotlight interactions so the next Probe can
        // identify that materialization without creating a store record.
        traceArmed = themer_iconservices_lab_trace_arm(
            d.targetBundle,
            d.descriptor,
            d.descScale,
            &d.beforeDescriptorSnapshot);
        if (traceArmed) {
            traceArmed = themer_iconservices_lab_trace_store_stock40_metadata(
                &d);
            if (!traceArmed) themer_iconservices_lab_trace_clear();
        }
    } else if (!mixedReady || genuineStock68Present ||
               d.traceResult == ThemerIconServicesLabTraceNew68) {
        themer_iconservices_lab_trace_clear();
    }
    if (!remote_call_current_success()) {
        themer_iconservices_lab_release_discovery(&d);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesProbeResultFailed;
    }

    bool storeFileRouteEligible = mixedReady && genuineStock68Present &&
        d.managerCachePathKnown;
    bool stock68IdentityPersisted = storeFileRouteEligible &&
        themer_iconservices_lab_persist_stock68_identity(&d);
    storeFileRouteEligible = storeFileRouteEligible &&
        stock68IdentityPersisted;
    if (!storeFileRouteEligible) {
        d.supportedMask = 0;
        if (!genuineStock68Present) {
            themer_iconservices_lab_clear_stock68_identity();
        }
    }
    if (supportedCandidateMaskOut) {
        *supportedCandidateMaskOut = d.supportedMask;
    }
    printf("[ICONSERVICES_LAB] probe ready pid=%d mask=0x%llx "
           "candidate=canonical-stock-preserved-themed68-store "
           "beforeDescriptor=%d/%d beforePrepare=%d/%d "
           "afterTargetPrepare=%d/%d afterAllPrepare=%d/%d "
           "stockCacheImageRoundTrip=%d themedCacheImageReady=%d "
           "tokenlessPayloadReady=%d mixedReady=%d traceResult=%d "
           "generationProbe=%d generationControl=%d generation68=%d "
           "genuineStock68=%d pathKnown=%d identityPersisted=%d "
           "storeFileEligible=%d traceArmed=%d total=%llums "
           "ioFailures=%llu\n",
           remote_call_current_pid(),
           (unsigned long long)d.supportedMask,
           d.beforeDescriptorSnapshot.captured,
           d.beforeDescriptorSnapshot.keyCount,
           d.beforePrepareSnapshot.captured,
           d.beforePrepareSnapshot.keyCount,
           d.afterTargetPrepareSnapshot.captured,
           d.afterTargetPrepareSnapshot.keyCount,
           d.afterAllPrepareSnapshot.captured,
           d.afterAllPrepareSnapshot.keyCount,
           stockCacheImageRoundTrip,
           themedCacheImageReady,
           tokenlessPayloadReady,
           mixedReady,
           d.traceResult,
           generationProbeRan,
           generationControlReady,
           generation68Ready,
           genuineStock68Present,
           d.managerCachePathKnown,
           stock68IdentityPersisted,
           storeFileRouteEligible,
           traceArmed,
           (unsigned long long)((themer_now_us() - startUS) / 1000ULL),
           (unsigned long long)remote_call_current_io_failure_count());
    themer_iconservices_lab_release_discovery(&d);
    r_settle_us(previousSettleUS);
    return ThemerSpotlightIconServicesProbeResultReady;
}

// Mutation target for one candidate run: which cache gets the write, which
// object provides imageForDescriptor: readback, and what stock image
// restores it. cloneDesc for candidates 2/3 is +1 owned separately.
typedef struct {
    uint64_t cache;
    uint64_t readObj;
    uint64_t desc;
    uint64_t stockImage;
    bool bagCandidate;
    bool bagSwapped;
    bool exactDictionaryRestore;
    int originalBagsCount;
    uint64_t originalBags;
    uint64_t replacementBags;  // +1 owned (bag swap only)
} ThemerIconServicesLabTarget;

static bool themer_iconservices_lab_seed_image(uint64_t cache,
                                               uint64_t image,
                                               uint64_t desc)
{
    if (!remote_call_current_success() || !r_is_objc_ptr(cache) ||
        !r_is_objc_ptr(image) || !r_is_objc_ptr(desc) ||
        !r_responds_main(cache, "setImage:forDescriptor:")) {
        return false;
    }
    r_msg2_main(cache, "setImage:forDescriptor:", image, desc, 0, 0);
    return remote_call_current_success();
}

static uint64_t themer_iconservices_lab_read_image(uint64_t obj,
                                                   uint64_t desc)
{
    if (!remote_call_current_success() || !r_is_objc_ptr(obj) ||
        !r_is_objc_ptr(desc) || !r_responds_main(obj, "imageForDescriptor:")) {
        return 0;
    }
    uint64_t image = r_msg2_main(obj, "imageForDescriptor:", desc, 0, 0, 0);
    return remote_call_current_success() ? image : 0;
}

// Verifies wholesale dictionary restoration without asking IconServices for an
// image, which would immediately rematerialize the named 40-point bag.
static bool themer_iconservices_lab_dictionary_restored(
    uint64_t cache,
    uint64_t expectedBags,
    int expectedCount)
{
    if (!r_is_objc_ptr(cache) || !r_is_objc_ptr(expectedBags) ||
        expectedCount < 0 ||
        !r_responds_main(cache, "imageBagsByDescriptor")) {
        return false;
    }
    uint64_t actualBags = r_msg2_main(
        cache, "imageBagsByDescriptor", 0, 0, 0, 0);
    int actualCount = r_is_objc_ptr(actualBags)
        ? (int)themer_remote_count(actualBags) : -1;
    bool restored = remote_call_current_success() &&
        r_is_objc_ptr(actualBags) && actualCount == expectedCount &&
        (actualBags == expectedBags || expectedCount == 0);
    printf("[ICONSERVICES_LAB] dictionary-restore-verify "
           "expected=0x%llx/%d actual=0x%llx/%d identity=%d restored=%d\n",
           (unsigned long long)expectedBags,
           expectedCount,
           (unsigned long long)actualBags,
           actualCount,
           actualBags == expectedBags,
           restored);
    return restored;
}

static bool themer_iconservices_lab_install_replacement_bag(
    const ThemerIconServicesLabDiscovery *d,
    ThemerIconServicesLabTarget *t,
    const uint64_t *themedImages,
    int themedImageCount)
{
    bool preflight = d && t && themedImages &&
        themedImageCount >= 1 &&
        themedImageCount == d->stockEntryCount &&
        themedImageCount <= THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP &&
        r_is_objc_ptr(d->originalBags) &&
        r_is_objc_ptr(d->originalBagKey) &&
        r_is_objc_ptr(d->originalBagValue) &&
        r_is_objc_ptr(t->cache) && d->stockTopologyKnown &&
        d->originalBagDigestKey &&
        themer_iconservices_lab_bag_key_matches_descriptor(
            d->descriptor, d->originalBagKey) &&
        r_responds_main(t->cache, "setImageBagsByDescriptor:");
    for (int i = 0; preflight && i < themedImageCount; i++) {
        const ThemerIconServicesLabBagEntry *entry = &d->stockEntries[i];
        preflight = r_is_objc_ptr(themedImages[i]) && entry->geometryKnown &&
            themer_iconservices_lab_image_geometry_matches(
                themedImages[i], entry->width, entry->height, entry->scale);
    }
    if (!preflight || !remote_call_current_success()) {
        printf("[ICONSERVICES_LAB] bag-clone stopped stage=preflight "
               "entries=%d stockEntries=%d\n",
               themedImageCount, d ? d->stockEntryCount : 0);
        return false;
    }

    uint64_t replacementBag = 0;
    const char *stage = "bag-init";
    bool installed = false;

    do {
        replacementBag = themer_iconservices_lab_make_bag_from_images(
            themedImages, themedImageCount);
        if (!r_is_objc_ptr(replacementBag)) break;

        printf("[ICONSERVICES_LAB] bag-compare "
               "role=themed-retained-cg-install mutation=0\n");
        themer_iconservices_lab_log_bag_value(
            replacementBag, d->descriptor);
        printf("[ICONSERVICES_LAB] bag-compare-end "
               "role=themed-retained-cg-install\n");
        if (!remote_call_current_success()) break;

        stage = "bag-route";
        int routeHits = 0;
        for (int i = 0;
             i < themedImageCount && remote_call_current_success(); i++) {
            const ThemerIconServicesLabBagEntry *entry = &d->stockEntries[i];
            uint64_t routed = themer_iconservices_lab_image_for_size_scale(
                replacementBag, entry->width, entry->height, entry->scale);
            bool hit = themer_spotlight_images_match(
                themedImages[i], routed);
            if (hit) routeHits++;
            printf("[ICONSERVICES_LAB] retained-cg-bag route "
                   "index=%d routed=0x%llx hit=%d size=%.1fx%.1f@%.2f\n",
                   i,
                   (unsigned long long)routed,
                   hit,
                   entry->width,
                   entry->height,
                   entry->scale);
        }
        if (routeHits != themedImageCount ||
            !remote_call_current_success()) break;

        stage = "dictionary-copy";
        uint64_t replacementBags = r_responds_main(
            d->originalBags, "mutableCopy")
            ? r_msg2_main(d->originalBags, "mutableCopy", 0, 0, 0, 0)
            : 0;
        if (!r_is_objc_ptr(replacementBags) ||
            !r_responds_main(replacementBags, "setObject:forKey:")) {
            if (r_is_objc_ptr(replacementBags) &&
                remote_call_current_success()) {
                r_msg2(replacementBags, "release", 0, 0, 0, 0);
            }
            break;
        }
        t->replacementBags = replacementBags;  // +1 from mutableCopy
        r_msg2_main(t->replacementBags, "setObject:forKey:",
                    replacementBag, d->originalBagKey, 0, 0);
        uint64_t copiedBag = remote_call_current_success()
            ? r_msg2_main(t->replacementBags, "objectForKey:",
                          d->originalBagKey, 0, 0, 0)
            : 0;
        if (!remote_call_current_success() || copiedBag != replacementBag) {
            break;
        }

        stage = "cache-install";
        t->bagSwapped = true;  // Arm rollback before the remote setter executes.
        r_msg2_main(t->cache, "setImageBagsByDescriptor:",
                    t->replacementBags, 0, 0, 0);
        if (!remote_call_current_success()) break;

        stage = "cache-readback";
        uint64_t installedBags = r_responds_main(
            t->cache, "imageBagsByDescriptor")
            ? r_msg2_main(t->cache, "imageBagsByDescriptor", 0, 0, 0, 0)
            : 0;
        uint64_t installedBag = r_is_objc_ptr(installedBags) &&
            r_responds_main(installedBags, "objectForKey:")
            ? r_msg2_main(installedBags, "objectForKey:",
                          d->originalBagKey, 0, 0, 0)
            : 0;
        int installedHits = 0;
        for (int i = 0;
             i < themedImageCount && remote_call_current_success(); i++) {
            const ThemerIconServicesLabBagEntry *entry = &d->stockEntries[i];
            uint64_t routed = themer_iconservices_lab_image_for_size_scale(
                installedBag, entry->width, entry->height, entry->scale);
            bool hit = themer_spotlight_images_match(
                themedImages[i], routed);
            if (hit) installedHits++;
            printf("[ICONSERVICES_LAB] retained-cg-bag install-entry "
                   "index=%d routed=0x%llx hit=%d size=%.1fx%.1f@%.2f\n",
                   i,
                   (unsigned long long)routed,
                   hit,
                   entry->width,
                   entry->height,
                   entry->scale);
        }
        installed = installedHits == themedImageCount &&
            remote_call_current_success();
        printf("[ICONSERVICES_LAB] retained-cg-bag install dict=0x%llx "
               "bag=0x%llx hits=%d/%d success=%d\n",
               (unsigned long long)installedBags,
               (unsigned long long)installedBag,
               installedHits,
               themedImageCount,
               installed);
    } while (0);

    if (!installed) {
        printf("[ICONSERVICES_LAB] retained-cg-bag stopped stage=%s swapped=%d "
               "success=%d\n",
               stage,
               t->bagSwapped,
               remote_call_current_success());
    }
    if (r_is_objc_ptr(replacementBag) && remote_call_current_success()) {
        r_msg2(replacementBag, "release", 0, 0, 0, 0);
    }
    return installed && remote_call_current_success();
}

static bool themer_iconservices_lab_rollback_target(
    ThemerIconServicesLabTarget *t)
{
    if (!t || !remote_call_current_success()) return false;
    if (t->bagCandidate && !t->bagSwapped) {
        return t->exactDictionaryRestore
            ? themer_iconservices_lab_dictionary_restored(
                t->cache, t->originalBags, t->originalBagsCount)
            : true;
    }
    if (t->bagSwapped) {
        if (!r_is_objc_ptr(t->cache) || !r_is_objc_ptr(t->originalBags) ||
            !r_responds_main(t->cache, "setImageBagsByDescriptor:")) {
            return false;
        }
        r_msg2_main(t->cache, "setImageBagsByDescriptor:",
                    t->originalBags, 0, 0, 0);
        if (!remote_call_current_success()) return false;
        if (t->exactDictionaryRestore) {
            return themer_iconservices_lab_dictionary_restored(
                t->cache, t->originalBags, t->originalBagsCount);
        }
        uint64_t readback = themer_iconservices_lab_read_image(
            t->readObj, t->desc);
        return themer_spotlight_images_match(t->stockImage, readback) &&
               remote_call_current_success();
    }
    if (!themer_iconservices_lab_seed_image(t->cache, t->stockImage,
                                            t->desc)) {
        return false;
    }
    uint64_t readback = themer_iconservices_lab_read_image(t->readObj,
                                                           t->desc);
    return themer_spotlight_images_match(t->stockImage, readback) &&
           remote_call_current_success();
}

static bool themer_iconservices_lab_cleanup_themed_store_mutation(
    ThemerIconServicesLabTarget *t,
    uint64_t managerCache,
    uint64_t themedStoreUUID,
    bool statePrearmed,
    bool *rolledBackOut,
    bool *storeRemovedOut,
    bool *stateClearedOut)
{
    if (rolledBackOut) *rolledBackOut = false;
    if (storeRemovedOut) *storeRemovedOut = false;
    if (stateClearedOut) *stateClearedOut = false;
    bool rolledBack = themer_iconservices_lab_rollback_target(t);
    bool storeRemoved = rolledBack &&
        themer_iconservices_lab_remove_store_unit(
            managerCache, themedStoreUUID);
    if (storeRemoved) {
        themer_iconservices_lab_clear_pending_store_uuid();
    }
    bool stateCleared = !statePrearmed;
    if (rolledBack && storeRemoved && statePrearmed &&
        remote_call_current_success()) {
        themer_iconservices_lab_clear_state();
        stateCleared = !r_is_objc_ptr(themer_iconservices_lab_state());
    }
    if (rolledBackOut) *rolledBackOut = rolledBack;
    if (storeRemovedOut) *storeRemovedOut = storeRemoved;
    if (stateClearedOut) *stateClearedOut = stateCleared;
    printf("[ICONSERVICES_LAB] themed-store rollback dictionary=%d "
           "uuid=0x%llx storeRemoved=%d statePrearmed=%d "
           "stateCleared=%d\n",
           rolledBack,
           (unsigned long long)themedStoreUUID,
           storeRemoved,
           statePrearmed,
           stateCleared);
    return rolledBack && storeRemoved && stateCleared &&
        remote_call_current_success();
}

static bool themer_iconservices_lab_control_still_stock(
    const ThemerIconServicesLabDiscovery *d)
{
    if (!d || !remote_call_current_success()) return true;
    if (!r_is_objc_ptr(d->controlCanonicalIcon) ||
        !r_is_objc_ptr(d->stockControlImage) ||
        !r_is_objc_ptr(d->descriptor)) {
        // Unchecked control is treated as stock: no evidence of change.
        return true;
    }
    uint64_t readback = themer_iconservices_lab_read_image(
        d->controlCanonicalIcon, d->descriptor);
    return themer_spotlight_images_match(d->stockControlImage, readback) &&
           remote_call_current_success();
}

static uint64_t themer_iconservices_lab_clone_descriptor(
    const ThemerIconServicesLabDiscovery *d,
    bool useFactory)
{
    if (!d || !r_is_objc_ptr(d->descriptor) ||
        !remote_call_current_success()) {
        return 0;
    }
    uint64_t descCls = themer_lookup_class("ISImageDescriptor");
    if (!remote_call_current_success() || !r_is_objc_ptr(descCls)) return 0;

    double width = d->descSizeOK && d->descSizeW >= 1.0
        ? d->descSizeW : 60.0;
    double height = d->descSizeOK && d->descSizeH >= 1.0
        ? d->descSizeH : width;
    double scale = d->descScaleOK && d->descScale >= 1.0 &&
                   d->descScale <= 4.0
        ? d->descScale : themer_screen_scale();

    uint64_t desc = 0;
    if (useFactory && d->descIconVariantOK &&
        r_responds_main(descCls, "imageDescriptorWithIconVariant:options:")) {
        desc = r_msg2_main(descCls, "imageDescriptorWithIconVariant:options:",
                           d->descIconVariant, d->descVariantOptions, 0, 0);
        if (remote_call_current_success() && r_is_objc_ptr(desc)) {
            desc = r_msg2(desc, "retain", 0, 0, 0, 0);
        }
    }
    if (!r_is_objc_ptr(desc)) {
        uint64_t alloc = r_msg2(descCls, "alloc", 0, 0, 0, 0);
        if (!remote_call_current_success()) return 0;
        struct { double width; double height; } size = { width, height };
        desc = r_is_objc_ptr(alloc)
            ? r_msg2_main_raw(alloc, "initWithSize:scale:",
                              &size, sizeof(size),
                              &scale, sizeof(scale),
                              NULL, 0, NULL, 0)
            : 0;
        if (!remote_call_current_success()) return 0;
    }
    if (!r_is_objc_ptr(desc)) return 0;

    struct { double width; double height; } size = { width, height };
    if (r_responds_main(desc, "setSize:")) {
        r_msg2_main_raw(desc, "setSize:",
                        &size, sizeof(size),
                        NULL, 0, NULL, 0, NULL, 0);
    }
    if (r_responds_main(desc, "setScale:")) {
        r_msg2_main_raw(desc, "setScale:",
                        &scale, sizeof(scale),
                        NULL, 0, NULL, 0, NULL, 0);
    }
    if (d->descAppearanceOK && r_responds_main(desc, "setAppearance:")) {
        r_msg2_main(desc, "setAppearance:", d->descAppearance, 0, 0, 0);
    }
    if (d->descAppearanceVariantOK &&
        r_responds_main(desc, "setAppearanceVariant:")) {
        r_msg2_main(desc, "setAppearanceVariant:",
                    d->descAppearanceVariant, 0, 0, 0);
    }
    if (r_responds_main(desc, "setIgnoreCache:")) {
        r_msg2_main(desc, "setIgnoreCache:", 0, 0, 0, 0);
    }
    return remote_call_current_success() ? desc : 0;  // +1 owned
}

static void themer_iconservices_lab_release_payload(
    uint64_t *ifImages,
    ThemerSpotlightRemoteImage sourceImages[][2],
    int *sourceImageCounts,
    int entryCount)
{
    if (!ifImages || !sourceImages || !sourceImageCounts) return;
    for (int i = 0;
         i < entryCount && remote_call_current_success(); i++) {
        if (r_is_objc_ptr(ifImages[i])) {
            r_msg2(ifImages[i], "release", 0, 0, 0, 0);
        }
    }
    for (int i = 0;
         i < entryCount && remote_call_current_success(); i++) {
        themer_spotlight_proof_release_images(
            sourceImages[i], sourceImageCounts[i], 0);
    }
}

ThemerSpotlightIconServicesBeginResult
themer_spotlight_iconservices_begin_in_session(
    ThemerSpotlightIconServicesCandidate candidate,
    NSDictionary<NSString *, NSData *> *imageDataByBundle,
    volatile int *stopRequested)
{
    uint64_t startUS = themer_now_us();
    uint32_t previousSettleUS = r_settle_us(1000);
    const char *candidateName =
        themer_spotlight_iconservices_candidate_name(candidate);
    if (!remote_call_current_success()) {
        printf("[ICONSERVICES_LAB] begin aborted reason=transport-down\n");
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesBeginResultStateFailed;
    }
    if (themer_spotlight_has_armed_recovery_in_session()) {
        printf("[ICONSERVICES_LAB] begin stopped reason=recovery-present "
               "candidate=%s transport=%d\n", candidateName,
               remote_call_current_success());
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesBeginResultStateFailed;
    }
    if (candidate < 0 ||
        candidate >= ThemerSpotlightIconServicesCandidateCount) {
        printf("[ICONSERVICES_LAB] begin stopped reason=unknown-candidate "
               "candidate=%d\n", (int)candidate);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesBeginResultUnsupported;
    }
    NSDictionary<NSString *, NSData *> *normalized =
        themer_normalized_theme_data(imageDataByBundle);
    if (normalized.count == 0) {
        printf("[ICONSERVICES_LAB] begin no-eligible-icon "
               "reason=empty-theme candidate=%s\n", candidateName);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesBeginResultNoEligibleIcon;
    }
    printf("[ICONSERVICES_LAB] begin phase=begin-1 pid=%d candidate=%s "
           "risk=%s\n",
           remote_call_current_pid(),
           candidateName,
           themer_iconservices_lab_candidate_risk(candidate));

    ThemerIconServicesLabDiscovery d = {0};
    int discoveryResult = themer_iconservices_lab_discover(
        normalized, stopRequested, false, &d);
    if (discoveryResult != 1) {
        printf("[ICONSERVICES_LAB] begin stopped reason=discovery "
               "result=%d candidate=%s\n", discoveryResult, candidateName);
        themer_iconservices_lab_release_discovery(&d);
        r_settle_us(previousSettleUS);
        if (discoveryResult == -1) {
            return ThemerSpotlightIconServicesBeginResultNoEligibleIcon;
        }
        if (discoveryResult == -2) {
            return ThemerSpotlightIconServicesBeginResultStateFailed;
        }
        return ThemerSpotlightIconServicesBeginResultUnsupported;
    }
    if (stopRequested && *stopRequested) {
        themer_iconservices_lab_release_discovery(&d);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesBeginResultStateFailed;
    }
    if (!themer_iconservices_lab_remove_pending_store_unit(
            d.managerIconCache)) {
        printf("[ICONSERVICES_LAB] begin stopped "
               "reason=pending-store-cleanup-failed candidate=%s\n",
               candidateName);
        themer_iconservices_lab_release_discovery(&d);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesBeginResultStateFailed;
    }
    if (!(d.supportedMask & (1ULL << candidate))) {
        printf("[ICONSERVICES_LAB] begin stopped reason=candidate-unsupported "
               "candidate=%s mask=0x%llx\n",
               candidateName,
               (unsigned long long)d.supportedMask);
        themer_iconservices_lab_release_discovery(&d);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesBeginResultUnsupported;
    }

    // Build the mutation target for exactly this candidate.
    ThemerIconServicesLabTarget t = {0};
    bool mixedCandidate = candidate ==
        ThemerSpotlightIconServicesCandidateCanonicalMixedBag;
    t.originalBags = mixedCandidate
        ? d.prePrepareBagsCopy : d.originalBags;
    t.exactDictionaryRestore = mixedCandidate;
    t.originalBagsCount = mixedCandidate
        ? d.prePrepareBagsCount : d.bagsCount;
    const char *descriptorSource = "named-spotlight";
    uint64_t cloneDesc = 0;  // +1 owned for candidates 2/3
    switch (candidate) {
        case ThemerSpotlightIconServicesCandidateLocalExistingDescriptor:
            t.cache = d.localCache;
            t.readObj = d.localIcon;
            t.stockImage = d.stockLocalImage;
            t.desc = d.descriptor;
            break;
        case ThemerSpotlightIconServicesCandidateCanonicalExistingDescriptor:
        case ThemerSpotlightIconServicesCandidateCanonicalBagSwap:
        case ThemerSpotlightIconServicesCandidateCanonicalMixedBag:
        case ThemerSpotlightIconServicesCandidateCanonicalDescriptorClear:
        case ThemerSpotlightIconServicesCandidateCanonicalIconInvalidator:
        case ThemerSpotlightIconServicesCandidateCanonicalCacheClear:
            t.cache = d.canonicalCache;
            t.readObj = d.canonicalIcon;
            t.stockImage = d.stockTargetImage;
            t.desc = d.descriptor;
            break;
        case ThemerSpotlightIconServicesCandidateCanonicalFactoryClone:
            cloneDesc = themer_iconservices_lab_clone_descriptor(&d, true);
            if (!r_is_objc_ptr(cloneDesc)) {
                printf("[ICONSERVICES_LAB] begin stopped "
                       "reason=factory-clone-failed candidate=%s\n",
                       candidateName);
                themer_iconservices_lab_release_discovery(&d);
                r_settle_us(previousSettleUS);
                return ThemerSpotlightIconServicesBeginResultUnsupported;
            }
            t.cache = d.canonicalCache;
            t.readObj = d.canonicalIcon;
            t.stockImage = d.stockTargetImage;
            t.desc = cloneDesc;
            descriptorSource = "factory-clone";
            break;
        case ThemerSpotlightIconServicesCandidateCanonicalInitClone:
            cloneDesc = themer_iconservices_lab_clone_descriptor(&d, false);
            if (!r_is_objc_ptr(cloneDesc)) {
                printf("[ICONSERVICES_LAB] begin stopped "
                       "reason=init-clone-failed candidate=%s\n",
                       candidateName);
                themer_iconservices_lab_release_discovery(&d);
                r_settle_us(previousSettleUS);
                return ThemerSpotlightIconServicesBeginResultUnsupported;
            }
            t.cache = d.canonicalCache;
            t.readObj = d.canonicalIcon;
            t.stockImage = d.stockTargetImage;
            t.desc = cloneDesc;
            descriptorSource = "init-clone";
            break;
        case ThemerSpotlightIconServicesCandidateManagerCache:
            t.cache = d.managerIconCache;
            t.readObj = d.managerIconCache;
            t.stockImage = d.stockManagerImage;
            t.desc = d.descriptor;
            break;
        default:
            break;
    }
    if (!r_is_objc_ptr(t.cache) || !r_is_objc_ptr(t.readObj) ||
        !r_is_objc_ptr(t.desc) || !r_is_objc_ptr(t.stockImage)) {
        printf("[ICONSERVICES_LAB] begin stopped reason=target-incomplete "
               "candidate=%s\n", candidateName);
        if (r_is_objc_ptr(cloneDesc) && remote_call_current_success()) {
            r_msg2(cloneDesc, "release", 0, 0, 0, 0);
        }
        themer_iconservices_lab_release_discovery(&d);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesBeginResultUnsupported;
    }
    themer_iconservices_lab_log_descriptor("target", t.desc);

    bool bagCandidate = candidate ==
            ThemerSpotlightIconServicesCandidateCanonicalBagSwap ||
        mixedCandidate;
    int payloadEntryCount = bagCandidate ? d.stockEntryCount : 1;
    int primaryPayloadIndex = bagCandidate ? d.primaryEntryIndex : 0;
    ThemerIconServicesLabBagEntry payloadEntries[
        THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP] = {{0}};
    if (bagCandidate) {
        for (int i = 0; i < d.stockEntryCount; i++) {
            payloadEntries[i] = d.stockEntries[i];
        }
    } else {
        payloadEntries[0].width = d.descSizeW;
        payloadEntries[0].height = d.descSizeH;
        payloadEntries[0].scale = d.descScale;
        payloadEntries[0].geometryKnown = d.descriptorPropsKnown;
    }

    int themedPayloadIndex = -1;
    int stock64Index = -1;
    uint64_t sharedValidationToken = 0;
    uint64_t stock64Token = 0;
    uint64_t themedStoreUUID = 0;
    bool themedStoreUnitAdded = false;
    if (mixedCandidate) {
        for (int i = 0; i < payloadEntryCount; i++) {
            const ThemerIconServicesLabBagEntry *entry = &payloadEntries[i];
            if (entry->geometryKnown &&
                themer_iconservices_lab_sizes_match(
                    entry->width, entry->height, 68.0, 68.0)) {
                themedPayloadIndex = i;
            } else if (entry->geometryKnown &&
                       themer_iconservices_lab_sizes_match(
                           entry->width, entry->height, 64.0, 64.0)) {
                stock64Index = i;
            }
        }
        if (themedPayloadIndex < 0 &&
            payloadEntryCount < THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP) {
            themedPayloadIndex = payloadEntryCount++;
            payloadEntries[themedPayloadIndex].width = 68.0;
            payloadEntries[themedPayloadIndex].height = 68.0;
            payloadEntries[themedPayloadIndex].scale = d.descScale;
            payloadEntries[themedPayloadIndex].geometryKnown = d.descScaleOK;
        }
        if (primaryPayloadIndex >= 0 &&
            primaryPayloadIndex < payloadEntryCount) {
            sharedValidationToken = themer_iconservices_lab_retained_getter(
                payloadEntries[primaryPayloadIndex].image,
                "validationToken");
        }
        if (stock64Index >= 0) {
            stock64Token = themer_iconservices_lab_retained_getter(
                payloadEntries[stock64Index].image,
                "validationToken");
        }
    }
    bool sharedTokenReady = !mixedCandidate ||
        (r_is_objc_ptr(sharedValidationToken) &&
         (stock64Index < 0 ||
          (r_is_objc_ptr(stock64Token) &&
           themer_iconservices_lab_objects_equal(
               sharedValidationToken, stock64Token))));
    printf("[ICONSERVICES_LAB] begin store-token gate mixed=%d "
           "entries=%d primary=%d stock64=%d themed68=%d "
           "primaryToken=0x%llx stock64Token=0x%llx "
           "mode=%s shared=%d\n",
           mixedCandidate,
           payloadEntryCount,
           primaryPayloadIndex,
           stock64Index,
           themedPayloadIndex,
           (unsigned long long)sharedValidationToken,
           (unsigned long long)stock64Token,
           stock64Index >= 0 ? "shared-40-64" : "current-stock40",
           sharedTokenReady);

    // Existing-cache-file route needs a genuine 68-pt stock IFCacheImage whose
    // uuid resolves to the record we overwrite in place. A synthetic appended
    // entry (themedPayloadIndex >= stockEntryCount) has no such record.
    const ThemerIconServicesLabBagEntry *stock68Donor = NULL;
    if (mixedCandidate && themedPayloadIndex >= 0 &&
        themedPayloadIndex < d.stockEntryCount &&
        d.stockEntries[themedPayloadIndex].geometryKnown) {
        stock68Donor = &d.stockEntries[themedPayloadIndex];
    }
    bool liveStock68Ready = stock68Donor != NULL &&
        r_is_objc_ptr(stock68Donor->image);
    bool persistedStock68Ready = mixedCandidate && d.managerCachePathKnown &&
        themer_iconservices_lab_load_stock68_identity(
            d.targetBundle, d.managerCachePath, NULL, NULL);
    bool storeFileRouteReady = !mixedCandidate ||
        (d.managerCachePathKnown &&
         (liveStock68Ready || persistedStock68Ready));
    printf("[ICONSERVICES_LAB] begin cache-file gate mixed=%d "
           "stockEntries=%d payloadEntries=%d appended68=%d "
           "liveDonor=0x%llx liveReady=%d persistedReady=%d "
           "pathKnown=%d path=\"%s\" ready=%d\n",
           mixedCandidate,
           d.stockEntryCount,
           payloadEntryCount,
           themedPayloadIndex >= d.stockEntryCount,
           (unsigned long long)(stock68Donor ? stock68Donor->image : 0),
           liveStock68Ready,
           persistedStock68Ready,
           d.managerCachePathKnown,
           d.managerCachePathKnown ? d.managerCachePath : "-",
           storeFileRouteReady);

    ThemerSpotlightRemoteImage sourceImages[
        THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP][2] = {0};
    int sourceImageCounts[THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP] = {0};
    uint64_t ifImages[THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP] = {0};
    bool payloadGeometryOK = payloadEntryCount >= 1 &&
        payloadEntryCount <= THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP &&
        primaryPayloadIndex >= 0 && primaryPayloadIndex < payloadEntryCount &&
        (!mixedCandidate ||
         (payloadEntryCount >= 2 && themedPayloadIndex >= 0 &&
          sharedTokenReady && storeFileRouteReady));

    // The mixed candidate retains the genuine stock 40 object as entry 0 and
    // constructs only the themed 68 object. Other candidates keep their prior
    // all-themed behavior.
    for (int i = 0;
         payloadGeometryOK && i < payloadEntryCount &&
             remote_call_current_success(); i++) {
        ThemerIconServicesLabBagEntry *entry = &payloadEntries[i];
        uint64_t sourceImage = 0;
        const char *role = "themed";
        if (mixedCandidate && i != themedPayloadIndex) {
            role = i == primaryPayloadIndex ? "stock40" : "stock-preserved";
            ifImages[i] = r_is_objc_ptr(entry->image)
                ? r_msg2(entry->image, "retain", 0, 0, 0, 0) : 0;
        } else {
            role = mixedCandidate ? "themed68-store-cacheimage" : "themed";
            NSDictionary<NSString *, NSData *> *scaledTheme =
                entry->geometryKnown
                    ? themer_iconservices_lab_scaled_theme_data(
                        normalized, d.targetBundle,
                        entry->width, entry->height, entry->scale)
                    : nil;
            sourceImage = themer_spotlight_remote_image_for_bundle(
                scaledTheme ?: normalized, d.targetBundle,
                sourceImages[i], &sourceImageCounts[i], 2);
            uint64_t concreteImage = entry->geometryKnown
                ? themer_iconservices_lab_make_if_image(
                    sourceImage, entry->scale)
                : 0;
            if (mixedCandidate && i == themedPayloadIndex) {
                bool storeReady = false;
                ifImages[i] =
                    themer_iconservices_lab_make_store_backed_cache_image(
                        concreteImage,
                        stock68Donor,
                        d.targetBundle,
                        d.managerCachePath,
                        entry->width, entry->height, entry->scale,
                        65.0, 65.0,
                        &themedStoreUnitAdded,
                        &storeReady);
                if (!storeReady) payloadGeometryOK = false;
            } else {
                ifImages[i] = concreteImage;
            }
        }
        int minimum65 = -1;
        if (mixedCandidate && i == themedPayloadIndex) {
            double minimumWidth = 0.0, minimumHeight = 0.0;
            minimum65 = r_is_objc_ptr(ifImages[i]) &&
                themer_iconservices_lab_read_size_property(
                    ifImages[i], "minimumSize",
                    &minimumWidth, &minimumHeight) &&
                themer_iconservices_lab_sizes_match(
                    minimumWidth, minimumHeight, 65.0, 65.0);
        }
        bool geometry = r_is_objc_ptr(ifImages[i]) &&
            entry->geometryKnown && minimum65 != 0 &&
            themer_iconservices_lab_image_geometry_matches(
                ifImages[i], entry->width, entry->height, entry->scale);
        payloadGeometryOK = payloadGeometryOK && geometry;
        char payloadClass[96] = {0};
        themer_read_class_name(
            ifImages[i], payloadClass, sizeof(payloadClass));
        printf("[ICONSERVICES_LAB] begin payload-entry index=%d/%d "
               "role=%s source=0x%llx image=0x%llx class=%s geometry=%d "
               "minimum65=%d expected=%.1fx%.1f@%.2f primary=%d\n",
               i,
               payloadEntryCount,
               role,
               (unsigned long long)sourceImage,
               (unsigned long long)ifImages[i],
               payloadClass[0] ? payloadClass : "-",
               geometry,
               minimum65,
               entry->width,
               entry->height,
               entry->scale,
               i == primaryPayloadIndex);
    }
    if (r_is_objc_ptr(stock64Token) && remote_call_current_success()) {
        r_msg2(stock64Token, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(sharedValidationToken) && remote_call_current_success()) {
        r_msg2(sharedValidationToken, "release", 0, 0, 0, 0);
    }
    // The existing-cache-file route persists its recovery metadata directly in
    // the constructor; there is no store-unit UUID to record here.
    bool pendingUUIDPersisted = true;
    payloadGeometryOK = payloadGeometryOK && pendingUUIDPersisted;
    uint64_t ifImage = payloadGeometryOK
        ? ifImages[primaryPayloadIndex] : 0;
    printf("[ICONSERVICES_LAB] begin payload=%s "
           "entries=%d primaryIndex=%d primaryImage=0x%llx geometry=%d\n",
           mixedCandidate ? "stock-preserved-themed68-store" :
               "themed-retained-cg",
           payloadEntryCount,
           primaryPayloadIndex,
           (unsigned long long)ifImage,
           payloadGeometryOK);

    if (!payloadGeometryOK || !remote_call_current_success()) {
        bool cacheFileRestored = !mixedCandidate ||
            themer_iconservices_lab_restore_pending_cache_file();
        printf("[ICONSERVICES_LAB] begin stopped "
               "reason=payload-geometry-mismatch candidate=%s bundle=%s "
               "entries=%d primaryIndex=%d cacheFileRestored=%d\n",
               candidateName,
               d.targetBundle,
               payloadEntryCount,
               primaryPayloadIndex,
               cacheFileRestored);
        if (themedStoreUnitAdded && r_is_objc_ptr(themedStoreUUID) &&
            remote_call_current_success()) {
            bool removed = themer_iconservices_lab_remove_store_unit(
                d.managerIconCache, themedStoreUUID);
            if (removed) {
                themer_iconservices_lab_clear_pending_store_uuid();
                themedStoreUnitAdded = false;
            }
        }
        if (r_is_objc_ptr(themedStoreUUID) && remote_call_current_success()) {
            r_msg2(themedStoreUUID, "release", 0, 0, 0, 0);
            themedStoreUUID = 0;
        }
        themer_iconservices_lab_release_payload(
            ifImages, sourceImages, sourceImageCounts, payloadEntryCount);
        if (r_is_objc_ptr(cloneDesc) && remote_call_current_success()) {
            r_msg2(cloneDesc, "release", 0, 0, 0, 0);
        }
        themer_iconservices_lab_release_discovery(&d);
        r_settle_us(previousSettleUS);
        return cacheFileRestored
            ? ThemerSpotlightIconServicesBeginResultNoEligibleIcon
            : ThemerSpotlightIconServicesBeginResultStateFailed;
    }

    uint64_t state = 0;
    bool statePrearmed = false;
    if (mixedCandidate) {
        uint64_t dictionaryClass = r_class("NSMutableDictionary");
        uint64_t stateAlloc = r_is_objc_ptr(dictionaryClass)
            ? r_msg2(dictionaryClass, "alloc", 0, 0, 0, 0) : 0;
        state = r_is_objc_ptr(stateAlloc)
            ? r_msg2_main(stateAlloc, "initWithCapacity:", 32, 0, 0, 0) : 0;
        uint64_t pidNumber = themer_spotlight_proof_number(
            (unsigned long long)remote_call_current_pid());
        uint64_t candidateNumber = themer_spotlight_proof_number(
            (unsigned long long)candidate);
        uint64_t storeAddedNumber = themer_spotlight_proof_number(
            (unsigned long long)(themedStoreUnitAdded ? 1 : 0));
        bool prearmReady = r_is_objc_ptr(state) && r_is_objc_ptr(pidNumber) &&
            r_is_objc_ptr(candidateNumber) && r_is_objc_ptr(storeAddedNumber) &&
            r_is_objc_ptr(t.originalBags) &&
            r_is_objc_ptr(d.canonicalCache) &&
            r_is_objc_ptr(d.managerIconCache) &&
            r_is_objc_ptr(t.desc) &&
            r_is_objc_ptr(t.stockImage);
        prearmReady = prearmReady &&
            themer_spotlight_dictionary_set_object(state, "pid", pidNumber) &&
            themer_spotlight_dictionary_set_object(
                state, "candidate", candidateNumber) &&
            themer_spotlight_proof_state_set_string(
                state, "targetBundle", d.targetBundle) &&
            themer_spotlight_dictionary_set_object(
                state, "canonicalCache", d.canonicalCache) &&
            themer_spotlight_dictionary_set_object(
                state, "managerCache", d.managerIconCache) &&
            themer_spotlight_dictionary_set_object(
                state, "descriptor", t.desc) &&
            themer_spotlight_dictionary_set_object(
                state, "stockTargetImage", t.stockImage) &&
            themer_spotlight_dictionary_set_object(
                state, "originalBags", t.originalBags) &&
            themer_spotlight_dictionary_set_object(
                state, "storeUnitAdded", storeAddedNumber) &&
            themer_spotlight_proof_state_set_string(
                state, "descriptorSource", descriptorSource) &&
            themer_spotlight_proof_state_set_string(
                state, "descriptorName",
                "com.apple.IconServices.ImageDescriptor.Spotlight");
        if (r_is_objc_ptr(themedStoreUUID)) {
            prearmReady = prearmReady &&
                themer_spotlight_dictionary_set_object(
                    state, "themedStoreUUID", themedStoreUUID);
        }
        statePrearmed = prearmReady &&
            themer_iconservices_lab_commit_state(state);
        printf("[ICONSERVICES_LAB] begin store-state prearm "
               "state=0x%llx uuid=0x%llx storeAdded=%d ready=%d\n",
               (unsigned long long)state,
               (unsigned long long)themedStoreUUID,
               themedStoreUnitAdded,
               statePrearmed);
        if (!statePrearmed) {
            bool cacheFileRestored =
                themer_iconservices_lab_restore_pending_cache_file();
            printf("[ICONSERVICES_LAB] begin prearm-failure cleanup "
                   "cacheFileRestored=%d\n",
                   cacheFileRestored);
            if (themedStoreUnitAdded && remote_call_current_success()) {
                bool removed = themer_iconservices_lab_remove_store_unit(
                    d.managerIconCache, themedStoreUUID);
                if (removed) {
                    themer_iconservices_lab_clear_pending_store_uuid();
                    themedStoreUnitAdded = false;
                }
            }
            if (r_is_objc_ptr(themedStoreUUID) &&
                remote_call_current_success()) {
                r_msg2(themedStoreUUID, "release", 0, 0, 0, 0);
                themedStoreUUID = 0;
            }
            if (r_is_objc_ptr(state) && remote_call_current_success()) {
                r_msg2(state, "release", 0, 0, 0, 0);
            }
            themer_iconservices_lab_release_payload(
                ifImages, sourceImages, sourceImageCounts, payloadEntryCount);
            themer_iconservices_lab_release_discovery(&d);
            r_settle_us(previousSettleUS);
            return ThemerSpotlightIconServicesBeginResultStateFailed;
        }
    }

    // Exactly one candidate mutation per run. Bag swap retains the original
    // dictionary intact. Clear/invalidation candidates invoke exactly one
    // known, correctly typed responder, never a selector shotgun.
    bool mutated = false;
    const char *selectorUsed = NULL;
    if (mixedCandidate) {
        ThemerIconServicesLabDiscovery mixedDiscovery = d;
        mixedDiscovery.stockEntryCount = payloadEntryCount;
        mixedDiscovery.primaryEntryIndex = primaryPayloadIndex;
        mixedDiscovery.stockTopologyKnown = true;
        for (int i = 0; i < payloadEntryCount; i++) {
            mixedDiscovery.stockEntries[i] = payloadEntries[i];
        }
        t.bagCandidate = true;
        mutated = themer_iconservices_lab_install_replacement_bag(
            &mixedDiscovery, &t, ifImages, payloadEntryCount);
        selectorUsed = "setImageBagsByDescriptor:";
    } else if (candidate ==
               ThemerSpotlightIconServicesCandidateCanonicalBagSwap) {
        t.bagCandidate = true;
        mutated = themer_iconservices_lab_install_replacement_bag(
            &d, &t, ifImages, payloadEntryCount);
        selectorUsed = "setImageBagsByDescriptor:";
    } else if (candidate == ThemerSpotlightIconServicesCandidateCanonicalDescriptorClear) {
        r_msg2_main(t.cache, d.descriptorClearSelector, t.desc, 0, 0, 0);
        mutated = remote_call_current_success() &&
            themer_iconservices_lab_seed_image(t.cache, ifImage, t.desc);
        selectorUsed = d.descriptorClearSelector;
    } else if (candidate == ThemerSpotlightIconServicesCandidateCanonicalIconInvalidator) {
        mutated = themer_iconservices_lab_seed_image(t.cache, ifImage, t.desc);
        if (mutated) {
            r_msg2_main(d.canonicalIcon, d.iconInvalidatorSelector,
                        0, 0, 0, 0);
            mutated = remote_call_current_success();
        }
        selectorUsed = d.iconInvalidatorSelector;
    } else if (candidate == ThemerSpotlightIconServicesCandidateCanonicalCacheClear) {
        r_msg2_main(t.cache, d.cacheClearSelector, 0, 0, 0, 0);
        mutated = remote_call_current_success() &&
            themer_iconservices_lab_seed_image(t.cache, ifImage, t.desc);
        selectorUsed = d.cacheClearSelector;
    } else {
        mutated = themer_iconservices_lab_seed_image(t.cache, ifImage, t.desc);
    }
    if (!mutated || !remote_call_current_success()) {
        bool rolledBack = false;
        bool storeRemoved = false;
        bool stateCleared = false;
        bool cleaned = mixedCandidate
            ? themer_iconservices_lab_cleanup_themed_store_mutation(
                &t, d.managerIconCache, themedStoreUUID, statePrearmed,
                &rolledBack, &storeRemoved, &stateCleared)
            : (rolledBack = themer_iconservices_lab_rollback_target(&t));
        if (cleaned) {
            themedStoreUnitAdded = false;
            statePrearmed = false;
        }
        printf("[ICONSERVICES_LAB] begin stopped reason=mutation-failed "
               "candidate=%s mutated=%d rollback=%d success=%d\n",
               candidateName,
               mutated,
               rolledBack,
               remote_call_current_success());
        themer_iconservices_lab_release_payload(
            ifImages, sourceImages, sourceImageCounts, payloadEntryCount);
        if (r_is_objc_ptr(cloneDesc) && remote_call_current_success()) {
            r_msg2(cloneDesc, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(t.replacementBags) &&
            remote_call_current_success()) {
            r_msg2(t.replacementBags, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(themedStoreUUID) &&
            remote_call_current_success()) {
            r_msg2(themedStoreUUID, "release", 0, 0, 0, 0);
            themedStoreUUID = 0;
        }
        if (r_is_objc_ptr(state) && remote_call_current_success()) {
            r_msg2(state, "release", 0, 0, 0, 0);
        }
        themer_iconservices_lab_release_discovery(&d);
        r_settle_us(previousSettleUS);
        return rolledBack
            ? ThemerSpotlightIconServicesBeginResultImmediateReadbackMiss
            : ThemerSpotlightIconServicesBeginResultStateFailed;
    }

    uint64_t readback = themer_iconservices_lab_read_image(t.readObj, t.desc);
    bool immediateHit = themer_spotlight_images_match(ifImage, readback) &&
                        remote_call_current_success();
    bool controlStock = themer_iconservices_lab_control_still_stock(&d);
    printf("[ICONSERVICES_LAB] begin phase1 pid=%d candidate=%s "
           "descriptorSource=%s selector=%s targetReadback=0x%llx "
           "hit=%d controlStock=%d success=%d ioFailures=%llu\n",
           remote_call_current_pid(),
           candidateName,
           descriptorSource,
           selectorUsed ?: "-",
           (unsigned long long)readback,
           immediateHit,
           controlStock,
           remote_call_current_success(),
           (unsigned long long)remote_call_current_io_failure_count());
    if (!immediateHit) {
        bool rolledBack = false;
        bool storeRemoved = false;
        bool stateCleared = false;
        bool cleaned = mixedCandidate
            ? themer_iconservices_lab_cleanup_themed_store_mutation(
                &t, d.managerIconCache, themedStoreUUID, statePrearmed,
                &rolledBack, &storeRemoved, &stateCleared)
            : (rolledBack = themer_iconservices_lab_rollback_target(&t));
        if (cleaned) {
            themedStoreUnitAdded = false;
            statePrearmed = false;
        }
        printf("[ICONSERVICES_LAB] begin stopped "
               "reason=immediate-readback-miss candidate=%s "
               "rollback=%d\n",
               candidateName,
               rolledBack);
        themer_iconservices_lab_release_payload(
            ifImages, sourceImages, sourceImageCounts, payloadEntryCount);
        if (r_is_objc_ptr(cloneDesc) && remote_call_current_success()) {
            r_msg2(cloneDesc, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(t.replacementBags) &&
            remote_call_current_success()) {
            r_msg2(t.replacementBags, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(themedStoreUUID) &&
            remote_call_current_success()) {
            r_msg2(themedStoreUUID, "release", 0, 0, 0, 0);
            themedStoreUUID = 0;
        }
        if (r_is_objc_ptr(state) && remote_call_current_success()) {
            r_msg2(state, "release", 0, 0, 0, 0);
        }
        themer_iconservices_lab_release_discovery(&d);
        r_settle_us(previousSettleUS);
        return rolledBack
            ? ThemerSpotlightIconServicesBeginResultImmediateReadbackMiss
            : ThemerSpotlightIconServicesBeginResultStateFailed;
    }
    if (!controlStock) {
        // Roll back the target first; when caches are shared this also
        // restores the control entry, then re-check the control.
        bool rolledBack = false;
        bool storeRemoved = false;
        bool stateCleared = false;
        bool cleaned = mixedCandidate
            ? themer_iconservices_lab_cleanup_themed_store_mutation(
                &t, d.managerIconCache, themedStoreUUID, statePrearmed,
                &rolledBack, &storeRemoved, &stateCleared)
            : (rolledBack = themer_iconservices_lab_rollback_target(&t));
        if (cleaned) {
            themedStoreUnitAdded = false;
            statePrearmed = false;
        }
        bool controlRestored = rolledBack &&
            themer_iconservices_lab_control_still_stock(&d);
        printf("[ICONSERVICES_LAB] begin stopped reason=control-changed "
               "candidate=%s controlRestoredAfterRollback=%d\n",
               candidateName,
               controlRestored);
        themer_iconservices_lab_release_payload(
            ifImages, sourceImages, sourceImageCounts, payloadEntryCount);
        if (r_is_objc_ptr(cloneDesc) && remote_call_current_success()) {
            r_msg2(cloneDesc, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(t.replacementBags) &&
            remote_call_current_success()) {
            r_msg2(t.replacementBags, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(themedStoreUUID) &&
            remote_call_current_success()) {
            r_msg2(themedStoreUUID, "release", 0, 0, 0, 0);
            themedStoreUUID = 0;
        }
        if (r_is_objc_ptr(state) && remote_call_current_success()) {
            r_msg2(state, "release", 0, 0, 0, 0);
        }
        themer_iconservices_lab_release_discovery(&d);
        r_settle_us(previousSettleUS);
        return rolledBack && controlRestored
            ? ThemerSpotlightIconServicesBeginResultControlChanged
            : ThemerSpotlightIconServicesBeginResultStateFailed;
    }

    // Commit the process-resident state so a later same-PID session can
    // verify persistence and perform the targeted restore.
    if (!mixedCandidate) {
        uint64_t dictionaryClass = r_class("NSMutableDictionary");
        uint64_t stateAlloc = r_is_objc_ptr(dictionaryClass)
            ? r_msg2(dictionaryClass, "alloc", 0, 0, 0, 0) : 0;
        state = r_is_objc_ptr(stateAlloc)
            ? r_msg2_main(stateAlloc, "initWithCapacity:", 24, 0, 0, 0) : 0;
    }
    bool stateReady = mixedCandidate ? statePrearmed : r_is_objc_ptr(state);
    uint64_t pidNumber = themer_spotlight_proof_number(
        (unsigned long long)remote_call_current_pid());
    uint64_t candidateNumber = themer_spotlight_proof_number(
        (unsigned long long)candidate);
    uint64_t bagSwappedNumber = t.bagSwapped
        ? themer_spotlight_proof_number(1) : 0;
    stateReady = stateReady && r_is_objc_ptr(pidNumber) &&
        themer_spotlight_dictionary_set_object(state, "pid", pidNumber);
    stateReady = stateReady && r_is_objc_ptr(candidateNumber) &&
        themer_spotlight_dictionary_set_object(state, "candidate",
                                               candidateNumber);
    stateReady = stateReady &&
        themer_spotlight_proof_state_set_string(
            state, "targetBundle", d.targetBundle);
    if (d.haveControl) {
        stateReady = themer_spotlight_proof_state_set_string(
            state, "controlBundle", d.controlBundle) && stateReady;
    }
    stateReady = stateReady &&
        themer_spotlight_dictionary_set_object(state, "localIcon",
                                               d.localIcon) &&
        themer_spotlight_dictionary_set_object(state, "canonicalIcon",
                                               d.canonicalIcon);
    if (r_is_objc_ptr(d.localCache)) {
        stateReady = themer_spotlight_dictionary_set_object(
            state, "localCache", d.localCache) && stateReady;
    }
    if (r_is_objc_ptr(d.canonicalCache)) {
        stateReady = themer_spotlight_dictionary_set_object(
            state, "canonicalCache", d.canonicalCache) && stateReady;
    }
    if (r_is_objc_ptr(d.managerIconCache)) {
        stateReady = themer_spotlight_dictionary_set_object(
            state, "managerCache", d.managerIconCache) && stateReady;
    }
    if (d.managerCachePathKnown) {
        stateReady = themer_spotlight_proof_state_set_string(
            state, "managerCachePath", d.managerCachePath) && stateReady;
    }
    if (mixedCandidate) {
        uint64_t storeAddedNumber = themer_spotlight_proof_number(
            (unsigned long long)(themedStoreUnitAdded ? 1 : 0));
        stateReady = stateReady && r_is_objc_ptr(storeAddedNumber) &&
            themer_spotlight_dictionary_set_object(
                state, "storeUnitAdded", storeAddedNumber);
        if (r_is_objc_ptr(themedStoreUUID)) {
            stateReady = stateReady &&
                themer_spotlight_dictionary_set_object(
                    state, "themedStoreUUID", themedStoreUUID);
        }
    }
    stateReady = stateReady &&
        themer_spotlight_dictionary_set_object(state, "descriptor", t.desc) &&
        themer_spotlight_proof_state_set_string(
            state, "descriptorSource", descriptorSource) &&
        themer_spotlight_proof_state_set_string(
            state, "descriptorName",
            "com.apple.IconServices.ImageDescriptor.Spotlight");
    if (d.descSizeOK) {
        uint64_t w = themer_iconservices_lab_double_number(d.descSizeW);
        uint64_t h = themer_iconservices_lab_double_number(d.descSizeH);
        stateReady = stateReady && r_is_objc_ptr(w) &&
            themer_spotlight_dictionary_set_object(state, "descSizeW", w);
        stateReady = stateReady && r_is_objc_ptr(h) &&
            themer_spotlight_dictionary_set_object(state, "descSizeH", h);
    }
    if (d.descScaleOK) {
        uint64_t scale = themer_iconservices_lab_double_number(d.descScale);
        stateReady = stateReady && r_is_objc_ptr(scale) &&
            themer_spotlight_dictionary_set_object(state, "descScale", scale);
    }
    if (d.descAppearanceOK) {
        uint64_t number = themer_spotlight_proof_number(d.descAppearance);
        stateReady = stateReady && r_is_objc_ptr(number) &&
            themer_spotlight_dictionary_set_object(state, "descAppearance",
                                                   number);
    }
    if (d.descAppearanceVariantOK) {
        uint64_t number = themer_spotlight_proof_number(
            d.descAppearanceVariant);
        stateReady = stateReady && r_is_objc_ptr(number) &&
            themer_spotlight_dictionary_set_object(
                state, "descAppearanceVariant", number);
    }
    if (d.descIconVariantOK) {
        uint64_t number = themer_spotlight_proof_number(d.descIconVariant);
        stateReady = stateReady && r_is_objc_ptr(number) &&
            themer_spotlight_dictionary_set_object(state, "descIconVariant",
                                                   number);
    }
    if (d.descVariantOptionsOK) {
        uint64_t number = themer_spotlight_proof_number(d.descVariantOptions);
        stateReady = stateReady && r_is_objc_ptr(number) &&
            themer_spotlight_dictionary_set_object(state, "descVariantOptions",
                                                   number);
    }
    stateReady = stateReady &&
        themer_spotlight_dictionary_set_object(state, "expectedImage",
                                               ifImage) &&
        themer_spotlight_dictionary_set_object(state, "stockTargetImage",
                                               t.stockImage);
    if (bagCandidate) {
        uint64_t entryCountNumber = themer_spotlight_proof_number(
            (unsigned long long)payloadEntryCount);
        uint64_t primaryIndexNumber = themer_spotlight_proof_number(
            (unsigned long long)primaryPayloadIndex);
        stateReady = stateReady && r_is_objc_ptr(entryCountNumber) &&
            themer_spotlight_dictionary_set_object(
                state, "bagEntryCount", entryCountNumber);
        stateReady = stateReady && r_is_objc_ptr(primaryIndexNumber) &&
            themer_spotlight_dictionary_set_object(
                state, "bagPrimaryIndex", primaryIndexNumber);
        for (int i = 0; i < payloadEntryCount; i++) {
            char imageKey[48] = {0};
            char widthKey[48] = {0};
            char heightKey[48] = {0};
            char scaleKey[48] = {0};
            snprintf(imageKey, sizeof(imageKey), "bagExpectedImage%d", i);
            snprintf(widthKey, sizeof(widthKey), "bagEntryWidth%d", i);
            snprintf(heightKey, sizeof(heightKey), "bagEntryHeight%d", i);
            snprintf(scaleKey, sizeof(scaleKey), "bagEntryScale%d", i);
            uint64_t widthNumber = themer_iconservices_lab_double_number(
                payloadEntries[i].width);
            uint64_t heightNumber = themer_iconservices_lab_double_number(
                payloadEntries[i].height);
            uint64_t scaleNumber = themer_iconservices_lab_double_number(
                payloadEntries[i].scale);
            stateReady = stateReady && r_is_objc_ptr(ifImages[i]) &&
                themer_spotlight_dictionary_set_object(
                    state, imageKey, ifImages[i]);
            stateReady = stateReady && r_is_objc_ptr(widthNumber) &&
                themer_spotlight_dictionary_set_object(
                    state, widthKey, widthNumber);
            stateReady = stateReady && r_is_objc_ptr(heightNumber) &&
                themer_spotlight_dictionary_set_object(
                    state, heightKey, heightNumber);
            stateReady = stateReady && r_is_objc_ptr(scaleNumber) &&
                themer_spotlight_dictionary_set_object(
                    state, scaleKey, scaleNumber);
        }
    }
    if (r_is_objc_ptr(d.stockControlImage)) {
        stateReady = themer_spotlight_dictionary_set_object(
            state, "stockControlImage", d.stockControlImage) && stateReady;
    }
    if (bagCandidate) {
        stateReady = stateReady &&
            themer_spotlight_dictionary_set_object(state, "originalBags",
                                                   t.originalBags) &&
            themer_spotlight_dictionary_set_object(state, "replacementBags",
                                                   t.replacementBags);
        stateReady = stateReady && r_is_objc_ptr(bagSwappedNumber) &&
            themer_spotlight_dictionary_set_object(state, "bagsSwapped",
                                                   bagSwappedNumber);
    }
    if (selectorUsed) {
        stateReady = themer_spotlight_proof_state_set_string(
            state, "selectorUsed", selectorUsed) && stateReady;
    }

    bool committed = stateReady &&
        themer_iconservices_lab_commit_state(state);
    if (!committed) {
        bool rolledBack = false;
        bool storeRemoved = false;
        bool stateCleared = false;
        bool cleaned = mixedCandidate
            ? themer_iconservices_lab_cleanup_themed_store_mutation(
                &t, d.managerIconCache, themedStoreUUID, statePrearmed,
                &rolledBack, &storeRemoved, &stateCleared)
            : (rolledBack = themer_iconservices_lab_rollback_target(&t));
        if (cleaned) {
            themedStoreUnitAdded = false;
            statePrearmed = false;
        }
        printf("[ICONSERVICES_LAB] begin stopped reason=state-commit-failed "
               "candidate=%s stateReady=%d rollback=%d\n",
               candidateName,
               stateReady,
               rolledBack);
        if (r_is_objc_ptr(state) && remote_call_current_success()) {
            r_msg2(state, "release", 0, 0, 0, 0);
        }
        themer_iconservices_lab_release_payload(
            ifImages, sourceImages, sourceImageCounts, payloadEntryCount);
        if (r_is_objc_ptr(cloneDesc) && remote_call_current_success()) {
            r_msg2(cloneDesc, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(t.replacementBags) &&
            remote_call_current_success()) {
            r_msg2(t.replacementBags, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(themedStoreUUID) &&
            remote_call_current_success()) {
            r_msg2(themedStoreUUID, "release", 0, 0, 0, 0);
            themedStoreUUID = 0;
        }
        themer_iconservices_lab_release_discovery(&d);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesBeginResultStateFailed;
    }

    // The committed state dictionary retains every object it stored; drop
    // the owned +1s that were transferred and release what remains.
    themer_iconservices_lab_release_payload(
        ifImages, sourceImages, sourceImageCounts, payloadEntryCount);
    if (r_is_objc_ptr(themedStoreUUID) && remote_call_current_success()) {
        r_msg2(themedStoreUUID, "release", 0, 0, 0, 0);
        themedStoreUUID = 0;
    }
    if (r_is_objc_ptr(cloneDesc) && remote_call_current_success()) {
        r_msg2(cloneDesc, "release", 0, 0, 0, 0);
    }
    if (bagCandidate) {
        if (r_is_objc_ptr(t.replacementBags) &&
            remote_call_current_success()) {
            r_msg2(t.replacementBags, "release", 0, 0, 0, 0);
        }
        if (mixedCandidate) {
            d.prePrepareBagsCopy = 0;  // stored as originalBags
        } else {
            d.originalBags = 0;  // stored
        }
    }
    d.localIcon = 0;  // stored
    if (candidate != ThemerSpotlightIconServicesCandidateCanonicalFactoryClone &&
        candidate != ThemerSpotlightIconServicesCandidateCanonicalInitClone) {
        d.descriptor = 0;  // stored
    }
    themer_iconservices_lab_release_discovery(&d);
    if (r_is_objc_ptr(state) && remote_call_current_success()) {
        r_msg2(state, "release", 0, 0, 0, 0);
    }
    r_settle_us(previousSettleUS);
    printf("[ICONSERVICES_LAB] begin seeded pid=%d candidate=%s "
           "descriptorSource=%s selector=%s readback=0x%llx "
           "committed=%d total=%llums\n",
           remote_call_current_pid(),
           candidateName,
           descriptorSource,
           selectorUsed ?: "-",
           (unsigned long long)readback,
           committed,
           (unsigned long long)((themer_now_us() - startUS) / 1000ULL));
    return ThemerSpotlightIconServicesBeginResultSeeded;
}

// Stored fields reloaded from the lab state dictionary.
typedef struct {
    int candidate;
    char targetBundle[192];
    char controlBundle[192];
    char descriptorSource[32];
    char descriptorName[96];
    char selectorUsed[96];
    char managerCachePath[240];
    uint64_t localIcon;
    uint64_t canonicalIcon;
    uint64_t localCache;
    uint64_t canonicalCache;
    uint64_t managerCache;
    uint64_t descriptor;
    uint64_t themedStoreUUID;
    bool storeUnitAdded;
    uint64_t expectedImage;  // Primary payload entry.
    uint64_t expectedImages[THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP];
    double bagEntryWidths[THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP];
    double bagEntryHeights[THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP];
    double bagEntryScales[THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP];
    int bagEntryCount;
    int bagPrimaryIndex;
    uint64_t stockTargetImage;
    uint64_t stockControlImage;
    uint64_t originalBags;
    uint64_t replacementBags;
    double descSizeW;
    double descSizeH;
    double descScale;
    uint64_t descAppearance;
    uint64_t descAppearanceVariant;
    uint64_t descIconVariant;
    uint64_t descVariantOptions;
} ThemerIconServicesLabStored;

static bool themer_iconservices_lab_state_load(
    uint64_t state,
    ThemerIconServicesLabStored *s)
{
    if (!s) return false;
    memset(s, 0, sizeof(*s));
    if (!r_is_objc_ptr(state)) return false;
    uint64_t candidate = 0;
    bool candidateKnown =
        themer_spotlight_proof_state_u64(state, "candidate", &candidate);
    if (candidateKnown &&
        candidate < (uint64_t)ThemerSpotlightIconServicesCandidateCount) {
        s->candidate = (int)candidate;
    } else {
        candidateKnown = false;
    }
    (void)themer_spotlight_proof_state_string(state, "targetBundle",
                                              s->targetBundle,
                                              sizeof(s->targetBundle));
    (void)themer_spotlight_proof_state_string(state, "controlBundle",
                                              s->controlBundle,
                                              sizeof(s->controlBundle));
    (void)themer_spotlight_proof_state_string(state, "descriptorSource",
                                              s->descriptorSource,
                                              sizeof(s->descriptorSource));
    (void)themer_spotlight_proof_state_string(state, "descriptorName",
                                              s->descriptorName,
                                              sizeof(s->descriptorName));
    (void)themer_spotlight_proof_state_string(state, "selectorUsed",
                                              s->selectorUsed,
                                              sizeof(s->selectorUsed));
    (void)themer_spotlight_proof_state_string(state, "managerCachePath",
                                              s->managerCachePath,
                                              sizeof(s->managerCachePath));
    s->localIcon = themer_spotlight_dictionary_object(state, "localIcon");
    s->canonicalIcon = themer_spotlight_dictionary_object(state,
                                                          "canonicalIcon");
    s->localCache = themer_spotlight_dictionary_object(state, "localCache");
    s->canonicalCache = themer_spotlight_dictionary_object(state,
                                                           "canonicalCache");
    s->managerCache = themer_spotlight_dictionary_object(state,
                                                         "managerCache");
    s->descriptor = themer_spotlight_dictionary_object(state, "descriptor");
    s->themedStoreUUID = themer_spotlight_dictionary_object(
        state, "themedStoreUUID");
    uint64_t storeUnitAdded = 0;
    s->storeUnitAdded = themer_spotlight_proof_state_u64(
        state, "storeUnitAdded", &storeUnitAdded) && storeUnitAdded != 0;
    s->expectedImage = themer_spotlight_dictionary_object(state,
                                                          "expectedImage");
    s->stockTargetImage = themer_spotlight_dictionary_object(
        state, "stockTargetImage");
    s->stockControlImage = themer_spotlight_dictionary_object(
        state, "stockControlImage");
    s->originalBags = themer_spotlight_dictionary_object(state,
                                                         "originalBags");
    s->replacementBags = themer_spotlight_dictionary_object(
        state, "replacementBags");
    (void)themer_iconservices_lab_state_double(state, "descSizeW",
                                               &s->descSizeW);
    (void)themer_iconservices_lab_state_double(state, "descSizeH",
                                               &s->descSizeH);
    (void)themer_iconservices_lab_state_double(state, "descScale",
                                               &s->descScale);
    (void)themer_spotlight_proof_state_u64(state, "descAppearance",
                                           &s->descAppearance);
    (void)themer_spotlight_proof_state_u64(state, "descAppearanceVariant",
                                           &s->descAppearanceVariant);
    (void)themer_spotlight_proof_state_u64(state, "descIconVariant",
                                           &s->descIconVariant);
    (void)themer_spotlight_proof_state_u64(state, "descVariantOptions",
                                           &s->descVariantOptions);

    bool topologyStateKnown = true;
    if (s->candidate ==
            ThemerSpotlightIconServicesCandidateCanonicalBagSwap ||
        s->candidate ==
            ThemerSpotlightIconServicesCandidateCanonicalMixedBag) {
        uint64_t entryCount = 0;
        uint64_t primaryIndex = 0;
        bool hasDynamicCount = themer_spotlight_proof_state_u64(
            state, "bagEntryCount", &entryCount);
        if (hasDynamicCount && entryCount >= 1 &&
            entryCount <= THEMER_ICONSERVICES_LAB_BAG_ITEM_CAP &&
            themer_spotlight_proof_state_u64(
                state, "bagPrimaryIndex", &primaryIndex) &&
            primaryIndex < entryCount) {
            s->bagEntryCount = (int)entryCount;
            s->bagPrimaryIndex = (int)primaryIndex;
            for (int i = 0; i < s->bagEntryCount; i++) {
                char imageKey[48] = {0};
                char widthKey[48] = {0};
                char heightKey[48] = {0};
                char scaleKey[48] = {0};
                snprintf(imageKey, sizeof(imageKey),
                         "bagExpectedImage%d", i);
                snprintf(widthKey, sizeof(widthKey), "bagEntryWidth%d", i);
                snprintf(heightKey, sizeof(heightKey), "bagEntryHeight%d", i);
                snprintf(scaleKey, sizeof(scaleKey), "bagEntryScale%d", i);
                s->expectedImages[i] =
                    themer_spotlight_dictionary_object(state, imageKey);
                bool widthKnown = themer_iconservices_lab_state_double(
                    state, widthKey, &s->bagEntryWidths[i]);
                bool heightKnown = themer_iconservices_lab_state_double(
                    state, heightKey, &s->bagEntryHeights[i]);
                bool scaleKnown = themer_iconservices_lab_state_double(
                    state, scaleKey, &s->bagEntryScales[i]);
                topologyStateKnown = topologyStateKnown &&
                    r_is_objc_ptr(s->expectedImages[i]) && widthKnown &&
                    heightKnown && scaleKnown &&
                    s->bagEntryWidths[i] > 0.0 &&
                    s->bagEntryHeights[i] > 0.0 &&
                    s->bagEntryScales[i] >= 1.0 &&
                    s->bagEntryScales[i] <= 4.0;
            }
            topologyStateKnown = topologyStateKnown &&
                s->expectedImages[s->bagPrimaryIndex] == s->expectedImage;
        } else {
            // Compatibility with the earlier fixed 40/68 state format. This
            // keeps an already-armed diagnostic run restorable after update.
            uint64_t legacy68 = themer_spotlight_dictionary_object(
                state, "expectedImage68");
            s->bagEntryCount = r_is_objc_ptr(legacy68) ? 2 : 1;
            s->bagPrimaryIndex = 0;
            s->expectedImages[0] = s->expectedImage;
            s->bagEntryWidths[0] = s->descSizeW;
            s->bagEntryHeights[0] = s->descSizeH;
            s->bagEntryScales[0] = s->descScale;
            if (s->bagEntryCount == 2) {
                s->expectedImages[1] = legacy68;
                s->bagEntryWidths[1] = 68.0;
                s->bagEntryHeights[1] = 68.0;
                s->bagEntryScales[1] = s->descScale;
            }
            topologyStateKnown = r_is_objc_ptr(s->expectedImage) &&
                s->descSizeW > 0.0 && s->descSizeH > 0.0 &&
                s->descScale >= 1.0 && s->descScale <= 4.0;
        }
    } else {
        s->bagEntryCount = 1;
        s->bagPrimaryIndex = 0;
        s->expectedImages[0] = s->expectedImage;
        s->bagEntryWidths[0] = s->descSizeW;
        s->bagEntryHeights[0] = s->descSizeH;
        s->bagEntryScales[0] = s->descScale;
    }
    bool storeStateKnown = s->candidate !=
            ThemerSpotlightIconServicesCandidateCanonicalMixedBag ||
        (s->storeUnitAdded && r_is_objc_ptr(s->themedStoreUUID));
    return candidateKnown && topologyStateKnown && storeStateKnown &&
           s->targetBundle[0] && r_is_objc_ptr(s->descriptor) &&
           r_is_objc_ptr(s->expectedImage) &&
           r_is_objc_ptr(s->stockTargetImage) &&
           remote_call_current_success();
}

// Fresh-session reacquisition of the canonical IconServices path. Pointers
// from state are never trusted alone; class names and identity relations
// are logged by the caller. freshLocal is +1 owned by the caller.
typedef struct {
    uint64_t freshLocal;        // +1 owned
    uint64_t canonicalIcon;
    uint64_t canonicalCache;
    uint64_t localCache;
    uint64_t managerCache;
    uint64_t descriptor;        // +1 fresh named Spotlight descriptor
    bool descriptorLiteralFallback;
    bool canonicalFresh;
} ThemerIconServicesLabReacquired;

static bool themer_iconservices_lab_reacquire(
    const ThemerIconServicesLabStored *s,
    ThemerIconServicesLabReacquired *r)
{
    memset(r, 0, sizeof(*r));
    if (!s || !r || !remote_call_current_success()) return false;
    if (!themer_ensure_iconservices_loaded()) {
        return false;
    }
    if (!remote_call_current_success()) return false;
    uint64_t mgrCls = themer_lookup_class("ISIconManager");
    if (!remote_call_current_success()) return false;
    uint64_t manager = r_is_objc_ptr(mgrCls) &&
                       r_responds_main(mgrCls, "sharedInstance")
        ? r_msg2_main(mgrCls, "sharedInstance", 0, 0, 0, 0) : 0;
    if (!remote_call_current_success()) return false;
    r->freshLocal = themer_iconservices_lab_make_bundle_icon(
        s->targetBundle);
    if (!remote_call_current_success()) return false;
    if (r_is_objc_ptr(manager) && r_is_objc_ptr(r->freshLocal) &&
        r_responds_main(manager, "findOrRegisterIcon:")) {
        r->canonicalIcon = r_msg2_main(manager, "findOrRegisterIcon:",
                                       r->freshLocal, 0, 0, 0);
        if (!remote_call_current_success()) return false;
        r->canonicalFresh = r_is_objc_ptr(r->canonicalIcon);
    }
    if (r_is_objc_ptr(r->canonicalIcon) &&
        r_responds_main(r->canonicalIcon, "imageCache")) {
        r->canonicalCache = r_msg2_main(r->canonicalIcon, "imageCache",
                                        0, 0, 0, 0);
    }
    if (r_is_objc_ptr(r->freshLocal) &&
        r_responds_main(r->freshLocal, "imageCache")) {
        r->localCache = r_msg2_main(r->freshLocal, "imageCache", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(manager) && r_responds_main(manager, "iconCache")) {
        r->managerCache = r_msg2_main(manager, "iconCache", 0, 0, 0, 0);
    }
    if (!remote_call_current_success()) return false;
    if (strcmp(s->descriptorSource, "named-spotlight") == 0) {
        r->descriptor = themer_iconservices_lab_named_spotlight_descriptor(
            NULL, NULL, &r->descriptorLiteralFallback);
    } else if (r_is_objc_ptr(s->descriptor)) {
        // Compatibility recovery for any state armed by an earlier diagnostic
        // build. New runs always take the named-spotlight branch above.
        r->descriptor = r_msg2(s->descriptor, "retain", 0, 0, 0, 0);
    }
    return remote_call_current_success() &&
           r_is_objc_ptr(r->descriptor) &&
           r->canonicalFresh;
}

static void themer_iconservices_lab_release_reacquired(
    ThemerIconServicesLabReacquired *r)
{
    if (!r) return;
    if (r_is_objc_ptr(r->descriptor) && remote_call_current_success()) {
        r_msg2(r->descriptor, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(r->freshLocal) && remote_call_current_success()) {
        r_msg2(r->freshLocal, "release", 0, 0, 0, 0);
    }
    memset(r, 0, sizeof(*r));
}

// Targeted stock/original-bags restore for the retained candidate. Returns
// true only when the post-restore readback matches the captured stock.
static bool themer_iconservices_lab_restore_candidate(
    const ThemerIconServicesLabStored *s,
    const ThemerIconServicesLabReacquired *r,
    uint64_t *readbackOut)
{
    if (readbackOut) *readbackOut = 0;
    if (!s || !r || !remote_call_current_success()) return false;

    uint64_t restoreCache = 0;
    uint64_t restoreReadObj = 0;
    uint64_t extraCache = 0;
    bool mixedRestore = s->candidate ==
        ThemerSpotlightIconServicesCandidateCanonicalMixedBag;
    bool bagSwap =
        s->candidate ==
            ThemerSpotlightIconServicesCandidateCanonicalBagSwap ||
        mixedRestore;
    switch (s->candidate) {
        case ThemerSpotlightIconServicesCandidateLocalExistingDescriptor:
            restoreCache = r_is_objc_ptr(s->localCache)
                ? s->localCache : r->localCache;
            restoreReadObj = s->localIcon;
            break;
        case ThemerSpotlightIconServicesCandidateManagerCache:
            restoreCache = r_is_objc_ptr(r->managerCache)
                ? r->managerCache : s->managerCache;
            restoreReadObj = restoreCache;
            break;
        default:
            if (bagSwap) {
                // Only the retained discovery-time cache was replaced. If
                // IconServices created a fresh cache meanwhile, leave its
                // unrelated live entries untouched.
                restoreCache = s->canonicalCache;
                restoreReadObj = s->canonicalIcon;
            } else {
                restoreCache = r_is_objc_ptr(r->canonicalCache)
                    ? r->canonicalCache : s->canonicalCache;
                restoreReadObj = r_is_objc_ptr(r->canonicalIcon)
                    ? r->canonicalIcon : s->canonicalIcon;
                if (r_is_objc_ptr(s->canonicalCache) &&
                    s->canonicalCache != restoreCache) {
                    extraCache = s->canonicalCache;
                }
            }
            break;
    }
    uint64_t descriptor = r->descriptor;
    if (!r_is_objc_ptr(restoreCache) || !r_is_objc_ptr(restoreReadObj) ||
        !r_is_objc_ptr(descriptor) ||
        !r_is_objc_ptr(s->stockTargetImage)) {
        return false;
    }
    if (bagSwap) {
        if (!r_is_objc_ptr(s->originalBags) ||
            !r_responds_main(restoreCache, "setImageBagsByDescriptor:")) {
            return false;
        }
        int originalBagsCount = (int)themer_remote_count(s->originalBags);
        if (!remote_call_current_success()) return false;
        r_msg2_main(restoreCache, "setImageBagsByDescriptor:",
                    s->originalBags, 0, 0, 0);
        if (!remote_call_current_success()) return false;
        if (r_is_objc_ptr(extraCache) && extraCache != restoreCache &&
            r_responds_main(extraCache, "setImageBagsByDescriptor:")) {
            r_msg2_main(extraCache, "setImageBagsByDescriptor:",
                        s->originalBags, 0, 0, 0);
            if (!remote_call_current_success()) return false;
        }
        if (mixedRestore) {
            bool dictionaryRestored =
                themer_iconservices_lab_dictionary_restored(
                    restoreCache, s->originalBags, originalBagsCount);
            uint64_t managerCache = r_is_objc_ptr(r->managerCache)
                ? r->managerCache : s->managerCache;
            bool storeRemoved = false;
            if (s->storeUnitAdded && r_is_objc_ptr(s->themedStoreUUID)) {
                storeRemoved = dictionaryRestored &&
                    themer_iconservices_lab_remove_store_unit(
                        managerCache, s->themedStoreUUID);
                if (storeRemoved) {
                    themer_iconservices_lab_clear_pending_store_uuid();
                }
            } else {
                // Existing-cache-file route: dictionary first, then the exact
                // backup overwrite of the stock68 record, then state clear.
                storeRemoved = dictionaryRestored &&
                    themer_iconservices_lab_restore_pending_cache_file();
            }
            printf("[ICONSERVICES_LAB] restore themed-store "
                   "dictionary=%d uuid=0x%llx removed=%d route=%s\n",
                   dictionaryRestored,
                   (unsigned long long)s->themedStoreUUID,
                   storeRemoved,
                   s->storeUnitAdded ? "store-unit" : "existing-cache-file");
            return dictionaryRestored && storeRemoved &&
                remote_call_current_success();
        }
    } else {
        if (!themer_iconservices_lab_seed_image(restoreCache,
                                                s->stockTargetImage,
                                                descriptor)) {
            return false;
        }
        if (r_is_objc_ptr(extraCache) && extraCache != restoreCache) {
            (void)themer_iconservices_lab_seed_image(extraCache,
                                                     s->stockTargetImage,
                                                     descriptor);
            if (!remote_call_current_success()) return false;
        }
    }
    uint64_t readback = themer_iconservices_lab_read_image(restoreReadObj,
                                                           descriptor);
    if (readbackOut) *readbackOut = readback;
    return themer_spotlight_images_match(s->stockTargetImage, readback) &&
           remote_call_current_success();
}

bool themer_spotlight_iconservices_has_state_in_session(void)
{
    if (!remote_call_current_success()) return false;
    return r_is_objc_ptr(themer_iconservices_lab_state());
}

ThemerSpotlightIconServicesVerifyResult
themer_spotlight_iconservices_verify_and_cleanup_in_session(void)
{
    uint64_t startUS = themer_now_us();
    uint32_t previousSettleUS = r_settle_us(1000);
    if (!remote_call_current_success()) {
        printf("[ICONSERVICES_LAB] verify aborted reason=transport-down\n");
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesVerifyResultInconclusive;
    }
    uint64_t state = themer_iconservices_lab_state();
    if (!r_is_objc_ptr(state)) {
        printf("[ICONSERVICES_LAB] verify skipped reason=no-state\n");
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesVerifyResultNoState;
    }

    uint64_t statePid = 0;
    bool pidKnown = themer_spotlight_proof_state_u64(state, "pid", &statePid);
    int currentPid = remote_call_current_pid();
    if (!pidKnown || statePid != (uint64_t)currentPid) {
        printf("[ICONSERVICES_LAB] verify host-mismatch statePid=%llu "
               "currentPid=%d stateRetained=1\n",
               (unsigned long long)statePid,
               currentPid);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesVerifyResultHostStateMismatch;
    }

    ThemerIconServicesLabStored s = {0};
    if (!themer_iconservices_lab_state_load(state, &s)) {
        if (!remote_call_current_success()) {
            // Transport failure while reading state: retain the state so a
            // later session can still perform the targeted restore.
            printf("[ICONSERVICES_LAB] verify inconclusive "
                   "reason=state-read-transport-failure stateRetained=1\n");
            r_settle_us(previousSettleUS);
            return ThemerSpotlightIconServicesVerifyResultInconclusive;
        }
        printf("[ICONSERVICES_LAB] verify host-mismatch "
               "reason=incomplete-state stateRetained=1\n");
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesVerifyResultHostStateMismatch;
    }
    const char *candidateName =
        themer_spotlight_iconservices_candidate_name(
            (ThemerSpotlightIconServicesCandidate)s.candidate);
    if (s.candidate < 0 ||
        s.candidate >= ThemerSpotlightIconServicesCandidateCount) {
        printf("[ICONSERVICES_LAB] verify host-mismatch "
               "reason=unknown-stored-candidate candidate=%d "
               "stateRetained=1\n",
               s.candidate);
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesVerifyResultHostStateMismatch;
    }

    ThemerIconServicesLabReacquired r = {0};
    bool reacquired = themer_iconservices_lab_reacquire(&s, &r);
    if (!remote_call_current_success()) {
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesVerifyResultInconclusive;
    }
    if (!reacquired) {
        themer_iconservices_lab_release_reacquired(&r);
        printf("[ICONSERVICES_LAB] verify inconclusive "
               "reason=reacquire-failed stateRetained=1\n");
        r_settle_us(previousSettleUS);
        return ThemerSpotlightIconServicesVerifyResultInconclusive;
    }

    char storedIconCls[96] = {0};
    char freshIconCls[96] = {0};
    char storedCacheCls[96] = {0};
    char freshCacheCls[96] = {0};
    themer_read_class_name(s.canonicalIcon, storedIconCls,
                           sizeof(storedIconCls));
    themer_read_class_name(r.canonicalIcon, freshIconCls,
                           sizeof(freshIconCls));
    themer_read_class_name(s.canonicalCache, storedCacheCls,
                           sizeof(storedCacheCls));
    themer_read_class_name(r.canonicalCache, freshCacheCls,
                           sizeof(freshCacheCls));
    printf("[ICONSERVICES_LAB] verify reacquire pid=%d candidate=%s "
           "storedIcon=0x%llx/%s freshIcon=0x%llx/%s iconsSame=%d "
           "storedCache=0x%llx/%s freshCache=0x%llx/%s cachesSame=%d "
           "storedDescriptor=0x%llx freshDescriptor=0x%llx "
           "descriptorSource=%s literalName=%d "
           "reacquired=%d\n",
           currentPid,
           candidateName,
           (unsigned long long)s.canonicalIcon,
           storedIconCls[0] ? storedIconCls : "-",
           (unsigned long long)r.canonicalIcon,
           freshIconCls[0] ? freshIconCls : "-",
           s.canonicalIcon == r.canonicalIcon,
           (unsigned long long)s.canonicalCache,
           storedCacheCls[0] ? storedCacheCls : "-",
           (unsigned long long)r.canonicalCache,
           freshCacheCls[0] ? freshCacheCls : "-",
           s.canonicalCache == r.canonicalCache,
           (unsigned long long)s.descriptor,
           (unsigned long long)r.descriptor,
           s.descriptorSource[0] ? s.descriptorSource : "-",
           r.descriptorLiteralFallback,
           reacquired);

    // Persistent classification through the same route that was mutated.
    uint64_t readObj = 0;
    bool routeReadable = false;
    switch (s.candidate) {
        case ThemerSpotlightIconServicesCandidateLocalExistingDescriptor:
            readObj = r_is_objc_ptr(s.localIcon) ? s.localIcon
                                                 : r.freshLocal;
            break;
        case ThemerSpotlightIconServicesCandidateManagerCache:
            readObj = r_is_objc_ptr(r.managerCache)
                ? r.managerCache : s.managerCache;
            break;
        default:
            readObj = r_is_objc_ptr(r.canonicalIcon)
                ? r.canonicalIcon : s.canonicalIcon;
            break;
    }
    if (r_is_objc_ptr(readObj)) {
        routeReadable = r_responds_main(readObj, "imageForDescriptor:");
    }
    uint64_t readback = themer_iconservices_lab_read_image(readObj,
                                                           r.descriptor);
    bool primaryPayloadMatches = themer_spotlight_images_match(
        s.expectedImage, readback) && remote_call_current_success();
    bool verifyBagCandidate = s.candidate ==
            ThemerSpotlightIconServicesCandidateCanonicalBagSwap ||
        s.candidate ==
            ThemerSpotlightIconServicesCandidateCanonicalMixedBag;
    int bagEntryMatchCount = verifyBagCandidate ? 0 : 1;
    bool allBagEntriesMatch = !verifyBagCandidate;
    uint64_t payloadBagReadback = 0;
    if (verifyBagCandidate && s.bagEntryCount >= 1) {
        uint64_t bagCache = r_is_objc_ptr(r.canonicalCache)
            ? r.canonicalCache : s.canonicalCache;
        uint64_t bags = r_is_objc_ptr(bagCache) &&
            r_responds_main(bagCache, "imageBagsByDescriptor")
            ? r_msg2_main(bagCache, "imageBagsByDescriptor", 0, 0, 0, 0)
            : 0;
        uint64_t digest = r_is_objc_ptr(r.descriptor) &&
            r_responds_main(r.descriptor, "digest")
            ? r_msg2_main(r.descriptor, "digest", 0, 0, 0, 0)
            : 0;
        payloadBagReadback = r_is_objc_ptr(bags) &&
            r_is_objc_ptr(digest) &&
            r_responds_main(bags, "objectForKey:")
            ? r_msg2_main(bags, "objectForKey:", digest, 0, 0, 0)
            : 0;
        if (!r_is_objc_ptr(payloadBagReadback) &&
            r_is_objc_ptr(bags) && r_is_objc_ptr(s.descriptor) &&
            r_responds_main(bags, "objectForKey:")) {
            payloadBagReadback = r_msg2_main(
                bags, "objectForKey:", s.descriptor, 0, 0, 0);
        }
        for (int i = 0;
             i < s.bagEntryCount && remote_call_current_success(); i++) {
            uint64_t routed = themer_iconservices_lab_image_for_size_scale(
                payloadBagReadback,
                s.bagEntryWidths[i],
                s.bagEntryHeights[i],
                s.bagEntryScales[i]);
            bool hit = themer_spotlight_images_match(
                s.expectedImages[i], routed);
            if (hit) bagEntryMatchCount++;
            printf("[ICONSERVICES_LAB] verify payload-entry index=%d/%d "
                   "expected=0x%llx routed=0x%llx hit=%d "
                   "size=%.1fx%.1f@%.2f primary=%d\n",
                   i,
                   s.bagEntryCount,
                   (unsigned long long)s.expectedImages[i],
                   (unsigned long long)routed,
                   hit,
                   s.bagEntryWidths[i],
                   s.bagEntryHeights[i],
                   s.bagEntryScales[i],
                   i == s.bagPrimaryIndex);
        }
        allBagEntriesMatch = bagEntryMatchCount == s.bagEntryCount &&
            remote_call_current_success();
    }
    bool themed = primaryPayloadMatches && allBagEntriesMatch;
    bool stock = themer_spotlight_images_match(s.stockTargetImage, readback) &&
                 remote_call_current_success();

    bool controlChecked = false;
    bool controlStillStock = true;
    bool controlMatchesThemed = false;
    bool controlIdentityChanged = false;
    uint64_t controlReadback = 0;
    if (s.controlBundle[0]) {
        uint64_t controlLocal = themer_iconservices_lab_make_bundle_icon(
            s.controlBundle);
        uint64_t controlCanonical = 0;
        if (r_is_objc_ptr(controlLocal) && remote_call_current_success()) {
            uint64_t mgrCls = themer_lookup_class("ISIconManager");
            uint64_t manager = r_is_objc_ptr(mgrCls) &&
                               r_responds_main(mgrCls, "sharedInstance")
                ? r_msg2_main(mgrCls, "sharedInstance", 0, 0, 0, 0) : 0;
            if (r_is_objc_ptr(manager) &&
                r_responds_main(manager, "findOrRegisterIcon:")) {
                controlCanonical = r_msg2_main(manager, "findOrRegisterIcon:",
                                               controlLocal, 0, 0, 0);
            }
        }
        if (r_is_objc_ptr(controlLocal) && remote_call_current_success()) {
            r_msg2(controlLocal, "release", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(controlCanonical)) {
            controlReadback = themer_iconservices_lab_read_image(
                controlCanonical, r.descriptor);
            controlChecked = r_is_objc_ptr(s.stockControlImage) &&
                             r_is_objc_ptr(controlReadback);
            if (r_is_objc_ptr(s.stockControlImage)) {
                controlStillStock = themer_spotlight_images_match(
                    s.stockControlImage, controlReadback) &&
                    remote_call_current_success();
            }
            if (r_is_objc_ptr(controlReadback)) {
                for (int i = 0;
                     i < s.bagEntryCount && remote_call_current_success(); i++) {
                    bool themedEntry = s.candidate !=
                            ThemerSpotlightIconServicesCandidateCanonicalMixedBag ||
                        themer_iconservices_lab_sizes_match(
                            s.bagEntryWidths[i], s.bagEntryHeights[i],
                            68.0, 68.0);
                    if (themedEntry && r_is_objc_ptr(s.expectedImages[i]) &&
                        themer_spotlight_images_match(
                            s.expectedImages[i], controlReadback)) {
                        controlMatchesThemed = true;
                        break;
                    }
                }
            }
            controlIdentityChanged = controlChecked &&
                !controlStillStock && !controlMatchesThemed;
        }
    }

    ThemerSpotlightIconServicesVerifyResult verdict;
    if (s.controlBundle[0] && !controlChecked) {
        printf("[ICONSERVICES_LAB] verify control-unreadable candidate=%s "
               "controlReadback=0x%llx\n",
               candidateName,
               (unsigned long long)controlReadback);
        verdict = ThemerSpotlightIconServicesVerifyResultInconclusive;
    } else if (controlMatchesThemed) {
        printf("[ICONSERVICES_LAB] verify control-themed candidate=%s "
               "controlReadback=0x%llx evidence=target-image-match\n",
               candidateName,
               (unsigned long long)controlReadback);
        verdict = ThemerSpotlightIconServicesVerifyResultInconclusive;
    } else if (themed && controlChecked && controlStillStock) {
        verdict = ThemerSpotlightIconServicesVerifyResultPersistentHit;
    } else if (themed && controlIdentityChanged) {
        printf("[ICONSERVICES_LAB] verify control-identity-changed "
               "candidate=%s controlReadback=0x%llx "
               "evidence=no-target-image-match visual-check-required=1\n",
               candidateName,
               (unsigned long long)controlReadback);
        verdict = ThemerSpotlightIconServicesVerifyResultInconclusive;
    } else if (routeReadable) {
        // Not the seeded image: either the stock image or a miss.
        verdict = ThemerSpotlightIconServicesVerifyResultStockOrMiss;
    } else {
        verdict = ThemerSpotlightIconServicesVerifyResultInconclusive;
    }

    uint64_t restoreReadback = 0;
    bool restored = themer_iconservices_lab_restore_candidate(&s, &r,
                                                              &restoreReadback);
    bool stateCleared = false;
    if (restored) {
        themer_iconservices_lab_clear_state();
        themer_iconservices_lab_trace_clear();
        stateCleared = !r_is_objc_ptr(themer_iconservices_lab_state()) &&
            !r_is_objc_ptr(themer_iconservices_lab_trace_state());
    }
    themer_iconservices_lab_release_reacquired(&r);
    printf("[ICONSERVICES_LAB] verify verdict=%d pid=%d candidate=%s "
           "descriptorSource=%s selector=%s readback=0x%llx payloadMatches=%d "
           "primaryPayload=%d bagEntries=%d/%d bag=0x%llx "
           "stockIdentity=%d controlChecked=%d controlStillStock=%d "
           "controlMatchesPayload=%d controlIdentityChanged=%d "
           "controlReadback=0x%llx restore=0x%llx restoreVerified=%d "
           "stateCleared=%d total=%llums ioFailures=%llu\n",
           verdict,
           currentPid,
           candidateName,
           s.descriptorSource[0] ? s.descriptorSource : "-",
           s.selectorUsed[0] ? s.selectorUsed : "-",
           (unsigned long long)readback,
           themed,
           primaryPayloadMatches,
           bagEntryMatchCount,
           s.bagEntryCount,
           (unsigned long long)payloadBagReadback,
           stock,
           controlChecked,
           controlStillStock,
           controlMatchesThemed,
           controlIdentityChanged,
           (unsigned long long)controlReadback,
           (unsigned long long)restoreReadback,
           restored,
           stateCleared,
           (unsigned long long)((themer_now_us() - startUS) / 1000ULL),
           (unsigned long long)remote_call_current_io_failure_count());
    r_settle_us(previousSettleUS);
    if (!restored || !stateCleared) {
        return ThemerSpotlightIconServicesVerifyResultCleanupFailed;
    }
    return verdict;
}

bool themer_spotlight_iconservices_emergency_restore_in_session(void)
{
    uint64_t startUS = themer_now_us();
    uint32_t previousSettleUS = r_settle_us(1000);
    if (!remote_call_current_success()) {
        printf("[ICONSERVICES_LAB] emergency aborted reason=transport-down\n");
        r_settle_us(previousSettleUS);
        return false;
    }
    uint64_t state = themer_iconservices_lab_state();
    if (!r_is_objc_ptr(state)) {
        // Existing-cache-file route: restore the backup even with no retained
        // state. This is a pure local overwrite and is idempotent when the
        // recovery keys are absent.
        bool cacheFilePresent = [[NSUserDefaults.standardUserDefaults
            stringForKey:THEMER_ICONSERVICES_LAB_PENDING_CACHE_TARGET_KEY]
                length] > 0;
        bool cacheFileRestored = cacheFilePresent
            ? themer_iconservices_lab_restore_pending_cache_file()
            : true;
        bool pendingPresent = [[NSUserDefaults.standardUserDefaults
            stringForKey:THEMER_ICONSERVICES_LAB_PENDING_STORE_UUID_KEY]
                length] > 0;
        bool pendingRemoved = !pendingPresent;
        if (pendingPresent && themer_ensure_iconservices_loaded()) {
            uint64_t mgrCls = themer_lookup_class("ISIconManager");
            uint64_t manager = r_is_objc_ptr(mgrCls) &&
                r_responds_main(mgrCls, "sharedInstance")
                ? r_msg2_main(mgrCls, "sharedInstance", 0, 0, 0, 0) : 0;
            uint64_t managerCache = r_is_objc_ptr(manager) &&
                r_responds_main(manager, "iconCache")
                ? r_msg2_main(manager, "iconCache", 0, 0, 0, 0) : 0;
            pendingRemoved = r_is_objc_ptr(managerCache) &&
                themer_iconservices_lab_remove_pending_store_unit(
                    managerCache);
        }
        bool tracePresent = r_is_objc_ptr(
            themer_iconservices_lab_trace_state());
        if (tracePresent) themer_iconservices_lab_trace_clear();
        bool traceCleared = !r_is_objc_ptr(
            themer_iconservices_lab_trace_state());
        printf("[ICONSERVICES_LAB] emergency no-state "
               "cacheFilePresent=%d cacheFileRestored=%d "
               "pendingPresent=%d pendingRemoved=%d tracePresent=%d "
               "traceCleared=%d\n",
               cacheFilePresent,
               cacheFileRestored,
               pendingPresent,
               pendingRemoved,
               tracePresent,
               traceCleared);
        r_settle_us(previousSettleUS);
        return cacheFileRestored && pendingRemoved && traceCleared &&
            (cacheFilePresent || pendingPresent || tracePresent);
    }

    uint64_t statePid = 0;
    bool pidKnown = themer_spotlight_proof_state_u64(state, "pid", &statePid);
    int currentPid = remote_call_current_pid();
    if (!pidKnown || statePid != (uint64_t)currentPid) {
        // The retained mutation objects belong to a different process
        // incarnation and remain untouched. The observation-only trace is safe
        // to discard because it cannot apply to this host incarnation.
        themer_iconservices_lab_trace_clear();
        printf("[ICONSERVICES_LAB] emergency host-mismatch statePid=%llu "
               "currentPid=%d stateRetained=1 traceCleared=%d\n",
               (unsigned long long)statePid,
               currentPid,
               !r_is_objc_ptr(themer_iconservices_lab_trace_state()));
        r_settle_us(previousSettleUS);
        return false;
    }

    ThemerIconServicesLabStored s = {0};
    if (!themer_iconservices_lab_state_load(state, &s)) {
        uint64_t candidate = 0;
        uint64_t storeUnitAdded = 0;
        uint64_t canonicalCache = themer_spotlight_dictionary_object(
            state, "canonicalCache");
        uint64_t managerCache = themer_spotlight_dictionary_object(
            state, "managerCache");
        uint64_t originalBags = themer_spotlight_dictionary_object(
            state, "originalBags");
        uint64_t themedStoreUUID = themer_spotlight_dictionary_object(
            state, "themedStoreUUID");
        bool minimalKnown = themer_spotlight_proof_state_u64(
                state, "candidate", &candidate) &&
            candidate == (uint64_t)
                ThemerSpotlightIconServicesCandidateCanonicalMixedBag &&
            themer_spotlight_proof_state_u64(
                state, "storeUnitAdded", &storeUnitAdded) &&
            r_is_objc_ptr(canonicalCache) &&
            r_is_objc_ptr(managerCache) && r_is_objc_ptr(originalBags) &&
            r_responds_main(canonicalCache, "setImageBagsByDescriptor:") &&
            (storeUnitAdded == 0 || r_is_objc_ptr(themedStoreUUID));
        bool dictionaryRestored = false;
        bool storeRemoved = false;
        if (minimalKnown) {
            int originalCount = (int)themer_remote_count(originalBags);
            r_msg2_main(canonicalCache, "setImageBagsByDescriptor:",
                        originalBags, 0, 0, 0);
            dictionaryRestored = remote_call_current_success() &&
                themer_iconservices_lab_dictionary_restored(
                    canonicalCache, originalBags, originalCount);
            if (storeUnitAdded != 0 && dictionaryRestored) {
                storeRemoved = themer_iconservices_lab_remove_store_unit(
                    managerCache, themedStoreUUID);
                if (storeRemoved) {
                    themer_iconservices_lab_clear_pending_store_uuid();
                }
            } else if (dictionaryRestored) {
                storeRemoved =
                    themer_iconservices_lab_restore_pending_cache_file();
            }
        }
        bool stateCleared = false;
        if (dictionaryRestored && storeRemoved) {
            themer_iconservices_lab_clear_state();
            themer_iconservices_lab_trace_clear();
            stateCleared = !r_is_objc_ptr(
                themer_iconservices_lab_state());
        }
        printf("[ICONSERVICES_LAB] emergency prearmed-recovery "
               "known=%d dictionary=%d uuid=0x%llx storeRemoved=%d "
               "route=%s stateCleared=%d\n",
               minimalKnown,
               dictionaryRestored,
               (unsigned long long)themedStoreUUID,
               storeRemoved,
               storeUnitAdded != 0 ? "store-unit" : "existing-cache-file",
               stateCleared);
        r_settle_us(previousSettleUS);
        return dictionaryRestored && storeRemoved && stateCleared;
    }
    if (s.candidate < 0 ||
        s.candidate >= ThemerSpotlightIconServicesCandidateCount) {
        printf("[ICONSERVICES_LAB] emergency stopped "
               "reason=unknown-stored-candidate candidate=%d "
               "stateRetained=1\n",
               s.candidate);
        r_settle_us(previousSettleUS);
        return false;
    }
    const char *candidateName =
        themer_spotlight_iconservices_candidate_name(
            (ThemerSpotlightIconServicesCandidate)s.candidate);
    ThemerIconServicesLabReacquired r = {0};
    bool reacquired = themer_iconservices_lab_reacquire(&s, &r);
    if (!remote_call_current_success() || !reacquired) {
        if (remote_call_current_success()) {
            themer_iconservices_lab_release_reacquired(&r);
        }
        printf("[ICONSERVICES_LAB] emergency stopped "
               "reason=reacquire-failed stateRetained=1\n");
        r_settle_us(previousSettleUS);
        return false;
    }
    uint64_t restoreReadback = 0;
    bool restored = themer_iconservices_lab_restore_candidate(&s, &r,
                                                              &restoreReadback);
    bool stateCleared = false;
    if (restored) {
        themer_iconservices_lab_clear_state();
        themer_iconservices_lab_trace_clear();
        stateCleared = !r_is_objc_ptr(themer_iconservices_lab_state()) &&
            !r_is_objc_ptr(themer_iconservices_lab_trace_state());
    }
    themer_iconservices_lab_release_reacquired(&r);
    printf("[ICONSERVICES_LAB] emergency pid=%d candidate=%s "
           "restoreReadback=0x%llx restored=%d stateCleared=%d "
           "total=%llums\n",
           currentPid,
           candidateName,
           (unsigned long long)restoreReadback,
           restored,
           stateCleared,
           (unsigned long long)((themer_now_us() - startUS) / 1000ULL));
    r_settle_us(previousSettleUS);
    return restored && stateCleared;
}

#pragma mark - VM visible indexed-response inspection

static void themer_indexed_response_copy_text(char *destination,
                                               size_t destinationLength,
                                               const char *source)
{
    if (!destination || destinationLength == 0) return;
    snprintf(destination, destinationLength, "%s", source ?: "");
}

static bool themer_indexed_response_capture_visible_row(
    const char *targetBundle,
    uint64_t *viewOut,
    uint64_t *consumerIconOut,
    uint64_t *displayedImageOut,
    int *visibleTargetCountOut,
    char rowSource[160])
{
    if (viewOut) *viewOut = 0;
    if (consumerIconOut) *consumerIconOut = 0;
    if (displayedImageOut) *displayedImageOut = 0;
    if (visibleTargetCountOut) *visibleTargetCountOut = 0;
    if (rowSource) rowSource[0] = '\0';
    if (!targetBundle || !targetBundle[0] ||
        !remote_call_current_success()) return false;

    enum { VIEW_CAP = 64 };
    uint64_t views[VIEW_CAP] = {0};
    printf("[ICONINDEX] visible-row scan begin cap=%d\n", VIEW_CAP);
    int viewCount = themer_spotlight_collect_searchui_views_fast(
        views, VIEW_CAP);
    printf("[ICONINDEX] visible-row scan collected=%d transport=%d\n",
           viewCount, remote_call_current_success());
    int visibleTargetCount = 0;
    uint64_t selectedView = 0;
    uint64_t selectedIcon = 0;
    uint64_t selectedImage = 0;
    char selectedSource[160] = {0};
    for (int i = 0; i < viewCount && remote_call_current_success(); i++) {
        char iconSource[96] = {0};
        uint64_t icon = themer_spotlight_app_icon_for_view(
            views[i], iconSource, sizeof(iconSource));
        if (!r_is_objc_ptr(icon)) continue;
        char bundle[192] = {0};
        char bundleSource[96] = {0};
        if (!themer_spotlight_bundle_for_view(
                views[i], icon, bundle, sizeof(bundle),
                bundleSource, sizeof(bundleSource), NULL) ||
            strcmp(bundle, targetBundle) != 0) {
            continue;
        }
        int hidden = themer_remote_hidden(views[i]);
        double alpha = themer_remote_alpha(views[i]);
        if (hidden == 1 || (alpha >= 0.0 && alpha < 0.01)) continue;
        visibleTargetCount++;
        uint64_t carrier = 0;
        char imageSource[96] = {0};
        uint64_t image = themer_spotlight_image_from_view(
            views[i], &carrier, imageSource, sizeof(imageSource));
        printf("[ICONINDEX] visible-row candidate=%d/%d view=0x%llx "
               "icon=0x%llx image=0x%llx hidden=%d alpha=%.3f "
               "iconSource=%s bundleSource=%s imageSource=%s\n",
               visibleTargetCount, viewCount,
               (unsigned long long)views[i],
               (unsigned long long)icon,
               (unsigned long long)image,
               hidden, alpha,
               iconSource[0] ? iconSource : "-",
               bundleSource[0] ? bundleSource : "-",
               imageSource[0] ? imageSource : "-");
        if (!selectedView && r_is_objc_ptr(image)) {
            selectedView = views[i];
            selectedIcon = icon;
            selectedImage = image;
            snprintf(selectedSource, sizeof(selectedSource),
                     "%s | %s | %s",
                     iconSource[0] ? iconSource : "-",
                     bundleSource[0] ? bundleSource : "-",
                     imageSource[0] ? imageSource : "-");
        }
    }
    if (visibleTargetCountOut) *visibleTargetCountOut = visibleTargetCount;
    if (visibleTargetCount != 1 || !r_is_objc_ptr(selectedView) ||
        !r_is_objc_ptr(selectedIcon) || !r_is_objc_ptr(selectedImage)) {
        return false;
    }
    if (viewOut) *viewOut = selectedView;
    if (consumerIconOut) *consumerIconOut = selectedIcon;
    if (displayedImageOut) *displayedImageOut = selectedImage;
    if (rowSource) {
        themer_indexed_response_copy_text(
            rowSource, 160, selectedSource);
    }
    return remote_call_current_success();
}

ThemerSpotlightIndexedResponseResult
themer_spotlight_identify_visible_indexed_response_in_session(
    const char *targetBundle,
    ThemerSpotlightIndexedResponseReport *reportOut)
{
    ThemerSpotlightIndexedResponseReport report = {0};
    report.result = ThemerSpotlightIndexedResponseUnsupportedABI;
    report.noMutation = true;
    themer_indexed_response_copy_text(
        report.targetBundle, sizeof(report.targetBundle), targetBundle);

    uint64_t view = 0;
    uint64_t consumerIcon = 0;
    uint64_t displayedImage = 0;
    uint64_t iconServicesIcon = 0;
    uint64_t imageCache = 0;
    uint64_t managerStore = 0;
    uint64_t selectedImage = 0;
    ThemerIconServicesLabDataCapture visiblePixels = {0};
    ThemerAgentCGMetadata visibleMetadata = {0};

    printf("[ICONINDEX] begin pid=%d target=%s readOnly=1 "
           "descriptorRequests=0 generation=0 setters=0 storeWrites=0 "
           "fileWrites=0 recoveryAccess=0\n",
           remote_call_current_pid(), targetBundle ?: "-");

    // The lab mailbox is synchronous and its injected payload serializes all
    // calls.  Per-call physical-device settling only turns a read-only view
    // walk into a multi-minute operation here; restore the caller's policy
    // before returning so other RemoteCall modes remain unchanged.
    bool labFastPath = remote_call_uses_lab_backend();
    uint32_t previousSettleUS = labFastPath ? r_settle_us(0) : 0;

    do {
    if (!targetBundle || !targetBundle[0] ||
        !remote_call_current_success() || !themer_ensure_iconservices_loaded()) {
        report.result = remote_call_current_success()
            ? ThemerSpotlightIndexedResponseUnsupportedABI
            : ThemerSpotlightIndexedResponseTransportFailed;
        snprintf(report.reason, sizeof(report.reason),
                 "invalid-input-or-iconservices-unavailable");
        break;
    }
    printf("[ICONINDEX] IconServices classes ready; locating visible row\n");

    bool rowCaptured = themer_indexed_response_capture_visible_row(
        targetBundle, &view, &consumerIcon, &displayedImage,
        &report.visibleTargetRowCount, report.rowSource);
    report.visibleRowFound = rowCaptured;
    if (!rowCaptured) {
        report.result = ThemerSpotlightIndexedResponseNoVisibleRow;
        snprintf(report.reason, sizeof(report.reason),
                 report.visibleTargetRowCount > 1
                    ? "visible-target-row-ambiguous"
                    : report.visibleTargetRowCount == 1
                    ? "visible-target-row-image-unavailable"
                    : "one-visible-target-row-not-found");
        break;
    }
    themer_read_class_name(view, report.rowClass, sizeof(report.rowClass));
    report.consumerIconFound = r_is_objc_ptr(consumerIcon);
    themer_read_class_name(consumerIcon, report.consumerIconClass,
                           sizeof(report.consumerIconClass));
    if (!report.consumerIconFound) {
        report.result = ThemerSpotlightIndexedResponseNoConsumerIcon;
        snprintf(report.reason, sizeof(report.reason),
                 "visible-row-consumer-icon-missing");
        break;
    }

    char consumerGetterTypes[192] = {0};
    bool consumerGetterABI =
        r_responds_main(consumerIcon, "iconServicesIconForImage") &&
        themer_iconservices_lab_method_types(
            consumerIcon, "iconServicesIconForImage",
            consumerGetterTypes, sizeof(consumerGetterTypes)) &&
        !strcmp(consumerGetterTypes, "@16@0:8");
    if (!consumerGetterABI) {
        report.result = ThemerSpotlightIndexedResponseUnsupportedABI;
        snprintf(report.reason, sizeof(report.reason),
                 "consumer-iconservicesiconforimage-abi");
        printf("[ICONINDEX] consumer-getter class=%s types=\"%s\" "
               "accepted=0\n",
               report.consumerIconClass[0]
                   ? report.consumerIconClass : "-",
               consumerGetterTypes[0] ? consumerGetterTypes : "-");
        break;
    }
    iconServicesIcon = r_msg2_main(
        consumerIcon, "iconServicesIconForImage", 0, 0, 0, 0);
    report.iconServicesIconFound = r_is_objc_ptr(iconServicesIcon);
    themer_read_class_name(iconServicesIcon, report.iconServicesIconClass,
                           sizeof(report.iconServicesIconClass));
    if (!report.iconServicesIconFound) {
        report.result = ThemerSpotlightIndexedResponseNoConsumerIcon;
        snprintf(report.reason, sizeof(report.reason),
                 "consumer-iconservices-icon-missing");
        break;
    }

    char cacheGetterTypes[192] = {0};
    bool cacheGetterABI =
        r_responds_main(iconServicesIcon, "imageCache") &&
        themer_iconservices_lab_method_types(
            iconServicesIcon, "imageCache",
            cacheGetterTypes, sizeof(cacheGetterTypes)) &&
        !strcmp(cacheGetterTypes, "@16@0:8");
    imageCache = cacheGetterABI
        ? r_msg2_main(iconServicesIcon, "imageCache", 0, 0, 0, 0) : 0;
    report.existingCacheFound = r_is_objc_ptr(imageCache);
    themer_read_class_name(imageCache, report.cacheClass,
                           sizeof(report.cacheClass));
    if (!cacheGetterABI || !report.existingCacheFound ||
        !r_responds_main(imageCache, "imageBagsByDescriptor")) {
        report.result = ThemerSpotlightIndexedResponseNoExistingCache;
        snprintf(report.reason, sizeof(report.reason),
                 "consumer-existing-image-cache-unavailable");
        break;
    }

    report.visiblePixelsCaptured = themer_agent_capture_image_pixels(
        displayedImage, &visiblePixels, &visibleMetadata,
        report.visiblePixelSHA256);
    double visibleW = 0.0, visibleH = 0.0, visibleScale = 0.0;
    bool visibleGeometry = themer_read_image_geometry(
        displayedImage, &visibleW, &visibleH, &visibleScale);
    if (visibleGeometry) {
        report.visiblePointWidth = visibleW;
        report.visiblePointHeight = visibleH;
        report.visibleScale = visibleScale;
    }
    report.visiblePixelWidth = visibleMetadata.width;
    report.visiblePixelHeight = visibleMetadata.height;

    uint64_t managerClass = themer_lookup_class("ISIconManager");
    uint64_t manager = r_is_objc_ptr(managerClass) &&
            r_responds_main(managerClass, "sharedInstance")
        ? r_msg2_main(managerClass, "sharedInstance", 0, 0, 0, 0) : 0;
    uint64_t managerCache = r_is_objc_ptr(manager) &&
            r_responds_main(manager, "iconCache")
        ? r_msg2_main(manager, "iconCache", 0, 0, 0, 0) : 0;
    uint64_t cachePathObject = r_is_objc_ptr(managerCache) &&
            r_responds_main(managerCache, "cachePath")
        ? r_msg2_main(managerCache, "cachePath", 0, 0, 0, 0) : 0;
    char cachePathText[512] = {0};
    bool cachePathKnown = r_is_objc_ptr(cachePathObject) &&
        r_read_nsstring(cachePathObject, cachePathText,
                        sizeof(cachePathText));
    managerStore = r_is_objc_ptr(managerCache)
        ? themer_iconservices_lab_retained_store(managerCache) : 0;
    char storeLookupTypes[192] = {0};
    bool storeLookupABI = r_is_objc_ptr(managerStore) &&
        r_responds_main(managerStore, "unitForUUID:") &&
        themer_iconservices_lab_method_types(
            managerStore, "unitForUUID:",
            storeLookupTypes, sizeof(storeLookupTypes)) &&
        !strcmp(storeLookupTypes, "@24@0:8@16");
    printf("[ICONINDEX] consumer view=0x%llx/%s icon=0x%llx/%s "
           "isIcon=0x%llx/%s cache=0x%llx/%s visible=0x%llx "
           "points=%.1fx%.1f@%.2f pixels=%llux%llu/%s "
           "store=0x%llx lookupABI=%d/%s cachePath=\"%s\"\n",
           (unsigned long long)view,
           report.rowClass[0] ? report.rowClass : "-",
           (unsigned long long)consumerIcon,
           report.consumerIconClass[0] ? report.consumerIconClass : "-",
           (unsigned long long)iconServicesIcon,
           report.iconServicesIconClass[0]
               ? report.iconServicesIconClass : "-",
           (unsigned long long)imageCache,
           report.cacheClass[0] ? report.cacheClass : "-",
           (unsigned long long)displayedImage,
           report.visiblePointWidth, report.visiblePointHeight,
           report.visibleScale,
           (unsigned long long)report.visiblePixelWidth,
           (unsigned long long)report.visiblePixelHeight,
           report.visiblePixelSHA256[0]
               ? report.visiblePixelSHA256 : "-",
           (unsigned long long)managerStore,
           storeLookupABI,
           storeLookupTypes[0] ? storeLookupTypes : "-",
           cachePathKnown ? cachePathText : "-");
    if (!report.visiblePixelsCaptured || !cachePathKnown ||
        !storeLookupABI) {
        report.result = ThemerSpotlightIndexedResponseUnsupportedABI;
        snprintf(report.reason, sizeof(report.reason),
                 !report.visiblePixelsCaptured
                    ? "visible-row-pixels-unavailable"
                    : !cachePathKnown
                        ? "manager-cache-path-unavailable"
                        : "store-unit-lookup-abi");
        break;
    }

    uint64_t bags = r_msg2_main(
        imageCache, "imageBagsByDescriptor", 0, 0, 0, 0);
    uint64_t keys = r_is_objc_ptr(bags) &&
            r_responds_main(bags, "allKeys")
        ? r_msg2_main(bags, "allKeys", 0, 0, 0, 0) : 0;
    int keyCount = r_is_objc_ptr(keys)
        ? (int)themer_remote_count(keys) : 0;
    report.descriptorKeyCount = keyCount;
    enum { KEY_CAP = 32, IMAGE_CAP = 32 };
    if (!r_is_objc_ptr(bags) || !r_is_objc_ptr(keys) ||
        !r_responds_main(bags, "objectForKey:") ||
        keyCount <= 0 || keyCount > KEY_CAP) {
        report.result = keyCount > KEY_CAP
            ? ThemerSpotlightIndexedResponseAmbiguous
            : ThemerSpotlightIndexedResponseNoExistingCache;
        snprintf(report.reason, sizeof(report.reason),
                 keyCount > KEY_CAP
                    ? "descriptor-key-count-unbounded"
                    : "existing-cache-bags-empty");
        break;
    }

    char selectedUUID[80] = {0};
    for (int keyIndex = 0;
         keyIndex < keyCount && remote_call_current_success(); keyIndex++) {
        uint64_t key = r_msg2_main(
            keys, "objectAtIndex:", (uint64_t)keyIndex, 0, 0, 0);
        uint64_t bag = r_msg2_main(
            bags, "objectForKey:", key, 0, 0, 0);
        uint64_t images = r_is_objc_ptr(bag) &&
                r_responds_main(bag, "images")
            ? r_msg2_main(bag, "images", 0, 0, 0, 0) : 0;
        int imageCount = r_is_objc_ptr(images)
            ? (int)themer_remote_count(images) : 0;
        char keyClass[96] = {0};
        char keyText[256] = {0};
        themer_read_class_name(key, keyClass, sizeof(keyClass));
        themer_read_remote_description(key, keyText, sizeof(keyText));
        printf("[ICONINDEX] descriptor-key index=%d/%d key=0x%llx/%s "
               "bag=0x%llx images=%d text=\"%s\"\n",
               keyIndex, keyCount, (unsigned long long)key,
               keyClass[0] ? keyClass : "-",
               (unsigned long long)bag, imageCount,
               keyText[0] ? keyText : "-");
        if (imageCount < 0 || imageCount > IMAGE_CAP ||
            !r_responds_main(images, "objectAtIndex:")) {
            report.result = ThemerSpotlightIndexedResponseAmbiguous;
            snprintf(report.reason, sizeof(report.reason),
                     "descriptor-image-count-unbounded");
            break;
        }

        for (int imageIndex = 0;
             imageIndex < imageCount && remote_call_current_success();
             imageIndex++) {
            uint64_t image = r_msg2_main(
                images, "objectAtIndex:", (uint64_t)imageIndex, 0, 0, 0);
            char imageClass[96] = {0};
            themer_read_class_name(image, imageClass, sizeof(imageClass));
            if (strcmp(imageClass, "IFCacheImage") != 0) {
                printf("[ICONINDEX] response key=%d image=%d "
                       "object=0x%llx class=%s indexedCandidate=0\n",
                       keyIndex, imageIndex,
                       (unsigned long long)image,
                       imageClass[0] ? imageClass : "-");
                continue;
            }
            report.cacheImageCount++;

            double responseW = 0.0, responseH = 0.0, responseScale = 0.0;
            bool responseGeometry =
                themer_iconservices_lab_read_image_geometry(
                    image, &responseW, &responseH, &responseScale);
            ThemerIconServicesLabDataCapture responsePixels = {0};
            ThemerAgentCGMetadata responseMetadata = {0};
            char responsePixelHash[65] = {0};
            bool responsePixelsCaptured = themer_agent_capture_image_pixels(
                image, &responsePixels, &responseMetadata,
                responsePixelHash);
            bool pixelMatch = responsePixelsCaptured &&
                report.visiblePixelSHA256[0] && responsePixelHash[0] &&
                !strcmp(report.visiblePixelSHA256, responsePixelHash) &&
                visibleMetadata.width == responseMetadata.width &&
                visibleMetadata.height == responseMetadata.height;

            uint64_t uuid = themer_iconservices_lab_retained_getter(
                image, "uuid");
            uint64_t token = themer_iconservices_lab_retained_getter(
                image, "validationToken");
            uint64_t uuidString = r_is_objc_ptr(uuid)
                ? themer_iconservices_lab_retained_getter(uuid, "UUIDString")
                : 0;
            char uuidText[80] = {0};
            bool uuidKnown = r_is_objc_ptr(uuidString) &&
                r_read_nsstring(uuidString, uuidText, sizeof(uuidText));

            ThemerIconServicesLabDataCapture tokenCapture = {0};
            char tokenHash[65] = {0};
            bool tokenCaptured = r_is_objc_ptr(token) &&
                themer_iconservices_lab_capture_nsdata(
                    token, THEMER_ICONSERVICES_LAB_TOKEN_CAPTURE_CAP,
                    &tokenCapture) && !tokenCapture.truncated;
            if (tokenCaptured) {
                themer_agent_capture_sha256(&tokenCapture, tokenHash);
            }

            uint64_t unit = uuidKnown
                ? r_msg2_main(managerStore, "unitForUUID:",
                              uuid, 0, 0, 0)
                : 0;
            bool indexMatch = r_is_objc_ptr(unit);
            NSString *cacheDirectory = cachePathKnown
                ? [NSString stringWithUTF8String:cachePathText] : nil;
            NSString *fileName = uuidKnown
                ? [NSString stringWithFormat:@"%s.isdata", uuidText] : nil;
            NSString *filePath = fileName.length > 0
                ? [cacheDirectory stringByAppendingPathComponent:fileName]
                : nil;
            NSString *standardCache = cacheDirectory.stringByStandardizingPath;
            NSString *standardFile = filePath.stringByStandardizingPath;
            NSString *cachePrefix = standardCache.length > 0
                ? [standardCache stringByAppendingString:@"/"] : nil;
            struct stat fileStat = {0};
            bool fileShape = standardFile.length > 0 &&
                [standardFile hasPrefix:cachePrefix] &&
                lstat(standardFile.fileSystemRepresentation, &fileStat) == 0 &&
                S_ISREG(fileStat.st_mode) && !S_ISLNK(fileStat.st_mode) &&
                fileStat.st_size > 0 && fileStat.st_size <= (16LL << 20);
            NSData *fileData = fileShape
                ? [NSData dataWithContentsOfFile:standardFile
                                         options:NSDataReadingMappedIfSafe
                                           error:NULL]
                : nil;
            NSString *fileHash = fileData
                ? themer_stock68_registration_hash(fileData) : nil;

            uint64_t unitData = indexMatch &&
                    r_responds_main(unit, "data")
                ? r_msg2_main(unit, "data", 0, 0, 0, 0) : 0;
            ThemerIconServicesLabDataCapture unitCapture = {0};
            bool unitCaptured = r_is_objc_ptr(unitData) &&
                themer_iconservices_lab_capture_nsdata(
                    unitData, THEMER_ICONSERVICES_LAB_STOCK_COMPARE_DATA_CAP,
                    &unitCapture) && !unitCapture.truncated;
            bool unitMatchesFile = unitCaptured && fileData &&
                unitCapture.objectLength == fileData.length &&
                unitCapture.capturedLength == fileData.length &&
                (fileData.length == 0 ||
                 !memcmp(unitCapture.bytes, fileData.bytes, fileData.length));
            bool indexed = indexMatch && fileShape && fileData.length > 0 &&
                unitMatchesFile;
            if (indexed) report.indexedCandidateCount++;

            printf("[ICONINDEX] response key=%d image=%d object=0x%llx/%s "
                   "geometry=%d/%.1fx%.1f@%.2f "
                   "pixels=%llux%llu/%s visibleMatch=%d "
                   "uuid=%s token=%s unit=0x%llx index=%d "
                   "path=\"%s\" file=%d/%lld/%s unitFileMatch=%d "
                   "indexedCandidate=%d\n",
                   keyIndex, imageIndex,
                   (unsigned long long)image,
                   imageClass,
                   responseGeometry, responseW, responseH, responseScale,
                   (unsigned long long)responseMetadata.width,
                   (unsigned long long)responseMetadata.height,
                   responsePixelHash[0] ? responsePixelHash : "-",
                   pixelMatch,
                   uuidKnown ? uuidText : "-",
                   tokenHash[0] ? tokenHash : "-",
                   (unsigned long long)unit,
                   indexMatch,
                   standardFile.UTF8String ?: "-",
                   fileShape,
                   fileShape ? (long long)fileStat.st_size : -1LL,
                   fileHash.UTF8String ?: "-",
                   unitMatchesFile,
                   indexed);

            if (pixelMatch && indexed &&
                (!selectedUUID[0] || strcmp(selectedUUID, uuidText) != 0)) {
                report.exactPixelMatchCount++;
                if (report.exactPixelMatchCount == 1) {
                    selectedImage = image;
                    themer_indexed_response_copy_text(
                        selectedUUID, sizeof(selectedUUID), uuidText);
                    themer_indexed_response_copy_text(
                        report.descriptorKeyClass,
                        sizeof(report.descriptorKeyClass), keyClass);
                    themer_indexed_response_copy_text(
                        report.descriptorKeyText,
                        sizeof(report.descriptorKeyText), keyText);
                    themer_indexed_response_copy_text(
                        report.responseClass,
                        sizeof(report.responseClass), imageClass);
                    themer_indexed_response_copy_text(
                        report.uuid, sizeof(report.uuid), uuidText);
                    themer_indexed_response_copy_text(
                        report.validationTokenSHA256,
                        sizeof(report.validationTokenSHA256), tokenHash);
                    themer_indexed_response_copy_text(
                        report.responsePixelSHA256,
                        sizeof(report.responsePixelSHA256), responsePixelHash);
                    themer_indexed_response_copy_text(
                        report.storeFileSHA256,
                        sizeof(report.storeFileSHA256),
                        fileHash.UTF8String);
                    themer_indexed_response_copy_text(
                        report.storePath, sizeof(report.storePath),
                        standardFile.UTF8String);
                    report.responsePointWidth = responseW;
                    report.responsePointHeight = responseH;
                    report.responseScale = responseScale;
                    report.storeFileLength = fileData.length;
                    report.exactPixelMatch = true;
                    report.storeIndexMatch = indexMatch;
                    report.storeFileVerified = fileShape && fileData.length > 0;
                    report.unitDataMatchesFile = unitMatchesFile;
                }
            }

            themer_iconservices_lab_free_data_capture(&unitCapture);
            themer_iconservices_lab_free_data_capture(&tokenCapture);
            themer_iconservices_lab_free_data_capture(&responsePixels);
            if (r_is_objc_ptr(uuidString) && remote_call_current_success())
                r_msg2(uuidString, "release", 0, 0, 0, 0);
            if (r_is_objc_ptr(token) && remote_call_current_success())
                r_msg2(token, "release", 0, 0, 0, 0);
            if (r_is_objc_ptr(uuid) && remote_call_current_success())
                r_msg2(uuid, "release", 0, 0, 0, 0);
        }
        if (report.result == ThemerSpotlightIndexedResponseAmbiguous) break;
    }

    if (!remote_call_current_success()) {
        report.result = ThemerSpotlightIndexedResponseTransportFailed;
        snprintf(report.reason, sizeof(report.reason), "transport-failed");
    } else if (report.result == ThemerSpotlightIndexedResponseAmbiguous) {
        // Preserve the bounded-enumeration failure above.
    } else if (report.exactPixelMatchCount == 1 &&
               r_is_objc_ptr(selectedImage)) {
        report.result = ThemerSpotlightIndexedResponseIdentified;
        snprintf(report.reason, sizeof(report.reason),
                 "visible-pixels-bound-to-indexed-store-response");
    } else if (report.exactPixelMatchCount > 1) {
        report.result = ThemerSpotlightIndexedResponseAmbiguous;
        snprintf(report.reason, sizeof(report.reason),
                 "multiple-indexed-responses-match-visible-pixels");
    } else {
        report.result = ThemerSpotlightIndexedResponseNoIndexedMatch;
        snprintf(report.reason, sizeof(report.reason),
                 report.indexedCandidateCount > 0
                    ? "indexed-responses-found-but-none-match-visible-pixels"
                    : "no-existing-cache-response-resolves-through-store");
    }
    } while (0);

    if (r_is_objc_ptr(managerStore) && remote_call_current_success())
        r_msg2(managerStore, "release", 0, 0, 0, 0);
    themer_iconservices_lab_free_data_capture(&visiblePixels);
    if (labFastPath) (void)r_settle_us(previousSettleUS);
    report.transportClean = remote_call_current_success();
    if (!report.transportClean) {
        report.result = ThemerSpotlightIndexedResponseTransportFailed;
    }
    printf("[ICONINDEX] complete result=%d target=%s rows=%d "
           "descriptorKeys=%d cacheImages=%d indexed=%d exactMatches=%d "
           "selectedUUID=%s path=\"%s\" noMutation=%d transport=%d "
           "reason=%s\n",
           report.result,
           report.targetBundle[0] ? report.targetBundle : "-",
           report.visibleTargetRowCount,
           report.descriptorKeyCount,
           report.cacheImageCount,
           report.indexedCandidateCount,
           report.exactPixelMatchCount,
           report.uuid[0] ? report.uuid : "-",
           report.storePath[0] ? report.storePath : "-",
           report.noMutation,
           report.transportClean,
           report.reason[0] ? report.reason : "-");
    if (reportOut) *reportOut = report;
    return report.result;
}

#pragma mark - VM persistent IconServices store proof

bool themer_spotlight_persistent_store_has_recovery(void)
{
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    NSString *target = [defaults stringForKey:
        THEMER_ICONSERVICES_LAB_PENDING_CACHE_TARGET_KEY];
    NSString *backup = [defaults stringForKey:
        THEMER_ICONSERVICES_LAB_PENDING_CACHE_BACKUP_KEY];
    NSString *temp = [defaults stringForKey:
        THEMER_ICONSERVICES_LAB_PENDING_CACHE_TEMP_KEY];
    return target.length > 0 || backup.length > 0 || temp.length > 0;
}

bool themer_spotlight_persistent_store_restore(void)
{
    if (!themer_spotlight_persistent_store_has_recovery()) return true;
    return themer_iconservices_lab_restore_pending_cache_file();
}

bool themer_spotlight_persistent_store_discard_recovery(void)
{
    NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
    NSString *backupPath = [[defaults stringForKey:
        THEMER_ICONSERVICES_LAB_PENDING_CACHE_BACKUP_KEY] copy];
    NSString *tempPath = [[defaults stringForKey:
        THEMER_ICONSERVICES_LAB_PENDING_CACHE_TEMP_KEY] copy];

    // This helper intentionally never reads, opens, or writes pendingTarget.
    // Only Cyanide-owned recovery artifacts are removed.
    themer_iconservices_lab_clear_cache_recovery();

    BOOL backupAbsent = backupPath.length == 0 ||
        access(backupPath.fileSystemRepresentation, F_OK) != 0;
    BOOL tempAbsent = tempPath.length == 0 ||
        access(tempPath.fileSystemRepresentation, F_OK) != 0;
    return !themer_spotlight_persistent_store_has_recovery() &&
        backupAbsent && tempAbsent;
}

ThemerSpotlightPersistentStoreResult
themer_spotlight_persistent_store_publish_in_session(
    NSDictionary<NSString *, NSData *> *imageDataByBundle,
    const char *targetBundle,
    ThemerSpotlightPersistentStoreReport *reportOut)
{
    ThemerSpotlightPersistentStoreReport report = {0};
    report.result = ThemerSpotlightPersistentStoreVerificationFailed;
    report.noThemedProcessMutation = true;
    snprintf(report.targetBundle, sizeof(report.targetBundle), "%s",
             targetBundle ?: "");

    do {
    if (!remote_call_current_success()) {
        report.result = ThemerSpotlightPersistentStoreTransportFailed;
        snprintf(report.reason, sizeof(report.reason), "transport-down");
        break;
    }
    if (!targetBundle || !targetBundle[0]) {
        snprintf(report.reason, sizeof(report.reason), "target-missing");
        break;
    }
    if (themer_spotlight_persistent_store_has_recovery()) {
        report.result = ThemerSpotlightPersistentStoreRecoveryPending;
        snprintf(report.reason, sizeof(report.reason),
                 "persistent-store-recovery-pending");
        break;
    }

    NSDictionary<NSString *, NSData *> *normalized =
        themer_normalized_theme_data(imageDataByBundle);
    NSString *targetKey = [NSString stringWithUTF8String:targetBundle];
    NSData *targetData = targetKey.length > 0
        ? themer_theme_data_for_key(normalized, targetKey, NULL) : nil;
    if (![targetData isKindOfClass:NSData.class] || targetData.length == 0) {
        snprintf(report.reason, sizeof(report.reason), "target-theme-missing");
        break;
    }

    // Discovery deliberately requires an untouched negative control.  Keep
    // the requested target as the only non-Cyanide key so the existing exact
    // target/control selection remains deterministic without changing any of
    // the older lab callers.
    NSString *controlKey = @"com.zeroxjf.ios-cyanide1";
    NSDictionary<NSString *, NSData *> *selection =
        [targetKey isEqualToString:controlKey]
            ? normalized
            : @{ targetKey: targetData, controlKey: targetData };

    ThemerIconServicesLabDiscovery discovery = {0};
    int discoveryResult = themer_iconservices_lab_discover(
        selection, NULL, false, &discovery);
    if (discoveryResult != 1) {
        report.result = discoveryResult == -2
            ? ThemerSpotlightPersistentStoreTransportFailed
            : ThemerSpotlightPersistentStoreNoIndexedRecord;
        snprintf(report.reason, sizeof(report.reason),
                 "spotlight-store-discovery-%d", discoveryResult);
        themer_iconservices_lab_release_discovery(&discovery);
        break;
    }
    if (strcmp(discovery.targetBundle, targetBundle) != 0 ||
        !discovery.managerCachePathKnown) {
        report.result = ThemerSpotlightPersistentStoreNoIndexedRecord;
        snprintf(report.reason, sizeof(report.reason),
                 "target-or-store-path-mismatch");
        themer_iconservices_lab_release_discovery(&discovery);
        break;
    }

    const ThemerIconServicesLabBagEntry *stock68 = NULL;
    for (int i = 0; i < discovery.stockEntryCount; i++) {
        const ThemerIconServicesLabBagEntry *entry =
            &discovery.stockEntries[i];
        if (entry->geometryKnown && r_is_objc_ptr(entry->image) &&
            themer_iconservices_lab_sizes_match(
                entry->width, entry->height, 68.0, 68.0)) {
            if (stock68) {
                stock68 = NULL;
                break;
            }
            stock68 = entry;
        }
    }
    report.indexedRecordFound = stock68 != NULL;
    if (!stock68) {
        report.result = ThemerSpotlightPersistentStoreNoIndexedRecord;
        snprintf(report.reason, sizeof(report.reason),
                 "one-exact-indexed-stock68-record-not-found");
        themer_iconservices_lab_release_discovery(&discovery);
        break;
    }

    uint64_t stockUUID = themer_iconservices_lab_retained_getter(
        stock68->image, "uuid");
    uint64_t uuidString = r_is_objc_ptr(stockUUID)
        ? themer_iconservices_lab_retained_getter(stockUUID, "UUIDString") : 0;
    bool uuidKnown = r_is_objc_ptr(uuidString) &&
        r_read_nsstring(uuidString, report.uuid, sizeof(report.uuid));
    NSString *storeDirectory = [NSString stringWithUTF8String:
        discovery.managerCachePath];
    NSString *stockFile = uuidKnown
        ? [NSString stringWithFormat:@"%s.isdata", report.uuid] : nil;
    NSString *stockPath = stockFile.length > 0
        ? [storeDirectory stringByAppendingPathComponent:stockFile] : nil;
    NSData *stockBytes = stockPath.length > 0
        ? themer_iconservices_lab_read_local_file(stockPath) : nil;
    if (stockPath.length > 0) {
        snprintf(report.storePath, sizeof(report.storePath), "%s",
                 stockPath.UTF8String ?: "");
    }
    report.stockLength = stockBytes.length;
    NSString *stockHash = stockBytes
        ? themer_stock68_registration_hash(stockBytes) : nil;
    snprintf(report.stockSHA256, sizeof(report.stockSHA256), "%s",
             stockHash.UTF8String ?: "");

    NSDictionary<NSString *, NSData *> *scaledTheme =
        themer_iconservices_lab_scaled_theme_data(
            selection, targetBundle,
            stock68->width, stock68->height, stock68->scale);
    NSData *scaledTargetPNG = scaledTheme[targetKey];
    NSError *structuredError = nil;
    NSDictionary *structuredDiagnostics = nil;
    NSData *structuredLayerData =
        CNDIconServicesCreateStructuredLayerData(
            scaledTargetPNG,
            CGSizeMake(stock68->width, stock68->height),
            stock68->scale,
            &structuredDiagnostics,
            &structuredError);
    printf("[ICONSERVICES_PERSISTENT] structured-payload marker=%s "
           "ready=%d layerBytes=%lu stackBytes=%llu "
           "pixels=%llux%llu error=\"%s\"\n",
           CNDIconServicesThemeMarker.UTF8String,
           structuredLayerData.length > 0,
           (unsigned long)structuredLayerData.length,
           [structuredDiagnostics[@"stackDataLength"] unsignedLongLongValue],
           [structuredDiagnostics[@"pixelWidth"] unsignedLongLongValue],
           [structuredDiagnostics[@"pixelHeight"] unsignedLongLongValue],
           structuredError.localizedDescription.UTF8String ?: "-");
    ThemerSpotlightRemoteImage sourceImages[2] = {0};
    int sourceImageCount = 0;
    uint64_t sourceImage = themer_spotlight_remote_image_for_bundle(
        scaledTheme ?: selection, targetBundle,
        sourceImages, &sourceImageCount, 2);
    uint64_t concreteImage = r_is_objc_ptr(sourceImage) &&
            structuredLayerData.length > 0
        ? themer_iconservices_lab_make_structured_if_image(
            sourceImage, stock68->scale, structuredLayerData)
        : 0;
    report.exactGeometry = r_is_objc_ptr(concreteImage) &&
        themer_iconservices_lab_image_geometry_matches(
            concreteImage, stock68->width, stock68->height, stock68->scale);

    uint64_t themedData = r_is_objc_ptr(concreteImage)
        ? themer_iconservices_lab_retained_getter(concreteImage, "data") : 0;
    ThemerIconServicesLabDataCapture themedCapture = {0};
    bool themedCaptured = r_is_objc_ptr(themedData) &&
        themer_iconservices_lab_capture_nsdata(
            themedData, THEMER_ICONSERVICES_LAB_DATA_CAPTURE_CAP,
            &themedCapture) && !themedCapture.truncated &&
        themedCapture.objectLength > 0;
    report.structuredMarkerSerialized = themedCaptured &&
        themer_capture_contains_marker(
            &themedCapture, CNDIconServicesThemeMarker.UTF8String);
    report.themedLength = themedCaptured ? themedCapture.objectLength : 0;
    if (themedCaptured) {
        NSData *bytes = [NSData dataWithBytes:themedCapture.bytes
                                       length:themedCapture.objectLength];
        NSString *hash = themer_stock68_registration_hash(bytes);
        snprintf(report.themedSHA256, sizeof(report.themedSHA256), "%s",
                 hash.UTF8String ?: "");
    }

    bool recordReady = uuidKnown && stockBytes.length > 0 &&
        report.exactGeometry && themedCaptured &&
        report.structuredMarkerSerialized && remote_call_current_success();
    if (recordReady && themedCapture.objectLength > stockBytes.length) {
        report.result = ThemerSpotlightPersistentStoreThemeDoesNotFit;
        snprintf(report.reason, sizeof(report.reason),
                 "themed-response-does-not-fit-existing-store-unit");
        if (r_is_objc_ptr(concreteImage) && remote_call_current_success()) {
            r_msg2(concreteImage, "release", 0, 0, 0, 0);
        }
    } else if (!recordReady) {
        report.result = remote_call_current_success()
            ? ThemerSpotlightPersistentStoreVerificationFailed
            : ThemerSpotlightPersistentStoreTransportFailed;
        snprintf(report.reason, sizeof(report.reason),
                 structuredLayerData.length == 0
                    ? "structured-layer-payload-unavailable"
                    : (!report.structuredMarkerSerialized
                        ? "structured-marker-missing-from-ifimage-data"
                        : "stock-or-themed-record-contract-unverified"));
        if (r_is_objc_ptr(concreteImage) && remote_call_current_success()) {
            r_msg2(concreteImage, "release", 0, 0, 0, 0);
        }
    } else {
        bool ignoredStoreUnitAdded = false;
        bool ready = false;
        uint64_t cacheImage =
            themer_iconservices_lab_make_store_backed_cache_image(
                concreteImage, stock68, targetBundle,
                discovery.managerCachePath,
                stock68->width, stock68->height, stock68->scale,
                65.0, 65.0, &ignoredStoreUnitAdded, &ready);
        // The constructor consumes concreteImage on every path.

        NSUserDefaults *defaults = NSUserDefaults.standardUserDefaults;
        NSString *pendingTarget = [defaults stringForKey:
            THEMER_ICONSERVICES_LAB_PENDING_CACHE_TARGET_KEY];
        NSString *pendingBackup = [defaults stringForKey:
            THEMER_ICONSERVICES_LAB_PENDING_CACHE_BACKUP_KEY];
        NSString *pendingTemp = [defaults stringForKey:
            THEMER_ICONSERVICES_LAB_PENDING_CACHE_TEMP_KEY];
        NSData *paddedThemedBytes = pendingTemp.length > 0
            ? themer_iconservices_lab_read_local_file(pendingTemp) : nil;
        if (paddedThemedBytes.length > 0) {
            report.themedLength = paddedThemedBytes.length;
            NSString *paddedHash =
                themer_stock68_registration_hash(paddedThemedBytes);
            snprintf(report.themedSHA256, sizeof(report.themedSHA256), "%s",
                     paddedHash.UTF8String ?: "");
        }
        report.backupPersisted = pendingTarget.length > 0 &&
            pendingBackup.length > 0 && pendingTemp.length > 0 &&
            [pendingTarget isEqualToString:stockPath];
        report.overwriteVerified = ready && report.backupPersisted &&
            themer_iconservices_lab_local_files_equal(
                pendingTarget, pendingTemp);
        if (report.overwriteVerified && r_is_objc_ptr(cacheImage) &&
            remote_call_current_success()) {
            report.result = ThemerSpotlightPersistentStoreReady;
            snprintf(report.reason, sizeof(report.reason),
                     "indexed-store-unit-overwritten-restart-spotlight");
        } else {
            report.result = remote_call_current_success()
                ? ThemerSpotlightPersistentStoreVerificationFailed
                : ThemerSpotlightPersistentStoreTransportFailed;
            snprintf(report.reason, sizeof(report.reason),
                     "indexed-store-unit-overwrite-unverified");
        }
        if (r_is_objc_ptr(cacheImage) && remote_call_current_success()) {
            r_msg2(cacheImage, "release", 0, 0, 0, 0);
        }
    }

    if (r_is_objc_ptr(themedData) && remote_call_current_success()) {
        r_msg2(themedData, "release", 0, 0, 0, 0);
    }
    themer_iconservices_lab_free_data_capture(&themedCapture);
    themer_spotlight_proof_release_images(
        sourceImages, sourceImageCount, 0);
    if (r_is_objc_ptr(uuidString) && remote_call_current_success()) {
        r_msg2(uuidString, "release", 0, 0, 0, 0);
    }
    if (r_is_objc_ptr(stockUUID) && remote_call_current_success()) {
        r_msg2(stockUUID, "release", 0, 0, 0, 0);
    }
    themer_iconservices_lab_release_discovery(&discovery);
    } while (0);

    report.transportClean = remote_call_current_success();
    if (!report.transportClean &&
        report.result != ThemerSpotlightPersistentStoreRecoveryPending) {
        report.result = ThemerSpotlightPersistentStoreTransportFailed;
    }
    printf("[ICONSERVICES_PERSISTENT] publish result=%d target=%s "
           "uuid=%s path=\"%s\" indexed=%d geometry=%d marker=%d "
           "stock=%llu/%s themed=%llu/%s backup=%d overwrite=%d "
           "themedProcessMutation=%d transport=%d reason=%s\n",
           report.result,
           report.targetBundle[0] ? report.targetBundle : "-",
           report.uuid[0] ? report.uuid : "-",
           report.storePath[0] ? report.storePath : "-",
           report.indexedRecordFound,
           report.exactGeometry,
           report.structuredMarkerSerialized,
           (unsigned long long)report.stockLength,
           report.stockSHA256[0] ? report.stockSHA256 : "-",
           (unsigned long long)report.themedLength,
           report.themedSHA256[0] ? report.themedSHA256 : "-",
           report.backupPersisted,
           report.overwriteVerified,
           !report.noThemedProcessMutation,
           report.transportClean,
           report.reason[0] ? report.reason : "-");
    if (reportOut) *reportOut = report;
    return report.result;
}

#pragma mark - VM provider-boundary interception proof

#define THEMER_PROVIDER_CONSUMER_BRIDGE_STATE_KEY \
    "cndIconServicesConsumerBridgeV1"

static uint64_t themer_provider_intercept_find_consumer_icon(
    const char *targetBundle,
    uint64_t *viewOut)
{
    if (viewOut) *viewOut = 0;
    if (!targetBundle || !targetBundle[0] ||
        !remote_call_current_success()) return 0;

    // Spotlight owns a private SBHIconModel and its SBHApplicationIcon
    // instances live in the Spotlight process, not SpringBoard. Prefer the
    // icon attached to a materialized SearchUI row so the proof binds the
    // exact object that will be asked to render.
    enum { VIEW_CAP = 64 };
    uint64_t views[VIEW_CAP] = {0};
    int viewCount = themer_spotlight_collect_searchui_views_fast(
        views, VIEW_CAP);
    uint64_t fallbackIcon = 0;
    uint64_t fallbackView = 0;
    for (int i = 0; i < viewCount && remote_call_current_success(); i++) {
        uint64_t icon = themer_spotlight_app_icon_for_view(
            views[i], NULL, 0);
        if (!r_is_objc_ptr(icon)) continue;
        char bundle[192] = {0};
        char source[160] = {0};
        if (!themer_spotlight_bundle_for_view(
                views[i], icon, bundle, sizeof(bundle),
                source, sizeof(source), NULL) ||
            strcmp(bundle, targetBundle) != 0) {
            continue;
        }
        if (!fallbackIcon) {
            fallbackIcon = icon;
            fallbackView = views[i];
        }
        int hidden = themer_remote_hidden(views[i]);
        double alpha = themer_remote_alpha(views[i]);
        if (hidden != 1 && (alpha < 0.0 || alpha >= 0.01)) {
            if (viewOut) *viewOut = views[i];
            return icon;
        }
    }
    if (r_is_objc_ptr(fallbackIcon)) {
        if (viewOut) *viewOut = fallbackView;
        return fallbackIcon;
    }

    // SearchUI keeps a private SBHIconModel even when no result row is
    // currently mounted. Ask that exact model to materialize the target so a
    // later search reuses the bridged canonical icon instead of requiring a
    // timing race with the visible row.
    uint64_t owner = 0, dataSource = 0, iconModel = 0, repository = 0;
    if (themer_spotlight_current_graph(
            &owner, &dataSource, &iconModel, &repository)) {
        uint64_t roots[3] = { iconModel, repository, owner };
        uint64_t modelIcon =
            themer_lookup_model_icon_for_bundle_with_roots(
                targetBundle, roots, 3);
        if (r_is_objc_ptr(modelIcon)) return modelIcon;
    }

    // SpringBoard's long-lived model is the corresponding Home Screen path.
    return themer_lookup_model_icon_for_bundle(targetBundle);
}

static uint64_t themer_provider_intercept_consumer_subclass(
    uint64_t baseClass,
    const char *methodTypes)
{
    if (!r_is_objc_ptr(baseClass) || !methodTypes || !methodTypes[0] ||
        !remote_call_current_success()) return 0;

    char baseName[128] = {0};
    themer_read_class_object_name(baseClass, baseName, sizeof(baseName));
    while (!strncmp(baseName, "CNDIconServicesConsumerBridgeV1_",
                    sizeof("CNDIconServicesConsumerBridgeV1_") - 1)) {
        uint64_t superClass = r_dlsym_call(
            R_TIMEOUT, "class_getSuperclass", baseClass,
            0, 0, 0, 0, 0, 0, 0);
        if (!r_is_objc_ptr(superClass) || superClass == baseClass) return 0;
        baseClass = superClass;
        themer_read_class_object_name(baseClass, baseName, sizeof(baseName));
    }
    if (!baseName[0]) return 0;

    char subclassName[192] = {0};
    snprintf(subclassName, sizeof(subclassName),
             "CNDIconServicesConsumerBridgeV1_%s", baseName);
    uint64_t subclass = themer_lookup_class(subclassName);
    uint64_t imp = themer_remote_symbol_addr("objc_getAssociatedObject");
    if (!imp) return 0;

    if (!r_is_objc_ptr(subclass)) {
        uint64_t remoteName = r_alloc_str(subclassName);
        subclass = remoteName ? r_dlsym_call(
            R_TIMEOUT, "objc_allocateClassPair", baseClass, remoteName,
            0, 0, 0, 0, 0, 0) : 0;
        if (remoteName && remote_call_current_success()) r_free(remoteName);
        if (!r_is_objc_ptr(subclass) ||
            !themer_add_method(subclass, "iconServicesIconForImage",
                               imp, methodTypes)) {
            return 0;
        }
        r_dlsym_call(R_TIMEOUT, "objc_registerClassPair",
                     subclass, 0, 0, 0, 0, 0, 0, 0);
    }

    uint64_t installed = themer_method_imp(
        subclass, "iconServicesIconForImage");
    return remote_call_current_success() &&
           native_strip(installed) == native_strip(imp)
        ? subclass : 0;
}

static uint64_t themer_provider_intercept_number(uint64_t value)
{
    uint64_t numberClass = themer_lookup_class("NSNumber");
    return r_is_objc_ptr(numberClass) &&
           r_responds_main(numberClass, "numberWithUnsignedLongLong:")
        ? r_msg2_main(numberClass, "numberWithUnsignedLongLong:",
                      value, 0, 0, 0)
        : 0;
}

static bool themer_provider_intercept_install_consumer_bridge(
    uint64_t consumerIcon,
    uint64_t targetIcon,
    uint64_t consumerView,
    ThemerIconProviderInterceptReport *report)
{
    if (!r_is_objc_ptr(consumerIcon) || !r_is_objc_ptr(targetIcon) ||
        !report || !remote_call_current_success()) return false;
    if (r_is_objc_ptr(themer_spotlight_associated_process_object(
            THEMER_PROVIDER_CONSUMER_BRIDGE_STATE_KEY))) {
        snprintf(report->reason, sizeof(report->reason),
                 "consumer-bridge-state-already-present");
        return false;
    }

    report->consumerIconLocated = true;
    themer_read_class_name(consumerIcon, report->consumerIconClass,
                           sizeof(report->consumerIconClass));
    char methodTypes[192] = {0};
    bool methodABI = themer_iconservices_lab_method_types(
        consumerIcon, "iconServicesIconForImage",
        methodTypes, sizeof(methodTypes)) &&
        !strcmp(methodTypes, "@16@0:8");
    uint64_t originalClass = r_dlsym_call(
        R_TIMEOUT, "object_getClass", consumerIcon,
        0, 0, 0, 0, 0, 0, 0);
    uint64_t subclass = methodABI
        ? themer_provider_intercept_consumer_subclass(
              originalClass, methodTypes)
        : 0;
    uint64_t selector = r_sel("iconServicesIconForImage");
    printf("[ICONINTERCEPT] consumer bridge icon=0x%llx class=%s "
           "view=0x%llx abi=\"%s\" accepted=%d subclass=0x%llx\n",
           (unsigned long long)consumerIcon,
           report->consumerIconClass[0] ? report->consumerIconClass : "-",
           (unsigned long long)consumerView,
           methodTypes[0] ? methodTypes : "-", methodABI,
           (unsigned long long)subclass);
    if (!methodABI || !r_is_objc_ptr(originalClass) ||
        !r_is_objc_ptr(subclass) || !selector) {
        snprintf(report->reason, sizeof(report->reason),
                 "consumer-iconservicesiconforimage-abi");
        return false;
    }

    uint64_t dictionaryClass = themer_lookup_class("NSMutableDictionary");
    uint64_t allocation = r_is_objc_ptr(dictionaryClass)
        ? r_msg2(dictionaryClass, "alloc", 0, 0, 0, 0) : 0;
    uint64_t state = r_is_objc_ptr(allocation)
        ? r_msg2_main(allocation, "initWithCapacity:", 4, 0, 0, 0) : 0;
    uint64_t classNumber = themer_provider_intercept_number(originalClass);
    bool stateReady = r_is_objc_ptr(state) && r_is_objc_ptr(classNumber) &&
        themer_spotlight_dictionary_set_object(
            state, "consumerIcon", consumerIcon) &&
        themer_spotlight_dictionary_set_object(
            state, "targetIcon", targetIcon) &&
        themer_spotlight_dictionary_set_object(
            state, "originalClass", classNumber);
    if (stateReady && r_is_objc_ptr(consumerView)) {
        stateReady = themer_spotlight_dictionary_set_object(
            state, "consumerView", consumerView);
    }
    if (!stateReady) {
        if (r_is_objc_ptr(state) && remote_call_current_success())
            r_msg2(state, "release", 0, 0, 0, 0);
        snprintf(report->reason, sizeof(report->reason),
                 "consumer-bridge-state-construction");
        return false;
    }

    r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                 consumerIcon, selector, targetIcon, 1, 0, 0, 0, 0);
    bool associated = r_dlsym_call(
        R_TIMEOUT, "objc_getAssociatedObject", consumerIcon, selector,
        0, 0, 0, 0, 0, 0) == targetIcon &&
        remote_call_current_success();
    bool classChanged = false;
    if (associated) {
        uint64_t previous = r_dlsym_call(
            R_TIMEOUT, "object_setClass", consumerIcon, subclass,
            0, 0, 0, 0, 0, 0);
        classChanged = previous == originalClass &&
            remote_call_current_success();
    }
    uint64_t readback = classChanged
        ? r_msg2_main(consumerIcon, "iconServicesIconForImage",
                      0, 0, 0, 0)
        : 0;
    report->consumerBridgeReadbackVerified =
        readback == targetIcon && remote_call_current_success();
    bool stateCommitted = report->consumerBridgeReadbackVerified &&
        themer_spotlight_commit_process_object(
            THEMER_PROVIDER_CONSUMER_BRIDGE_STATE_KEY, state);
    report->consumerBridgeInstalled = stateCommitted;

    if (!stateCommitted && remote_call_current_success()) {
        if (classChanged) {
            (void)r_dlsym_call(R_TIMEOUT, "object_setClass",
                               consumerIcon, originalClass,
                               0, 0, 0, 0, 0, 0);
        }
        r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                     consumerIcon, selector, 0, 1, 0, 0, 0, 0);
    }

    if (stateCommitted && remote_call_current_success()) {
        bool refreshIssued = themer_notify_icon_image_changed(consumerIcon);
        if (r_is_objc_ptr(consumerView) &&
            r_responds_main(consumerView, "resetImageWithAppIcon:")) {
            r_msg2_main(consumerView, "resetImageWithAppIcon:",
                        consumerIcon, 0, 0, 0);
            refreshIssued = remote_call_current_success();
        }
        if (r_is_objc_ptr(consumerView) &&
            r_responds_main(consumerView, "setNeedsLayout")) {
            r_msg2_main(consumerView, "setNeedsLayout", 0, 0, 0, 0);
        }
        report->consumerRefreshIssued = refreshIssued &&
            remote_call_current_success();
    }

    if (r_is_objc_ptr(state) && remote_call_current_success())
        r_msg2(state, "release", 0, 0, 0, 0);
    return report->consumerBridgeInstalled &&
           report->consumerBridgeReadbackVerified &&
           report->consumerRefreshIssued && remote_call_current_success();
}

static bool themer_provider_intercept_restore_consumer_bridge(
    ThemerIconProviderInterceptReport *report)
{
    if (!report || !remote_call_current_success()) return false;
    uint64_t state = themer_spotlight_associated_process_object(
        THEMER_PROVIDER_CONSUMER_BRIDGE_STATE_KEY);
    if (!r_is_objc_ptr(state)) {
        // Compatibility with provider-only journals created by the previous
        // VM proof: there was no consumer mutation to restore.
        report->consumerBridgeRestored = true;
        return true;
    }

    uint64_t consumerIcon = themer_spotlight_dictionary_object(
        state, "consumerIcon");
    uint64_t consumerView = themer_spotlight_dictionary_object(
        state, "consumerView");
    uint64_t classNumber = themer_spotlight_dictionary_object(
        state, "originalClass");
    uint64_t originalClass = r_is_objc_ptr(classNumber) &&
        r_responds_main(classNumber, "unsignedLongLongValue")
        ? r_msg2_main(classNumber, "unsignedLongLongValue", 0, 0, 0, 0)
        : 0;
    uint64_t selector = r_sel("iconServicesIconForImage");
    bool restored = r_is_objc_ptr(consumerIcon) &&
        r_is_objc_ptr(originalClass) && selector;
    if (restored) {
        uint64_t currentClass = r_dlsym_call(
            R_TIMEOUT, "object_getClass", consumerIcon,
            0, 0, 0, 0, 0, 0, 0);
        if (currentClass != originalClass) {
            uint64_t previous = r_dlsym_call(
                R_TIMEOUT, "object_setClass", consumerIcon, originalClass,
                0, 0, 0, 0, 0, 0);
            restored = previous == currentClass &&
                remote_call_current_success();
        }
    }
    if (restored) {
        r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                     consumerIcon, selector, 0, 1, 0, 0, 0, 0);
        restored = r_dlsym_call(
            R_TIMEOUT, "objc_getAssociatedObject", consumerIcon, selector,
            0, 0, 0, 0, 0, 0) == 0 &&
            remote_call_current_success();
    }
    bool stateCleared = restored &&
        themer_spotlight_commit_process_object(
            THEMER_PROVIDER_CONSUMER_BRIDGE_STATE_KEY, 0);
    if (stateCleared && remote_call_current_success()) {
        (void)themer_notify_icon_image_changed(consumerIcon);
        if (r_is_objc_ptr(consumerView) &&
            r_responds_main(consumerView, "resetImageWithAppIcon:")) {
            r_msg2_main(consumerView, "resetImageWithAppIcon:",
                        consumerIcon, 0, 0, 0);
        }
    }
    report->consumerBridgeRestored = stateCleared &&
        remote_call_current_success();
    printf("[ICONINTERCEPT] consumer bridge restore icon=0x%llx "
           "originalClass=0x%llx restored=%d stateCleared=%d\n",
           (unsigned long long)consumerIcon,
           (unsigned long long)originalClass,
           restored, stateCleared);
    return report->consumerBridgeRestored;
}

static uint64_t themer_provider_intercept_make_legacy_resource(
    const char *bundlePath,
    const char *resourceBaseName,
    ThemerIconProviderInterceptReport *report)
{
    if (!bundlePath || !bundlePath[0] || !resourceBaseName ||
        !resourceBaseName[0] || !report || !remote_call_current_success()) {
        return 0;
    }

    uint64_t urlClass = themer_lookup_class("NSURL");
    uint64_t arrayClass = themer_lookup_class("NSMutableArray");
    uint64_t dictionaryClass = themer_lookup_class("NSMutableDictionary");
    uint64_t providerClass = themer_lookup_class("ISResourceProvider");
    uint64_t path = r_nsstr_retained(bundlePath);
    uint64_t baseName = r_nsstr_retained(resourceBaseName);
    uint64_t url = 0, files = 0, dictionary = 0, provider = 0;
    char factoryTypes[192] = {0};

    bool factoryABI = r_is_objc_ptr(urlClass) &&
        r_is_objc_ptr(arrayClass) && r_is_objc_ptr(dictionaryClass) &&
        r_is_objc_ptr(providerClass) && r_is_objc_ptr(path) &&
        r_is_objc_ptr(baseName) &&
        r_responds_main(providerClass,
                        "resourceWithBundleURL:iconDictionary:options:") &&
        themer_iconservices_lab_method_types(
            providerClass, "resourceWithBundleURL:iconDictionary:options:",
            factoryTypes, sizeof(factoryTypes)) &&
        (!strcmp(factoryTypes, "@40@0:8@16@24Q32") ||
         !strcmp(factoryTypes, "@40@0:8@16@24q32"));
    printf("[ICONINTERCEPT] provider-factory abi=\"%s\" accepted=%d "
           "bundle=\"%s\" resource=%s\n",
           factoryTypes[0] ? factoryTypes : "-", factoryABI,
           bundlePath, resourceBaseName);
    if (!factoryABI) goto cleanup;

    url = r_msg2_main(urlClass, "fileURLWithPath:", path, 0, 0, 0);
    if (r_is_objc_ptr(url)) url = r_msg2(url, "retain", 0, 0, 0, 0);
    uint64_t arrayAlloc = r_msg2(arrayClass, "alloc", 0, 0, 0, 0);
    files = r_is_objc_ptr(arrayAlloc)
        ? r_msg2_main(arrayAlloc, "initWithCapacity:", 1, 0, 0, 0) : 0;
    if (r_is_objc_ptr(files)) {
        r_msg2_main(files, "addObject:", baseName, 0, 0, 0);
    }
    uint64_t dictionaryAlloc = r_msg2(
        dictionaryClass, "alloc", 0, 0, 0, 0);
    dictionary = r_is_objc_ptr(dictionaryAlloc)
        ? r_msg2_main(dictionaryAlloc, "initWithCapacity:", 1, 0, 0, 0) : 0;
    bool dictionaryReady = r_is_objc_ptr(dictionary) &&
        themer_spotlight_dictionary_set_object(
            dictionary, "CFBundleIconFiles", files);
    if (!r_is_objc_ptr(url) || !dictionaryReady ||
        !remote_call_current_success()) goto cleanup;

    provider = r_msg2_main(
        providerClass, "resourceWithBundleURL:iconDictionary:options:",
        url, dictionary, 0xc, 0);
    if (r_is_objc_ptr(provider) && remote_call_current_success()) {
        provider = r_msg2(provider, "retain", 0, 0, 0, 0);
        themer_read_class_name(
            provider, report->resolvedResourceClass,
            sizeof(report->resolvedResourceClass));
        if (r_responds_main(provider, "resolveResources")) {
            r_msg2_main(provider, "resolveResources", 0, 0, 0, 0);
        }
    }

cleanup:
    if (r_is_objc_ptr(dictionary) && remote_call_current_success())
        r_msg2(dictionary, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(files) && remote_call_current_success())
        r_msg2(files, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(url) && remote_call_current_success())
        r_msg2(url, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(baseName) && remote_call_current_success())
        r_msg2(baseName, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(path) && remote_call_current_success())
        r_msg2(path, "release", 0, 0, 0, 0);
    return remote_call_current_success() && r_is_objc_ptr(provider)
        ? provider : 0;
}

static uint64_t themer_provider_intercept_subclass(
    uint64_t baseClass,
    const char *methodTypes)
{
    if (!r_is_objc_ptr(baseClass) || !methodTypes || !methodTypes[0] ||
        !remote_call_current_success()) return 0;
    const char *name = "CNDProviderInterceptISBundleIdentifierIcon";
    uint64_t subclass = themer_lookup_class(name);
    uint64_t imp = themer_remote_symbol_addr("objc_getAssociatedObject");
    if (!imp) return 0;
    if (!r_is_objc_ptr(subclass)) {
        uint64_t remoteName = r_alloc_str(name);
        subclass = remoteName ? r_dlsym_call(
            R_TIMEOUT, "objc_allocateClassPair", baseClass, remoteName,
            0, 0, 0, 0, 0, 0) : 0;
        if (remoteName && remote_call_current_success()) r_free(remoteName);
        if (!r_is_objc_ptr(subclass)) return 0;
        if (!themer_add_method(
                subclass,
                "_makeResourceProviderAllowIconResourceFallback:",
                imp, methodTypes)) {
            return 0;
        }
        r_dlsym_call(R_TIMEOUT, "objc_registerClassPair",
                     subclass, 0, 0, 0, 0, 0, 0, 0);
    }
    uint64_t installed = themer_method_imp(
        subclass, "_makeResourceProviderAllowIconResourceFallback:");
    return remote_call_current_success() && native_strip(installed) ==
        native_strip(imp) ? subclass : 0;
}

static uint64_t themer_provider_intercept_copy_descriptor(void)
{
    uint64_t named = themer_iconservices_lab_named_spotlight_descriptor(
        NULL, NULL, NULL);
    if (!r_is_objc_ptr(named)) return 0;
    uint64_t descriptor = r_responds_main(named, "copy")
        ? r_msg2_main(named, "copy", 0, 0, 0, 0) : 0;
    if (r_is_objc_ptr(descriptor) &&
        r_responds_main(descriptor, "setIgnoreCache:")) {
        r_msg2_main(descriptor, "setIgnoreCache:", 1, 0, 0, 0);
    }
    if (remote_call_current_success()) {
        r_msg2(named, "release", 0, 0, 0, 0);
    }
    return remote_call_current_success() && r_is_objc_ptr(descriptor)
        ? descriptor : 0;
}

static uint64_t themer_provider_intercept_canonical_icon(uint64_t seedIcon)
{
    uint64_t managerClass = themer_lookup_class("ISIconManager");
    uint64_t manager = r_is_objc_ptr(managerClass) &&
        r_responds_main(managerClass, "sharedInstance")
        ? r_msg2_main(managerClass, "sharedInstance", 0, 0, 0, 0) : 0;
    uint64_t canonical = r_is_objc_ptr(manager) &&
        r_responds_main(manager, "findOrRegisterIcon:")
        ? r_msg2_main(manager, "findOrRegisterIcon:",
                      seedIcon, 0, 0, 0) : 0;
    return r_is_objc_ptr(canonical) && remote_call_current_success()
        ? r_msg2(canonical, "retain", 0, 0, 0, 0) : 0;
}

static uint64_t themer_provider_intercept_original_icon_key(void)
{
    return r_sel("cnd_providerInterceptOriginalIconResource");
}

static uint64_t themer_provider_intercept_original_badge_key(void)
{
    return r_sel("cnd_providerInterceptOriginalBadgeResource");
}

static bool themer_provider_intercept_store_original_resources(
    uint64_t provider,
    uint64_t iconResource,
    uint64_t badgeResource)
{
    uint64_t iconKey = themer_provider_intercept_original_icon_key();
    uint64_t badgeKey = themer_provider_intercept_original_badge_key();
    if (!r_is_objc_ptr(provider) || !r_is_objc_ptr(iconResource) ||
        !r_is_objc_ptr(badgeResource) || !iconKey || !badgeKey ||
        !remote_call_current_success()) return false;
    r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                 provider, iconKey, iconResource, 1, 0, 0, 0, 0);
    r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                 provider, badgeKey, badgeResource, 1, 0, 0, 0, 0);
    return remote_call_current_success() &&
        r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                     provider, iconKey, 0, 0, 0, 0, 0, 0) == iconResource &&
        r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                     provider, badgeKey, 0, 0, 0, 0, 0, 0) == badgeResource;
}

static bool themer_provider_intercept_clear_original_resources(
    uint64_t provider)
{
    uint64_t iconKey = themer_provider_intercept_original_icon_key();
    uint64_t badgeKey = themer_provider_intercept_original_badge_key();
    if (!r_is_objc_ptr(provider) || !iconKey || !badgeKey ||
        !remote_call_current_success()) return false;
    r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                 provider, iconKey, 0, 1, 0, 0, 0, 0);
    r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                 provider, badgeKey, 0, 1, 0, 0, 0, 0);
    return remote_call_current_success() &&
        r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                     provider, iconKey, 0, 0, 0, 0, 0, 0) == 0 &&
        r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                     provider, badgeKey, 0, 0, 0, 0, 0, 0) == 0;
}

static bool themer_provider_intercept_publish_cache(
    uint64_t targetIcon,
    uint64_t descriptor,
    uint64_t image,
    ThemerIconProviderInterceptReport *report)
{
    uint64_t managerClass = themer_lookup_class("ISIconManager");
    uint64_t manager = r_is_objc_ptr(managerClass) &&
        r_responds_main(managerClass, "sharedInstance")
        ? r_msg2_main(managerClass, "sharedInstance", 0, 0, 0, 0) : 0;
    uint64_t canonical = r_is_objc_ptr(manager) &&
        r_responds_main(manager, "findOrRegisterIcon:")
        ? r_msg2_main(manager, "findOrRegisterIcon:",
                      targetIcon, 0, 0, 0) : 0;
    uint64_t cache = r_is_objc_ptr(canonical) &&
        r_responds_main(canonical, "imageCache")
        ? r_msg2_main(canonical, "imageCache", 0, 0, 0, 0) : 0;
    bool abi = r_is_objc_ptr(cache) &&
        r_responds_main(cache, "setImage:forDescriptor:") &&
        r_responds_main(cache, "imageForDescriptor:");
    if (!abi) return false;
    r_msg2_main(cache, "setImage:forDescriptor:", image, descriptor, 0, 0);
    report->canonicalCachePublished = remote_call_current_success();
    uint64_t readback = report->canonicalCachePublished
        ? r_msg2_main(cache, "imageForDescriptor:", descriptor, 0, 0, 0)
        : 0;
    report->canonicalCacheReadbackVerified =
        readback == image && remote_call_current_success();
    return report->canonicalCacheReadbackVerified;
}

static bool themer_provider_intercept_restore_resources(
    uint64_t provider,
    uint64_t originalIconResource,
    uint64_t originalBadgeResource)
{
    if (!r_is_objc_ptr(provider) ||
        !r_is_objc_ptr(originalIconResource) ||
        !r_is_objc_ptr(originalBadgeResource) ||
        !remote_call_current_success()) {
        return false;
    }
    r_msg2_main(provider, "setIconResource:",
                originalIconResource, 0, 0, 0);
    r_msg2_main(provider, "setBadgeResource:",
                originalBadgeResource, 0, 0, 0);
    if (!r_msg2_main(provider, "resolved", 0, 0, 0, 0)) {
        r_msg2_main(provider, "setResolved:", 1, 0, 0, 0);
    }
    return remote_call_current_success() &&
        r_msg2_main(provider, "iconResource", 0, 0, 0, 0) ==
            originalIconResource &&
        r_msg2_main(provider, "badgeResource", 0, 0, 0, 0) ==
            originalBadgeResource &&
        r_msg2_main(provider, "resolved", 0, 0, 0, 0) != 0;
}

static ThemerIconProviderInterceptResult
themer_provider_intercept_run(
    NSDictionary<NSString *, NSData *> *imageDataByBundle,
    const char *targetBundle,
    const char *themeBundlePath,
    const char *themeResourceBaseName,
    bool applying,
    ThemerIconProviderInterceptReport *reportOut)
{
    ThemerIconProviderInterceptReport report = {0};
    report.result = ThemerIconProviderInterceptTransportFailed;
    if (targetBundle) snprintf(report.targetBundle,
        sizeof(report.targetBundle), "%s", targetBundle);
    uint64_t seedIcon = 0, targetIcon = 0, controlIcon = 0, descriptor = 0;
    uint64_t stockProvider = 0, themedProvider = 0, themedResource = 0;
    uint64_t originalIconResource = 0, originalBadgeResource = 0;
    uint64_t originalClass = 0, subclass = 0, selector = 0;
    uint64_t generated = 0, stockImage = 0;
    uint64_t consumerIcon = 0, consumerView = 0;
    bool classChanged = false, associationInstalled = false;
    bool providerResourcesReplaced = false;
    bool originalResourcesStored = false;
    bool consumerBridgeInstalled = false;
    bool keepCanonicalReplacement = false;
    ThemerIconServicesLabDataCapture stockPixels = {0};
    ThemerIconServicesLabDataCapture generatedPixels = {0};
    ThemerAgentCGMetadata stockMetadata = {0}, generatedMetadata = {0};
    ThemerIconServicesLabRecordIdentifiersObservation identifiers = {0};
    bool requestABI = false, generationInvoked = false;

    printf("[ICONINTERCEPT] begin mode=%s pid=%d target=%s "
           "bundleMutations=0 registrationMutations=0 globalHooks=0\n",
           applying ? "apply" : "restore", remote_call_current_pid(),
           targetBundle ?: "-");
    if (!targetBundle || !targetBundle[0] ||
        !remote_call_current_success() || !themer_ensure_iconservices_loaded()) {
        snprintf(report.reason, sizeof(report.reason),
                 "invalid-input-or-iconservices-unavailable");
        goto cleanup;
    }
    if (themer_spotlight_has_armed_recovery_in_session()) {
        report.result = ThemerIconProviderInterceptStatePresent;
        snprintf(report.reason, sizeof(report.reason),
                 "another-iconservices-recovery-owner-is-armed");
        goto cleanup;
    }

    seedIcon = themer_iconservices_lab_make_bundle_icon(targetBundle);
    targetIcon = themer_provider_intercept_canonical_icon(seedIcon);
    controlIcon = themer_iconservices_lab_make_bundle_icon(targetBundle);
    descriptor = themer_provider_intercept_copy_descriptor();
    report.canonicalIconSelected = r_is_objc_ptr(seedIcon) &&
        r_is_objc_ptr(targetIcon) && remote_call_current_success();
    if (!report.canonicalIconSelected || !r_is_objc_ptr(controlIcon) ||
        !r_is_objc_ptr(descriptor)) {
        report.result = ThemerIconProviderInterceptUnsupportedABI;
        snprintf(report.reason, sizeof(report.reason),
                 "canonical-target-icon-or-descriptor-unavailable");
        goto cleanup;
    }

    selector = r_sel("_makeResourceProviderAllowIconResourceFallback:");
    originalClass = r_dlsym_call(
        R_TIMEOUT, "object_getClass", targetIcon, 0, 0, 0, 0, 0, 0, 0);
    subclass = themer_lookup_class("CNDProviderInterceptISBundleIdentifierIcon");
    uint64_t installedProvider = selector
        ? r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                       targetIcon, selector, 0, 0, 0, 0, 0, 0)
        : 0;

    if (!applying) {
        if (!themer_provider_intercept_restore_consumer_bridge(&report)) {
            report.result = remote_call_current_success()
                ? ThemerIconProviderInterceptVerificationFailed
                : ThemerIconProviderInterceptTransportFailed;
            snprintf(report.reason, sizeof(report.reason),
                     "consumer-bridge-restore-failed");
            goto cleanup;
        }
        bool classIsReplacement = r_is_objc_ptr(subclass) &&
            originalClass == subclass;
        bool providerIsInstalled = r_is_objc_ptr(installedProvider);
        if (classIsReplacement != providerIsInstalled) {
            report.result = ThemerIconProviderInterceptVerificationFailed;
            snprintf(report.reason, sizeof(report.reason),
                     "canonical-provider-replacement-inconsistent");
            goto cleanup;
        }
        if (!classIsReplacement) {
            report.providerResourcesRestored = true;
            report.providerReplacementRestored = true;
            report.objectClassRestored = true;
            report.associationCleared = true;
            report.controlProviderStayedStock = true;
            report.result = ThemerIconProviderInterceptReady;
            snprintf(report.reason, sizeof(report.reason),
                     "canonical-provider-replacement-already-absent");
            goto cleanup;
        }

        themedProvider = r_msg2(
            installedProvider, "retain", 0, 0, 0, 0);
        themer_read_class_name(
            themedProvider, report.themedProviderClass,
            sizeof(report.themedProviderClass));
        uint64_t iconKey = themer_provider_intercept_original_icon_key();
        uint64_t badgeKey = themer_provider_intercept_original_badge_key();
        originalIconResource = iconKey
            ? r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                           themedProvider, iconKey, 0, 0, 0, 0, 0, 0)
            : 0;
        originalBadgeResource = badgeKey
            ? r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                           themedProvider, badgeKey, 0, 0, 0, 0, 0, 0)
            : 0;
        if (r_is_objc_ptr(originalIconResource)) {
            originalIconResource = r_msg2(
                originalIconResource, "retain", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(originalBadgeResource)) {
            originalBadgeResource = r_msg2(
                originalBadgeResource, "retain", 0, 0, 0, 0);
        }
        report.providerResourcesRestored =
            themer_provider_intercept_restore_resources(
                themedProvider,
                originalIconResource,
                originalBadgeResource);
        bool savedResourcesCleared = report.providerResourcesRestored &&
            themer_provider_intercept_clear_original_resources(themedProvider);
        uint64_t stockClass = r_dlsym_call(
            R_TIMEOUT, "class_getSuperclass", subclass,
            0, 0, 0, 0, 0, 0, 0);
        if (savedResourcesCleared && r_is_objc_ptr(stockClass)) {
            uint64_t previous = r_dlsym_call(
                R_TIMEOUT, "object_setClass", targetIcon, stockClass,
                0, 0, 0, 0, 0, 0);
            report.objectClassRestored = previous == subclass &&
                remote_call_current_success();
        }
        if (report.objectClassRestored) {
            r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                         targetIcon, selector, 0, 1, 0, 0, 0, 0);
            report.associationCleared =
                r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                             targetIcon, selector,
                             0, 0, 0, 0, 0, 0) == 0 &&
                remote_call_current_success();
        }
        report.providerReplacementRestored =
            report.providerResourcesRestored && savedResourcesCleared &&
            report.objectClassRestored && report.associationCleared;
        report.controlProviderStayedStock =
            report.providerReplacementRestored;
        report.result = report.providerReplacementRestored
            ? ThemerIconProviderInterceptReady
            : (remote_call_current_success()
                ? ThemerIconProviderInterceptVerificationFailed
                : ThemerIconProviderInterceptTransportFailed);
        snprintf(report.reason, sizeof(report.reason), "%s",
                 report.providerReplacementRestored
                    ? "canonical-provider-replacement-restored"
                    : "canonical-provider-replacement-restore-failed");
        goto cleanup;
    }

    if (originalClass == subclass || r_is_objc_ptr(installedProvider)) {
        report.result = ThemerIconProviderInterceptStatePresent;
        snprintf(report.reason, sizeof(report.reason),
                 "canonical-provider-replacement-already-present");
        goto cleanup;
    }

    char providerTypes[192] = {0};
    bool providerABI = themer_iconservices_lab_method_types(
        targetIcon, "_makeResourceProviderAllowIconResourceFallback:",
        providerTypes, sizeof(providerTypes)) &&
        (!strcmp(providerTypes, "@20@0:8B16") ||
         !strcmp(providerTypes, "@24@0:8B16"));
    if (!providerABI) {
        report.result = ThemerIconProviderInterceptUnsupportedABI;
        snprintf(report.reason, sizeof(report.reason),
                 "provider-selector-abi");
        goto cleanup;
    }
    stockProvider = r_msg2_main(
        controlIcon, "_makeResourceProviderAllowIconResourceFallback:",
        1, 0, 0, 0);
    if (r_is_objc_ptr(stockProvider)) {
        stockProvider = r_msg2(stockProvider, "retain", 0, 0, 0, 0);
        themer_read_class_name(stockProvider, report.stockProviderClass,
                               sizeof(report.stockProviderClass));
    }
    report.stockProviderCaptured = r_is_objc_ptr(stockProvider) &&
        remote_call_current_success();

    stockImage = r_responds_main(controlIcon, "imageForDescriptor:")
        ? r_msg2_main(controlIcon, "imageForDescriptor:",
                      descriptor, 0, 0, 0) : 0;
    if (r_is_objc_ptr(stockImage)) {
        stockImage = r_msg2(stockImage, "retain", 0, 0, 0, 0);
        (void)themer_agent_capture_image_pixels(
            stockImage, &stockPixels, &stockMetadata,
            report.stockPixelSHA256);
    }
    if (!report.stockProviderCaptured || !remote_call_current_success()) {
        report.result = remote_call_current_success()
            ? ThemerIconProviderInterceptVerificationFailed
            : ThemerIconProviderInterceptTransportFailed;
        snprintf(report.reason, sizeof(report.reason),
                 "stock-provider-unavailable");
        goto cleanup;
    }

    if (applying) {
        if (!imageDataByBundle || imageDataByBundle.count == 0 ||
            !themeBundlePath || !themeBundlePath[0] ||
            !themeResourceBaseName || !themeResourceBaseName[0]) {
            report.result = ThemerIconProviderInterceptVerificationFailed;
            snprintf(report.reason, sizeof(report.reason),
                     "theme-input-unavailable");
            goto cleanup;
        }
        themedResource = themer_provider_intercept_make_legacy_resource(
            themeBundlePath, themeResourceBaseName, &report);
        if (!r_is_objc_ptr(themedResource)) {
            report.result = remote_call_current_success()
                ? ThemerIconProviderInterceptVerificationFailed
                : ThemerIconProviderInterceptTransportFailed;
            snprintf(report.reason, sizeof(report.reason),
                     "themed-resource-construction");
            goto cleanup;
        }

        // _makeResourceProviderAllowIconResourceFallback: returns a record
        // provider facade.  The convenience factory above returns only its
        // leaf compositor resource.  Preserve the genuine facade (including
        // its LS record/token/platform state) and replace only the two leaf
        // resource slots observed in the successful legacy resolver path.
        themedProvider = r_msg2_main(
            targetIcon, "_makeResourceProviderAllowIconResourceFallback:",
            1, 0, 0, 0);
        if (r_is_objc_ptr(themedProvider)) {
            themedProvider = r_msg2(
                themedProvider, "retain", 0, 0, 0, 0);
            themer_read_class_name(
                themedProvider, report.themedProviderClass,
                sizeof(report.themedProviderClass));
        }
        char resolveTypes[192] = {0};
        char iconGetterTypes[192] = {0};
        char badgeGetterTypes[192] = {0};
        char iconSetterTypes[192] = {0};
        char badgeSetterTypes[192] = {0};
        char resolvedGetterTypes[192] = {0};
        char resolvedSetterTypes[192] = {0};
        bool wrapperABI = r_is_objc_ptr(themedProvider) &&
            themer_iconservices_lab_method_types(
                themedProvider, "resolveResources",
                resolveTypes, sizeof(resolveTypes)) &&
            !strcmp(resolveTypes, "v16@0:8") &&
            themer_iconservices_lab_method_types(
                themedProvider, "iconResource",
                iconGetterTypes, sizeof(iconGetterTypes)) &&
            !strcmp(iconGetterTypes, "@16@0:8") &&
            themer_iconservices_lab_method_types(
                themedProvider, "badgeResource",
                badgeGetterTypes, sizeof(badgeGetterTypes)) &&
            !strcmp(badgeGetterTypes, "@16@0:8") &&
            themer_iconservices_lab_method_types(
                themedProvider, "setIconResource:",
                iconSetterTypes, sizeof(iconSetterTypes)) &&
            !strcmp(iconSetterTypes, "v24@0:8@16") &&
            themer_iconservices_lab_method_types(
                themedProvider, "setBadgeResource:",
                badgeSetterTypes, sizeof(badgeSetterTypes)) &&
            !strcmp(badgeSetterTypes, "v24@0:8@16") &&
            themer_iconservices_lab_method_types(
                themedProvider, "resolved",
                resolvedGetterTypes, sizeof(resolvedGetterTypes)) &&
            !strcmp(resolvedGetterTypes, "B16@0:8") &&
            themer_iconservices_lab_method_types(
                themedProvider, "setResolved:",
                resolvedSetterTypes, sizeof(resolvedSetterTypes)) &&
            !strcmp(resolvedSetterTypes, "v20@0:8B16");
        printf("[ICONINTERCEPT] record-provider wrapper=%s abi=%d "
               "resolve=\"%s\" icon=\"%s\"/\"%s\" "
               "badge=\"%s\"/\"%s\" resolved=\"%s\"/\"%s\"\n",
               report.themedProviderClass[0]
                    ? report.themedProviderClass : "-",
               wrapperABI,
               resolveTypes[0] ? resolveTypes : "-",
               iconGetterTypes[0] ? iconGetterTypes : "-",
               iconSetterTypes[0] ? iconSetterTypes : "-",
               badgeGetterTypes[0] ? badgeGetterTypes : "-",
               badgeSetterTypes[0] ? badgeSetterTypes : "-",
               resolvedGetterTypes[0] ? resolvedGetterTypes : "-",
               resolvedSetterTypes[0] ? resolvedSetterTypes : "-");
        if (!wrapperABI || !remote_call_current_success()) {
            report.result = remote_call_current_success()
                ? ThemerIconProviderInterceptUnsupportedABI
                : ThemerIconProviderInterceptTransportFailed;
            snprintf(report.reason, sizeof(report.reason),
                     "record-provider-wrapper-abi");
            goto cleanup;
        }
        r_msg2_main(themedProvider, "resolveResources", 0, 0, 0, 0);
        originalIconResource = r_msg2_main(
            themedProvider, "iconResource", 0, 0, 0, 0);
        originalBadgeResource = r_msg2_main(
            themedProvider, "badgeResource", 0, 0, 0, 0);
        if (r_is_objc_ptr(originalIconResource)) {
            originalIconResource = r_msg2(
                originalIconResource, "retain", 0, 0, 0, 0);
        }
        if (r_is_objc_ptr(originalBadgeResource)) {
            originalBadgeResource = r_msg2(
                originalBadgeResource, "retain", 0, 0, 0, 0);
        }
        if (!r_is_objc_ptr(originalIconResource) ||
            !r_is_objc_ptr(originalBadgeResource) ||
            !remote_call_current_success()) {
            report.result = remote_call_current_success()
                ? ThemerIconProviderInterceptVerificationFailed
                : ThemerIconProviderInterceptTransportFailed;
            snprintf(report.reason, sizeof(report.reason),
                     "record-provider-stock-resources");
            goto cleanup;
        }
        originalResourcesStored =
            themer_provider_intercept_store_original_resources(
                themedProvider,
                originalIconResource,
                originalBadgeResource);
        if (!originalResourcesStored) {
            report.result = remote_call_current_success()
                ? ThemerIconProviderInterceptVerificationFailed
                : ThemerIconProviderInterceptTransportFailed;
            snprintf(report.reason, sizeof(report.reason),
                     "record-provider-original-resource-retention");
            goto cleanup;
        }
        r_msg2_main(themedProvider, "setIconResource:",
                    themedResource, 0, 0, 0);
        r_msg2_main(themedProvider, "setBadgeResource:",
                    themedResource, 0, 0, 0);
        if (!r_msg2_main(
                themedProvider, "resolved", 0, 0, 0, 0)) {
            r_msg2_main(themedProvider, "setResolved:", 1, 0, 0, 0);
        }
        providerResourcesReplaced = remote_call_current_success() &&
            r_msg2_main(themedProvider, "iconResource", 0, 0, 0, 0) ==
                themedResource &&
            r_msg2_main(themedProvider, "badgeResource", 0, 0, 0, 0) ==
                themedResource &&
            r_msg2_main(themedProvider, "resolved", 0, 0, 0, 0) != 0;
        report.providerResourcesReplaced = providerResourcesReplaced;
        report.themedProviderConstructed = providerResourcesReplaced;
        printf("[ICONINTERCEPT] record-provider resources primary=0x%llx "
               "badge=0x%llx themed=0x%llx replaced=%d resolved=%llu\n",
               (unsigned long long)originalIconResource,
               (unsigned long long)originalBadgeResource,
               (unsigned long long)themedResource,
               providerResourcesReplaced,
               (unsigned long long)r_msg2_main(
                    themedProvider, "resolved", 0, 0, 0, 0));
        if (!providerResourcesReplaced || !remote_call_current_success()) {
            report.result = remote_call_current_success()
                ? ThemerIconProviderInterceptVerificationFailed
                : ThemerIconProviderInterceptTransportFailed;
            snprintf(report.reason, sizeof(report.reason),
                     "record-provider-resource-replacement");
            goto cleanup;
        }

        originalClass = r_dlsym_call(
            R_TIMEOUT, "object_getClass", targetIcon, 0, 0, 0, 0, 0, 0, 0);
        subclass = themer_provider_intercept_subclass(
            originalClass, providerTypes);
        selector = r_sel("_makeResourceProviderAllowIconResourceFallback:");
        if (!r_is_objc_ptr(originalClass) || !r_is_objc_ptr(subclass) ||
            !selector) {
            report.result = ThemerIconProviderInterceptUnsupportedABI;
            snprintf(report.reason, sizeof(report.reason),
                     "temporary-subclass-unavailable");
            goto cleanup;
        }
        r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                     targetIcon, selector, themedProvider, 1, 0, 0, 0, 0);
        associationInstalled = remote_call_current_success() &&
            r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                         targetIcon, selector, 0, 0, 0, 0, 0, 0) ==
                themedProvider;
        if (associationInstalled) {
            uint64_t previous = r_dlsym_call(
                R_TIMEOUT, "object_setClass", targetIcon, subclass,
                0, 0, 0, 0, 0, 0);
            classChanged = previous == originalClass &&
                remote_call_current_success();
        }
        uint64_t intercepted = classChanged ? r_msg2_main(
            targetIcon, "_makeResourceProviderAllowIconResourceFallback:",
            1, 0, 0, 0) : 0;
        report.providerBoundaryIntercepted =
            intercepted == themedProvider && remote_call_current_success();
        uint64_t controlAfter = report.providerBoundaryIntercepted
            ? r_msg2_main(
                controlIcon,
                "_makeResourceProviderAllowIconResourceFallback:",
                1, 0, 0, 0) : 0;
        report.controlProviderStayedStock = r_is_objc_ptr(controlAfter) &&
            controlAfter != themedProvider && remote_call_current_success();
        report.providerReplacementInstalled =
            providerResourcesReplaced && originalResourcesStored &&
            report.providerBoundaryIntercepted &&
            report.controlProviderStayedStock && classChanged &&
            associationInstalled && remote_call_current_success();
        if (!report.providerBoundaryIntercepted ||
            !report.controlProviderStayedStock ||
            !report.providerReplacementInstalled) {
            report.result = ThemerIconProviderInterceptVerificationFailed;
            snprintf(report.reason, sizeof(report.reason),
                     "provider-boundary-or-control-proof");
            goto cleanup;
        }
    } else {
        report.controlProviderStayedStock = true;
    }

    generated = themer_iconservices_lab_generation_request(
        targetIcon, descriptor, &requestABI, &identifiers,
        &generationInvoked, NULL, NULL, NULL);
    report.generationInvoked = generationInvoked;
    report.recordIdentifiersObserved = identifiers.observed;
    report.recordIdentifiersOwnershipVerified = identifiers.observed &&
        identifiers.holderArgumentMatches && identifiers.argumentsRetained &&
        identifiers.directArgumentMatches &&
        identifiers.directArgumentsRetained &&
        identifiers.ownerBoundPostDispatch && identifiers.transportClean;

    // Keep the canonical target's provider replacement installed after the
    // synthetic proof request.  Subsequent real consumer requests can then
    // ask the same manager-owned icon for any descriptor they require.  The
    // matching restore operation reverses all three retained state changes.

    report.generationReturnedImage = r_is_objc_ptr(generated) && requestABI &&
        generationInvoked && remote_call_current_success();
    if (report.generationReturnedImage) {
        themer_read_class_name(generated, report.generatedImageClass,
                               sizeof(report.generatedImageClass));
        report.generatedPixelsCaptured = themer_agent_capture_image_pixels(
            generated, &generatedPixels, &generatedMetadata,
            report.generatedPixelSHA256);
        report.generatedImageLength = generatedPixels.objectLength;
        report.generatedPixelsDifferFromStock =
            !stockPixels.truncated && !generatedPixels.truncated &&
            stockPixels.objectLength > 0 && generatedPixels.objectLength > 0 &&
            (stockPixels.objectLength != generatedPixels.objectLength ||
             memcmp(stockPixels.bytes, generatedPixels.bytes,
                    stockPixels.objectLength) != 0);
        (void)themer_provider_intercept_publish_cache(
            targetIcon, descriptor, generated, &report);
    }

    if (applying && report.canonicalCacheReadbackVerified &&
        remote_call_current_success()) {
        consumerIcon = themer_provider_intercept_find_consumer_icon(
            targetBundle, &consumerView);
        report.consumerIconLocated = r_is_objc_ptr(consumerIcon);
        if (report.consumerIconLocated) {
            consumerBridgeInstalled =
                themer_provider_intercept_install_consumer_bridge(
                    consumerIcon, targetIcon, consumerView, &report);
        } else {
            snprintf(report.reason, sizeof(report.reason),
                     "consumer-sbhapplicationicon-not-found");
        }
    }

    bool complete = report.stockProviderCaptured &&
        report.canonicalIconSelected &&
        report.recordIdentifiersObserved &&
        report.recordIdentifiersOwnershipVerified &&
        report.generationReturnedImage && report.generatedPixelsCaptured &&
        report.canonicalCachePublished &&
        report.canonicalCacheReadbackVerified &&
        report.themedProviderConstructed &&
        report.providerResourcesReplaced &&
        report.providerReplacementInstalled &&
        report.providerBoundaryIntercepted &&
        report.controlProviderStayedStock &&
        report.generatedPixelsDifferFromStock &&
        report.consumerIconLocated &&
        report.consumerBridgeInstalled &&
        report.consumerBridgeReadbackVerified &&
        report.consumerRefreshIssued;
    keepCanonicalReplacement = applying && complete;
    report.result = complete
        ? ThemerIconProviderInterceptReady
        : (remote_call_current_success()
            ? ThemerIconProviderInterceptVerificationFailed
            : ThemerIconProviderInterceptTransportFailed);
    snprintf(report.reason, sizeof(report.reason), "%s",
             complete ? (applying
                    ? "canonical-provider-replacement-installed"
                    : "canonical-provider-replacement-restored")
                : "generation-publication-or-restore-proof");

cleanup:
    // Failed apply attempts remain fail-closed.  A successful apply is the
    // sole case that intentionally retains the target-only replacement.
    if (!keepCanonicalReplacement && consumerBridgeInstalled &&
        remote_call_current_success()) {
        report.consumerBridgeRestored =
            themer_provider_intercept_restore_consumer_bridge(&report);
        consumerBridgeInstalled = !report.consumerBridgeRestored;
    }
    if (!keepCanonicalReplacement && providerResourcesReplaced &&
        r_is_objc_ptr(themedProvider) &&
        remote_call_current_success()) {
        report.providerResourcesRestored =
            themer_provider_intercept_restore_resources(
                themedProvider,
                originalIconResource,
                originalBadgeResource);
        providerResourcesReplaced = !report.providerResourcesRestored;
    }
    if (!keepCanonicalReplacement && originalResourcesStored &&
        r_is_objc_ptr(themedProvider) && remote_call_current_success()) {
        bool cleared =
            themer_provider_intercept_clear_original_resources(themedProvider);
        originalResourcesStored = !cleared;
    }
    if (!keepCanonicalReplacement && classChanged &&
        r_is_objc_ptr(targetIcon) &&
        r_is_objc_ptr(originalClass) && remote_call_current_success()) {
        (void)r_dlsym_call(R_TIMEOUT, "object_setClass",
                           targetIcon, originalClass, 0, 0, 0, 0, 0, 0);
        report.objectClassRestored = remote_call_current_success();
        classChanged = !report.objectClassRestored;
    }
    if (!keepCanonicalReplacement && associationInstalled &&
        r_is_objc_ptr(targetIcon) && selector &&
        remote_call_current_success()) {
        r_dlsym_call(R_TIMEOUT, "objc_setAssociatedObject",
                     targetIcon, selector, 0, 1, 0, 0, 0, 0);
        report.associationCleared =
            r_dlsym_call(R_TIMEOUT, "objc_getAssociatedObject",
                         targetIcon, selector, 0, 0, 0, 0, 0, 0) == 0 &&
            remote_call_current_success();
        associationInstalled = !report.associationCleared;
    }
    if (!keepCanonicalReplacement && report.providerResourcesRestored &&
        report.objectClassRestored && report.associationCleared &&
        !providerResourcesReplaced && !originalResourcesStored &&
        !classChanged && !associationInstalled) {
        report.providerReplacementRestored = true;
    }
    report.transportClean = remote_call_current_success();
    if (!report.transportClean) {
        report.result = ThemerIconProviderInterceptTransportFailed;
    }
    printf("[ICONINTERCEPT] summary mode=%s result=%d target=%s "
           "stockProvider=%d/%s themedProvider=%d/%s resource=%s "
           "canonical=%d resourceSwap=%d/%d replacement=%d/%d restart=%d "
           "boundary=%d "
           "controlStock=%d generated=%d records=%d/%d image=%d/%s "
           "pixels=%d/%llu/%s "
           "differentFromStock=%d cache=%d/%d consumer=%d/%s "
           "bridge=%d/%d refresh=%d bridgeRestored=%d restored=%d/%d "
           "transport=%d reason=%s bundleMutations=0 "
           "registrationMutations=0 globalHooks=0\n",
           applying ? "apply" : "restore", report.result,
           report.targetBundle[0] ? report.targetBundle : "-",
           report.stockProviderCaptured,
           report.stockProviderClass[0] ? report.stockProviderClass : "-",
           report.themedProviderConstructed,
           report.themedProviderClass[0] ? report.themedProviderClass : "-",
           report.resolvedResourceClass[0]
                ? report.resolvedResourceClass : "-",
           report.canonicalIconSelected,
           report.providerResourcesReplaced,
           report.providerResourcesRestored,
           report.providerReplacementInstalled,
           report.providerReplacementRestored,
           report.agentRestartDiscardedReplacement,
           report.providerBoundaryIntercepted,
           report.controlProviderStayedStock,
           report.generationInvoked,
           report.recordIdentifiersObserved,
           report.recordIdentifiersOwnershipVerified,
           report.generationReturnedImage,
           report.generatedImageClass[0] ? report.generatedImageClass : "-",
           report.generatedPixelsCaptured,
           (unsigned long long)report.generatedImageLength,
           report.generatedPixelSHA256[0]
                ? report.generatedPixelSHA256 : "-",
           report.generatedPixelsDifferFromStock,
           report.canonicalCachePublished,
           report.canonicalCacheReadbackVerified,
           report.consumerIconLocated,
           report.consumerIconClass[0] ? report.consumerIconClass : "-",
           report.consumerBridgeInstalled,
           report.consumerBridgeReadbackVerified,
           report.consumerRefreshIssued,
           report.consumerBridgeRestored,
           report.objectClassRestored, report.associationCleared,
           report.transportClean,
           report.reason[0] ? report.reason : "-");

    if (r_is_objc_ptr(generated) && remote_call_current_success())
        r_msg2(generated, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(stockImage) && remote_call_current_success())
        r_msg2(stockImage, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(originalBadgeResource) && remote_call_current_success())
        r_msg2(originalBadgeResource, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(originalIconResource) && remote_call_current_success())
        r_msg2(originalIconResource, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(themedResource) && remote_call_current_success())
        r_msg2(themedResource, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(themedProvider) && remote_call_current_success())
        r_msg2(themedProvider, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(stockProvider) && remote_call_current_success())
        r_msg2(stockProvider, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(descriptor) && remote_call_current_success())
        r_msg2(descriptor, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(controlIcon) && remote_call_current_success())
        r_msg2(controlIcon, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(targetIcon) && remote_call_current_success())
        r_msg2(targetIcon, "release", 0, 0, 0, 0);
    if (r_is_objc_ptr(seedIcon) && remote_call_current_success())
        r_msg2(seedIcon, "release", 0, 0, 0, 0);
    themer_iconservices_lab_free_data_capture(&identifiers.firstBlob.capture);
    themer_iconservices_lab_free_data_capture(&generatedPixels);
    themer_iconservices_lab_free_data_capture(&stockPixels);
    if (reportOut) *reportOut = report;
    return report.result;
}

ThemerIconProviderInterceptResult
themer_iconservices_provider_intercept_apply_in_session(
    NSDictionary<NSString *, NSData *> *imageDataByBundle,
    const char *targetBundle,
    const char *themeBundlePath,
    const char *themeResourceBaseName,
    ThemerIconProviderInterceptReport *reportOut)
{
    return themer_provider_intercept_run(
        imageDataByBundle, targetBundle, themeBundlePath,
        themeResourceBaseName, true, reportOut);
}

ThemerIconProviderInterceptResult
themer_iconservices_provider_intercept_restore_in_session(
    const char *targetBundle,
    ThemerIconProviderInterceptReport *reportOut)
{
    return themer_provider_intercept_run(
        nil, targetBundle, NULL, NULL, false, reportOut);
}
